/// Integer element-WIDTH variants of the runtime `__trustcg_slice_eq_*` helper:
/// `eq(a: Ptr, a_len: I64, b: Ptr, b_len: I64) -> I64` returns 1 iff the two
/// integer buffers are equal. One variant per pow2-<=8 width.
const SLICE_EQ_VARIANTS: &[(u64, &str)] = &[
    (1, "__trustcg_slice_eq_i8"),
    (2, "__trustcg_slice_eq_i16"),
    (4, "__trustcg_slice_eq_i32"),
    (8, "__trustcg_slice_eq_i64"),
];

/// Float-element variants of `__trustcg_slice_eq_*` (per-element IEEE `OEq`,
/// not a bitwise compare — see `build_slice_eq_object`). Only 4/8-byte floats.
const SLICE_EQ_FLOAT_VARIANTS: &[(u64, &str)] =
    &[(4, "__trustcg_slice_eq_f32"), (8, "__trustcg_slice_eq_f64")];

fn slice_eq_symbol(size: u64, is_float: bool) -> &'static str {
    match (is_float, size) {
        (true, 4) => "__trustcg_slice_eq_f32",
        (true, _) => "__trustcg_slice_eq_f64",
        (false, 1) => "__trustcg_slice_eq_i8",
        (false, 2) => "__trustcg_slice_eq_i16",
        (false, 4) => "__trustcg_slice_eq_i32",
        (false, _) => "__trustcg_slice_eq_i64",
    }
}

fn slice_eq_callee(ctx: &mut MirLoweringCtx<'_>, size: u64, is_float: bool) -> FuncId {
    ctx.extern_callee_by_name(
        slice_eq_symbol(size, is_float),
        FuncTy {
            params: vec![
                TrustIrTy::Ptr,
                TrustIrTy::I64,
                TrustIrTy::Ptr,
                TrustIrTy::I64,
            ],
            returns: vec![TrustIrTy::I64],
            abi: None,
            is_vararg: false,
        },
    )
}

