/// Element-width variants of the runtime `__trustcg_array_fill_*` helper:
/// `fill(dst: Ptr, value: I64, count: I64) -> ()` stores the low `size*8` bits
/// of `value` at `dst + i*size` for `i in 0..count`, ascending — the LOOP form
/// of a large `[v; N]` array-repeat store (see the `Rvalue::Repeat` arm of the
/// scalar-element memory-array lowering). Signedness is irrelevant to a fill
/// (only the stored byte width matters), so there is one variant per width.
const ARRAY_FILL_VARIANTS: &[(u64, &str)] = &[
    (1, "__trustcg_array_fill_i8"),
    (2, "__trustcg_array_fill_i16"),
    (4, "__trustcg_array_fill_i32"),
    (8, "__trustcg_array_fill_i64"),
];

/// Float-element `__trustcg_array_fill_*` variants — the value is passed as
/// F32/F64 and stored directly (no I64 truncation). Used only by `Vec::resize`
/// with a float fill; the `[v; N]` array-literal path keeps floats on its
/// unrolled inline-store branch, so array_fill_symbol stays integer-only.
const ARRAY_FILL_FLOAT_VARIANTS: &[(u64, &str)] = &[
    (4, "__trustcg_array_fill_f32"),
    (8, "__trustcg_array_fill_f64"),
];

/// Minimum `[v; N]` element count that routes through the fill-helper loop
/// instead of `N` inline unrolled stores. Below this the unrolled stores are
/// cheap, constant-foldable, and free of call overhead; above it the unroll
/// bloats code/frame size linearly in `N` (p7_sieve's `[0u8; 1024]` unrolled
/// to 1024 stores whose hoisted address pairs consumed a 16KB frame).
const ARRAY_FILL_MIN_COUNT: u64 = 16;

/// The `__trustcg_array_fill_*` symbol for an element byte width, if that
/// width has a variant.
fn array_fill_symbol(size: u64) -> Option<&'static str> {
    ARRAY_FILL_VARIANTS
        .iter()
        .find(|(s, _)| *s == size)
        .map(|(_, sym)| *sym)
}

/// `__trustcg_array_fill_iN(dst: Ptr, value: I64, count: I64) -> ()`, selected
/// by element byte width. Declares the extern (recording helper usage for the
/// lazy emission in `codegen_crate`) and returns its `FuncId`.
fn array_fill_callee(ctx: &mut MirLoweringCtx<'_>, size: u64, is_float: bool) -> FuncId {
    if is_float {
        let (symbol, value_ty) = match size {
            4 => ("__trustcg_array_fill_f32", TrustIrTy::F32),
            _ => ("__trustcg_array_fill_f64", TrustIrTy::F64),
        };
        return ctx.extern_callee_by_name(
            symbol,
            FuncTy {
                params: vec![TrustIrTy::Ptr, value_ty, TrustIrTy::I64],
                returns: vec![],
                abi: None,
                is_vararg: false,
            },
        );
    }
    let symbol = array_fill_symbol(size).expect("array_fill_callee: unsupported element width");
    ctx.extern_callee_by_name(
        symbol,
        FuncTy {
            params: vec![TrustIrTy::Ptr, TrustIrTy::I64, TrustIrTy::I64],
            returns: vec![],
            abi: None,
            is_vararg: false,
        },
    )
}

/// Try to lower a `<[T]>::sort()` / `sort_unstable()` (ascending, integer `T`)
/// call. Returns `Ok(true)` if intercepted + fully lowered; `Ok(false)` if it is
/// not a slice-sort we recognize (the caller continues); `Err` to fail closed on
/// a sort we must not silently miscompile (a custom comparator, a non-integer
/// element, an unresolvable slice argument).
///
/// The receiver `&mut [T]` is a memory-backed `{ data, len }` fat pointer; we
/// read its two lanes and call `__trustcg_vec_sort_{i,u}N(data, len)`, which
/// sorts the buffer in place comparing in the element's own signedness.
/// `T` must be a scalar integer (the helper compares i64 lanes); a wider/aggregate
/// element fails closed. `sort_by_key` uses its guarded model below;
/// `sort_unstable_by_key` / `sort_by_cached_key` keep std's ordinary body and
/// algorithm. A `sort_by` comparator cannot be proven a total order here, so it
/// fails closed rather than risk a wrong order.
fn lower_slice_sort_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    let name = name.as_str();
    let is_plain_sort = matches!(name, "sort" | "sort_unstable");
    let is_by_sort = matches!(
        name,
        "sort_by"
            | "sort_unstable_by"
            | "sort_by_key"
            | "sort_unstable_by_key"
            | "sort_by_cached_key"
    );
    if !is_plain_sort && !is_by_sort {
        return Ok(false);
    }
    // The receiver must be `&mut [T]` (the `<[T]>::sort` self). Confirm by the
    // first argument's type being a slice fat pointer; a non-slice `sort` (e.g. on
    // a user type with a `sort` method) is not ours.
    let Some(self_arg) = call.args.first() else {
        return Ok(false);
    };
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
    let Some(element_ty) = fat_ptr_slice_or_str_pointee(ctx.tcx, self_ty) else {
        return Ok(false);
    };
    let element_ty = ctx.monomorphize_ty(element_ty);

    // From here it IS a slice sort: any shape we cannot model fails CLOSED.
    if is_by_sort {
        // Keep the ordinary std algorithms and their key-call/allocation behavior
        // for cached and unstable key sorts. This declines before any emission;
        // general body, iterator and compiler-owned ABI lowering do the work.
        if matches!(name, "sort_unstable_by_key" | "sort_by_cached_key") {
            return Ok(false);
        }
        // `sort_by_key` alone uses the guarded stable insertion model. Its Pure
        // check retains address, panic-site and caller-chain requirements.
        // Non-integer keys/elements or wide elements fail closed inside it.
        // We intentionally DO NOT model
        // `sort_by` / `sort_unstable_by` (a raw `Fn(&T,&T) -> Ordering`): an
        // arbitrary comparator that is not a valid total order yields an
        // *algorithm-dependent* permutation, which our insertion sort cannot be
        // proven to match std's driftsort/ipnsort for — so those remain
        // fail-closed.
        if name == "sort_by_key" {
            return lower_slice_sort_by_key(ctx, body, block, call, name, element_ty);
        }
        return Err(format!(
            "<[{element_ty:?}]>::{name} with a custom comparator is not modeled \
             (an arbitrary `Fn(&T,&T) -> Ordering` may not be a valid total order, \
             so its result is algorithm-dependent) — fail closed"
        ));
    }
    debug_assert!(is_plain_sort);
    // Integer element only: the helper compares 64-bit lanes with a signed or
    // unsigned predicate. A bool/char or wider/aggregate element fails closed.
    if !is_integer(element_ty) {
        return Err(format!(
            "<[{element_ty:?}]>::sort over a non-integer element is not modeled — fail closed"
        ));
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    if size > 8 {
        return Err(format!(
            "<[{element_ty:?}]>::sort over a wider-than-64-bit element is not modeled — fail closed"
        ));
    }
    let signed = is_signed_integer(element_ty);

    // Resolve the slice argument `&mut [T]` to its `{ data, len }` lanes. The
    // operand is a place (a fat-pointer local, memory-backed); read both lanes.
    let (Operand::Copy(place) | Operand::Move(place)) = &self_arg.node else {
        return Err("slice sort self argument is not a place operand".to_owned());
    };
    if !place.projection.is_empty() {
        return Err("slice sort self argument uses a projected place".to_owned());
    }
    if !local_is_memory_backed(ctx, place.local) {
        return Err("slice sort self argument is not a memory-backed slice".to_owned());
    }
    let data = load_fat_ptr_data(ctx, block, place.local)?;
    let len = load_fat_ptr_meta(ctx, block, place.local)?;

    let data_ptr = coerce_to_plain_ptr(ctx, block, data);
    let len_i64 = coerce_to_i64(ctx, block, len);
    let sort_callee = vec_sort_callee(ctx, size, signed);
    block.body.push(InstrNode::new(Inst::Call {
        callee: sort_callee,
        args: vec![data_ptr, len_i64],
    }));

    // `sort` returns `()`.
    emit_call_successor(block, call.target);
    Ok(true)
}

/// `<[T]>::contains(&self, &needle) -> bool` (and `Vec`/array `contains`, which
/// deref/unsize to this slice method first): a linear equality scan over the
/// slice buffer. Lowered to the hand-authored `__trustcg_slice_contains_*`
/// runtime helper (which owns the scan loop), gated to a scalar integer or
/// F32/F64 element. Integer helpers compare masked 64-bit lanes; float helpers
/// use IEEE `OEq`, so a NaN needle never matches and signed zeros do.
/// Bool/char/aggregate elements fail closed. `str::contains` (a substring/char
/// PATTERN search, not a single-element scan) never matches: its receiver is
/// `&str`, not `&[T]`.
fn lower_slice_contains_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    // The callee must be core's own inherent `<[T]>::contains`. A `&[T]`
    // receiver and the name are not that identity: core's provided
    // `RangeBounds::contains`, for a user `impl RangeBounds<L> for [u32]`, takes
    // the same `(&[u32], &u32)` and answers from the user's bounds, not from
    // the slice's elements.
    let did = callee.def_id();
    if !is_std_collection_method_callee(ctx.tcx, did)
        || !ctx.tcx.inherent_impl_of_assoc(did).is_some_and(|impl_did| {
            matches!(ctx.tcx.type_of(impl_did).skip_binder().kind(), ty::Slice(_))
        })
    {
        return Ok(false);
    }
    if callee_item_name_str(ctx.tcx, did).as_str() != "contains" {
        return Ok(false);
    }
    if call.args.len() != 2 {
        return Ok(false);
    }
    // The receiver is `&[T]` (a slice fat pointer). A `Vec`/array `contains`
    // derefs/unsizes to this slice method first.
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let element_ty = match self_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => match inner.kind() {
            ty::Slice(e) => ctx.monomorphize_ty(*e),
            _ => return Ok(false),
        },
        _ => return Ok(false),
    };
    // From here it IS a slice `contains`: unmodelable element shapes fail CLOSED
    // (rather than miscompile). Integers use a raw masked-lane compare, floats
    // use IEEE equality, and bool/char/aggregate `PartialEq` remains unmodeled.
    let is_float = element_ty.is_floating_point();
    if !is_integer(element_ty) && !is_float {
        return Err(format!(
            "<[{element_ty:?}]>::contains over a non-integer/non-float element is not modeled \
             (its PartialEq is not a raw integer or IEEE compare) — fail closed"
        ));
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    if is_float && !matches!(size, 4 | 8) {
        return Err(format!(
            "<[{element_ty:?}]>::contains over a {size}-byte float element is not modeled \
             — fail closed"
        ));
    }
    if size > 8 {
        return Err(format!(
            "<[{element_ty:?}]>::contains over a wider-than-64-bit element is not modeled \
             — fail closed"
        ));
    }
    let ety = if is_float {
        match size {
            4 => TrustIrTy::F32,
            _ => TrustIrTy::F64,
        }
    } else {
        match size {
            1 => TrustIrTy::I8,
            2 => TrustIrTy::I16,
            4 => TrustIrTy::I32,
            _ => TrustIrTy::I64,
        }
    };

    // Resolve the slice receiver `{ data, len }` and the needle value (loaded
    // through the `&T` argument pointer at the element width).
    let (data, len) = slice_receiver_data_len(ctx, block, &call.args[0].node)?;
    let data_ptr = coerce_to_plain_ptr(ctx, block, data);
    let len_i64 = coerce_to_i64(ctx, block, len);
    let needle_ptr = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let needle_val = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Load {
            ty: ety.clone(),
            ptr: needle_ptr,
            volatile: false,
            align: None,
        })
        .with_result(needle_val),
    );
    // Integers pass an I64 needle, which the helper masks to its low `size`
    // bytes; floats pass the F32/F64 value straight through (the helper
    // compares with `fcmp OEq`). A narrower needle is ZERO-EXTENDED to the I64
    // parameter: trust-ir refuses a `Copy` that widens (`OperandTypeMismatch`
    // "copy operand type mismatch: expected i64, got i8"), and the extension
    // keeps the low bytes, the only ones the helper compares.
    let needle_arg = if is_float {
        needle_val
    } else {
        emit_extend_to_i64(ctx, block, &ety, false, needle_val)
    };

    // Call the width-keyed scan helper -> I64 (0/1), then narrow to the `bool`
    // destination.
    let contains_callee = slice_contains_callee(ctx, size, is_float);
    let found_i64 = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Call {
            callee: contains_callee,
            args: vec![data_ptr, len_i64, needle_arg],
        })
        .with_result(found_i64),
    );
    let zero = emit_i64_const(ctx, block, 0);
    let found = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: found_i64,
            rhs: zero,
        })
        .with_result(found),
    );
    let dest_ty = place_trust_ir_ty(ctx, body, call.destination).unwrap_or(TrustIrTy::Bool);
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: dest_ty,
            operand: found,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(true)
}

/// The most lanes `lower_slice_swap_call` moves for one element (both elements'
/// lanes are loaded before any is stored, so this bounds the live values).
const SLICE_SWAP_MAX_LANES: u64 = 16;

/// The lanes `lower_slice_swap_call` moves one element of `size` bytes aligned
/// to `align` with: `(lane type, lane bytes, lane count)`, covering the element
/// exactly with aligned accesses, or `None` (fail closed).
///
/// An element of 1/2/4/8 bytes is one lane of its own width, and a 16-byte
/// element aligned to at least 8 is two 8-byte lanes. Any other element moves
/// as lanes of its own alignment capped at 8 bytes (a Rust size is a multiple
/// of its alignment), up to `SLICE_SWAP_MAX_LANES` lanes. A zero-sized element,
/// an element aligned to more than 16, or one needing more lanes is `None`.
fn slice_swap_lanes(size: u64, align: u64) -> Option<(TrustIrTy, u64, usize)> {
    let lane_ty = |bytes: u64| match bytes {
        1 => TrustIrTy::I8,
        2 => TrustIrTy::I16,
        4 => TrustIrTy::I32,
        _ => TrustIrTy::I64,
    };
    match (size, align) {
        (1 | 2 | 4 | 8, _) => Some((lane_ty(size), size, 1)),
        (16, align) if align >= 8 => Some((TrustIrTy::I64, 8, 2)),
        (size, align) if matches!(align, 1 | 2 | 4 | 8 | 16) && size > 0 => {
            let lane_bytes = align.min(8);
            let lanes = size / lane_bytes;
            (size % lane_bytes == 0 && lanes <= SLICE_SWAP_MAX_LANES)
                .then(|| (lane_ty(lane_bytes), lane_bytes, lanes as usize))
        }
        _ => None,
    }
}

/// `<[T]>::swap(&mut self, a, b)`: exchange the elements at indices `a` and `b`,
/// with the SAME `a < len && b < len` bounds panic std raises. The exchange is a
/// pure BYTE move (load both, store swapped), so it is sound for ANY element whose
/// bytes it moves exactly — the value is never interpreted. An element of size
/// 1/2/4/8 moves as one lane of its own width (integer/float/char/bool/`&T`/small
/// aggregate); a 16-byte element aligned to at least 8 (`i128`/`u128`,
/// `(u64, u64)`, `(f64, f64)`) moves as two 8-byte lanes. Any other element
/// (`[f64; 3]`, `[u32; 4]`, `(u8, u8, u8)`) moves as lanes of its own alignment,
/// capped at 8 bytes, so every lane access is aligned on every target (the
/// 8-byte lane is the widest scalar access this swap emits), up to
/// `SLICE_SWAP_MAX_LANES` lanes. A zero-sized element, an element aligned to
/// more than 16, or one needing more lanes fails closed.
/// The real `<[T]>::swap` body (`ptr::swap` over `&raw mut (*self)[i]`) hits an
/// unlowerable `Rvalue::RawPtr [Deref, Index]` shape, so we synthesize it directly.
fn lower_slice_swap_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    if callee_item_name_str(ctx.tcx, callee.def_id()).as_str() != "swap" {
        return Ok(false);
    }
    if call.args.len() != 3 {
        return Ok(false);
    }
    // The receiver must be `&mut [T]` (a slice fat pointer). A `Vec`/array `swap`
    // derefs to this; a user `swap`, `mem::swap`, or `HashMap::swap` never matches.
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let element_ty = match self_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => match inner.kind() {
            ty::Slice(e) => ctx.monomorphize_ty(*e),
            _ => return Ok(false),
        },
        _ => return Ok(false),
    };
    let (size, align) = element_layout_size_align(ctx.tcx, element_ty)?;
    // Byte-exact exchange: `lanes` loads/stores of `ety` at byte offsets
    // `0, lane_bytes, ..` cover the element exactly (`slice_swap_lanes`); an
    // element it does not cover fails closed rather than half-swap.
    let Some((ety, lane_bytes, lanes)) = slice_swap_lanes(size, align) else {
        return Err(format!(
            "<[{element_ty:?}]>::swap over a {size}-byte, {align}-aligned element (zero \
             sized, aligned to more than 16, or more than {SLICE_SWAP_MAX_LANES} lanes \
             of its alignment) is not modeled — fail closed"
        ));
    };

    // Resolve `{ data, len }` and the two indices.
    let (data, len) = slice_receiver_data_len(ctx, block, &call.args[0].node)?;
    let len_i64 = coerce_to_i64(ctx, block, len);
    let i_raw = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let i = coerce_to_i64(ctx, block, i_raw);
    let j_raw = lower_operand_to_value(ctx, body, block, &call.args[2].node)?;
    let j = coerce_to_i64(ctx, block, j_raw);

    // Bounds: `ok = (i <u len) && (j <u len)` — std's `a < len && b < len`.
    let i_ok = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ult,
            ty: TrustIrTy::I64,
            lhs: i,
            rhs: len_i64,
        })
        .with_result(i_ok),
    );
    let j_ok = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ult,
            ty: TrustIrTy::I64,
            lhs: j,
            rhs: len_i64,
        })
        .with_result(j_ok),
    );
    let ok = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::And,
            ty: TrustIrTy::Bool,
            lhs: i_ok,
            rhs: j_ok,
        })
        .with_result(ok),
    );

    // std's body indexes `self[a]` and then `self[b]`, each a MIR bounds check,
    // so the first failing index is `a` when it is out of bounds and `b`
    // otherwise.
    let failing_index = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::I64,
            cond: i_ok,
            then_val: j,
            else_val: i,
        })
        .with_result(failing_index),
    );
    let fail = std_panic_route::fail_target(
        ctx,
        body,
        call,
        std_panic_route::StdFailure::BoundsCheck {
            index: failing_index,
            len: len_i64,
        },
    )?;
    let Some(target) = call.target else {
        block.body.push(InstrNode::new(Inst::Br {
            target: fail,
            args: Vec::new(),
        }));
        return Ok(true);
    };
    let target = BlockId::new(target.index() as u32);

    // The actual exchange runs ONLY on the in-bounds edge (it MUTATES the buffer,
    // so unlike a value-producing intercept it must not execute on the fail path).
    let swap_id = ctx.fresh_block_id();
    block.body.push(InstrNode::new(Inst::CondBr {
        cond: ok,
        then_target: swap_id,
        then_args: Vec::new(),
        else_target: fail,
        else_args: Vec::new(),
    }));
    // Load BOTH elements' lanes before storing any, so `i == j` is a correct
    // no-op. `data`/`i`/`j` are referenced by dominance (this block is dominated
    // by the CondBr above).
    let mut sb = Block::new(swap_id);
    let base_i = emit_element_addr(ctx, &mut sb, data, i, size);
    let base_j = emit_element_addr(ctx, &mut sb, data, j, size);
    let mut moves = Vec::with_capacity(lanes);
    for lane in 0..lanes {
        let (addr_i, addr_j) = if lane == 0 {
            (base_i, base_j)
        } else {
            let lane_index = emit_i64_const(ctx, &mut sb, i128::from(lane as u64));
            (
                emit_element_addr(ctx, &mut sb, base_i, lane_index, lane_bytes),
                emit_element_addr(ctx, &mut sb, base_j, lane_index, lane_bytes),
            )
        };
        let vi = emit_typed_load(ctx, &mut sb, addr_i, ety.clone());
        let vj = emit_typed_load(ctx, &mut sb, addr_j, ety.clone());
        moves.push((addr_i, addr_j, vi, vj));
    }
    for (addr_i, addr_j, vi, vj) in moves {
        emit_typed_store(&mut sb, addr_i, ety.clone(), vj);
        emit_typed_store(&mut sb, addr_j, ety.clone(), vi);
    }
    sb.body.push(InstrNode::new(Inst::Br {
        target,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(sb);
    Ok(true)
}

/// `<[T]>::rotate_left(mid)` / `rotate_right(k)` (and `Vec`/array via deref): rotate
/// the slice in place, moving the first `mid` (resp. last `k`) elements to the other
/// end. Panics (std's `assert mid <= len`) on out of bounds. Implemented as the
/// classic THREE reversals — `rotate_left(mid)` = reverse(0,mid); reverse(mid,len);
/// reverse(0,len) — via three calls to the `__trustcg_slice_reverse_*` helper (with
/// `mid = len - k` for `rotate_right`). Pure byte swaps (the reversal helper), sound
/// for any pow2-<=8-byte element. The reversals run ONLY on the in-bounds edge (they
/// mutate the buffer).
fn lower_slice_rotate_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    let is_left = match callee_item_name_str(ctx.tcx, callee.def_id()).as_str() {
        "rotate_left" => true,
        "rotate_right" => false,
        _ => return Ok(false),
    };
    if call.args.len() != 2 {
        return Ok(false);
    }
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let element_ty = match self_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => match inner.kind() {
            ty::Slice(e) => ctx.monomorphize_ty(*e),
            _ => return Ok(false),
        },
        _ => return Ok(false),
    };
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    if !matches!(size, 1 | 2 | 4 | 8) {
        return Err(format!(
            "<[{element_ty:?}]>::rotate over a {size}-byte element (not 1/2/4/8) is not modeled \
             — fail closed"
        ));
    }

    let (data, len) = slice_receiver_data_len(ctx, block, &call.args[0].node)?;
    let len = coerce_to_i64(ctx, block, len);
    let k_raw = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let k = coerce_to_i64(ctx, block, k_raw);

    // Bounds: `k <= len` (both `rotate_left(mid)` and `rotate_right(k)` assert this).
    let ok = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ule,
            ty: TrustIrTy::I64,
            lhs: k,
            rhs: len,
        })
        .with_result(ok),
    );
    // `mid` = k for rotate_left, `len - k` for rotate_right (dead/underflow-unused on
    // the OOB edge, which traps before the reversals run).
    let mid = if is_left {
        k
    } else {
        let m = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::Sub,
                ty: TrustIrTy::I64,
                lhs: len,
                rhs: k,
            })
            .with_result(m),
        );
        m
    };
    let zero = emit_i64_const(ctx, block, 0);

    let fail =
        std_panic_route::fail_target(ctx, body, call, std_panic_route::StdFailure::Constant)?;
    let Some(target) = call.target else {
        block.body.push(InstrNode::new(Inst::Br {
            target: fail,
            args: Vec::new(),
        }));
        return Ok(true);
    };
    let target = BlockId::new(target.index() as u32);

    // In-bounds edge only: three reversals rotate the slice in place.
    let reverse_callee = slice_reverse_callee(ctx, size);
    let work_id = ctx.fresh_block_id();
    block.body.push(InstrNode::new(Inst::CondBr {
        cond: ok,
        then_target: work_id,
        then_args: Vec::new(),
        else_target: fail,
        else_args: Vec::new(),
    }));
    let mut wb = Block::new(work_id);
    wb.body.push(InstrNode::new(Inst::Call {
        callee: reverse_callee,
        args: vec![data, zero, mid],
    }));
    wb.body.push(InstrNode::new(Inst::Call {
        callee: reverse_callee,
        args: vec![data, mid, len],
    }));
    wb.body.push(InstrNode::new(Inst::Call {
        callee: reverse_callee,
        args: vec![data, zero, len],
    }));
    wb.body.push(InstrNode::new(Inst::Br {
        target,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(wb);
    Ok(true)
}

/// Intrinsics a pure sort key may call: integer operations
/// with no effect and no panic.
const SORT_KEY_PURE_INTRINSICS: &[&str] = &[
    "add_with_overflow",
    "bitreverse",
    "bswap",
    "cold_path",
    "ctlz",
    "ctlz_nonzero",
    "ctpop",
    "cttz",
    "cttz_nonzero",
    "disjoint_bitor",
    "exact_div",
    "likely",
    "mul_with_overflow",
    "rotate_left",
    "rotate_right",
    "saturating_add",
    "saturating_sub",
    "sub_with_overflow",
    "three_way_compare",
    "ub_checks",
    "unchecked_add",
    "unchecked_div",
    "unchecked_mul",
    "unchecked_rem",
    "unchecked_shl",
    "unchecked_shr",
    "unchecked_sub",
    "unlikely",
    "wrapping_add",
    "wrapping_mul",
    "wrapping_sub",
];

/// How far `sort_key_closure_is_pure` reads: call depth and distinct bodies.
const SORT_KEY_WALK_DEPTH: usize = 8;
const SORT_KEY_WALK_BODIES: usize = 64;

/// `Ok` when the key closure `closure_ty` is pure; `Err` names the first construct
/// that is not (or that this check cannot read). The key writes nothing outside
/// its own locals, exposes no address, and can fail in at most one way under
/// `panic=abort`, reporting one location. Calls through another address of an
/// equal value then yield the same key and, when one fails, the same panic.
///
/// Decided on the optimized MIR of the closure body and, recursively, of every
/// function it calls directly, each instantiated with its concrete arguments.
/// Cleanup blocks are skipped: they run only while unwinding, which this check
/// does not let the key start. Anything this cannot see fails the check:
///   * a call through a function pointer or a vtable, to a shim, to a body
///     without MIR (a foreign function, the allocator, the panic runtime), past
///     `SORT_KEY_WALK_DEPTH` / `SORT_KEY_WALK_BODIES`, to an intrinsic outside
///     `SORT_KEY_PURE_INTRINSICS`; a `Drop`, tail call, inline assembly, or any other
///     terminator but `Goto` / `SwitchInt` / `Return` / `Unreachable` /
///     `Assert` / `Call`;
///   * an `Assert` this crate's codegen keeps (`assert_is_elided_overflow_check`
///     drops the overflow checks of a `-Coverflow-checks=off` crate), with one
///     exception under `panic=abort`: ONE panic site, an overflow or
///     division check whose message is constant. Every algorithm keys every
///     element of a slice of two or more, so whichever element reaches that
///     site first, the same message at the same location aborts the program —
///     provided every key call terminates, so the walk then also refuses a
///     cycle in any body's control flow or in the call graph. Sites are
///     `SortKeyPanicSite`s: a check in a `#[track_caller]` body reports the
///     call that reached it, so the walk reads such a body once per call chain
///     into it and counts its checks per chain; the closure itself having the
///     attribute refuses. Two or more distinct sites refuse: which one a call
///     order reaches first is observable (measured: a subtraction and a
///     multiplication overflow, or two divisions by zero, or one subtraction in
///     a `#[track_caller]` callee reached from two calls, report different
///     locations under std and the model);
///   * any write outside the key's own locals (an `Assign`,
///     `SetDiscriminant` or `CopyNonOverlapping` through a pointer), and every
///     form this check knows to turn an address into a value
///     (`rvalue_observes_an_address`): a cast from a reference or pointer to
///     anything but a pointer, a transmute from a non-numeric type, a binary
///     operation on raw or fn pointers, a thread-local reference, a union field
///     (any projection through a union), and a pointer cast or raw-pointer
///     aggregate that reads memory which may hold an address at another type.
///
/// Reads — of the argument, of captured state, of statics — are allowed for
/// a pure key because nothing writes memory while it runs: the sort only
/// moves elements, whose values the key reads through its argument.
fn sort_key_closure_is_pure<'tcx>(tcx: TyCtxt<'tcx>, closure_ty: Ty<'tcx>) -> Result<(), String> {
    let ty::Closure(def_id, args) = closure_ty.kind() else {
        return Err(format!("the key {closure_ty:?} is not a closure"));
    };
    let typing_env = ty::TypingEnv::fully_monomorphized();
    let Ok(Some(instance)) = Instance::try_resolve(tcx, typing_env, *def_id, *args) else {
        return Err(format!(
            "the key closure {closure_ty:?} does not resolve to a body"
        ));
    };
    let mut walk = SortKeyWalk {
        tcx,
        abort: panic_is_abort(tcx),
        read: Vec::new(),
        walked: 0,
        stack: Vec::new(),
        kept_asserts: Vec::new(),
        may_not_terminate: None,
    };
    walk.body(instance, &[])?;
    if let [first, second, ..] = walk.kept_asserts.as_slice() {
        return Err(format!(
            "it may panic at {} sites ({} and {}), so which one a call order reaches \
             first is observable",
            walk.kept_asserts.len(),
            first.described,
            second.described
        ));
    }
    if let (Some(assert), Some(cycle)) = (walk.kept_asserts.first(), walk.may_not_terminate) {
        return Err(format!(
            "it may panic ({}) and may not terminate ({cycle}), so which of the two a \
             call order reaches first is observable",
            assert.described
        ));
    }
    Ok(())
}

/// The calls through which the walk entered a `#[track_caller]` body, from the
/// outermost one, made in a body without the attribute, inward: each is the
/// calling body and the call's source position. A panic in that body reports
/// a location that is a function of this chain alone (its caller's call, or a
/// position inside the body for a check inlined from a callee without the
/// attribute), so equal chains report equal locations.
type SortKeyCallChain<'tcx> = Vec<(Instance<'tcx>, mir::SourceInfo)>;

/// One panic site a pure key keeps under `panic=abort`
/// (`sort_key_closure_is_pure`): the call chain into a `#[track_caller]` body
/// (empty for any other body), the body, the `Assert` terminator's source
/// position and its constant message. Two `Assert`s that agree on all four
/// panic with the same message at the same location; any other two count as
/// distinct sites (at worst an over-count, which refuses).
struct SortKeyPanicSite<'tcx> {
    chain: SortKeyCallChain<'tcx>,
    instance: Instance<'tcx>,
    source_info: mir::SourceInfo,
    message: String,
    described: String,
}

struct SortKeyWalk<'tcx> {
    tcx: TyCtxt<'tcx>,
    abort: bool,
    /// Bodies without `#[track_caller]` already read: their checks report
    /// their own positions, so one read covers every call.
    read: Vec<Instance<'tcx>>,
    /// Every body read, a `#[track_caller]` one once per call chain into it.
    walked: usize,
    stack: Vec<Instance<'tcx>>,
    kept_asserts: Vec<SortKeyPanicSite<'tcx>>,
    may_not_terminate: Option<String>,
}

impl<'tcx> SortKeyWalk<'tcx> {
    /// Read `instance`'s body, entered through `chain` when it has
    /// `#[track_caller]` (empty otherwise; see `SortKeyCallChain`).
    fn body(
        &mut self,
        instance: Instance<'tcx>,
        chain: &[(Instance<'tcx>, mir::SourceInfo)],
    ) -> Result<(), String> {
        let tcx = self.tcx;
        let name = tcx.def_path_str(instance.def_id());
        let tracked = instance.def.requires_caller_location(tcx);
        if self.stack.contains(&instance) {
            self.may_not_terminate
                .get_or_insert_with(|| format!("`{name}` is recursive"));
            return Ok(());
        }
        if !tracked && self.read.contains(&instance) {
            return Ok(());
        }
        if self.stack.len() >= SORT_KEY_WALK_DEPTH || self.walked >= SORT_KEY_WALK_BODIES {
            return Err(format!(
                "its call graph reaches `{name}`, past the depth or breadth this check reads"
            ));
        }
        let ty::InstanceKind::Item(def_id) = instance.def else {
            return Err(format!(
                "it calls `{name}` through a {:?} shim",
                instance.def
            ));
        };
        if !tcx.is_mir_available(def_id) {
            return Err(format!("it calls `{name}`, whose MIR is not available"));
        }
        if !tracked {
            self.read.push(instance);
        }
        self.walked += 1;
        self.stack.push(instance);
        let body = tcx.instance_mir(instance.def);
        let result = self.blocks(instance, body, &name, chain);
        self.stack.pop();
        result
    }

    fn blocks(
        &mut self,
        instance: Instance<'tcx>,
        body: &Body<'tcx>,
        name: &str,
        chain: &[(Instance<'tcx>, mir::SourceInfo)],
    ) -> Result<(), String> {
        let tcx = self.tcx;
        let tracked = instance.def.requires_caller_location(tcx);
        let typing_env = ty::TypingEnv::fully_monomorphized();
        let mono = |ty: Ty<'tcx>| {
            instance.instantiate_mir_and_normalize_erasing_regions(
                tcx,
                typing_env,
                ty::EarlyBinder::bind(tcx, ty),
            )
        };
        let derefs = |place: &Place<'tcx>| {
            place
                .projection
                .iter()
                .any(|p| matches!(p, ProjectionElem::Deref))
        };
        if body_cfg_is_cyclic(body) {
            self.may_not_terminate
                .get_or_insert_with(|| format!("`{name}` loops"));
        }
        for (block, data) in body
            .basic_blocks
            .iter_enumerated()
            .filter(|(_, data)| !data.is_cleanup)
        {
            if let Some(union_ty) = block_projects_through_a_union(tcx, body, block, data) {
                return Err(format!(
                    "`{name}` projects through the union {union_ty:?}, whose fields \
                     reinterpret one another's bytes"
                ));
            }
            for statement in &data.statements {
                let effect = match &statement.kind {
                    StatementKind::Assign(boxed) => {
                        let (place, rvalue) = &**boxed;
                        if derefs(place) {
                            Some("stores through a pointer".to_owned())
                        } else {
                            rvalue_observes_an_address(tcx, body, rvalue, &mono)
                        }
                    }
                    StatementKind::SetDiscriminant { place, .. } => {
                        derefs(place).then(|| "stores through a pointer".to_owned())
                    }
                    StatementKind::Intrinsic(intrinsic) => match &**intrinsic {
                        mir::NonDivergingIntrinsic::Assume(_) => None,
                        mir::NonDivergingIntrinsic::CopyNonOverlapping(_) => {
                            Some("copies through a pointer".to_owned())
                        }
                    },
                    StatementKind::StorageLive(_)
                    | StatementKind::StorageDead(_)
                    | StatementKind::Nop
                    | StatementKind::FakeRead(..)
                    | StatementKind::PlaceMention(..)
                    | StatementKind::AscribeUserType(..)
                    | StatementKind::Coverage(..)
                    | StatementKind::ConstEvalCounter => None,
                    other => Some(format!("has a {other:?} statement")),
                };
                if let Some(effect) = effect {
                    return Err(format!("`{name}` {effect}"));
                }
            }
            match &data.terminator().kind {
                TerminatorKind::Goto { .. }
                | TerminatorKind::SwitchInt { .. }
                | TerminatorKind::Return
                | TerminatorKind::Unreachable => {}
                TerminatorKind::Assert {
                    cond,
                    expected,
                    msg,
                    ..
                } => {
                    if assert_is_elided_overflow_check(tcx, msg)
                        || sort_key_assert_never_fires(tcx, instance, body, cond, *expected)
                    {
                        continue;
                    }
                    let Some(message) = sort_key_constant_assert_message(msg) else {
                        return Err(format!("`{name}` may panic ({msg:?})"));
                    };
                    if !self.abort {
                        return Err(format!("`{name}` may panic ({msg:?})"));
                    }
                    if tracked && chain.is_empty() {
                        return Err(format!(
                            "`{name}` may panic ({msg:?}) at the location of a call this \
                             model does not make (`#[track_caller]`)"
                        ));
                    }
                    let source_info = data.terminator().source_info;
                    let seen = self.kept_asserts.iter().any(|site| {
                        site.chain.as_slice() == chain
                            && site.instance == instance
                            && site.source_info == source_info
                            && site.message == message
                    });
                    if !seen {
                        self.kept_asserts.push(SortKeyPanicSite {
                            chain: chain.to_vec(),
                            instance,
                            source_info,
                            described: format!("`{name}`: {msg:?}"),
                            message,
                        });
                    }
                }
                TerminatorKind::Call {
                    func, destination, ..
                } => {
                    if derefs(destination) {
                        return Err(format!("`{name}` stores a call result through a pointer"));
                    }
                    let func_ty = mono(func.ty(body, tcx));
                    let Some(item) = fn_items::view(func_ty.kind()) else {
                        return Err(format!("`{name}` calls through a function pointer"));
                    };
                    let callee_def = item.def_id();
                    let callee_args = item.require_unbound_args("sort-key purity")?;
                    let Ok(Some(callee)) =
                        Instance::try_resolve(tcx, typing_env, callee_def, callee_args)
                    else {
                        return Err(format!(
                            "`{name}` calls `{}`, which does not resolve",
                            tcx.def_path_str(callee_def)
                        ));
                    };
                    if let ty::InstanceKind::Intrinsic(intrinsic) = callee.def {
                        let intrinsic_name = tcx.item_name(intrinsic);
                        let intrinsic_name = intrinsic_name.as_str();
                        let allowed = SORT_KEY_PURE_INTRINSICS.contains(&intrinsic_name);
                        if !allowed {
                            return Err(format!("`{name}` calls the intrinsic `{intrinsic_name}`"));
                        }
                        continue;
                    }
                    // A `#[track_caller]` callee's checks report this call (or,
                    // when this body has the attribute too, the chain into it).
                    let callee_chain: SortKeyCallChain<'tcx> =
                        if callee.def.requires_caller_location(tcx) {
                            let mut callee_chain =
                                if tracked { chain.to_vec() } else { Vec::new() };
                            callee_chain.push((instance, data.terminator().source_info));
                            callee_chain
                        } else {
                            Vec::new()
                        };
                    self.body(callee, &callee_chain)?;
                }
                other => {
                    return Err(format!("`{name}` has a `{}` terminator", other.name()));
                }
            }
        }
        Ok(())
    }
}

/// The panic message of `msg` when it names no operand, so two failures of
/// that `Assert` print the same text: arithmetic overflow, negation overflow,
/// division and remainder by zero. `None` for any other kind (a bounds check
/// names its index and length; an alignment or null check names an address).
fn sort_key_constant_assert_message(msg: &mir::AssertKind<Operand<'_>>) -> Option<String> {
    match msg {
        mir::AssertKind::Overflow(op, ..) => Some(format!("Overflow({op:?})")),
        mir::AssertKind::OverflowNeg(_) => Some("OverflowNeg".to_owned()),
        mir::AssertKind::DivisionByZero(_) => Some("DivisionByZero".to_owned()),
        mir::AssertKind::RemainderByZero(_) => Some("RemainderByZero".to_owned()),
        _ => None,
    }
}

/// Whether the assert on `cond` in `instance`'s `body` can never fire because
/// its condition always equals `expected` (`sort_key_assert_bool`): `-O0`'s
/// division guards for a constant divisor, `divisor == 0` and
/// `divisor == -1 && dividend == MIN`, are the cases this exists for.
fn sort_key_assert_never_fires<'tcx>(
    tcx: TyCtxt<'tcx>,
    instance: Instance<'tcx>,
    body: &Body<'tcx>,
    cond: &Operand<'tcx>,
    expected: bool,
) -> bool {
    sort_key_assert_bool(tcx, instance, body, cond, 0) == Some(expected)
}

/// The value a boolean MIR operand always has, when this can tell: a constant;
/// or a local whose only write is one assignment (no call result lands in it,
/// no borrow of it exists, it is not an argument) of `Eq` / `Ne` of two
/// integer constants, of `BitAnd` with an operand that is always `false`, of
/// `BitOr` with one that is always `true`, of `Not`, or of a `Use` of such an
/// operand. `None` for anything else.
fn sort_key_assert_bool<'tcx>(
    tcx: TyCtxt<'tcx>,
    instance: Instance<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
    depth: usize,
) -> Option<bool> {
    if depth > 6 {
        return None;
    }
    let typing_env = ty::TypingEnv::fully_monomorphized();
    let bits = |operand: &Operand<'tcx>| -> Option<u128> {
        let Operand::Constant(constant) = operand else {
            return None;
        };
        instance
            .instantiate_mir_and_normalize_erasing_regions(
                tcx,
                typing_env,
                ty::EarlyBinder::bind(tcx, constant.const_),
            )
            .try_eval_bits(tcx, typing_env)
    };
    let place = match operand {
        Operand::Constant(_) => return bits(operand).map(|b| b != 0),
        Operand::Copy(place) | Operand::Move(place) if place.projection.is_empty() => place,
        _ => return None,
    };
    let written_elsewhere = body.args_iter().any(|arg| arg == place.local)
        || body.basic_blocks.iter().any(|data| {
            matches!(&data.terminator().kind,
                TerminatorKind::Call { destination, .. } if destination.local == place.local)
                || data.statements.iter().any(|statement| {
                    matches!(&statement.kind, StatementKind::Assign(boxed)
                        if matches!(&boxed.1, Rvalue::Ref(_, _, borrowed)
                            | Rvalue::RawPtr(_, borrowed) if borrowed.local == place.local))
                })
        });
    if written_elsewhere {
        return None;
    }
    let mut definitions = body
        .basic_blocks
        .iter()
        .flat_map(|data| data.statements.iter())
        .filter_map(|statement| match &statement.kind {
            StatementKind::Assign(boxed) if boxed.0.local == place.local => {
                Some((&boxed.0, &boxed.1))
            }
            _ => None,
        });
    let (Some((target, rvalue)), None) = (definitions.next(), definitions.next()) else {
        return None;
    };
    if !target.projection.is_empty() {
        return None;
    }
    let value =
        |operand: &Operand<'tcx>| sort_key_assert_bool(tcx, instance, body, operand, depth + 1);
    match rvalue {
        Rvalue::Use(inner, ..) => value(inner),
        Rvalue::UnaryOp(mir::UnOp::Not, inner) => value(inner).map(|b| !b),
        Rvalue::BinaryOp(op @ (mir::BinOp::Eq | mir::BinOp::Ne), operands) => {
            let (lhs, rhs) = (bits(&operands.0)?, bits(&operands.1)?);
            Some((lhs == rhs) == (*op == mir::BinOp::Eq))
        }
        Rvalue::BinaryOp(mir::BinOp::BitAnd, operands) => {
            match (value(&operands.0), value(&operands.1)) {
                (Some(false), _) | (_, Some(false)) => Some(false),
                (Some(true), Some(true)) => Some(true),
                _ => None,
            }
        }
        Rvalue::BinaryOp(mir::BinOp::BitOr, operands) => {
            match (value(&operands.0), value(&operands.1)) {
                (Some(true), _) | (_, Some(true)) => Some(true),
                (Some(false), Some(false)) => Some(false),
                _ => None,
            }
        }
        _ => None,
    }
}

/// Whether `body`'s control flow (cleanup blocks excluded) has a cycle.
fn body_cfg_is_cyclic(body: &Body<'_>) -> bool {
    let blocks = &body.basic_blocks;
    // 0 = unvisited, 1 = on the DFS stack, 2 = done.
    let mut state = vec![0u8; blocks.len()];
    for root in blocks.indices() {
        if state[root.index()] != 0 || blocks[root].is_cleanup {
            continue;
        }
        let mut stack = vec![(root, false)];
        while let Some((block, exiting)) = stack.pop() {
            if exiting {
                state[block.index()] = 2;
                continue;
            }
            if state[block.index()] != 0 {
                continue;
            }
            state[block.index()] = 1;
            stack.push((block, true));
            for successor in blocks[block].terminator().successors() {
                if blocks[successor].is_cleanup {
                    continue;
                }
                match state[successor.index()] {
                    0 => stack.push((successor, false)),
                    1 => return true,
                    _ => {}
                }
            }
        }
    }
    false
}

/// For a pure key: a description of the address `rvalue` turns into a value,
/// if it does (`sort_key_closure_is_pure`).
fn rvalue_observes_an_address<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    rvalue: &Rvalue<'tcx>,
    mono: &impl Fn(Ty<'tcx>) -> Ty<'tcx>,
) -> Option<String> {
    let numeric = |ty: Ty<'tcx>| {
        ty.is_integral() || ty.is_floating_point() || matches!(ty.kind(), ty::Bool | ty::Char)
    };
    match rvalue {
        Rvalue::ThreadLocalRef(_) => Some("takes a thread-local reference".to_owned()),
        Rvalue::Cast(kind, operand, to) => {
            let from = mono(operand.ty(body, tcx));
            let to = mono(*to);
            let reinterprets = matches!(kind, mir::CastKind::PtrToPtr)
                && match (from.builtin_deref(true), to.builtin_deref(true)) {
                    (Some(from), Some(to)) => pointee_view_may_read_an_address(tcx, from, to),
                    _ => true,
                };
            let observes = matches!(kind, mir::CastKind::PointerExposeProvenance)
                || (matches!(kind, mir::CastKind::Transmute) && !numeric(from))
                || ((from.is_any_ptr() || from.is_box()) && !(to.is_any_ptr() || to.is_box()))
                || reinterprets;
            observes.then(|| format!("casts {from:?} to {to:?}"))
        }
        Rvalue::BinaryOp(op, operands) => {
            let lhs = mono(operands.0.ty(body, tcx));
            (lhs.is_raw_ptr() || lhs.is_fn_ptr())
                .then(|| format!("applies {op:?} to the pointer {lhs:?}"))
        }
        // `ptr::from_raw_parts` / `slice_from_raw_parts`: a raw pointer to
        // `pointee` over a data pointer of another type is a pointer cast too.
        Rvalue::Aggregate(kind, operands) => {
            let mir::AggregateKind::RawPtr(pointee, _) = &**kind else {
                return None;
            };
            let data = mono(operands.iter().next()?.ty(body, tcx));
            let pointee = mono(*pointee);
            let reinterprets = data
                .builtin_deref(true)
                .is_none_or(|from| pointee_view_may_read_an_address(tcx, from, pointee));
            reinterprets.then(|| format!("builds a raw pointer to {pointee:?} over {data:?}"))
        }
        _ => None,
    }
}

/// Whether reading a `to` through a pointer that pointed at a `from` may read
/// memory holding an address at a type that is not that address's: `from`
/// may hold one (`type_may_hold_an_address`) and `to` is neither `from`, nor
/// its element (`[T]` / `[T; N]` / `str` to `T` / `u8`), nor a sequence of it.
fn pointee_view_may_read_an_address<'tcx>(tcx: TyCtxt<'tcx>, from: Ty<'tcx>, to: Ty<'tcx>) -> bool {
    let element = |ty: Ty<'tcx>| match ty.kind() {
        ty::Slice(element) | ty::Array(element, _) => Some(*element),
        ty::Str => Some(tcx.types.u8),
        _ => None,
    };
    let same_view = from == to
        || element(from) == Some(to)
        || element(to) == Some(from)
        || (element(from).is_some() && element(from) == element(to));
    !same_view && type_may_hold_an_address(tcx, from, 0)
}

/// Whether a value of `ty` may hold an address in its bytes: false only for
/// integers, floats, `bool`, `char`, `str`, `!` and sequences, tuples, structs
/// and enums built from them alone; true for anything else (a reference, a raw
/// or fn pointer, a `Box`, a union, a trait object, an unresolved type).
fn type_may_hold_an_address<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, depth: u32) -> bool {
    if depth > 8 {
        return true;
    }
    let typing_env = ty::TypingEnv::fully_monomorphized();
    match ty.kind() {
        ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char | ty::Str | ty::Never => {
            false
        }
        ty::Array(element, _) | ty::Slice(element) | ty::Pat(element, _) => {
            type_may_hold_an_address(tcx, *element, depth + 1)
        }
        ty::Tuple(fields) => fields
            .iter()
            .any(|field| type_may_hold_an_address(tcx, field, depth + 1)),
        ty::Adt(adt, args) if !adt.is_union() && !adt.is_box() => adt.all_fields().any(|field| {
            tcx.try_normalize_erasing_regions(typing_env, field.ty(tcx, *args))
                .map_or(true, |field_ty| {
                    type_may_hold_an_address(tcx, field_ty, depth + 1)
                })
        }),
        _ => true,
    }
}

/// For a pure key: the union type, if any place in
/// `data` (statements and terminator) projects through one of its fields.
/// Reading a union field another field wrote reinterprets its bytes, a
/// pointer's among them, so a pure key never touches one.
fn block_projects_through_a_union<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    block: mir::BasicBlock,
    data: &mir::BasicBlockData<'tcx>,
) -> Option<Ty<'tcx>> {
    use rustc_middle::mir::visit::{PlaceContext, Visitor};
    struct UnionProjection<'a, 'tcx> {
        tcx: TyCtxt<'tcx>,
        body: &'a Body<'tcx>,
        found: Option<Ty<'tcx>>,
    }
    impl<'tcx> Visitor<'tcx> for UnionProjection<'_, 'tcx> {
        fn visit_place(&mut self, place: &Place<'tcx>, _: PlaceContext, _: mir::Location) {
            if self.found.is_some() {
                return;
            }
            for (base, element) in place.as_ref().iter_projections() {
                let base_ty = base.ty(self.body, self.tcx).ty;
                if matches!(element, ProjectionElem::Field(..)) && base_ty.is_union() {
                    self.found = Some(base_ty);
                    return;
                }
            }
        }
    }
    let mut visitor = UnionProjection {
        tcx,
        body,
        found: None,
    };
    visitor.visit_basic_block_data(block, data);
    visitor.found
}

/// The checked operands of a `sort_by_key`-family call over an integer slice
/// (`sort_by_key_operands`): every type the models need, nothing emitted yet.
struct SortByKeyOperands<'tcx> {
    /// The element's width-keyed load/store type (elements move as raw bytes).
    element_ir: TrustIrTy,
    /// The element's size in bytes (1, 2, 4 or 8).
    size: u64,
    /// The monomorphized key closure type.
    closure_ty: Ty<'tcx>,
    /// The key's trust-ir type (an integer of at most 64 bits).
    key_ir: TrustIrTy,
    key_signed: bool,
}

/// Check a `sort_by_key` / `sort_unstable_by_key` call's
/// shape: an integer element of at most 64 bits and a closure key returning an
/// integer of at most 64 bits. Anything else refuses by name.
fn sort_by_key_operands<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
    element_ty: Ty<'tcx>,
) -> Result<SortByKeyOperands<'tcx>, String> {
    // Element must be a scalar integer of width <= 64 (loaded/stored as one lane).
    if !is_integer(element_ty) {
        return Err(format!(
            "<[{element_ty:?}]>::{name} over a non-integer element is not modeled — fail closed"
        ));
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    // The element is moved as RAW BYTES (loaded/stored, never compared directly —
    // only its closure-computed key is compared). Use the width-keyed signed-flavored
    // load/store type the proven `__trustcg_vec_sort_T` helper uses, so the element
    // bytes round-trip through already-proven load/store opcodes.
    let element_ir = match size {
        1 => TrustIrTy::I8,
        2 => TrustIrTy::I16,
        4 => TrustIrTy::I32,
        8 => TrustIrTy::I64,
        other => {
            return Err(format!(
                "<[{element_ty:?}]>::{name} over a {other}-byte element is not modeled — fail closed"
            ));
        }
    };
    // The closure argument (arg 1) must be a closure `&T -> K`.
    let Some(closure_operand) = call.args.get(1) else {
        return Err(format!(
            "<[{element_ty:?}]>::{name} is missing its key closure argument"
        ));
    };
    let closure_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &closure_operand.node)?);
    let ty::Closure(_, cargs) = closure_ty.kind() else {
        return Err(format!(
            "<[{element_ty:?}]>::{name} key argument is not a closure"
        ));
    };
    // The callee owns the key closure; the sort below runs no glue for it.
    refuse_unlowered_owned_drop(
        ctx.tcx,
        closure_ty,
        "key closure",
        &format!("slice::{name}"),
    )?;
    // The key output type must be a scalar integer of width <= 64 (compared by `<`).
    let sig = ctx
        .tcx
        .instantiate_bound_regions_with_erased(cargs.as_closure().sig());
    let key_rust_ty = ctx.monomorphize_ty(sig.output());
    if !is_integer(key_rust_ty) {
        return Err(format!(
            "<[{element_ty:?}]>::{name} key is not an integer (only integer keys are modeled) — fail closed"
        ));
    }
    let key_ir = rust_ty_to_trust_ir_ty(ctx.tcx, key_rust_ty)?;
    if !key_ir.is_integer() || key_ir.bit_width().map_or(true, |w| w > 64) {
        return Err(format!(
            "<[{element_ty:?}]>::{name} key has no <=64-bit integer trust-ir type — fail closed"
        ));
    }
    Ok(SortByKeyOperands {
        element_ir,
        size,
        closure_ty,
        key_ir,
        key_signed: is_signed_integer(key_rust_ty),
    })
}

/// Emit what a `sort_by_key`-family model reads before its loops: the key
/// closure's env pointer, materialized ONCE (a capturing closure's env slot via
/// `closure_env_ptr`, or a never-read `Alloca I8` placeholder for a ZST closure,
/// whose body takes no env), and the `&mut [T]` self argument's memory-backed
/// `{ data, len }` lanes. Returns `(key_env, data, len)`.
fn sort_by_key_env_and_slice<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
    element_ty: Ty<'tcx>,
    closure_ty: Ty<'tcx>,
) -> Result<(ValueId, ValueId, ValueId), String> {
    let key_env = if is_zero_sized_ty(ctx.tcx, closure_ty) {
        let d = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: TrustIrTy::I8,
                count: None,
                align: None,
            })
            .with_result(d),
        );
        d
    } else {
        closure_env_ptr(ctx, body, block, &call.args[1].node)?
    };

    // Resolve the `&mut [T]` self argument to its memory-backed `{ data, len }` slot.
    let Some(self_arg) = call.args.first() else {
        return Err(format!(
            "<[{element_ty:?}]>::{name} is missing its self argument"
        ));
    };
    let (Operand::Copy(place) | Operand::Move(place)) = &self_arg.node else {
        return Err(format!(
            "<[{element_ty:?}]>::{name} self argument is not a place operand"
        ));
    };
    if !place.projection.is_empty() {
        return Err(format!(
            "<[{element_ty:?}]>::{name} self argument uses a projected place"
        ));
    }
    if !local_is_memory_backed(ctx, place.local) {
        return Err(format!(
            "<[{element_ty:?}]>::{name} self argument is not a memory-backed slice"
        ));
    }
    let data = load_fat_ptr_data(ctx, block, place.local)?;
    let data = coerce_to_plain_ptr(ctx, block, data);
    let len = load_fat_ptr_meta(ctx, block, place.local)?;
    let len = coerce_to_i64(ctx, block, len);
    Ok((key_env, data, len))
}

/// Lower `<[T]>::sort_by_key(f)` / `sort_unstable_by_key(f)` for an integer
/// element `T` and a closure key `f: &T -> K` returning an integer: an in-place,
/// closure-driven STABLE INSERTION SORT over the slice buffer, structurally the
/// `__trustcg_vec_sort_T` helper with each comparison `keyfn(a[j]) > ikey`, where
/// `ikey = keyfn(insertee)` is computed once per outer step.
///
/// What the model reproduces, and what it does not:
///   * the ORDER. Keys compare by integer `<`, a valid total order, so a stable
///     sort's permutation is unique: `sort_by_key`'s stable driftsort (and its
///     insertion sort up to 20 elements) produces exactly this one.
///     `sort_unstable_by_key` is std's insertion sort up to 20 elements and
///     ipnsort above, which may order distinct elements with equal keys
///     differently (measured: 40 elements keyed by `x / 100`, at O0..O3), so
///     it is modeled only when its key is also injective on the element
///     (`sort_key_is_injective`): equal keys then hold equal elements.
///   * NOT the KEY CALLS. std's comparator is `|a, b| f(a).lt(&f(b))`, two calls
///     per comparison in its own sequence, with the insertee read from a stack
///     copy; this model makes one call per comparison plus one per insertee, on
///     the element in place. That difference is invisible only for a key that
///     `sort_key_closure_is_pure` admits; any other
///     `sort_by_key` key refuses by name (`[TCG-SORT-KEY-EFFECT]`).
///   * NOT std's scratch allocation: above 20 elements std's stable sort takes a
///     scratch buffer from a 4 KiB stack array when it fits and from the global
///     allocator otherwise; this model, like the `sort` helper, allocates
///     nothing (measured: a counting allocator around a 2000-element `u32`
///     `sort_by_key` saw one allocation under LLVM, none here, at O0/O1).
///
/// A `sort_unstable_by_key` the model does not admit (an impure or non-injective
/// key, a non-integer or wider-than-64-bit element or key) is declined
/// (`Ok(false)`): the call takes the ordinary path and std's own body sorts, or
/// is refused by name there. A `sort_by_key` outside the subset fails CLOSED, as
/// does a non-place / projected / non-memory-backed slice arg for either.
fn lower_slice_sort_by_key<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
    element_ty: Ty<'tcx>,
) -> Result<bool, String> {
    // Nothing is emitted before the model commits, so declining stays possible.
    let unstable = name == "sort_unstable_by_key";
    let SortByKeyOperands {
        element_ir,
        size,
        closure_ty,
        key_ir,
        key_signed,
    } = match sort_by_key_operands(ctx, body, call, name, element_ty) {
        Ok(operands) => operands,
        Err(_) if unstable => return Ok(false),
        Err(why) => return Err(why),
    };
    if let Err(why) = sort_key_closure_is_pure(ctx.tcx, closure_ty) {
        if unstable {
            return Ok(false);
        }
        return Err(format!(
            "[TCG-SORT-KEY-EFFECT] <[{element_ty:?}]>::{name}: the key closure is not a pure \
             function of its argument ({why}). std calls it twice per comparison, in an order \
             this model's insertion sort does not reproduce, and std's own sort body is not \
             lowered here — fail closed"
        ));
    }
    if unstable && !sort_key_is_injective(ctx.tcx, closure_ty) {
        return Ok(false);
    }
    let (key_env, data, len) =
        sort_by_key_env_and_slice(ctx, body, block, call, name, element_ty, closure_ty)?;

    // Scratch slots (memory-backed => phi-free loops). `i_slot`/`j_slot` are the
    // outer/inner loop counters; `insertee_slot` holds the element being inserted
    // (its buffer position is overwritten by the shift, so it must be saved).
    let alloca_i64 = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block| -> ValueId {
        let v = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: TrustIrTy::I64,
                count: None,
                align: None,
            })
            .with_result(v),
        );
        v
    };
    let i_slot = alloca_i64(ctx, block);
    let j_slot = alloca_i64(ctx, block);
    // The insertee's key, saved across the inner loop (computed once per outer step).
    let ikey_slot = alloca_i64(ctx, block);
    let insertee_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: element_ir.clone(),
            count: None,
            align: None,
        })
        .with_result(insertee_slot),
    );

    let size_c = i128::from(size);
    // Helper: address of buffer element at i64 index `idx` (`data + idx*size`).
    fn elem_addr(
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        data: ValueId,
        idx: ValueId,
        size_c: i128,
    ) -> ValueId {
        let stride = emit_i64_const(ctx, block, size_c);
        let off = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::Mul,
                ty: TrustIrTy::I64,
                lhs: idx,
                rhs: stride,
            })
            .with_result(off),
        );
        let base_int = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::PtrToInt,
                src_ty: TrustIrTy::Ptr,
                dst_ty: TrustIrTy::I64,
                operand: data,
            })
            .with_result(base_int),
        );
        let sum = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::Add,
                ty: TrustIrTy::I64,
                lhs: base_int,
                rhs: off,
            })
            .with_result(sum),
        );
        let addr = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::IntToPtr,
                src_ty: TrustIrTy::I64,
                dst_ty: TrustIrTy::Ptr,
                operand: sum,
            })
            .with_result(addr),
        );
        addr
    }

    // === Block layout (all phi-free; counters live in slots). ===
    //   entry(cur): i = 1; -> outer_hdr
    //   outer_hdr:  if i < len -> outer_body else exit
    //   outer_body: insertee = a[i]; ikey = keyfn(&a[i]); j = i-1; -> inner_hdr
    //   inner_hdr:  if j >= 0 -> inner_test else inner_done
    //   inner_test: if keyfn(&a[j]) > ikey -> inner_shift else inner_done
    //   inner_shift:a[j+1] = a[j]; j -= 1; -> inner_hdr
    //   inner_done: a[j+1] = insertee; i += 1; -> outer_hdr
    //   exit:       -> call successor
    let outer_hdr = ctx.fresh_block_id();
    let outer_body = ctx.fresh_block_id();
    let inner_hdr = ctx.fresh_block_id();
    let inner_test = ctx.fresh_block_id();
    let inner_shift = ctx.fresh_block_id();
    let inner_done = ctx.fresh_block_id();
    let exit_id = ctx.fresh_block_id();

    // entry: i = 1.
    let one = emit_i64_const(ctx, block, 1);
    emit_typed_store(block, i_slot, TrustIrTy::I64, one);
    block.body.push(InstrNode::new(Inst::Br {
        target: outer_hdr,
        args: Vec::new(),
    }));

    // outer_hdr: if i <u len -> outer_body else exit.
    let mut oh = Block::new(outer_hdr);
    let i_v = emit_typed_load(ctx, &mut oh, i_slot, TrustIrTy::I64);
    let cont = ctx.fresh_value();
    oh.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ult,
            ty: TrustIrTy::I64,
            lhs: i_v,
            rhs: len,
        })
        .with_result(cont),
    );
    oh.body.push(InstrNode::new(Inst::CondBr {
        cond: cont,
        then_target: outer_body,
        then_args: Vec::new(),
        else_target: exit_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(oh);

    // outer_body: insertee = a[i]; ikey = keyfn(&a[i]); j = i-1.
    let mut ob = Block::new(outer_body);
    let i_v = emit_typed_load(ctx, &mut ob, i_slot, TrustIrTy::I64);
    let ai_addr = elem_addr(ctx, &mut ob, data, i_v, size_c);
    let ai = emit_typed_load(ctx, &mut ob, ai_addr, element_ir.clone());
    emit_typed_store(&mut ob, insertee_slot, element_ir.clone(), ai);
    // ikey = keyfn(&a[i]). The buffer address IS a valid `&T`.
    let ikey_raw = emit_closure_call_1(
        ctx,
        &mut ob,
        closure_ty,
        key_env, // env_ptr (loop-invariant; a placeholder for a ZST closure)
        ai_addr, // arg: &T
        key_ir.clone(),
    )?;
    // Stash the insertee key for the inner-loop comparisons (env_ptr arg above is a
    // harmless unused pointer for a ZST closure; the real `&T` is the second arg).
    let ikey = convert_scalar(ctx, &mut ob, ikey_raw, &key_ir, &TrustIrTy::I64);
    emit_typed_store(&mut ob, ikey_slot, TrustIrTy::I64, ikey);
    let one = emit_i64_const(ctx, &mut ob, 1);
    let jm = ctx.fresh_value();
    ob.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: i_v,
            rhs: one,
        })
        .with_result(jm),
    );
    emit_typed_store(&mut ob, j_slot, TrustIrTy::I64, jm);
    ob.body.push(InstrNode::new(Inst::Br {
        target: inner_hdr,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(ob);

    // inner_hdr: if j >= 0 (signed) -> inner_test else inner_done.
    let mut ih = Block::new(inner_hdr);
    let j_v = emit_typed_load(ctx, &mut ih, j_slot, TrustIrTy::I64);
    let zero = emit_i64_const(ctx, &mut ih, 0);
    let ge0 = ctx.fresh_value();
    ih.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Sge,
            ty: TrustIrTy::I64,
            lhs: j_v,
            rhs: zero,
        })
        .with_result(ge0),
    );
    ih.body.push(InstrNode::new(Inst::CondBr {
        cond: ge0,
        then_target: inner_test,
        then_args: Vec::new(),
        else_target: inner_done,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(ih);

    // inner_test: if keyfn(&a[j]) > ikey -> inner_shift else inner_done.
    let mut it = Block::new(inner_test);
    let j_v = emit_typed_load(ctx, &mut it, j_slot, TrustIrTy::I64);
    let aj_addr = elem_addr(ctx, &mut it, data, j_v, size_c);
    let jkey_raw = emit_closure_call_1(
        ctx,
        &mut it,
        closure_ty,
        key_env, // env_ptr (loop-invariant; a placeholder for a ZST closure)
        aj_addr, // arg: &T
        key_ir.clone(),
    )?;
    let jkey = convert_scalar(ctx, &mut it, jkey_raw, &key_ir, &TrustIrTy::I64);
    let ikey = emit_typed_load(ctx, &mut it, ikey_slot, TrustIrTy::I64);
    // Compare with the KEY's signedness, on the widened-to-i64 keys. A narrow key
    // was converted via `convert_scalar` (sign/zero-extending per its signedness),
    // so a 64-bit signed compare orders both signed and unsigned keys correctly.
    let gt_op = if key_signed { ICmpOp::Sgt } else { ICmpOp::Ugt };
    let gt = ctx.fresh_value();
    it.body.push(
        InstrNode::new(Inst::ICmp {
            op: gt_op,
            ty: TrustIrTy::I64,
            lhs: jkey,
            rhs: ikey,
        })
        .with_result(gt),
    );
    it.body.push(InstrNode::new(Inst::CondBr {
        cond: gt,
        then_target: inner_shift,
        then_args: Vec::new(),
        else_target: inner_done,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(it);

    // inner_shift: a[j+1] = a[j]; j -= 1; -> inner_hdr.
    let mut is_blk = Block::new(inner_shift);
    let j_v = emit_typed_load(ctx, &mut is_blk, j_slot, TrustIrTy::I64);
    let aj_addr = elem_addr(ctx, &mut is_blk, data, j_v, size_c);
    let aj = emit_typed_load(ctx, &mut is_blk, aj_addr, element_ir.clone());
    let one = emit_i64_const(ctx, &mut is_blk, 1);
    let jp1 = ctx.fresh_value();
    is_blk.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: TrustIrTy::I64,
            lhs: j_v,
            rhs: one,
        })
        .with_result(jp1),
    );
    let dst_addr = elem_addr(ctx, &mut is_blk, data, jp1, size_c);
    emit_typed_store(&mut is_blk, dst_addr, element_ir.clone(), aj);
    let jm1 = ctx.fresh_value();
    is_blk.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: j_v,
            rhs: one,
        })
        .with_result(jm1),
    );
    emit_typed_store(&mut is_blk, j_slot, TrustIrTy::I64, jm1);
    is_blk.body.push(InstrNode::new(Inst::Br {
        target: inner_hdr,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(is_blk);

    // inner_done: a[j+1] = insertee; i += 1; -> outer_hdr.
    let mut id_blk = Block::new(inner_done);
    let j_v = emit_typed_load(ctx, &mut id_blk, j_slot, TrustIrTy::I64);
    let one = emit_i64_const(ctx, &mut id_blk, 1);
    let jp1 = ctx.fresh_value();
    id_blk.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: TrustIrTy::I64,
            lhs: j_v,
            rhs: one,
        })
        .with_result(jp1),
    );
    let dst_addr = elem_addr(ctx, &mut id_blk, data, jp1, size_c);
    let insertee = emit_typed_load(ctx, &mut id_blk, insertee_slot, element_ir.clone());
    emit_typed_store(&mut id_blk, dst_addr, element_ir.clone(), insertee);
    let i_v = emit_typed_load(ctx, &mut id_blk, i_slot, TrustIrTy::I64);
    let one = emit_i64_const(ctx, &mut id_blk, 1);
    let i_next = ctx.fresh_value();
    id_blk.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: TrustIrTy::I64,
            lhs: i_v,
            rhs: one,
        })
        .with_result(i_next),
    );
    emit_typed_store(&mut id_blk, i_slot, TrustIrTy::I64, i_next);
    id_blk.body.push(InstrNode::new(Inst::Br {
        target: outer_hdr,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(id_blk);

    // exit: `sort_by_key` returns `()`; branch to the call's successor.
    let mut exit_block = Block::new(exit_id);
    if let Some(target) = call.target {
        exit_block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        exit_block.body.push(InstrNode::new(Inst::Unreachable));
    }
    ctx.extra_blocks.push(exit_block);

    Ok(true)
}

/// Whether the key closure `closure_ty` is injective on its argument's pointee,
/// so that equal keys can only come from equal elements
/// (`lower_slice_sort_by_key`'s `sort_unstable_by_key` condition). Proven only
/// for a closure whose optimized MIR defines each local at most once — an
/// argument's one definition being its value on entry — and computes its return
/// value from `*arg` through copies and moves, integer casts to a type at least
/// as wide, and `Neg` / `Not` — bijections on a fixed-width integer; anything
/// else is `false`. It is asked only of a key `sort_key_closure_is_pure`
/// admitted, which writes no local through a pointer, so the body's own
/// assignments and call destinations are every write to its locals.
fn sort_key_is_injective<'tcx>(tcx: TyCtxt<'tcx>, closure_ty: Ty<'tcx>) -> bool {
    let ty::Closure(def_id, args) = closure_ty.kind() else {
        return false;
    };
    let typing_env = ty::TypingEnv::fully_monomorphized();
    let Ok(Some(instance)) = Instance::try_resolve(tcx, typing_env, *def_id, *args) else {
        return false;
    };
    let body = tcx.instance_mir(instance.def);
    // A closure body's arguments are its environment, then the `&T` key input.
    let Some(arg) = body.args_iter().nth(1) else {
        return false;
    };
    let mono = |ty: Ty<'tcx>| {
        instance.instantiate_mir_and_normalize_erasing_regions(
            tcx,
            typing_env,
            ty::EarlyBinder::bind(tcx, ty),
        )
    };
    let width = |ty: Ty<'tcx>| {
        ty.is_integral()
            .then(|| {
                element_layout_size_align(tcx, ty)
                    .ok()
                    .map(|(size, _)| size)
            })
            .flatten()
    };
    // An argument is defined once on entry, so any assignment in the body is
    // its second definition: `*arg` is the element only while `arg` is the
    // incoming reference (a key that reassigns it, `x = &OTHER`, measured with
    // ties ordered as the stable model, not as std's ipnsort).
    let mut assignments = vec![0u32; body.local_decls.len()];
    for argument in body.args_iter() {
        assignments[argument.index()] = 1;
    }
    let mut definitions = Vec::new();
    for data in body.basic_blocks.iter().filter(|data| !data.is_cleanup) {
        for statement in &data.statements {
            if let StatementKind::Assign(boxed) = &statement.kind {
                let (place, rvalue) = &**boxed;
                if !place.projection.is_empty() {
                    return false;
                }
                assignments[place.local.index()] += 1;
                definitions.push((place.local, rvalue));
            }
        }
        if let TerminatorKind::Call { destination, .. } = &data.terminator().kind {
            assignments[destination.local.index()] += 2;
        }
    }
    if assignments.iter().any(|&count| count > 1) {
        return false;
    }
    let mut injective = vec![false; body.local_decls.len()];
    let operand_injective = |injective: &[bool], operand: &Operand<'tcx>| match operand {
        Operand::Copy(place) | Operand::Move(place) => {
            (place.local == arg
                && place.projection.len() == 1
                && matches!(place.projection[0], ProjectionElem::Deref))
                || (place.projection.is_empty() && injective[place.local.index()])
        }
        _ => false,
    };
    // Each local is defined once, so a pass that adds nothing is the fixpoint.
    loop {
        let mut changed = false;
        for (local, rvalue) in &definitions {
            if injective[local.index()] {
                continue;
            }
            let derived = match rvalue {
                Rvalue::Use(operand, ..) => operand_injective(&injective, operand),
                Rvalue::Cast(mir::CastKind::IntToInt, operand, to) => {
                    operand_injective(&injective, operand)
                        && match (width(mono(operand.ty(body, tcx))), width(mono(*to))) {
                            (Some(from), Some(to)) => to >= from,
                            _ => false,
                        }
                }
                Rvalue::UnaryOp(mir::UnOp::Neg | mir::UnOp::Not, operand) => {
                    operand_injective(&injective, operand)
                }
                _ => false,
            };
            if derived {
                injective[local.index()] = true;
                changed = true;
            }
        }
        if !changed {
            break;
        }
    }
    injective[mir::RETURN_PLACE.index()]
}

// ---------------------------------------------------------------------------
// `BTreeMap<K, V>` method lowering (see the section header near `btreemap_kv_ty`).
// ---------------------------------------------------------------------------

/// Mangled symbol of the runtime `__trustcg_btm_get` helper.
const BTM_GET_SYMBOL: &str = "__trustcg_btm_get";
/// Mangled symbol of the runtime `__trustcg_btm_insert` helper.
const BTM_INSERT_SYMBOL: &str = "__trustcg_btm_insert";
/// Mangled symbol of the runtime `__trustcg_btm_entry` (find-or-insert) helper.
const BTM_ENTRY_SYMBOL: &str = "__trustcg_btm_entry";
/// Mangled symbol of the runtime `__trustcg_btm_remove` (shift-delete) helper.
const BTM_REMOVE_SYMBOL: &str = "__trustcg_btm_remove";

/// `__trustcg_btm_get(slot_ptr, key) -> (found: i64, val_addr: Ptr)`.
fn btm_get_callee(ctx: &mut MirLoweringCtx<'_>) -> FuncId {
    ctx.extern_callee_by_name(
        BTM_GET_SYMBOL,
        FuncTy {
            params: vec![TrustIrTy::Ptr, TrustIrTy::I64],
            returns: vec![TrustIrTy::I64, TrustIrTy::Ptr],
            abi: None,
            is_vararg: false,
        },
    )
}

/// `__trustcg_btm_insert(slot_ptr, key, val) -> (found: i64, old_val: i64)`.
fn btm_insert_callee(ctx: &mut MirLoweringCtx<'_>) -> FuncId {
    ctx.extern_callee_by_name(
        BTM_INSERT_SYMBOL,
        FuncTy {
            params: vec![TrustIrTy::Ptr, TrustIrTy::I64, TrustIrTy::I64],
            returns: vec![TrustIrTy::I64, TrustIrTy::I64],
            abi: None,
            is_vararg: false,
        },
    )
}

/// `__trustcg_btm_entry(slot_ptr, key, default) -> val_addr: Ptr` (find-or-insert).
fn btm_entry_callee(ctx: &mut MirLoweringCtx<'_>) -> FuncId {
    ctx.extern_callee_by_name(
        BTM_ENTRY_SYMBOL,
        FuncTy {
            params: vec![TrustIrTy::Ptr, TrustIrTy::I64, TrustIrTy::I64],
            returns: vec![TrustIrTy::Ptr],
            abi: None,
            is_vararg: false,
        },
    )
}

/// `__trustcg_btm_remove(slot_ptr, key) -> (found: i64, old_val: i64)`.
fn btm_remove_callee(ctx: &mut MirLoweringCtx<'_>) -> FuncId {
    ctx.extern_callee_by_name(
        BTM_REMOVE_SYMBOL,
        FuncTy {
            params: vec![TrustIrTy::Ptr, TrustIrTy::I64],
            returns: vec![TrustIrTy::I64, TrustIrTy::I64],
            abi: None,
            is_vararg: false,
        },
    )
}

/// Zero-extend (or reinterpret) an integer `value` of trust-ir type `from` to a
/// 64-bit lane (the helper ABI). When `from` is already 64-bit this is a same-
/// width register move; otherwise a `ZExt`. The extension choice is round-trip
/// irrelevant: the helper stores/loads the full lane, and the read path truncates
/// back to the value's width, recovering the exact low bits (and equal keys
/// extend to equal lanes, so key equality is preserved).
fn btm_extend_to_i64(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    value: ValueId,
    from: &TrustIrTy,
) -> ValueId {
    if from.bit_width() == Some(64) {
        return coerce_to_i64(ctx, block, value);
    }
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::ZExt,
            src_ty: from.clone(),
            dst_ty: TrustIrTy::I64,
            operand: value,
        })
        .with_result(result),
    );
    result
}

/// Truncate a 64-bit lane back to integer type `to` (the inverse of
/// `btm_extend_to_i64`). When `to` is 64-bit this is a same-width move.
fn btm_truncate_from_i64(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    value: ValueId,
    to: &TrustIrTy,
) -> ValueId {
    if to.bit_width() == Some(64) {
        let result = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Copy {
                ty: to.clone(),
                operand: value,
            })
            .with_result(result),
        );
        return result;
    }
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::Trunc,
            src_ty: TrustIrTy::I64,
            dst_ty: to.clone(),
            operand: value,
        })
        .with_result(result),
    );
    result
}

/// The refusal for a map SELF-method name whose receiver is not a modeled map
/// although its destination is (`Vec<BTreeMap<K, V>>::remove(i)` returns a map).
fn map_receiver_refusal(map: &str, name: &str) -> String {
    format!(
        "[TCG-MAP-RECEIVER] `{name}` returns a modeled {map} but its self is not one; \
         the {map} intercept would treat the receiver as a map slot -- failing closed"
    )
}

/// [TCG-MAP-CALLEE] The refusal for a standard-library call whose first
/// argument is a modeled map but which is not that map's own inherent method
/// (`is_std_map_inherent_method`): a free function (`ptr::eq`, `mem::swap`), a
/// trait method (`Clone::clone`, `Drop::drop`, a provided method) or another
/// type's method. The map arms stand in only for the map's own methods, and the
/// callee's real body would read the bridge's slot image as rustc's map layout.
fn map_callee_refusal(tcx: TyCtxt<'_>, callee: DefId, map: &str) -> String {
    format!(
        "[TCG-MAP-CALLEE] `{}` takes a {map} this backend models as its own slot image, \
         but it is not one of the {map}'s own inherent methods: only those are lowered \
         against the slot, and this callee's real body would read the slot as rustc's \
         {map} layout -- failing closed",
        tcx.def_path_str(callee)
    )
}

/// `Err` with the `[TCG-MAP-MODEL-TRAIT]` refusal (`map_model_refusal`) when
/// `call` is a std callee whose destination or self (peeled of one reference)
/// is a std map with integer lanes that the model does not serve. Such a map
/// cannot be lowered through std's real bodies either, so naming the model's
/// reason at its first constructor or method call replaces a refusal deep
/// inside B-tree or hashbrown internals.
fn refuse_unmodeled_lane_map_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<(), String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(());
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    if let Some(reason) = map_model_refusal(ctx.tcx, dest_ty) {
        return Err(reason);
    }
    let Some(self_arg) = call.args.first() else {
        return Ok(());
    };
    let Ok(arg_ty) = operand_rust_ty(ctx, body, &self_arg.node) else {
        return Ok(());
    };
    let arg_ty = ctx.monomorphize_ty(arg_ty);
    let peeled = match arg_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
        _ => arg_ty,
    };
    match map_model_refusal(ctx.tcx, peeled) {
        Some(reason) => Err(reason),
        None => Ok(()),
    }
}

/// The lookup key of `get` / `get_mut` / `contains_key` / `remove` is `&Q` with
/// `K: Borrow<Q>`. std compares `q` with `k.borrow()`, so a `Q` other than `K`
/// runs `K`'s (possibly user) `Borrow` impl and `Q`'s own `Ord` / `Eq` /
/// `Hash`, none of which the lane compare models; only `Q == K` (core's
/// identity `Borrow`) is admitted.
fn btm_require_lookup_key_is_k<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
    key_ty: Ty<'tcx>,
    what: &str,
) -> Result<(), String> {
    let operand_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, operand)?);
    let lookup_ty = match operand_ty.kind() {
        ty::Ref(_, inner, _) => ctx.monomorphize_ty(*inner),
        _ => operand_ty,
    };
    if lookup_ty == key_ty {
        return Ok(());
    }
    Err(map_model_trait_refusal(
        "map",
        format_args!(
            "`{what}` looks up a `&{lookup_ty:?}` in a map keyed by `{key_ty:?}`; std \
             compares it through `{key_ty:?}: Borrow<{lookup_ty:?}>`"
        ),
    ))
}

/// Try to lower a `BTreeMap<K, V>` method call. Returns `Ok(true)` if the call
/// was an intercepted `BTreeMap` method (fully lowered, including its successor
/// branch); `Ok(false)` if it is not a `BTreeMap` method (caller continues);
/// `Err` if it is a `BTreeMap` method this backend does not lower (fail closed
/// precisely — never miscompile).
fn lower_btreemap_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    refuse_unmodeled_lane_map_call(ctx, body, call, callee)?;
    // Identify a `BTreeMap` method by a `BTreeMap`-typed self (first arg, by ref)
    // or a `BTreeMap`-typed destination (the `new` constructor, which takes no
    // self). The `(K, V)` come from whichever map we find.
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let dest_kv = btreemap_kv_ty(ctx.tcx, dest_ty);

    // Self-keyed recognition is restricted to genuine std `BTreeMap` methods; a
    // user helper taking `&mut BTreeMap` as its first parameter is not a method
    // and falls through to the general call path (see
    // `is_std_collection_method_callee`). The `new` constructor is keyed off the
    // DESTINATION type, so it is unaffected.
    let self_kv = call
        .args
        .first()
        .filter(|_| is_std_collection_method_callee(ctx.tcx, callee.def_id()))
        .and_then(|arg| {
            let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &arg.node).ok()?);
            let peeled = match arg_ty.kind() {
                ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
                _ => arg_ty,
            };
            btreemap_kv_ty(ctx.tcx, peeled)
        });

    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    let name = name.as_str();
    // Only the `new` constructor is identified by its DESTINATION. A self-method
    // arm whose self is NOT a modeled map but whose destination is one (the
    // `Vec<BTreeMap<_, _>>::remove(i)` that returns the map) is not a map method:
    // routed by the destination it would treat the receiver as a map slot.
    if name != "new"
        && self_kv.is_none()
        && dest_kv.is_some()
        && matches!(
            name,
            "len" | "insert" | "get" | "get_mut" | "contains_key" | "remove" | "entry"
        )
    {
        return Err(map_receiver_refusal("BTreeMap", name));
    }
    // A std callee taking a modeled map that is not the map's own inherent
    // method (`ptr::eq::<BTreeMap<_, _>>`, `<BTreeMap<_, _> as Clone>::clone`) is
    // never one of the arms below, whatever its name.
    if self_kv.is_some() && !is_std_map_inherent_method(ctx.tcx, callee.def_id()) {
        return Err(map_callee_refusal(ctx.tcx, callee.def_id(), "BTreeMap"));
    }
    let (key_ty, val_ty) = match dest_kv.or(self_kv) {
        Some(kv) => kv,
        None => return Ok(false),
    };

    match name {
        // [TCG-FOREIGN-MAP] By callee IDENTITY, never by name: only the real
        // `BTreeMap::new` yields the empty map this slot (and its receipt) stands
        // for (`is_std_map_inherent_method`).
        "new" if dest_kv.is_some() => {
            if !is_std_map_inherent_method(ctx.tcx, callee.def_id()) {
                return Err(foreign_map_constructor_refusal(
                    ctx.tcx,
                    callee.def_id(),
                    "BTreeMap",
                ));
            }
            lower_btreemap_new(ctx, body, block, call)
        }
        "len" => lower_btreemap_len(ctx, body, block, call),
        "insert" => lower_btreemap_insert(ctx, body, block, call, key_ty, val_ty),
        // `get_mut` returns `Option<&mut V>` — the same niche-pointer Option as
        // `get`'s `Option<&V>`, holding the value-lane address the get helper
        // already returns; writes through it land in the real backing buffer.
        "get" | "get_mut" => lower_btreemap_get(ctx, body, block, call, key_ty, val_ty),
        "contains_key" => lower_btreemap_contains_key(ctx, body, block, call, key_ty),
        "remove" => lower_btreemap_remove(ctx, body, block, call, key_ty, val_ty),
        "entry" => lower_btreemap_entry(ctx, body, block, call, key_ty),
        other => Err(format!(
            "BTreeMap::<{key_ty:?}, {val_ty:?}>::{other} is not an intercepted BTreeMap \
             method (only new/insert/get/get_mut/contains_key/remove/entry/len are \
             lowered; iteration and non-integer keys/values fail closed)"
        )),
    }
    .map(|()| true)
}

/// `dest = BTreeMap::new()`: alloca an empty `{ptr,cap,len}` slot and bind the
/// destination map local to the slot address. Like std's empty map (whose
/// `root` is `None`), it owns NO allocation: the entry buffer is allocated by
/// the first insert (`__trustcg_btm_insert` / `__trustcg_btm_entry`), so a
/// failing allocator is never consulted by a constructor std does not
/// allocate in.
fn lower_btreemap_new<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    let slot_ptr = emit_btreemap_empty_slot(ctx, block)?;
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: slot_ptr,
        })
        .with_result(target.value),
    );
    ctx.bridge_map_images.insert(target.value);
    ctx.map_slot_receipts.insert(target.value);
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// Alloca a fresh empty-map `{ ptr, cap, len }` slot and return its address:
/// `cap = 0`, `len = 0` and the entry alignment's dangling sentinel as `ptr`,
/// with no allocation (std's `BTreeMap::new` / `HashMap::new` allocate
/// nothing). The helpers allocate the buffer on the first insert and free
/// paths skip a zero-capacity buffer (`emit_btreemap_data_dealloc`). Shared by
/// the `new` call interception and the inlined-`new` aggregate interception
/// (at -O3 rustc inlines `BTreeMap::new` into an `Rvalue::Aggregate` struct
/// literal).
fn emit_btreemap_empty_slot(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
) -> Result<ValueId, String> {
    let slot_ptr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: vec_slot_ty(),
            count: None,
            align: None,
        })
        .with_result(slot_ptr),
    );
    // The slot's address IS the collection value: fresh per execution.
    ctx.per_execution_allocas.insert(slot_ptr);
    let cap_value = emit_i64_const(ctx, block, 0);
    // The i64-lane entry buffer's natural alignment is 8 bytes.
    let data_ptr = emit_collection_dangling(ctx, block, 8);
    let len_value = emit_i64_const(ctx, block, 0);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_PTR, data_ptr);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_CAP, cap_value);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_LEN, len_value);
    Ok(slot_ptr)
}

/// At -O3 rustc inlines `BTreeMap::new()` into a struct-literal
/// `Rvalue::Aggregate` (`BTreeMap { root: None, length: 0, alloc, _marker }`)
/// assigned to the map local, and inlines `len()` into a read of the `.length`
/// field. Recognize the EMPTY-map aggregate (a constant `root: None`,
/// `length: 0`) and synthesize the same `{ ptr, cap, len }` slot the `new` call
/// interception builds, binding the map local to its address. Any non-empty /
/// unrecognized map aggregate fails closed.
///
/// Returns `Ok(true)` if it intercepted the assignment, `Ok(false)` if `place`/
/// `rvalue` is not an empty-BTreeMap aggregate (caller continues), `Err` to fail
/// closed.
fn lower_btreemap_aggregate_assign<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
    rvalue: &Rvalue<'tcx>,
) -> Result<bool, String> {
    if !place.projection.is_empty() {
        return Ok(false);
    }
    let place_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    if let Some(reason) = map_model_refusal(ctx.tcx, place_ty) {
        return Err(reason);
    }
    if btreemap_kv_ty(ctx.tcx, place_ty).is_none() {
        return Ok(false);
    }
    let Rvalue::Aggregate(kind, operands) = rvalue else {
        return Err(format!(
            "BTreeMap local {:?} assigned from a non-aggregate rvalue this backend \
             does not model (only the inlined empty-map `new` aggregate is lowered)",
            place.local
        ));
    };
    // Must be an `Adt` aggregate of the `BTreeMap` struct. The inlined `new` sets
    // `length` (field 1) to the constant `0` and `root` (field 0) to `None`; we
    // only synthesize an EMPTY map, so require `length == 0`. The `root`/`alloc`/
    // `_marker` operands are constants we do not need (an empty map has no nodes).
    let mir::AggregateKind::Adt(_, _, _, _, _) = &**kind else {
        return Err("BTreeMap aggregate is not an Adt struct literal".to_owned());
    };
    // `length` is field index 1. Require it to be the constant 0 (an empty map);
    // a non-zero / non-constant length is not the inlined `new` and is rejected.
    let length_is_zero = operands
        .iter()
        .nth(1)
        .and_then(|op| op.constant())
        .and_then(|c| const_to_scalar_i128(&c.const_))
        .map(|v| v == 0)
        .unwrap_or(false);
    if !length_is_zero {
        return Err(
            "BTreeMap struct literal is not the inlined empty-map `new` (length != const 0)"
                .to_owned(),
        );
    }
    let slot_ptr = emit_btreemap_empty_slot(ctx, block)?;
    let target = prepare_assign_target(ctx, place)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: slot_ptr,
        })
        .with_result(target.value),
    );
    ctx.bridge_map_images.insert(target.value);
    ctx.map_slot_receipts.insert(target.value);
    finish_assign_target(ctx, body, block, place, target)?;
    Ok(true)
}

/// At `-O3` rustc inlines `HashMap::new()` into a chain of struct literals:
///
///     _18 = RawTable { table: RawTableInner::NEW, alloc: Global, marker }
///     _17 = hashbrown::map::HashMap { hash_builder: _16, table: _18 }   // _16 = RandomState
///     _1  = HashMap { base: _17 }                                       // the public map local
///
/// The bridge synthesizes the map's `{ ptr, cap, len }` slot directly, so:
///   * an OUTER `HashMap { base }` / inner `hashbrown HashMap { .. }` aggregate
///     (a map-typed `place`) -> synthesize a fresh empty slot, bind the local to
///     its address (exactly as the `new` call interception);
///   * a DEAD-internal aggregate (`RawTable`/`RawTableInner`, a `RandomState`-typed
///     `place`) -> no-op: bind the local to a null `Ptr` (it is never read).
///
/// Returns `Ok(true)` if it intercepted the assignment, `Ok(false)` if `place` is
/// not a HashMap-construction local (caller continues), `Err` to fail closed.
fn lower_hashmap_aggregate_assign<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
    rvalue: &Rvalue<'tcx>,
) -> Result<bool, String> {
    if !place.projection.is_empty() {
        return Ok(false);
    }
    let place_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    if let Some(reason) = map_model_refusal(ctx.tcx, place_ty) {
        return Err(reason);
    }
    let is_map = any_hashmap_kv_ty(ctx.tcx, place_ty).is_some();
    let is_dead = is_hashmap_dead_internal_ty(ctx.tcx, place_ty);
    if !is_map && !is_dead {
        return Ok(false);
    }
    // A dead-internal local is built from an `Aggregate` or a `Use` of a const
    // (e.g. `RawTableInner::NEW`). Either way the value is unread, so bind null and
    // succeed regardless of the rvalue shape.
    if is_dead {
        let null = ctx.fresh_value();
        block
            .body
            .push(InstrNode::new(Inst::NullPtr).with_result(null));
        let target = prepare_assign_target(ctx, place)?;
        block.body.push(
            InstrNode::new(Inst::Copy {
                ty: TrustIrTy::Ptr,
                operand: null,
            })
            .with_result(target.value),
        );
        finish_assign_target(ctx, body, block, place, target)?;
        return Ok(true);
    }
    // A map-typed local: the empty-map construction is an `Adt` struct literal
    // (outer `HashMap { base }` or inner `hashbrown::map::HashMap { .. }`). Any
    // other rvalue shape (a `move` of another map local) is not the inlined `new`
    // — fail closed rather than guess.
    let Rvalue::Aggregate(kind, _operands) = rvalue else {
        return Err(format!(
            "HashMap local {:?} assigned from a non-aggregate rvalue this backend does \
             not model (only the inlined empty-map `new` aggregate is lowered)",
            place.local
        ));
    };
    let mir::AggregateKind::Adt(..) = &**kind else {
        return Err("HashMap aggregate is not an Adt struct literal".to_owned());
    };
    let slot_ptr = emit_btreemap_empty_slot(ctx, block)?;
    let target = prepare_assign_target(ctx, place)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: slot_ptr,
        })
        .with_result(target.value),
    );
    ctx.map_slot_receipts.insert(target.value);
    finish_assign_target(ctx, body, block, place, target)?;
    Ok(true)
}

/// Read of an intercepted `BTreeMap`'s `.length` field (`-O3` inlines `len()`
/// into a `(map.1: usize)` projection). `BTreeMap`'s fields are
/// `{ root(0), length(1), alloc(2), _marker(3) }`, so field index 1 is the
/// length; we map it to the `{ptr,cap,len}` slot's `len` lane (`VEC_FIELD_LEN`).
/// The result is typed at the projection's own trust-ir type (`usize` = `U64`),
/// so a downstream `len as iN` cast's source-type gate is satisfied.
///
/// Returns `Ok(Some(value))` when `place` is a `map.length` read; `Ok(None)`
/// when it is not a `BTreeMap` field read (caller continues); `Err` for a
/// `BTreeMap` projection we do not model (e.g. a read of `.root`).
fn lower_btreemap_field_read<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<Option<ValueId>, String> {
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    if btreemap_kv_ty(ctx.tcx, base_ty).is_none() {
        return Ok(None);
    }
    // A WHOLE-map read (no projection) is a plain `Ptr` (slot address) copy —
    // leave it to the normal scalar path. We only intercept a single field
    // projection here.
    let [ProjectionElem::Field(field, field_ty)] = place.projection.as_ref() else {
        if place.projection.is_empty() {
            return Ok(None);
        }
        return Err(format!(
            "BTreeMap projection {:?} is not a `.length` field read (only the inlined \
             `len()` field access is lowered)",
            place.projection
        ));
    };
    // `length` is field index 1. Any other field (`root`/`alloc`/`_marker`) is not
    // modeled — fail closed rather than misread the slot.
    if field.index() != 1 {
        return Err(format!(
            "BTreeMap field read of index {} is not `.length` (only the length field, \
             index 1, is lowered)",
            field.index()
        ));
    }
    if !local_has_map_slot_receipt(ctx, place.local) {
        return Err(foreign_map_refusal(
            base_ty,
            "the inlined `len()` (`.length` field read) the bridge lowers itself",
            "a local that no map constructor in this function produced (an argument, \
             a call result, a load, or a value selected at a join)",
        ));
    }
    let slot_ptr = value_for_scalar_binding(ctx, ScalarPlaceBinding::Local(place.local))?;
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    // Re-type the loaded lane (declared `I64`) to the field's own trust-ir type
    // (`usize` -> `U64`), a same-width reinterpret, so a following `as iN` cast's
    // source-type gate matches.
    let field_ir =
        rust_ty_to_trust_ir_ty(ctx.tcx, ctx.monomorphize_ty(*field_ty)).unwrap_or(TrustIrTy::I64);
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: field_ir,
            operand: len,
        })
        .with_result(result),
    );
    Ok(Some(result))
}

/// Read of an intercepted `HashMap`'s length at `-O3`, where rustc inlines
/// `len()` into a deeply-nested field projection of the public map local:
///
///     _13 = copy ((((_1.0).1).0).3: usize)
///         = (((HashMap.base: hashbrown::map::HashMap).table: RawTable)
///                 .table: RawTableInner).items: usize
///
/// i.e. the projection chain `[Field(0), Field(1), Field(0), Field(3)]` reads the
/// `items` count, which is exactly the map's length. We map it to the
/// `{ptr,cap,len}` slot's `len` lane. Returns `Ok(Some(value))` when `place` is
/// this length read; `Ok(None)` when `place` is not a `HashMap` length
/// projection (caller continues); `Err` for a `HashMap` projection we do not
/// model (a different field of the inner table — fail closed).
fn lower_hashmap_field_read<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<Option<ValueId>, String> {
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    if hashmap_kv_ty(ctx.tcx, base_ty).is_none() {
        return Ok(None);
    }
    // A WHOLE-map read (no projection) is a plain `Ptr` slot-address copy — leave
    // it to the normal scalar path.
    if place.projection.is_empty() {
        return Ok(None);
    }
    // Recognize the inlined-`len()` projection chain. Its field indices are the
    // stable struct layout `base(0).table(1).table(0).items(3)`. The final field
    // is the `usize` item count == the map length.
    let fields: Vec<usize> = place
        .projection
        .iter()
        .map(|p| match p {
            ProjectionElem::Field(f, _) => Some(f.index()),
            _ => None,
        })
        .collect::<Option<Vec<_>>>()
        .ok_or_else(|| {
            format!(
                "HashMap projection {:?} is not the inlined `len()` field chain",
                place.projection
            )
        })?;
    if fields != [0, 1, 0, 3] {
        return Err(format!(
            "HashMap field projection {fields:?} is not the inlined `len()` chain \
             [0, 1, 0, 3] (only the item-count length read is lowered)"
        ));
    }
    let field_ty = match place.projection.last() {
        Some(ProjectionElem::Field(_, ty)) => *ty,
        _ => unreachable!("checked Field projection above"),
    };
    if !local_has_map_slot_receipt(ctx, place.local) {
        return Err(foreign_map_refusal(
            base_ty,
            "the inlined `len()` (item-count field read) the bridge lowers itself",
            "a local that no map constructor in this function produced (an argument, \
             a call result, a load, or a value selected at a join)",
        ));
    }
    let slot_ptr = value_for_scalar_binding(ctx, ScalarPlaceBinding::Local(place.local))?;
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    let field_ir =
        rust_ty_to_trust_ir_ty(ctx.tcx, ctx.monomorphize_ty(field_ty)).unwrap_or(TrustIrTy::I64);
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: field_ir,
            operand: len,
        })
        .with_result(result),
    );
    Ok(Some(result))
}

/// `BTreeMap::len(&self) -> usize`: load the slot's `len` field.
fn lower_btreemap_len<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("BTreeMap::len with {} args", call.args.len()));
    }
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    // Bind the `usize` destination at its OWN trust-ir type (`U64`), not a bare
    // `I64`: a downstream `len() as iN` cast declares its `src_ty` from the
    // destination local's type, and the fail-closed cast-source-type gate requires
    // the bound value's type to match (`U64` here). The slot's `len` lane is
    // numerically a `usize` so the same-width reinterpret loses no bits.
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let dest_ir = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty).unwrap_or(TrustIrTy::I64);
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: dest_ir,
            operand: len,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `BTreeMap::insert(&mut self, key, val) -> Option<V>`: extend `key`/`val` to
/// i64 lanes, call `__trustcg_btm_insert` (which searches, overwrites or appends,
/// and reports the previous value), then write `Option<V>` = `found ?
/// Some(trunc(old)) : None` into the memory-backed destination slot.
fn lower_btreemap_insert<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    key_ty: Ty<'tcx>,
    val_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 3 {
        return Err(format!("BTreeMap::insert with {} args", call.args.len()));
    }
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let key_ir = rust_ty_to_trust_ir_ty(ctx.tcx, key_ty)?;
    let val_ir = rust_ty_to_trust_ir_ty(ctx.tcx, val_ty)?;

    let key_raw = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let val_raw = lower_operand_to_value(ctx, body, block, &call.args[2].node)?;
    let key = btm_extend_to_i64(ctx, block, key_raw, &key_ir);
    let val = btm_extend_to_i64(ctx, block, val_raw, &val_ir);

    let callee = btm_insert_callee(ctx);
    let found = ctx.fresh_value();
    let old_val = ctx.fresh_value();
    // The helper's growth can reach the allocation-error entry, which a
    // panicking hook unwinds out of: honor this call's edge.
    push_intercept_edge_call(
        ctx,
        block,
        callee,
        vec![slot_ptr, key, val],
        [found, old_val],
    );

    // `found` (0/1) is the `Some`/`None` selector. `cond` must be a `Bool` for the
    // `Select` in `store_option_some_value`; derive it as `found != 0`.
    let zero = emit_i64_const(ctx, block, 0);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: found,
            rhs: zero,
        })
        .with_result(cond),
    );
    let payload = btm_truncate_from_i64(ctx, block, old_val, &val_ir);

    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Scalar {
            value: payload,
            ty: val_ir,
        },
    )?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// Resolve the lookup-key VALUE (typed `key_ir`) from a `get(&self, &Q)` key
/// operand `&Q`. Two shapes occur:
///   * a BORROWED SCALAR `&k` (a reference to a live local `k`): its scalar
///     binding's target IS `k`, so read `k`'s value directly — no load. (A
///     deref-load of `&k` would trip the "borrowed scalar reference used without
///     deref" guard, since `&k` is not a materialized pointer.)
///   * otherwise a real pointer (e.g. a promoted-const `&3` whose value lives in
///     static data): materialize the pointer and deref-load the key through it.
fn btm_resolve_key_value<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    operand: &Operand<'tcx>,
    key_ir: &TrustIrTy,
) -> Result<ValueId, String> {
    if let Operand::Copy(place) | Operand::Move(place) = operand {
        if place.projection.is_empty() {
            if let Some(binding) = ctx.borrowed_scalars.get(&place.local).copied() {
                return value_for_borrow_target(ctx, binding.target);
            }
        }
    }
    let key_ref = lower_operand_to_value(ctx, body, block, operand)?;
    let key_ptr = coerce_to_plain_ptr(ctx, block, key_ref);
    Ok(emit_typed_load(ctx, block, key_ptr, key_ir.clone()))
}

/// `BTreeMap::get(&self, &Q) -> Option<&V>`: load the lookup key through the
/// `&Q` reference, extend it to an i64 lane, call `__trustcg_btm_get` (which
/// returns whether the key was found and the ADDRESS of its value lane inside the
/// heap buffer), then write `Option<&V>` = `found ? Some(val_addr) : None` into
/// the memory-backed destination. The returned `&V` points at the value lane;
/// on little-endian x86_64 the low `size_of::<V>()` bytes there are exactly `V`,
/// so a narrower `V` reads correctly through the reference.
fn lower_btreemap_get<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    key_ty: Ty<'tcx>,
    val_ty: Ty<'tcx>,
) -> Result<(), String> {
    let _ = val_ty;
    if call.args.len() != 2 {
        return Err(format!("BTreeMap::get with {} args", call.args.len()));
    }
    btm_require_lookup_key_is_k(ctx, body, &call.args[1].node, key_ty, "get")?;
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let key_ir = rust_ty_to_trust_ir_ty(ctx.tcx, key_ty)?;

    // The key argument is `&Q` (here `&K`): a reference to the lookup key. Resolve
    // the key VALUE: if the reference is a borrowed scalar (`&k` of a live local
    // `k`), read `k`'s value directly from its scalar binding (no load); otherwise
    // it is a pointer (e.g. a promoted-const `&3`), so deref-load through it. Then
    // extend to the i64 lane.
    let key_raw = btm_resolve_key_value(ctx, body, block, &call.args[1].node, &key_ir)?;
    let key = btm_extend_to_i64(ctx, block, key_raw, &key_ir);

    let callee = btm_get_callee(ctx);
    let found = ctx.fresh_value();
    let val_addr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Call {
            callee,
            args: vec![slot_ptr, key],
        })
        .with_results(vec![found, val_addr]),
    );

    let zero = emit_i64_const(ctx, block, 0);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: found,
            rhs: zero,
        })
        .with_result(cond),
    );

    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Reference { ptr: val_addr },
    )?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `BTreeMap/HashMap::contains_key(&self, &Q) -> bool`: resolve the lookup key,
/// call `__trustcg_btm_get` (whose `found` flag is exactly the answer), and bind
/// the `bool` destination to `found != 0`. Identical key resolution to `get`.
fn lower_btreemap_contains_key<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    key_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 2 {
        return Err(format!("map::contains_key with {} args", call.args.len()));
    }
    btm_require_lookup_key_is_k(ctx, body, &call.args[1].node, key_ty, "contains_key")?;
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let key_ir = rust_ty_to_trust_ir_ty(ctx.tcx, key_ty)?;
    let key_raw = btm_resolve_key_value(ctx, body, block, &call.args[1].node, &key_ir)?;
    let key = btm_extend_to_i64(ctx, block, key_raw, &key_ir);

    let callee = btm_get_callee(ctx);
    let found = ctx.fresh_value();
    let val_addr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Call {
            callee,
            args: vec![slot_ptr, key],
        })
        .with_results(vec![found, val_addr]),
    );
    // The `bool` destination is `found != 0` (the found lane is 0/1).
    let zero = emit_i64_const(ctx, block, 0);
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: found,
            rhs: zero,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `BTreeMap/HashMap::remove(&mut self, &Q) -> Option<V>`: resolve the lookup
/// key, call `__trustcg_btm_remove` (which shift-deletes the matching entry,
/// decrements `len`, and reports the previous value), then write `Option<V>` =
/// `found ? Some(trunc(old)) : None` into the memory-backed destination —
/// exactly the `insert`-return shape.
fn lower_btreemap_remove<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    key_ty: Ty<'tcx>,
    val_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 2 {
        return Err(format!("map::remove with {} args", call.args.len()));
    }
    btm_require_lookup_key_is_k(ctx, body, &call.args[1].node, key_ty, "remove")?;
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let key_ir = rust_ty_to_trust_ir_ty(ctx.tcx, key_ty)?;
    let val_ir = rust_ty_to_trust_ir_ty(ctx.tcx, val_ty)?;
    let key_raw = btm_resolve_key_value(ctx, body, block, &call.args[1].node, &key_ir)?;
    let key = btm_extend_to_i64(ctx, block, key_raw, &key_ir);

    let callee = btm_remove_callee(ctx);
    let found = ctx.fresh_value();
    let old_val = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Call {
            callee,
            args: vec![slot_ptr, key],
        })
        .with_results(vec![found, old_val]),
    );

    let zero = emit_i64_const(ctx, block, 0);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: found,
            rhs: zero,
        })
        .with_result(cond),
    );
    let payload = btm_truncate_from_i64(ctx, block, old_val, &val_ir);

    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Scalar {
            value: payload,
            ty: val_ir,
        },
    )?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// [TCG-MAP-ENTRY-USE] The discriminants of `Occupied` and `Vacant` when
/// `ty` is one of the real standard library's map entry enums (by crate
/// IDENTITY, `std_def_path`): alloc's `btree_map::Entry`, std's
/// `hash_map::Entry`, or the real `hashbrown` `RustcEntry` that the `-O3`
/// inlined `HashMap::entry` produces. `None` for any other type.
fn modeled_entry_variant_discriminants<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<(i128, i128)> {
    let ty::Adt(adt, _) = ty.kind() else {
        return None;
    };
    if !adt.is_enum() {
        return None;
    }
    let path = std_def_path(tcx, adt.did())?;
    let modeled = match path.as_str() {
        "collections::btree::map::entry::Entry" | "collections::hash::map::Entry" => {
            is_real_std_crate_def(tcx, adt.did())
        }
        "rustc_entry::RustcEntry" => Some(adt.did().krate) == real_hashbrown_crate(tcx),
        _ => false,
    };
    if !modeled || adt.variants().len() != 2 {
        return None;
    }
    let discriminant = |name: &str| -> Option<i128> {
        let (index, _) = adt
            .variants()
            .iter_enumerated()
            .find(|(_, variant)| variant.name.as_str() == name)?;
        Some(adt.discriminant_for_variant(tcx, index).val as i128)
    };
    Some((discriminant("Occupied")?, discriminant("Vacant")?))
}

/// [TCG-FOREIGN-MAP] Whether `ty` is the real standard library's public map
/// `Entry` (`btree_map::Entry` / `hash_map::Entry`, by crate IDENTITY) over
/// integer `K`/`V` lanes (`is_integer_map_lane`), the lanes of the slot image
/// the bridge builds for a map it models. A map with such lanes whose traits
/// `map_lane_admission` refuses is never modeled, so it records no entry
/// either, and its `Entry` fails closed here too.
fn is_modeled_map_entry_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, args) = ty.kind() else {
        return false;
    };
    if !matches!(
        std_def_path(tcx, adt.did()).as_deref(),
        Some("collections::btree::map::entry::Entry" | "collections::hash::map::Entry")
    ) {
        return false;
    }
    let mut types = args.types();
    let (Some(key_ty), Some(val_ty)) = (types.next(), types.next()) else {
        return false;
    };
    is_integer_map_lane(tcx, key_ty) && is_integer_map_lane(tcx, val_ty)
}

/// [TCG-FOREIGN-MAP] Drop the `map.entry(k)` records (`map_entry_pending`) of
/// every local the MIR statement or terminator `scan` visits MUTATES (an
/// assignment, a call destination, a borrow that lets it be written, a drop,
/// a storage marker). A record names the map slot and key captured at THIS
/// function's own `entry(k)` call; once the local is overwritten (`e =
/// provider::leaked_entry()`, `*(&mut e) = ..`), its live value is no longer
/// that entry, and a record left behind made the consuming `or_insert` operate
/// on the bridge's own map instead (measured: exit 10 where LLVM exits 3).
/// The lowering that runs next re-records a local it defines from a recorded
/// entry (`lower_btreemap_entry`, `carry_map_entry_record`).
fn invalidate_overwritten_map_entry_records<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    scan: impl FnOnce(&mut MutatedLocals),
) {
    if ctx.map_entry_pending.is_empty() {
        return;
    }
    let mut mutated = MutatedLocals(Vec::new());
    scan(&mut mutated);
    for local in mutated.0 {
        ctx.map_entry_pending.remove(&local);
    }
}

/// [TCG-MAP-ENTRY-USE] Refuse any READ of a local that may hold an entry an
/// intercepted `entry(k)` produced (`map_entry_cells`) other than the three
/// this backend models, each only while a live record (`map_entry_pending`)
/// serves it: the consuming `or_insert` / `or_insert_with` / `or_default`
/// receiver (`lower_map_entry_or_insert`, which refuses an unrecorded one
/// itself), a carry of the record onto another local (`map_entry_carry_source`;
/// returned to the caller, which performs it), and a discriminant read
/// (`lower_discriminant`, which looks the key up to yield the real variant).
/// The `Entry` value is never materialized — every other read (a borrow
/// (`e.key()`, `&mut e` handed to `mem::replace`), a call taking the entry
/// (`and_modify`, a helper `fn f(e: Entry<..>)`), a `return` of it, a cast,
/// an aggregate holding two entries, the drop glue of a wrapper with a `Drop`
/// impl) would read memory that holds no entry
/// (measured: `*m.entry(7).key()` read 10 at -O0/-O1 where LLVM reads 7;
/// `mem::replace(&mut e, ..)` then `or_insert` exited 10 where LLVM exits 3;
/// `let (x, y) = (a.entry(1), b.entry(2))` ran both `or_insert`s on `b`).
/// A read of such a local WITHOUT a live record is refused too, whatever the
/// read, as `[TCG-FOREIGN-MAP]`: on some path the local holds a value no
/// `entry(k)` of this function produced (a join merged it with one that did,
/// so the record was dropped), and on another its memory was never written
/// (measured: `let e = if c { m.entry(2) } else { provider::leaked_entry(31)
/// }; matches!(e, Vacant(_))` exited 41 where LLVM exits 40; reading the
/// arm's payload gave 1, 105 or SIGSEGV where LLVM gives 20). Runs before the
/// statement or terminator is lowered and before its writes drop records
/// (`invalidate_overwritten_map_entry_records`).
fn refuse_unmodeled_map_entry_use<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    statement: Option<&mir::Statement<'tcx>>,
    terminator: Option<&mir::Terminator<'tcx>>,
    location: mir::Location,
) -> Result<Option<MapEntryCarry>, String> {
    use rustc_middle::mir::visit::Visitor;
    if ctx.map_entry_cells.is_empty() && ctx.map_entry_pending.is_empty() {
        return Ok(None);
    }
    let mut carry = None;
    let mut reads = LocalReads(Vec::new());
    if let Some(statement) = statement {
        match &statement.kind {
            StatementKind::Assign(boxed) => {
                let (place, rvalue) = &**boxed;
                match rvalue {
                    // Served from the record by `lower_discriminant`, which
                    // refuses every place but the entry itself or the only
                    // field of a one-field wrapper.
                    Rvalue::Discriminant(source)
                        if ctx.map_entry_pending.contains_key(&source.local) => {}
                    _ => {
                        let served =
                            map_entry_carry_source(ctx, body, place, rvalue).and_then(|source| {
                                let record = ctx.map_entry_pending.get(&source).copied()?;
                                Some(MapEntryCarry {
                                    dest: place.local,
                                    source,
                                    record,
                                })
                            });
                        if served.is_some() {
                            carry = served;
                        } else {
                            reads.visit_rvalue(rvalue, location);
                        }
                    }
                }
                // A read inside the destination place (an `Index` local, or
                // the base of a deref) is a read too.
                for local in place.projection.iter().filter_map(|elem| match elem {
                    mir::ProjectionElem::Index(local) => Some(local),
                    _ => None,
                }) {
                    reads.0.push(local);
                }
            }
            StatementKind::Intrinsic(..) | StatementKind::SetDiscriminant { .. } => {
                reads.visit_statement(statement, location);
            }
            _ => {}
        }
    }
    if let Some(terminator) = terminator {
        match &terminator.kind {
            mir::TerminatorKind::Call { func, args, .. } => {
                reads.visit_operand(func, location);
                let consumer = match ctx.monomorphize_ty(func.ty(body, ctx.tcx)).kind() {
                    ty::FnDef(callee, _) => {
                        matches!(
                            callee_item_name_str(ctx.tcx, *callee).as_str(),
                            "or_insert" | "or_insert_with" | "or_default"
                        ) && is_std_collection_method_callee(ctx.tcx, *callee)
                    }
                    _ => false,
                };
                for (index, arg) in args.iter().enumerate() {
                    // Served (or, without a record, refused by name) by
                    // `lower_map_entry_or_insert`.
                    let modeled_receiver = consumer
                        && index == 0
                        && matches!(
                            &arg.node,
                            Operand::Copy(place) | Operand::Move(place)
                                if place.projection.is_empty()
                        );
                    if !modeled_receiver {
                        reads.visit_operand(&arg.node, location);
                    }
                }
            }
            // A drop of an entry runs no code (an integer `Entry` holds nothing
            // to drop), and a storage marker reads nothing. A drop whose type
            // has drop glue reads the value: a one-field wrapper the record was
            // carried onto (`struct W(Entry<..>)` with a `Drop` impl, an enum
            // with a variant that owns a heap value) runs code over memory the
            // carry never stored (measured: `impl Drop for W { .. if let
            // Occupied(_) = self.0 .. }` read `Vacant` at every level where
            // LLVM reads `Occupied`, `*self.0.key()` read 1 or 101 where LLVM
            // reads 7).
            mir::TerminatorKind::Drop { place, .. } => {
                if ctx.map_entry_pending.contains_key(&place.local)
                    || ctx.map_entry_cells.contains_key(&place.local)
                {
                    let dropped = ctx.monomorphize_ty(place_rust_ty(ctx, body, place));
                    if dropped.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized()) {
                        reads.0.push(place.local);
                    }
                }
            }
            _ => reads.visit_terminator(terminator, location),
        }
    }
    let Some(local) = reads.0.into_iter().find(|local| {
        ctx.map_entry_pending.contains_key(local) || ctx.map_entry_cells.contains_key(local)
    }) else {
        return Ok(carry);
    };
    let entry_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
    if !ctx.map_entry_pending.contains_key(&local) {
        // [TCG-FOREIGN-MAP] On some path into this read the local holds a
        // value that is not an entry this function's own `entry(k)` produced
        // (a call result, a value read from memory, an entry another crate
        // made), and on another it may hold one that was never materialized:
        // the same provenance failure `Entry::or_insert` refuses on a local
        // without a record (`lower_map_entry_or_insert`).
        return Err(format!(
            "[TCG-FOREIGN-MAP] {local:?} (`{entry_ty:?}`) may hold a map entry this function's \
             own `entry(k)` produced, and is read where no record of that call reaches: on \
             some path it holds a value that is not such an entry (a call result, a value \
             read from memory, an entry another crate made), and this backend lowers \
             `entry(k)` to a record and never builds the `Entry`, so its memory holds no \
             entry on the other. Failing closed rather than read memory the intercepted \
             `entry(k)` never wrote. Fix options: (1) use one `entry(k)` per map in the \
             function that built it, (2) build this crate with the LLVM backend."
        ));
    }
    Err(format!(
        "[TCG-MAP-ENTRY-USE] the map entry `{entry_ty:?}` in {local:?}, returned by `entry(..)`, \
         is used other than by `or_insert` / `or_insert_with` / `or_default` (borrowed, passed \
         to another function, returned, put in an aggregate with other values, dropped by drop \
         glue that reads it, or read by a statement this backend does not model): this backend \
         lowers `entry(k)` to a record consumed by those three combinators and a variant read, \
         and never builds the `Entry` value, so there is no entry in memory to read. Failing \
         closed. Fix options: (1) use `entry(k).or_insert(..)` / `get` / `contains_key`, (2) \
         build this crate with the LLVM backend."
    ))
}

/// [TCG-MAP-ENTRY-USE] A statement that carries a live `map.entry(k)` record
/// from `source` onto `dest` (`map_entry_carry_source`), performed by
/// `carry_map_entry_record` in place of lowering the statement.
#[derive(Clone, Copy, Debug)]
struct MapEntryCarry {
    dest: Local,
    source: Local,
    record: MapEntryPending,
}

/// [TCG-MAP-ENTRY-USE] The local whose `map.entry(k)` record the whole-local
/// assignment `place = rvalue` carries onto `place`, for the shapes in which
/// `place`'s value provably IS the recorded entry (or wraps it as its only
/// field): a `Use` of the whole local, of the only field of a struct or tuple,
/// or of the only field of an enum variant (`(_12 as Vacant).0`, `match e {
/// Occupied(o) => .. }`), and a one-operand struct / enum-variant / tuple
/// aggregate over the whole local (`VacantEntry { base: _17 }`,
/// `Entry::Vacant(_18)`). This covers std's `-O3` `RustcEntry` diamond
/// (`hash_map::map_entry`), whose arms unwrap and re-wrap the entry for one
/// `or_insert*`. Every other read of a recorded local is refused
/// (`refuse_unmodeled_map_entry_use`): a projection that may select something
/// other than the entry, or an aggregate of several values, would bind the
/// record to a value that is not that entry (measured: `let (x, y) =
/// (a.entry(1), b.entry(2))` gave both `x` and `y` the record of `b`).
fn map_entry_carry_source<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
    rvalue: &Rvalue<'tcx>,
) -> Option<Local> {
    if !place.projection.is_empty() {
        return None;
    }
    match rvalue {
        Rvalue::Use(Operand::Copy(source) | Operand::Move(source), _) => {
            map_entry_place_selects_sole_field(ctx, body, source).then_some(source.local)
        }
        Rvalue::Aggregate(kind, operands) => {
            let wraps = match &**kind {
                // A union literal names ONE field of several; a read of
                // another field reinterprets the entry.
                mir::AggregateKind::Adt(_, _, _, _, active_field) => active_field.is_none(),
                mir::AggregateKind::Tuple => true,
                _ => false,
            };
            if !wraps || operands.len() != 1 {
                return None;
            }
            match operands.iter().next()? {
                Operand::Copy(source) | Operand::Move(source) if source.projection.is_empty() => {
                    Some(source.local)
                }
                _ => None,
            }
        }
        _ => None,
    }
}

/// [TCG-MAP-ENTRY-USE] Whether `place` is a recorded local's whole value or
/// its only field: the local itself, the only field of a struct or tuple, or
/// the only field of an enum variant. A local carries a record only when its
/// value IS the recorded entry or wraps it as its only field
/// (`map_entry_carry_source`), so such a place holds that entry or a wrapper
/// of it and nothing else. A carry (`map_entry_carry_source`) and a variant
/// read (`lower_discriminant`) are served only through such a place.
fn map_entry_place_selects_sole_field<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> bool {
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    match place.projection.as_ref() {
        [] => true,
        [ProjectionElem::Field(..)] => match base_ty.kind() {
            ty::Adt(adt, _) if adt.is_struct() => adt.non_enum_variant().fields.len() == 1,
            ty::Tuple(members) => members.len() == 1,
            _ => false,
        },
        [
            ProjectionElem::Downcast(_, variant),
            ProjectionElem::Field(..),
        ] => match base_ty.kind() {
            ty::Adt(adt, _) if adt.is_enum() => adt
                .variants()
                .get(*variant)
                .is_some_and(|v| v.fields.len() == 1),
            _ => false,
        },
        _ => false,
    }
}

/// [TCG-MAP-ENTRY-USE] Carry `carry.record` onto `carry.dest` (the statement
/// `refuse_unmodeled_map_entry_use` found to be a carry; nothing else of it is
/// lowered). The source keeps its record: an affine `Entry` has one live
/// forward chain, and the dead (un-taken) arm of std's `-O3` diamond, which the
/// bridge still lowers statically, must not clear it.
fn carry_map_entry_record<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    carry: MapEntryCarry,
) -> Result<(), String> {
    let (slot, key) = map_entry_record_values(ctx, block, carry.source, carry.record)?;
    ctx.clear_full_place_bindings(carry.dest);
    establish_map_entry_record(ctx, block, carry.dest, slot, key)
}

/// [TCG-MAP-ENTRY-USE] Record that `local` now holds the entry of the map slot
/// `slot` and key lane `key`, and store both into the local's record cell
/// (`map_entry_cells`) so that a join or loop header whose incoming records
/// differ reads the values of the path taken (`MapEntryPending::Cell`). A local
/// the whole-body pre-scan (`map_entry_record_locals`) did not find has no cell
/// and no read of it is checked, so recording on it fails closed.
fn establish_map_entry_record(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    local: Local,
    slot: ValueId,
    key: ValueId,
) -> Result<(), String> {
    let Some(cell) = ctx.map_entry_cells.get(&local).copied() else {
        return Err(format!(
            "[TCG-MAP-ENTRY-USE] a map entry record reached {local:?}, which the scan of this \
             function's `entry(k)` calls and their carries did not find: its reads would not \
             be checked against the record. Failing closed."
        ));
    };
    emit_typed_store(block, cell.slot, TrustIrTy::Ptr, slot);
    emit_typed_store(block, cell.key, TrustIrTy::I64, key);
    ctx.map_entry_pending
        .insert(local, MapEntryPending::Values { slot, key });
    Ok(())
}

/// [TCG-MAP-ENTRY-USE] The map slot address and key lane of `local`'s live
/// record: the values themselves, or (`MapEntryPending::Cell`) loaded from the
/// local's record cell.
fn map_entry_record_values(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    local: Local,
    record: MapEntryPending,
) -> Result<(ValueId, ValueId), String> {
    match record {
        MapEntryPending::Values { slot, key } => Ok((slot, key)),
        MapEntryPending::Cell => {
            let cell = ctx.map_entry_cells.get(&local).copied().ok_or_else(|| {
                format!("[TCG-MAP-ENTRY-USE] the merged map entry record of {local:?} has no cell")
            })?;
            let slot = emit_typed_load(ctx, block, cell.slot, TrustIrTy::Ptr);
            let key = emit_typed_load(ctx, block, cell.key, TrustIrTy::I64);
            Ok((slot, key))
        }
    }
}

/// [TCG-MAP-ENTRY-USE] Whether the call `func(args..)` is one the bridge may
/// lower to a `map.entry(k)` record (`lower_btreemap_entry`): the standard
/// library's `entry` / `rustc_entry` whose receiver is a slot-modeled
/// `BTreeMap` / `HashMap` (the receiver test of `lower_btreemap_call` /
/// `lower_hashmap_call`).
fn may_intercept_map_entry_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    func: &Operand<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
) -> bool {
    let ty::FnDef(callee, _) = ctx.monomorphize_ty(func.ty(body, ctx.tcx)).kind() else {
        return false;
    };
    if !matches!(
        callee_item_name_str(ctx.tcx, *callee).as_str(),
        "entry" | "rustc_entry"
    ) || !is_std_collection_method_callee(ctx.tcx, *callee)
    {
        return false;
    }
    let Some(receiver) = args.first() else {
        return false;
    };
    let Ok(receiver_ty) = operand_rust_ty(ctx, body, &receiver.node) else {
        return true;
    };
    let receiver_ty = ctx.monomorphize_ty(receiver_ty);
    let peeled = match receiver_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
        _ => receiver_ty,
    };
    btreemap_kv_ty(ctx.tcx, peeled).is_some() || any_hashmap_kv_ty(ctx.tcx, peeled).is_some()
}

/// [TCG-MAP-ENTRY-USE] Every local of `body` that may hold an entry an
/// intercepted `entry(k)` produced: the destination of every call the bridge
/// may lower to a record (`may_intercept_map_entry_call`), closed over every
/// assignment that reads one of them by `Use` or in an aggregate (a superset of
/// the carries `map_entry_carry_source` performs). Computed over the whole
/// body before any block is lowered, so a read lowered BEFORE the write that
/// makes the local an entry (the top of a loop whose bottom assigns
/// `e = m.entry(k)`) is still seen.
fn map_entry_record_locals<'tcx>(ctx: &MirLoweringCtx<'tcx>, body: &Body<'tcx>) -> Vec<Local> {
    let mut locals: HashSet<Local> = HashSet::new();
    for data in body.basic_blocks.iter() {
        if let Some(terminator) = &data.terminator {
            if let mir::TerminatorKind::Call {
                func,
                args,
                destination,
                ..
            } = &terminator.kind
            {
                if may_intercept_map_entry_call(ctx, body, func, args) {
                    locals.insert(destination.local);
                }
            }
        }
    }
    if locals.is_empty() {
        return Vec::new();
    }
    loop {
        let before = locals.len();
        for data in body.basic_blocks.iter() {
            for statement in &data.statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (place, rvalue) = &**boxed;
                let operand_reads = |operand: &Operand<'tcx>| {
                    matches!(
                        operand,
                        Operand::Copy(source) | Operand::Move(source)
                            if locals.contains(&source.local)
                    )
                };
                let reads = match rvalue {
                    Rvalue::Use(operand, _) => operand_reads(operand),
                    Rvalue::Aggregate(_, operands) => operands.iter().any(operand_reads),
                    _ => false,
                };
                if reads {
                    locals.insert(place.local);
                }
            }
        }
        if locals.len() == before {
            break;
        }
    }
    let mut locals: Vec<Local> = locals.into_iter().collect();
    locals.sort_unstable();
    locals
}

/// [TCG-MAP-ENTRY-USE] Give every local that may hold an intercepted entry
/// (`map_entry_record_locals`) its record cell (`map_entry_cells`), allocated
/// in the entry block so it dominates every record made on the local.
fn allocate_map_entry_record_cells<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
) {
    for local in map_entry_record_locals(ctx, body) {
        let mut alloca = |ctx: &mut MirLoweringCtx<'tcx>, ty: TrustIrTy| {
            let ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty,
                    count: None,
                    align: Some(8),
                })
                .with_result(ptr),
            );
            ptr
        };
        let slot = alloca(ctx, TrustIrTy::Ptr);
        let key = alloca(ctx, TrustIrTy::I64);
        ctx.map_entry_cells
            .insert(local, MapEntryCell { slot, key });
    }
}

/// Every local a visited MIR node READS: any non-mutating use, and a
/// mutable or raw borrow (`refuse_unmodeled_map_entry_use`).
struct LocalReads(Vec<Local>);

impl<'tcx> rustc_middle::mir::visit::Visitor<'tcx> for LocalReads {
    fn visit_local(
        &mut self,
        local: Local,
        context: rustc_middle::mir::visit::PlaceContext,
        _location: mir::Location,
    ) {
        use rustc_middle::mir::visit::{MutatingUseContext, PlaceContext};
        if matches!(
            context,
            PlaceContext::NonMutatingUse(_)
                | PlaceContext::MutatingUse(
                    MutatingUseContext::Borrow
                        | MutatingUseContext::RawBorrow
                        | MutatingUseContext::Projection
                )
        ) {
            self.0.push(local);
        }
    }
}

/// The locals a visited MIR statement / terminator mutates or ends the
/// storage of (`invalidate_overwritten_map_entry_records`).
struct MutatedLocals(Vec<Local>);

impl<'tcx> rustc_middle::mir::visit::Visitor<'tcx> for MutatedLocals {
    fn visit_local(
        &mut self,
        local: Local,
        context: rustc_middle::mir::visit::PlaceContext,
        _location: mir::Location,
    ) {
        use rustc_middle::mir::visit::{NonUseContext, PlaceContext};
        if context.is_mutating_use()
            || matches!(
                context,
                PlaceContext::NonUse(NonUseContext::StorageLive | NonUseContext::StorageDead)
            )
        {
            self.0.push(local);
        }
    }
}

/// `BTreeMap/HashMap::entry(&mut self, key) -> Entry<K, V>`: the first half of
/// the `entry(k).or_insert*(..)` idiom. std's `entry` mutates nothing observable
/// (the map changes only when the `Entry` is consumed by `or_insert*`), so we
/// lower it to NOTHING but a record: the map's slot address and the extended
/// key lane, keyed by the `Entry`-typed destination local
/// (`ctx.map_entry_pending`). The consuming `Entry::or_insert*` call reads the
/// record back and performs the find-or-insert (see
/// `lower_map_entry_or_insert`). The `Entry` enum value itself is never
/// materialized: a bare un-consumed `m.entry(k);` is correctly a no-op. Every
/// other read of the entry local is reconstructed (a discriminant read looks the
/// key up, `lower_discriminant`) or refused (`refuse_unmodeled_map_entry_use`,
/// [TCG-MAP-ENTRY-USE]), and a write to it drops the record
/// (`invalidate_overwritten_map_entry_records`).
fn lower_btreemap_entry<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    key_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 2 {
        return Err(format!("map::entry with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("map::entry destination is a projected place".to_owned());
    }
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let key_ir = rust_ty_to_trust_ir_ty(ctx.tcx, key_ty)?;
    // `entry(k)` takes the key BY VALUE (not `&Q` like `get`): lower the operand
    // directly to its value, then extend to the i64 lane (the same extension the
    // insert/get paths apply, so key equality is preserved).
    let key_raw = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let key = btm_extend_to_i64(ctx, block, key_raw, &key_ir);

    ctx.clear_full_place_bindings(call.destination.local);
    establish_map_entry_record(ctx, block, call.destination.local, slot_ptr, key)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// Lower an `Entry::or_insert(default)` / `or_insert_with(f)` / `or_default()`
/// call that consumes a map `Entry` recorded by `lower_btreemap_entry`. The
/// self (first) arg is the `Entry`-typed local whose map slot + key lane were
/// recorded; this performs the actual find-or-insert via the
/// `__trustcg_btm_entry` runtime helper (on a HIT the existing value is kept,
/// on a MISS `(key, default)` is appended), then binds the `&mut V` result
/// local to the returned value-lane ADDRESS — a real pointer into the map's
/// heap buffer, so read-modify-writes through it (`*e += 1`) stick.
///
/// The default VALUE:
///   * `or_insert(d)`: the second operand (always evaluated, exactly as std;
///     `V` has no drop glue, so an unused default needs no drop).
///   * `or_default()`: the zero lane, when `V`'s `Default` is primitive or a
///     builtin derive, with no default field value, over such fields
///     (`BuiltinTraitClaim::DefaultIsZero`); any other `V` refuses by name.
///   * `or_insert_with(f)`: only a TRIVIAL closure whose body returns a plain
///     constant (`|| 0`, `|| 7`) is folded to that constant — such a closure is
///     side-effect-free, so calling it eagerly-vs-lazily is unobservable. Any
///     other closure (captures, computation, side effects) FAILS CLOSED.
///
/// Returns `Ok(true)` if it intercepted the call (fully lowered, including the
/// successor); `Ok(false)` if `call` is not an `or_insert*` consuming a
/// recorded entry (caller continues; a genuine un-recorded `Entry` then fails
/// closed in the general path); `Err` to fail closed.
fn lower_map_entry_or_insert<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    let name = name.as_str();
    if !matches!(name, "or_insert" | "or_insert_with" | "or_default") {
        return Ok(false);
    }
    // Only the genuine std/`alloc`/`hashbrown` Entry combinators — a USER method
    // that happens to be named `or_insert` is not this idiom.
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    // The receiver must be a bare `Entry` local recorded at its `entry(..)` call.
    let Some(self_arg) = call.args.first() else {
        return Ok(false);
    };
    let (Operand::Copy(place) | Operand::Move(place)) = &self_arg.node else {
        return Ok(false);
    };
    if !place.projection.is_empty() {
        return Ok(false);
    }
    let Some(pending) = ctx.map_entry_pending.get(&place.local).copied() else {
        // [TCG-FOREIGN-MAP] Not an entry THIS function's own `entry(k)` produced
        // on a map it built (its record was never made, or was dropped when the
        // local was overwritten or where paths merged): a parameter, a call
        // result, a local reassigned from LLVM code. For a map the bridge
        // models, its `Entry` points into a real B-tree / hash table (or at a
        // bridge slot image read as one), and std's `or_insert*` compiled
        // anywhere reads it at rustc's layout. A local an intercepted
        // `entry(k)` may have written (`map_entry_cells`) holds no entry in
        // memory on that path either.
        let entry_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
        if is_modeled_map_entry_ty(ctx.tcx, entry_ty)
            || ctx.map_entry_cells.contains_key(&place.local)
        {
            return Err(format!(
                "[TCG-FOREIGN-MAP] `Entry::{name}` on `{entry_ty:?}` whose value is not an entry \
                 this function's own `entry(k)` produced on a map it constructed (a parameter, \
                 a call result, or a local reassigned since): this backend lowers `entry(k)` to \
                 a record over its OWN map slot image and never builds the `Entry`; a real \
                 entry points into rustc's B-tree / hash-table layout. Failing closed. Fix \
                 options: (1) call `entry(k).{name}(..)` in the function that built the map, \
                 (2) build this crate with the LLVM backend."
            ));
        }
        return Ok(false);
    };
    // From here on this IS the recorded idiom: consume the record (an `Entry` is
    // affine, so it has exactly one consumer) and fail closed on any surprise.
    ctx.map_entry_pending.remove(&place.local);
    let (entry_slot, entry_key) = map_entry_record_values(ctx, block, place.local, pending)?;

    // The result is `&mut V`; recover `V`'s trust-ir type from the destination
    // reference's pointee.
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let val_ty = match dest_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
        other => {
            return Err(format!(
                "map Entry::{name} destination is not a reference: {other:?}"
            ));
        }
    };
    let val_ir = rust_ty_to_trust_ir_ty(ctx.tcx, val_ty)?;
    if !val_ir.is_integer() {
        return Err(format!(
            "map Entry::{name} value type {val_ir:?} is not an integer lane"
        ));
    }

    // The default value (typed `val_ir`), per combinator.
    let default_raw = match name {
        "or_insert" => {
            if call.args.len() != 2 {
                return Err(format!(
                    "map Entry::or_insert with {} args",
                    call.args.len()
                ));
            }
            lower_operand_to_value(ctx, body, block, &call.args[1].node)?
        }
        "or_default" => {
            if call.args.len() != 1 {
                return Err(format!(
                    "map Entry::or_default with {} args",
                    call.args.len()
                ));
            }
            // `V::default()` is the zero lane only when `V`'s `Default` is
            // primitive or a builtin derive, with no default field value, over
            // such fields. A hand-written `Default`, a derived enum one (the
            // `#[default]` variant) or a field's default value has its own
            // value or effects, which this constant would replace.
            if !trait_claim_holds(ctx.tcx, val_ty, BuiltinTraitClaim::DefaultIsZero, 0) {
                return Err(map_model_trait_refusal(
                    "map Entry::or_default",
                    format_args!(
                        "value type `{val_ty:?}`'s Default is not primitive or a builtin \
                         derive (with no default field value) over such fields, so it is \
                         not the zero lane"
                    ),
                ));
            }
            let v = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: val_ir.clone(),
                    value: Constant::Int(0),
                })
                .with_result(v),
            );
            v
        }
        "or_insert_with" => {
            if call.args.len() != 2 {
                return Err(format!(
                    "map Entry::or_insert_with with {} args",
                    call.args.len()
                ));
            }
            let value = trivial_const_closure_value(ctx, body, &call.args[1].node)?;
            let v = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: val_ir.clone(),
                    value: Constant::Int(value),
                })
                .with_result(v),
            );
            v
        }
        _ => unreachable!("matched or_insert/or_insert_with/or_default above"),
    };
    let default_lane = btm_extend_to_i64(ctx, block, default_raw, &val_ir);

    // Find-or-insert: returns the value-lane address (existing on a hit, freshly
    // appended `(key, default)` on a miss).
    let callee_id = btm_entry_callee(ctx);
    let val_addr = ctx.fresh_value();
    // The helper's growth can reach the allocation-error entry, which a
    // panicking hook unwinds out of: honor this call's edge.
    push_intercept_edge_call(
        ctx,
        block,
        callee_id,
        vec![entry_slot, entry_key, default_lane],
        [val_addr],
    );

    // Bind the `&mut V` result to the value-lane address (a plain `Ptr` scalar);
    // deref reads/writes then lower through the existing memory-deref machinery.
    if !call.destination.projection.is_empty() {
        return Err(format!(
            "map Entry::{name} destination is a projected place"
        ));
    }
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: val_addr,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(true)
}

/// Extract the constant an `or_insert_with` closure returns, accepting ONLY a
/// trivially-const closure: a non-capturing-shape closure operand whose MIR body
/// is a single block assigning a plain integer constant to the return place and
/// returning (`|| 0`, `|| 42`). Such a body is side-effect-free, so the
/// eager-vs-lazy evaluation difference is unobservable. Anything else — a
/// capture, arithmetic, a call, multiple blocks — fails closed (`Err`).
fn trivial_const_closure_value<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Result<i128, String> {
    let op_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, operand)?);
    let ty::Closure(def_id, _) = op_ty.kind() else {
        return Err(format!(
            "map Entry::or_insert_with default is not a closure: {op_ty:?} (only a \
             trivial `|| CONST` closure is lowered; fails closed)"
        ));
    };
    let mir = ctx.tcx.instance_mir(ty::InstanceKind::Item(*def_id));
    if mir.basic_blocks.len() != 1 {
        return Err(
            "map Entry::or_insert_with closure is not a single-block `|| CONST` body \
             (fails closed)"
                .to_owned(),
        );
    }
    let bb = &mir.basic_blocks[mir::START_BLOCK];
    if !matches!(bb.terminator().kind, TerminatorKind::Return) {
        return Err(
            "map Entry::or_insert_with closure body does not end in a plain return \
             (fails closed)"
                .to_owned(),
        );
    }
    let mut value: Option<i128> = None;
    for statement in &bb.statements {
        match &statement.kind {
            StatementKind::StorageLive(_) | StatementKind::StorageDead(_) | StatementKind::Nop => {}
            StatementKind::Assign(boxed) => {
                let (place, rvalue) = &**boxed;
                if place.local != mir::RETURN_PLACE || !place.projection.is_empty() {
                    return Err(
                        "map Entry::or_insert_with closure assigns a non-return place \
                         (fails closed)"
                            .to_owned(),
                    );
                }
                let Rvalue::Use(Operand::Constant(c), _) = rvalue else {
                    return Err(
                        "map Entry::or_insert_with closure return is not a plain constant \
                         (fails closed)"
                            .to_owned(),
                    );
                };
                let Some(v) = const_to_scalar_i128(&c.const_) else {
                    return Err(
                        "map Entry::or_insert_with closure constant is not an integer \
                         scalar (fails closed)"
                            .to_owned(),
                    );
                };
                if value.replace(v).is_some() {
                    return Err(
                        "map Entry::or_insert_with closure assigns the return place twice \
                         (fails closed)"
                            .to_owned(),
                    );
                }
            }
            other => {
                return Err(format!(
                    "map Entry::or_insert_with closure has an unsupported statement \
                     {other:?} (fails closed)"
                ));
            }
        }
    }
    value.ok_or_else(|| {
        "map Entry::or_insert_with closure never assigns its return value (fails closed)".to_owned()
    })
}

// ---------------------------------------------------------------------------
// `HashMap<K, V>` method lowering.
//
// A `HashMap<K, V>` (integer `K`/`V`) is intercepted and represented with the
// SAME flat `{ ptr, cap, len }` slot + 16-byte `[key:i64|value:i64]` entry
// backing store as `BTreeMap` (the `__trustcg_btm_*` helpers), so the
// per-method lowering DELEGATES to the shared `lower_btreemap_*` functions. The
// only HashMap-specific concerns are: (1) the public `new()` constructs a
// `RandomState` hasher (which the backing does not need, so it is treated as
// dead — see `lower_hashmap_dead_call`/`lower_hashmap_aggregate_assign`);
// (2) at `-O3` the inlined `insert`/`get`/`len` calls land on the INNER
// `hashbrown::map::HashMap` whose `&mut/&self` is a projection of the outer map
// local. Iteration and non-integer / wider-than-64-bit `K`/`V` fail closed, and
// so does any `K`/`V`/`S` the admission refuses (`hashmap_lane_admission`).
// ---------------------------------------------------------------------------

/// Try to lower a `HashMap<K, V>` method call (public or inner `hashbrown`
/// type). Returns `Ok(true)` if intercepted + fully lowered (including the
/// successor branch); `Ok(false)` if it is not a `HashMap` method (caller
/// continues); `Err` for a `HashMap` method this backend does not lower (fail
/// closed precisely — never miscompile).
fn lower_hashmap_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    // A `RandomState`-producing call (the `new()` hasher construction at `-O3`,
    // a `LocalKey::with(..)` thread-local read) is dead for the backing store —
    // intercept it as a no-op so the map's `new` aggregate is fully lowered.
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    if is_hashmap_dead_internal_ty(ctx.tcx, dest_ty) {
        // [TCG-FOREIGN-MAP] Dropping the call is sound only for the real
        // standard library's own construction steps (`RandomState::new`, the
        // `LocalKey::with` key read, `hashbrown`'s table constructors), whose
        // only effect is the value this model never reads. Any other function
        // producing one of these types runs a body (side effects, a value used
        // elsewhere) that must not be discarded by its result TYPE.
        if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
            return Err(format!(
                "[TCG-FOREIGN-MAP] `{}` returns `{dest_ty:?}`, a type this backend treats as a \
                 dead step of the standard library's own HashMap construction (its call is \
                 dropped and its value bound to a null pointer), but the callee is not part of \
                 the standard library: its body would be discarded. Failing closed. Fix \
                 options: (1) construct the hasher with std's own `RandomState::new()`, \
                 (2) build this crate with the LLVM backend.",
                ctx.tcx.def_path_str(callee.def_id())
            ));
        }
        return lower_hashmap_dead_call(ctx, body, block, call).map(|()| true);
    }

    refuse_unmodeled_lane_map_call(ctx, body, call, callee)?;
    // Identify a `HashMap` method by a `HashMap`-typed destination (the `new` /
    // `with_*` constructors, which take no self) or a `HashMap`-typed self (first
    // arg, by ref). Both the public and inner `hashbrown` map types qualify.
    let dest_kv = any_hashmap_kv_ty(ctx.tcx, dest_ty);
    // Self-keyed recognition is restricted to genuine std/`hashbrown` `HashMap`
    // methods; a user helper taking `&mut HashMap` as its first parameter is not
    // a method and falls through to the general call path (see
    // `is_std_collection_method_callee`). The `new`/`with_*` constructors are
    // keyed off the DESTINATION type, so they are unaffected.
    let self_kv = call
        .args
        .first()
        .filter(|_| is_std_collection_method_callee(ctx.tcx, callee.def_id()))
        .and_then(|arg| {
            let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &arg.node).ok()?);
            let peeled = match arg_ty.kind() {
                ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
                _ => arg_ty,
            };
            any_hashmap_kv_ty(ctx.tcx, peeled)
        });

    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    let name = name.as_str();
    // Only the constructors are identified by the DESTINATION (see the same
    // guard in `lower_btreemap_call`).
    if !matches!(
        name,
        "new" | "with_capacity" | "with_capacity_and_hasher" | "with_hasher"
    ) && self_kv.is_none()
        && dest_kv.is_some()
        && matches!(
            name,
            "len"
                | "is_empty"
                | "insert"
                | "get"
                | "get_mut"
                | "contains_key"
                | "remove"
                | "entry"
                | "rustc_entry"
        )
    {
        return Err(map_receiver_refusal("HashMap", name));
    }
    // A std callee taking a modeled map that is not the map's own inherent
    // method (see the same guard in `lower_btreemap_call`).
    if self_kv.is_some() && !is_std_map_inherent_method(ctx.tcx, callee.def_id()) {
        return Err(map_callee_refusal(ctx.tcx, callee.def_id(), "HashMap"));
    }
    let (key_ty, val_ty) = match dest_kv.or(self_kv) {
        Some(kv) => kv,
        None => return Ok(false),
    };

    match name {
        // Constructors. `new`/`with_capacity`/`with_hasher` all yield an EMPTY map
        // (the capacity hint is unobservable here; the slot grows on insert). They
        // bind the destination map local to a fresh `{ptr,cap,len}` slot. The
        // admission accepts only std's `RandomState` hasher (no drop glue, no
        // observable state), so `with_hasher`'s hasher operand is unused.
        //
        // [TCG-FOREIGN-MAP] By callee IDENTITY, never by name: only the real
        // std / `hashbrown` constructor yields the empty map this slot (and its
        // receipt) stands for (`is_std_map_inherent_method`).
        "new" | "with_capacity" | "with_capacity_and_hasher" | "with_hasher"
            if dest_kv.is_some() =>
        {
            if !is_std_map_inherent_method(ctx.tcx, callee.def_id()) {
                return Err(foreign_map_constructor_refusal(
                    ctx.tcx,
                    callee.def_id(),
                    "HashMap",
                ));
            }
            lower_btreemap_new(ctx, body, block, call)
        }
        "len" => lower_btreemap_len(ctx, body, block, call),
        "is_empty" => lower_hashmap_is_empty(ctx, body, block, call),
        "insert" => lower_btreemap_insert(ctx, body, block, call, key_ty, val_ty),
        "get" | "get_mut" => lower_btreemap_get(ctx, body, block, call, key_ty, val_ty),
        "contains_key" => lower_btreemap_contains_key(ctx, body, block, call, key_ty),
        "remove" => lower_btreemap_remove(ctx, body, block, call, key_ty, val_ty),
        // The public `HashMap::entry` and the inner `hashbrown` `rustc_entry` it
        // delegates to (the form the `-O3` inliner exposes).
        "entry" | "rustc_entry" => lower_btreemap_entry(ctx, body, block, call, key_ty),
        other => Err(format!(
            "HashMap::<{key_ty:?}, {val_ty:?}>::{other} is not an intercepted HashMap \
             method (only new/with_capacity/with_hasher/insert/get/get_mut/contains_key/\
             remove/entry/len/is_empty are lowered; iteration and non-integer keys/values \
             fail closed)"
        )),
    }
    .map(|()| true)
}

/// `HashMap::is_empty(&self) -> bool`: load the slot's `len` and bind the `bool`
/// destination to `len == 0`. (At `-O0` `is_empty` is a real call; at `-O3` it
/// inlines to a `len == 0` comparison the general path already handles, so this
/// only fires at `-O0`.)
fn lower_hashmap_is_empty<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("HashMap::is_empty with {} args", call.args.len()));
    }
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    let zero = emit_i64_const(ctx, block, 0);
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: TrustIrTy::I64,
            lhs: len,
            rhs: zero,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// Lower a DEAD `HashMap`-construction call whose result is one of the inlined-
/// `new()` internal types (`RandomState` via `LocalKey::with`, ...). The intercepted
/// outer `HashMap { base }` aggregate synthesizes its slot fresh and never reads
/// this value, so we emit no computation: bind the destination to a null `Ptr`
/// (its trust-ir type — see `is_hashmap_dead_internal_ty` in the type mapping)
/// and branch to the successor.
fn lower_hashmap_dead_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    let null = ctx.fresh_value();
    block
        .body
        .push(InstrNode::new(Inst::NullPtr).with_result(null));
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: null,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

// ===========================================================================
// `format!` / `write!` / `String` — intercepted formatting
//
// The `format!("{}", x)` macro lowers (in MIR) to a fixed chain:
//
//     a   = Argument::new_display::<T>(&x)        // one per placeholder
//     arr = [a, ...]                              // [Argument; M]
//     tpl = const b"...\x00"                      // the rt template bytes
//     args= Arguments::new::<N, M>(&tpl, &arr)    // the fmt::Arguments value
//     s   = format(args)                          // -> String  (or)
//     ()  = <W as Write>::write_fmt(&mut w, args) // -> Result   (write!)
//
// The real `core::fmt` machinery (Formatter, the `fmt` trait-object dispatch,
// padding/precision) is unlowerable, so — exactly as `Box::new`/`Vec`/iterators
// are intercepted — we decode this chain at compile time and SYNTHESIZE the
// formatted bytes directly into a `{ ptr, cap, len }` String slot (the same
// representation the bridge uses for an intercepted `Vec<u8>`).
//
// SOUND PARTIAL. We accept ONLY the common, unambiguous case:
//   * every placeholder is a `Display` (`Argument::new_display`) of an integer
//     (any width, signed/unsigned), `&str`, `char`, or `bool`;
//   * the placeholder carries NO flags / width / precision / explicit arg_index
//     (a bare `0b11000000` byte) — i.e. plain `{}` in argument order;
//   * the template decodes cleanly to literal pieces + bare placeholders.
// Anything else (Debug, hex/octal, padding `{:>5}`, named/positional reuse, a
// non-primitive Display, a non-constant template) returns `Ok(false)` and the
// call falls through to the general path, which FAILS CLOSED with a precise
// diagnostic. It never guesses, so it never miscompiles.
// ===========================================================================

/// One decoded format argument: the source operand that produced the `&value`
/// reference, and the displayed value's Rust type.
struct FmtArg<'tcx> {
    /// The `&value` reference operand passed to `Argument::new_display`.
    ref_operand: Operand<'tcx>,
    /// The displayed type `T` (the pointee of `ref_operand`).
    value_ty: Ty<'tcx>,
}

/// The decoded `fmt::Arguments`: the rt template bytes and the per-placeholder
/// arguments (in `args`-array order).
struct DecodedArguments<'tcx> {
    template: Vec<u8>,
    args: Vec<FmtArg<'tcx>>,
}

/// Find the single rvalue assigned to `local` by a plain `StatementKind::Assign`
/// anywhere in the body. The format-macro desugar assigns each temporary exactly
/// once, so this is unambiguous. Returns `None` if there is no such assignment
/// (e.g. the local is a call destination — see `find_local_call`).
fn find_local_assign<'a, 'tcx>(body: &'a Body<'tcx>, local: Local) -> Option<&'a Rvalue<'tcx>> {
    for bb in body.basic_blocks.iter() {
        for stmt in &bb.statements {
            if let StatementKind::Assign(boxed) = &stmt.kind {
                if boxed.0.local == local && boxed.0.projection.is_empty() {
                    return Some(&boxed.1);
                }
            }
        }
    }
    None
}

/// Find the single `Call` terminator whose destination is `local` (a
/// projection-free destination). Returns `(func_operand, args)`.
fn find_local_call<'a, 'tcx>(
    body: &'a Body<'tcx>,
    local: Local,
) -> Option<(&'a Operand<'tcx>, &'a [rustc_span::Spanned<Operand<'tcx>>])> {
    for bb in body.basic_blocks.iter() {
        if let TerminatorKind::Call {
            func,
            args,
            destination,
            ..
        } = &bb.terminator().kind
        {
            if destination.local == local && destination.projection.is_empty() {
                return Some((func, args));
            }
        }
    }
    None
}

/// TRUE iff `local` has exactly ONE direct whole-local definition in `body` and
/// is never partially written, never a `Yield`/`InlineAsm` output, and never
/// mutably (or raw-)borrowed. `find_local_assign` / `find_local_call` return the
/// FIRST matching definition site in block order; a recognizer that credits that
/// site's rvalue as THE compile-time value of the local (e.g. the `format!`
/// `&str`-length reader) is only sound when the definition is provably unique —
/// a branch-varying local (`let n: &str = if c { "trust" } else { "cg" }`
/// assigns `n` in BOTH arms) reaches the use with whichever arm ran, and
/// crediting the first-scanned arm's value silently miscompiles the other path.
/// This predicate is the fail-closed gate: unique direct def and no out-of-band
/// mutation channel => the traced definition IS the reaching definition on
/// every path. (A loop re-executing the single textual def re-produces the same
/// rvalue, so "textually unique" suffices.) Function arguments carry an
/// implicit entry definition, counted here, so a reassigned argument is
/// correctly multi-def while a never-reassigned one has only its (untraceable)
/// caller-provided def — callers then fail to trace it and reject, rather than
/// misread a stale in-body assignment.
fn local_has_unique_direct_def(body: &Body<'_>, local: Local) -> bool {
    // The caller defines every argument on entry.
    let mut defs: usize = usize::from(local.index() >= 1 && local.index() <= body.arg_count);
    for bb in body.basic_blocks.iter() {
        for stmt in &bb.statements {
            match &stmt.kind {
                StatementKind::Assign(boxed) => {
                    let (place, rvalue) = (&boxed.0, &boxed.1);
                    if place.local == local {
                        if place.projection.is_empty() {
                            defs += 1;
                            if defs > 1 {
                                return false;
                            }
                        } else {
                            // A projected (partial) write: the whole-local value
                            // at a use is not any single traced rvalue.
                            return false;
                        }
                    }
                    // A mutable or raw borrow of the LOCAL'S OWN STORAGE opens
                    // an out-of-band write channel; only the read-only
                    // `FakeForPtrMetadata` raw borrow (a compiler-generated
                    // metadata probe) is safe to ignore. A projection containing
                    // a `Deref` (`&raw const (*_r)`, the O3 inlined fmt
                    // reborrow) addresses the POINTEE's memory, not the local's
                    // — the local's own value stays unwritable through it.
                    let borrows_local_storage = |src: &Place<'_>| {
                        src.local == local
                            && !src
                                .projection
                                .iter()
                                .any(|elem| matches!(elem, ProjectionElem::Deref))
                    };
                    match rvalue {
                        Rvalue::Ref(_, mir::BorrowKind::Mut { .. }, src)
                            if borrows_local_storage(src) =>
                        {
                            return false;
                        }
                        Rvalue::RawPtr(kind, src)
                            if borrows_local_storage(src)
                                && !matches!(kind, mir::RawPtrKind::FakeForPtrMetadata) =>
                        {
                            return false;
                        }
                        _ => {}
                    }
                }
                // The only other statement that WRITES a place is
                // `SetDiscriminant` (`Intrinsic(CopyNonOverlapping)` writes
                // through a pointer operand, which must originate from a
                // raw/mut borrow of the local — rejected above).
                StatementKind::SetDiscriminant { place, .. } if place.local == local => {
                    return false;
                }
                _ => {}
            }
        }
        match &bb.terminator().kind {
            TerminatorKind::Call { destination, .. } => {
                if destination.local == local {
                    if destination.projection.is_empty() {
                        defs += 1;
                        if defs > 1 {
                            return false;
                        }
                    } else {
                        return false;
                    }
                }
            }
            // Conservatively treat coroutine resume / inline-asm outputs as
            // untraceable writes (neither occurs in the shapes the fmt
            // recognizers accept; this keeps the predicate honest if they do).
            TerminatorKind::Yield { resume_arg, .. } => {
                if resume_arg.local == local {
                    return false;
                }
            }
            TerminatorKind::InlineAsm { operands, .. } => {
                for op in operands.iter() {
                    let (mir::InlineAsmOperand::Out { place: Some(p), .. }
                    | mir::InlineAsmOperand::InOut {
                        out_place: Some(p), ..
                    }) = op
                    else {
                        continue;
                    };
                    if p.local == local {
                        return false;
                    }
                }
            }
            _ => {}
        }
    }
    defs == 1
}

/// Resolve a call-`func` operand to its monomorphized callee instance, returning
/// `None` for an indirect call or a callee that does not resolve.
fn resolve_call_callee<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    func: &Operand<'tcx>,
) -> Option<Instance<'tcx>> {
    let Operand::Constant(constant) = func else {
        return None;
    };
    let const_ty = ctx.monomorphize_ty(constant.const_.ty());
    let item = fn_items::view(const_ty.kind())?;
    let def_id = item.def_id();
    let args = item.unbound_args()?;
    Instance::try_resolve(ctx.tcx, ty::TypingEnv::fully_monomorphized(), def_id, args)
        .ok()
        .flatten()
}

/// Peel a `move`/`copy` operand to the local it reads (projection-free only).
fn operand_as_local(op: &Operand<'_>) -> Option<Local> {
    match op {
        Operand::Copy(place) | Operand::Move(place) if place.projection.is_empty() => {
            Some(place.local)
        }
        _ => None,
    }
}

/// Read the bytes of a `const &[u8; N]` / `const &[u8]` template operand at
/// compile time. The format macro emits the template as a `const b"..."`
/// reference to a read-only allocation with no provenance.
fn read_const_byte_template<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    operand: &Operand<'tcx>,
) -> Option<Vec<u8>> {
    let Operand::Constant(constant) = operand else {
        return None;
    };
    let evaluated = ctx.eval_const_operand(constant);
    let (alloc_id, range) = match evaluated {
        // `&[u8; N]` reference: a `Scalar` pointer into the array allocation.
        mir::Const::Val(ConstValue::Scalar(scalar), const_ty) => {
            let ptr = rustc_api::allocation_pointer(ctx.tcx, scalar)?;
            let (prov, offset) = ptr.prov_and_relative_offset();
            let alloc_id = prov.alloc_id();
            // The referent type tells us the byte length (`&[u8; N]`).
            let pointee = match const_ty.kind() {
                ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => *inner,
                _ => return None,
            };
            let len = match pointee.kind() {
                ty::Array(elem, count) if *elem == ctx.tcx.types.u8 => {
                    count.try_to_target_usize(ctx.tcx)? as usize
                }
                _ => return None,
            };
            let start = offset.bytes() as usize;
            (alloc_id, start..start + len)
        }
        // `&[u8]` slice fat pointer: `Slice { data, meta }`.
        mir::Const::Val(ConstValue::Slice { alloc_id, meta }, _) => (alloc_id, 0..meta as usize),
        _ => return None,
    };
    let global_alloc = ctx.tcx.try_get_global_alloc(alloc_id)?;
    let GlobalAlloc::Memory(const_alloc) = global_alloc else {
        return None;
    };
    let alloc = const_alloc.inner();
    if !alloc.provenance().ptrs().is_empty() {
        return None;
    }
    if range.end > alloc.len() {
        return None;
    }
    let raw = alloc.inspect_with_uninit_and_ptr_outside_interpreter(range);
    Some(raw.to_vec())
}

/// Decode the `fmt::Arguments` value held in `args_local` back to its template
/// bytes + the ordered placeholder arguments. Returns `None` (caller fails
/// closed) for any shape outside the accepted subset.
///
/// Two MIR shapes are decoded, depending on the inlining level:
///   * O0 — a CALL chain: `Arguments::new(&template, &[Argument::new_display(&x),
///     ...])`. The displayed type is the `new_display` generic arg; the value ref
///     is its argument.
///   * O2/O3 — INLINED struct literals: `Arguments { template: <const> as NonNull
///     (Transmute), args: &[Argument { ty: ArgumentType::Placeholder { value:
///     &x as NonNull (Transmute), formatter: <T as Display>::fmt (reify) } }] as
///     NonNull (Transmute) }`. The displayed type is read off the `formatter`
///     fn-pointer's instance (`<T as Display>::fmt`), and the value ref off the
///     `value` field.
/// Decoding BOTH shapes is what lets the SAME `format!` compile + match at O0 AND
/// O3 (the milestone's differential requirement).
fn decode_fmt_arguments<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    args_local: Local,
) -> Option<DecodedArguments<'tcx>> {
    // A fully-CONST-FOLDED `format!`: rustc itself folds a call whose every
    // placeholder is a literal (`format!("{}", 42)` — no `black_box`, no
    // variable) into `Arguments::from_str_nonconst(const "42")` — one
    // compile-time string, ZERO placeholder args. Recognize it and synthesize
    // the equivalent pure-literal template.
    if let Some(decoded) = decode_from_str_nonconst(ctx, body, args_local) {
        return Some(decoded);
    }
    // Resolve `args_local` to `(template_operand, args_array_ref_operand)` from
    // either the CALL shape (`Arguments::new(tpl, arr)`) or the STRUCT-LITERAL
    // shape (`Arguments { template, args }`).
    let (template_operand, args_array_operand) = decode_arguments_fields(ctx, body, args_local)?;

    // The O2/O3-INLINED `from_str(_nonconst)` struct literal (tagged-pointer
    // encoding — args = `(len << 1) | 1`, not an `&[Argument; M]`): decode the
    // one literal string. Shapes that don't match fall through to the
    // rt-template path below untouched.
    if let Some(decoded) =
        decode_o3_inlined_literal_arguments(ctx, body, &template_operand, &args_array_operand)
    {
        return Some(decoded);
    }

    // Template bytes: a const `&[u8; N]` (O0) or a `const b"..." as NonNull
    // (Transmute)` (O3). Peel a `Transmute`/`Use` to the underlying const.
    let template_const = peel_to_const_through_transmute(body, &template_operand);
    let template = read_const_byte_template(ctx, &template_const)?;

    // The args array: a `&[Argument; M]` (O0) or `&[Argument; M] as NonNull
    // (Transmute)` (O3). Peel to the array reference, then to the array aggregate.
    let array_local = peel_to_array_ref_local(body, &args_array_operand)?;
    let elems = match find_local_assign(body, array_local) {
        Some(Rvalue::Aggregate(_, operands)) => operands.clone(),
        _ => return None,
    };

    let mut decoded_args = Vec::with_capacity(elems.len());
    for elem in &elems {
        let arg = decode_one_argument(ctx, body, elem)?;
        decoded_args.push(arg);
    }

    Some(DecodedArguments {
        template,
        args: decoded_args,
    })
}

/// Decode the fully-const-folded `Arguments` builder:
/// `_args = Arguments::from_str_nonconst(const "…")`. rustc's own const folding
/// produced the string (it IS the formatted output — no guessing on our part),
/// so the decode is a zero-arg `DecodedArguments` whose template is the string
/// re-encoded as a single literal piece in the rt template byte format
/// `parse_fmt_template` reads (`[len]` / `[0x80, u16-le]` prefix + bytes, then
/// the `0x00` terminator). STRICT gating: the callee must be named
/// `from_str_nonconst`, defined in `core`, and return the lang-item
/// `fmt::Arguments`, with exactly one CONST `&str` operand whose bytes are
/// provenance-free — anything else returns `None` and the caller's existing
/// fail-closed path takes over.
fn decode_from_str_nonconst<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    args_local: Local,
) -> Option<DecodedArguments<'tcx>> {
    let (func, call_args) = find_local_call(body, args_local)?;
    let callee = resolve_call_callee(ctx, func)?;
    let def_id = callee.def_id();
    // `from_str` is the explicit-literal builder (`format!("hello")`);
    // `from_str_nonconst` the const-folded one (`format!("{}", 42)`). Same
    // signature, same meaning: the one operand IS the output string.
    if !matches!(
        callee_item_name_str(ctx.tcx, def_id).as_str(),
        "from_str" | "from_str_nonconst"
    ) {
        return None;
    }
    // The real `core::fmt::Arguments::from_str_nonconst`: core-defined and
    // returning the `format_arguments` lang item (a user fn of the same name
    // cannot satisfy both).
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !is_real_core_def(ctx.tcx, def_id) {
        return None;
    }
    let ret_ty = ctx.monomorphize_ty(
        callee
            .ty(ctx.tcx, ty::TypingEnv::fully_monomorphized())
            .fn_sig(ctx.tcx)
            .output()
            .skip_binder(),
    );
    let ty::Adt(ret_adt, _) = ret_ty.kind() else {
        return None;
    };
    if Some(ret_adt.did()) != ctx.tcx.lang_items().format_arguments() {
        return None;
    }
    if call_args.len() != 1 {
        return None;
    }
    // The folded string: a const `&str` (a `ConstValue::Slice`), read via the
    // same provenance-checked const-bytes reader the template decode uses.
    let bytes = read_const_byte_template(ctx, &call_args[0].node)?;
    Some(DecodedArguments {
        template: encode_pure_literal_template(&bytes)?,
        args: Vec::new(),
    })
}

/// Encode `bytes` as a single-literal-piece rt template in the byte format
/// `parse_fmt_template` reads: `[len]` (short, < 0x80) or `[0x80, u16-le]`
/// (long) prefix + the bytes, then the `0x00` terminator. Empty input encodes
/// as just the terminator (zero pieces — `format!("")`).
fn encode_pure_literal_template(bytes: &[u8]) -> Option<Vec<u8>> {
    let mut template = Vec::with_capacity(bytes.len() + 4);
    if bytes.is_empty() {
        // No literal piece — just the terminator.
    } else if bytes.len() < 0x80 {
        template.push(bytes.len() as u8);
        template.extend_from_slice(bytes);
    } else if bytes.len() <= u16::MAX as usize {
        template.push(0x80);
        template.extend_from_slice(&(bytes.len() as u16).to_le_bytes());
        template.extend_from_slice(bytes);
    } else {
        return None;
    }
    template.push(0x00);
    Some(template)
}

/// Peel `Use`/`Cast` links (each unique-def-gated) from `operand` down to the
/// first definition that is neither, returning that rvalue. A `Use`/`Cast` OF A
/// CONSTANT terminates the chain and is itself returned (the caller extracts
/// the constant). Every step requires the peeled local's definition to be
/// unique (`local_has_unique_direct_def`), so a multi-def local can never be
/// traced through the wrong arm's definition.
fn peel_to_defining_rvalue<'a, 'tcx>(
    body: &'a Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Option<&'a Rvalue<'tcx>> {
    let mut local = operand_as_local(operand)?;
    for _ in 0..8 {
        if !local_has_unique_direct_def(body, local) {
            return None;
        }
        let rvalue = find_local_assign(body, local)?;
        match rvalue {
            Rvalue::Use(op, _) | Rvalue::Cast(_, op, _) => match operand_as_local(op) {
                Some(next) => local = next,
                None => return Some(rvalue),
            },
            _ => return Some(rvalue),
        }
    }
    None
}

/// Decode the O2/O3-INLINED literal `Arguments` builder. `Arguments::from_str
/// (_nonconst)` inlines to a TAGGED-POINTER struct literal (the `as_str` niche
/// encoding):
///
/// ```text
/// _s   = const "…";                                  // the literal &str
/// _t   = &raw const (*_s) as *const u8 as NonNull;   // template = DATA ptr
/// _m   = PtrMetadata(const "…" as &[u8]);            // its byte length
/// _a   = BitOr(Shl(_m, 1), 1) as NonNull<Argument>;  // args = (len << 1) | 1
/// _arg = Arguments { template: _t, args: _a };
/// ```
///
/// Both fields must resolve to the SAME `ConstValue::Slice` allocation (id and
/// length), pinning the template pointer and the tagged length to one string —
/// then the decode is that string as a pure-literal template with zero
/// placeholder args (exactly what the runtime `as_str` fast path would
/// produce). A genuine rt-template `Arguments` has an `&[Argument; M]` args
/// field, which cannot match the `BitOr(Shl(PtrMetadata(..), 1), 1)` shape, so
/// this recognizer can never claim one. Any deviation returns `None` and the
/// caller's rt-template path / fail-closed handling takes over.
fn decode_o3_inlined_literal_arguments<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    template_operand: &Operand<'tcx>,
    args_operand: &Operand<'tcx>,
) -> Option<DecodedArguments<'tcx>> {
    // Evaluate a const operand to a `ConstValue::Slice` (alloc + length).
    let const_slice = |op: &Operand<'tcx>| -> Option<(mir::interpret::AllocId, u64)> {
        let Operand::Constant(c) = op else {
            return None;
        };
        match ctx.eval_const_operand(c) {
            mir::Const::Val(ConstValue::Slice { alloc_id, meta }, _) => Some((alloc_id, meta)),
            _ => None,
        }
    };
    let const_is_one = |op: &Operand<'tcx>| -> bool {
        let Operand::Constant(c) = op else {
            return false;
        };
        match ctx.eval_const_operand(c) {
            mir::Const::Val(ConstValue::Scalar(s), _) => s
                .try_to_scalar_int()
                .is_ok_and(|si| si.to_bits(si.size()) == 1),
            _ => false,
        }
    };
    // Extract the constant a chain-terminating `Use`/`Cast` reads.
    let rvalue_const_operand = |rv: &Rvalue<'tcx>| -> Option<Operand<'tcx>> {
        match rv {
            Rvalue::Use(op @ Operand::Constant(_), _)
            | Rvalue::Cast(_, op @ Operand::Constant(_), _) => Some(op.clone()),
            _ => None,
        }
    };

    // args field: BitOr(Shl(PtrMetadata(const str), 1), 1).
    let Rvalue::BinaryOp(mir::BinOp::BitOr, or_ops) = peel_to_defining_rvalue(body, args_operand)?
    else {
        return None;
    };
    let (or_lhs, or_rhs) = (&or_ops.0, &or_ops.1);
    let shl_operand = if const_is_one(or_rhs) {
        or_lhs
    } else if const_is_one(or_lhs) {
        or_rhs
    } else {
        return None;
    };
    let Rvalue::BinaryOp(mir::BinOp::Shl, shl_ops) = peel_to_defining_rvalue(body, shl_operand)?
    else {
        return None;
    };
    if !const_is_one(&shl_ops.1) {
        return None;
    }
    let Rvalue::UnaryOp(mir::UnOp::PtrMetadata, meta_src) =
        peel_to_defining_rvalue(body, &shl_ops.0)?
    else {
        return None;
    };
    let meta_const = match meta_src {
        Operand::Constant(_) => meta_src.clone(),
        _ => rvalue_const_operand(peel_to_defining_rvalue(body, meta_src)?)?,
    };
    let (len_alloc, len_meta) = const_slice(&meta_const)?;

    // template field: `&raw const (*_s)` / `&(*_s)` where `_s = const "…"`.
    let (Rvalue::RawPtr(_, place) | Rvalue::Ref(_, _, place)) =
        peel_to_defining_rvalue(body, template_operand)?
    else {
        return None;
    };
    if !matches!(place.projection.as_ref(), [ProjectionElem::Deref]) {
        return None;
    }
    if !local_has_unique_direct_def(body, place.local) {
        return None;
    }
    let str_const = rvalue_const_operand(find_local_assign(body, place.local)?)?;
    let (tpl_alloc, tpl_meta) = const_slice(&str_const)?;

    // Both fields must denote the SAME literal.
    if tpl_alloc != len_alloc || tpl_meta != len_meta {
        return None;
    }
    let bytes = read_const_byte_template(ctx, &str_const)?;
    Some(DecodedArguments {
        template: encode_pure_literal_template(&bytes)?,
        args: Vec::new(),
    })
}

/// Decode the `fmt::Arguments` local feeding a `panic_fmt` raise when it is a
/// PURE LITERAL — zero placeholder arguments and a template made exclusively
/// of literal pieces — returning the exact message bytes (the `Display`
/// output of that `Arguments` value). This is what `panic!("literal")` /
/// `assert!(cond, "literal")` build on this nightly
/// (`Arguments::from_str(const "…")` at O0; the MIR-inlined tagged-pointer
/// struct literal at O2/O3), letting the unwinding raise pass the message
/// through byte-identical instead of synthesizing one (FUZZ-8 follow-up).
///
/// Reuses the strict recognizers the `format!` interception already trusts
/// (`decode_fmt_arguments`: core-defined builders only, provenance-free const
/// bytes, template/length same-alloc pinning) and adds two fail-safe gates of
/// its own:
///   * the local must have a UNIQUE whole-local definition
///     (`local_has_unique_direct_def`) — two panic sites sharing a multi-def
///     temp could otherwise be credited the OTHER site's message;
///   * any placeholder in the template rejects the decode — a formatted
///     message is never printed as a partial template.
/// Returns `None` on any deviation; the caller then lowers the original call
/// with its real `Arguments` (`exact_panic_block_message`), or the std route
/// refuses (`std_panic_route`).
fn decode_pure_literal_fmt_arguments<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    args_local: Local,
) -> Option<Vec<u8>> {
    if !local_has_unique_direct_def(body, args_local) {
        return None;
    }
    let decoded = decode_fmt_arguments(ctx, body, args_local)?;
    if !decoded.args.is_empty() {
        return None;
    }
    let mut text = Vec::new();
    for piece in parse_fmt_template(&decoded.template)? {
        match piece {
            FmtPiece::Literal(range) => text.extend_from_slice(&decoded.template[range]),
            FmtPiece::Placeholder => return None,
        }
    }
    Some(text)
}

/// The O3-inlined `format!` consumer.
///
/// At `-O2`/`-O3` rustc inlines `alloc::fmt::format(args)` into
/// `args.as_str().map_or_else(|| <closure builds the String>, str::to_owned)` —
/// a call `Option::<&str>::map_or_else::<String, format::{closure#0}, str::to_owned>
/// (option, closure, to_owned)` where the `closure` captures `&args` (the
/// `fmt::Arguments` value). BOTH arms produce the SAME String (`format(args)`):
/// the `as_str()` fast arm is taken only for a single-literal-no-placeholder
/// template, and even then `str::to_owned` yields exactly that literal, which is
/// what formatting it would produce; the slow arm calls the closure which is
/// `format`. So intercepting this call and synthesizing `format(args)` directly is
/// sound regardless of the runtime niche branch. This struct records the locals so
/// the deadness / memory-backing analyses can drop the whole inlined region.
struct O3FormatConsumer {
    /// The `fmt::Arguments` local captured by the format closure (decoded to a
    /// template + args exactly like the O0 `format(args)` call).
    args_local: Local,
    /// The `format::{closure#0}` local passed as the `map_or_else` fallback. It is
    /// DEAD (we synthesize the result), so it must not be memory-backed (its
    /// `&Arguments` capture's pointee has no lowerable layout).
    closure_local: Local,
    /// The `Option<&str>` local (the `as_str()` result) passed as `self`. DEAD.
    option_local: Local,
}

/// Recognize the O3-inlined `format!` consumer described on `O3FormatConsumer`.
/// Returns `Some` when the call is `Option::<&str>::map_or_else(option, closure,
/// to_owned)` with a `String` destination, the `closure` is a `format::{closure#0}`
/// capturing exactly one `&fmt::Arguments`, and the final arg is `str::to_owned` —
/// the exact shape rustc emits for an inlined `format!`. Any deviation returns
/// `None` (the call lowers normally / fails closed), so a user's own `map_or_else`
/// is never mistaken for the format engine.
fn recognize_o3_format_consumer<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    callee: Instance<'tcx>,
    call_args: &[rustc_span::Spanned<Operand<'tcx>>],
    destination: &Place<'tcx>,
) -> Option<O3FormatConsumer> {
    // Callee must be `Option::map_or_else` (the `core::option` method). Use
    // `opt_item_name` — a closure / shim callee def-id has no name and `item_name`
    // would ICE.
    if ctx
        .tcx
        .opt_item_name(callee.def_id())
        .map(|n| n.to_string())
        .as_deref()
        != Some("map_or_else")
    {
        return None;
    }
    if ctx.tcx.def_path_str(callee.def_id()) != "std::option::Option::<T>::map_or_else"
        && !ctx
            .tcx
            .def_path(callee.def_id())
            .data
            .iter()
            .filter_map(|d| d.data.get_opt_name())
            .map(|n| n.to_string())
            .collect::<Vec<_>>()
            .ends_with(&["map_or_else".to_owned()])
    {
        return None;
    }
    if call_args.len() != 3 {
        return None;
    }
    // The `Option`'s payload must be `&str` (the `as_str()` result type) — this is
    // what distinguishes the format consumer from an arbitrary `map_or_else`.
    let self_ty = ctx.monomorphize_ty(
        operand_rust_ty(ctx, body, &call_args[0].node).unwrap_or(ctx.tcx.types.unit),
    );
    if !option_of_str_ref(ctx.tcx, self_ty) {
        return None;
    }
    // Destination must be a `String`.
    if !destination.projection.is_empty() {
        return None;
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, destination));
    if !is_string_ty(ctx.tcx, dest_ty) {
        return None;
    }
    // The third argument must be `<str as ToOwned>::to_owned` (the fast-arm
    // converter) — a reified fn item.
    let to_owned_op = &call_args[2].node;
    if !operand_is_str_to_owned(ctx, body, to_owned_op) {
        return None;
    }

    let option_local = operand_as_local(&call_args[0].node)?;
    let closure_local = operand_as_local(&call_args[1].node)?;

    // The closure must be a `format::{closure#0}` aggregate capturing exactly one
    // `&fmt::Arguments`. Decode the captured Arguments local.
    let args_local = fmt_closure_captured_arguments(ctx, body, closure_local)?;
    Some(O3FormatConsumer {
        args_local,
        closure_local,
        option_local,
    })
}

/// Whether `ty` is `Option<&str>` (the `Arguments::as_str()` result).
fn option_of_str_ref<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, generics) = ty.kind() else {
        return false;
    };
    if Some(adt.did()) != tcx.get_diagnostic_item(rustc_span::sym::Option) {
        return false;
    }
    let Some(inner) = generics.types().next() else {
        return false;
    };
    matches!(inner.kind(), ty::Ref(_, pointee, _) if pointee.is_str())
}

/// Whether `operand` reifies `<str as ToOwned>::to_owned`.
fn operand_is_str_to_owned<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> bool {
    let mut cur = operand.clone();
    for _ in 0..8 {
        match &cur {
            Operand::Constant(c) => {
                let const_ty = ctx.monomorphize_ty(c.const_.ty());
                let Some(item) = fn_items::view(const_ty.kind()) else {
                    return false;
                };
                let did = item.def_id();
                if ctx.tcx.opt_item_name(did).map(|n| n.to_string()).as_deref() != Some("to_owned")
                    || !is_upstream_std_library_def(ctx.tcx, did)
                {
                    return false;
                }
                // Self type (the first generic) must be `str`.
                return item
                    .unbound_args()
                    .is_some_and(|generics| generics.types().next().is_some_and(|t| t.is_str()));
            }
            _ => {
                let Some(local) = operand_as_local(&cur) else {
                    return false;
                };
                match find_local_assign(body, local) {
                    Some(Rvalue::Use(op, _)) | Some(Rvalue::Cast(_, op, _)) => cur = op.clone(),
                    _ => return false,
                }
            }
        }
    }
    false
}

/// Given the `format::{closure#0}` local, return the captured `fmt::Arguments`
/// local. The closure is `_c = closure { 0: _r }` where `_r = &_args` (the format
/// closure captures a single `&Arguments` upvar). Returns `None` for any other
/// closure shape.
fn fmt_closure_captured_arguments<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    closure_local: Local,
) -> Option<Local> {
    // The closure type must be `std::fmt::format::{closure#0}` (the only closure
    // `format` builds). Identify it by its enclosing fn being `alloc`'s `format`.
    let closure_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, closure_local));
    let ty::Closure(closure_did, _) = closure_ty.kind() else {
        return None;
    };
    let parent = ctx.tcx.parent(*closure_did);
    // The enclosing fn must be `alloc`'s `format`. Use `opt_item_name` — a closure
    // / other anonymous parent has no name and `item_name` would ICE.
    if ctx
        .tcx
        .opt_item_name(parent)
        .map(|n| n.to_string())
        .as_deref()
        != Some("format")
        || !is_upstream_std_library_def(ctx.tcx, parent)
    {
        return None;
    }
    // `_c = closure { 0: _r }` — a single upvar.
    let Some(Rvalue::Aggregate(kind, operands)) = find_local_assign(body, closure_local) else {
        return None;
    };
    if !matches!(&**kind, mir::AggregateKind::Closure(..)) || operands.len() != 1 {
        return None;
    }
    let upvar_local = operand_as_local(operands.iter().next()?)?;
    // `_r = &_args` — the captured reference to the `fmt::Arguments` value.
    let mut cur_local = upvar_local;
    for _ in 0..8 {
        match find_local_assign(body, cur_local)? {
            Rvalue::Ref(_, _, place) | Rvalue::RawPtr(_, place) if place.projection.is_empty() => {
                let pointee_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
                if is_fmt_internal_ty(ctx.tcx, pointee_ty) {
                    return Some(place.local);
                }
                return None;
            }
            Rvalue::Use(op, _) | Rvalue::Cast(_, op, _) => {
                cur_local = operand_as_local(op)?;
            }
            _ => return None,
        }
    }
    None
}

/// Resolve a `fmt::Arguments` local to its `(template, args)` field operands,
/// handling the O0 `Arguments::new(tpl, arr)` call and the O3 `Arguments { template,
/// args }` struct literal.
fn decode_arguments_fields<'a, 'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &'a Body<'tcx>,
    args_local: Local,
) -> Option<(Operand<'tcx>, Operand<'tcx>)> {
    // O3 struct literal: `_args = Arguments { template, args }`.
    if let Some(Rvalue::Aggregate(kind, operands)) = find_local_assign(body, args_local) {
        if let mir::AggregateKind::Adt(did, _, _, _, _) = &**kind {
            if Some(*did) == ctx.tcx.lang_items().format_arguments() && operands.len() == 2 {
                let mut it = operands.iter();
                let template = it.next()?.clone();
                let args = it.next()?.clone();
                return Some((template, args));
            }
        }
    }
    // O0 call: `_args = Arguments::new(template, array)`.
    let (new_func, new_args) = find_local_call(body, args_local)?;
    let new_callee = resolve_call_callee(ctx, new_func)?;
    if callee_item_name_str(ctx.tcx, new_callee.def_id()).as_str() != "new"
        || !is_upstream_std_library_def(ctx.tcx, new_callee.def_id())
    {
        return None;
    }
    let ret_ty = new_callee
        .ty(ctx.tcx, ty::TypingEnv::fully_monomorphized())
        .fn_sig(ctx.tcx)
        .output()
        .skip_binder();
    if !is_fmt_internal_ty(ctx.tcx, ctx.monomorphize_ty(ret_ty)) {
        return None;
    }
    if new_args.len() != 2 {
        return None;
    }
    Some((new_args[0].node.clone(), new_args[1].node.clone()))
}

/// Peel `Transmute`/`Use`-of-local chains down to a const operand (for the
/// template, which at O3 is `const b"..." as NonNull (Transmute)`).
fn peel_to_const_through_transmute<'tcx>(
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Operand<'tcx> {
    let mut cur = operand.clone();
    for _ in 0..8 {
        if let Operand::Constant(_) = &cur {
            return cur;
        }
        let Some(local) = operand_as_local(&cur) else {
            return cur;
        };
        match find_local_assign(body, local) {
            Some(Rvalue::Use(op, _)) => cur = op.clone(),
            Some(Rvalue::Cast(_, op, _)) => cur = op.clone(),
            _ => return cur,
        }
    }
    cur
}

/// Peel a `&[Argument; M]` / `&[Argument; M] as NonNull (Transmute)` operand to
/// the underlying array LOCAL (`_arr` in `_ref = &_arr`).
fn peel_to_array_ref_local<'tcx>(body: &Body<'tcx>, operand: &Operand<'tcx>) -> Option<Local> {
    let mut cur = operand.clone();
    for _ in 0..8 {
        let local = operand_as_local(&cur)?;
        match find_local_assign(body, local) {
            // `_ref = &_arr` — found the array.
            Some(Rvalue::Ref(_, _, place)) | Some(Rvalue::RawPtr(_, place))
                if place.projection.is_empty() =>
            {
                return Some(place.local);
            }
            // `_x = _y` / `_x = _y as NonNull (Transmute)` — peel through.
            Some(Rvalue::Use(op, _)) | Some(Rvalue::Cast(_, op, _)) => cur = op.clone(),
            _ => return None,
        }
    }
    None
}

/// Decode one `[Argument; M]` element into `(ref_operand, value_ty)` from either
/// the O0 `Argument::new_display::<T>(ref)` call or the O3 inlined `Argument { ty:
/// ArgumentType::Placeholder { value, formatter, .. } }` struct literal.
fn decode_one_argument<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    elem: &Operand<'tcx>,
) -> Option<FmtArg<'tcx>> {
    let arg_local = operand_as_local(elem)?;

    // O0: `_a = Argument::new_display::<T>(ref)`.
    if let Some((arg_func, arg_args)) = find_local_call(body, arg_local) {
        let arg_callee = resolve_call_callee(ctx, arg_func)?;
        // Only plain `Display` placeholders (Debug/hex/etc. format differently).
        if callee_item_name_str(ctx.tcx, arg_callee.def_id()).as_str() != "new_display"
            || !is_upstream_std_library_def(ctx.tcx, arg_callee.def_id())
        {
            return None;
        }
        if arg_args.len() != 1 {
            return None;
        }
        let value_ty = ctx.monomorphize_ty(arg_callee.args.types().next()?);
        return Some(FmtArg {
            ref_operand: arg_args[0].node.clone(),
            value_ty,
        });
    }

    // O3: `_a = Argument { ty: _t }` where `_t = ArgumentType::Placeholder {
    // value: _v, formatter: _f, .. }`.
    let ty_field_op = match find_local_assign(body, arg_local) {
        Some(Rvalue::Aggregate(kind, operands)) => {
            // `Argument { ty }` — a single-field struct of the `format_argument`
            // lang item.
            match &**kind {
                mir::AggregateKind::Adt(did, _, _, _, _)
                    if Some(*did) == ctx.tcx.lang_items().format_argument()
                        && operands.len() == 1 =>
                {
                    operands.iter().next()?.clone()
                }
                _ => return None,
            }
        }
        _ => return None,
    };
    let ty_field_local = operand_as_local(&ty_field_op)?;
    let (value_op, formatter_op) = match find_local_assign(body, ty_field_local) {
        Some(Rvalue::Aggregate(kind, operands)) => {
            // `ArgumentType::Placeholder { value, formatter, _lifetime }`. We only
            // accept the `Placeholder` variant (a `Count` variant is a dynamic
            // width/precision, outside the subset). Identify it structurally: the
            // ADT is `ArgumentType` and the variant has a `value` + `formatter`
            // pair (the first two fields).
            match &**kind {
                mir::AggregateKind::Adt(did, _variant, _, _, _)
                    if is_fmt_internal_ty(ctx.tcx, ctx.tcx.type_of(*did).skip_binder())
                        && operands.len() >= 2 =>
                {
                    let mut it = operands.iter();
                    let value = it.next()?.clone();
                    let formatter = it.next()?.clone();
                    (value, formatter)
                }
                _ => return None,
            }
        }
        _ => return None,
    };

    // The displayed type `T` from the `formatter` field = `<T as Display>::fmt`
    // reified to a fn pointer. Trace it to the Display::fmt instance and read its
    // self type.
    let value_ty = display_fmt_self_ty(ctx, body, &formatter_op)?;
    // The `value` field is `&x as NonNull (Transmute)`; the underlying ref operand.
    let ref_operand = peel_to_value_ref_operand(body, &value_op)?;
    Some(FmtArg {
        ref_operand,
        value_ty,
    })
}

/// Trace a `formatter` operand (`<T as Display>::fmt` reified + transmuted to an
/// untyped fn pointer) to the displayed type `T`. Returns `None` if it is not a
/// `Display::fmt` reification (e.g. a Debug formatter — out of the subset).
fn display_fmt_self_ty<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Option<Ty<'tcx>> {
    // Peel `Use`/`Transmute`/`ReifyFnPointer` casts to the underlying `<T as
    // Display>::fmt` fn-item constant.
    let mut cur = operand.clone();
    for _ in 0..8 {
        match &cur {
            Operand::Constant(c) => {
                let const_ty = ctx.monomorphize_ty(c.const_.ty());
                let item = fn_items::view(const_ty.kind())?;
                let did = item.def_id();
                // The fn must be `core::fmt::Display::fmt`. Its self type is the
                // first generic argument.
                let name = ctx.tcx.item_name(did);
                if name.as_str() != "fmt" {
                    return None;
                }
                // Confirm the trait is core's `Display` (Debug/hex format
                // differently; a user trait named `Display` is not it).
                let trait_did = ctx.tcx.trait_of_assoc(did)?;
                if Some(trait_did) != ctx.tcx.get_diagnostic_item(rustc_span::sym::Display) {
                    return None;
                }
                return Some(ctx.monomorphize_ty(item.unbound_args()?.type_at(0)));
            }
            _ => {
                let local = operand_as_local(&cur)?;
                match find_local_assign(body, local) {
                    Some(Rvalue::Use(op, _)) | Some(Rvalue::Cast(_, op, _)) => cur = op.clone(),
                    _ => return None,
                }
            }
        }
    }
    None
}

/// Peel a `value` field operand (`&x as NonNull (Transmute)`, possibly via
/// `&raw const (*ref)`) back to an operand whose `Ref`/value the existing
/// ref-tracer (`trace_fmt_ref_to_value_local`) can follow to the value local.
fn peel_to_value_ref_operand<'tcx>(
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Option<Operand<'tcx>> {
    let mut cur = operand.clone();
    for _ in 0..8 {
        let local = operand_as_local(&cur)?;
        match find_local_assign(body, local) {
            // A bare `&x` / `&raw const x` IS a ref operand the value-tracer
            // follows; return the current operand (reading `local`).
            Some(Rvalue::Ref(_, _, _)) | Some(Rvalue::RawPtr(_, _)) => {
                return Some(cur);
            }
            // Peel `Use`/`Transmute`/`Cast` (e.g. `&x -> NonNull -> *const`).
            Some(Rvalue::Use(op, _)) | Some(Rvalue::Cast(_, op, _)) => cur = op.clone(),
            _ => return None,
        }
    }
    None
}

/// Parse the rt template byte sequence into an ordered list of pieces: a literal
/// string slice (by byte range into `template`) or a bare placeholder (consuming
/// the next argument). Returns `None` for any placeholder that is not the plain
/// `0b11000000` byte (any flags / width / precision / explicit index) — those
/// need the full Formatter and are out of the accepted subset.
enum FmtPiece {
    Literal(std::ops::Range<usize>),
    Placeholder,
}

fn parse_fmt_template(template: &[u8]) -> Option<Vec<FmtPiece>> {
    let mut pieces = Vec::new();
    let mut i = 0usize;
    loop {
        if i >= template.len() {
            // A well-formed template ends with a `0` byte; running off the end
            // without one is malformed for our decoder.
            return None;
        }
        let b = template[i];
        if b == 0x00 {
            // End of template.
            return Some(pieces);
        } else if b < 0x80 {
            // Short literal piece: `len` byte then `len` UTF-8 bytes.
            let len = b as usize;
            let start = i + 1;
            let end = start + len;
            if end > template.len() {
                return None;
            }
            pieces.push(FmtPiece::Literal(start..end));
            i = end;
        } else if b == 0x80 {
            // Long literal piece: `0x80`, u16-le length, then the bytes.
            if i + 3 > template.len() {
                return None;
            }
            let len = u16::from_le_bytes([template[i + 1], template[i + 2]]) as usize;
            let start = i + 3;
            let end = start + len;
            if end > template.len() {
                return None;
            }
            pieces.push(FmtPiece::Literal(start..end));
            i = end;
        } else if b == 0xC0 {
            // A fully-default placeholder: a single `0b11000000` byte, no fields.
            pieces.push(FmtPiece::Placeholder);
            i += 1;
        } else {
            // A placeholder WITH flags / width / precision / arg_index (the high
            // two bits set but extra fields follow). Outside the accepted subset.
            return None;
        }
    }
}

/// Whether the `_print`/`_eprint` call whose `fmt::Arguments` is `args_local`
/// is lowered as the REAL std call instead of being synthesized: on x86-64
/// Linux (the target this fallback was measured on against LLVM) when
/// `print_interception_synthesizes` does not hold. Every other target keeps
/// the interception's previous behaviour, where such a call refuses
/// (`[TCG-FMT-DECLINED]`, `[TCG-FMT-ARGPLACE]` or the template refusal).
fn print_falls_back_to_std<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    args_local: Local,
) -> bool {
    print_std_fallback_target(ctx.tcx) && !print_interception_synthesizes(ctx, body, args_local)
}

/// x86-64 Linux: the one target the `print!` std fallback was measured on
/// (bridge vs LLVM, O0-O3, `reports/2026-11-15-x86-slice-capabilities`).
/// Deliberately separate from `array_element_aggregate_target`: widening one
/// admission to a new target must not widen the other.
fn print_std_fallback_target(tcx: TyCtxt<'_>) -> bool {
    tcx.sess.target.arch.desc() == "x86_64" && tcx.sess.target.os == rustc_target::spec::Os::Linux
}

/// x86-64 Linux: the one target the whole-aggregate array-element store and
/// scalarized element read through a reference to a sized array were measured
/// on (bridge vs LLVM, O0-O3, `reports/2026-11-15-x86-slice-capabilities`).
/// Every other target keeps the previous refusal for an element step.
fn array_element_aggregate_target(tcx: TyCtxt<'_>) -> bool {
    tcx.sess.target.arch.desc() == "x86_64" && tcx.sess.target.os == rustc_target::spec::Os::Linux
}

/// Whether the `print!`/`eprint!` interception (`lower_print`) synthesizes the
/// `std::io::_print`/`_eprint` call whose one argument is the `fmt::Arguments`
/// local `args_local`. Decided from the MIR alone, so the deadness analysis
/// (`fmt_intercepted_consumer_locals`, which roots the `Arguments` chain only
/// when this holds) and the call's lowering (`lower_fmt_call`, which
/// synthesizes only when this holds) cannot disagree:
///
/// * the `Arguments` decodes (`decode_fmt_arguments`);
/// * every placeholder is in the synthesized subset
///   (`classify_decoded_arguments`: plain `{}` of an integer, `bool`, `char` or
///   `&str`, one argument per placeholder);
/// * every placeholder's value place is one the synthesis may read at the call
///   (`fmt_placeholder_value_place`).
///
/// When it does not hold, nothing is assumed away: the `Arguments`, its
/// `Argument` array and each argument's formatter function pointer are lowered
/// as ordinary runtime values and the real `_print` formats them with `core::fmt`
/// (whatever trait, flags, width or argument place), exactly as the LLVM backend
/// does; anything in that chain the bridge cannot lower refuses there. A
/// `&str` whose length is not known at the call still refuses in the synthesis
/// (`[TCG-FMT-RTSTR]`): that fact is flow-sensitive and is not judged here.
fn print_interception_synthesizes<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    args_local: Local,
) -> bool {
    let Some(decoded) = decode_fmt_arguments(ctx, body, args_local) else {
        return false;
    };
    let Ok((_, kinds, _)) = classify_decoded_arguments(ctx, body, &decoded) else {
        return false;
    };
    decoded
        .args
        .iter()
        .zip(kinds.iter())
        .all(|(arg, kind)| fmt_placeholder_value_place(ctx, body, arg, kind).is_ok())
}

/// Recognize + lower a `format!`/`write!`/`String` call. Returns `Ok(true)` when
/// handled, `Ok(false)` to fall through, `Err` only on an internal inconsistency
/// in an otherwise-recognized shape.
fn lower_fmt_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    let def_id = callee.def_id();
    // Every recognized String/fmt entry point is defined by core, alloc, or std.
    // Item names and String-shaped arguments are not identities: user functions
    // such as `fn new() -> String` and user traits such as `Evil::len(&String)`
    // can otherwise be mistaken for std operations and silently synthesized with
    // different semantics. Reject the entire interceptor before inspecting the
    // name or destination when the callee comes from any other crate.
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !is_real_std_crate_def(ctx.tcx, def_id) {
        return Ok(false);
    }
    let name = ctx.tcx.item_name(def_id).as_str().to_owned();
    // Untrimmed + no-visible printer: this classifier runs for EVERY
    // core/alloc/std callee, and the default printer's first visible-path
    // use per compile decodes the visible universe (visible_parent_map +
    // 399 module_children, ~3.4 ms — the first-item lowering warmup,
    // gdb-pinned here after the vtable-hash trigger was removed). The two
    // consumers below are substring/prefix matches on paths whose def and
    // visible renderings coincide (`Write` via the trait-impl rendering,
    // `std::io` items defined in std), so the verdicts are unchanged.
    let def_path = rustc_middle::ty::print::with_no_visible_paths!(ctx.tcx.def_path_str(def_id));

    // A call that BUILDS a `core::fmt` plumbing value — `Argument::new_display`,
    // `Arguments::new`, etc. — whose result the `format!`/`write!` interception
    // decodes statically and never uses at runtime. Drop it to a no-op (branch to
    // the successor, bind nothing): the destination local is dead (only the
    // intercepted `format`/`write_fmt` reads it, statically from the MIR). Without
    // this, lowering the call's niche-enum `Argument` result fails closed.
    //
    // SELF-HOST: `ctx.fmt_dead_locals` — not the TYPE — is the authority on
    // whether the destination is decoded statically. Every fmt-internal-typed
    // local of a DOWNSTREAM crate is in that set (it is seeded from exactly those
    // locals), so this is behaviour-identical for user programs; inside `core`
    // itself a `Argument::new(..)` whose result the crate really returns is NOT in
    // it, and the call is lowered for real instead of being dropped.
    if !call.destination.projection.is_empty() {
        // Projected fmt-internal destinations do not occur; leave to fall-through.
    } else if ctx.fmt_dead_locals.contains(&call.destination.local)
        && is_fmt_internal_ty(
            ctx.tcx,
            ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination)),
        )
    {
        ctx.clear_full_place_bindings(call.destination.local);
        emit_call_successor(block, call.target);
        return Ok(true);
    }

    // `core::hint::must_use::<String>(s)` — the identity wrapper `format!` emits
    // around its result. Copy the source String value (a `Ptr`) to the dest.
    if name == "must_use" {
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        if is_string_ty(ctx.tcx, dest_ty) {
            return lower_string_identity(ctx, body, block, call).map(|()| true);
        }
        return Ok(false);
    }

    // `String::new()` — an empty String. Allocate the `{ptr,cap,len}` slot like
    // `Vec::new`, len = 0.
    if name == "new" {
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        if is_string_ty(ctx.tcx, dest_ty) && call.args.is_empty() {
            return lower_string_new(ctx, body, block, call).map(|()| true);
        }
        return Ok(false);
    }

    // `<String as From<&str>>::from(s)` / `<str as ToString>::to_string(s)` /
    // `<str as ToOwned>::to_owned(s)` — the `&str -> owned String` constructors
    // (`String::from("hi")`, `"x".to_string()`, `"x".to_owned()`). A `String` is
    // the same `{ptr,cap,len}` slot as `Vec<u8>`, so this is exactly the slice
    // `to_vec` materialization with `u8` elements, synthesized in the CALLER's
    // frame. STRICTLY GATED: a std/alloc/core callee, a `String` destination,
    // and a single `&str` argument — an integer `42.to_string()` (owned by the
    // `format!` machinery), a `String::from(char)`, and every user method of
    // these names fall through to their existing (fail-closed) paths. The real
    // callee bodies — which build the String in THEIR frame and return the
    // escaping slot address — are never lowered: the un-referenced internal
    // monomorphizations are dropped, and any that remain reachable fail closed
    // on the collection return-escape guard.
    if matches!(name.as_str(), "from" | "to_string" | "to_owned")
        && call.args.len() == 1
        && is_std_collection_method_callee(ctx.tcx, def_id)
    {
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        let arg_ty = ctx.monomorphize_ty(
            operand_rust_ty(ctx, body, &call.args[0].node).unwrap_or(ctx.tcx.types.unit),
        );
        let arg_is_str_ref =
            matches!(arg_ty.kind(), ty::Ref(_, inner, _) if matches!(inner.kind(), ty::Str));
        if is_string_ty(ctx.tcx, dest_ty) && arg_is_str_ref {
            return lower_slice_to_vec(ctx, body, block, call, ctx.tcx.types.u8).map(|()| true);
        }
    }

    // `<intN as ToString>::to_string(&self) -> String` (`-O0`) / `<intN as
    // SpecToString>::spec_to_string(&self) -> String` (the `-O2`/`-O3` inlined
    // form) for a PRIMITIVE INTEGER `self` — the ubiquitous `n.to_string()`
    // shape. The real std body builds the value's decimal ASCII in a stack
    // `itoa::Buffer` and returns an OWNING `String`, which the collection
    // return-escape guard rejects (fail closed). Synthesize the byte-identical
    // String directly in the CALLER's frame instead (reusing the branchless
    // `format!` itoa emitter), so nothing reachable references the real body —
    // it drops out as an un-referenced monomorphization. STRICTLY GATED: a
    // std/core/alloc callee named `to_string`/`spec_to_string`, a single arg
    // whose (peeled) self type is a primitive integer of width <= 64
    // (i8..i64 / u8..u64), and a `String` destination. i128/u128 (whose >64-bit
    // magnitude the I64-carried `emit_itoa` cannot faithfully convert) and every
    // other self type / destination fall through to their existing (fail-closed)
    // paths.
    if matches!(name.as_str(), "to_string" | "spec_to_string")
        && call.args.len() == 1
        && is_std_collection_method_callee(ctx.tcx, def_id)
    {
        if let Some((int_ir, signed)) = int_to_string_self_int_ty(ctx, body, &call.args[0].node) {
            let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
            if is_string_ty(ctx.tcx, dest_ty) {
                return lower_int_to_string(ctx, body, block, call, int_ir, signed).map(|()| true);
            }
        }
    }

    // Methods taking a `&String`/`&mut String`/`String` self: identified by the
    // (peeled) first-arg type.
    let self_is_string = call.args.first().is_some_and(|arg| {
        let ty = ctx
            .monomorphize_ty(operand_rust_ty(ctx, body, &arg.node).unwrap_or(ctx.tcx.types.unit));
        let peeled = match ty.kind() {
            ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
            _ => ty,
        };
        is_string_ty(ctx.tcx, peeled)
    });

    if self_is_string {
        match name.as_str() {
            // `String::len(&self) -> usize`: load the LEN field (reuse Vec::len).
            "len" => return lower_vec_len(ctx, body, block, call).map(|()| true),
            // `String::is_empty(&self) -> bool`: `len == 0`.
            "is_empty" => return lower_string_is_empty(ctx, body, block, call).map(|()| true),
            // `String::push_str(&mut self, &str)` (-O0): grow the buffer and copy
            // the `&str`'s bytes (`u8` elements) to `buf + len`. (At -O3 `push_str`
            // inlines to `Vec::<u8>::append_elements`, handled by `lower_vec_call`.)
            "push_str" => {
                return lower_collection_extend(ctx, body, block, call, ctx.tcx.types.u8)
                    .map(|()| true);
            }
            // `String::push(&mut self, char)` (-O0): UTF-8-encode the `char` (1..4 bytes)
            // and append to the buffer. See `lower_string_push_char`.
            "push" if call.args.len() == 2 => {
                return lower_string_push_char(ctx, body, block, call).map(|()| true);
            }
            // `String::as_bytes(&self) -> &[u8]` / `as_str(&self) -> &str` /
            // `<String as Deref>::deref(&self) -> &str`: a VIEW over the slot's
            // buffer. The destination is a memory-backed fat-pointer local (every
            // slice/str fat pointer is — `fat_ptr_or_memory_aggregate_layout`),
            // so bind its RUNTIME `{ data, len }` slot from the String slot's
            // `ptr`/`len` lanes, exactly as `<Vec<T> as Deref>::deref` does (a
            // `String` is the same `{ptr,cap,len}` slot over `u8`).
            "as_bytes" | "as_str" | "deref" => {
                return lower_vec_deref(ctx, body, block, call).map(|()| true);
            }
            _ => {}
        }
    }

    // `<String as fmt::Write>::write_fmt(&mut self, args)` — `write!`. Append the
    // formatted bytes to the existing String slot.
    if name == "write_fmt" && def_path.contains("Write") && call.args.len() == 2 && self_is_string {
        let Some(args_local) = operand_as_local(&call.args[1].node) else {
            return Ok(false);
        };
        let Some(decoded) = decode_fmt_arguments(ctx, body, args_local) else {
            return Ok(false);
        };
        return lower_write_fmt(ctx, body, block, call, decoded).map(|()| true);
    }

    // `std::io::_print(args)` / `_eprint(args)` — the `print!`/`println!`/
    // `eprint!`/`eprintln!` entry. STRICTLY GATED: the std entry point by name
    // and path, one projection-free `fmt::Arguments` argument (the lang item),
    // and a decodable `Arguments` shape. A decode miss returns `Ok(false)` so
    // the general path keeps today's fail-closed behavior for `{:?}`, padding,
    // named args, and every other unmodeled placeholder — never a wrong byte.
    // The rewritten call still reaches this same std entry (`lower_print`).
    if matches!(name.as_str(), "_print" | "_eprint")
        && call.args.len() == 1
        && def_path.starts_with("std::io")
    {
        let arg_ty = ctx.monomorphize_ty(
            operand_rust_ty(ctx, body, &call.args[0].node).unwrap_or(ctx.tcx.types.unit),
        );
        let is_arguments = matches!(
            arg_ty.kind(),
            ty::Adt(adt, _) if Some(adt.did()) == ctx.tcx.lang_items().format_arguments()
        );
        if is_arguments {
            let Some(args_local) = operand_as_local(&call.args[0].node) else {
                return Ok(false);
            };
            // The same predicate `fmt_intercepted_consumer_locals` rooted this
            // call's `Arguments` by: a call it did not root kept its whole
            // `Arguments` chain live, so it is lowered as the real `_print`.
            if print_falls_back_to_std(ctx, body, args_local) {
                return Ok(false);
            }
            let Some(decoded) = decode_fmt_arguments(ctx, body, args_local) else {
                return Ok(false);
            };
            return lower_print(ctx, body, block, call, decoded, callee, arg_ty).map(|()| true);
        }
    }

    // `Result::<(), fmt::Error>::unwrap(r)` — the `.unwrap()` on a `write!`
    // result. The bridge synthesizes `write_fmt` to ALWAYS produce `Ok(())`, and
    // the real `unwrap` body descends into panic/`Debug`-formatting machinery the
    // backend cannot lower (its symbol would be undefined at link). Intercept it:
    // when the `self` `Result<(), fmt::Error>` was produced by an intercepted
    // `write_fmt` (its discriminant is statically `Ok`), unwrap yields `()` — a
    // no-op (the `()` destination occupies no slot). We recognize the case by the
    // self type being `Result<(), fmt::Error>` (the only Result a `write!` makes);
    // any other `unwrap` falls through to the general path.
    if (name == "unwrap" || name == "expect") && !call.args.is_empty() {
        let self_ty = ctx.monomorphize_ty(
            operand_rust_ty(ctx, body, &call.args[0].node).unwrap_or(ctx.tcx.types.unit),
        );
        // BOTH conditions, each independently necessary:
        //   1. the receiver type is exactly `Result<(), core::fmt::Error>`
        //      (`is_write_result_ty` keys the payload on the core DefId), and
        //   2. the receiver LOCAL carries a compile-time `adt_discriminants`
        //      binding whose variant is `Ok` — which is what the intercepted,
        //      synthesized `write_fmt` binds (`bind_adt_discriminant_binding` in
        //      `lower_write_fmt`), and what no call-returned `Result` has.
        // Condition 1 alone no-op'd `.unwrap()` on a genuine `Err(fmt::Error)`
        // from a USER `fmt::Write` impl whose `write_str` fails (the review's
        // `probe_unwrap_fmt_write_err.rs`: exit 3 vs LLVM's abort); a receiver
        // with no static `Ok` binding — or an `Err` one — now falls through to
        // the real `unwrap`/`expect` MIR, which panics or fails closed.
        if is_write_result_ty(ctx, self_ty) {
            let receiver_statically_ok = operand_as_local(&call.args[0].node)
                .and_then(|local| ctx.adt_discriminants.get(&local))
                .zip(result_ok_variant(ctx, self_ty))
                .is_some_and(|(binding, (ok_idx, _))| binding.variant_index == ok_idx);
            if receiver_statically_ok {
                // The destination is `()` (a ZST) — nothing to bind; just thread
                // the successor. The receiver is statically `Ok(())`, so the real
                // `unwrap` would return `()` without panicking.
                emit_call_successor(block, call.target);
                return Ok(true);
            }
        }
    }

    // `alloc::fmt::format(args) -> String` — the `format!` engine (O0). Synthesize
    // a fresh String holding the formatted bytes.
    if name == "format" {
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        if !is_string_ty(ctx.tcx, dest_ty) || call.args.len() != 1 {
            return Ok(false);
        }
        let Some(args_local) = operand_as_local(&call.args[0].node) else {
            return Ok(false);
        };
        let Some(decoded) = decode_fmt_arguments(ctx, body, args_local) else {
            return Ok(false);
        };
        return lower_format(ctx, body, block, call, decoded).map(|()| true);
    }

    // The -O2/-O3 INLINED `format!` consumer. rustc inlines `format(args)` into
    // `args.as_str().map_or_else(|| <closure: format>, str::to_owned)`, emitted as
    // a `Option::<&str>::map_or_else(option, closure, to_owned)` call whose closure
    // captures `&args`. Both arms yield the SAME String (`format(args)`), so we
    // intercept the call and synthesize the formatted bytes from the captured
    // Arguments exactly like the O0 `format` path. The dead `as_str()` niche-check
    // / `Option<&str>` / closure region is dropped by the deadness analysis (see
    // `compute_fmt_dead_locals` and `compute_memory_backed_locals`).
    if name == "map_or_else" {
        if let Some(consumer) =
            recognize_o3_format_consumer(ctx, body, callee, call.args, call.destination)
        {
            let Some(decoded) = decode_fmt_arguments(ctx, body, consumer.args_local) else {
                return Ok(false);
            };
            return lower_format(ctx, body, block, call, decoded).map(|()| true);
        }
    }

    Ok(false)
}

/// The trust-ir integer type + signedness of a primitive-integer `ToString` /
/// `SpecToString` receiver `operand` (a `&self` reference), or `None` if the
/// (peeled) self type is not a primitive integer of width <= 64 bits. i128/u128
/// are deliberately EXCLUDED: the shared `emit_itoa` carries the magnitude in an
/// I64, which cannot faithfully represent a >64-bit value — those return `None`
/// so the caller falls through to fail closed rather than TRUNCATE. A non-integer
/// (`ty::Adt` etc.) self is also `None`, so a user trait method that merely
/// happens to be named `to_string` over a non-integer receiver never routes here.
fn int_to_string_self_int_ty<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Option<(TrustIrTy, bool)> {
    let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, operand).ok()?);
    let self_ty = match arg_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
        _ => arg_ty,
    };
    match self_ty.kind() {
        ty::Int(int_ty) => Some((
            match int_ty.bit_width() {
                Some(8) => TrustIrTy::I8,
                Some(16) => TrustIrTy::I16,
                Some(32) => TrustIrTy::I32,
                // `isize` reports `None`; on a 64-bit target it is 64 bits.
                Some(64) | None => TrustIrTy::I64,
                _ => return None, // i128 — cannot be I64-carried
            },
            true,
        )),
        ty::Uint(uint_ty) => Some((
            match uint_ty.bit_width() {
                Some(8) => TrustIrTy::U8,
                Some(16) => TrustIrTy::U16,
                Some(32) => TrustIrTy::U32,
                // `usize` reports `None`; on a 64-bit target it is 64 bits.
                Some(64) | None => TrustIrTy::U64,
                _ => return None, // u128 — cannot be I64-carried
            },
            false,
        )),
        _ => None,
    }
}

/// Load the primitive integer value behind an integer `to_string`/`spec_to_string`
/// `&self` receiver `operand`, as a value of trust-ir type `int_ir`. Two receiver
/// shapes occur:
///   * a PLACE operand `move/copy _r` where `_r: &intN` (`-O0`: `_r = &x`) —
///     read through a synthesized `(*_r)` deref place, which the place kernel
///     resolves for BOTH a real reference (a typed load through the pointer) and
///     a virtual `&scalar` borrow (folded to the borrow target's value), so a
///     scalarized local receiver is handled correctly;
///   * a promoted-const reference (`-O2`/`-O3`: `const &intN`, e.g.
///     `const main::promoted[0]`) — materialize the const's data-relocated
///     address and load the pointee.
/// Any other operand fails closed (no partial effect — this runs before any slot
/// or allocation is emitted).
fn emit_int_to_string_self_load<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    operand: &Operand<'tcx>,
    int_ir: TrustIrTy,
) -> Result<ValueId, String> {
    match operand {
        Operand::Copy(place) | Operand::Move(place) if place.projection.is_empty() => {
            let deref = Place {
                local: place.local,
                projection: ctx.tcx.mk_place_elems(&[ProjectionElem::Deref]),
            };
            lower_operand_to_value(ctx, body, block, &Operand::Copy(deref))
        }
        Operand::Constant(_) => {
            let ref_ptr = lower_operand_to_value(ctx, body, block, operand)?;
            let ptr = coerce_to_plain_ptr(ctx, block, ref_ptr);
            Ok(emit_typed_load(ctx, block, ptr, int_ir))
        }
        _ => Err("integer to_string receiver is not a resolvable &self operand".to_owned()),
    }
}

/// Synthesize `<intN as ToString>::to_string(&self)` / `spec_to_string(&self)`
/// for a primitive integer `self` of width <= 64 (`int_ir`, `signed`): build a
/// fresh `{ptr,cap,len}` String slot in the caller's frame holding the value's
/// decimal ASCII at std's capacity, bind the destination to the slot address,
/// and thread the call successor — reusing the branchless `format!` itoa
/// machinery (`emit_itoa_extent` + `emit_string_slot_alloc` + `emit_itoa`). Byte-for-byte identical to the std
/// body's output (leading-zero-suppressed decimal, a leading `'-'` for a negative
/// signed value). The caller (`lower_fmt_call`) has already gated the callee,
/// self width, and `String` destination.
fn lower_int_to_string<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    int_ir: TrustIrTy,
    signed: bool,
) -> Result<(), String> {
    if !call.destination.projection.is_empty() {
        return Err("integer to_string into a projected destination".to_owned());
    }
    // Load the receiver's integer value FIRST — an unresolvable receiver fails
    // closed before any slot/allocation exists (no partial side effect).
    let narrow =
        emit_int_to_string_self_load(ctx, body, block, &call.args[0].node, int_ir.clone())?;

    // Widen the value to the I64 magnitude carrier the digit loop consumes
    // (mirrors `emit_format_one_placeholder`): a same-width reinterpret for a
    // 64-bit value, else a sign/zero extension. Reading the resulting I64 bit
    // pattern as UNSIGNED (`emit_itoa`'s UDiv/URem) covers the full u64 range;
    // the signed sign/magnitude split covers the full i64 range incl. `i64::MIN`.
    let bits = int_ir.bit_width().unwrap_or(64);
    let value = if bits >= 64 {
        coerce_to_i64(ctx, block, narrow)
    } else {
        let op = if signed { CastOp::SExt } else { CastOp::ZExt };
        let widened = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op,
                src_ty: int_ir.clone(),
                dst_ty: TrustIrTy::I64,
                operand: narrow,
            })
            .with_result(widened),
        );
        widened
    };

    // std's `SpecToString` capacity: a signed value is
    // `String::with_capacity(SIZE)` (`SIZE + 1` when negative), where SIZE is
    // the digit count of the type's MAX, and its `'-'` and digits then fit; an
    // unsigned value is its digit string's `to_string()`, exactly its length.
    let (sign, digits) = emit_itoa_extent(ctx, block, value, signed);
    let cap = match sign {
        Some(sign) => {
            let max = (1u128 << (bits - 1)) - 1;
            let size = emit_i64_const(ctx, block, i128::from(max.ilog10() + 1));
            emit_i64_binop(ctx, block, TrustIrBinOp::Add, size, sign)
        }
        None => digits,
    };
    let slot_ptr = emit_string_slot_alloc(ctx, body, block, cap, Some(call))?;

    // Cursor scratch slot (running length), init 0.
    let cursor_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I64,
            count: None,
            align: None,
        })
        .with_result(cursor_slot),
    );
    let zero = emit_i64_const(ctx, block, 0);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, zero);
    let data_ptr = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
    emit_itoa(ctx, block, data_ptr, cursor_slot, value, signed);

    // Finalize the length, bind the destination String to the slot address, and
    // branch to the successor (exactly as `lower_format`).
    let final_len = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_LEN, final_len);
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: slot_ptr,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// The category of a formattable placeholder value, with what it needs to emit.
enum FmtKind {
    /// A signed integer of the given trust-ir width (`I8`/.../`I64`/`I128`).
    SignedInt(TrustIrTy),
    /// An unsigned integer of the given trust-ir width (`U8`/.../`U64`/`U128`).
    UnsignedInt(TrustIrTy),
    /// A `bool` (formats as `true` / `false`).
    Bool,
    /// A `char` (formats as its 1..=4 UTF-8 bytes).
    Char,
    /// A `&str` (formats as its bytes verbatim).
    Str,
}

/// Classify a Display placeholder's value type into a `FmtKind`, or `None` if it
/// is outside the accepted subset (so the whole `format!` falls through to fail
/// closed). `&str` is recognized by the pointee being `str`.
fn classify_fmt_value<'tcx>(_tcx: TyCtxt<'tcx>, value_ty: Ty<'tcx>) -> Option<FmtKind> {
    match value_ty.kind() {
        ty::Bool => Some(FmtKind::Bool),
        ty::Char => Some(FmtKind::Char),
        ty::Int(int_ty) => Some(FmtKind::SignedInt(match int_ty.bit_width() {
            Some(8) => TrustIrTy::I8,
            Some(16) => TrustIrTy::I16,
            Some(32) => TrustIrTy::I32,
            Some(64) | None => TrustIrTy::I64,
            // 128-bit ints route to `emit_itoa_i128` (a full 128-bit magnitude
            // digit loop), NOT the truncating `coerce_to_i64` path; the
            // placeholder emitter branches on `bits == 128`.
            Some(128) => TrustIrTy::I128,
            _ => return None,
        })),
        ty::Uint(uint_ty) => Some(FmtKind::UnsignedInt(match uint_ty.bit_width() {
            Some(8) => TrustIrTy::U8,
            Some(16) => TrustIrTy::U16,
            Some(32) => TrustIrTy::U32,
            Some(64) | None => TrustIrTy::U64,
            Some(128) => TrustIrTy::U128,
            _ => return None,
        })),
        ty::Ref(_, inner, _) if matches!(inner.kind(), ty::Str) => Some(FmtKind::Str),
        _ => None,
    }
}

/// The COMPILE-TIME upper bound (bytes) a `FmtKind` placeholder can occupy in the
/// output, EXCLUDING `&str` whose length is runtime (`Str` contributes its
/// runtime length separately). Used to size the output buffer's static part.
fn fmt_kind_max_static_len(kind: &FmtKind) -> u64 {
    match kind {
        // Worst-case decimal digit count + an optional sign byte.
        FmtKind::SignedInt(ty) => match ty {
            TrustIrTy::I8 => 4,    // "-128"
            TrustIrTy::I16 => 6,   // "-32768"
            TrustIrTy::I32 => 11,  // "-2147483648"
            TrustIrTy::I64 => 20,  // "-9223372036854775808"
            TrustIrTy::I128 => 40, // "-170141183460469231731687303715884105728"
            _ => 40,
        },
        FmtKind::UnsignedInt(ty) => match ty {
            TrustIrTy::U8 => 3,
            TrustIrTy::U16 => 5,
            TrustIrTy::U32 => 10,
            TrustIrTy::U64 => 20,
            TrustIrTy::U128 => 39,
            _ => 39,
        },
        FmtKind::Bool => 5, // "false"
        FmtKind::Char => 4, // a 4-byte UTF-8 scalar
        FmtKind::Str => 0,  // runtime length, added separately
    }
}

/// Allocate a real `{cap,ptr,len}` String header with the requested capacity.
/// Zero capacity keeps the aligned dangling pointer and makes no allocation.
fn emit_string_slot_alloc<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    cap: ValueId,
    call: Option<&DirectCallTerminator<'_, 'tcx>>,
) -> Result<ValueId, String> {
    let slot_ptr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: vec_slot_ty(),
            count: None,
            align: None,
        })
        .with_result(slot_ptr),
    );
    // The slot's address IS the collection value: fresh per execution.
    ctx.per_execution_allocas.insert(slot_ptr);
    if let Some(call) = call {
        emit_collection_capacity_guard(ctx, body, block, call, cap, 1)?;
    } else if !collection_value_is_zero(block, cap) {
        return Err(
            "[TCG-COLLECTION-ALLOC-SITE] nonzero String allocation has no real MIR call edge"
                .to_owned(),
        );
    }
    let align_const = emit_i64_const(ctx, block, 1);
    let zero = emit_i64_const(ctx, block, 0);
    let dangling = emit_collection_dangling(ctx, block, 1);
    let no_allocation = collection_value_is_zero(block, cap);
    let data_ptr = emit_collection_resize(ctx, block, dangling, zero, cap, align_const)?;
    if !no_allocation {
        if let Some(call) = call {
            emit_collection_null_error_guard(ctx, block, call, data_ptr, cap, align_const)?;
        }
    }
    let len_zero = emit_i64_const(ctx, block, 0);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_PTR, data_ptr);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_CAP, cap);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_LEN, len_zero);
    Ok(slot_ptr)
}

/// Compute the runtime byte capacity required to hold the formatted output:
/// `static_max + sum(runtime length of each &str arg)`, clamped to `>= 1`. The
/// static part bounds every non-`&str` placeholder by its worst case (see
/// `fmt_kind_max_static_len`); `&str` lengths are read from the pointer-metadata
/// side table (a `&str` arg's length). Returns the capacity value, or `Err` if a
/// `&str` arg's length is not statically known to the bridge. Only `print!`'s
/// private buffer is sized this way: a `format!` or `write!` String starts at
/// std's capacity and grows per write (`fmt_initial_capacity`,
/// `emit_format_into_slot`).
#[allow(clippy::too_many_arguments)]
fn emit_format_capacity<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    pieces: &[FmtPiece],
    template: &[u8],
    kinds: &[FmtKind],
    str_lengths: &[Option<u64>],
    runtime_strs: &[Option<(ValueId, ValueId)>],
) -> Result<ValueId, String> {
    let mut static_max: u64 = 0;
    for piece in pieces {
        if let FmtPiece::Literal(range) = piece {
            static_max += (range.end - range.start) as u64;
        }
    }
    let _ = template;
    // The runtime `&str` lengths to add on top of `static_max` (each a resolved
    // `I64` fat-pointer `len` lane). Collected in placeholder order; empty when
    // every `&str` is const-length, so the capacity stays a single compile-time
    // constant (byte-for-byte the previous behavior).
    let mut runtime_lens: Vec<ValueId> = Vec::new();
    let mut arg_idx = 0usize;
    for piece in pieces {
        if matches!(piece, FmtPiece::Placeholder) {
            static_max += fmt_kind_max_static_len(&kinds[arg_idx]);
            // A `&str` arg contributes its byte length: a const `&str` adds its
            // statically-known length to `static_max`; a RUNTIME `&str`
            // contributes its resolved `len` lane, summed in at runtime below.
            if matches!(kinds[arg_idx], FmtKind::Str) {
                if let Some(len) = str_lengths[arg_idx] {
                    static_max += len;
                } else {
                    let (_data, len) = runtime_strs[arg_idx].ok_or_else(|| {
                        "format! runtime &str argument was not resolved to (data, len)".to_owned()
                    })?;
                    runtime_lens.push(len);
                }
            }
            arg_idx += 1;
        }
    }
    let _ = body;
    // `+1` guard so the buffer is never zero-sized (a valid heap allocation).
    let mut cap = emit_i64_const(ctx, block, i128::from(static_max + 1));
    // Add each runtime `&str` length: `cap = static_const + sum(runtime len_i)`.
    for len in runtime_lens {
        cap = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cap, len);
    }
    Ok(cap)
}

/// The compile-time byte length of a `&str` placeholder argument. The arg's
/// value traces (via `trace_fmt_ref_to_value_local`) to a `&str` value local;
/// we follow that local's definition through `black_box` calls / `Use` copies to
/// the underlying `&str` CONSTANT and read its length from the const's slice
/// metadata. (A const `&str`'s length is fixed at compile time even when wrapped
/// in `black_box`, which is an identity barrier.) Returns `None` if the length is
/// not compile-time determinable — the caller fails closed.
fn str_arg_static_len<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    ref_operand: &Operand<'tcx>,
) -> Option<u64> {
    let value_local = trace_fmt_ref_to_value_local(body, ref_operand)?;
    // Follow the `&str` value local through black_box / Use copies to a const.
    let mut cur = value_local;
    for _ in 0..8 {
        // A recorded metadata length (a const `&str` bound with its length).
        // Flow-CORRECT for any def shape: the state map is sampled at the
        // format-call program point and joins drop disagreeing entries.
        if let Some(len) = ctx.pointer_metadata_lengths.get(&cur).copied() {
            return Some(len);
        }
        // Every arm below reads `cur`'s first-scanned DEFINITION SITE as its
        // value, which is only its reaching definition when that def is
        // provably unique. A branch-varying `&str` (`if c { "trust" } else
        // { "cg" }` assigns `cur` in both arms) would otherwise be credited
        // the first-scanned arm's length — a silent miscompile on the other
        // path (wrong copy length AND wrong final String len). Fail closed.
        if !local_has_unique_direct_def(body, cur) {
            return None;
        }
        // `_v = const "..."` — read the slice metadata length directly.
        if let Some(Rvalue::Use(Operand::Constant(c), _)) = find_local_assign(body, cur) {
            if let mir::Const::Val(ConstValue::Slice { meta, .. }, _) = ctx.eval_const_operand(c) {
                return Some(meta);
            }
        }
        // `_v = black_box(_x)` — follow the black_box argument (identity barrier).
        if let Some((func, args)) = find_local_call(body, cur) {
            if let Some(callee) = resolve_call_callee(ctx, func) {
                if is_std_black_box(ctx.tcx, callee.def_id()) && args.len() == 1 {
                    // The const may be the direct arg, or a local assigned a const.
                    if let Operand::Constant(c) = &args[0].node {
                        if let mir::Const::Val(ConstValue::Slice { meta, .. }, _) =
                            ctx.eval_const_operand(c)
                        {
                            return Some(meta);
                        }
                    }
                    if let Some(next) = operand_as_local(&args[0].node) {
                        cur = next;
                        continue;
                    }
                }
            }
        }
        // `_v = _w` — peel a plain copy.
        if let Some(Rvalue::Use(op, _)) = find_local_assign(body, cur) {
            if let Some(next) = operand_as_local(op) {
                cur = next;
                continue;
            }
        }
        return None;
    }
    None
}

/// Validate `decoded` and classify each arg, returning `(pieces, kinds,
/// str_lengths)` or an `Err` for any shape outside the accepted subset. Pure (no
/// IR emitted) so callers can reject BEFORE mutating any block or binding a
/// destination — the call then fails closed with no observable effect.
fn classify_decoded_arguments<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    decoded: &DecodedArguments<'tcx>,
) -> Result<(Vec<FmtPiece>, Vec<FmtKind>, Vec<Option<u64>>), String> {
    let pieces = parse_fmt_template(&decoded.template)
        .ok_or_else(|| "format! template has an unsupported placeholder/encoding".to_owned())?;
    let placeholder_count = pieces
        .iter()
        .filter(|p| matches!(p, FmtPiece::Placeholder))
        .count();
    if placeholder_count != decoded.args.len() {
        return Err(format!(
            "format! placeholder count {placeholder_count} != arg count {} \
             (named/positional/reused args not supported)",
            decoded.args.len()
        ));
    }
    let mut kinds = Vec::with_capacity(decoded.args.len());
    let mut str_lengths = Vec::with_capacity(decoded.args.len());
    for arg in &decoded.args {
        let kind = classify_fmt_value(ctx.tcx, arg.value_ty)
            .ok_or_else(|| format!("format! placeholder of unsupported type {:?}", arg.value_ty))?;
        // A `&str` placeholder: a CONST `&str` yields its statically-known length
        // (`Some(len)` — the branchless unrolled copy path). A RUNTIME `&str` (a fn
        // param / non-const local) leaves this `None`; the emitter then resolves
        // its `(data, len)` fat-pointer halves at runtime (`resolve_fmt_runtime_strs`)
        // and copies with a runtime-count loop. `None` no longer fails closed here —
        // an unresolvable runtime `&str` instead fails closed at emit time (before
        // the destination is bound), discarding the whole `format!`. A non-`Str`
        // arg is always `None`.
        //
        // An INTEGER placeholder is read like every other one, whatever its value
        // derives from. A length used to be refused here ([TCG-FMT-LEN], removed
        // 2026-10-03): at -O0 `str::len` was then a real call taking the `&str`
        // pair by value, whose by-value-aggregate retype poisoned the caller's
        // own slot, so the length was undefined and printed as a stale `4096`.
        // That retype is now scoped to a fresh temp at the call site, and
        // `str::len` is intercepted (`lower_str_len_call`); `Vec`/`String::len`,
        // `PtrMetadata` and every other length source bind a defined value.
        // Measured with the gate disabled (bridge vs LLVM, -O0..-O3, panic
        // abort and unwind): Vec/String/`&str`/slice/array/subslice lengths,
        // after push/truncate/pop/clear/extend/retain, through arithmetic, casts
        // and branches, into format!/println!/eprintln!/write!, matched in every
        // cell that compiled. tests/format_length_black_box_aarch64.rs pins it.
        let str_len = match kind {
            FmtKind::Str => str_arg_static_len(ctx, body, &arg.ref_operand),
            _ => None,
        };
        kinds.push(kind);
        str_lengths.push(str_len);
    }
    Ok((pieces, kinds, str_lengths))
}

/// Classify every `&str` argument `classify_decoded_arguments` left with
/// `str_lengths[i] == None` — a GENUINE runtime-length `&str` (no compile-time
/// length). Returns a vec parallel to `decoded.args`: `None` for a non-`Str` arg
/// OR a `Str` with a static length (the branchless unrolled const path).
///
/// FAIL-CLOSED [TCG-FMT-RTSTR]: a `Str` arg with `str_lengths[i] == None` returns
/// `Err`, discarding the whole `format!`. The runtime `(data, len)` resolution +
/// byte-copy path this used to take (`resolve_slice_source_data_len` + a
/// runtime-count copy loop) is NOT yet sound across `&str` provenances — a
/// pre-bound intermediate `&str` view (`let a = owned.as_str(); format!("({})",
/// a)`) resolved to a WRONG `(data, len)` and silently copied zero / garbage
/// bytes (found by the FUZZ-1 differential). Every SHIPPED runtime-`&str`
/// `format!` fixture binds its arg to a `black_box("literal")`, whose length
/// `str_arg_static_len` recovers through the identity barrier, so those take the
/// CONST path (`str_lengths[i] == Some(_)`) and are UNAFFECTED. Emits no IR, so a
/// rejection fails the `format!` closed with no bound destination and no committed
/// IR. A future sound runtime resolution can re-open this branch.
fn resolve_fmt_runtime_strs<'tcx>(
    _ctx: &mut MirLoweringCtx<'tcx>,
    _body: &Body<'tcx>,
    _block: &mut Block,
    decoded: &DecodedArguments<'tcx>,
    kinds: &[FmtKind],
    str_lengths: &[Option<u64>],
) -> Result<Vec<Option<(ValueId, ValueId)>>, String> {
    let mut out = Vec::with_capacity(decoded.args.len());
    for (i, _arg) in decoded.args.iter().enumerate() {
        if matches!(kinds[i], FmtKind::Str) && str_lengths[i].is_none() {
            // A GENUINE runtime-length `&str` (no compile-time length recovered by
            // `str_arg_static_len`). Fail closed: the runtime `(data, len)`
            // resolution + copy path is NOT yet sound across provenances. A
            // pre-bound intermediate `&str` VIEW (`let a = owned.as_str();
            // format!("({})", a)`) resolves to a WRONG `(data, len)` and silently
            // copies zero / garbage bytes (the differential produced "()" and
            // out-of-range lengths), while a fn-param / sub-slice source already
            // fails closed downstream. Crucially, NO shipped fixture exercises this
            // branch: every runtime-`&str` `format!` fixture binds its arg to a
            // `black_box("literal")`, whose length `str_arg_static_len` recovers
            // through the identity barrier — those take the CONST path
            // (`str_lengths[i] == Some(_)`) and are unaffected here. Reject rather
            // than risk a silent wrong copy. [TCG-FMT-RTSTR]
            return Err("[TCG-FMT-RTSTR] format! runtime-length &str argument (no \
                 compile-time length) — the runtime (data,len) resolution is not \
                 sound for every provenance; failing closed rather than risk a \
                 wrong-length / wrong-address byte copy"
                .to_owned());
        }
        out.push(None);
    }
    Ok(out)
}

/// Emit the whole formatting program for `decoded` into the (already-allocated)
/// String slot at `slot_ptr`, starting from `cursor_slot` bytes already written
/// (`cursor_slot` holds the running length, an `I64`).
///
/// The const-only surface (literals + integer / bool / char / const-`&str`
/// placeholders) is BRANCHLESS — the integer digit loop and each const `&str`
/// copy are unrolled to a fixed width — so it slots into the single trust-ir block
/// the call terminator owns. A RUNTIME `&str` placeholder (`runtime_strs[i] =
/// Some((data, len))`) instead copies its bytes with a runtime-count loop, which
/// SPLITS control flow: the current block ends with a branch into the copy loop
/// and emission continues in a fresh continuation block. Since every write reads /
/// updates the `cursor_slot` and `data_ptr` through MEMORY (not SSA carried across
/// the split), splitting is sound; the fresh loop/continuation blocks all go to
/// `ctx.extra_blocks` while the ORIGINAL `block` keeps its id/position (terminated
/// by the first split's branch). Returns `Some(tail)` — the final still-open
/// continuation block the caller must finalize into and push — when any split
/// happened, or `None` when the whole program stayed in `block` (the caller then
/// finalizes into `block` directly).
///
/// The caller has already validated `decoded` via `classify_decoded_arguments` and
/// resolved every runtime `&str` via `resolve_fmt_runtime_strs`, so a
/// classification mismatch here is an internal inconsistency (`Err`).
#[allow(clippy::too_many_arguments)]
fn emit_format_into_slot<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    block: &mut Block,
    slot_ptr: ValueId,
    cursor_slot: ValueId,
    decoded: &DecodedArguments<'tcx>,
    pieces: &[FmtPiece],
    kinds: &[FmtKind],
    str_lengths: &[Option<u64>],
    runtime_strs: &[Option<(ValueId, ValueId)>],
) -> Result<Option<Block>, String> {
    // Read every PROJECTED placeholder value (`(*_b).f`, a load through a
    // pointer — see `fmt_placeholder_value_place`) BEFORE the first reserve
    // below can `__rust_realloc`. `core::fmt` reads a leading placeholder before
    // the receiver grows, so a `write!` whose pointee lives in the receiver
    // String's own heap buffer is defined for that order and would read freed
    // memory after a reserve. A bare-local placeholder cannot live in the
    // heap and keeps its in-place read (unchanged IR). The loads go in the
    // ORIGINAL block, which dominates every continuation block a runtime-`&str`
    // copy creates.
    let mut preloaded: Vec<Option<ValueId>> = Vec::with_capacity(decoded.args.len());
    for (arg, kind) in decoded.args.iter().zip(kinds.iter()) {
        if matches!(kind, FmtKind::Str) {
            preloaded.push(None);
            continue;
        }
        let place = fmt_placeholder_value_place(ctx, body, arg, kind)?;
        if place.projection.is_empty() {
            preloaded.push(None);
        } else {
            let value = lower_operand_to_value(ctx, body, block, &Operand::Copy(place))?;
            preloaded.push(Some(value));
        }
    }

    // Each write reserves exactly its own bytes first, as `core::fmt::write`
    // does: a literal piece and a `&str` are one `write_str`, a negative
    // integer's `'-'` is a `write_char` before its digits. So the String grows
    // (and calls the allocator) exactly when and as std's would, and ends with
    // std's capacity. The buffer address is reloaded after every reserve,
    // which may reallocate it.
    // `tail` is the current continuation block once a runtime-`&str` copy has split
    // control flow; while it is `None` we emit into the original `block`.
    let mut tail: Option<Block> = None;
    let mut arg_idx = 0usize;
    for piece in pieces {
        match piece {
            FmtPiece::Literal(range) => {
                let bytes = &decoded.template[range.clone()];
                if bytes.is_empty() {
                    continue;
                }
                let cur = tail.as_mut().unwrap_or(&mut *block);
                let extra = emit_i64_const(ctx, cur, bytes.len() as i128);
                emit_string_reserve(ctx, body, call, cur, slot_ptr, cursor_slot, extra)?;
                let data_ptr = emit_vec_field_load(ctx, cur, slot_ptr, VEC_FIELD_PTR);
                emit_write_const_bytes(ctx, cur, data_ptr, cursor_slot, bytes);
            }
            FmtPiece::Placeholder => {
                let arg = &decoded.args[arg_idx];
                let kind = &kinds[arg_idx];
                if let Some((src_data, src_len)) = runtime_strs[arg_idx] {
                    // RUNTIME `&str`: copy `src_len` bytes from `src_data` to
                    // `data_ptr + cursor` with a runtime-count loop, advancing the
                    // cursor by `src_len`. This splits the current block.
                    let cont_id = ctx.fresh_block_id();
                    {
                        let cur = tail.as_mut().unwrap_or(&mut *block);
                        emit_string_reserve(ctx, body, call, cur, slot_ptr, cursor_slot, src_len)?;
                        let data_ptr = emit_vec_field_load(ctx, cur, slot_ptr, VEC_FIELD_PTR);
                        let cursor = emit_typed_load(ctx, cur, cursor_slot, TrustIrTy::I64);
                        let dst_base = emit_element_addr(ctx, cur, data_ptr, cursor, 1);
                        // Advance the cursor by the (runtime) length BEFORE the loop
                        // (the copy loop itself does not touch `cursor_slot`); the
                        // continuation block then reads the advanced cursor.
                        let new_cursor =
                            emit_i64_binop(ctx, cur, TrustIrBinOp::Add, cursor, src_len);
                        emit_typed_store(cur, cursor_slot, TrustIrTy::I64, new_cursor);
                        // `emit_typed_copy_loop` terminates `cur` with a branch into
                        // a fresh loop (header/body -> `ctx.extra_blocks`) whose exit
                        // is `cont_id`. The source `&str` and the freshly-(re)alloc'd
                        // heap buffer are disjoint allocations, so the copy is
                        // non-overlapping; `src_len == 0` copies nothing (correct for
                        // an empty runtime `&str`).
                        emit_typed_copy_loop(
                            ctx,
                            cur,
                            cont_id,
                            src_data,
                            dst_base,
                            src_len,
                            1,
                            TrustIrTy::I8,
                        );
                    }
                    // The block we just terminated: if it was a PRIOR continuation
                    // (owned), commit it to `extra_blocks`; the original `block` is
                    // committed by the caller's terminator loop, so leave it.
                    if let Some(finished) = tail.take() {
                        ctx.extra_blocks.push(finished);
                    }
                    tail = Some(Block::new(cont_id));
                } else {
                    let cur = tail.as_mut().unwrap_or(&mut *block);
                    emit_format_one_placeholder(
                        ctx,
                        body,
                        call,
                        cur,
                        slot_ptr,
                        cursor_slot,
                        arg,
                        kind,
                        str_lengths[arg_idx],
                        preloaded[arg_idx],
                    )?;
                }
                arg_idx += 1;
            }
        }
    }
    Ok(tail)
}

/// Reserve bytes for the current formatted cursor through the same amortized
/// growth helper as String::push_str. Preserve capacity and make no allocator
/// call when the bytes already fit; zero capacity allocates on first growth.
fn emit_string_reserve<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    block: &mut Block,
    slot_ptr: ValueId,
    cursor_slot: ValueId,
    extra: ValueId,
) -> Result<(), String> {
    let len = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    let needed = emit_i64_binop(ctx, block, TrustIrBinOp::Add, len, extra);
    let _ = emit_collection_grow_to(ctx, body, call, block, slot_ptr, needed, 1, 1, false)?;
    Ok(())
}

/// Reserve a formatted integer's bytes the way std's `Formatter::pad_integral`
/// writes them: a negative value's `'-'` is its own `write_char`, so its own
/// growth step, before the digits' `write_str`. `sign` (0 or 1, `None` for an
/// unsigned type) and `digits` come from `emit_itoa_extent{,_i128}`; the
/// cursor is not advanced.
#[allow(clippy::too_many_arguments)]
fn emit_integer_reserve<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    block: &mut Block,
    slot_ptr: ValueId,
    cursor_slot: ValueId,
    sign: Option<ValueId>,
    digits: ValueId,
) -> Result<(), String> {
    let total = match sign {
        Some(sign) => {
            emit_string_reserve(ctx, body, call, block, slot_ptr, cursor_slot, sign)?;
            emit_i64_binop(ctx, block, TrustIrBinOp::Add, sign, digits)
        }
        None => digits,
    };
    emit_string_reserve(ctx, body, call, block, slot_ptr, cursor_slot, total)
}

/// Write the constant `bytes` into the buffer at `data_ptr + cursor`, advancing
/// `cursor_slot` by `bytes.len()`. Inline (no loop) since the literal length is
/// a compile-time constant.
fn emit_write_const_bytes(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    data_ptr: ValueId,
    cursor_slot: ValueId,
    bytes: &[u8],
) {
    if bytes.is_empty() {
        return;
    }
    let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    let base = emit_element_addr(ctx, block, data_ptr, cursor, 1);
    for (i, &byte) in bytes.iter().enumerate() {
        let val = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Const {
                ty: TrustIrTy::I8,
                value: i8_image_byte_constant(byte),
            })
            .with_result(val),
        );
        let addr = if i == 0 {
            base
        } else {
            let off = emit_i64_const(ctx, block, i as i128);
            emit_element_addr(ctx, block, base, off, 1)
        };
        emit_typed_store(block, addr, TrustIrTy::I8, val);
    }
    let len_const = emit_i64_const(ctx, block, bytes.len() as i128);
    let new_cursor = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: TrustIrTy::I64,
            lhs: cursor,
            rhs: len_const,
        })
        .with_result(new_cursor),
    );
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, new_cursor);
}

/// Emit a `Const` of type `ty` and return its value.
/// A `SwitchInt` case, which MIR gives as the selector's bit pattern
/// zero-extended to `u128`, spelled as the literal trust-ir admits for the
/// selector type `ty`: a signed selector's case is its signed value
/// (`switch i8 [-1: ..]`, never `255`), any other its unsigned value. trust-ir
/// checks a switch case against its selector's range exactly as it checks an
/// `Inst::Const` of that type, and refuses the whole module otherwise.
fn switch_case_literal(ty: &TrustIrTy, bits: u128) -> Constant {
    // A Boolean selector's literal is Boolean too. Only its exact valid
    // images may change spelling; invalid bits remain invalid at the floor.
    if *ty == TrustIrTy::Bool {
        return match bits {
            0 => Constant::Bool(false),
            1 => Constant::Bool(true),
            _ => Constant::u128(bits),
        };
    }
    let width = ty.bit_width_with(64).unwrap_or(128);
    if ty.is_signed() && width < 128 {
        let shift = 128 - width;
        Constant::Int(((bits << shift) as i128) >> shift)
    } else if ty.is_signed() {
        Constant::Int(bits as i128)
    } else {
        Constant::u128(bits)
    }
}

#[cfg(test)]
mod switch_case_literal_tests {
    use super::{Constant, TrustIrTy, switch_case_literal};

    #[test]
    fn a_case_is_its_selectors_value() {
        let cells = [
            (TrustIrTy::Bool, 0, Constant::Bool(false)),
            (TrustIrTy::Bool, 1, Constant::Bool(true)),
            (TrustIrTy::I8, 0xFF, Constant::Int(-1)),
            (TrustIrTy::I8, 0x80, Constant::Int(-128)),
            (TrustIrTy::I8, 0x7F, Constant::Int(127)),
            (TrustIrTy::U8, 0xFF, Constant::Int(255)),
            (TrustIrTy::I16, 0xFFFE, Constant::Int(-2)),
            (TrustIrTy::I32, 1 << 31, Constant::Int(i128::from(i32::MIN))),
            (
                TrustIrTy::U32,
                u128::from(u32::MAX),
                Constant::Int(i128::from(u32::MAX)),
            ),
            (TrustIrTy::I64, 1 << 63, Constant::Int(i128::from(i64::MIN))),
            (TrustIrTy::Isize, u128::from(u64::MAX), Constant::Int(-1)),
            (
                TrustIrTy::U64,
                u128::from(u64::MAX),
                Constant::Int(i128::from(u64::MAX)),
            ),
            (TrustIrTy::Usize, 7, Constant::Int(7)),
            (TrustIrTy::Char, 0x10FFFF, Constant::Int(0x10FFFF)),
            (TrustIrTy::I128, u128::MAX, Constant::Int(-1)),
            (TrustIrTy::U128, u128::MAX, Constant::u128(u128::MAX)),
        ];
        for (ty, bits, want) in cells {
            assert_eq!(
                switch_case_literal(&ty, bits),
                want,
                "{ty:?} case {bits:#x}"
            );
        }
    }

    #[test]
    fn invalid_boolean_switch_images_never_coerce_to_true() {
        for bits in [2, 127, 255, u64::MAX as u128, u128::MAX] {
            let value = switch_case_literal(&TrustIrTy::Bool, bits);
            assert_eq!(value, Constant::u128(bits));
            assert!(!value.value_matches_ty(&TrustIrTy::Bool, 64));
        }
    }
}

fn emit_typed_const(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    ty: TrustIrTy,
    v: i128,
) -> ValueId {
    // `v` is a RAW 128-bit pattern, so for `U128` a value with the high bit set
    // arrives here as a negative i128. Spelling that `Constant::Int` violates
    // trust-ir's v24 one-spelling rule — `Ty::U128` admits `Constant::Int` only
    // over [0, i128::MAX] — and the adapter rejects the whole function closed
    // ("Constant::Int(-1) does not fit in U128"). Route U128 through trust-ir's
    // canonical constructor, which keeps small values as `Int` and switches to
    // `Constant::U128` above i128::MAX. Bool's exact 0/1 values have their own
    // canonical spelling; other Bool integers retain their invalid spelling so
    // the unchanged typed admission rejects them, never coercing them to true.
    let value = typed_integer_constant(&ty, v);
    let result = ctx.fresh_value();
    block
        .body
        .push(InstrNode::new(Inst::Const { ty, value }).with_result(result));
    result
}

fn typed_integer_constant(ty: &TrustIrTy, value: i128) -> Constant {
    match (ty, value) {
        (TrustIrTy::Bool, 0) => Constant::Bool(false),
        (TrustIrTy::Bool, 1) => Constant::Bool(true),
        (TrustIrTy::U128, _) => Constant::u128(value as u128),
        _ => Constant::Int(signed_pattern_spelling(ty, value)),
    }
}

/// Spell every signed integer constant (`I8`..`I64`) of `module` that a
/// producer wrote as its unsigned bit pattern as the type's signed value with
/// the same bits ([`signed_pattern_spelling`]), before trust-ir's typed codegen
/// admission sees it. Many producers build `Constant::Int` straight from a
/// layout's raw bits (a niche value, a mask, a tag), and the admission refuses
/// a signed type's constant outside that type's range ("const type mismatch:
/// expected i32, got int"): measured on main 4f5020306, a `SetDiscriminant` of a
/// niche-encoded enum at -O1..-O3 (`mir_families_aarch64`) and
/// `u64::reverse_bits`. The bits, and so the program, are unchanged; a value
/// outside both ranges is left for the admission to refuse.
fn canonicalize_signed_constant_spellings(module: &mut TrustIrModule) {
    for function in &mut module.functions {
        for block in &mut function.blocks {
            for node in &mut block.body {
                if let Inst::Const {
                    ty,
                    value: Constant::Int(value),
                } = &mut node.inst
                {
                    *value = signed_pattern_spelling(ty, *value);
                }
            }
        }
    }
}

/// A signed integer constant's value spelled from its bit pattern. A
/// caller can hold the pattern as its UNSIGNED value (`u64::MAX`, a
/// `0xAAAA_..` reverse-bits mask or `10^19` for an `I64`, `0xFF` for an
/// `I8`); trust-ir's typed admission takes a signed type's constant only in
/// that type's range, so those are the same bits as the type's signed value.
/// A value outside both the signed and the unsigned range of the width is
/// returned unchanged: the admission still refuses it, rather than this
/// truncating an integer the caller got wrong. Other types are unchanged.
fn signed_pattern_spelling(ty: &TrustIrTy, value: i128) -> i128 {
    let bits = match ty {
        TrustIrTy::I8 => 8,
        TrustIrTy::I16 => 16,
        TrustIrTy::I32 => 32,
        TrustIrTy::I64 => 64,
        _ => return value,
    };
    let signed_max = (1i128 << (bits - 1)) - 1;
    let unsigned_max = (1i128 << bits) - 1;
    if value > signed_max && value <= unsigned_max {
        value - (1i128 << bits)
    } else {
        value
    }
}

#[cfg(test)]
mod bool_constant_tests;

// Signed constants spelled from an unsigned bit pattern (`signed_pattern_spelling`).
#[cfg(test)]
mod signed_constant_spelling_tests;

/// Emit an `I64` binary op `lhs OP rhs`.
fn emit_i64_binop(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    op: TrustIrBinOp,
    lhs: ValueId,
    rhs: ValueId,
) -> ValueId {
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op,
            ty: TrustIrTy::I64,
            lhs,
            rhs,
        })
        .with_result(result),
    );
    result
}

/// Emit an `I64` `ICmp lhs OP rhs` (a `Bool` result).
fn emit_i64_icmp(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    op: ICmpOp,
    lhs: ValueId,
    rhs: ValueId,
) -> ValueId {
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op,
            ty: TrustIrTy::I64,
            lhs,
            rhs,
        })
        .with_result(result),
    );
    result
}

/// Emit an `I64` `Select(cond, a, b)`.
fn emit_i64_select(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    cond: ValueId,
    a: ValueId,
    b: ValueId,
) -> ValueId {
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::I64,
            cond,
            then_val: a,
            else_val: b,
        })
        .with_result(result),
    );
    result
}

/// Sign- or zero-extend an `ety`-wide integer `value` to `I64` (a no-op when
/// `ety` is already `I64`). `signed` selects `SExt` vs `ZExt`. The free-function
/// counterpart of the builder's `extend_to_i64`.
fn emit_extend_to_i64(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    ety: &TrustIrTy,
    signed: bool,
    value: ValueId,
) -> ValueId {
    if matches!(ety, TrustIrTy::I64 | TrustIrTy::U64) {
        return value;
    }
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: if signed { CastOp::SExt } else { CastOp::ZExt },
            src_ty: ety.clone(),
            dst_ty: TrustIrTy::I64,
            operand: value,
        })
        .with_result(result),
    );
    result
}

/// Truncate an `I64` `value` to the narrower integer type `ety` (a no-op when
/// `ety` is already 64-bit) — the inverse of `emit_extend_to_i64` for the low bits.
fn emit_trunc_from_i64(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    ety: &TrustIrTy,
    value: ValueId,
) -> ValueId {
    if matches!(ety, TrustIrTy::I64 | TrustIrTy::U64) {
        return value;
    }
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::Trunc,
            src_ty: TrustIrTy::I64,
            dst_ty: ety.clone(),
            operand: value,
        })
        .with_result(result),
    );
    result
}

/// Emit the logical AND of two `Bool` values (each an `ICmp` result).
fn emit_bool_and(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    lhs: ValueId,
    rhs: ValueId,
) -> ValueId {
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::And,
            ty: TrustIrTy::Bool,
            lhs,
            rhs,
        })
        .with_result(result),
    );
    result
}

/// Store the low byte of an `I64` `value` into the buffer at `addr` (truncating
/// to `I8`).
fn emit_store_low_byte(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    addr: ValueId,
    value: ValueId,
) {
    let byte = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::Trunc,
            src_ty: TrustIrTy::I64,
            dst_ty: TrustIrTy::I8,
            operand: value,
        })
        .with_result(byte),
    );
    emit_typed_store(block, addr, TrustIrTy::I8, byte);
}

/// Trace a format-arg `&value` reference operand back to the LOCAL whose value
/// is being formatted, following the fixed shape the `format!` desugar emits:
///
///     _v   = <the value>            (a bare local, e.g. a `black_box` result)
///     _r   = &_v                    (the reference)
///     _tup = (move _r, ...)         (the args tuple)
///     _a   = copy (_tup.0: &T)      (extract the reference)
///     Argument::new_display(copy _a)
///
/// Returns the pointee local `_v` (the value to read directly). This is more
/// robust than synthesizing a `Deref` place, because `_v` is a plain scalar local
/// the bridge already binds. Returns `None` for any other shape (caller fails
/// closed) — including a PROJECTED pointee such as `&((*_1).0)`, which only the
/// placeholder emitter accepts, through its own gate
/// (`fmt_placeholder_value_place`). Every other consumer (the `&str` static
/// length) keeps exactly this bare-local contract.
fn trace_fmt_ref_to_value_local<'tcx>(
    body: &Body<'tcx>,
    ref_operand: &Operand<'tcx>,
) -> Option<Local> {
    let place = trace_fmt_ref_to_value_place(body, ref_operand)?;
    place.projection.is_empty().then_some(place.local)
}

/// `trace_fmt_ref_to_value_local`'s walk, returning the borrowed PLACE instead of
/// only a bare local: `_r = &_v` yields `_v`, and `_r = &((*_1).0)` — what
/// `format!("... {}", self.0)` in a `&self` method lowers to, e.g. gimli's
/// `DwTag`/`DwAt`/`DwForm`/... `Display` impls in `library/std`'s dependency
/// graph — yields `(*_1).0`. The walk (and its per-peel uniqueness gate) is
/// unchanged; a projected pointee is merely RETURNED where the local tracer
/// refused it. Whether that place may be read at the formatting call is decided
/// by `fmt_placeholder_value_place`, never here.
fn trace_fmt_ref_to_value_place<'tcx>(
    body: &Body<'tcx>,
    ref_operand: &Operand<'tcx>,
) -> Option<Place<'tcx>> {
    // The arg operand reads a local holding the `&T` reference.
    let mut ref_local = operand_as_local(ref_operand)?;
    // Follow `Use`/tuple-field/`Ref` rvalues until we hit `&pointee`.
    for _ in 0..8 {
        // Peeling reads `ref_local`'s first-scanned definition as its value —
        // only sound when that def is unique (the peeled locals are per-call-site
        // macro temporaries, which are; this gate keeps a multi-def local from
        // being traced through the wrong arm's definition). The final VALUE
        // local is returned without this requirement: its consumers either read
        // it at runtime (flow-correct) or re-establish compile-time knowledge
        // under their own uniqueness gate (`str_arg_static_len`).
        if !local_has_unique_direct_def(body, ref_local) {
            return None;
        }
        let rvalue = find_local_assign(body, ref_local)?;
        match rvalue {
            // `_a = copy/move place` — a plain use or a tuple-field extract.
            Rvalue::Use(op, _) => {
                match op {
                    Operand::Copy(place) | Operand::Move(place) => {
                        if place.projection.is_empty() {
                            ref_local = place.local;
                        } else if let [ProjectionElem::Field(field, _)] = place.projection.as_ref()
                        {
                            // `copy (_tup.field)`: resolve the tuple's aggregate
                            // (unique-def-gated like every other peel).
                            if !local_has_unique_direct_def(body, place.local) {
                                return None;
                            }
                            let tup_rvalue = find_local_assign(body, place.local)?;
                            let Rvalue::Aggregate(_, operands) = tup_rvalue else {
                                return None;
                            };
                            let elem = operands.get(*field)?;
                            ref_local = operand_as_local(elem)?;
                        } else {
                            return None;
                        }
                    }
                    _ => return None,
                }
            }
            // `_r = &pointee` — the reference itself. The pointee is the value.
            Rvalue::Ref(_, _, place) | Rvalue::RawPtr(_, place) => {
                if place.projection.is_empty() {
                    return Some(*place);
                }
                // `&raw const (*_inner)` / `&(*_inner)` (a Deref) is just a
                // re-borrow of `_inner` (a reference) — continue tracing `_inner`
                // as the reference. (The O3 inlined `value` field arrives as
                // `&raw const (*_4)` where `_4: &T`.)
                if let [ProjectionElem::Deref] = place.projection.as_ref() {
                    ref_local = place.local;
                    continue;
                }
                // Any other projection (`&((*_1).0)`): the borrowed place itself.
                // Returned, NOT accepted — the local tracer maps it to `None`,
                // and the placeholder emitter gates it
                // (`fmt_placeholder_value_place`).
                return Some(*place);
            }
            // A `Transmute`/`Cast` of a reference value preserves the address;
            // peel through to the underlying reference local. (The O3 `value`
            // field casts `&x` to `NonNull` then `*const`.)
            Rvalue::Cast(_, op, _) => {
                ref_local = operand_as_local(op)?;
            }
            _ => return None,
        }
    }
    None
}

/// The place a placeholder's value is READ from at the formatting call, or an
/// `Err` naming why its reference cannot be read there. [TCG-FMT-ARGPLACE]
///
/// A bare pointee local (`_r = &_v`) is accepted exactly as before. A PROJECTED
/// pointee is accepted only in the one shape whose ADDRESS is provably the same
/// at the call as at the borrow: `(*_b).f0.f1...` — exactly one leading `Deref`
/// of a `&T`/`&mut T`/`*const T`/`*mut T` local `_b`, then one or more `Field`s.
///
/// Why reading at the call is right: `core::fmt` itself reads `*value` when it
/// reaches the placeholder inside `format`/`write_fmt` (the `Argument` holds the
/// pointer, not a copy), so the call-time VALUE is the value real Rust prints.
/// What must not change between borrow and call is the ADDRESS, which for
/// `(*_b).f...` is `_b` plus constant field offsets:
///
/// * `_b` must have a unique direct definition (`local_has_unique_direct_def`:
///   an argument counts as its one def; a second def, a projected write, a
///   `SetDiscriminant`, or a mutable/raw borrow of `_b`'s own storage refuse).
///   Load-bearing: NLL lets a REFERENCE local be overwritten while a reborrow of
///   its pointee is live (`format!("{} {}", (*p).x, { p = q; 0 })` compiles),
///   and re-reading `(*p).x` at the call would print `q.x`.
/// * No second `Deref`, `Index`, `ConstantIndex`, `Subslice`, `Downcast`, or
///   cast/binder projection: each adds an address input this gate does not
///   track (a pointer stored in memory, an index local, a variant).
/// * The place's type must equal the decoded `value_ty` (at `-O3` the type comes
///   from the reified `Display::fmt` and the reference from a separate cast
///   peel; disagreement means the peel reached some other place).
/// * `&str` placeholders keep the bare-local requirement: their byte count
///   comes from `str_arg_static_len`, which reads a LOCAL's definition.
///
/// `emit_format_into_slot` loads an accepted projected value BEFORE its
/// up-front reserve can reallocate (see there).
fn fmt_placeholder_value_place<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    arg: &FmtArg<'tcx>,
    kind: &FmtKind,
) -> Result<Place<'tcx>, String> {
    let place = trace_fmt_ref_to_value_place(body, &arg.ref_operand).ok_or_else(|| {
        "[TCG-FMT-ARGPLACE] format! arg reference does not trace to a value local \
         or place: the `&value` operand is not a unique-def chain of copies, \
         tuple-field extracts, casts and reborrows ending in `&place`. Options: \
         bind the argument to a `let` first (`let v = expr; format!(\"{}\", v)`), \
         or extend `trace_fmt_ref_to_value_place` with the new peel and a \
         uniqueness argument for it"
            .to_owned()
    })?;
    if place.projection.is_empty() {
        return Ok(place);
    }
    let refuse = |why: &str| {
        format!(
            "[TCG-FMT-ARGPLACE] format! arg borrows the projected place {place:?}, \
             which is read at the formatting call and so must have a call-stable \
             address: {why}. Options: bind the value to a `let` first \
             (`let v = {place:?}; format!(\"{{}}\", v)` is a bare local), or widen \
             `fmt_placeholder_value_place` with an argument that the address \
             cannot change between the borrow and the call"
        )
    };
    if matches!(kind, FmtKind::Str) {
        return Err(refuse(
            "a `&str` placeholder needs a bare local (its length is read from \
             the local's definition by `str_arg_static_len`)",
        ));
    }
    let [ProjectionElem::Deref, fields @ ..] = place.projection.as_ref() else {
        return Err(refuse(
            "only `(*base).field...` (one leading Deref) is modeled",
        ));
    };
    if fields.is_empty()
        || !fields
            .iter()
            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
    {
        return Err(refuse(
            "after the leading Deref only struct/tuple `Field` projections are modeled \
             (an Index/Subslice/Downcast/second Deref adds an untracked address input)",
        ));
    }
    let base_ty = ctx.monomorphize_ty(body.local_decls[place.local].ty);
    if !matches!(base_ty.kind(), ty::Ref(..) | ty::RawPtr(..)) {
        return Err(refuse(
            "the dereferenced base is not a reference or raw pointer",
        ));
    }
    if !local_has_unique_direct_def(body, place.local) {
        return Err(refuse(
            "the dereferenced base pointer has more than one definition (or a \
             projected write / mutable or raw borrow of its storage), so it may be \
             re-pointed between the borrow and the call",
        ));
    }
    let place_ty = ctx.monomorphize_ty(place.ty(body, ctx.tcx).ty);
    if place_ty != arg.value_ty {
        return Err(refuse(&format!(
            "the place's type {place_ty:?} is not the placeholder's Display type {:?}",
            arg.value_ty
        )));
    }
    Ok(place)
}

/// Format one placeholder `arg` of category `kind` into the String at
/// `slot_ptr`, advancing `cursor_slot`. The value's byte count is computed
/// first and reserved the way std's `Display` writes it (a negative integer's
/// `'-'`, then its digits; every other kind in one write), so the String grows
/// exactly as std's would; the bytes are then stored strictly inside what was
/// reserved. `preloaded` is the value `emit_format_into_slot` already read for
/// a projected placeholder (before any reserve); `None` reads the value here.
#[allow(clippy::too_many_arguments)]
fn emit_format_one_placeholder<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    block: &mut Block,
    slot_ptr: ValueId,
    cursor_slot: ValueId,
    arg: &FmtArg<'tcx>,
    kind: &FmtKind,
    str_len: Option<u64>,
    preloaded: Option<ValueId>,
) -> Result<(), String> {
    let value_place = fmt_placeholder_value_place(ctx, body, arg, kind)?;
    // For `Str` the gate guarantees a bare local (the side-table lookup below
    // is keyed by it); for a projected scalar it is only the base pointer.
    let value_local = value_place.local;
    let value_operand = Operand::Copy(value_place);
    match kind {
        FmtKind::SignedInt(int_ty) | FmtKind::UnsignedInt(int_ty) => {
            let signed = matches!(kind, FmtKind::SignedInt(_));
            let narrow = match preloaded {
                Some(value) => value,
                None => lower_operand_to_value(ctx, body, block, &value_operand)?,
            };
            // Widen the value to an I64 magnitude carrier for the digit loop.
            let bits = int_ty.bit_width().unwrap_or(64);
            // 128-bit placeholders use the full 128-bit digit loop
            // (`emit_itoa_i128`); coercing to I64 would truncate. The value is
            // already 128-bit-wide (`classify_fmt_value` mapped it to I128/U128),
            // so pass it through unchanged.
            if bits == 128 {
                let (sign, digits) = emit_itoa_extent_i128(ctx, block, narrow, signed);
                emit_integer_reserve(ctx, body, call, block, slot_ptr, cursor_slot, sign, digits)?;
                let data_ptr = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
                emit_itoa_i128(ctx, block, data_ptr, cursor_slot, narrow, signed);
                return Ok(());
            }
            // DEFENSE-IN-DEPTH: no non-128 placeholder should ever be > 64 bits;
            // fail closed rather than let `coerce_to_i64` silently truncate.
            if bits > 64 {
                return Err(format!(
                    "[TCG-FMT-INT128] format! integer placeholder is {bits} bits wide; \
                     the itoa magnitude carrier is 64-bit and would truncate — failing \
                     closed rather than printing a wrong value"
                ));
            }
            let value = if bits >= 64 {
                coerce_to_i64(ctx, block, narrow)
            } else {
                let op = if signed { CastOp::SExt } else { CastOp::ZExt };
                let w = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op,
                        src_ty: int_ty.clone(),
                        dst_ty: TrustIrTy::I64,
                        operand: narrow,
                    })
                    .with_result(w),
                );
                w
            };
            let (sign, digits) = emit_itoa_extent(ctx, block, value, signed);
            emit_integer_reserve(ctx, body, call, block, slot_ptr, cursor_slot, sign, digits)?;
            let data_ptr = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
            emit_itoa(ctx, block, data_ptr, cursor_slot, value, signed);
        }
        FmtKind::Bool => {
            let b = match preloaded {
                Some(value) => value,
                None => lower_operand_to_value(ctx, body, block, &value_operand)?,
            };
            let len = emit_bool_display_len(ctx, block, b);
            emit_string_reserve(ctx, body, call, block, slot_ptr, cursor_slot, len)?;
            let data_ptr = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
            emit_format_bool(ctx, block, data_ptr, cursor_slot, b);
        }
        FmtKind::Char => {
            let c = match preloaded {
                Some(value) => value,
                None => lower_operand_to_value(ctx, body, block, &value_operand)?,
            };
            let len = emit_char_utf8_len(ctx, block, c);
            emit_string_reserve(ctx, body, call, block, slot_ptr, cursor_slot, len)?;
            let data_ptr = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
            emit_format_char(ctx, block, data_ptr, cursor_slot, c);
        }
        FmtKind::Str => {
            let len = str_len.ok_or_else(|| "format! &str arg missing length".to_owned())?;
            // The `&str` value's trust-ir representation is its DATA pointer. A
            // const-slice binding (`lower_const_slice_use`: `let name = "trust";
            // format!("hi, {}", name)`) carries that data pointer in
            // `scalar_values` with the length in the `pointer_metadata_lengths`
            // side table; the place kernel deliberately REJECTS reading such a
            // metadata-bound local as a plain scalar (the scalar half alone
            // would lose the length), so resolve the data half directly — the
            // same sanctioned lane `resolve_slice_source_data_len` uses. Sound
            // here because the value is used strictly as the byte-copy SOURCE
            // ADDRESS while the byte count is the SAME binding's side-table
            // length (`str_arg_static_len` read it under its uniqueness gate);
            // the map is flow-sensitive (joins drop disagreeing entries), so a
            // branch-varying data pointer never reaches this lookup.
            let v = if let Some(&data) = ctx.scalar_values.get(&value_local) {
                data
            } else {
                lower_operand_to_value(ctx, body, block, &value_operand)?
            };
            let str_ptr = coerce_to_plain_ptr(ctx, block, v);
            let extra = emit_i64_const(ctx, block, i128::from(len));
            emit_string_reserve(ctx, body, call, block, slot_ptr, cursor_slot, extra)?;
            let data_ptr = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
            emit_format_str(ctx, block, data_ptr, cursor_slot, str_ptr, len);
        }
    }
    Ok(())
}

/// The maximum decimal-digit width (excluding sign) of a 64-bit magnitude. We
/// unroll the itoa digit extraction to this fixed count so the whole conversion
/// is BRANCHLESS (no new basic blocks). 20 digits covers `u64::MAX`
/// (18446744073709551615) and every value the I64-carried magnitude can hold.
const ITOA_MAX_DIGITS: u32 = 20;

/// The byte counts of the two writes std's integer `Display` makes for the
/// `I64`-carried `value` (as [`emit_itoa`] takes it): `Some(sign)` (an `I64` 0
/// or 1) for a signed type, `None` for an unsigned one, and the magnitude's
/// significant-digit count (1 for zero), exactly the bytes `emit_itoa` stores.
/// Branchless: `digits = 1 + #{k in 1..20 : magnitude >= 10^k}`, the magnitude
/// and each `10^k` word (`itoa_divisor_word`) compared unsigned, so `i64::MIN`
/// counts its 19 digits.
fn emit_itoa_extent(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    value: ValueId,
    signed: bool,
) -> (Option<ValueId>, ValueId) {
    let zero = emit_i64_const(ctx, block, 0);
    let one = emit_i64_const(ctx, block, 1);
    let (sign, mag) = if signed {
        let is_neg = emit_i64_icmp(ctx, block, ICmpOp::Slt, value, zero);
        let neg = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, zero, value);
        let mag = emit_i64_select(ctx, block, is_neg, neg, value);
        (Some(emit_i64_select(ctx, block, is_neg, one, zero)), mag)
    } else {
        (None, value)
    };
    let mut digits = one;
    for k in 1..ITOA_MAX_DIGITS {
        let Some(word) = itoa_divisor_word(k) else {
            continue;
        };
        let pow = emit_i64_const(ctx, block, word);
        let reaches = emit_i64_icmp(ctx, block, ICmpOp::Uge, mag, pow);
        let inc = emit_i64_select(ctx, block, reaches, one, zero);
        digits = emit_i64_binop(ctx, block, TrustIrBinOp::Add, digits, inc);
    }
    (sign, digits)
}

/// itoa: write the decimal representation of the `I64`-carried `value` into the
/// buffer at `data_ptr + cursor`, advancing `cursor_slot`. Branchless and
/// single-block — the digit loop is unrolled to `ITOA_MAX_DIGITS`.
///
/// Algorithm (MSB-first, leading-zero suppression):
///   * sign: if `signed && value < 0`, write `'-'` at the cursor and advance the
///     cursor by 1 (branchless: always store `'-'`, advance by `is_neg ? 1 : 0`;
///     for a non-negative value the `'-'` byte is at the un-advanced cursor and
///     is overwritten by the first digit). magnitude = `is_neg ? 0 - value :
///     value`, read as UNSIGNED by the `UDiv`/`URem` below — so `i64::MIN`
///     (`0 - MIN == MIN` in two's complement) yields the correct unsigned
///     magnitude `9223372036854775808`.
///   * for k = MAX_DIGITS-1 .. 0: `d = (mag / 10^k) % 10`; the digit becomes
///     "active" once a nonzero digit has been seen (or at k==0, so `0` prints as
///     "0"). We ALWAYS store `'0'+d` at `cursor + out_idx`, but advance `out_idx`
///     only for active digits — so leading zeros write to `cursor+out_idx` and
///     are overwritten by the first active digit (out_idx unchanged). `out_idx`
///     ends equal to the significant-digit count.
///   * advance the cursor by `out_idx`.
/// Every store lands in `[cursor, cursor + sign + digits)` ([`emit_itoa_extent`]):
/// the always-stored `'-'` is at the sign byte, or for a non-negative value at
/// the first digit's position, and a leading zero is stored at the first
/// digit's position. The caller reserves exactly those bytes first.
fn emit_itoa(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    data_ptr: ValueId,
    cursor_slot: ValueId,
    value: ValueId,
    signed: bool,
) {
    let zero = emit_i64_const(ctx, block, 0);
    let is_neg = if signed {
        emit_i64_icmp(ctx, block, ICmpOp::Slt, value, zero)
    } else {
        // A constant false (`0 != 0`).
        emit_i64_icmp(ctx, block, ICmpOp::Ne, zero, zero)
    };
    if signed {
        // Always store '-' at the current cursor; advance by is_neg ? 1 : 0.
        let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
        let minus_addr = emit_element_addr(ctx, block, data_ptr, cursor, 1);
        let minus = emit_typed_const(ctx, block, TrustIrTy::I8, i128::from(b'-'));
        emit_typed_store(block, minus_addr, TrustIrTy::I8, minus);
        let one = emit_i64_const(ctx, block, 1);
        let inc = emit_i64_select(ctx, block, is_neg, one, zero);
        let advanced = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, inc);
        emit_typed_store(block, cursor_slot, TrustIrTy::I64, advanced);
    }
    // magnitude = is_neg ? 0 - value : value (unsigned bit pattern).
    let mag = if signed {
        let neg = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, zero, value);
        emit_i64_select(ctx, block, is_neg, neg, value)
    } else {
        value
    };

    let ten = emit_i64_const(ctx, block, 10);
    let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    // out_idx: running count of significant digits written so far.
    let mut out_idx = emit_i64_const(ctx, block, 0);
    // started: whether a nonzero digit has been seen (an I64 0/1 flag).
    let mut started = emit_i64_const(ctx, block, 0);
    // Precompute the powers of ten as constants and divide the magnitude.
    for k in (0..ITOA_MAX_DIGITS).rev() {
        // pow = 10^k (fits in u64 for k <= 19; k==20's 10^20 overflows but the
        // top digit position for a 20-digit number is k==19, so we cap at 19).
        let Some(pow) = itoa_divisor_word(k) else {
            continue;
        };
        let pow_c = emit_i64_const(ctx, block, pow);
        // d = (mag / pow) % 10
        let q = emit_i64_binop(ctx, block, TrustIrBinOp::UDiv, mag, pow_c);
        let d = emit_i64_binop(ctx, block, TrustIrBinOp::URem, q, ten);
        // nonzero = d != 0
        let nonzero = emit_i64_icmp(ctx, block, ICmpOp::Ne, d, zero);
        let nonzero64 = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::ZExt,
                src_ty: TrustIrTy::Bool,
                dst_ty: TrustIrTy::I64,
                operand: nonzero,
            })
            .with_result(nonzero64),
        );
        // started' = started | nonzero | (k == 0)
        let started_or = emit_i64_binop(ctx, block, TrustIrBinOp::Or, started, nonzero64);
        let active = if k == 0 {
            // Force the last digit active so `0` prints "0".
            emit_i64_const(ctx, block, 1)
        } else {
            started_or
        };
        // store '0' + d at cursor + out_idx (always).
        let digit_ch = {
            let z = emit_i64_const(ctx, block, i128::from(b'0'));
            emit_i64_binop(ctx, block, TrustIrBinOp::Add, d, z)
        };
        let pos = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, out_idx);
        let addr = emit_element_addr(ctx, block, data_ptr, pos, 1);
        emit_store_low_byte(ctx, block, addr, digit_ch);
        // out_idx += active ? 1 : 0
        let active_bool = emit_i64_icmp(ctx, block, ICmpOp::Ne, active, zero);
        let one = emit_i64_const(ctx, block, 1);
        let inc = emit_i64_select(ctx, block, active_bool, one, zero);
        out_idx = emit_i64_binop(ctx, block, TrustIrBinOp::Add, out_idx, inc);
        started = active;
    }
    // advance cursor by out_idx.
    let new_cursor = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, out_idx);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, new_cursor);
}

/// Decimal magnitudes use UDiv/URem on the exact 64-bit word carrier.
/// 10^19 is an unsigned word, not an in-range positive I64 literal. Retain
/// its bits in the canonical signed spelling; never truncate an arbitrary
/// mathematical integer or infer its width from the host.
fn itoa_divisor_word(exponent: u32) -> Option<i128> {
    if exponent >= 20 {
        return None;
    }
    let word = 10_u64.checked_pow(exponent)?;
    Some(i128::from(i64::from_ne_bytes(word.to_ne_bytes())))
}

/// The maximum decimal-digit width (excluding sign) of a 128-bit magnitude:
/// `u128::MAX` (340282366920938463463374607431768211455) is 39 digits, and
/// `10^38 < i128::MAX` so every power-of-ten divisor is a representable positive
/// i128 constant.
const ITOA_MAX_DIGITS_128: u32 = 39;

/// [`emit_itoa_extent`] for a 128-bit `value` (an `I128` or `U128`, as
/// [`emit_itoa_i128`] takes it): `Some(sign)` for a signed type, and the
/// magnitude's significant-digit count, `1 + #{k in 1..39 : magnitude >= 10^k}`
/// with the magnitude compared unsigned.
fn emit_itoa_extent_i128(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    value: ValueId,
    signed: bool,
) -> (Option<ValueId>, ValueId) {
    let carrier = if signed {
        TrustIrTy::I128
    } else {
        TrustIrTy::U128
    };
    let zero = emit_i64_const(ctx, block, 0);
    let one = emit_i64_const(ctx, block, 1);
    let icmp = |ctx: &mut MirLoweringCtx<'_>,
                block: &mut Block,
                op: ICmpOp,
                lhs: ValueId,
                rhs: ValueId| {
        let result = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::ICmp {
                op,
                ty: carrier.clone(),
                lhs,
                rhs,
            })
            .with_result(result),
        );
        result
    };
    let (sign, mag) = if signed {
        let zero_c = emit_typed_const(ctx, block, carrier.clone(), 0);
        let is_neg = icmp(ctx, block, ICmpOp::Slt, value, zero_c);
        let neg = emit_i128_binop(
            ctx,
            block,
            TrustIrBinOp::Sub,
            carrier.clone(),
            zero_c,
            value,
        );
        let mag = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: carrier.clone(),
                cond: is_neg,
                then_val: neg,
                else_val: value,
            })
            .with_result(mag),
        );
        (Some(emit_i64_select(ctx, block, is_neg, one, zero)), mag)
    } else {
        (None, value)
    };
    let mut digits = one;
    for k in 1..ITOA_MAX_DIGITS_128 {
        let pow = emit_typed_const(ctx, block, carrier.clone(), 10i128.pow(k));
        let reaches = icmp(ctx, block, ICmpOp::Uge, mag, pow);
        let inc = emit_i64_select(ctx, block, reaches, one, zero);
        digits = emit_i64_binop(ctx, block, TrustIrBinOp::Add, digits, inc);
    }
    (sign, digits)
}

/// itoa for a 128-bit magnitude — the i128/u128 sibling of [`emit_itoa`].
///
/// Identical branchless, single-block, MSB-first, leading-zero-suppressing
/// scheme, but the magnitude, sign, powers of ten, and the `mag / 10^k` / `% 10`
/// divisions are all 128-bit (the digit `d` — always 0..9 — is truncated back to
/// `I64` so the cursor / out-idx / started / store arithmetic is shared verbatim
/// with the 64-bit path). `UDiv`/`URem` read the magnitude as UNSIGNED, so a
/// negative i128 sign bit is irrelevant to digit extraction (as for i64), and
/// `0 - i128::MIN == i128::MIN` gives the correct unsigned magnitude `2^127`.
fn emit_itoa_i128(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    data_ptr: ValueId,
    cursor_slot: ValueId,
    value: ValueId,
    signed: bool,
) {
    // The magnitude carrier matches the incoming value's own type tag (the
    // adapter requires exact-type operands): a signed i128 arrives as `I128`, an
    // unsigned u128 as `U128`. `UDiv`/`URem` below are UNSIGNED ops regardless of
    // the tag, so digit extraction is identical for both.
    let carrier = if signed {
        TrustIrTy::I128
    } else {
        TrustIrTy::U128
    };
    let zero_i64 = emit_i64_const(ctx, block, 0);
    let zero_i128 = emit_typed_const(ctx, block, carrier.clone(), 0);
    // is_neg (an I64 0/1): for unsigned there is no sign, so it is constant 0.
    let is_neg = if signed {
        let cmp = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::ICmp {
                op: ICmpOp::Slt,
                ty: carrier.clone(),
                lhs: value,
                rhs: zero_i128,
            })
            .with_result(cmp),
        );
        let widened = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::ZExt,
                src_ty: TrustIrTy::Bool,
                dst_ty: TrustIrTy::I64,
                operand: cmp,
            })
            .with_result(widened),
        );
        widened
    } else {
        emit_i64_const(ctx, block, 0)
    };
    if signed {
        // Always store '-' at the current cursor; advance by is_neg ? 1 : 0.
        let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
        let minus_addr = emit_element_addr(ctx, block, data_ptr, cursor, 1);
        let minus = emit_typed_const(ctx, block, TrustIrTy::I8, i128::from(b'-'));
        emit_typed_store(block, minus_addr, TrustIrTy::I8, minus);
        let one = emit_i64_const(ctx, block, 1);
        let is_neg_bool = emit_i64_icmp(ctx, block, ICmpOp::Ne, is_neg, zero_i64);
        let inc = emit_i64_select(ctx, block, is_neg_bool, one, zero_i64);
        let advanced = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, inc);
        emit_typed_store(block, cursor_slot, TrustIrTy::I64, advanced);
    }
    // magnitude = is_neg ? (0 - value) : value (128-bit, in the carrier type).
    let mag = if signed {
        let neg = emit_i128_binop(
            ctx,
            block,
            TrustIrBinOp::Sub,
            carrier.clone(),
            zero_i128,
            value,
        );
        let is_neg_bool = emit_i64_icmp(ctx, block, ICmpOp::Ne, is_neg, zero_i64);
        let sel = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: carrier.clone(),
                cond: is_neg_bool,
                then_val: neg,
                else_val: value,
            })
            .with_result(sel),
        );
        sel
    } else {
        value
    };

    let ten_i128 = emit_typed_const(ctx, block, carrier.clone(), 10);
    let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    let mut out_idx = emit_i64_const(ctx, block, 0);
    let mut started = emit_i64_const(ctx, block, 0);
    for k in (0..ITOA_MAX_DIGITS_128).rev() {
        // 10^k for k in 0..=38 is <= 10^38 < i128::MAX (a positive i128 const).
        let pow = 10u128.checked_pow(k).expect("10^k, k<=38, fits in u128");
        let pow_c = emit_typed_const(ctx, block, carrier.clone(), pow as i128);
        // d128 = (mag / 10^k) % 10, both UNSIGNED 128-bit; d in 0..9.
        let q = emit_i128_binop(ctx, block, TrustIrBinOp::UDiv, carrier.clone(), mag, pow_c);
        let d128 = emit_i128_binop(ctx, block, TrustIrBinOp::URem, carrier.clone(), q, ten_i128);
        // Truncate the 0..9 digit to I64 for the shared store arithmetic.
        let d = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::Trunc,
                src_ty: carrier.clone(),
                dst_ty: TrustIrTy::I64,
                operand: d128,
            })
            .with_result(d),
        );
        let nonzero = emit_i64_icmp(ctx, block, ICmpOp::Ne, d, zero_i64);
        let nonzero64 = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::ZExt,
                src_ty: TrustIrTy::Bool,
                dst_ty: TrustIrTy::I64,
                operand: nonzero,
            })
            .with_result(nonzero64),
        );
        let started_or = emit_i64_binop(ctx, block, TrustIrBinOp::Or, started, nonzero64);
        let active = if k == 0 {
            emit_i64_const(ctx, block, 1)
        } else {
            started_or
        };
        let digit_ch = {
            let z = emit_i64_const(ctx, block, i128::from(b'0'));
            emit_i64_binop(ctx, block, TrustIrBinOp::Add, d, z)
        };
        let pos = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, out_idx);
        let addr = emit_element_addr(ctx, block, data_ptr, pos, 1);
        emit_store_low_byte(ctx, block, addr, digit_ch);
        let active_bool = emit_i64_icmp(ctx, block, ICmpOp::Ne, active, zero_i64);
        let one = emit_i64_const(ctx, block, 1);
        let inc = emit_i64_select(ctx, block, active_bool, one, zero_i64);
        out_idx = emit_i64_binop(ctx, block, TrustIrBinOp::Add, out_idx, inc);
        started = active;
    }
    let new_cursor = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, out_idx);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, new_cursor);
}

/// The byte count of a `bool`'s `Display` (`"true"` 4, `"false"` 5), an `I64`.
fn emit_bool_display_len(ctx: &mut MirLoweringCtx<'_>, block: &mut Block, b: ValueId) -> ValueId {
    let b64 = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::ZExt,
            src_ty: TrustIrTy::Bool,
            dst_ty: TrustIrTy::I64,
            operand: b,
        })
        .with_result(b64),
    );
    let one = emit_i64_const(ctx, block, 1);
    let is_true = emit_i64_icmp(ctx, block, ICmpOp::Eq, b64, one);
    let four = emit_i64_const(ctx, block, 4);
    let five = emit_i64_const(ctx, block, 5);
    emit_i64_select(ctx, block, is_true, four, five)
}

/// Format a `bool` (`true`/`false`) into the buffer at `data_ptr + cursor`,
/// advancing `cursor_slot`. Branchless: the four positions both words have
/// select their `true`/`false` byte, and the final `'e'` (`"true"[3]`,
/// `"false"[4]`) is stored at `cursor + len - 1`, so exactly `len` bytes (4 or
/// 5) are written; the cursor advances by `len`.
fn emit_format_bool(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    data_ptr: ValueId,
    cursor_slot: ValueId,
    b: ValueId,
) {
    // Normalize the Bool value to an I64 0/1.
    let b64 = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::ZExt,
            src_ty: TrustIrTy::Bool,
            dst_ty: TrustIrTy::I64,
            operand: b,
        })
        .with_result(b64),
    );
    let one = emit_i64_const(ctx, block, 1);
    let is_true = emit_i64_icmp(ctx, block, ICmpOp::Eq, b64, one);
    let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    let base = emit_element_addr(ctx, block, data_ptr, cursor, 1);
    // "true" vs "false": position-wise character select.
    let pairs: [(u8, u8); 4] = [(b't', b'f'), (b'r', b'a'), (b'u', b'l'), (b'e', b's')];
    for (i, (t, f)) in pairs.iter().enumerate() {
        let tc = emit_i64_const(ctx, block, i128::from(*t));
        let fc = emit_i64_const(ctx, block, i128::from(*f));
        let ch = emit_i64_select(ctx, block, is_true, tc, fc);
        let addr = if i == 0 {
            base
        } else {
            let off = emit_i64_const(ctx, block, i as i128);
            emit_element_addr(ctx, block, base, off, 1)
        };
        emit_store_low_byte(ctx, block, addr, ch);
    }
    // len = is_true ? 4 : 5; the final 'e' at `base + len - 1`.
    let four = emit_i64_const(ctx, block, 4);
    let five = emit_i64_const(ctx, block, 5);
    let len = emit_i64_select(ctx, block, is_true, four, five);
    let last = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, one);
    let last_addr = emit_element_addr(ctx, block, base, last, 1);
    let e = emit_i64_const(ctx, block, i128::from(b'e'));
    emit_store_low_byte(ctx, block, last_addr, e);
    let new_cursor = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, len);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, new_cursor);
}

/// A `char`'s UTF-8 byte count (1..=4, an `I64`), as `char::len_utf8`.
fn emit_char_utf8_len(ctx: &mut MirLoweringCtx<'_>, block: &mut Block, c: ValueId) -> ValueId {
    let c64 = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::ZExt,
            src_ty: TrustIrTy::U32,
            dst_ty: TrustIrTy::I64,
            operand: c,
        })
        .with_result(c64),
    );
    let below = |ctx: &mut MirLoweringCtx<'_>, block: &mut Block, k: i128| {
        let k = emit_i64_const(ctx, block, k);
        emit_i64_icmp(ctx, block, ICmpOp::Ult, c64, k)
    };
    let lt80 = below(ctx, block, 0x80);
    let lt800 = below(ctx, block, 0x800);
    let lt10000 = below(ctx, block, 0x10000);
    let one = emit_i64_const(ctx, block, 1);
    let two = emit_i64_const(ctx, block, 2);
    let three = emit_i64_const(ctx, block, 3);
    let four = emit_i64_const(ctx, block, 4);
    let len_34 = emit_i64_select(ctx, block, lt10000, three, four);
    let len_234 = emit_i64_select(ctx, block, lt800, two, len_34);
    emit_i64_select(ctx, block, lt80, one, len_234)
}

/// Format a `char` (1..=4 UTF-8 bytes) into the buffer at `data_ptr + cursor`,
/// advancing `cursor_slot`. Branchless: compute the 4 candidate output bytes via
/// `Select`s on the encoded length; byte `i` is stored at `cursor + i` while
/// `i < len` and otherwise the last byte is stored again at `cursor + len - 1`,
/// so exactly the `len` bytes the caller reserved are written. The cursor
/// advances by the UTF-8 length.
fn emit_format_char(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    data_ptr: ValueId,
    cursor_slot: ValueId,
    c: ValueId,
) {
    // The char is a U32 scalar; widen to I64 for the bit math.
    let c64 = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::ZExt,
            src_ty: TrustIrTy::U32,
            dst_ty: TrustIrTy::I64,
            operand: c,
        })
        .with_result(c64),
    );
    let lt80 = {
        let k = emit_i64_const(ctx, block, 0x80);
        emit_i64_icmp(ctx, block, ICmpOp::Ult, c64, k)
    };
    let lt800 = {
        let k = emit_i64_const(ctx, block, 0x800);
        emit_i64_icmp(ctx, block, ICmpOp::Ult, c64, k)
    };
    let lt10000 = {
        let k = emit_i64_const(ctx, block, 0x10000);
        emit_i64_icmp(ctx, block, ICmpOp::Ult, c64, k)
    };
    // Helper closures via inline expressions.
    let mask3f = emit_i64_const(ctx, block, 0x3F);
    let cont = |ctx: &mut MirLoweringCtx<'_>, block: &mut Block, shift: i128| -> ValueId {
        let s = emit_i64_const(ctx, block, shift);
        let shifted = emit_i64_binop(ctx, block, TrustIrBinOp::LShr, c64, s);
        let masked = emit_i64_binop(ctx, block, TrustIrBinOp::And, shifted, mask3f);
        let c80 = emit_i64_const(ctx, block, 0x80);
        emit_i64_binop(ctx, block, TrustIrBinOp::Or, masked, c80)
    };
    let lead = |ctx: &mut MirLoweringCtx<'_>,
                block: &mut Block,
                shift: i128,
                prefix: i128,
                mask: i128|
     -> ValueId {
        let s = emit_i64_const(ctx, block, shift);
        let shifted = emit_i64_binop(ctx, block, TrustIrBinOp::LShr, c64, s);
        let m = emit_i64_const(ctx, block, mask);
        let masked = emit_i64_binop(ctx, block, TrustIrBinOp::And, shifted, m);
        let p = emit_i64_const(ctx, block, prefix);
        emit_i64_binop(ctx, block, TrustIrBinOp::Or, masked, p)
    };

    // o0 = select(lt80, c, select(lt800, 0xC0|(c>>6), select(lt10000, 0xE0|(c>>12), 0xF0|(c>>18))))
    let l2 = lead(ctx, block, 6, 0xC0, 0x1F);
    let l3 = lead(ctx, block, 12, 0xE0, 0x0F);
    let l4 = lead(ctx, block, 18, 0xF0, 0x07);
    let o0_34 = emit_i64_select(ctx, block, lt10000, l3, l4);
    let o0_234 = emit_i64_select(ctx, block, lt800, l2, o0_34);
    let o0 = emit_i64_select(ctx, block, lt80, c64, o0_234);
    // o1 = select(lt800, cont(0), select(lt10000, cont(6), cont(12)))
    let c_s0 = cont(ctx, block, 0);
    let c_s6 = cont(ctx, block, 6);
    let c_s12 = cont(ctx, block, 12);
    let o1_inner = emit_i64_select(ctx, block, lt10000, c_s6, c_s12);
    let o1 = emit_i64_select(ctx, block, lt800, c_s0, o1_inner);
    // o2 = select(lt10000, cont(0), cont(6))
    let c2_s0 = cont(ctx, block, 0);
    let c2_s6 = cont(ctx, block, 6);
    let o2 = emit_i64_select(ctx, block, lt10000, c2_s0, c2_s6);
    // o3 = cont(0)
    let o3 = cont(ctx, block, 0);

    // len = lt80?1 : lt800?2 : lt10000?3 : 4
    let one = emit_i64_const(ctx, block, 1);
    let two = emit_i64_const(ctx, block, 2);
    let three = emit_i64_const(ctx, block, 3);
    let four = emit_i64_const(ctx, block, 4);
    let len_34 = emit_i64_select(ctx, block, lt10000, three, four);
    let len_234 = emit_i64_select(ctx, block, lt800, two, len_34);
    let len = emit_i64_select(ctx, block, lt80, one, len_234);
    // The byte at `len - 1`, stored again for every position past the end.
    let last_idx = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, one);
    let o_34 = emit_i64_select(ctx, block, lt10000, o2, o3);
    let o_234 = emit_i64_select(ctx, block, lt800, o1, o_34);
    let o_last = emit_i64_select(ctx, block, lt80, o0, o_234);
    let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    let base = emit_element_addr(ctx, block, data_ptr, cursor, 1);
    let outs = [o0, o1, o2, o3];
    for (i, &o) in outs.iter().enumerate() {
        let (addr, byte) = if i == 0 {
            (base, o)
        } else {
            let idx = emit_i64_const(ctx, block, i as i128);
            let inside = emit_i64_icmp(ctx, block, ICmpOp::Ult, idx, len);
            let off = emit_i64_select(ctx, block, inside, idx, last_idx);
            let byte = emit_i64_select(ctx, block, inside, o, o_last);
            (emit_element_addr(ctx, block, base, off, 1), byte)
        };
        emit_store_low_byte(ctx, block, addr, byte);
    }
    let new_cursor = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, len);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, new_cursor);
}

/// Format a `&str` (its bytes verbatim) into the buffer at `data_ptr + cursor`,
/// advancing `cursor_slot`. The byte `len` is compile-time-known (from the
/// metadata side table); the source bytes live at `str_ptr` (a runtime data
/// pointer). The copy is unrolled (no loop) since `len` is constant.
fn emit_format_str(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    data_ptr: ValueId,
    cursor_slot: ValueId,
    str_ptr: ValueId,
    len: u64,
) {
    let cursor = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    let dst_base = emit_element_addr(ctx, block, data_ptr, cursor, 1);
    for i in 0..len {
        let off = emit_i64_const(ctx, block, i as i128);
        let src = emit_element_addr(ctx, block, str_ptr, off, 1);
        let byte = emit_typed_load(ctx, block, src, TrustIrTy::I8);
        let dst = if i == 0 {
            dst_base
        } else {
            let doff = emit_i64_const(ctx, block, i as i128);
            emit_element_addr(ctx, block, dst_base, doff, 1)
        };
        emit_typed_store(block, dst, TrustIrTy::I8, byte);
    }
    let len_const = emit_i64_const(ctx, block, len as i128);
    let new_cursor = emit_i64_binop(ctx, block, TrustIrBinOp::Add, cursor, len_const);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, new_cursor);
}

/// The capacity `alloc::fmt::format` gives its String before the first write.
/// A template with no placeholder is `Arguments::from_str` (rustc lowers
/// exactly that shape to it), and `format` returns `str::to_owned` of it: its
/// length. Otherwise `String::with_capacity(Arguments::estimated_capacity())`:
/// 0 when the template starts with a placeholder and its literal pieces total
/// under 16 bytes, else twice their total.
fn fmt_initial_capacity(pieces: &[FmtPiece]) -> u64 {
    let mut literal = 0u64;
    let mut placeholders = false;
    let mut starts_with_placeholder = false;
    for piece in pieces {
        match piece {
            FmtPiece::Literal(range) => literal += (range.end - range.start) as u64,
            FmtPiece::Placeholder => {
                if !placeholders && literal == 0 {
                    starts_with_placeholder = true;
                }
                placeholders = true;
            }
        }
    }
    if !placeholders {
        literal
    } else if starts_with_placeholder && literal < 16 {
        0
    } else {
        literal.wrapping_mul(2)
    }
}

/// `dest = format(args)`: allocate a fresh String slot, synthesize the formatted
/// bytes into it, store the final length, and bind the destination String local
/// to the slot address. Threads through the integer-formatting loop blocks.
fn lower_format<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    decoded: DecodedArguments<'tcx>,
) -> Result<(), String> {
    if !call.destination.projection.is_empty() {
        return Err("format! into a projected destination".to_owned());
    }
    // Validate the whole shape FIRST, so a rejected case fails closed BEFORE we
    // emit any IR or bind the destination (no observable partial effect).
    let (pieces, kinds, str_lengths) = classify_decoded_arguments(ctx, body, &decoded)?;

    // Resolve every RUNTIME `&str` arg's `(data, len)` fat-pointer halves up front
    // (straight-line, before the allocation and the destination binding), so an
    // unresolvable runtime `&str` fails closed here with no bound destination.
    let runtime_strs = resolve_fmt_runtime_strs(ctx, body, block, &decoded, &kinds, &str_lengths)?;

    // Allocate std's initial capacity; every write then grows it as std's would.
    let cap = emit_i64_const(ctx, block, i128::from(fmt_initial_capacity(&pieces)));
    let slot_ptr = emit_string_slot_alloc(ctx, body, block, cap, Some(call))?;

    // A cursor scratch slot (running length), init 0.
    let cursor_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I64,
            count: None,
            align: None,
        })
        .with_result(cursor_slot),
    );
    let zero = emit_i64_const(ctx, block, 0);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, zero);

    // Synthesize the formatting. A runtime `&str` copy splits control flow; the
    // returned `tail` is the final continuation block to finalize into.
    let tail = emit_format_into_slot(
        ctx,
        body,
        call,
        block,
        slot_ptr,
        cursor_slot,
        &decoded,
        &pieces,
        &kinds,
        &str_lengths,
        &runtime_strs,
    )?;

    // Store the final length, bind the destination String to the slot address, and
    // branch to the successor — into `tail` when a runtime copy split the block
    // (then commit `tail` to `extra_blocks`), else into the original `block`.
    if let Some(mut cur) = tail {
        finalize_format_string(ctx, body, &mut cur, call, slot_ptr, cursor_slot)?;
        ctx.extra_blocks.push(cur);
    } else {
        finalize_format_string(ctx, body, block, call, slot_ptr, cursor_slot)?;
    }
    Ok(())
}

/// Finalize a `format!` into `block`: store the running cursor as the String's
/// final length, bind the call's destination `String` local to the slot address,
/// and branch to the call successor. Shared by the single-block and the
/// runtime-`&str`-split paths (the latter passes the tail continuation block).
fn finalize_format_string<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    slot_ptr: ValueId,
    cursor_slot: ValueId,
) -> Result<(), String> {
    let final_len = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    emit_vec_field_store(ctx, block, slot_ptr, VEC_FIELD_LEN, final_len);

    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: slot_ptr,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `std::io::_print(args)` / `_eprint(args)`: synthesize the formatted bytes
/// into a fresh heap buffer (the exact bounded pipeline `format!` uses —
/// classify, resolve runtime `&str`s, capacity, alloc, emit), then CALL THE
/// SAME STD ENTRY with a `fmt::Arguments` in its string-literal
/// representation over those bytes (`emit_str_fmt_arguments`), free the
/// buffer, and thread the `()` destination (nothing to bind).
///
/// The sink is std's own, not a parallel one: `_print` writes through the
/// global `Stdout` (a `LineWriter` under its reentrant lock), `_eprint`
/// through `Stderr`, both honor libtest's output capture, and both panic on a
/// failed write. Bytes another writer left in std's buffer (a partial line from
/// LLVM-compiled code, `stdout().write_all`, `write!(stdout().lock(), ..)`) are
/// therefore ordered before this call's bytes exactly as in an LLVM build, and
/// a process that exits normally writes the same bytes to each stream in the
/// same order.
///
/// The buffer is an allocation LLVM's `print!` does not make: a
/// `#[global_allocator]` sees one more request per call (measured: a counting
/// allocator reports 1 request for `println!("k")` where LLVM's reports 0), and
/// an allocator that fails it ends the process in std's allocation-error abort
/// where LLVM's print succeeds.
///
/// One granularity difference remains: std receives this call's text as ONE
/// `write_all`, where an LLVM build's `fmt::write` hands it over in pieces
/// (each literal piece, then each argument's sign and digits). Two effects of
/// it are observable; a process that exits normally without a write error
/// writes the same bytes to each stream in either build.
///
/// * When the text does not fit the free space of std's 1024-byte `LineWriter`
///   buffer, the two can leave a different prefix already written. That is
///   observable wherever the descriptor is seen before std's next flush: when
///   the process then dies without flushing (`abort()`, a signal), and when a
///   writer that bypasses std's stdout buffer writes to the same file
///   (`eprint!` while stdout and stderr share one terminal, pipe or `2>&1`
///   file). Measured: a 1000-byte partial line, then
///   `print!("aaaaaaaaaa{}bbbbbbbbbbbbbbbbbbb", 5)` and `abort()`, leaves 1011
///   bytes on stdout under LLVM and 1000 here; with `eprint!("E")` in place of
///   `abort()` and stderr on the same pipe, the "E" follows byte 1011 under
///   LLVM and byte 1000 here.
/// * A FAILED write leaves different state in std's buffer. LLVM's
///   `println!("{}", 5)` buffers "5", then the "\n" piece flushes the line,
///   the flush fails and the line stays buffered; one `write_all("5\n")` with
///   nothing buffered goes straight to the descriptor and keeps nothing. Both
///   panic, but once that panic is caught (`catch_unwind`, or this print runs
///   in a destructor during that unwind) the next stdout write re-flushes the
///   kept line and panics again under LLVM, and is only buffered here.
///   Measured (panic=unwind, stdout a pipe whose read end is closed):
///   `catch_unwind(|| klib::show(5)); print!("x")` exits 101 under LLVM and 0
///   here. When the failed line was written by LLVM code, this call re-panics
///   exactly as LLVM's does.
///
/// The only modeled part is the formatting; `fmt::write` reads a
/// string-literal `Arguments` through `as_str`, so std copies these bytes and
/// keeps no reference to the buffer after the call returns.
///
/// The buffer is freed on the normal return only: when `_print` panics on a
/// failed write and unwinds, the buffer is leaked, never freed twice or read
/// after free.
fn lower_print<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    decoded: DecodedArguments<'tcx>,
    sink: Instance<'tcx>,
    arguments_ty: Ty<'tcx>,
) -> Result<(), String> {
    // Validate the whole shape FIRST, so a rejected case fails closed BEFORE
    // any IR is emitted (no observable partial effect).
    let (pieces, kinds, str_lengths) = classify_decoded_arguments(ctx, body, &decoded)?;
    let sink_plan = print_sink_plan(ctx, sink, arguments_ty)?;
    let runtime_strs = resolve_fmt_runtime_strs(ctx, body, block, &decoded, &kinds, &str_lengths)?;
    let cap = emit_format_capacity(
        ctx,
        body,
        block,
        &pieces,
        &decoded.template,
        &kinds,
        &str_lengths,
        &runtime_strs,
    )?;
    let slot_ptr = emit_string_slot_alloc(ctx, body, block, cap, Some(call))?;

    // A cursor scratch slot (running length), init 0.
    let cursor_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I64,
            count: None,
            align: None,
        })
        .with_result(cursor_slot),
    );
    let zero = emit_i64_const(ctx, block, 0);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, zero);

    let tail = emit_format_into_slot(
        ctx,
        body,
        call,
        block,
        slot_ptr,
        cursor_slot,
        &decoded,
        &pieces,
        &kinds,
        &str_lengths,
        &runtime_strs,
    )?;

    if let Some(mut cur) = tail {
        finalize_print(ctx, &mut cur, call, &sink_plan, slot_ptr, cursor_slot, cap)?;
        ctx.extra_blocks.push(cur);
    } else {
        finalize_print(ctx, block, call, &sink_plan, slot_ptr, cursor_slot, cap)?;
    }
    Ok(())
}

/// How the rewritten `print!` reaches std: the declared `_print`/`_eprint`
/// callee, rustc's byte offsets of the two words of `fmt::Arguments`, the
/// bridge's slot for that value, and how the call passes it.
struct PrintSinkPlan {
    callee: FuncId,
    /// The `fmt::Arguments` slot: 16 bytes, 8-aligned, two `I64` lanes.
    slot: MemoryAggregateLayout,
    /// Slot lane of the `template` pointer.
    template_lane: u32,
    /// Slot lane of the `args` word.
    args_lane: u32,
    /// `Some`: rustc's two `PassMode::Pair` lanes (the declaration takes two
    /// values, loaded from the slot at these offsets with these carriers);
    /// `None`: the whole slot is the one argument value.
    pair: Option<ScalarPairAbiPlan>,
}

/// The `[TCG-PRINT-SINK]` refusal: the rewritten `print!` cannot hand its bytes
/// to std's own entry in the shape this toolchain defines.
fn print_sink_refusal(sink: &str, detail: &str) -> String {
    format!(
        "[TCG-PRINT-SINK] `{sink}`: {detail}. The bridge formats a decoded `print!` \
         itself and must then hand the bytes to this same std entry as a string-literal \
         `fmt::Arguments`, so std's buffered stdout, output capture and write-error panic \
         apply; it cannot build that value or call shape here. Failing closed rather than \
         writing around std's buffer, which reorders output against every other writer."
    )
}

/// Decide `PrintSinkPlan` for the call to `sink` (`std::io::_print` or
/// `_eprint`) whose one input is `arguments_ty`, before any IR is emitted.
///
/// `fmt::Arguments` must be the two-word `{ template, args }` struct whose
/// string-literal representation is `template` = the first byte of the text and
/// `args` = `len << 1 | 1` (core's `Arguments::from_str`; `as_str` and
/// `fmt::write` read the low bit). The field NAMES pin that representation;
/// the offsets come from rustc's own layout, never declaration order. The
/// argument passing is the decision `lower_call_args_from_inputs` makes for a
/// MIR operand, asked of the same `FnAbi` with the same three facts, so the
/// values match the declaration `extern_callee` makes. Only rustc's two `Pair`
/// lanes and the whole slot are built here; every other lane (indirect,
/// unsized, wasm32 memory or `Cast`, AArch64 integer `Cast`) is not expected
/// for a two-pointer value and is refused by name.
fn print_sink_plan<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    sink: Instance<'tcx>,
    arguments_ty: Ty<'tcx>,
) -> Result<PrintSinkPlan, String> {
    let tcx = ctx.tcx;
    let sink_name =
        rustc_middle::ty::print::with_no_visible_paths!(tcx.def_path_str(sink.def_id()));
    let refuse = |detail: &str| print_sink_refusal(&sink_name, detail);
    let sig = tcx.instantiate_bound_regions_with_erased(
        sink.ty(tcx, ty::TypingEnv::fully_monomorphized())
            .fn_sig(tcx),
    );
    let arguments_ty = ctx.normalize_ty(arguments_ty);
    if sig.inputs().len() != 1
        || ctx.normalize_ty(ctx.monomorphize_ty(sig.inputs()[0])) != arguments_ty
        || !sig.output().is_unit()
        || sig.c_variadic()
    {
        return Err(refuse("the entry is not `fn(fmt::Arguments<'_>)`"));
    }
    let ty::Adt(adt, _) = arguments_ty.kind() else {
        return Err(refuse("the argument is not the `format_arguments` struct"));
    };
    if Some(adt.did()) != tcx.lang_items().format_arguments() || !adt.is_struct() {
        return Err(refuse("the argument is not the `format_arguments` struct"));
    }
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(arguments_ty))
        .map_err(|e| refuse(&format!("`fmt::Arguments` has no layout: {e:?}")))?;
    let pointer_bytes = tcx.data_layout.pointer_size().bytes();
    if pointer_bytes != 8 || layout.size.bytes() != 16 || layout.align.bytes() != 8 {
        return Err(refuse(&format!(
            "`fmt::Arguments` is {} bytes / align {} on a {}-byte-pointer target, not two \
             8-byte words",
            layout.size.bytes(),
            layout.align.bytes(),
            pointer_bytes
        )));
    }
    let variant = adt.non_enum_variant();
    let cx = LayoutCx(tcx);
    let word_offset = |name: &str| -> Option<u64> {
        let (index, _) = variant
            .fields
            .iter_enumerated()
            .find(|(_, field)| field.name.as_str() == name)?;
        let index = index.as_usize();
        let field = layout.field(&cx, index);
        let is_thin_pointer = matches!(
            field.backend_repr,
            rustc_abi::BackendRepr::Scalar(rustc_abi::Scalar::Initialized {
                value: rustc_abi::Primitive::Pointer(_),
                ..
            })
        );
        (is_thin_pointer && field.size.bytes() == 8).then(|| layout.fields.offset(index).bytes())
    };
    let (Some(template_offset), Some(args_offset)) = (word_offset("template"), word_offset("args"))
    else {
        return Err(refuse(
            "`fmt::Arguments` is not the `{ template, args }` pair of thin pointers whose \
             string-literal form is `args = len << 1 | 1`",
        ));
    };
    if variant.fields.len() != 2 || template_offset % 8 != 0 || args_offset % 8 != 0 {
        return Err(refuse(
            "`fmt::Arguments` has fields beside its two 8-aligned words",
        ));
    }
    let Some(slot) = fat_ptr_or_memory_aggregate_layout(tcx, arguments_ty)? else {
        return Err(refuse("`fmt::Arguments` has no memory slot"));
    };
    let lanes = aggregate_memory_field_tys(&slot.slot_ty)?;
    if slot.size != 16
        || slot.align != 8
        || slot.tag.is_some()
        || lanes.len() != 2
        || lanes.iter().any(|(_, lane)| *lane != TrustIrTy::I64)
    {
        return Err(refuse(&format!(
            "the `fmt::Arguments` slot {:?} is not two `I64` lanes",
            slot.slot_ty
        )));
    }
    // The lanes `lower_call_args_from_inputs` tries, in its order, for this
    // one by-value struct argument (index 0, offset 0). Every lane that would
    // pass something other than rustc's two `Pair` values or the whole slot
    // claims it first and is refused here by name; the reference, slice and
    // `dyn` arms between them never match a `format_arguments` struct.
    let source = RustcFnAbiSource::Instance(sink);
    if ctx
        .indirect_arg_param_plan(arguments_ty, 0, source)?
        .is_some()
    {
        return Err(refuse("rustc passes `fmt::Arguments` to it indirectly"));
    }
    if unsized_arguments::plan(ctx, arguments_ty, 0, source)? {
        return Err(refuse(
            "rustc passes `fmt::Arguments` to it as an unsized argument",
        ));
    }
    if ctx
        .wasm32_indirect_carrier_param(arguments_ty, 0, source)?
        .is_some()
    {
        return Err(refuse(
            "rustc passes `fmt::Arguments` to it through wasm32 memory",
        ));
    }
    let pair = ctx
        .scalar_pair_param_plan(arguments_ty, 0, source)?
        .filter(|plan| plan.ty == arguments_ty)
        .map(|plan| plan.plan);
    if pair.is_none() {
        if ctx
            .small_cast_param_plan(arguments_ty, 0, source)?
            .is_some()
        {
            return Err(refuse(
                "rustc passes `fmt::Arguments` to it as a wasm32 `Cast`",
            ));
        }
        if ctx
            .narrow_cast_param_plan(arguments_ty, 0, source)?
            .is_some()
        {
            return Err(refuse(
                "rustc passes `fmt::Arguments` to it as an integer `Cast`",
            ));
        }
    }
    // This lane builds its own argument list, which never carries the hidden
    // `#[track_caller]` location `func_ty_for_instance` declares for such an
    // instance: refuse that sink by name rather than call it one argument short.
    refuse_unthreaded_caller_location(ctx.tcx, sink)?;
    let callee = ctx.extern_callee(sink)?;
    Ok(PrintSinkPlan {
        callee,
        slot,
        template_lane: (template_offset / 8) as u32,
        args_lane: (args_offset / 8) as u32,
        pair,
    })
}

/// Build the string-literal `fmt::Arguments` over `len` bytes at `data` in a
/// fresh slot of `plan.slot`: `template` = `data`, `args` = `len << 1 | 1`
/// (see `print_sink_plan`). `data` is non-null: it is the `__rust_alloc`
/// buffer of `emit_string_slot_alloc`, whose capacity is at least 1.
fn emit_str_fmt_arguments(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    plan: &PrintSinkPlan,
    data: ValueId,
    len: ValueId,
) -> Result<ValueId, String> {
    let slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: plan.slot.slot_ty.clone(),
            count: None,
            align: Some(plan.slot.align),
        })
        .with_result(slot),
    );
    let data_ptr = coerce_to_plain_ptr(ctx, block, data);
    let template = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::PtrToInt,
            src_ty: TrustIrTy::Ptr,
            dst_ty: TrustIrTy::I64,
            operand: data_ptr,
        })
        .with_result(template),
    );
    let one = emit_i64_const(ctx, block, 1);
    let len_i64 = coerce_to_i64(ctx, block, len);
    let doubled = emit_i64_binop(ctx, block, TrustIrBinOp::Shl, len_i64, one);
    let args_word = emit_i64_binop(ctx, block, TrustIrBinOp::Or, doubled, one);
    let slot_ty = plan.slot.slot_ty.clone();
    emit_aggregate_field_store(
        ctx,
        block,
        slot_ty.clone(),
        slot,
        plan.template_lane,
        template,
    )?;
    emit_aggregate_field_store(ctx, block, slot_ty, slot, plan.args_lane, args_word)?;
    Ok(slot)
}

/// Finalize a `_print`/`_eprint` into `block`: call std's entry (`plan`) with
/// the string-literal `fmt::Arguments` over the synthesized bytes, honoring the
/// MIR call's unwind edge (`push_unwindable_intercept_call`); on its normal
/// return free the buffer (`__rust_dealloc`, the byte-buffer's `size = cap,
/// align = 1` — the exact allocation shape `emit_string_slot_alloc` made) and
/// branch to the call successor. The `()` destination binds nothing.
fn finalize_print(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, '_>,
    plan: &PrintSinkPlan,
    slot_ptr: ValueId,
    cursor_slot: ValueId,
    cap: ValueId,
) -> Result<(), String> {
    let final_len = emit_typed_load(ctx, block, cursor_slot, TrustIrTy::I64);
    let data_ptr = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
    let arguments = emit_str_fmt_arguments(ctx, block, plan, data_ptr, final_len)?;
    let args = match &plan.pair {
        Some(pair) => (0..2)
            .map(|lane| {
                let addr = slot_byte_ptr(ctx, block, arguments, pair.lanes[lane].1);
                pair.load_lane_carrier(ctx, block, addr, lane)
            })
            .collect(),
        None => vec![arguments],
    };
    push_unwindable_intercept_call(ctx, block, plan.callee, args, None);
    let dealloc = vec_dealloc_callee(ctx)?;
    let align_one = emit_i64_const(ctx, block, 1);
    let cap_usize = allocator_usize_from_i64(ctx, block, cap)?;
    let align_one_usize = allocator_usize_from_i64(ctx, block, align_one)?;
    block.body.push(InstrNode::new(Inst::Call {
        callee: dealloc,
        args: vec![data_ptr, cap_usize, align_one_usize],
    }));
    emit_call_successor(block, call.target);
    Ok(())
}

/// `<String as Write>::write_fmt(&mut self, args)`: append the formatted bytes to
/// the existing String slot, returning `Ok(())`. The `Result` destination is a
/// ZST-ish `Ok(())` we bind to 0 (the bridge models `Result<(), Error>` for the
/// `write!(...).unwrap()` chain; an infallible append always succeeds).
fn lower_write_fmt<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    decoded: DecodedArguments<'tcx>,
) -> Result<(), String> {
    // Validate the whole shape FIRST (fail closed before any IR is emitted).
    let (pieces, kinds, str_lengths) = classify_decoded_arguments(ctx, body, &decoded)?;

    // Resolve every RUNTIME `&str` arg's `(data, len)` up front (before mutating the
    // destination slot), so an unresolvable one fails closed with no side effect.
    let runtime_strs = resolve_fmt_runtime_strs(ctx, body, block, &decoded, &kinds, &str_lengths)?;

    // The `&mut String` self arg's slot address.
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    // Cursor scratch slot, seeded with the existing length (write! appends).
    let cursor_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I64,
            count: None,
            align: None,
        })
        .with_result(cursor_slot),
    );
    let cur_len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    emit_typed_store(block, cursor_slot, TrustIrTy::I64, cur_len);

    // A runtime `&str` copy splits control flow; the returned `tail` is the final
    // continuation block to finalize into.
    let mut tail = emit_format_into_slot(
        ctx,
        body,
        call,
        block,
        slot_ptr,
        cursor_slot,
        &decoded,
        &pieces,
        &kinds,
        &str_lengths,
        &runtime_strs,
    )?;
    // Finalize into the tail continuation (when a runtime copy split the block) or
    // the original `block`.
    let cur: &mut Block = tail.as_mut().unwrap_or(&mut *block);

    let final_len = emit_typed_load(ctx, cur, cursor_slot, TrustIrTy::I64);
    emit_vec_field_store(ctx, cur, slot_ptr, VEC_FIELD_LEN, final_len);

    // Bind the destination `Result<(), fmt::Error>` to `Ok(())`. The infallible
    // synthesized append always succeeds, so the result is the `Ok` variant —
    // a no-payload variant (its `()` payload is a ZST). The destination is a
    // memory-backed Direct/Niche enum slot; write the `Ok` variant's tag, exactly
    // as `from_residual` writes `Err`/`None`. A subsequent `discriminant(dest)` /
    // `unwrap` then reads `Ok` from the slot. If the destination is unit/never
    // (the result is discarded as a ZST), there is nothing to bind.
    if call.destination.projection.is_empty() {
        let dest_local = call.destination.local;
        let dest_rust_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, dest_local));
        let (ok_variant, adt) = result_ok_variant(ctx, dest_rust_ty)
            .ok_or_else(|| "write! result is not a recognizable Result<(),E>".to_owned())?;
        if local_is_memory_backed(ctx, dest_local) {
            let layout = memory_aggregate_layout_shared(ctx.tcx, dest_rust_ty)?
                .ok_or_else(|| "write! Result destination without aggregate layout".to_owned())?;
            write_memory_enum_variant_no_payload(
                ctx, body, cur, dest_local, adt, &layout, ok_variant,
            )?;
        } else if !matches!(
            local_trust_ir_ty(ctx, body, dest_local),
            Ok(TrustIrTy::Unit) | Ok(TrustIrTy::Never)
        ) {
            // A scalarized result: bind the destination's discriminant so a
            // following `discriminant`/`unwrap` reads `Ok`.
            ctx.bind_adt_discriminant_binding(
                dest_local,
                AdtDiscriminantBinding {
                    value: adt.discriminant_for_variant(ctx.tcx, ok_variant).val as i128,
                    variant_index: ok_variant,
                },
            );
        }
    }
    emit_call_successor(cur, call.target);

    // Commit the tail continuation block (if a runtime copy split the block).
    if let Some(t) = tail {
        ctx.extra_blocks.push(t);
    }
    Ok(())
}

/// Whether `ty` is `Result<(), fmt::Error>` — the result type a `write!` (a
/// `<W as fmt::Write>::write_fmt`) produces. The `Ok` payload is `()` and the
/// `Err` payload is the ZST `fmt::Error`, so an `.unwrap()` on a synthesized
/// (always-`Ok`) one is a no-op.
///
/// The `Err` payload is keyed on the ONE `core::fmt::Error` definition (crate
/// `core`, def path `fmt::Error`), never on an item merely NAMED `Error`: the
/// review's `probe_unwrap_user_error.rs` defined `struct Error;` in the user
/// crate, and the name-only test let `lower_fmt_call` no-op a `.unwrap()` on a
/// genuine `Err(Error)` (exit 3 where LLVM aborts with 134). `fmt::Error` carries
/// no diagnostic item, so the def path is the identity.
fn is_write_result_ty<'tcx>(ctx: &MirLoweringCtx<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, args) = ty.kind() else {
        return false;
    };
    if Some(adt.did()) != ctx.tcx.get_diagnostic_item(rustc_span::sym::Result) {
        return false;
    }
    // Ok payload `()` and Err payload `core::fmt::Error`.
    let ok_ty = ctx.monomorphize_ty(args.type_at(0));
    let err_ty = ctx.monomorphize_ty(args.type_at(1));
    if !ok_ty.is_unit() {
        return false;
    }
    is_core_fmt_error_ty(ctx.tcx, err_ty)
}

/// `ty` is exactly `core::fmt::Error` — the ZST unit struct at def path
/// `core::fmt::Error`. Raw DefPath segments (not the pretty printer, which is
/// per-call expensive cross-crate); a same-named user or third-party `Error` in
/// any other crate or module is NOT it.
fn is_core_fmt_error_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, _) = ty.kind() else {
        return false;
    };
    if !adt.is_struct() || !adt.non_enum_variant().fields.is_empty() {
        return false;
    }
    let did = adt.did();
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !is_real_core_def(tcx, did) {
        return false;
    }
    let path = tcx.def_path(did);
    let mut names = path
        .data
        .iter()
        .rev()
        .filter_map(|seg| seg.data.get_opt_name())
        .map(|name| name.as_str().to_owned());
    names.next().as_deref() == Some("Error") && names.next().as_deref() == Some("fmt")
}

/// For a `Result<(), E>`, return its `Ok` variant index + ADT def. Used by
/// `write!` to bind its result to `Ok(())`.
fn result_ok_variant<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Option<(VariantIdx, ty::AdtDef<'tcx>)> {
    let ty::Adt(adt, _) = ty.kind() else {
        return None;
    };
    if !adt.is_enum() {
        return None;
    }
    for (idx, variant) in adt.variants().iter_enumerated() {
        if ctx.tcx.item_name(variant.def_id).as_str() == "Ok" {
            return Some((idx, *adt));
        }
    }
    None
}

/// `dest = String::new()`: a zero-capacity, zero-length inline header with
/// a dangling data pointer and no heap allocation.
fn lower_string_new<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    let zero = emit_i64_const(ctx, block, 0);
    let slot_ptr = emit_string_slot_alloc(ctx, body, block, zero, Some(call))?;
    // Anchor the slot address in `vec_slot_addrs` for loop-header recovery: when a
    // later loop header's in-state merge drops this String local's `scalar_values`
    // binding (the INVARIANT slot address reads as branch-varying across the
    // pre-loop/latch predecessors), `value_for_scalar_binding` recovers it from
    // `vec_slot_addrs` rather than falling through to a never-defined synthetic
    // ValueId — which was the [TCG-SSA-071] fail-close on `for _ in .. { s.push(..) }`
    // (and `for c in s.chars() { out.push(c) }`). Mirrors `lower_vec_new`; a String
    // shares `Vec<u8>`'s `{ptr,cap,len}` slot, and the slot address is loop-invariant
    // (`push` reallocs the buffer FIELD, never moves the stack slot).
    if call.destination.projection.is_empty() {
        ctx.register_vec_slot_addr(call.destination.local, slot_ptr);
    }
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: slot_ptr,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `dest = must_use::<String>(src)` — the identity wrapper. Copy the source
/// String's slot-address scalar to the destination.
fn lower_string_identity<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err("String must_use with != 1 arg".to_owned());
    }
    let src = lower_operand_to_value(ctx, body, block, &call.args[0].node)?;
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Ptr,
            operand: src,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `dest = String::is_empty(&self)`: `len == 0` (a `Bool`).
fn lower_string_is_empty<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    let zero = emit_i64_const(ctx, block, 0);
    let is_empty = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: TrustIrTy::I64,
            lhs: len,
            rhs: zero,
        })
        .with_result(is_empty),
    );
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: TrustIrTy::Bool,
            operand: is_empty,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

// ===========================================================================
// `for` loop iterators: `Range<T>` and `core::slice::Iter<T>`
//
// A `for pat in iterable { body }` desugars (in MIR) to
//
//     let mut it = IntoIterator::into_iter(iterable);
//     loop { match Iterator::next(&mut it) { Some(pat) => body, None => break } }
//
// The real std `next` bodies descend into machinery this backend cannot lower:
//   * `<Range<T> as Iterator>::next` -> `RangeIteratorImpl::spec_next` (a
//     `Rvalue::Ref` of a projected place) -> `Step::forward_unchecked`
//     (the `cold_path` intrinsic) -> `unreachable_unchecked` precondition
//     (`Rvalue::RawPtr`);
//   * `<slice::Iter<T> as Iterator>::next` and `slice::Iter::new` use a
//     `NonNull`/`end_or_len` union representation built from nested-aggregate
//     operands the backend rejects ("nested aggregate field operand is not a
//     place" / "memory aggregate whole assignment from non-local operand").
//
// So — exactly as `Box::new` and the `Vec<T>` methods are intercepted — we
// intercept the three calls these two iterators need and synthesize them
// directly, using the SAME memory-backed-aggregate machinery the rest of the
// bridge uses for `Option` / structs:
//
//   * the iterator-state local is memory-backed (its NATURAL layout: a
//     `Range<T>` is `{ start, end }`; a `slice::Iter<T>` is `{ ptr, end }`),
//     so `&mut it` lowers to the slot pointer and `Iterator::next(&mut it)`
//     reads/writes the slot;
//   * `IntoIterator::into_iter` for a `Range` is the identity (it copies the
//     `{start,end}` into the iterator slot); for `&[T]` / `&[T; N]` it computes
//     `{ data, data + len*size }` into the iterator slot;
//   * `Iterator::next` loads the state, computes `cond` (`start < end`, or
//     `ptr != end`), the yielded value, and the advanced state; it stores the
//     advanced state back (a `Select`, so the state only advances when in
//     range — matching the real `next`'s "no mutation past the end") and writes
//     the `Option<…>` result into the (memory-backed) destination slot with the
//     tag/niche and payload chosen by `cond` (also a `Select`). Downstream
//     `discriminant(opt)` + `switchInt` + `(opt as Some).0` then flow through
//     the existing memory-enum machinery unchanged.
//
// This is branchless (no new basic blocks): the whole `next` is a straight-line
// sequence of loads, arithmetic, `Select`s and stores, so it slots into the one
// trust-ir block the call terminator already owns. Any iterator shape we do not
// model (an adapter, a non-scalar element, …) is left to the general call path,
// which fails closed precisely.
// ===========================================================================

/// If `ty` is `core::ops::Range<T>` for a memory-scalar index `T` (`i64`,
/// `usize`, …), return `T`. Identified by the `Range` lang item.
fn range_index_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    // (`std_def_is_interceptable`: a local `Range` is never modeled.)
    if Some(adt.did()) != tcx.lang_items().range_struct()
        || !std_def_is_interceptable(tcx, adt.did())
    {
        return None;
    }
    let index_ty = args.type_at(0);
    // The index must be a RUST integer (`ty::Int`/`ty::Uint`). Checking the
    // trust-ir image alone is NOT enough: `char` erases to `U32` (whose
    // `is_integer()` is true) but has DIFFERENT stepping semantics — a
    // `Range<char>` steps OVER the Unicode surrogate gap (0xD800..0xE000)
    // while a `+1`-at-U32 model steps INTO it (a measured silent wrong result:
    // '\u{d7ff}'..'\u{e001}' yields 2 chars in std, 513 under the +1 model).
    // The RUST-level firewall rejects char (and any future non-int scalar) so
    // those ranges fall to the general path and fail closed.
    if !matches!(index_ty.kind(), ty::Int(_) | ty::Uint(_)) {
        return None;
    }
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, index_ty).ok()?;
    if !trust_ir_ty.is_integer() {
        return None;
    }
    Some(index_ty)
}

/// If `ty` is core's `ops::index_range::IndexRange` in a 32-bit (wasm32)
/// session, return `usize`. `IndexRange { start, end }` is the `alive` index
/// range of `array::IntoIter` (`ArrayIntoIterLayout`); its `Iterator` impl
/// yields `start..end` exactly as `Range<usize>` does (it keeps
/// `start <= end`, so its `len() > 0` test is `start < end`), and stepping
/// backwards decrements `end` as `Range` does. On wasm32 rustc's MIR inliner
/// inlines `array::IntoIter::fold` down to `<IndexRange as Iterator>::try_fold`
/// over core's `PolymorphicIter::try_fold` closure (which reads `data[index]`
/// and calls the fold closure), so the chain engine drives that call as a
/// `Range<usize>` source. Admitted only when rustc lays the two `usize`
/// fields out as the `Range` model reads them: `start` at 0 and `end` one
/// word later. A native session keeps core's own bodies for it.
fn index_range_index_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    if tcx.data_layout.pointer_size().bits() != 32 {
        return None;
    }
    let ty::Adt(adt, _) = ty.kind() else {
        return None;
    };
    let did = adt.did();
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !(adt.is_struct()
        && std_def_is_interceptable(tcx, did)
        && is_real_std_crate_def(tcx, did)
        && tcx.item_name(did).as_str() == "IndexRange"
        && tcx.def_path_str(did).contains("index_range"))
    {
        return None;
    }
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .ok()?;
    let word = tcx.data_layout.pointer_size().bytes();
    let usize_ty = tcx.types.usize;
    let fields = &adt.non_enum_variant().fields;
    let field_at = |name: &str| -> Option<u64> {
        let index = fields.iter().position(|f| f.name.as_str() == name)?;
        let field = layout.field(&LayoutCx(tcx), index);
        (field.ty == usize_ty && field.size.bytes() == word)
            .then(|| layout.fields.offset(index).bytes())
    };
    (fields.len() == 2
        && layout.size.bytes() == 2 * word
        && field_at("start") == Some(0)
        && field_at("end") == Some(word))
    .then_some(usize_ty)
}

/// If `ty` is `core::ops::RangeInclusive<T>` for a memory-scalar index `T`
/// (`i64`, `usize`, `u8`, …), return `T`. Identified by the `RangeInclusive`
/// lang item. Unlike `Range`, a `RangeInclusive<T>` is a THREE-field struct
/// `{ start, end, exhausted: bool }` whose iteration yields `start..=end`
/// inclusively (one more element than `start..end`, with the final element
/// produced exactly once even at `end == T::MAX`). Non-integer index types and
/// unrecognized shapes return `None` (fail closed).
fn range_inclusive_index_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    // (`std_def_is_interceptable`: a local `RangeInclusive` is never modeled.)
    if Some(adt.did()) != tcx.lang_items().range_inclusive_struct()
        || !std_def_is_interceptable(tcx, adt.did())
    {
        return None;
    }
    let index_ty = args.type_at(0);
    // The index must be a RUST integer (`ty::Int`/`ty::Uint`) — the trust-ir
    // image alone is NOT enough (`char` erases to an "integer" `U32` but steps
    // OVER the surrogate gap; see `range_index_ty`). This comment's old
    // "(char / non-integer)" intent is now actually ENFORCED at the Rust level.
    if !matches!(index_ty.kind(), ty::Int(_) | ty::Uint(_)) {
        return None;
    }
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, index_ty).ok()?;
    if !trust_ir_ty.is_integer() {
        return None;
    }
    Some(index_ty)
}

/// The byte offsets of a `RangeInclusive<T>`'s three fields within its slot, as
/// reported by rustc's layout (the layout is NOT necessarily declaration order:
/// for `RangeInclusive<u8>` rustc places the `exhausted` bool FIRST, at offset
/// 0, with `start`/`end` after it). Source field indices are `start = 0`,
/// `end = 1`, `exhausted = 2`. Returns `(start_off, end_off, exhausted_off)`.
fn range_inclusive_field_offsets<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<(u64, u64, u64), String> {
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("RangeInclusive layout_of failed: {e:?}"))?;
    let rustc_abi::FieldsShape::Arbitrary { .. } = layout.fields else {
        return Err("RangeInclusive layout is not a field struct".to_owned());
    };
    if layout.fields.count() != 3 {
        return Err(format!(
            "RangeInclusive has {} fields, expected 3",
            layout.fields.count()
        ));
    }
    Ok((
        layout.fields.offset(0).bytes(),
        layout.fields.offset(1).bytes(),
        layout.fields.offset(2).bytes(),
    ))
}

/// If `ty` is `core::slice::Iter<'_, T>` for a memory-scalar element `T`, return
/// `T`. Identified by the `SliceIter` diagnostic item.
fn slice_iter_element_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    // (`std_def_is_interceptable`: a local `slice::Iter` is never modeled.)
    if Some(adt.did()) != tcx.get_diagnostic_item(rustc_span::Symbol::intern("SliceIter"))
        || !std_def_is_interceptable(tcx, adt.did())
    {
        return None;
    }
    // `slice::Iter<'a, T>`'s generic args are `['a, T]`: the element type is the
    // first TYPE argument (a lifetime arg precedes it), so select it by kind.
    let element_ty = args.types().next()?;
    // The element must be a single memory-scalar leaf: `next` yields `&T`, and
    // the iterator advances by `size_of::<T>()`. A non-scalar / ZST element
    // would need a different stride / yield path — fail closed (return `None`).
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, element_ty).ok()?;
    if trust_ir_ty.bit_width().is_none() {
        return None;
    }
    Some(element_ty)
}

/// Like `slice_iter_element_ty`, but recognizes BOTH `slice::Iter<'a, T>` (yields
/// `&T`) AND `slice::IterMut<'a, T>` (yields `&mut T`). Both share the identical
/// `{ ptr, end }` two-pointer layout and the same `data + len*size` construction —
/// only the yielded reference's mutability differs, which is transparent to the
/// bridge's memory model. Used by `<&mut Vec<T>>::into_iter` (`for x in &mut v`),
/// whose destination is `slice::IterMut`.
fn slice_iter_or_mut_element_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    if let Some(e) = slice_iter_element_ty(tcx, ty) {
        return Some(e);
    }
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    let did = adt.did();
    let is_slice_iter_mut = Some(did)
        == tcx.get_diagnostic_item(rustc_span::Symbol::intern("SliceIterMut"))
        || (tcx.item_name(did).as_str() == "IterMut"
            // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
            && is_real_std_crate_def(tcx, did)
            && tcx.def_path_str(did).contains("slice"));
    // (`std_def_is_interceptable`: a local `slice::IterMut` is never modeled.)
    if !is_slice_iter_mut || !std_def_is_interceptable(tcx, did) {
        return None;
    }
    let element_ty = args.types().next()?;
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, element_ty).ok()?;
    if trust_ir_ty.bit_width().is_none() {
        return None;
    }
    Some(element_ty)
}

/// If `ty` is `core::array::IntoIter<T, N>` for a memory-scalar element `T` that
/// needs no drop, return `T` — the BY-VALUE array iterator (`for x in a`). Its
/// real `fold` bottoms out in a `try_fold` this backend cannot lower, so we
/// intercept its `into_iter`/`next` and its iterator-chain terminals. The
/// intercepted state IS rustc's own layout ([`ArrayIntoIterLayout`]: the `alive`
/// index range plus the inline element buffer), so it agrees with rustc's
/// inlined constructor and `next` at `-O2`/`-O3`.
///
/// Every model keyed on this predicate treats the iterator's `Drop` as a no-op:
/// the array owns no heap, and a `T` that needs no drop has nothing to destruct.
/// A scalar `T` CAN need drop (the single-scalar-leaf struct arm maps a newtype
/// with a `Drop` impl, `struct D(u64); impl Drop for D`, to its leaf), and then
/// std's `Drop` drops the unyielded `alive` elements, which those models skip.
/// Such an element, and a non-scalar one, returns `None`: nothing here intercepts
/// that iterator, and its constructor, `next`, terminals and drop are std's own
/// bodies over rustc's layout, or refuse where this backend cannot lower them.
fn array_intoiter_element_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    let did = adt.did();
    // (`std_def_is_interceptable`: a local `array::IntoIter` is never modeled.)
    if !(std_def_is_interceptable(tcx, did)
        && tcx.item_name(did).as_str() == "IntoIter"
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        && is_real_std_crate_def(tcx, did)
        && tcx.def_path_str(did).contains("array"))
    {
        return None;
    }
    let element_ty = args.types().next()?;
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, element_ty).ok()?;
    if trust_ir_ty.bit_width().is_none() {
        return None;
    }
    if element_ty.needs_drop(tcx, ty::TypingEnv::fully_monomorphized()) {
        return None;
    }
    Some(element_ty)
}

/// Whether `instance` is `<core::array::IntoIter<T, N> as Drop>::drop` for a
/// modeled element (`array_intoiter_element_ty`) that itself needs no drop:
/// core's body is `drop_in_place` of the alive element slice, which then
/// destroys nothing. A `Drop` impl lives in the crate that defines its type, so
/// the real-core identity of the self type pins the impl as core's.
fn array_intoiter_no_op_drop<'tcx>(tcx: TyCtxt<'tcx>, instance: Instance<'tcx>) -> bool {
    let def_id = instance.def_id();
    if !matches!(instance.def, ty::InstanceKind::Item(_))
        || tcx.item_name(def_id).as_str() != "drop"
    {
        return false;
    }
    let Some(impl_did) = tcx.trait_impl_of_assoc(def_id) else {
        return false;
    };
    if Some(tcx.impl_trait_id(impl_did)) != tcx.lang_items().drop_trait() {
        return false;
    }
    let self_ty = tcx.type_of(impl_did).instantiate(tcx, instance.args);
    let self_ty = tcx.normalize_erasing_regions(ty::TypingEnv::fully_monomorphized(), self_ty);
    array_intoiter_element_ty(tcx, self_ty)
        .is_some_and(|element_ty| !element_ty.needs_drop(tcx, ty::TypingEnv::fully_monomorphized()))
}

/// `Some((drain_ty, element_ty))` when `instance` is `<alloc::vec::Drain<T> as
/// Drop>::drop` for a modeled Drain (`vec_drain_element_ty`): the call rustc's
/// `drop_glue::<Drain<T>>` makes, and so every drop that reaches a Drain through
/// that glue (`ptr::drop_in_place`, `ManuallyDrop::drop`, an enclosing value's
/// glue). A `Drop` impl lives in the crate that defines its type, so the
/// real-alloc identity of the self type pins the impl as alloc's.
fn vec_drain_drop_impl<'tcx>(
    tcx: TyCtxt<'tcx>,
    instance: Instance<'tcx>,
) -> Option<(Ty<'tcx>, Ty<'tcx>)> {
    let def_id = instance.def_id();
    if !matches!(instance.def, ty::InstanceKind::Item(_))
        || tcx.item_name(def_id).as_str() != "drop"
    {
        return None;
    }
    let impl_did = tcx.trait_impl_of_assoc(def_id)?;
    if Some(tcx.impl_trait_id(impl_did)) != tcx.lang_items().drop_trait() {
        return None;
    }
    let self_ty = tcx.type_of(impl_did).instantiate(tcx, instance.args);
    let self_ty = tcx.normalize_erasing_regions(ty::TypingEnv::fully_monomorphized(), self_ty);
    let element_ty = vec_drain_element_ty(tcx, self_ty)?;
    Some((self_ty, element_ty))
}

/// rustc's own byte offsets of a modeled `core::array::IntoIter<T, N>`
/// (`array_intoiter_element_ty`): `IntoIter { inner: ManuallyDrop<PolymorphicIter<
/// [MaybeUninit<T>; N]>> }` with `PolymorphicIter { alive: IndexRange { start, end
/// }, data }`. `start`/`end` are the `usize` indices of the live elements and
/// `data` the inline element buffer. The bridge's `array::IntoIter` state IS this
/// layout: the intercepted constructor, `next` and the iterator-chain source read
/// and write these offsets. At `-O2`/`-O3` rustc's MIR inliner builds the iterator
/// itself (`PolymorphicIter { alive: IndexRange { start: 0, end: N }, data }`) and
/// may advance it with its own inlined `next`, so any other state shape would make
/// the bridge read rustc's indices as pointers. The offsets are read from rustc,
/// never assumed.
#[derive(Clone, Copy)]
struct ArrayIntoIterLayout {
    start: u64,
    end: u64,
    data: u64,
    /// `N`, the element count of the inline buffer.
    len: u64,
}

/// Read [`ArrayIntoIterLayout`] from rustc's layout of `ty`, failing closed unless
/// single-field wrappers lead to a struct with an `alive: { start, end }` pair of
/// disjoint pointer-width integers and a `data: [_; N]` buffer of exactly `N`
/// elements of `element_ty`'s nonzero size that lies after `alive.start`.
fn array_intoiter_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    element_ty: Ty<'tcx>,
) -> Result<ArrayIntoIterLayout, String> {
    let cx = LayoutCx(tcx);
    let outer = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("[TCG-ARRAY-INTOITER-LAYOUT] layout of {ty:?}: {e:?}"))?;
    let (elem_size, _) = element_layout_size_align(tcx, element_ty)?;
    let named = |layout: rustc_middle::ty::layout::TyAndLayout<'tcx>, name: &str| {
        let ty::Adt(adt, _) = layout.ty.kind() else {
            return None;
        };
        if !adt.is_struct() || !matches!(layout.variants, rustc_abi::Variants::Single { .. }) {
            return None;
        }
        let index = adt
            .non_enum_variant()
            .fields
            .iter()
            .position(|f| f.name.as_str() == name)?;
        Some((
            layout.field(&cx, index),
            layout.fields.offset(index).bytes(),
        ))
    };
    // `alive.start`/`alive.end` are `usize`: the session's pointer width, which
    // the cursor loads and stores read and write (`emit_usize_field_load`/`_store`).
    let word = tcx.data_layout.pointer_size().bytes();
    let index_scalar = |layout: rustc_middle::ty::layout::TyAndLayout<'tcx>| {
        layout.size.bytes() == word
            && layout.align.bytes() == word
            && matches!(layout.backend_repr, rustc_abi::BackendRepr::Scalar(scalar)
                if matches!(scalar.primitive(), rustc_abi::Primitive::Int(integer, _)
                    if integer.size().bytes() == word))
    };
    // Peel the single-field wrappers (`IntoIter.inner`, `ManuallyDrop.value`,
    // `MaybeDangling.0`) down to the struct that holds `alive` and `data`.
    let mut cur = outer;
    let mut base = 0u64;
    for _ in 0..8 {
        if let (Some((alive, alive_off)), Some((data, data_off))) =
            (named(cur, "alive"), named(cur, "data"))
        {
            let (Some((start, start_off)), Some((end, end_off))) =
                (named(alive, "start"), named(alive, "end"))
            else {
                break;
            };
            let start_off = base + alive_off + start_off;
            let end_off = base + alive_off + end_off;
            let data_off = base + data_off;
            let len = match data.ty.kind() {
                ty::Array(_, len) => len.try_to_target_usize(tcx),
                _ => None,
            };
            let Some(len) = len else {
                break;
            };
            let disjoint = start_off + word <= end_off || end_off + word <= start_off;
            if !outer.is_sized()
                || elem_size == 0
                || !index_scalar(start)
                || !index_scalar(end)
                || !disjoint
                || data_off <= start_off
                || data.size.bytes() != len.saturating_mul(elem_size)
                || data_off + data.size.bytes() > outer.size.bytes()
            {
                return Err(format!(
                    "[TCG-ARRAY-INTOITER-LAYOUT] {ty:?} ({} bytes) has alive.start@{start_off} \
                     alive.end@{end_off} data@{data_off} ({} bytes for {len} elements of \
                     {elem_size}); the modeled state needs two disjoint pointer-width indices \
                     and an exactly sized inline buffer after alive.start",
                    outer.size.bytes(),
                    data.size.bytes()
                ));
            }
            return Ok(ArrayIntoIterLayout {
                start: start_off,
                end: end_off,
                data: data_off,
                len,
            });
        }
        let ty::Adt(adt, _) = cur.ty.kind() else {
            break;
        };
        if !adt.is_struct() || adt.non_enum_variant().fields.len() != 1 {
            break;
        }
        base += cur.fields.offset(0).bytes();
        cur = cur.field(&cx, 0);
    }
    Err(format!(
        "[TCG-ARRAY-INTOITER-LAYOUT] {ty:?} is not single-field wrappers around an \
         `alive: {{ start, end }}` index range and a `data` array"
    ))
}

/// Recognize the owning `alloc::vec::IntoIter<T>` produced by `<Vec<T> as
/// IntoIterator>::into_iter` — the destination of the BY-VALUE `for x in v` loop.
/// Returns the (scalar) element type `T`. The defining path is
/// `alloc::vec::into_iter::IntoIter` (or its `alloc::vec::IntoIter` re-export);
/// the `"::vec::"` segment distinguishes it from `array::IntoIter`
/// (`core::array::...`) AND from `vec_deque::IntoIter`
/// (`alloc::collections::vec_deque::...`, which the `!contains("deque")` guard
/// also excludes). Restricted to an element whose trust-ir type is a single
/// fixed-width scalar (the by-value `next` model moves that scalar out). Such an
/// element may still NEED DROP: the single-scalar-leaf struct arm maps a
/// newtype with a `Drop` impl (`struct D(u64); impl Drop for D`) to its leaf.
/// That element is admitted only when its `drop_in_place::<T>` glue is the one
/// the per-element drop loop lowers (`drop_glue_needs_drop_element_lowerable`,
/// the gate a `Vec<T>` drop uses); every other droppable element returns `None`
/// and fails closed downstream. An admitted droppable element is owed a drop
/// wherever std drops it: the iterator's drop and a consumed chain release the
/// unyielded `[ptr, end)` (`emit_vec_intoiter_release`), and a drive that
/// discards a pulled item drops it there (`emit_discard_drop`). Under
/// `panic=unwind` a drive over such an element fails closed (`emit_chain_next`);
/// the intercepted `next`, which moves one element out and drops nothing, and
/// the iterator's own drop, with its nested cleanup, are still lowered.
fn vec_intoiter_element_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    let did = adt.did();
    // Untrimmed + no-visible printer: this runs per candidate call in the
    // iterator-chain resolver, and the default printer's first visible-path
    // use per compile decodes the visible universe (~3.4 ms — the h1-crate
    // instance of the first-item warmup, gdb-pinned here via
    // iter_chain_wraps_stepby). Both consumers are substring matches on
    // module segments (`::vec::`, `deque`) present identically in the DEF
    // path rendering.
    let path = rustc_middle::ty::print::with_no_visible_paths!(tcx.def_path_str(did));
    // (`std_def_is_interceptable`: a local `vec::IntoIter` is never modeled.)
    if !(std_def_is_interceptable(tcx, did)
        && tcx.item_name(did).as_str() == "IntoIter"
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        && is_real_alloc_or_std_def(tcx, did)
        && path.contains("::vec::")
        && !path.contains("deque"))
    {
        return None;
    }
    let element_ty = args.types().next()?;
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, element_ty).ok()?;
    if trust_ir_ty.bit_width().is_none() {
        return None;
    }
    if element_ty.needs_drop(tcx, ty::TypingEnv::fully_monomorphized())
        && !drop_glue_needs_drop_element_lowerable(tcx, element_ty)
    {
        return None;
    }
    Some(element_ty)
}

/// Whether `ty` mentions a modeled owning `vec::IntoIter` (`vec_intoiter_element_ty`)
/// anywhere among its type components, e.g. as the source of an adapter chain
/// (`Map<vec::IntoIter<u64>, F>`).
fn ty_holds_vec_intoiter<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    ty.walk().any(|arg| {
        arg.as_type().is_some_and(|inner| {
            matches!(inner.kind(), ty::Adt(adt, _) if tcx.item_name(adt.did()).as_str() == "IntoIter")
                && vec_intoiter_element_ty(tcx, inner).is_some()
        })
    })
}

/// rustc's own byte offsets of the four state fields of a modeled
/// `alloc::vec::IntoIter<T>` (`vec_intoiter_element_ty`): `buf` (the allocation
/// base), `ptr` (the next element), `cap` (the capacity in elements) and `end`
/// (one past the last element). The bridge's `vec::IntoIter` state IS this
/// layout: the intercepted constructor, `next`, the identity `into_iter`, the
/// iterator-chain source and the drop all read and write these offsets. At
/// `-O2`/`-O3` rustc's MIR inliner builds the iterator itself
/// (`IntoIter { buf, phantom, cap, alloc, ptr, end }`, an aggregate stored at
/// these offsets) and moves it by value, so any other layout would make the
/// bridge read rustc's `cap` as the buffer. The physical field order is NOT the
/// declaration order (on this host `buf@0, ptr@8, cap@16, end@24`), so it is read
/// from rustc, never assumed.
#[derive(Clone, Copy)]
struct VecIntoIterLayout {
    buf: u64,
    ptr: u64,
    cap: u64,
    end: u64,
}

impl VecIntoIterLayout {
    /// The four state lanes with their trust-ir types, for a whole-state copy.
    fn lanes(self) -> [(u64, TrustIrTy); 4] {
        [
            (self.buf, TrustIrTy::Ptr),
            (self.ptr, TrustIrTy::Ptr),
            (self.cap, TrustIrTy::I64),
            (self.end, TrustIrTy::Ptr),
        ]
    }
}

/// Read [`VecIntoIterLayout`] from rustc's layout of `ty`, failing closed unless
/// it is a single-variant struct with the Global allocator whose `buf`/`ptr`/
/// `end` are pointer-width pointer scalars and `cap` a pointer-width integer.
fn vec_intoiter_layout<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<VecIntoIterLayout, String> {
    let cx = LayoutCx(tcx);
    let outer = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("[TCG-VEC-INTOITER-LAYOUT] layout of {ty:?}: {e:?}"))?;
    let ty::Adt(adt, args) = ty.kind() else {
        return Err(format!("[TCG-VEC-INTOITER-LAYOUT] {ty:?} is not a struct"));
    };
    if !adt.is_struct() || !matches!(outer.variants, rustc_abi::Variants::Single { .. }) {
        return Err(format!(
            "[TCG-VEC-INTOITER-LAYOUT] {ty:?} is not a single-variant struct"
        ));
    }
    let field = |name: &str| -> Result<(rustc_middle::ty::layout::TyAndLayout<'tcx>, u64), String> {
        let index = adt
            .non_enum_variant()
            .fields
            .iter()
            .position(|f| f.name.as_str() == name)
            .ok_or_else(|| format!("[TCG-VEC-INTOITER-LAYOUT] {ty:?} has no field `{name}`"))?;
        Ok((outer.field(&cx, index), outer.fields.offset(index).bytes()))
    };
    // The genuine IntoIter's allocator parameter must itself be Global.
    // Peeling arbitrary generic ADTs can turn a custom ZST allocator
    // Custom<Global> into a false Global witness.
    let global = args.len() == 2
        && matches!(args.type_at(1).kind(), ty::Adt(allocator, _)
            if Some(allocator.did()) == tcx.lang_items().global_alloc_ty());
    let (allocator, _) = field("alloc")?;
    if !global || allocator.size.bytes() != 0 {
        return Err(format!(
            "[TCG-VEC-INTOITER-LAYOUT] {ty:?} uses a custom allocator; the modeled iterator \
             frees through the Global allocator"
        ));
    }
    let scalar = |layout: rustc_middle::ty::layout::TyAndLayout<'tcx>, pointer: bool| {
        layout.size.bytes() == 8
            && layout.align.bytes() == 8
            && match layout.backend_repr {
                rustc_abi::BackendRepr::Scalar(scalar) => match scalar.primitive() {
                    rustc_abi::Primitive::Pointer(..) => pointer,
                    rustc_abi::Primitive::Int(integer, _) => {
                        !pointer && integer.size().bytes() == 8
                    }
                    _ => false,
                },
                _ => false,
            }
    };
    let (buf, buf_off) = field("buf")?;
    let (ptr, ptr_off) = field("ptr")?;
    let (cap, cap_off) = field("cap")?;
    let (end, end_off) = field("end")?;
    let mut offsets = [buf_off, ptr_off, cap_off, end_off];
    offsets.sort_unstable();
    let disjoint = offsets.windows(2).all(|pair| pair[0] + 8 <= pair[1]);
    if !outer.is_sized()
        || !disjoint
        || offsets[3] + 8 > outer.size.bytes()
        || !scalar(buf, true)
        || !scalar(ptr, true)
        || !scalar(cap, false)
        || !scalar(end, true)
    {
        return Err(format!(
            "[TCG-VEC-INTOITER-LAYOUT] {ty:?} ({} bytes) has buf@{buf_off} ptr@{ptr_off} \
             cap@{cap_off} end@{end_off}; the modeled state needs four disjoint \
             pointer-width scalar leaves",
            outer.size.bytes()
        ));
    }
    Ok(VecIntoIterLayout {
        buf: buf_off,
        ptr: ptr_off,
        cap: cap_off,
        end: end_off,
    })
}

/// The bridge's `vec::Drain<T>` models — the `Vec::drain` constructor
/// (`lower_vec_drain`), the intercepted `next` and the drop
/// (`lower_vec_drain_drop`) — drop no element: the drop only moves the kept
/// tail back and restores the drained Vec's length. std's `Drain` drops every
/// drained element no pull yielded (a `for` loop's `break`, a single `next()`,
/// an unused drain). A `T` that needs drop therefore fails closed here, at
/// whichever of the three the program reaches first; `vec_drain_element_ty`'s
/// class-1 arm admits such a `T` (a `Drop` newtype of one scalar).
fn refuse_droppable_drain_element<'tcx>(
    tcx: TyCtxt<'tcx>,
    element_ty: Ty<'tcx>,
) -> Result<(), String> {
    if element_ty.needs_drop(tcx, ty::TypingEnv::fully_monomorphized()) {
        return Err(format!(
            "[TCG-DRAIN-ELEMENT-DROP] a vec::Drain<{element_ty:?}> whose element needs drop: \
             this backend's Drain drops none of the drained elements no pull yielded; \
             failing closed rather than leaking them"
        ));
    }
    Ok(())
}

/// Recognize `alloc::vec::Drain<T>` (from `Vec::drain(range)`) for a scalar element.
/// Same `"::vec::"`-segment gate as `vec_intoiter_element_ty` (disjoint from
/// `String::Drain` / `vec_deque::Drain` / `HashMap::Drain`).
fn vec_drain_element_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    let did = adt.did();
    // Untrimmed/no-visible printer: classifier-path rendering must not
    // trigger the visible-universe decode (~3.4 ms first-use; the first-item
    // warmup class). All consumers are module-segment substring matches,
    // identical in the def-path rendering.
    let path = rustc_middle::ty::print::with_no_visible_paths!(tcx.def_path_str(did));
    // (`std_def_is_interceptable`: a local `vec::Drain` is never modeled.)
    if !(std_def_is_interceptable(tcx, did)
        && tcx.item_name(did).as_str() == "Drain"
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        && is_real_alloc_or_std_def(tcx, did)
        && path.contains("::vec::")
        && !path.contains("deque"))
    {
        return None;
    }
    // `Drain<'a, T, A>`: the TYPE arguments are `[T, A]`. The modeled drop reads
    // and writes the drained `Vec<T, A>` through the Global `Vec` header
    // (`real_vec_string_header_layout`), as `vec_element_ty` requires; a custom
    // allocator's Drain is std's own code end to end.
    let mut types = args.types();
    let element_ty = types.next()?;
    if !matches!(types.next().map(|a| a.kind()), Some(ty::Adt(allocator, _))
        if Some(allocator.did()) == tcx.lang_items().global_alloc_ty())
    {
        return None;
    }
    // Class 1 (a single scalar lane) OR class 2 (a no-Drop aggregate image). The
    // element class drives BOTH the `next` yield and the DROP interception, and
    // getting `None` here is what previously made std's own
    // `<vec::Drain<P> as Drop>::drop` a required root. Class 2 requires
    // `!needs_drop`, so the drop interception's "no per-element drop is owed"
    // premise holds for it exactly as it does for a scalar.
    match rust_ty_to_trust_ir_ty(tcx, element_ty) {
        Ok(t) if t.bit_width().is_some() => {}
        _ if vec_struct_element_admissible(tcx, element_ty) => {}
        _ => return None,
    }
    Some(element_ty)
}

/// rustc's own byte offsets of the state of a modeled `alloc::vec::Drain<T>`
/// (`vec_drain_element_ty`): the cursor over the drained range that is still
/// unyielded, `iter.ptr` and `iter.end_or_len` (the past-the-end pointer, since
/// `T` is not zero-sized), the drained Vec's address `vec`, and the kept tail,
/// `tail_start` and `tail_len`.
///
/// The bridge's `vec::Drain` state IS std's: the constructor writes std's
/// `Vec::drain` values (and sets the Vec's length to the range start before the
/// Drain exists, as std does, so a leaked Drain leaves exactly `[..start]`),
/// `next` advances `iter.ptr`, the identity `into_iter` copies all five words,
/// and the drop applies std's `Drop` transition. A Drain either side built is
/// therefore a valid Drain for the other: one LLVM-compiled code built and
/// passed, returned or wrapped to the bridge, or one the bridge built and
/// returned, passed, wrapped or leaked to LLVM-compiled code or std's drop glue.
/// The physical field order is not the declaration order (on this host
/// `iter.ptr@0, iter.end_or_len@8, vec@16, tail_start@24, tail_len@32`), so it
/// is read from rustc, never assumed.
#[derive(Clone, Copy)]
struct VecDrainLayout {
    iter_ptr: u64,
    iter_end: u64,
    vec: u64,
    tail_start: u64,
    tail_len: u64,
}

impl VecDrainLayout {
    /// The five state words with their trust-ir types, for a whole-state copy in
    /// the 64-bit model (`usize` is `I64`; its consumers `require_64bit_model`).
    fn lanes(self) -> [(u64, TrustIrTy); 5] {
        [
            (self.iter_ptr, TrustIrTy::Ptr),
            (self.iter_end, TrustIrTy::Ptr),
            (self.vec, TrustIrTy::Ptr),
            (self.tail_start, TrustIrTy::I64),
            (self.tail_len, TrustIrTy::I64),
        ]
    }
}

/// Read [`VecDrainLayout`] from rustc's layout of `ty`, a `vec::Drain` whose
/// identity the caller established (`vec_drain_element_ty`, or the destination
/// of an intercepted `Vec::drain`), failing closed (`[TCG-VEC-DRAIN-LAYOUT]`)
/// unless it is a single-variant
/// struct over the Global allocator whose five words are disjoint
/// pointer-width scalars (pointers for the cursor and `vec`, integers for the
/// tail) that together are its whole size, whose `iter` is the real
/// `core::slice::Iter` (two words, its whole size), whose element is not
/// zero-sized, and whose `vec` points at a `Vec` with the bridge's checked
/// header (`real_vec_string_header_layout`).
fn vec_drain_layout<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<VecDrainLayout, String> {
    use rustc_middle::ty::layout::TyAndLayout;
    let cx = LayoutCx(tcx);
    let env = ty::TypingEnv::fully_monomorphized();
    let outer = tcx
        .layout_of(env.as_query_input(ty))
        .map_err(|e| format!("[TCG-VEC-DRAIN-LAYOUT] layout of {ty:?}: {e:?}"))?;
    // `Drain<'a, T, A>`: the TYPE arguments are `[T, A]`.
    let ty::Adt(_, args) = ty.kind() else {
        return Err(format!("[TCG-VEC-DRAIN-LAYOUT] {ty:?} is not a struct"));
    };
    let mut types = args.types();
    let element_ty = types.next();
    let global = matches!(types.next().map(|a| a.kind()), Some(ty::Adt(allocator, _))
        if Some(allocator.did()) == tcx.lang_items().global_alloc_ty());
    let (Some(element_ty), true) = (element_ty, global) else {
        return Err(format!(
            "[TCG-VEC-DRAIN-LAYOUT] {ty:?} is not a vec::Drain over the Global allocator"
        ));
    };
    let field =
        |layout: TyAndLayout<'tcx>, name: &str| -> Result<(TyAndLayout<'tcx>, u64), String> {
            let ty::Adt(adt, _) = layout.ty.kind() else {
                return Err(format!(
                    "[TCG-VEC-DRAIN-LAYOUT] {ty:?}: `{:?}` is not a struct",
                    layout.ty
                ));
            };
            if !adt.is_struct() || !matches!(layout.variants, rustc_abi::Variants::Single { .. }) {
                return Err(format!(
                    "[TCG-VEC-DRAIN-LAYOUT] {ty:?}: `{:?}` is not a single-variant struct",
                    layout.ty
                ));
            }
            let index = adt
                .non_enum_variant()
                .fields
                .iter()
                .position(|f| f.name.as_str() == name)
                .ok_or_else(|| {
                    format!(
                        "[TCG-VEC-DRAIN-LAYOUT] {ty:?}: `{:?}` has no field `{name}`",
                        layout.ty
                    )
                })?;
            Ok((
                layout.field(&cx, index),
                layout.fields.offset(index).bytes(),
            ))
        };
    let width = tcx.data_layout.pointer_size().bytes();
    let word = |layout: TyAndLayout<'tcx>, pointer: bool| {
        layout.size.bytes() == width
            && layout.align.bytes() == width
            && match layout.backend_repr {
                rustc_abi::BackendRepr::Scalar(scalar) => match scalar.primitive() {
                    rustc_abi::Primitive::Pointer(..) => pointer,
                    rustc_abi::Primitive::Int(integer, _) => {
                        !pointer && integer.size().bytes() == width
                    }
                    _ => false,
                },
                _ => false,
            }
    };
    let (iter, iter_off) = field(outer, "iter")?;
    let real_slice_iter = matches!(iter.ty.kind(), ty::Adt(adt, _)
        if Some(adt.did()) == tcx.get_diagnostic_item(rustc_span::Symbol::intern("SliceIter")));
    if !real_slice_iter || !iter.is_sized() || iter.size.bytes() != 2 * width {
        return Err(format!(
            "[TCG-VEC-DRAIN-LAYOUT] {ty:?}: its `iter` is `{:?}` ({} bytes), not the real \
             two-word core::slice::Iter the bridge's cursor drives",
            iter.ty,
            iter.size.bytes()
        ));
    }
    let (iter_ptr, iter_ptr_off) = field(iter, "ptr")?;
    let (iter_end, iter_end_off) = field(iter, "end_or_len")?;
    let (vec, vec_off) = field(outer, "vec")?;
    let (tail_start, tail_start_off) = field(outer, "tail_start")?;
    let (tail_len, tail_len_off) = field(outer, "tail_len")?;
    // `end_or_len` holds the past-the-end POINTER only for a sized, non-ZST `T`.
    let (element_size, _) = element_layout_size_align(tcx, element_ty)?;
    if element_size == 0 {
        return Err(format!(
            "[TCG-VEC-DRAIN-LAYOUT] {ty:?}: a zero-sized element keeps a length, not an end \
             pointer, in `iter.end_or_len`"
        ));
    }
    // The `vec` word must address a `Vec<T>` whose header the bridge reads and
    // writes as `{ cap, ptr, len }` at rustc's offsets.
    let vec_ty = match vec.ty.kind() {
        ty::Adt(_, nonnull_args) if nonnull_args.len() == 1 => nonnull_args.type_at(0),
        _ => {
            return Err(format!(
                "[TCG-VEC-DRAIN-LAYOUT] {ty:?}: its `vec` is `{:?}`, not a NonNull<Vec<T>>",
                vec.ty
            ));
        }
    };
    if real_vec_string_header_layout(tcx, vec_ty)?.is_none() {
        return Err(format!(
            "[TCG-VEC-DRAIN-LAYOUT] {ty:?}: its `vec` addresses `{vec_ty:?}`, not a Vec whose \
             header the bridge models"
        ));
    }
    let layout = VecDrainLayout {
        iter_ptr: iter_off + iter_ptr_off,
        iter_end: iter_off + iter_end_off,
        vec: vec_off,
        tail_start: tail_start_off,
        tail_len: tail_len_off,
    };
    let mut offsets = layout.lanes().map(|(offset, _)| offset);
    offsets.sort_unstable();
    let disjoint = offsets.windows(2).all(|pair| pair[0] + width <= pair[1]);
    // Five disjoint words that fill the whole struct leave no room for state the
    // model does not maintain.
    if !outer.is_sized()
        || outer.size.bytes() != 5 * width
        || !disjoint
        || offsets[4] + width > outer.size.bytes()
        || !word(iter_ptr, true)
        || !word(iter_end, true)
        || !word(vec, true)
        || !word(tail_start, false)
        || !word(tail_len, false)
    {
        return Err(format!(
            "[TCG-VEC-DRAIN-LAYOUT] {ty:?} ({} bytes) has iter.ptr@{} iter.end_or_len@{} \
             vec@{} tail_start@{} tail_len@{}; the modeled state needs five disjoint \
             pointer-width scalar words filling the whole value",
            outer.size.bytes(),
            layout.iter_ptr,
            layout.iter_end,
            layout.vec,
            layout.tail_start,
            layout.tail_len
        ));
    }
    Ok(layout)
}

/// A `<[T]>::windows(n)` (overlapping, fixed-length) or `chunks(n)` (non-overlapping,
/// last may be short) sub-slice iterator.
#[derive(Clone, Copy, PartialEq)]
enum SliceStrideIter {
    Windows,      // overlapping, fixed len n, advance 1, from front
    Chunks,       // non-overlapping, len min(n, remaining), from front (last may be short)
    ChunksExact,  // non-overlapping full chunks only (short remainder DROPPED), from front
    RChunks,      // non-overlapping, from the END (first-from-front may be short)
    RChunksExact, // non-overlapping full chunks only, from the END
}

impl SliceStrideIter {
    /// std's field names for this iterator, in declaration order. The state is
    /// exactly these fields: `Windows { v: &[T], size: NonZero<usize> }`,
    /// `Chunks`/`RChunks { v: &[T], chunk_size: usize }` and
    /// `ChunksExact`/`RChunksExact { v: &[T], rem: &[T], chunk_size: usize }`.
    fn std_fields(self) -> &'static [&'static str] {
        match self {
            SliceStrideIter::Windows => &["v", "size"],
            SliceStrideIter::Chunks | SliceStrideIter::RChunks => &["v", "chunk_size"],
            SliceStrideIter::ChunksExact | SliceStrideIter::RChunksExact => {
                &["v", "rem", "chunk_size"]
            }
        }
    }

    /// The refinement spec's view of this constructor's state.
    fn ctor_kind(self) -> trust_cg_verify::mir_semantics::StrideIterCtorKind {
        use trust_cg_verify::mir_semantics::StrideIterCtorKind;
        match self {
            SliceStrideIter::Windows | SliceStrideIter::Chunks | SliceStrideIter::RChunks => {
                StrideIterCtorKind::Whole
            }
            SliceStrideIter::ChunksExact => StrideIterCtorKind::ChunksExact,
            SliceStrideIter::RChunksExact => StrideIterCtorKind::RChunksExact,
        }
    }
}

/// rustc's own byte offsets of a modeled slice STRIDE iterator's state
/// (`slice_stride_iter_element_ty`; the fields are [`SliceStrideIter::std_fields`]).
/// The bridge's stride-iterator state IS this layout: the intercepted constructor,
/// `next` and `remainder` read and write exactly the words std's own bodies read.
/// At `-O2`/`-O3` rustc's MIR inliner exposes those bodies as field projections
/// of the iterator local after an intercepted constructor CALL —
/// `chunks_exact(n).count()` becomes `PtrMetadata(_3.0) / _3.2`, and an inlined
/// `RChunksExact::next` moves `_3.0`/`_3.1`/`_3.2` out and splits them — and it
/// builds the state itself where it inlines the constructor
/// (`Chunks { v, chunk_size }`). Until 2026-10-04 the bridge wrote a private
/// `{ ptr@0, end@8, n@16, rem_data@24, rem_len@32 }` cursor instead, so those
/// projections read its end pointer as `v.len` and its remainder length as
/// `chunk_size`: `[1u8, 2, 3].chunks_exact(2).count()` returned 80 or 96 at
/// `-O2`/`-O3` where LLVM returns 1, and a `rchunks_exact(2)` loop read freed
/// stack. The offsets are read from rustc, never assumed.
#[derive(Clone, Copy)]
struct SliceStrideIterLayout {
    /// `v: &[T]`, the part of the slice not yet yielded: its data pointer and length.
    v_data: u64,
    v_len: u64,
    /// `rem: &[T]`'s data pointer and length (`ChunksExact`/`RChunksExact` only).
    rem: Option<(u64, u64)>,
    /// `chunk_size: usize` (`Windows`: `size: NonZero<usize>`).
    size: u64,
}

/// Read [`SliceStrideIterLayout`] from rustc's layout of `ty`, failing closed
/// unless it is a single-variant struct whose fields are EXACTLY
/// [`SliceStrideIter::std_fields`] (a state field the bridge does not write would
/// be read by std's bodies, inlined or called, without ever having been written),
/// each `&[T]` a (pointer, pointer-width integer) scalar pair and the size a
/// pointer-width integer scalar, every lane disjoint and inside the value.
fn slice_stride_iter_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    kind: SliceStrideIter,
) -> Result<SliceStrideIterLayout, String> {
    let cx = LayoutCx(tcx);
    let outer = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("[TCG-STRIDE-ITER-LAYOUT] layout of {ty:?}: {e:?}"))?;
    let ty::Adt(adt, _) = ty.kind() else {
        return Err(format!("[TCG-STRIDE-ITER-LAYOUT] {ty:?} is not a struct"));
    };
    let expected = kind.std_fields();
    let invalid_shape = || {
        format!(
            "[TCG-STRIDE-ITER-LAYOUT] {ty:?} is not a sized single-variant struct with exactly \
             the fields {expected:?}; the bridge writes only those, so any other state would be \
             read without having been written"
        )
    };
    // `non_enum_variant` asserts on enums: reject the unsupported ADT first.
    if !adt.is_struct() {
        return Err(invalid_shape());
    }
    let fields = &adt.non_enum_variant().fields;
    if !matches!(outer.variants, rustc_abi::Variants::Single { .. })
        || !outer.is_sized()
        || fields.len() != expected.len()
        || !fields
            .iter()
            .zip(expected)
            .all(|(f, name)| f.name.as_str() == *name)
    {
        return Err(invalid_shape());
    }
    let word = tcx.data_layout.pointer_size().bytes();
    let word_int = |primitive: rustc_abi::Primitive| match primitive {
        rustc_abi::Primitive::Int(integer, _) => integer.size().bytes() == word,
        _ => false,
    };
    let field = |index: usize| (outer.field(&cx, index), outer.fields.offset(index).bytes());
    // `&[T]`: a (data pointer, `usize` length) scalar pair.
    let slice_lanes = |index: usize| -> Option<(u64, u64)> {
        let (layout, base) = field(index);
        let pair = crate::scalar_pair::view(layout.backend_repr)?;
        let (data, len) = (pair.a, pair.b);
        if !matches!(data.primitive(), rustc_abi::Primitive::Pointer(_))
            || !word_int(len.primitive())
            || layout.size.bytes() != 2 * word
            || layout.fields.count() != 2
        {
            return None;
        }
        Some((base, base + pair.second_offset(&tcx).bytes()))
    };
    let size_lane = |index: usize| -> Option<u64> {
        let (layout, base) = field(index);
        (layout.size.bytes() == word
            && matches!(layout.backend_repr, rustc_abi::BackendRepr::Scalar(scalar)
                if word_int(scalar.primitive())))
        .then_some(base)
    };
    let v = slice_lanes(0);
    let (rem, size) = if expected.len() == 3 {
        (slice_lanes(1).map(Some), size_lane(2))
    } else {
        (Some(None), size_lane(1))
    };
    let (Some((v_data, v_len)), Some(rem), Some(size)) = (v, rem, size) else {
        return Err(format!(
            "[TCG-STRIDE-ITER-LAYOUT] {ty:?}: a slice field is not a (pointer, usize) pair or the \
             size is not a pointer-width integer"
        ));
    };
    let mut lanes = vec![v_data, v_len, size];
    if let Some((rem_data, rem_len)) = rem {
        lanes.extend([rem_data, rem_len]);
    }
    lanes.sort_unstable();
    let disjoint = lanes.windows(2).all(|pair| pair[0] + word <= pair[1]);
    let end = lanes.last().map_or(0, |last| last + word);
    if !disjoint || end > outer.size.bytes() {
        return Err(format!(
            "[TCG-STRIDE-ITER-LAYOUT] {ty:?} ({} bytes) has overlapping or out-of-range state lanes \
             {lanes:?}",
            outer.size.bytes()
        ));
    }
    Ok(SliceStrideIterLayout {
        v_data,
        v_len,
        rem,
        size,
    })
}

/// Recognize `core::slice::Windows<'a, T>` / `Chunks<'a, T>` (from `<[T]>::windows(n)`
/// / `chunks(n)`) for a scalar element `T`. The iterator yields `&[T]` sub-slices; its
/// item is a FAT slice pointer (no element is loaded), but we gate to a scalar-width
/// `T` so the stride is a single power-of-two lane. `def_path_str` yields only the leaf
/// name for these ADTs, so gate on crate + exact item name (`ChunksMut`/`ChunksExact`/
/// `RChunks`/… have distinct item names and fall through).
fn slice_stride_iter_element_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<(SliceStrideIter, Ty<'tcx>)> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    let did = adt.did();
    let kind = match tcx.item_name(did).as_str() {
        "Windows" => SliceStrideIter::Windows,
        "Chunks" => SliceStrideIter::Chunks,
        "ChunksExact" => SliceStrideIter::ChunksExact,
        "RChunks" => SliceStrideIter::RChunks,
        "RChunksExact" => SliceStrideIter::RChunksExact,
        _ => return None,
    };
    // (`std_def_is_interceptable`: a local stride iterator is never modeled.)
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !is_real_core_or_std_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return None;
    }
    let element_ty = args.types().next()?;
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, element_ty).ok()?;
    if trust_ir_ty.bit_width().is_none() {
        return None;
    }
    Some((kind, element_ty))
}

/// `true` when `ty` is core's `Windows`/`Chunks`/`ChunksExact`/`RChunks`/
/// `RChunksExact` (any element type) and every value of it is in std's own
/// representation: a modeled iterator whose layout certificate
/// ([`slice_stride_iter_layout`]) holds, or one whose element the bridge does
/// not model (no bridge code writes or reads its state; std's bodies own it).
/// Then std's own bodies — the trait methods the
/// bridge does not intercept (`count`, `nth`, `last`, `size_hint`, `next_back`,
/// `__iterator_get_unchecked`, the default `fold`/`try_fold`, adapter and `Zip`
/// bodies over it) — are correct over it and are LIVE: the real-body
/// iterator-source predicates ([`ty_mentions_real_body_iterator_source`],
/// [`iterator_spine_has_real_body_source`]) answer `true` for it, which routes
/// terminals and `try_fold` to those bodies and keeps
/// `is_dead_std_iterator_reduction_body` from trapping them. A modeled iterator
/// whose certificate FAILS answers `false` (its methods are refused instead).
fn slice_stride_iter_state_is_std<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    if let Some((kind, _)) = slice_stride_iter_element_ty(tcx, ty) {
        return slice_stride_iter_layout(tcx, ty, kind).is_ok();
    }
    std_slice_stride_iter_kind(tcx, ty).is_some()
}

/// Recognize core's own `Windows` / `Chunks` / `ChunksExact` / `RChunks` /
/// `RChunksExact` for ANY element type, by crate identity plus the exact item
/// name (`ChunksMut`/`ArrayWindows`/… have distinct names and fall through), and
/// return the kind and element type. A local definition is never matched
/// (`std_def_is_interceptable`).
fn std_slice_stride_iter_kind<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<(SliceStrideIter, Ty<'tcx>)> {
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    let did = adt.did();
    let kind = match tcx.item_name(did).as_str() {
        "Windows" => SliceStrideIter::Windows,
        "Chunks" => SliceStrideIter::Chunks,
        "ChunksExact" => SliceStrideIter::ChunksExact,
        "RChunks" => SliceStrideIter::RChunks,
        "RChunksExact" => SliceStrideIter::RChunksExact,
        _ => return None,
    };
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !is_real_core_or_std_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return None;
    }
    Some((kind, args.types().next()?))
}

/// `<[T]>::windows(&self, n)` / `chunks` / `chunks_exact` / `rchunks` /
/// `rchunks_exact` — the sub-slice iterator constructors. Panic as std does on
/// `n == 0`, then write std's own initial state into the (memory-backed)
/// destination at rustc's offsets ([`SliceStrideIterLayout`]), exactly as std's
/// `new` builds it over the receiver `s = { data, len }`:
///   * `Windows`/`Chunks`/`RChunks`: `v = s`, size `n`.
///   * `ChunksExact`: `r = len % n`; `v = s[..len - r]`, `rem = s[len - r..]`.
///   * `RChunksExact`: `r = len % n`; `v = s[r..]`, `rem = s[..r]`.
///
/// A non-`&[T]` receiver, an unmodeled destination, or a non-scalar element
/// falls through / fails closed.
fn lower_slice_stride_iter_ctor<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    let method = callee_item_name_str(ctx.tcx, callee.def_id());
    if !matches!(
        method.as_str(),
        "windows" | "chunks" | "chunks_exact" | "rchunks" | "rchunks_exact"
    ) {
        return Ok(false);
    }
    if call.args.len() != 2 || !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let Some((kind, element_ty)) = slice_stride_iter_element_ty(ctx.tcx, dest_ty) else {
        return Ok(false);
    };
    let element_ty = ctx.monomorphize_ty(element_ty);
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    if fat_ptr_slice_or_str_pointee(ctx.tcx, self_ty).is_none() {
        return Ok(false);
    }
    let layout = slice_stride_iter_layout(ctx.tcx, dest_ty, kind)?;
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    let (Operand::Copy(place) | Operand::Move(place)) = &call.args[0].node else {
        return Err("slice stride-iter self argument is not a place operand".to_owned());
    };
    if !place.projection.is_empty() {
        return Err("slice stride-iter self argument uses a projected place".to_owned());
    }
    if !local_is_memory_backed(ctx, place.local) {
        return Err("slice stride-iter self argument is not a memory-backed slice".to_owned());
    }
    let data = load_fat_ptr_data(ctx, block, place.local)?;
    let len = load_fat_ptr_meta(ctx, block, place.local)?;
    let data = coerce_to_plain_ptr(ctx, block, data);
    let len = coerce_to_i64(ctx, block, len);
    let n = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let n = coerce_to_i64(ctx, block, n);

    // std panics ("chunk/window size must be non-zero") when the stride is 0; a
    // stride-0 state would never advance (an INFINITE LOOP instead of the required
    // panic). Trap here BEFORE the `*_exact` `URem` by `n` and before storing the
    // state.
    // TRANSLATION-VALIDATION CAPTURE (Phase P1): the `n != 0` check and every
    // instruction of the work block up to its successor branch (the state
    // computation and its stores) are folded and refined against
    // `stride_iter_ctor_spec`; the `data`/`len`/`n` values are computed OUTSIDE
    // the captured slice, so the fold names them symbolically as the shared
    // inputs. See `push_stride_iter_refinement` + the `mir_to_trust_ir` drain.
    let refine = ctx.refinements_active();
    let icmp_capture_start = block.body.len();
    let n_zero = emit_i64_const(ctx, block, 0);
    let n_nonzero = emit_i64_icmp(ctx, block, ICmpOp::Ne, n, n_zero);
    let icmp_nodes: Vec<InstrNode> = if refine {
        block.body[icmp_capture_start..].to_vec()
    } else {
        Vec::new()
    };
    let stride_fail =
        std_panic_route::fail_target(ctx, body, call, std_panic_route::StdFailure::Constant)?;
    let stride_work_id = ctx.fresh_block_id();
    block.body.push(InstrNode::new(Inst::CondBr {
        cond: n_nonzero,
        then_target: stride_work_id,
        then_args: Vec::new(),
        else_target: stride_fail,
        else_args: Vec::new(),
    }));
    let mut stride_work = Block::new(stride_work_id);
    let block = &mut stride_work;

    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "slice stride-iter destination is not memory-backed".to_owned())?
        .ptr;
    // std's `new`: the yielded part `v` and, for the `*_exact` kinds, the fixed
    // `rem` (`n >= 1` here, so the `URem` is defined).
    let (v_data, v_len, rem) = match kind {
        SliceStrideIter::Windows | SliceStrideIter::Chunks | SliceStrideIter::RChunks => {
            (data, len, None)
        }
        SliceStrideIter::ChunksExact => {
            let rem_len = emit_i64_binop(ctx, block, TrustIrBinOp::URem, len, n);
            let fst_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, rem_len);
            let rem_data = emit_element_addr(ctx, block, data, fst_len, size);
            (data, fst_len, Some((rem_data, rem_len)))
        }
        SliceStrideIter::RChunksExact => {
            let rem_len = emit_i64_binop(ctx, block, TrustIrBinOp::URem, len, n);
            let snd_data = emit_element_addr(ctx, block, data, rem_len, size);
            let snd_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, rem_len);
            (snd_data, snd_len, Some((data, rem_len)))
        }
    };
    let v_data_addr = iter_field_addr(ctx, block, dest_slot, layout.v_data);
    emit_typed_store(block, v_data_addr, TrustIrTy::Ptr, v_data);
    let v_len_addr = iter_field_addr(ctx, block, dest_slot, layout.v_len);
    emit_usize_field_store(ctx, block, v_len_addr, v_len);
    let size_addr = iter_field_addr(ctx, block, dest_slot, layout.size);
    emit_usize_field_store(ctx, block, size_addr, n);
    let rem_lanes = match (layout.rem, rem) {
        (Some((rem_data_off, rem_len_off)), Some((rem_data, rem_len))) => {
            let rem_data_addr = iter_field_addr(ctx, block, dest_slot, rem_data_off);
            emit_typed_store(block, rem_data_addr, TrustIrTy::Ptr, rem_data);
            let rem_len_addr = iter_field_addr(ctx, block, dest_slot, rem_len_off);
            emit_usize_field_store(ctx, block, rem_len_addr, rem_len);
            Some((rem_data_off, rem_len_off))
        }
        (None, None) => None,
        _ => {
            return Err(format!(
                "[TCG-STRIDE-ITER-LAYOUT] {dest_ty:?}: the `rem` field and the constructor kind \
                 disagree"
            ));
        }
    };

    // TRANSLATION-VALIDATION CAPTURE (cont.): `block` now aliases `stride_work`,
    // which holds exactly the state computation and its stores.
    if refine {
        let mut emitted = icmp_nodes;
        emitted.extend(block.body.iter().cloned());
        push_stride_iter_refinement(
            ctx,
            &emitted,
            kind,
            data,
            len,
            n,
            dest_slot,
            mem_refine::StrideIterStateOffsets {
                v_data: layout.v_data,
                v_len: layout.v_len,
                size: layout.size,
                rem: rem_lanes,
            },
            size,
        );
    }

    emit_call_successor(block, call.target);
    ctx.extra_blocks.push(stride_work);
    Ok(true)
}

/// `<slice::{Windows, Chunks, ChunksExact, RChunks, RChunksExact}<T> as
/// Iterator>::next(&mut self) -> Option<&[T]>` over std's own state
/// ([`SliceStrideIterLayout`]; `v = { data, len }`, size `n`), as std's `next`:
///   * Windows: `Some(v[..n])` while `n <= len`, then `v = v[1..]`.
///   * Chunks: `Some(v[..min(len, n)])` while `len != 0`, then `v = v[min(len, n)..]`.
///   * ChunksExact: `Some(v[..n])` while `n <= len`, then `v = v[n..]`.
///   * RChunks: with `i = len.saturating_sub(n)`, `Some(v[i..])` while `len != 0`,
///     then `v = v[..i]`.
///   * RChunksExact: with `i = len - n`, `Some(v[i..])` while `n <= len`, then
///     `v = v[..i]`.
///
/// On `None` the state is unchanged. The yielded fat `&[T]` is built through the
/// niche `OptionPayload::Slice` (its data pointer carries the `Some`/`None`
/// discriminant).
fn lower_slice_stride_iter_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    iter_ty: Ty<'tcx>,
    kind: SliceStrideIter,
    element_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!(
            "slice stride-iter next with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("slice stride-iter next into projected destination".to_owned());
    }
    let layout = slice_stride_iter_layout(ctx.tcx, iter_ty, kind)?;
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let v_data_addr = iter_field_addr(ctx, block, slot_ptr, layout.v_data);
    let data = emit_typed_load(ctx, block, v_data_addr, TrustIrTy::Ptr);
    let v_len_addr = iter_field_addr(ctx, block, slot_ptr, layout.v_len);
    let len = emit_usize_field_load(ctx, block, v_len_addr);
    let size_addr = iter_field_addr(ctx, block, slot_ptr, layout.size);
    let n = emit_usize_field_load(ctx, block, size_addr);

    // `(cond, yielded data, yielded len, remaining data, remaining len)`.
    let (cond, yield_data, yield_len, rest_data, rest_len) = match kind {
        SliceStrideIter::Windows => {
            let cond = emit_i64_icmp(ctx, block, ICmpOp::Ule, n, len);
            let one = emit_i64_const(ctx, block, 1);
            let rest_data = emit_element_addr(ctx, block, data, one, size);
            let rest_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, one);
            (cond, data, n, rest_data, rest_len)
        }
        SliceStrideIter::Chunks => {
            let zero = emit_i64_const(ctx, block, 0);
            let cond = emit_i64_icmp(ctx, block, ICmpOp::Ne, len, zero);
            let len_le_n = emit_i64_icmp(ctx, block, ICmpOp::Ule, len, n);
            let chunk = emit_i64_select(ctx, block, len_le_n, len, n);
            let rest_data = emit_element_addr(ctx, block, data, chunk, size);
            let rest_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, chunk);
            (cond, data, chunk, rest_data, rest_len)
        }
        SliceStrideIter::ChunksExact => {
            let cond = emit_i64_icmp(ctx, block, ICmpOp::Ule, n, len);
            let rest_data = emit_element_addr(ctx, block, data, n, size);
            let rest_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, n);
            (cond, data, n, rest_data, rest_len)
        }
        SliceStrideIter::RChunks => {
            let zero = emit_i64_const(ctx, block, 0);
            let cond = emit_i64_icmp(ctx, block, ICmpOp::Ne, len, zero);
            let len_le_n = emit_i64_icmp(ctx, block, ICmpOp::Ule, len, n);
            let len_minus_n = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, n);
            let idx = emit_i64_select(ctx, block, len_le_n, zero, len_minus_n);
            let chunk_data = emit_element_addr(ctx, block, data, idx, size);
            let chunk_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, idx);
            (cond, chunk_data, chunk_len, data, idx)
        }
        SliceStrideIter::RChunksExact => {
            let cond = emit_i64_icmp(ctx, block, ICmpOp::Ule, n, len);
            let idx = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, n);
            let chunk_data = emit_element_addr(ctx, block, data, idx, size);
            (cond, chunk_data, n, data, idx)
        }
    };

    // Advance only on `Some`; on `None` std leaves `v` as it was.
    let new_data = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::Ptr,
            cond,
            then_val: rest_data,
            else_val: data,
        })
        .with_result(new_data),
    );
    emit_typed_store(block, v_data_addr, TrustIrTy::Ptr, new_data);
    let new_len = emit_i64_select(ctx, block, cond, rest_len, len);
    emit_usize_field_store(ctx, block, v_len_addr, new_len);

    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Slice {
            data: yield_data,
            len: yield_len,
        },
    )?;

    emit_call_successor(block, call.target);
    Ok(())
}

/// The REAL sysroot `core::str::Chars` ADT, by DEF-ID IDENTITY — no crate-name
/// string anywhere in the derivation.
///
/// `is_str_chars_ty` used to be `item_name == "Chars"` plus a crate-NAME string
/// compare against `"core" | "std"`. That is SPELLED provenance: an ordinary rlib
/// built `--crate-name core` declaring its own `pub struct Chars` satisfies it, and
/// the bridge then writes its own `{ptr, end}` cursor over that crate's type (and
/// correspondingly trips the `[TCG-STRIDE-ITER-METHOD]` guard that exists only to
/// protect a cursor the bridge wrote).
///
/// `str::chars` carries the `str_chars` DIAGNOSTIC ITEM, a diagnostic-item name is
/// UNIQUE across the whole crate graph — a second definition of the same name is
/// `DuplicateDiagnosticItemInCrate`, a hard error, not a silent shadow
/// (`compiler/rustc_passes/src/diagnostic_items.rs`) — and `Chars` is by
/// construction the ADT that function RETURNS. So this is the one `Chars` reachable
/// from the sysroot's own `str::chars`, whatever anybody's crate is named. It is
/// also stronger than resolving the crate by `CrateNum` and then disambiguating
/// with `item_name == "Chars"`, which a second `Chars` inside the real `core`/`std`
/// could collide with.
///
/// Returns `None` if the sysroot does not carry the item (then every caller falls
/// through, nothing is intercepted, and the stride-iterator guard does not fire —
/// the fail-closed direction).
fn real_str_chars_adt_did(tcx: TyCtxt<'_>) -> Option<rustc_hir::def_id::DefId> {
    let chars_fn = tcx.get_diagnostic_item(rustc_span::Symbol::intern("str_chars"))?;
    let out = tcx
        .fn_sig(chars_fn)
        .instantiate_identity()
        .skip_binder()
        .output();
    match out.kind() {
        ty::Adt(adt, _) => Some(adt.did()),
        _ => None,
    }
}

/// Whether `did` is the REAL `core::str::Chars::as_str` — an IDENTITY test.
///
/// Three conjuncts, each load-bearing:
///   * `std_def_is_interceptable` — SELF-HOST RULE: when the crate under
///     compilation defines `Chars` itself, nothing is intercepted;
///   * `inherent_impl_of_assoc` — the callee must be an associated item of an
///     INHERENT impl. This is what a free function cannot be: the refuting witness
///     (`--crate-name hashbrown`, `pub fn as_str(&Chars) -> &str`) is a free
///     function and fails here, and no crate can write an inherent impl for a
///     foreign type at all (coherence, E0116);
///   * the impl's SELF TYPE must be `real_str_chars_adt_did` — the `Chars` the
///     sysroot's own `str::chars` returns, not an ADT named `Chars`.
///
/// The leaf-name test (`as_str`) is kept as the cheap prefilter it is; it is not
/// the provenance argument and must not be read as one.
fn is_real_str_chars_as_str_callee(tcx: TyCtxt<'_>, did: rustc_hir::def_id::DefId) -> bool {
    if !std_def_is_interceptable(tcx, did) {
        return false;
    }
    if tcx
        .opt_item_name(did)
        .map(|n| n.as_str().to_owned())
        .as_deref()
        != Some("as_str")
    {
        return false;
    }
    let Some(impl_did) = tcx.inherent_impl_of_assoc(did) else {
        return false;
    };
    // `skip_normalization`: an inherent impl's self type is a concrete ADT
    // application (`Chars<'a>`), with no projection to normalize — and this is a
    // DEF-ID comparison, which normalization cannot change.
    let self_ty = tcx
        .type_of(impl_did)
        .instantiate_identity()
        .skip_normalization();
    let ty::Adt(adt, _) = self_ty.kind() else {
        return false;
    };
    Some(adt.did()) == real_str_chars_adt_did(tcx)
}

/// Recognize `core::str::Chars<'a>` (from `<str>::chars()`). Yields `char` by value.
///
/// Keyed on DEF-ID IDENTITY (`real_str_chars_adt_did`), NOT on
/// `item_name == "Chars"` plus a crate-name string as it was before 2026-09-25 —
/// see that helper for the executed witness against the name test. This is a strict
/// NARROWING of every site that uses it: an upstream ADT merely NAMED `Chars` in a
/// crate merely NAMED `core`/`std` no longer has its `chars()` constructor
/// intercepted with the bridge's `{ptr, end}` cursor (it is lowered generally, or
/// refused), and correspondingly no longer trips the `[TCG-STRIDE-ITER-METHOD]`
/// guard that exists only to protect a cursor the bridge wrote.
fn is_str_chars_ty(tcx: TyCtxt<'_>, ty: Ty<'_>) -> bool {
    let ty::Adt(adt, _) = ty.kind() else {
        return false;
    };
    let did = adt.did();
    // (`std_def_is_interceptable`: a local `str::Chars` is never modeled.)
    // Two independent identity fixes met here and the ADT compare is the stronger
    // one, so it is what survives. `real_str_chars_adt_did` derives the real
    // `Chars` from the RETURN TYPE of the real `str::chars` (itself found through
    // the `str_chars` diagnostic item), so no name is involved at any step. The
    // alternative resolved the crate by `CrateNum` identity and then still
    // disambiguated with `item_name == "Chars"`, which a second `Chars` inside
    // the real `core`/`std` could collide with. Both are sound against
    // `--crate-name` spoofing; only this one is sound against a name collision.
    std_def_is_interceptable(tcx, did) && Some(did) == real_str_chars_adt_did(tcx)
}

/// One word of a cursor the bridge writes ITSELF: the declaration NAME std gives
/// it, the byte OFFSET the bridge's model stores it at, and its expected byte
/// SIZE. A `CursorWord` is a claim about std's representation that
/// `adt_field_certificate` either PROVES from rustc's own layout or refuses.
struct CursorWord {
    name: &'static str,
    offset: u64,
    size: u64,
}

/// Prove, from rustc's own layout, that a std struct's representation is EXACTLY
/// the record the bridge's cursor model writes. Returns `None` on agreement and
/// `Some(reason)` naming the FIRST disagreement.
///
/// Four conjuncts, each of which has a concrete way to be false:
///   * the struct's own size/align match the bridge's slot;
///   * every named word exists, sits at the byte offset the bridge writes it at,
///     and has the byte size the bridge writes there;
///   * **every OTHER field is ZERO-SIZED.** This is the conjunct that keeps the
///     certificate from being a coincidence test: `ChunksExact` is
///     `{ v, rem, chunk_size }` where the bridge writes `{ v, size }`, so an
///     unaccounted-for non-ZST state field is precisely the failure mode, and it
///     must refuse rather than be ignored;
///   * anything rustc cannot lay out refuses.
///
/// Field NAMES are used as the lookup key, which is sound here and is not a
/// provenance test: the ADT's identity is established by the CALLER (a diagnostic
/// item / def-id compare), and within a struct of proven identity the declaration
/// name is the stable way to ask rustc for a field's layout offset (the same
/// technique `StepBy`'s `field_index_by_name` arm uses). A rename or a reorder
/// makes this certificate FAIL, which is the fail-closed direction.
fn adt_field_certificate<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    what: &str,
    size: u64,
    align: u64,
    words: &[CursorWord],
) -> Option<String> {
    let env = ty::TypingEnv::fully_monomorphized();
    let layout = match tcx.layout_of(env.as_query_input(ty)) {
        Ok(l) => l,
        Err(e) => return Some(format!("{what}: rustc cannot lay out `{ty:?}` ({e:?})")),
    };
    if layout.size.bytes() != size || layout.align.bytes() != align {
        return Some(format!(
            "{what}: std lays `{ty:?}` out as size {} align {} where the bridge's cursor \
             model is size {size} align {align}",
            layout.size.bytes(),
            layout.align.bytes()
        ));
    }
    let ty::Adt(adt, args) = ty.kind() else {
        return Some(format!("{what}: `{ty:?}` is not an ADT"));
    };
    if adt.is_enum() || adt.is_union() {
        return Some(format!("{what}: `{ty:?}` is not a plain struct"));
    }
    let variant = adt.non_enum_variant();
    for w in words {
        let Some((idx, field)) = variant
            .fields
            .iter_enumerated()
            .find(|(_, f)| f.name.as_str() == w.name)
        else {
            return Some(format!(
                "{what}: std's `{ty:?}` has no `{}` field, so the word the bridge writes at \
                 byte {} is not the one std reads",
                w.name, w.offset
            ));
        };
        let got = layout.fields.offset(idx.as_usize()).bytes();
        if got != w.offset {
            return Some(format!(
                "{what}: std puts `{ty:?}::{}` at byte {got}, the bridge writes it at byte {}",
                w.name, w.offset
            ));
        }
        let fty = field.ty(tcx, *args).skip_normalization();
        match tcx.layout_of(env.as_query_input(fty)) {
            Ok(fl) if fl.size.bytes() == w.size => {}
            Ok(fl) => {
                return Some(format!(
                    "{what}: std's `{ty:?}::{}` is {} bytes, the bridge writes {} there",
                    w.name,
                    fl.size.bytes(),
                    w.size
                ));
            }
            Err(e) => return Some(format!("{what}: rustc cannot lay out `{fty:?}` ({e:?})")),
        }
    }
    for (idx, field) in variant.fields.iter_enumerated() {
        if words.iter().any(|w| w.name == field.name.as_str()) {
            continue;
        }
        let fty = field.ty(tcx, *args).skip_normalization();
        match tcx.layout_of(env.as_query_input(fty)) {
            Ok(fl) if fl.size.bytes() == 0 => {}
            Ok(fl) => {
                return Some(format!(
                    "{what}: std's `{ty:?}` carries a {}-byte field `{}` (declaration index {}) \
                     that the bridge's cursor model never maintains",
                    fl.size.bytes(),
                    field.name,
                    idx.as_usize()
                ));
            }
            Err(e) => return Some(format!("{what}: rustc cannot lay out `{fty:?}` ({e:?})")),
        }
    }
    None
}

/// THE LAYOUT-AGREEMENT CERTIFICATE for the bridge's `Chars` cursor — the
/// argument that withdraws the `[TCG-STRIDE-ITER-METHOD]` guard for `Chars`.
/// Returns `None` when the bridge's `{ ptr@0, end@8 }` cursor is
/// PROVABLY byte-identical to std's own representation of `Chars`, and
/// `Some(reason)` naming the first disagreement otherwise.
///
/// # Why this licenses falling through to the real std body
///
/// The guard exists because a value the BRIDGE wrote can be read by code that
/// assumes STD's representation — a non-generic std body living in the frozen
/// rlib (LLVM-compiled), or a generic std body the bridge itself lowers from real
/// MIR using rustc's layout offsets. Both are correct exactly when the two
/// representations coincide, and that is a decidable question about rustc's
/// layout, not a question about the callee's crate, its name, or its locality
/// (both of those were measured insufficient; see the guard).
///
/// For `Chars` the bridge's model is std's FULL state, not a reduced one:
/// `lower_str_chars_ctor` writes `ptr = data`, `end = data + len`, and
/// `lower_str_chars_next` advances `ptr` by the decoded UTF-8 width — exactly the
/// transition std's `Chars::next` applies to `self.iter`. So if the words live
/// where std keeps them, a bridge-written cursor IS a std `Chars` at every
/// observable point and std's own `size_hint` / `next_back` / `count` / `as_str`
/// read it correctly.
///
/// The stride families (`windows`/`chunks`/`chunks_exact`/`rchunks`/
/// `rchunks_exact`) have their own certificate, `slice_stride_iter_layout`:
/// until 2026-10-04 the bridge wrote a REDUCED private cursor for them that no
/// placement check could repair (it never maintained `ChunksExact::rem`), and
/// they were refused unconditionally; it now writes std's own state at rustc's
/// offsets.
///
/// # What this does NOT prove (read before widening it)
///
/// It proves PLACEMENT, SIZE, and the ABSENCE of unmodeled state; it does not
/// prove that `slice::Iter::end_or_len` MEANS the past-the-end pointer. That is
/// std's documented invariant for a non-ZST element (for a ZST it holds a length
/// instead), so the element type is pinned to `u8` below — and it is an
/// assumption the bridge's own `next` model already rests on today, so falling
/// through adds no new one. A semantic flip that kept the name, the type and the
/// offset would pass this certificate; the differential fixture
/// `fix_chars_cursor_crosses_to_std.rs` is what would catch that.
fn chars_cursor_layout_disagreement<'tcx>(tcx: TyCtxt<'tcx>, chars_ty: Ty<'tcx>) -> Option<String> {
    let word = tcx.data_layout.pointer_size().bytes();
    let end_offset = slice_iter_end_offset();
    if word != end_offset {
        return Some(format!(
            "this target's pointer is {word} bytes, but the bridge's cursor model puts \
             the second word at byte {end_offset}"
        ));
    }
    // (1) `Chars` is `{ iter: slice::Iter<'_, u8> }` — one pointer-pair field at 0.
    if let Some(why) = adt_field_certificate(
        tcx,
        chars_ty,
        "Chars",
        2 * word,
        word,
        &[CursorWord {
            name: "iter",
            offset: 0,
            size: 2 * word,
        }],
    ) {
        return Some(why);
    }
    // (2) that field must BE the real `core::slice::Iter<'_, u8>` (IDENTITY, via
    //     the `SliceIter` diagnostic item inside `slice_iter_element_ty`), and its
    //     element must be `u8` — std's `end_or_len` is the past-the-end POINTER
    //     only for a non-ZST element, and the bridge decodes BYTES.
    let iter_ty = match field_ty_of(tcx, chars_ty, 0) {
        Ok(t) => t,
        Err(e) => return Some(format!("Chars: {e}")),
    };
    match slice_iter_element_ty(tcx, iter_ty) {
        Some(elem) if elem == tcx.types.u8 => {}
        Some(elem) => {
            return Some(format!(
                "Chars: its cursor iterates `{elem:?}`, not `u8`, so the bridge's byte-stride \
                 UTF-8 decode does not describe std's state"
            ));
        }
        None => {
            return Some(format!(
                "Chars: field 0 `{iter_ty:?}` is not the real `core::slice::Iter` (the \
                 `SliceIter` diagnostic item), so its two words are not the ones the bridge \
                 models"
            ));
        }
    }
    // (3) the two cursor words, where the bridge writes them, and NO third state
    //     field (the `ChunksExact` failure mode).
    adt_field_certificate(
        tcx,
        iter_ty,
        "slice::Iter<u8>",
        2 * word,
        word,
        &[
            CursorWord {
                name: "ptr",
                offset: 0,
                size: word,
            },
            CursorWord {
                name: "end_or_len",
                offset: end_offset,
                size: word,
            },
        ],
    )
}

/// `true` when `ty` is the real `core::str::Chars` AND the bridge's cursor model
/// for it is PROVABLY std's own representation
/// (`chars_cursor_layout_disagreement`). This is the single predicate that
/// licenses handing a bridge-written `Chars` to a body the bridge did not
/// synthesize — std's own, LLVM-compiled or lowered from real MIR — because under
/// it the two read the same words.
///
/// The certificate has exactly three consumers and they must move together. Two
/// call THIS predicate; the first calls `chars_cursor_layout_disagreement` directly
/// because it needs the failing conjunct's TEXT for its refusal, so grep for both
/// names when changing any of this:
///   * the `[TCG-STRIDE-ITER-METHOD]` guard in `lower_direct_call_terminator_lanes`
///     (via `chars_cursor_layout_disagreement`), which stops refusing;
///   * `lower_iter_try_fold`, which stops hard-erroring and falls through to the
///     real `try_fold`/`try_rfold` body (a `next`/`next_back` loop);
///   * `is_dead_std_iterator_reduction_body`, which must then STOP trapping those
///     bodies — a fall-through onto a `ud2` stub is a runtime SIGILL, which is the
///     exact fail-open the `step_by`/`scan`/`flatten`/`enumerate`/`by_ref`
///     exclusions there already exist to prevent. Mutation-proved: with the
///     exclusion deleted and one certified-Chars `try_fold` body forced
///     unlowerable, `fix_chars_cursor_crosses_to_std` compiles and dies with
///     exit 133 (SIGILL) at its `skip_while` row; with it, the compile
///     fail-closes on that body instead.
///
/// NOTE ON OVER- vs UNDER-MATCHING at the third site: it keys on the SELF type,
/// read from `instance.args.types().next()` for a trait-default method and from the
/// impl's `type_of` for a method defined in the `Chars` impl itself (`size_hint`,
/// whose instance carries only an erased lifetime). Matching MORE than
/// intended there only suppresses a trap stub, which is the fail-closed direction.
/// Matching LESS is the dangerous direction. For `try_fold`/`try_rfold` it is
/// aligned by construction: `lower_iter_try_fold` falls through only for an EXACT
/// certified `Chars` receiver, which is the same set this test accepts. An adapter
/// merely WRAPPING a `Chars` (`Rev<Chars>`, `SkipWhile<Chars, P>`) is in NEITHER
/// set — its `try_fold` interception still hard-errors, so its body is never
/// called. The guard also lets every OTHER method of a certified `Chars` reach
/// std's body (`size_hint` is not intercepted); the impl-`type_of` half of the
/// third site covers those, pinned by
/// `tests::certified_chars_impl_methods_are_not_dead_bodies`.
fn is_certified_chars_cursor<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    is_str_chars_ty(tcx, ty) && chars_cursor_layout_disagreement(tcx, ty).is_none()
}

/// `<str>::chars(&self) -> Chars` — the `for c in s.chars()` code-point iterator
/// constructor. Build a `{ ptr@0, end@8 }` byte cursor over the `&str`'s UTF-8 bytes
/// (our model replaces std's `Chars(slice::Iter<u8>)`; `next` decodes). Any callee
/// other than core's inherent `<str>::chars` falls through to the general call
/// path, which lowers its real body: a user free fn `chars(s: &str) -> Chars` or
/// an extension-trait method `MyChars::chars(s)` has the same name, argument and
/// result types, and its body is not `s.chars()`. A non-`&str` receiver /
/// non-`Chars` destination falls through too.
fn lower_str_chars_ctor<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if callee_item_name_str(ctx.tcx, callee.def_id()).as_str() != "chars"
        || !is_std_inherent_method_on(ctx.tcx, callee.def_id(), |self_ty| self_ty.is_str())
    {
        return Ok(false);
    }
    if call.args.len() != 1 || !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    if !is_str_chars_ty(ctx.tcx, dest_ty) {
        return Ok(false);
    }
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    if fat_ptr_slice_or_str_pointee(ctx.tcx, self_ty).is_none() {
        return Ok(false);
    }
    let (Operand::Copy(place) | Operand::Move(place)) = &call.args[0].node else {
        return Err("str chars self is not a place operand".to_owned());
    };
    if !place.projection.is_empty() || !local_is_memory_backed(ctx, place.local) {
        return Err("str chars self is not a memory-backed &str".to_owned());
    }
    let data = load_fat_ptr_data(ctx, block, place.local)?;
    let len = load_fat_ptr_meta(ctx, block, place.local)?;
    let data = coerce_to_plain_ptr(ctx, block, data);
    let len = coerce_to_i64(ctx, block, len);
    let end = emit_element_addr(ctx, block, data, len, 1);

    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "str chars destination is not memory-backed".to_owned())?
        .ptr;
    let ptr_addr = iter_field_addr(ctx, block, dest_slot, 0);
    emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, data);
    let end_addr = iter_field_addr(ctx, block, dest_slot, slice_iter_end_offset());
    emit_typed_store(block, end_addr, TrustIrTy::Ptr, end);

    emit_call_successor(block, call.target);
    Ok(true)
}

/// `<Chars as ..>::as_str(&self) -> &str` — the remaining, not-yet-yielded UTF-8 of
/// a `str::chars()` cursor (`alloc::string::Drain::as_str` forwards to it).
///
/// # Why this one method may be modeled when the guard refuses the rest
///
/// `lower_str_chars_ctor` writes the bridge's OWN cursor — `{ ptr@0, end@8 }`, two
/// raw byte pointers — where std has `Chars(slice::Iter<'a, u8>)`. Every method
/// whose answer needs anything std's layout holds and this one does not (a
/// `DoubleEnded` back cursor, an `ExactSize` count) reads garbage, which is why the
/// `[TCG-STRIDE-ITER-METHOD]` guard below refuses all of them. `as_str` is the
/// exception by construction: std defines it as the remainder of the underlying
/// byte slice reinterpreted as `str`, and the remainder is EXACTLY `[ptr, end)` —
/// the same two words `next` consumes and advances. The value is therefore fully
/// determined by the cursor the bridge itself wrote, with nothing derived from
/// std's field order, and it stays correct after any number of `next` calls
/// because `next` maintains `ptr` on a code-point boundary.
///
/// The `&str` is `{ data: ptr, len: end - ptr }`, stored through the same
/// `store_fat_ptr_slot` the `ChunksExact::remainder` arm uses.
///
/// Returns `Ok(false)` — fall through, do not intercept — unless ALL of: the CALLEE
/// is the real `core::str::Chars::as_str` by DEF-ID IDENTITY
/// (`is_real_str_chars_as_str_callee`; a crate merely NAMED `core`/`hashbrown`
/// exporting a same-named function does NOT satisfy it, and a name-keyed version of
/// this conjunct was refuted with an executed witness — see the comment at the test
/// itself), the receiver is that same `Chars` (`is_str_chars_ty`, likewise
/// identity-keyed, and carrying the SELF-HOST RULE: when the crate under
/// compilation DEFINES `Chars`, nothing is intercepted and the real body is
/// lowered), and the destination is an unprojected `&str` local. That keeps the
/// widening to the one shape argued above; `size_hint`, `rev`, `next_back`,
/// `as_bytes` and the rest stay refused by the guard.
fn lower_str_chars_as_str<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if callee_item_name_str(ctx.tcx, callee.def_id()).as_str() != "as_str" {
        return Ok(false);
    }
    // THE CALLEE MUST BE THE REAL `core::str::Chars::as_str`, PROVED BY DEF-ID
    // IDENTITY — NOT merely named `as_str`, and NOT merely defined in a crate
    // SPELLED `core`/`alloc`/`hashbrown`.
    //
    // `opt_item_name` above is a NAME and the receiver check below is a TYPE;
    // neither says who DEFINED this function. Without a provenance conjunct a
    // user's own `fn as_str(it: &Chars) -> &str` has its BODY DISCARDED and
    // replaced by the bridge's cursor remainder — measured 2026-09-25, a silent
    // wrong answer rather than a refusal:
    //
    //     fn as_str<'a>(_it: &core::str::Chars<'a>) -> &'a str { "SENTINEL" }
    //     let mut it = "abcdef".chars(); it.next(); hash(as_str(&it))
    //
    //   LLVM:                   hash("SENTINEL") = 15763585847121849335
    //   with no such conjunct:  hash("bcdef")    = 11585393754820217191
    //
    // THE FIRST ATTEMPT AT THIS CONJUNCT WAS `is_std_collection_method_callee`,
    // AND IT WAS REFUTED WITH AN EXECUTED WITNESS. That helper is
    // `!is_local() && crate_name(krate) in {std, core, alloc, hashbrown}` — a
    // STRING COMPARE against a name the person compiling chooses. Rebuilding the
    // same `fake.rs` as an rlib with `--crate-name hashbrown` satisfies it, and
    // the patched backend then returned 11585393754820217191 — the identical wrong
    // hash the author's own mutation proof produced by DELETING the guard — with
    // the guard fully present. A named `[TCG-STRIDE-ITER-METHOD]` refusal became a
    // silently wrong program.
    //
    // `is_real_str_chars_as_str_callee` is that provenance test done by identity:
    // an INHERENT impl (a free function, which every such witness is, cannot be
    // one, and no crate may write an inherent impl on a foreign type — E0116)
    // whose SELF TYPE is the very `Chars` the sysroot's `str::chars` returns
    // (`real_str_chars_adt_did`, via the unique `str_chars` diagnostic item).
    // Pinned fixtures: `tests/bridge_corpus/fix_user_as_str_not_intercepted.rs`
    // (a LOCAL `as_str`) and the `--crate-name hashbrown` witness of the
    // acceptance battery. Delete this conjunct and both COMPILE and diverge from
    // LLVM, which the differential gate reports as a hard failure (mutation-proved
    // 2026-09-25). Do not weaken it back to a name/receiver test, and do not
    // substitute a crate-name test for it.
    if !is_real_str_chars_as_str_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    if call.args.len() != 1 || !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let peeled = match self_ty.kind() {
        ty::Ref(_, t, _) | ty::RawPtr(t, _) => ctx.monomorphize_ty(*t),
        _ => self_ty,
    };
    if !is_str_chars_ty(ctx.tcx, peeled) {
        return Ok(false);
    }
    // The destination must be a `&str` fat pointer — `str`'s element carrier is
    // `u8`, and a `Chars::as_str` returning anything else is a shape we have not
    // established.
    let dest_rust_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    if fat_ptr_slice_or_str_pointee(ctx.tcx, dest_rust_ty) != Some(ctx.tcx.types.u8)
        || !matches!(
            dest_rust_ty.kind(),
            ty::Ref(_, inner, _) | ty::RawPtr(inner, _) if inner.is_str()
        )
    {
        return Ok(false);
    }
    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let ptr_addr = iter_field_addr(ctx, block, slot_ptr, 0);
    let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
    let end_addr = iter_field_addr(ctx, block, slot_ptr, slice_iter_end_offset());
    let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
    let ptr_int = emit_ptr_to_int(ctx, block, ptr);
    let end_int = emit_ptr_to_int(ctx, block, end);
    let len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: end_int,
            rhs: ptr_int,
        })
        .with_result(len),
    );
    store_fat_ptr_slot(ctx, block, call.destination.local, ptr, len)?;
    emit_call_successor(block, call.target);
    Ok(true)
}

/// `<Chars as Iterator>::next(&mut self) -> Option<char>` — decode one UTF-8 code
/// point at `ptr` and advance by its byte length, or `None` at `ptr == end`. The four
/// candidate bytes are read GUARDED (each address `Select`ed to the iterator slot
/// when it is `>= end`, so a 1-byte char at the buffer tail — and the exhausting call
/// — never reads out of bounds; only the `< n` bytes feed the decode). The code point
/// is assembled branch-free (inverse of `String::push`'s encode), and yielded through
/// the niche `Option<char>` scalar payload.
fn lower_str_chars_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 || !call.destination.projection.is_empty() {
        return Err("str Chars::next shape".to_owned());
    }
    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let ptr_addr = iter_field_addr(ctx, block, slot_ptr, 0);
    let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
    let end_addr = iter_field_addr(ctx, block, slot_ptr, slice_iter_end_offset());
    let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
    let end_int = emit_ptr_to_int(ctx, block, end);

    // Small IR emit helpers (take ctx/block by param → no capture/borrow issues).
    let konst =
        |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, v: i128| emit_i64_const(ctx, block, v);
    let binop = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, op, a, b| {
        emit_i64_binop(ctx, block, op, a, b)
    };
    let icmp = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, op, a, b| {
        let r = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::ICmp {
                op,
                ty: TrustIrTy::I64,
                lhs: a,
                rhs: b,
            })
            .with_result(r),
        );
        r
    };
    let sel_i64 = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, cond, t, f| {
        let r = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: TrustIrTy::I64,
                cond,
                then_val: t,
                else_val: f,
            })
            .with_result(r),
        );
        r
    };

    // Read the four candidate bytes GUARDED: address `Select`ed to the slot when
    // `ptr+k >= end` (a safe, in-bounds alloca read whose garbage byte is never used).
    let read_byte =
        |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, k: i128| -> (ValueId, ValueId) {
            let kv = emit_i64_const(ctx, block, k);
            let addr = emit_element_addr(ctx, block, ptr, kv, 1);
            let addr_int = emit_ptr_to_int(ctx, block, addr);
            let inb = {
                let r = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Ult,
                        ty: TrustIrTy::I64,
                        lhs: addr_int,
                        rhs: end_int,
                    })
                    .with_result(r),
                );
                r
            };
            let safe = {
                let r = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::Ptr,
                        cond: inb,
                        then_val: addr,
                        else_val: slot_ptr,
                    })
                    .with_result(r),
                );
                r
            };
            let raw = emit_typed_load(ctx, block, safe, TrustIrTy::I8);
            let byte = {
                let r = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::ZExt,
                        src_ty: TrustIrTy::I8,
                        dst_ty: TrustIrTy::I64,
                        operand: raw,
                    })
                    .with_result(r),
                );
                r
            };
            (inb, byte)
        };
    let (cond, b0) = read_byte(ctx, block, 0);
    let (_ib1, b1) = read_byte(ctx, block, 1);
    let (_ib2, b2) = read_byte(ctx, block, 2);
    let (_ib3, b3) = read_byte(ctx, block, 3);

    // Byte-length class from the lead byte (well-formed UTF-8): <0x80 →1, <0xE0 →2,
    // <0xF0 →3, else →4.
    let k80 = konst(ctx, block, 0x80);
    let ke0 = konst(ctx, block, 0xE0);
    let kf0 = konst(ctx, block, 0xF0);
    let lt80 = icmp(ctx, block, ICmpOp::Slt, b0, k80);
    let lte0 = icmp(ctx, block, ICmpOp::Slt, b0, ke0);
    let ltf0 = icmp(ctx, block, ICmpOp::Slt, b0, kf0);
    let (n1, n2, n3, n4) = (
        konst(ctx, block, 1),
        konst(ctx, block, 2),
        konst(ctx, block, 3),
        konst(ctx, block, 4),
    );
    let n34 = sel_i64(ctx, block, ltf0, n3, n4);
    let n234 = sel_i64(ctx, block, lte0, n2, n34);
    let n = sel_i64(ctx, block, lt80, n1, n234);

    // Continuation groups `byte & 0x3F` and lead-payload masks.
    let m3f = konst(ctx, block, 0x3F);
    let g1 = binop(ctx, block, TrustIrBinOp::And, b1, m3f);
    let g2 = binop(ctx, block, TrustIrBinOp::And, b2, m3f);
    let g3 = binop(ctx, block, TrustIrBinOp::And, b3, m3f);
    let s6 = konst(ctx, block, 6);
    let s12 = konst(ctx, block, 12);
    let s18 = konst(ctx, block, 18);
    // cp2 = ((b0 & 0x1F) << 6) | g1
    let m1f = konst(ctx, block, 0x1F);
    let l2 = binop(ctx, block, TrustIrBinOp::And, b0, m1f);
    let l2s = binop(ctx, block, TrustIrBinOp::Shl, l2, s6);
    let cp2 = binop(ctx, block, TrustIrBinOp::Or, l2s, g1);
    // cp3 = ((b0 & 0x0F) << 12) | (g1 << 6) | g2
    let m0f = konst(ctx, block, 0x0F);
    let l3 = binop(ctx, block, TrustIrBinOp::And, b0, m0f);
    let l3s = binop(ctx, block, TrustIrBinOp::Shl, l3, s12);
    let g1s6 = binop(ctx, block, TrustIrBinOp::Shl, g1, s6);
    let cp3a = binop(ctx, block, TrustIrBinOp::Or, l3s, g1s6);
    let cp3 = binop(ctx, block, TrustIrBinOp::Or, cp3a, g2);
    // cp4 = ((b0 & 0x07) << 18) | (g1 << 12) | (g2 << 6) | g3
    let m07 = konst(ctx, block, 0x07);
    let l4 = binop(ctx, block, TrustIrBinOp::And, b0, m07);
    let l4s = binop(ctx, block, TrustIrBinOp::Shl, l4, s18);
    let g1s12 = binop(ctx, block, TrustIrBinOp::Shl, g1, s12);
    let g2s6 = binop(ctx, block, TrustIrBinOp::Shl, g2, s6);
    let cp4a = binop(ctx, block, TrustIrBinOp::Or, l4s, g1s12);
    let cp4b = binop(ctx, block, TrustIrBinOp::Or, cp4a, g2s6);
    let cp4 = binop(ctx, block, TrustIrBinOp::Or, cp4b, g3);
    // cp = select(lt80, b0, select(lte0, cp2, select(ltf0, cp3, cp4)))
    let cp_34 = sel_i64(ctx, block, ltf0, cp3, cp4);
    let cp_234 = sel_i64(ctx, block, lte0, cp2, cp_34);
    let cp = sel_i64(ctx, block, lt80, b0, cp_234);
    // Truncate to the 32-bit `char` payload.
    let cp32 = {
        let r = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::Trunc,
                src_ty: TrustIrTy::I64,
                dst_ty: TrustIrTy::I32,
                operand: cp,
            })
            .with_result(r),
        );
        r
    };

    // Advance `ptr` by `n` bytes on a successful decode; keep it otherwise.
    let advanced = emit_element_addr(ctx, block, ptr, n, 1);
    let new_ptr = {
        let r = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: TrustIrTy::Ptr,
                cond,
                then_val: advanced,
                else_val: ptr,
            })
            .with_result(r),
        );
        r
    };
    emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, new_ptr);

    // Yield `Some(char)` / `None` (niche `Option<char>`).
    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Scalar {
            value: cp32,
            ty: TrustIrTy::I32,
        },
    )?;

    emit_call_successor(block, call.target);
    Ok(())
}

/// CLASS GUARD — a `StepBy` adapter a REAL core `Iterator::next` /
/// `IntoIterator::into_iter` (or any other unintercepted core method) would
/// consume.
///
/// The bridge intercepts the `.step_by(k)` CONSTRUCTOR
/// (`lower_iter_structural_ctor`), which writes core's `StepBy::new` state —
/// `step_minus_one = k-1`, `first_take = true`, and for a countdown `Range`
/// `SpecRangeSetup::setup`'s `end = div_ceil(len, k)` — and its own drivers
/// (`emit_chain_next` for the intercepted `.sum()` / `.fold()` / `.count()` /
/// `.collect()` terminals, `lower_step_by_next` for `next`) read that layout.
/// Those drivers are the validated StepBy surface: the chain drive keeps a
/// running countdown in `step_minus_one` while it runs and leaves std's `k-1`
/// there when it stops (a yield resets it, its exhaustion exit writes it back).
/// History: before the constructor wrote
/// std's layout, a BARE `for` loop's real core `next` iterated
/// `(0..10).step_by(3)` as if `step == 1` (COMPLETE-12: summed 45, not 18).
///
/// So: whenever a real `next` / `into_iter` would consume a chain that CONTAINS
/// a StepBy adapter (any element type, any nesting order), we FAIL CLOSED here
/// rather than run an unvalidated core body over the bridge's drive state. This
/// is the single chokepoint for the general class "the frontend
/// recognizes an iterator's inner shape but drops an outer adapter's
/// construction-side semantics"; a future adapter with the same
/// constructor-preprocessing hazard is vetted by extending this predicate.
///
/// Returns `false` (never an error) for every non-StepBy / unresolved shape, so
/// the faithfully-handled adapters whose real `next` reads plain fields and
/// delegates to the (intercepted) inner `next` — `Range` / `RangeInclusive` /
/// `slice::Iter` / `Rev` / `Take` / `Skip` / `Map` / `Copied` / `Cloned` — are
/// NEVER over-rejected.
fn iter_chain_wraps_stepby<'tcx>(ctx: &MirLoweringCtx<'tcx>, ty: Ty<'tcx>) -> bool {
    matches!(
        resolve_iter_chain(ctx, ty),
        Ok(Some(chain))
            if chain
                .adapters
                .iter()
                .any(|(a, _)| matches!(a.kind, AdapterKind::StepBy { .. }))
    )
}

/// Whether an optimized MIR body still contains a standard-library `StepBy`
/// value. This catches a constructor that rustc inlined before
/// [`lower_iterator_call`] can intercept the original `.step_by()` call.
const STEP_BY_TYPE_SCAN_MAX_DEPTH: usize = 128;
const STEP_BY_TYPE_SCAN_MAX_TYPES: usize = 4096;

fn body_contains_std_step_by<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
) -> Result<bool, String> {
    let mut pending: Vec<(Ty<'tcx>, usize)> = body
        .local_decls
        .iter()
        .map(|decl| (ctx.monomorphize_ty(decl.ty), 0))
        .collect();
    let mut seen = HashSet::new();
    while let Some((current, depth)) = pending.pop() {
        if depth > STEP_BY_TYPE_SCAN_MAX_DEPTH {
            return Err(format!(
                "[TCG-STEPBY-TYPE-SCAN] optimized MIR type graph exceeded the safe \
                 nesting limit of {STEP_BY_TYPE_SCAN_MAX_DEPTH} while checking for a nested \
                 std::iter::StepBy value; failing closed rather than risking an unbounded scan"
            ));
        }
        if !seen.insert(current) {
            continue;
        }
        if seen.len() > STEP_BY_TYPE_SCAN_MAX_TYPES {
            return Err(format!(
                "[TCG-STEPBY-TYPE-SCAN] optimized MIR type graph exceeded the safe \
                 {STEP_BY_TYPE_SCAN_MAX_TYPES}-type traversal budget while checking for a \
                 nested std::iter::StepBy value; failing closed rather than risking an \
                 unbounded scan"
            ));
        }
        let child_depth = depth + 1;
        match current.kind() {
            ty::Adt(adt, args) => {
                if adapter_kind_of(ctx.tcx, adt.did()) == Some(AdapterTag::StepBy) {
                    return Ok(true);
                }
                pending.extend(
                    args.types()
                        .map(|ty| (ctx.monomorphize_ty(ty), child_depth)),
                );
                for variant in adt.variants() {
                    for field in &variant.fields {
                        pending.push((
                            ctx.monomorphize_ty(field.ty(ctx.tcx, *args).skip_normalization()),
                            child_depth,
                        ));
                    }
                }
            }
            ty::Ref(_, inner, _)
            | ty::RawPtr(inner, _)
            | ty::Slice(inner)
            | ty::Array(inner, _) => {
                pending.push((ctx.monomorphize_ty(*inner), child_depth));
            }
            ty::Tuple(fields) => {
                pending.extend(
                    fields
                        .iter()
                        .map(|ty| (ctx.monomorphize_ty(ty), child_depth)),
                );
            }
            ty::Closure(_, args) => {
                pending.extend(
                    args.as_closure()
                        .upvar_tys()
                        .iter()
                        .map(|ty| (ctx.monomorphize_ty(ty), child_depth)),
                );
            }
            ty::Coroutine(_, args) => {
                pending.extend(
                    args.as_coroutine()
                        .upvar_tys()
                        .iter()
                        .map(|ty| (ctx.monomorphize_ty(ty), child_depth)),
                );
            }
            ty::CoroutineClosure(_, args) => pending.push((
                ctx.monomorphize_ty(args.as_coroutine_closure().tupled_upvars_ty()),
                child_depth,
            )),
            _ => {}
        }
    }
    Ok(false)
}

/// Whether this session can inline `StepBy` before the bridge sees its normal
/// constructor/`next` calls. This mirrors the pinned compiler's `Inline` pass
/// enablement order: a final `-Zmir-enable-passes=+/-Inline` override wins,
/// then explicit `-Zinline-mir`, then MIR level 3+. All codegen O1+ modes are
/// rejected as the documented conservative `StepBy` boundary regardless of
/// inliner switches.
fn step_by_mir_may_inline(sess: &rustc_session::Session) -> bool {
    if sess.opts.optimize != rustc_session::config::OptLevel::No {
        return true;
    }
    if let Some((_, enabled)) = sess
        .opts
        .unstable_opts
        .mir_enable_passes
        .iter()
        .rev()
        .find(|(name, _)| name == "Inline")
    {
        return *enabled;
    }
    sess.opts
        .unstable_opts
        .inline_mir
        .unwrap_or_else(|| sess.mir_opt_level() >= 3)
}

/// Try to lower a `Range<T>` / `slice::Iter<T>` iterator call (`into_iter` /
/// `next`). Returns `Ok(true)` if the call was an intercepted iterator method
/// (fully lowered, including its successor branch); `Ok(false)` if it is not one
/// (the caller continues with the general call path); `Err` for an iterator
/// shape this backend does not model (fail closed precisely — never miscompile).
fn lower_iterator_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    let name = name.as_str();

    // SEMANTIC-IDENTITY GATE: every operation synthesized by this interceptor is
    // defined by the standard iterator/range surface. A path-segment match alone
    // (`map`, `sum`, `min_by`, ...) lets a user extension trait or UFCS function
    // on an actual `Range` spoof the name and have its body silently replaced by
    // std semantics. Require the defining crate to be the standard library before
    // considering any name-based recognizer below. Stronger lang/diagnostic-item
    // identity checks remain in place where rustc exposes one.
    // SELF-HOST RULE (`std_def_is_interceptable`): a LOCAL callee is the crate's
    // own iterator surface — lowered from its real MIR, never modeled.
    // THE FIX. This gate used to be a crate-NAME STRING COMPARE, and an ordinary
    // rlib built `--crate-name core` satisfied it: the witness in
    // `real_core_crate`'s doc comment had its real body DISCARDED and its `next`
    // answered from the bridge's slice cursor (`probe=7` against LLVM's
    // `probe=0`). `is_real_std_crate_def` is that same provenance test done by
    // `CrateNum` IDENTITY, anchored on the `sized`/`owned_box`/`start` LANG ITEMS,
    // which no crate can claim without a graph-wide `E0152`.
    if !is_real_std_crate_def(ctx.tcx, callee.def_id())
        || !std_def_is_interceptable(ctx.tcx, callee.def_id())
    {
        return Ok(false);
    }

    // `RangeInclusive::<T>::new(start, end)` — the `start..=end` constructor (the
    // `for i in 1..=n` / `(1..=n).sum()` desugar emits this before `into_iter`).
    // Identified by the `range_inclusive_new` lang item (robust across def
    // paths). We synthesize the 3-field `{ start, end, exhausted: false }` struct
    // directly into the (memory-backed) destination slot at its rustc field
    // offsets, rather than calling the real `new` body (which is trivial but
    // would otherwise force the general aggregate-return call path).
    if Some(callee.def_id()) == ctx.tcx.lang_items().range_inclusive_new_method() {
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        if let Some(index_ty) = range_inclusive_index_ty(ctx.tcx, dest_ty) {
            return lower_range_inclusive_new(ctx, body, block, call, index_ty).map(|()| true);
        }
        return Ok(false);
    }

    // `.flat_map(f)` — BOUNDED shape only (`Range<T>` outer AND inner, same `T`,
    // non-capturing `f`). Like `map`/`filter` we synthesize the adapter value
    // directly (std's `FlatMap::new` layout, `lower_flatmap_bounded_ctor`) rather
    // than call the real constructor; an unmatched shape falls through to the
    // general path and core's real bodies.
    if name == "flat_map" {
        return lower_flatmap_bounded_ctor(ctx, body, block, call);
    }

    // Lazy adapters (`.map(f)` / `.filter(p)`) build a `Map`/`Filter` value that
    // wraps the inner iterator + the closure. We synthesize that adapter state in
    // the destination's (memory-backed) slot rather than calling the real
    // constructor (whose later `next` descends into `Map::next`/`Filter::next` ->
    // `try_fold` machinery this backend cannot lower).
    if name == "map" || name == "filter" {
        return lower_iter_adapter_ctor(ctx, body, block, call, name);
    }

    // Structural adapters (`.copied()` / `.cloned()` / `.rev()` / `.take(n)` /
    // `.skip(n)` / `.step_by(k)` / `.enumerate()`) build a `Copied`/`Rev`/`Take`/…
    // value wrapping the inner iterator (field 0) plus their own state fields. We
    // copy the inner state into the destination slot at field-0 and initialize the
    // adapter's count/index fields, then drive it via the same `emit_chain_next`.
    if matches!(
        name,
        "copied" | "cloned" | "rev" | "take" | "skip" | "step_by" | "enumerate"
    ) {
        // Only intercept when the destination is an adapter chain we fully model;
        // otherwise fall through (e.g. a user method of the same name).
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        // `StepBy` is intentionally supported only at default O0, with MIR
        // inlining disabled. There the explicit core
        // `StepBy::next` call reaches `lower_step_by_next`, whose state model is
        // verified against the bridge constructor. At O1+ rustc may inline
        // `StepBy` methods and read its representation directly; that bypasses
        // the modeled call and is not a stable supported lowering surface.
        //
        // Identify the *result* as std's `StepBy` rather than relying on a
        // modelable chain: an unmodeled source must receive the same clear
        // optimized-level diagnostic at the point that the `StepBy` value is
        // made. Keep the call-level guards below for pre-existing or otherwise
        // unintercepted StepBy values.
        let creates_step_by = matches!(
            dest_ty.kind(),
            ty::Adt(adt, _) if adapter_kind_of(ctx.tcx, adt.did()) == Some(AdapterTag::StepBy)
        );
        if name == "step_by" && step_by_mir_may_inline(ctx.tcx.sess) && creates_step_by {
            return Err("[TCG-STEPBY-OPT-LEVEL] `.step_by()` is supported only at \
                 -Copt-level=0 with default MIR settings (MIR inlining disabled): \
                 optimized std StepBy methods may inline and read \
                 an internal representation the bridge does not model. Failing \
                 closed at iterator construction."
                .to_owned());
        }
        // DESTINATION-IDENTITY GATE. `resolve_iter_chain(dest_ty).is_some()` is
        // satisfied by ANY modelled chain — including a BARE base iterator with no
        // adapter at all — so on its own it does not establish that this call is
        // the adapter constructor its NAME suggests.
        //
        // MEASURED HOLE (2026-09-26, `<alloc::vec::Drain<u8> as Drop>::drop`):
        // `core::mem::take::<slice::Iter<'_, u8>>(&mut self.iter)` satisfies every
        // gate above — item name `take`, defined in the real `core`, interceptable,
        // and a destination (`slice::Iter<u8>`) that resolves as a chain — and was
        // routed into `lower_iter_structural_ctor` as if it were `Iterator::take`.
        // There it survived only because the `&mut` argument happens not to be
        // memory-backed; a memory-backed one would have had EIGHT bytes (the
        // POINTER) copied into a 24-byte `slice::Iter` slot as its inner state,
        // `*src` left un-defaulted, and no count field written (`chain.adapters` is
        // empty for a base iterator, so the `Take` initializer never runs). That is
        // a silently wrong program, not a refusal.
        //
        // `Iterator::take` returns `Take<Self>`, `skip` returns `Skip<Self>`, and so
        // on for every name in this list — no exceptions in the standard surface.
        // So require the destination's OWN outermost ADT to be the adapter this
        // name constructs, by `adapter_kind_of`'s def-path identity (NOT a type
        // name compare). This only ever NARROWS interception: a call that fails it
        // falls through to the general, itself-fail-closed call path and is lowered
        // from its real MIR body.
        let expected_tag = match name {
            "copied" => AdapterTag::Copied,
            "cloned" => AdapterTag::Cloned,
            "rev" => AdapterTag::Rev,
            "take" => AdapterTag::Take,
            "skip" => AdapterTag::Skip,
            "step_by" => AdapterTag::StepBy,
            "enumerate" => AdapterTag::Enumerate,
            _ => unreachable!("gated by the matches! above"),
        };
        let dest_is_that_adapter = matches!(
            dest_ty.kind(),
            ty::Adt(adt, _) if adapter_kind_of(ctx.tcx, adt.did()) == Some(expected_tag)
        );
        if !dest_is_that_adapter {
            return Ok(false);
        }
        if resolve_iter_chain(ctx, dest_ty)?.is_some() {
            return lower_iter_structural_ctor(ctx, body, block, call, name);
        }
        return Ok(false);
    }

    // The `.chain(b)` constructor builds a `Chain<A, B>` = `{ Some(a), Some(b) }`.
    // Like the other adapter constructors we synthesize it directly (copy each
    // sub-iterator's state into its `Option` payload + write the `Some` tags), so
    // the later terminal can drive it through `emit_chain_next`.
    if name == "chain" {
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        if resolve_iter_chain(ctx, dest_ty)?.is_some() {
            return lower_chain_ctor(ctx, body, block, call);
        }
        return Ok(false);
    }

    // The `.zip(b)` constructor builds a `Zip<A, B>` = `{ a, b, index: 0, len }`.
    // We synthesize it directly (copy each sub-iterator's state into its field +
    // compute the `min`-length cursor) so the terminal drives it through the same
    // `emit_chain_next` (a `ChainSource::Zip` yielding the `(&A, &B)` tuple).
    if name == "zip" {
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        if resolve_iter_chain(ctx, dest_ty)?.is_some() {
            return lower_zip_ctor(ctx, body, block, call);
        }
        return Ok(false);
    }

    // Terminal consumers (`.sum()` / `.fold(init, f)` / `.count()`) DRIVE the
    // iterator chain to exhaustion. The real bodies inline to `Iterator::fold` ->
    // `Range/slice/Map/Filter::next` -> `spec_next`/`try_fold`/`cold_path`, none
    // of which this backend lowers, so — like the other iterator entry points — we
    // synthesize the driving loop directly against the (memory-backed) iterator
    // state, calling the user closure through the closure-body symbol.
    if name == "sum" || name == "fold" || name == "count" {
        // When `lower_iter_consumer` cannot model the chain (an UNMODELED adapter such
        // as `Scan`/`FilterMap`, or a `Take`/`Skip` WRAPPING one — `resolve_iter_chain`
        // returns `None` → `Ok(false)`), we must NOT fall through to the general call
        // path: the real `Iterator::{sum,fold,count}` body reaches an `<Adapter>::
        // try_fold` that `is_dead_std_iterator_reduction_body` classifies as dead —
        // a (wrongly-assumed-dead) ud2 stub in a library crate type, a refusal of
        // that body in an executable — which the live reduction then hits at RUNTIME →
        // SIGILL (FUZZ-2 differential: `.filter_map(..).scan(..).take(n).sum()` exited
        // 132 instead of failing closed at O0). Fail closed at COMPILE time instead —
        // the general path never lowers these bodies anyway (they inline to
        // `try_fold`/`spec_next`/`cold_path`), so `Ok(false)` here can only mean a
        // SIGILL-ing (or link-error) binary. A modeled chain returns `Ok(true)`.
        // BOUNDED `flat_map` (`Range<T>` outer AND inner, same `T`, non-capturing
        // `f`): a dedicated two-level driver (`lower_flatmap_bounded_consumer`)
        // BYPASSES `lower_iter_consumer`/`emit_chain_next` entirely — their
        // "≤1 item out per ≤1 item pulled" contract cannot express flat_map's
        // "0..N items out per 1 outer pull". Tried FIRST (it only fires when the
        // self type resolves via `resolve_flatmap_bounded`; every non-FlatMap
        // chain gets `Ok(false)` immediately and falls through unchanged).
        // A chain over a source the bridge leaves to core's real bodies (a
        // `RangeFrom`, or the general `Zip` of a 32-bit target) is the one
        // exception: the general call path lowers those bodies, and the trap
        // exclusion keeps every one whose types mention the source out of the
        // dead-body stubs (`real_body_iterator_receiver` states its limit).
        if real_body_iterator_receiver(ctx, body, call)? {
            return Ok(false);
        }
        if lower_flatmap_bounded_consumer(ctx, body, block, call, name)? {
            return Ok(true);
        }
        // A DIRECT `.sum()` whose selected `Sum` impl is not one the bridge's loop
        // models (a user impl, `impl Sum<Local> for u64`, `Saturating<u128>`), over a
        // chain it DOES model: step aside to the real `Iterator::sum`, which runs that
        // impl's own code (`std_reduction_falls_through`). Before 2026-09-27 the loop
        // replaced such impls with a bare add — a silent miscompile whenever the
        // impl was anything else.
        if name == "sum" {
            if let Some(self_arg) = call.args.first() {
                let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                if std_reduction_falls_through(ctx, body, call, self_ty, false)? {
                    return Ok(false);
                }
            }
        }
        if lower_iter_consumer(ctx, body, block, call, name, false)? {
            return Ok(true);
        }
        return Err(format!(
            "[TCG-ITER-UNMODELED] iterator `{name}` terminal over an unmodeled chain \
             (an unsupported adapter — e.g. scan / filter_map, or take/skip wrapping \
             one): the general `Iterator::{name}` body reaches a trapped `try_fold` \
             stub at runtime; failing closed rather than emitting a SIGILL-ing binary."
        ));
    }

    // `.for_each(f)` — a SIDE-EFFECT terminal (`f: FnMut(Self::Item) -> ()`). Its real
    // body inlines to `Iterator::fold((), ...)` — a unit accumulator the fold consumer
    // rejects — so drive the chain directly, calling `f` per element. Like sum/fold, an
    // unmodeled chain must FAIL CLOSED (the general `for_each` body reaches the same
    // trapped `try_fold` stub → SIGILL), never fall through.
    if name == "for_each" {
        // The real-body exception of the `sum`/`fold`/`count` arm above.
        if real_body_iterator_receiver(ctx, body, call)? {
            return Ok(false);
        }
        if lower_iter_for_each(ctx, body, block, call)? {
            return Ok(true);
        }
        // Refusal per v7/D3 (name the rule, why this program broke it, the ways
        // forward). The refusal itself STAYS — measured on the frozen r3 compiler:
        // falling through is not a fix. The general `for_each` body is
        // `self.fold((), call(f))`; reaching it anyway (e.g. through a fn pointer, for
        // `Map<DecodeUtf16<Cloned<slice::Iter<u16>>>, F>` and bare `DecodeUtf16<..>`) is
        // refused one frame down at the `fold` terminal for the same chain, and for a
        // std adapter whose `fold` is implemented via `try_fold` (`GenericShunt`,
        // `CaseMappingIter` -> `array::IntoIter`) that body bottoms out in a `try_fold`
        // this backend emits as a trap stub in a library crate type (an executable
        // refuses it). An explicit `while let Some(x) = it.next()`
        // over `Map<DecodeUtf16<Cloned<slice::Iter<u16>>>, F>` DOES lower and runs ==
        // LLVM at O0/O3, so option (2) below is a real way forward where the call site
        // is editable. The chain type is named so the reader knows WHICH source/adapter
        // to model.
        let chain_ty = match call.args.first() {
            Some(arg) => match operand_rust_ty(ctx, body, &arg.node) {
                Ok(ty) => format!("{:?}", ctx.monomorphize_ty(ty)),
                Err(_) => "<unresolved>".to_owned(),
            },
            None => "<unresolved>".to_owned(),
        };
        return Err(format!(
            "[TCG-ITER-UNMODELED] iterator `for_each` over an unmodeled chain `{chain_ty}` \
             (an unsupported adapter, or a tuple/owning source): `for_each` is lowered only \
             as a synthesized loop over a chain `resolve_iter_chain` models. The general \
             `Iterator::for_each` body is not a safe fallback: it is `self.fold((), ..)`, \
             whose `fold` terminal is refused for the same chain, and a std adapter whose \
             `fold` goes through `try_fold` (e.g. `GenericShunt`, `array::IntoIter`) reaches \
             a trapped `try_fold` stub at runtime; failing closed rather than emitting a \
             SIGILL-ing binary. Ways forward: (1) model this source/adapter in \
             `resolve_iter_chain` + `emit_chain_next`, so `for_each` over it is driven \
             directly; (2) where the call site is editable, replace `.for_each(f)` with \
             `while let Some(x) = it.next() {{ f(x) }}`, which lowers on the general loop \
             path instead of through `fold`/`try_fold`; (3) build this crate with the LLVM \
             backend (omit `-Zcodegen-backend=trust-ir-cg`)."
        ));
    }

    // `-O3` specializes `<Take<I>>::sum`/`fold` into `<Take<I> as SpecTake>::spec_fold`
    // (and Skip's) — a fold over the adapter receiver `(self, init, closure)`, the
    // same arg shape as an explicit `.fold(init, f)`. The by-name `sum`/`fold` call
    // disappears (inlined), so route the `spec_fold` callee to the SAME consumer
    // driver as a fold: `lower_iter_consumer` resolves the Take/Skip chain from arg-0
    // and drives it, applying the reduction closure (arg-2). If arg-0 is not a chain
    // we model, `lower_iter_consumer` returns `Ok(false)` and this falls through to
    // the fail-closed general path. This makes the collector-required real `spec_fold`
    // body DEAD (never called by the emitted loop) so its dead-body trap stub is
    // never reached at runtime — take/skip reductions then run == LLVM at O3 too.
    // `<Iter as DoubleEndedIterator>::rfold(self, init, f)` — the engine `-O3`
    // inlines `.rev().count()` into: `Rev::count` = `rfold(0, count::plus_one)`.
    // COUNT is direction-independent (it ignores the items), so driving the
    // FORWARD chain's `count` consumer yields the identical value. Any OTHER
    // rfold payload is order-sensitive — FALL THROUGH to the general call path,
    // which lowers the REAL `rfold` body (compilable since the `next_back`
    // NonNull load/store + precondition_check fixes) and so runs the true
    // reverse fold (`.rev().sum()` works exactly this way).
    if name == "rfold" && call.args.len() == 3 {
        if real_body_iterator_receiver(ctx, body, call)? {
            return Ok(false);
        }
        let payload_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[2].node)?);
        if let ty::FnDef(fdef, _) = payload_ty.kind() {
            // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
            if is_real_std_crate_def(ctx.tcx, *fdef)
                && ctx.tcx.def_path_str(*fdef).ends_with("count::plus_one")
            {
                return lower_iter_consumer(ctx, body, block, call, "count", false);
            }
        }
        // A peelable STD sum/product glue (`.rev().map(f).sum()` inlines to
        // `rfold(0, map_fold(F, sum_closure))`) — verify with a THROWAWAY peel (the
        // innermost `G` must be the std Sum/Product closure; a user fold `G` or a
        // float accumulator is order-sensitive and falls through to the REAL
        // reverse rfold body). `rfold` visits the items BACK TO FRONT. This route
        // used to drive the FORWARD chain on the premise that an integer
        // sum/product is commutative + associative; that premise is FALSE in two
        // directions (`rfold_reduction_order_blind`): core's overflow-CHECKED
        // integer closure traps on a PARTIAL result, which depends on the order,
        // and every `map`/`filter` closure the drive calls runs in drive order. So
        // the forward drive is kept ONLY where both are provably blind to order,
        // and everything else is driven back to front (`reverse = true`).
        if matches!(payload_ty.kind(), ty::Closure(..)) {
            let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
            let dest_is_integer =
                rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty).map_or(false, |t| t.is_integer());
            if dest_is_integer {
                if let Some(self_arg) = call.args.first() {
                    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                    if let Some(mut probe_chain) = resolve_iter_chain(ctx, self_ty)? {
                        let glue_is_const = matches!(call.args[2].node, Operand::Constant(_));
                        if let Some(reduce @ ("sum" | "product")) =
                            peel_fold_glue_to_sum(ctx, &mut probe_chain, payload_ty, glue_is_const)
                        {
                            // The FORWARD-drive shortcut is sound ONLY when every
                            // peeled adapter is ORDER-INSENSITIVE for a commutative
                            // sum/product (Map / Filter / Copied): reordering the
                            // addends does not change the total. An `Enumerate` (or a
                            // count-modifier take/skip/step_by) makes the per-element
                            // VALUE depend on its POSITION, so the reversed walk pairs
                            // different indices with elements than the forward walk —
                            // driving forward would silently miscompute (FUZZ-2
                            // differential: `v.iter().rev().enumerate().map(|(i,x)|
                            // (i+1)*x).sum()` yielded the un-reversed 55 instead of
                            // 35 at O2/O3). Fail closed rather than drop the rev; the
                            // reverse-drive `lower_iter_consumer(reverse=true)` path
                            // does not model reversed enumerate either (its own guard),
                            // so this stays consistent with `-O0` / the try_fold routes.
                            if probe_chain.adapters.iter().any(|(a, _)| {
                                a.kind.is_count_modifier()
                                    || matches!(a.kind, AdapterKind::Enumerate { .. })
                            }) {
                                return Err("iterator reverse sum/product over an \
                                     enumerate/take/skip/step_by chain is \
                                     order-sensitive and not modeled"
                                    .to_owned());
                            }
                            // `lower_iter_consumer` re-resolves + re-peels the same
                            // way (deterministic) and drives the chain — FORWARD only
                            // when that is unobservable, else in rfold's own
                            // back-to-front order. (The enumerate/count-modifier
                            // refusal above stays for both: `reverse = true` refuses
                            // those chains too.)
                            if rfold_reduction_order_blind(ctx, &probe_chain, dest_ty, reduce) {
                                return lower_iter_consumer(ctx, body, block, call, "fold", false);
                            }
                            return match lower_iter_consumer(ctx, body, block, call, "fold", true) {
                                Ok(true) => Ok(true),
                                Ok(false) => Err(format!(
                                    "{RFOLD_ORDER_REFUSAL} The chain `{self_ty:?}` did not resolve \
                                     for the back-to-front drive."
                                )),
                                Err(why) => Err(format!(
                                    "{RFOLD_ORDER_REFUSAL} The back-to-front drive refused \
                                     `{self_ty:?}`: {why}."
                                )),
                            };
                        }
                    }
                }
            }
            // ORDER-SENSITIVE adapter-glue rfold: `.map(f).rev().fold(0, g)`
            // inlines to `Iter::rfold(0, map_fold(F, G))` with a USER `G` (and
            // `filter_fold`/`copy_fold` likewise, including NESTED compositions
            // `map_fold(F, filter_fold(P, G))`). The glue is a STATELESS
            // per-element composition, so `rfold(init, glue)` == driving the
            // resolved chain BACKWARDS calling the SAME glue per item: the
            // identical glue call the forward `.map(f).fold(0, g)` consumer
            // drive already makes (validated ==LLVM), plus the `reversed`
            // slice/Range walk the O0 `.rev()` chains already use (validated
            // ==LLVM). The glue closure body is a collected mono that lowers
            // standalone; only the rfold BODY (glue env inlined) is
            // unlowerable and TRAPPED in a library crate type (see
            // `is_dead_std_iterator_reduction_body`; an executable refuses
            // it) — so this route MUST never fall through to the general
            // path (`Ok(false)`): a real call would reach the ud2 stub at
            // runtime. Everything not driven
            // fails CLOSED at compile time instead: a non-integer accumulator
            // (below), an unresolvable chain (`vec::IntoIter`, projected /
            // non-memory-backed self — the consumer's Err/Ok(false) mapped
            // here), a capturing `F`/`G` (non-ZST glue — the fold consumer's
            // ZST gate), a stateful adapter (the consumer's reverse block), a
            // tuple item (the tuple gate).
            // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
            if is_real_std_crate_def(ctx.tcx, callee.def_id())
                && is_adapter_rfold_glue_closure(ctx.tcx, payload_ty)
            {
                if !dest_is_integer {
                    return Err("iterator rfold with an adapter fold-glue payload into a \
                         non-integer accumulator is not modeled (order-sensitive \
                         float fold)"
                        .to_owned());
                }
                if lower_iter_consumer(ctx, body, block, call, "fold", true)? {
                    return Ok(true);
                }
                return Err("iterator rfold with an adapter fold-glue payload over an \
                     unmodeled iterator chain"
                    .to_owned());
            }
        }
        // `<RangeInclusive<T> as DoubleEndedIterator>::rfold(self, init, f)` with
        // any OTHER payload into a primitive SCALAR accumulator: the bare
        // `Sum`/`Product` closure `.rev().sum()` / `.rev().product()` reach at
        // `-O2`/`-O3` (`Rev::sum` -> `Rev::fold` -> `self.iter.rfold(0, |a, b|
        // a + b)`), a user `.rev().fold(init, g)` / `.rfold(init, g)`. (The
        // `count::plus_one` payload of `.rev().count()` is routed above, and a
        // peelable adapter glue by the two routes before this one.) UNLIKE
        // `Range` / `slice::Iter`, whose
        // `rfold` is the default `while let Some(x) = self.next_back()` body, the
        // inclusive range OVERRIDES `rfold` as `self.try_rfold(init,
        // NeverShortCircuit::wrap_mut_2(f)).0`, which reaches
        // `RangeInclusiveIteratorImpl::spec_try_rfold::<B, _, NeverShortCircuit<B>>`.
        // For a scalar `B` the general path does not lower that body: its
        // `NeverShortCircuit<B>` return local is left unbound
        // (`[TCG-RET-UNBOUND]`, measured on the base for u64/usize/i32/u128 sums,
        // products, folds and counts), refused in an executable and trapped as a
        // dead `try_rfold` body in a library. So drive the chain BACK TO FRONT
        // calling the SAME `f` per item instead — the `fold` consumer, reversed;
        // `emit_source_next`'s `spec_next_back` step yields exactly
        // `spec_try_rfold`'s sequence — and fail closed on anything that consumer
        // refuses (an unsupported capture). Driving in rfold's own order keeps
        // both overflow-checked partial results and `f`'s effects in LLVM's
        // order; no order-blindness argument is needed.
        //
        // A NON-scalar accumulator is left to the general path on purpose: a unit
        // one (`.rev().for_each(f)`'s `rfold((), for_each::call(f))`) or an
        // aggregate one (`.rev().last()`'s `rfold(None, last::some)`) lowers there
        // and matches LLVM (measured on the base at -O2/-O3: `for_each`, `last`
        // over u64, an `Option` / tuple `fold` accumulator), and the `fold`
        // consumer carries only a scalar, so intercepting it would only trade a
        // working program for a refusal.
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        if is_real_std_crate_def(ctx.tcx, callee.def_id()) {
            let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
            let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
            // A PRIMITIVE scalar only (not a scalar-mapped newtype such as
            // `Wrapping<u64>`, nor an `Option` the mapper might scalarize): the
            // measured `[TCG-RET-UNBOUND]` class, and nothing the general path
            // was lowering.
            let scalar_accumulator = matches!(
                dest_ty.kind(),
                ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool
            );
            if scalar_accumulator && range_inclusive_index_ty(ctx.tcx, self_ty).is_some() {
                return match lower_iter_consumer(ctx, body, block, call, "fold", true) {
                    Ok(true) => Ok(true),
                    Ok(false) => Err(format!(
                        "[TCG-ITER-UNMODELED] `rfold` over `{self_ty:?}`: the chain did not \
                         resolve for the back-to-front drive, and std's `rfold` body for an \
                         inclusive range (`spec_try_rfold` into `NeverShortCircuit<{dest_ty:?}>`) \
                         is not lowered by this backend; failing closed"
                    )),
                    Err(why) => Err(format!(
                        "[TCG-ITER-UNMODELED] `rfold` over `{self_ty:?}`: the back-to-front \
                         drive refused it ({why}), and std's `rfold` body for an inclusive \
                         range (`spec_try_rfold` into `NeverShortCircuit<{dest_ty:?}>`) is not \
                         lowered by this backend; failing closed"
                    )),
                };
            }
        }
    }

    if name == "spec_fold" {
        // GATE: a `step_by` chain's O2/O3-specialized `spec_fold` (the terminal
        // `.sum()`/`.fold()`/`.count()` over a `StepBy`) drives the `StepBy` state
        // in a layout the bridge would run ignoring the step (the known step_by
        // miscompile class), so FAIL CLOSED on any chain carrying a `StepBy`
        // adapter. Take / Skip / Copied / Map / Filter drive correctly. If arg-0 is
        // not a chain we resolve, fall through to the fail-closed general path.
        //
        // We must fail closed HERE (an explicit `Err`) rather than fall through to
        // the general call path: for a `u64` element the general path incidentally
        // fails closed on the reachable `<StepBy<Range<u64>> as SpecRangeSetup>::
        // setup` (a `usize`->`u64` `Rvalue::Cast` this backend cannot lower), but a
        // `usize`/`isize` element makes that setup cast-free, so it would compile
        // and emit a REAL call to `StepByImpl::spec_fold` — whose body drags in an
        // `unchecked_add::precondition_check` the bridge never emits, producing an
        // ugly UNDEFINED-SYMBOL link error instead of a clean compile-time reject.
        // Failing closed here makes every element type reject uniformly.
        let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
        if let Some(chain) = resolve_iter_chain(ctx, self_ty)? {
            if chain
                .adapters
                .iter()
                .any(|(a, _)| matches!(a.kind, AdapterKind::StepBy { .. }))
            {
                return Err(
                    "[TCG-MIR-UNSUPPORTED] `.step_by(k)` reduction (`.sum()`/`.fold()`/\
                     `.count()`) at -Copt-level=2/3: the O2/O3-specialized \
                     `<StepBy<_> as StepByImpl>::spec_fold` drives the `StepBy` state \
                     in a layout the bridge would iterate as if `step == 1` (the \
                     step_by miscompile class). Failing closed rather than \
                     miscompiling (or emitting an unresolvable `spec_fold` call)."
                        .to_owned(),
                );
            }
            // `<Take/Skip>::count()` inlines at O3 to `spec_fold(self, 0, count::plus_one)`
            // where `plus_one` is a bare `FnDef` (`|acc, _| acc + 1`), not a ZST closure
            // — the fold consumer rejects it. Recognize it and drive the `count`
            // consumer (which ignores the payload) instead.
            let payload_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[2].node)?);
            // `<Take/Skip>::last()` inlines at O3 to `spec_fold(self, None, last::some)`
            // — a fold into a non-scalar `Option<Item>` accumulator the fold consumer
            // rejects. Route it to the `last` TERMINAL (which computes the final
            // element directly, returning `Option<Item>`), matching the O0 path.
            if let ty::FnDef(fdef, _) = payload_ty.kind() {
                // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
                if is_real_std_crate_def(ctx.tcx, *fdef)
                    && ctx.tcx.def_path_str(*fdef).ends_with("last::some")
                {
                    return lower_iter_terminal(ctx, body, block, call, "last");
                }
            }
            let terminal = if let ty::FnDef(fdef, _) = payload_ty.kind() {
                let fp = ctx.tcx.def_path_str(*fdef);
                // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
                if is_real_std_crate_def(ctx.tcx, *fdef) && fp.ends_with("count::plus_one") {
                    "count"
                } else {
                    "fold"
                }
            } else {
                "fold"
            };
            return lower_iter_consumer(ctx, body, block, call, terminal, false);
        }
        return Ok(false);
    }

    // `-O3` inlines `iter().max()` / `iter().min()` (over the default `Ord`) into
    // `Iterator::reduce::<{max_by::fold | min_by::fold}<_, fn{Ord::cmp}>::closure}>`
    // — the by-name `max`/`min` call disappears, replaced by `reduce` driven by the
    // std-internal `max_by`/`min_by` fold closure that compares via `Ord::cmp`. The
    // bridge cannot lower that closure (it calls the `Ord::cmp` FnDef), so the call
    // fails closed at O3 even though the user wrote `max()`/`min()`. Recover it: when
    // a `reduce` call's comparator is EXACTLY the std `max_by::fold` / `min_by::fold`
    // closure over `Ord::cmp`, route it to the SAME `MinMax` terminal the O0 `max`/
    // `min` path uses. Sound because: (1) we fire ONLY on that std-internal closure
    // (a user `reduce(|a,b| ..)` has a different closure def-path and falls through);
    // (2) the `MinMax` terminal is restricted to SCALAR-VALUE (integer) items, for
    // which `max()`/`min()` return the element value itself — so the `max_by`-keeps-
    // LAST vs `min_by`-keeps-FIRST tie distinction is value-unobservable (tied
    // elements are equal). Verified differentially vs LLVM at O0 AND O3, with ties.
    if name == "reduce" {
        if let Some(want_max) = reduce_ord_minmax_direction(ctx, body, call)? {
            return lower_iter_terminal(
                ctx,
                body,
                block,
                call,
                if want_max { "max" } else { "min" },
            );
        }
        return Ok(false);
    }

    // Reducing / short-circuiting terminal consumers (`.find` / `.position` /
    // `.find_map` / `.any` / `.all` / `.min` / `.max` / `.min_by_key` /
    // `.max_by_key` / `.product` / `.last` / `.nth`). Like `sum`/`fold`/`count`
    // these drive the chain; the short-circuiting ones early-exit the loop on the
    // first match. Modeled directly against the memory-backed chain slot. Anything
    // not modelable (a non-scalar item, a capturing/unsupported closure, an Option
    // result whose layout we cannot write) fails closed inside `lower_iter_terminal`.
    if matches!(
        name,
        "find"
            | "position"
            | "find_map"
            | "any"
            | "all"
            | "min"
            | "max"
            | "min_by"
            | "max_by"
            | "min_by_key"
            | "max_by_key"
            | "product"
            | "last"
            | "nth"
    ) {
        return lower_iter_terminal(ctx, body, block, call, name);
    }

    // `<Iter>::try_fold(self, init, check)` — the short-circuiting engine that
    // `-O3` inlines `.any()/.all()/.find()/.position()/.find_map()` into. Drive it
    // directly (the by-name terminal is NOT present at O3 — the caller makes a raw
    // `try_fold` call and maps the returned `ControlFlow`).
    if name == "try_fold" {
        return lower_iter_try_fold(ctx, body, block, call, false);
    }

    // `<RangeInclusive<T> as RangeInclusiveIteratorImpl>::spec_try_fold(self, init,
    // check)` — the RangeInclusive-SPECIALIZED short-circuit engine. A
    // `RangeInclusive`'s `Iterator::{find,any,all,position,find_map,try_fold}` (and
    // the synthesized `Filter::next` -> `self.iter.find(&mut predicate)`) all
    // dispatch through `RangeInclusive::try_fold`, which — UNLIKE the generic
    // `try_fold` intercepted above — forwards to this
    // `RangeInclusiveIteratorImpl::spec_try_fold` (the three-field `{start, end,
    // exhausted}` representation needs its own driver). At `-O2/O3` that
    // `spec_try_fold` CALL survives (`.find()`/`.any()` inline down to it, and a
    // `for x in (0..=n).filter(p)` loop reaches it out-of-line via `Filter::next`).
    // Without this interception it falls through to the general call path and hits a
    // `ud2`-trapped dead body at RUNTIME (SIGILL) in a library crate type, or refuses
    // the compile on that body in an executable. It is the SAME (self, init, check)
    // shape and `ControlFlow`-returning contract as the generic `try_fold`, so drive
    // it through the identical engine: `lower_iter_try_fold` resolves the
    // `RangeInclusive` chain (already modeled in `emit_source_next`, exhausted-flag
    // included, and validated by the `.sum()`/`.fold()` consumers) and FAILS CLOSED
    // on any shape it cannot model (a `StepBy` wrap, a reversed/tuple chain). Gated
    // to the std callee (a user method named `spec_try_fold` keeps its own body).
    if name == "spec_try_fold"
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        && is_real_std_crate_def(ctx.tcx, callee.def_id())
    {
        return lower_iter_try_fold(ctx, body, block, call, false);
    }

    // `<I as DoubleEndedIterator>::try_rfold(self, init, check)` — the REVERSE
    // short-circuiting engine `-O3` inlines `.rev().find()/.position()/.any()/
    // .all()/.find_map()` (via `<Rev<I>>::try_fold` -> inner `try_rfold`) and
    // bare `.rfind()` into. Same driver, driving the resolved chain in the
    // OPPOSITE direction. Gated to the std callee: a user method named
    // `try_rfold` keeps the general call path (its body is never trapped).
    if name == "try_rfold"
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        && is_real_std_crate_def(ctx.tcx, callee.def_id())
    {
        return lower_iter_try_fold(ctx, body, block, call, true);
    }

    // NOT intercepted: `<RangeInclusive<T> as RangeInclusiveIteratorImpl>::
    // spec_try_rfold`, the reverse twin of the `spec_try_fold` arm above. With a
    // `ControlFlow` result (`.rev().find()/.any()/.all()/.position()`,
    // `.rfind()`, a user `try_rfold` at `-O2/O3`) its std body LOWERS on the
    // general path and matches LLVM — measured on the base for `any`, `all`, a
    // capturing `find` / `rfind` and an `Option`-returning `try_rfold`, every
    // one of which `lower_iter_try_fold` refuses — so routing it here would trade
    // working programs for refusals. Only the `NeverShortCircuit<T>` instance
    // (what `rfold` reaches) does not lower, and the `rfold` route above drives
    // that at the `rfold` call instead.
    //
    // EXCEPT where no `rfold` call survives: on wasm32 rustc's MIR inliner
    // inlines `RangeInclusive::rfold` and its `try_rfold` into the caller at
    // `-O2`/`-O3` (measured with the wasm32 sysroot; the native sysroot keeps the
    // `rfold` call), so the call this backend sees is
    // `spec_try_rfold::<B, NeverShortCircuit::wrap_mut_2(f)::{closure},
    // NeverShortCircuit<B>>(&mut range, init, wrap)`. Its std body is the
    // `[TCG-RET-UNBOUND]` one above — trapped as a dead body in a library, so
    // every `(a..=b).rev().fold(..)` / `.rev().map(..).sum()` trapped. Drive it
    // back to front through the wasm32 `NeverShortCircuit` engine
    // (`lower_iter_try_fold_never_short_circuit`): the same reversed source step
    // (`spec_next_back`) the `rfold` route uses, calling the wrapper closure per
    // item in rfold's own order, with the range state written back through the
    // `&mut` receiver. Only that instance (a `NeverShortCircuit` of a primitive
    // scalar) is routed; a `ControlFlow` result keeps the general path, and a
    // shape the engine does not model fails closed instead of reaching the trap.
    // Two instances never reach this arm. A 128-bit accumulator is returned
    // through memory on wasm32, so its call takes the carrier-return lowering
    // first and std's body is lowered for real (exact since the wasm lane copies
    // a lane read through a pointer, `extract_reads_through`). Any other live
    // instance — a native session, a `char` range, a `bool` / `char` / newtype
    // accumulator — keeps the general path, and when its std body is the trap
    // stub, the reference-graph gate refuses the crate by name once every stub
    // is known (`[TCG-ITER-STUB-REACHABLE]`).
    if name == "spec_try_rfold"
        && session_is_wasm32(ctx.tcx)
        && call.args.len() == 3
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        && is_real_std_crate_def(ctx.tcx, callee.def_id())
    {
        let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
        let range_ty = match self_ty.kind() {
            ty::Ref(_, inner, _) => ctx.monomorphize_ty(*inner),
            _ => self_ty,
        };
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        let scalar_never_short_circuit = is_never_short_circuit(ctx.tcx, dest_ty)
            && matches!(
                dest_ty.kind(),
                ty::Adt(adt, args) if matches!(
                    ctx_field_ty(ctx.tcx, adt.non_enum_variant(), *args, 0).kind(),
                    ty::Int(_) | ty::Uint(_) | ty::Float(_)
                )
            );
        if scalar_never_short_circuit && range_inclusive_index_ty(ctx.tcx, range_ty).is_some() {
            let emitted = (block.body.len(), ctx.extra_blocks.len());
            let why = match lower_iter_try_fold(ctx, body, block, call, true) {
                Ok(true) => return Ok(true),
                Ok(false) => "the chain did not resolve for the back-to-front drive".to_owned(),
                Err(why) => format!("the back-to-front drive refused it ({why})"),
            };
            // A drive the engine refuses (a capturing fold closure, which the
            // `NeverShortCircuit` engine's by-value capture gate rejects) inside
            // a STD body keeps the general path it had before this route: that
            // body is std's own `rfold`, which a caller's `rfold` route already
            // drives (and which is lowered at `-O0`), so refusing here would
            // refuse a crate whose only call of it is intercepted. In a user
            // body the call is live and its std callee does not lower, so the
            // refusal names it rather than reaching a trapped body at run time.
            let untouched = emitted == (block.body.len(), ctx.extra_blocks.len());
            if untouched && is_real_std_crate_def(ctx.tcx, ctx.instance.def_id()) {
                return Ok(false);
            }
            return Err(format!(
                "[TCG-ITER-UNMODELED] `spec_try_rfold` over `{range_ty:?}` into \
                 `{dest_ty:?}`: {why}, and std's body is not lowered by this backend; \
                 failing closed"
            ));
        }
    }

    // We only ever intercept the iterator entry points a bare `for` loop uses:
    // `into_iter` / `iter` (the constructors) and `next`. `spec_next` is the
    // `RangeInclusiveIteratorImpl::spec_next` that `-O3` inlines `next` into for a
    // `RangeInclusive` (the bare `next` body never appears); route it through the
    // inclusive-next path below (gated on a `RangeInclusive` self type). Any other
    // associated fn name is not ours.
    if name != "into_iter"
        && name != "iter"
        && name != "next"
        && name != "spec_next"
        && name != "bytes"
    {
        return Ok(false);
    }

    let dest_ty = place_rust_ty(ctx, body, call.destination);

    // `<str>::bytes(&str) -> str::Bytes` = `Copied<slice::Iter<u8>>` over the
    // string's UTF-8 bytes. `&str` and `&[u8]` share the `{ data, len }` fat-ptr
    // repr, and `Bytes` wraps the `slice::Iter<u8>` at offset 0 (a newtype, no added
    // layout) -- so build the SAME `{ ptr, end }` slice-iter state a `&[u8]`
    // into_iter would, with element `u8`. The terminal drives it via
    // `resolve_iter_chain`'s `str::Bytes` peel. STRICTLY gated on the `str::Bytes`
    // result type + a `&str` argument (a user `bytes` method never matches).
    if name == "bytes" {
        if is_str_bytes_ty(ctx.tcx, dest_ty) {
            if let Some(self_arg) = call.args.first() {
                let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                if matches!(arg_ty.kind(), ty::Ref(_, p, _) if matches!(p.kind(), ty::Str)) {
                    return lower_slice_into_iter(ctx, body, block, call, ctx.tcx.types.u8)
                        .map(|()| true);
                }
            }
        }
        return Ok(false);
    }

    // `<[T]>::iter(&[T]) -> slice::Iter<T>` — the explicit `arr.iter()` /
    // `slice.iter()` constructor (`for x in arr.iter()`). Same as the slice
    // `into_iter`: build `{ ptr, end }` from the slice reference. Identified by
    // the `slice::Iter` result; a `Vec::iter` / other `iter` is NOT a
    // `slice::Iter`-returning call here and falls through.
    if name == "iter" {
        if let Some(element_ty) = slice_iter_element_ty(ctx.tcx, dest_ty) {
            // The argument must be a slice / array reference (the `<[T]>::iter`
            // receiver); an Iterator-adapter `iter` would not be.
            if let Some(self_arg) = call.args.first() {
                let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                if matches!(arg_ty.kind(), ty::Ref(..)) {
                    return lower_slice_into_iter(ctx, body, block, call, element_ty)
                        .map(|()| true);
                }
            }
        }
        return Ok(false);
    }

    // `Range<T> as IntoIterator>::into_iter(self)` — identity. The destination is
    // the `Range<T>` iterator state.
    if name == "into_iter" {
        // PERFECTION UN-GATE: a bare `for` loop over a bridge-MODELED bare/forward
        // `.step_by(k)` (over a `Range`/`slice::Iter` source) lowers `into_iter`
        // (identity) then the real `StepBy::next`. The `.step_by()` ctor already
        // wrote core's `StepBy::new` state, so the identity copy + our
        // `lower_step_by_next` reproduce the yield set bit-identically.
        // Everything else (nested / reversed / RangeInclusive / non-const step)
        // returns `None` here and falls to the fail-closed guard below.
        if resolve_bare_stepby_chain(ctx, dest_ty)?.is_some() {
            return lower_stepby_into_iter(ctx, body, block, call, dest_ty).map(|()| true);
        }
        // CLASS GUARD (see `iter_chain_wraps_stepby`): a bare `for` loop over a
        // `.step_by(k)` chain lowers `into_iter` then an explicit real-core
        // `next` at -O0. The bridge synthesized the StepBy slot for its OWN chain
        // driver, not the real `spec_next`, so that `next` would iterate as if
        // `step == 1` (silent miscompile). Fail closed the whole loop here.
        if iter_chain_wraps_stepby(ctx, dest_ty) {
            return Err(
                "[TCG-MIR-UNSUPPORTED] `for` loop over a `.step_by(k)` iterator at \
                 -Copt-level=0: the bridge synthesizes the StepBy adapter state for its \
                 own terminal driver (`.sum()`/`.fold()`/`.collect()`), but a bare loop \
                 calls the real specialized `StepBy::next`, which reads an `iter.end` the \
                 skipped `SpecRangeSetup::setup` was to preprocess — it would iterate as \
                 if `step == 1`. Failing closed rather than miscompiling."
                    .to_owned(),
            );
        }
        if let Some(index_ty) = range_index_ty(ctx.tcx, dest_ty) {
            return lower_range_into_iter(ctx, body, block, call, index_ty).map(|()| true);
        }
        // `RangeInclusive<T> as IntoIterator>::into_iter(self)` — also the
        // identity; copy all THREE fields (`start`, `end`, `exhausted`) at their
        // rustc offsets into the destination iterator slot.
        if let Some(index_ty) = range_inclusive_index_ty(ctx.tcx, dest_ty) {
            return lower_range_inclusive_into_iter(ctx, body, block, call, index_ty)
                .map(|()| true);
        }
        // `<slice::Iter<T> as IntoIterator>::into_iter(self)` — the identity on an
        // already-built `slice::Iter` (the `for x in arr.iter()` desugaring): the
        // argument is a `slice::Iter`, not a reference. Copy its `{ ptr, end }`.
        if slice_iter_element_ty(ctx.tcx, dest_ty).is_some() {
            if let Some(self_arg) = call.args.first() {
                let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                if slice_iter_element_ty(ctx.tcx, arg_ty).is_some() {
                    return lower_slice_iter_identity(ctx, body, block, call).map(|()| true);
                }
            }
            // `<&[T] / &[T; N] as IntoIterator>::into_iter(self) -> slice::Iter<T>`.
            if let Some(element_ty) = slice_iter_element_ty(ctx.tcx, dest_ty) {
                return lower_slice_into_iter(ctx, body, block, call, element_ty).map(|()| true);
            }
        }
        // `<[T; N] as IntoIterator>::into_iter(self) -> array::IntoIter<T, N>` — the
        // BY-VALUE array loop `for x in a` (destination is `array::IntoIter`).
        if let Some(element_ty) = array_intoiter_element_ty(ctx.tcx, dest_ty) {
            // `<array::IntoIter<T, N> as IntoIterator>::into_iter(it)` — the
            // blanket identity a `for x in it` over an already-built (possibly
            // partly consumed) iterator calls. Admitted in a 32-bit session
            // (`lower_array_intoiter_identity`); a native session keeps refusing it.
            if session_pointer_bytes() == 4 {
                if let Some(self_arg) = call.args.first() {
                    let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                    if arg_ty == ctx.monomorphize_ty(dest_ty) {
                        return lower_array_intoiter_identity(ctx, body, block, call, element_ty)
                            .map(|()| true);
                    }
                }
            }
            return lower_array_into_iter(ctx, body, block, call, element_ty).map(|()| true);
        }
        // `<vec::Drain<T> as IntoIterator>::into_iter(self)` — IDENTITY on an already-
        // built Drain (`for x in v.drain(..)`; `Drain: Iterator`, so the blanket impl
        // returns `self`). Copy all five state words at rustc's offsets
        // (`VecDrainLayout`), so a Drain with a kept tail (one LLVM-compiled code
        // built) keeps it; the modeled `next`/`drop` then drive it. Gated: both
        // destination AND argument must be a `vec::Drain` (a chain terminal like
        // `.collect()` resolves the chain above and never reaches here).
        if vec_drain_element_ty(ctx.tcx, dest_ty).is_some() {
            if let Some(self_arg) = call.args.first() {
                let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                if vec_drain_element_ty(ctx.tcx, arg_ty).is_some() {
                    let lanes = vec_drain_layout(ctx.tcx, dest_ty)?.lanes();
                    return lower_owning_iter_identity(ctx, block, call, &lanes).map(|()| true);
                }
            }
        }
        // `<vec::IntoIter<T> as IntoIterator>::into_iter(self)` — IDENTITY on an
        // already-built by-value Vec iterator (`for x in v.into_iter()`; the explicit
        // `.into_iter()` yields a `vec::IntoIter`, then the `for` desugar's blanket impl
        // returns `self`). Copy its four state fields at rustc's offsets
        // (`VecIntoIterLayout`); the modeled `next`/`drop` drive + free the buffer. The
        // common `for x in v` uses the single `<Vec as IntoIterator>::into_iter`
        // (handled by `lower_vec_into_iter`) and does NOT reach here. Gated: both
        // destination AND argument must be a `vec::IntoIter`.
        if vec_intoiter_element_ty(ctx.tcx, dest_ty).is_some() {
            if let Some(self_arg) = call.args.first() {
                let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
                if vec_intoiter_element_ty(ctx.tcx, arg_ty).is_some() {
                    let lanes = vec_intoiter_layout(ctx.tcx, dest_ty)?.lanes();
                    return lower_owning_iter_identity(ctx, block, call, &lanes).map(|()| true);
                }
            }
        }
        return Ok(false);
    }

    // `name == "next"` / `"spec_next"`: the self argument is `&mut <iterator>`.
    // Peel the reference to find which iterator this is.
    let Some(self_arg) = call.args.first() else {
        return Ok(false);
    };
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
    let iter_ty = match self_ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
        _ => return Ok(false),
    };
    // PERFECTION UN-GATE: the real `<StepBy as Iterator>::next` a bare -O0 `for`
    // loop calls over a bridge-MODELED bare/forward `.step_by(k)` (Range /
    // slice::Iter source, the ONLY shape `resolve_bare_stepby_chain` accepts).
    // The `.step_by()` ctor already wrote core's `StepBy::new` state, so
    // `lower_step_by_next` reproduces core's yield sequence EXACTLY. Gated to
    // the std callee (a user trait `next` on core's StepBy keeps its body). Any
    // other StepBy shape (nested / adapted / reversed) resolves to `None` and
    // falls to the fail-closed guard below, never a miscompile.
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if is_real_core_or_std_def(ctx.tcx, callee.def_id()) {
        if let Some(chain) = resolve_bare_stepby_chain(ctx, iter_ty)? {
            return lower_step_by_next(ctx, body, block, call, &chain).map(|()| true);
        }
        // PERFECTION UN-GATE: the real `<Filter as Iterator>::next` a bare -O0
        // `for` loop (or any direct `next`) calls over a bridge-MODELED bare/
        // forward `.filter(p)` (Range / slice::Iter source, the ONLY shape
        // `resolve_bare_filter_chain` accepts). std's `Filter::next` is
        // `self.iter.find(&mut self.predicate)` — a body whose intercepted `find`
        // payload (a `&mut predicate`, not a bare ZST closure) this backend cannot
        // lower, so it fails closed today. `lower_filter_next` reproduces that
        // skip-loop EXACTLY in the bridge's own model (byte-identical to the
        // `emit_chain_next` `Filter` arm the terminal `.sum()`/`.fold()` drive
        // already runs ==LLVM): the SAME source-cursor advance + `predicate(&item)`
        // call. Gated to the std callee (a user trait `next` on core's Filter keeps
        // its body). Any other Filter shape (nested / adapted / reversed / tuple
        // item / non-Range/Slice source) resolves to `None` and falls to the
        // fail-closed guard below, never a miscompile.
        if let Some(chain) = resolve_bare_filter_chain(ctx, iter_ty)? {
            return lower_filter_next(ctx, body, block, call, &chain).map(|()| true);
        }
        // PERFECTION UN-GATE: the real `<FilterMap as Iterator>::next` a bare -O0
        // `for` loop (or any direct `next`) calls over a bridge-MODELED bare/
        // forward `.filter_map(f)` (Range / slice::Iter / RangeInclusive source,
        // the ONLY shape `resolve_bare_filtermap_chain` accepts). std's
        // `FilterMap::next` is `self.iter.find_map(&mut self.f)` — a body whose
        // intercepted `find_map` payload (a `&mut f`, not a bare ZST closure) this
        // backend cannot lower, so it fails closed today. `lower_filter_map_next`
        // reproduces that skip-loop EXACTLY in the bridge's own model (byte-
        // identical to the `emit_chain_next` `FilterMap` arm the terminal
        // `.sum()`/`.fold()` drive already runs ==LLVM): the SAME source-cursor
        // advance + by-value `f(item) -> Option<U>` call, re-pulling on a `None`.
        // Gated to the std callee (a user trait `next` on core's FilterMap keeps
        // its body). Any other FilterMap shape (nested / adapted / reversed /
        // tuple item / non-Range/Slice source / niche or sret Option return)
        // resolves to `None` and falls to the fail-closed guard below, never a
        // miscompile.
        if let Some(chain) = resolve_bare_filtermap_chain(ctx, iter_ty)? {
            return lower_filter_map_next(ctx, body, block, call, &chain).map(|()| true);
        }
    }
    // CLASS GUARD (see `iter_chain_wraps_stepby`): a real `<.. as
    // Iterator>::next` over a chain wrapping a StepBy that `lower_step_by_next`
    // does not drive (a `RangeInclusive` / `Chain` / `Zip` source,
    // `step_by().map()`, `map().step_by()`). The StepBy slot holds core's
    // `StepBy::new` state, but the intercepted drivers keep a running countdown in
    // `step_minus_one` while they drive, and no differential covers a real core
    // `next` over that state. Fail closed. (The intercepted terminals never reach
    // here — they resolve the chain and drive it themselves.)
    if iter_chain_wraps_stepby(ctx, iter_ty) {
        return Err(
            "[TCG-MIR-UNSUPPORTED] real `Iterator::next` on a `.step_by(k)` chain at \
             -Copt-level=0 that the bridge's own StepBy `next` does not drive: core's \
             `StepBy::next` over this chain is not validated against the bridge's \
             StepBy drivers. Failing closed rather than miscompiling."
                .to_owned(),
        );
    }
    // T15 UN-GATE: a bare `for (x, y) in a.iter().zip(b.iter())` calls the REAL
    // `<Zip as Iterator>::next`, whose TRA specialization reads elements via
    // `__iterator_get_unchecked` — a body the dead-body trap turns into `ud2` in a
    // library crate type and that an executable refuses (it is dead only when the
    // zip is DRIVEN by an intercepted terminal). Rather than reach that runtime
    // trap or refusal, SYNTHESIZE the single-step `Zip::next` here in
    // the bridge's own TRA model (`lower_zip_next`), byte-identical to the terminal
    // Zip drive. Strictly gated: the type must be the std `iter::adapters::zip::Zip`
    // (def-path check, not `item_name == "Zip"` — a user type named `Zip` would
    // otherwise get its `next` body silently replaced), the callee must be
    // core/std's own `next` (a user trait `next` on core's Zip keeps its body),
    // and `resolve_iter_chain` must MODEL the zip as a bare, forward, unadapted,
    // unclamped `ChainSource::Zip`. Any shape `resolve_zip` does not model (nested
    // zip, RangeInclusive side, narrow Range side, reversed) — OR a `(val, val)`
    // range+range Option layout `store_option_some_value` cannot niche-encode —
    // fails closed via the Err below / the `_ => Err` payload arm, never a
    // miscompile. A Range+Range zip (no slice side) keeps its old behavior: it is
    // NOT intercepted here and stays on the general call path (its real `next`
    // lowers fine), so this un-gate never regresses it to fail-closed.
    {
        let is_zip_adt = matches!(iter_ty.kind(), ty::Adt(adt, _)
            if is_zip_adapter(ctx.tcx, adt.did()));
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        let callee_is_std = is_real_core_or_std_def(ctx.tcx, callee.def_id());
        if is_zip_adt {
            if let ty::Adt(_, zargs) = iter_ty.kind() {
                let a_ty = ctx.monomorphize_ty(zargs.type_at(0));
                let b_ty = ctx.monomorphize_ty(zargs.type_at(1));
                // A Zip that is the GENERAL `ZipImpl` on this target (a Range
                // side wider than a 32-bit `usize`) is not TRA: its real `next`
                // advances the sub-iterators and lowers on the general path.
                if (slice_iter_element_ty(ctx.tcx, a_ty).is_some()
                    || slice_iter_element_ty(ctx.tcx, b_ty).is_some())
                    && !zip_is_general_on_narrow_target(ctx, a_ty, b_ty)?
                {
                    // Slice-sided zip: try to model + lower the real single-step
                    // next. Only a bare/forward/unadapted/unclamped modeled Zip is
                    // intercepted; everything else falls through to fail closed.
                    if callee_is_std {
                        if let Ok(Some(chain)) = resolve_iter_chain(ctx, iter_ty) {
                            if matches!(chain.source, ChainSource::Zip { .. })
                                && chain.adapters.is_empty()
                                && !chain.reversed
                                && chain.rev_clamp.is_none()
                            {
                                return lower_zip_next(ctx, body, block, call, &chain)
                                    .map(|()| true);
                            }
                        }
                    }
                    return Err(
                        "[TCG-MIR-UNSUPPORTED] real `Iterator::next` on a slice-sided \
                         `.zip()` chain the bridge could not model in its TRA `next` \
                         form (unmodeled sub-source / Option layout). Failing closed \
                         rather than reaching a runtime trap."
                            .to_owned(),
                    );
                }
            }
        }
    }
    // CLASS GUARD (the T15 lesson, review-required): a chain the bridge resolved
    // with a `rev_clamp` rewrite (`.take(n)`/`.skip(k)` directly below `.rev()`
    // over a slice) has its Take/Skip adapter REWRITTEN AWAY into a slot boundary
    // clamp for the bridge's own terminal drivers. A bare `for` loop (or any
    // direct `next`) would run the REAL `Rev<Take<..>>::next` std bodies over
    // that slot; the clamped state is canonical for them, but whether every
    // transitively-reached body LOWERS (vs hits a `ud2`-trapped dead-body stub at
    // RUNTIME in a library crate type) is not guaranteed — fail closed at compile
    // time instead. (A
    // resolve `Err` is NOT propagated here: an Err chain was never clamp-
    // rewritten, and falling through preserves today's behavior for it.)
    if matches!(resolve_iter_chain(ctx, iter_ty), Ok(Some(ref c)) if c.rev_clamp.is_some()) {
        return Err(
            "[TCG-MIR-UNSUPPORTED] real `Iterator::next` on a rewritten below-rev \
             take/skip chain — the bridge clamped the slot for its own terminal \
             driver; failing closed rather than risk a trapped std body at runtime"
                .to_owned(),
        );
    }
    // `spec_next` only ever names the `RangeInclusiveIteratorImpl` method (the
    // `-O3`-inlined inclusive next); route it ONLY to the inclusive path and never
    // to plain Range / slice (which use `next`).
    if name == "spec_next" {
        if let Some(index_ty) = range_inclusive_index_ty(ctx.tcx, iter_ty) {
            return lower_range_inclusive_next(ctx, body, block, call, index_ty).map(|()| true);
        }
        return Ok(false);
    }
    if let Some(index_ty) = range_index_ty(ctx.tcx, iter_ty) {
        // Gate to the std callee (mirrors the `try_rfold` gate above): a USER
        // trait/inherent method named `next` whose self peels to `Range<iN>` has
        // arbitrary semantics — routing it into `lower_range_next` would silently
        // REPLACE its body with range-next semantics (a live silent-miscompile
        // vector: `Stepper::next` stepping by 2 computed the step-1 sum). Fall
        // through instead: the general call path lowers the REAL user body.
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        if !is_real_core_or_std_def(ctx.tcx, callee.def_id()) {
            return Ok(false);
        }
        return lower_range_next(ctx, body, block, call, index_ty).map(|()| true);
    }
    if let Some(index_ty) = range_inclusive_index_ty(ctx.tcx, iter_ty) {
        return lower_range_inclusive_next(ctx, body, block, call, index_ty).map(|()| true);
    }
    if let Some(element_ty) = slice_iter_element_ty(ctx.tcx, iter_ty) {
        return lower_slice_iter_next(ctx, body, block, call, element_ty).map(|()| true);
    }
    // `<array::IntoIter<T, N> as Iterator>::next` — the by-value array loop's `next`.
    // It steps rustc's own `alive` index range over the inline `data`
    // (`ArrayIntoIterLayout`), whichever constructor built the state.
    if let Some(element_ty) = array_intoiter_element_ty(ctx.tcx, iter_ty) {
        let layout = array_intoiter_layout(ctx.tcx, iter_ty, element_ty)?;
        return lower_array_into_iter_next(
            ctx,
            body,
            block,
            call,
            element_ty,
            layout.start,
            layout.end,
            SliceCursorRepr::Indices {
                data_off: layout.data - layout.start,
            },
        )
        .map(|()| true);
    }
    // `<vec::IntoIter<T> as Iterator>::next` — the by-value `for x in v` loop's
    // `next`. The same by-value yield-and-advance lowering drives its `{ ptr, end }`
    // pair at rustc's offsets (`VecIntoIterLayout`); `buf`/`cap` are untouched,
    // preserved for drop.
    if let Some(element_ty) = vec_intoiter_element_ty(ctx.tcx, iter_ty) {
        let layout = vec_intoiter_layout(ctx.tcx, iter_ty)?;
        return lower_array_into_iter_next(
            ctx,
            body,
            block,
            call,
            element_ty,
            layout.ptr,
            layout.end,
            SliceCursorRepr::Pointers,
        )
        .map(|()| true);
    }
    // `<vec::Drain<T> as Iterator>::next` — std's `self.iter.next()` read by value:
    // the `iter.ptr` / `iter.end_or_len` pair at rustc's offsets (`VecDrainLayout`);
    // `vec` and the tail words are untouched, preserved for drop.
    if let Some(element_ty) = vec_drain_element_ty(ctx.tcx, iter_ty) {
        refuse_droppable_drain_element(ctx.tcx, ctx.monomorphize_ty(element_ty))?;
        let layout = vec_drain_layout(ctx.tcx, iter_ty)?;
        return lower_array_into_iter_next(
            ctx,
            body,
            block,
            call,
            element_ty,
            layout.iter_ptr,
            layout.iter_end,
            SliceCursorRepr::Pointers,
        )
        .map(|()| true);
    }
    // `<slice::{Windows, Chunks, ChunksExact, RChunks, RChunksExact}<T> as
    // Iterator>::next` — yields the current `&[T]` sub-slice and advances std's own
    // `v` (`SliceStrideIterLayout`).
    if let Some((kind, element_ty)) = slice_stride_iter_element_ty(ctx.tcx, iter_ty) {
        return lower_slice_stride_iter_next(ctx, body, block, call, iter_ty, kind, element_ty)
            .map(|()| true);
    }
    // `<str::Chars as Iterator>::next` — decode one UTF-8 code point and advance.
    if is_str_chars_ty(ctx.tcx, iter_ty) {
        return lower_str_chars_next(ctx, body, block, call).map(|()| true);
    }
    Ok(false)
}

/// Resolve a `&mut iter` / `iter`-by-value self operand to the iterator-state
/// slot address (a `Ptr`). The iterator state local is memory-backed, so a
/// `&mut it` reference is bound to its slot pointer and a by-value `it` is the
/// slot pointer itself.
fn iterator_self_slot_addr<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    operand: &Operand<'tcx>,
) -> Result<ValueId, String> {
    lower_operand_to_value(ctx, body, block, operand)
}

/// `<Range<T> as IntoIterator>::into_iter(self) -> Range<T>` — the identity. Copy
/// the source `Range`'s `{ start, end }` into the destination iterator slot.
fn lower_range_into_iter<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    index_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("Range::into_iter with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("Range::into_iter into projected destination".to_owned());
    }
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "Range::into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let (size, _align) = element_layout_size_align(ctx.tcx, index_ty)?;
    let elem_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;

    // The argument is a `move Range` — read its two fields from the source's slot.
    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        // ...unless rustc const-propagated it. A literal `for i in 0..64` reaches
        // codegen at -O1 as
        //
        //     _3 = <Range<usize> as IntoIterator>::into_iter(
        //              const Range::<usize> {{ start: 0_usize, end: 64_usize }})
        //
        // with no source place to copy from. The place path below is a straight
        // two-field copy between IDENTICAL layouts — i.e. a memcpy of the struct
        // image — so writing the constant's own byte image into the destination
        // slot produces exactly the same iterator state, field order and padding
        // included, without this code having to know either.
        //
        // `store_const_aggregate_bytes_into_memory_at` returns Ok(false) rather
        // than guessing for a const it cannot image byte-exactly (notably one
        // carrying pointer provenance, which a `Range<usize>` never does), and
        // that falls through to the same fail-closed error as before.
        if matches!(&call.args[0].node, Operand::Constant(_)) {
            let arg_ty = operand_rust_ty(ctx, body, &call.args[0].node)?;
            if store_const_aggregate_bytes_into_memory_at(
                ctx,
                block,
                dest_slot,
                0,
                arg_ty,
                &call.args[0].node,
            )? {
                emit_call_successor(block, call.target);
                return Ok(());
            }
        }
        return Err("Range::into_iter argument is not a place".to_owned());
    };
    if !src.projection.is_empty() {
        return Err("Range::into_iter argument uses a projected place".to_owned());
    }
    let src_slot = ctx
        .memory_slots
        .get(&src.local)
        .cloned()
        .ok_or_else(|| "Range::into_iter argument is not memory-backed".to_owned())?
        .ptr;

    // Copy `start` (offset 0) and `end` (offset `size`).
    for offset in [0u64, size] {
        let src_addr = iter_field_addr(ctx, block, src_slot, offset);
        let v = emit_typed_load(ctx, block, src_addr, elem_ty.clone());
        let dst_addr = iter_field_addr(ctx, block, dest_slot, offset);
        emit_typed_store(block, dst_addr, elem_ty.clone(), v);
    }
    emit_call_successor(block, call.target);
    Ok(())
}

/// `RangeInclusive::<T>::new(start, end) -> RangeInclusive<T>` — the `start..=end`
/// constructor. Synthesize the 3-field `{ start, end, exhausted: false }` struct
/// directly into the (memory-backed) destination slot at its rustc field offsets.
fn lower_range_inclusive_new<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    index_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 2 {
        return Err(format!("RangeInclusive::new with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("RangeInclusive::new into projected destination".to_owned());
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "RangeInclusive::new destination is not memory-backed".to_owned())?
        .ptr;
    let elem_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
    let (start_off, end_off, exhausted_off) = range_inclusive_field_offsets(ctx.tcx, dest_ty)?;

    // start := arg0, end := arg1 (both scalar integers of `index_ty`).
    let start = lower_operand_to_value(ctx, body, block, &call.args[0].node)?;
    let end = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let start_addr = iter_field_addr(ctx, block, dest_slot, start_off);
    emit_typed_store(block, start_addr, elem_ty.clone(), start);
    let end_addr = iter_field_addr(ctx, block, dest_slot, end_off);
    emit_typed_store(block, end_addr, elem_ty, end);

    // exhausted := false. Modeled as a single I8 byte (the bool's storage width)
    // so it composes with the I8 loads/stores `next` uses below.
    let zero = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::I8,
            value: Constant::Int(0),
        })
        .with_result(zero),
    );
    let exhausted_addr = iter_field_addr(ctx, block, dest_slot, exhausted_off);
    emit_typed_store(block, exhausted_addr, TrustIrTy::I8, zero);

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<RangeInclusive<T> as IntoIterator>::into_iter(self) -> RangeInclusive<T>` —
/// the identity. Copy all THREE fields (`start`, `end`, `exhausted`) at their
/// rustc offsets from the source `RangeInclusive` slot into the destination
/// iterator slot.
fn lower_range_inclusive_into_iter<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    index_ty: Ty<'tcx>,
) -> Result<(), String> {
    let _ = body;
    if call.args.len() != 1 {
        return Err(format!(
            "RangeInclusive::into_iter with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("RangeInclusive::into_iter into projected destination".to_owned());
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "RangeInclusive::into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let elem_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
    let (start_off, end_off, exhausted_off) = range_inclusive_field_offsets(ctx.tcx, dest_ty)?;

    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        // The twin of the const-propagated case in `lower_range_into_iter` — see
        // the comment there. `for i in 0..=63` const-folds the same way, and the
        // copy below is likewise a straight field-for-field move between
        // identical layouts, so the constant's own byte image is that same state.
        // Writing it whole also covers `exhausted` without this path having to
        // know where rustc put it.
        if matches!(&call.args[0].node, Operand::Constant(_)) {
            let arg_ty = operand_rust_ty(ctx, body, &call.args[0].node)?;
            if store_const_aggregate_bytes_into_memory_at(
                ctx,
                block,
                dest_slot,
                0,
                arg_ty,
                &call.args[0].node,
            )? {
                emit_call_successor(block, call.target);
                return Ok(());
            }
        }
        return Err("RangeInclusive::into_iter argument is not a place".to_owned());
    };
    if !src.projection.is_empty() {
        return Err("RangeInclusive::into_iter argument uses a projected place".to_owned());
    }
    let src_slot = ctx
        .memory_slots
        .get(&src.local)
        .cloned()
        .ok_or_else(|| "RangeInclusive::into_iter argument is not memory-backed".to_owned())?
        .ptr;

    // Copy `start` / `end` (index-typed) and `exhausted` (a single byte).
    for (offset, ty) in [
        (start_off, elem_ty.clone()),
        (end_off, elem_ty.clone()),
        (exhausted_off, TrustIrTy::I8),
    ] {
        let src_addr = iter_field_addr(ctx, block, src_slot, offset);
        let v = emit_typed_load(ctx, block, src_addr, ty.clone());
        let dst_addr = iter_field_addr(ctx, block, dest_slot, offset);
        emit_typed_store(block, dst_addr, ty, v);
    }
    emit_call_successor(block, call.target);
    Ok(())
}

/// `<RangeInclusive<T> as Iterator>::next(&mut self) -> Option<T>`. The std
/// `spec_next` semantics (`core::iter::range`):
///
///     if self.exhausted || !(self.start <= self.end) { return None; }
///     let is_iterating = self.start < self.end;
///     let v = self.start;
///     if is_iterating { self.start += 1; }       // SAFE: start < end, no overflow
///     else            { self.exhausted = true; } // start == end: final element
///     Some(v)
///
/// Lowered BRANCHLESSLY: the `start += 1` is computed unconditionally (a wrapping
/// trust-ir `Add` whose result is DISCARDED via `Select` when `!is_iterating`, so
/// it never traps even at `start == end == T::MAX` — this is exactly why the
/// `exhausted` flag exists). State (`start` and `exhausted`) is only mutated when
/// `cond` (non-empty), matching the real `next` leaving an exhausted range
/// untouched. The `Option<T>` is written via the shared `store_option_some_value`.
fn lower_range_inclusive_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    index_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!(
            "RangeInclusive::next with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("RangeInclusive::next into projected destination".to_owned());
    }
    let elem_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
    let signed = is_signed_trust_ir_integer(&elem_ty);

    // The `&mut self` iterator state local is memory-backed; resolve its slot.
    let iter_ty = {
        let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
        match self_ty.kind() {
            ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
            _ => return Err("RangeInclusive::next self is not a reference".to_owned()),
        }
    };
    let (start_off, end_off, exhausted_off) = range_inclusive_field_offsets(ctx.tcx, iter_ty)?;
    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;

    // Load start / end / exhausted.
    let start_addr = iter_field_addr(ctx, block, slot_ptr, start_off);
    let start = emit_typed_load(ctx, block, start_addr, elem_ty.clone());
    let end_addr = iter_field_addr(ctx, block, slot_ptr, end_off);
    let end = emit_typed_load(ctx, block, end_addr, elem_ty.clone());
    let exhausted_addr = iter_field_addr(ctx, block, slot_ptr, exhausted_off);
    let exhausted_byte = emit_typed_load(ctx, block, exhausted_addr, TrustIrTy::I8);

    let cmp = |ctx: &mut MirLoweringCtx<'tcx>,
               block: &mut Block,
               op_signed: ICmpOp,
               op_unsigned: ICmpOp,
               lhs: ValueId,
               rhs: ValueId|
     -> ValueId {
        let r = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::ICmp {
                op: if signed { op_signed } else { op_unsigned },
                ty: elem_ty.clone(),
                lhs,
                rhs,
            })
            .with_result(r),
        );
        r
    };

    // already_exhausted = exhausted_byte != 0.
    let zero8 = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::I8,
            value: Constant::Int(0),
        })
        .with_result(zero8),
    );
    let already_exhausted = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I8,
            lhs: exhausted_byte,
            rhs: zero8,
        })
        .with_result(already_exhausted),
    );

    // start_le_end = start <= end; cond (yield Some) = !exhausted && start <= end.
    let start_le_end = cmp(ctx, block, ICmpOp::Sle, ICmpOp::Ule, start, end);
    // cond = already_exhausted ? false : start_le_end. Expressed as a Bool Select
    // (the verified bool-AND idiom — a `UnOp::Not` on a 1-bit Bool is avoided, see
    // the `lower_unary_op` bool path which uses `== false` / Select, not bitwise
    // Not). `false_bool` is the canonical 0.
    let false_bool = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::Bool,
            value: Constant::Bool(false),
        })
        .with_result(false_bool),
    );
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::Bool,
            cond: already_exhausted,
            then_val: false_bool,
            else_val: start_le_end,
        })
        .with_result(cond),
    );

    // is_iterating = start < end (when true, advance start; when false AND cond,
    // this is the FINAL element: leave start, set exhausted).
    let is_iterating = cmp(ctx, block, ICmpOp::Slt, ICmpOp::Ult, start, end);

    // advanced = start + 1 (wrapping; discarded unless is_iterating — never
    // selected at start==end==MAX, so the wrap is dead).
    let one = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: elem_ty.clone(),
            value: Constant::Int(1),
        })
        .with_result(one),
    );
    let advanced = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: elem_ty.clone(),
            lhs: start,
            rhs: one,
        })
        .with_result(advanced),
    );
    // start_if_yield = is_iterating ? advanced : start.
    let start_if_yield = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: elem_ty.clone(),
            cond: is_iterating,
            then_val: advanced,
            else_val: start,
        })
        .with_result(start_if_yield),
    );
    // new_start = cond ? start_if_yield : start (only mutate when yielding).
    let new_start = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: elem_ty.clone(),
            cond,
            then_val: start_if_yield,
            else_val: start,
        })
        .with_result(new_start),
    );
    emit_typed_store(block, start_addr, elem_ty.clone(), new_start);

    // became_exhausted = cond && !is_iterating (yielded the final element). The
    // new exhausted byte is `(already_exhausted || became_exhausted) ? 1 : 0`,
    // but since `cond` already requires `!already_exhausted`, and we only mutate
    // when `cond`, the post-state is: set to 1 iff (cond && !is_iterating), else
    // leave the prior byte. Compute it as a byte Select.
    let one8 = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::I8,
            value: Constant::Int(1),
        })
        .with_result(one8),
    );
    // set_exhausted = cond && !is_iterating, i.e. (yield the final element). As a
    // Bool Select: `is_iterating ? false : cond` (when iterating we never exhaust;
    // otherwise we exhaust exactly when we yield, i.e. `cond`).
    let set_exhausted = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::Bool,
            cond: is_iterating,
            then_val: false_bool,
            else_val: cond,
        })
        .with_result(set_exhausted),
    );
    // new_exhausted_byte = set_exhausted ? 1 : exhausted_byte.
    let new_exhausted_byte = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::I8,
            cond: set_exhausted,
            then_val: one8,
            else_val: exhausted_byte,
        })
        .with_result(new_exhausted_byte),
    );
    emit_typed_store(block, exhausted_addr, TrustIrTy::I8, new_exhausted_byte);

    // Write `Option<T>`: tag = cond ? Some : None, payload = the yielded `start`.
    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Scalar {
            value: start,
            ty: elem_ty,
        },
    )?;

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<&[T] / &[T; N] as IntoIterator>::into_iter(self) -> slice::Iter<T>`. Build
/// the iterator state `{ ptr: data, end: data + len*size }` in the destination
/// slot. The argument is `&[T]` (a fat pointer: data + len) or `&[T; N]` (a thin
/// pointer to the array, `len == N`).
fn lower_slice_into_iter<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    element_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("slice into_iter with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("slice into_iter into projected destination".to_owned());
    }
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "slice into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    // The data pointer and length come from the slice / array reference argument.
    let (data, len) = slice_iter_data_and_len(ctx, body, block, &call.args[0].node)?;

    // end = data + len * size.
    let end = emit_element_addr(ctx, block, data, len, size);

    // Store the `{ ptr, end }` iterator state (two pointer-width lanes).
    let ptr_addr = iter_field_addr(ctx, block, dest_slot, 0);
    emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, data);
    let end_addr = iter_field_addr(ctx, block, dest_slot, slice_iter_end_offset());
    emit_typed_store(block, end_addr, TrustIrTy::Ptr, end);

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<&Vec<T> as IntoIterator>::into_iter(&self) -> slice::Iter<T>` — the `for &x in
/// &v` / `for x in &v` desugaring (a BORROWING iteration, which yields `&T` over the
/// Vec's buffer, exactly like `v.iter()`). Builds the same `{ ptr, end }` slice-iter
/// state as `lower_slice_into_iter`, but reads the `{data, len}` from the Vec's slot
/// header (`vec_self_slot_addr` + `VEC_FIELD_PTR/LEN`) since the receiver is a
/// `&Vec`, not a `&[T]` fat pointer. The BY-VALUE `for x in v` (whose destination is
/// the owning `vec::IntoIter<T>`, not `slice::Iter<T>`) is NOT this shape and fails
/// closed here (its owning-iterator drop/free is unmodeled).
fn lower_vec_into_iter<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    require_64bit_model("`Vec::into_iter` (the slice-cursor view of a Vec)")?;
    if call.args.len() != 1 {
        return Err(format!("Vec into_iter with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("Vec into_iter into projected destination".to_owned());
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    // By-value `for x in v`: the destination is the OWNING `vec::IntoIter<T>` (not
    // a borrowing `slice::Iter`/`IterMut`). Build its `{ buf, ptr, cap, end }` state
    // over the Vec's heap buffer and free that buffer at the iterator's drop.
    if let Some(element_ty) = vec_intoiter_element_ty(ctx.tcx, dest_ty) {
        let element_ty = ctx.monomorphize_ty(element_ty);
        return lower_vec_into_iter_owning(ctx, body, block, call, dest_ty, element_ty);
    }
    let element_ty = slice_iter_or_mut_element_ty(ctx.tcx, dest_ty).ok_or_else(|| {
        "Vec::into_iter destination is neither a borrowing `slice::Iter`/`IterMut` nor a modeled \
         owning `vec::IntoIter` — fail closed"
            .to_owned()
    })?;
    let element_ty = ctx.monomorphize_ty(element_ty);
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let data = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    let end = emit_element_addr(ctx, block, data, len, size);

    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "Vec into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let ptr_addr = iter_field_addr(ctx, block, dest_slot, 0);
    emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, data);
    let end_addr = iter_field_addr(ctx, block, dest_slot, slice_iter_end_offset());
    emit_typed_store(block, end_addr, TrustIrTy::Ptr, end);

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<Vec<T> as IntoIterator>::into_iter(self) -> vec::IntoIter<T>` — the BY-VALUE
/// `for x in v` loop. Unlike the borrowing `&Vec` path (which yields a
/// `slice::Iter` and never frees), this OWNS the heap buffer: `v` is moved in, so
/// the iterator's drop is the buffer's sole free. We snapshot the Vec's
/// `{ data, len, cap }` from its slot header and write exactly what std's own
/// `into_iter` writes, at rustc's offsets ([`VecIntoIterLayout`]): `buf = data`,
/// `ptr = data`, `cap = cap`, `end = data + len*size`. `next` drives the
/// `{ptr, end}` pair by value and the drop releases `[ptr, end)` and `buf`/`cap`.
/// At `-O2`/`-O3` rustc inlines this constructor and stores the same four
/// fields itself, so both producers leave the same bytes. The element is a
/// single scalar (`vec_intoiter_element_ty`); one that needs drop has its
/// unyielded elements dropped by the iterator's drop, however far iteration
/// advanced — see `lower_vec_intoiter_drop`.
fn lower_vec_into_iter_owning<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    iter_ty: Ty<'tcx>,
    element_ty: Ty<'tcx>,
) -> Result<(), String> {
    require_64bit_model("the owning `vec::IntoIter` cursor")?;
    if call.args.len() != 1 {
        return Err(format!(
            "Vec owning into_iter with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("Vec owning into_iter into projected destination".to_owned());
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    let layout = vec_intoiter_layout(ctx.tcx, iter_ty)?;

    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let data = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
    let cap = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_CAP);
    let end = emit_element_addr(ctx, block, data, len, size);

    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "Vec owning into_iter destination is not memory-backed".to_owned())?
        .ptr;
    for (offset, ty, value) in [
        (layout.buf, TrustIrTy::Ptr, data),
        (layout.ptr, TrustIrTy::Ptr, data),
        (layout.cap, TrustIrTy::I64, cap),
        (layout.end, TrustIrTy::Ptr, end),
    ] {
        let addr = iter_field_addr(ctx, block, dest_slot, offset);
        emit_typed_store(block, addr, ty, value);
    }

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<vec::IntoIter<T> as Drop>::drop`: drop the elements the iterator still
/// owns, then free its heap buffer (`emit_vec_intoiter_release`). The iterator
/// holds `buf` / `ptr` / `cap` / `end` at rustc's offsets ([`VecIntoIterLayout`])
/// whichever producer built it (`lower_vec_into_iter_owning`, or rustc's inlined
/// constructor at `-O2`/`-O3`) and whichever advanced it (the intercepted `next`,
/// rustc's inlined one, or a `&mut self` drive, which keeps its cursor in the
/// iterator's own slot), so `[ptr, end)` is exactly the unyielded elements.
/// The source `Vec` was moved into `into_iter`, so its own drop never runs and
/// this is the sole drop and free (no double drop, no double free).
fn lower_vec_intoiter_drop<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
    iter_ty: Ty<'tcx>,
    element_ty: Ty<'tcx>,
    target: mir::BasicBlock,
    unwind: &mir::UnwindAction,
) -> Result<(), String> {
    require_64bit_model("the owning `vec::IntoIter` drop")?;
    let slot_ptr = ctx
        .memory_slots
        .get(&place.local)
        .cloned()
        .ok_or_else(|| "vec::IntoIter drop self is not memory-backed".to_owned())?
        .ptr;
    let layout = vec_intoiter_layout(ctx.tcx, iter_ty)?;
    emit_vec_intoiter_release(
        ctx,
        block,
        slot_ptr,
        layout,
        element_ty,
        IntoIterRelease::Terminator(unwind),
    )?;
    block.body.push(InstrNode::new(Inst::Br {
        target: BlockId::new(target.index() as u32),
        args: Vec::new(),
    }));
    Ok(())
}

/// Who releases a `vec::IntoIter` in `emit_vec_intoiter_release`, which decides
/// where an element's panicking `Drop::drop` goes.
#[derive(Clone, Copy)]
enum IntoIterRelease<'a> {
    /// A MIR `Drop` terminator, with its own unwind action. Under
    /// `panic=unwind` the loop replicates rustc's nested cleanup
    /// (`emit_element_drop_loop_unwind`: the remaining elements, then the
    /// buffer, then this action), exactly `drop_in_place::<[T]>` inside the
    /// iterator's `DropGuard`.
    Terminator(&'a mir::UnwindAction),
    /// The drive of a by-value terminal that consumed the iterator: its normal
    /// exit, or its pad (`begin_consumed_owner_drive`). The release has no
    /// nested cleanup of its own, so a droppable element is released only under
    /// `panic=abort`, where an element's panic aborts on the spot;
    /// `emit_chain_next` refuses an unwinding drive over such a source
    /// (`[TCG-INTOITER-UNWIND-DROP]`) before this is reached.
    ConsumingDrive,
}

/// Release an owning `vec::IntoIter` at `slot` (offsets `fields`): drop each
/// element of `[ptr, end)` — the elements no pull yielded — in ascending order
/// with `drop_in_place::<T>` (`emit_vec_intoiter_drop_unyielded`), then free
/// `buf` (`cap * size_of::<T>()` bytes at `align_of::<T>()`, skipping a
/// zero-capacity buffer) through `emit_vec_buffer_dealloc`. That is std's
/// `<vec::IntoIter<T> as Drop>::drop` order. For an element that does not need
/// drop only the free is emitted. `block` continues after the free.
fn emit_vec_intoiter_release<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    slot: ValueId,
    fields: VecIntoIterLayout,
    element_ty: Ty<'tcx>,
    release: IntoIterRelease<'_>,
) -> Result<(), String> {
    let (size, align) = element_layout_size_align(ctx.tcx, element_ty)?;
    let (buf, cap) =
        emit_vec_intoiter_drop_unyielded(ctx, block, slot, fields, element_ty, release)?;
    emit_vec_buffer_dealloc(ctx, block, buf, cap, size, align)
}

/// Drop each element of the owning `vec::IntoIter` at `slot` (offsets `fields`)
/// that no pull yielded, `[ptr, end)`, in ascending order with
/// `drop_in_place::<T>`, and return its `(buf, cap)`; frees nothing. Emits
/// nothing but the two loads for an element that does not need drop. `block`
/// continues after the drops.
///
/// The per-element glue is admitted by the same gate as a `Vec<T>` drop's
/// (`drop_glue_needs_drop_element_lowerable`), which `vec_intoiter_element_ty`
/// already applies; a zero-sized droppable element (whose `IntoIter` counts in
/// `end` rather than walking `ptr`) fails closed.
fn emit_vec_intoiter_drop_unyielded<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    slot: ValueId,
    fields: VecIntoIterLayout,
    element_ty: Ty<'tcx>,
    release: IntoIterRelease<'_>,
) -> Result<(ValueId, ValueId), String> {
    let (size, align) = element_layout_size_align(ctx.tcx, element_ty)?;
    let buf_addr = iter_field_addr(ctx, block, slot, fields.buf);
    let buf = emit_typed_load(ctx, block, buf_addr, TrustIrTy::Ptr);
    let cap_addr = iter_field_addr(ctx, block, slot, fields.cap);
    let cap = emit_typed_load(ctx, block, cap_addr, TrustIrTy::I64);
    if element_ty.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized()) {
        if size == 0 || !drop_glue_needs_drop_element_lowerable(ctx.tcx, element_ty) {
            return Err(format!(
                "[TCG-INTOITER-ELEMENT-DROP] dropping a vec::IntoIter<{element_ty:?}> needs \
                 per-element drop glue this backend does not lower for this element \
                 (zero-sized, or not a user-`Drop` struct of `Copy` fields); failing closed"
            ));
        }
        let ptr_addr = iter_field_addr(ctx, block, slot, fields.ptr);
        let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
        let end_addr = iter_field_addr(ctx, block, slot, fields.end);
        let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
        let ptr_int = emit_ptr_to_int(ctx, block, ptr);
        let end_int = emit_ptr_to_int(ctx, block, end);
        let byte_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, end_int, ptr_int);
        let stride = emit_i64_const(ctx, block, i128::from(size));
        let count = emit_i64_binop(ctx, block, TrustIrBinOp::UDiv, byte_len, stride);
        let glue = ctx.extern_callee(Instance::resolve_drop_glue(ctx.tcx, element_ty))?;
        let cont_id = ctx.fresh_block_id();
        match release {
            _ if panic_is_abort(ctx.tcx) => {
                // An element's panic aborts on the spot: no cleanup to model.
                emit_element_drop_loop(ctx, block, cont_id, ptr, count, size, glue);
            }
            IntoIterRelease::Terminator(action) => {
                if !ctx.eh_active {
                    return Err(
                        "[TCG-INTOITER-ELEMENT-DROP] dropping a vec::IntoIter with needs-drop \
                         elements under panic=unwind without EH lowering (TCG_DISABLE_UNWIND) \
                         — failing closed rather than skipping the glue's nested cleanup"
                            .to_owned(),
                    );
                }
                emit_element_drop_loop_unwind(
                    ctx,
                    block,
                    cont_id,
                    ptr,
                    count,
                    Some((buf, cap, align)),
                    size,
                    glue,
                    action,
                )?;
            }
            IntoIterRelease::ConsumingDrive => {
                return Err(format!(
                    "[TCG-INTOITER-UNWIND-DROP] a by-value iterator drive releasing a \
                     vec::IntoIter<{element_ty:?}> under panic=unwind has no cleanup that \
                     finishes the release when an element's drop panics; failing closed"
                ));
            }
        }
        let looped = std::mem::replace(block, Block::new(cont_id));
        ctx.extra_blocks.push(looped);
    }
    Ok((buf, cap))
}

/// Drop the owning `vec::IntoIter` a BY-VALUE iterator terminal consumed
/// (`emit_vec_intoiter_release`: its unyielded elements, then its buffer). No-op
/// for a chain without an owned buffer.
///
/// Callers: the collect (unless the collected Vec adopted the buffer:
/// `emit_adopted_chain_source_drop`) / extend / for_each / sum / fold / count /
/// reducing terminals, each on its normal exit and only for a by-value
/// receiver. The receiver was moved into the terminal, so the caller's MIR never
/// drops it and this is its sole drop; a `&mut self` terminal (`find` /
/// `position` / `any` / `nth` / `try_fold`) must not call this, because the
/// caller still owns and drops the iterator. `slot` may be the private `#111`
/// copy: the drive writes only the cursor, so its `buf` / `cap` equal the
/// original's. Every element
/// the drive pulled was either moved on (into a by-value closure, the collected
/// `Vec`, the terminal's result) or dropped at the discard that consumed it
/// (`emit_discard_drop`); for an element type that needs drop the drive keeps
/// the cursor in the slot (`chain_owns_droppable_elements`), so `[ptr, end)` here
/// is exactly the elements nothing pulled, and each element is dropped once.
/// This is the release on the normal exit; an unwind out of the drive takes the
/// terminal's pad instead (`begin_consumed_owner_drive`), which frees the same
/// buffer. A drive over an element that needs drop exists only under
/// `panic=abort` (`emit_chain_next`).
fn emit_consumed_chain_drop<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    chain: &IterChain<'tcx>,
    slot: ValueId,
) -> Result<(), String> {
    let Some(owned) = chain.owned_buffer else {
        return Ok(());
    };
    emit_vec_intoiter_release(
        ctx,
        block,
        slot,
        owned.fields,
        owned.element_ty,
        IntoIterRelease::ConsumingDrive,
    )
}

/// Drop the elements no pull yielded from the owning `vec::IntoIter` whose
/// buffer an in-place `collect` adopted (`CollectSizing::InPlace`), and free
/// nothing: std's `from_iter_in_place` calls `forget_allocation_drop_remaining`
/// once the drive stops, which drops `[ptr, end)` in ascending order and hands
/// the buffer to the collected Vec. Only an element that needs drop owes
/// anything; the drive kept the cursor in the slot for it
/// (`chain_owns_droppable_elements`), so `[ptr, end)` is what an adapter that
/// stops early (`take`) left. Under `panic=unwind` no such drive is lowered
/// (`emit_chain_next`), so this is the `panic=abort` release.
fn emit_adopted_chain_source_drop<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    chain: &IterChain<'tcx>,
    slot: ValueId,
) -> Result<(), String> {
    let Some(owned) = chain.owned_buffer else {
        return Err(
            "[TCG-COLLECT-CAPACITY] an in-place collect adopted an owning source the chain \
             records no buffer for"
                .to_owned(),
        );
    };
    if chain_owns_droppable_elements(ctx.tcx, chain) {
        emit_vec_intoiter_drop_unyielded(
            ctx,
            block,
            slot,
            owned.fields,
            owned.element_ty,
            IntoIterRelease::ConsumingDrive,
        )?;
    }
    Ok(())
}

/// The pad of a by-value iterator terminal that owns heap memory while it
/// drives (`begin_consumed_owner_drive`): `landing` is its landing pad, which
/// stores the exception and enters `release`; `release` frees what the terminal
/// owns and continues at the terminal call's own unwind action. A drive pad of
/// its own (`held_item_unwind_pad`) stores its exception and enters `release`
/// after it has dropped what it holds.
#[derive(Clone, Copy)]
struct ConsumedOwnerPad {
    landing: BlockId,
    release: BlockId,
}

/// The landing pad an unwinding call or raise with action `unwind` takes while
/// a by-value terminal that owns heap memory is lowered
/// (`begin_consumed_owner_drive`): that terminal's pad, unless nothing unwinds
/// (`panic=abort`, an `Unreachable` action).
fn consumed_owner_pad_for(ctx: &MirLoweringCtx<'_>, unwind: &mir::UnwindAction) -> Option<BlockId> {
    consumed_owner_release_for(ctx, unwind).map(|pad| pad.landing)
}

/// [`consumed_owner_pad_for`], with the block a drive pad of its own enters
/// once it has stored its exception and dropped what it holds.
fn consumed_owner_release_for(
    ctx: &MirLoweringCtx<'_>,
    unwind: &mir::UnwindAction,
) -> Option<ConsumedOwnerPad> {
    ctx.consumed_owner_pad
        .filter(|_| !panic_is_abort(ctx.tcx) && !matches!(unwind, mir::UnwindAction::Unreachable))
}

/// The destination `Vec` of a `collect` the bridge drives: std's `from_iter`
/// holds it as a local while the source is driven, so an unwind out of the
/// drive drops it right after the consumed source. `header` is its `{ptr, cap,
/// len}` slot and `size` / `align` its element's layout; its elements need no
/// drop (`collect` lowers scalar elements only).
#[derive(Clone, Copy)]
struct CollectedVec {
    header: ValueId,
    size: u64,
    align: u64,
}

/// What `begin_consumed_owner_drive` replaced; `end` puts it back once the
/// terminal's last unwinding call or raise is emitted.
#[must_use]
#[derive(Clone, Copy)]
struct ConsumedOwnerDrive {
    intercept_unwind_pad: Option<BlockId>,
    consumed_owner_pad: Option<ConsumedOwnerPad>,
}

impl ConsumedOwnerDrive {
    fn end(self, ctx: &mut MirLoweringCtx<'_>) {
        ctx.intercept_unwind_pad = self.intercept_unwind_pad;
        ctx.consumed_owner_pad = self.consumed_owner_pad;
    }
}

/// Open the pad of a BY-VALUE iterator terminal that owns heap memory while it
/// drives: the owning `vec::IntoIter` its chain consumed (`chain.owned_buffer`),
/// the `Vec` a `collect` builds (`collected`), or both. Every unwinding call and
/// raise the terminal emits after this goes into it until `end`
/// (`ctx.intercept_unwind_pad`, `consumed_owner_pad_for`).
///
/// std's terminal owns that memory: when a payload closure, a reduction's
/// overflow check or an allocation failure unwinds out of its drive, the
/// iterator is dropped there, which frees its buffer, and a `collect` then
/// drops the destination it was building, before the unwind reaches the caller.
/// The pad does the same: it frees `buf` (`cap` elements, read from the chain
/// slot, whose `buf` / `cap` the drive never writes), then `collected`'s buffer
/// (`cap` elements, read from its header when the pad runs; nothing for a
/// capacity of zero) unless it is that same allocation (an in-place collect
/// adopted it), then continues at the terminal call's own unwind action
/// (`emit_elem_cleanup_unwind_exit`). For a `Terminate` action the landing pad
/// has the empty-filter head of `terminate_pad_block`, so the frees precede
/// the abort as they do in LLVM's phase-two unwind through std's terminal.
///
/// Nothing is opened under `panic=abort`, for a terminal that owns neither, for
/// an `Unreachable` action, or for an owned source element that needs drop (a
/// drive over such a source under `panic=unwind` refuses in `emit_chain_next`,
/// `[TCG-INTOITER-UNWIND-DROP]`). A live action without EH lowering
/// (`disable-unwind`) refuses (`[TCG-INTOITER-UNWIND-RELEASE]` for an owned
/// source, `[TCG-COLLECT-UNWIND-RELEASE]` for a collect over a source that owns
/// nothing); `seed_eh_landing_pads` activates EH for every call that receives
/// such an iterator by value and for every `collect` into a `Vec`
/// (`call_collects_into_vec`), so a `Continue` action has its exn slot.
fn begin_consumed_owner_drive<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
    chain_slot: ValueId,
    collected: Option<CollectedVec>,
) -> Result<ConsumedOwnerDrive, String> {
    let saved = ConsumedOwnerDrive {
        intercept_unwind_pad: ctx.intercept_unwind_pad,
        consumed_owner_pad: ctx.consumed_owner_pad,
    };
    if panic_is_abort(ctx.tcx)
        || (chain.owned_buffer.is_some() && chain_owns_droppable_elements(ctx.tcx, chain))
        || (chain.owned_buffer.is_none() && collected.is_none())
    {
        return Ok(saved);
    }
    let terminate = match call.unwind {
        mir::UnwindAction::Continue | mir::UnwindAction::Cleanup(_) => false,
        mir::UnwindAction::Terminate(_) if supports_rust_terminate_filter(ctx.tcx) => true,
        mir::UnwindAction::Terminate(_) | mir::UnwindAction::Unreachable => return Ok(saved),
    };
    let Some(exn_slot) = ctx.eh_exn_slot.filter(|_| ctx.eh_active) else {
        return Err(match chain.owned_buffer {
            Some(owned) => format!(
                "[TCG-INTOITER-UNWIND-RELEASE] a by-value iterator terminal that consumed a \
                 vec::IntoIter<{:?}> under panic=unwind without EH lowering: a payload call or \
                 raise that unwinds would skip the iterator's release that std's unwind \
                 performs; failing closed",
                owned.element_ty
            ),
            None => "[TCG-COLLECT-UNWIND-RELEASE] a collect into a Vec under panic=unwind \
                     without EH lowering: a payload call or raise that unwinds would skip the \
                     free of the Vec it builds, which std's unwind performs; failing closed"
                .to_owned(),
        });
    };
    let landing_id = ctx.fresh_block_id();
    let release_id = ctx.fresh_block_id();
    let mut landing = Block::new(landing_id);
    let exn = ctx.fresh_value();
    let selector = ctx.fresh_value();
    landing.body.push(
        InstrNode::new(Inst::LandingPad {
            is_cleanup: !terminate,
            catch_type_indices: if terminate {
                vec![trust_cg_lower::function::RUST_EH_EMPTY_FILTER]
            } else {
                Vec::new()
            },
        })
        .with_results(vec![exn, selector]),
    );
    emit_exn_slot_store(&mut landing, exn_slot, exn);
    landing.body.push(InstrNode::new(Inst::Br {
        target: release_id,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(landing);
    let mut release = Block::new(release_id);
    // std's `<vec::IntoIter<T> as Drop>::drop`: no element needs drop here.
    if let Some(owned) = chain.owned_buffer {
        emit_vec_intoiter_release(
            ctx,
            &mut release,
            chain_slot,
            owned.fields,
            owned.element_ty,
            IntoIterRelease::ConsumingDrive,
        )?;
    }
    if let Some(dst) = collected {
        let data = emit_vec_field_load(ctx, &mut release, dst.header, VEC_FIELD_PTR);
        let cap = emit_vec_field_load(ctx, &mut release, dst.header, VEC_FIELD_CAP);
        let owned_cap = match chain.owned_buffer {
            Some(owned) => {
                let buf_addr = iter_field_addr(ctx, &mut release, chain_slot, owned.fields.buf);
                let buf = emit_typed_load(ctx, &mut release, buf_addr, TrustIrTy::Ptr);
                let buf_int = emit_ptr_to_int(ctx, &mut release, buf);
                let data_int = emit_ptr_to_int(ctx, &mut release, data);
                let adopted = emit_i64_icmp(ctx, &mut release, ICmpOp::Eq, data_int, buf_int);
                let zero = emit_i64_const(ctx, &mut release, 0);
                emit_i64_select(ctx, &mut release, adopted, zero, cap)
            }
            None => cap,
        };
        emit_vec_buffer_dealloc(ctx, &mut release, data, owned_cap, dst.size, dst.align)?;
    }
    emit_elem_cleanup_unwind_exit(ctx, &mut release, call.unwind)?;
    ctx.extra_blocks.push(release);
    ctx.intercept_unwind_pad = Some(landing_id);
    ctx.consumed_owner_pad = Some(ConsumedOwnerPad {
        landing: landing_id,
        release: release_id,
    });
    Ok(saved)
}

/// `<Vec<T>>::drain(&mut self, r) -> vec::Drain<T>` for a SUFFIX range: the full
/// range `..` (drain-all: `v.drain(..).sum()` / `.collect()` / `for x in v.drain(..)`)
/// and a to-end `start..` (drain the suffix: `v.drain(k..)`). Both remove
/// `[start..len]` and keep no tail. Build exactly std's `Vec::drain` state at
/// rustc's offsets ([`VecDrainLayout`]): `iter` over `[start..len]` (the cursor
/// `lower_array_into_iter_next` drives by value), `vec` = the drained Vec,
/// `tail_start = len`, `tail_len = 0`; and, as std does before the Drain exists,
/// set the Vec's length to `start`, so a leaked Drain leaves `[..start]` and never
/// exposes a drained (possibly already yielded) element. A `start..` range sets the
/// length only when `start <= len`; otherwise the call traps with the length
/// unchanged. A range with a bounded END (`..b` / `a..b` / `a..=b`) is not built
/// here — fail closed. Only an element that needs no drop
/// (`refuse_droppable_drain_element`): the drop drops none of the removed elements.
fn lower_vec_drain<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    element_ty: Ty<'tcx>,
    size: u64,
) -> Result<(), String> {
    require_64bit_model("the `vec::Drain` cursor")?;
    if call.args.len() != 2 {
        return Err(format!("Vec::drain with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("Vec::drain into a projected destination".to_owned());
    }
    // Only a SUFFIX range — full `..` or to-end `start..` — is built here: it
    // removes `[start..len]` and keeps no tail (`tail_len = 0`). A bounded-end
    // range (`..b` / `a..b` / `a..=b`) needs `slice::range`'s end checks, which
    // are not modeled — fail closed.
    let li = ctx.tcx.lang_items();
    let range_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let range_did = match range_ty.kind() {
        ty::Adt(adt, _) => Some(adt.did()),
        _ => None,
    };
    let is_full = range_did.is_some() && range_did == li.range_full_struct();
    let is_from = range_did.is_some() && range_did == li.range_from_struct();
    if !is_full && !is_from {
        return Err(
            "Vec::drain with a bounded-end range is not modeled (end bounds checks) — fail closed"
                .to_owned(),
        );
    }
    // `RangeFrom<usize>` only (a `RangeFrom<u32>` etc. would mis-load the index width).
    if is_from {
        let ty::Adt(_, args) = range_ty.kind() else {
            unreachable!()
        };
        if !matches!(args.type_at(0).kind(), ty::Uint(ty::UintTy::Usize)) {
            return Err("Vec::drain RangeFrom index is not usize — fail closed".to_owned());
        }
    }
    let element_ty = ctx.monomorphize_ty(element_ty);
    refuse_droppable_drain_element(ctx.tcx, element_ty)?;
    // The cursor is element-agnostic; the per-element YIELD lives in
    // `lower_array_into_iter_next`, which handles a class-1 scalar and a class-2
    // aggregate image. Neither needs drop (class 2 by its own `!needs_drop`
    // requirement, class 1 by the refusal above), so "no per-element drop" holds.
    if rust_ty_to_trust_ir_ty(ctx.tcx, element_ty).is_err()
        && !vec_struct_element_admissible(ctx.tcx, element_ty)
    {
        return Err(format!(
            "Vec::drain of a non-single-scalar element {element_ty:?} — fail closed"
        ));
    }

    let drain_ty = place_rust_ty(ctx, body, call.destination);
    let layout = vec_drain_layout(ctx.tcx, drain_ty)?;

    let v_slot = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let data = emit_vec_field_load(ctx, block, v_slot, VEC_FIELD_PTR);
    let len = emit_vec_field_load(ctx, block, v_slot, VEC_FIELD_LEN);
    let end = emit_element_addr(ctx, block, data, len, size);

    // `start` = the range's lower bound (0 for `..`, the `RangeFrom.start` field for
    // `start..`): the cursor's first element index and the length std's
    // `Vec::drain` gives the Vec before it returns. RangeFull keeps `data` as the
    // cursor base directly.
    let (cursor_ptr, start) = if is_full {
        (data, emit_i64_const(ctx, block, 0))
    } else {
        let range_local = match &call.args[1].node {
            Operand::Copy(p) | Operand::Move(p) if p.projection.is_empty() => p.local,
            _ => return Err("Vec::drain RangeFrom argument is not a bare local".to_owned()),
        };
        let usize_ty = ctx.tcx.types.usize;
        let field0 = Operand::Copy(Place {
            local: range_local,
            projection: ctx
                .tcx
                .mk_place_elems(&[ProjectionElem::Field(FieldIdx::new(0), usize_ty)]),
        });
        let s = lower_operand_to_value(ctx, body, block, &field0)?;
        let start = coerce_to_i64(ctx, block, s);
        (emit_element_addr(ctx, block, data, start, size), start)
    };

    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "Vec::drain destination is not memory-backed".to_owned())?
        .ptr;
    // A suffix range keeps no tail: `tail_start = end = len`, `tail_len = len - end = 0`.
    let no_tail = emit_i64_const(ctx, block, 0);
    let words = [
        (layout.iter_ptr, TrustIrTy::Ptr, cursor_ptr),
        (layout.iter_end, TrustIrTy::Ptr, end),
        (layout.vec, TrustIrTy::Ptr, v_slot),
        (layout.tail_start, TrustIrTy::I64, len),
        (layout.tail_len, TrustIrTy::I64, no_tail),
    ];
    for (offset, ty, value) in words {
        let addr = iter_field_addr(ctx, block, dest_slot, offset);
        emit_typed_store(block, addr, ty, value);
    }

    // RangeFull needs no bounds check (`start = 0 <= len` always). A `start..` drain
    // MUST trap when `start > len` — std's `Vec::drain` asserts `start <= len` via the
    // `slice::range` bounds check; without it the new length `start` could exceed
    // the buffer (a memory-safety hole). The trapping path keeps the old length.
    if is_full {
        emit_vec_field_store(ctx, block, v_slot, VEC_FIELD_LEN, start);
        emit_call_successor(block, call.target);
        return Ok(());
    }
    let fail = std_panic_route::fail_target(
        ctx,
        body,
        call,
        // std's `slice::range(start.., ..len)` (`into_slice_range`): the end is
        // `Unbounded` (`len`), so only `Included(start) if start > end =>
        // slice_index_fail(start, end, len)` can fail.
        std_panic_route::StdFailure::Helper {
            name: "slice_index_fail",
            payload: vec![
                std_panic_route::Payload::Bound(start, ctx.tcx.types.usize, "Included"),
                std_panic_route::Payload::Scalar(len, ctx.tcx.types.usize),
                std_panic_route::Payload::Scalar(len, ctx.tcx.types.usize),
            ],
        },
    )?;
    let Some(target) = call.target else {
        block.body.push(InstrNode::new(Inst::Br {
            target: fail,
            args: Vec::new(),
        }));
        return Ok(());
    };
    let target = BlockId::new(target.index() as u32);
    let ok = emit_i64_icmp(ctx, block, ICmpOp::Ule, start, len);
    let new_len = emit_i64_select(ctx, block, ok, start, len);
    emit_vec_field_store(ctx, block, v_slot, VEC_FIELD_LEN, new_len);
    block.body.push(InstrNode::new(Inst::CondBr {
        cond: ok,
        then_target: target,
        then_args: Vec::new(),
        else_target: fail,
        else_args: Vec::new(),
    }));
    Ok(())
}

/// `<vec::Drain<T> as Drop>::drop`, std's transition over the state at rustc's
/// offsets ([`VecDrainLayout`]), for a Drain any producer built — this
/// function's `Vec::drain`, another bridge function's, or LLVM-compiled code's
/// (a parameter, a call result): when `tail_len > 0`, move the kept tail
/// `[tail_start, tail_start + tail_len)` down to the Vec's current length
/// `start` (a `memmove`, as std's `ptr::copy`) and set the length to
/// `start + tail_len`; otherwise leave the Vec as `Vec::drain` left it. The
/// unyielded elements are not dropped: the element needs no drop (the caller
/// applies `refuse_droppable_drain_element`).
fn lower_vec_drain_drop<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
    drain_ty: Ty<'tcx>,
    element_ty: Ty<'tcx>,
    target: mir::BasicBlock,
) -> Result<(), String> {
    let slot_ptr = ctx
        .memory_slots
        .get(&place.local)
        .cloned()
        .ok_or_else(|| "vec::Drain drop self is not memory-backed".to_owned())?
        .ptr;
    let target = BlockId::new(target.index() as u32);
    emit_vec_drain_drop(ctx, block, slot_ptr, drain_ty, element_ty, target)
}

/// `lower_vec_drain_drop`'s transition over the Drain at `slot_ptr`, then a
/// branch to `target`. Also the body of `<vec::Drain<T> as Drop>::drop(&mut d)`
/// where rustc's drop glue calls it (`vec_drain_drop_impl`).
fn emit_vec_drain_drop<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    slot_ptr: ValueId,
    drain_ty: Ty<'tcx>,
    element_ty: Ty<'tcx>,
    target: BlockId,
) -> Result<(), String> {
    require_64bit_model("the `vec::Drain` drop")?;
    let layout = vec_drain_layout(ctx.tcx, drain_ty)?;
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    let size_ty = memory_libcall_size_ty(ctx.tcx).ok_or_else(|| {
        "[TCG-MEM-LIBCALL-ABI] the `vec::Drain` drop's tail move has no 64-bit size_t".to_owned()
    })?;
    let tail_len_addr = iter_field_addr(ctx, block, slot_ptr, layout.tail_len);
    let tail_len = emit_typed_load(ctx, block, tail_len_addr, TrustIrTy::I64);
    let zero = emit_i64_const(ctx, block, 0);
    let has_tail = emit_i64_icmp(ctx, block, ICmpOp::Ne, tail_len, zero);
    let move_id = ctx.fresh_block_id();
    block.body.push(InstrNode::new(Inst::CondBr {
        cond: has_tail,
        then_target: move_id,
        then_args: Vec::new(),
        else_target: target,
        else_args: Vec::new(),
    }));

    let mut mv = Block::new(move_id);
    let vec_addr = iter_field_addr(ctx, &mut mv, slot_ptr, layout.vec);
    let v_slot = emit_typed_load(ctx, &mut mv, vec_addr, TrustIrTy::Ptr);
    let start = emit_vec_field_load(ctx, &mut mv, v_slot, VEC_FIELD_LEN);
    let data = emit_vec_field_load(ctx, &mut mv, v_slot, VEC_FIELD_PTR);
    let tail_start_addr = iter_field_addr(ctx, &mut mv, slot_ptr, layout.tail_start);
    let tail_start = emit_typed_load(ctx, &mut mv, tail_start_addr, TrustIrTy::I64);
    let src = emit_element_addr(ctx, &mut mv, data, tail_start, size);
    let dst = emit_element_addr(ctx, &mut mv, data, start, size);
    let size_const = emit_i64_const(ctx, &mut mv, i128::from(size));
    let bytes = emit_i64_binop(ctx, &mut mv, TrustIrBinOp::Mul, tail_len, size_const);
    let nbytes = ctx.fresh_value();
    mv.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::Bitcast,
            src_ty: TrustIrTy::I64,
            dst_ty: size_ty,
            operand: bytes,
        })
        .with_result(nbytes),
    );
    let memmove = memory_libcall_callee(ctx, MemoryLibcall::Move)?;
    note_memory_libcall_unwind(ctx, memmove, MemoryLibcall::Move, None);
    let unused_destination = ctx.fresh_value();
    mv.body.push(
        InstrNode::new(Inst::Call {
            callee: memmove,
            args: vec![dst, src, nbytes],
        })
        .with_result(unused_destination),
    );
    let new_len = emit_i64_binop(ctx, &mut mv, TrustIrBinOp::Add, start, tail_len);
    emit_vec_field_store(ctx, &mut mv, v_slot, VEC_FIELD_LEN, new_len);
    mv.body.push(InstrNode::new(Inst::Br {
        target,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(mv);
    Ok(())
}

/// `<[T; N] as IntoIterator>::into_iter(self) -> array::IntoIter<T, N>` — the
/// BY-VALUE array loop `for x in a`. `compute_memory_backed_locals` forces the
/// moved array `a` memory-backed (its by-value MIR local is otherwise scalarized),
/// so `a` has a slot to read. Build exactly what std's `into_iter` builds, at
/// rustc's own offsets ([`ArrayIntoIterLayout`]): `alive = 0..N` and the `N`
/// elements MOVED into the iterator's inline `data` buffer. The iterator therefore
/// owns its elements: it stays valid when it is moved or returned out of `a`'s
/// frame, and it is the same state rustc's inlined constructor builds at
/// `-O2`/`-O3`. `next` loads BY VALUE. Only a scalar element that needs no drop
/// (`array_intoiter_element_ty`), so the iterator's drop is a no-op.
fn lower_array_into_iter<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    element_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("array into_iter with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("array into_iter into projected destination".to_owned());
    }
    let (Operand::Copy(p) | Operand::Move(p)) = &call.args[0].node else {
        return Err("array into_iter argument is not a place operand".to_owned());
    };
    if !p.projection.is_empty() {
        return Err("array into_iter argument uses a projected place".to_owned());
    }
    let arr_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, p.local));
    let n = match arr_ty.kind() {
        ty::Array(_, len) => len
            .try_to_target_usize(ctx.tcx)
            .ok_or_else(|| format!("array into_iter length not target-usize: {arr_ty:?}"))?,
        _ => return Err("array into_iter argument is not an array".to_owned()),
    };
    let data = ctx
        .memory_slots
        .get(&p.local)
        .cloned()
        .ok_or_else(|| "array into_iter source array is not memory-backed".to_owned())?
        .ptr;
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    let iter_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let layout = array_intoiter_layout(ctx.tcx, iter_ty, element_ty)?;
    if layout.len != n {
        return Err(format!(
            "[TCG-ARRAY-INTOITER-LAYOUT] {iter_ty:?} holds {} elements but the source \
             array has {n}",
            layout.len
        ));
    }

    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "array into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let word = usize_field_ty(ctx.tcx);
    let start = emit_usize_field_const(ctx, block, 0);
    let start_addr = iter_field_addr(ctx, block, dest_slot, layout.start);
    emit_typed_store(block, start_addr, word.clone(), start);
    let end = emit_usize_field_const(ctx, block, i128::from(n));
    let end_addr = iter_field_addr(ctx, block, dest_slot, layout.end);
    emit_typed_store(block, end_addr, word, end);
    copy_slot_bytes(ctx, block, data, 0, dest_slot, layout.data, n * size)?;

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<array::IntoIter<T, N> as IntoIterator>::into_iter(self) -> Self` — the
/// identity. The state is rustc's own layout (`ArrayIntoIterLayout`: the
/// `alive` indices and the inline elements), so the destination receives the
/// source slot's whole image, `layout_of` bytes long, and the `alive` range
/// a partly consumed source carries is kept. Both slots are memory-backed.
fn lower_array_intoiter_identity<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    element_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!(
            "array IntoIter::into_iter with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("array IntoIter::into_iter into projected destination".to_owned());
    }
    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        return Err("array IntoIter::into_iter argument is not a place".to_owned());
    };
    if !src.projection.is_empty() {
        return Err("array IntoIter::into_iter argument uses a projected place".to_owned());
    }
    let iter_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    // The state must be the modeled one before its bytes are copied whole.
    array_intoiter_layout(ctx.tcx, iter_ty, element_ty)?;
    let size = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(iter_ty))
        .map_err(|e| format!("[TCG-ARRAY-INTOITER-LAYOUT] layout of {iter_ty:?}: {e:?}"))?
        .size
        .bytes();
    let src_slot = ctx
        .memory_slots
        .get(&src.local)
        .cloned()
        .ok_or_else(|| "array IntoIter::into_iter argument is not memory-backed".to_owned())?
        .ptr;
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "array IntoIter::into_iter destination is not memory-backed".to_owned())?
        .ptr;
    copy_slot_bytes(ctx, block, src_slot, 0, dest_slot, 0, size)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `<array::IntoIter<T, N> as Iterator>::next(&mut self) -> Option<T>` — yield the
/// element at the cursor BY VALUE and advance. Mirrors `lower_slice_iter_next`, but
/// the payload is the loaded scalar VALUE (a direct-tagged `Option<T>` via
/// `OptionPayload::Scalar`, like `Range::next`). The value is read through a
/// bounds-safe address (the cursor when non-empty, else the always-valid slot
/// header) so an exhausted `next` never reads one-past-the-end. `ptr_off` /
/// `end_off` locate the cursor pair in the iterator slot and `repr` says how it
/// encodes positions: rustc's `iter` pointer fields for `vec::Drain`
/// (`VecDrainLayout`) and for `vec::IntoIter` (`VecIntoIterLayout`), rustc's
/// `alive` indices over the inline `data` for `array::IntoIter`
/// (`ArrayIntoIterLayout`).
#[allow(clippy::too_many_arguments)]
fn lower_array_into_iter_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    element_ty: Ty<'tcx>,
    ptr_off: u64,
    end_off: u64,
    repr: SliceCursorRepr,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!(
            "array IntoIter::next with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("array IntoIter::next into projected destination".to_owned());
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    // A class-1 element yields one scalar; a class-2 aggregate yields its scalar
    // LEAVES via `OptionPayload::Image`, exactly as `Vec::pop` delivers one. Shared
    // by `array::IntoIter::next`, `vec::IntoIter::next` and `vec::Drain::next`.
    let scalar_ir = rust_ty_to_trust_ir_ty(ctx.tcx, element_ty);
    let lanes: Option<Vec<(u64, TrustIrTy)>> = match &scalar_ir {
        Ok(_) => None,
        Err(_) if vec_struct_element_admissible(ctx.tcx, element_ty) => {
            Some(vec_element_image_lanes(ctx.tcx, element_ty)?)
        }
        Err(_) => None,
    };
    if scalar_ir.is_err() && lanes.is_none() {
        return Err(scalar_ir.unwrap_err());
    }
    let element_ir = scalar_ir.unwrap_or(TrustIrTy::I64);

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let ptr_addr = iter_field_addr(ctx, block, slot_ptr, ptr_off);
    let data = emit_slice_cursor_data(ctx, block, ptr_addr, repr);
    let ptr = emit_slice_cursor_load(ctx, block, ptr_addr, data, size);
    let end_addr = iter_field_addr(ctx, block, slot_ptr, end_off);
    let end = emit_slice_cursor_load(ctx, block, end_addr, data, size);

    let ptr_int = emit_ptr_to_int(ctx, block, ptr);
    let end_int = emit_ptr_to_int(ctx, block, end);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: ptr_int,
            rhs: end_int,
        })
        .with_result(cond),
    );

    let index_one = emit_i64_const(ctx, block, 1);
    let advanced = emit_element_addr(ctx, block, ptr, index_one, size);
    let new_ptr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::Ptr,
            cond,
            then_val: advanced,
            else_val: ptr,
        })
        .with_result(new_ptr),
    );
    emit_slice_cursor_store(ctx, block, ptr_addr, data, size, new_ptr);

    let read_ptr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::Ptr,
            cond,
            then_val: ptr,
            else_val: slot_ptr,
        })
        .with_result(read_ptr),
    );
    let payload = match lanes {
        None => OptionPayload::Scalar {
            value: emit_typed_load(ctx, block, read_ptr, element_ir.clone()),
            ty: element_ir,
        },
        Some(lanes) => OptionPayload::Image {
            src_addr: read_ptr,
            lanes,
        },
    };

    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        payload,
    )?;

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<slice::Iter<T> as IntoIterator>::into_iter(self) -> slice::Iter<T>` — the
/// identity on an already-built `slice::Iter` (the `for x in arr.iter()`
/// desugaring). Copy the source iterator's `{ ptr, end }` (two pointer-width
/// lanes) into the destination iterator slot.
fn lower_slice_iter_identity<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    let _ = body;
    if call.args.len() != 1 {
        return Err(format!(
            "slice Iter into_iter with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("slice Iter into_iter into projected destination".to_owned());
    }
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "slice Iter into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        return Err("slice Iter into_iter argument is not a place".to_owned());
    };
    if !src.projection.is_empty() {
        return Err("slice Iter into_iter argument uses a projected place".to_owned());
    }
    let src_slot = ctx
        .memory_slots
        .get(&src.local)
        .cloned()
        .ok_or_else(|| "slice Iter into_iter argument is not memory-backed".to_owned())?
        .ptr;
    for offset in [0u64, slice_iter_end_offset()] {
        let src_addr = iter_field_addr(ctx, block, src_slot, offset);
        let v = emit_typed_load(ctx, block, src_addr, TrustIrTy::Ptr);
        let dst_addr = iter_field_addr(ctx, block, dest_slot, offset);
        emit_typed_store(block, dst_addr, TrustIrTy::Ptr, v);
    }
    emit_call_successor(block, call.target);
    Ok(())
}

/// `<vec::Drain<T> | vec::IntoIter<T> as IntoIterator>::into_iter(self)` — the
/// IDENTITY on an already-built OWNING iterator (`for x in v.drain(..)` / `for x in
/// v.into_iter()`: both are `Iterator`, so the `for` desugar's blanket
/// `IntoIterator for I: Iterator` returns `self`). Copy the FULL state (`lanes`:
/// byte offset and type of each word) from the source temporary into the loop
/// iterator's destination slot: the Drain's `{ iter.ptr, iter.end_or_len, vec,
/// tail_start, tail_len }` (`VecDrainLayout`) or the IntoIter's
/// `{ buf, ptr, cap, end }` (`VecIntoIterLayout`), both at rustc's offsets. The
/// modeled `next` then drives the cursor and the modeled `drop` reads the rest at
/// loop end: Drain moves the kept tail back and restores the Vec's length;
/// IntoIter drops its unyielded elements, then frees the buffer
/// (`emit_vec_intoiter_release`). Both slots are memory-backed.
/// The element is one fixed-width scalar, as the ctor and `next` already
/// require; it may need drop for an IntoIter (`vec_intoiter_element_ty`), never
/// for a Drain (`refuse_droppable_drain_element`). The copy moves the state and
/// drops nothing.
fn lower_owning_iter_identity<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    lanes: &[(u64, TrustIrTy)],
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!(
            "owning iter into_iter with {} args",
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("owning iter into_iter into projected destination".to_owned());
    }
    // The aux `I64` lane is the 64-bit model's `usize` (the ctors refuse any
    // other width the same way).
    require_64bit_model("the owning `vec::IntoIter` / `vec::Drain` identity")?;
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "owning iter into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        return Err("owning iter into_iter argument is not a place".to_owned());
    };
    if !src.projection.is_empty() {
        return Err("owning iter into_iter argument uses a projected place".to_owned());
    }
    let src_slot = ctx
        .memory_slots
        .get(&src.local)
        .cloned()
        .ok_or_else(|| "owning iter into_iter argument is not memory-backed".to_owned())?
        .ptr;
    for (offset, ty) in lanes {
        let src_addr = iter_field_addr(ctx, block, src_slot, *offset);
        let v = emit_typed_load(ctx, block, src_addr, ty.clone());
        let dst_addr = iter_field_addr(ctx, block, dest_slot, *offset);
        emit_typed_store(block, dst_addr, ty.clone(), v);
    }
    emit_call_successor(block, call.target);
    Ok(())
}

/// The byte offset of `slice::Iter`'s `end_or_len` field (== a pointer width,
/// since `ptr` is the first field). For a non-ZST element this field is the
/// END pointer. The cursor models below lay further pointer-width lanes out
/// after it, so every offset here scales with the session's pointer width.
fn slice_iter_end_offset() -> u64 {
    session_pointer_bytes()
}

/// Compute the `(data_ptr, len)` of a slice / array reference operand for
/// `into_iter`. Handles `&[T]` (a memory-backed fat pointer, or a const-slice
/// reference) and `&[T; N]` (a thin pointer to the array; `len == N`).
fn slice_iter_data_and_len<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    operand: &Operand<'tcx>,
) -> Result<(ValueId, ValueId), String> {
    let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, operand)?);
    let ty::Ref(_, pointee, _) = arg_ty.kind() else {
        return Err(format!(
            "slice into_iter argument is not a reference: {arg_ty:?}"
        ));
    };
    let pointee = ctx.monomorphize_ty(*pointee);
    match pointee.kind() {
        // `&[T; N]`: a thin pointer to the array storage; the length is the const
        // `N`. The array is memory-backed (see `compute_memory_backed_locals`),
        // so a `&arr` argument is the array slot pointer (its data pointer).
        ty::Array(_, count) => {
            let n = count
                .try_to_target_usize(ctx.tcx)
                .ok_or_else(|| "slice into_iter array length is not a const usize".to_owned())?;
            let data = lower_operand_to_value(ctx, body, block, operand)?;
            let len = emit_i64_const(ctx, block, i128::from(n));
            Ok((data, len))
        }
        // `&[T]`: a fat pointer carrying `{ data, len }`. The argument local is a
        // memory-backed slice fat pointer; read its data half and length.
        ty::Slice(_) => {
            let (Operand::Copy(place) | Operand::Move(place)) = operand else {
                return Err("slice into_iter fat-pointer argument is not a place".to_owned());
            };
            if !place.projection.is_empty() {
                return Err("slice into_iter fat-pointer argument is projected".to_owned());
            }
            if !local_is_memory_backed(ctx, place.local) {
                return Err(
                    "slice into_iter fat-pointer argument is not a memory-backed slice".to_owned(),
                );
            }
            let data = load_fat_ptr_data(ctx, block, place.local)?;
            let len = load_fat_ptr_meta(ctx, block, place.local)?;
            Ok((data, len))
        }
        // `&str`: a fat pointer `{ data, len }` with the SAME representation as
        // `&[u8]` (`data` = the UTF-8 byte pointer, `len` = the byte length). Used
        // by `str::bytes()` -> `slice::Iter<u8>` over the string's bytes. Read the
        // two lanes exactly as the `&[u8]` slice arm above.
        ty::Str => {
            let (Operand::Copy(place) | Operand::Move(place)) = operand else {
                return Err("str bytes fat-pointer argument is not a place".to_owned());
            };
            if !place.projection.is_empty() {
                return Err("str bytes fat-pointer argument is projected".to_owned());
            }
            if !local_is_memory_backed(ctx, place.local) {
                return Err("str bytes fat-pointer argument is not a memory-backed &str".to_owned());
            }
            let data = load_fat_ptr_data(ctx, block, place.local)?;
            let len = load_fat_ptr_meta(ctx, block, place.local)?;
            Ok((data, len))
        }
        other => Err(format!(
            "slice into_iter over unsupported pointee {other:?}"
        )),
    }
}

/// Compute the byte address `slot_ptr + offset` for reading/writing an iterator
/// state field, reusing the verified `PtrToInt`/add/`IntToPtr` element-address
/// sequence (offset 0 is the slot pointer itself).
fn iter_field_addr(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    slot_ptr: ValueId,
    offset: u64,
) -> ValueId {
    if offset == 0 {
        return slot_ptr;
    }
    let index = emit_i64_const(ctx, block, i128::from(offset));
    emit_element_addr(ctx, block, slot_ptr, index, 1)
}

/// How the two fields of a `{ start, end }` element cursor encode positions.
/// The cursor drivers work in element POINTERS; an index cursor is converted at
/// each field load and store, so its stored state stays the source's own layout.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum SliceCursorRepr {
    /// Element pointers: `slice::Iter`, `vec::IntoIter`, `vec::Drain`.
    Pointers,
    /// `usize` element indices into an inline element buffer that begins
    /// `data_off` bytes after the `start` field: `array::IntoIter`'s
    /// `alive: IndexRange` and `data` ([`ArrayIntoIterLayout`]).
    Indices { data_off: u64 },
}

impl SliceCursorRepr {
    /// Fail closed where a driver reads or writes the cursor fields as raw
    /// pointers instead of through `emit_slice_cursor_load`/`_store`.
    fn require_pointers(self, driver: &str) -> Result<(), String> {
        match self {
            SliceCursorRepr::Pointers => Ok(()),
            SliceCursorRepr::Indices { .. } => Err(format!(
                "[TCG-ARRAY-INTOITER-CURSOR] {driver} drives its source cursor as raw element \
                 pointers, but an array::IntoIter source keeps rustc's `alive` index range; \
                 failing closed rather than reading indices as addresses"
            )),
        }
    }
}

/// The inline element buffer an index cursor whose `start` field sits at
/// `start_field` addresses; `None` for a pointer cursor.
fn emit_slice_cursor_data(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    start_field: ValueId,
    repr: SliceCursorRepr,
) -> Option<ValueId> {
    match repr {
        SliceCursorRepr::Pointers => None,
        SliceCursorRepr::Indices { data_off } => {
            Some(iter_field_addr(ctx, block, start_field, data_off))
        }
    }
}

/// Load one cursor field at `field_addr` as an element POINTER: the stored
/// pointer, or `data + index * elem_size` for an index cursor over `data`.
fn emit_slice_cursor_load(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    field_addr: ValueId,
    data: Option<ValueId>,
    elem_size: u64,
) -> ValueId {
    match data {
        None => emit_typed_load(ctx, block, field_addr, TrustIrTy::Ptr),
        Some(data) => {
            let index = emit_usize_field_load(ctx, block, field_addr);
            emit_element_addr(ctx, block, data, index, elem_size)
        }
    }
}

/// Store the element POINTER `ptr` into the cursor field at `field_addr`: the
/// pointer itself, or its element index `(ptr - data) / elem_size` for an index
/// cursor over `data` (`ptr` is always an element boundary in `data[0..=N]`, so
/// the division is exact).
fn emit_slice_cursor_store(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    field_addr: ValueId,
    data: Option<ValueId>,
    elem_size: u64,
    ptr: ValueId,
) {
    match data {
        None => emit_typed_store(block, field_addr, TrustIrTy::Ptr, ptr),
        Some(data) => {
            let ptr_int = emit_ptr_to_int(ctx, block, ptr);
            let data_int = emit_ptr_to_int(ctx, block, data);
            let bytes = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, ptr_int, data_int);
            let size = emit_i64_const(ctx, block, i128::from(elem_size));
            let index = emit_i64_binop(ctx, block, TrustIrBinOp::UDiv, bytes, size);
            emit_usize_field_store(ctx, block, field_addr, index);
        }
    }
}

/// `<Range<T> as Iterator>::next(&mut self) -> Option<T>`:
///
///     if self.start < self.end { let v = self.start; self.start += 1; Some(v) }
///     else { None }
///
/// Branchless: load `start`/`end`, `cond = start < end`, advance `start` only
/// when `cond` (a `Select`, so a finished range never mutates past its end), and
/// write the `Option<T>` (Direct-tagged: `tag = cond ? 1 : 0`, payload = `start`)
/// into the memory-backed destination slot.
fn lower_range_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    index_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("Range::next with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("Range::next into projected destination".to_owned());
    }
    let elem_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
    let (size, _align) = element_layout_size_align(ctx.tcx, index_ty)?;
    let signed = is_signed_trust_ir_integer(&elem_ty);

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;

    // TRANSLATION-VALIDATION CAPTURE (Phase P1, lane 7 — Range::next STATE
    // TRANSITION): record the block position BEFORE the `start`/`end` pre-state
    // loads + the `ICmp`/`Add`/`Select`s + the three stores so the exact emitted
    // trust-ir can be folded + refined against `range_next_spec` after the whole
    // statement is built. `slot_ptr` (self) and the destination slot pointer are
    // OUTSIDE the captured slice, so the fold names them symbolically.
    let refine = ctx.refinements_active();
    let refine_start = block.body.len();

    // Load start / end.
    let start_addr = iter_field_addr(ctx, block, slot_ptr, 0);
    let start = emit_typed_load(ctx, block, start_addr, elem_ty.clone());
    let end_addr = iter_field_addr(ctx, block, slot_ptr, size);
    let end = emit_typed_load(ctx, block, end_addr, elem_ty.clone());

    // cond = start < end (signed for a signed index, unsigned otherwise).
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
            ty: elem_ty.clone(),
            lhs: start,
            rhs: end,
        })
        .with_result(cond),
    );

    // advanced = start + 1; new_start = cond ? advanced : start (only advance in
    // range, matching the real `next` which leaves a finished range untouched).
    let one = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: elem_ty.clone(),
            value: Constant::Int(1),
        })
        .with_result(one),
    );
    let advanced = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: elem_ty.clone(),
            lhs: start,
            rhs: one,
        })
        .with_result(advanced),
    );
    let new_start = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: elem_ty.clone(),
            cond,
            then_val: advanced,
            else_val: start,
        })
        .with_result(new_start),
    );
    emit_typed_store(block, start_addr, elem_ty.clone(), new_start);

    // Write `Option<T>` into the destination slot: a Direct-tagged enum with
    // `tag = cond ? Some_discr : None_discr` and payload = the yielded `start`.
    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Scalar {
            value: start,
            ty: elem_ty,
        },
    )?;

    // Queue the lane-7 refinement job (lane 13: 1/2/4/8-byte elements — the
    // fold + spec are width-faithful; `elem_size` flows to the width-aware
    // obligations builder; a 16-byte element stays out of scope).
    // The `Option` layout data is re-derived INDEPENDENTLY through the same
    // helpers `store_option_some_value` used — it already errored out above if
    // the layout was missing, so these queries succeed in practice; still every
    // miss SKIPS (never turning a working compile into an error just to capture).
    //
    // RANGE-LAYOUT GUARD (adversarial-review defect 3): the lowering above
    // hardcodes `start @ 0` / `end @ size` — a SHARED assumption the spec
    // pairing would otherwise inherit (the exact StepBy hardcoded-offset bug
    // class). Consult rustc's layout oracle for `Range<T>`'s ACTUAL field
    // offsets (field 0 = `start`, field 1 = `end` by declaration index) and
    // queue the job only when they are `(0, size)` — under a reordered layout
    // (e.g. `-Z randomize-layout`) the refinement SKIPS rather than certifying
    // the offset-0 cell as "start". (The lowering itself under such a layout is
    // a separate pre-existing hazard, tracked as the Range-offset audit.)
    if refine && matches!(size, 1 | 2 | 4 | 8) {
        let range_layout_is_canonical = (|| {
            let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node).ok()?);
            let ty::Ref(_, range_ty, _) = self_ty.kind() else {
                return None;
            };
            let range_ty = ctx.monomorphize_ty(*range_ty);
            let layout = ctx
                .tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(range_ty))
                .ok()?;
            let rustc_abi::FieldsShape::Arbitrary { .. } = layout.fields else {
                return None;
            };
            if layout.fields.count() != 2 {
                return None;
            }
            Some(layout.fields.offset(0).bytes() == 0 && layout.fields.offset(1).bytes() == size)
        })()
        .unwrap_or(false);
        let tag = memory_aggregate_layout_shared(ctx.tcx, dest_ty)
            .ok()
            .flatten()
            .and_then(|layout| layout.tag.clone());
        if let Some(tag) = tag.filter(|_| range_layout_is_canonical) {
            if matches!(tag.encoding, MemoryTagEncoding::Direct) {
                if let (Ok((some_variant, none_variant, some_field_offset, _)), Ok(did)) = (
                    option_some_none_variants(ctx.tcx, dest_ty),
                    option_did(ctx.tcx, dest_ty),
                ) {
                    if let (Ok(some_discr), Ok(none_discr)) = (
                        adt_discriminant_value(ctx.tcx, did, some_variant),
                        adt_discriminant_value(ctx.tcx, did, none_variant),
                    ) {
                        if let (Some(dest_slot), Some(tag_width)) = (
                            ctx.memory_slots.get(&call.destination.local).map(|s| s.ptr),
                            mem_refine::scalar_byte_width(&tag.ty),
                        ) {
                            push_range_next_refinement(
                                ctx,
                                &block.body[refine_start..],
                                signed,
                                slot_ptr,
                                dest_slot,
                                size,
                                tag.offset,
                                tag_width,
                                some_field_offset,
                                some_discr as u64,
                                none_discr as u64,
                            );
                        }
                    }
                }
            }
        }
    }

    emit_call_successor(block, call.target);
    Ok(())
}

/// `<slice::Iter<T> as Iterator>::next(&mut self) -> Option<&T>`:
///
///     if self.ptr != self.end { let e = self.ptr; self.ptr += size; Some(&*e) }
///     else { None }
///
/// Branchless: load `ptr`/`end`, `cond = ptr != end`, advance `ptr` only when
/// `cond`, and write `Option<&T>` (a niche enum: `Some(p)` is the non-null `p`,
/// `None` is null) — `cond ? ptr : null` — into the destination slot.
fn lower_slice_iter_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    element_ty: Ty<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("slice Iter::next with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("slice Iter::next into projected destination".to_owned());
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;

    // TRANSLATION-VALIDATION CAPTURE (Phase P1, lane 9 — slice Iter::next STATE
    // TRANSITION, the `for x in slice` workhorse): record the block position
    // BEFORE the `ptr`/`end` pre-state loads + the `ICmp Ne`/advance/`Select`s +
    // the two stores so the exact emitted trust-ir can be folded + refined
    // against `slice_iter_next_spec` after the whole statement is built.
    // `slot_ptr` (self) and the destination slot pointer are OUTSIDE the
    // captured slice, so the fold names them symbolically.
    let refine = ctx.refinements_active();
    let refine_start = block.body.len();

    // Load ptr / end (both pointer-width).
    let ptr_addr = iter_field_addr(ctx, block, slot_ptr, 0);
    let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
    let end_addr = iter_field_addr(ctx, block, slot_ptr, slice_iter_end_offset());
    let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);

    // cond = ptr != end. Compare as integers (the verified pointer-comparison
    // route): a slice iterator is exhausted exactly when `ptr == end`.
    let ptr_int = emit_ptr_to_int(ctx, block, ptr);
    let end_int = emit_ptr_to_int(ctx, block, end);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: ptr_int,
            rhs: end_int,
        })
        .with_result(cond),
    );

    // advanced = ptr + size; new_ptr = cond ? advanced : ptr.
    let index_one = emit_i64_const(ctx, block, 1);
    let advanced = emit_element_addr(ctx, block, ptr, index_one, size);
    let new_ptr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::Ptr,
            cond,
            then_val: advanced,
            else_val: ptr,
        })
        .with_result(new_ptr),
    );
    emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, new_ptr);

    // Write `Option<&T>`: the yielded reference IS the (pre-advance) element
    // pointer `ptr`; `None` is the null pointer.
    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Reference { ptr },
    )?;

    // Queue the lane-9 refinement job. The `Option<&T>` layout data is re-derived
    // INDEPENDENTLY through the same helpers `store_option_some_value` used — it
    // already errored out above if the layout was missing, so these queries
    // succeed in practice; still every miss SKIPS (never turning a working
    // compile into an error just to capture). The spec hardcodes the null `None`,
    // so a `none_niche != 0` layout SKIPS rather than certifying a non-null
    // niche as "None".
    //
    // NO Range-layout-guard analogue is needed here (contrast lane 7's
    // RANGE-LAYOUT GUARD): the iterator slot layout `{ptr@0, end@8}` is the
    // bridge's OWN cursor model, not a rustc layout — both the constructor
    // (the `slice_iter_end_offset()` writes in the slice into_iter lowerings) and
    // this `next` use the same constants. That shared model is the
    // TRUSTED-MODEL BOUNDARY of this lane: the refinement certifies `next`
    // faithful to the Rust iterator semantics OVER that model, and the
    // ctor/next agreement is by shared-constant construction.
    if refine {
        let tag = memory_aggregate_layout_shared(ctx.tcx, dest_ty)
            .ok()
            .flatten()
            .and_then(|layout| layout.tag.clone());
        if let Some(tag) = tag {
            if let MemoryTagEncoding::Niche {
                untagged_variant,
                niche_variants_start,
                niche_start,
                ..
            } = &tag.encoding
            {
                if let Ok((some_variant, none_variant, _, _)) =
                    option_some_none_variants(ctx.tcx, dest_ty)
                {
                    if *untagged_variant == some_variant {
                        // The `None` niche exactly as the Reference arm computed
                        // it (the arm already ran without error, so this
                        // subtraction cannot underflow); REQUIRED == 0 — the
                        // spec's `None` is the null pointer.
                        let none_rel =
                            none_variant.as_u32() as u128 - niche_variants_start.as_u32() as u128;
                        let none_niche = niche_start.wrapping_add(none_rel);
                        if none_niche == 0 {
                            if let Some(dest_slot) =
                                ctx.memory_slots.get(&call.destination.local).map(|s| s.ptr)
                            {
                                push_slice_iter_next_refinement(
                                    ctx,
                                    &block.body[refine_start..],
                                    slot_ptr,
                                    dest_slot,
                                    size,
                                    slice_iter_end_offset(),
                                    tag.offset,
                                );
                            }
                        }
                    }
                }
            }
        }
    }

    emit_call_successor(block, call.target);
    Ok(())
}

/// Compute a `.zip()` side's element `i` off the (un-advanced) sub-iterator state
/// at `slot_ptr + source_offset + side.offset`. Byte-identical to
/// `emit_source_next`'s Zip-arm `side_elem` (the terminal-drive path): a slice
/// side yields the POINTER `base + i*stride` (a `&T`); a 64-bit Range side yields
/// the VALUE `start + i` (`__iterator_get_unchecked(i)` == `Step::forward(start,
/// i)`). The `start`/`base` fields are the ORIGINAL state (TRA never advances the
/// sub-iterators), so this is a random-access read.
fn emit_zip_side_elem<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    slot_ptr: ValueId,
    source_offset: u64,
    index: ValueId,
    side: &ZipSide<'tcx>,
) -> ValueId {
    match side.kind {
        ZipSideKind::SlicePtr => {
            let base_addr = iter_field_addr(ctx, block, slot_ptr, source_offset + side.offset);
            let base = emit_typed_load(ctx, block, base_addr, TrustIrTy::Ptr);
            emit_element_addr(ctx, block, base, index, side.elem_size)
        }
        ZipSideKind::RangeStart => {
            let word = zip_range_word_ty(side);
            let start_addr = iter_field_addr(ctx, block, slot_ptr, source_offset + side.offset);
            let start = emit_typed_load(ctx, block, start_addr, word.clone());
            let result = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Add,
                    ty: word,
                    lhs: start,
                    rhs: index,
                })
                .with_result(result),
            );
            result
        }
    }
}

/// The integer type a pointer-width `Range` zip side's `start`/`end` (and the
/// `start + index` it yields) are read and computed in: its own width, which
/// `resolve_zip` admits only when it equals `usize`'s — `I64` on a 64-bit
/// target, `I32` on a 32-bit one — so the add against the `usize` cursor
/// ([`usize_field_ty`]) is one same-width add.
fn zip_range_word_ty(side: &ZipSide<'_>) -> TrustIrTy {
    if side.elem_size == 4 {
        TrustIrTy::I32
    } else {
        TrustIrTy::I64
    }
}

/// The trust-ir type of a `.zip()` side's THREADED representation (a `Ptr` for a
/// slice side's `&T`; the 64-bit scalar itself for a Range side).
fn zip_side_repr_ir(side: &ZipSide<'_>) -> TrustIrTy {
    match side.kind {
        ZipSideKind::SlicePtr => TrustIrTy::Ptr,
        ZipSideKind::RangeStart => zip_range_word_ty(side),
    }
}

/// `<Zip<A, B> as Iterator>::next(&mut self) -> Option<(A::Item, B::Item)>` for a
/// bridge-MODELED, forward, unadapted, unclamped TRA Zip (`chain.source ==
/// ChainSource::Zip`). Synthesizes std's `TrustedRandomAccess` specialization
/// EXACTLY: keep an `index`/`len` cursor, NEVER advance the sub-iterators, read
/// element `index` off each side's original state, and `index += 1` on yield.
///
///     if index < len { let e = (side_a[index], side_b[index]); index += 1; Some(e) }
///     else { None }
///
/// Branchless: `cond = index <u len`, `new_index = cond ? index+1 : index`, and a
/// `cond ? Some((a,b)) : None` write through `store_option_some_value`. The element
/// math is byte-identical to the terminal Zip drive (measured == LLVM). Every
/// unmodeled Option layout (e.g. the 24-byte direct-tagged `(val,val)` range+range
/// case) fails closed in `store_option_some_value`, never a miscompile.
fn lower_zip_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("Zip::next with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("Zip::next into projected destination".to_owned());
    }
    // Defensive: only a bare forward unadapted zip reaches here (the caller gates
    // on exactly this), but re-check so a future caller cannot slip a reversed /
    // adapted / clamped chain into the un-advancing single-step model.
    if chain.reversed || chain.rev_clamp.is_some() || !chain.adapters.is_empty() {
        return Err("lower_zip_next on a reversed/clamped/adapted zip".to_owned());
    }
    let ChainSource::Zip {
        a,
        b,
        index_offset,
        len_offset,
    } = &chain.source
    else {
        return Err("lower_zip_next on a non-Zip chain".to_owned());
    };
    let src_off = chain.source_offset;

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;

    // Load `index` / `len` (both `usize` fields, `usize_field_ty`).
    let word = usize_field_ty(ctx.tcx);
    let index_addr = iter_field_addr(ctx, block, slot_ptr, src_off + *index_offset);
    let index = emit_typed_load(ctx, block, index_addr, word.clone());
    let len_addr = iter_field_addr(ctx, block, slot_ptr, src_off + *len_offset);
    let len = emit_typed_load(ctx, block, len_addr, word.clone());

    // cond = index <u len (usize, unsigned).
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ult,
            ty: word.clone(),
            lhs: index,
            rhs: len,
        })
        .with_result(cond),
    );

    // Per-side element `index` (identical math to the terminal Zip drive).
    let a_elem = emit_zip_side_elem(ctx, block, slot_ptr, src_off, index, a);
    let b_elem = emit_zip_side_elem(ctx, block, slot_ptr, src_off, index, b);

    // new_index = cond ? index+1 : index (advance only when yielding).
    let one = emit_usize_field_const(ctx, block, 1);
    let advanced = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: word.clone(),
            lhs: index,
            rhs: one,
        })
        .with_result(advanced),
    );
    let new_index = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: word.clone(),
            cond,
            then_val: advanced,
            else_val: index,
        })
        .with_result(new_index),
    );
    emit_typed_store(block, index_addr, word, new_index);

    // Write `Option<(A::Item, B::Item)>`: at least one component is a niche
    // pointer (slice side), so the Option is niche-encoded — the `(val, val)`
    // range+range direct-tagged case fails closed in `store_option_some_value`.
    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Tuple2 {
            a: a_elem,
            a_ir: zip_side_repr_ir(a),
            b: b_elem,
            b_ir: zip_side_repr_ir(b),
        },
    )?;

    emit_call_successor(block, call.target);
    Ok(())
}

/// If `ty` resolves to EXACTLY a `.step_by(k)` over a bare, FORWARD, unadapted
/// `Range<scalar>` or `slice::Iter<scalar>` source — the ONLY shape whose
/// single-step `StepBy::next` this backend reproduces bit-identically — return the
/// resolved chain. Any other shape (a StepBy nested UNDER or wrapping another
/// adapter, a reversed / rev-clamped chain, a `RangeInclusive` / `Chain` / `Zip`
/// source, or a tuple item) returns `None`, so the caller keeps failing closed.
/// Fail-safe by construction: the accepted set is a strict subset of what the
/// `.step_by()` constructor (`lower_iter_structural_ctor`) builds core's
/// `StepBy::new` state for, so `next` reads exactly the layout the ctor wrote.
fn resolve_bare_stepby_chain<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<IterChain<'tcx>>, String> {
    let Some(chain) = resolve_iter_chain(ctx, ty)? else {
        return Ok(None);
    };
    if chain.reversed || chain.rev_clamp.is_some() {
        return Ok(None);
    }
    if chain.adapters.len() != 1 || !matches!(chain.adapters[0].0.kind, AdapterKind::StepBy { .. })
    {
        return Ok(None);
    }
    if chain.item.tuple.is_some() {
        return Ok(None);
    }
    if !matches!(
        chain.source,
        ChainSource::Range { .. } | ChainSource::Slice { .. }
    ) {
        return Ok(None);
    }
    Ok(Some(chain))
}

/// If `ty` resolves to EXACTLY a `.filter(p)` over a bare, FORWARD, unadapted
/// `Range<scalar>` or `slice::Iter<scalar>` source — the ONLY shape whose
/// single-step `Filter::next` this backend reproduces bit-identically — return the
/// resolved chain. Any other shape (a Filter nested UNDER or wrapping another
/// adapter, a reversed / rev-clamped chain, a `RangeInclusive` / `Chain` / `Zip`
/// source, or a tuple item) returns `None`, so the caller keeps failing closed.
/// Fail-safe by construction: the accepted set is a strict subset of what the
/// `.filter()` constructor (`lower_iter_adapter_ctor`) already synthesizes the
/// bridge's `Filter { iter, predicate }` slot for, AND of what the terminal
/// consumer (`emit_chain_next`'s `Filter` arm) already drives ==LLVM — so `next`
/// reads exactly the layout the ctor wrote and skips exactly the elements the
/// terminal drive skips.
fn resolve_bare_filter_chain<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<IterChain<'tcx>>, String> {
    let Some(chain) = resolve_iter_chain(ctx, ty)? else {
        return Ok(None);
    };
    if chain.reversed || chain.rev_clamp.is_some() {
        return Ok(None);
    }
    if chain.adapters.len() != 1 || !matches!(chain.adapters[0].0.kind, AdapterKind::Filter) {
        return Ok(None);
    }
    if chain.item.tuple.is_some() {
        return Ok(None);
    }
    if !matches!(
        chain.source,
        ChainSource::Range { .. } | ChainSource::Slice { .. } | ChainSource::RangeInclusive { .. }
    ) {
        return Ok(None);
    }
    // `lower_filter_next` yields the value it stored for the predicate's `&item`;
    // these sources yield integers and `&T`, which no predicate can change.
    if chain_item_writable_through_shared_ref(ctx, &chain.item) {
        return Ok(None);
    }
    Ok(Some(chain))
}

/// The bridge-MODELED bare/forward `.filter_map(f)` shape `lower_filter_map_next`
/// accepts: a SINGLE `FilterMap` adapter (no other adapter above/below), NOT
/// reversed / rev-clamped, over a Range / slice::Iter / RangeInclusive source.
/// A tuple output item (impossible for `filter_map`, whose closure returns a
/// scalar `Option<U>`) is rejected defensively. Anything else -> `Ok(None)` (the
/// caller falls through to fail closed, never a miscompile). Mirrors
/// `resolve_bare_filter_chain`.
fn resolve_bare_filtermap_chain<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<IterChain<'tcx>>, String> {
    let Some(chain) = resolve_iter_chain(ctx, ty)? else {
        return Ok(None);
    };
    if chain.reversed || chain.rev_clamp.is_some() {
        return Ok(None);
    }
    if chain.adapters.len() != 1 || !matches!(chain.adapters[0].0.kind, AdapterKind::FilterMap) {
        return Ok(None);
    }
    if chain.item.tuple.is_some() {
        return Ok(None);
    }
    if !matches!(
        chain.source,
        ChainSource::Range { .. } | ChainSource::Slice { .. } | ChainSource::RangeInclusive { .. }
    ) {
        return Ok(None);
    }
    Ok(Some(chain))
}

/// `<StepBy<Range<T>> | StepBy<slice::Iter<T>> as IntoIterator>::into_iter(self)`
/// — the IDENTITY (`IntoIterator for I: Iterator` returns `self`). Copy the whole
/// StepBy state slot (std's layout, built by the `.step_by()` constructor) from
/// the moved-in source into the destination iterator slot. Only the
/// bridge-modeled bare/forward shape reaches here.
fn lower_stepby_into_iter<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    iter_ty: Ty<'tcx>,
) -> Result<(), String> {
    let _ = body;
    if call.args.len() != 1 {
        return Err(format!("StepBy::into_iter with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("StepBy::into_iter into projected destination".to_owned());
    }
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "StepBy::into_iter destination is not memory-backed".to_owned())?
        .ptr;
    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        return Err("StepBy::into_iter argument is not a place".to_owned());
    };
    if !src.projection.is_empty() {
        return Err("StepBy::into_iter argument uses a projected place".to_owned());
    }
    let src_slot = ctx
        .memory_slots
        .get(&src.local)
        .cloned()
        .ok_or_else(|| "StepBy::into_iter argument is not memory-backed".to_owned())?
        .ptr;
    let size = iter_state_slot_size(ctx, iter_ty)?;
    copy_slot_bytes(ctx, block, src_slot, 0, dest_slot, 0, size)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// `<StepBy<Range<T>> | StepBy<slice::Iter<T>> as Iterator>::next(&mut self)` for
/// a bridge-MODELED, bare/forward/unadapted `.step_by(k)` (the ONLY shape
/// `resolve_bare_stepby_chain` accepts), over std's layout. A countdown `Range`
/// (`range_countdown`) is core's `spec_next` ([`lower_step_by_countdown_next`]).
/// Every other source is core's default `spec_next`, `nth(first_take ? 0 :
/// step_minus_one)`, which selects element 0 first and then lands each
/// subsequent yield `k` elements further along:
///
///     countdown = first_take ? 0 : step_minus_one
///     y         = source_position + countdown // the element to yield
///     if y in [source_position, end):
///         yield element(y); advance source past y; first_take := false
///     else: None
///
/// STRAIGHT-LINE (no inner loop): both sources are random-access, so the
/// `nth(k-1)` skip is a closed-form offset (`start + countdown` for a Range,
/// `ptr + countdown*stride` for a slice). All index math is widened to `I64` so a
/// narrow-element `start + countdown` cannot wrap back into range; a genuine
/// 64-bit overflow is caught by the `y >= source_position` guard (matching std's
/// `forward_checked` → `None`). Byte-identical to the terminal-drive StepBy model
/// in `emit_chain_next`.
fn lower_step_by_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("StepBy::next with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("StepBy::next into projected destination".to_owned());
    }
    // Defensive re-check (the caller already gates on exactly this shape).
    if chain.reversed || chain.rev_clamp.is_some() || chain.adapters.len() != 1 {
        return Err("lower_step_by_next on a reversed/clamped/multi-adapter chain".to_owned());
    }
    let AdapterKind::StepBy {
        step_minus_one_off,
        first_take_off,
        range_countdown,
    } = chain.adapters[0].0.kind
    else {
        return Err("lower_step_by_next on a non-StepBy chain".to_owned());
    };
    if range_countdown {
        return lower_step_by_countdown_next(ctx, body, block, call, chain, step_minus_one_off);
    }
    let src_off = chain.source_offset;

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;

    // TRANSLATION-VALIDATION CAPTURE (Phase P1, lane 11 — StepBy::next STATE
    // TRANSITION, the WIDTH-FAITHFUL lane): record the block position right
    // after the self slot pointer — BEFORE the `Const 0`, the address chains,
    // the `step_minus_one`/`first_take`/`start`/`end` pre-state loads (incl.
    // the NARROW I8 `first_take` load + `ZExt`), the `ICmp`s/`And`/`Select`s,
    // the `Trunc`, and the four stores — so the exact emitted trust-ir can be
    // folded + refined against `step_by_next_spec` after the whole statement
    // is built. `slot_ptr` (self) and the destination slot pointer are OUTSIDE
    // the captured slice, so the fold names them symbolically. Only the
    // SIGNED-Range-i64 std-layout path queues (v1); everything else SKIPS —
    // including a 32-bit target, whose `usize`-width `step_minus_one` access is
    // not the I64 shape `step_by_next_spec` folds.
    let refine = ctx.refinements_active() && usize_field_ty(ctx.tcx) == TrustIrTy::I64;
    let refine_start = block.body.len();

    // std's `{step_minus_one: usize, first_take: bool}` at their independently
    // rustc-layout-derived offsets; the "next element to yield" is at
    // `start + countdown` (countdown = 0 on the very first pull).
    let zero_c = emit_i64_const(ctx, block, 0);
    let state_addr = iter_field_addr(ctx, block, slot_ptr, step_minus_one_off);
    let ft_addr = iter_field_addr(ctx, block, slot_ptr, first_take_off);
    // `step_minus_one` is a `usize` field: read at its own width, then
    // zero-extended into the I64 index math (a no-op on a 64-bit target).
    let sm_ty = usize_field_ty(ctx.tcx);
    let sm = emit_typed_load(ctx, block, state_addr, sm_ty.clone());
    let sm = emit_extend_to_i64(ctx, block, &sm_ty, false, sm);
    let ft_i8 = emit_typed_load(ctx, block, ft_addr, TrustIrTy::I8);
    let ft = emit_extend_to_i64(ctx, block, &TrustIrTy::I8, false, ft_i8);
    let ft_nz = emit_i64_icmp(ctx, block, ICmpOp::Ne, ft, zero_c);
    // countdown = first_take ? 0 : step_minus_one.
    let countdown = emit_i64_select(ctx, block, ft_nz, zero_c, sm);

    match &chain.source {
        ChainSource::Range {
            index_ty,
            ir_ty,
            size,
        } => {
            let _ = index_ty;
            let elem_ty = ir_ty.clone();
            let signed = is_signed_trust_ir_integer(&elem_ty);
            // start / end at the Range's field offsets within the StepBy slot.
            let start_addr = iter_field_addr(ctx, block, slot_ptr, src_off);
            let start = emit_typed_load(ctx, block, start_addr, elem_ty.clone());
            let end_addr = iter_field_addr(ctx, block, slot_ptr, src_off + *size);
            let end = emit_typed_load(ctx, block, end_addr, elem_ty.clone());
            // Widen to I64 (sext/zext by signedness) so `start + countdown` cannot
            // wrap the element width.
            let start_w = emit_extend_to_i64(ctx, block, &elem_ty, signed, start);
            let end_w = emit_extend_to_i64(ctx, block, &elem_ty, signed, end);
            // y = start + countdown (the next element to yield).
            let y = emit_i64_binop(ctx, block, TrustIrBinOp::Add, start_w, countdown);
            // cond = (y >= start) AND (y < end), signed/unsigned per the index type.
            let (ge_op, lt_op) = if signed {
                (ICmpOp::Sge, ICmpOp::Slt)
            } else {
                (ICmpOp::Uge, ICmpOp::Ult)
            };
            let no_overflow = emit_i64_icmp(ctx, block, ge_op, y, start_w);
            let in_range = emit_i64_icmp(ctx, block, lt_op, y, end_w);
            let cond = emit_bool_and(ctx, block, no_overflow, in_range);
            // Yielded value (narrowed to element width) and advanced start = y + 1.
            let yval = emit_trunc_from_i64(ctx, block, &elem_ty, y);
            let one = emit_i64_const(ctx, block, 1);
            let y_plus1 = emit_i64_binop(ctx, block, TrustIrBinOp::Add, y, one);
            let new_start_yield = emit_trunc_from_i64(ctx, block, &elem_ty, y_plus1);
            let new_start = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: elem_ty.clone(),
                    cond,
                    then_val: new_start_yield,
                    else_val: start,
                })
                .with_result(new_start),
            );
            emit_typed_store(block, start_addr, elem_ty.clone(), new_start);
            // Advance the step state (only on a yield): clear `first_take`.
            let new_ft = emit_i64_select(ctx, block, cond, zero_c, ft);
            let new_ft8 = emit_trunc_from_i64(ctx, block, &TrustIrTy::I8, new_ft);
            emit_typed_store(block, ft_addr, TrustIrTy::I8, new_ft8);
            // Write `Option<T>`: `Some(yval)` when `cond`, else `None`.
            let dest_ty = place_rust_ty(ctx, body, call.destination);
            store_option_some_value(
                ctx,
                body,
                block,
                call.destination.local,
                dest_ty,
                cond,
                OptionPayload::Scalar {
                    value: yval,
                    ty: elem_ty.clone(),
                },
            )?;

            // Queue the lane-11 refinement job — SIGNED-Range-i64 ONLY in v1
            // (a non-I64 element or a non-Direct `Option` layout SKIPS). The
            // `Option` layout data is re-derived INDEPENDENTLY
            // through the same helpers `store_option_some_value` used — it
            // already errored out above if the layout was missing, so these
            // queries succeed in practice; still every miss SKIPS (never
            // turning a working compile into an error just to capture).
            if refine && signed && matches!(elem_ty, TrustIrTy::I64) && *size == 8 {
                let tag = memory_aggregate_layout_shared(ctx.tcx, dest_ty)
                    .ok()
                    .flatten()
                    .and_then(|layout| layout.tag.clone());
                if let Some(tag) = tag {
                    if matches!(tag.encoding, MemoryTagEncoding::Direct) {
                        if let (Ok((some_variant, none_variant, some_field_offset, _)), Ok(did)) = (
                            option_some_none_variants(ctx.tcx, dest_ty),
                            option_did(ctx.tcx, dest_ty),
                        ) {
                            if let (Ok(some_discr), Ok(none_discr)) = (
                                adt_discriminant_value(ctx.tcx, did, some_variant),
                                adt_discriminant_value(ctx.tcx, did, none_variant),
                            ) {
                                if let (Some(dest_slot), Some(tag_width)) = (
                                    ctx.memory_slots.get(&call.destination.local).map(|s| s.ptr),
                                    mem_refine::scalar_byte_width(&tag.ty),
                                ) {
                                    push_step_by_next_refinement(
                                        ctx,
                                        &block.body[refine_start..],
                                        slot_ptr,
                                        dest_slot,
                                        step_minus_one_off,
                                        first_take_off,
                                        src_off,
                                        tag.offset,
                                        tag_width,
                                        some_field_offset,
                                        some_discr as u64,
                                        none_discr as u64,
                                    );
                                }
                            }
                        }
                    }
                }
            }
        }
        ChainSource::Slice {
            element_ty,
            ir_ty,
            size,
            end_off,
            repr,
            ..
        } => {
            repr.require_pointers("`StepBy::next`")?;
            let _ = (element_ty, ir_ty);
            let ptr_addr = iter_field_addr(ctx, block, slot_ptr, src_off);
            let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
            let end_addr = iter_field_addr(ctx, block, slot_ptr, src_off + *end_off);
            let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
            // y_ptr = ptr + countdown*stride (the element to yield); advance one
            // more stride past it.
            let y_ptr = emit_element_addr(ctx, block, ptr, countdown, *size);
            let one_idx = emit_i64_const(ctx, block, 1);
            let advanced = emit_element_addr(ctx, block, y_ptr, one_idx, *size);
            let ptr_int = emit_ptr_to_int(ctx, block, ptr);
            let end_int = emit_ptr_to_int(ctx, block, end);
            let y_int = emit_ptr_to_int(ctx, block, y_ptr);
            // cond = (y >= ptr) AND (y < end), unsigned address comparison.
            let no_overflow = emit_i64_icmp(ctx, block, ICmpOp::Uge, y_int, ptr_int);
            let in_range = emit_i64_icmp(ctx, block, ICmpOp::Ult, y_int, end_int);
            let cond = emit_bool_and(ctx, block, no_overflow, in_range);
            let new_ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Ptr,
                    cond,
                    then_val: advanced,
                    else_val: ptr,
                })
                .with_result(new_ptr),
            );
            emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, new_ptr);
            // Advance the step state (only on a yield): clear `first_take`.
            let new_ft = emit_i64_select(ctx, block, cond, zero_c, ft);
            let new_ft8 = emit_trunc_from_i64(ctx, block, &TrustIrTy::I8, new_ft);
            emit_typed_store(block, ft_addr, TrustIrTy::I8, new_ft8);
            // Write `Option<&T>`: `Some(y_ptr)` (the element reference) when `cond`,
            // else `None` (the null pointer).
            let dest_ty = place_rust_ty(ctx, body, call.destination);
            store_option_some_value(
                ctx,
                body,
                block,
                call.destination.local,
                dest_ty,
                cond,
                OptionPayload::Reference { ptr: y_ptr },
            )?;

            // Queue the lane-12b refinement job — the STD-LAYOUT SLICE-source
            // path. The `Option<&T>` layout data is re-derived INDEPENDENTLY
            // through the same helpers `store_option_some_value` used (exactly
            // the lane-9 gating): the dest must be NICHE-encoded with
            // `untagged_variant == Some` and a NULL (0) `None` niche — the
            // spec hardcodes the null `None`, so any other layout SKIPS
            // rather than certifying a non-null niche as "None". The
            // `{ptr@src_off, end@src_off+8}` cursor is the bridge's OWN model
            // (`slice_iter_end_offset()`, the lane-9 trusted-model boundary); any
            // other `end` distance SKIPS. Every miss SKIPS (skip-not-fail).
            if refine && *end_off == slice_iter_end_offset() {
                let tag = memory_aggregate_layout_shared(ctx.tcx, dest_ty)
                    .ok()
                    .flatten()
                    .and_then(|layout| layout.tag.clone());
                if let Some(tag) = tag {
                    if let MemoryTagEncoding::Niche {
                        untagged_variant,
                        niche_variants_start,
                        niche_start,
                        ..
                    } = &tag.encoding
                    {
                        if let Ok((some_variant, none_variant, _, _)) =
                            option_some_none_variants(ctx.tcx, dest_ty)
                        {
                            if *untagged_variant == some_variant {
                                // The `None` niche exactly as the Reference arm
                                // computed it; REQUIRED == 0 — the spec's
                                // `None` is the null pointer.
                                let none_rel = none_variant.as_u32() as u128
                                    - niche_variants_start.as_u32() as u128;
                                let none_niche = niche_start.wrapping_add(none_rel);
                                if none_niche == 0 && *size > 0 {
                                    if let Some(dest_slot) =
                                        ctx.memory_slots.get(&call.destination.local).map(|s| s.ptr)
                                    {
                                        push_step_by_next_slice_refinement(
                                            ctx,
                                            &block.body[refine_start..],
                                            slot_ptr,
                                            dest_slot,
                                            step_minus_one_off,
                                            first_take_off,
                                            src_off,
                                            *size,
                                            tag.offset,
                                        );
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        _ => return Err("lower_step_by_next on an unmodeled source".to_owned()),
    }

    emit_call_successor(block, call.target);
    Ok(())
}

/// core's `spec_next` for a countdown `StepBy<Range<T>>` ([`step_by_range_countdown`];
/// `end` holds the number of items still to yield):
///
///     step = T::try_from(step_minus_one + 1).unwrap_or(T::MAX)
///     if end > 0 { yield start; start = start.wrapping_add(step); end -= 1 }
///     else { None }
///
/// `first_take` is neither read nor written, exactly as in core.
fn lower_step_by_countdown_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
    step_minus_one_off: u64,
) -> Result<(), String> {
    let ChainSource::Range { ir_ty, size, .. } = &chain.source else {
        return Err("countdown StepBy::next over a non-Range source".to_owned());
    };
    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    // TRANSLATION-VALIDATION CAPTURE (lane 12c): record the block position
    // right after the self slot pointer, so the exact trust-ir emitted below
    // (the address chains, the `step_minus_one`/`start`/`end` loads, the
    // advance and the four stores) can be folded and refined against
    // `step_by_countdown_next_spec` once the statement is built. The self and
    // destination slot pointers are OUTSIDE the captured slice. Only a 64-bit
    // element (`u64`, or `usize` on a 64-bit target) queues: a narrower `T`
    // emits narrow arithmetic and the `T::MAX` step clamp, which the fold
    // does not model.
    let refine = ctx.refinements_active()
        && usize_field_ty(ctx.tcx) == TrustIrTy::I64
        && matches!(ir_ty, TrustIrTy::U64)
        && *size == 8;
    let refine_start = block.body.len();
    let sm_addr = iter_field_addr(ctx, block, slot_ptr, step_minus_one_off);
    let step = emit_step_by_range_step(ctx, block, sm_addr, ir_ty)?;
    let start_addr = iter_field_addr(ctx, block, slot_ptr, chain.source_offset);
    let end_addr = iter_field_addr(ctx, block, slot_ptr, chain.source_offset + *size);
    let start = emit_typed_load(ctx, block, start_addr, ir_ty.clone());
    let end = emit_typed_load(ctx, block, end_addr, ir_ty.clone());
    let next = emit_step_by_countdown_advance(ctx, block, ir_ty, start, end, step);
    emit_typed_store(block, start_addr, ir_ty.clone(), next.new_start);
    emit_typed_store(block, end_addr, ir_ty.clone(), next.new_end);
    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        next.cond,
        OptionPayload::Scalar {
            value: start,
            ty: ir_ty.clone(),
        },
    )?;
    // Queue the lane-12c job. The `Option` cells are re-derived independently
    // through the helpers `store_option_some_value` used (it already failed
    // above if the layout was missing); a non-Direct tag or any other miss
    // SKIPS, never turning a working compile into an error just to capture.
    if refine {
        if let Some(cells) = direct_option_refine_cells(ctx, call.destination.local, dest_ty) {
            push_step_by_countdown_next_refinement(
                ctx,
                &block.body[refine_start..],
                slot_ptr,
                step_minus_one_off,
                chain.source_offset,
                cells,
            );
        }
    }
    emit_call_successor(block, call.target);
    Ok(())
}

/// The Direct-tagged `Option<T>` destination cells a value-refinement capture
/// re-derives from the layout, independently of the emission.
struct DirectOptionRefineCells {
    /// The destination slot pointer (the base of the tag/payload cells).
    dest_slot: ValueId,
    /// Byte offset and LAYOUT width of the tag scalar.
    tag_off: u64,
    tag_width: u32,
    /// Byte offset of the `Some` payload.
    payload_off: u64,
    /// The `Some` / `None` discriminant values.
    some_discr: u64,
    none_discr: u64,
}

/// [`DirectOptionRefineCells`] for the memory-backed `dest_local` of type
/// `dest_ty`, or `None` (the capture skips) when the layout is not a
/// Direct-tagged `Option` or any query misses.
fn direct_option_refine_cells<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    dest_local: Local,
    dest_ty: Ty<'tcx>,
) -> Option<DirectOptionRefineCells> {
    let tag = memory_aggregate_layout_shared(ctx.tcx, dest_ty)
        .ok()
        .flatten()
        .and_then(|layout| layout.tag.clone())?;
    if !matches!(tag.encoding, MemoryTagEncoding::Direct) {
        return None;
    }
    let (some_variant, none_variant, payload_off, _) =
        option_some_none_variants(ctx.tcx, dest_ty).ok()?;
    let did = option_did(ctx.tcx, dest_ty).ok()?;
    let some_discr = adt_discriminant_value(ctx.tcx, did, some_variant).ok()?;
    let none_discr = adt_discriminant_value(ctx.tcx, did, none_variant).ok()?;
    Some(DirectOptionRefineCells {
        dest_slot: ctx.memory_slots.get(&dest_local)?.ptr,
        tag_off: tag.offset,
        tag_width: mem_refine::scalar_byte_width(&tag.ty)?,
        payload_off,
        some_discr: some_discr as u64,
        none_discr: none_discr as u64,
    })
}

/// The step core's countdown `spec_next` adds to `start`:
/// `T::try_from(step_minus_one + 1).unwrap_or(T::MAX)`, as an `ir_ty` value,
/// from the `step_minus_one` field at `sm_addr`.
fn emit_step_by_range_step(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    sm_addr: ValueId,
    ir_ty: &TrustIrTy,
) -> Result<ValueId, String> {
    let width = ir_ty
        .bit_width()
        .filter(|w| *w <= 64)
        .ok_or_else(|| format!("countdown step_by over a {ir_ty:?} range"))?;
    let sm_ty = usize_field_ty(ctx.tcx);
    let sm = emit_typed_load(ctx, block, sm_addr, sm_ty.clone());
    let sm = emit_extend_to_i64(ctx, block, &sm_ty, false, sm);
    // `step_minus_one < usize::MAX` (core's type invariant), so `+ 1` cannot wrap.
    let one = emit_i64_const(ctx, block, 1);
    let step = emit_i64_binop(ctx, block, TrustIrBinOp::Add, sm, one);
    let step = if width < 64 {
        let max = emit_i64_const(ctx, block, (1i128 << width) - 1);
        let over = emit_i64_icmp(ctx, block, ICmpOp::Ugt, step, max);
        emit_i64_select(ctx, block, over, max, step)
    } else {
        step
    };
    Ok(emit_trunc_from_i64(ctx, block, ir_ty, step))
}

/// One countdown `StepBy<Range<T>>` pull over the loaded `start` / `end`
/// (`end` = items left): `cond = end != 0`; on a yield `start` advances by
/// `step` (wrapping, in `T`) and `end` decrements; otherwise both stay.
struct StepByCountdownNext {
    cond: ValueId,
    new_start: ValueId,
    new_end: ValueId,
}

fn emit_step_by_countdown_advance(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    ir_ty: &TrustIrTy,
    start: ValueId,
    end: ValueId,
    step: ValueId,
) -> StepByCountdownNext {
    let zero = emit_typed_const(ctx, block, ir_ty.clone(), 0);
    let one = emit_typed_const(ctx, block, ir_ty.clone(), 1);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: ir_ty.clone(),
            lhs: end,
            rhs: zero,
        })
        .with_result(cond),
    );
    let mut binop = |op, lhs, rhs| {
        let result = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op,
                ty: ir_ty.clone(),
                lhs,
                rhs,
            })
            .with_result(result),
        );
        result
    };
    let stepped = binop(TrustIrBinOp::Add, start, step);
    let left = binop(TrustIrBinOp::Sub, end, one);
    let mut select = |then_val, else_val| {
        let result = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Select {
                ty: ir_ty.clone(),
                cond,
                then_val,
                else_val,
            })
            .with_result(result),
        );
        result
    };
    let new_start = select(stepped, start);
    let new_end = select(left, end);
    StepByCountdownNext {
        cond,
        new_start,
        new_end,
    }
}

/// `<Filter<Range<T>, P> | Filter<slice::Iter<T>, P> as Iterator>::next(&mut self)`
/// for a bridge-MODELED, bare/forward/unadapted `.filter(p)` (the ONLY shape
/// `resolve_bare_filter_chain` accepts). Reproduces std's `Filter::next` (whose
/// body is `self.iter.find(&mut self.predicate)`) EXACTLY: pull source elements —
/// each pull ADVANCES + commits the source cursor in the slot, so a rejected
/// element is consumed — until the predicate accepts one (yield `Some`) or the
/// source is exhausted (yield `None`). Byte-identical to `emit_chain_next`'s
/// `Filter` arm (measured ==LLVM as a terminal drive): the SAME source-cursor
/// advance and the SAME `predicate(&item)` call, only exposed as a single
/// `Iterator::next` rather than a fused terminal loop.
///
/// Block structure (`block` is the caller's current block; the rest go to
/// `ctx.extra_blocks`). The source cursor is MEMORY-BACKED in the slot, re-loaded
/// each header pass and stored back on advance, so the skip-loop needs NO SSA
/// loop-carried value / phi (exactly the memory-backed loop-state model the
/// terminal consumers already use):
///
///   block:  filter_ref = alloca; -> header
///   header: load source cursor; cond = has_next; advance+store cursor;
///           if !cond -> none_exit; else -> test
///   test:   *filter_ref = item; keep = predicate(&item);
///           if keep -> some_exit; else -> header   (reject re-pulls; item consumed)
///   some_exit: dest = Some(item); -> call successor
///   none_exit: dest = None;       -> call successor
fn lower_filter_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("Filter::next with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("Filter::next into projected destination".to_owned());
    }
    // Defensive re-check (the caller already gates on exactly this shape).
    if chain.reversed || chain.rev_clamp.is_some() || chain.adapters.len() != 1 {
        return Err("lower_filter_next on a reversed/clamped/multi-adapter chain".to_owned());
    }
    if !matches!(chain.adapters[0].0.kind, AdapterKind::Filter) {
        return Err("lower_filter_next on a non-Filter chain".to_owned());
    }
    if chain.item.tuple.is_some() {
        return Err("lower_filter_next on a tuple item".to_owned());
    }
    let src_off = chain.source_offset;
    let closure_ty = chain.adapters[0].0.closure_ty;
    let closure_off = chain.adapters[0].1;

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let dest_ty = place_rust_ty(ctx, body, call.destination);

    // Exact-typed scratch for `&Item` (the predicate's argument), allocated in
    // the entry block so it dominates every use. An I64 allocation is too small
    // for i128 and violates the pointee type for narrow/reference items.
    let filter_ref_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: chain.item.ir_ty.clone(),
            count: None,
            align: None,
        })
        .with_result(filter_ref_slot),
    );

    let header_id = ctx.fresh_block_id();
    let test_id = ctx.fresh_block_id();
    let some_id = ctx.fresh_block_id();
    let none_id = ctx.fresh_block_id();

    // Entry -> header.
    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: Vec::new(),
    }));

    // === header: pull one source element (advancing + committing the cursor), or
    // branch to `none_exit` when the source is exhausted. `cond`/`item`/`item_ir`
    // are the SSA values threaded into `test`/`some_exit`; each re-execution of
    // the header (on the reject back-edge) reloads them from the slot, so their
    // last binding at loop exit is the accepting/exhausting pass's — no phi. ===
    let mut header = Block::new(header_id);
    let (cond, item, item_ir, payload_some, payload_none) = match &chain.source {
        ChainSource::Range {
            index_ty,
            ir_ty,
            size,
        } => {
            let _ = index_ty;
            let elem_ty = ir_ty.clone();
            let signed = is_signed_trust_ir_integer(&elem_ty);
            let start_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off);
            let start = emit_typed_load(ctx, &mut header, start_addr, elem_ty.clone());
            let end_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *size);
            let end = emit_typed_load(ctx, &mut header, end_addr, elem_ty.clone());
            // cond = start < end (signed/unsigned per the index type).
            let cond = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(cond),
            );
            // advanced = start + 1; new_start = cond ? advanced : start (only
            // advance in range, matching `Range::next`).
            let one = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: elem_ty.clone(),
                    value: Constant::Int(1),
                })
                .with_result(one),
            );
            let advanced = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Add,
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: one,
                })
                .with_result(advanced),
            );
            let new_start = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: elem_ty.clone(),
                    cond,
                    then_val: advanced,
                    else_val: start,
                })
                .with_result(new_start),
            );
            emit_typed_store(&mut header, start_addr, elem_ty.clone(), new_start);
            // The item is the pre-advance `start` (by value); the predicate sees
            // `&T`. Payload `Some(start)` / `None`.
            (
                cond,
                start,
                elem_ty.clone(),
                OptionPayload::Scalar {
                    value: start,
                    ty: elem_ty.clone(),
                },
                OptionPayload::Scalar {
                    value: start,
                    ty: elem_ty,
                },
            )
        }
        ChainSource::Slice {
            element_ty,
            ir_ty,
            size,
            end_off,
            repr,
            ..
        } => {
            repr.require_pointers("`Filter::next`")?;
            let _ = (element_ty, ir_ty);
            let ptr_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off);
            let ptr = emit_typed_load(ctx, &mut header, ptr_addr, TrustIrTy::Ptr);
            let end_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *end_off);
            let end = emit_typed_load(ctx, &mut header, end_addr, TrustIrTy::Ptr);
            // cond = ptr != end (unsigned address comparison, the verified route).
            let ptr_int = emit_ptr_to_int(ctx, &mut header, ptr);
            let end_int = emit_ptr_to_int(ctx, &mut header, end);
            let cond = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ne,
                    ty: TrustIrTy::I64,
                    lhs: ptr_int,
                    rhs: end_int,
                })
                .with_result(cond),
            );
            // advanced = ptr + size; new_ptr = cond ? advanced : ptr.
            let index_one = emit_i64_const(ctx, &mut header, 1);
            let advanced = emit_element_addr(ctx, &mut header, ptr, index_one, *size);
            let new_ptr = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Ptr,
                    cond,
                    then_val: advanced,
                    else_val: ptr,
                })
                .with_result(new_ptr),
            );
            emit_typed_store(&mut header, ptr_addr, TrustIrTy::Ptr, new_ptr);
            // The item is the (pre-advance) element pointer `ptr` (a `&T`); the
            // predicate sees `&&T`. Payload `Some(ptr)` (Reference) / `None` (null).
            (
                cond,
                ptr,
                TrustIrTy::Ptr,
                OptionPayload::Reference { ptr },
                OptionPayload::Reference { ptr },
            )
        }
        ChainSource::RangeInclusive {
            index_ty,
            ir_ty,
            start_off,
            end_off,
            exhausted_off,
        } => {
            // `start..=end` — the THREE-field `{ start, end, exhausted }` walk.
            // BYTE-IDENTICAL to `emit_source_next`'s RangeInclusive (Slot) arm
            // (the drive the `.sum()`/`.fold()` consumers already run ==LLVM):
            //   cond = !exhausted && start <= end          (yield `start`)
            //   is_iterating = start < end                 (a non-final element)
            //   on yield: start := is_iterating ? start+1 : start  (final stays)
            //             exhausted := is_iterating ? false : cond (final sets it)
            // The pre-advance `start` is the yielded value; the predicate sees `&T`.
            let _ = index_ty;
            let elem_ty = ir_ty.clone();
            let signed = is_signed_trust_ir_integer(&elem_ty);
            let start_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *start_off);
            let start = emit_typed_load(ctx, &mut header, start_addr, elem_ty.clone());
            let end_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *end_off);
            let end = emit_typed_load(ctx, &mut header, end_addr, elem_ty.clone());
            let exhausted_addr =
                iter_field_addr(ctx, &mut header, slot_ptr, src_off + *exhausted_off);
            let exhausted_byte = emit_typed_load(ctx, &mut header, exhausted_addr, TrustIrTy::I8);
            // already_exhausted = exhausted_byte != 0.
            let zero8 = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I8,
                    value: Constant::Int(0),
                })
                .with_result(zero8),
            );
            let already_exhausted = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ne,
                    ty: TrustIrTy::I8,
                    lhs: exhausted_byte,
                    rhs: zero8,
                })
                .with_result(already_exhausted),
            );
            // start_le_end = start <= end.
            let start_le_end = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Sle } else { ICmpOp::Ule },
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(start_le_end),
            );
            let false_bool = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::Bool,
                    value: Constant::Bool(false),
                })
                .with_result(false_bool),
            );
            // cond = already_exhausted ? false : start_le_end.
            let cond = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Bool,
                    cond: already_exhausted,
                    then_val: false_bool,
                    else_val: start_le_end,
                })
                .with_result(cond),
            );
            // is_iterating = start < end.
            let is_iterating = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(is_iterating),
            );
            // advanced = start + 1 (dead unless is_iterating).
            let one = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: elem_ty.clone(),
                    value: Constant::Int(1),
                })
                .with_result(one),
            );
            let advanced = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Add,
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: one,
                })
                .with_result(advanced),
            );
            let start_if_yield = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: elem_ty.clone(),
                    cond: is_iterating,
                    then_val: advanced,
                    else_val: start,
                })
                .with_result(start_if_yield),
            );
            // new_start = cond ? start_if_yield : start.
            let new_start = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: elem_ty.clone(),
                    cond,
                    then_val: start_if_yield,
                    else_val: start,
                })
                .with_result(new_start),
            );
            emit_typed_store(&mut header, start_addr, elem_ty.clone(), new_start);
            // set_exhausted = is_iterating ? false : cond.
            let set_exhausted = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Bool,
                    cond: is_iterating,
                    then_val: false_bool,
                    else_val: cond,
                })
                .with_result(set_exhausted),
            );
            let one8 = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I8,
                    value: Constant::Int(1),
                })
                .with_result(one8),
            );
            let new_exhausted_byte = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::I8,
                    cond: set_exhausted,
                    then_val: one8,
                    else_val: exhausted_byte,
                })
                .with_result(new_exhausted_byte),
            );
            emit_typed_store(
                &mut header,
                exhausted_addr,
                TrustIrTy::I8,
                new_exhausted_byte,
            );
            (
                cond,
                start,
                elem_ty.clone(),
                OptionPayload::Scalar {
                    value: start,
                    ty: elem_ty.clone(),
                },
                OptionPayload::Scalar {
                    value: start,
                    ty: elem_ty,
                },
            )
        }
        _ => return Err("lower_filter_next on an unmodeled source".to_owned()),
    };
    header.body.push(InstrNode::new(Inst::CondBr {
        cond,
        then_target: test_id,
        then_args: Vec::new(),
        else_target: none_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(header);

    // === test: store the item into the `&Item` scratch, call the predicate; on
    // accept -> some_exit, on reject -> header (re-pull; the element was already
    // consumed by the header's cursor advance). ===
    let mut test = Block::new(test_id);
    emit_typed_store(&mut test, filter_ref_slot, item_ir, item);
    let env_ptr = iter_field_addr(ctx, &mut test, slot_ptr, closure_off);
    let keep = emit_closure_call_1(
        ctx,
        &mut test,
        closure_ty,
        env_ptr,
        filter_ref_slot,
        TrustIrTy::Bool,
    )?;
    test.body.push(InstrNode::new(Inst::CondBr {
        cond: keep,
        then_target: some_id,
        then_args: Vec::new(),
        else_target: header_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(test);

    // === some_exit: write `Some(item)` (cond = const true), then the successor. ===
    let mut some_exit = Block::new(some_id);
    let true_bool = ctx.fresh_value();
    some_exit.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::Bool,
            value: Constant::Bool(true),
        })
        .with_result(true_bool),
    );
    store_option_some_value(
        ctx,
        body,
        &mut some_exit,
        call.destination.local,
        dest_ty,
        true_bool,
        payload_some,
    )?;
    emit_call_successor(&mut some_exit, call.target);
    ctx.extra_blocks.push(some_exit);

    // === none_exit: write `None` (cond = const false), then the successor. The
    // payload bytes are dead (the tag disambiguates), but a value of the right
    // representation must be supplied. ===
    let mut none_exit = Block::new(none_id);
    let false_bool = ctx.fresh_value();
    none_exit.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::Bool,
            value: Constant::Bool(false),
        })
        .with_result(false_bool),
    );
    store_option_some_value(
        ctx,
        body,
        &mut none_exit,
        call.destination.local,
        dest_ty,
        false_bool,
        payload_none,
    )?;
    emit_call_successor(&mut none_exit, call.target);
    ctx.extra_blocks.push(none_exit);

    let _ = item;
    Ok(())
}

/// `<FilterMap<Range<T> | slice::Iter<T> | RangeInclusive<T>, F> as
/// Iterator>::next(&mut self)` for a bridge-MODELED, bare/forward/unadapted
/// `.filter_map(f)` (the ONLY shape `resolve_bare_filtermap_chain` accepts).
/// Reproduces std's `FilterMap::next` (body `self.iter.find_map(&mut self.f)`)
/// EXACTLY: pull source elements — each pull ADVANCES + commits the source cursor
/// in the slot, so a skipped element is consumed — calling `f(item) -> Option<U>`
/// by value on each until it returns `Some(u)` (yield `Some(u)`) or the source is
/// exhausted (yield `None`). Byte-identical to `emit_chain_next`'s `FilterMap`
/// arm (measured ==LLVM as a terminal drive): the SAME source-cursor advance, the
/// SAME by-value `f(item)` call, and the SAME `Option<U>` dissection, only exposed
/// as a single `Iterator::next` rather than a fused terminal loop.
///
/// Structurally a sibling of `lower_filter_next`; the two differences are that the
/// closure takes the item BY VALUE (no `&item` scratch slot) and returns
/// `Option<U>` (dissected with `emit_option_step`) rather than a `bool`, so the
/// yielded payload is the closure's mapped `U` (not the source element):
///
///   block:  -> header
///   header: load source cursor; cond = has_next; advance+store cursor;
///           if !cond -> none_exit; else -> test
///   test:   opt = f(item); (is_some, u) = dissect opt;
///           if is_some -> some_exit; else -> header   (None re-pulls; item consumed)
///   some_exit: dest = Some(u); -> call successor
///   none_exit: dest = None;    -> call successor
fn lower_filter_map_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("FilterMap::next with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("FilterMap::next into projected destination".to_owned());
    }
    // Defensive re-check (the caller already gates on exactly this shape).
    if chain.reversed || chain.rev_clamp.is_some() || chain.adapters.len() != 1 {
        return Err("lower_filter_map_next on a reversed/clamped/multi-adapter chain".to_owned());
    }
    if !matches!(chain.adapters[0].0.kind, AdapterKind::FilterMap) {
        return Err("lower_filter_map_next on a non-FilterMap chain".to_owned());
    }
    if chain.item.tuple.is_some() {
        return Err("lower_filter_map_next on a tuple output item".to_owned());
    }
    let src_off = chain.source_offset;
    let closure_ty = chain.adapters[0].0.closure_ty;
    let closure_off = chain.adapters[0].1;
    // The closure's `Option<U>` return type (dissected in `test`) and the yielded
    // `U` representation (the payload written on `Some`). `resolve` built the
    // output item via `option_payload_scalar_item`, so `U` is a lane-fitting
    // scalar and its `Option<U>` return is a DIRECT-tagged register-pair.
    let opt_ty = closure_output_ty(ctx, closure_ty)?;
    let out_ir = chain.adapters[0].0.output.ir_ty.clone();

    let slot_ptr = iterator_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let dest_ty = place_rust_ty(ctx, body, call.destination);

    let header_id = ctx.fresh_block_id();
    let test_id = ctx.fresh_block_id();
    let some_id = ctx.fresh_block_id();
    let none_id = ctx.fresh_block_id();

    // Entry -> header.
    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: Vec::new(),
    }));

    // === header: pull one source element (advancing + committing the cursor), or
    // branch to `none_exit` when the source is exhausted. `cond`/`item`/`item_ir`
    // are re-bound each header pass (the cursor is memory-backed, reloaded per
    // pass) so the None-reject back-edge needs no phi — IDENTICAL to
    // `lower_filter_next`'s header, only the source payloads are unused (the
    // yielded value is the closure's mapped `U`, computed in `test`). ===
    let mut header = Block::new(header_id);
    let (cond, item, _item_ir) = match &chain.source {
        ChainSource::Range {
            index_ty,
            ir_ty,
            size,
        } => {
            let _ = index_ty;
            let elem_ty = ir_ty.clone();
            let signed = is_signed_trust_ir_integer(&elem_ty);
            let start_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off);
            let start = emit_typed_load(ctx, &mut header, start_addr, elem_ty.clone());
            let end_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *size);
            let end = emit_typed_load(ctx, &mut header, end_addr, elem_ty.clone());
            let cond = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(cond),
            );
            let one = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: elem_ty.clone(),
                    value: Constant::Int(1),
                })
                .with_result(one),
            );
            let advanced = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Add,
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: one,
                })
                .with_result(advanced),
            );
            let new_start = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: elem_ty.clone(),
                    cond,
                    then_val: advanced,
                    else_val: start,
                })
                .with_result(new_start),
            );
            emit_typed_store(&mut header, start_addr, elem_ty.clone(), new_start);
            // The item is the pre-advance `start`, passed to `f` BY VALUE.
            (cond, start, elem_ty)
        }
        ChainSource::Slice {
            element_ty,
            ir_ty,
            size,
            end_off,
            repr,
            ..
        } => {
            repr.require_pointers("`FilterMap::next`")?;
            let _ = (element_ty, ir_ty);
            let ptr_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off);
            let ptr = emit_typed_load(ctx, &mut header, ptr_addr, TrustIrTy::Ptr);
            let end_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *end_off);
            let end = emit_typed_load(ctx, &mut header, end_addr, TrustIrTy::Ptr);
            let ptr_int = emit_ptr_to_int(ctx, &mut header, ptr);
            let end_int = emit_ptr_to_int(ctx, &mut header, end);
            let cond = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ne,
                    ty: TrustIrTy::I64,
                    lhs: ptr_int,
                    rhs: end_int,
                })
                .with_result(cond),
            );
            let index_one = emit_i64_const(ctx, &mut header, 1);
            let advanced = emit_element_addr(ctx, &mut header, ptr, index_one, *size);
            let new_ptr = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Ptr,
                    cond,
                    then_val: advanced,
                    else_val: ptr,
                })
                .with_result(new_ptr),
            );
            emit_typed_store(&mut header, ptr_addr, TrustIrTy::Ptr, new_ptr);
            // The item is the (pre-advance) element pointer `ptr` (a `&T`), passed
            // to `f` BY VALUE (the closure's `Self::Item` is `&T`).
            (cond, ptr, TrustIrTy::Ptr)
        }
        ChainSource::RangeInclusive {
            index_ty,
            ir_ty,
            start_off,
            end_off,
            exhausted_off,
        } => {
            // The THREE-field `{ start, end, exhausted }` walk, BYTE-IDENTICAL to
            // `lower_filter_next`'s RangeInclusive arm (itself ==LLVM as a terminal
            // drive). The pre-advance `start` is passed to `f` BY VALUE.
            let _ = index_ty;
            let elem_ty = ir_ty.clone();
            let signed = is_signed_trust_ir_integer(&elem_ty);
            let start_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *start_off);
            let start = emit_typed_load(ctx, &mut header, start_addr, elem_ty.clone());
            let end_addr = iter_field_addr(ctx, &mut header, slot_ptr, src_off + *end_off);
            let end = emit_typed_load(ctx, &mut header, end_addr, elem_ty.clone());
            let exhausted_addr =
                iter_field_addr(ctx, &mut header, slot_ptr, src_off + *exhausted_off);
            let exhausted_byte = emit_typed_load(ctx, &mut header, exhausted_addr, TrustIrTy::I8);
            let zero8 = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I8,
                    value: Constant::Int(0),
                })
                .with_result(zero8),
            );
            let already_exhausted = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ne,
                    ty: TrustIrTy::I8,
                    lhs: exhausted_byte,
                    rhs: zero8,
                })
                .with_result(already_exhausted),
            );
            let start_le_end = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Sle } else { ICmpOp::Ule },
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(start_le_end),
            );
            let false_bool = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::Bool,
                    value: Constant::Bool(false),
                })
                .with_result(false_bool),
            );
            let cond = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Bool,
                    cond: already_exhausted,
                    then_val: false_bool,
                    else_val: start_le_end,
                })
                .with_result(cond),
            );
            let is_iterating = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(is_iterating),
            );
            let one = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: elem_ty.clone(),
                    value: Constant::Int(1),
                })
                .with_result(one),
            );
            let advanced = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Add,
                    ty: elem_ty.clone(),
                    lhs: start,
                    rhs: one,
                })
                .with_result(advanced),
            );
            let start_if_yield = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: elem_ty.clone(),
                    cond: is_iterating,
                    then_val: advanced,
                    else_val: start,
                })
                .with_result(start_if_yield),
            );
            let new_start = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: elem_ty.clone(),
                    cond,
                    then_val: start_if_yield,
                    else_val: start,
                })
                .with_result(new_start),
            );
            emit_typed_store(&mut header, start_addr, elem_ty.clone(), new_start);
            let set_exhausted = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Bool,
                    cond: is_iterating,
                    then_val: false_bool,
                    else_val: cond,
                })
                .with_result(set_exhausted),
            );
            let one8 = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I8,
                    value: Constant::Int(1),
                })
                .with_result(one8),
            );
            let new_exhausted_byte = ctx.fresh_value();
            header.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::I8,
                    cond: set_exhausted,
                    then_val: one8,
                    else_val: exhausted_byte,
                })
                .with_result(new_exhausted_byte),
            );
            emit_typed_store(
                &mut header,
                exhausted_addr,
                TrustIrTy::I8,
                new_exhausted_byte,
            );
            (cond, start, elem_ty)
        }
        _ => return Err("lower_filter_map_next on an unmodeled source".to_owned()),
    };
    header.body.push(InstrNode::new(Inst::CondBr {
        cond,
        then_target: test_id,
        then_args: Vec::new(),
        else_target: none_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(header);

    // === test: call `f(item) -> Option<U>` by value, dissect it. On `Some` ->
    // some_exit (carrying the mapped `U`, live in this block); on `None` -> header
    // (re-pull; the element was already consumed by the header's cursor advance —
    // IDENTICAL to Filter's reject edge and the terminal FilterMap arm). ===
    let mut test = Block::new(test_id);
    let env_ptr = iter_field_addr(ctx, &mut test, slot_ptr, closure_off);
    let opt = emit_closure_call_n(
        ctx,
        &mut test,
        closure_ty,
        env_ptr,
        vec![item],
        out_ir.clone(),
    )?;
    let (is_some, payload, _payload_ir) = emit_option_step(ctx, &mut test, opt_ty, opt)?;
    test.body.push(InstrNode::new(Inst::CondBr {
        cond: is_some,
        then_target: some_id,
        then_args: Vec::new(),
        else_target: header_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(test);

    // === some_exit: write `Some(u)` (cond = const true) with the mapped payload
    // computed in `test` (which is `some_exit`'s sole predecessor, so `payload`
    // dominates every use — no phi), then the successor. ===
    let mut some_exit = Block::new(some_id);
    let true_bool = ctx.fresh_value();
    some_exit.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::Bool,
            value: Constant::Bool(true),
        })
        .with_result(true_bool),
    );
    store_option_some_value(
        ctx,
        body,
        &mut some_exit,
        call.destination.local,
        dest_ty,
        true_bool,
        OptionPayload::Scalar {
            value: payload,
            ty: out_ir.clone(),
        },
    )?;
    emit_call_successor(&mut some_exit, call.target);
    ctx.extra_blocks.push(some_exit);

    // === none_exit: write `None` (cond = const false). The payload bytes are dead
    // (the tag disambiguates), but a value of the right representation must be
    // supplied — reuse `out_ir`'s zero. ===
    let mut none_exit = Block::new(none_id);
    let false_bool = ctx.fresh_value();
    none_exit.body.push(
        InstrNode::new(Inst::Const {
            ty: TrustIrTy::Bool,
            value: Constant::Bool(false),
        })
        .with_result(false_bool),
    );
    // A well-typed zero of the payload's exact scalar type (int OR float — a
    // hand-rolled `Int(0)` would be wrong for an `f32`/`f64` `U`).
    let dead_payload = emit_zero_scalar_const(ctx, &mut none_exit, &out_ir)?;
    store_option_some_value(
        ctx,
        body,
        &mut none_exit,
        call.destination.local,
        dest_ty,
        false_bool,
        OptionPayload::Scalar {
            value: dead_payload,
            ty: out_ir,
        },
    )?;
    emit_call_successor(&mut none_exit, call.target);
    ctx.extra_blocks.push(none_exit);

    Ok(())
}

// ===========================================================================
// Iterator adapters (`.map` / `.filter`) and terminal consumers
// (`.sum` / `.fold` / `.count`) over Range / slice / Map / Filter.
//
// These build directly on the bare-iterator interception above. The lazy
// adapters synthesize the `Map`/`Filter` value's runtime state in the
// destination slot; the consumers synthesize the driving loop (next() until
// exhaustion, accumulating) — a real multi-block loop whose loop-carried state
// (the iterator chain + the accumulator) is MEMORY-BACKED, so it needs no phi
// machinery. The closure each adapter/fold carries is called through its
// compiled closure-body symbol (`func_ty_for_instance`'s closure path).
//
// SCOPE (everything else fails closed, never miscompiles):
//   * source iterators: `Range<scalar int>` and `core::slice::Iter<scalar>`;
//   * adapters: `Map`/`Filter` whose closure is a ZST (no captures) OR CAPTURES
//     scalar upvars (by value or by reference). A capturing closure's upvars are
//     stored at the closure field's offset within the adapter slot by the
//     constructor, and the chain `next` calls the closure with that env address
//     (`&env`); the body reads its captures through `(*env).N`. A capture we
//     cannot flat-slot (a moved aggregate / heap value) is rejected;
//   * consumers: `sum` (integer `+`), `fold(init, f)` (apply `f`), `count`.
// ===========================================================================

/// A scalar element flowing through an iterator chain. The representation is
/// the trust-ir value actually threaded through the loop: for a by-value item
/// (a `Range`'s `i64`, or a `Map` closure's scalar return) it is the scalar
/// itself; for a by-reference item (a `slice::Iter`'s `&T`) it is the element
/// POINTER, and `deref_elem_ir` records the pointee scalar type so a terminal
/// consumer can load through it. `rust_ty` is the `Iterator::Item` type (kept
/// for diagnostics).
#[derive(Clone)]
#[allow(dead_code)]
struct ChainItem<'tcx> {
    rust_ty: Ty<'tcx>,
    /// The trust-ir type of the threaded representation value (the scalar, or
    /// `Ptr` for a reference item).
    ir_ty: TrustIrTy,
    /// `Some(elem)` when the item is a reference `&elem` (the representation is a
    /// pointer); `None` for a by-value scalar item.
    deref_elem_ir: Option<TrustIrTy>,
    /// `Some((a, b))` when the item is a 2-TUPLE `(A, B)` (produced by
    /// `.enumerate()` / `.zip()`); the chain threads two representation values and
    /// only a `.map`/`.fold` that untuples it (or another tuple adapter) can
    /// consume it. `None` for a single-component scalar / reference item.
    tuple: Option<(Box<ChainItem<'tcx>>, Box<ChainItem<'tcx>>)>,
}

/// One lazy adapter layered over an inner iterator. For closure-carrying
/// adapters (`Map`/`Filter`) `closure_ty` is the (ZST or capturing) closure; for
/// the structural adapters (`Copied`/`Cloned`/`Take`/`Skip`/`StepBy`/`Enumerate`)
/// `closure_ty` is unused. `kind` carries the per-adapter runtime data (a count
/// field offset, a step constant, …).
#[allow(dead_code)]
struct ChainAdapter<'tcx> {
    kind: AdapterKind,
    /// The closure value's type (`Closure(def_id, args)`); ZST (no captures), or
    /// a unit placeholder for non-closure adapters.
    closure_ty: Ty<'tcx>,
    /// The element type the closure RECEIVES (the inner chain's item type; kept
    /// for diagnostics).
    input: ChainItem<'tcx>,
    /// The element type the closure/Filter PRODUCES (for Map, the closure's
    /// return; for Filter, the same as `input`).
    output: ChainItem<'tcx>,
}

/// Each adapter's kind plus its per-adapter runtime parameters. `Copied`/`Cloned`
/// carry the deref'd element ir type; the bounded/index adapters carry the byte
/// offset of their state field within the chain slot (read from the adapter
/// type's layout); `Enumerate` carries its `count` field offset.
#[derive(Clone)]
enum AdapterKind {
    Map,
    Filter,
    /// `.copied()` / `.cloned()` over `&T`: yield the deref'd scalar `T` (ir).
    Copied {
        elem_ir: TrustIrTy,
    },
    /// `.take(n)`: a `usize` remaining-count field at `count_off`; stop at 0.
    Take {
        count_off: u64,
    },
    /// `.skip(n)`: a `usize` remaining-skip field at `count_off`; drop the first n.
    Skip {
        count_off: u64,
    },
    /// `.step_by(k)`: exact rustc-layout-derived offsets for std's
    /// `step_minus_one: usize` and `first_take: bool` fields. Never infer the
    /// bool offset from padding after the usize: rustc may reorder struct
    /// fields. The slot always holds std's layout. `range_countdown` is true
    /// exactly when core's `SpecRangeSetup` specializes this `StepBy`: its
    /// `iter` is a `Range<T>` whose `end` holds the number of items still to
    /// yield (not a bound), each yield advances `start` by the step, and
    /// `first_take` is unused ([`step_by_range_countdown`]).
    StepBy {
        step_minus_one_off: u64,
        first_take_off: u64,
        range_countdown: bool,
    },
    /// `.enumerate()`: a `usize` running count at `count_off`; yields `(i, value)`.
    Enumerate {
        count_off: u64,
        /// A PEELED (`-O3`) enumerate has no count field in the bare source's
        /// chain slot; it uses a fresh standalone counter alloca instead
        /// (`count_off == u64::MAX` sentinel, slot filled post-peel). A
        /// chain-backed (`-O0` constructor) enumerate keeps `None`.
        counter_slot: Option<ValueId>,
    },
    /// `.filter_map(f)`: STATELESS (= a fused Filter+Map with an `Option` gate).
    /// The closure takes `Self::Item` BY VALUE and returns `Option<U>`; `None`
    /// SKIPS (re-pull), `Some(u)` yields `u`. No slot state (the closure offset is
    /// the tuple `.1`, shifted separately).
    FilterMap,
    /// `.take_while(p)`: `TakeWhile<I, P> { iter, flag, predicate }`, with std's
    /// done-`flag` (a `bool` in the chain slot at `flag_off`). A set flag means
    /// the adapter already stopped: std's `next`/`fold`/`try_fold` then yield
    /// nothing without pulling `iter` or calling `p`, so a drive over a chain
    /// holding a set flag yields nothing. Otherwise the predicate takes
    /// `&Self::Item` and returns `bool`; `false` sets the flag and TERMINATES the
    /// drive (= Take's exhaust edge, NOT Filter's re-pull edge).
    TakeWhile {
        flag_off: u64,
    },
    /// `.skip_while(p)`: STATEFUL. `SkipWhile<I, P> { iter, flag, predicate }`.
    /// While the `flag` (a `bool` in the chain slot at `flag_off`) is unset AND
    /// `p(&item)` is true, SKIP (re-pull). Once `p` is false (or the flag is
    /// already set), set the flag and YIELD this and every later element (even if
    /// `p` becomes true again). Predicate `&Self::Item -> bool`; output == input.
    SkipWhile {
        flag_off: u64,
    },
    /// `.scan(init, f)`: an 8*-byte `state` cell at `state_off`; the closure takes
    /// `(&mut state, Self::Item)` and returns `Option<U>`. `None` TERMINATES the
    /// drive; `Some(u)` yields `u`. The state is threaded left-to-right through the
    /// private slot copy (memory-backed).
    Scan {
        state_off: u64,
    },
    /// `.map_while(f)`: STATELESS. The closure takes `Self::Item` BY VALUE and
    /// returns `Option<U>` (like `FilterMap`), but `None` TERMINATES the drive (like
    /// `Scan`/`TakeWhile`'s exhaust edge) instead of skipping. `Some(u)` yields `u`.
    /// No slot state: std's `MapWhile { iter, predicate }` has no done flag (it is
    /// not fused), and its `fold`/`try_fold` stop at the first `None`.
    MapWhile,
    /// `.inspect(f)`: STATELESS transparent pass-through. The closure takes
    /// `&Self::Item` and returns `()` (called purely for its side effect); the item
    /// is yielded UNCHANGED and the drive always proceeds. Output == input.
    Inspect,
}

impl AdapterKind {
    /// A bounded-count / stepping adapter whose forward sequence cannot be
    /// reproduced by a naive backward source walk (so `.rev()` below one of these
    /// fails closed).
    fn is_count_modifier(&self) -> bool {
        matches!(
            self,
            AdapterKind::Take { .. } | AdapterKind::Skip { .. } | AdapterKind::StepBy { .. }
        )
    }
    /// Shift this adapter's STATE-field byte offsets by `delta` when the adapter is
    /// nested inside an outer adapter's slot (the inner chain's components move up
    /// by the outer's field-0 offset). `Map`/`Filter`/`Copied` carry no slot state
    /// (the closure offset is the tuple's `.1`, shifted separately).
    fn shift_offsets(&mut self, delta: u64) {
        match self {
            AdapterKind::Take { count_off }
            | AdapterKind::Skip { count_off }
            | AdapterKind::Enumerate { count_off, .. } => *count_off += delta,
            AdapterKind::StepBy {
                step_minus_one_off,
                first_take_off,
                ..
            } => {
                *step_minus_one_off += delta;
                *first_take_off += delta;
            }
            AdapterKind::Scan { state_off } => *state_off += delta,
            AdapterKind::SkipWhile { flag_off } | AdapterKind::TakeWhile { flag_off } => {
                *flag_off += delta
            }
            AdapterKind::Map
            | AdapterKind::Filter
            | AdapterKind::Copied { .. }
            | AdapterKind::FilterMap
            | AdapterKind::MapWhile
            | AdapterKind::Inspect => {}
        }
    }
}

/// If `chain` is a FORWARD, not-yet-clamped, bare-slice chain whose ONLY
/// adapter is a `.take(n)` / `.skip(k)`, rewrite that adapter into the boundary
/// clamp (`rev_clamp`) so the chain can be driven BACKWARDS (the caller sets /
/// flips `reversed` afterwards). Used by the `.rev()` resolve arm and by the
/// `rfold`/`try_rfold` reverse routes (where `-O3` inlining exposes the inner
/// `Take`/`Skip` receiver directly). STRICT by construction: any other shape
/// (extra adapters, Range/RangeInclusive/Concat/Zip source, already reversed,
/// already clamped) is left untouched for the fail-closed rejections.
fn rewrite_below_rev_bounded(chain: &mut IterChain<'_>) -> bool {
    if chain.reversed
        || chain.rev_clamp.is_some()
        || chain.adapters.len() != 1
        || !matches!(chain.source, ChainSource::Slice { .. })
    {
        return false;
    }
    let clamp = match chain.adapters[0].0.kind {
        AdapterKind::Take { count_off } => RevClamp::TakeEnd { count_off },
        AdapterKind::Skip { count_off } => RevClamp::SkipStart { count_off },
        _ => return false,
    };
    // Take/Skip are item-identity adapters (output == input), so dropping the
    // entry keeps `chain.item` correct as-is.
    chain.adapters.clear();
    chain.rev_clamp = Some(clamp);
    true
}

/// One side of a modeled `.zip()`: where its sub-iterator state lives within the
/// Zip slot and how element `i` is produced from it.
#[derive(Clone)]
struct ZipSide<'tcx> {
    /// Byte offset of this side's sub-iterator state within the Zip slot
    /// (`slice::Iter`'s `{ptr, end}` base or `Range`'s `{start, end}` base).
    /// Field-INDEXED from rustc's layout (`fields.offset(0/1)`), NOT memory
    /// order — `Zip<Range, Iter>` lays `b` out first, and offset-by-index is
    /// still correct.
    offset: u64,
    /// Element byte size: the load stride for a slice side; 8 for a Range side
    /// (also the `end` field's offset within the Range: `offset + elem_size`).
    elem_size: u64,
    elem_ir: TrustIrTy,
    elem_ty: Ty<'tcx>,
    kind: ZipSideKind,
}

/// How a `.zip()` side yields element `i`. Both forms are `TrustedRandomAccess`
/// (std's specialized `Zip::next` never advances the sub-iterators; it reads
/// element `i` via `__iterator_get_unchecked(i)` off the ORIGINAL state).
#[derive(Clone, Copy, PartialEq, Eq)]
enum ZipSideKind {
    /// `slice::Iter<T>` — element `i` is the POINTER `base_ptr + i*elem_size`
    /// (the item is `&T`; a downstream closure/copied derefs it).
    SlicePtr,
    /// 64-bit `Range<T>` — element `i` is `start + i` BY VALUE (no load through
    /// a pointer; `<Range as Iterator>::__iterator_get_unchecked(i)` is
    /// `Step::forward_unchecked(start, i)`).
    RangeStart,
}

/// Where a `Chain` half's `Option` field says `None`. core's `Chain` clears a
/// half it has exhausted: `next` sets `a = None` (`and_then_or_clear`),
/// `next_back` sets `b = None`, and `nth` / `advance_by` / `try_fold` clear the
/// half they run out of. A cleared half's payload is not an iterator state: the
/// `None` of an `Option<slice::Iter>` is its null `ptr` niche (the `end` field
/// keeps whatever it held), and an `Option<Range>`'s `None` leaves the payload
/// bytes undefined. A drive reads this field before it trusts the payload.
#[derive(Clone, Debug)]
struct OptionNoneTest {
    /// Byte offset of the `Option`'s tag (Direct) or niche field, relative to
    /// the base the `Concat` payload offsets are relative to.
    offset: u64,
    /// That field's trust-ir type: an integer of at most 64 bits or a pointer.
    ty: TrustIrTy,
    /// The field's bit pattern for `None`, zero-extended to 64 bits.
    none_bits: u64,
}

/// The innermost iterator source of a chain.
enum ChainSource<'tcx> {
    Range {
        index_ty: Ty<'tcx>,
        ir_ty: TrustIrTy,
        /// byte size of the index (the `start`/`end` stride within the slot).
        size: u64,
    },
    /// `RangeInclusive<T>` — `start..=end`, a THREE-field struct yielding the
    /// inclusive endpoint exactly once. The field byte offsets (RELATIVE to the
    /// `RangeInclusive` struct base; the struct itself sits at the chain's
    /// `source_offset`) are layout-derived (NOT declaration order — for `u8` the
    /// bool is first).
    RangeInclusive {
        index_ty: Ty<'tcx>,
        ir_ty: TrustIrTy,
        /// Field offsets within the `RangeInclusive` struct: start, end, exhausted.
        start_off: u64,
        end_off: u64,
        exhausted_off: u64,
    },
    /// A `{ ptr, end }` element cursor. `ptr` sits at the chain's
    /// `source_offset`; `end` sits `end_off` bytes after it — `slice_iter_end_offset()`
    /// for `slice::Iter`, rustc's `end - ptr` field distance for `vec::IntoIter`
    /// (`VecIntoIterLayout`, whose `ptr` is not its first field) and
    /// `alive.end - alive.start` for `array::IntoIter` (`ArrayIntoIterLayout`).
    Slice {
        element_ty: Ty<'tcx>,
        ir_ty: TrustIrTy,
        /// byte size of the element (the iterator's advance stride).
        size: u64,
        /// Whether the modeled Rust source implements core's
        /// `TrustedRandomAccess`: true for the borrowing `slice::Iter` /
        /// `slice::IterMut`, false for the owning `vec::IntoIter` /
        /// `array::IntoIter`, which implement only `TrustedRandomAccessNoCoerce`
        /// and so never select a `TrustedRandomAccess` specialization.
        trusted_random_access: bool,
        /// byte distance from the `ptr` field to the `end` field.
        end_off: u64,
        /// Pointer fields, or `array::IntoIter`'s indices over its inline data.
        /// A driver accesses the fields through `emit_slice_cursor_load`/`_store`
        /// or refuses an index cursor (`SliceCursorRepr::require_pointers`).
        repr: SliceCursorRepr,
        /// `Some` for the owning `vec::IntoIter`, which holds a heap buffer
        /// (`buf`, `cap`): rustc's field layout, whose `ptr` field sits at the
        /// chain's `source_offset`. `collect` reuses or frees that buffer as
        /// std's `SpecFromIter` does (`collect_sizing`).
        owning_vec: Option<VecIntoIterLayout>,
    },
    /// `a.chain(b)`: two sub-sources iterated sequentially (`a` to exhaustion, then
    /// `b`). Both sub-sources must yield the SAME item shape; `first_offset` /
    /// `second_offset` are the byte offsets of each sub-source's iterator STATE
    /// within the `Chain` slot (the `Option<A>` / `Option<B>` field payloads).
    /// `resolve_chain_concat` admits a bare `Range` (a Direct-tagged
    /// `Option<Range>`) or a pointer-cursor `slice::Iter` (an `Option<Iter>`
    /// whose `None` is the null `ptr` niche) on each side. A half is driven only
    /// while its `Option` is `Some` (`first_none` / `second_none`): core's own
    /// `Chain` bodies clear a half they exhaust, and a cleared half's payload is
    /// not an iterator state.
    Concat {
        first: Box<ChainSource<'tcx>>,
        first_offset: u64,
        first_none: OptionNoneTest,
        second: Box<ChainSource<'tcx>>,
        second_offset: u64,
        second_none: OptionNoneTest,
    },
    /// `a.zip(b)` over two `TrustedRandomAccess` sub-sources (`slice::Iter`
    /// and/or 64-bit `Range`): yields `(A::Item, B::Item)` for
    /// `i = 0..min(a_len, b_len)`. Both forms use std's 4-field TRA `Zip`
    /// specialization `{ a, b, index, len }` whose `next` does NOT advance the
    /// sub-iterators — it keeps an `index`/`len` cursor and reads element `i`
    /// directly via `__iterator_get_unchecked(i)`: a slice side yields the
    /// pointer `base + i*stride` (`&T`), a Range side yields `start + i` BY
    /// VALUE. We reproduce that exactly: `cond = index < len`; on yield emit
    /// each side's element and `index += 1`. `len = min(a_len, b_len)` is set
    /// by the constructor. Any other sub-source (adapter, nested Zip,
    /// RangeInclusive, narrow Range) fails closed in `resolve_zip`.
    Zip {
        a: ZipSide<'tcx>,
        b: ZipSide<'tcx>,
        /// byte offsets of the `usize` `index` / `len` cursor fields.
        index_offset: u64,
        len_offset: u64,
    },
}

/// The shape of an iterator-adapter ADT, identified by its def path (independent
/// of the layout-derived runtime parameters that fill in the `AdapterKind`).
#[derive(Clone, Copy, PartialEq, Eq)]
enum AdapterTag {
    Map,
    Filter,
    Copied,
    Cloned,
    Take,
    Skip,
    StepBy,
    Enumerate,
    Rev,
    FilterMap,
    TakeWhile,
    SkipWhile,
    Scan,
    MapWhile,
    Inspect,
}

/// Robustly identify the std iterator-adapter ADTs by their FULL def path
/// (`def_path_str` elides module segments — it prints just `"Map"` — which would
/// also match a user type named `Map`). We require the type to live in
/// `core`/`std`/`alloc` under `iter::adapters::{…}`.
fn adapter_kind_of(tcx: TyCtxt<'_>, did: rustc_hir::def_id::DefId) -> Option<AdapterTag> {
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    // (`std_def_is_interceptable`: a local adapter ADT is never modeled.)
    if !is_real_std_crate_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return None;
    }
    // Build the within-crate path: e.g. `iter::adapters::map::Map`.
    let segments: Vec<String> = tcx
        .def_path(did)
        .data
        .iter()
        .filter_map(|d| d.data.get_opt_name().map(|n| n.to_string()))
        .collect();
    match segments.join("::").as_str() {
        "iter::adapters::map::Map" => Some(AdapterTag::Map),
        "iter::adapters::filter::Filter" => Some(AdapterTag::Filter),
        "iter::adapters::copied::Copied" => Some(AdapterTag::Copied),
        "iter::adapters::cloned::Cloned" => Some(AdapterTag::Cloned),
        "iter::adapters::take::Take" => Some(AdapterTag::Take),
        "iter::adapters::skip::Skip" => Some(AdapterTag::Skip),
        "iter::adapters::step_by::StepBy" => Some(AdapterTag::StepBy),
        "iter::adapters::enumerate::Enumerate" => Some(AdapterTag::Enumerate),
        "iter::adapters::rev::Rev" => Some(AdapterTag::Rev),
        "iter::adapters::filter_map::FilterMap" => Some(AdapterTag::FilterMap),
        "iter::adapters::take_while::TakeWhile" => Some(AdapterTag::TakeWhile),
        "iter::adapters::skip_while::SkipWhile" => Some(AdapterTag::SkipWhile),
        "iter::adapters::scan::Scan" => Some(AdapterTag::Scan),
        "iter::adapters::map_while::MapWhile" => Some(AdapterTag::MapWhile),
        "iter::adapters::inspect::Inspect" => Some(AdapterTag::Inspect),
        // `iter::adapters::chain::Chain` is NOT a per-element adapter — it is a
        // two-source concatenation handled specially in `resolve_iter_chain`
        // (`is_chain_adapter`), so it is deliberately absent here.
        _ => None,
    }
}

/// `true` if `did` is the std `iter::adapters::chain::Chain` ADT (the `.chain()`
/// adapter), identified by its full def path (so a user type named `Chain` does
/// not match).
fn is_chain_adapter(tcx: TyCtxt<'_>, did: rustc_hir::def_id::DefId) -> bool {
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    // (`std_def_is_interceptable`: a local ADT is never modeled.)
    if !is_real_std_crate_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return false;
    }
    let segments: Vec<String> = tcx
        .def_path(did)
        .data
        .iter()
        .filter_map(|d| d.data.get_opt_name().map(|n| n.to_string()))
        .collect();
    segments.join("::") == "iter::adapters::chain::Chain"
}

/// `true` if `ty` is the std `str::Bytes` ADT (the iterator `s.bytes()` returns:
/// `struct Bytes<'a>(Copied<slice::Iter<'a, u8>>)`). A NEWTYPE over
/// `Copied<slice::Iter<u8>>` (adds no layout), so `resolve_iter_chain` peels it to
/// its field-0 inner and the ctor builds the same `{ ptr, end }` slice-iter state.
fn is_str_bytes_ty(tcx: TyCtxt<'_>, ty: Ty<'_>) -> bool {
    let ty::Adt(adt, _) = ty.kind() else {
        return false;
    };
    let did = adt.did();
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    // (`std_def_is_interceptable`: a local ADT is never modeled.)
    if !is_real_std_crate_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return false;
    }
    let segments: Vec<String> = tcx
        .def_path(did)
        .data
        .iter()
        .filter_map(|d| d.data.get_opt_name().map(|n| n.to_string()))
        .collect();
    let path = segments.join("::");
    path == "str::iter::Bytes" || path == "str::Bytes"
}

/// `true` if `did` is the std `iter::adapters::zip::Zip` ADT (the `.zip()`
/// adapter), identified by its full def path. Like `Chain`, `Zip` is NOT a
/// per-element adapter wrapping ONE inner iterator — it is a PARALLEL pairing of
/// two sub-iterators that yields a `(A::Item, B::Item)` tuple — so it is handled
/// specially (`resolve_zip`) rather than via `adapter_kind_of`.
fn is_zip_adapter(tcx: TyCtxt<'_>, did: rustc_hir::def_id::DefId) -> bool {
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    // (`std_def_is_interceptable`: a local ADT is never modeled.)
    if !is_real_std_crate_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return false;
    }
    let segments: Vec<String> = tcx
        .def_path(did)
        .data
        .iter()
        .filter_map(|d| d.data.get_opt_name().map(|n| n.to_string()))
        .collect();
    segments.join("::") == "iter::adapters::zip::Zip"
}

/// `true` if `did` is the std `iter::adapters::flatten::FlatMap` ADT (the
/// `.flat_map()` adapter's OWN struct — `struct FlatMap<I, U: IntoIterator, F>
/// { inner: FlattenCompat<Map<I, F>, U::IntoIter> }`, NOT the inner
/// `FlattenCompat`/`Fuse` plumbing). Identified by its full def path, exactly
/// like `Chain`/`Zip` above. Like `Chain`/`Zip`, `FlatMap` is not a per-element
/// "≤1 in, ≤1 out" adapter — flat_map yields `0..N` items per pull — so it is
/// handled by its OWN dedicated two-level driver (`lower_flatmap_bounded_ctor`
/// / `lower_flatmap_bounded_consumer`) rather than via `adapter_kind_of` /
/// `emit_chain_next`.
fn is_flatmap_adapter(tcx: TyCtxt<'_>, did: rustc_hir::def_id::DefId) -> bool {
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    // (`std_def_is_interceptable`: a local ADT is never modeled.)
    if !is_real_std_crate_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return false;
    }
    let segments: Vec<String> = tcx
        .def_path(did)
        .data
        .iter()
        .filter_map(|d| d.data.get_opt_name().map(|n| n.to_string()))
        .collect();
    segments.join("::") == "iter::adapters::flatten::FlatMap"
}

/// A BOUNDED `flat_map` shape this backend drives directly.
struct FlatMapBounded<'tcx> {
    /// `T`'s trust-ir scalar (integer) type (the shared scalar index type of the
    /// OUTER and INNER ranges — `I` and `U` must both be bare `Range<T>` for the
    /// identical `T`, verified by `range_index_ty` on each plus a `Ty` equality
    /// check in `resolve_flatmap_bounded`).
    ir_ty: TrustIrTy,
    /// `size_of::<T>()`, the width of one `Range<T>` bound.
    size: u64,
    /// `Range<T>` itself (`== I == U`, since `T1 == T2` implies the two are the
    /// SAME monomorphized `Ty` — `Range` has exactly one type parameter and no
    /// lifetime parameters). Used to classify `F`'s aggregate RETURN layout for
    /// the closure-call relocation in `lower_flatmap_bounded_consumer`.
    range_ty: Ty<'tcx>,
    /// `F`: the (validated ZST / non-capturing) `FnMut(T) -> Range<T>` closure.
    closure_ty: Ty<'tcx>,
    /// Where std's `FlatMap` keeps its three `Range<T>` states.
    std_layout: FlatMapStdLayout,
}

/// std's `FlatMap<Range<T>, Range<T>, F>` state, from rustc's layout:
/// `inner: FlattenCompat { iter: Fuse { iter: Option<Map { iter: Range<T>, f }> },
/// frontiter: Option<Range<T>>, backiter: Option<Range<T>> }`. Every offset is a
/// byte offset within the `FlatMap` value.
struct FlatMapStdLayout {
    /// The outer `Range<T>` inside `Fuse`'s `Some(Map { .. })`.
    outer: FlatMapOptionalRange,
    /// The partially consumed inner range `next` left at the front.
    front: FlatMapOptionalRange,
    /// The partially consumed inner range `next_back` left at the back.
    back: FlatMapOptionalRange,
    /// Offsets of `Range<T>`'s `start` / `end` within the range, and its size.
    start_off: u64,
    end_off: u64,
    range_size: u64,
}

/// One `Option`-wrapped `Range<T>` of a `FlatMap`: the `Option`'s offset and
/// tag, and the offset of the `Range<T>` its `Some` holds.
struct FlatMapOptionalRange {
    option_off: u64,
    tag: OptionTagLayout,
    range_off: u64,
}

/// Byte offset and (normalized) type of the field named `name` of the struct
/// `ty`, from rustc's layout.
fn named_struct_field<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    name: &str,
) -> Result<(u64, Ty<'tcx>), String> {
    let ty::Adt(adt, _) = ty.kind() else {
        return Err(format!("{ty:?} is not a struct"));
    };
    if !adt.is_struct() {
        return Err(format!("{ty:?} is not a struct"));
    }
    let idx = adt
        .non_enum_variant()
        .fields
        .iter_enumerated()
        .find(|(_, f)| f.name.as_str() == name)
        .map(|(i, _)| i.as_usize())
        .ok_or_else(|| format!("{ty:?} has no `{name}` field"))?;
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("layout_of({ty:?}) failed: {e:?}"))?;
    Ok((
        layout.fields.offset(idx).bytes(),
        field_ty_of(tcx, ty, idx)?,
    ))
}

/// [`FlatMapStdLayout`] for the bounded `flat_map_ty` (`FlatMap<Range<T>,
/// Range<T>, F>`), walking rustc's own field layout by field name.
fn flatmap_std_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    flat_map_ty: Ty<'tcx>,
    range_ty: Ty<'tcx>,
) -> Result<FlatMapStdLayout, String> {
    let (inner_off, compat_ty) = named_struct_field(tcx, flat_map_ty, "inner")?;
    let (fuse_off, fuse_ty) = named_struct_field(tcx, compat_ty, "iter")?;
    let (fuse_iter_off, fuse_option_ty) = named_struct_field(tcx, fuse_ty, "iter")?;
    let outer_tag = option_tag_layout(tcx, fuse_option_ty)?;
    let (_, _, _, map_ty) = option_some_none_variants(tcx, fuse_option_ty)?;
    let (map_iter_off, map_iter_ty) = named_struct_field(tcx, map_ty, "iter")?;
    if map_iter_ty != range_ty {
        return Err(format!(
            "flat_map Map iter {map_iter_ty:?} is not {range_ty:?}"
        ));
    }
    let outer_option_off = inner_off + fuse_off + fuse_iter_off;
    let outer = FlatMapOptionalRange {
        option_off: outer_option_off,
        range_off: outer_option_off + outer_tag.some_payload_off + map_iter_off,
        tag: outer_tag,
    };
    let optional_range = |name: &str| -> Result<FlatMapOptionalRange, String> {
        let (off, option_ty) = named_struct_field(tcx, compat_ty, name)?;
        let (_, _, _, payload_ty) = option_some_none_variants(tcx, option_ty)?;
        if payload_ty != range_ty {
            return Err(format!(
                "flat_map {name} {payload_ty:?} is not {range_ty:?}"
            ));
        }
        let tag = option_tag_layout(tcx, option_ty)?;
        let option_off = inner_off + off;
        Ok(FlatMapOptionalRange {
            option_off,
            range_off: option_off + tag.some_payload_off,
            tag,
        })
    };
    let front = optional_range("frontiter")?;
    let back = optional_range("backiter")?;
    let (start_off, _) = named_struct_field(tcx, range_ty, "start")?;
    let (end_off, _) = named_struct_field(tcx, range_ty, "end")?;
    let range_size = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(range_ty))
        .map_err(|e| format!("layout_of({range_ty:?}) failed: {e:?}"))?
        .size
        .bytes();
    Ok(FlatMapStdLayout {
        outer,
        front,
        back,
        start_off,
        end_off,
        range_size,
    })
}

/// If `ty` is `iter::adapters::flatten::FlatMap<I, U, F>` where BOTH `I` and `U`
/// are bare `Range<T>` for the SAME scalar index type `T`, and `F` is a
/// non-capturing (ZST) closure, resolve the shape. Returns `None` for anything
/// else — a non-`FlatMap` type, a non-Range `I`/`U`, a mismatched `T`, or a
/// CAPTURING `F`, or a `FlatMap` whose rustc layout does not have std's
/// `FlattenCompat` shape — so the caller falls through to the general call path
/// and core's real bodies. Used by BOTH the ctor (`lower_flatmap_bounded_ctor`)
/// and the terminal driver (`lower_flatmap_bounded_consumer`) — ONE resolver, so
/// the shape gate and the std-layout offsets can never drift between the two.
fn resolve_flatmap_bounded<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Option<FlatMapBounded<'tcx>> {
    let ty = ctx.monomorphize_ty(ty);
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    if !is_flatmap_adapter(ctx.tcx, adt.did()) {
        return None;
    }
    let i_ty = ctx.monomorphize_ty(args.type_at(0));
    let u_ty = ctx.monomorphize_ty(args.type_at(1));
    let f_ty = ctx.monomorphize_ty(args.type_at(2));
    let t1 = range_index_ty(ctx.tcx, i_ty)?;
    let t2 = range_index_ty(ctx.tcx, u_ty)?;
    if t1 != t2 {
        return None;
    }
    // Only a ZST (non-capturing) `F` is admitted — a capturing closure would
    // need its upvar bytes in `Map::f`, which this driver does not model (fail
    // closed, matching `Map`/`Filter`'s own capturing-closure support boundary
    // being a SEPARATE, explicit branch).
    if !matches!(f_ty.kind(), ty::Closure(..)) {
        return None;
    }
    if !is_zero_sized_ty(ctx.tcx, f_ty) {
        return None;
    }
    let ir_ty = rust_ty_to_trust_ir_ty(ctx.tcx, t1).ok()?;
    if !ir_ty.is_integer() {
        return None;
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, t1).ok()?;
    let std_layout = flatmap_std_layout(ctx.tcx, ty, i_ty).ok()?;
    Some(FlatMapBounded {
        ir_ty,
        size,
        range_ty: i_ty,
        closure_ty: f_ty,
        std_layout,
    })
}

/// A `.take(n)` / `.skip(k)` that sat DIRECTLY below a `.rev()` over a BARE
/// slice source, rewritten into a boundary CLAMP of the walk; the adapter
/// itself is dropped from `adapters` (Take/Skip are item-identity adapters, so
/// the chain's `item` is unchanged). `count_off` is the byte offset of the
/// adapter's `usize` count field within the chain slot (shifted like every
/// other state offset when the chain nests inside an outer adapter's slot).
/// Applied by `emit_rev_clamp` — IDEMPOTENTLY — at the `.rev()` ctor AND at
/// every drive preheader; see `emit_rev_clamp` for why both are required.
#[derive(Clone, Copy)]
enum RevClamp {
    /// `.take(n)`: `end' = ptr + min(n, (end - ptr) / elem_size) * elem_size` —
    /// the reversed walk over the clamped prefix IS "first n, then reversed".
    /// `n` is left in place: the walk only ever shrinks `end`, so a re-clamp is
    /// `min(n, remaining) = remaining` (identity); and with `n >= remaining`
    /// any REAL (non-intercepted) `Take::next`/`next_back` body degenerates to
    /// the bare-iterator walk, matching the clamped semantics.
    TakeEnd { count_off: u64 },
    /// `.skip(k)`: `ptr' = ptr + min(k, (end - ptr) / elem_size) * elem_size`,
    /// then `k := 0` (std's own `Skip::next` zeroes `n` once the skip is
    /// applied) — a re-clamp then moves `ptr` by `min(0, len) = 0` (identity).
    SkipStart { count_off: u64 },
}

/// A fully-resolved iterator chain: a source plus an outermost-last stack of
/// adapters, all sharing ONE memory slot (the outermost type's layout). Each
/// component records its byte offset within that slot.
struct IterChain<'tcx> {
    source: ChainSource<'tcx>,
    /// Byte offset of the source iterator state within the chain slot.
    source_offset: u64,
    /// Adapters from innermost to outermost, with the byte offset of each
    /// closure value within the chain slot.
    adapters: Vec<(ChainAdapter<'tcx>, u64)>,
    /// The element type the WHOLE chain yields (the outermost item).
    item: ChainItem<'tcx>,
    /// `true` if a `.rev()` wraps the whole chain: the source is iterated
    /// end -> start (only modelable for a bounded Range / slice source, and only
    /// when NO bounded-count adapter sits BELOW the `.rev()`; otherwise fail
    /// closed). A double `.rev()` cancels back to forward.
    reversed: bool,
    /// `Some` when a below-rev `.take(n)` / `.skip(k)` was rewritten away into
    /// a slot boundary clamp (see `RevClamp`). Slice source only.
    rev_clamp: Option<RevClamp>,
    /// `Some` when the source is an owning `vec::IntoIter` whose heap buffer and
    /// unyielded elements the chain state holds. A terminal that takes the chain
    /// BY VALUE owns them and must drop them once its drive finishes
    /// (`emit_consumed_chain_drop`).
    owned_buffer: Option<OwnedVecBuffer<'tcx>>,
}

/// The owning `vec::IntoIter` state of a chain source, addressed within the
/// chain slot. `fields` are rustc's own `buf` / `ptr` / `cap` / `end` offsets
/// (`VecIntoIterLayout`) plus every enclosing adapter's field-0 offset, shifted
/// exactly like `IterChain::source_offset`. The drive writes only the `ptr` /
/// `end` cursor, so `buf` and `cap` keep the values the iterator was built with
/// in the original slot and in any private copy of it, and in `Slot` cursor mode
/// `[ptr, end)` is exactly the elements no pull has yielded.
#[derive(Clone, Copy)]
struct OwnedVecBuffer<'tcx> {
    fields: VecIntoIterLayout,
    element_ty: Ty<'tcx>,
}

impl OwnedVecBuffer<'_> {
    fn shift(&mut self, delta: u64) {
        self.fields.buf += delta;
        self.fields.ptr += delta;
        self.fields.cap += delta;
        self.fields.end += delta;
    }
}

/// Whether `chain`'s drive must keep its source cursor in the chain slot
/// (`SourceCursor::Slot`) so the drop that follows it can read the unyielded
/// `[ptr, end)` range: an owning `vec::IntoIter` source whose element needs drop.
fn chain_owns_droppable_elements<'tcx>(tcx: TyCtxt<'tcx>, chain: &IterChain<'tcx>) -> bool {
    chain.owned_buffer.is_some_and(|owned| {
        owned
            .element_ty
            .needs_drop(tcx, ty::TypingEnv::fully_monomorphized())
    })
}

/// The refusal for a `.cloned()` whose element `cloned_ty` has a bitwise clone
/// (`clone_is_bitwise_copy`) but needs drop. The bridge models such a `Cloned`
/// as `Copied`: its drive LOADS `T` out of the reference, so every clone is an
/// owned `T` that must be dropped wherever the drive discards it (a `count`ed
/// item, a `filter` reject, ...), and no differential covers those drops for
/// `Cloned` output. The refusal is an `Err` out of `resolve_iter_chain`, so the
/// `.cloned()` constructor and every interception that resolves the chain (a
/// drive, a direct `next`) fail closed by name.
fn cloned_drop_refusal(cloned_ty: Ty<'_>) -> String {
    format!(
        "[TCG-ITER-CLONED-CLONE] `.cloned()` over `{cloned_ty:?}`, which needs drop: this \
         backend models `Cloned` by loading the element, and no differential covers the \
         drops of the clones its drive discards; failing closed"
    )
}

/// If `ty` is one of the iterator shapes we drive (`Range`, `slice::Iter`,
/// `Map`, `Filter`, possibly nested), resolve the whole chain — its source, its
/// adapter stack, and every component's byte offset within `ty`'s layout.
/// Returns `Ok(None)` for any iterator we do not model (fail closed).
fn resolve_iter_chain<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<IterChain<'tcx>>, String> {
    let ty = ctx.monomorphize_ty(ty);
    // The scalar drive cannot represent an aggregate Map output. Its real
    // constructor/consumer bodies retain the existing aggregate ABI instead;
    // decide before inspecting/emitting any synthesized chain state. The same
    // classifier protects these bodies from dead-iterator trap substitution.
    if iterator_aggregate_fallback::mentions_aggregate_map(ctx.tcx, ty) {
        return Ok(None);
    }
    // `str::Bytes` = `Bytes(Copied<slice::Iter<u8>>)`: a transparent newtype over
    // its inner `Copied<slice::Iter<u8>>` (field 0, offset 0, no added layout).
    // Peel it and resolve the inner -- `Copied` is a modeled adapter over the u8
    // `slice::Iter`, yielding `u8` by value (exactly `s.as_bytes().iter().copied()`).
    if is_str_bytes_ty(ctx.tcx, ty) {
        let inner_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, 0)?);
        return resolve_iter_chain(ctx, inner_ty);
    }
    // A bare source iterator.
    if let Some(index_ty) = range_index_ty(ctx.tcx, ty) {
        let ir_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
        let (size, _) = element_layout_size_align(ctx.tcx, index_ty)?;
        return Ok(Some(IterChain {
            source: ChainSource::Range {
                index_ty,
                ir_ty: ir_ty.clone(),
                size,
            },
            source_offset: 0,
            adapters: Vec::new(),
            item: ChainItem {
                rust_ty: index_ty,
                ir_ty,
                deref_elem_ir: None,
                tuple: None,
            },
            reversed: false,
            rev_clamp: None,
            owned_buffer: None,
        }));
    }
    if let Some(index_ty) = index_range_index_ty(ctx.tcx, ty) {
        let ir_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
        let (size, _) = element_layout_size_align(ctx.tcx, index_ty)?;
        return Ok(Some(IterChain {
            source: ChainSource::Range {
                index_ty,
                ir_ty: ir_ty.clone(),
                size,
            },
            source_offset: 0,
            adapters: Vec::new(),
            item: ChainItem {
                rust_ty: index_ty,
                ir_ty,
                deref_elem_ir: None,
                tuple: None,
            },
            reversed: false,
            rev_clamp: None,
            owned_buffer: None,
        }));
    }
    if let Some(index_ty) = range_inclusive_index_ty(ctx.tcx, ty) {
        let ir_ty = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
        let (start_off, end_off, exhausted_off) = range_inclusive_field_offsets(ctx.tcx, ty)?;
        return Ok(Some(IterChain {
            source: ChainSource::RangeInclusive {
                index_ty,
                ir_ty: ir_ty.clone(),
                start_off,
                end_off,
                exhausted_off,
            },
            source_offset: 0,
            adapters: Vec::new(),
            item: ChainItem {
                rust_ty: index_ty,
                ir_ty,
                deref_elem_ir: None,
                tuple: None,
            },
            reversed: false,
            rev_clamp: None,
            owned_buffer: None,
        }));
    }
    if let Some(element_ty) = slice_iter_or_mut_element_ty(ctx.tcx, ty) {
        let elem_ir = rust_ty_to_trust_ir_ty(ctx.tcx, element_ty)?;
        let (size, _) = element_layout_size_align(ctx.tcx, element_ty)?;
        // `slice::Iter<T>::next` yields `&T`; `slice::IterMut<T>::next` yields `&mut T`.
        // Both share the identical `{ ptr, end }` cursor + `data + len*size` stride — only
        // the yielded reference's mutability differs, which is TRANSPARENT to the bridge's
        // memory model: the item is a POINTER (the element address) either way, and a
        // `for_each`/`map` closure over `.iter_mut()` writes THROUGH it into the live
        // buffer (the private chain-state copy duplicates only the `{ptr,end}` cursor,
        // whose `ptr` still points at that buffer). The item `rust_ty` is `&T` in both
        // cases — it is read only at the pointer/aggregate-layout level, where `&T` and
        // `&mut T` are identical (both thin pointers, no aggregate layout).
        let item_rust_ty = Ty::new_imm_ref(ctx.tcx, ctx.tcx.lifetimes.re_erased, element_ty);
        return Ok(Some(IterChain {
            source: ChainSource::Slice {
                element_ty,
                ir_ty: elem_ir.clone(),
                size,
                trusted_random_access: true,
                end_off: slice_iter_end_offset(),
                repr: SliceCursorRepr::Pointers,
                owning_vec: None,
            },
            source_offset: 0,
            adapters: Vec::new(),
            item: ChainItem {
                rust_ty: item_rust_ty,
                ir_ty: TrustIrTy::Ptr,
                deref_elem_ir: Some(elem_ir),
                tuple: None,
            },
            reversed: false,
            rev_clamp: None,
            owned_buffer: None,
        }));
    }

    // `vec::IntoIter<T>` — a BY-VALUE owning slice source (`v.into_iter().map(f).sum()`
    // / `.collect()` / bare `.sum()`). Its `next` yields `T` BY VALUE, unlike
    // `slice::Iter`'s `&T`. Model it as the SAME `{ ptr, end }` POINTER cursor a
    // borrowing slice uses, read at rustc's own field offsets (`VecIntoIterLayout`:
    // the source starts at the `ptr` field, `end_off` bytes before `end`) PLUS an
    // implicit leading `Copied` adapter that turns each yielded `&T` pointer into the
    // LOADED value `T` — i.e. EXACTLY the chain `v.iter().copied()` produces, whose
    // cond-guarded value-load (`AdapterKind::Copied`'s proven drive) never faults
    // one-past-end. Every outer adapter layered by the recursion below (`.map`/`.filter`/
    // …) then receives the by-value `T` its closure expects, and the terminal
    // accumulates values. The chain records the iterator's owned state
    // (`owned_buffer`): a terminal that takes the chain by value consumes the
    // iterator, so after its drive it drops the elements no pull yielded and frees
    // the buffer (`emit_consumed_chain_drop`), as std's terminal does when its
    // `self` goes out of scope. A `&mut self` terminal leaves the iterator to the
    // caller's own `vec::IntoIter` drop, which does the same. The element is a
    // single scalar (the `vec_intoiter_element_ty` gate) but may need drop (a
    // `Drop` newtype); the gate admits only one whose glue the per-element drop
    // loop lowers, and every pulled item the drive discards instead of moving on
    // is dropped at that discard (`discard_drop_plan`), so each element is
    // dropped exactly once. A non-scalar element falls through and fails closed.
    if let Some(element_ty) = vec_intoiter_element_ty(ctx.tcx, ty) {
        let elem_ir = rust_ty_to_trust_ir_ty(ctx.tcx, element_ty)?;
        let (size, _) = element_layout_size_align(ctx.tcx, element_ty)?;
        let ptr_rust_ty = Ty::new_imm_ref(ctx.tcx, ctx.tcx.lifetimes.re_erased, element_ty);
        // The `&T` pointer item the {ptr,end} slice cursor yields (Copied's INPUT).
        let ptr_item = ChainItem {
            rust_ty: ptr_rust_ty,
            ir_ty: TrustIrTy::Ptr,
            deref_elem_ir: Some(elem_ir.clone()),
            tuple: None,
        };
        // The by-value `T` item AFTER Copied (this chain's top-level Item).
        let value_item = ChainItem {
            rust_ty: element_ty,
            ir_ty: elem_ir.clone(),
            deref_elem_ir: None,
            tuple: None,
        };
        let layout = vec_intoiter_layout(ctx.tcx, ty)?;
        if layout.end <= layout.ptr {
            return Err(format!(
                "[TCG-VEC-INTOITER-LAYOUT] {ty:?} places `end`@{} before `ptr`@{}; the \
                 iterator-chain cursor needs `end` after `ptr`",
                layout.end, layout.ptr
            ));
        }
        return Ok(Some(IterChain {
            source: ChainSource::Slice {
                element_ty,
                ir_ty: elem_ir.clone(),
                size,
                trusted_random_access: false,
                end_off: layout.end - layout.ptr,
                repr: SliceCursorRepr::Pointers,
                owning_vec: Some(layout),
            },
            source_offset: layout.ptr,
            adapters: vec![(
                ChainAdapter {
                    kind: AdapterKind::Copied { elem_ir },
                    closure_ty: ctx.tcx.types.unit,
                    input: ptr_item,
                    output: value_item.clone(),
                },
                0,
            )],
            item: value_item,
            reversed: false,
            rev_clamp: None,
            owned_buffer: Some(OwnedVecBuffer {
                fields: layout,
                element_ty,
            }),
        }));
    }

    // `array::IntoIter<T, N>` — a BY-VALUE owning array source (`a.into_iter().map(f).sum()`
    // / `.collect()` / bare `[..].into_iter().sum()`). Same shape as `vec::IntoIter`
    // above — the slice cursor PLUS an implicit leading `Copied` adapter that loads the
    // yielded `&T` pointer into the value `T`, exactly `a.iter().copied()` — but its
    // cursor is rustc's own `alive: IndexRange { start, end }` of element INDICES into
    // the iterator's inline `data` buffer (`ArrayIntoIterLayout`,
    // `SliceCursorRepr::Indices`). That is the state both `lower_array_into_iter` and
    // rustc's inlined `-O2`/`-O3` constructor build, and the state rustc's inlined
    // `next` advances, so the terminal reads it correctly whoever built or advanced
    // it. The elements live inline, so there is NO heap buffer — nothing to free or
    // leak — and the element needs no drop (`array_intoiter_element_ty`), so no
    // pulled, discarded or unyielded element is owed a destructor. Any other
    // element (non-scalar, or one that needs drop) is not modeled here.
    if let Some(element_ty) = array_intoiter_element_ty(ctx.tcx, ty) {
        let elem_ir = rust_ty_to_trust_ir_ty(ctx.tcx, element_ty)?;
        let (size, _) = element_layout_size_align(ctx.tcx, element_ty)?;
        let ptr_rust_ty = Ty::new_imm_ref(ctx.tcx, ctx.tcx.lifetimes.re_erased, element_ty);
        let ptr_item = ChainItem {
            rust_ty: ptr_rust_ty,
            ir_ty: TrustIrTy::Ptr,
            deref_elem_ir: Some(elem_ir.clone()),
            tuple: None,
        };
        let value_item = ChainItem {
            rust_ty: element_ty,
            ir_ty: elem_ir.clone(),
            deref_elem_ir: None,
            tuple: None,
        };
        let layout = array_intoiter_layout(ctx.tcx, ty, element_ty)?;
        if layout.end <= layout.start {
            return Err(format!(
                "[TCG-ARRAY-INTOITER-LAYOUT] {ty:?} places `alive.end`@{} before \
                 `alive.start`@{}; the iterator-chain cursor needs `end` after `start`",
                layout.end, layout.start
            ));
        }
        return Ok(Some(IterChain {
            source: ChainSource::Slice {
                element_ty,
                ir_ty: elem_ir.clone(),
                size,
                trusted_random_access: false,
                end_off: layout.end - layout.start,
                repr: SliceCursorRepr::Indices {
                    data_off: layout.data - layout.start,
                },
                owning_vec: None,
            },
            source_offset: layout.start,
            adapters: vec![(
                ChainAdapter {
                    kind: AdapterKind::Copied { elem_ir },
                    closure_ty: ctx.tcx.types.unit,
                    input: ptr_item,
                    output: value_item.clone(),
                },
                0,
            )],
            item: value_item,
            reversed: false,
            rev_clamp: None,
            owned_buffer: None,
        }));
    }

    // `a.chain(b)` — a two-source concatenation. `Chain<A, B>` is laid out as
    // `{ a: Option<A>, b: Option<B> }`; we model it by iterating each sub-source's
    // RAW iterator state (the `Option` payload) directly, tracking exhaustion by
    // `start < end` rather than by the `Option` tag (which we set to `Some` at
    // construction and never re-read). Only when BOTH sub-iterators are bare
    // sources with the SAME item shape, and each `Option<sub>` is a Direct-tagged
    // (Range) layout whose payload offset is fixed, is the chain modeled.
    if let ty::Adt(adt, args) = ty.kind() {
        if is_chain_adapter(ctx.tcx, adt.did()) {
            return resolve_chain_concat(ctx, ty, *args);
        }
        // `a.zip(b)` — a two-source parallel pairing yielding `(A::Item, B::Item)`.
        if is_zip_adapter(ctx.tcx, adt.did()) {
            return resolve_zip(ctx, ty, *args);
        }
    }

    // An adapter ADT (`Map`/`Filter`/`Copied`/`Take`/…). Identify by def path,
    // peel the inner iterator (always field 0) off the generic args, recurse, then
    // layer this adapter on top.
    let ty::Adt(adt, args) = ty.kind() else {
        return Ok(None);
    };
    let tag = match adapter_kind_of(ctx.tcx, adt.did()) {
        Some(tag) => tag,
        None => return Ok(None),
    };
    let inner_ty = ctx.monomorphize_ty(args.type_at(0));

    let Some(mut inner) = resolve_iter_chain(ctx, inner_ty)? else {
        return Ok(None);
    };

    // Layout of THIS adapter type. Field 0 is ALWAYS the inner iterator; the
    // inner chain's component offsets are relative to the inner slot which sits at
    // this adapter's field-0 offset, so shift them all by that offset.
    let layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("iterator adapter layout_of failed: {e:?}"))?;
    let rustc_abi::FieldsShape::Arbitrary { .. } = layout.fields else {
        return Err("iterator adapter layout is not a field struct".to_owned());
    };
    let inner_field_offset = layout.fields.offset(0).bytes();
    inner.source_offset += inner_field_offset;
    // A rewritten below-rev take/skip's count-field offset shifts into this
    // outer slot exactly like every other state offset.
    if let Some(RevClamp::TakeEnd { count_off } | RevClamp::SkipStart { count_off }) =
        inner.rev_clamp.as_mut()
    {
        *count_off += inner_field_offset;
    }
    if let Some(owned) = inner.owned_buffer.as_mut() {
        owned.shift(inner_field_offset);
    }
    for (adapter, off) in inner.adapters.iter_mut() {
        // Shift BOTH the closure-field offset (tuple `.1`) AND any state-field
        // offsets embedded inside the adapter kind (take/skip count, step_by state,
        // enumerate index) into this outer slot.
        *off += inner_field_offset;
        adapter.kind.shift_offsets(inner_field_offset);
    }
    let off = |field: usize| -> u64 { layout.fields.offset(field).bytes() };
    // Find an adapter field's declaration INDEX by its NAME (robust against layout
    // field reordering — `off`/`layout.fields.offset` key on the declaration index,
    // which the field NAME resolves to). Used by the `filter_map`/`take_while`/`scan`
    // arms to locate the closure ("f"/"predicate") and `scan`'s "state" cell.
    let field_index_by_name = |name: &str| -> Option<usize> {
        adt.non_enum_variant()
            .fields
            .iter_enumerated()
            .find(|(_, f)| f.name.as_str() == name)
            .map(|(i, _)| i.as_usize())
    };

    let input = inner.item.clone();

    // `.rev()` is a SOURCE-level modifier, not a per-element adapter. It only
    // makes sense over a bounded DoubleEndedIterator we can run backwards (our
    // Range / slice sources), and only when NO bounded-count adapter (`take`/
    // `skip`/`step_by`) sits BELOW it — those change the forward sequence in a way
    // a naive end->start walk would not reproduce. A double `.rev()` cancels.
    if tag == AdapterTag::Rev {
        // A `.take(n)` / `.skip(k)` DIRECTLY below this `.rev()`, over a BARE
        // slice source, is exactly a boundary CLAMP of the reversed walk
        // ("first n, then reversed" / "all but the first k, then reversed").
        // Drop the adapter into `rev_clamp` and mark the chain reversed; the
        // rev ctor AND every drive preheader apply the (idempotent) clamp via
        // `emit_rev_clamp`.
        if rewrite_below_rev_bounded(&mut inner) {
            inner.reversed = true;
            return Ok(Some(inner));
        }
        // A bounded-count adapter (`take`/`skip`/`step_by`) or an `Enumerate`
        // counter below a `.rev()` is direction-dependent WHEREVER it sits —
        // including ABOVE an inner Rev: the old `!inner.reversed` exemption let
        // `.rev().take(2).rev()` "cancel" the double flip THROUGH the Take,
        // silently computing the FORWARD `take(2)` (12, not 45, for `a*10+b`
        // over [1,2,3,4,5]); and a below-rev `.enumerate()`'s forward counter
        // was driven 0,1,2,… along the BACKWARD walk (153, not 161). Reject
        // UNCONDITIONALLY (mirrors the `try_rfold` reverse-route guard).
        if inner.adapters.iter().any(|(a, _)| {
            a.kind.is_count_modifier()
                || matches!(
                    a.kind,
                    AdapterKind::Enumerate { .. }
                        | AdapterKind::FilterMap
                        | AdapterKind::TakeWhile { .. }
                        | AdapterKind::SkipWhile { .. }
                        | AdapterKind::Scan { .. }
                        | AdapterKind::MapWhile
                )
        }) {
            return Err("rev() over a take/skip/step_by/enumerate chain is not modeled".to_owned());
        }
        // A `RangeInclusive` reverses too: `emit_source_next` drives a reversed
        // inclusive source as std's `spec_next_back` (yield `end`, step `end`
        // down, set `exhausted` on the `start == end` element), not as the
        // forward step run backwards.
        inner.reversed = !inner.reversed;
        return Ok(Some(inner));
    }

    // The closure-carrying adapters (`Map`/`Filter`) read field 1 (the closure);
    // the structural adapters read their own state fields.
    let (kind, output, closure_ty) = match tag {
        AdapterTag::Map | AdapterTag::Filter => {
            let closure_ty = ctx.monomorphize_ty(args.type_at(1));
            let ty::Closure(..) = closure_ty.kind() else {
                return Err("iterator adapter payload is not a closure".to_owned());
            };
            // A capturing (non-ZST) closure's upvars live at the closure field's
            // offset; a flat-slot layout is required (else fail closed).
            if !is_zero_sized_ty(ctx.tcx, closure_ty) {
                closure_memory_layout(ctx.tcx, closure_ty)?;
            }
            let closure_off = off(1);
            if tag == AdapterTag::Filter {
                (
                    AdapterKind::Filter,
                    input.clone(),
                    Some((closure_ty, closure_off)),
                )
            } else {
                // A `.map` whose `Self::Item` is a TUPLE (from `.enumerate()` /
                // `.zip()`) takes a tuple-pattern closure (`|(i, x)| ..`). rustc
                // DOES codegen the tuple-pattern closure body as a standalone
                // symbol (`fn {closure}(_1: &mut env, _2: (A, B)) -> R`), so we can
                // call it — provided the tuple `(A, B)` is a by-value aggregate the
                // bridge can build and the callee can declare (a `<=16`-byte
                // register pair of scalar / pointer leaves). Validate that here;
                // otherwise fail closed.
                if input.tuple.is_some() {
                    if memory_aggregate_layout_shared(ctx.tcx, input.rust_ty)?.is_none() {
                        return Err("map over a tuple item whose tuple is not a by-value \
                             register-pair aggregate is not modeled"
                            .to_owned());
                    }
                }
                // Map output = the closure's return scalar. The closure RECEIVES
                // the inner item (a scalar / `&T`, or the tuple aggregate handled
                // above).
                let ty::Closure(_, cargs) = closure_ty.kind() else {
                    return Err("map closure is not a closure".to_owned());
                };
                let sig = ctx
                    .tcx
                    .instantiate_bound_regions_with_erased(cargs.as_closure().sig());
                let out_ty = ctx.monomorphize_ty(sig.output());
                let out_ir = rust_ty_to_trust_ir_ty(ctx.tcx, out_ty)?;
                if out_ir.bit_width().is_none() {
                    return Err("map closure output is not a scalar".to_owned());
                }
                if matches!(out_ty.kind(), ty::Ref(..)) {
                    return Err("map closure returning a reference is not modeled".to_owned());
                }
                let out_item = ChainItem {
                    rust_ty: out_ty,
                    ir_ty: out_ir,
                    deref_elem_ir: None,
                    tuple: None,
                };
                (AdapterKind::Map, out_item, Some((closure_ty, closure_off)))
            }
        }
        AdapterTag::Copied | AdapterTag::Cloned => {
            // `Copied<I>` / `Cloned<I>` over `&T`: yield the deref'd scalar `T`.
            // Only modelable when the inner item is a `&T` (a slice element); a
            // copied over a by-value scalar iter is a no-op we still model.
            //
            // `Cloned` yields `<T as Clone>::clone(&elem)`, which is the loaded
            // element only when that clone is a bitwise copy. Any other clone
            // (a hand-written body, with its own value and side effects) is left
            // to core's real `Cloned` body, which calls it. A bitwise clone of a
            // `T` that needs drop refuses (`cloned_drop_refusal`): every clone
            // is an owned `T` the drive must drop wherever it discards one, and
            // no differential covers those drops for `Cloned` output. A bitwise
            // clone may be `!Freeze` (core's `Cell<T>`): a closure handed
            // `&clone` can write it, so every by-reference consumer reloads the
            // item after the call (`shared_ref_item_reload`).
            if tag == AdapterTag::Cloned {
                let ty::Ref(_, elem_ty, _) = *input.rust_ty.kind() else {
                    return Ok(None);
                };
                let elem_ty = ctx.monomorphize_ty(elem_ty);
                if !clone_is_bitwise_copy(ctx.tcx, elem_ty, 0) {
                    return Ok(None);
                }
                if elem_ty.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized()) {
                    return Err(cloned_drop_refusal(elem_ty));
                }
            }
            let elem_ir = match &input.deref_elem_ir {
                Some(e) => e.clone(),
                None => {
                    // Already by-value (e.g. `(0..n).copied()` is ill-typed, but a
                    // `map(|&x| x)` chain could produce a value Copied) — identity.
                    if input.tuple.is_some() {
                        return Err("copied/cloned over a tuple item is not modeled".to_owned());
                    }
                    input.ir_ty.clone()
                }
            };
            // The yielded item is the element `T` itself, not the `&T` the inner
            // chain yields: a tuple built over it (`.copied().enumerate()` passes
            // `(usize, T)` to the next closure) must have `T`'s layout.
            let out_item = ChainItem {
                rust_ty: input.rust_ty.builtin_deref(true).unwrap_or(input.rust_ty),
                ir_ty: elem_ir.clone(),
                deref_elem_ir: None,
                tuple: None,
            };
            (AdapterKind::Copied { elem_ir }, out_item, None)
        }
        AdapterTag::Take => {
            // `Take<I> { iter, n: usize }`: the count field at off(1).
            (AdapterKind::Take { count_off: off(1) }, input.clone(), None)
        }
        AdapterTag::Skip => {
            // `Skip<I> { iter, n: usize }`: the skip field at off(1).
            (AdapterKind::Skip { count_off: off(1) }, input.clone(), None)
        }
        AdapterTag::StepBy => {
            // Resolve both fields by NAME and then through rustc's layout. Rust
            // declaration order does not authorize an `off(1) + sizeof(usize)`
            // guess: the layout may reorder fields. Also seal their exact types
            // so a future std representation change fails closed here.
            let step_minus_one_idx = field_index_by_name("step_minus_one")
                .ok_or_else(|| "StepBy has no `step_minus_one` field".to_owned())?;
            let first_take_idx = field_index_by_name("first_take")
                .ok_or_else(|| "StepBy has no `first_take` field".to_owned())?;
            let step_minus_one_ty =
                ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, step_minus_one_idx)?);
            let first_take_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, first_take_idx)?);
            if step_minus_one_ty != ctx.tcx.types.usize || first_take_ty != ctx.tcx.types.bool {
                return Err(format!(
                    "StepBy state fields changed type: step_minus_one={step_minus_one_ty:?}, \
                     first_take={first_take_ty:?}"
                ));
            }
            let iter_idx = field_index_by_name("iter")
                .ok_or_else(|| "StepBy has no `iter` field".to_owned())?;
            let iter_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, iter_idx)?);
            let range_countdown = step_by_range_countdown(ctx.tcx, iter_ty);
            // The countdown drivers address `start` / `end` through the bare
            // Range source the chain resolved for `iter`.
            if range_countdown
                && (!inner.adapters.is_empty()
                    || inner.reversed
                    || inner.rev_clamp.is_some()
                    || !matches!(inner.source, ChainSource::Range { .. }))
            {
                return Err(
                    "step_by over a Range did not resolve to a bare Range source".to_owned(),
                );
            }
            (
                AdapterKind::StepBy {
                    step_minus_one_off: off(step_minus_one_idx),
                    first_take_off: off(first_take_idx),
                    range_countdown,
                },
                input.clone(),
                None,
            )
        }
        AdapterTag::Enumerate => {
            // `Enumerate<I> { iter, count: usize }`: yields `(usize, item)`.
            if input.tuple.is_some() {
                return Err("enumerate over a tuple item is not modeled".to_owned());
            }
            let usize_ty = ctx.tcx.types.usize;
            // The index is the running count, loaded at `usize_field_ty` (the
            // width the drive's Enumerate arm reads it at).
            let idx_item = ChainItem {
                rust_ty: usize_ty,
                ir_ty: usize_field_ty(ctx.tcx),
                deref_elem_ir: None,
                tuple: None,
            };
            // The value side of the tuple is the inner item's VALUE: for a slice
            // `&T` inner, enumerate yields `(usize, &T)` — keep the pointer rep.
            let val_item = input.clone();
            // The `Self::Item` rust type is the real `(usize, InnerItem)` tuple, so
            // a downstream `.map(|(i,x)| ..)` closure's aggregate parameter layout
            // can be computed from it.
            let tuple_rust_ty = Ty::new_tup(ctx.tcx, &[usize_ty, input.rust_ty]);
            let out_item = ChainItem {
                rust_ty: tuple_rust_ty,
                ir_ty: TrustIrTy::I64,
                deref_elem_ir: None,
                tuple: Some((Box::new(idx_item), Box::new(val_item))),
            };
            (
                AdapterKind::Enumerate {
                    count_off: off(1),
                    counter_slot: None,
                },
                out_item,
                None,
            )
        }
        AdapterTag::FilterMap => {
            // `.filter_map(f)`: `FilterMap<I, F> { iter, f }`. The closure takes
            // `Self::Item` BY VALUE and returns `Option<U>`.
            // REV-BELOW REJECT: a `.rev()` below this adapter (`inner.reversed`)
            // would drive a REVERSED sequence through the Option gate — an
            // unvalidated combination (the forward rev-above / rfold guards do NOT
            // catch rev-BELOW). Fail closed BEFORE building the adapter.
            if inner.reversed {
                return Err(
                    "filter_map over a reversed (below-rev) chain is not modeled".to_owned(),
                );
            }
            // A 2-tuple item is materialized for the BY-VALUE closure arg in the
            // drive (build_tuple_item_arg); a non-register-pair tuple fails closed
            // there. The output is the Option payload scalar (below), never a tuple.
            let idx =
                field_index_by_name("f").ok_or_else(|| "FilterMap has no `f` field".to_owned())?;
            let closure_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, idx)?);
            let ty::Closure(..) = closure_ty.kind() else {
                return Err("filter_map payload is not a closure".to_owned());
            };
            if !is_zero_sized_ty(ctx.tcx, closure_ty) {
                closure_memory_layout(ctx.tcx, closure_ty)?;
            }
            let out_ty = ctx.monomorphize_ty(closure_output_ty(ctx, closure_ty)?);
            let out_item = option_payload_scalar_item(ctx, out_ty)?;
            (
                AdapterKind::FilterMap,
                out_item,
                Some((closure_ty, off(idx))),
            )
        }
        AdapterTag::TakeWhile => {
            // `.take_while(p)`: `TakeWhile<I, P> { iter, flag, predicate }`. The
            // predicate takes `&Self::Item` and returns `bool` (identical shape to a
            // Filter predicate); output == input. The `flag` field is std's done
            // flag: the drive reads it before pulling and sets it where `p` stops.
            if inner.reversed {
                return Err(
                    "take_while over a reversed (below-rev) chain is not modeled".to_owned(),
                );
            }
            // A 2-tuple item is materialized for the `&Self::Item` predicate in the
            // drive (build_tuple_item_arg); a non-register-pair tuple fails closed
            // there. Output == input, so the tuple flows on unchanged.
            let idx = field_index_by_name("predicate")
                .ok_or_else(|| "TakeWhile has no `predicate` field".to_owned())?;
            let flag_idx = field_index_by_name("flag")
                .ok_or_else(|| "TakeWhile has no `flag` field".to_owned())?;
            let closure_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, idx)?);
            let ty::Closure(..) = closure_ty.kind() else {
                return Err("take_while payload is not a closure".to_owned());
            };
            if !is_zero_sized_ty(ctx.tcx, closure_ty) {
                closure_memory_layout(ctx.tcx, closure_ty)?;
            }
            (
                AdapterKind::TakeWhile {
                    flag_off: off(flag_idx),
                },
                input.clone(),
                Some((closure_ty, off(idx))),
            )
        }
        AdapterTag::SkipWhile => {
            // `.skip_while(p)`: `SkipWhile<I, P> { iter, flag, predicate }`. STATEFUL
            // (unlike TakeWhile): the `flag` field IS read — it records "done
            // skipping" ACROSS elements, so it must be memory-backed in the chain
            // slot. Predicate `&Self::Item -> bool` (same shape as Filter/TakeWhile);
            // output == input. A 2-tuple item is materialized in the drive.
            if inner.reversed {
                return Err(
                    "skip_while over a reversed (below-rev) chain is not modeled".to_owned(),
                );
            }
            let p_idx = field_index_by_name("predicate")
                .ok_or_else(|| "SkipWhile has no `predicate` field".to_owned())?;
            let flag_idx = field_index_by_name("flag")
                .ok_or_else(|| "SkipWhile has no `flag` field".to_owned())?;
            let closure_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, p_idx)?);
            let ty::Closure(..) = closure_ty.kind() else {
                return Err("skip_while payload is not a closure".to_owned());
            };
            if !is_zero_sized_ty(ctx.tcx, closure_ty) {
                closure_memory_layout(ctx.tcx, closure_ty)?;
            }
            (
                AdapterKind::SkipWhile {
                    flag_off: off(flag_idx),
                },
                input.clone(),
                Some((closure_ty, off(p_idx))),
            )
        }
        AdapterTag::Scan => {
            // `.scan(init, f)`: `Scan<I, St, F> { iter, state, f }`. The closure
            // takes `(&mut state, Self::Item)` and returns `Option<U>`. `None`
            // terminates; `Some(u)` yields `u`.
            if inner.reversed {
                return Err("scan over a reversed (below-rev) chain is not modeled".to_owned());
            }
            // A 2-tuple item is materialized for the BY-VALUE item arg in the drive
            // (build_tuple_item_arg); a non-register-pair tuple fails closed there.
            // The output is the Option payload scalar (below), never a tuple.
            let f_idx =
                field_index_by_name("f").ok_or_else(|| "Scan has no `f` field".to_owned())?;
            let state_idx = field_index_by_name("state")
                .ok_or_else(|| "Scan has no `state` field".to_owned())?;
            let closure_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, f_idx)?);
            let ty::Closure(..) = closure_ty.kind() else {
                return Err("scan payload is not a closure".to_owned());
            };
            if !is_zero_sized_ty(ctx.tcx, closure_ty) {
                closure_memory_layout(ctx.tcx, closure_ty)?;
            }
            let out_ty = ctx.monomorphize_ty(closure_output_ty(ctx, closure_ty)?);
            let out_item = option_payload_scalar_item(ctx, out_ty)?;
            (
                AdapterKind::Scan {
                    state_off: off(state_idx),
                },
                out_item,
                Some((closure_ty, off(f_idx))),
            )
        }
        AdapterTag::MapWhile => {
            // `.map_while(f)`: `MapWhile<I, P> { iter, predicate }`. Despite the
            // field name, `predicate` takes `Self::Item` BY VALUE and returns
            // `Option<U>` (like filter_map's `f`); a `None` TERMINATES the iterator
            // (like take_while), not skip. STATELESS: std's `MapWhile` has no
            // done flag.
            if inner.reversed {
                return Err("map_while over a reversed (below-rev) chain is not modeled".to_owned());
            }
            // A 2-tuple item is materialized for the BY-VALUE closure arg in the
            // drive (build_tuple_item_arg); a non-register-pair tuple fails closed
            // there. The output is the Option payload scalar (below), never a tuple.
            let idx = field_index_by_name("predicate")
                .ok_or_else(|| "MapWhile has no `predicate` field".to_owned())?;
            let closure_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, idx)?);
            let ty::Closure(..) = closure_ty.kind() else {
                return Err("map_while payload is not a closure".to_owned());
            };
            if !is_zero_sized_ty(ctx.tcx, closure_ty) {
                closure_memory_layout(ctx.tcx, closure_ty)?;
            }
            let out_ty = ctx.monomorphize_ty(closure_output_ty(ctx, closure_ty)?);
            let out_item = option_payload_scalar_item(ctx, out_ty)?;
            (
                AdapterKind::MapWhile,
                out_item,
                Some((closure_ty, off(idx))),
            )
        }
        AdapterTag::Inspect => {
            // `.inspect(f)`: `Inspect<I, F> { iter, f }`. The closure takes
            // `&Self::Item` and returns `()` (called for its side effect only); the
            // item is passed through UNCHANGED, so output == input.
            if inner.reversed {
                return Err("inspect over a reversed (below-rev) chain is not modeled".to_owned());
            }
            // A 2-tuple item is materialized for the `&Self::Item` closure in the
            // drive (build_tuple_item_arg); a non-register-pair tuple fails closed
            // there. Output == input (transparent pass-through).
            let idx =
                field_index_by_name("f").ok_or_else(|| "Inspect has no `f` field".to_owned())?;
            let closure_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, idx)?);
            let ty::Closure(..) = closure_ty.kind() else {
                return Err("inspect payload is not a closure".to_owned());
            };
            if !is_zero_sized_ty(ctx.tcx, closure_ty) {
                closure_memory_layout(ctx.tcx, closure_ty)?;
            }
            (
                AdapterKind::Inspect,
                input.clone(),
                Some((closure_ty, off(idx))),
            )
        }
        AdapterTag::Rev => unreachable!("rev handled above"),
    };

    let item = output.clone();
    let (closure_ty_val, closure_off) = match closure_ty {
        Some((cty, coff)) => (cty, coff),
        // A unit placeholder closure type for non-closure adapters (never called).
        None => (ctx.tcx.types.unit, 0),
    };
    let mut adapters = inner.adapters;
    adapters.push((
        ChainAdapter {
            kind,
            closure_ty: closure_ty_val,
            input,
            output,
        },
        closure_off,
    ));
    Ok(Some(IterChain {
        source: inner.source,
        source_offset: inner.source_offset,
        adapters,
        item,
        reversed: inner.reversed,
        rev_clamp: inner.rev_clamp,
        owned_buffer: inner.owned_buffer,
    }))
}

/// How rustc encodes which variant an `Option<T>` value holds, relative to the
/// `Option`'s own base address. Derived from `layout_of(Option<T>)`, so it is
/// exact for both encodings an iterator-state `Option` takes: a Direct tag word
/// beside the payload (`Option<Range<u32>>`), and a niche inside the payload
/// (`Option<slice::Iter<T>>`, whose `NonNull` cursor is null for `None`).
#[derive(Clone, Debug)]
struct OptionTagLayout {
    /// The tag (Direct) or niche field: offset within the `Option`, in-memory
    /// type and encoding.
    tag: MemoryEnumTag,
    some_variant: VariantIdx,
    none_variant: VariantIdx,
    /// Byte offset of the `Some` payload within the `Option`.
    some_payload_off: u64,
    /// The `Option` ADT, for its variants' discriminant values.
    option_did: DefId,
}

/// [`OptionTagLayout`] for `option_ty`, from rustc's own layout. `Err` for a
/// type that is not a two-variant `Option` with a tag or niche (an `Option`
/// whose `Some` is uninhabited has a single-variant layout and no tag).
fn option_tag_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    option_ty: Ty<'tcx>,
) -> Result<OptionTagLayout, String> {
    use rustc_abi::{TagEncoding, Variants};
    let (some_variant, none_variant, some_payload_off, _) =
        option_some_none_variants(tcx, option_ty)?;
    let option_did = option_did(tcx, option_ty)?;
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(option_ty))
        .map_err(|e| format!("Option layout_of({option_ty:?}) failed: {e:?}"))?;
    let Variants::Multiple {
        tag,
        tag_encoding,
        tag_field,
        ..
    } = layout.layout.variants()
    else {
        return Err(format!("{option_ty:?} has no variant tag in its layout"));
    };
    let encoding = match tag_encoding {
        TagEncoding::Direct => MemoryTagEncoding::Direct,
        TagEncoding::Niche {
            untagged_variant,
            niche_variants,
            niche_start,
        } => MemoryTagEncoding::Niche {
            untagged_variant: *untagged_variant,
            niche_variants_start: niche_variants.start,
            niche_variants_end: niche_variants.last,
            niche_start: *niche_start,
        },
    };
    Ok(OptionTagLayout {
        tag: MemoryEnumTag {
            offset: layout.fields.offset(tag_field.as_usize()).bytes(),
            ty: scalar_primitive_trust_ir_ty(tcx, tag)?,
            encoding,
        },
        some_variant,
        none_variant,
        some_payload_off,
        option_did,
    })
}

/// Whether the `Option` whose tag (or niche) field sits at `tag_addr` holds
/// `Some`, as a `Bool`. A Direct tag is compared with `Some`'s discriminant; a
/// niche field is decoded with rustc's niche formula
/// ([`lower_niche_discriminant_decode`]) and compared with `Some`'s variant.
fn emit_option_is_some_at(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    tag_addr: ValueId,
    layout: &OptionTagLayout,
) -> Result<ValueId, String> {
    let tag = &layout.tag;
    let loaded = emit_typed_load(ctx, block, tag_addr, tag.ty.clone());
    let (discr, cmp_ty, some) = match &tag.encoding {
        MemoryTagEncoding::Direct => {
            if !tag.ty.is_integer() {
                return Err(format!("Option tag type {:?} is not an integer", tag.ty));
            }
            let some = adt_discriminant_value(ctx.tcx, layout.option_did, layout.some_variant)?;
            (loaded, tag.ty.clone(), some)
        }
        MemoryTagEncoding::Niche {
            untagged_variant,
            niche_variants_start,
            niche_variants_end,
            niche_start,
        } => {
            let discr = lower_niche_discriminant_decode(
                ctx,
                block,
                loaded,
                &tag.ty,
                &TrustIrTy::I64,
                *untagged_variant,
                *niche_variants_start,
                *niche_variants_end,
                *niche_start,
            )?;
            (
                discr,
                TrustIrTy::I64,
                i128::from(layout.some_variant.as_u32()),
            )
        }
    };
    let some = emit_typed_const(ctx, block, cmp_ty.clone(), some);
    let is_some = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: cmp_ty,
            lhs: discr,
            rhs: some,
        })
        .with_result(is_some),
    );
    Ok(is_some)
}

/// Write the tag that makes the `Option` at `option_addr` hold `Some`
/// (`some == true`) or `None`. A Direct tag stores the variant's discriminant.
/// A niche `Option` stores nothing for its untagged variant (a valid payload
/// already encodes it) and refuses to synthesize a reserved niche value.
fn emit_option_tag_store(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    option_addr: ValueId,
    layout: &OptionTagLayout,
    some: bool,
) -> Result<(), String> {
    let variant = if some {
        layout.some_variant
    } else {
        layout.none_variant
    };
    match &layout.tag.encoding {
        MemoryTagEncoding::Direct => {
            let discr = adt_discriminant_value(ctx.tcx, layout.option_did, variant)?;
            let value = emit_typed_const(ctx, block, layout.tag.ty.clone(), discr);
            let addr = iter_field_addr(ctx, block, option_addr, layout.tag.offset);
            emit_typed_store(block, addr, layout.tag.ty.clone(), value);
            Ok(())
        }
        MemoryTagEncoding::Niche {
            untagged_variant, ..
        } if *untagged_variant == variant => Ok(()),
        MemoryTagEncoding::Niche { .. } => {
            Err("writing a niche-encoded Option's reserved variant value is not modeled".to_owned())
        }
    }
}

/// The byte offset of the `Some` payload within an `Option<sub>` whose `sub`
/// (a `Range` or `slice::Iter`) iterator state a `Concat` drives directly: the
/// `Some` field's offset for a Direct-tagged `Option<Range>`, 0 for a
/// niche-encoded one (`Option<slice::Iter>`, whose `Some` payload is the whole
/// value). An `Option` with no memory layout fails closed.
fn option_direct_payload_offset<'tcx>(
    tcx: TyCtxt<'tcx>,
    option_ty: Ty<'tcx>,
) -> Result<u64, String> {
    let Some(layout) = memory_aggregate_layout_shared(tcx, option_ty)? else {
        return Err("chain() sub-source Option has no memory layout".to_owned());
    };
    match &layout.tag {
        // Direct-tagged `Option<Range>`: the `Some` payload sits at its own field
        // offset (a separate discriminant precedes/follows it).
        Some(tag) if matches!(tag.encoding, MemoryTagEncoding::Direct) => {
            let (_, _, some_off, _) = option_some_none_variants(tcx, option_ty)?;
            Ok(some_off)
        }
        // NICHE-encoded `Option<T>` (e.g. `Option<slice::Iter>`: the iterator's
        // `NonNull` ptr IS the niche, so `None` = a null ptr and there is no
        // separate discriminant). `Some(T)` occupies `T`'s layout at offset 0, so
        // the payload starts at 0. (For an `Option`, a `None`/niche tag can only be
        // this pointer-niche case.)
        _ => Ok(0),
    }
}

/// The [`OptionNoneTest`] of the `Option<_>` (`option_ty`) a `Chain` holds at
/// `field_offset`, from rustc's layout: the tag's stored discriminant of `None`
/// (Direct), or the niche value rustc assigns `None` (Niche). A tag wider than
/// 64 bits, or a `None` the layout does not encode in its tag field, fails
/// closed.
fn chain_half_none_test<'tcx>(
    tcx: TyCtxt<'tcx>,
    option_ty: Ty<'tcx>,
    field_offset: u64,
) -> Result<OptionNoneTest, String> {
    let Some(layout) = memory_aggregate_layout_shared(tcx, option_ty)? else {
        return Err("chain() sub-source Option has no memory layout".to_owned());
    };
    let Some(tag) = &layout.tag else {
        return Err("chain() sub-source Option has no tag or niche field".to_owned());
    };
    let width = match &tag.ty {
        TrustIrTy::Ptr
        | TrustIrTy::PtrConst(_)
        | TrustIrTy::PtrMut(_)
        | TrustIrTy::Ref(_)
        | TrustIrTy::RefMut(_) => 64,
        other => match other.bit_width() {
            Some(width) if width <= 64 && other.is_integer() => width,
            _ => {
                return Err(format!(
                    "chain() sub-source Option tag {other:?} is not an integer of at most \
                     64 bits or a pointer"
                ));
            }
        },
    };
    let (_, none_variant, _, _) = option_some_none_variants(tcx, option_ty)?;
    let none_raw: u128 = match &tag.encoding {
        // rustc stores the variant's discriminant value in a Direct tag.
        MemoryTagEncoding::Direct => {
            adt_discriminant_value(tcx, option_did(tcx, option_ty)?, none_variant)? as u128
        }
        // rustc's niche value of a niche variant `v`:
        // `niche_start + (v - niche_variants.start)`, wrapping at the field width.
        MemoryTagEncoding::Niche {
            untagged_variant,
            niche_variants_start,
            niche_variants_end,
            niche_start,
        } => {
            if none_variant == *untagged_variant
                || none_variant < *niche_variants_start
                || none_variant > *niche_variants_end
            {
                return Err(
                    "chain() sub-source Option's None is not a niche value of its tag field"
                        .to_owned(),
                );
            }
            niche_start.wrapping_add(u128::from(
                none_variant.as_u32() - niche_variants_start.as_u32(),
            ))
        }
    };
    let mask = if width == 64 {
        u128::from(u64::MAX)
    } else {
        (1u128 << width) - 1
    };
    Ok(OptionNoneTest {
        offset: field_offset + tag.offset,
        ty: tag.ty.clone(),
        none_bits: (none_raw & mask) as u64,
    })
}

/// Whether the `Chain` half `test` describes is `Some`: the tag / niche field
/// at `addr` (its address) differs from the `None` pattern. A `Bool`.
fn emit_chain_half_is_some(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    addr: ValueId,
    test: &OptionNoneTest,
) -> ValueId {
    let loaded = emit_typed_load(ctx, block, addr, test.ty.clone());
    let bits = match &test.ty {
        TrustIrTy::Ptr
        | TrustIrTy::PtrConst(_)
        | TrustIrTy::PtrMut(_)
        | TrustIrTy::Ref(_)
        | TrustIrTy::RefMut(_) => emit_ptr_to_int(ctx, block, loaded),
        TrustIrTy::I64 | TrustIrTy::U64 => coerce_to_i64(ctx, block, loaded),
        narrow => emit_extend_to_i64(ctx, block, narrow, false, loaded),
    };
    let none = emit_i64_const(ctx, block, i128::from(test.none_bits));
    emit_i64_icmp(ctx, block, ICmpOp::Ne, bits, none)
}

/// Resolve a `Chain<A, B>` (`a.chain(b)`) into a two-source `Concat` chain. Both
/// `A` and `B` must be bare `Range` or pointer-cursor `slice::Iter` sources (no
/// adapters below the chain) yielding the SAME item shape. Each half's payload
/// offset comes from its `Option`'s layout (`option_direct_payload_offset`) and
/// its `None` test from the same layout (`chain_half_none_test`). Anything else
/// (an adapter, reversed or owning sub-source, another source kind, mismatched
/// items) fails closed.
fn resolve_chain_concat<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
    args: crate::fn_items::GenericArgsRef<'tcx>,
) -> Result<Option<IterChain<'tcx>>, String> {
    let a_ty = ctx.monomorphize_ty(args.type_at(0));
    let b_ty = ctx.monomorphize_ty(args.type_at(1));
    let Some(a_chain) = resolve_iter_chain(ctx, a_ty)? else {
        return Ok(None);
    };
    let Some(b_chain) = resolve_iter_chain(ctx, b_ty)? else {
        return Ok(None);
    };
    // Only a BARE source on each side (no adapters, not reversed, not itself a
    // concat) is modeled — composing the per-element adapter logic of two distinct
    // sub-chains is out of scope (fail closed). The offsets below place each
    // sub-source's state at its `Option` payload, so a sub-source whose cursor does
    // not start its own state (`source_offset != 0`) is refused too. A `Concat`
    // carries no `owned_buffer`, so an owning sub-source is refused as well.
    if !a_chain.adapters.is_empty()
        || !b_chain.adapters.is_empty()
        || a_chain.reversed
        || b_chain.reversed
        || a_chain.source_offset != 0
        || b_chain.source_offset != 0
        || a_chain.owned_buffer.is_some()
        || b_chain.owned_buffer.is_some()
    {
        return Err("chain() over an adapter/reversed sub-source is not modeled".to_owned());
    }
    // Both sub-sources must yield the same item representation (same ir type + same
    // deref shape), else their elements would be threaded differently downstream.
    if a_chain.item.ir_ty != b_chain.item.ir_ty
        || a_chain.item.deref_elem_ir != b_chain.item.deref_elem_ir
        || a_chain.item.tuple.is_some()
        || b_chain.item.tuple.is_some()
    {
        return Err(
            "chain() over sub-sources with differing element handling is not modeled".to_owned(),
        );
    }
    // Only bare `Range` and `slice::Iter` sub-sources are modeled (their per-element
    // `next` state machines are `emit_range_next_guarded` / `emit_slice_next_guarded`
    // in the `Concat` arm). A `Range` wraps in a Direct-tagged `Option<Range>`; a
    // `slice::Iter` in a NICHE-encoded `Option<slice::Iter>` (its `NonNull` ptr is the
    // niche, `None` = null); `option_tag_layout` describes both. Anything else
    // (RangeInclusive / a nested Zip or Chain / an adapter sub-source) fails closed.
    let sub_ok = |s: &ChainSource<'_>| {
        matches!(
            s,
            ChainSource::Range { .. }
                | ChainSource::Slice {
                    repr: SliceCursorRepr::Pointers,
                    ..
                }
        )
    };
    if !sub_ok(&a_chain.source) || !sub_ok(&b_chain.source) {
        return Err("chain() is only modeled for bare Range / slice::Iter sub-sources".to_owned());
    }

    // The `Chain<A, B>` layout: field 0 = `Option<A>`, field 1 = `Option<B>`. Each
    // sub-source's iterator state sits at `option_field_offset + some_payload_off`,
    // and is live only while that `Option`'s tag / niche says `Some`.
    let layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("chain() layout_of failed: {e:?}"))?;
    let rustc_abi::FieldsShape::Arbitrary { .. } = layout.fields else {
        return Err("chain() layout is not a field struct".to_owned());
    };
    let opt_a_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, 0)?);
    let opt_b_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, ty, 1)?);
    let first_offset =
        layout.fields.offset(0).bytes() + option_direct_payload_offset(ctx.tcx, opt_a_ty)?;
    let second_offset =
        layout.fields.offset(1).bytes() + option_direct_payload_offset(ctx.tcx, opt_b_ty)?;
    // Each half's `None` test: a drive reads it before the half's payload.
    let first_none = chain_half_none_test(ctx.tcx, opt_a_ty, layout.fields.offset(0).bytes())?;
    let second_none = chain_half_none_test(ctx.tcx, opt_b_ty, layout.fields.offset(1).bytes())?;

    let item = a_chain.item.clone();
    Ok(Some(IterChain {
        source: ChainSource::Concat {
            first: Box::new(a_chain.source),
            first_offset,
            first_none,
            second: Box::new(b_chain.source),
            second_offset,
            second_none,
        },
        source_offset: 0,
        adapters: Vec::new(),
        item,
        reversed: false,
        rev_clamp: None,
        owned_buffer: None,
    }))
}

/// Whether `Zip<a_ty, b_ty>` is core's GENERAL `ZipImpl` because a `Range`
/// side is wider than `usize` on a 32-bit target.
///
/// core implements `TrustedRandomAccess` for `Range<u64>` / `Range<i64>` only
/// under `target_pointer_width = "64"` (a Range wider than `usize` has no
/// in-`usize` length). On a 32-bit target such a `Zip` is the general form —
/// its `new` leaves `index`/`len` at 0 and its `next` advances both
/// sub-iterators — so the bridge's index/len cursor model does not describe it,
/// and its real `next` never reaches `__iterator_get_unchecked`. A 64-bit
/// target always answers `false` (its wider-Range refusal is in `resolve_zip`).
fn zip_is_general_on_narrow_target<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    a_ty: Ty<'tcx>,
    b_ty: Ty<'tcx>,
) -> Result<bool, String> {
    zip_sides_general_on_narrow_target(
        ctx.tcx,
        ctx.monomorphize_ty(a_ty),
        ctx.monomorphize_ty(b_ty),
    )
}

/// [`zip_is_general_on_narrow_target`] over already-monomorphic side types.
fn zip_sides_general_on_narrow_target<'tcx>(
    tcx: TyCtxt<'tcx>,
    a_ty: Ty<'tcx>,
    b_ty: Ty<'tcx>,
) -> Result<bool, String> {
    let ptr_bytes = tcx.data_layout.pointer_size().bytes();
    if ptr_bytes >= 8 {
        return Ok(false);
    }
    for sub_ty in [a_ty, b_ty] {
        if let Some(index_ty) = range_index_ty(tcx, sub_ty) {
            let (elem_size, _) = element_layout_size_align(tcx, index_ty)?;
            if elem_size > ptr_bytes {
                return Ok(true);
            }
        }
    }
    Ok(false)
}

/// Whether `ty` is core's `RangeFrom<T>` (`start..`). The bridge models no
/// `RangeFrom` iterator: a chain over one takes core's real bodies
/// ([`real_body_iterator_receiver`]).
fn is_std_range_from_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    matches!(ty.kind(), ty::Adt(adt, _)
        if Some(adt.did()) == tcx.lang_items().range_from_struct()
            && std_def_is_interceptable(tcx, adt.did()))
}

/// Whether `ty` is one of core's generator sources `Repeat`, `RepeatWith`,
/// `FromFn` or `Successors`. The bridge models none of them (their items come
/// from a clone or a closure call, not a cursor), so a chain over one takes
/// core's real bodies ([`real_body_iterator_receiver`]) like a `RangeFrom`.
///
/// Before they were, a generic helper's `it.take(n).sum()` called
/// `<Take<Repeat<_>> as SpecTake>::spec_fold` directly at `-O2`, a body the
/// bridge had replaced with a trap stub (refused since as
/// `[TCG-ITER-STUB-REACHABLE]`), and every by-name terminal over them was
/// refused as `[TCG-ITER-UNMODELED]`.
fn is_std_generator_source_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, _) = ty.kind() else {
        return false;
    };
    let did = adt.did();
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !is_real_std_crate_def(tcx, did) || !std_def_is_interceptable(tcx, did) {
        return false;
    }
    let segments: Vec<String> = tcx
        .def_path(did)
        .data
        .iter()
        .filter_map(|d| d.data.get_opt_name().map(|n| n.to_string()))
        .collect();
    matches!(
        segments.join("::").as_str(),
        "iter::sources::repeat::Repeat"
            | "iter::sources::repeat_with::RepeatWith"
            | "iter::sources::from_fn::FromFn"
            | "iter::sources::successors::Successors"
    )
}

/// Whether monomorphic type `ty` mentions, anywhere among its component types,
/// an iterator source whose chains take core's real bodies: a `RangeFrom`, a
/// generator source ([`is_std_generator_source_ty`]), a slice stride iterator in
/// std's own representation ([`slice_stride_iter_state_is_std`]: std's `count`/
/// `size_hint`/`nth`/`next_back`/`try_fold`/`Zip` bodies over it are correct and
/// LIVE), an aggregate-valued Map, or a `Zip` that
/// [`zip_is_general_on_narrow_target`] answers `true` for. A layout query that
/// fails answers `true`: the caller only uses a `true` to keep a body on its
/// fail-closed real-lowering path.
fn ty_mentions_real_body_iterator_source<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    ty.walk().any(|arg| {
        let Some(t) = arg.as_type() else {
            return false;
        };
        if iterator_aggregate_fallback::map_requires_real_body(tcx, t)
            || iterator_aggregate_fallback::iterator_callback_takes_real_body(tcx, t)
        {
            return true;
        }
        if is_std_range_from_ty(tcx, t)
            || is_std_generator_source_ty(tcx, t)
            || slice_stride_iter_state_is_std(tcx, t)
        {
            return true;
        }
        let ty::Adt(adt, args) = t.kind() else {
            return false;
        };
        is_zip_adapter(tcx, adt.did())
            && args.len() >= 2
            && zip_sides_general_on_narrow_target(tcx, args.type_at(0), args.type_at(1))
                .unwrap_or(true)
    })
}

/// Whether iterator adapter type `ty` is, or wraps through adapter / `Chain` /
/// `Zip` type parameters, a `Zip` that `zip_is_general_on_narrow_target`
/// answers `true` for. Always `false` on a 64-bit target.
fn contains_general_zip_on_narrow_target<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    if ctx.tcx.data_layout.pointer_size().bytes() >= 8 {
        return Ok(false);
    }
    let ty = ctx.monomorphize_ty(ty);
    let ty::Adt(adt, args) = ty.kind() else {
        return Ok(false);
    };
    let did = adt.did();
    let is_zip = is_zip_adapter(ctx.tcx, did);
    if !is_zip && adapter_kind_of(ctx.tcx, did).is_none() && !is_chain_adapter(ctx.tcx, did) {
        return Ok(false);
    }
    if is_zip
        && zip_is_general_on_narrow_target(
            ctx,
            ctx.monomorphize_ty(args.type_at(0)),
            ctx.monomorphize_ty(args.type_at(1)),
        )?
    {
        return Ok(true);
    }
    for inner in args.types() {
        if contains_general_zip_on_narrow_target(ctx, inner)? {
            return Ok(true);
        }
    }
    Ok(false)
}

/// Whether iterator type `ty` is, or wraps through adapter / `Chain` / `Zip`
/// type parameters, a source whose chains take core's real bodies instead of the
/// bridge's chain driver: a `RangeFrom` or a generator source
/// ([`is_std_generator_source_ty`]) (neither modeled), a slice stride iterator in
/// std's own representation ([`slice_stride_iter_state_is_std`]: at most its
/// constructor, `next` and `remainder` are intercepted, over std's own state, so
/// std's terminal and adapter bodies are correct over it), an aggregate-valued
/// Map, or a `Zip` that
/// [`zip_is_general_on_narrow_target`] answers `true` for.
fn iterator_spine_has_real_body_source<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    let ty = ctx.monomorphize_ty(ty);
    if iterator_aggregate_fallback::mentions_aggregate_map(ctx.tcx, ty) {
        return Ok(true);
    }
    if is_std_range_from_ty(ctx.tcx, ty)
        || is_std_generator_source_ty(ctx.tcx, ty)
        || slice_stride_iter_state_is_std(ctx.tcx, ty)
    {
        return Ok(true);
    }
    let ty::Adt(adt, args) = ty.kind() else {
        return Ok(false);
    };
    let did = adt.did();
    let is_zip = is_zip_adapter(ctx.tcx, did);
    if !is_zip && adapter_kind_of(ctx.tcx, did).is_none() && !is_chain_adapter(ctx.tcx, did) {
        return Ok(false);
    }
    if is_zip && zip_is_general_on_narrow_target(ctx, args.type_at(0), args.type_at(1))? {
        return Ok(true);
    }
    for inner in args.types() {
        if iterator_spine_has_real_body_source(ctx, inner)? {
            return Ok(true);
        }
    }
    Ok(false)
}

/// Whether an iterator terminal's receiver or actual callback takes core's
/// real bodies. The receiver uses [`iterator_spine_has_real_body_source`];
/// callback captures retain an aggregate mapper after std peels its Map
/// (`iterator_aggregate_fallback::iterator_callback_takes_real_body`, the
/// predicate the dead-body exclusion uses too).
///
/// The bridge models neither source, so a `sum`/`fold`/`count`/`for_each`/
/// `try_fold` over such a chain is not intercepted: each adapter's `fold`
/// forwards to its inner `fold` (or, for `Take`/`Skip`, to `try_fold`), the
/// general `Zip`'s to `SpecFold::spec_fold`, a `while let Some(x) =
/// ZipImpl::next(&mut self)` loop over the sub-iterators' own `next`, and a
/// `RangeFrom`'s to the default loop over `RangeFrom::next`.
/// `is_dead_std_iterator_reduction_body` never traps a body whose impl self
/// type or instance type args mention such a source, so each of those is
/// lowered for real or fails the compile closed. The exclusion is keyed on
/// types only: a nested std helper whose generics omit the source (e.g. the
/// closure of `Take::try_fold::check`) is not covered, and if it failed to
/// lower it would become a trap stub reachable at run time, not a refusal.
fn real_body_iterator_receiver<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<bool, String> {
    let Some(arg) = call.args.first() else {
        return Ok(false);
    };
    for argument in call.args.iter().skip(1) {
        let callback = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &argument.node)?);
        if iterator_aggregate_fallback::iterator_callback_takes_real_body(ctx.tcx, callback) {
            return Ok(true);
        }
    }
    let receiver_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &arg.node)?);
    let iter_ty = match receiver_ty.kind() {
        ty::Ref(_, inner, _) => ctx.monomorphize_ty(*inner),
        _ => receiver_ty,
    };
    iterator_spine_has_real_body_source(ctx, iter_ty)
}

/// Resolve `a.zip(b)` over two `slice::Iter` / 64-bit `Range` sub-sources into a
/// `ChainSource::Zip`. `Zip<A, B>` (TRA specialization) is laid out
/// `{ a: A, b: B, index: usize, len: usize }` (field-indexed offsets — the
/// layout may memory-reorder the fields); std's specialized `Zip::next` reads
/// element `index` off each sub-iterator's ORIGINAL state (it does NOT advance
/// them), so we record each side's state offset, element stride/kind, and the
/// `index`/`len` cursor offsets. Adapter / nested-Zip / RangeInclusive /
/// narrow-Range sub-sources ride a different `next` state machine — fail closed.
fn resolve_zip<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
    args: crate::fn_items::GenericArgsRef<'tcx>,
) -> Result<Option<IterChain<'tcx>>, String> {
    let a_ty = ctx.monomorphize_ty(args.type_at(0));
    let b_ty = ctx.monomorphize_ty(args.type_at(1));
    // A `Zip` that is the GENERAL `ZipImpl` on this target is not modeled: the
    // real `ZipImpl` bodies run (see `zip_is_general_on_narrow_target`).
    if zip_is_general_on_narrow_target(ctx, a_ty, b_ty)? {
        return Ok(None);
    }
    // Nor is a `Zip` over a slice stride iterator in std's own representation
    // (anywhere in either side's type; `slice_stride_iter_state_is_std`), so std's real
    // `Zip` bodies (`ZipImpl::new`/`next` and the side's `size` /
    // `__iterator_get_unchecked`) read it correctly; `ty_mentions_real_body_iterator_source`
    // keeps those bodies out of the dead-body trap stubs.
    if [a_ty, b_ty].iter().any(|side| {
        side.walk()
            .filter_map(|arg| arg.as_type())
            .any(|t| slice_stride_iter_state_is_std(ctx.tcx, t))
    }) {
        return Ok(None);
    }
    let side_of = |sub_ty: Ty<'tcx>, offset: u64| -> Result<ZipSide<'tcx>, String> {
        if let Some(elem_ty) = slice_iter_element_ty(ctx.tcx, sub_ty) {
            let elem_ty = ctx.monomorphize_ty(elem_ty);
            let elem_ir = rust_ty_to_trust_ir_ty(ctx.tcx, elem_ty)?;
            let (elem_size, _) = element_layout_size_align(ctx.tcx, elem_ty)?;
            if elem_size == 0 {
                return Err("zip() over a zero-sized element is not modeled".to_owned());
            }
            return Ok(ZipSide {
                offset,
                elem_size,
                elem_ir,
                elem_ty,
                kind: ZipSideKind::SlicePtr,
            });
        }
        if let Some(index_ty) = range_index_ty(ctx.tcx, sub_ty) {
            let index_ty = ctx.monomorphize_ty(index_ty);
            let elem_ir = rust_ty_to_trust_ir_ty(ctx.tcx, index_ty)?;
            let (elem_size, _) = element_layout_size_align(ctx.tcx, index_ty)?;
            // Pointer-width indices only: the drive computes `start + i` as ONE
            // add in the index's own width against the `usize` cursor
            // (`zip_range_word_ty`). A narrower Range would need trunc/extend
            // plumbing — fail closed rather than risk a wrong-width add. (A
            // Range WIDER than `usize` never reaches here: it is not
            // TrustedRandomAccess, see the 32-bit rule in `resolve_zip`.)
            let ptr_bytes = ctx.tcx.data_layout.pointer_size().bytes();
            if elem_size != 8 && !(ptr_bytes == 4 && elem_size == 4) {
                return Err("zip() over a non-64-bit Range sub-source is not modeled".to_owned());
            }
            return Ok(ZipSide {
                offset,
                elem_size,
                elem_ir,
                elem_ty: index_ty,
                kind: ZipSideKind::RangeStart,
            });
        }
        Err("zip() is only modeled over slice::Iter / 64-bit Range sub-sources".to_owned())
    };

    // `Zip<A, B>` layout: field 0 = a, 1 = b, 2 = index, 3 = len.
    let layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("zip() layout_of failed: {e:?}"))?;
    let rustc_abi::FieldsShape::Arbitrary { .. } = layout.fields else {
        return Err("zip() layout is not a field struct".to_owned());
    };
    if layout.fields.count() != 4 {
        // core's `Zip` always declares `a`, `b`, `index`, `len`; whether it is
        // the `TrustedRandomAccess` form is decided by the side types (both
        // modeled sides above are TRA on this target), not by this count. A
        // different field count is a layout this model does not know.
        return Err("zip() layout is not core's 4-field Zip".to_owned());
    }
    let a = side_of(a_ty, layout.fields.offset(0).bytes())?;
    let b = side_of(b_ty, layout.fields.offset(1).bytes())?;
    let index_offset = layout.fields.offset(2).bytes();
    let len_offset = layout.fields.offset(3).bytes();

    let a_item = zip_side_item(ctx.tcx, &a);
    let b_item = zip_side_item(ctx.tcx, &b);
    let tuple_rust_ty = Ty::new_tup(ctx.tcx, &[a_item.rust_ty, b_item.rust_ty]);
    let item = ChainItem {
        rust_ty: tuple_rust_ty,
        ir_ty: TrustIrTy::Ptr,
        deref_elem_ir: None,
        tuple: Some((Box::new(a_item), Box::new(b_item))),
    };
    Ok(Some(IterChain {
        source: ChainSource::Zip {
            a,
            b,
            index_offset,
            len_offset,
        },
        source_offset: 0,
        adapters: Vec::new(),
        item,
        reversed: false,
        rev_clamp: None,
        owned_buffer: None,
    }))
}

/// The `ChainItem` one `.zip()` side yields: `&T` (pointer rep + `deref_elem_ir`
/// so a downstream `.copied()`/closure deref works) for a slice side; the 64-bit
/// scalar BY VALUE (like `.enumerate()`'s index component) for a Range side.
fn zip_side_item<'tcx>(tcx: TyCtxt<'tcx>, side: &ZipSide<'tcx>) -> ChainItem<'tcx> {
    match side.kind {
        ZipSideKind::SlicePtr => ChainItem {
            rust_ty: Ty::new_imm_ref(tcx, tcx.lifetimes.re_erased, side.elem_ty),
            ir_ty: TrustIrTy::Ptr,
            deref_elem_ir: Some(side.elem_ir.clone()),
            tuple: None,
        },
        ZipSideKind::RangeStart => ChainItem {
            rust_ty: side.elem_ty,
            ir_ty: side.elem_ir.clone(),
            deref_elem_ir: None,
            tuple: None,
        },
    }
}

/// The type of the `idx`-th field of a (single-variant) struct/ADT `ty`.
fn field_ty_of<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, idx: usize) -> Result<Ty<'tcx>, String> {
    let ty::Adt(adt, args) = ty.kind() else {
        return Err(format!("field_ty_of on a non-ADT type {ty:?}"));
    };
    let variant = adt.non_enum_variant();
    let field = variant
        .fields
        .get(FieldIdx::from_usize(idx))
        .ok_or_else(|| format!("field_ty_of: field {idx} out of range for {ty:?}"))?;
    Ok(normalized_adt_field_ty(tcx, field, *args))
}

/// The byte size of the runtime state slot for ANY iterator type we drive — a bare
/// `Range`/`slice::Iter` source OR an adapter chain. This is just the type's layout
/// size, but routed through `monomorphize_ty` for consistency with the offsets the
/// chain components carry. Used by `lower_iter_terminal` to allocate a PRIVATE copy
/// of the iterator state before draining it (so two structurally-identical sources
/// that O3 CSE/GVN folded into ONE slot do not alias their drives — see #111).
fn iter_state_slot_size<'tcx>(ctx: &MirLoweringCtx<'tcx>, ty: Ty<'tcx>) -> Result<u64, String> {
    let ty = ctx.monomorphize_ty(ty);
    let size = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("iterator state layout_of failed: {e:?}"))?
        .size
        .bytes();
    Ok(size)
}

/// #111 — Allocate a FRESH private slot and copy the byte-exact iterator state of
/// `iter_ty` from `orig_slot` into it, returning the fresh slot pointer. The
/// reducing consumers/terminals drain the chain state IN PLACE; at O3 two
/// structurally-identical sources may share ONE slot (CSE/GVN), so draining the
/// shared slot would corrupt the second consumer. Driving over a private copy makes
/// each consumer own its state and leaves the original untouched.
///
/// The copy is straight-line (the state size is a small compile-time constant: 16
/// bytes for a `Range<i64>`, a few more for an adapter chain). It copies EXACTLY
/// `iter_state_slot_size` bytes so it never over-reads `orig_slot` — which for a
/// bare Range source is allocated to its precise layout size (e.g. 2 bytes for a
/// `Range<i8>`). Bulk 8-byte lanes plus a narrowing tail.
fn copy_iter_state_to_private_slot<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    iter_ty: Ty<'tcx>,
    orig_slot: ValueId,
) -> Result<ValueId, String> {
    let state_size = iter_state_slot_size(ctx, iter_ty)?;
    // Allocate the private copy as 8-byte (I64) lanes — identical to how adapter
    // chain slots are allocated in `compute_memory_backed_locals` — so it is
    // 8-aligned and large enough for the whole state.
    let lanes = state_size.div_ceil(8).max(1);
    let copy = ctx.fresh_value();
    let count = emit_i64_const(ctx, block, i128::from(lanes));
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I64,
            count: Some(count),
            align: Some(8),
        })
        .with_result(copy),
    );
    let mut off: u64 = 0;
    let widths: [(u64, TrustIrTy); 4] = [
        (8, TrustIrTy::I64),
        (4, TrustIrTy::I32),
        (2, TrustIrTy::I16),
        (1, TrustIrTy::I8),
    ];
    while off < state_size {
        let remaining = state_size - off;
        let (w, ir) = widths
            .iter()
            .find(|(w, _)| *w <= remaining)
            .cloned()
            .unwrap_or((1, TrustIrTy::I8));
        let src_addr = iter_field_addr(ctx, block, orig_slot, off);
        let v = emit_typed_load(ctx, block, src_addr, ir.clone());
        let dst_addr = iter_field_addr(ctx, block, copy, off);
        emit_typed_store(block, dst_addr, ir, v);
        off += w;
    }
    Ok(copy)
}

/// If `ty` is an iterator-adapter chain (`Map`/`Filter`, possibly nested over a
/// Range / slice source) we fully model, return the byte size of its runtime slot
/// (its layout size). A bare Range / slice::Iter returns `None` here (those are
/// memory-backed through the existing aggregate-layout path). Used to memory-back
/// adapter locals with a raw byte slot.
fn iter_chain_slot_size<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<u64>, String> {
    let ty = ctx.monomorphize_ty(ty);
    // Only adapter (Map/Filter/…/Chain/FlatMap) types get a raw slot here; bare
    // sources use the aggregate-layout path.
    let ty::Adt(adt, _) = ty.kind() else {
        return Ok(None);
    };
    // A BOUNDED `flat_map` shape (`resolve_flatmap_bounded` matches): memory-back
    // it with a raw byte slot sized to its REAL rustc layout — `lower_flatmap_
    // bounded_ctor` writes std's `FlatMap::new` value there (`FlatMapStdLayout`)
    // and every reader, the bridge's driver or a real std body, reads it at
    // rustc's offsets. Checked BEFORE the
    // `adapter_kind_of`/`is_chain_adapter`/`is_zip_adapter` gate below (FlatMap
    // matches none of those). An UNRESOLVED FlatMap (a non-Range side / mismatched
    // `T` / capturing closure / …) returns `None` here — its ctor already falls
    // through to the general path, which is empirically already fail-closed for
    // it (a `Range<T>` FIELD nested inside `FlatMap`/`FlattenCompat`/`Map` has no
    // `memory_aggregate_layout` — the SAME "multi-field struct field" rejection
    // that made even a bare, unintercepted `.flat_map(..)` fail to compile before
    // this feature existed), so leaving it un-memory-backed steals no working case.
    if is_flatmap_adapter(ctx.tcx, adt.did()) {
        if resolve_flatmap_bounded(ctx, ty).is_none() {
            return Ok(None);
        }
        let size = ctx
            .tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
            .map_err(|e| format!("flat_map layout_of failed: {e:?}"))?
            .size
            .bytes();
        return Ok(Some(size));
    }
    if adapter_kind_of(ctx.tcx, adt.did()).is_none()
        && !is_chain_adapter(ctx.tcx, adt.did())
        && !is_zip_adapter(ctx.tcx, adt.did())
    {
        return Ok(None);
    }
    // A `Zip` that is core's GENERAL `ZipImpl` on this target is not modeled
    // (its real `new` / `next` bodies run), nor is any adapter wrapping one
    // (`Take<Zip<..>>`: its real bodies call into that `Zip`). Such a local
    // still needs a slot of its real layout: those bodies take `&mut` of it and
    // its fields are nested iterator aggregates with no scalarized form.
    let general_zip = contains_general_zip_on_narrow_target(ctx, ty)?;
    if !general_zip && resolve_iter_chain(ctx, ty)?.is_none() {
        return Ok(None);
    }
    let size = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("iterator chain layout_of failed: {e:?}"))?
        .size
        .bytes();
    Ok(Some(size))
}

/// Where a closure call site holds ONE argument value, before the callee's
/// convention for it is applied.
#[derive(Clone, Copy, Debug)]
enum ClosureArgSrc {
    /// The value itself: a scalar or thin pointer.
    Scalar(ValueId),
    /// A pointer to the value's own bytes, in rustc's layout (what the iterator
    /// intercepts build: `build_tuple_item_arg`, an element address, a by-value
    /// environment's slot).
    Slot(ValueId),
    /// Field `offset` of a memory-backed tupled-arguments slot of `tuple_size`
    /// bytes (the MIR `Fn*::call*` terminator's argument tuple).
    TupleField {
        slot: ValueId,
        offset: u64,
        tuple_size: u64,
    },
}

/// One argument of a call to a closure BODY (or a function item standing in
/// for one): its Rust type, its index in the callee's own `FnAbi::args`, and
/// where the call site holds it.
#[derive(Clone, Copy, Debug)]
struct ClosureArg<'tcx> {
    ty: Ty<'tcx>,
    abi_arg_index: usize,
    src: ClosureArgSrc,
}

/// The ABI values one [`ClosureArg`] crosses as, with their declared types
/// (the types a hand-built signature — the `Fn`-trait dispatch spread —
/// declares for them).
#[derive(Default)]
struct ClosureArgValues {
    tys: Vec<TrustIrTy>,
    values: Vec<ValueId>,
}

impl ClosureArgValues {
    fn push(&mut self, ty: TrustIrTy, value: ValueId) {
        self.tys.push(ty);
        self.values.push(value);
    }
}

/// THE ONE BUILDER of an argument to a closure body. Every closure call site —
/// the MIR `Fn*::call*` terminator (`lower_closure_call_terminator`), every
/// iterator / sort / option intercept (`closure_body_call_args`, through
/// `emit_closure_call_n` or directly), and the `Fn`-trait dispatch spread over a
/// `dyn Fn*` vtable (`spread_fn_call_tuple_untupled`) — builds each argument
/// here, and asks the SAME plans, in the same order, that the callee's
/// declaration asked (`classify_func_ty`): wasm32's address of an over-aligned
/// copy (`wasm32_indirect_carrier_param`), the indirect argument
/// (`indirect_arg_param_plan`: a fresh copy's address), rustc's two `Pair`
/// scalars (`scalar_pair_param_plan`), wasm32's one-`i32` cast
/// (`small_cast_param_plan`), the one integer of a native narrow `Cast`
/// (`narrow_cast_param_plan`), a `&dyn` pair, the whole slot, or the scalar. So a
/// closure body's declaration and every call of it pass the same number of
/// values of the same types in the same convention — the declaration is global
/// to the callee, and before this builder the hand-built call lists could only
/// agree with it because closure bodies were excluded from the pair lane (and
/// refused where another backend's code reached them).
fn closure_call_arg_values<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    source: RustcFnAbiSource<'tcx>,
    args: Vec<ClosureArg<'tcx>>,
) -> Result<Vec<ClosureArgValues>, String> {
    closure_body_abi::argument_values(ctx, block, source, args)
}

/// Whether a closure BODY takes its environment BY VALUE: its receiver `_1` is
/// the (non-zero-sized) closure itself — an `FnOnce` closure — rather than
/// `&closure` / `&mut closure`. Such a receiver is an ordinary by-value
/// argument at `FnAbi` index 0 and crosses by rustc's own mode for it (a pointer
/// to a copy, two `Pair` scalars, one integer, or one scalar), through the same
/// plans as any other argument.
fn closure_body_env_by_value<'tcx>(tcx: TyCtxt<'tcx>, instance: Instance<'tcx>) -> bool {
    if !matches!(instance.def, ty::InstanceKind::Item(_))
        || !matches!(
            instance
                .ty(tcx, ty::TypingEnv::fully_monomorphized())
                .kind(),
            ty::Closure(..)
        )
    {
        return false;
    }
    let body = tcx.instance_mir(instance.def);
    let Some(recv_local) = body.args_iter().next() else {
        return false;
    };
    let recv_ty = instance.instantiate_mir_and_normalize_erasing_regions(
        tcx,
        ty::TypingEnv::fully_monomorphized(),
        ty::EarlyBinder::bind(tcx, body.local_decls[recv_local].ty),
    );
    matches!(recv_ty.kind(), ty::Closure(..)) && !is_zero_sized_ty(tcx, recv_ty)
}

/// The full argument list of a call to the closure body (or function item)
/// `instance`: its environment when the body declares one (`env` is the
/// environment POINTER a call site holds — the `&closure` value, or a by-value
/// closure's own slot), then each untupled argument. Every value is built by
/// [`closure_call_arg_values`] against `instance`'s own `FnAbi`, so this list
/// and the body's declaration cannot disagree.
fn closure_body_call_args<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    instance: Instance<'tcx>,
    env: Option<ValueId>,
    args: Vec<ClosureArg<'tcx>>,
) -> Result<Vec<ValueId>, String> {
    closure_body_abi::call_args(ctx, block, instance, env, args)
}

/// [`closure_body_call_args`] for a call site that holds each untupled
/// argument as ONE value in the bridge's representation of its type — the
/// value itself for a scalar or thin pointer, the address of its bytes for
/// anything the bridge keeps in memory (what every iterator intercept passes).
/// The types come from `instance`'s own signature, never from the site.
fn closure_body_call_args_from_values<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    instance: Instance<'tcx>,
    env: Option<ValueId>,
    values: Vec<ValueId>,
) -> Result<Vec<ValueId>, String> {
    let instance_ty = instance.ty(ctx.tcx, ty::TypingEnv::fully_monomorphized());
    // (Rust type, FnAbi index) of every untupled parameter, ZSTs included.
    let params: Vec<(Ty<'tcx>, usize)> = match instance_ty.kind() {
        ty::Closure(..) => {
            let sig = ctx
                .tcx
                .instantiate_bound_regions_with_erased(closure_signature(ctx, instance)?);
            let tupled = sig.inputs()[0];
            let ty::Tuple(elems) = tupled.kind() else {
                return Err(format!(
                    "closure signature arguments are not a tuple: {tupled:?}"
                ));
            };
            elems.iter().enumerate().map(|(i, t)| (t, i + 1)).collect()
        }
        ty::FnDef(..) => {
            let sig = ctx
                .tcx
                .instantiate_bound_regions_with_erased(instance_ty.fn_sig(ctx.tcx));
            rust_call_spread::abi_inputs(ctx.tcx, &sig)?
                .into_iter()
                .enumerate()
                .map(|(i, t)| (t, i))
                .collect()
        }
        other => {
            return Err(format!(
                "closure call callee is not a closure or fn item: {other:?}"
            ));
        }
    };
    let params: Vec<(Ty<'tcx>, usize)> = params
        .into_iter()
        .map(|(t, i)| (ctx.monomorphize_ty(t), i))
        .filter(|(t, _)| !is_zero_sized_call_ty(ctx.tcx, *t))
        .collect();
    if params.len() != values.len() {
        return Err(format!(
            "[TCG-ARG-ABI] a call of `{}` passes {} argument value(s) for {} non-zero-sized \
             parameter(s); failing closed",
            ctx.tcx.symbol_name(instance).name,
            values.len(),
            params.len()
        ));
    }
    let mut args = Vec::with_capacity(values.len());
    for ((ty, abi_arg_index), value) in params.into_iter().zip(values) {
        let in_memory = fat_ptr_or_memory_aggregate_layout(ctx.tcx, ty)?.is_some()
            || is_vtable_pair_abi_ref_ty(ctx.tcx, ty);
        args.push(ClosureArg {
            ty,
            abi_arg_index,
            src: if in_memory {
                ClosureArgSrc::Slot(value)
            } else {
                ClosureArgSrc::Scalar(value)
            },
        });
    }
    closure_body_call_args(ctx, block, instance, env, args)
}

/// Resolve the closure-body `Instance` of a closure type for a synthesized loop
/// that does NOT run the closure's drop glue, refusing ([TCG-CLOSURE-DROP]) a
/// closure whose environment needs drop. A drive that runs that glue itself
/// resolves through [`owned_closure_body_instance`].
fn closure_body_instance<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    closure_ty: Ty<'tcx>,
) -> Result<Instance<'tcx>, String> {
    if !matches!(closure_ty.kind(), ty::Closure(..)) {
        return Err("closure_body_instance: not a closure".to_owned());
    }
    // These callers have no environment cleanup; every owner must refuse.
    // for_each/fold with a real cleanup plan use owned_closure_body_instance.
    refuse_unmodeled_closure_drop(ctx, closure_ty)?;
    resolve_closure_body_instance(ctx, closure_ty)
}

/// Resolve the closure-body `Instance` of the closure a drive OWNS, given
/// `planned`, the result of `owned_closure_drop_plan` for this same closure and
/// environment. With a plan, the drive calls rustc's own drop glue for the
/// closure once after its last call and on every unwind edge of its payload
/// calls (`emit_owned_closure_drop`, `owned_closure_cleanup_pad`), as the real
/// callee does, so no destructor is skipped and the admission for an
/// uncleaned environment does not apply. Without a plan that admission still
/// applies; an allocation-only owner is not exempt.
fn owned_closure_body_instance<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    closure_ty: Ty<'tcx>,
    planned: Option<&OwnedClosureDrop>,
) -> Result<Instance<'tcx>, String> {
    match planned {
        Some(_) => resolve_closure_body_instance(ctx, closure_ty),
        None => closure_body_instance(ctx, closure_ty),
    }
}

/// The closure-body `Instance` of a closure type, with no admission check.
fn resolve_closure_body_instance<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    closure_ty: Ty<'tcx>,
) -> Result<Instance<'tcx>, String> {
    let ty::Closure(def_id, args) = closure_ty.kind() else {
        return Err("closure_body_instance: not a closure".to_owned());
    };
    Ok(Instance::expect_resolve(
        ctx.tcx,
        ty::TypingEnv::fully_monomorphized(),
        *def_id,
        *args,
        ctx.tcx.def_span(*def_id),
    ))
}

/// Admit a closure called directly by a synthesized std/collection loop only
/// when its environment owes no drop glue. These loops do not own a normal or
/// unwind cleanup for that environment. This includes allocations released by
/// `Box`, `Vec` or `String`: skipping their release retains resources even with
/// the default allocator. Destructor significance and allocator kind cannot
/// substitute for executing the consumed environment's actual cleanup.
fn refuse_unmodeled_closure_drop<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    closure_ty: Ty<'tcx>,
) -> Result<(), String> {
    if !closure_ty.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized()) {
        return Ok(());
    }
    Err(format!(
        "[TCG-CLOSURE-DROP] rustc_codegen_trust_cg: closure {closure_ty:?} owns a value \
         requiring drop glue, and the intercepted std call that consumes it is lowered \
         as a synthesized loop with no normal or unwind cleanup for that environment; \
         failing closed rather than skipping its destructor or allocation release"
    ))
}

/// Emit `result = closure(env_ptr, arg)` for a single-argument (ZST) closure,
/// returning the result value. The closure body fn's ABI is
/// `(&closure_env, arg) -> output` (see `func_ty_for_instance`); for a ZST
/// closure `env_ptr` is unused but still occupies the receiver slot.
fn emit_closure_call_1<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    closure_ty: Ty<'tcx>,
    env_ptr: ValueId,
    arg: ValueId,
    output_ir: TrustIrTy,
) -> Result<ValueId, String> {
    emit_closure_call_n(ctx, block, closure_ty, env_ptr, vec![arg], output_ir)
}

/// Emit `result = closure(env_ptr, args…)` for a closure whose `Self::Item` was
/// untupled into `args` (one value for a scalar item, two for a `(A, B)` tuple
/// from `.enumerate()` / `.zip()`). The closure body ABI is `(&env,
/// untupled_args…) -> output`.
fn emit_closure_call_n<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    closure_ty: Ty<'tcx>,
    env_ptr: ValueId,
    args: Vec<ValueId>,
    output_ir: TrustIrTy,
) -> Result<ValueId, String> {
    let instance = closure_body_instance(ctx, closure_ty)?;
    refuse_unthreaded_caller_location(ctx.tcx, instance)?;
    let callee = ctx.extern_callee(instance)?;
    refuse_hand_built_small_cast_return(ctx, instance)?;
    closure_body_abi::refuse_single_result_call(ctx, instance)?;
    // All original arguments, including a by-value environment, are planned
    // before any argument loads/copies or the result ID are emitted.
    let call_args = closure_body_call_args_from_values(ctx, block, instance, Some(env_ptr), args)?;
    let result = ctx.fresh_value();
    // The closure body may PANIC: honor the intercepted terminator's cleanup
    // edge (FUZZ-8 [TCG-EH-INTERCEPT-CLEANUP]; Invoke + continuation split when
    // a pad is live, the plain Call otherwise).
    push_unwindable_intercept_call(ctx, block, callee, call_args, Some(result));
    let _ = output_ir;
    Ok(result)
}

/// Refuse a hand-built closure call whose body returns rustc's wasm32
/// one-integer `PassMode::Cast` (`SmallAggregateCastPlan`). These builders bind
/// the call's result as the returned aggregate VALUE and read it lane by lane;
/// the body returns one `i32` carrying its bytes instead, so reading lanes out
/// of it would misread the value. Only MIR closure calls split that carrier
/// (`finish_closure_call_aggregate_return`).
fn refuse_hand_built_small_cast_return<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    instance: Instance<'tcx>,
) -> Result<(), String> {
    if !ctx.small_cast_returns.contains_key(&instance) {
        return Ok(());
    }
    Err(format!(
        "[TCG-RET-ABI] closure `{}` returns its value as rustc's wasm32 one-integer \
         `PassMode::Cast`, but this intercepted iterator consumer reads the closure's returned \
         aggregate lane by lane; failing closed rather than reading lanes out of the carrier. \
         Options: (1) return a scalar or a two-scalar pair from the closure; (2) call the \
         closure directly and bind its result to a local.",
        ctx.tcx.def_path_str(instance.def_id())
    ))
}

/// Materialize a 2-tuple `Self::Item` (`(usize, &T)` from `.enumerate()`,
/// `(&A, &B)` from `.zip()`) as a FRESH by-value aggregate slot whose pointer is
/// the SINGLE argument a tuple-pattern `.map`/`.fold` closure receives. The
/// closure body's parameter is exactly this tuple, passed by value; rustc's MIR
/// reads it as `_2.0` / `_2.1`. We build the slot the same way every other
/// by-value aggregate argument is built (an aggregate `slot_ty` alloca filled
/// lane-by-lane via `emit_aggregate_field_store`), so the verified SysV register-pair classifier
/// places the two eightbytes exactly as the callee's parameter ABI expects.
///
/// `comp0`/`comp1` are the live representation values of the tuple's two
/// components (declaration order: index/first then value/second), in the
/// representation the chain threads (a scalar integer, or a `Ptr` for a `&T`
/// component). Each is stored at its rustc-LAYOUT byte offset (the layout may
/// reorder fields; we never assume declaration order), `PtrToInt`-narrowed into
/// the I64 lane for a pointer component (the proven fat-pointer lane convention).
fn build_tuple_item_arg<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    tuple_ty: Ty<'tcx>,
    comp0: (ValueId, &TrustIrTy),
    comp1: (ValueId, &TrustIrTy),
) -> Result<ValueId, String> {
    let tuple_ty = ctx.monomorphize_ty(tuple_ty);
    let Some(layout) = memory_aggregate_layout_shared(ctx.tcx, tuple_ty)? else {
        return Err(format!(
            "tuple-item closure argument {tuple_ty:?} has no by-value aggregate layout"
        ));
    };
    if layout.tag.is_some() {
        return Err("tuple-item closure argument is unexpectedly a tagged enum".to_owned());
    }
    let (lane_ty, lane_size) = memory_aggregate_lane(layout.align)?;
    // The tuple's per-field byte offsets from the rustc layout (NOT declaration
    // order — the layout may reorder). Field 0 holds `comp0`, field 1 `comp1`.
    let tuple_layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(tuple_ty))
        .map_err(|e| format!("tuple-item layout_of failed: {e:?}"))?;
    let rustc_abi::FieldsShape::Arbitrary { .. } = tuple_layout.fields else {
        return Err("tuple-item layout is not a field struct".to_owned());
    };
    let off0 = tuple_layout.fields.offset(0).bytes();
    let off1 = tuple_layout.fields.offset(1).bytes();
    if off0 % lane_size != 0 || off1 % lane_size != 0 {
        return Err("tuple-item field offset not lane-aligned".to_owned());
    }
    let agg = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: layout.slot_ty.clone(),
            count: None,
            align: Some(layout.align),
        })
        .with_result(agg),
    );
    for (off, (comp, comp_ir)) in [(off0, comp0), (off1, comp1)] {
        // A pointer-representation component (`&T`) is narrowed into the I64 lane
        // via `PtrToInt` (recovered as `Ptr` by the callee's body typed-load),
        // exactly as the fat-pointer data lane is stored. Scalar components
        // keep their bits through typed extension or a float bitcast.
        let lane_val = if is_pointer_like_trust_ir_ty(comp_ir) {
            emit_ptr_to_int(ctx, block, comp)
        } else if !session_is_wasm32(ctx.tcx) || comp_ir.bit_width().is_some_and(|w| w < 64) {
            tuple_lane_value(ctx, block, comp, comp_ir, &lane_ty)?
        } else {
            coerce_to_i64(ctx, block, comp)
        };
        // wasm32, a 4-aligned tuple: its lanes are `I32`, and the two arms
        // above that yield the native `i64` word (a pointer's `PtrToInt`, a
        // 64-bit `usize` component) hand that word to the lane through a
        // 32-bit `Copy`, the word fact the wasm32 word pass narrows (a genuine
        // `i64` there is refused by that pass). The field `Store` then has the
        // lane's type, which the field-store value-type gate requires
        // (`check_field_store_value_types`); the store-form `InsertField` it
        // replaced got the same narrowing from that pass's lane crossing.
        let lane_val = if session_is_wasm32(ctx.tcx)
            && lane_ty == TrustIrTy::I32
            && (is_pointer_like_trust_ir_ty(comp_ir)
                || !comp_ir.bit_width().is_some_and(|w| w < 64))
        {
            coerce_to_pointer_lane(ctx, block, lane_val)
        } else {
            lane_val
        };
        let lane = (off / lane_size) as u32;
        emit_aggregate_field_store(ctx, block, layout.slot_ty.clone(), agg, lane, lane_val)?;
    }
    Ok(agg)
}

/// A scalar tuple-item component as a value of the tuple slot's lane type.
///
/// Lanes follow the tuple's alignment (`I32` for `(u32, u32)`, `I64` for
/// `(usize, u32)` on a native 64-bit target). The callee reads each component
/// at its own type and rustc-layout offset, so preserve its low bits with an
/// explicit sign/zero extension; floats first need a same-width integer
/// bitcast, never a numeric conversion or an integer `Copy` of a float.
/// A component wider than its lane fails closed.
///
/// On wasm32 the caller uses this helper only below 64 bits. Its 64-bit word
/// spelling of a `usize` index retains the existing `copy i64` path, which the
/// wasm32 word pass narrows to the actual pointer-width lane.
fn tuple_lane_value(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    comp: ValueId,
    comp_ir: &TrustIrTy,
    lane_ty: &TrustIrTy,
) -> Result<ValueId, String> {
    let lane_bits = lane_ty
        .bit_width()
        .ok_or_else(|| format!("tuple-item lane {lane_ty:?} has no bit width"))?;
    let (value, int_ty) = if comp_ir.is_float() {
        let int_ty = match comp_ir.bit_width() {
            Some(32) => TrustIrTy::I32,
            Some(64) => TrustIrTy::I64,
            _ => {
                return Err(format!(
                    "tuple-item float component {comp_ir:?} is not modeled"
                ));
            }
        };
        let bits = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::Bitcast,
                src_ty: comp_ir.clone(),
                dst_ty: int_ty.clone(),
                operand: comp,
            })
            .with_result(bits),
        );
        (bits, int_ty)
    } else {
        (comp, comp_ir.clone())
    };
    let comp_bits = int_ty
        .bit_width()
        .ok_or_else(|| format!("tuple-item component {comp_ir:?} has no bit width"))?;
    if comp_bits > lane_bits {
        return Err(format!(
            "tuple-item component {comp_ir:?} is wider than its {lane_ty:?} lane"
        ));
    }
    let (op, dst) = if comp_bits == lane_bits {
        let r = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Copy {
                ty: lane_ty.clone(),
                operand: value,
            })
            .with_result(r),
        );
        return Ok(r);
    } else if is_signed_trust_ir_integer(&int_ty) {
        (CastOp::SExt, lane_ty.clone())
    } else {
        (CastOp::ZExt, lane_ty.clone())
    };
    let r = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op,
            src_ty: int_ty,
            dst_ty: dst,
            operand: value,
        })
        .with_result(r),
    );
    Ok(r)
}

/// Lower `.map(f)` / `.filter(p)`: build the `Map`/`Filter` adapter value in the
/// destination's memory slot. The adapter value is `{ inner_iter_state,
/// closure }`; for a ZST closure that is exactly the inner iterator state, so we
/// copy the inner iterator's bytes into the destination at the inner's (field-0)
/// offset. The destination IS the chain's runtime state, read later by an
/// intercepted consumer (`sum`/`fold`/`count`).
fn lower_iter_adapter_ctor<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
) -> Result<bool, String> {
    // `map(self, f)` / `filter(self, p)`: arg 0 is the inner iterator (by value),
    // arg 1 the closure (a ZST const).
    if call.args.len() != 2 {
        return Err(format!("iterator {name} with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err(format!("iterator {name} into projected destination"));
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    // Resolve the whole destination chain (so we validate it is one we model and
    // learn where the inner iterator sits inside the adapter slot).
    let Some(chain) = resolve_iter_chain(ctx, dest_ty)? else {
        return Ok(false);
    };
    // The newly-built adapter is the outermost layer; its inner iterator slot is
    // everything below the last adapter. The inner iterator's bytes come from the
    // arg-0 source (a Range / slice::Iter / Map / Filter value, by value).
    let Some((_, _closure_off)) = chain.adapters.last() else {
        return Err(format!("iterator {name} produced a non-adapter type"));
    };
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| format!("iterator {name} destination is not memory-backed"))?
        .ptr;

    // The inner iterator value (arg 0) is itself a chain; its slot is `dest +
    // inner_field_offset`. The inner field offset is the destination layout's
    // field-0 offset (the `iter` field). Copy the inner iterator's bytes there.
    let inner_layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(dest_ty))
        .map_err(|e| format!("iterator {name} layout_of failed: {e:?}"))?;
    let inner_field_offset = inner_layout.fields.offset(0).bytes();
    let inner_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let inner_size = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(inner_ty))
        .map_err(|e| format!("iterator {name} inner layout_of failed: {e:?}"))?
        .size
        .bytes();

    // O1 can fold a literal Range into an aggregate constant. Materialize its
    // rustc image at the same inner-field offset used by a local iterator's
    // state; do not require a nonexistent source local after constant folding.
    if let Operand::Constant(_) = &call.args[0].node {
        if !store_const_aggregate_bytes_into_memory_at(
            ctx,
            block,
            dest_slot,
            inner_field_offset,
            inner_ty,
            &call.args[0].node,
        )? {
            return Err(format!(
                "iterator {name} constant inner image is not materializable"
            ));
        }
    } else {
        let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
            return Err(format!("iterator {name} inner argument is not a place"));
        };
        if !src.projection.is_empty() {
            return Err(format!("iterator {name} inner argument is projected"));
        }
        let src_slot = ctx
            .memory_slots
            .get(&src.local)
            .cloned()
            .ok_or_else(|| format!("iterator {name} inner argument is not memory-backed"))?
            .ptr;
        copy_slot_bytes(
            ctx,
            block,
            src_slot,
            0,
            dest_slot,
            inner_field_offset,
            inner_size,
        )?;
    }

    // The closure env (arg 1) lives at the adapter type's field-1 offset within
    // the dest slot. A ZST closure carries no upvars (nothing to store; its env
    // pointer is a harmless unused address). A CAPTURING closure's upvars are
    // stored there so the chain `next` can call it with `dest + closure_offset`
    // as `&env`.
    let closure_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    if !is_zero_sized_ty(ctx.tcx, closure_ty) {
        let Some(layout) = closure_memory_layout(ctx.tcx, closure_ty)? else {
            return Err(format!("iterator {name} closure has no flat-slot layout"));
        };
        let closure_field_offset = inner_layout.fields.offset(1).bytes();
        let (Operand::Copy(cl) | Operand::Move(cl)) = &call.args[1].node else {
            return Err(format!("iterator {name} closure argument is not a place"));
        };
        if !cl.projection.is_empty() {
            return Err(format!("iterator {name} closure argument is projected"));
        }
        // The capturing-closure local is memory-backed (see
        // `compute_memory_backed_locals` (6)); copy its env slot bytes into the
        // adapter slot at the closure field offset.
        let closure_slot = ctx
            .memory_slots
            .get(&cl.local)
            .cloned()
            .ok_or_else(|| format!("iterator {name} capturing closure is not memory-backed"))?
            .ptr;
        copy_slot_bytes(
            ctx,
            block,
            closure_slot,
            0,
            dest_slot,
            closure_field_offset,
            layout.size,
        )?;
    }
    emit_call_successor(block, call.target);
    Ok(true)
}

/// Lower `(0..n).flat_map(f)`'s CTOR for the BOUNDED shape
/// (`resolve_flatmap_bounded` matches): build std's `FlatMap::new` value in the
/// destination's rustc-sized slot — `Fuse::iter = Some(Map { iter: range, f })`
/// (`f` is a ZST, so it has no bytes), `frontiter = None`, `backiter = None` —
/// at the offsets and tag encodings `FlatMapStdLayout` read from rustc's layout.
/// Any std body that later reads the value (`size_hint`, `next`, a caller
/// compiled by LLVM) therefore reads exactly what `FlatMap::new` would have
/// written, and `lower_flatmap_bounded_consumer` reads the same fields.
fn lower_flatmap_bounded_ctor<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<bool, String> {
    // `flat_map(self, f)`: arg 0 is the outer `Range<T>` (by value), arg 1 the
    // (ZST-only) closure — no bytes of arg 1 are ever read or stored (mirrors
    // the ZST-closure branch of `lower_iter_adapter_ctor`).
    if call.args.len() != 2 {
        return Ok(false);
    }
    if !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let Some(shape) = resolve_flatmap_bounded(ctx, dest_ty) else {
        return Ok(false);
    };
    // arg 0's operand: resolved the SAME way every neighboring ctor
    // (`lower_iter_adapter_ctor` / `lower_iter_structural_ctor`) resolves its
    // inner-iterator operand — an unprojected Copy/Move place with a memory
    // slot. NOT a newly-invented operand helper (a fresh, non-const local is the
    // only shape this driver models; anything else falls through to `Ok(false)`,
    // safe by the same "already fail-closed" argument as an unrecognized shape).
    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        return Ok(false);
    };
    if !src.projection.is_empty() {
        return Ok(false);
    }
    let Some(src_slot) = ctx.memory_slots.get(&src.local).cloned() else {
        return Ok(false);
    };
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "flat_map destination is not memory-backed".to_owned())?;
    let std_layout = &shape.std_layout;
    // `Fuse::iter = Some(Map { iter: range, f })`: the outer `Range<T>` bytes
    // (byte-agnostic — the same primitive `lower_iter_adapter_ctor` uses to copy
    // its inner iterator's state) and the `Some` tag.
    copy_slot_bytes(
        ctx,
        block,
        src_slot.ptr,
        0,
        dest_slot.ptr,
        std_layout.outer.range_off,
        std_layout.range_size,
    )?;
    for (optional, some) in [
        (&std_layout.outer, true),
        (&std_layout.front, false),
        (&std_layout.back, false),
    ] {
        let option_addr = iter_field_addr(ctx, block, dest_slot.ptr, optional.option_off);
        emit_option_tag_store(ctx, block, option_addr, &optional.tag, some)?;
    }
    emit_call_successor(block, call.target);
    Ok(true)
}

/// Lower a STRUCTURAL adapter constructor (`.copied()` / `.cloned()` / `.rev()` /
/// `.take(n)` / `.skip(n)` / `.step_by(k)` / `.enumerate()`): copy the inner
/// iterator's bytes into the destination slot at field-0 and initialize the
/// adapter's own state fields (a take/skip count, a step-by countdown + constant,
/// an enumerate index). The destination IS the chain's runtime state, driven
/// later by an intercepted consumer through `emit_chain_next`.
fn lower_iter_structural_ctor<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
) -> Result<bool, String> {
    if !call.destination.projection.is_empty() {
        return Err(format!("iterator {name} into projected destination"));
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let Some(chain) = resolve_iter_chain(ctx, dest_ty)? else {
        return Ok(false);
    };
    // The outermost (just-built) adapter is `chain.adapters.last()`. `.rev()`
    // produces NO adapter entry (it only flips `reversed`), so a `rev` with an
    // empty adapter stack is still valid — handle it specially below.
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| format!("iterator {name} destination is not memory-backed"))?
        .ptr;

    // Copy the inner iterator's bytes (arg 0) into the dest slot at field-0.
    let dest_layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(dest_ty))
        .map_err(|e| format!("iterator {name} layout_of failed: {e:?}"))?;
    let inner_field_offset = dest_layout.fields.offset(0).bytes();
    let inner_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let inner_size = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(inner_ty))
        .map_err(|e| format!("iterator {name} inner layout_of failed: {e:?}"))?
        .size
        .bytes();
    let (Operand::Copy(src) | Operand::Move(src)) = &call.args[0].node else {
        return Err(format!("iterator {name} inner argument is not a place"));
    };
    if !src.projection.is_empty() {
        return Err(format!("iterator {name} inner argument is projected"));
    }
    let src_slot = ctx
        .memory_slots
        .get(&src.local)
        .cloned()
        .ok_or_else(|| {
            format!(
                "iterator {name} inner argument is not memory-backed [inner {:?} ty={:?} \
                 scalar_bound={} entry_arg={} dest_ty={dest_ty:?}]",
                src.local,
                inner_ty,
                ctx.scalar_values.contains_key(&src.local),
                is_entry_arg(body, src.local),
            )
        })?
        .ptr;
    copy_slot_bytes(
        ctx,
        block,
        src_slot,
        0,
        dest_slot,
        inner_field_offset,
        inner_size,
    )?;

    // Initialize the adapter's own state from the just-built outermost adapter's
    // kind (the offsets the constructor must write are exactly those the driver
    // reads). `.copied()`/`.cloned()`/`.rev()`/`.enumerate()` take 1 arg (just the
    // inner iter); `.take`/`.skip`/`.step_by` take a second `n`/`k`.
    if name == "rev" {
        // `.rev()` adds NO adapter of its own (`resolve_iter_chain` only flips
        // `reversed`), so `chain.adapters.last()` — if any — belongs to the
        // already-constructed INNER chain (`.map(f).rev()`: last = the inner
        // Map, whose state the byte copy above already carried over).
        // A REWRITTEN below-rev `.take(n)`/`.skip(k)` (`chain.rev_clamp`) IS
        // initialized here: clamp the walk boundary in the freshly-copied slot
        // (the inner byte copy carried ptr/end AND the count field over).
        emit_rev_clamp(ctx, block, &chain, dest_slot)?;
    } else if let Some((adapter, _)) = chain.adapters.last() {
        match &adapter.kind {
            AdapterKind::Copied { .. } => {
                // No extra state; the slot is the inner iterator copied above.
            }
            AdapterKind::Enumerate { count_off, .. } => {
                // Running count (a `usize` field) starts at 0.
                let zero = emit_usize_field_const(ctx, block, 0);
                let addr = iter_field_addr(ctx, block, dest_slot, *count_off);
                emit_typed_store(block, addr, usize_field_ty(ctx.tcx), zero);
            }
            AdapterKind::Take { count_off } | AdapterKind::Skip { count_off } => {
                // The remaining/skip count `n` (arg 1) may be runtime (`black_box`).
                // It is stored at the `usize` field's own width.
                if call.args.len() != 2 {
                    return Err(format!("iterator {name} with {} args", call.args.len()));
                }
                let n = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
                let n = coerce_to_usize_field(ctx, block, n);
                let addr = iter_field_addr(ctx, block, dest_slot, *count_off);
                emit_typed_store(block, addr, usize_field_ty(ctx.tcx), n);
            }
            AdapterKind::StepBy {
                step_minus_one_off,
                first_take_off,
                range_countdown,
            } => {
                // `k` must be a compile-time constant (`k >= 1`, and `k-1`
                // fitting in 32 bits); a runtime / enormous step is not modeled
                // (fail closed). The slot gets exactly what core's
                // `StepBy::new` writes: `step_minus_one = k-1`, `first_take =
                // true`, each at its layout-derived offset, and — for a
                // countdown `Range` — `SpecRangeSetup::setup`'s
                // `end = div_ceil(len, k)`. Any std body reading the value
                // (an LLVM-built caller, a share-generics instance, an inlined
                // `spec_next`) therefore agrees with the bridge's drivers.
                if call.args.len() != 2 {
                    return Err(format!("iterator {name} with {} args", call.args.len()));
                }
                let Operand::Constant(c) = &call.args[1].node else {
                    return Err("step_by with a non-constant step is not modeled".to_owned());
                };
                let Some(k) = const_to_scalar_i128(&c.const_) else {
                    return Err("step_by step is not a scalar constant".to_owned());
                };
                if k < 1 {
                    return Err("step_by step must be >= 1".to_owned());
                }
                if k - 1 > i128::from(u32::MAX) {
                    return Err("step_by step too large to model".to_owned());
                }
                if *range_countdown {
                    emit_step_by_range_setup(ctx, block, &chain, dest_slot, k)?;
                }
                let km1 = emit_usize_field_const(ctx, block, k - 1);
                let sm_addr = iter_field_addr(ctx, block, dest_slot, *step_minus_one_off);
                emit_typed_store(block, sm_addr, usize_field_ty(ctx.tcx), km1);
                let one = emit_first_take_const(ctx, block, 1);
                let ft_addr = iter_field_addr(ctx, block, dest_slot, *first_take_off);
                emit_typed_store(block, ft_addr, TrustIrTy::I8, one);
            }
            AdapterKind::Map
            | AdapterKind::Filter
            | AdapterKind::FilterMap
            | AdapterKind::TakeWhile { .. }
            | AdapterKind::SkipWhile { .. }
            | AdapterKind::Scan { .. }
            | AdapterKind::MapWhile
            | AdapterKind::Inspect => {
                return Err(format!(
                    "iterator {name} produced an unexpected closure adapter"
                ));
            }
        }
    } else {
        // No outermost adapter and not a `.rev()` — unexpected.
        return Err(format!("iterator {name} produced a non-adapter type"));
    }
    // `.rev()` requires nothing beyond the inner-byte copy (it only flips the
    // chain's `reversed` flag, consumed by the driver).
    emit_call_successor(block, call.target);
    Ok(true)
}

/// Lower the `.chain(b)` constructor: build `Chain<A, B> = { Some(a), Some(b) }`
/// in the destination slot. Each sub-iterator's state (args 0 = `a`, 1 = `b`) is
/// copied into its `Option` payload offset and a Direct-tagged `Option`'s tag is
/// set to `Some` (a niche-encoded one is `Some` by its non-null payload). The
/// driver (`emit_source_next` `Concat`) reads those tags: it drives a half only
/// while it is `Some`, as core's `Chain` does after clearing an exhausted half.
fn lower_chain_ctor<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<bool, String> {
    if !call.destination.projection.is_empty() {
        return Err("iterator chain into projected destination".to_owned());
    }
    if call.args.len() != 2 {
        return Err(format!("iterator chain with {} args", call.args.len()));
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "iterator chain destination is not memory-backed".to_owned())?
        .ptr;
    let layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(dest_ty))
        .map_err(|e| format!("iterator chain layout_of failed: {e:?}"))?;

    // For each sub-iterator: copy its state bytes into the Option payload at
    // `option_field_offset + some_payload_off`, then write the `Some` tag. A byte
    // copy is correct only when the argument's type IS the stored sub-iterator
    // type; an `IntoIterator` argument of another type (`chain(&v)`,
    // `iter::chain(&a, &b)`) is converted first.
    let iter_tys = two_source_adapter_iter_tys(ctx, dest_ty)?;
    for (field, arg) in [(0usize, &call.args[0].node), (1usize, &call.args[1].node)] {
        let opt_ty = ctx.monomorphize_ty(field_ty_of(ctx.tcx, dest_ty, field)?);
        let opt_field_off = layout.fields.offset(field).bytes();
        let opt_layout = option_tag_layout(ctx.tcx, opt_ty)?;
        let payload_off = opt_layout.some_payload_off;
        let inner_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, arg)?);
        // The payload holds the adapter's sub-iterator `iter_tys[field]`; both
        // arms below write exactly that type's state there.
        let inner_size = ctx
            .tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(iter_tys[field]))
            .map_err(|e| format!("iterator chain inner layout_of failed: {e:?}"))?
            .size
            .bytes();
        let payload_dst = opt_field_off
            .checked_add(payload_off)
            .filter(|offset| {
                offset
                    .checked_add(inner_size)
                    .is_some_and(|end| end <= layout.size.bytes())
            })
            .ok_or_else(|| "iterator chain payload exceeds its destination layout".to_owned())?;
        if inner_ty == iter_tys[field] {
            // Optimized MIR can fold either Range argument into a CTFE image.
            // Materialize the same compiler-derived bytes as Zip, then retain the
            // Option tag write below: an initialized payload alone is not Some.
            if !store_const_aggregate_bytes_into_memory_at(
                ctx,
                block,
                dest_slot,
                payload_dst,
                inner_ty,
                arg,
            )? {
                let (Operand::Copy(src) | Operand::Move(src)) = arg else {
                    return Err(
                        "iterator chain inner argument has no materializable image".to_owned()
                    );
                };
                if !src.projection.is_empty() {
                    return Err("iterator chain inner argument is projected".to_owned());
                }
                let src_slot = ctx
                    .memory_slots
                    .get(&src.local)
                    .cloned()
                    .ok_or_else(|| "iterator chain inner argument is not memory-backed".to_owned())?
                    .ptr;
                copy_slot_bytes(ctx, block, src_slot, 0, dest_slot, payload_dst, inner_size)?;
            }
        } else {
            store_into_iter_arg_state(
                ctx,
                body,
                block,
                arg,
                iter_tys[field],
                dest_slot,
                payload_dst,
                "chain",
            )?;
        }
        // Write the `Some` tag. A Direct-tagged `Option<Range>` has an explicit
        // discriminant field to set. A NICHE-encoded `Option<slice::Iter>` has NONE:
        // the iterator state written above holds a non-null `ptr` (the niche), which
        // already encodes `Some`, so `emit_option_tag_store` writes nothing there.
        let opt_addr = iter_field_addr(ctx, block, dest_slot, opt_field_off);
        emit_option_tag_store(ctx, block, opt_addr, &opt_layout, true)?;
    }

    emit_call_successor(block, call.target);
    Ok(true)
}

/// Write the sub-iterator state that the callee's own `IntoIterator::into_iter`
/// would build from `arg` into `dest_slot + offset`, for an adapter constructor
/// whose parameter is `U: IntoIterator` rather than the iterator itself
/// (`Iterator::zip(self, other: U)`, `Iterator::chain(self, other: U)`, the free
/// `iter::zip(a, b)` / `iter::chain(a, b)`). The bytes of such an `arg` are NOT
/// the sub-iterator's state: `&[T]` is `{ data, len }` where `slice::Iter<T>` is
/// `{ ptr, end }`, and `&[T; N]` / `&Vec<T>` are a single pointer.
///
/// `iter_ty` is the sub-iterator type the destination adapter stores
/// (`U::IntoIter`); only a `slice::Iter<T>` / `slice::IterMut<T>` is built here,
/// from a `&[T]`, a `&[T; N]`, or a borrow of a non-argument `Vec<T>` local
/// (`borrows_local_vec`) (or their `&mut` forms), exactly as
/// `lower_slice_into_iter` / `lower_vec_into_iter` build it: `ptr = data`,
/// `end = data + len * size_of::<T>()`. Every other `U` (and any argument the
/// data/length readers cannot place) refuses with `[TCG-ITER-INTOITER-ARG]`; a
/// `&Vec` in a 32-bit session refuses with `lower_vec_into_iter`'s
/// `[TCG-WASM32-MODEL]`.
#[allow(clippy::too_many_arguments)]
fn store_into_iter_arg_state<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    arg: &Operand<'tcx>,
    iter_ty: Ty<'tcx>,
    dest_slot: ValueId,
    offset: u64,
    ctor: &str,
) -> Result<(), String> {
    let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, arg)?);
    let refuse = |detail: String| {
        format!(
            "[TCG-ITER-INTOITER-ARG] rustc_codegen_trust_cg: the `{ctor}` constructor's \
             `IntoIterator` argument `{arg_ty:?}` must be converted to its `{iter_ty:?}` \
             state before the adapter stores it, and this argument is not one the bridge \
             converts ({detail}) — failing closed rather than storing the argument's own \
             bytes as iterator state"
        )
    };
    let Some(element_ty) = slice_iter_or_mut_element_ty(ctx.tcx, iter_ty) else {
        return Err(refuse(
            "only a borrowed slice / array / Vec producing a `slice::Iter` or \
             `slice::IterMut` is modeled"
                .to_owned(),
        ));
    };
    let element_ty = ctx.monomorphize_ty(element_ty);
    let ty::Ref(_, pointee, _) = arg_ty.kind() else {
        return Err(refuse("the argument is not a reference".to_owned()));
    };
    let pointee = ctx.monomorphize_ty(*pointee);
    // The pointee's element must be the iterator's: `<&[T] as IntoIterator>::IntoIter
    // = slice::Iter<T>` (and likewise for arrays and `Vec`), so a mismatch means the
    // argument is not the conversion this function models.
    let pointee_element = match pointee.kind() {
        ty::Slice(e) | ty::Array(e, _) => Some(ctx.monomorphize_ty(*e)),
        _ => vec_element_ty(ctx.tcx, pointee).map(|e| ctx.monomorphize_ty(e)),
    };
    if pointee_element != Some(element_ty) {
        return Err(refuse(format!(
            "the referent `{pointee:?}` is not a slice, array or modeled Vec of `{element_ty:?}`"
        )));
    }
    let (size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;
    let (data, len) = if matches!(pointee.kind(), ty::Slice(_) | ty::Array(..)) {
        slice_iter_data_and_len(ctx, body, block, arg).map_err(refuse)?
    } else {
        // The Vec header read below is the 64-bit `{ cap, ptr, len }` image, as in
        // `lower_vec_into_iter`.
        require_64bit_model("a `&Vec` `IntoIterator` argument of `zip` / `chain`")?;
        if !borrows_local_vec(ctx, body, arg) {
            return Err(refuse(
                "a `&Vec` that is not a borrow of a non-argument Vec local of this body".to_owned(),
            ));
        }
        let slot_ptr = vec_self_slot_addr(ctx, body, block, arg).map_err(refuse)?;
        let data = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
        let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);
        (data, len)
    };
    let end = emit_element_addr(ctx, block, data, len, size);
    let ptr_addr = iter_field_addr(ctx, block, dest_slot, offset);
    emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, data);
    let end_addr = iter_field_addr(ctx, block, dest_slot, offset + slice_iter_end_offset());
    emit_typed_store(block, end_addr, TrustIrTy::Ptr, end);
    Ok(())
}

/// Whether `arg` is `&v` / `&mut v` of a non-argument `Vec` local `v` of this
/// body — the one `&Vec` form the `zip` / `chain` conversion admits. The
/// reference is recognised as the bridge's virtual borrow of `v`
/// (`borrowed_scalars`, not branch-varying), or, when it is a real reference
/// local, by its MIR definition: it has exactly one direct definition and no
/// other write channel (`local_has_unique_direct_def`), and that definition is
/// `Rvalue::Ref` of the projection-free local `v`, so on every path the
/// reference reaching the call is the address of `v`'s header. This is a shape
/// rule, not a provenance rule: `v` may hold a header a call or a move built
/// (`let v = param;`), read as rustc's real image like every other Vec header
/// (LIMITATIONS.md "Collection representation": native AArch64 Linux and
/// measured shapes only). Every other `&Vec` (a parameter, a reference loaded
/// from memory or reborrowed through a deref, a direct borrow of a by-value
/// `Vec` parameter) has no qualifying `zip` / `chain` row and refuses.
fn borrows_local_vec<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    arg: &Operand<'tcx>,
) -> bool {
    let Some(reference) = operand_as_local(arg) else {
        return false;
    };
    let target = if let Some(binding) = ctx.borrowed_scalars.get(&reference) {
        let ScalarPlaceBinding::Local(target) = binding.target else {
            return false;
        };
        if binding.branch_varying {
            return false;
        }
        target
    } else {
        if !local_has_unique_direct_def(body, reference) {
            return false;
        }
        let Some(Rvalue::Ref(_, _, borrowed)) = find_local_assign(body, reference) else {
            return false;
        };
        if !borrowed.projection.is_empty() {
            return false;
        }
        borrowed.local
    };
    let is_argument = (1..=body.arg_count).contains(&target.index());
    let target_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, target));
    target != reference && !is_argument && vec_element_ty(ctx.tcx, target_ty).is_some()
}

/// The two sub-iterator types `A`, `B` of a `Zip<A, B>` / `Chain<A, B>`
/// destination (its first two generic type arguments).
fn two_source_adapter_iter_tys<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    dest_ty: Ty<'tcx>,
) -> Result<[Ty<'tcx>; 2], String> {
    let ty::Adt(_, args) = dest_ty.kind() else {
        return Err(format!(
            "two-source iterator adapter destination is not an ADT: {dest_ty:?}"
        ));
    };
    Ok([
        ctx.monomorphize_ty(args.type_at(0)),
        ctx.monomorphize_ty(args.type_at(1)),
    ])
}

/// Lower the `.zip(b)` constructor: build `Zip<A, B> = { a, b, index: 0, len }` in
/// the destination slot. An argument whose type is the sub-iterator type (`A` /
/// `B`) is copied into its `Zip` field at the dest layout's field-0 / field-1
/// offset; an `IntoIterator` argument of another type (`zip(&v)`, `iter::zip(&a,
/// &b)`) is converted first (`store_into_iter_arg_state`). Then compute `len =
/// min(a_len, b_len)` (each sub-iterator's element count `(end - ptr) /
/// elem_size`) and write `index = 0`. The driver (`emit_source_next` `Zip`) reads
/// element `index` off each sub-iterator's base `ptr` and the cursor.
fn lower_zip_ctor<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<bool, String> {
    if !call.destination.projection.is_empty() {
        return Err("iterator zip into projected destination".to_owned());
    }
    if call.args.len() != 2 {
        return Err(format!("iterator zip with {} args", call.args.len()));
    }
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    // Resolve the dest Zip chain to learn the field offsets / element strides the
    // driver will read; only a slice+slice (4-field TRA) Zip is modeled.
    let Some(chain) = resolve_iter_chain(ctx, dest_ty)? else {
        return Ok(false);
    };
    let ChainSource::Zip {
        a,
        b,
        index_offset,
        len_offset,
    } = &chain.source
    else {
        return Err("iterator zip destination is not a modeled Zip source".to_owned());
    };
    let (a, b) = (a.clone(), b.clone());
    let (index_offset, len_offset) = (*index_offset, *len_offset);

    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "iterator zip destination is not memory-backed".to_owned())?
        .ptr;

    // Copy each sub-iterator arg into its `Zip` field (field 0 = a, field 1 = b):
    // a `slice::Iter` is 16 bytes `{ptr, end}`, a 64-bit `Range` 16 bytes
    // `{start, end}`. At `-O3` a literal-bound Range arrives as a CONST operand
    // (`const Range { 0, 5 }`) — write its in-memory image bytes directly into
    // the field; otherwise copy from the arg place's memory slot. A byte copy is
    // correct only when the argument's type IS the stored sub-iterator type.
    let [a_iter_ty, b_iter_ty] = two_source_adapter_iter_tys(ctx, dest_ty)?;
    for (side, arg, iter_ty) in [
        (&a, &call.args[0].node, a_iter_ty),
        (&b, &call.args[1].node, b_iter_ty),
    ] {
        let inner_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, arg)?);
        if inner_ty != iter_ty {
            store_into_iter_arg_state(
                ctx,
                body,
                block,
                arg,
                iter_ty,
                dest_slot,
                side.offset,
                "zip",
            )?;
            continue;
        }
        let inner_size = ctx
            .tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(inner_ty))
            .map_err(|e| format!("iterator zip inner layout_of failed: {e:?}"))?
            .size
            .bytes();
        if store_const_aggregate_bytes_into_memory_at(
            ctx,
            block,
            dest_slot,
            side.offset,
            inner_ty,
            arg,
        )? {
            continue;
        }
        let (Operand::Copy(src) | Operand::Move(src)) = arg else {
            return Err("iterator zip inner argument is not a place".to_owned());
        };
        if !src.projection.is_empty() {
            return Err("iterator zip inner argument is projected".to_owned());
        }
        let src_slot = ctx
            .memory_slots
            .get(&src.local)
            .cloned()
            .ok_or_else(|| "iterator zip inner argument is not memory-backed".to_owned())?
            .ptr;
        copy_slot_bytes(ctx, block, src_slot, 0, dest_slot, side.offset, inner_size)?;
    }

    // Per-side element count, read back off the dest slot AFTER the copy above.
    let side_len = |ctx: &mut MirLoweringCtx<'tcx>,
                    block: &mut Block,
                    side: &ZipSide<'tcx>|
     -> ValueId {
        match side.kind {
            ZipSideKind::SlicePtr => {
                // `(end - ptr) / elem_size`; `end` (one-past-end pointer) sits at
                // `offset + slice_iter_end_offset()`. Non-negative for a valid
                // iterator, `elem_size` nonzero (resolve-checked) => UDiv defined.
                let ptr_addr = iter_field_addr(ctx, block, dest_slot, side.offset);
                let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
                let end_addr =
                    iter_field_addr(ctx, block, dest_slot, side.offset + slice_iter_end_offset());
                let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
                let ptr_int = emit_ptr_to_int(ctx, block, ptr);
                let end_int = emit_ptr_to_int(ctx, block, end);
                let byte_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, end_int, ptr_int);
                let stride = emit_i64_const(ctx, block, i128::from(side.elem_size));
                emit_i64_binop(ctx, block, TrustIrBinOp::UDiv, byte_len, stride)
            }
            ZipSideKind::RangeStart => {
                // `Range::size() = start < end ? end - start : 0` — SIGNED compare
                // for a signed index (mirrors std's size_hint clamp); the Sub's
                // 64-bit two's-complement result equals `steps_between` exactly.
                // In the index's own (pointer) width, `zip_range_word_ty`.
                let word = zip_range_word_ty(side);
                let start_addr = iter_field_addr(ctx, block, dest_slot, side.offset);
                let start = emit_typed_load(ctx, block, start_addr, word.clone());
                let end_addr = iter_field_addr(ctx, block, dest_slot, side.offset + side.elem_size);
                let end = emit_typed_load(ctx, block, end_addr, word.clone());
                let nonempty = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: if is_signed_trust_ir_integer(&side.elem_ir) {
                            ICmpOp::Slt
                        } else {
                            ICmpOp::Ult
                        },
                        ty: word.clone(),
                        lhs: start,
                        rhs: end,
                    })
                    .with_result(nonempty),
                );
                let diff = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Sub,
                        ty: word.clone(),
                        lhs: end,
                        rhs: start,
                    })
                    .with_result(diff),
                );
                let zero = emit_typed_const(ctx, block, word.clone(), 0);
                let len = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: word,
                        cond: nonempty,
                        then_val: diff,
                        else_val: zero,
                    })
                    .with_result(len),
                );
                len
            }
        }
    };
    let a_len = side_len(ctx, block, &a);
    let b_len = side_len(ctx, block, &b);
    // min(a_len, b_len) = a_len < b_len ? a_len : b_len (unsigned).
    let a_lt_b = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ult,
            ty: TrustIrTy::I64,
            lhs: a_len,
            rhs: b_len,
        })
        .with_result(a_lt_b),
    );
    let len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::I64,
            cond: a_lt_b,
            then_val: a_len,
            else_val: b_len,
        })
        .with_result(len),
    );
    // `len` and `index` are `usize` fields, each stored at its own width. (An
    // 8-byte store of a fact-less `const i64 0` into a 4-byte `index` would
    // clobber the `len` beside it.)
    let len_addr = iter_field_addr(ctx, block, dest_slot, len_offset);
    emit_usize_field_store(ctx, block, len_addr, len);
    let zero = emit_usize_field_const(ctx, block, 0);
    let index_addr = iter_field_addr(ctx, block, dest_slot, index_offset);
    emit_typed_store(block, index_addr, usize_field_ty(ctx.tcx), zero);

    emit_call_successor(block, call.target);
    Ok(true)
}

/// Copy `size` bytes from `src_slot + src_off` to `dst_slot + dst_off`, as
/// pointer-width (8-byte) lanes plus a trailing partial lane. Used to relocate an
/// inner iterator's `{start,end}` / `{ptr,end}` state into an adapter slot.
fn copy_slot_bytes(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    src_slot: ValueId,
    src_off: u64,
    dst_slot: ValueId,
    dst_off: u64,
    size: u64,
) -> Result<(), String> {
    let mut copied = 0u64;
    while size - copied >= 8 {
        let s = iter_field_addr(ctx, block, src_slot, src_off + copied);
        let v = emit_typed_load(ctx, block, s, TrustIrTy::I64);
        let d = iter_field_addr(ctx, block, dst_slot, dst_off + copied);
        emit_typed_store(block, d, TrustIrTy::I64, v);
        copied += 8;
    }
    // A trailing sub-8 remainder, decomposed into power-of-two byte chunks (4 / 2
    // / 1). A `{i64,i64}` / `{ptr,ptr}` chain has none; a 4-byte index `Range`
    // slot copies one I32; a 3-byte `RangeInclusive<u8>` (`{start,end,exhausted}`)
    // copies an I16 then an I8. This byte copy is layout-agnostic (it moves the
    // raw bytes of the whole inner iterator, including the `exhausted` flag),
    // which is exactly what an adapter's "copy inner state into field 0" needs.
    for chunk in [4u64, 2, 1] {
        while size - copied >= chunk {
            let ty = match chunk {
                4 => TrustIrTy::I32,
                2 => TrustIrTy::I16,
                _ => TrustIrTy::I8,
            };
            let s = iter_field_addr(ctx, block, src_slot, src_off + copied);
            let v = emit_typed_load(ctx, block, s, ty.clone());
            let d = iter_field_addr(ctx, block, dst_slot, dst_off + copied);
            emit_typed_store(block, d, ty, v);
            copied += chunk;
        }
    }
    if copied != size {
        return Err(format!("iterator slot copy: unsupported size {size}"));
    }
    Ok(())
}

/// Apply a rewritten below-rev `.take(n)` / `.skip(k)` boundary clamp to a
/// slice chain slot (see `RevClamp`); a no-op for a chain without one.
/// IDEMPOTENT (safe to apply at BOTH the ctor and every drive preheader, and
/// across successive `&mut`-receiver drives): the take clamp recomputes
/// `min(n, remaining) = remaining` (the reversed walk only shrinks `end`); the
/// skip clamp zeroes the count after moving `ptr`. Emitted at the `.rev()`
/// ctor AND at every drive preheader — an `-O3`-inlined ctor (plain field
/// stores) never runs the rev-ctor interception, and `lower_iter_consumer`'s
/// CONST-self image materialization has no ctor at all, so the drive-site
/// clamp is the load-bearing one; the ctor clamp keeps the slot state
/// canonical for any REAL (non-intercepted) `next`/`next_back` body a bare
/// `for` loop may later run over it (with `n >= remaining`, real
/// `Take::next/next_back` degenerate to the bare iterator walk).
fn emit_rev_clamp<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    chain: &IterChain<'tcx>,
    chain_slot: ValueId,
) -> Result<(), String> {
    let Some(clamp) = chain.rev_clamp else {
        return Ok(());
    };
    let ChainSource::Slice {
        size,
        end_off,
        repr,
        ..
    } = &chain.source
    else {
        return Err("rev-clamp chain has a non-slice source".to_owned());
    };
    repr.require_pointers("the `.rev()` take/skip clamp")?;
    let elem_size = *size;
    let end_off = *end_off;
    if elem_size == 0 {
        return Err("rev-clamp over a zero-sized element is not modeled".to_owned());
    }
    let (count_off, is_take) = match clamp {
        RevClamp::TakeEnd { count_off } => (count_off, true),
        RevClamp::SkipStart { count_off } => (count_off, false),
    };
    // len = (end - ptr) / elem_size (the zip-ctor SlicePtr idiom; non-negative
    // for a valid iterator, elem_size nonzero => UDiv defined).
    let ptr_addr = iter_field_addr(ctx, block, chain_slot, chain.source_offset);
    let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
    let end_addr = iter_field_addr(ctx, block, chain_slot, chain.source_offset + end_off);
    let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
    let ptr_int = emit_ptr_to_int(ctx, block, ptr);
    let end_int = emit_ptr_to_int(ctx, block, end);
    let byte_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, end_int, ptr_int);
    let stride = emit_i64_const(ctx, block, i128::from(elem_size));
    let len = emit_i64_binop(ctx, block, TrustIrBinOp::UDiv, byte_len, stride);
    // The take/skip count `n` from its slot field (a `usize`, loaded at the
    // field's own width and zero-extended onto the `I64` length lane).
    let count_ty = usize_field_ty(ctx.tcx);
    let n_addr = iter_field_addr(ctx, block, chain_slot, count_off);
    let n_field = emit_typed_load(ctx, block, n_addr, count_ty.clone());
    let n = if count_ty == TrustIrTy::I64 {
        n_field
    } else {
        let widened = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::ZExt,
                src_ty: count_ty.clone(),
                dst_ty: TrustIrTy::I64,
                operand: n_field,
            })
            .with_result(widened),
        );
        widened
    };
    // m = min(n, len), unsigned (the zip-ctor min idiom).
    let n_lt_len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ult,
            ty: TrustIrTy::I64,
            lhs: n,
            rhs: len,
        })
        .with_result(n_lt_len),
    );
    let m = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::I64,
            cond: n_lt_len,
            then_val: n,
            else_val: len,
        })
        .with_result(m),
    );
    // boundary' = ptr + m * elem_size (the proven address sequence).
    let clamped = emit_element_addr(ctx, block, ptr, m, elem_size);
    if is_take {
        emit_typed_store(block, end_addr, TrustIrTy::Ptr, clamped);
    } else {
        emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, clamped);
        // Zero the skip count (std's own `Skip::next` semantics; makes the
        // re-clamp a no-op and the slot state canonical for real bodies). A
        // `usize` field: stored at `usize_field_ty`, never as a fact-less i64.
        let zero = emit_usize_field_const(ctx, block, 0);
        emit_typed_store(block, n_addr, usize_field_ty(ctx.tcx), zero);
    }
    Ok(())
}

/// How a by-value consumer reaches core's `Take` fold specialization.
#[derive(Clone, Copy, PartialEq, Eq)]
enum TakeFoldRoute {
    /// `Iterator::fold` and the terminals core implements through it (`sum`,
    /// `product`, `count`, `last`, `for_each`). Every `Map`/`Copied`/`Cloned`/
    /// `Enumerate`/`Filter`/`FilterMap`/`Inspect` above the `Take` forwards its
    /// own `fold` to the inner one, so the call reaches `Take::fold` /
    /// `Take::for_each` with the Take untouched.
    Fold,
    /// `Vec` collect/extend. core takes `for_each` (hence `Take::for_each`) only
    /// for a `TrustedLen` iterator, which above a `Take` means only
    /// `Map`/`Copied`/`Cloned`/`Enumerate`; any other iterator is pulled with
    /// `next`, which is the drive's sequential order.
    TrustedLenForEach,
}

/// core's `SpecTake::spec_fold` / `spec_for_each` for a `Take<I>` whose `I` is
/// `TrustedRandomAccess` (take.rs): `end = min(n, I::size())` is computed
/// BEFORE anything is fetched, and only indices `0..end` are fetched. A `Skip`
/// inside `I` evaluates (and drops) its skipped prefix only when index 0 is
/// fetched (`Skip::__iterator_get_unchecked`), so when the skip covers the
/// whole source no `Map` closure below it runs at all, while the drive's
/// sequential skip-discard would map and drop every element. When `end > 0` the
/// sequential drive already evaluates exactly core's sequence (the prefix, then
/// `end` yielded elements), so storing `end` into the Take count before the
/// drive makes the two identical.
///
/// Emitted into the preheader of a by-value consumer over a PRIVATE chain slot
/// (the Take count is dead after the consumer). A no-op unless the chain has
/// that exact shape: the Take the consumer's fold reaches (only `route`'s
/// forwarding adapters above it), every adapter below it
/// `TrustedRandomAccess`-preserving (`Map`/`Copied`/`Cloned`/`Enumerate`/
/// `Skip`; not `Take`, `Filter`, `StepBy`, `Rev`, …), a
/// `TrustedRandomAccess` source (`slice::Iter` / `slice::IterMut`, a `Range` of
/// an integer core implements it for on this target, a modeled `Zip` of those;
/// never the owning `vec::IntoIter` / `array::IntoIter`, which the chain also
/// models as a slice cursor), and a `Skip` with a
/// `Map` below it (the only way the prefix has an effect). Every other chain
/// takes core's sequential `try_fold`/`next` route, which the drive models.
fn emit_take_tra_fold_clamp<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    chain: &IterChain<'tcx>,
    chain_slot: ValueId,
    route: TakeFoldRoute,
) -> Result<(), String> {
    let mut take = None;
    for (idx, (adapter, _)) in chain.adapters.iter().enumerate().rev() {
        match adapter.kind {
            AdapterKind::Take { count_off } => {
                take = Some((idx, count_off));
                break;
            }
            AdapterKind::Map | AdapterKind::Copied { .. } | AdapterKind::Enumerate { .. } => {}
            AdapterKind::Filter | AdapterKind::FilterMap | AdapterKind::Inspect
                if route == TakeFoldRoute::Fold => {}
            _ => return Ok(()),
        }
    }
    let Some((take_idx, take_count_off)) = take else {
        return Ok(());
    };
    let below = &chain.adapters[..take_idx];
    if !below.iter().all(|(a, _)| {
        matches!(
            a.kind,
            AdapterKind::Map
                | AdapterKind::Copied { .. }
                | AdapterKind::Enumerate { .. }
                | AdapterKind::Skip { .. }
        )
    }) {
        return Ok(());
    }
    let prefix_has_effect = below.iter().enumerate().any(|(j, (a, _))| {
        matches!(a.kind, AdapterKind::Skip { .. })
            && below[..j]
                .iter()
                .any(|(b, _)| matches!(b.kind, AdapterKind::Map))
    });
    if !prefix_has_effect || chain.reversed || chain.rev_clamp.is_some() {
        return Ok(());
    }

    // `I::size()` of the source, zero-extended onto an I64 lane.
    let count_ty = usize_field_ty(ctx.tcx);
    let widen_usize = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, v: ValueId| {
        emit_extend_to_i64(ctx, block, &count_ty, false, v)
    };
    let offset = chain.source_offset;
    let source_size = match &chain.source {
        ChainSource::Slice {
            size,
            trusted_random_access,
            end_off,
            repr,
            ..
        } => {
            // An owning `vec::IntoIter` / `array::IntoIter` is not
            // `TrustedRandomAccess`, so neither is any `Map`/`Skip` over it:
            // core takes the default `SpecTake` (`try_fold` -> `Skip::nth`),
            // which evaluates the skipped prefix sequentially, as the drive does.
            if !*trusted_random_access {
                return Ok(());
            }
            // A `TrustedRandomAccess` source is a borrowing `slice::Iter` /
            // `IterMut`: pointer fields `end_off` bytes apart.
            repr.require_pointers("the `Take<Skip<..>>` TrustedRandomAccess fold")?;
            let elem_size = *size;
            if elem_size == 0 {
                return Err(
                    "iterator take fold over a skip of a zero-sized slice element is not \
                     modeled"
                        .to_owned(),
                );
            }
            let ptr_addr = iter_field_addr(ctx, block, chain_slot, offset);
            let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
            let end_addr = iter_field_addr(ctx, block, chain_slot, offset + *end_off);
            let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
            let ptr_int = emit_ptr_to_int(ctx, block, ptr);
            let end_int = emit_ptr_to_int(ctx, block, end);
            let byte_len = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, end_int, ptr_int);
            let stride = emit_i64_const(ctx, block, i128::from(elem_size));
            emit_i64_binop(ctx, block, TrustIrBinOp::UDiv, byte_len, stride)
        }
        ChainSource::Range {
            index_ty,
            ir_ty,
            size,
        } => {
            // core/src/iter/range.rs: `Range<T>: TrustedRandomAccess` for
            // `u8/u16/u32/usize/i8/i16/i32/isize`, plus `u64/i64` only on a
            // 64-bit target. Any other index takes the sequential route.
            let pointer_64 = ctx.tcx.data_layout.pointer_size().bits() == 64;
            let tra = match index_ty.kind() {
                ty::Uint(ty::UintTy::U128) | ty::Int(ty::IntTy::I128) => false,
                ty::Uint(ty::UintTy::U64) | ty::Int(ty::IntTy::I64) => pointer_64,
                ty::Uint(_) | ty::Int(_) => true,
                _ => false,
            };
            if !tra {
                return Ok(());
            }
            let signed = is_signed_trust_ir_integer(ir_ty);
            let start_addr = iter_field_addr(ctx, block, chain_slot, offset);
            let start = emit_typed_load(ctx, block, start_addr, ir_ty.clone());
            let end_addr = iter_field_addr(ctx, block, chain_slot, offset + size);
            let end = emit_typed_load(ctx, block, end_addr, ir_ty.clone());
            let nonempty = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                    ty: ir_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(nonempty),
            );
            // `end - start` wraps into the index width's UNSIGNED range, which
            // holds every non-empty range's exact length.
            let diff = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Sub,
                    ty: ir_ty.clone(),
                    lhs: end,
                    rhs: start,
                })
                .with_result(diff),
            );
            let diff64 = if ir_ty.bit_width() == Some(64) {
                coerce_to_i64(ctx, block, diff)
            } else {
                let widened = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::ZExt,
                        src_ty: ir_ty.clone(),
                        dst_ty: TrustIrTy::I64,
                        operand: diff,
                    })
                    .with_result(widened),
                );
                widened
            };
            let zero = emit_i64_const(ctx, block, 0);
            emit_i64_select(ctx, block, nonempty, diff64, zero)
        }
        ChainSource::Zip {
            index_offset,
            len_offset,
            ..
        } => {
            // The TRA `Zip`'s `size()` is `len - index`.
            let index_addr = iter_field_addr(ctx, block, chain_slot, offset + *index_offset);
            let index = emit_typed_load(ctx, block, index_addr, count_ty.clone());
            let index = widen_usize(ctx, block, index);
            let len_addr = iter_field_addr(ctx, block, chain_slot, offset + *len_offset);
            let len = emit_typed_load(ctx, block, len_addr, count_ty.clone());
            let len = widen_usize(ctx, block, len);
            emit_i64_binop(ctx, block, TrustIrBinOp::Sub, len, index)
        }
        ChainSource::RangeInclusive { .. } | ChainSource::Concat { .. } => return Ok(()),
    };

    // `Skip::size()` is `inner.size().saturating_sub(n)` at every Skip below the
    // Take (saturating subtractions commute, so their order is irrelevant).
    let mut size = source_size;
    for (adapter, _) in below {
        let AdapterKind::Skip { count_off } = adapter.kind else {
            continue;
        };
        let skip_addr = iter_field_addr(ctx, block, chain_slot, count_off);
        let skip = emit_typed_load(ctx, block, skip_addr, count_ty.clone());
        let skip = widen_usize(ctx, block, skip);
        let covers = emit_i64_icmp(ctx, block, ICmpOp::Ule, size, skip);
        let rest = emit_i64_binop(ctx, block, TrustIrBinOp::Sub, size, skip);
        let zero = emit_i64_const(ctx, block, 0);
        size = emit_i64_select(ctx, block, covers, zero, rest);
    }
    // end = min(n, size), stored as the Take's remaining count.
    let n_addr = iter_field_addr(ctx, block, chain_slot, take_count_off);
    let n_field = emit_typed_load(ctx, block, n_addr, count_ty.clone());
    let n = widen_usize(ctx, block, n_field);
    let n_below = emit_i64_icmp(ctx, block, ICmpOp::Ult, n, size);
    let end = emit_i64_select(ctx, block, n_below, n, size);
    let end = emit_trunc_from_i64(ctx, block, &count_ty, end);
    emit_typed_store(block, n_addr, count_ty, end);
    Ok(())
}

/// Declare a memory libcall from the genuine core runtime authority. Its
/// pointer result remains part of the C ABI even when an intrinsic ignores it;
/// name-based module merging must see the same prototype as ordinary C calls.
fn memory_libcall_callee<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    kind: MemoryLibcall,
) -> Result<FuncId, String> {
    let did = kind.definition(ctx.tcx)?;
    // The byte-count lowering is bounded to the target's real size_t: 64-bit
    // natively, 32-bit on wasm32 (`memory_libcall_size_ty`). Check size_t and
    // C int against the actual core declaration, then use extern_callee's
    // ordinary Rust FnAbi/parameter/return classification. On wasm32 that
    // declaration is the exact C prototype a typed wasm import needs,
    // `(ptr, ptr|int, size_t) -> ptr` (`wasm32_words::check_c_memory_libcalls`).
    if memory_libcall_size_ty(ctx.tcx).is_none() {
        let sig = ctx.tcx.fn_sig(did).instantiate_identity().skip_binder();
        return Err(format!(
            "[TCG-MEM-LIBCALL-ABI] unsupported genuine {} prototype {sig:?}",
            kind.label()
        ));
    }
    ctx.extern_callee(Instance::mono(ctx.tcx, did))
}

/// The trust-ir type of the target's genuine `size_t` (`usize`) for a memory
/// libcall: `U64` on a 64-bit target, `U32` on wasm32 (the only 32-bit
/// session). `None` for any other pointer width or mapping, which fails closed.
fn memory_libcall_size_ty(tcx: TyCtxt<'_>) -> Option<TrustIrTy> {
    let mapped = rust_ty_to_trust_ir_ty(tcx, tcx.types.usize).ok()?;
    match (tcx.data_layout.pointer_size().bits(), mapped) {
        (64, TrustIrTy::U64) => Some(TrustIrTy::U64),
        (32, TrustIrTy::U32) if session_is_wasm32(tcx) => Some(TrustIrTy::U32),
        _ => None,
    }
}

/// Form the original element count times element extent in the genuine
/// size_t (64-bit natively, 32-bit on wasm32), retaining the intrinsic's
/// wrapping arithmetic and safety contract.
fn memory_libcall_byte_count<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    count: &Operand<'tcx>,
    elem_size: u64,
) -> Result<ValueId, String> {
    let size_ty = memory_libcall_size_ty(ctx.tcx);
    let Some(size_ty) = size_ty.filter(|_| {
        operand_rust_ty(ctx, body, count)
            .is_ok_and(|ty| ctx.monomorphize_ty(ty) == ctx.tcx.types.usize)
    }) else {
        return Err(
            "[TCG-MEM-LIBCALL-ABI] element count is not the target's 64-bit (or wasm32 \
             32-bit) usize"
                .into(),
        );
    };
    let count = lower_operand_to_value(ctx, body, block, count)?;
    let size = emit_typed_const(ctx, block, size_ty.clone(), i128::from(elem_size));
    let bytes = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Mul,
            ty: size_ty,
            lhs: count,
            rhs: size,
        })
        .with_result(bytes),
    );
    Ok(bytes)
}

/// Lower a `copy_nonoverlapping(src, dst, count)` intrinsic STATEMENT (the real
/// `ptr::copy_nonoverlapping` / `<*const T>::copy_to_nonoverlapping` memcpy).
///
/// Two lowerings, both semantically a non-overlapping memcpy of
/// `count * size_of::<T>()` bytes from `src` to `dst`:
///
///   * FAST PROVEN UNROLL — a COMPILE-TIME-CONSTANT count (≤ 1024) of a
///     SCALAR-leaf element unrolls to `count` naturally aligned typed load+store
///     pairs (`dst[i] = src[i]` at byte offset `i*size_of::<T>`), each an
///     already-proven `Load`/`Store` (no new proof obligation; the same
///     primitives `copy_slot_bytes` uses). The intrinsic's non-overlapping
///     precondition makes the sequential per-element copy equivalent to a memcpy,
///     and its alignment precondition makes each access naturally aligned.
///
///   * GENERAL `memcpy` CALL — a RUNTIME count, a non-scalar element, or a count
///     too large to unroll emit a call to libc `memcpy(dst, src, count*elem)`.
///     `memcpy`'s contract (source and destination must NOT overlap) is exactly
///     `copy_nonoverlapping`'s documented safety precondition, so the call is a
///     faithful lowering — this is what rustc's own backend emits (`llvm.memcpy`).
///     The undefined callee is named `_memcpy` by the object emitter
///     (`macho_symbol_name` prepends `_`; the ELF path likewise), resolved by
///     libSystem/libc at link, exactly like the allocator-shim `__rust_dealloc`
///     external call the `Box` drop path already emits and links. The byte length
///     is a wrapping `count * size_of::<T>()` — the same value LLVM passes to
///     `llvm.memcpy`; the intrinsic's contract guarantees it does not overflow for
///     a valid copy (a violation is UB either way).
fn lower_copy_nonoverlapping<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    copy: &mir::CopyNonOverlapping<'tcx>,
) -> Result<(), String> {
    // The element type comes from the `*const T` source pointer; `count` is in
    // ELEMENTS, not bytes.
    let src_ptr_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &copy.src)?);
    let elem_ty = match src_ptr_ty.kind() {
        ty::RawPtr(inner, _) => ctx.monomorphize_ty(*inner),
        _ => return Err("copy_nonoverlapping source is not a raw pointer".to_owned()),
    };
    let elem_size = layout_size_of(ctx, elem_ty)?;

    // A compile-time-constant count (if evaluable). Only such a count can drive
    // the proven fixed unroll below; a runtime `Copy(_local)` count falls through
    // to the `memcpy` call.
    let const_count = match &copy.count {
        Operand::Constant(count_c) => ctx
            .eval_const_operand(count_c)
            .try_eval_target_usize(ctx.tcx, ty::TypingEnv::fully_monomorphized()),
        _ => None,
    };

    // FAST PROVEN UNROLL: a bounded const count of a scalar-leaf element whose ONE
    // leaf covers the element's whole layout. `memory_scalar_leaf_ty` also answers
    // a synthetic CARRIER: a `Vec<T>` / `String` header (24 bytes) or a map maps to
    // a one-word `Ptr`, so an unroll keyed on it alone moved 8 of an element's 24
    // bytes -- the `ptr::copy_nonoverlapping(cur, hole, 1)` that compacts every kept
    // element of `Vec<String>::retain` left `{cap, <stale ptr>, <stale len>}`: a
    // wrong digest, then a trap freeing the stale pointer. Any element the leaf
    // does not cover takes the byte-exact `memcpy` below.
    if let Some(count) = const_count {
        if count <= 1024 {
            if let Ok(leaf_ty) = memory_scalar_leaf_ty(ctx.tcx, elem_ty).and_then(|leaf| {
                match trust_ir_leaf_byte_size(&leaf) {
                    Some(bytes) if bytes == elem_size => Ok(leaf),
                    other => Err(format!(
                        "scalar leaf {leaf:?} covers {other:?} of a {elem_size}-byte element"
                    )),
                }
            }) {
                // Source / destination first-element addresses (the `as_ptr()` /
                // `as_mut_ptr()` results).
                let src_base = lower_operand_to_value(ctx, body, block, &copy.src)?;
                let dst_base = lower_operand_to_value(ctx, body, block, &copy.dst)?;
                for i in 0..count {
                    let off = i
                        .checked_mul(elem_size)
                        .ok_or_else(|| "copy_nonoverlapping byte offset overflow".to_owned())?;
                    let s = iter_field_addr(ctx, block, src_base, off);
                    let v = emit_typed_load(ctx, block, s, leaf_ty.clone());
                    let d = iter_field_addr(ctx, block, dst_base, off);
                    emit_typed_store(block, d, leaf_ty.clone(), v);
                }
                return Ok(());
            }
        }
    }

    // GENERAL `memcpy` CALL: runtime count / non-scalar element / over-large unroll.
    let src_base = lower_operand_to_value(ctx, body, block, &copy.src)?;
    let dst_base = lower_operand_to_value(ctx, body, block, &copy.dst)?;
    let nbytes = memory_libcall_byte_count(ctx, body, block, &copy.count, elem_size)?;
    let memcpy = memory_libcall_callee(ctx, MemoryLibcall::Copy)?;
    let bytes = constant_memory_bytes(ctx, &copy.count, elem_size);
    note_memory_libcall_unwind(ctx, memcpy, MemoryLibcall::Copy, bytes);
    // C memcpy returns dst. Preserve that value in IR and intentionally leave
    // it unused: the Rust intrinsic itself still has no result.
    let unused_destination = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Call {
            callee: memcpy,
            args: vec![dst_base, src_base, nbytes],
        })
        .with_result(unused_destination),
    );
    Ok(())
}

/// Lower a `copy::<T>(src: *const T, dst: *mut T, count: usize)` intrinsic CALL —
/// the OVERLAPPING pointer copy (`core::intrinsics::copy` / `ptr::copy`). The
/// regions may overlap, so this lowers to the libc `memmove` (dst, src, n) — the
/// SAME linker-resolved-libcall path as the `memcpy` arm of `copy_nonoverlapping`
/// and exactly what rustc emits (`llvm.memmove`). `count` is in ELEMENTS; the byte
/// length is `count * size_of::<T>()`. No unrolled fast path: a forward
/// load/store loop would corrupt a `dst > src` overlap, and memmove is correct
/// for all overlap cases.
fn lower_copy_intrinsic<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 3 {
        return Err(format!(
            "copy intrinsic with {} args (expected src, dst, count)",
            call.args.len()
        ));
    }
    let elem_ty = ctx.monomorphize_ty(callee.args.type_at(0));
    let elem_size = layout_size_of(ctx, elem_ty)?;
    // Intrinsic arg order is (src, dst, count); memmove's is (dst, src, n).
    let src = lower_operand_to_value(ctx, body, block, &call.args[0].node)?;
    let dst = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let nbytes = memory_libcall_byte_count(ctx, body, block, &call.args[2].node, elem_size)?;
    let memmove = memory_libcall_callee(ctx, MemoryLibcall::Move)?;
    let bytes = constant_memory_bytes(ctx, &call.args[2].node, elem_size);
    note_memory_libcall_unwind(ctx, memmove, MemoryLibcall::Move, bytes);
    let unused_destination = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Call {
            callee: memmove,
            args: vec![dst, src, nbytes],
        })
        .with_result(unused_destination),
    );
    emit_call_successor(block, call.target);
    Ok(())
}

/// Lower a `write_bytes::<T>(dst: *mut T, val: u8, count: usize)` intrinsic CALL
/// (the real `ptr::write_bytes` / `<*mut T>::write_bytes`, and the `[T]::fill`
/// size-1 `SpecFill` specialization). Semantically a C `memset` of
/// `count * size_of::<T>()` bytes at `dst` to the byte `val`:
///
///     memset(dst, val, count * size_of::<T>())
///
/// Lowered to the libc `memset` symbol — the SAME linker-resolved-libcall path as
/// the `memcpy` general arm of `copy_nonoverlapping` (and `memcmp`/`fma`). This is
/// EXACTLY what rustc's own backend emits for `write_bytes` (`llvm.memset`), so it
/// is a faithful lowering with no re-derived byte loop and no new proof obligation
/// (the undefined `memset` callee is resolved by libSystem/libc at link, like the
/// `memcpy`/`memcmp` externals). The element type `T` is the intrinsic's single
/// generic arg; `count` is in ELEMENTS. `val` (a `u8`) is zero-extended to the
/// genuine C `int` lane. The C pointer return is retained and unused; the Rust
/// intrinsic remains unit-valued and control falls to its call successor.
fn lower_write_bytes_intrinsic<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<(), String> {
    if call.args.len() != 3 {
        return Err(format!(
            "write_bytes intrinsic with {} args (expected dst, val, count)",
            call.args.len()
        ));
    }
    // Element type `T` from the intrinsic's single generic arg (mirrors `raw_eq`/
    // the atomics); `count` is in ELEMENTS, so the byte length is `count * size`.
    let elem_ty = ctx.monomorphize_ty(callee.args.type_at(0));
    let elem_size = layout_size_of(ctx, elem_ty)?;

    let dst_ptr = lower_operand_to_value(ctx, body, block, &call.args[0].node)?;
    let dst_ptr = coerce_to_plain_ptr(ctx, block, dst_ptr);
    if ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?) != ctx.tcx.types.u8 {
        return Err("[TCG-MEM-LIBCALL-ABI] write_bytes fill is not u8".into());
    }
    let byte = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    // write_bytes' u8 converts to the real C int, never a made-up I64 lane.
    let c_int = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::ZExt,
            src_ty: TrustIrTy::U8,
            dst_ty: TrustIrTy::I32,
            operand: byte,
        })
        .with_result(c_int),
    );
    let nbytes = memory_libcall_byte_count(ctx, body, block, &call.args[2].node, elem_size)?;
    let memset = memory_libcall_callee(ctx, MemoryLibcall::Set)?;
    let bytes = constant_memory_bytes(ctx, &call.args[2].node, elem_size);
    note_memory_libcall_unwind(ctx, memset, MemoryLibcall::Set, bytes);
    let unused_destination = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Call {
            callee: memset,
            args: vec![dst_ptr, c_int, nbytes],
        })
        .with_result(unused_destination),
    );
    emit_call_successor(block, call.target);
    Ok(())
}
/// What a terminal consumer does with each yielded item.
enum ConsumerKind {
    /// `.sum()`: `acc += item` (integer add / IEEE FAdd from the `-0.0` identity).
    Sum,
    /// `.product()`: `acc *= item` (integer mul / IEEE FMul from the `1.0` identity).
    Product,
    /// `.count()`: `acc += 1` (ignore the item).
    Count,
    /// `.fold(init, f)`: `acc = f(acc, item)`.
    Fold { closure_ty_field: usize },
}

/// The arithmetic a `.sum()` / `.product()` reduction performs, decided by WHICH
/// `Sum` / `Product` IMPL is selected — never by the accumulator's trust-ir scalar
/// type.
///
/// # Why this exists (a live miscompile on the base, measured 2026-09-27)
///
/// Every `sum`/`product` consumer in this file used to admit ANY destination
/// whose `rust_ty_to_trust_ir_ty` is an integer or float and then emit a bare
/// `Add`/`Mul`. That type map collapses every single-scalar-leaf struct to its
/// leaf, so it cannot tell `u64` from `Saturating<u64>` from a user newtype —
/// and the interception replaces whatever `Sum` impl rustc selected with plain
/// wrapping arithmetic. Executed witnesses against the unpatched backend
/// (`-Copt-level=0`, LLVM is the oracle):
///
///   * a USER `impl Sum for Meters` (returns `max(1000, ..)`) over `[1, 2, 3]`:
///     LLVM `1000`, trust-cg `6` — the user's body was silently discarded;
///   * `Saturating<u64>` product of `[1<<40, 1<<40]`: LLVM `u64::MAX`, trust-cg
///     `0` — `saturating_mul` computed as a wrapping `Mul`;
///   * `u64` sum of `[u64::MAX - 1, 5]`: LLVM PANICS ("attempt to add with
///     overflow", `#[rustc_inherit_overflow_checks]` on std's closure), trust-cg
///     printed `3` and exited 0.
///
/// `String::push_str_slice` (a `library/alloc` census root) sums
/// `Saturating<usize>` precisely so that an overflow reaches `reserve()` as an
/// OOM instead of a wrapped, too-small capacity — admitting it to the old
/// consumer would have been a miscompile in exactly the case the code exists for.
///
/// # The identity argument
///
/// The accumulator `S` must be a primitive integer / float, `Wrapping<int>` or
/// `Saturating<int>` (the last two by DIAGNOSTIC-ITEM identity, which no other
/// crate can claim), AND the item must be `S` or `&S`. Under both conjuncts the
/// selected impl is `impl Sum<S> for S` / `impl Sum<&S> for S`, and coherence
/// lets ONLY the crate defining `Sum` write those: trait and every type are
/// foreign to any other crate (and `&` is fundamental over a foreign `S`). The
/// caller has already established that the terminal is the REAL std `Iterator`
/// method, so that crate is the real `core` and the arithmetic is core's.
/// Dropping the ITEM conjunct is not safe: `impl Sum<Local> for u64` IS legal in
/// a user crate (a local type argument satisfies the orphan rule).
///
/// # What happens to every OTHER impl
///
/// It is NOT replaced, and — for a direct `.sum()` / `.product()` call over a chain
/// the bridge models — it is NOT refused either: the interception steps aside
/// (`std_reduction_falls_through`) and the REAL `Iterator::sum` / `product` body
/// runs, calling the selected impl's own code — a user impl is lowered from its
/// own MIR; a core impl the step below does not model (`Saturating<u128>`) is
/// core's `iter.fold(zero, |a, b| a + b)`, whose `fold` the bridge drives over the
/// same modeled chain while calling core's REAL closure. A user `impl Sum` that
/// merely adds COMPILED and MATCHED on the base (by coincidence), and still does.
/// Only a reduction the bridge reached WITHOUT the call — an `-O3` fold-glue peel,
/// whose real `fold` / `spec_fold` / `rfold` body is a dead body (trapped in a
/// library crate type, refused in an executable) — is refused instead, with this
/// function's reason.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum StdReductionArith {
    /// `impl Sum for {integer}`: `a + b` / `a * b` under
    /// `#[rustc_inherit_overflow_checks]` — WRAPS with overflow checks off,
    /// PANICS with them on. `overflow_site` is the span whose `Location` that
    /// panic reports (`std_reduction_overflow_span`), present exactly when
    /// overflow checks are on.
    CheckedInt {
        overflow_site: Option<rustc_span::Span>,
    },
    /// `impl Sum for {float}`: IEEE `FAdd` / `FMul`.
    Float,
    /// `impl Sum for Wrapping<{integer}>`: `wrapping_add` / `wrapping_mul`.
    Wrapping,
    /// `impl Sum for Saturating<{unsigned}>`: `saturating_add` / `saturating_mul`.
    Saturating,
}

/// Decide the std `Sum`/`Product` arithmetic for accumulator `acc_ty` over items
/// of type `item_ty` (see [`StdReductionArith`] for the identity argument), or
/// refuse with a named reason. `what` is `"sum"` or `"product"`.
fn std_sum_product_arith<'tcx>(
    tcx: TyCtxt<'tcx>,
    acc_ty: Ty<'tcx>,
    item_ty: Ty<'tcx>,
    what: &str,
) -> Result<StdReductionArith, String> {
    let refuse = |why: &str| -> Result<StdReductionArith, String> {
        Err(format!(
            "[TCG-ITER-REDUCTION-IMPL] iterator `{what}` into `{acc_ty:?}` over items of type \
             `{item_ty:?}`: {why}. The bridge may replace a `{what}` reduction with its own \
             loop only when it KNOWS which arithmetic rustc selected: core's \
             `impl Sum<S> for S` / `impl Sum<&S> for S` for a primitive integer or float, \
             `Wrapping<int>` or `Saturating<unsigned>` — any other impl (a user newtype's, or \
             `impl Sum<Local> for u64`) has a body that loop would silently discard. A direct \
             `.{what}()` call over a modeled chain runs the real impl instead; this reduction \
             was reached some other way (an optimized fold-glue peel), where no real body is \
             safe to call. Ways forward: (1) write the reduction as an explicit `fold`, whose \
             closure is called for real; (2) build this crate with the LLVM backend (omit \
             `-Zcodegen-backend=trust-ir-cg`)"
        ))
    };
    // The item must be `S` or `&S` — see the ITEM conjunct above.
    let item_value_ty = match item_ty.kind() {
        ty::Ref(_, inner, _) => *inner,
        _ => item_ty,
    };
    if item_value_ty != acc_ty {
        return refuse("the item type is neither the accumulator type nor a reference to it");
    }
    match acc_ty.kind() {
        ty::Int(_) | ty::Uint(_) => {
            // With checks on, the panic reports the location of core's own
            // check, which a step that cannot name it would misreport.
            let overflow_site = if tcx.sess.overflow_checks() {
                match std_reduction_overflow_span(tcx, acc_ty, item_ty, what) {
                    Ok(span) => Some(span),
                    Err(why) => return refuse(&why),
                }
            } else {
                None
            };
            Ok(StdReductionArith::CheckedInt { overflow_site })
        }
        ty::Float(_) => Ok(StdReductionArith::Float),
        ty::Adt(adt, args) => {
            let did = adt.did();
            let int_payload = args
                .types()
                .next()
                .is_some_and(|t| matches!(t.kind(), ty::Int(_) | ty::Uint(_)));
            // (`std_def_is_interceptable`: a LOCAL `Wrapping` is the crate under
            // compilation's own type — never classified.)
            if !std_def_is_interceptable(tcx, did) || !int_payload {
                return refuse(
                    "the accumulator is not a primitive / `Wrapping` / `Saturating` integer",
                );
            }
            if Some(did) == tcx.get_diagnostic_item(rustc_span::Symbol::intern("Wrapping")) {
                Ok(StdReductionArith::Wrapping)
            } else if Some(did) == tcx.get_diagnostic_item(rustc_span::Symbol::intern("Saturating"))
            {
                Ok(StdReductionArith::Saturating)
            } else {
                refuse("the accumulator is a struct whose `Sum`/`Product` impl is not core's")
            }
        }
        _ => refuse("the accumulator is not a primitive integer or float"),
    }
}

/// The span whose `&'static Location` the overflow panic of core's
/// `impl Sum<A> for S` / `impl Product<A> for S` (`what` = `"sum"` /
/// `"product"`) reports: the overflow `Assert` of the
/// `#[rustc_inherit_overflow_checks] |a, b| a + b` (`a * b`) closure that impl
/// passes to `fold`, as rustc's `codegen_assert_terminator` reports it
/// (`Body::caller_location_span` of the closure's own body, which takes no
/// caller location; `span_as_caller_location` then climbs to the outermost
/// macro call site). A reduction step the bridge synthesizes raises at this
/// span, never at the reduction's call site.
///
/// The impl is the one rustc selects for `S: Sum<A>` (`codegen_select_candidate`),
/// the trait being the bound `Iterator::sum` / `product` puts on its own
/// parameter. `Err` names what was not found: the trait, a core impl, exactly
/// one closure of that impl's method, or exactly one overflow `Assert` of the
/// matching operator in that closure's MIR.
fn std_reduction_overflow_span<'tcx>(
    tcx: TyCtxt<'tcx>,
    acc_ty: Ty<'tcx>,
    item_ty: Ty<'tcx>,
    what: &str,
) -> Result<rustc_span::Span, String> {
    let named_fn = |container: DefId| {
        tcx.associated_items(container)
            .in_definition_order()
            .find(|item| item.is_fn() && item.name().as_str() == what)
            .map(|item| item.def_id)
    };
    let iterator = tcx
        .get_diagnostic_item(rustc_span::sym::Iterator)
        .ok_or_else(|| "core's overflow site: no `Iterator` trait".to_owned())?;
    let iter_method =
        named_fn(iterator).ok_or_else(|| format!("core's overflow site: no `Iterator::{what}`"))?;
    let parent_count = tcx.generics_of(iter_method).parent_count;
    let trait_did = predicate_queries::own(tcx, iter_method)
        .1
        .iter()
        .find_map(|(clause, _)| match clause.kind().skip_binder() {
            ty::ClauseKind::Trait(pred)
                if matches!(pred.self_ty().kind(), ty::Param(p) if p.index as usize >= parent_count)
                    && !tcx.is_lang_item(pred.def_id(), LangItem::Sized) =>
            {
                Some(pred.def_id())
            }
            _ => None,
        })
        .ok_or_else(|| {
            format!("core's overflow site: `Iterator::{what}` has no reduction bound")
        })?;
    let trait_ref =
        tcx.erase_and_anonymize_regions(ty::TraitRef::new(tcx, trait_did, [acc_ty, item_ty]));
    let Ok(rustc_middle::traits::ImplSource::UserDefined(selected)) = tcx
        .codegen_select_candidate(ty::TypingEnv::fully_monomorphized().as_query_input(trait_ref))
    else {
        return Err(format!(
            "core's overflow site: no impl selected for `{acc_ty:?}: {}<{item_ty:?}>`",
            tcx.item_name(trait_did)
        ));
    };
    if !is_real_std_crate_def(tcx, selected.impl_def_id) {
        return Err("core's overflow site: the selected impl is not core's".to_owned());
    }
    let impl_method = named_fn(selected.impl_def_id)
        .ok_or_else(|| format!("core's overflow site: the selected impl has no `{what}`"))?;
    let impl_body = tcx.optimized_mir(impl_method);
    let mut closures: Vec<DefId> = Vec::new();
    let mut note = |ty: Ty<'tcx>| {
        for inner in ty.walk().filter_map(|arg| arg.as_type()) {
            if let ty::Closure(closure, _) = inner.kind() {
                if tcx.parent(*closure) == impl_method && !closures.contains(closure) {
                    closures.push(*closure);
                }
            }
        }
    };
    for decl in impl_body.local_decls.iter() {
        note(decl.ty);
    }
    for data in impl_body.basic_blocks.iter() {
        if let TerminatorKind::Call { func, args, .. } = &data.terminator().kind {
            note(func.ty(impl_body, tcx));
            for arg in args.iter() {
                note(arg.node.ty(impl_body, tcx));
            }
        }
    }
    let [closure] = closures[..] else {
        return Err(format!(
            "core's overflow site: the selected `{what}` defines {} closures, not one",
            closures.len()
        ));
    };
    let op = if what == "product" {
        mir::BinOp::Mul
    } else {
        mir::BinOp::Add
    };
    let closure_body = tcx.optimized_mir(closure);
    let mut sites = closure_body.basic_blocks.iter().filter_map(|data| {
        let terminator = data.terminator();
        match &terminator.kind {
            TerminatorKind::Assert {
                msg, ..
            } if matches!(&**msg, mir::AssertKind::Overflow(o, ..) if *o == op) => {
                Some(terminator.source_info)
            }
            _ => None,
        }
    });
    let (Some(site), None) = (sites.next(), sites.next()) else {
        return Err(format!(
            "core's overflow site: the `{what}` closure has no single `{op:?}` overflow check"
        ));
    };
    Ok(closure_body.caller_location_span(site, None, tcx, |span| span))
}

/// Whether `emit_std_reduction_step` MODELS `arith` for this accumulator: unsigned
/// saturating add/mul and signed saturating ADD of at most 64 bits; every other
/// class unconditionally. `Err(reason)` otherwise — which the direct `sum` /
/// `product` interceptions turn into a step-aside to the real impl
/// (`std_reduction_falls_through`), and every other route into a refusal.
fn std_reduction_modeled(
    arith: StdReductionArith,
    is_product: bool,
    acc_ir: &TrustIrTy,
    ptr_bits: u32,
) -> Result<(), String> {
    let what = if is_product { "product" } else { "sum" };
    if arith != StdReductionArith::Saturating {
        return Ok(());
    }
    let width = acc_ir
        .bit_width_with(ptr_bits)
        .ok_or_else(|| format!("iterator {what}: accumulator has no bit width"))?;
    if width > 64 || (is_product && acc_ir.is_signed()) {
        // A SIGNED `saturating_mul` clamps by the sign of the TRUE product (both
        // operands), which the step does not model — core implements `Sum` /
        // `Product` for UNSIGNED `Saturating` only today, so this guards a future
        // impl, not a live shape — and the >64-bit clamp constants are not wired.
        return Err(format!(
            "[TCG-ITER-REDUCTION-IMPL] iterator `{what}` into `Saturating<{acc_ir:?}>`: only \
             unsigned saturating arithmetic (and signed saturating ADD) of an integer of at \
             most 64 bits is modeled; a wrapping stand-in would be a silent miscompile on \
             overflow. Ways forward: (1) write it as an explicit `fold`, whose closure is \
             called for real; (2) build this crate with the LLVM backend"
        ));
    }
    Ok(())
}

/// The STEP-ASIDE decision for a DIRECT `.sum()` (`is_product == false`) or
/// `.product()` terminal call over a chain `resolve_iter_chain` models: `Ok(true)`
/// when the selected impl's arithmetic is not one `emit_std_reduction_step`
/// models, so the interception must return `Ok(false)` and let the REAL
/// `Iterator::sum` / `product` body run — the selected impl's own code (see
/// `StdReductionArith`, "What happens to every OTHER impl"). Decided BEFORE any
/// instruction is emitted. `Ok(false)` for an unmodeled chain (the caller keeps its
/// own handling of those) and for a modeled reduction.
///
/// Sound to step aside ONLY because the chain is MODELED: the real body's next
/// hop is either a user impl (lowered from its own MIR, operating on the chain
/// through the same intercepted methods any user function receiving it uses) or
/// core's `iter.fold(..)`, which the bridge drives over that chain. For an
/// UNMODELED chain the real body bottoms out in the chain's own `fold` /
/// `try_fold`, which may be a dead body trapped in a library crate type — hence
/// the `Ok(false)` there.
fn std_reduction_falls_through<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    iter_ty: Ty<'tcx>,
    is_product: bool,
) -> Result<bool, String> {
    let Some(chain) = resolve_iter_chain(ctx, iter_ty)? else {
        return Ok(false);
    };
    let what = if is_product { "product" } else { "sum" };
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let arith = match std_sum_product_arith(ctx.tcx, dest_ty, chain.item.rust_ty, what) {
        Ok(arith) => arith,
        Err(_) => return Ok(true),
    };
    let Ok(acc_ir) = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty) else {
        return Ok(false);
    };
    let ptr_bits = u32::try_from(ctx.tcx.data_layout.pointer_size().bits())
        .map_err(|_| format!("iterator {what}: pointer width does not fit u32"))?;
    Ok(std_reduction_modeled(arith, is_product, &acc_ir, ptr_bits).is_err())
}

/// Emit ONE std `Sum` / `Product` step, `acc (+|*) item`, with the arithmetic
/// `arith` selects. `item` must already be converted to `acc_ir`.
///
/// May SPLIT `*block`: the overflow-checked integer form branches to the call's
/// panic/trap target on overflow, exactly as rustc's `#[rustc_inherit_overflow_checks]`
/// closure does, and on return `*block` is the no-overflow CONTINUATION (the
/// original block has been pushed to `ctx.extra_blocks`, ending in that `CondBr`).
/// Callers must therefore append everything after the step to `*block`.
#[allow(clippy::too_many_arguments)]
fn emit_std_reduction_step<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    arith: StdReductionArith,
    is_product: bool,
    acc_ir: &TrustIrTy,
    acc: ValueId,
    item: ValueId,
) -> Result<ValueId, String> {
    let what = if is_product { "product" } else { "sum" };
    let bin = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, op: TrustIrBinOp| {
        let r = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op,
                ty: acc_ir.clone(),
                lhs: acc,
                rhs: item,
            })
            .with_result(r),
        );
        r
    };
    let wrapping_op = if is_product {
        TrustIrBinOp::Mul
    } else {
        TrustIrBinOp::Add
    };
    match arith {
        StdReductionArith::Float => {
            if !acc_ir.is_float() {
                return Err(format!(
                    "iterator {what}: float impl over a non-float accumulator"
                ));
            }
            Ok(bin(
                ctx,
                block,
                if is_product {
                    TrustIrBinOp::FMul
                } else {
                    TrustIrBinOp::FAdd
                },
            ))
        }
        StdReductionArith::Wrapping => {
            if !acc_ir.is_integer() {
                return Err(format!(
                    "iterator {what}: Wrapping impl over a non-integer accumulator"
                ));
            }
            Ok(bin(ctx, block, wrapping_op))
        }
        StdReductionArith::CheckedInt { .. } if !ctx.tcx.sess.overflow_checks() => {
            // `-Coverflow-checks` off: rustc strips the closure's overflow assert
            // and the arithmetic wraps (the same removal `lower_assert_terminator`
            // applies).
            if !acc_ir.is_integer() {
                return Err(format!(
                    "iterator {what}: integer impl over a non-integer accumulator"
                ));
            }
            Ok(bin(ctx, block, wrapping_op))
        }
        StdReductionArith::CheckedInt { .. } | StdReductionArith::Saturating => {
            if !acc_ir.is_integer() {
                return Err(format!(
                    "iterator {what}: integer impl over a non-integer accumulator"
                ));
            }
            let ptr_bits = u32::try_from(ctx.tcx.data_layout.pointer_size().bits())
                .map_err(|_| format!("iterator {what}: pointer width does not fit u32"))?;
            let width = acc_ir
                .bit_width_with(ptr_bits)
                .ok_or_else(|| format!("iterator {what}: accumulator has no bit width"))?;
            let ov_op = if is_product {
                OverflowOp::MulOverflow
            } else {
                OverflowOp::AddOverflow
            };
            // REFUSE (never fall back to the wrapping op — what the base did: a
            // `Saturating<u64>` product of `[1 << 40, 1 << 40]` printed `0` where LLVM
            // prints `u64::MAX`) whatever `std_reduction_modeled` does not model. The
            // direct `sum`/`product` interceptions have already stepped aside for
            // those; this is the backstop for every other route.
            std_reduction_modeled(arith, is_product, acc_ir, ptr_bits)?;
            let wrapped = ctx.fresh_value();
            let overflow = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Overflow {
                    op: ov_op,
                    ty: acc_ir.clone(),
                    lhs: acc,
                    rhs: item,
                })
                .with_results([wrapped, overflow]),
            );
            refine_push_overflow(ctx, ov_op, acc_ir);
            if let StdReductionArith::CheckedInt { overflow_site } = arith {
                // `#[rustc_inherit_overflow_checks] |a, b| a + b` with checks ON:
                // overflow PANICS, reporting the location of core's own check
                // (`std_reduction_overflow_span`), not the reduction's call. The
                // raise calls the check's own `panic_const_*` entry with that
                // Location (`std_panic_route::StdFailure::OverflowAt`, OD-170),
                // honoring the call's unwind edge with the entry's actual unwind
                // permission; only `panic=immediate-abort` keeps the trap.
                let site = overflow_site.ok_or_else(|| {
                    format!(
                        "[TCG-ITER-REDUCTION-IMPL] iterator `{what}`: an overflow-checked step \
                         without the location of core's overflow check; failing closed"
                    )
                })?;
                let fail = std_panic_route::fail_target(
                    ctx,
                    body,
                    call,
                    std_panic_route::StdFailure::OverflowAt {
                        op: if is_product {
                            mir::BinOp::Mul
                        } else {
                            mir::BinOp::Add
                        },
                        span: site,
                    },
                )?;
                let cont_id = ctx.fresh_block_id();
                block.body.push(InstrNode::new(Inst::CondBr {
                    cond: overflow,
                    then_target: fail,
                    then_args: Vec::new(),
                    else_target: cont_id,
                    else_args: Vec::new(),
                }));
                let finished = std::mem::replace(block, Block::new(cont_id));
                ctx.extra_blocks.push(finished);
                return Ok(wrapped);
            }
            // SATURATING ADD / MUL. Unsigned (add and mul alike): on overflow the true
            // result exceeds MAX, clamp to MAX (all ones) — `saturating_mul` for an
            // unsigned integer is exactly `checked_mul().unwrap_or(MAX)`. Signed ADD
            // (the only signed form admitted above): overflow needs both operands of
            // the same sign, so the accumulator's sign names the direction — MIN if
            // negative, MAX otherwise. Mirrors `lower_saturating_method_call`, the
            // lowering of the very `saturating_add` core's `Saturating::add` calls.
            let konst = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, v: i128| {
                let c = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Const {
                        ty: acc_ir.clone(),
                        value: Constant::Int(v),
                    })
                    .with_result(c),
                );
                c
            };
            let clamp = if acc_ir.is_signed() && !is_product {
                let zero = konst(ctx, block, 0);
                let is_neg = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Slt,
                        ty: acc_ir.clone(),
                        lhs: acc,
                        rhs: zero,
                    })
                    .with_result(is_neg),
                );
                let maxc = konst(ctx, block, (1i128 << (width - 1)) - 1);
                let minc = konst(ctx, block, -(1i128 << (width - 1)));
                let c = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: acc_ir.clone(),
                        cond: is_neg,
                        then_val: minc,
                        else_val: maxc,
                    })
                    .with_result(c),
                );
                c
            } else {
                konst(ctx, block, (1i128 << width) - 1)
            };
            let result = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: acc_ir.clone(),
                    cond: overflow,
                    then_val: clamp,
                    else_val: wrapped,
                })
                .with_result(result),
            );
            Ok(result)
        }
    }
}

/// `true` iff `t` is one of the std STATELESS adapter fold-glue closures
/// (`iter::adapters::{map::map_fold, filter::filter_fold, copied::copy_fold}::
/// {closure#0}`) — the per-element composition rustc's `-O3` specialization
/// threads a `fold`/`rfold` payload through. Recognized by the closure's PARENT
/// item name in a std crate, exactly like `peel_fold_glue_to_sum`'s glue match.
/// `enumerate` glue is EXCLUDED: it captures a running count (direction-
/// dependent), so it must never be driven backwards.
fn is_adapter_rfold_glue_closure<'tcx>(tcx: TyCtxt<'tcx>, t: Ty<'tcx>) -> bool {
    let ty::Closure(cdef, _) = t.kind() else {
        return false;
    };
    // (`std_def_is_interceptable`: a local glue closure is never modeled.)
    std_def_is_interceptable(tcx, *cdef)
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        && is_real_std_crate_def(tcx, *cdef)
        && matches!(
            tcx.item_name(tcx.parent(*cdef)).as_str(),
            "map_fold" | "filter_fold" | "copy_fold"
        )
}

/// Recognize an `-O3` fold-glue closure (`copy_fold`/`map_fold`) whose inner fold
/// closure `G` is a `Sum` add-closure. On success, append the hidden adapter the
/// glue represents (`.copied()` / `.map(F)`) onto `chain` and return `Some("sum")`
/// so the consumer drives it as a sum — reconstructing the SAME logical chain the
/// `-O0` path already compiles == LLVM (`Copied<I>.sum()` / `Map<I,F>.sum()`).
/// Returns `None` (leaving the caller to fail closed) for ANY other glue, a
/// capturing (non-ZST) glue closure, a non-`Sum` inner closure, a tuple item, or an
/// unrepresentable map output — a wrong recognizer would silently compute the wrong
/// reduction, so the default is to reject.
fn peel_fold_glue_to_sum<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    chain: &mut IterChain<'tcx>,
    glue: Ty<'tcx>,
    glue_is_const: bool,
) -> Option<&'static str> {
    // A `sum`/`product` inner fold closure — the recursion's base case.
    let reduction_of = |t: &Ty<'tcx>| -> Option<&'static str> {
        let ty::Closure(d, _) = t.kind() else {
            return None;
        };
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        if !is_real_std_crate_def(ctx.tcx, *d) {
            // A USER-crate closure whose PARENT fn happens to be named `sum`/
            // `product` is NOT the std reduce — treating it as one would
            // silently commute an order-sensitive fold (adversarial-review
            // finding). User glue falls through to the order-preserving routes.
            return None;
        }
        // `opt_item_name` (not `item_name`): the parent may be ANOTHER CLOSURE
        // (a nested user `fold(.., |..| inner.fold(..))`), and `item_name` ICEs
        // on a closure DefPath. A closure parent is never a std `sum`/`product`
        // reduce, so `None` (bail) is correct — the caller falls back to the
        // order-preserving route (which fail-closes on the nested capturing fold).
        match ctx
            .tcx
            .opt_item_name(ctx.tcx.parent(*d))
            .as_ref()
            .map(|n| n.as_str())
        {
            Some("sum") => Some("sum"),
            Some("product") => Some("product"),
            _ => None,
        }
    };
    // Peel nested glue closures OUTER→INNER (the outer glue is the SOURCE-adjacent
    // adapter). `.filter(p).copied().sum()` inlines at `-O3` to
    // `filter_fold(P, copy_fold(sum))` → adapters `[Filter{P}, Copied]` + sum;
    // `.map(f).filter(p).sum()` → `map_fold(F, filter_fold(P, sum))` → `[Map{F},
    // Filter{P}]` + sum. Accumulate the hidden adapters WITHOUT mutating `chain`
    // until the WHOLE chain is recognized — the caller falls back to `name` on
    // `None`, so a partial peel must leave `chain` untouched.
    let mut pending: Vec<(ChainAdapter<'tcx>, u64)> = Vec::new();
    let mut item = chain.item.clone();
    let mut cur = glue;
    let reduce = loop {
        // Depth backstop (a real chain is short; a runaway means an unexpected shape).
        if pending.len() > 8 {
            return None;
        }
        let ty::Closure(cdef, cargs) = cur.kind() else {
            return None;
        };
        // `opt_item_name` (not `item_name`): the closure's parent may itself be a
        // CLOSURE — a nested user `fold(.., |..| inner.fold(..))` reaches here with
        // `cur` = the inner fold's closure whose parent is the OUTER fold closure,
        // and `item_name` ICEs on a closure DefPath (rustc panic, not a clean
        // fail-close). A closure/anonymous parent is never a std adapter glue, so
        // bail — the caller falls back to the general (fail-closing) route.
        let Some(glue_name) = ctx.tcx.opt_item_name(ctx.tcx.parent(*cdef)) else {
            return None;
        };
        // Every peelable adapter glue is a ZST closure EXCEPT the `.enumerate()`
        // glue (`Enumerate::fold::enumerate::{closure#0}`), which captures a
        // `usize` running count (non-ZST) and is handled — with a const-operand
        // (count == 0) gate — in the match below.
        if glue_name.as_str() != "enumerate" && !is_zero_sized_ty(ctx.tcx, cur) {
            return None;
        }
        let closure_args = cargs.as_closure();
        let parent_args = closure_args.parent_args();
        // `G` = the LAST closure-typed arg (the inner fold closure); the adapter's own
        // closure (`F`/`P`) is the earlier non-`G` closure, if any.
        let g = parent_args
            .iter()
            .filter_map(|a| a.as_type())
            .rev()
            .find(|t| matches!(t.kind(), ty::Closure(..)))?;
        let non_g = || {
            parent_args
                .iter()
                .filter_map(|a| a.as_type())
                .find(|t| matches!(t.kind(), ty::Closure(..)) && *t != g)
        };
        let (kind, closure_ty, output) = match glue_name.as_str() {
            // `copy_fold<T, Acc, G>` → `.copied()` over a `&T` (deref) item.
            "copy_fold" => {
                let elem_ir = match &item.deref_elem_ir {
                    Some(e) => e.clone(),
                    None if item.tuple.is_none() => item.ir_ty.clone(),
                    None => return None,
                };
                // The element `T` (see the `Copied` arm of `resolve_iter_chain`).
                let out = ChainItem {
                    rust_ty: item.rust_ty.builtin_deref(true).unwrap_or(item.rust_ty),
                    ir_ty: elem_ir.clone(),
                    deref_elem_ir: None,
                    tuple: None,
                };
                (AdapterKind::Copied { elem_ir }, ctx.tcx.types.unit, out)
            }
            // `map_fold<T, B, Acc, F, G>` → `.map(F)`. `F` = the non-`G` closure; ZST
            // (no captures) only. The peeled `Map` is the SAME adapter `-O0` builds;
            // its ZST closure is called with an ignored env pointer.
            "map_fold" => {
                // A tuple item (from a peeled `.enumerate()`) is allowed IFF the
                // tuple is a by-value memory aggregate the shared `Map` emit arm
                // can build (`build_tuple_item_arg`); `F` then collapses it to a
                // scalar (`bit_width` checked below).
                if item.tuple.is_some()
                    && !matches!(
                        memory_aggregate_layout_shared(ctx.tcx, item.rust_ty),
                        Ok(Some(_))
                    )
                {
                    return None;
                }
                let f = non_g()?;
                if !is_zero_sized_ty(ctx.tcx, f) {
                    return None;
                }
                let ty::Closure(_, fargs) = f.kind() else {
                    return None;
                };
                let sig = ctx
                    .tcx
                    .instantiate_bound_regions_with_erased(fargs.as_closure().sig());
                let out_ty = ctx.monomorphize_ty(sig.output());
                let out_ir = rust_ty_to_trust_ir_ty(ctx.tcx, out_ty).ok()?;
                if out_ir.bit_width().is_none() {
                    return None;
                }
                let out = ChainItem {
                    rust_ty: out_ty,
                    ir_ty: out_ir,
                    deref_elem_ir: None,
                    tuple: None,
                };
                (AdapterKind::Map, f, out)
            }
            // `filter_fold<T, Acc, P, G>` → `.filter(P)`. `P` = the non-`G` (ZST)
            // predicate; Filter leaves the item type unchanged (a `&T` item stays
            // `&T`, then an inner `copy_fold` derefs it).
            "filter_fold" => {
                if item.tuple.is_some() {
                    return None;
                }
                let p = non_g()?;
                if !is_zero_sized_ty(ctx.tcx, p) {
                    return None;
                }
                (AdapterKind::Filter, p, item.clone())
            }
            // `.enumerate()` inlines at `-O3` to `<inner>::fold(0, enumerate::
            // {closure#0})` whose glue is a NON-ZST closure capturing a `usize`
            // running count (always 0 for a fresh `.enumerate()`, materialized as a
            // CONST operand) plus the inner fold glue `G` (ZST). Model it as an
            // `Enumerate` adapter over a FRESH standalone counter slot (allocated
            // post-peel in `lower_iter_consumer` — a bare source's chain slot has
            // no count field; `u64::MAX` sentinel), turning the scalar item into a
            // `(usize, item)` tuple; the loop then peels `G` (the map_fold that
            // collapses the tuple).
            "enumerate" => {
                if !glue_is_const {
                    // A runtime (partially-advanced) enumerate glue captures a
                    // count != 0 we would ignore — fail closed.
                    return None;
                }
                if item.tuple.is_some() {
                    // Nested enumerate (tuple-of-tuple) is not modeled.
                    return None;
                }
                // A `&T` (slice) item is allowed: `val_item` keeps its pointer
                // representation + `deref_elem_ir`, and the shared Map emit path
                // (`build_tuple_item_arg`) already threads pointer lanes — the
                // SAME machinery the `-O0` resolve-built [Enumerate, Map] slice
                // chain exercises (validated there).
                let usize_ty = ctx.tcx.types.usize;
                // Loaded at `usize_field_ty`, as in `resolve_iter_chain`.
                let idx_item = ChainItem {
                    rust_ty: usize_ty,
                    ir_ty: usize_field_ty(ctx.tcx),
                    deref_elem_ir: None,
                    tuple: None,
                };
                let val_item = item.clone();
                let tuple_rust_ty = Ty::new_tup(ctx.tcx, &[usize_ty, item.rust_ty]);
                let out = ChainItem {
                    rust_ty: tuple_rust_ty,
                    ir_ty: TrustIrTy::I64,
                    deref_elem_ir: None,
                    tuple: Some((Box::new(idx_item), Box::new(val_item))),
                };
                (
                    AdapterKind::Enumerate {
                        // "standalone; allocate a counter slot post-peel" — a real
                        // layout offset can never be u64::MAX, and `shift_offsets`
                        // never runs on a peel-produced adapter.
                        count_off: u64::MAX,
                        counter_slot: None,
                    },
                    ctx.tcx.types.unit,
                    out,
                )
            }
            _ => return None,
        };
        pending.push((
            ChainAdapter {
                kind,
                closure_ty,
                input: item.clone(),
                output: output.clone(),
            },
            0u64,
        ));
        item = output;
        // Base case: `G` is a Sum/Product reduce closure → the chain is fully peeled.
        if let Some(r) = reduction_of(&g) {
            break r;
        }
        // Otherwise `G` must itself be a nested glue closure — peel it next.
        cur = g;
    };
    // Commit — the whole nested chain is recognized (adapters in source→sink order).
    for a in pending {
        chain.adapters.push(a);
    }
    chain.item = item;
    Some(reduce)
}

/// Why an `rfold` std sum/product (`.rev()...sum()` / `.product()` at `-O2`+) that
/// must be driven BACK TO FRONT, and could not be, is refused rather than driven
/// forward (see `rfold_reduction_order_blind`).
const RFOLD_ORDER_REFUSAL: &str = "[TCG-ITER-RFOLD-ORDER] a reversed `sum`/`product` (an `rfold` over a std Sum/Product \
     closure) must visit its items BACK TO FRONT, as rustc's `rfold` does: its arithmetic \
     is order-sensitive (the integer impl is overflow-CHECKED under `-Coverflow-checks` / \
     `-Cdebug-assertions`, so which PARTIAL result overflows depends on the order), or the \
     chain calls a `map`/`filter` closure per item, whose effects happen in call order. \
     Driving the forward chain instead — this backend's shortcut for order-blind \
     reductions — would abort a program LLVM runs (or run one LLVM aborts) and reorder \
     those effects. Ways forward: (1) drop the `.rev()` where the order does not \
     matter to the program; (2) build this crate with the LLVM backend (omit \
     `-Zcodegen-backend=trust-ir-cg`).";

/// Whether an `rfold` std sum/product may be driven FRONT TO BACK (the forward-drive
/// shortcut of `lower_iterator_call`'s `rfold` route) instead of in rfold's own
/// BACK-TO-FRONT order without any observable difference. `chain` is the PEELED
/// probe chain (receiver adapters plus the adapters hidden in the fold glue);
/// `reduce` is `"sum"` or `"product"`. `false` means "drive it back to front".
///
/// The route's old premise was "an integer sum/product is commutative +
/// associative". Two things break it, and BOTH must be ruled out here:
///
///   (1) THE ARITHMETIC (`std_sum_product_arith`). Core's integer impl is
///       `#[rustc_inherit_overflow_checks] |a, b| a + b`: with overflow checks ON it
///       panics the first time a PARTIAL result overflows, and the partial results
///       depend on the order — measured: `v.iter().rev().map(|&x| x).sum::<i64>()`
///       on `[i64::MAX, 1, -1]` is `i64::MAX` under LLVM (back to front: -1, 0,
///       MAX) and a forward drive traps on `MAX + 1`; `[-1, 1, i64::MAX]` is the
///       other way round. Order-blind: `Wrapping` (modular), the checked impl with
///       overflow checks OFF (it wraps — the same), and UNSIGNED `Saturating` (add
///       and mul both compute `min(MAX, true result)`, or `0` once a factor is `0`,
///       whatever the order). NOT order-blind: the checked impl with checks ON, and
///       a SIGNED `Saturating` add (`[MAX, 1, -1]` gives `MAX - 1` forward, `MAX`
///       backward; core has no such impl today, so this guards a future one). A
///       float never reaches this route (the caller requires an integer
///       accumulator).
///   (2) USER CODE CALLED PER ITEM. Every `map` / `filter` closure the chain
///       carries is CALLED once per item, in drive order. The peel's ZST gate does
///       not make it pure — a capture-free closure can print, write a static or
///       panic — so a forward drive reorders those effects. Measured on the base
///       at `-O3` (no proof certificates): `.rev().map(|&x| { print!("{x} "); x
///       }).sum()` printed `1 2 3 4` where LLVM prints `4 3 2 1`, over slice,
///       `Range`, `RangeInclusive`, `zip` and `chain` sources, `map` and `filter`,
///       `sum` and `product`. Order-blind only when every adapter is a `Copied` (a
///       deref of a core-classified `S` or `&S`, pinned by (1)) or a `Map` /
///       `Filter` whose closure body `closure_body_is_effect_free` proves has no
///       effect at all.
fn rfold_reduction_order_blind<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    chain: &IterChain<'tcx>,
    dest_ty: Ty<'tcx>,
    reduce: &str,
) -> bool {
    let Ok(arith) = std_sum_product_arith(ctx.tcx, dest_ty, chain.item.rust_ty, reduce) else {
        // Not a reduction the consumer models at all: it refuses on either drive,
        // with `std_sum_product_arith`'s own reason. Take the order-preserving one.
        return false;
    };
    let arith_order_blind = match arith {
        StdReductionArith::Wrapping => true,
        StdReductionArith::CheckedInt { .. } => !ctx.tcx.sess.overflow_checks(),
        // `std_sum_product_arith` classified `dest_ty` as `Saturating<T>`; order-blind
        // for an UNSIGNED `T` only.
        StdReductionArith::Saturating => matches!(
            dest_ty.kind(),
            ty::Adt(_, args) if args.types().next().is_some_and(|t| matches!(t.kind(), ty::Uint(_)))
        ),
        StdReductionArith::Float => false,
    };
    arith_order_blind
        && chain.adapters.iter().all(|(a, _)| match a.kind {
            AdapterKind::Copied { .. } => true,
            AdapterKind::Map | AdapterKind::Filter => {
                closure_body_is_effect_free(ctx.tcx, a.closure_ty)
            }
            _ => false,
        })
}

/// Whether calling the capture-free closure `closure_ty` can have NO effect but its
/// return value — so calling it on the same items in another ORDER is unobservable
/// (`rfold_reduction_order_blind`'s user-code conjunct). Decided on the closure's
/// own optimized MIR, and `false` for anything it cannot see into:
///   * any `Call`, `TailCall`, `Drop`, `Assert` (a panic — its message depends on
///     which item fails first), `InlineAsm`, `Yield` or unwind terminator, i.e.
///     anything but `Goto` / `SwitchInt` / `Return` / `Unreachable` — except an
///     `Assert` that is an overflow check this crate's codegen ELIDES
///     (`assert_is_elided_overflow_check`: `-Coverflow-checks=off`). Core's
///     `#[rustc_inherit_overflow_checks]` operator impls keep that assert in the
///     MIR of every closure they are inlined into (`|(x, y)| x * y` over two
///     `&u64`), and counting it as an effect refused order-blind chains the
///     forward drive compiled and matched;
///   * any store THROUGH a pointer (an `Assign` or `SetDiscriminant` whose place
///     has a `Deref` projection) — a capture-free closure owns no memory but its
///     locals, so every other store is to a local;
///   * any statement that is not a plain assignment or pure bookkeeping
///     (`StorageLive/Dead`, `Nop`, `FakeRead`, `PlaceMention`,
///     `AscribeUserType`, `Coverage`, `ConstEvalCounter`, an `assume` intrinsic).
///
/// READS are allowed — through the item reference, or of a static — because no
/// closure in an order-blind chain writes anything, so every read sees the same
/// memory in either order.
fn closure_body_is_effect_free<'tcx>(tcx: TyCtxt<'tcx>, closure_ty: Ty<'tcx>) -> bool {
    let ty::Closure(def_id, _) = closure_ty.kind() else {
        return false;
    };
    if !tcx.is_mir_available(*def_id) {
        return false;
    }
    let mir = tcx.optimized_mir(*def_id);
    let stores_through_pointer = |place: &Place<'_>| {
        place
            .projection
            .iter()
            .any(|p| matches!(p, ProjectionElem::Deref))
    };
    mir.basic_blocks.iter().all(|bb| {
        let statements_pure = bb.statements.iter().all(|stmt| match &stmt.kind {
            StatementKind::Assign(boxed) => !stores_through_pointer(&boxed.0),
            StatementKind::SetDiscriminant { place, .. } => !stores_through_pointer(place),
            StatementKind::Intrinsic(intrinsic) => {
                matches!(&**intrinsic, mir::NonDivergingIntrinsic::Assume(_))
            }
            StatementKind::StorageLive(_)
            | StatementKind::StorageDead(_)
            | StatementKind::Nop
            | StatementKind::FakeRead(..)
            | StatementKind::PlaceMention(..)
            | StatementKind::AscribeUserType(..)
            | StatementKind::Coverage(..)
            | StatementKind::ConstEvalCounter => true,
            _ => false,
        });
        statements_pure
            && match &bb.terminator().kind {
                TerminatorKind::Goto { .. }
                | TerminatorKind::SwitchInt { .. }
                | TerminatorKind::Return
                | TerminatorKind::Unreachable => true,
                // An overflow check this crate's codegen drops never fires.
                TerminatorKind::Assert { msg, .. } => assert_is_elided_overflow_check(tcx, msg),
                _ => false,
            }
    })
}

/// The panic core raises once a wasm32 `count()` passes `usize::MAX` (2^32 - 1)
/// items, or `None` where the count wraps or cannot overflow.
///
/// `Range::count` and `RangeInclusive::count` are `steps_between(..)` followed by
/// `.expect("count overflowed usize")`, a panic under every overflow-check
/// setting, and `Copied`/`Cloned`/`Enumerate`/`Skip` forward `count()` to their
/// inner iterator. A slice count is its length. `Chain::count` is
/// `a.count() + b.count()` under `#[rustc_inherit_overflow_checks]`: with
/// overflow checks on, a chain of halves that cannot overflow alone panics with
/// the checked add exactly when its total passes `usize::MAX`, which the per-item
/// checked increment reproduces; with them off the sum wraps. Every other count
/// that reaches the
/// model is core's `fold(0, |c, _| c + 1)` (the default `count`, and the
/// `count::plus_one` fold routes) or `Filter`'s `map(..).sum()`, both under
/// `#[rustc_inherit_overflow_checks]`: a panic with overflow checks on, a
/// wrapping count with them off.
///
/// `call` is the intercepted call: only a direct `count` call selects the
/// source's own `count`; a `fold`/`rfold`/`spec_fold` with `count::plus_one` is
/// the default count's fold. A direct count over a `Chain` with a half that can
/// itself pass `usize::MAX` (a 64-bit `Range`, a 32-bit or wider
/// `RangeInclusive`), or with a half that is neither a range nor a slice, is
/// refused under every overflow-check setting: core panics
/// in that half's `count()` with its own message, which the per-item model
/// cannot tell from the sum's checked add (checks on) or wrap (checks off).
///
/// On a 64-bit target the per-item model would need 2^64 iterations to reach
/// the overflow, so callers apply this on wasm32 only and native objects are
/// unchanged.
fn wasm32_count_overflow_panic<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
) -> Result<Option<CountOverflow>, String> {
    let checked = || {
        ctx.tcx
            .sess
            .overflow_checks()
            .then_some(CountOverflow::CheckedAdd)
    };
    let callee_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, call.func)?);
    let direct_count = matches!(callee_ty.kind(), ty::FnDef(did, _)
        if callee_item_name_str(ctx.tcx, *did) == "count");
    let forwards_to_source = direct_count
        && !chain.reversed
        && chain.rev_clamp.is_none()
        && chain.adapters.iter().all(|(a, _)| {
            matches!(
                a.kind,
                AdapterKind::Copied { .. }
                    | AdapterKind::Enumerate { .. }
                    | AdapterKind::Skip { .. }
            )
        });
    if !forwards_to_source {
        return Ok(checked());
    }
    // Whether a chain half's own `count()` can exceed a 32-bit `usize`: a
    // slice count is its length, so it cannot; any other half is unknown.
    let half_can_overflow = |source: &ChainSource<'tcx>| -> Option<bool> {
        let bits = |t: &TrustIrTy| t.bit_width_with(32).unwrap_or(u32::MAX);
        match source {
            ChainSource::Range { ir_ty, .. } => Some(bits(ir_ty) > 32),
            ChainSource::RangeInclusive { ir_ty, .. } => Some(bits(ir_ty) >= 32),
            ChainSource::Slice { .. } => Some(false),
            _ => None,
        }
    };
    match &chain.source {
        // A range of at most 32-bit items (16-bit for an inclusive one) holds
        // at most `usize::MAX` of them, so its `expect` can never fire and the
        // per-item check would only cost a compare in every iteration.
        ChainSource::Range { .. } | ChainSource::RangeInclusive { .. }
            if half_can_overflow(&chain.source) == Some(false) =>
        {
            Ok(None)
        }
        ChainSource::Range { .. } | ChainSource::RangeInclusive { .. } => {
            Ok(Some(CountOverflow::Expect))
        }
        ChainSource::Concat { first, second, .. } => {
            if half_can_overflow(first) != Some(false) || half_can_overflow(second) != Some(false) {
                return Err(
                    "[TCG-ITER-UNMODELED] wasm32 `count()` over a `chain` whose half \
                     can itself count past `usize::MAX`: core panics in that half's \
                     `count()` (\"count overflowed usize\"), which the per-item count \
                     model does not distinguish from the halves' sum overflowing — \
                     failing closed"
                        .to_owned(),
                );
            }
            // `a_count + b_count` inherits overflow checks: checked, it panics
            // once the total passes `usize::MAX`; unchecked, it wraps.
            Ok(checked())
        }
        ChainSource::Slice { .. } | ChainSource::Zip { .. } => Ok(None),
    }
}

/// How core's `count()` reports the overflow `wasm32_count_overflow_panic`
/// models; the raise is derived from std's MIR (`std_panic_route`).
#[derive(Clone, Copy)]
enum CountOverflow {
    /// The `#[rustc_inherit_overflow_checks]` `c + 1` overflow assertion.
    CheckedAdd,
    /// `Range::count`'s `.expect(..)` on `steps_between`'s upper bound.
    Expect,
}

impl CountOverflow {
    fn failure<'tcx>(self) -> std_panic_route::StdFailure<'tcx> {
        match self {
            CountOverflow::CheckedAdd => std_panic_route::StdFailure::Overflow(mir::BinOp::Add),
            CountOverflow::Expect => std_panic_route::StdFailure::Constant,
        }
    }
}

/// `acc + step` for a count that panics through `overflow` when it overflows
/// `acc_ir` (`wasm32_count_overflow_panic`). Splits `block`: the overflow edge
/// goes to std's own raise for it (`std_panic_route`), and `block` continues
/// in the non-overflow successor.
#[allow(clippy::too_many_arguments)]
fn emit_count_increment_or_panic<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    acc_ir: &TrustIrTy,
    acc: ValueId,
    step: ValueId,
    overflow_route: CountOverflow,
) -> Result<ValueId, String> {
    let wrapped = ctx.fresh_value();
    let overflow = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Overflow {
            op: OverflowOp::AddOverflow,
            ty: acc_ir.clone(),
            lhs: acc,
            rhs: step,
        })
        .with_results([wrapped, overflow]),
    );
    refine_push_overflow(ctx, OverflowOp::AddOverflow, acc_ir);
    let fail = std_panic_route::fail_target(ctx, body, call, overflow_route.failure())?;
    let cont_id = ctx.fresh_block_id();
    block.body.push(InstrNode::new(Inst::CondBr {
        cond: overflow,
        then_target: fail,
        then_args: Vec::new(),
        else_target: cont_id,
        else_args: Vec::new(),
    }));
    let finished = std::mem::replace(block, Block::new(cont_id));
    ctx.extra_blocks.push(finished);
    Ok(wrapped)
}

/// Lower a terminal consumer (`.sum()` / `.fold(init, f)` / `.count()`) over a
/// Range / slice / Map / Filter chain: synthesize the driving loop directly.
///
/// The loop's carried state is memory-backed (the iterator chain slot + a fresh
/// accumulator slot), so no phi nodes are needed. The current block initializes
/// the slots and branches to the loop header; the synthesized header / body /
/// exit blocks (appended to `ctx.extra_blocks`) run the chain's `next` and the
/// accumulation; the exit block binds the destination scalar and branches to the
/// call's normal successor.
fn lower_iter_consumer<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
    // `true` when routed from `<I as DoubleEndedIterator>::rfold`: drive the
    // resolved chain BACKWARDS (flip `reversed`), mirroring
    // `lower_iter_try_fold(reverse = true)`.
    reverse: bool,
) -> Result<bool, String> {
    // Std fold glue can retain the aggregate mapper after its Map receiver
    // has been peeled. Preserve its real tuple ABI before resolving a scalar
    // chain, peeling glue, allocating state or emitting any drive.
    if real_body_iterator_receiver(ctx, body, call)? {
        return Ok(false);
    }
    // Optimized for_each becomes fold((), ..). Unit has no value lane:
    // drive its callback through the same void-consumer path, using the
    // callback's actual FnAbi and the same owned-environment cleanup.
    if name == "fold" && !reverse && call.args.len() == 3 {
        let dest = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
        let init = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
        let payload = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[2].node)?);
        let unit = |ty: Ty<'tcx>| matches!(ty.kind(), ty::Tuple(fields) if fields.is_empty());
        if unit(dest) && unit(init) && matches!(payload.kind(), ty::Closure(..)) {
            return lower_iter_void_consumer(ctx, body, block, call, 2, "Iterator::fold(unit)");
        }
    }
    // The self iterator is arg 0 (by value). Resolve its chain.
    let Some(self_arg) = call.args.first() else {
        return Ok(false);
    };
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
    let Some(mut chain) = resolve_iter_chain(ctx, self_ty)? else {
        return Ok(false);
    };
    // The consumer owns `self`; its exit releases only the owning source.
    refuse_unlowered_consumed_iterator_drop(
        ctx.tcx,
        &chain,
        self_ty,
        "iterator `self`",
        &format!("Iterator::{name}"),
    )?;

    // FOLD-GLUE PEEL (report Phase 2, SAFE SUBSET `copy_fold -> Sum`). At `-O3`,
    // rustc's specialized `<Copied<I> as Iterator>::sum` inlines to
    // `<I as Iterator>::fold(0, iter::adapters::copied::copy_fold::<T,Acc,G>::{closure#0})`
    // over the BARE inner source `I` — so `resolve_iter_chain` sees only `I` (e.g.
    // `slice::Iter`) and the `.copied()` + the `Sum` reduction are hidden inside the
    // glue closure, which would otherwise lower as an independent mono item and fail
    // closed. Reconstruct the logical `Copied<I>.sum()` chain the `-O0` path already
    // compiles: recognize the glue by its parent fn name, append a `Copied` adapter,
    // and drive as `sum`. STRICTLY GATED — only `copy_fold` whose inner fold closure
    // `G` is a `Sum`/`Product` add-closure; `map_fold`, Filter glue, nested chains,
    // capturing (non-ZST) glue, and any arg-shape mismatch stay FAIL-CLOSED (a wrong
    // recognizer would silently compute the wrong reduction, so default to reject).
    // A TUPLE-yielding chain (a `Zip` source: `<Zip as ZipImpl>::fold(self, 0,
    // map_fold_glue)`) is peelable too — the peel's `map_fold` arm accepts a tuple
    // item iff it is a memory aggregate the shared Map emit path can build, and
    // every other arm rejects tuples; an unpeeled tuple chain then fails closed at
    // the tuple gate below exactly as before.
    // `<Zip as ZipImpl>::count()` (and other tuple-chain counts) inline at `-O3`
    // to `fold(0, count::plus_one)` with a bare FnDef payload — COUNT ignores the
    // items, so a tuple-yielding chain is fine: recognize the std `plus_one`
    // exactly like the `spec_fold`/`rfold` count routes do.
    let name = if name == "fold" && !reverse && call.args.len() == 3 {
        let payload_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[2].node)?);
        // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
        let is_plus_one = matches!(payload_ty.kind(), ty::FnDef(fdef, _)
            if is_real_std_crate_def(ctx.tcx, *fdef)
                && ctx.tcx.def_path_str(*fdef).ends_with("count::plus_one"));
        if is_plus_one {
            "count"
        } else {
            let glue = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[2].node)?);
            // Whether the glue operand is a compile-time CONSTANT: the enumerate peel
            // arm requires it (a const enumerate glue has count == 0; a runtime `move`
            // glue could carry a partially-advanced nonzero count → fail closed).
            let glue_is_const = matches!(call.args[2].node, Operand::Constant(_));
            peel_fold_glue_to_sum(ctx, &mut chain, glue, glue_is_const).unwrap_or(name)
        }
    } else {
        name
    };

    // REVERSE drive (routed from an `rfold` whose payload composes STATELESS
    // per-element adapters): flip `reversed`, mirroring `lower_iter_try_fold`'s
    // reverse block. The flip commutes ONLY with stateless adapters (Map /
    // Filter / Copied) — a bounded-count adapter (take/skip/step_by) or an
    // `Enumerate` counter is direction-dependent WHEREVER it sits, so reject
    // UNCONDITIONALLY (Enumerate is NOT in `is_count_modifier`; name it
    // explicitly). A `RangeInclusive` source reverses as std's
    // `spec_next_back` (see `emit_source_next`). A double reversal over a
    // stateless chain cancels forward.
    if reverse {
        // A below-rev `.take(n)`/`.skip(k)` over a bare slice source: rewrite
        // into the boundary clamp instead of rejecting (the drive-preheader
        // `emit_rev_clamp` below applies it to the slot).
        rewrite_below_rev_bounded(&mut chain);
        if chain.adapters.iter().any(|(a, _)| {
            a.kind.is_count_modifier()
                || matches!(
                    a.kind,
                    AdapterKind::Enumerate { .. }
                        | AdapterKind::FilterMap
                        | AdapterKind::TakeWhile { .. }
                        | AdapterKind::Scan { .. }
                )
        }) {
            return Err(format!(
                "iterator reverse {name} over a take/skip/step_by/enumerate/filter_map/\
                 take_while/scan chain (none is modeled back to front)"
            ));
        }
        chain.reversed = !chain.reversed;
    }
    if !call.destination.projection.is_empty() {
        return Err(format!("iterator {name} into projected destination"));
    }
    // A chain that still yields a TUPLE (`.enumerate()` / `.zip()` with no
    // collapsing `.map`) can only be consumed by `count` (which ignores the item).
    // `sum`/`fold` over a tuple item are not modeled (fail closed).
    if chain.item.tuple.is_some() && name != "count" {
        return Err(format!(
            "iterator {name} over a tuple-yielding chain is not modeled"
        ));
    }

    // The chain state slot: the arg-0 iterator local's slot (it is `move`d in, so
    // mutating it in place is sound — the source is dead after the call).
    //
    // A CONSTANT self (`Range::fold(const Range { 0, 10 }, ..)` — rustc const-folds
    // a literal-bound chain's source at `-O3`): materialize the const's in-memory
    // image into a FRESH private slot and drive over it (fresh => no #111 aliasing;
    // the image encodes start/end at rustc's layout offsets).
    let chain_slot = if let Operand::Constant(_) = &self_arg.node {
        let state_size = iter_state_slot_size(ctx, self_ty)?;
        let lanes = state_size.div_ceil(8).max(1);
        let slot = ctx.fresh_value();
        let count = emit_i64_const(ctx, block, i128::from(lanes));
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: TrustIrTy::I64,
                count: Some(count),
                align: Some(8),
            })
            .with_result(slot),
        );
        if !store_const_aggregate_bytes_into_memory_at(
            ctx,
            block,
            slot,
            0,
            self_ty,
            &self_arg.node,
        )? {
            return Err(format!(
                "iterator {name} constant self image is not materializable"
            ));
        }
        slot
    } else {
        let (Operand::Copy(src) | Operand::Move(src)) = &self_arg.node else {
            return Err(format!("iterator {name} self argument is not a place"));
        };
        if !src.projection.is_empty() {
            return Err(format!("iterator {name} self argument is projected"));
        }
        let orig_chain_slot = ctx
            .memory_slots
            .get(&src.local)
            .cloned()
            .ok_or_else(|| format!("iterator {name} self argument is not memory-backed"))?
            .ptr;

        // #111 — PRIVATE iterator-state copy. The consumer DRAINS the chain state in
        // place. At O3, rustc's CSE/GVN can fold two structurally-identical source-init
        // sequences (`let a = (1..n).sum(); let b = (1..n).sum();`) into ONE memory slot,
        // so BOTH consumers resolve the SAME slot — the first drains it and the second
        // reduces over an exhausted iterator (sum -> 0, product -> 1, count -> 0). Copy
        // the resolved slot's bytes into a FRESH private alloca and drive over the copy;
        // the original is never mutated, so an O3-aliased slot is safe. See the matching
        // copy in `lower_iter_terminal`. (O0 already gives distinct slots — a no-op there.)
        copy_iter_state_to_private_slot(ctx, block, self_ty, orig_chain_slot)?
    };

    // A rewritten below-rev take/skip: clamp the slot boundary BEFORE driving
    // (idempotent; the O0 rev ctor already clamped, an O3-inlined ctor did not).
    emit_rev_clamp(ctx, block, &chain, chain_slot)?;
    emit_take_tra_fold_clamp(ctx, block, &chain, chain_slot, TakeFoldRoute::Fold)?;

    // Determine the consumer kind and the accumulator type.
    // The std `Sum`/`Product` arithmetic, decided by IMPL IDENTITY
    // (`std_sum_product_arith`) — `Some` exactly for the `sum`/`product` arms.
    let mut reduction_arith: Option<StdReductionArith> = None;
    // `Some(message)` when a `count` past a 32-bit `usize::MAX` panics
    // (`wasm32_count_overflow_panic`).
    let mut count_overflow: Option<CountOverflow> = None;
    let (consumer, acc_ir, acc_rust): (ConsumerKind, TrustIrTy, Ty<'tcx>) = match name {
        "sum" => {
            // `sum::<S>()` — the accumulator is the sum type `S`, the destination.
            let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
            let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty)?;
            // Admit an INTEGER OR a FLOAT (`FAdd`, IEEE-754, the
            // same left-fold order rustc's `Sum for f32/f64` uses: `-0.0 + x0 + x1 +
            // …`) accumulator. The accumulator is a memory-backed slot threaded by
            // load/store across the loop back-edge (NOT an SSA phi), so the float
            // recurrence is carried correctly without phi reconstruction. Anything
            // else (a `Ptr`/`Bool`/`i128`-wide leaf) fails closed.
            if !acc_ir.is_integer() && !acc_ir.is_float() {
                return Err("iterator sum over a non-integer/non-float accumulator".to_owned());
            }
            // WHICH arithmetic is decided by the selected `Sum` impl, not by
            // `acc_ir` — a scalar-mapped `S` may be `Saturating<_>` or a user
            // newtype (see `StdReductionArith` for the executed witnesses).
            reduction_arith = Some(std_sum_product_arith(
                ctx.tcx,
                dest_ty,
                chain.item.rust_ty,
                "sum",
            )?);
            (ConsumerKind::Sum, acc_ir, dest_ty)
        }
        "product" => {
            // `product::<P>()` — the accumulator is `P` (the destination); integer
            // or float (`FMul`, the same left-fold rustc's
            // `Product for f32/f64` uses from the `1.0` identity).
            let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
            let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty)?;
            if !acc_ir.is_integer() && !acc_ir.is_float() {
                return Err("iterator product over a non-integer/non-float accumulator".to_owned());
            }
            reduction_arith = Some(std_sum_product_arith(
                ctx.tcx,
                dest_ty,
                chain.item.rust_ty,
                "product",
            )?);
            (ConsumerKind::Product, acc_ir, dest_ty)
        }
        "count" => {
            let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
            let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty)?;
            if !acc_ir.is_integer() {
                return Err("iterator count into a non-integer destination".to_owned());
            }
            if session_is_wasm32(ctx.tcx) {
                count_overflow = wasm32_count_overflow_panic(ctx, body, call, &chain)?;
            }
            (ConsumerKind::Count, acc_ir, dest_ty)
        }
        "fold" => {
            // `fold(self, init, f)`: arg 1 is the init accumulator, arg 2 the
            // closure. The accumulator type is the destination type.
            if call.args.len() != 3 {
                return Err(format!("iterator fold with {} args", call.args.len()));
            }
            let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
            let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty)?;
            if acc_ir.bit_width().is_none() {
                return Err("iterator fold over a non-scalar accumulator".to_owned());
            }
            (
                ConsumerKind::Fold {
                    closure_ty_field: 2,
                },
                acc_ir,
                dest_ty,
            )
        }
        _ => return Ok(false),
    };
    // The accumulator is held by the drive while the chain's adapter closures
    // run; one that needs drop would be skipped by their unwind.
    refuse_droppable_carry_across_payloads(
        ctx,
        call.unwind,
        Some(acc_rust),
        chain_calls_user_code(&chain),
        &format!("iterator `{name}`'s accumulator"),
    )?;
    // The consumer owns the iterator: an unwind out of the drive frees it.
    let drive = begin_consumed_owner_drive(ctx, call, &chain, chain_slot, None)?;

    // For `fold`, resolve the closure and — for a CAPTURING (non-ZST) closure —
    // materialize its env slot pointer ONCE here in the preheader (the env is
    // loop-invariant). A non-capturing ZST closure needs no env (a dummy
    // `chain_slot` pointer is passed only because the body declares a `&self`
    // param it never reads). `closure_env_ptr` fail-closes if the capturing env
    // is not a memory-backed slot / supported reference, so an unmodeled capture
    // shape REFUSES rather than reading garbage — no miscompile surface.
    // RETRY NOTE (2026-07-17): the first landing attempt was reverted when the
    // multi-closure fuzz found captured TERMINAL-RESULT locals reading garbage —
    // root-caused NOT to this change but to the intercepted terminals never
    // storing an address-taken destination's scalar cell (fixed via
    // `finish_assign_target` at the 5 bind sites, eb622aa). With the cell fix
    // landed, a by-ref-captured fold/sum result reads its (now populated) cell.
    let (fold_closure_ty, fold_env_ptr) = if let ConsumerKind::Fold { closure_ty_field } = &consumer
    {
        let recv = &call.args[*closure_ty_field].node;
        let cty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, recv)?);
        if !matches!(cty.kind(), ty::Closure(..) | ty::FnDef(..)) {
            return Err("iterator fold payload is not a closure or function item".to_owned());
        }
        let env = if is_zero_sized_ty(ctx.tcx, cty) {
            None
        } else {
            Some(closure_env_ptr(ctx, body, block, recv)?)
        };
        (Some(cty), env)
    } else {
        (None, None)
    };
    // The consumer owns its by-value payload arguments. A capturing `fold` closure
    // with drop glue is dropped once, after the drive (the exit block below) or when
    // a call in the drive unwinds (the cleanup opened below, which then enters the
    // consumed-owner pad's release); every other owned argument must have no glue.
    let fold_closure_drop = match (&consumer, fold_closure_ty, fold_env_ptr) {
        (ConsumerKind::Fold { closure_ty_field }, Some(cty), Some(env)) => owned_closure_drop_plan(
            ctx,
            &call.args[*closure_ty_field].node,
            cty,
            env,
            &format!("Iterator::{name}"),
        )?,
        _ => None,
    };
    for (index, arg) in call.args.iter().enumerate().skip(1) {
        if matches!(consumer, ConsumerKind::Fold { closure_ty_field } if closure_ty_field == index)
            && fold_closure_drop.is_some()
        {
            continue;
        }
        // `fold`'s initial accumulator (argument 1) is not a value the callee
        // drops when it returns: it becomes the result, which this lowering
        // binds to the destination. The drive carries it across its payload
        // calls, so an unwind out of an adapter closure would skip its drop;
        // `refuse_droppable_carry_across_payloads` (above) refuses exactly that
        // under `panic=unwind`, and a `fold` closure that unwinds owns the
        // accumulator it was passed.
        if matches!(consumer, ConsumerKind::Fold { .. }) && index == 1 {
            continue;
        }
        let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &arg.node)?);
        refuse_unlowered_owned_drop(
            ctx.tcx,
            arg_ty,
            &format!("argument {index}"),
            &format!("Iterator::{name}"),
        )?;
    }
    let closure_drive = begin_owned_closure_drive(ctx, fold_closure_drop.as_ref(), &call.unwind)?;

    // The accumulator's INITIAL VALUE (live SSA — E2: the accumulator is a
    // loop-carried header block param, not an alloca; this value becomes the
    // preheader's entry branch argument). `sum`/`count` start at 0; `fold` at
    // the init operand (arg 1).
    let init_val = match &consumer {
        ConsumerKind::Sum | ConsumerKind::Count => {
            // `sum` starts at the additive identity; `count` at `0`. For a FLOAT
            // accumulator the identity rustc's `Sum for f32/f64` uses is NEGATIVE
            // zero `-0.0`, NOT `+0.0` — std's impl is `iter.fold(-0.0, Add::add)`.
            // This is observable: an EMPTY float sum returns `-0.0` (bits
            // 0x8000…) and `[-0.0].iter().sum() == -0.0` (since `-0.0 + -0.0 ==
            // -0.0` but `+0.0 + -0.0 == +0.0`). Initializing to `+0.0` would
            // bit-mismatch LLVM in exactly these cases, so use `-0.0`.
            let zero = ctx.fresh_value();
            let zero_const = if acc_ir.is_float() {
                Constant::Float(-0.0)
            } else {
                Constant::Int(0)
            };
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: acc_ir.clone(),
                    value: zero_const,
                })
                .with_result(zero),
            );
            zero
        }
        ConsumerKind::Product => {
            // `product` starts at the multiplicative identity `1` (integer) / `1.0`
            // (float — rustc's `Product for f32/f64` is `fold(1.0, Mul::mul)`).
            let one = ctx.fresh_value();
            let one_const = if acc_ir.is_float() {
                Constant::Float(1.0)
            } else {
                Constant::Int(1)
            };
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: acc_ir.clone(),
                    value: one_const,
                })
                .with_result(one),
            );
            one
        }
        ConsumerKind::Fold { .. } => lower_operand_to_value(ctx, body, block, &call.args[1].node)?,
    };
    // A `Range` run (only `Skip` / `Take` adapters, plus `Enumerate` for `count`,
    // over a `Range` / `RangeInclusive`) over this PRIVATE slot: its windows are
    // applied in O(1) first, as core's `Skip` skips with one source `nth`, so
    // the drive walks only the items that remain. core's `count` of it is O(1)
    // too: the count starts at its closed form and the drive pulls nothing.
    if chain_is_range_run(&chain, matches!(consumer, ConsumerKind::Count)) {
        let _ = emit_range_run_normalize(ctx, block, &chain, chain_slot);
    }
    let init_val = match &consumer {
        ConsumerKind::Count => {
            match emit_range_run_count_closed_form(ctx, body, block, call, &chain, chain_slot)? {
                Some(count) if acc_ir.bit_width() == Some(64) => {
                    let result = ctx.fresh_value();
                    block.body.push(
                        InstrNode::new(Inst::Copy {
                            ty: acc_ir.clone(),
                            operand: count,
                        })
                        .with_result(result),
                    );
                    result
                }
                Some(count) => convert_scalar(ctx, block, count, &TrustIrTy::I64, &acc_ir),
                None => init_val,
            }
        }
        _ => init_val,
    };

    // A peeled `.enumerate()` adapter (`count_off == u64::MAX`) has no count field
    // in the bare source's chain slot; give it a FRESH counter slot initialized to
    // 0 (the fresh-enumerate start count — the peel's const-glue gate guarantees
    // it), incremented in place across the drive loop.
    for (adapter, _) in chain.adapters.iter_mut() {
        if let AdapterKind::Enumerate {
            count_off,
            counter_slot,
        } = &mut adapter.kind
        {
            if *count_off == u64::MAX && counter_slot.is_none() {
                let slot = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Alloca {
                        ty: usize_field_ty(ctx.tcx),
                        count: None,
                        align: None,
                    })
                    .with_result(slot),
                );
                let zero = emit_usize_field_const(ctx, block, 0);
                emit_typed_store(block, slot, usize_field_ty(ctx.tcx), zero);
                *counter_slot = Some(slot);
            }
        }
    }

    // E3 — the source cursor as a loop-carried header param with the invariant
    // bound hoisted to the preheader (Range fwd/rev + slice-fwd sources only;
    // `None` keeps the v1 Slot fallback). SOUND here because this consumer's
    // chain slot is a FRESH PRIVATE copy (#111 above) or a const image: nothing
    // else reads or writes it, so the never-written-back cursor is unobservable.
    // The advance commits on EVERY header re-entry edge (body back-edge AND
    // Filter-reject/Skip-discard/StepBy-re-pull — the element is consumed even
    // when filtered). Adapter state (Take/Skip counts, StepBy state,
    // Enumerate counters) is never governed by the cursor mode and stays
    // memory-backed in the chain slot. An owning source whose elements need drop
    // keeps the Slot cursor: the exit drops the unyielded `[ptr, end)` it reads
    // back from the slot (`emit_consumed_chain_drop`).
    let cursor_pre = if chain_owns_droppable_elements(ctx.tcx, &chain) {
        None
    } else {
        emit_source_cursor_preheader(ctx, &chain, chain_slot, block)?
    };
    // `count` ignores its items, and std drops each one as it is counted.
    let count_drop = if matches!(consumer, ConsumerKind::Count) {
        discard_drop_plan(ctx, block, &chain.item, "count")?
    } else {
        None
    };

    // === Header block: loop-carried params ([cursor,] acc), then the chain's
    // `next`; its `found` block IS the consumer body and its `not_found` block
    // IS the exit — no cont block, no scratch-slot round-trip. ===
    let header_id = ctx.fresh_block_id();
    let mut header = Block::new(header_id);
    let mut entry_args: Vec<ValueId> = Vec::new();
    let cursor_mode = match &cursor_pre {
        Some((cursor0, bound, cursor_ir)) => {
            let cursor_param = ctx.fresh_value();
            header.params.push((cursor_param, cursor_ir.clone()));
            entry_args.push(*cursor0);
            SourceCursor::Params {
                cursor: cursor_param,
                bound: *bound,
            }
        }
        None => SourceCursor::Slot,
    };
    // E2 — the accumulator as a loop-carried header block param (the same block
    // param API entry blocks use).
    let acc_param = ctx.fresh_value();
    header.params.push((acc_param, acc_ir.clone()));
    entry_args.push(init_val);

    let out = emit_chain_next(
        ctx,
        &chain,
        chain_slot,
        block,
        &mut header,
        header_id,
        &[acc_param],
        &cursor_mode,
    )?;
    ctx.extra_blocks.push(header);

    // The preheader branches into the loop header with the initial carried state
    // (emitted AFTER `emit_chain_next` so the E4 hoisted invariant addresses land
    // before the terminator).
    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: entry_args,
    }));

    // === Body block (the chain's `found` block): accumulate the live item,
    // branch back to the header with the advanced carried state. ===
    let mut body_block = Block::new(out.found_id);
    // The yielded item representation: a scalar, or (for a `&T` item, e.g. a
    // slice element with no `map`) a pointer — live SSA defined in the chain
    // blocks, which dominate the body. `scalar_item` is the value side: deref
    // the pointer for a reference item.
    let item_repr = out.item[0];
    let scalar_item = if let Some(elem_ir) = &chain.item.deref_elem_ir {
        emit_typed_load(ctx, &mut body_block, item_repr, elem_ir.clone())
    } else {
        item_repr
    };
    let scalar_item_ir = chain
        .item
        .deref_elem_ir
        .clone()
        .unwrap_or_else(|| chain.item.ir_ty.clone());
    let acc = acc_param;
    let new_acc = match &consumer {
        ConsumerKind::Sum | ConsumerKind::Product => {
            // `acc + item` / `acc * item` with the arithmetic of the `Sum`/`Product`
            // impl rustc SELECTED (`std_sum_product_arith`): IEEE `FAdd`/`FMul` for a
            // float — the same left-associative fold from the `-0.0` / `1.0` identity
            // rustc's impls use, so bit-identical to LLVM's; for an integer, the
            // overflow-CHECKED op (a panic on overflow under `-Coverflow-checks`,
            // exactly `#[rustc_inherit_overflow_checks] |a, b| a + b`), the wrapping
            // op for `Wrapping`, the saturating add for `Saturating`. Before
            // 2026-09-27 this was a bare wrapping `Add`/`Mul` for all of them.
            // (`convert_scalar` is the identity here: the impl-identity gate pins
            // the item to `S`/`&S`, whose scalar IS `acc_ir`.) May split
            // `body_block` (the overflow check) — everything below appends to it.
            let arith = reduction_arith
                .ok_or_else(|| format!("iterator {name}: reduction arithmetic unresolved"))?;
            let item_conv =
                convert_scalar(ctx, &mut body_block, scalar_item, &scalar_item_ir, &acc_ir);
            emit_std_reduction_step(
                ctx,
                body,
                &mut body_block,
                call,
                arith,
                matches!(consumer, ConsumerKind::Product),
                &acc_ir,
                acc,
                item_conv,
            )?
        }
        ConsumerKind::Count => {
            if let Some(plan) = &count_drop {
                emit_discard_drop(ctx, &mut body_block, plan, item_repr);
            }
            let one = ctx.fresh_value();
            body_block.body.push(
                InstrNode::new(Inst::Const {
                    ty: acc_ir.clone(),
                    value: Constant::Int(1),
                })
                .with_result(one),
            );
            match count_overflow {
                None => {
                    let r = ctx.fresh_value();
                    body_block.body.push(
                        InstrNode::new(Inst::BinOp {
                            op: TrustIrBinOp::Add,
                            ty: acc_ir.clone(),
                            lhs: acc,
                            rhs: one,
                        })
                        .with_result(r),
                    );
                    r
                }
                Some(overflow_route) => emit_count_increment_or_panic(
                    ctx,
                    body,
                    &mut body_block,
                    call,
                    &acc_ir,
                    acc,
                    one,
                    overflow_route,
                )?,
            }
        }
        ConsumerKind::Fold { .. } => {
            // `acc = f(acc, item)`: a two-argument closure. The closure body ABI is
            // `(&env, acc, item) -> acc`. The closure receives `Self::Item`, which
            // is the item REPRESENTATION (the `&T` pointer for a reference item).
            let cty = fold_closure_ty.unwrap();
            // A non-capturing ZST closure passes the dummy `chain_slot` (unread);
            // a capturing closure passes its real, loop-invariant env slot pointer
            // (materialized once in the preheader above).
            let env_ptr = fold_env_ptr.unwrap_or(chain_slot);
            let (instance, call_args) = if let Some(item) = fn_items::view(cty.kind()) {
                // A function item's type identifies its target; its zero-sized
                // value carries no environment argument.
                let instance = Instance::expect_resolve(
                    ctx.tcx,
                    ty::TypingEnv::fully_monomorphized(),
                    item.def_id(),
                    item.require_unbound_args("iterator fold function item")?,
                    rustc_span::DUMMY_SP,
                );
                // Each value is built by the one closure-argument builder
                // against the item's own `FnAbi`.
                let mut call_args = closure_body_call_args_from_values(
                    ctx,
                    &mut body_block,
                    instance,
                    None,
                    vec![acc, item_repr],
                )?;
                if instance_abi_has_caller_location(ctx.tcx, instance) {
                    // `fold` calls its `F: FnMut` payload through
                    // `<F as FnMut>::call_mut`, which for a fn item is rustc's
                    // `FnPtrShim`: it passes the constant `Location` of its own
                    // call span, `def_span(FnMut::call_mut)`.
                    call_args.push(fn_mut_shim_caller_location(ctx, &mut body_block, instance)?);
                }
                (instance, call_args)
            } else {
                let instance = owned_closure_body_instance(ctx, cty, fold_closure_drop.as_ref())?;
                refuse_unthreaded_caller_location(ctx.tcx, instance)?;
                // The env arg is passed only when the body declares one, and each
                // value by the one closure-argument builder.
                let call_args = closure_body_call_args_from_values(
                    ctx,
                    &mut body_block,
                    instance,
                    Some(env_ptr),
                    vec![acc, item_repr],
                )?;
                (instance, call_args)
            };
            let callee = ctx.extern_callee(instance)?;
            let r = ctx.fresh_value();
            // The fold payload may PANIC: honor the intercepted terminator's
            // cleanup edge (FUZZ-8 [TCG-EH-INTERCEPT-CLEANUP]).
            push_unwindable_intercept_call(ctx, &mut body_block, callee, call_args, Some(r));
            r
        }
    };
    // Back-edge: thread the advanced cursor (Params mode) + the new accumulator
    // as the header's block-param arguments — no store, no reload.
    let mut back_args: Vec<ValueId> = Vec::new();
    if let Some(advanced) = out.cursor_advanced {
        back_args.push(advanced);
    }
    back_args.push(new_acc);
    body_block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: back_args,
    }));
    ctx.extra_blocks.push(body_block);
    closure_drive.end(ctx);

    // === Exit block (the chain's `not_found` block): drop the owned `fold`
    // closure, then a consumed owning source (the callee drops its parameters in
    // reverse order: `f` before `self`); the final accumulator IS the header's acc
    // param (the header dominates the exit), bind the destination, branch to the
    // call's successor. ===
    let mut exit_block = Block::new(out.not_found_id);
    emit_owned_closure_drop(ctx, &mut exit_block, fold_closure_drop.as_ref(), call)?;
    drive.end(ctx);
    emit_consumed_chain_drop(ctx, &mut exit_block, &chain, chain_slot)?;
    // An ADDRESS-TAKEN destination (a later `&dest` borrow or a by-REF closure
    // capture) reads through its canonical backing store — a scalar CELL
    // (`scalar_cells`) or a memory slot — NOT the SSA binding. A bare
    // `bind_scalar_value` leaves that backing store as uninitialized frame
    // garbage. Repro class (P0, 2026-07-17): `let first: i64 = a.iter().sum();`
    // captured by a non-`move` adapter closure (`.map(|&y| y ^ first)`) — the env
    // holds `&first` (the CELL address), the chain-`next` derefs it, and reads
    // garbage. Route through `finish_assign_target` — the SAME primitive every
    // plain call/cast/binop assignment uses — which stores into the cell (celled
    // dest) or records the SSA binding (plain dest). The memory-slot arm is kept
    // as well for a memory-backed (non-celled) destination.
    if let Some(slot) = ctx.memory_slots.get(&call.destination.local).cloned() {
        emit_typed_store(&mut exit_block, slot.ptr, acc_ir.clone(), acc_param);
    }
    finish_assign_target(
        ctx,
        body,
        &mut exit_block,
        call.destination,
        AssignTarget {
            value: acc_param,
            binding: ScalarPlaceBinding::Local(call.destination.local),
            preserve_self_borrow: false,
        },
    )?;
    if let Some(target) = call.target {
        exit_block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        exit_block.body.push(InstrNode::new(Inst::Unreachable));
    }
    ctx.extra_blocks.push(exit_block);

    Ok(true)
}

/// A BOUNDED `flat_map` terminal (`.sum()` / `.count()` / `.fold(init, f)`):
/// DRIVE a `FlatMap<Range<T>, Range<T>, F>` (`resolve_flatmap_bounded` matches)
/// to exhaustion with a DEDICATED two-level nested loop, bypassing
/// `lower_iter_consumer`/`emit_chain_next`/`AdapterKind` entirely.
///
/// WHY a separate driver: `emit_chain_next`'s contract is "pull ONE source
/// element, thread it through ≤1 adapter per element, land in EXACTLY ONE
/// `found`/`not_found` block pair per pull" — every existing `AdapterKind`
/// (Map/Filter/Copied/Take/Skip/StepBy/Enumerate/FilterMap/TakeWhile/Scan)
/// satisfies "≤1 item out per ≤1 item pulled". `flat_map` is "0..N items out
/// per 1 outer pull" — the `found` step must be re-entered a VARIABLE number of
/// times per outer element, continuing into a DIFFERENT block (the inner
/// header) than a plain re-pull of the outer source. Extending
/// `emit_chain_next`'s single `(found_id, not_found_id)` contract to express
/// that would break it for every other adapter, so — exactly as
/// `lower_chain_ctor`/`lower_zip_ctor` already bypass `AdapterKind` for THEIR
/// non-conforming shapes (`Chain`/`Zip` are not "1 in -> ≤1 out" either) — this
/// is a wholly separate, hand-built two-level loop using the SAME low-level
/// `Block`/block-param/`CondBr`/`Br` primitives `emit_chain_next` itself is
/// built from.
///
/// The drive follows std's `FlattenCompat::iter_fold` (which `fold`, `sum` and
/// `count` all reach): the `frontiter` range first, then every outer element's
/// inner range, then the `backiter` range. Each of the three sits in an `Option`
/// in std's layout (`FlatMapStdLayout`); a `None` contributes an empty range, so
/// a `FlatMap` that std code already advanced (a `next` left `frontiter` set, a
/// `next_back` set `backiter`) is folded exactly as std folds it.
///
/// Block layout (7 fresh blocks + the caller's still-open preheader block):
///
///   preheader (`block`, still open): from the private `#111` copy of the
///     `FlatMap`, read the three `Option` tags and the `{start, end}` of each
///     range, substituting the empty range `0..0` for a `None`; branch into
///     `inner_header` with `[front_start, front_end, outer_start, init_val]`, so
///     the front range drains first and then hands over to `outer_header`.
///
///   outer_header(outer_cur, acc): loop-carried `[outer_cur, acc]`.
///     `cond = outer_cur < outer_end` (loop-invariant `outer_end`, hoisted to
///     the preheader). `condbr cond -> outer_body : back_header(back_start,
///     acc)`.
///
///   outer_body: `x = outer_cur`; `outer_next = outer_cur + 1` (commits
///     IMMEDIATELY, every re-entry — the same "advance commits on every header
///     re-entry" convention `Filter`'s reject edge / `StepBy`'s re-pull already
///     use); call `F(x)` (a ZST-env closure call whose declared return `U ==
///     Range<T>` is a 2-field AGGREGATE — `emit_closure_call_n` already handles
///     an aggregate-returning callee generically, since its `result` is just
///     the opaque SysV register-pair/sret value `Inst::Call` produces, exactly
///     like `lower_memory_aggregate_call`'s own call result); `ExtractField`
///     the two `Range<T>` lanes (`{start,end}`, replicating
///     `lower_memory_aggregate_call`'s lane-relocation pattern verbatim); `br
///     inner_header(inner_start, inner_end, outer_next, acc)`.
///
///   inner_header(inner_cur, inner_end, outer_next, acc): FOUR loop-carried
///     params, ALL freshly-minted `ctx.fresh_value()` IDs distinct from
///     `outer_header`'s by construction (the state-clobber guarantee: no shared
///     SSA name, no byte-level slot aliasing — `inner_start`/`inner_end` come
///     from an `ExtractField` on a closure-call result, never written back into
///     the chain slot). `cond2 = inner_cur < inner_end`. `condbr cond2 ->
///     inner_body : outer_header(outer_next, acc)` — inner-exhausted re-enters
///     the OUTER header with the ALREADY-advanced outer cursor + the inner
///     loop's final accumulator.
///
///   inner_body: `new_acc = accumulate(acc, inner_cur)` (Sum/Count/Fold — the
///     SAME arithmetic `lower_iter_consumer` uses, duplicated rather than
///     shared: this driver's block SHAPE is entirely different, so sharing
///     would couple two independently-verified drivers through a helper
///     neither fully controls — a wrong shared helper risks BOTH silently).
///     `inner_next = inner_cur + 1`; `br inner_header(inner_next, inner_end,
///     outer_next, new_acc)`.
///
///   back_header(back_cur, acc) / back_body: the same accumulate loop over the
///     `backiter` range (loop-invariant `back_end`); exhausted -> `exit`.
///
///   exit: the final result is `acc` AS BOUND ON back_header's FALSE edge —
///     `back_header` dominates `exit` (its only predecessor), so `exit`'s body
///     is just an unconditional `Br` to the call's successor and the
///     destination local is bound directly to that `acc` param value, exactly
///     matching `lower_iter_consumer`'s own exit-block convention.
///
/// Correctness (nested order): the ONLY edge back into `outer_header` is
/// `inner_header`'s exhausted (false) edge — so outer element `x`'s ENTIRE
/// inner range is fully drained before `outer_header` is ever re-entered for
/// `x + 1`, matching flat_map's defined "all inner ys for x, then x+1"
/// semantics exactly (verified against the LLVM oracle for an ORDER-SENSITIVE
/// weighted `fold` in the differential test suite, not just this argument).
///
/// Correctness (empty inner): `inner_header`'s condition is evaluated fresh on
/// EVERY entry, including the very first (from `outer_body`) — an `F(x)` that
/// returns `start == end` takes the false edge immediately, with ZERO
/// `inner_body` visits and `outer_next` already computed; no path from
/// `outer_body` reaches `inner_body` except through `inner_header`'s true edge.
///
/// Scope: BOUNDED only (a bare `Range<T>` self, non-const, unprojected — a
/// constant self / `&mut` receiver / projected place are outside this driver's
/// scope and return `Ok(false)`, falling through to `lower_iter_consumer`,
/// which also cannot see a `FlatMap` self and returns `Ok(false)` too, ending
/// at the caller's fail-closed `[TCG-ITER-UNMODELED]` error — never a
/// miscompile). `product` is NOT intercepted here (std routes it through the
/// structurally different `lower_iter_terminal`, not `lower_iter_consumer`'s
/// dispatch this function shares a gate with); an unintercepted
/// `.flat_map(..).product()` falls through to the general call path and core's
/// real bodies, which read the std layout the ctor wrote.
///
/// OPT-LEVEL SCOPE — this driver is `-O0` only, and that is SAFE at every level.
/// At `-O2`/`-O3` rustc FULLY INLINES `(0..n).flat_map(f).sum()` (etc.): the
/// `flat_map` CTOR call disappears into direct `FlattenCompat`/`Fuse`/`Map`/
/// `Option` aggregate-literal construction, and the `sum`/`fold`/`count`
/// terminal disappears into a direct `FlattenCompat::iter_fold(self, init,
/// fold::flatten_glue)` call over that `FlattenCompat` self — so NEITHER
/// intercept point fires (no `flat_map` callee name, no `sum`/`fold`/`count`
/// terminal over a bare `FlatMap` self). The MEASURED outcome (differential
/// harness, O2 AND O3, both panic modes) is a clean COMPILE-TIME fail-closed:
/// the general aggregate path cannot build the `Option`-of-`Map` nest
/// (`Place projection field 0 before aggregate binding`) and aborts — NEVER a
/// wrong value. Supporting the O2/O3 glue-collapsed
/// `FlattenCompat::iter_fold` form is a SEPARATE, larger increment (it needs
/// intercepting the nested-aggregate CONSTRUCTION plus the `iter_fold` +
/// `fold::flatten` glue closure — the same class of O3 adapter-terminal
/// glue-collapse that `peel_fold_glue_to_sum`/`spec_fold` routing handles for
/// the SIMPLER 1-in-1-out adapters) and is deliberately deferred here rather
/// than risk a wrong nested drive.
fn lower_flatmap_bounded_consumer<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
) -> Result<bool, String> {
    if !matches!(name, "sum" | "count" | "fold") {
        return Ok(false);
    }
    let Some(self_arg) = call.args.first() else {
        return Ok(false);
    };
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
    let Some(shape) = resolve_flatmap_bounded(ctx, self_ty) else {
        return Ok(false);
    };
    // The consumer owns `self` and its payload; the drive below runs no glue.
    // `fold`'s initial accumulator (argument 1) is the result, not a value the
    // callee drops, and the carry rule below guards it across the closure.
    for (index, arg) in call.args.iter().enumerate() {
        if name == "fold" && index == 1 {
            continue;
        }
        let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &arg.node)?);
        refuse_unlowered_owned_drop(
            ctx.tcx,
            arg_ty,
            &format!("argument {index}"),
            &format!("FlatMap::{name}"),
        )?;
    }
    if !call.destination.projection.is_empty() {
        return Err(format!("flat_map {name} into projected destination"));
    }
    // The self operand: a fresh, non-const, unprojected place with a memory
    // slot (mirrors `lower_iter_consumer`'s by-value receiver contract). A
    // CONSTANT self (an O3 const-folded `FlatMap`) is outside this driver's
    // scope — `Ok(false)` falls through to `lower_iter_consumer` (which also
    // returns `Ok(false)` for a `FlatMap` self) and on to the fail-closed
    // general path; deferred honestly rather than risking a wrong const image.
    let (Operand::Copy(src) | Operand::Move(src)) = &self_arg.node else {
        return Ok(false);
    };
    if !src.projection.is_empty() {
        return Ok(false);
    }
    let Some(orig_slot) = ctx.memory_slots.get(&src.local).cloned() else {
        return Ok(false);
    };
    // #111 — PRIVATE iterator-state copy (see `lower_iter_consumer` / the
    // matching `lower_iter_terminal` comment): an O3 CSE/GVN pass can fold two
    // structurally-identical `.flat_map(..)` constructions into ONE memory
    // slot; copy this call's own private instance before draining it so a
    // second by-value terminal over an aliased slot reduces over its own
    // (undrained) copy, not the first terminal's already-drained state.
    let chain_slot = copy_iter_state_to_private_slot(ctx, block, self_ty, orig_slot.ptr)?;

    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty)?;
    // The accumulator is held by the drive while the `flat_map` closure runs.
    refuse_droppable_carry_across_payloads(
        ctx,
        call.unwind,
        Some(dest_ty),
        true,
        &format!("`flat_map(..).{name}`'s accumulator"),
    )?;

    enum FmConsumer<'tcx> {
        Sum { arith: StdReductionArith },
        Count,
        Fold { closure_ty: Ty<'tcx> },
    }
    let consumer = match name {
        "sum" => {
            if !acc_ir.is_integer() {
                return Err("flat_map sum over a non-integer accumulator".to_owned());
            }
            // The SAME impl-identity gate as `lower_iter_consumer`'s `sum` arm (this
            // is a second copy of that predicate): a scalar-mapped `S` may be a user
            // type with `impl Sum<T> for S`, whose body a bare `Add` would discard.
            // The flat_map item is the inner `Range<T>`'s `T`.
            let item_ty = range_index_ty(ctx.tcx, shape.range_ty)
                .ok_or_else(|| "flat_map sum: inner range index type unresolved".to_owned())?;
            FmConsumer::Sum {
                arith: std_sum_product_arith(ctx.tcx, dest_ty, item_ty, "sum")?,
            }
        }
        "count" => {
            if !acc_ir.is_integer() {
                return Err("flat_map count into a non-integer destination".to_owned());
            }
            // Core's `FlattenCompat::count` panics when one inner `Range::count`
            // passes `usize::MAX` and sums the inner counts under
            // `#[rustc_inherit_overflow_checks]`; this per-item count wraps. Both
            // are reachable only with a 32-bit `usize`.
            if session_is_wasm32(ctx.tcx) {
                return Err(
                    "[TCG-ITER-UNMODELED] wasm32 `flat_map(..).count()`: the per-item \
                     count model does not reproduce core's overflow panics past a 32-bit \
                     `usize::MAX` — failing closed"
                        .to_owned(),
                );
            }
            FmConsumer::Count
        }
        "fold" => {
            if call.args.len() != 3 {
                return Err(format!("flat_map fold with {} args", call.args.len()));
            }
            if acc_ir.bit_width().is_none() {
                return Err("flat_map fold over a non-scalar accumulator".to_owned());
            }
            let cty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[2].node)?);
            if !matches!(cty.kind(), ty::Closure(..)) {
                return Err("flat_map fold payload is not a closure".to_owned());
            }
            if !is_zero_sized_ty(ctx.tcx, cty) {
                return Err(
                    "flat_map fold with a capturing (non-ZST) closure is not modeled".to_owned(),
                );
            }
            FmConsumer::Fold { closure_ty: cty }
        }
        _ => return Ok(false),
    };
    let init_val = match &consumer {
        FmConsumer::Sum { .. } | FmConsumer::Count => {
            let zero = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: acc_ir.clone(),
                    value: Constant::Int(0),
                })
                .with_result(zero),
            );
            zero
        }
        FmConsumer::Fold { .. } => lower_operand_to_value(ctx, body, block, &call.args[1].node)?,
    };

    // === Preheader (still `block`): each of std's three `Option<Range<T>>`
    // states as an effective `{start, end}` — the range when the `Option` holds
    // `Some`, the empty `0..0` when it holds `None` (whose payload bytes are
    // dead; the select discards them). ===
    let std_layout = &shape.std_layout;
    let effective_range = |ctx: &mut MirLoweringCtx<'tcx>,
                           block: &mut Block,
                           optional: &FlatMapOptionalRange|
     -> Result<(ValueId, ValueId), String> {
        let tag_addr = iter_field_addr(
            ctx,
            block,
            chain_slot,
            optional.option_off + optional.tag.tag.offset,
        );
        let live = emit_option_is_some_at(ctx, block, tag_addr, &optional.tag)?;
        let empty = emit_typed_const(ctx, block, shape.ir_ty.clone(), 0);
        let bound = |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, field_off: u64| {
            let addr = iter_field_addr(ctx, block, chain_slot, optional.range_off + field_off);
            let value = emit_typed_load(ctx, block, addr, shape.ir_ty.clone());
            let chosen = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: shape.ir_ty.clone(),
                    cond: live,
                    then_val: value,
                    else_val: empty,
                })
                .with_result(chosen),
            );
            chosen
        };
        let start = bound(ctx, block, std_layout.start_off);
        let end = bound(ctx, block, std_layout.end_off);
        Ok((start, end))
    };
    let (front_start, front_end) = effective_range(ctx, block, &std_layout.front)?;
    let (outer_start, outer_end) = effective_range(ctx, block, &std_layout.outer)?;
    let (back_start, back_end) = effective_range(ctx, block, &std_layout.back)?;
    let signed = is_signed_trust_ir_integer(&shape.ir_ty);

    // The closure-call aggregate-return layout for `F`'s `Range<T>` result
    // (`memory_aggregate_layout` is the SAME function `fat_ptr_or_memory_
    // aggregate_layout` — which `func_ty_for_instance` uses to classify `F`'s
    // declared return type — bottoms out to for a plain struct, so this is
    // GUARANTEED to agree with the callee's own declared `FuncTy`, not an
    // independently-derived guess that could drift from it).
    let Some(range_layout) = memory_aggregate_layout_shared(ctx.tcx, shape.range_ty)? else {
        return Err("flat_map inner Range<T> has no aggregate call-return layout".to_owned());
    };
    if range_layout.tag.is_some() {
        return Err("flat_map inner Range<T> is unexpectedly a tagged enum".to_owned());
    }
    let (lane_ty, lane_size) = memory_aggregate_lane(range_layout.align)?;
    if lane_ty != shape.ir_ty
        || lane_size != shape.size
        || range_layout.size != 2 * shape.size
        || std_layout.start_off != 0
        || std_layout.end_off != shape.size
    {
        return Err(
            "flat_map inner Range<T> aggregate layout does not match the expected {start,end} \
             shape"
                .to_owned(),
        );
    }

    let outer_header_id = ctx.fresh_block_id();
    let outer_body_id = ctx.fresh_block_id();
    let inner_header_id = ctx.fresh_block_id();
    let inner_body_id = ctx.fresh_block_id();
    let back_header_id = ctx.fresh_block_id();
    let back_body_id = ctx.fresh_block_id();
    let exit_id = ctx.fresh_block_id();

    // The front range drains through the inner loop first; its exhausted edge
    // enters `outer_header` at the outer range's start.
    block.body.push(InstrNode::new(Inst::Br {
        target: inner_header_id,
        args: vec![front_start, front_end, outer_start, init_val],
    }));

    // --- outer_header(outer_cur, acc) ---
    let outer_cur_p = ctx.fresh_value();
    let acc_p = ctx.fresh_value();
    let mut outer_header = Block::new(outer_header_id);
    outer_header.params.push((outer_cur_p, shape.ir_ty.clone()));
    outer_header.params.push((acc_p, acc_ir.clone()));
    let outer_cond = ctx.fresh_value();
    outer_header.body.push(
        InstrNode::new(Inst::ICmp {
            op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
            ty: shape.ir_ty.clone(),
            lhs: outer_cur_p,
            rhs: outer_end,
        })
        .with_result(outer_cond),
    );
    outer_header.body.push(InstrNode::new(Inst::CondBr {
        cond: outer_cond,
        then_target: outer_body_id,
        then_args: Vec::new(),
        else_target: back_header_id,
        else_args: vec![back_start, acc_p],
    }));
    ctx.extra_blocks.push(outer_header);

    // --- outer_body: x = outer_cur; outer_next = outer_cur + 1 (commits
    // immediately); call F(x); decompose its Range<T> result; enter inner_header. ---
    let mut outer_body = Block::new(outer_body_id);
    let one_outer = ctx.fresh_value();
    outer_body.body.push(
        InstrNode::new(Inst::Const {
            ty: shape.ir_ty.clone(),
            value: Constant::Int(1),
        })
        .with_result(one_outer),
    );
    let outer_next = ctx.fresh_value();
    outer_body.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: shape.ir_ty.clone(),
            lhs: outer_cur_p,
            rhs: one_outer,
        })
        .with_result(outer_next),
    );
    // `env_ptr = chain_slot`: a harmless unused address for a ZST closure,
    // mirroring every other adapter closure call in this file (e.g.
    // `emit_chain_next`'s Map arm: `pre.field_addr(ctx, *closure_off)`).
    let call_result = emit_closure_call_n(
        ctx,
        &mut outer_body,
        shape.closure_ty,
        chain_slot,
        vec![outer_cur_p],
        range_layout.slot_ty.clone(),
    )?;
    let inner_start = ctx.fresh_value();
    emit_lane_value_read(
        ctx,
        &mut outer_body,
        &range_layout.slot_ty,
        call_result,
        0,
        inner_start,
    )?;
    let inner_end0 = ctx.fresh_value();
    emit_lane_value_read(
        ctx,
        &mut outer_body,
        &range_layout.slot_ty,
        call_result,
        1,
        inner_end0,
    )?;
    outer_body.body.push(InstrNode::new(Inst::Br {
        target: inner_header_id,
        args: vec![inner_start, inner_end0, outer_next, acc_p],
    }));
    ctx.extra_blocks.push(outer_body);

    // --- inner_header(inner_cur, inner_end, outer_next, acc): 4 FRESH params. ---
    let inner_cur_p = ctx.fresh_value();
    let inner_end_p = ctx.fresh_value();
    let outer_next_p = ctx.fresh_value();
    let acc_c_p = ctx.fresh_value();
    let mut inner_header = Block::new(inner_header_id);
    inner_header.params.push((inner_cur_p, shape.ir_ty.clone()));
    inner_header.params.push((inner_end_p, shape.ir_ty.clone()));
    inner_header
        .params
        .push((outer_next_p, shape.ir_ty.clone()));
    inner_header.params.push((acc_c_p, acc_ir.clone()));
    let inner_cond = ctx.fresh_value();
    inner_header.body.push(
        InstrNode::new(Inst::ICmp {
            op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
            ty: shape.ir_ty.clone(),
            lhs: inner_cur_p,
            rhs: inner_end_p,
        })
        .with_result(inner_cond),
    );
    inner_header.body.push(InstrNode::new(Inst::CondBr {
        cond: inner_cond,
        then_target: inner_body_id,
        then_args: Vec::new(),
        else_target: outer_header_id,
        else_args: vec![outer_next_p, acc_c_p],
    }));
    ctx.extra_blocks.push(inner_header);

    // `accumulate(acc, item)` for one yielded item: the consumer's step.
    let accumulate = |ctx: &mut MirLoweringCtx<'tcx>,
                      blk: &mut Block,
                      acc: ValueId,
                      item: ValueId|
     -> Result<ValueId, String> {
        Ok(match &consumer {
            FmConsumer::Sum { arith } => {
                // The selected impl's arithmetic (overflow-checked for a primitive
                // integer, exactly std's `#[rustc_inherit_overflow_checks]`
                // closure). May split `blk`; the caller's increment and back-edge
                // append to the continuation.
                let item_conv = convert_scalar(ctx, blk, item, &shape.ir_ty, &acc_ir);
                emit_std_reduction_step(
                    ctx, body, blk, call, *arith, false, &acc_ir, acc, item_conv,
                )?
            }
            FmConsumer::Count => {
                let one = ctx.fresh_value();
                blk.body.push(
                    InstrNode::new(Inst::Const {
                        ty: acc_ir.clone(),
                        value: Constant::Int(1),
                    })
                    .with_result(one),
                );
                let r = ctx.fresh_value();
                blk.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Add,
                        ty: acc_ir.clone(),
                        lhs: acc,
                        rhs: one,
                    })
                    .with_result(r),
                );
                r
            }
            FmConsumer::Fold { closure_ty } => emit_closure_call_n(
                ctx,
                blk,
                *closure_ty,
                chain_slot,
                vec![acc, item],
                acc_ir.clone(),
            )?,
        })
    };
    // `cur + 1` in the range's index type.
    let increment = |ctx: &mut MirLoweringCtx<'tcx>, blk: &mut Block, cur: ValueId| {
        let one = emit_typed_const(ctx, blk, shape.ir_ty.clone(), 1);
        let next = ctx.fresh_value();
        blk.body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::Add,
                ty: shape.ir_ty.clone(),
                lhs: cur,
                rhs: one,
            })
            .with_result(next),
        );
        next
    };

    // --- inner_body: new_acc = accumulate(acc, inner_cur); inner_next =
    // inner_cur + 1; back-edge to inner_header. ---
    let mut inner_body = Block::new(inner_body_id);
    let new_acc = accumulate(ctx, &mut inner_body, acc_c_p, inner_cur_p)?;
    let inner_next = increment(ctx, &mut inner_body, inner_cur_p);
    let back_args = vec![inner_next, inner_end_p, outer_next_p, new_acc];
    inner_body.body.push(InstrNode::new(Inst::Br {
        target: inner_header_id,
        args: back_args,
    }));
    ctx.extra_blocks.push(inner_body);

    // --- back_header(back_cur, acc): the `backiter` range, after the outer
    // range is exhausted. `cond = back_cur < back_end` (loop-invariant). ---
    let back_cur_p = ctx.fresh_value();
    let back_acc_p = ctx.fresh_value();
    let mut back_header = Block::new(back_header_id);
    back_header.params.push((back_cur_p, shape.ir_ty.clone()));
    back_header.params.push((back_acc_p, acc_ir.clone()));
    let back_cond = ctx.fresh_value();
    back_header.body.push(
        InstrNode::new(Inst::ICmp {
            op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
            ty: shape.ir_ty.clone(),
            lhs: back_cur_p,
            rhs: back_end,
        })
        .with_result(back_cond),
    );
    back_header.body.push(InstrNode::new(Inst::CondBr {
        cond: back_cond,
        then_target: back_body_id,
        then_args: Vec::new(),
        else_target: exit_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(back_header);

    // --- back_body: accumulate; back_next = back_cur + 1; back-edge. ---
    let mut back_body = Block::new(back_body_id);
    let back_new_acc = accumulate(ctx, &mut back_body, back_acc_p, back_cur_p)?;
    let back_next = increment(ctx, &mut back_body, back_cur_p);
    back_body.body.push(InstrNode::new(Inst::Br {
        target: back_header_id,
        args: vec![back_next, back_new_acc],
    }));
    ctx.extra_blocks.push(back_body);

    // --- exit: the final accumulator is back_header's `acc` param on its
    // FALSE edge (back_header dominates exit — its only predecessor). ---
    let mut exit_block = Block::new(exit_id);
    // ADDRESS-TAKEN destination: populate the canonical backing store (scalar
    // CELL or memory slot) — `bind_scalar_value` alone leaves it uninitialized
    // garbage for any `&dest` borrow / by-REF closure capture reader. Same P0
    // class and same fix as the generic iterator consumer's exit (2026-07-17).
    if let Some(slot) = ctx.memory_slots.get(&call.destination.local).cloned() {
        emit_typed_store(&mut exit_block, slot.ptr, acc_ir.clone(), back_acc_p);
    }
    finish_assign_target(
        ctx,
        body,
        &mut exit_block,
        call.destination,
        AssignTarget {
            value: back_acc_p,
            binding: ScalarPlaceBinding::Local(call.destination.local),
            preserve_self_borrow: false,
        },
    )?;
    if let Some(target) = call.target {
        exit_block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        exit_block.body.push(InstrNode::new(Inst::Unreachable));
    }
    ctx.extra_blocks.push(exit_block);

    Ok(true)
}

/// Lower an `-O3`-inlined `<Iter>::try_fold(self, init, check)` call — the
/// short-circuiting engine that `.any()/.all()/.find()/.position()/.find_map()`
/// inline into (the by-name terminal disappears; the caller makes a raw `try_fold`
/// call and maps the returned `ControlFlow`). `check: FnMut(Acc, Item) ->
/// ControlFlow<B, Acc>` is a ZST or supported reference-capturing closure. Apply
/// `check` per item;
/// on `ControlFlow::Break(b)` the result IS that value (short-circuit); on
/// `Continue(a)` keep `a` as the accumulator; on exhaustion the result is
/// `Continue(acc)`. The `ControlFlow` result flows to the caller's own mapping
/// (`== Break`, or a Break-payload extract) unchanged. Fail closed (not miscompile)
/// on any shape this driver does not model: a StepBy/tuple chain (and, on a
/// native target, a reversed chain or an indirectly returning check), a
/// by-value capturing closure, an unsupported result layout, or a non-scalar
/// accumulator. A tagless result requires rustc's sole-Continue layout witness;
/// a scalar-pair result uses the closure body's own ABI lanes.
fn lower_iter_try_fold<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    // `true` for `<I as DoubleEndedIterator>::try_rfold`: drive the chain
    // BACKWARDS (flip `reversed`, mirroring the `.rev()` ctor guards).
    reverse: bool,
) -> Result<bool, String> {
    // `try_fold(self, init, check)` — exactly three MIR args.
    if call.args.len() != 3 {
        return Ok(false);
    }
    let self_arg = &call.args[0];
    let self_arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
    // `&mut self` receiver: peel one ref to the underlying iterator type.
    let iter_ty = match self_arg_ty.kind() {
        ty::Ref(_, inner, _) => ctx.monomorphize_ty(*inner),
        _ => self_arg_ty,
    };
    // FAIL CLOSED (not Ok(false)) on any try_fold we cannot fully drive: in a
    // library crate type the dead `<Iter>::try_fold` bodies are trapped (see
    // is_dead_std_iterator_reduction_body), so a fall-through to the normal call
    // lowering would reach a `ud2` stub at runtime (an executable would refuse the
    // body instead, naming it rather than this call site). Erroring here keeps the
    // program fail-closed at compile time with the more precise reason.
    // The exception is a chain over a source the bridge leaves to core's real
    // bodies: its real `try_fold` is lowered on the general call path, and the
    // trap exclusion keeps every body whose types mention the source out of the
    // dead-body stubs (`real_body_iterator_receiver` states its limit).
    if real_body_iterator_receiver(ctx, body, call)? {
        return Ok(false);
    }
    let Some(mut chain) = resolve_iter_chain(ctx, iter_ty)? else {
        // EXCEPTION, and the ONLY one: a CERTIFIED `Chars` receiver. `Chars` is not
        // a chain `resolve_iter_chain` models, but under
        // `is_certified_chars_cursor` the bridge's cursor IS std's representation,
        // so the real `Iterator::try_fold` / `DoubleEndedIterator::try_rfold`
        // default body — a plain `while let Some(x) = self.next()` /
        // `self.next_back()` loop — reads exactly the words the bridge wrote and is
        // CORRECT. Falling through to it is therefore not a fail-open; it is the
        // right lowering. The `ud2` hazard the paragraph below names is closed in
        // lockstep: `is_dead_std_iterator_reduction_body` excludes every body whose
        // SELF type is a certified `Chars`, so nothing traps the body we are about
        // to call. Remove either half alone and this becomes a runtime SIGILL —
        // they are one change.
        if is_certified_chars_cursor(ctx.tcx, iter_ty) {
            return Ok(false);
        }
        // A `Cloned<I>` over a modeled `I` whose element `clone` is not a bitwise
        // copy (`resolve_iter_chain` leaves those unmodeled): core's real
        // `Cloned::try_fold` body is `self.it.try_fold(init, clone_try_fold(f))`,
        // whose inner call this function drives over the modeled `I`, calling the
        // `clone_try_fold` glue — and so the user's `clone` — for every element.
        // If that body fails to lower, its trap stub is reachable from here and
        // the compile is refused ([TCG-ITER-STUB-REACHABLE]).
        if let ty::Adt(adt, args) = iter_ty.kind() {
            if adapter_kind_of(ctx.tcx, adt.did()) == Some(AdapterTag::Cloned)
                && resolve_iter_chain(ctx, ctx.monomorphize_ty(args.type_at(0)))?.is_some()
            {
                return Ok(false);
            }
        }
        return Err(format!(
            "[TCG-ITER-UNMODELED] iterator try_fold over an unmodeled iterator chain \
             `{iter_ty:?}`"
        ));
    };
    if chain
        .adapters
        .iter()
        .any(|(a, _)| matches!(a.kind, AdapterKind::StepBy { .. }))
    {
        // A StepBy chain's O3 state is unreliable (the known step_by miscompile
        // class) — fail closed.
        return Err("iterator try_fold over a step_by chain".to_owned());
    }
    // STRICT INITIAL SCOPE: `filter_map`/`take_while`/`scan` are validated ONLY for
    // the exhaustive `sum`/`fold`/`count` consumers (the `emit_chain_next` drive
    // reached via `lower_iter_consumer`). The short-circuit family
    // (`find`/`any`/`all`/`position`/`try_fold`/`try_rfold`) shares
    // `emit_chain_next`, so it would run "for free" — but that surface is NOT yet
    // validated (the None re-pull / TERMINATE edges interact with early-exit
    // ControlFlow bookkeeping). Fail closed here until separately test-gated.
    if chain.adapters.iter().any(|(a, _)| {
        matches!(
            a.kind,
            AdapterKind::FilterMap | AdapterKind::TakeWhile { .. } | AdapterKind::Scan { .. }
        )
    }) {
        return Err(
            "iterator try_fold/find/any/all over a filter_map/take_while/scan chain is not \
             modeled (initial scope: exhaustive sum/fold/count consumers only)"
                .to_owned(),
        );
    }
    if reverse {
        // `try_rfold`: drive the chain BACKWARDS by flipping `reversed`. The
        // flip commutes ONLY with STATELESS per-element adapters (Map / Filter /
        // Copied). A bounded-count adapter (take/skip/step_by) or an `Enumerate`
        // counter is direction-dependent WHEREVER it sits — below the flip the
        // forward prefix is not a backward-walk prefix; ABOVE a Rev
        // (`chain.reversed == true`, e.g. `.rev().take(2).rfind(..)`) the count
        // applies to the reversed sequence a cancelled double-flip would not
        // reproduce — so reject UNCONDITIONALLY (Enumerate is NOT in
        // `is_count_modifier`; name it explicitly). A `RangeInclusive` source
        // reverses as std's `spec_next_back` (see `emit_source_next`). A DOUBLE
        // reversal over a stateless chain cancels to the forward drive.
        // A below-rev `.take(n)`/`.skip(k)` over a bare slice source: rewrite
        // into the boundary clamp instead of rejecting (the drive-preheader
        // `emit_rev_clamp` below applies it — idempotently — to the caller's
        // live slot).
        rewrite_below_rev_bounded(&mut chain);
        if chain.adapters.iter().any(|(a, _)| {
            a.kind.is_count_modifier()
                || matches!(
                    a.kind,
                    AdapterKind::Enumerate { .. }
                        | AdapterKind::FilterMap
                        | AdapterKind::TakeWhile { .. }
                        | AdapterKind::Scan { .. }
                )
        }) {
            return Err("iterator try_rfold over a take/skip/step_by/enumerate chain".to_owned());
        }
        chain.reversed = !chain.reversed;
    } else if chain.reversed && !session_is_wasm32(ctx.tcx) {
        return Err("iterator try_fold over a reversed chain".to_owned());
    }
    // A forward drive of a reversed chain (`.rev()` below the whole spine, with
    // stateless adapters or a take/skip ABOVE it, e.g. `Take<Rev<Range>>`) walks
    // the source backwards exactly as the exhaustive consumers do: every
    // adapter counts over the reversed sequence it sees, and the source cursor
    // (`end` for a range, the tail pointer for a slice) is written back to the
    // caller's live slot on every step. Chain resolution refused every shape a
    // backward walk would not reproduce — a count adapter or `RangeInclusive`
    // BELOW the rev — with one exception: a bare slice source's lone below-rev
    // `.take(n)` / `.skip(k)` is rewritten into the boundary clamp
    // (`rewrite_below_rev_bounded`), which `emit_rev_clamp` applies to the
    // caller's live slot before this drive starts. Native sessions keep
    // refusing it: their evidence does not cover this drive.
    if chain.item.tuple.is_some() {
        return Err("iterator try_fold over a tuple-yielding chain".to_owned());
    }

    // The check closure (arg 2): a callable ZST closure.
    let check_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[2].node)?);
    if !matches!(check_ty.kind(), ty::Closure(..)) {
        return Err("iterator try_fold payload is not a closure".to_owned());
    }
    // `try_fold` owns its by-value arguments (a by-value `self`, `init`, the check
    // closure); the drive below runs no glue for them.
    for (index, arg) in call.args.iter().enumerate() {
        let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &arg.node)?);
        refuse_unlowered_owned_drop(
            ctx.tcx,
            arg_ty,
            &format!("argument {index}"),
            "Iterator::try_fold",
        )?;
    }
    // A CAPTURING (non-ZST) check closure is allowed IFF its env is a memory-backed
    // slot we can hand to the body by pointer: `.position()` inlines to
    // `try_fold((), position::check(&mut counter, pred))`, whose check captures the
    // `&mut counter` (non-ZST). We pass that env slot ptr to the check call below;
    // `closure_env_ptr` fails closed if the env is not a memory-backed by-value
    // closure slot (a scalarized / unsupported-capture closure).
    let check_is_zst = is_zero_sized_ty(ctx.tcx, check_ty);
    // SOUNDNESS GATE: a non-ZST check env is handed to the check body BY POINTER,
    // which is correct only when each captured upvar is itself a REFERENCE to its
    // (elsewhere-stored) data — the `find::check(&mut predicate)` shape a `for x in
    // it.filter(p)` loop and a captured-predicate `.filter()` produce, whose check
    // env is just a pointer the body derefs. A check that captures a predicate BY
    // VALUE (`all::check(pred)` / `any::check(pred)` when `pred` itself captures)
    // holds that predicate's environment INLINE in the check env; reading that
    // nested by-value capture through the handed-off pointer is NOT modeled and
    // yields a WRONG value (a silent miscompile — e.g. `(0..=n).all(|x| x >= lo)`).
    // Require every non-ZST-check upvar to be a reference; fail closed otherwise. A
    // ZST check (the common non-capturing `.find()/.any()/.all()`) has no upvars and
    // is unaffected. (`.position()`'s `&mut counter` capture is a reference, so it
    // keeps compiling.)
    if !check_is_zst {
        if let ty::Closure(_, cargs) = check_ty.kind() {
            // Reject a NON-ZST BY-VALUE upvar (inline captured data). A REFERENCE
            // upvar (`find::check(&mut pred)`, `position::check`'s `&mut acc`) points
            // to elsewhere-stored data the body derefs — sound. A ZST upvar (a
            // captured non-capturing predicate, e.g. alongside `position`'s `&mut
            // acc`) carries nothing to read — sound. Only a non-ZST by-value upvar
            // (`all::check(pred)` where `pred` captures `start`) holds real bytes
            // INLINE in the check env that the by-pointer hand-off misreads.
            if cargs.as_closure().upvar_tys().iter().any(|u| {
                !matches!(u.kind(), ty::Ref(..) | ty::RawPtr(..)) && !is_zero_sized_ty(ctx.tcx, u)
            }) {
                return Err(
                    "iterator try_fold with a by-value capturing check closure is not \
                     modeled (only a reference-captured predicate, e.g. \
                     `find::check(&mut p)`, is supported) — failing closed rather than \
                     miscompiling"
                        .to_owned(),
                );
            }
        }
    }

    // The `ControlFlow` result type + its (Direct-tagged, 2-variant) memory layout.
    if !call.destination.projection.is_empty() {
        return Err("iterator try_fold into a projected destination".to_owned());
    }
    let dest_local = call.destination.local;
    let cf_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, dest_local));
    // `fold` over an adapter whose `fold` is `try_fold` with a
    // `NeverShortCircuit` result (`Take::fold` at `-O`): an exhaustive fold.
    if session_is_wasm32(ctx.tcx) && is_never_short_circuit(ctx.tcx, cf_ty) {
        return lower_iter_try_fold_never_short_circuit(
            ctx,
            body,
            block,
            call,
            &chain,
            check_ty,
            check_is_zst,
            cf_ty,
        );
    }
    let ty::Adt(cf_adt, cf_args) = cf_ty.kind() else {
        return Err(format!("iterator try_fold result {cf_ty:?} is not an enum"));
    };
    if cf_adt.variants().len() != 2 {
        return Err("iterator try_fold result is not a 2-variant ControlFlow".to_owned());
    }
    // A TAG-ONLY `ControlFlow` (`ControlFlow<()>`, the result of `any` / `all`
    // over an adapter's own `try_fold`) is a scalar local, the tag
    // (`tag_only_enum_scalar_ty`), so it has no memory layout of its own. Drive
    // it through a scratch image of rustc's layout (`tag_only_enum_memory_image`)
    // and bind the destination to the tag read back at the loop exit
    // (`scalar_result`).
    let (layout, scalar_result) = match memory_aggregate_layout_shared(ctx.tcx, cf_ty)? {
        Some(layout) => (layout, None),
        None => match (
            tag_only_enum_scalar_ty(ctx.tcx, cf_ty),
            tag_only_enum_memory_image(ctx.tcx, cf_ty)?,
        ) {
            (Some(scalar), Some(image)) => (std::rc::Rc::new(image), Some(scalar)),
            _ => return Err("iterator try_fold result has no memory layout".to_owned()),
        },
    };
    let tag = layout.tag.clone();
    // A NICHE-encoded ControlFlow (`ControlFlow<&T, ()>` — find's by-ref Break
    // payload IS the niche) is supported for a ZST accumulator (checked below).
    let tag_is_niche = tag
        .as_ref()
        .is_some_and(|tag| !matches!(tag.encoding, MemoryTagEncoding::Direct));
    // Identify the Break / Continue variants by name; each variant's payload-0 byte
    // offset (within the whole enum) + monomorphized field type + discriminant.
    let cx = LayoutCx(ctx.tcx);
    let base_layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(cf_ty))
        .map_err(|e| format!("ControlFlow layout_of failed: {e:?}"))?;
    let mut break_discr: Option<i128> = None;
    let mut continue_info: Option<(u64, Ty<'tcx>, i128)> = None;
    let mut continue_vidx: Option<VariantIdx> = None;
    for (vi, variant) in cf_adt.variants().iter_enumerated() {
        if variant.fields.len() != 1 {
            return Err("ControlFlow variant does not have exactly 1 field".to_owned());
        }
        let field_ty = ctx.monomorphize_ty(ctx_field_ty(ctx.tcx, variant, *cf_args, 0));
        let off = base_layout.for_variant(&cx, vi).fields.offset(0).bytes();
        let discr = adt_discriminant_value(ctx.tcx, cf_adt.did(), vi)?;
        match variant.name.as_str() {
            "Break" => break_discr = Some(discr),
            "Continue" => {
                continue_info = Some((off, field_ty, discr));
                continue_vidx = Some(vi);
            }
            other => return Err(format!("unexpected ControlFlow variant {other}")),
        }
    }
    let break_discr = break_discr.ok_or_else(|| "ControlFlow has no Break variant".to_owned())?;
    let (cont_off, cont_field_ty, cont_discr) =
        continue_info.ok_or_else(|| "ControlFlow has no Continue variant".to_owned())?;

    // The accumulator = `init` (arg 1). A ZST acc (`()`, for any/all/find) has no
    // slot and is not passed to the closure; a scalar acc (usize, for position) is
    // stored in a slot and threaded. The Continue payload's ZST-ness must match.
    let acc_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let acc_zst = is_zero_sized_ty(ctx.tcx, acc_ty);
    if tag.is_none() {
        // No tag is valid only when rustc proves that Continue is the sole
        // inhabited variant of core::ops::ControlFlow. The accumulator is its
        // entire scalar payload; no branch or tag load can distinguish Break.
        let sole_continue = matches!(base_layout.variants,
            rustc_abi::Variants::Single { index } if Some(index) == continue_vidx);
        let break_is_uninhabited = cf_adt.variants().iter_enumerated().any(|(vi, variant)| {
            variant.name.as_str() == "Break" && base_layout.for_variant(&cx, vi).is_uninhabited()
        });
        if ctx.tcx.get_diagnostic_item(rustc_span::sym::ControlFlow) != Some(cf_adt.did())
            || !sole_continue
            || !break_is_uninhabited
            || acc_ty != cont_field_ty
            || acc_zst
            || cont_off != 0
        {
            return Err(
                "iterator try_fold untagged result has no sole scalar Continue witness".to_owned(),
            );
        }
        let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, acc_ty)?;
        let acc_layout = ctx
            .tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(acc_ty))
            .map_err(|e| format!("iterator try_fold accumulator layout failed: {e:?}"))?;
        if !acc_ir.is_integer()
            || acc_ir.bit_width().is_none_or(|bits| bits > 64)
            || layout.size != acc_layout.size.bytes()
            || layout.align != layout.size
        {
            return Err(
                "iterator try_fold untagged accumulator is not a full integer lane".to_owned(),
            );
        }
    }
    if is_zero_sized_ty(ctx.tcx, cont_field_ty) != acc_zst {
        return Err("iterator try_fold Continue payload / accumulator ZST mismatch".to_owned());
    }
    // NICHE: only the ZST-accumulator form (find-family), and Continue must be a
    // NICHE variant so the exhausted arm can build it by a tag-offset store.
    let continue_niche_value: Option<i128> = if tag_is_niche {
        if !acc_zst {
            return Err(
                "iterator try_fold niche-encoded result with a non-ZST accumulator".to_owned(),
            );
        }
        let Some(niche_tag) = tag.as_ref() else {
            return Err("iterator try_fold niche-encoded result has no tag".to_owned());
        };
        let MemoryTagEncoding::Niche {
            untagged_variant,
            niche_variants_start,
            niche_start,
            ..
        } = &niche_tag.encoding
        else {
            unreachable!("tag_is_niche implies a Niche encoding");
        };
        let cvi = continue_vidx.ok_or_else(|| "ControlFlow has no Continue variant".to_owned())?;
        if cvi == *untagged_variant {
            return Err(
                "iterator try_fold niche ControlFlow's Continue is the untagged variant".to_owned(),
            );
        }
        let rel = cvi.as_u32() as u128 - niche_variants_start.as_u32() as u128;
        Some(niche_start.wrapping_add(rel) as i128)
    } else {
        None
    };
    // E2 — the (non-ZST) accumulator becomes a loop-carried header block param;
    // here we only compute its INITIAL value (the preheader's entry branch arg).
    let acc_init: Option<(ValueId, TrustIrTy)> = if acc_zst {
        None
    } else {
        let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, acc_ty)?;
        if acc_ir.bit_width().is_none() {
            return Err("iterator try_fold non-scalar accumulator".to_owned());
        }
        let init_val = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
        Some((init_val, acc_ir))
    };

    // The chain-state slot pointer: for a `&mut self` receiver the operand's VALUE
    // is the slot pointer (drain in place; try_fold consumes the iterator).
    let chain_slot = lower_operand_to_value(ctx, body, block, &self_arg.node)?;

    // A rewritten below-rev take/skip: clamp the slot boundary BEFORE driving
    // (idempotent; the O0 rev ctor already clamped, an O3-inlined ctor did not —
    // and the caller's LIVE `&mut self` slot stays canonical across re-drives).
    emit_rev_clamp(ctx, block, &chain, chain_slot)?;

    // The destination `ControlFlow` slot doubles as scratch for the per-step closure
    // result: on Break it IS the returned value; on Continue we read the acc out of
    // it and overwrite it next step; on exhaustion we build `Continue(acc)` into it.
    let dest_slot = match (ctx.memory_slots.get(&dest_local).cloned(), &scalar_result) {
        (Some(slot), _) => slot.ptr,
        (None, Some(_)) => {
            let scratch = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: layout.slot_ty.clone(),
                    count: None,
                    align: Some(layout.align),
                })
                .with_result(scratch),
            );
            scratch
        }
        (None, None) => {
            return Err("iterator try_fold destination is not memory-backed".to_owned());
        }
    };
    // Every loop exit goes here: the call's successor, or — for a scalar
    // (tag-only) destination — a join that reads the tag back and binds it.
    let exit_join = (scalar_result.is_some() && !ctx.memory_slots.contains_key(&dest_local))
        .then(|| ctx.fresh_block_id());
    let emit_exit = |block: &mut Block| match exit_join {
        Some(join) => block.body.push(InstrNode::new(Inst::Br {
            target: join,
            args: Vec::new(),
        })),
        None => emit_try_fold_exit(block, call),
    };

    let break_id = ctx.fresh_block_id();

    // === Header: loop-carried acc param (if non-ZST), then the chain `next`.
    // The SOURCE CURSOR stays in Slot mode here — this chain_slot is the
    // CALLER's live `&mut self` iterator (drained in place, see above), so the
    // per-iteration state write-back is REQUIRED: a caller that touches the
    // iterator after `position()`/`find()` observes the drained state. Only the
    // accumulator (private to this loop) moves into a block param. ===
    let header_id = ctx.fresh_block_id();
    let mut header = Block::new(header_id);
    let mut entry_args: Vec<ValueId> = Vec::new();
    let acc_param: Option<(ValueId, TrustIrTy)> = acc_init.as_ref().map(|(init_val, acc_ir)| {
        let p = ctx.fresh_value();
        header.params.push((p, acc_ir.clone()));
        entry_args.push(*init_val);
        (p, acc_ir.clone())
    });
    let loop_carried: Vec<ValueId> = acc_param.iter().map(|(p, _)| *p).collect();
    let out = emit_chain_next(
        ctx,
        &chain,
        chain_slot,
        block,
        &mut header,
        header_id,
        &loop_carried,
        &SourceCursor::Slot,
    )?;
    ctx.extra_blocks.push(header);

    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: entry_args,
    }));

    let exhausted_id = out.not_found_id;

    // === body (the chain's `found` block): cf = check(acc, item); branch on the
    // ControlFlow tag. ===
    let mut body_block = Block::new(out.found_id);
    let item_repr = out.item[0];
    let instance = closure_body_instance(ctx, check_ty)?;
    refuse_unthreaded_caller_location(ctx.tcx, instance)?;
    let callee = ctx.extern_callee(instance)?;
    // The check closure's env pointer: for a ZST check the env is never
    // dereferenced (chain_slot is an unused placeholder); for a capturing check
    // (`.position()`'s `&mut counter`) it is the real env slot ptr.
    let check_env_ptr = if check_is_zst {
        chain_slot
    } else {
        closure_env_ptr(ctx, body, &mut body_block, &call.args[2].node)?
    };
    let mut check_args = Vec::with_capacity(2);
    if let Some((p, _)) = &acc_param {
        check_args.push(*p);
    }
    check_args.push(item_repr);
    let call_args = closure_body_call_args_from_values(
        ctx,
        &mut body_block,
        instance,
        Some(check_env_ptr),
        check_args,
    )?;
    // Bind the result according to the closure body's actual ABI. A scalar
    // pair has two results with rustc's lane types and byte offsets; treating it
    // as one aggregate disagrees with the callee's declared return signature.
    // An indirect (`sret`) return — rustc's wasm32 convention for a
    // `ControlFlow` wider than two words or a `ControlFlow<u64>` — takes the
    // destination slot as its leading buffer, the position the body's own
    // declaration gives it (`classify_func_ty`), and leaves the bytes there.
    let pair = ctx.scalar_pair_returns.get(&instance).cloned();
    let sret = ctx.sret_returns.get(&instance).cloned();
    refuse_hand_built_small_cast_return(ctx, instance)?;
    let cf = if let Some(buffer) = &sret {
        // The native selectors place a hidden buffer from a callee-symbol
        // marker this hand-built call does not carry; only wasm32 (whose
        // buffer is the leading `i32` parameter) lowers it.
        if !session_is_wasm32(ctx.tcx) {
            return Err("iterator try_fold closure has an indirect return".to_owned());
        }
        if tag.is_none()
            || buffer.slot_ty != layout.slot_ty
            || buffer.size != layout.size
            || buffer.align != layout.align
        {
            return Err(
                "iterator try_fold closure's indirect return does not match the result layout"
                    .to_owned(),
            );
        }
        let mut sret_args = Vec::with_capacity(call_args.len() + 1);
        sret_args.push(dest_slot);
        sret_args.extend(call_args);
        push_unwindable_intercept_call(ctx, &mut body_block, callee, sret_args, None);
        None
    } else if let Some(plan) = &pair {
        if tag.is_none()
            || plan.layout.slot_ty != layout.slot_ty
            || plan.layout.size != layout.size
            || plan.layout.align != layout.align
        {
            return Err("iterator try_fold scalar pair does not match result layout".to_owned());
        }
        let results = [ctx.fresh_value(), ctx.fresh_value()];
        // A payload can panic: both result forms must preserve the intercepted
        // MIR terminator's cleanup edge.
        push_unwindable_intercept_call(ctx, &mut body_block, callee, call_args, results);
        for (lane, result) in results.into_iter().enumerate() {
            let value = plan.narrow_carrier(ctx, &mut body_block, lane, result);
            let addr = slot_byte_ptr(ctx, &mut body_block, dest_slot, plan.lanes[lane].1);
            emit_typed_store(&mut body_block, addr, plan.lanes[lane].0.clone(), value);
        }
        None
    } else if let (Some(scalar), Some(tag)) = (&scalar_result, &tag) {
        // A tag-only result is returned as its scalar tag: store it at the tag
        // offset of the scratch image, whose other bytes are never read.
        let result = ctx.fresh_value();
        push_unwindable_intercept_call(ctx, &mut body_block, callee, call_args, Some(result));
        let tag_addr = slot_byte_ptr(ctx, &mut body_block, dest_slot, tag.offset);
        emit_typed_store(&mut body_block, tag_addr, scalar.clone(), result);
        None
    } else {
        let result = ctx.fresh_value();
        push_unwindable_intercept_call(ctx, &mut body_block, callee, call_args, Some(result));
        Some(result)
    };
    let align = layout.align;
    let (lane_ty, lane_size) = memory_aggregate_lane(align)
        .map_err(|_| format!("iterator try_fold result alignment {align} unsupported"))?;
    if layout.size % lane_size != 0 {
        return Err("iterator try_fold result size is not a lane multiple".to_owned());
    }
    let lanes = (layout.size / lane_size) as u32;
    // Extract lane `lane` of the returned `ControlFlow` aggregate `cf` as SSA
    // (the call result IS the returned bytes — SysV by-value aggregate return).
    let extract_lane =
        |ctx: &mut MirLoweringCtx<'tcx>, blk: &mut Block, lane: u32| -> Result<ValueId, String> {
            let aggregate = cf.ok_or_else(|| {
                "iterator try_fold has no aggregate return to extract from (a scalar-pair plan \
             owns this result)"
                    .to_owned()
            })?;
            let v = ctx.fresh_value();
            emit_lane_value_read(ctx, blk, &layout.slot_ty, aggregate, lane, v)?;
            Ok(v)
        };

    if tag.is_none() {
        // The witnessed result contains exactly the new accumulator. Keep it
        // on the back edge, while the iterator cursor remains in its caller's
        // live slot. Exhaustion stores the final Continue payload once.
        let (acc, acc_ir) = acc_param.as_ref().ok_or_else(|| {
            "iterator try_fold untagged result has no scalar accumulator".to_owned()
        })?;
        let returned = extract_lane(ctx, &mut body_block, 0)?;
        let next_acc = convert_scalar(ctx, &mut body_block, returned, &lane_ty, acc_ir);
        body_block.body.push(InstrNode::new(Inst::Br {
            target: header_id,
            args: vec![next_acc],
        }));
        ctx.extra_blocks.push(body_block);
        let mut exhausted_block = Block::new(exhausted_id);
        emit_typed_store(&mut exhausted_block, dest_slot, acc_ir.clone(), *acc);
        emit_exit(&mut exhausted_block);
        ctx.extra_blocks.push(exhausted_block);
        ctx.clear_full_place_bindings(dest_local);
        return Ok(true);
    }
    let tag = tag.ok_or_else(|| {
        "iterator try_fold tagged path reached without a tag (the untagged sole-Continue \
         path returns above)"
            .to_owned()
    })?;

    // E5 — drop the per-step dest_slot round-trip when the tag (and, for a
    // scalar accumulator, the Continue payload) sits lane-aligned in a
    // DIRECT-tagged layout: read tag/payload straight off the returned
    // aggregate as SSA, loop back with the payload as the acc param's back-edge
    // arg, and write dest_slot only on the two loop EXITS. Any other layout (a
    // niche encoding, an unaligned tag/payload, a non-integer accumulator)
    // KEEPS the per-step spill below — correct, just slower.
    let lane_fits = |ty: &TrustIrTy| -> bool {
        match (ty.bit_width(), lane_ty.bit_width()) {
            (Some(t), Some(l)) => t <= l,
            _ => false,
        }
    };
    let tag_lane = tag.offset / lane_size;
    let cont_lane = cont_off / lane_size;
    let ssa_cf = cf.is_some()
        && matches!(tag.encoding, MemoryTagEncoding::Direct)
        && tag.offset % lane_size == 0
        && tag_lane < u64::from(lanes)
        && tag.ty.is_integer()
        && lane_fits(&tag.ty)
        && match &acc_param {
            None => true,
            Some((_, acc_ir)) => {
                acc_ir.is_integer()
                    && lane_fits(acc_ir)
                    && cont_off % lane_size == 0
                    && cont_lane < u64::from(lanes)
            }
        };

    if ssa_cf {
        let tag_lane_val = extract_lane(ctx, &mut body_block, tag_lane as u32)?;
        let tag_val = convert_scalar(ctx, &mut body_block, tag_lane_val, &lane_ty, &tag.ty);
        let break_c = ctx.fresh_value();
        body_block.body.push(
            InstrNode::new(Inst::Const {
                ty: tag.ty.clone(),
                value: Constant::Int(break_discr),
            })
            .with_result(break_c),
        );
        let is_break = ctx.fresh_value();
        body_block.body.push(
            InstrNode::new(Inst::ICmp {
                op: ICmpOp::Eq,
                ty: tag.ty.clone(),
                lhs: tag_val,
                rhs: break_c,
            })
            .with_result(is_break),
        );
        // Continue payload (the next accumulator) as SSA, threaded straight
        // back to the header on the else edge — no continue block.
        let mut cont_args: Vec<ValueId> = Vec::new();
        if let Some((_, acc_ir)) = &acc_param {
            let payload_lane = extract_lane(ctx, &mut body_block, cont_lane as u32)?;
            let payload = convert_scalar(ctx, &mut body_block, payload_lane, &lane_ty, acc_ir);
            cont_args.push(payload);
        }
        body_block.body.push(InstrNode::new(Inst::CondBr {
            cond: is_break,
            then_target: break_id,
            then_args: Vec::new(),
            else_target: header_id,
            else_args: cont_args,
        }));
        ctx.extra_blocks.push(body_block);

        // === break: spill the Break `cf` into dest_slot ONCE (`cf` dominates
        // this block); go to the successor. ===
        let mut break_block = Block::new(break_id);
        for lane in 0..lanes {
            let offset = u64::from(lane) * lane_size;
            let extracted = extract_lane(ctx, &mut break_block, lane)?;
            let dst_addr = slot_byte_ptr(ctx, &mut break_block, dest_slot, offset);
            emit_typed_store(&mut break_block, dst_addr, lane_ty.clone(), extracted);
        }
        emit_exit(&mut break_block);
        ctx.extra_blocks.push(break_block);
    } else {
        // Fallback: spill the returned `ControlFlow` into dest_slot lane by lane
        // every step, read the tag from memory (handles the niche encodings),
        // and thread the Continue payload back to the header from a small
        // continue block.
        let continue_id = ctx.fresh_block_id();
        // A scalar pair was already stored at its exact ABI lane offsets, and
        // an indirect return wrote the whole value into the slot. Do not read
        // or invent aggregate padding between those lanes.
        if cf.is_some() {
            for lane in 0..lanes {
                let offset = u64::from(lane) * lane_size;
                let extracted = extract_lane(ctx, &mut body_block, lane)?;
                let dst_addr = slot_byte_ptr(ctx, &mut body_block, dest_slot, offset);
                emit_typed_store(&mut body_block, dst_addr, lane_ty.clone(), extracted);
            }
        }
        let disc = emit_tag_discriminant_from_base(
            ctx,
            &mut body_block,
            dest_slot,
            &tag,
            &TrustIrTy::I64,
        )?;
        let break_c = emit_i64_const(ctx, &mut body_block, break_discr);
        let is_break = ctx.fresh_value();
        body_block.body.push(
            InstrNode::new(Inst::ICmp {
                op: ICmpOp::Eq,
                ty: TrustIrTy::I64,
                lhs: disc,
                rhs: break_c,
            })
            .with_result(is_break),
        );
        body_block.body.push(InstrNode::new(Inst::CondBr {
            cond: is_break,
            then_target: break_id,
            then_args: Vec::new(),
            else_target: continue_id,
            else_args: Vec::new(),
        }));
        ctx.extra_blocks.push(body_block);

        // === continue: read the Continue payload (the next acc) out of the
        // spilled cf; loop with it as the back-edge argument. ===
        let mut continue_block = Block::new(continue_id);
        let mut cont_args: Vec<ValueId> = Vec::new();
        if let Some((_, acc_ir)) = &acc_param {
            let payload_addr = iter_field_addr(ctx, &mut continue_block, dest_slot, cont_off);
            let new_acc = emit_typed_load(ctx, &mut continue_block, payload_addr, acc_ir.clone());
            cont_args.push(new_acc);
        }
        continue_block.body.push(InstrNode::new(Inst::Br {
            target: header_id,
            args: cont_args,
        }));
        ctx.extra_blocks.push(continue_block);

        // === break: dest_slot already holds cf (= Break(b)); go to the successor. ===
        let mut break_block = Block::new(break_id);
        emit_exit(&mut break_block);
        ctx.extra_blocks.push(break_block);
    }

    // === exhausted (the chain's `not_found` block): build `Continue(acc)` into
    // dest_slot; go to the successor. ===
    let mut exhausted_block = Block::new(exhausted_id);
    let cont_tag = ctx.fresh_value();
    exhausted_block.body.push(
        InstrNode::new(Inst::Const {
            ty: tag.ty.clone(),
            // Direct: the declared Continue discriminant. Niche: the computed
            // Continue niche value stored at the tag word.
            value: Constant::Int(continue_niche_value.unwrap_or(cont_discr)),
        })
        .with_result(cont_tag),
    );
    let tag_addr = iter_field_addr(ctx, &mut exhausted_block, dest_slot, tag.offset);
    emit_typed_store(&mut exhausted_block, tag_addr, tag.ty.clone(), cont_tag);
    if let Some((p, acc_ir)) = &acc_param {
        let payload_addr = iter_field_addr(ctx, &mut exhausted_block, dest_slot, cont_off);
        emit_typed_store(&mut exhausted_block, payload_addr, acc_ir.clone(), *p);
    }
    emit_exit(&mut exhausted_block);
    ctx.extra_blocks.push(exhausted_block);

    // The ControlFlow result lives in the destination's memory slot (no scalar
    // bind), or, for a tag-only result, is the tag read back out of the scratch
    // image at the join every exit reaches.
    ctx.clear_full_place_bindings(dest_local);
    if let (Some(join), Some(scalar)) = (exit_join, scalar_result) {
        if tag.ty != scalar {
            return Err(format!(
                "iterator try_fold tag-only result `{cf_ty:?}`: tag {:?} is not its scalar \
                 {scalar:?}",
                tag.ty
            ));
        }
        let mut join_block = Block::new(join);
        let tag_addr = iter_field_addr(ctx, &mut join_block, dest_slot, tag.offset);
        let value = emit_typed_load(ctx, &mut join_block, tag_addr, tag.ty.clone());
        let target = prepare_assign_target(ctx, &call.destination)?;
        join_block.body.push(
            InstrNode::new(Inst::Copy {
                ty: scalar,
                operand: value,
            })
            .with_result(target.value),
        );
        finish_assign_target(ctx, body, &mut join_block, &call.destination, target)?;
        emit_try_fold_exit(&mut join_block, call);
        ctx.extra_blocks.push(join_block);
    }
    Ok(true)
}

/// Intercept `<ControlFlow<B,C> as PartialEq>::eq(a, b)` — the mapping `.any()` /
/// `.all()` use at O3 to turn the `try_fold` result into a `bool` (`result ==
/// Break` / `== Continue`, where the RHS is a promoted const `ControlFlow`). The
/// general call path fails closed on the `&ControlFlow` args + the promoted const;
/// we lower it directly as a discriminant comparison the backend already supports.
///
/// The comparison is exactly the callee's result only when all of these hold,
/// and each is checked on identity, never on a name:
///   * the self type is core's `ControlFlow` (its diagnostic item) — a user enum
///     that happens to be named `ControlFlow` has its own `PartialEq`;
///   * the callee is core's `#[automatically_derived]` `PartialEq::eq` impl for
///     it, comparing two `ControlFlow` values of the same type — a user free fn
///     or inherent method named `eq`, or a user `impl PartialEq<Local> for
///     ControlFlow<..>`, has an arbitrary body;
///   * every payload is `()` or uninhabited, so the derived `eq` reduces to
///     discriminant equality: `() == ()` is true and an uninhabited variant is
///     never compared. A zero-sized USER payload is not enough — its own `eq`
///     may return false;
///   * the tag is Direct.
/// Anything else returns `Ok(false)` and the call lowers through the general
/// path.
fn lower_control_flow_eq<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if call.args.len() != 2 || !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let tcx = ctx.tcx;
    let Some(cf_did) = tcx.get_diagnostic_item(rustc_span::sym::ControlFlow) else {
        return Ok(false);
    };
    // The callee: core's derived `PartialEq` impl method.
    let callee_did = callee.def_id();
    let Some(impl_did) = tcx.trait_impl_of_assoc(callee_did) else {
        return Ok(false);
    };
    if !std_def_is_interceptable(tcx, impl_did)
        || impl_did.krate != cf_did.krate
        || Some(tcx.impl_trait_id(impl_did)) != tcx.get_diagnostic_item(rustc_span::sym::PartialEq)
        || !tcx.is_automatically_derived(impl_did)
        || tcx.opt_item_name(callee_did) != Some(rustc_span::sym::eq)
    {
        return Ok(false);
    }
    // arg 0 = `&Self`, arg 1 = `&Rhs`; both must be the same `ControlFlow`.
    let a_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let b_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let (ty::Ref(_, a_inner, _) | ty::RawPtr(a_inner, _)) = a_ty.kind() else {
        return Ok(false);
    };
    let (ty::Ref(_, b_inner, _) | ty::RawPtr(b_inner, _)) = b_ty.kind() else {
        return Ok(false);
    };
    let cf_ty = ctx.monomorphize_ty(*a_inner);
    if ctx.monomorphize_ty(*b_inner) != cf_ty {
        return Ok(false);
    }
    let ty::Adt(adt, cf_args) = cf_ty.kind() else {
        return Ok(false);
    };
    if adt.did() != cf_did || adt.variants().len() != 2 {
        return Ok(false);
    }
    // Every payload is `()` or uninhabited (see the doc comment).
    for variant in adt.variants() {
        for field in &variant.fields {
            let fty = ctx.monomorphize_ty(field.ty(tcx, *cf_args).skip_normalization());
            let uninhabited = tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(fty))
                .is_ok_and(|layout| layout.is_uninhabited());
            if !fty.is_unit() && !uninhabited {
                return Ok(false);
            }
        }
    }
    let Some(layout) = memory_aggregate_layout_shared(ctx.tcx, cf_ty)? else {
        return Ok(false);
    };
    let Some(tag) = layout.tag.clone() else {
        return Ok(false);
    };
    if !matches!(tag.encoding, MemoryTagEncoding::Direct) {
        return Ok(false);
    }
    // Pointers to the two `ControlFlow` values (arg 1's promoted const materializes
    // to a readable allocation pointer through the normal const-operand path).
    let ptr_a = lower_operand_to_value(ctx, body, block, &call.args[0].node)?;
    let ptr_b = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let disc_a = emit_tag_discriminant_from_base(ctx, block, ptr_a, &tag, &TrustIrTy::I64)?;
    let disc_b = emit_tag_discriminant_from_base(ctx, block, ptr_b, &tag, &TrustIrTy::I64)?;
    let eq = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: TrustIrTy::I64,
            lhs: disc_a,
            rhs: disc_b,
        })
        .with_result(eq),
    );
    // `finish_assign_target` (not a bare `bind_scalar_value`) so an ADDRESS-TAKEN
    // destination's scalar cell is stored — the capture-of-terminal-result P0
    // class (2026-07-17; see the generic iterator consumer's exit).
    finish_assign_target(
        ctx,
        body,
        block,
        call.destination,
        AssignTarget {
            value: eq,
            binding: ScalarPlaceBinding::Local(call.destination.local),
            preserve_self_borrow: false,
        },
    )?;
    emit_call_successor(block, call.target);
    Ok(true)
}

/// Terminate a try_fold exit block by branching to the call's MIR successor (or
/// `Unreachable` if the call has no return target — a diverging path).
/// Whether `ty` is core's `NeverShortCircuit<T>` (`core::ops::try_trait`), the
/// infallible `Try` type `fold` hands to `try_fold` when an adapter implements
/// `fold` through it: a one-field struct holding the accumulator, whose
/// `try_fold` never breaks.
fn is_never_short_circuit<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, _) = ty.kind() else {
        return false;
    };
    adt.is_struct()
        && adt.non_enum_variant().fields.len() == 1
        && tcx.crate_name(adt.did().krate).as_str() == "core"
        && tcx.def_path_str(adt.did()) == "core::ops::try_trait::NeverShortCircuit"
}

/// [`lower_iter_try_fold`] for a `NeverShortCircuit<Acc>` result (wasm32): the
/// check closure is `NeverShortCircuit::wrap_mut_2(f)`, which returns
/// `NeverShortCircuit(f(acc, item))` and never breaks, so the drive is an
/// exhaustive fold: the accumulator is a loop-carried block parameter, each
/// item's check result is the next accumulator, and exhaustion binds the
/// destination to the final one. Admitted only where the accumulator is one
/// integer or float scalar, the result struct is exactly its bytes, the check
/// body is declared returning exactly that scalar (no buffer, pair or cast
/// plan), and the destination holds it as that scalar; anything else fails
/// closed. The chain and closure admission (`lower_iter_try_fold`'s gates) are
/// the caller's.
#[allow(clippy::too_many_arguments)]
fn lower_iter_try_fold_never_short_circuit<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    chain: &IterChain<'tcx>,
    check_ty: Ty<'tcx>,
    check_is_zst: bool,
    result_ty: Ty<'tcx>,
) -> Result<bool, String> {
    let refuse = |why: &str| Err(format!("iterator try_fold into NeverShortCircuit: {why}"));
    let acc_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let ty::Adt(adt, args) = result_ty.kind() else {
        return refuse("the result is not a struct");
    };
    let field_ty = ctx.monomorphize_ty(ctx_field_ty(ctx.tcx, adt.non_enum_variant(), *args, 0));
    if field_ty != acc_ty {
        return refuse("the result does not wrap the accumulator");
    }
    let layout_of = |ty: Ty<'tcx>| {
        ctx.tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
            .map_err(|e| format!("iterator try_fold layout_of({ty:?}) failed: {e:?}"))
    };
    let (acc_layout, result_layout) = (layout_of(acc_ty)?, layout_of(result_ty)?);
    if acc_layout.size != result_layout.size
        || acc_layout.align.bytes() != result_layout.align.bytes()
    {
        return refuse("the result is not exactly the accumulator's bytes");
    }
    let acc_ir = rust_ty_to_trust_ir_ty(ctx.tcx, acc_ty)?;
    if !(acc_ir.is_integer() || acc_ir.is_float()) || acc_ir.bit_width().is_none_or(|b| b > 64) {
        return refuse("the accumulator is not one integer or float scalar");
    }
    if place_trust_ir_ty(ctx, body, call.destination)? != acc_ir {
        return refuse("the destination does not hold the accumulator scalar");
    }
    let instance = closure_body_instance(ctx, check_ty)?;
    refuse_unthreaded_caller_location(ctx.tcx, instance)?;
    let callee = ctx.extern_callee(instance)?;
    if ctx.sret_returns.contains_key(&instance)
        || ctx.scalar_pair_returns.contains_key(&instance)
        || ctx.small_cast_returns.contains_key(&instance)
        || ctx.carrier_sret_returns.contains_key(&instance)
    {
        return refuse("the check closure returns through an ABI plan");
    }
    let declared_returns = ctx
        .module
        .function_by_id(callee)
        .map(|f| ctx.module.func_types[f.ty.index() as usize].returns.clone())
        .ok_or_else(|| "iterator try_fold check closure declaration is missing".to_owned())?;
    if declared_returns != [acc_ir.clone()] {
        return refuse("the check closure is not declared returning the accumulator scalar");
    }

    let init_val = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let chain_slot = lower_operand_to_value(ctx, body, block, &call.args[0].node)?;
    emit_rev_clamp(ctx, block, chain, chain_slot)?;

    let header_id = ctx.fresh_block_id();
    let mut header = Block::new(header_id);
    let acc = ctx.fresh_value();
    header.params.push((acc, acc_ir.clone()));
    let out = emit_chain_next(
        ctx,
        chain,
        chain_slot,
        block,
        &mut header,
        header_id,
        &[acc],
        &SourceCursor::Slot,
    )?;
    ctx.extra_blocks.push(header);
    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: vec![init_val],
    }));

    let mut body_block = Block::new(out.found_id);
    let check_env_ptr = if check_is_zst {
        chain_slot
    } else {
        closure_env_ptr(ctx, body, &mut body_block, &call.args[2].node)?
    };
    let call_args = closure_body_call_args_from_values(
        ctx,
        &mut body_block,
        instance,
        Some(check_env_ptr),
        vec![acc, out.item[0]],
    )?;
    let next_acc = ctx.fresh_value();
    push_unwindable_intercept_call(ctx, &mut body_block, callee, call_args, Some(next_acc));
    body_block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: vec![next_acc],
    }));
    ctx.extra_blocks.push(body_block);

    let mut exit_block = Block::new(out.not_found_id);
    if let Some(slot) = ctx.memory_slots.get(&call.destination.local).cloned() {
        emit_typed_store(&mut exit_block, slot.ptr, acc_ir, acc);
    }
    finish_assign_target(
        ctx,
        body,
        &mut exit_block,
        call.destination,
        AssignTarget {
            value: acc,
            binding: ScalarPlaceBinding::Local(call.destination.local),
            preserve_self_borrow: false,
        },
    )?;
    emit_try_fold_exit(&mut exit_block, call);
    ctx.extra_blocks.push(exit_block);
    Ok(true)
}

fn emit_try_fold_exit(block: &mut Block, call: &DirectCallTerminator<'_, '_>) {
    if let Some(target) = call.target {
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        block.body.push(InstrNode::new(Inst::Unreachable));
    }
}

/// Which reducing / short-circuiting terminal we are lowering.
enum TerminalKind<'tcx> {
    /// `.find(p)`: yield the first element whose predicate (`&Item -> bool`) holds.
    /// Result `Option<Item>`. Short-circuits.
    Find { closure_ty: Ty<'tcx> },
    /// `.position(p)`: yield the index of the first element whose predicate
    /// (`Item -> bool`) holds. Result `Option<usize>`. Short-circuits.
    Position { closure_ty: Ty<'tcx> },
    /// `.any(p)`: `true` if any element's predicate (`Item -> bool`) holds. Result
    /// `bool`. Short-circuits on the first `true`.
    Any { closure_ty: Ty<'tcx> },
    /// `.all(p)`: `true` if every element's predicate (`Item -> bool`) holds.
    /// Result `bool`. Short-circuits on the first `false`.
    All { closure_ty: Ty<'tcx> },
    /// `.min()` / `.max()`: the smallest / largest element by integer compare.
    /// Result `Option<Item>`. Runs to exhaustion.
    MinMax { want_max: bool },
    /// `.min_by_key(f)` / `.max_by_key(f)`: the element minimizing / maximizing a
    /// scalar key (`&Item -> K`, K an integer). Result `Option<Item>`. Runs to
    /// exhaustion.
    MinMaxByKey {
        want_max: bool,
        closure_ty: Ty<'tcx>,
        key_ir: TrustIrTy,
    },
    /// `.min_by(cmp)` / `.max_by(cmp)`: the element that is smallest / largest
    /// under a user comparator `cmp(&Item, &Item) -> Ordering`. Result
    /// `Option<Item>`. Runs to exhaustion. `min_by` keeps the FIRST minimum,
    /// `max_by` the LAST maximum (std tie-break) — encoded by whether the replace
    /// condition is `cmp(best, item) == Greater` (min) or `!= Greater` (max).
    MinMaxByCmp {
        want_max: bool,
        closure_ty: Ty<'tcx>,
    },
    /// `.product()`: the product of all elements. Result a scalar.
    Product,
    /// `.last()`: the final element. Result `Option<Item>`. Runs to exhaustion.
    Last,
    /// `.nth(k)`: the element at index `k` (0-based). Result `Option<Item>`.
    /// Short-circuits once `k` elements have been skipped.
    Nth { k: ValueId },
}

/// Whether `ty`'s `Ord` is the integer order of its scalar lane `lane_ir`, the
/// comparison the `MinMax`/`MinMaxByKey` terminals emit (signed exactly when
/// `lane_ir` is signed). That holds for the primitive integers, `char` and `bool`,
/// and for core's `Ordering`, whose `Ord` compares its `i8` discriminants. Every
/// other type orders by its own `Ord::cmp`, which the terminal does not call.
fn ord_is_scalar_lane_order<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, lane_ir: &TrustIrTy) -> bool {
    if !lane_ir.is_integer() {
        return false;
    }
    let lane_signed = is_signed_trust_ir_integer(lane_ir);
    match ty.kind() {
        ty::Int(_) => lane_signed,
        ty::Uint(_) | ty::Char | ty::Bool => !lane_signed,
        ty::Adt(adt, _) => lane_signed && tcx.lang_items().ordering_enum() == Some(adt.did()),
        _ => false,
    }
}

/// Detect the `-O3`-inlined `iter().max()` / `iter().min()` shape: an
/// `Iterator::reduce` whose comparator (call arg 1) is the std-internal
/// `Iterator::max_by::fold` / `min_by::fold` closure over the default `Ord::cmp`.
/// Returns `Some(true)` for `max`, `Some(false)` for `min`, and `None` for any
/// other `reduce` (a user `reduce(|a, b| ..)` closure, or a non-closure arg) — the
/// caller then falls through to the fail-closed general path. We match on the
/// closure's def-path (`max_by::fold` / `min_by::fold` under `Iterator`) so a
/// user-defined function NAMED `max_by`/`min_by` cannot be mistaken for it.
fn reduce_ord_minmax_direction<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<Option<bool>, String> {
    // `reduce(self, comparator)` — exactly two MIR operands.
    if call.args.len() != 2 {
        return Ok(None);
    }
    let cmp_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let ty::Closure(def_id, cargs) = cmp_ty.kind() else {
        return Ok(None);
    };
    // Only core's own closure; the path match below alone would admit a user
    // item path that merely contains the same segments.
    if !is_upstream_std_library_def(ctx.tcx, *def_id) {
        return Ok(None);
    }
    // The std `max`/`min` reduce closure is the ZST `max_by::fold` / `min_by::fold`
    // closure; a capturing user comparator would not be ZST.
    if !is_zero_sized_ty(ctx.tcx, cmp_ty) {
        return Ok(None);
    }
    // `def_path_str` renders the full closure path, e.g.
    // `std::iter::Iterator::max_by::fold::{closure#0}`. Match the `max_by`/`min_by`
    // fold segment under `Iterator` — the std-internal `Iterator::max`/`min` =
    // `self.max_by(Ord::cmp)` / `self.min_by(Ord::cmp)` inlining. Any other closure
    // (a user `reduce` lambda) has a different path and falls through.
    // Untrimmed/no-visible printer: classifier-path rendering must not
    // trigger the visible-universe decode (~3.4 ms first-use; the first-item
    // warmup class). All consumers are module-segment substring matches,
    // identical in the def-path rendering.
    let path = rustc_middle::ty::print::with_no_visible_paths!(ctx.tcx.def_path_str(*def_id));
    let is_iterator = path.contains("Iterator::");
    let want_max = if is_iterator && path.contains("max_by::fold") {
        true
    } else if is_iterator && path.contains("min_by::fold") {
        false
    } else {
        return Ok(None);
    };
    // SOUNDNESS: the `{min,max}_by::fold` closure CAPTURES the inner comparator
    // (`self.{min,max}_by(compare)` -> `reduce({min,max}_by::fold(compare))`). The
    // plain-min/max shortcut is only correct when that comparator is EXACTLY
    // `Ord::cmp`. An EXPLICIT `.min_by(|a,b| ..)` / `.min_by(some_fn)` produces the
    // SAME `min_by::fold` wrapper path but captures a DIFFERENT (still-ZST) fn — its
    // custom order must NOT be flattened to `min`/`max` (that silently ignores the
    // comparator = a miscompile: `.min_by(|a,b| b.cmp(a))` is a MAX, not a min). So
    // require the single captured upvar to be the exact diagnostic-item identity
    // of `Ord::cmp` (a def-path substring is user-spoofable); otherwise fall through
    // (the comparator-carrying reduce is handled/fails-closed elsewhere).
    let upvars = cargs.as_closure().upvar_tys();
    let ord_cmp = ctx.tcx.get_diagnostic_item(rustc_span::sym::ord_cmp_method);
    let captured_is_ord_cmp = upvars.len() == 1
        && matches!(
            upvars[0].kind(),
            ty::FnDef(inner_def, _) if ord_cmp == Some(*inner_def)
        );
    if !captured_is_ord_cmp {
        return Ok(None);
    }
    Ok(Some(want_max))
}

/// Lower a reducing / short-circuiting terminal consumer (`.find` / `.position` /
/// `.any` / `.all` / `.min` / `.max` / `.min_by_key` / `.max_by_key` /
/// `.product` / `.last` / `.nth`) over a Range / slice / adapter chain.
///
/// Like `lower_iter_consumer`, the driving loop's carried state is memory-backed
/// (the chain slot + a few fresh scratch slots), so it is phi-free. Each iteration
/// advances the chain (`emit_chain_next`) and, in the body block, applies the
/// terminal's per-element logic; the SHORT-CIRCUITING terminals (`find` /
/// `position` / `any` / `all` / `nth`) branch straight to the exit on a hit (an
/// early break), while the reducers (`min`/`max`/`product`/`last`/by-key) loop to
/// exhaustion. The exit block materializes the result (an `Option` written through
/// `store_option_some_value`, or a bare scalar) and binds the destination.
fn lower_iter_terminal<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    name: &str,
) -> Result<bool, String> {
    let Some(self_arg) = call.args.first() else {
        return Ok(false);
    };
    let self_arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
    // The `Iterator` terminal consumers split into two receiver shapes:
    //   * by-value `self` (`min`/`max`/`product`/`last`): the arg is the iterator,
    //     resolved through its memory slot like `sum`/`fold`/`count`;
    //   * `&mut self` (`find`/`position`/`any`/`all`/`nth`): the arg is a `&mut`
    //     reference whose value IS the iterator's slot pointer.
    // Peel a single `&`/`&mut` to find the underlying iterator type for the chain.
    let iter_ty = match self_arg_ty.kind() {
        ty::Ref(_, inner, _) => ctx.monomorphize_ty(*inner),
        _ => self_arg_ty,
    };
    let Some(chain) = resolve_iter_chain(ctx, iter_ty)? else {
        return Ok(false);
    };
    if !call.destination.projection.is_empty() {
        return Err(format!("iterator {name} into projected destination"));
    }
    // A `.product()` whose selected `Product` impl the loop below does not model:
    // step aside to the real `Iterator::product` BEFORE emitting anything (see
    // `std_reduction_falls_through`; the `sum` arm of `lower_iterator_call` does the
    // same). The by-value receiver is the only `product` shape.
    if name == "product"
        && !matches!(self_arg_ty.kind(), ty::Ref(..))
        && std_reduction_falls_through(ctx, body, call, iter_ty, true)?
    {
        return Ok(false);
    }
    let is_ref_receiver = matches!(self_arg_ty.kind(), ty::Ref(..));
    // A by-value receiver and every payload are owned by the terminal; the exit
    // releases only a by-value receiver's owning source and the drive runs no
    // other glue for them. (A `&mut self` receiver needs none.)
    for (index, arg) in call.args.iter().enumerate() {
        let arg_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &arg.node)?);
        let role = format!("argument {index}");
        let lowering = format!("Iterator::{name}");
        if index == 0 && !is_ref_receiver {
            refuse_unlowered_consumed_iterator_drop(ctx.tcx, &chain, arg_ty, &role, &lowering)?;
        } else {
            refuse_unlowered_owned_drop(ctx.tcx, arg_ty, &role, &lowering)?;
        }
    }
    // The borrowed, short-circuiting terminals routed here
    // (`any`/`all`/`find`/`position`/`nth`) leave a `TakeWhile` in the caller's
    // hands afterwards. `emit_chain_next` reads and sets std's done-`flag`, but
    // this borrowed family has not been validated against std's state after an
    // early exit, so it stays fail-closed, mirroring the `lower_iter_try_fold`
    // gate for the optimized form.
    if is_ref_receiver
        && chain
            .adapters
            .iter()
            .any(|(a, _)| matches!(a.kind, AdapterKind::TakeWhile { .. }))
    {
        return Err(format!(
            "iterator {name} over a take_while chain is not modeled \
             (a borrowed short-circuit terminal hands TakeWhile's persistent done flag \
             back to its caller; that route is not validated)"
        ));
    }
    // A tuple-yielding chain (`.enumerate()`/`.zip()` with no collapsing `.map`)
    // is not consumed by any reducing terminal here (they all read the scalar item).
    if chain.item.tuple.is_some() {
        return Err(format!(
            "iterator {name} over a tuple-yielding chain is not modeled"
        ));
    }

    // The chain state slot. For a `&mut iter` receiver the operand's value is the
    // slot pointer; for a by-value `iter` receiver the operand is a (memory-backed)
    // place whose slot pointer is the chain state. (Mutating the state in place is
    // sound: a by-value receiver is moved in / dead after the call, and a `&mut`
    // receiver's iterator is consumed by the terminal.)
    let orig_chain_slot = if matches!(self_arg_ty.kind(), ty::Ref(..)) {
        lower_operand_to_value(ctx, body, block, &self_arg.node)?
    } else {
        let (Operand::Copy(src) | Operand::Move(src)) = &self_arg.node else {
            return Err(format!("iterator {name} self argument is not a place"));
        };
        if !src.projection.is_empty() {
            return Err(format!("iterator {name} self argument is projected"));
        }
        ctx.memory_slots
            .get(&src.local)
            .cloned()
            .ok_or_else(|| format!("iterator {name} self argument is not memory-backed"))?
            .ptr
    };

    // #111 — PRIVATE iterator-state copy (BY-VALUE receiver ONLY). The terminal
    // DRAINS the chain state in place (`emit_source_next` stores the advanced Range
    // `start` / slice `ptr` back into the slot). At O3, rustc's CSE/GVN can fold two
    // structurally-identical source-init sequences (`let a = (1..n).sum(); let b =
    // (1..n).sum();`) into ONE memory slot, so BOTH terminals resolve the SAME slot —
    // the first drains it and the second reduces over an exhausted iterator, yielding
    // the reduction IDENTITY (sum -> 0, product -> 1, …). To make each by-value
    // terminal own its own iterator state, copy the resolved slot's bytes into a
    // FRESH private alloca and drive over the copy; the original slot is never
    // mutated, so an O3-aliased slot is safe. (O0 already gives distinct slots, so
    // this is a no-op-on-correctness there too.)
    //
    // A `&mut self` receiver (the short-circuiting `find`/`position`/`any`/`all`/`nth`)
    // must NOT be copied: the iterator is borrowed, NOT moved in, so the CALLER may
    // reuse it after the terminal and expects the consumed elements to be drained
    // from the ORIGINAL slot (`let mut it = 0..n; it.find(..); it.sum();`). Draining a
    // private copy would leave `it` un-advanced — a miscompile. A `&mut` iterator is
    // not subject to the by-value CSE aliasing (its slot is a named, addressed local),
    // so the in-place drain is both required and sound there.
    let chain_slot = if is_ref_receiver {
        orig_chain_slot
    } else {
        copy_iter_state_to_private_slot(ctx, block, iter_ty, orig_chain_slot)?
    };

    // A rewritten below-rev take/skip: clamp the slot boundary BEFORE driving
    // (idempotent; the O0 rev ctor already clamped, an O3-inlined ctor did not).
    emit_rev_clamp(ctx, block, &chain, chain_slot)?;
    // By-value `last`/`product` are core's `fold` (the `spec_fold(.., last::some)`
    // route included); `min`/`max`/`reduce` pull their first item with `next` and
    // the borrowed family goes through `try_fold`/`nth`, both sequential.
    if !is_ref_receiver && matches!(name, "last" | "product") {
        emit_take_tra_fold_clamp(ctx, block, &chain, chain_slot, TakeFoldRoute::Fold)?;
    }

    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));

    // The scalar item representation type + the value-side scalar IR type (the
    // `&T` pointee for a reference item). Reducers compare / accumulate the scalar
    // value; `min`/`max`/`last`/`find`/`nth` carry the ITEM representation (the
    // `&T` pointer for a slice element) into the `Some` payload, matching the real
    // `Self::Item`.
    let item_repr_ir = chain.item.ir_ty.clone();
    let scalar_ir = chain
        .item
        .deref_elem_ir
        .clone()
        .unwrap_or_else(|| item_repr_ir.clone());

    // Resolve the terminal kind + validate its closure (if any) is a callable ZST.
    let validate_zst_closure =
        |ctx: &MirLoweringCtx<'tcx>, idx: usize| -> Result<Ty<'tcx>, String> {
            let cty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[idx].node)?);
            if !matches!(cty.kind(), ty::Closure(..)) {
                return Err(format!("iterator {name} payload is not a closure"));
            }
            if !is_zero_sized_ty(ctx.tcx, cty) {
                return Err(format!(
                    "iterator {name} with a capturing (non-ZST) closure is not modeled"
                ));
            }
            Ok(cty)
        };
    // `Some` exactly for `product`: the selected impl's arithmetic.
    let mut product_arith: Option<StdReductionArith> = None;
    let kind = match name {
        "find" => TerminalKind::Find {
            closure_ty: validate_zst_closure(ctx, 1)?,
        },
        "position" => TerminalKind::Position {
            closure_ty: validate_zst_closure(ctx, 1)?,
        },
        "any" => TerminalKind::Any {
            closure_ty: validate_zst_closure(ctx, 1)?,
        },
        "all" => TerminalKind::All {
            closure_ty: validate_zst_closure(ctx, 1)?,
        },
        "min" | "max" => {
            if !scalar_ir.is_integer() {
                return Err(format!("iterator {name} over a non-integer item"));
            }
            // The model compares the scalar lane; `Iterator::max`/`min` compare with
            // the item's `Ord::cmp`. Those agree only for a primitive order. Any other
            // item (a user newtype, `core::cmp::Reverse`) lowers `Iterator`'s body.
            // `Ord for &A` forwards to `A`.
            let item_ty = ctx.monomorphize_ty(chain.item.rust_ty).peel_refs();
            if !ord_is_scalar_lane_order(ctx.tcx, item_ty, &scalar_ir) {
                return Ok(false);
            }
            TerminalKind::MinMax {
                want_max: name == "max",
            }
        }
        "min_by" | "max_by" => {
            // `.min_by(cmp)` / `.max_by(cmp)`: `cmp(&Item, &Item) -> Ordering`. The
            // item must be a SCALAR (integer/float) — the reducer stores it as a
            // scalar payload and passes `&best`/`&item` to `cmp`. A non-scalar item
            // fails closed. (`cmp` is call arg 1, intercepted here directly, so the
            // `Iterator::min_by` body — which passes the fold closure by value — is
            // never lowered.)
            let closure_ty = validate_zst_closure(ctx, 1)?;
            // The DEREF'd item must be a scalar (integer/float). This covers a
            // by-value scalar item (`.copied().min_by(..)`, item_repr == scalar) AND
            // a reference item (`v.iter().min_by(..)` yields `&T`, item_repr a `Ptr`
            // with deref_elem_ir the scalar). The reducer materializes `&best`/`&item`
            // at `item_repr_ir` in both cases, which IS the `&Item` the comparator
            // expects (`&i32` / `&&i32` respectively). The drive branches on its
            // initialized-state flag before loading `best` or calling the comparator.
            if !(scalar_ir.is_integer() || scalar_ir.is_float()) {
                return Err(format!("iterator {name} over a non-scalar item"));
            }
            TerminalKind::MinMaxByCmp {
                want_max: name == "max_by",
                closure_ty,
            }
        }
        "min_by_key" | "max_by_key" => {
            let closure_ty = validate_zst_closure(ctx, 1)?;
            // The key fn's output must be a scalar integer (compared by <).
            let ty::Closure(_, cargs) = closure_ty.kind() else {
                return Err(format!("iterator {name} payload is not a closure"));
            };
            let sig = ctx
                .tcx
                .instantiate_bound_regions_with_erased(cargs.as_closure().sig());
            let out_ty = ctx.monomorphize_ty(sig.output());
            let key_ir = rust_ty_to_trust_ir_ty(ctx.tcx, out_ty)?;
            if !key_ir.is_integer() {
                return Err(format!("iterator {name} key is not an integer"));
            }
            // The key is compared as a scalar lane, which is its `Ord` only for a
            // primitive order; any other key type lowers `Iterator`'s body.
            if !ord_is_scalar_lane_order(ctx.tcx, out_ty, &key_ir) {
                return Ok(false);
            }
            TerminalKind::MinMaxByKey {
                want_max: name == "max_by_key",
                closure_ty,
                key_ir,
            }
        }
        "product" => {
            let acc = rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty)?;
            if !acc.is_integer() && !acc.is_float() {
                return Err("iterator product over a non-integer/non-float accumulator".to_owned());
            }
            // The arithmetic of the `Product` impl rustc SELECTED — see
            // `StdReductionArith` (a `Saturating<u64>` product used to wrap).
            product_arith = Some(std_sum_product_arith(
                ctx.tcx,
                dest_ty,
                chain.item.rust_ty,
                "product",
            )?);
            TerminalKind::Product
        }
        "last" => TerminalKind::Last,
        "nth" => {
            // `.nth(k)`: arg 1 is the `usize` index.
            if call.args.len() != 2 {
                return Err(format!("iterator nth with {} args", call.args.len()));
            }
            let k = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
            // Normalize to I64 (the loop's counter width).
            let k_ir = rust_ty_to_trust_ir_ty(
                ctx.tcx,
                ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?),
            )?;
            let k = convert_scalar(ctx, block, k, &k_ir, &TrustIrTy::I64);
            TerminalKind::Nth { k }
        }
        _ => return Ok(false),
    };
    // `last` holds the result it keeps while the chain's adapter closures run.
    if matches!(kind, TerminalKind::Last) {
        refuse_droppable_carry_across_payloads(
            ctx,
            call.unwind,
            chain_item_needs_drop(ctx, &chain.item)
                .then(|| ctx.monomorphize_ty(chain.item.rust_ty)),
            chain_calls_user_code(&chain),
            "iterator `last`'s kept result",
        )?;
    }
    // A by-value receiver is owned by the terminal: an unwind out of the drive
    // frees it. A `&mut` receiver stays the caller's to drop on unwind too.
    let drive = if is_ref_receiver {
        None
    } else {
        let drive = begin_consumed_owner_drive(ctx, call, &chain, chain_slot, None)?;
        Some(drive)
    };

    // Whether this terminal short-circuits (an early break out of the loop) vs runs
    // to exhaustion. Short-circuiting terminals branch from the body to the exit on
    // a hit; reducers always loop back to the header.
    let short_circuit = matches!(
        kind,
        TerminalKind::Find { .. }
            | TerminalKind::Position { .. }
            | TerminalKind::Any { .. }
            | TerminalKind::All { .. }
            | TerminalKind::Nth { .. }
    );

    // === Scratch slots ===
    // `have`: 1 if a result element was found/produced, else 0 (drives the
    // Some/None at exit for the Option terminals; also `any`/`all`'s bool).
    // `payload`: the carried item representation (find/last/min/max/by_key/nth) or
    // index (position).
    // `key`: the current best key (min_by_key/max_by_key).
    // `idx`: a running 0-based element index (position); also reused as the `nth`
    // countdown register.
    let alloca_typed =
        |ctx: &mut MirLoweringCtx<'tcx>, block: &mut Block, ty: TrustIrTy| -> ValueId {
            let v = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty,
                    count: None,
                    align: None,
                })
                .with_result(v),
            );
            v
        };
    let have_slot = alloca_typed(ctx, block, TrustIrTy::I64);
    // The payload-slot type: the carried item representation for the value-yielding
    // Option terminals; `usize` at the target's width (`usize_field_ty`) for
    // `.position()`, whose Option<usize> Some field is the matched INDEX, not the
    // element. The running index counts in `idx_slot`'s `I64` word and is
    // truncated to this width before it reaches the payload, so the Some/None
    // stores write the 4-byte field on a 32-bit target, never the bytes after it.
    let payload_ir = if matches!(kind, TerminalKind::Position { .. }) {
        usize_field_ty(ctx.tcx)
    } else {
        item_repr_ir.clone()
    };
    let payload_slot = alloca_typed(ctx, block, payload_ir.clone());
    let key_slot_ir = match &kind {
        TerminalKind::MinMax { .. } => scalar_ir.clone(),
        TerminalKind::MinMaxByKey { key_ir, .. } => key_ir.clone(),
        _ => TrustIrTy::I64,
    };
    let key_slot = alloca_typed(ctx, block, key_slot_ir);
    let idx_slot = alloca_typed(ctx, block, TrustIrTy::I64);
    // `product` accumulator slot (sized to the destination integer width).
    let prod_ir = if matches!(kind, TerminalKind::Product) {
        rust_ty_to_trust_ir_ty(ctx.tcx, dest_ty)?
    } else {
        TrustIrTy::I64
    };
    let prod_slot = alloca_typed(ctx, block, prod_ir.clone());

    // Initialize the scratch slots.
    let zero = emit_i64_const(ctx, block, 0);
    emit_typed_store(block, have_slot, TrustIrTy::I64, zero);
    match &kind {
        TerminalKind::All { .. } => {
            // `all` starts `true` (vacuously true over an empty iterator).
            let t = emit_i64_const(ctx, block, 1);
            emit_typed_store(block, have_slot, TrustIrTy::I64, t);
        }
        TerminalKind::Product => {
            // `product` starts at the multiplicative identity `1` / `1.0` (float —
            // rustc's `Product for f32/f64` is `fold(1.0, Mul::mul)`).
            let one = ctx.fresh_value();
            let one_const = if prod_ir.is_float() {
                Constant::Float(1.0)
            } else {
                Constant::Int(1)
            };
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: prod_ir.clone(),
                    value: one_const,
                })
                .with_result(one),
            );
            emit_typed_store(block, prod_slot, prod_ir.clone(), one);
        }
        TerminalKind::Nth { k } => {
            // The countdown register starts at `k`.
            emit_typed_store(block, idx_slot, TrustIrTy::I64, *k);
        }
        _ => {
            // `position`'s index starts at 0.
            emit_typed_store(block, idx_slot, TrustIrTy::I64, zero);
        }
    }
    // core's O(1) `Skip` / `Take` windows, `last` / `min` / `max` and `nth`
    // over a `Range` run: the source is left holding only what the terminal
    // still walks (for `nth`, advanced past the `k` skipped items, so the
    // countdown is spent).
    if emit_range_run_terminal_closed_form(ctx, block, &chain, chain_slot, &kind, is_ref_receiver) {
        emit_typed_store(block, idx_slot, TrustIrTy::I64, zero);
    }

    // Per-step scratch slots: a `&Item` materialization slot for a Filter
    // predicate + one for a `find` predicate / `*_by_key` fn. (The old `found` /
    // `item` scratch slots are gone — E1 hands the chain's result to the body as
    // live SSA; the chain's `found`/`not_found` blocks ARE the body/exit. The
    // terminal's own carried state — have/payload/key/idx/prod — stays
    // memory-backed in v1, so the header carries no params and the source
    // cursor keeps Slot mode: a `&mut self` receiver's chain slot is the
    // CALLER's live iterator and must observe the drained state.)
    // A scratch slot to materialize `&Item` for a `find` predicate / `*_by_key` fn.
    let item_ref_slot = alloca_typed(ctx, block, item_repr_ir.clone());
    // A SECOND `&Item` slot for a `min_by`/`max_by` comparator's `&best` argument
    // (it takes two references — the running best and the current item).
    let cmp_lhs_slot = alloca_typed(ctx, block, item_repr_ir.clone());
    // Whether an item handed to a by-reference closure (`find`, `*_by_key`,
    // `min_by` / `max_by`) is reloaded from its slot after the call: core's
    // `find` returns or drops, and its `*_by_key` / `*_by` reductions keep, the
    // item the closure may have written through `&Cell` (`shared_ref_item_reload`).
    let reload = shared_ref_item_reload(ctx, &chain.item, name)?;
    // The items a terminal DISCARDS are dropped where std drops them: a `find`
    // candidate its predicate rejects, an item `nth` skips, the result `last`
    // replaces. `position` / `any` / `all` move every item into their by-value
    // predicate, and `min` / `max` / `product` only take items with a primitive
    // order or arithmetic, which never need drop. A by-key or comparator
    // reduction drops each comparison's loser mid-reduction, which this drive
    // does not model, so a droppable item there fails closed.
    let discard = match &kind {
        TerminalKind::Find { .. } | TerminalKind::Nth { .. } | TerminalKind::Last => {
            discard_drop_plan(ctx, block, &chain.item, name)?
        }
        TerminalKind::MinMaxByKey { .. } | TerminalKind::MinMaxByCmp { .. }
            if chain_item_needs_drop(ctx, &chain.item) =>
        {
            return Err(format!(
                "[TCG-ITER-DISCARD-DROP] `{name}` drops the loser of each comparison, a \
                 `{:?}` item that needs drop; this drive does not model those drops — \
                 failing closed rather than skipping them",
                chain.item.rust_ty
            ));
        }
        _ => None,
    };

    // === Header: run the chain's `next`. ===
    let header_id = ctx.fresh_block_id();
    let mut header = Block::new(header_id);
    let out = emit_chain_next(
        ctx,
        &chain,
        chain_slot,
        block,
        &mut header,
        header_id,
        &[],
        &SourceCursor::Slot,
    )?;
    ctx.extra_blocks.push(header);

    let body_id = out.found_id;
    let exit_id = out.not_found_id;
    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: Vec::new(),
    }));

    // === Body: per-terminal logic. `cur_block`/`cur_id` is the block currently
    // being filled; a short-circuiting terminal may branch from a hit-block to the
    // exit. The non-hit path always loops back to the header. ===
    let mut body_block = Block::new(body_id);
    // The item representation (live SSA from the chain blocks) + scalar value side.
    let item_repr = out.item[0];
    let scalar_item = if chain.item.deref_elem_ir.is_some() {
        emit_typed_load(ctx, &mut body_block, item_repr, scalar_ir.clone())
    } else {
        item_repr
    };

    // Helper closure-call argument materializers (built inline below per kind).
    match &kind {
        TerminalKind::Any { closure_ty } | TerminalKind::All { closure_ty } => {
            let want_break_on = matches!(&kind, TerminalKind::Any { .. }); // any breaks on true; all breaks on false.
            // The predicate takes `Self::Item` BY VALUE.
            let keep = emit_closure_call_1(
                ctx,
                &mut body_block,
                *closure_ty,
                chain_slot,
                item_repr,
                TrustIrTy::Bool,
            )?;
            // Break condition = (keep == want_break_on).
            let break_target = ctx.fresh_block_id();
            let (then_t, else_t) = if want_break_on {
                (break_target, header_id) // any: keep -> break (set true)
            } else {
                (header_id, break_target) // all: keep -> continue; !keep -> break (set false)
            };
            body_block.body.push(InstrNode::new(Inst::CondBr {
                cond: keep,
                then_target: then_t,
                then_args: Vec::new(),
                else_target: else_t,
                else_args: Vec::new(),
            }));
            ctx.extra_blocks.push(body_block);
            // The break block sets the bool result and jumps to exit.
            let mut brk = Block::new(break_target);
            let v = emit_i64_const(ctx, &mut brk, if want_break_on { 1 } else { 0 });
            emit_typed_store(&mut brk, have_slot, TrustIrTy::I64, v);
            brk.body.push(InstrNode::new(Inst::Br {
                target: exit_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(brk);
        }
        TerminalKind::Find { closure_ty } => {
            // `find` predicate takes `&Self::Item`. Materialize `&item` into a slot,
            // which holds the item while the predicate runs.
            emit_typed_store(
                &mut body_block,
                item_ref_slot,
                item_repr_ir.clone(),
                item_repr,
            );
            let held = held_item_unwind_pad(ctx, &chain.item, item_ref_slot, name)?;
            let keep = emit_closure_call_via_pad(
                ctx,
                &mut body_block,
                *closure_ty,
                chain_slot,
                vec![item_ref_slot],
                TrustIrTy::Bool,
                held,
            )?;
            let candidate = if reload {
                emit_typed_load(ctx, &mut body_block, item_ref_slot, item_repr_ir.clone())
            } else {
                item_repr
            };
            let hit = ctx.fresh_block_id();
            // A rejected candidate is consumed: std's `find` drops it.
            let (reject_target, reject_args) =
                discard_edge(ctx, discard.as_ref(), candidate, header_id, Vec::new());
            body_block.body.push(InstrNode::new(Inst::CondBr {
                cond: keep,
                then_target: hit,
                then_args: Vec::new(),
                else_target: reject_target,
                else_args: reject_args,
            }));
            ctx.extra_blocks.push(body_block);
            // Hit: store the item payload + have=1, jump to exit.
            let mut hb = Block::new(hit);
            emit_typed_store(&mut hb, payload_slot, item_repr_ir.clone(), candidate);
            let one = emit_i64_const(ctx, &mut hb, 1);
            emit_typed_store(&mut hb, have_slot, TrustIrTy::I64, one);
            hb.body.push(InstrNode::new(Inst::Br {
                target: exit_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(hb);
        }
        TerminalKind::Position { closure_ty } => {
            // `position` predicate takes `Self::Item` by value; on a hit the result
            // is the current running index.
            let idx_val = emit_typed_load(ctx, &mut body_block, idx_slot, TrustIrTy::I64);
            let keep = emit_closure_call_1(
                ctx,
                &mut body_block,
                *closure_ty,
                chain_slot,
                item_repr,
                TrustIrTy::Bool,
            )?;
            // Increment the running index for the NEXT element (store before branch).
            let one = emit_i64_const(ctx, &mut body_block, 1);
            let next_idx = ctx.fresh_value();
            body_block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Add,
                    ty: TrustIrTy::I64,
                    lhs: idx_val,
                    rhs: one,
                })
                .with_result(next_idx),
            );
            emit_typed_store(&mut body_block, idx_slot, TrustIrTy::I64, next_idx);
            let hit = ctx.fresh_block_id();
            // core's `position` counts misses with `*acc += 1` under
            // `#[rustc_inherit_overflow_checks]`: with overflow checks on, a miss at
            // index `usize::MAX` panics. The `I64` index word reaches a 32-bit
            // `usize::MAX` only on wasm32 (a 64-bit target would need 2^64 misses),
            // so only wasm32 routes the miss edge through that check, and only
            // where the source's `position` is one that checks (`has_site`: the
            // slice iterator's override counts unchecked and wraps).
            let miss = if session_is_wasm32(ctx.tcx)
                && ctx.tcx.sess.overflow_checks()
                && std_panic_route::has_site(
                    ctx,
                    call,
                    &std_panic_route::StdFailure::Overflow(mir::BinOp::Add),
                )? {
                let miss_id = ctx.fresh_block_id();
                let mut miss = Block::new(miss_id);
                let max = emit_i64_const(ctx, &mut miss, i128::from(u32::MAX));
                let at_max = ctx.fresh_value();
                miss.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Eq,
                        ty: TrustIrTy::I64,
                        lhs: idx_val,
                        rhs: max,
                    })
                    .with_result(at_max),
                );
                let fail = std_panic_route::fail_target(
                    ctx,
                    body,
                    call,
                    std_panic_route::StdFailure::Overflow(mir::BinOp::Add),
                )?;
                miss.body.push(InstrNode::new(Inst::CondBr {
                    cond: at_max,
                    then_target: fail,
                    then_args: Vec::new(),
                    else_target: header_id,
                    else_args: Vec::new(),
                }));
                ctx.extra_blocks.push(miss);
                miss_id
            } else {
                header_id
            };
            body_block.body.push(InstrNode::new(Inst::CondBr {
                cond: keep,
                then_target: hit,
                then_args: Vec::new(),
                else_target: miss,
                else_args: Vec::new(),
            }));
            ctx.extra_blocks.push(body_block);
            let mut hb = Block::new(hit);
            // Store the CURRENT (pre-increment) index as the Option<usize> payload,
            // at the payload's `usize` width.
            let idx_out = emit_trunc_from_i64(ctx, &mut hb, &payload_ir, idx_val);
            emit_typed_store(&mut hb, payload_slot, payload_ir.clone(), idx_out);
            let one = emit_i64_const(ctx, &mut hb, 1);
            emit_typed_store(&mut hb, have_slot, TrustIrTy::I64, one);
            hb.body.push(InstrNode::new(Inst::Br {
                target: exit_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(hb);
        }
        TerminalKind::Nth { .. } => {
            // `.nth(k)`: countdown in `idx_slot`. If 0, this is the target element:
            // store payload + have=1, break. Else decrement and loop.
            let rem = emit_typed_load(ctx, &mut body_block, idx_slot, TrustIrTy::I64);
            let z = emit_i64_const(ctx, &mut body_block, 0);
            let is_zero = ctx.fresh_value();
            body_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Eq,
                    ty: TrustIrTy::I64,
                    lhs: rem,
                    rhs: z,
                })
                .with_result(is_zero),
            );
            let one = emit_i64_const(ctx, &mut body_block, 1);
            let dec = ctx.fresh_value();
            body_block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Sub,
                    ty: TrustIrTy::I64,
                    lhs: rem,
                    rhs: one,
                })
                .with_result(dec),
            );
            emit_typed_store(&mut body_block, idx_slot, TrustIrTy::I64, dec);
            let hit = ctx.fresh_block_id();
            // A skipped item is consumed: std's `nth` drops it. Over a `Range`
            // run, core skips the other `k - 1` with the inner `nth` in O(1):
            // consume them in closed form, then pull the item `nth` returns.
            let (skip_target, skip_args) = if discard.is_none() && chain_is_range_run(&chain, false)
            {
                let fast_id = ctx.fresh_block_id();
                let mut fast = Block::new(fast_id);
                let spent = emit_i64_const(ctx, &mut fast, 0);
                emit_typed_store(&mut fast, idx_slot, TrustIrTy::I64, spent);
                let args = emit_skip_range_source_fast_forward(
                    ctx,
                    &mut fast,
                    &chain,
                    chain_slot,
                    &chain.adapters,
                    &SourceCursor::Slot,
                    None,
                    dec,
                    &[],
                )?;
                fast.body.push(InstrNode::new(Inst::Br {
                    target: header_id,
                    args,
                }));
                ctx.extra_blocks.push(fast);
                (fast_id, Vec::new())
            } else {
                discard_edge(ctx, discard.as_ref(), item_repr, header_id, Vec::new())
            };
            body_block.body.push(InstrNode::new(Inst::CondBr {
                cond: is_zero,
                then_target: hit,
                then_args: Vec::new(),
                else_target: skip_target,
                else_args: skip_args,
            }));
            ctx.extra_blocks.push(body_block);
            let mut hb = Block::new(hit);
            emit_typed_store(&mut hb, payload_slot, item_repr_ir.clone(), item_repr);
            let one = emit_i64_const(ctx, &mut hb, 1);
            emit_typed_store(&mut hb, have_slot, TrustIrTy::I64, one);
            hb.body.push(InstrNode::new(Inst::Br {
                target: exit_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(hb);
        }
        TerminalKind::Last => {
            // `last`: store the current item as the running result; have=1; loop.
            // The result it replaces is consumed: std's `last` (`fold(None,
            // some)`) drops it once the next item has been pulled.
            if let Some(plan) = &discard {
                let have = emit_typed_load(ctx, &mut body_block, have_slot, TrustIrTy::I64);
                let z = emit_i64_const(ctx, &mut body_block, 0);
                let had = emit_i64_icmp(ctx, &mut body_block, ICmpOp::Ne, have, z);
                let drop_id = ctx.fresh_block_id();
                let store_id = ctx.fresh_block_id();
                body_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: had,
                    then_target: drop_id,
                    then_args: Vec::new(),
                    else_target: store_id,
                    else_args: Vec::new(),
                }));
                let tested = std::mem::replace(&mut body_block, Block::new(store_id));
                ctx.extra_blocks.push(tested);
                let mut drop_block = Block::new(drop_id);
                let replaced =
                    emit_typed_load(ctx, &mut drop_block, payload_slot, item_repr_ir.clone());
                emit_discard_drop(ctx, &mut drop_block, plan, replaced);
                drop_block.body.push(InstrNode::new(Inst::Br {
                    target: store_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(drop_block);
            }
            emit_typed_store(
                &mut body_block,
                payload_slot,
                item_repr_ir.clone(),
                item_repr,
            );
            let one = emit_i64_const(ctx, &mut body_block, 1);
            emit_typed_store(&mut body_block, have_slot, TrustIrTy::I64, one);
            body_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(body_block);
        }
        TerminalKind::MinMax { want_max } => {
            // The first item establishes both payload and comparison key before
            // either slot may be read. Subsequent items compare against initialized
            // state. `min` keeps the FIRST equal minimum (strict `<`); `max` keeps
            // the LAST equal maximum (`>=`). The latter distinction is observable
            // for reference items even when the compared values are equal.
            let have = emit_typed_load(ctx, &mut body_block, have_slot, TrustIrTy::I64);
            let z = emit_i64_const(ctx, &mut body_block, 0);
            let no_result = ctx.fresh_value();
            body_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Eq,
                    ty: TrustIrTy::I64,
                    lhs: have,
                    rhs: z,
                })
                .with_result(no_result),
            );
            let first_id = ctx.fresh_block_id();
            let compare_id = ctx.fresh_block_id();
            body_block.body.push(InstrNode::new(Inst::CondBr {
                cond: no_result,
                then_target: first_id,
                then_args: Vec::new(),
                else_target: compare_id,
                else_args: Vec::new(),
            }));
            ctx.extra_blocks.push(body_block);

            let mut first_block = Block::new(first_id);
            emit_typed_store(
                &mut first_block,
                payload_slot,
                item_repr_ir.clone(),
                item_repr,
            );
            emit_typed_store(&mut first_block, key_slot, scalar_ir.clone(), scalar_item);
            let one = emit_i64_const(ctx, &mut first_block, 1);
            emit_typed_store(&mut first_block, have_slot, TrustIrTy::I64, one);
            first_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(first_block);

            let mut compare_block = Block::new(compare_id);
            let best = emit_typed_load(ctx, &mut compare_block, key_slot, scalar_ir.clone());
            let signed = is_signed_trust_ir_integer(&scalar_ir);
            let op = match (*want_max, signed) {
                (true, true) => ICmpOp::Sge,
                (true, false) => ICmpOp::Uge,
                (false, true) => ICmpOp::Slt,
                (false, false) => ICmpOp::Ult,
            };
            let beats = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op,
                    ty: scalar_ir.clone(),
                    lhs: scalar_item,
                    rhs: best,
                })
                .with_result(beats),
            );
            let old_payload =
                emit_typed_load(ctx, &mut compare_block, payload_slot, item_repr_ir.clone());
            let new_payload = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::Select {
                    ty: item_repr_ir.clone(),
                    cond: beats,
                    then_val: item_repr,
                    else_val: old_payload,
                })
                .with_result(new_payload),
            );
            emit_typed_store(
                &mut compare_block,
                payload_slot,
                item_repr_ir.clone(),
                new_payload,
            );
            let new_best = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::Select {
                    ty: scalar_ir.clone(),
                    cond: beats,
                    then_val: scalar_item,
                    else_val: best,
                })
                .with_result(new_best),
            );
            emit_typed_store(&mut compare_block, key_slot, scalar_ir.clone(), new_best);
            compare_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(compare_block);
        }
        TerminalKind::MinMaxByCmp {
            want_max,
            closure_ty,
        } => {
            // Reduce by a user comparator `cmp(&best, &item) -> Ordering`. If no
            // result yet (have==0), take the item WITHOUT calling the comparator;
            // std invokes it exactly N-1 times for N items. Calling it for the first
            // item is observably wrong and would require reading an uninitialized
            // payload as `best`. Only the have!=0 path may load/call. There, replace
            // per the std
            // tie-break: min_by replaces when `cmp(best,item) == Greater` (best is
            // bigger, so item is the smaller / new min); max_by replaces when
            // `cmp(best,item) != Greater` (keep best ONLY if it is strictly greater,
            // so a tie takes the LATER item — max_by keeps the last maximum).
            let have = emit_typed_load(ctx, &mut body_block, have_slot, TrustIrTy::I64);
            let z = emit_i64_const(ctx, &mut body_block, 0);
            let no_result = ctx.fresh_value();
            body_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Eq,
                    ty: TrustIrTy::I64,
                    lhs: have,
                    rhs: z,
                })
                .with_result(no_result),
            );
            let first_id = ctx.fresh_block_id();
            let compare_id = ctx.fresh_block_id();
            body_block.body.push(InstrNode::new(Inst::CondBr {
                cond: no_result,
                then_target: first_id,
                then_args: Vec::new(),
                else_target: compare_id,
                else_args: Vec::new(),
            }));
            ctx.extra_blocks.push(body_block);

            let mut first_block = Block::new(first_id);
            emit_typed_store(
                &mut first_block,
                payload_slot,
                item_repr_ir.clone(),
                item_repr,
            );
            let one = emit_i64_const(ctx, &mut first_block, 1);
            emit_typed_store(&mut first_block, have_slot, TrustIrTy::I64, one);
            first_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(first_block);

            let mut compare_block = Block::new(compare_id);
            let old_payload =
                emit_typed_load(ctx, &mut compare_block, payload_slot, item_repr_ir.clone());
            // Materialize `&best` (cmp_lhs_slot) and `&item` (item_ref_slot).
            emit_typed_store(
                &mut compare_block,
                cmp_lhs_slot,
                item_repr_ir.clone(),
                old_payload,
            );
            emit_typed_store(
                &mut compare_block,
                item_ref_slot,
                item_repr_ir.clone(),
                item_repr,
            );
            // `Ordering` is a `#[repr(i8)]` enum (Less=-1, Equal=0, Greater=1).
            let ord = emit_closure_call_n(
                ctx,
                &mut compare_block,
                *closure_ty,
                chain_slot,
                vec![cmp_lhs_slot, item_ref_slot],
                TrustIrTy::I8,
            )?;
            // core's `cmp::max_by` / `min_by` keep `v1` (best) or `v2` (item)
            // as the comparator left them.
            let (old_payload, item_repr) = if reload {
                (
                    emit_typed_load(ctx, &mut compare_block, cmp_lhs_slot, item_repr_ir.clone()),
                    emit_typed_load(ctx, &mut compare_block, item_ref_slot, item_repr_ir.clone()),
                )
            } else {
                (old_payload, item_repr)
            };
            let greater = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I8,
                    value: Constant::Int(1),
                })
                .with_result(greater),
            );
            let beats = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if *want_max { ICmpOp::Ne } else { ICmpOp::Eq },
                    ty: TrustIrTy::I8,
                    lhs: ord,
                    rhs: greater,
                })
                .with_result(beats),
            );
            let new_payload = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::Select {
                    ty: item_repr_ir.clone(),
                    cond: beats,
                    then_val: item_repr,
                    else_val: old_payload,
                })
                .with_result(new_payload),
            );
            emit_typed_store(
                &mut compare_block,
                payload_slot,
                item_repr_ir.clone(),
                new_payload,
            );
            compare_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(compare_block);
        }
        TerminalKind::MinMaxByKey {
            want_max,
            closure_ty,
            key_ir,
        } => {
            // Reduce by a closure-computed integer key. The key fn takes `&Item`.
            emit_typed_store(
                &mut body_block,
                item_ref_slot,
                item_repr_ir.clone(),
                item_repr,
            );
            let new_key = emit_closure_call_1(
                ctx,
                &mut body_block,
                *closure_ty,
                chain_slot,
                item_ref_slot,
                key_ir.clone(),
            )?;
            // core pairs each key with the item its key fn saw (`(f(&x), x)`).
            let item_repr = if reload {
                emit_typed_load(ctx, &mut body_block, item_ref_slot, item_repr_ir.clone())
            } else {
                item_repr
            };
            let have = emit_typed_load(ctx, &mut body_block, have_slot, TrustIrTy::I64);
            let z = emit_i64_const(ctx, &mut body_block, 0);
            let no_result = ctx.fresh_value();
            body_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Eq,
                    ty: TrustIrTy::I64,
                    lhs: have,
                    rhs: z,
                })
                .with_result(no_result),
            );
            let first_id = ctx.fresh_block_id();
            let compare_id = ctx.fresh_block_id();
            body_block.body.push(InstrNode::new(Inst::CondBr {
                cond: no_result,
                then_target: first_id,
                then_args: Vec::new(),
                else_target: compare_id,
                else_args: Vec::new(),
            }));
            ctx.extra_blocks.push(body_block);

            // The key closure correctly runs once for every item, including the
            // first. Establish both running slots before any subsequent load.
            let mut first_block = Block::new(first_id);
            emit_typed_store(
                &mut first_block,
                payload_slot,
                item_repr_ir.clone(),
                item_repr,
            );
            emit_typed_store(&mut first_block, key_slot, key_ir.clone(), new_key);
            let one = emit_i64_const(ctx, &mut first_block, 1);
            emit_typed_store(&mut first_block, have_slot, TrustIrTy::I64, one);
            first_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(first_block);

            let mut compare_block = Block::new(compare_id);
            let best_key = emit_typed_load(ctx, &mut compare_block, key_slot, key_ir.clone());
            let signed = is_signed_trust_ir_integer(&key_ir);
            // `min_by_key` keeps the FIRST minimum; `max_by_key` keeps the LAST
            // maximum (matching std: min uses `<`, max uses `>=` on the key). So the
            // strict comparison differs: replace on `new < best` (min) / `new >= best`
            // (max).
            let op = match (*want_max, signed) {
                (true, true) => ICmpOp::Sge,
                (true, false) => ICmpOp::Uge,
                (false, true) => ICmpOp::Slt,
                (false, false) => ICmpOp::Ult,
            };
            let beats = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op,
                    ty: key_ir.clone(),
                    lhs: new_key,
                    rhs: best_key,
                })
                .with_result(beats),
            );
            let old_payload =
                emit_typed_load(ctx, &mut compare_block, payload_slot, item_repr_ir.clone());
            let new_payload = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::Select {
                    ty: item_repr_ir.clone(),
                    cond: beats,
                    then_val: item_repr,
                    else_val: old_payload,
                })
                .with_result(new_payload),
            );
            emit_typed_store(
                &mut compare_block,
                payload_slot,
                item_repr_ir.clone(),
                new_payload,
            );
            let stored_key = ctx.fresh_value();
            compare_block.body.push(
                InstrNode::new(Inst::Select {
                    ty: key_ir.clone(),
                    cond: beats,
                    then_val: new_key,
                    else_val: best_key,
                })
                .with_result(stored_key),
            );
            emit_typed_store(&mut compare_block, key_slot, key_ir.clone(), stored_key);
            compare_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(compare_block);
        }
        TerminalKind::Product => {
            // acc *= item with the SELECTED `Product` impl's arithmetic
            // (`emit_std_reduction_step`: IEEE `FMul`, the overflow-checked integer
            // `Mul`, `Wrapping`'s wrapping mul; `Saturating` products REFUSE there).
            // It may split `body_block` (the overflow check); the store and the
            // back-edge below append to the continuation.
            let arith = product_arith
                .ok_or_else(|| "iterator product: reduction arithmetic unresolved".to_owned())?;
            let acc = emit_typed_load(ctx, &mut body_block, prod_slot, prod_ir.clone());
            let item_conv = convert_scalar(ctx, &mut body_block, scalar_item, &scalar_ir, &prod_ir);
            let r = emit_std_reduction_step(
                ctx,
                body,
                &mut body_block,
                call,
                arith,
                true,
                &prod_ir,
                acc,
                item_conv,
            )?;
            emit_typed_store(&mut body_block, prod_slot, prod_ir.clone(), r);
            body_block.body.push(InstrNode::new(Inst::Br {
                target: header_id,
                args: Vec::new(),
            }));
            ctx.extra_blocks.push(body_block);
        }
    }
    let _ = short_circuit;
    if let Some(drive) = drive {
        drive.end(ctx);
    }

    // === Exit: drop a by-value receiver's consumed owning source (a `&mut`
    // receiver stays the caller's to drop), materialize the result + bind the
    // destination. Every hit and exhaustion path joins here. ===
    let mut exit_block = Block::new(exit_id);
    if !is_ref_receiver {
        emit_consumed_chain_drop(ctx, &mut exit_block, &chain, chain_slot)?;
    }
    match &kind {
        TerminalKind::Any { .. } | TerminalKind::All { .. } => {
            // The bool result lives in `have_slot` (1/0). Load + truncate to Bool.
            let v = emit_typed_load(ctx, &mut exit_block, have_slot, TrustIrTy::I64);
            let b = ctx.fresh_value();
            exit_block.body.push(
                InstrNode::new(Inst::Cast {
                    op: CastOp::Trunc,
                    src_ty: TrustIrTy::I64,
                    dst_ty: TrustIrTy::Bool,
                    operand: v,
                })
                .with_result(b),
            );
            // Route through `finish_assign_target` so an ADDRESS-TAKEN destination
            // (scalar cell) is STORED, not just SSA-bound — the capture-of-terminal-
            // result P0 class (2026-07-17; see the generic consumer's exit).
            finish_assign_target(
                ctx,
                body,
                &mut exit_block,
                call.destination,
                AssignTarget {
                    value: b,
                    binding: ScalarPlaceBinding::Local(call.destination.local),
                    preserve_self_borrow: false,
                },
            )?;
            finish_terminal_block(ctx, &mut exit_block, call);
            ctx.extra_blocks.push(exit_block);
        }
        TerminalKind::Product => {
            let v = emit_typed_load(ctx, &mut exit_block, prod_slot, prod_ir.clone());
            // Same address-taken-destination store as the Any/All arm above.
            finish_assign_target(
                ctx,
                body,
                &mut exit_block,
                call.destination,
                AssignTarget {
                    value: v,
                    binding: ScalarPlaceBinding::Local(call.destination.local),
                    preserve_self_borrow: false,
                },
            )?;
            finish_terminal_block(ctx, &mut exit_block, call);
            ctx.extra_blocks.push(exit_block);
        }
        _ => {
            // An Option<…> result. Split Some/None before reading `payload_slot`:
            // empty/no-hit terminals never initialize it, so a branchless load is
            // an invalid read even if the eventual Option tag would discard the
            // bytes. Only the Some block loads the carried item/index.
            let have = emit_typed_load(ctx, &mut exit_block, have_slot, TrustIrTy::I64);
            let hz = emit_i64_const(ctx, &mut exit_block, 0);
            let have_cond = ctx.fresh_value();
            exit_block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ne,
                    ty: TrustIrTy::I64,
                    lhs: have,
                    rhs: hz,
                })
                .with_result(have_cond),
            );
            let some_id = ctx.fresh_block_id();
            let none_id = ctx.fresh_block_id();
            exit_block.body.push(InstrNode::new(Inst::CondBr {
                cond: have_cond,
                then_target: some_id,
                then_args: Vec::new(),
                else_target: none_id,
                else_args: Vec::new(),
            }));
            ctx.extra_blocks.push(exit_block);

            let is_reference_payload = chain.item.deref_elem_ir.is_some()
                && !matches!(kind, TerminalKind::Position { .. });

            let mut some_block = Block::new(some_id);
            let payload_val =
                emit_typed_load(ctx, &mut some_block, payload_slot, payload_ir.clone());
            let true_cond = ctx.fresh_value();
            some_block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::Bool,
                    value: Constant::Bool(true),
                })
                .with_result(true_cond),
            );
            let some_payload = if is_reference_payload {
                OptionPayload::Reference { ptr: payload_val }
            } else {
                OptionPayload::Scalar {
                    value: payload_val,
                    ty: payload_ir.clone(),
                }
            };
            store_option_some_value(
                ctx,
                body,
                &mut some_block,
                call.destination.local,
                dest_ty,
                true_cond,
                some_payload,
            )?;
            finish_terminal_block(ctx, &mut some_block, call);
            ctx.extra_blocks.push(some_block);

            // `store_option_some_value` accepts one well-typed carrier even when
            // `cond=false`; supply an explicit typed zero/null built in the None
            // block, never bytes loaded from the uninitialized payload slot.
            let mut none_block = Block::new(none_id);
            let false_cond = ctx.fresh_value();
            none_block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::Bool,
                    value: Constant::Bool(false),
                })
                .with_result(false_cond),
            );
            let none_payload = if is_reference_payload {
                let zero = emit_i64_const(ctx, &mut none_block, 0);
                let null = ctx.fresh_value();
                none_block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::IntToPtr,
                        src_ty: TrustIrTy::I64,
                        dst_ty: TrustIrTy::Ptr,
                        operand: zero,
                    })
                    .with_result(null),
                );
                OptionPayload::Reference { ptr: null }
            } else if matches!(payload_ir, TrustIrTy::Ptr) {
                // Raw-pointer items use a direct-tagged `Option<*const T>` rather
                // than the reference niche. Its dead None payload still needs an
                // initialized pointer carrier; use null without classifying it as
                // `OptionPayload::Reference`.
                let zero = emit_i64_const(ctx, &mut none_block, 0);
                let null = ctx.fresh_value();
                none_block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::IntToPtr,
                        src_ty: TrustIrTy::I64,
                        dst_ty: TrustIrTy::Ptr,
                        operand: zero,
                    })
                    .with_result(null),
                );
                OptionPayload::Scalar {
                    value: null,
                    ty: TrustIrTy::Ptr,
                }
            } else {
                OptionPayload::Scalar {
                    value: emit_zero_scalar_const(ctx, &mut none_block, &payload_ir)?,
                    ty: payload_ir.clone(),
                }
            };
            store_option_some_value(
                ctx,
                body,
                &mut none_block,
                call.destination.local,
                dest_ty,
                false_cond,
                none_payload,
            )?;
            finish_terminal_block(ctx, &mut none_block, call);
            ctx.extra_blocks.push(none_block);

            // The Option lives in the destination's memory slot; clear any stale
            // scalar binding so reads go through the slot.
            ctx.clear_full_place_bindings(call.destination.local);
        }
    }

    Ok(true)
}

/// Terminate a synthesized terminal-consumer exit block: branch to the call's
/// normal successor (or `Unreachable` for a diverging call).
fn finish_terminal_block(
    ctx: &MirLoweringCtx<'_>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, '_>,
) {
    let _ = ctx;
    if let Some(target) = call.target {
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        block.body.push(InstrNode::new(Inst::Unreachable));
    }
}

/// Convert a scalar `value` of `from` to `to` (a no-op when equal, an integer
/// extend/truncate otherwise). Used so a `sum`'s element type can be folded into
/// a (possibly wider) accumulator.
fn convert_scalar(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    value: ValueId,
    from: &TrustIrTy,
    to: &TrustIrTy,
) -> ValueId {
    if from == to {
        return value;
    }
    // FLOAT->FLOAT width change (`f32`->`f64` = FPExt, `f64`->`f32` = FPTrunc): a
    // genuine value-preserving (or rounding) float conversion, NOT a bit-level
    // integer widen. `float_cast_op` returns `Some(None)` for an equal-width float
    // pair (no cast needed) and `Some(Some(op))` for a real FPExt/FPTrunc. A mixed
    // int/float pair never reaches `convert_scalar` from a float-aware caller (the
    // iterator element/accumulator types match in domain — both int or both float —
    // because rustc's `Sum`/`collect` impls require `Item == Accumulator`'s element
    // domain), so we only handle the same-domain cases here. Fall through to the
    // integer logic for an integer pair.
    if from.is_float() && to.is_float() {
        match float_cast_op(from, to) {
            Some(None) => return value,
            Some(Some(op)) => {
                let r = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op,
                        src_ty: from.clone(),
                        dst_ty: to.clone(),
                        operand: value,
                    })
                    .with_result(r),
                );
                return r;
            }
            None => return value,
        }
    }
    let from_bits = from.bit_width().unwrap_or(64);
    let to_bits = to.bit_width().unwrap_or(64);
    // A SAME-WIDTH integer conversion (e.g. `usize`->`i64` / `u32`->`i32`) is a
    // pure signedness reinterpretation — no bits change. Emitting a ZExt/SExt of
    // equal source/dest width is rejected by ISel ("invalid cast shape"), so model
    // it as the identity (the trust-ir value carries no signedness tag at the bit
    // level; consumers re-interpret per their op). Where the unconverted value
    // then reaches a block parameter of the other signedness, the module-level
    // legalization re-spells that edge from the value's ACTUAL type
    // (`canonicalize_copies`, LD-48); this function sees only the type its
    // caller names, not the value's own.
    if from_bits == to_bits {
        return value;
    }
    let op = if to_bits < from_bits {
        CastOp::Trunc
    } else if is_signed_trust_ir_integer(from) {
        CastOp::SExt
    } else {
        CastOp::ZExt
    };
    let r = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op,
            src_ty: from.clone(),
            dst_ty: to.clone(),
            operand: value,
        })
        .with_result(r),
    );
    r
}

/// The result of emitting an iterator chain's `next`: the ids of the `found` /
/// `not_found` continuation blocks — which the CALLER creates and owns (this
/// avoids a double-created block id: the chain only BRANCHES to them) — plus the
/// yielded item as LIVE SSA value(s). The chain is linear (a Filter reject exits
/// back to `entry_id`), so the item values, defined in the source/adapter
/// blocks, DOMINATE `found_id`: the caller's body reads them directly with zero
/// scratch slots and zero new phis.
///
/// `item` carries ONE value for a scalar / `&T` item and TWO for a tuple item
/// (`.zip()` / `.enumerate()`). A tuple item reaching `found` is only valid for
/// a consumer that IGNORES the item (`count`) — value-using consumers over a
/// tuple were rejected at resolve time — so callers read `item[0]` only for
/// non-tuple chains (the tuple-item-only-for-count rule).
struct ChainNextOut {
    /// The block the chain branches to with a yielded element (the caller's loop
    /// body). The caller creates `Block::new(found_id)`.
    found_id: BlockId,
    /// The block the chain branches to on exhaustion (the caller's loop exit).
    /// The caller creates `Block::new(not_found_id)`. Neither block carries
    /// params — the caller's loop-carried state lives on the HEADER's params.
    not_found_id: BlockId,
    /// The yielded item as live SSA value(s) (see the struct doc).
    item: Vec<ValueId>,
    /// `Some(advanced)` when the source cursor is in `Params` mode (E3): the
    /// post-advance cursor value the caller must pass as the FIRST back-edge
    /// argument on its body -> header branch. (Every chain-internal re-entry
    /// edge — Filter reject / Skip discard / StepBy re-pull — already forwards
    /// it, so the element is consumed even when filtered.)
    cursor_advanced: Option<ValueId>,
}

/// How the drive loop carries the source-iterator cursor (E3).
enum SourceCursor {
    /// v1 fallback: the cursor is loaded from / stored back to the chain slot
    /// every iteration (the original memory-backed protocol). Correct for every
    /// source, including a caller-owned `&mut self` slot (try_fold) that must
    /// observe the drained state after the loop.
    Slot,
    /// The cursor is a loop-carried header block param with the loop-invariant
    /// bound hoisted to the preheader: no per-iteration Select, no store. SOUND
    /// ONLY over a PRIVATE chain slot (the #111 fresh copy / a const image)
    /// whose exhausted-iterator cursor is unobservable. Strictly opt-in per
    /// matched source arm (Range fwd/rev, slice fwd — see
    /// `source_cursor_params_supported`); everything else stays `Slot`.
    Params { cursor: ValueId, bound: ValueId },
}

/// `true` for the source arms `SourceCursor::Params` is implemented for: a
/// `Range` (forward or reversed — the reversed cursor is the `end` lane) and a
/// FORWARD slice iterator. Everything else (`RangeInclusive`'s exhausted flag,
/// `Concat`'s two sub-states, `Zip`'s index cursor, a REVERSED slice) keeps the
/// `Slot` fallback in v1 and degrades safely.
fn source_cursor_params_supported(source: &ChainSource<'_>, reversed: bool) -> bool {
    match source {
        ChainSource::Range { .. } => true,
        ChainSource::Slice { .. } => !reversed,
        _ => false,
    }
}

/// Loop-invariant chain-slot field addresses, hoisted to the PREHEADER (the
/// block that branches into the loop header) instead of being rematerialized
/// per iteration (E4). The chain slot is a fixed alloca and every field offset
/// a constant, so the `const + ptr-arith` chains are invariant; the preheader
/// dominates the header and every chain/adapter block, so the hoisted values
/// are in scope everywhere in the loop. Only ADDRESSES are hoisted — the loads
/// and stores through them stay in-loop (the fields they name are mutated).
struct PreheaderAddrs<'b> {
    block: &'b mut Block,
    chain_slot: ValueId,
    cache: Vec<(u64, ValueId)>,
}

impl PreheaderAddrs<'_> {
    fn field_addr(&mut self, ctx: &mut MirLoweringCtx<'_>, offset: u64) -> ValueId {
        if offset == 0 {
            return self.chain_slot;
        }
        if let Some((_, v)) = self.cache.iter().find(|(o, _)| *o == offset) {
            return *v;
        }
        let v = iter_field_addr(ctx, self.block, self.chain_slot, offset);
        self.cache.push((offset, v));
        v
    }
}

/// The drop a bridge drive owes a by-value item it DISCARDS. std drops such an
/// item right where it stops using it: a `filter` / `skip_while` / `find`
/// reject, a `skip` / `step_by` / `nth` skip, the item a `take_while` stops at,
/// every item `count` counts, the result `last` replaces. A drive that moves the
/// item on instead (into a by-value closure, a collected `Vec`, the terminal's
/// result) owes nothing. This is the normal path; an item the drive holds while
/// a by-reference payload unwinds is dropped by that call's own landing pad
/// (`held_item_unwind_pad`).
struct DiscardDrop {
    glue: FuncId,
    /// A preheader scratch slot (outside the drive loop) that holds the item's
    /// whole image while its glue runs.
    slot: ValueId,
    ir_ty: TrustIrTy,
}

/// Whether a drive owes a drop for `item` when it discards it. A reference item
/// (`deref_elem_ir`) never does: its `rust_ty` may carry the pointee as a
/// placeholder (`chain_source_item`'s slice item), and dropping a `&T` drops
/// nothing. A tuple item does when either component does; any other item when
/// its `rust_ty` needs drop.
fn chain_item_needs_drop<'tcx>(ctx: &MirLoweringCtx<'tcx>, item: &ChainItem<'tcx>) -> bool {
    if item.deref_elem_ir.is_some() {
        return false;
    }
    if let Some((first, second)) = &item.tuple {
        return chain_item_needs_drop(ctx, first) || chain_item_needs_drop(ctx, second);
    }
    ctx.monomorphize_ty(item.rust_ty)
        .needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized())
}

/// Whether user code that receives `&item` for the chain item `item` can change
/// the item: a BY-VALUE item (or tuple component) whose type is `!Freeze`, i.e.
/// holds an `UnsafeCell` inline. core's `Cell<T>` is one: `.cloned()` yields it
/// by value once `clone_is_bitwise_copy` admits it, an owning `IntoIter` over
/// `Cell`s yields it, and a `map` closure may return one, or a struct over one.
/// A closure handed `&Cell<T>` writes it with `set`. A reference item (`&T`,
/// `deref_elem_ir`) cannot change: the closure receives `&&T`, and a write
/// through it lands in the element `T`, which the drive reads from memory.
/// Every `Freeze` item is unchanged by such a call (a write through `&T` to a
/// `Freeze` `T` is undefined behavior).
fn chain_item_writable_through_shared_ref<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    item: &ChainItem<'tcx>,
) -> bool {
    match &item.tuple {
        Some((first, second)) => {
            chain_item_writable_through_shared_ref(ctx, first)
                || chain_item_writable_through_shared_ref(ctx, second)
        }
        None => {
            item.deref_elem_ir.is_none()
                && !ctx
                    .monomorphize_ty(item.rust_ty)
                    .is_freeze(ctx.tcx, ty::TypingEnv::fully_monomorphized())
        }
    }
}

/// Whether a drive that materializes `&item` in a stack slot and calls user code
/// with that address (`filter`, `take_while`, `skip_while` and `inspect` in
/// `emit_chain_next`; `find`, `min_by_key` / `max_by_key` and `min_by` /
/// `max_by` in `lower_iter_terminal`) must RELOAD the item from the slot after
/// the call. core's adapters hand the closure `&x` for a local `x` and then move
/// `x` on, so the item that continues (is kept, returned, compared or dropped)
/// is the one the call left in the slot. `Ok(false)`: the item cannot change
/// through the reference (`chain_item_writable_through_shared_ref`), so the
/// stored value is still the item. `Ok(true)`: a by-value scalar item that can
/// change; the drive reloads it at its representation type. A tuple item that
/// can change refuses (`[TCG-ITER-INTERIOR-MUT-ITEM]`): its `&(A, B)` argument
/// is a by-value aggregate (`build_tuple_item_arg`) that no drive reads back.
fn shared_ref_item_reload<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    item: &ChainItem<'tcx>,
    consumer: &str,
) -> Result<bool, String> {
    if !chain_item_writable_through_shared_ref(ctx, item) {
        return Ok(false);
    }
    if item.tuple.is_some() {
        return Err(format!(
            "[TCG-ITER-INTERIOR-MUT-ITEM] `{consumer}` hands its closure `&{:?}`, a tuple \
             item with an interior-mutable (`!Freeze`) component the closure may write; \
             this drive passes a by-value copy of the tuple and does not read the \
             written components back — failing closed rather than dropping the writes",
            ctx.monomorphize_ty(item.rust_ty)
        ));
    }
    Ok(true)
}

/// The drop glue of an `item` a drive destroys itself, with the item's
/// alignment: `None` when the item owes no drop (`chain_item_needs_drop`). A
/// droppable item is admitted only when its whole image IS its single scalar
/// representation (`size_of` equals the scalar's width, so the stored scalar is
/// the value the glue reads) and its glue is the one the per-element drop loops
/// lower (`drop_glue_needs_drop_element_lowerable`). Any other droppable item
/// (a tuple carrying one, a wider or padded struct, a non-`Copy`-field struct)
/// fails closed with `refusal(item type)` rather than skipping its destructor.
fn chain_item_drop_glue<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    item: &ChainItem<'tcx>,
    refusal: impl FnOnce(Ty<'tcx>) -> String,
) -> Result<Option<(FuncId, u64)>, String> {
    if !chain_item_needs_drop(ctx, item) {
        return Ok(None);
    }
    let ty = ctx.monomorphize_ty(item.rust_ty);
    if item.tuple.is_some() || !drop_glue_needs_drop_element_lowerable(ctx.tcx, ty) {
        return Err(refusal(ty));
    }
    let (size, align) = element_layout_size_align(ctx.tcx, ty)?;
    let Some(bits) = item.ir_ty.bit_width() else {
        return Err(refusal(ty));
    };
    if size != u64::from(bits.div_ceil(8)) {
        return Err(refusal(ty));
    }
    let glue = ctx.extern_callee(Instance::resolve_drop_glue(ctx.tcx, ty))?;
    Ok(Some((glue, align)))
}

/// Plan the drop of a discarded `item` (see `DiscardDrop`): `None` when the item
/// owes none. A droppable item `chain_item_drop_glue` does not admit fails
/// closed, naming `site`. The scratch slot is allocated in `preheader`.
fn discard_drop_plan<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    preheader: &mut Block,
    item: &ChainItem<'tcx>,
    site: &str,
) -> Result<Option<DiscardDrop>, String> {
    let refusal = |ty: Ty<'tcx>| {
        format!(
            "[TCG-ITER-DISCARD-DROP] `{site}` discards a `{ty:?}` item, which needs drop; \
             this drive runs a discarded item's destructor only for a user-`Drop` struct \
             whose whole image is one scalar — failing closed rather than skipping it"
        )
    };
    let Some((glue, align)) = chain_item_drop_glue(ctx, item, refusal)? else {
        return Ok(None);
    };
    let slot = ctx.fresh_value();
    preheader.body.push(
        InstrNode::new(Inst::Alloca {
            ty: item.ir_ty.clone(),
            count: None,
            align: Some(align),
        })
        .with_result(slot),
    );
    Ok(Some(DiscardDrop {
        glue,
        slot,
        ir_ty: item.ir_ty.clone(),
    }))
}

/// The landing pad of a by-reference payload call (a `find` predicate, a
/// `filter` / `take_while` / `skip_while` predicate, an `inspect` closure) made
/// while the drive holds the item it passes in `slot`: `None` when nothing
/// needs it (`panic=abort`, an item that owes no drop, an unwind edge that is
/// not live), and then the call keeps the intercepted terminator's own edge.
///
/// std's frame owns that item while the payload runs, so when the payload
/// unwinds the item is dropped before the unwind leaves the drive. The pad
/// does the same: it drops the item in `slot` (as the payload left it, which
/// for an interior-mutable item is the image it wrote, `shared_ref_item_reload`)
/// with its glue, as a cleanup-path drop (a
/// destructor that unwinds there is a panic during cleanup and aborts,
/// `Terminate(InCleanup)`), then continues at the intercepted call's own
/// action (`emit_elem_cleanup_unwind_exit`). For a `Terminate` action the pad
/// carries the terminate pad's empty filter, so the search phase still stops in
/// this frame and the item is dropped before the abort, as std's own frames do.
///
/// A droppable item `chain_item_drop_glue` does not admit fails closed, and so
/// does a live edge in a body whose EH lowering is off
/// (`[TCG-ITER-UNWIND-DROP]`); `seed_eh_landing_pads` turns it on for every
/// body whose iterator call may need such a pad. Inside a by-value terminal
/// that owns heap memory (`begin_consumed_owner_drive`: a `collect` frees the
/// `Vec` it builds) the pad continues at that terminal's `release` instead of
/// the call's action, so the item is dropped first and the terminal's memory
/// is freed next, the order of std's frames. `emit_chain_next` refuses every
/// droppable item of a drive over an owning `vec::IntoIter` under
/// `panic=unwind`, so the item held there is one of a source that owns nothing.
fn held_item_unwind_pad<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    item: &ChainItem<'tcx>,
    slot: ValueId,
    site: &str,
) -> Result<Option<BlockId>, String> {
    if panic_is_abort(ctx.tcx) || !chain_item_needs_drop(ctx, item) {
        return Ok(None);
    }
    let Some(action) = ctx.intercept_unwind_action else {
        return Ok(None);
    };
    let filter = match action {
        mir::UnwindAction::Continue | mir::UnwindAction::Cleanup(_) => false,
        mir::UnwindAction::Terminate(_) if supports_rust_terminate_filter(ctx.tcx) => true,
        mir::UnwindAction::Terminate(_) | mir::UnwindAction::Unreachable => return Ok(None),
    };
    let refusal = |ty: Ty<'tcx>| {
        format!(
            "[TCG-ITER-DISCARD-DROP] `{site}` holds a `{ty:?}` item, which needs drop, while \
             its by-reference payload may unwind; this drive runs an item's destructor only \
             for a user-`Drop` struct whose whole image is one scalar — failing closed rather \
             than skipping it"
        )
    };
    let Some((glue, _)) = chain_item_drop_glue(ctx, item, refusal)? else {
        return Ok(None);
    };
    let exn_slot = ctx.eh_exn_slot.filter(|_| ctx.eh_active).ok_or_else(|| {
        format!(
            "[TCG-ITER-UNWIND-DROP] `{site}` holds an item that needs drop while its \
             by-reference payload may unwind, in a body without EH lowering: the unwind would \
             skip the item's destructor std runs — failing closed"
        )
    })?;
    let mut pad = Block::new(ctx.fresh_block_id());
    let pad_id = pad.id;
    let exn = ctx.fresh_value();
    let selector = ctx.fresh_value();
    pad.body.push(
        InstrNode::new(Inst::LandingPad {
            is_cleanup: !filter,
            catch_type_indices: if filter {
                vec![trust_cg_lower::function::RUST_EH_EMPTY_FILTER]
            } else {
                Vec::new()
            },
        })
        .with_results(vec![exn, selector]),
    );
    emit_exn_slot_store(&mut pad, exn_slot, exn);
    // User code may replace an image through an escaped mutable alias.
    ctx.bridge_map_images.clear();
    let terminate = terminate_pad_block(ctx, mir::UnwindTerminateReason::InCleanup)?;
    let cont_id = ctx.fresh_block_id();
    pad.body.push(InstrNode::new(Inst::Invoke {
        callee: glue,
        args: vec![slot],
        normal_dest: cont_id,
        normal_args: Vec::new(),
        unwind_dest: terminate,
    }));
    ctx.extra_blocks.push(pad);
    let mut cont = Block::new(cont_id);
    match consumed_owner_release_for(ctx, &action) {
        Some(owner) => cont.body.push(InstrNode::new(Inst::Br {
            target: owner.release,
            args: Vec::new(),
        })),
        None => emit_elem_cleanup_unwind_exit(ctx, &mut cont, &action)?,
    }
    ctx.extra_blocks.push(cont);
    Ok(Some(pad_id))
}

/// Whether a drive over `chain` calls user code from its adapters: a `map`,
/// `filter`, `filter_map`, `take_while`, `skip_while`, `scan`, `map_while` or
/// `inspect` closure, any of which may unwind out of the drive.
fn chain_calls_user_code(chain: &IterChain<'_>) -> bool {
    chain.adapters.iter().any(|(adapter, _)| {
        matches!(
            adapter.kind,
            AdapterKind::Map
                | AdapterKind::Filter
                | AdapterKind::FilterMap
                | AdapterKind::TakeWhile { .. }
                | AdapterKind::SkipWhile { .. }
                | AdapterKind::Scan { .. }
                | AdapterKind::MapWhile
                | AdapterKind::Inspect
        )
    })
}

/// Fail closed (`[TCG-ITER-UNWIND-CARRY]`) when a drive's terminal holds a value
/// that needs drop, `carried` (a `fold` accumulator, the result `last` keeps),
/// across calls into user code other than the call that owns that value
/// (`user_code`: an adapter closure, `chain_calls_user_code`, or a `flat_map`
/// closure). When such a call unwinds, std's frame that holds the value drops
/// it; this drive keeps the value in its own state and has no landing pad that
/// drops it, so the unwind would skip that destructor
/// (`iter_chain_unwind_item_differential_aarch64`'s `refuse_*_accumulator_*`
/// and `refuse_last_result_*` rows). The terminal's own closure (`fold`'s)
/// receives the accumulator by value and drops it itself.
/// Nothing is refused under `panic=abort`, for an `Unreachable` unwind action,
/// for a value that needs no drop (`carried` is `None` or its type owes none),
/// or for a drive with no such call. The `Vec` a `collect` builds is not such a
/// value: the terminal's own pad frees it (`begin_consumed_owner_drive`).
fn refuse_droppable_carry_across_payloads<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    unwind: &mir::UnwindAction,
    carried: Option<Ty<'tcx>>,
    user_code: bool,
    what: &str,
) -> Result<(), String> {
    let Some(carried) = carried else {
        return Ok(());
    };
    if panic_is_abort(ctx.tcx)
        || matches!(unwind, mir::UnwindAction::Unreachable)
        || !user_code
        || !carried.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized())
    {
        return Ok(());
    }
    Err(format!(
        "[TCG-ITER-UNWIND-CARRY] {what} is a `{carried:?}`, which needs drop, held across \
         calls into user code that may unwind: std's frame drops that value when one \
         does, and this drive has no landing pad that drops it — failing closed"
    ))
}

/// Whether a call is a `collect` / `from_iter` of the real standard library
/// into a `Vec` this backend models: the calls `lower_vec_collect` may lower
/// (`lower_vec_call` names them by their `Vec` destination), each of which owns
/// the pad that frees the `Vec` it builds (`begin_consumed_owner_drive`). A
/// superset of those drives, so `seed_eh_landing_pads` can turn EH lowering on
/// for them.
fn call_collects_into_vec<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    func: &Operand<'tcx>,
    destination: &Place<'tcx>,
) -> bool {
    let callee_ty = ctx.monomorphize_ty(func.ty(body, ctx.tcx));
    let ty::FnDef(def_id, _) = *callee_ty.kind() else {
        return false;
    };
    is_std_collection_method_callee(ctx.tcx, def_id)
        && matches!(
            callee_item_name_str(ctx.tcx, def_id).as_str(),
            "collect" | "from_iter"
        )
        && vec_element_ty(
            ctx.tcx,
            ctx.monomorphize_ty(destination.ty(body, ctx.tcx).ty),
        )
        .is_some()
}

/// Whether a call may be lowered as a drive that holds an item needing drop
/// (`held_item_unwind_pad`): its callee is std's, and some argument, through
/// one reference, resolves as an iterator chain whose source item or some
/// adapter's output item needs drop. Every argument is asked, not only the
/// receiver: `Vec::extend` drives its second (`lower_vec_extend_from_iter`). A
/// superset of the drives that own such a pad, so `seed_eh_landing_pads` can
/// turn EH lowering on for them.
fn iter_call_may_hold_droppable_item<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    func: &Operand<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
) -> bool {
    let callee_ty = ctx.monomorphize_ty(func.ty(body, ctx.tcx));
    let ty::FnDef(def_id, _) = *callee_ty.kind() else {
        return false;
    };
    // IDENTITY, not a crate-name string (`real_core_crate`'s witness).
    if !is_real_std_crate_def(ctx.tcx, def_id) {
        return false;
    }
    args.iter().any(|arg| {
        let arg_ty = ctx.monomorphize_ty(arg.node.ty(body, ctx.tcx));
        let iter_ty = match arg_ty.kind() {
            ty::Ref(_, inner, _) => *inner,
            _ => arg_ty,
        };
        let Ok(Some(chain)) = resolve_iter_chain(ctx, iter_ty) else {
            return false;
        };
        chain_item_needs_drop(ctx, &source_item(ctx.tcx, &chain))
            || chain
                .adapters
                .iter()
                .any(|(adapter, _)| chain_item_needs_drop(ctx, &adapter.output))
    })
}

/// Drop the discarded item `value` per `plan`: store its image into the plan's
/// slot and call the glue through `push_unwindable_intercept_call`, so a
/// panicking destructor unwinds to the intercepted call's cleanup pad like the
/// drive's payload closures. May split `block`.
fn emit_discard_drop(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    plan: &DiscardDrop,
    value: ValueId,
) {
    emit_typed_store(block, plan.slot, plan.ir_ty.clone(), value);
    push_unwindable_intercept_call(ctx, block, plan.glue, vec![plan.slot], []);
}

/// The branch target of a discard edge: `(target, args)` unchanged when no drop
/// is owed, else a fresh block that drops `value` (`emit_discard_drop`) and then
/// branches to `target` with `args`, entered with no arguments.
fn discard_edge(
    ctx: &mut MirLoweringCtx<'_>,
    plan: Option<&DiscardDrop>,
    value: ValueId,
    target: BlockId,
    args: Vec<ValueId>,
) -> (BlockId, Vec<ValueId>) {
    let Some(plan) = plan else {
        return (target, args);
    };
    let id = ctx.fresh_block_id();
    let mut drop_block = Block::new(id);
    emit_discard_drop(ctx, &mut drop_block, plan, value);
    drop_block
        .body
        .push(InstrNode::new(Inst::Br { target, args }));
    ctx.extra_blocks.push(drop_block);
    (id, Vec::new())
}

/// Emit the iterator chain's `next` logic: advance the chain by one element,
/// branching to a `found` block with the yielded item LIVE as SSA (see
/// `ChainNextOut`) or to a `not_found` block on exhaustion. The caller creates
/// and owns both blocks. Builds whatever intermediate blocks the chain needs —
/// notably a Filter's skip-loop, which jumps back to `entry_id`.
///
/// `loop_carried`: the caller's header-param values (e.g. the accumulator)
/// forwarded VERBATIM as branch args on every edge that re-enters `entry_id`
/// (Filter reject / Skip discard / StepBy re-pull), prefixed with the advanced
/// source cursor when `cursor` is `Params` mode. A missed forwarding is a
/// compile-time fail-closed: the `ssa_loop_complete` gate enforces branch-arg
/// arity + types on every edge and positional derivation (a cursor<->acc swap
/// is a provable cross-slot misroute).
///
/// Block structure (`entry_id` == the caller's loop header):
///   take gate:    only when the chain has `.take(n)` adapters: for each one,
///                 remaining == 0? -> not_found; else -> the next gate / the pull.
///                 core's `Take::next` and `Take::try_fold` test `n != 0` BEFORE
///                 they touch the inner iterator and stop right after the n-th
///                 item, so no source pull and no adapter closure below a Take
///                 may run once its count is exhausted (or for `take(0)`).
///   source_check: cond = source-has-next? if not -> not_found; else value =
///                 elem; advance source; -> adapter_0 (or `found` if no adapters)
///   adapter_k(Map):    value = closure_k(value); -> adapter_{k+1}
///   adapter_k(Filter): keep = pred_k(value); if keep -> next
///                      else -> entry_id(carried...)
///   adapter_k(Take):   remaining -= 1 (> 0 by the gate); -> adapter_{k+1}
///   found / not_found: created by the caller.
///
/// Every re-entry edge targets `entry_id`, so it re-runs the gate: that is
/// core's order for an adapter above a Take (its next pull calls `Take::next`
/// again) and a no-op re-read for an adapter below one (only that Take's own
/// per-element block decrements its count).
///
/// A chain over an owning `vec::IntoIter` source whose element, or any item an
/// adapter produces from it (`.map(|x| D(x))`), needs drop is driven only under
/// `panic=abort`. Under `panic=unwind` a payload call or an item drop of the
/// drive may unwind, and std then drops, in a by-value terminal, the iterator it
/// owns: its unyielded elements, then its buffer. The drive's unwind edge
/// leaves the elements behind, so such a drive fails closed
/// (`[TCG-INTOITER-UNWIND-DROP]`). An owning source whose items all need no
/// drop is still driven under `panic=unwind`: a by-value terminal's unwind
/// frees its buffer in the terminal's pad (`begin_consumed_owner_drive`), and a
/// `&mut self` terminal leaves the iterator to the caller's own drop.
///
/// A non-owning source (`Range`, a slice) is driven under `panic=unwind` too.
/// An item the drive holds in memory while a by-reference payload runs (a
/// `filter` / `take_while` / `skip_while` predicate, an `inspect` closure) is
/// dropped by that call's own landing pad when the payload unwinds
/// (`held_item_unwind_pad`), as std's frame drops it. A terminal that carries a
/// value needing drop across the drive (a `fold` or `reduce` accumulator, the
/// result `last` keeps) refuses under `panic=unwind`
/// (`refuse_droppable_carry_across_payloads`). A `collect` frees the `Vec` it
/// builds in its terminal's pad (`begin_consumed_owner_drive`), after a held
/// item's pad has dropped the item, as std's `from_iter` frees it.
#[allow(clippy::too_many_arguments)]
fn emit_chain_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    chain: &IterChain<'tcx>,
    chain_slot: ValueId,
    // The PREHEADER block (must not yet be terminated): loop-invariant field
    // addresses and exact-typed per-adapter reference scratch slots are hoisted
    // here (E4).
    preheader: &mut Block,
    block: &mut Block,
    entry_id: BlockId,
    loop_carried: &[ValueId],
    cursor: &SourceCursor,
) -> Result<ChainNextOut, String> {
    let unwinding_owner = chain.owned_buffer.filter(|_| !panic_is_abort(ctx.tcx));
    if let Some(owned) = unwinding_owner {
        if chain_owns_droppable_elements(ctx.tcx, chain) {
            return Err(format!(
                "[TCG-INTOITER-UNWIND-DROP] an iterator drive over an owning \
                 vec::IntoIter<{:?}> whose element needs drop, under panic=unwind: an \
                 unwinding payload call or element drop would skip the drops std's unwind \
                 runs (the item in flight, the iterator the terminal owns); failing closed",
                owned.element_ty
            ));
        }
        let droppable_item = chain
            .adapters
            .iter()
            .map(|(adapter, _)| &adapter.output)
            .chain([&chain.item])
            .find(|item| chain_item_needs_drop(ctx, item));
        if let Some(item) = droppable_item {
            return Err(format!(
                "[TCG-INTOITER-UNWIND-DROP] an iterator drive over an owning \
                 vec::IntoIter<{:?}> whose adapters produce a `{:?}` item, which needs \
                 drop, under panic=unwind: an unwinding payload call or item drop would \
                 skip the drops std's unwind runs (the item in flight, the iterator the \
                 terminal owns); failing closed",
                owned.element_ty,
                ctx.monomorphize_ty(item.rust_ty)
            ));
        }
    }
    let found_id = ctx.fresh_block_id();
    let not_found_id = ctx.fresh_block_id();
    // Every exhaustion edge of the drive leaves through `exhausted_id`. A
    // default-path `StepBy` (`range_countdown: false`) keeps the drive's running
    // countdown in its `step_minus_one` field, which std holds at the constant
    // `k-1`: a yield resets it there, but an exhaustion edge can leave mid-skip
    // (the source runs out, or a non-fused `MapWhile`/`Scan` below it answers
    // `None`). So with such an adapter `exhausted_id` is a block that writes each
    // StepBy's `k-1` (`step_by_resets`, loaded in the preheader) back before
    // branching to the caller's `not_found_id`; a `&mut` terminal hands the
    // StepBy back to std code, which reads that field.
    let restores_step_by = chain.adapters.iter().any(|(adapter, _)| {
        matches!(
            adapter.kind,
            AdapterKind::StepBy {
                range_countdown: false,
                ..
            }
        )
    });
    let exhausted_id = if restores_step_by {
        ctx.fresh_block_id()
    } else {
        not_found_id
    };
    let mut step_by_resets: Vec<(ValueId, TrustIrTy, ValueId)> = Vec::new();
    let mut pre = PreheaderAddrs {
        block: preheader,
        chain_slot,
        cache: Vec::new(),
    };

    // Take gate (emitted into `block`, the entry block, BEFORE the source pull):
    // one `remaining == 0 -> not_found` test per `.take(n)` adapter. The source
    // pull then lands in a fresh block the entry block dominates, so the header
    // params (cursor, carried values) stay in scope there.
    //
    // TakeWhile gate (same place, same edge): a `take_while` whose done-`flag`
    // is already set yields nothing — std's `TakeWhile::{next, fold, try_fold}`
    // return before pulling the inner iterator or calling the predicate — and
    // every adapter above it then sees an exhausted inner iterator.
    let mut gate_block: Option<Block> = None;
    for (adapter, _) in &chain.adapters {
        let (field_off, field_ty) = match adapter.kind {
            AdapterKind::Take { count_off } => (count_off, usize_field_ty(ctx.tcx)),
            AdapterKind::TakeWhile { flag_off } => (flag_off, TrustIrTy::I8),
            _ => continue,
        };
        let field_addr = pre.field_addr(ctx, field_off);
        let cur = gate_block.as_mut().unwrap_or(&mut *block);
        let field = emit_typed_load(ctx, cur, field_addr, field_ty.clone());
        let (zero, done_op) = if matches!(adapter.kind, AdapterKind::Take { .. }) {
            // `.take(n)` is exhausted when its remaining count is 0.
            (emit_usize_field_const(ctx, cur, 0), ICmpOp::Eq)
        } else {
            // `.take_while(p)` is exhausted when its `flag` is set.
            (emit_typed_const(ctx, cur, TrustIrTy::I8, 0), ICmpOp::Ne)
        };
        let exhausted = ctx.fresh_value();
        cur.body.push(
            InstrNode::new(Inst::ICmp {
                op: done_op,
                ty: field_ty,
                lhs: field,
                rhs: zero,
            })
            .with_result(exhausted),
        );
        let pass_id = ctx.fresh_block_id();
        cur.body.push(InstrNode::new(Inst::CondBr {
            cond: exhausted,
            then_target: exhausted_id,
            then_args: Vec::new(),
            else_target: pass_id,
            else_args: Vec::new(),
        }));
        if let Some(done) = gate_block.replace(Block::new(pass_id)) {
            ctx.extra_blocks.push(done);
        }
    }
    let pull_block: &mut Block = match gate_block.as_mut() {
        Some(pull) => pull,
        None => block,
    };

    // Source check (emitted into the entry block, or into the pull block after a
    // Take gate): compute the raw element + cond, advance the source, branch to
    // the first adapter (or straight to `found` if there are no adapters) on
    // success, else `not_found`.
    let advance = match countdown_step_by(chain) {
        Some(step_minus_one_off) => emit_step_by_countdown_pull(
            ctx,
            chain,
            step_minus_one_off,
            pull_block,
            &mut pre,
            cursor,
        )?,
        None => emit_source_next(
            ctx,
            &chain.source,
            chain.source_offset,
            chain_slot,
            chain.reversed,
            pull_block,
            &mut pre,
            cursor,
        )?,
    };
    // The FULL loop-carried argument list every re-entry edge forwards: the
    // advanced source cursor (Params mode — the element is consumed even when a
    // Filter rejects it) followed by the caller's carried params verbatim.
    let carried: Vec<ValueId> = advance
        .advanced_cursor
        .iter()
        .chain(loop_carried.iter())
        .copied()
        .collect();
    let first_target = if chain.adapters.is_empty() {
        found_id
    } else {
        ctx.fresh_block_id()
    };
    pull_block.body.push(InstrNode::new(Inst::CondBr {
        cond: advance.cond,
        then_target: first_target,
        then_args: Vec::new(),
        else_target: exhausted_id,
        else_args: Vec::new(),
    }));
    if let Some(pull) = gate_block {
        ctx.extra_blocks.push(pull);
    }

    // Thread the element through each adapter. `cur_id` is the block we are
    // currently filling; `value` is the live element representation(s) in it (one
    // for a scalar/ref item, two for a tuple), with `cur_item` describing its
    // type.
    let mut cur_id = first_target;
    let mut cur_block = Block::new(cur_id);
    // A tuple-yielding source (`Zip`) seeds BOTH components; a scalar / `&T`
    // source seeds one.
    let mut value: Vec<ValueId> = match advance.value2 {
        Some(v2) => vec![advance.value, v2],
        None => vec![advance.value],
    };
    let mut cur_item: ChainItem<'tcx> = source_item(ctx.tcx, chain);
    for (idx, (adapter, closure_off)) in chain.adapters.iter().enumerate() {
        let next_id = if idx + 1 == chain.adapters.len() {
            found_id
        } else {
            ctx.fresh_block_id()
        };
        // The closure env address within the chain slot: `chain_slot +
        // closure_off`. For a ZST closure this address is never dereferenced
        // (a harmless non-null receiver); for a CAPTURING closure its upvars were
        // stored here by `lower_iter_adapter_ctor`, so the body reads `(*env).N`.
        // Loop-invariant: hoisted to the preheader (E4).
        let env_ptr = pre.field_addr(ctx, *closure_off);
        match &adapter.kind {
            AdapterKind::Map => {
                // A `Map` closure takes `Self::Item` BY VALUE. For a 2-tuple item
                // (`.enumerate()` -> `(usize, &T)`, `.zip()` -> `(&A, &B)`) the
                // closure receives a SINGLE by-value aggregate parameter (the
                // tuple); rustc DOES codegen the tuple-pattern closure body as a
                // standalone symbol (`fn {closure}(_1: &mut env, _2: (A, B)) -> R`,
                // reading `_2.0` / `_2.1`). Build the tuple aggregate slot and pass
                // its pointer as that one argument. A scalar item passes its single
                // component directly.
                let out = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    let arg = build_tuple_item_arg(
                        ctx,
                        &mut cur_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?;
                    emit_closure_call_n(
                        ctx,
                        &mut cur_block,
                        adapter.closure_ty,
                        env_ptr,
                        vec![arg],
                        adapter.output.ir_ty.clone(),
                    )?
                } else {
                    emit_closure_call_1(
                        ctx,
                        &mut cur_block,
                        adapter.closure_ty,
                        env_ptr,
                        value[0],
                        adapter.output.ir_ty.clone(),
                    )?
                };
                value = vec![out];
                cur_item = adapter.output.clone();
                cur_block.body.push(InstrNode::new(Inst::Br {
                    target: next_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::Filter => {
                // A `Filter` predicate takes `&Self::Item`. A scalar item is stored
                // into a stack slot whose address is the `&item`; a 2-tuple item
                // (`.enumerate()`/`.zip()`) is materialized into an in-memory tuple
                // aggregate (build_tuple_item_arg — the same helper `.map` uses)
                // whose pointer IS the `&(A,B)`. Filter does not transform the
                // item, so `value`/`cur_item` keep BOTH tuple lanes for the
                // downstream consumer. The kept item is the one the predicate left
                // in the slot: an interior-mutable scalar item is reloaded from it
                // (`shared_ref_item_reload`, which refuses such a tuple item).
                let reload = shared_ref_item_reload(ctx, &cur_item, "filter")?;
                let item_ref = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    build_tuple_item_arg(
                        ctx,
                        &mut cur_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?
                } else {
                    // Each reference-taking adapter gets its own exact-typed slot.
                    // Reusing one I64 slot is unsound when a Map changes width
                    // between filters (and overflows outright for i128 items).
                    let filter_ref_slot = ctx.fresh_value();
                    pre.block.body.push(
                        InstrNode::new(Inst::Alloca {
                            ty: cur_item.ir_ty.clone(),
                            count: None,
                            align: None,
                        })
                        .with_result(filter_ref_slot),
                    );
                    emit_typed_store(
                        &mut cur_block,
                        filter_ref_slot,
                        cur_item.ir_ty.clone(),
                        value[0],
                    );
                    filter_ref_slot
                };
                // The predicate returns `bool` (trust-ir `Bool`), used directly as
                // the branch condition. The slot holds the item while it runs.
                let held = held_item_unwind_pad(ctx, &cur_item, item_ref, "filter")?;
                let keep = emit_closure_call_via_pad(
                    ctx,
                    &mut cur_block,
                    adapter.closure_ty,
                    env_ptr,
                    vec![item_ref],
                    TrustIrTy::Bool,
                    held,
                )?;
                if reload {
                    value = vec![emit_typed_load(
                        ctx,
                        &mut cur_block,
                        item_ref,
                        cur_item.ir_ty.clone(),
                    )];
                }
                // The reject edge re-enters the loop header: forward the
                // loop-carried args (advanced cursor + caller params) so the
                // header's params stay bound on this path — the rejected element
                // IS consumed (the cursor advance commits), and std's `Filter`
                // drops it there.
                let plan = discard_drop_plan(ctx, pre.block, &cur_item, "filter")?;
                let (reject_target, reject_args) =
                    discard_edge(ctx, plan.as_ref(), value[0], entry_id, carried.clone());
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: keep,
                    then_target: next_id,
                    then_args: Vec::new(),
                    else_target: reject_target,
                    else_args: reject_args,
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
                // cur_item unchanged (Filter does not transform the item's type).
            }
            AdapterKind::Copied { elem_ir } => {
                // `.copied()` / `.cloned()` over `&T`: dereference the pointer
                // representation to the scalar value. A non-pointer item (already
                // by value) is the identity.
                if cur_item.deref_elem_ir.is_some() {
                    let derefed = emit_typed_load(ctx, &mut cur_block, value[0], elem_ir.clone());
                    value = vec![derefed];
                }
                cur_item = adapter.output.clone();
                cur_block.body.push(InstrNode::new(Inst::Br {
                    target: next_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::Take { count_off } => {
                // `.take(n)`: the entry gate already routed an exhausted count to
                // `not_found` before the source pull, and nothing between the gate
                // and this block writes this count, so it is > 0 here: count the
                // yielded element and continue. The count FIELD stays
                // memory-backed (adapter state is never governed by the cursor
                // mode; a borrowed receiver observes it after the drive); only
                // its invariant ADDRESS is hoisted (E4).
                let count_addr = pre.field_addr(ctx, *count_off);
                let count_ty = usize_field_ty(ctx.tcx);
                let count = emit_typed_load(ctx, &mut cur_block, count_addr, count_ty.clone());
                let one = emit_usize_field_const(ctx, &mut cur_block, 1);
                let dec = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Sub,
                        ty: count_ty.clone(),
                        lhs: count,
                        rhs: one,
                    })
                    .with_result(dec),
                );
                emit_typed_store(&mut cur_block, count_addr, count_ty, dec);
                cur_block.body.push(InstrNode::new(Inst::Br {
                    target: next_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::Skip { count_off } => {
                // `.skip(n)`: while the skip count is > 0, decrement and DISCARD
                // this element (jump back to the entry block); else proceed. The
                // count is CLAMPED at 0 (a `Select`) so once skipping is done the
                // field stays 0 and all later elements pass through. This is
                // core's `Skip::{next,fold,try_fold}` order (`nth(n - 1)` pulls,
                // and runs every adapter below on, each skipped element); the
                // `TrustedRandomAccess` fold of a Take over it, which skips
                // nothing when nothing is taken, is applied before the drive by
                // `emit_take_tra_fold_clamp`. The count field stays
                // memory-backed; its invariant address is hoisted (E4).
                let count_addr = pre.field_addr(ctx, *count_off);
                let count_ty = usize_field_ty(ctx.tcx);
                let count = emit_typed_load(ctx, &mut cur_block, count_addr, count_ty.clone());
                let zero = emit_usize_field_const(ctx, &mut cur_block, 0);
                let is_zero = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Eq,
                        ty: count_ty.clone(),
                        lhs: count,
                        rhs: zero,
                    })
                    .with_result(is_zero),
                );
                let one = emit_usize_field_const(ctx, &mut cur_block, 1);
                let dec = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Sub,
                        ty: count_ty.clone(),
                        lhs: count,
                        rhs: one,
                    })
                    .with_result(dec),
                );
                // new count = is_zero ? 0 : count-1.
                let new_count = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: count_ty.clone(),
                        cond: is_zero,
                        then_val: zero,
                        else_val: dec,
                    })
                    .with_result(new_count),
                );
                emit_typed_store(&mut cur_block, count_addr, count_ty.clone(), new_count);
                // If done skipping (count == 0): proceed. Else: re-pull (discard).
                // The discard edge re-enters the header: forward the loop-carried
                // args (the discarded element IS consumed — cursor advances, and
                // std's `Skip` drops it).
                let plan = discard_drop_plan(ctx, pre.block, &cur_item, "skip")?;
                let below = &chain.adapters[..idx];
                let skips_range_run = plan.is_none()
                    && matches!(
                        chain.source,
                        ChainSource::Range { .. } | ChainSource::RangeInclusive { .. }
                    )
                    && below.iter().all(|(a, _)| {
                        matches!(a.kind, AdapterKind::Skip { .. } | AdapterKind::Take { .. })
                    });
                let (skip_target, skip_args) = if skips_range_run {
                    // Over a `Range` / `RangeInclusive` source and only
                    // `Skip` / `Take` below, core's `Skip` takes its `n` items
                    // with ONE inner `nth` (O(1)). The first of them was just
                    // pulled: consume the other `n - 1` in closed form and
                    // clear the count, then re-pull.
                    let fast_id = ctx.fresh_block_id();
                    let mut fast = Block::new(fast_id);
                    let rest = emit_extend_to_i64(ctx, &mut fast, &count_ty, false, dec);
                    let cleared = emit_usize_field_const(ctx, &mut fast, 0);
                    emit_typed_store(&mut fast, count_addr, count_ty.clone(), cleared);
                    let args = emit_skip_range_source_fast_forward(
                        ctx,
                        &mut fast,
                        chain,
                        chain_slot,
                        below,
                        cursor,
                        advance.advanced_cursor,
                        rest,
                        &carried,
                    )?;
                    fast.body.push(InstrNode::new(Inst::Br {
                        target: entry_id,
                        args,
                    }));
                    ctx.extra_blocks.push(fast);
                    (fast_id, Vec::new())
                } else {
                    discard_edge(ctx, plan.as_ref(), value[0], entry_id, carried.clone())
                };
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: is_zero,
                    then_target: next_id,
                    then_args: Vec::new(),
                    else_target: skip_target,
                    else_args: skip_args,
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::StepBy {
                range_countdown: true,
                ..
            } => {
                // A countdown `Range` (`range_countdown`) is stepped by the
                // source pull itself (`emit_step_by_countdown_pull`): every
                // element it yields is one core's `spec_next` yields, so the
                // element passes on unchanged.
                cur_block.body.push(InstrNode::new(Inst::Br {
                    target: next_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::StepBy {
                step_minus_one_off,
                first_take_off,
                range_countdown: false,
            } => {
                // std's layout (`step_minus_one: usize`, `first_take: bool`, each
                // at its layout-derived offset), stepped as core's default
                // `spec_next` (`nth(first_take ? 0 : step_minus_one)`). The drive
                // keeps its running countdown in the `step_minus_one` field: a
                // yield resets it to `k-1`, and the drive's exhaustion exit
                // (`exhausted_id`) writes `k-1` back, so between drives the field
                // holds std's constant.
                // `step_minus_one` is a `usize` field: every access is at its
                // own width, with the countdown math in I64 (the widen/narrow
                // is a no-op on a 64-bit target).
                let sm_ty = usize_field_ty(ctx.tcx);
                // The `step_minus_one` field holds the constant `k-1` (a yield
                // resets the running countdown back to it, so it is always
                // recoverable BETWEEN drives). Read it ONCE as `reset`. The INITIAL
                // countdown depends on freshness: a FRESH iterator (first_take==1)
                // yields its first pulled element (countdown 0); a PARTIALLY-consumed
                // one (first_take==0, e.g. after a prior `nth`/`next`) must SKIP
                // `step-1` source elements before the next yield (countdown = reset).
                // Deriving it from first_take (not hardcoding 0) is what makes a
                // SECOND partial drive correct — `it.nth(0); it.nth(0)` must yield 0
                // then `step`, not 0 then the immediate next source element.
                let sm_addr = pre.field_addr(ctx, *step_minus_one_off);
                let reset_raw = emit_typed_load(ctx, pre.block, sm_addr, sm_ty.clone());
                step_by_resets.push((sm_addr, sm_ty.clone(), reset_raw));
                let reset = emit_extend_to_i64(ctx, pre.block, &sm_ty, false, reset_raw);
                let ft_addr = pre.field_addr(ctx, *first_take_off);
                let ft_i8 = emit_typed_load(ctx, pre.block, ft_addr, TrustIrTy::I8);
                let ft = emit_extend_to_i64(ctx, pre.block, &TrustIrTy::I8, false, ft_i8);
                let zero_pre = emit_i64_const(ctx, pre.block, 0);
                let ft_nz = emit_i64_icmp(ctx, pre.block, ICmpOp::Ne, ft, zero_pre);
                let init_cd = emit_i64_select(ctx, pre.block, ft_nz, zero_pre, reset);
                let init_cd = emit_trunc_from_i64(ctx, pre.block, &sm_ty, init_cd);
                emit_typed_store(pre.block, sm_addr, sm_ty.clone(), init_cd);
                // ANY driving makes the iterator non-fresh: clear first_take so a
                // LATER `<StepBy>::next` (lower_step_by_next reads first_take) agrees.
                // The 0 is the `I8` constant the `I8` store writes (see
                // `emit_first_take_const`), not the `I64` `zero_pre`.
                let ft_clear = emit_first_take_const(ctx, pre.block, 0);
                emit_typed_store(pre.block, ft_addr, TrustIrTy::I8, ft_clear);
                let countdown_raw = emit_typed_load(ctx, &mut cur_block, sm_addr, sm_ty.clone());
                let countdown =
                    emit_extend_to_i64(ctx, &mut cur_block, &sm_ty, false, countdown_raw);
                let zero = emit_i64_const(ctx, &mut cur_block, 0);
                let is_zero = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Eq,
                        ty: TrustIrTy::I64,
                        lhs: countdown,
                        rhs: zero,
                    })
                    .with_result(is_zero),
                );
                let one = emit_i64_const(ctx, &mut cur_block, 1);
                let cd_minus = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Sub,
                        ty: TrustIrTy::I64,
                        lhs: countdown,
                        rhs: one,
                    })
                    .with_result(cd_minus),
                );
                let new_cd = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::I64,
                        cond: is_zero,
                        then_val: reset,
                        else_val: cd_minus,
                    })
                    .with_result(new_cd),
                );
                let new_cd = emit_trunc_from_i64(ctx, &mut cur_block, &sm_ty, new_cd);
                emit_typed_store(&mut cur_block, sm_addr, sm_ty, new_cd);
                // A stepped-over element is consumed and dropped (std's
                // `StepBy` reaches it through `nth`).
                let plan = discard_drop_plan(ctx, pre.block, &cur_item, "step_by")?;
                let (skip_target, skip_args) =
                    discard_edge(ctx, plan.as_ref(), value[0], entry_id, carried.clone());
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: is_zero,
                    then_target: next_id,
                    then_args: Vec::new(),
                    else_target: skip_target,
                    else_args: skip_args,
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::Enumerate {
                count_off,
                counter_slot,
            } => {
                // `.enumerate()`: yield `(count, value)`; the running count starts
                // at 0 (constructor / peel zero-init) and increments per yielded
                // element. The item becomes a 2-tuple `[index, value]`. A PEELED
                // (`-O3`) enumerate uses its standalone counter alloca; a
                // chain-backed one reads `chain_slot + count_off`.
                let cnt_addr = match counter_slot {
                    Some(slot) => *slot,
                    // Invariant address hoisted to the preheader (E4); the count
                    // itself stays memory-backed (adapter state).
                    None => pre.field_addr(ctx, *count_off),
                };
                // The count is a `usize` (`usize_field_ty`): the ctor, the peel's
                // counter slot and this drive all access it at that width.
                let cnt_ty = usize_field_ty(ctx.tcx);
                let idx_val = emit_typed_load(ctx, &mut cur_block, cnt_addr, cnt_ty.clone());
                let one = emit_usize_field_const(ctx, &mut cur_block, 1);
                let next_cnt = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Add,
                        ty: cnt_ty.clone(),
                        lhs: idx_val,
                        rhs: one,
                    })
                    .with_result(next_cnt),
                );
                emit_typed_store(&mut cur_block, cnt_addr, cnt_ty, next_cnt);
                // The tuple is `(index, value)`: prepend the index to the current
                // value component(s). The inner value must itself be single-component
                // (enumerate over a tuple was rejected at resolve time).
                let inner_val = value[0];
                value = vec![idx_val, inner_val];
                cur_item = adapter.output.clone();
                cur_block.body.push(InstrNode::new(Inst::Br {
                    target: next_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::FilterMap => {
                // `.filter_map(f)`: call `f(env, item BY VALUE) -> Option<U>` and
                // dissect the Option. On `Some(u)` yield `u` as the new item and
                // proceed; on `None` RE-PULL (jump back to `entry_id` with the
                // carried loop args — IDENTICAL to Filter's reject edge, the
                // consumed-element re-entry). The closure takes `Self::Item` BY
                // VALUE; a 2-tuple item is materialized into an in-memory aggregate
                // (build_tuple_item_arg — the same by-value tuple arg `.map()`
                // passes). Extracting the payload before the branch is side-effect-
                // free (harmless on the None path).
                let opt_ty = closure_output_ty(ctx, adapter.closure_ty)?;
                let fm_arg = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    build_tuple_item_arg(
                        ctx,
                        &mut cur_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?
                } else {
                    value[0]
                };
                let opt = emit_closure_call_n(
                    ctx,
                    &mut cur_block,
                    adapter.closure_ty,
                    env_ptr,
                    vec![fm_arg],
                    adapter.output.ir_ty.clone(),
                )?;
                let (is_some, payload, _payload_ir) =
                    emit_option_step(ctx, &mut cur_block, opt_ty, opt)?;
                value = vec![payload];
                cur_item = adapter.output.clone();
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: is_some,
                    then_target: next_id,
                    then_args: Vec::new(),
                    else_target: entry_id,
                    else_args: carried.clone(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::TakeWhile { flag_off } => {
                // `.take_while(p)`: store the item into `filter_ref_slot`, call
                // `p(env, &item) -> bool`. On `true` proceed; on `false` set std's
                // done-`flag` and TERMINATE the drive (jump to `exhausted_id` with
                // EMPTY args — IDENTICAL to Take's exhaust edge). This is the
                // CRITICAL distinction from Filter, whose reject edge re-pulls
                // (`entry_id`): a take_while modeled as a filter would wrongly
                // INCLUDE later elements. The entry gate above already left the
                // drive when the flag was set, so it is clear here. cur_item is
                // unchanged (output == input); an interior-mutable scalar item is
                // reloaded from the slot the predicate received
                // (`shared_ref_item_reload`). A 2-tuple item is materialized in an
                // in-memory aggregate for the `&(A,B)` predicate (like Filter/map).
                let reload = shared_ref_item_reload(ctx, &cur_item, "take_while")?;
                let item_ref = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    build_tuple_item_arg(
                        ctx,
                        &mut cur_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?
                } else {
                    let filter_ref_slot = ctx.fresh_value();
                    pre.block.body.push(
                        InstrNode::new(Inst::Alloca {
                            ty: cur_item.ir_ty.clone(),
                            count: None,
                            align: None,
                        })
                        .with_result(filter_ref_slot),
                    );
                    emit_typed_store(
                        &mut cur_block,
                        filter_ref_slot,
                        cur_item.ir_ty.clone(),
                        value[0],
                    );
                    filter_ref_slot
                };
                let held = held_item_unwind_pad(ctx, &cur_item, item_ref, "take_while")?;
                let keep = emit_closure_call_via_pad(
                    ctx,
                    &mut cur_block,
                    adapter.closure_ty,
                    env_ptr,
                    vec![item_ref],
                    TrustIrTy::Bool,
                    held,
                )?;
                // flag = keep ? 0 : 1 — std's `TakeWhile` sets it exactly where the
                // predicate first answers false. A Select avoids the unsupported
                // Bool->I8 cast.
                let flag_addr = pre.field_addr(ctx, *flag_off);
                let flag_clear = emit_typed_const(ctx, &mut cur_block, TrustIrTy::I8, 0);
                let flag_set = emit_typed_const(ctx, &mut cur_block, TrustIrTy::I8, 1);
                let new_flag = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::I8,
                        cond: keep,
                        then_val: flag_clear,
                        else_val: flag_set,
                    })
                    .with_result(new_flag),
                );
                emit_typed_store(&mut cur_block, flag_addr, TrustIrTy::I8, new_flag);
                if reload {
                    value = vec![emit_typed_load(
                        ctx,
                        &mut cur_block,
                        item_ref,
                        cur_item.ir_ty.clone(),
                    )];
                }
                // The item the predicate rejects is consumed: std's `TakeWhile`
                // drops it before it reports exhaustion.
                let plan = discard_drop_plan(ctx, pre.block, &cur_item, "take_while")?;
                let (stop_target, stop_args) =
                    discard_edge(ctx, plan.as_ref(), value[0], exhausted_id, Vec::new());
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: keep,
                    then_target: next_id,
                    then_args: Vec::new(),
                    else_target: stop_target,
                    else_args: stop_args,
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::SkipWhile { flag_off } => {
                // `.skip_while(p)`: once `flag` says skipping is finished, yield
                // directly WITHOUT invoking `p` again. This short-circuit is
                // semantically required: predicate side effects/call counts/panics
                // after the first false are observable. While the flag is clear,
                // call `p(&item)` exactly once; true skips/re-pulls, false stores the
                // flag and yields. cur_item remains unchanged. An interior-mutable
                // scalar item (`shared_ref_item_reload`) is stored into its `&item`
                // slot BEFORE the flag test, and both yield edges meet in a block
                // that reloads it, so the yielded item is the one the predicate
                // left (or the stored one when the predicate was not called).
                let reload = shared_ref_item_reload(ctx, &cur_item, "skip_while")?;
                let reload_slot = if reload {
                    let slot = ctx.fresh_value();
                    pre.block.body.push(
                        InstrNode::new(Inst::Alloca {
                            ty: cur_item.ir_ty.clone(),
                            count: None,
                            align: None,
                        })
                        .with_result(slot),
                    );
                    emit_typed_store(&mut cur_block, slot, cur_item.ir_ty.clone(), value[0]);
                    Some(slot)
                } else {
                    None
                };
                let yield_id = if reload_slot.is_some() {
                    ctx.fresh_block_id()
                } else {
                    next_id
                };
                let flag_addr = pre.field_addr(ctx, *flag_off);
                let flag_i8 = emit_typed_load(ctx, &mut cur_block, flag_addr, TrustIrTy::I8);
                let zero_i8 = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::Const {
                        ty: TrustIrTy::I8,
                        value: Constant::Int(0),
                    })
                    .with_result(zero_i8),
                );
                let flag_set = ctx.fresh_value();
                cur_block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Ne,
                        ty: TrustIrTy::I8,
                        lhs: flag_i8,
                        rhs: zero_i8,
                    })
                    .with_result(flag_set),
                );
                let pred_id = ctx.fresh_block_id();
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: flag_set,
                    then_target: yield_id,
                    then_args: Vec::new(),
                    else_target: pred_id,
                    else_args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);

                let mut pred_block = Block::new(pred_id);
                let item_ref = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    build_tuple_item_arg(
                        ctx,
                        &mut pred_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?
                } else if let Some(slot) = reload_slot {
                    slot
                } else {
                    let item_ref_slot = ctx.fresh_value();
                    pre.block.body.push(
                        InstrNode::new(Inst::Alloca {
                            ty: cur_item.ir_ty.clone(),
                            count: None,
                            align: None,
                        })
                        .with_result(item_ref_slot),
                    );
                    emit_typed_store(
                        &mut pred_block,
                        item_ref_slot,
                        cur_item.ir_ty.clone(),
                        value[0],
                    );
                    item_ref_slot
                };
                let held = held_item_unwind_pad(ctx, &cur_item, item_ref, "skip_while")?;
                let pred = emit_closure_call_via_pad(
                    ctx,
                    &mut pred_block,
                    adapter.closure_ty,
                    env_ptr,
                    vec![item_ref],
                    TrustIrTy::Bool,
                    held,
                )?;
                let one_i8 = ctx.fresh_value();
                pred_block.body.push(
                    InstrNode::new(Inst::Const {
                        ty: TrustIrTy::I8,
                        value: Constant::Int(1),
                    })
                    .with_result(one_i8),
                );
                // flag = pred ? 0 : 1. A Select avoids the unsupported Bool->I8
                // uextend and records completion exactly on the first false.
                let new_flag = ctx.fresh_value();
                pred_block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::I8,
                        cond: pred,
                        then_val: zero_i8,
                        else_val: one_i8,
                    })
                    .with_result(new_flag),
                );
                emit_typed_store(&mut pred_block, flag_addr, TrustIrTy::I8, new_flag);
                // A skipped item is consumed: std's `SkipWhile` drops it.
                let skipped = match reload_slot {
                    Some(slot) => {
                        emit_typed_load(ctx, &mut pred_block, slot, cur_item.ir_ty.clone())
                    }
                    None => value[0],
                };
                let plan = discard_drop_plan(ctx, pre.block, &cur_item, "skip_while")?;
                let (skip_target, skip_args) =
                    discard_edge(ctx, plan.as_ref(), skipped, entry_id, carried.clone());
                pred_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: pred,
                    then_target: skip_target,
                    then_args: skip_args,
                    else_target: yield_id,
                    else_args: Vec::new(),
                }));
                ctx.extra_blocks.push(pred_block);
                if let Some(slot) = reload_slot {
                    let mut yield_block = Block::new(yield_id);
                    value = vec![emit_typed_load(
                        ctx,
                        &mut yield_block,
                        slot,
                        cur_item.ir_ty.clone(),
                    )];
                    yield_block.body.push(InstrNode::new(Inst::Br {
                        target: next_id,
                        args: Vec::new(),
                    }));
                    ctx.extra_blocks.push(yield_block);
                }
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::Scan { state_off } => {
                // `.scan(init, f)`: the `state` cell lives at `chain_slot +
                // state_off` in the PRIVATE #111 slot copy (memory-backed, never SSA
                // — the `&mut state` mutation persists left-to-right across
                // iterations regardless of the source-cursor mode; adapter state is
                // never governed by the cursor). Call `f(env, &mut state, item BY
                // VALUE) -> Option<U>`. On `Some(u)` yield `u`; on `None` TERMINATE
                // (jump to `exhausted_id` — like Take's exhaust edge). A 2-tuple
                // item is materialized into an in-memory aggregate for the by-value
                // item arg (build_tuple_item_arg); `&mut state` is unaffected.
                let state_ptr = pre.field_addr(ctx, *state_off);
                let opt_ty = closure_output_ty(ctx, adapter.closure_ty)?;
                let scan_arg = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    build_tuple_item_arg(
                        ctx,
                        &mut cur_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?
                } else {
                    value[0]
                };
                let opt = emit_closure_call_n(
                    ctx,
                    &mut cur_block,
                    adapter.closure_ty,
                    env_ptr,
                    vec![state_ptr, scan_arg],
                    adapter.output.ir_ty.clone(),
                )?;
                let (is_some, payload, _payload_ir) =
                    emit_option_step(ctx, &mut cur_block, opt_ty, opt)?;
                value = vec![payload];
                cur_item = adapter.output.clone();
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: is_some,
                    then_target: next_id,
                    then_args: Vec::new(),
                    else_target: exhausted_id,
                    else_args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::MapWhile => {
                // `.map_while(f)`: call `f(env, item BY VALUE) -> Option<U>` and
                // dissect the Option. On `Some(u)` yield `u` as the new item and
                // proceed; on `None` TERMINATE the drive (jump to `exhausted_id` with
                // EMPTY args — like Scan/TakeWhile's exhaust edge). This is the
                // CRITICAL distinction from FilterMap, whose `None` RE-PULLS
                // (`entry_id`): a map_while modeled as a filter_map would wrongly
                // CONTINUE past the first `None`. The closure takes the item BY
                // VALUE; a 2-tuple item is materialized via build_tuple_item_arg
                // (the same by-value tuple arg `.map()` passes).
                let opt_ty = closure_output_ty(ctx, adapter.closure_ty)?;
                let mw_arg = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    build_tuple_item_arg(
                        ctx,
                        &mut cur_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?
                } else {
                    value[0]
                };
                let opt = emit_closure_call_n(
                    ctx,
                    &mut cur_block,
                    adapter.closure_ty,
                    env_ptr,
                    vec![mw_arg],
                    adapter.output.ir_ty.clone(),
                )?;
                let (is_some, payload, _payload_ir) =
                    emit_option_step(ctx, &mut cur_block, opt_ty, opt)?;
                value = vec![payload];
                cur_item = adapter.output.clone();
                cur_block.body.push(InstrNode::new(Inst::CondBr {
                    cond: is_some,
                    then_target: next_id,
                    then_args: Vec::new(),
                    else_target: exhausted_id,
                    else_args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
            AdapterKind::Inspect => {
                // `.inspect(f)`: store the item into `filter_ref_slot`, call
                // `f(env, &item) -> ()` for its SIDE EFFECT (the returned unit is
                // discarded — `emit_closure_call_n` ignores the output type), then
                // yield the item and ALWAYS proceed (a transparent pass-through —
                // like Filter but with no reject edge). cur_item is unchanged; an
                // interior-mutable scalar item is reloaded from the slot the
                // closure received (`shared_ref_item_reload`). A 2-tuple item is
                // materialized in an in-memory aggregate for the `&(A,B)` closure
                // (like Filter/map).
                let reload = shared_ref_item_reload(ctx, &cur_item, "inspect")?;
                let item_ref = if let Some((c0_item, c1_item)) = &cur_item.tuple {
                    build_tuple_item_arg(
                        ctx,
                        &mut cur_block,
                        cur_item.rust_ty,
                        (value[0], &c0_item.ir_ty),
                        (value[1], &c1_item.ir_ty),
                    )?
                } else {
                    let filter_ref_slot = ctx.fresh_value();
                    pre.block.body.push(
                        InstrNode::new(Inst::Alloca {
                            ty: cur_item.ir_ty.clone(),
                            count: None,
                            align: None,
                        })
                        .with_result(filter_ref_slot),
                    );
                    emit_typed_store(
                        &mut cur_block,
                        filter_ref_slot,
                        cur_item.ir_ty.clone(),
                        value[0],
                    );
                    filter_ref_slot
                };
                // The closure returns `()` (VOID) — emit the call with NO result
                // binding (a `Some(result)` on a void callee is unsupported trust_ir
                // in the backend, [TCG-REGALLOC-063]). Mirror `emit_closure_call_n`'s
                // arg/env plumbing but pass `None` for the result.
                let instance = closure_body_instance(ctx, adapter.closure_ty)?;
                refuse_unthreaded_caller_location(ctx.tcx, instance)?;
                let callee = ctx.extern_callee(instance)?;
                let call_args = closure_body_call_args_from_values(
                    ctx,
                    &mut cur_block,
                    instance,
                    Some(env_ptr),
                    vec![item_ref],
                )?;
                // The slot holds the item while the closure runs.
                let held = held_item_unwind_pad(ctx, &cur_item, item_ref, "inspect")?;
                let edge = ctx.intercept_unwind_pad;
                if held.is_some() {
                    ctx.intercept_unwind_pad = held;
                }
                push_unwindable_intercept_call(ctx, &mut cur_block, callee, call_args, None);
                ctx.intercept_unwind_pad = edge;
                if reload {
                    value = vec![emit_typed_load(
                        ctx,
                        &mut cur_block,
                        item_ref,
                        cur_item.ir_ty.clone(),
                    )];
                }
                cur_block.body.push(InstrNode::new(Inst::Br {
                    target: next_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(cur_block);
                cur_id = next_id;
                cur_block = Block::new(cur_id);
            }
        }
    }
    // After the adapter loop `cur_block`/`cur_id` is the (still-EMPTY) `found`
    // block placeholder (the loop routed its last edge to `found_id`, and
    // `cur_id == found_id`). If there were no adapters, `block` already branched
    // to `found_id`. The CALLER creates and owns `Block::new(found_id)` — drop
    // the empty placeholder rather than double-create the block id.
    debug_assert_eq!(cur_id, found_id);
    debug_assert!(cur_block.body.is_empty());
    drop(cur_block);
    // A tuple item that reaches `found` is only valid for a consumer that IGNORES
    // the item (`count`): value-using consumers (`sum`/`fold`) over a tuple were
    // rejected earlier by `lower_iter_consumer`; `collect` over a tuple is
    // rejected by its element type. So handing back BOTH components live is
    // sound (a tuple-consuming caller never reads them).
    let _ = &cur_item;
    if restores_step_by {
        let mut exhausted = Block::new(exhausted_id);
        for (sm_addr, sm_ty, reset) in step_by_resets {
            emit_typed_store(&mut exhausted, sm_addr, sm_ty, reset);
        }
        exhausted.body.push(InstrNode::new(Inst::Br {
            target: not_found_id,
            args: Vec::new(),
        }));
        ctx.extra_blocks.push(exhausted);
    }
    Ok(ChainNextOut {
        found_id,
        not_found_id,
        item: value,
        cursor_advanced: advance.advanced_cursor,
    })
}

/// The source-level item of a chain (what the source iterator's `next` yields):
/// a Range's by-value scalar, a slice's `&T` pointer, or a Zip's `(&A, &B)` tuple.
fn source_item<'tcx>(tcx: TyCtxt<'tcx>, chain: &IterChain<'tcx>) -> ChainItem<'tcx> {
    chain_source_item(tcx, &chain.source)
}

/// The item a `ChainSource` yields, computed structurally (recursing into a
/// `Concat`'s first sub-source — both sub-sources share the same item shape).
fn chain_source_item<'tcx>(tcx: TyCtxt<'tcx>, source: &ChainSource<'tcx>) -> ChainItem<'tcx> {
    match source {
        ChainSource::Range {
            index_ty, ir_ty, ..
        }
        | ChainSource::RangeInclusive {
            index_ty, ir_ty, ..
        } => ChainItem {
            rust_ty: *index_ty,
            ir_ty: ir_ty.clone(),
            deref_elem_ir: None,
            tuple: None,
        },
        ChainSource::Slice {
            element_ty, ir_ty, ..
        } => ChainItem {
            // The slice item is `&T`; carry the element rust ty as a placeholder
            // (only `ir_ty`/`deref_elem_ir` are used downstream).
            rust_ty: *element_ty,
            ir_ty: TrustIrTy::Ptr,
            deref_elem_ir: Some(ir_ty.clone()),
            tuple: None,
        },
        // A `Concat` (`a.chain(b)`) yields the item of its first sub-source.
        ChainSource::Concat { first, .. } => chain_source_item(tcx, first),
        // A `Zip` yields the 2-tuple of its sides' items: `&T` for a slice side,
        // the 64-bit scalar BY VALUE for a Range side. Rebuild the same tuple
        // ChainItem `resolve_zip` produced so a downstream `.map(|(x,y)| ..)`
        // reads the correct tuple aggregate parameter layout from
        // `cur_item.rust_ty`.
        ChainSource::Zip { a, b, .. } => {
            let a_item = zip_side_item(tcx, a);
            let b_item = zip_side_item(tcx, b);
            ChainItem {
                rust_ty: Ty::new_tup(tcx, &[a_item.rust_ty, b_item.rust_ty]),
                ir_ty: TrustIrTy::Ptr,
                deref_elem_ir: None,
                tuple: Some((Box::new(a_item), Box::new(b_item))),
            }
        }
    }
}

/// E3 preheader setup for `SourceCursor::Params`: load the source cursor's
/// initial value and its loop-invariant bound from the chain slot ONCE, in the
/// caller's preheader block. Returns `(cursor0, bound, cursor_ir)` for a
/// supported source (Range fwd/rev, slice fwd) or `None` for any other source —
/// the caller then keeps the v1 `Slot` fallback (safe degradation for
/// `RangeInclusive` / `Concat` / `Zip` / reversed slices / any future source).
///
/// SOUND ONLY over a PRIVATE chain slot (the caller must hold the #111 fresh
/// copy or a const image): the bound lanes are then loop-invariant by
/// construction and the never-written-back cursor is unobservable.
fn emit_source_cursor_preheader<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    chain: &IterChain<'tcx>,
    chain_slot: ValueId,
    block: &mut Block,
) -> Result<Option<(ValueId, ValueId, TrustIrTy)>, String> {
    if !source_cursor_params_supported(&chain.source, chain.reversed)
        || countdown_step_by(chain).is_some()
    {
        return Ok(None);
    }
    let offset = chain.source_offset;
    match &chain.source {
        ChainSource::Range { ir_ty, size, .. } => {
            let start_addr = iter_field_addr(ctx, block, chain_slot, offset);
            let start = emit_typed_load(ctx, block, start_addr, ir_ty.clone());
            let end_addr = iter_field_addr(ctx, block, chain_slot, offset + size);
            let end = emit_typed_load(ctx, block, end_addr, ir_ty.clone());
            if chain.reversed {
                // Reversed walk: the cursor is the DECREMENTING `end` lane; the
                // invariant bound is `start`.
                Ok(Some((end, start, ir_ty.clone())))
            } else {
                Ok(Some((start, end, ir_ty.clone())))
            }
        }
        ChainSource::Slice {
            size,
            end_off,
            repr,
            ..
        } => {
            // Forward only (the support predicate rejected a reversed slice). An
            // index cursor enters the loop as element pointers into the private
            // slot's inline data; Params mode never writes the cursor back.
            let ptr_addr = iter_field_addr(ctx, block, chain_slot, offset);
            let data = emit_slice_cursor_data(ctx, block, ptr_addr, *repr);
            let ptr = emit_slice_cursor_load(ctx, block, ptr_addr, data, *size);
            let end_addr = iter_field_addr(ctx, block, chain_slot, offset + *end_off);
            let end = emit_slice_cursor_load(ctx, block, end_addr, data, *size);
            Ok(Some((ptr, end, TrustIrTy::Ptr)))
        }
        _ => Ok(None),
    }
}

/// `Some(step_minus_one_off)` when `chain`'s innermost adapter is a countdown
/// `StepBy<Range<T>>` (`range_countdown`, which the resolver admits only directly
/// over the bare `Range` source): its drive pulls the source through core's
/// countdown `spec_next` ([`emit_step_by_countdown_pull`]) instead of the Range's
/// own `next`.
fn countdown_step_by(chain: &IterChain<'_>) -> Option<u64> {
    match chain.adapters.first().map(|(adapter, _)| &adapter.kind) {
        Some(AdapterKind::StepBy {
            step_minus_one_off,
            range_countdown: true,
            ..
        }) => Some(*step_minus_one_off),
        _ => None,
    }
}

/// The source pull of a drive over a countdown `StepBy<Range<T>>`: core's
/// countdown `spec_next` on the slot's `{start, end}` (`end` = items left), so
/// each element this yields is the next `StepBy` item. The step is read once in
/// the preheader (`step_minus_one` is never written by the drive). Slot cursor
/// only: `emit_source_cursor_preheader` never chooses `Params` for such a chain.
fn emit_step_by_countdown_pull<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    chain: &IterChain<'tcx>,
    step_minus_one_off: u64,
    block: &mut Block,
    pre: &mut PreheaderAddrs<'_>,
    cursor: &SourceCursor,
) -> Result<SourceNext, String> {
    if !matches!(cursor, SourceCursor::Slot) {
        return Err("countdown step_by drive with a Params source cursor".to_owned());
    }
    let ChainSource::Range { ir_ty, size, .. } = &chain.source else {
        return Err("countdown step_by drive over a non-Range source".to_owned());
    };
    let sm_addr = pre.field_addr(ctx, step_minus_one_off);
    let step = emit_step_by_range_step(ctx, pre.block, sm_addr, ir_ty)?;
    let start_addr = pre.field_addr(ctx, chain.source_offset);
    let end_addr = pre.field_addr(ctx, chain.source_offset + *size);
    let start = emit_typed_load(ctx, block, start_addr, ir_ty.clone());
    let end = emit_typed_load(ctx, block, end_addr, ir_ty.clone());
    let next = emit_step_by_countdown_advance(ctx, block, ir_ty, start, end, step);
    emit_typed_store(block, start_addr, ir_ty.clone(), next.new_start);
    emit_typed_store(block, end_addr, ir_ty.clone(), next.new_end);
    Ok(SourceNext {
        cond: next.cond,
        value: start,
        value2: None,
        advanced_cursor: None,
    })
}

/// Result of advancing an iterator source by one: a `cond` (`I8`/`I1` truthy
/// value: more elements?) and the raw `value` yielded (valid only when `cond`).
/// `value2` is `Some` ONLY for a tuple-yielding source (`Zip`), carrying the
/// second tuple component; `None` for every scalar / `&T` source.
/// `advanced_cursor` is `Some` ONLY in `SourceCursor::Params` mode: the
/// post-advance cursor value every header re-entry edge must forward (the
/// slot-mode arms committed their advance by store instead).
struct SourceNext {
    cond: ValueId,
    value: ValueId,
    value2: Option<ValueId>,
    advanced_cursor: Option<ValueId>,
}

/// Emit the branchless source-iterator advance into `block`: load the state at
/// `chain_slot + offset`, compute `cond` + the yielded element, store the
/// advanced state back (guarded by `cond` so an exhausted source never mutates).
/// When `reversed` (a `.rev()` wraps the chain) the bounded source is walked
/// end -> start: a Range yields `end-1` and decrements `end`; a slice yields the
/// element at `end-1` and decrements `end` by one stride; a RangeInclusive yields
/// `end` and decrements it (std's `spec_next_back`, exhausted flag included).
#[allow(clippy::too_many_arguments)]
fn emit_source_next<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    source: &ChainSource<'tcx>,
    offset: u64,
    _chain_slot: ValueId,
    reversed: bool,
    block: &mut Block,
    pre: &mut PreheaderAddrs<'_>,
    cursor: &SourceCursor,
) -> Result<SourceNext, String> {
    // `Params` mode is strictly opt-in per matched arm; a caller enabling it for
    // an unsupported source is an internal error — fail closed, never a silent
    // fall-through to slot semantics with a param-carrying header.
    if matches!(cursor, SourceCursor::Params { .. })
        && !source_cursor_params_supported(source, reversed)
    {
        return Err("iterator source-cursor Params mode on an unsupported source".to_owned());
    }
    match source {
        ChainSource::Range { ir_ty, size, .. } => {
            let signed = is_signed_trust_ir_integer(ir_ty);
            // E3 — loop-carried cursor: no per-iteration load / Select / store.
            // The exhausted iterator's non-advanced cursor is unobservable (the
            // chain slot is a private #111 copy), so the unconditional advance
            // is sound: it is only ever OBSERVED via a header re-entry edge,
            // which exists only when `cond` held and the element was consumed.
            if let SourceCursor::Params { cursor, bound } = cursor {
                let one = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Const {
                        ty: ir_ty.clone(),
                        value: Constant::Int(1),
                    })
                    .with_result(one),
                );
                if reversed {
                    // cursor = the walking `end` lane; bound = the invariant
                    // `start`. cond = start < end; value = advanced = end - 1.
                    let cond = ctx.fresh_value();
                    block.body.push(
                        InstrNode::new(Inst::ICmp {
                            op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                            ty: ir_ty.clone(),
                            lhs: *bound,
                            rhs: *cursor,
                        })
                        .with_result(cond),
                    );
                    let dec_end = ctx.fresh_value();
                    block.body.push(
                        InstrNode::new(Inst::BinOp {
                            op: TrustIrBinOp::Sub,
                            ty: ir_ty.clone(),
                            lhs: *cursor,
                            rhs: one,
                        })
                        .with_result(dec_end),
                    );
                    return Ok(SourceNext {
                        cond,
                        value: dec_end,
                        value2: None,
                        advanced_cursor: Some(dec_end),
                    });
                }
                // Forward: cursor = the walking `start`; bound = the invariant
                // `end`. cond = start < end; value = start; advanced = start + 1.
                let cond = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                        ty: ir_ty.clone(),
                        lhs: *cursor,
                        rhs: *bound,
                    })
                    .with_result(cond),
                );
                let advanced = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Add,
                        ty: ir_ty.clone(),
                        lhs: *cursor,
                        rhs: one,
                    })
                    .with_result(advanced),
                );
                return Ok(SourceNext {
                    cond,
                    value: *cursor,
                    value2: None,
                    advanced_cursor: Some(advanced),
                });
            }
            let start_addr = pre.field_addr(ctx, offset);
            let start = emit_typed_load(ctx, block, start_addr, ir_ty.clone());
            let end_addr = pre.field_addr(ctx, offset + size);
            let end = emit_typed_load(ctx, block, end_addr, ir_ty.clone());
            // `cond = start < end` (non-empty) in BOTH directions.
            let cond = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                    ty: ir_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(cond),
            );
            let one = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: ir_ty.clone(),
                    value: Constant::Int(1),
                })
                .with_result(one),
            );
            if reversed {
                // value = end - 1; new end = cond ? end-1 : end. `start` untouched.
                let dec_end = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Sub,
                        ty: ir_ty.clone(),
                        lhs: end,
                        rhs: one,
                    })
                    .with_result(dec_end),
                );
                let new_end = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: ir_ty.clone(),
                        cond,
                        then_val: dec_end,
                        else_val: end,
                    })
                    .with_result(new_end),
                );
                emit_typed_store(block, end_addr, ir_ty.clone(), new_end);
                // The yielded value is `end - 1` (valid only when `cond`).
                Ok(SourceNext {
                    cond,
                    value: dec_end,
                    value2: None,
                    advanced_cursor: None,
                })
            } else {
                let advanced = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Add,
                        ty: ir_ty.clone(),
                        lhs: start,
                        rhs: one,
                    })
                    .with_result(advanced),
                );
                let new_start = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: ir_ty.clone(),
                        cond,
                        then_val: advanced,
                        else_val: start,
                    })
                    .with_result(new_start),
                );
                emit_typed_store(block, start_addr, ir_ty.clone(), new_start);
                Ok(SourceNext {
                    cond,
                    value: start,
                    value2: None,
                    advanced_cursor: None,
                })
            }
        }
        ChainSource::RangeInclusive {
            ir_ty,
            start_off,
            end_off,
            exhausted_off,
            ..
        } => {
            // Forward this is std's `RangeInclusiveIteratorImpl::spec_next`;
            // `reversed` (a `.rev()` / `rfold` / `try_rfold` drive) is its
            // `spec_next_back`, the SAME three-way step with the roles of the
            // two endpoints swapped:
            //
            //   if exhausted || !(start <= end) { None }          // is_empty()
            //   else if start < end { Some(replace(&mut CUR, CUR ± 1)) }
            //   else { exhausted = true; Some(CUR) }               // start == end
            //
            // where CUR is `start` (+1) forward and `end` (-1) backward. The
            // emptiness test, the `is_iterating` test and the exhausted-flag
            // update do not depend on the direction; only which endpoint is
            // yielded and stepped does. `spec_try_rfold` (what `rfold` /
            // `try_rfold` reach) yields the identical sequence: its `while
            // start < end` loop is the `is_iterating` arm, and its tail sets
            // `exhausted` and yields `start` — equal to `end` there — once. The
            // state it leaves after a short-circuit (`?` after `replace`, or
            // after the flag is set) is the state this step leaves too.
            let signed = is_signed_trust_ir_integer(ir_ty);
            // Field addresses: the RangeInclusive struct sits at `chain_slot +
            // offset`; its fields are at the layout-derived sub-offsets. The
            // invariant addresses are hoisted to the preheader (E4).
            let start_addr = pre.field_addr(ctx, offset + *start_off);
            let start = emit_typed_load(ctx, block, start_addr, ir_ty.clone());
            let end_addr = pre.field_addr(ctx, offset + *end_off);
            let end = emit_typed_load(ctx, block, end_addr, ir_ty.clone());
            let exhausted_addr = pre.field_addr(ctx, offset + *exhausted_off);
            let exhausted_byte = emit_typed_load(ctx, block, exhausted_addr, TrustIrTy::I8);

            // already_exhausted = exhausted_byte != 0.
            let zero8 = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I8,
                    value: Constant::Int(0),
                })
                .with_result(zero8),
            );
            let already_exhausted = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ne,
                    ty: TrustIrTy::I8,
                    lhs: exhausted_byte,
                    rhs: zero8,
                })
                .with_result(already_exhausted),
            );
            // start_le_end = start <= end.
            let start_le_end = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Sle } else { ICmpOp::Ule },
                    ty: ir_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(start_le_end),
            );
            let false_bool = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::Bool,
                    value: Constant::Bool(false),
                })
                .with_result(false_bool),
            );
            // cond = already_exhausted ? false : start_le_end.
            let cond = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Bool,
                    cond: already_exhausted,
                    then_val: false_bool,
                    else_val: start_le_end,
                })
                .with_result(cond),
            );
            // is_iterating = start < end.
            let is_iterating = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
                    ty: ir_ty.clone(),
                    lhs: start,
                    rhs: end,
                })
                .with_result(is_iterating),
            );
            // The yielded-and-stepped endpoint: `start` (+1) forward, `end` (-1)
            // reversed (`spec_next_back`). The yielded value is that endpoint's
            // PRE-step value in both directions (`mem::replace`, or the
            // `start == end` element itself).
            let (cur_addr, cur, step_op) = if reversed {
                (end_addr, end, TrustIrBinOp::Sub)
            } else {
                (start_addr, start, TrustIrBinOp::Add)
            };
            // stepped = cur ± 1 (wrapping; dead unless is_iterating, and
            // `start < end` keeps it in range in either direction).
            let one = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: ir_ty.clone(),
                    value: Constant::Int(1),
                })
                .with_result(one),
            );
            let stepped = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: step_op,
                    ty: ir_ty.clone(),
                    lhs: cur,
                    rhs: one,
                })
                .with_result(stepped),
            );
            let cur_if_yield = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: ir_ty.clone(),
                    cond: is_iterating,
                    then_val: stepped,
                    else_val: cur,
                })
                .with_result(cur_if_yield),
            );
            // new_cur = cond ? cur_if_yield : cur.
            let new_cur = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: ir_ty.clone(),
                    cond,
                    then_val: cur_if_yield,
                    else_val: cur,
                })
                .with_result(new_cur),
            );
            emit_typed_store(block, cur_addr, ir_ty.clone(), new_cur);
            // set_exhausted = is_iterating ? false : cond.
            let set_exhausted = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Bool,
                    cond: is_iterating,
                    then_val: false_bool,
                    else_val: cond,
                })
                .with_result(set_exhausted),
            );
            let one8 = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I8,
                    value: Constant::Int(1),
                })
                .with_result(one8),
            );
            let new_exhausted_byte = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::I8,
                    cond: set_exhausted,
                    then_val: one8,
                    else_val: exhausted_byte,
                })
                .with_result(new_exhausted_byte),
            );
            emit_typed_store(block, exhausted_addr, TrustIrTy::I8, new_exhausted_byte);
            Ok(SourceNext {
                cond,
                value: cur,
                value2: None,
                advanced_cursor: None,
            })
        }
        ChainSource::Slice {
            ir_ty,
            size,
            end_off,
            repr,
            ..
        } => {
            // E3 — loop-carried element pointer (FORWARD only; the support
            // predicate rejects Params for a reversed slice in v1): no
            // per-iteration load / Select / store. The invariant `end` bound's
            // int form is hoisted to the preheader.
            if let SourceCursor::Params { cursor, bound } = cursor {
                let end_int = emit_ptr_to_int(ctx, pre.block, *bound);
                let ptr_int = emit_ptr_to_int(ctx, block, *cursor);
                let cond = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Ne,
                        ty: TrustIrTy::I64,
                        lhs: ptr_int,
                        rhs: end_int,
                    })
                    .with_result(cond),
                );
                let index_one = emit_i64_const(ctx, block, 1);
                let advanced = emit_element_addr(ctx, block, *cursor, index_one, *size);
                // `slice::Iter::next` yields `&T`: the item is the pre-advance
                // element POINTER itself (the cursor param).
                let _ = ir_ty;
                return Ok(SourceNext {
                    cond,
                    value: *cursor,
                    value2: None,
                    advanced_cursor: Some(advanced),
                });
            }
            // An index cursor (`array::IntoIter`) is driven as element pointers
            // into its inline data and stored back as indices.
            let data = match repr {
                SliceCursorRepr::Pointers => None,
                SliceCursorRepr::Indices { data_off } => {
                    Some(pre.field_addr(ctx, offset + *data_off))
                }
            };
            let ptr_addr = pre.field_addr(ctx, offset);
            let ptr = emit_slice_cursor_load(ctx, block, ptr_addr, data, *size);
            let end_addr = pre.field_addr(ctx, offset + *end_off);
            let end = emit_slice_cursor_load(ctx, block, end_addr, data, *size);
            let ptr_int = emit_ptr_to_int(ctx, block, ptr);
            let end_int = emit_ptr_to_int(ctx, block, end);
            // `cond = ptr != end` (non-empty) in BOTH directions.
            let cond = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ne,
                    ty: TrustIrTy::I64,
                    lhs: ptr_int,
                    rhs: end_int,
                })
                .with_result(cond),
            );
            if reversed {
                // Reversed slice: yield the element at `end - 1` stride, decrement
                // `end`. `new_end = cond ? end - size : end`; value = end - size.
                let neg_one = emit_i64_const(ctx, block, -1);
                let back = emit_element_addr(ctx, block, end, neg_one, *size);
                let new_end = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::Ptr,
                        cond,
                        then_val: back,
                        else_val: end,
                    })
                    .with_result(new_end),
                );
                emit_slice_cursor_store(ctx, block, end_addr, data, *size, new_end);
                let _ = ir_ty;
                Ok(SourceNext {
                    cond,
                    value: back,
                    value2: None,
                    advanced_cursor: None,
                })
            } else {
                let index_one = emit_i64_const(ctx, block, 1);
                let advanced = emit_element_addr(ctx, block, ptr, index_one, *size);
                let new_ptr = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::Ptr,
                        cond,
                        then_val: advanced,
                        else_val: ptr,
                    })
                    .with_result(new_ptr),
                );
                emit_slice_cursor_store(ctx, block, ptr_addr, data, *size, new_ptr);
                // `slice::Iter::next` yields `&T`: the item representation is the
                // pre-advance element POINTER itself (a `Map` closure receives `&T`;
                // a terminal consumer derefs it). Carry the pointer through.
                let _ = ir_ty;
                Ok(SourceNext {
                    cond,
                    value: ptr,
                    value2: None,
                    advanced_cursor: None,
                })
            }
        }
        ChainSource::Concat {
            first,
            first_offset,
            first_none,
            second,
            second_offset,
            second_none,
        } => {
            // `a.chain(b)`: advance `a`; if `a` had an element use it, else advance
            // `b`. Each side is a bare `Range` OR `slice::Iter` (the only two shapes
            // `resolve_chain_concat` admits). A side advances only while its
            // `Option` is `Some`: core's `Chain::next` sets `a = None` once `a` is
            // exhausted and `next_back` / `nth` clear a side they exhaust, which
            // leaves no cursor in its payload (a null `slice::Iter` `ptr`, or
            // undefined `Range` bytes). The second advance's state mutation is
            // GATED on `a` being exhausted or cleared, so a `b` element is never
            // consumed while `a` still has elements.
            if reversed {
                return Err("rev() over a chain() is not modeled".to_owned());
            }
            // The yielded value's ir type: a `Range` yields its scalar int; a
            // `slice::Iter` yields a `&T` POINTER. Both sub-sources yield the SAME
            // representation (enforced in `resolve_chain_concat`), so take the first.
            let value_ty = match &**first {
                ChainSource::Range { ir_ty, .. } => ir_ty.clone(),
                ChainSource::Slice { .. } => TrustIrTy::Ptr,
                _ => {
                    return Err(
                        "chain() first sub-source is not a bare Range or slice::Iter".to_owned(),
                    );
                }
            };
            // `enable` for the first sub-source: `a` is `Some`.
            let a_tag_addr = pre.field_addr(ctx, offset + first_none.offset);
            let a_some = emit_chain_half_is_some(ctx, block, a_tag_addr, first_none);
            let a = match &**first {
                ChainSource::Range { ir_ty, size, .. } => emit_range_next_guarded(
                    ctx,
                    block,
                    pre,
                    offset + *first_offset,
                    ir_ty,
                    *size,
                    a_some,
                ),
                ChainSource::Slice { size, end_off, .. } => emit_slice_next_guarded(
                    ctx,
                    block,
                    pre,
                    offset + *first_offset,
                    *end_off,
                    *size,
                    a_some,
                ),
                _ => {
                    return Err(
                        "chain() first sub-source is not a bare Range or slice::Iter".to_owned(),
                    );
                }
            };
            // `a_empty = (a.cond == false)` (a bool NOT, modeled as `== 0`).
            let bfalse = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::Bool,
                    value: Constant::Bool(false),
                })
                .with_result(bfalse),
            );
            let a_empty = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Eq,
                    ty: TrustIrTy::Bool,
                    lhs: a.cond,
                    rhs: bfalse,
                })
                .with_result(a_empty),
            );
            // Advance `b` only when `a` gave nothing and `b` is `Some`.
            let b_tag_addr = pre.field_addr(ctx, offset + second_none.offset);
            let b_some = emit_chain_half_is_some(ctx, block, b_tag_addr, second_none);
            let b_enable = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::And,
                    ty: TrustIrTy::Bool,
                    lhs: a_empty,
                    rhs: b_some,
                })
                .with_result(b_enable),
            );
            let b = match &**second {
                ChainSource::Range { ir_ty, size, .. } => emit_range_next_guarded(
                    ctx,
                    block,
                    pre,
                    offset + *second_offset,
                    ir_ty,
                    *size,
                    b_enable,
                ),
                ChainSource::Slice { size, end_off, .. } => emit_slice_next_guarded(
                    ctx,
                    block,
                    pre,
                    offset + *second_offset,
                    *end_off,
                    *size,
                    b_enable,
                ),
                _ => {
                    return Err(
                        "chain() second sub-source is not a bare Range or slice::Iter".to_owned(),
                    );
                }
            };
            // Combined cond = a.cond || b.cond.
            let cond = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Or,
                    ty: TrustIrTy::Bool,
                    lhs: a.cond,
                    rhs: b.cond,
                })
                .with_result(cond),
            );
            // Combined value = a.cond ? a.value : b.value. (Both sub-sources yield the
            // same ir representation -- both a scalar int, or both a `&T` ptr.)
            let value = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: value_ty,
                    cond: a.cond,
                    then_val: a.value,
                    else_val: b.value,
                })
                .with_result(value),
            );
            Ok(SourceNext {
                cond,
                value,
                value2: None,
                advanced_cursor: None,
            })
        }
        ChainSource::Zip {
            a,
            b,
            index_offset,
            len_offset,
        } => {
            // TRA Zip: read element `index` off each side's ORIGINAL state (the
            // sub-iterators are NOT advanced); the `index`/`len` cursor drives
            // termination. `.rev()` over a zip() is not modeled.
            if reversed {
                return Err("rev() over a zip() is not modeled".to_owned());
            }
            // `index` / `len` are `usize` fields (`usize_field_ty`).
            let word = usize_field_ty(ctx.tcx);
            let index_addr = pre.field_addr(ctx, offset + *index_offset);
            let index = emit_typed_load(ctx, block, index_addr, word.clone());
            let len_addr = pre.field_addr(ctx, offset + *len_offset);
            let len = emit_typed_load(ctx, block, len_addr, word.clone());
            // cond = index < len (usize, unsigned).
            let cond = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ult,
                    ty: word.clone(),
                    lhs: index,
                    rhs: len,
                })
                .with_result(cond),
            );
            // Per-side element `index`: slice side = `base_ptr + index*stride`
            // (a `&T` pointer); Range side = `start + index` BY VALUE (the
            // `start` field is never advanced under TRA, so it is the original
            // range base — `__iterator_get_unchecked(i)` exactly).
            let side_elem = |ctx: &mut MirLoweringCtx<'tcx>,
                             block: &mut Block,
                             pre: &mut PreheaderAddrs<'_>,
                             side: &ZipSide<'tcx>|
             -> ValueId {
                match side.kind {
                    ZipSideKind::SlicePtr => {
                        let base_addr = pre.field_addr(ctx, offset + side.offset);
                        let base = emit_typed_load(ctx, block, base_addr, TrustIrTy::Ptr);
                        emit_element_addr(ctx, block, base, index, side.elem_size)
                    }
                    ZipSideKind::RangeStart => {
                        let side_word = zip_range_word_ty(side);
                        let start_addr = pre.field_addr(ctx, offset + side.offset);
                        let start = emit_typed_load(ctx, block, start_addr, side_word.clone());
                        let result = ctx.fresh_value();
                        block.body.push(
                            InstrNode::new(Inst::BinOp {
                                op: TrustIrBinOp::Add,
                                ty: side_word,
                                lhs: start,
                                rhs: index,
                            })
                            .with_result(result),
                        );
                        result
                    }
                }
            };
            let a_elem = side_elem(ctx, block, pre, a);
            let b_elem = side_elem(ctx, block, pre, b);
            // new_index = cond ? index+1 : index (advance only when yielding).
            let one = emit_usize_field_const(ctx, block, 1);
            let advanced = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Add,
                    ty: word.clone(),
                    lhs: index,
                    rhs: one,
                })
                .with_result(advanced),
            );
            let new_index = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: word.clone(),
                    cond,
                    then_val: advanced,
                    else_val: index,
                })
                .with_result(new_index),
            );
            emit_typed_store(block, index_addr, word, new_index);
            // Yields the 2-tuple: each component a pointer (slice side) or a
            // 64-bit value (Range side); `chain_source_item` describes which.
            Ok(SourceNext {
                cond,
                value: a_elem,
                value2: Some(b_elem),
                advanced_cursor: None,
            })
        }
    }
}

/// Advance a forward `Range<T>` iterator state at `chain_slot + offset` by one,
/// GATED on `enable`: the `start` field is only incremented when `enable` AND the
/// range is non-empty. Returns `cond` (= `enable && start < end`, the element is
/// valid) and the yielded `value` (the pre-advance `start`). Used by `chain()`'s
/// Range sub-sources: enable = the half's `Option` is `Some`, and for the second
/// half also that the first gave nothing. A disabled call still loads the state
/// and stores `start` back unchanged.
fn emit_range_next_guarded(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    pre: &mut PreheaderAddrs<'_>,
    offset: u64,
    ir_ty: &TrustIrTy,
    size: u64,
    enable: ValueId,
) -> SourceNext {
    let signed = is_signed_trust_ir_integer(ir_ty);
    let start_addr = pre.field_addr(ctx, offset);
    let start = emit_typed_load(ctx, block, start_addr, ir_ty.clone());
    let end_addr = pre.field_addr(ctx, offset + size);
    let end = emit_typed_load(ctx, block, end_addr, ir_ty.clone());
    let nonempty = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: if signed { ICmpOp::Slt } else { ICmpOp::Ult },
            ty: ir_ty.clone(),
            lhs: start,
            rhs: end,
        })
        .with_result(nonempty),
    );
    // cond = enable && nonempty.
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::And,
            ty: TrustIrTy::Bool,
            lhs: enable,
            rhs: nonempty,
        })
        .with_result(cond),
    );
    let one = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: ir_ty.clone(),
            value: Constant::Int(1),
        })
        .with_result(one),
    );
    let advanced = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Add,
            ty: ir_ty.clone(),
            lhs: start,
            rhs: one,
        })
        .with_result(advanced),
    );
    // new start = cond ? start+1 : start (mutate only when this element is taken).
    let new_start = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: ir_ty.clone(),
            cond,
            then_val: advanced,
            else_val: start,
        })
        .with_result(new_start),
    );
    emit_typed_store(block, start_addr, ir_ty.clone(), new_start);
    SourceNext {
        cond,
        value: start,
        value2: None,
        advanced_cursor: None,
    }
}

/// Advance a forward `slice::Iter` state at `chain_slot + offset` by one, GATED on
/// `enable`: the `ptr` field is only advanced when `enable` AND the iterator is
/// non-empty (`ptr != end`). Returns `cond` (= `enable && ptr != end`, the element
/// is valid) and the yielded `value` (the pre-advance element POINTER `&T` — exactly
/// what `slice::Iter::next` yields). The slice `next` analogue of
/// [`emit_range_next_guarded`], used by `chain()`'s slice sub-sources (enable =
/// the half's `Option` is `Some`, and for the second half also that the first
/// gave nothing; a disabled call stores `ptr` back unchanged). Forward only
/// (a reversed chain fails closed upstream); mirrors the non-reversed bare-`Slice`
/// arm of `emit_source_next`. `end_off` is the source's `ptr`-to-`end` distance.
fn emit_slice_next_guarded(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    pre: &mut PreheaderAddrs<'_>,
    offset: u64,
    end_off: u64,
    size: u64,
    enable: ValueId,
) -> SourceNext {
    let ptr_addr = pre.field_addr(ctx, offset);
    let ptr = emit_typed_load(ctx, block, ptr_addr, TrustIrTy::Ptr);
    let end_addr = pre.field_addr(ctx, offset + end_off);
    let end = emit_typed_load(ctx, block, end_addr, TrustIrTy::Ptr);
    let ptr_int = emit_ptr_to_int(ctx, block, ptr);
    let end_int = emit_ptr_to_int(ctx, block, end);
    let nonempty = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: ptr_int,
            rhs: end_int,
        })
        .with_result(nonempty),
    );
    // cond = enable && (ptr != end).
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::And,
            ty: TrustIrTy::Bool,
            lhs: enable,
            rhs: nonempty,
        })
        .with_result(cond),
    );
    let index_one = emit_i64_const(ctx, block, 1);
    let advanced = emit_element_addr(ctx, block, ptr, index_one, size);
    // new ptr = cond ? ptr + stride : ptr (advance only when this element is taken).
    let new_ptr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: TrustIrTy::Ptr,
            cond,
            then_val: advanced,
            else_val: ptr,
        })
        .with_result(new_ptr),
    );
    emit_typed_store(block, ptr_addr, TrustIrTy::Ptr, new_ptr);
    SourceNext {
        cond,
        value: ptr,
        value2: None,
        advanced_cursor: None,
    }
}

/// The payload of an `Option` the iterator `next` builds.
enum OptionPayload {
    /// A scalar value stored in the `Some` variant's payload field (e.g.
    /// `Option<i64>` from `Range::next`).
    Scalar { value: ValueId, ty: TrustIrTy },
    /// A multi-leaf AGGREGATE payload copied lane-by-lane out of `src_addr` (e.g.
    /// `Option<P>` from `Vec::<P>::pop`, where `P` is a class-2 struct element).
    /// `lanes` are element-relative `(byte offset, scalar type)` pairs, exactly as
    /// `vec_element_image_lanes` produces them, so padding is never touched.
    Image {
        src_addr: ValueId,
        lanes: Vec<(u64, TrustIrTy)>,
    },
    /// A reference / pointer that IS the niche field (e.g. `Option<&T>` from
    /// `slice::Iter::next`): `Some(p)` holds the non-null `p`, `None` is null.
    Reference { ptr: ValueId },
    /// A 2-tuple `(A::Item, B::Item)` payload (from `Zip::next`). Each component is
    /// a niche POINTER (a slice side's `&T`, ir `Ptr`) or a by-value SCALAR (a
    /// Range side, ir `I64`), threaded in source-side order (`a` = tuple field 0,
    /// `b` = tuple field 1). At least one component MUST be a pointer so the
    /// `Option<(A, B)>` is niche-encoded; the `(val, val)` direct-tagged case
    /// (range.zip(range)) fails closed via the `_ => Err` arm.
    Tuple2 {
        a: ValueId,
        a_ir: TrustIrTy,
        b: ValueId,
        b_ir: TrustIrTy,
    },
    /// A 2-tuple `(&T, &[T])` payload (from `<[T]>::split_first` / `split_last`):
    /// field 0 is a THIN element reference (`first_ptr`, ir `Ptr`), field 1 is a
    /// FAT slice reference (`tail_data`/`tail_len`, the `{ ptr, len }` lanes). The
    /// niche is whichever non-null pointer field rustc chose (`first_ptr`, or the
    /// tail's data pointer); the OTHER pointer + the tail `len` are written
    /// unconditionally (dead on `None`).
    RefAndSlice {
        first_ptr: ValueId,
        tail_data: ValueId,
        tail_len: ValueId,
    },
    /// A fat `&[T]` sub-slice payload (from `<[T]>::windows`/`chunks` `next`):
    /// `Some(&[T])` holds `{ data (non-null), len }`; `None` is the null-data niche.
    /// The `Option<&[T]>` is niche-encoded on the slice's data pointer (a `NonNull`),
    /// so `data` IS the discriminant field and `len` is written unconditionally
    /// (dead on `None`).
    Slice { data: ValueId, len: ValueId },
}

/// Emit a `PtrToInt` cast of `ptr` to `I64`. The pointer is first normalized to a
/// plain `Ptr` carrier (it may be a typed `PtrConst`/`PtrMut`/`Ref`), so the cast's
/// declared `src_ty=Ptr` satisfies the fail-closed cast-source-type gate.
fn emit_ptr_to_int(ctx: &mut MirLoweringCtx<'_>, block: &mut Block, ptr: ValueId) -> ValueId {
    let ptr = coerce_to_plain_ptr(ctx, block, ptr);
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::PtrToInt,
            src_ty: TrustIrTy::Ptr,
            dst_ty: TrustIrTy::I64,
            operand: ptr,
        })
        .with_result(result),
    );
    result
}

/// Write `cond ? Some(payload) : None` into the memory-backed destination
/// `Option<…>` slot. Reuses the bridge's `memory_aggregate_layout` to learn the
/// `Option`'s exact layout (tag offset/encoding), then chooses the tag and
/// payload at runtime with `Select`s so the result flows through the existing
/// memory-enum `discriminant` / payload-read machinery unchanged.
fn store_option_some_value<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    dest_local: Local,
    dest_ty: Ty<'tcx>,
    cond: ValueId,
    payload: OptionPayload,
) -> Result<(), String> {
    let _ = body;
    let slot_ptr = ctx
        .memory_slots
        .get(&dest_local)
        .cloned()
        .ok_or_else(|| "iterator next destination is not memory-backed".to_owned())?
        .ptr;
    let Some(layout) = memory_aggregate_layout_shared(ctx.tcx, dest_ty)? else {
        return Err(format!(
            "iterator next destination {dest_ty:?} has no memory layout"
        ));
    };
    let Some(tag) = layout.tag.clone() else {
        return Err("iterator next destination is not a tagged Option".to_owned());
    };

    // Identify the `Some` / `None` variants by their payload-carrying-ness: the
    // `Option<…>` enum has exactly two inhabited variants; `Some` is the one with
    // a field. We locate them by walking the enum's variants.
    let (some_variant, none_variant, some_field_offset, some_field_ty) =
        option_some_none_variants(ctx.tcx, dest_ty)?;

    match (&tag.encoding, payload) {
        // Direct-tagged `Option<T>` (e.g. `Option<i64>`): write the chosen tag
        // word and the payload value at the `Some` field offset. The payload is
        // written UNCONDITIONALLY (its bytes are dead for the `None` case, which
        // the tag disambiguates), so this stays branchless.
        (
            MemoryTagEncoding::Direct,
            OptionPayload::Scalar {
                value,
                ty: payload_ty,
            },
        ) => {
            let some_discr =
                adt_discriminant_value(ctx.tcx, option_did(ctx.tcx, dest_ty)?, some_variant)?;
            let none_discr =
                adt_discriminant_value(ctx.tcx, option_did(ctx.tcx, dest_ty)?, none_variant)?;
            let some_tag = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: tag.ty.clone(),
                    value: Constant::Int(some_discr),
                })
                .with_result(some_tag),
            );
            let none_tag = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: tag.ty.clone(),
                    value: Constant::Int(none_discr),
                })
                .with_result(none_tag),
            );
            let chosen_tag = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: tag.ty.clone(),
                    cond,
                    then_val: some_tag,
                    else_val: none_tag,
                })
                .with_result(chosen_tag),
            );
            let tag_addr = iter_field_addr(ctx, block, slot_ptr, tag.offset);
            emit_typed_store(block, tag_addr, tag.ty.clone(), chosen_tag);

            // Payload: store the value at the `Some` field offset.
            let _ = some_field_ty;
            let payload_addr = iter_field_addr(ctx, block, slot_ptr, some_field_offset);
            emit_typed_store(block, payload_addr, payload_ty, value);
            Ok(())
        }
        // Direct-tagged `Option<Aggregate>` (e.g. `Option<P>` from
        // `Vec::<P>::pop`): identical tag handling, but the payload is copied
        // lane-by-lane from `src_addr` to the `Some` field offset. Like the scalar
        // arm the payload bytes are written UNCONDITIONALLY — they are dead for
        // `None`, which the tag disambiguates — so this stays branchless.
        (MemoryTagEncoding::Direct, OptionPayload::Image { src_addr, lanes }) => {
            let some_discr =
                adt_discriminant_value(ctx.tcx, option_did(ctx.tcx, dest_ty)?, some_variant)?;
            let none_discr =
                adt_discriminant_value(ctx.tcx, option_did(ctx.tcx, dest_ty)?, none_variant)?;
            let some_tag = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: tag.ty.clone(),
                    value: Constant::Int(some_discr),
                })
                .with_result(some_tag),
            );
            let none_tag = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: tag.ty.clone(),
                    value: Constant::Int(none_discr),
                })
                .with_result(none_tag),
            );
            let chosen_tag = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: tag.ty.clone(),
                    cond,
                    then_val: some_tag,
                    else_val: none_tag,
                })
                .with_result(chosen_tag),
            );
            let tag_addr = iter_field_addr(ctx, block, slot_ptr, tag.offset);
            emit_typed_store(block, tag_addr, tag.ty.clone(), chosen_tag);

            let _ = some_field_ty;
            let payload_base = iter_field_addr(ctx, block, slot_ptr, some_field_offset);
            emit_element_image_copy(ctx, block, payload_base, src_addr, &lanes);
            Ok(())
        }
        // Niche-tagged `Option<&T>`: the niche field IS the reference. `Some(p)`
        // stores the non-null `p`; `None` stores the null niche value
        // (`niche_start`). Choose between them with a `Select`.
        (
            MemoryTagEncoding::Niche {
                untagged_variant,
                niche_variants_start,
                niche_start,
                ..
            },
            OptionPayload::Reference { ptr },
        ) => {
            // For `Option<&T>` the untagged (payload-holding) variant is `Some`;
            // `None` is the single niche variant whose niche value is `niche_start`
            // (== 0, a null pointer).
            if *untagged_variant != some_variant {
                return Err("Option niche untagged variant is not Some".to_owned());
            }
            let none_rel = none_variant.as_u32() as u128 - niche_variants_start.as_u32() as u128;
            let none_niche = niche_start.wrapping_add(none_rel);

            // Materialize the `None` niche pointer (a null/`none_niche` address).
            let none_int = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I64,
                    value: Constant::Int(none_niche as i128),
                })
                .with_result(none_int),
            );
            let none_ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Cast {
                    op: CastOp::IntToPtr,
                    src_ty: TrustIrTy::I64,
                    dst_ty: TrustIrTy::Ptr,
                    operand: none_int,
                })
                .with_result(none_ptr),
            );
            let chosen = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Ptr,
                    cond,
                    then_val: ptr,
                    else_val: none_ptr,
                })
                .with_result(chosen),
            );
            let niche_addr = iter_field_addr(ctx, block, slot_ptr, tag.offset);
            emit_typed_store(block, niche_addr, TrustIrTy::Ptr, chosen);
            Ok(())
        }
        // Niche-tagged `Option<SCALAR>` where the SCALAR itself carries the niche
        // (`Option<char>` from `Chars::next`: `char` is 4 bytes valid `0..=0x10FFFF`,
        // so `Option<char>` niche-optimizes to a single i32 with `Some(c) == c` and
        // `None` = the first invalid value). `Some` stores the scalar; `None` stores
        // the niche value, chosen with a `Select`.
        (
            MemoryTagEncoding::Niche {
                untagged_variant,
                niche_variants_start,
                niche_start,
                ..
            },
            OptionPayload::Scalar {
                value,
                ty: payload_ty,
            },
        ) => {
            if *untagged_variant != some_variant {
                return Err("Option niche (scalar) untagged variant is not Some".to_owned());
            }
            let none_rel = none_variant.as_u32() as u128 - niche_variants_start.as_u32() as u128;
            let none_niche = niche_start.wrapping_add(none_rel);
            // `Option<bool>`: the payload's IR type is the 1-bit `Bool`, but its niche
            // field is the 8-bit tag (`None` = 2), which no `Bool` constant can
            // hold. Widen the payload to the tag's integer type and build, select
            // and store the niche there. Every other niche scalar (`char`,
            // `NonZero`, a niche-carrying enum) already has the tag's width.
            let (value, payload_ty) = if payload_ty == TrustIrTy::Bool {
                if !tag.ty.is_integer() {
                    return Err(format!(
                        "Option<bool> niche tag has a non-integer type {:?}",
                        tag.ty
                    ));
                }
                let widened = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::ZExt,
                        src_ty: TrustIrTy::Bool,
                        dst_ty: tag.ty.clone(),
                        operand: value,
                    })
                    .with_result(widened),
                );
                (widened, tag.ty.clone())
            } else {
                (value, payload_ty)
            };
            let none_val = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: payload_ty.clone(),
                    value: Constant::Int(none_niche as i128),
                })
                .with_result(none_val),
            );
            let chosen = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: payload_ty.clone(),
                    cond,
                    then_val: value,
                    else_val: none_val,
                })
                .with_result(chosen),
            );
            let niche_addr = iter_field_addr(ctx, block, slot_ptr, tag.offset);
            emit_typed_store(block, niche_addr, payload_ty, chosen);
            Ok(())
        }
        // Niche-tagged `Option<(A, B)>` (from `Zip::next`): the niche lives in ONE
        // of the tuple's pointer fields (a slice side's `&T`). We do NOT assume
        // which one — we match `tag.offset` (the niche byte offset) against each
        // tuple field's layout offset and treat the matching pointer field as the
        // niche (`Some` = the non-null element pointer, `None` = the null niche
        // value). The OTHER field is written UNCONDITIONALLY (its bytes are dead on
        // `None`, which the niche disambiguates). Any layout the niche offset does
        // not identify (e.g. the 24-byte direct-tagged `(val, val)` range+range
        // case, which never reaches this arm) fails closed.
        (
            MemoryTagEncoding::Niche {
                untagged_variant,
                niche_variants_start,
                niche_start,
                ..
            },
            OptionPayload::Tuple2 { a, a_ir, b, b_ir },
        ) => {
            if *untagged_variant != some_variant {
                return Err("Option<(A,B)> niche untagged variant is not Some".to_owned());
            }
            // Tuple field byte offsets WITHIN the Option (some_field_offset + the
            // field's offset inside the tuple). Layout order may differ from
            // declaration order, so use the layout offsets, not field indices.
            let tuple_ty = ctx.monomorphize_ty(some_field_ty);
            let ty::Tuple(elems) = tuple_ty.kind() else {
                return Err("Zip::next Option payload is not a tuple".to_owned());
            };
            if elems.len() != 2 {
                return Err("Zip::next Option payload tuple is not a 2-tuple".to_owned());
            }
            let tuple_layout = ctx
                .tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(tuple_ty))
                .map_err(|e| format!("Zip::next tuple layout_of failed: {e:?}"))?;
            let rustc_abi::FieldsShape::Arbitrary { .. } = tuple_layout.fields else {
                return Err("Zip::next Option payload tuple is not a field struct".to_owned());
            };
            // `a` is tuple field 0, `b` is tuple field 1 (source-side order); place
            // each at its LAYOUT offset within the Option.
            let f0 = some_field_offset + tuple_layout.fields.offset(0).bytes();
            let f1 = some_field_offset + tuple_layout.fields.offset(1).bytes();

            // The niche field is the tuple field the niche byte offset lands in.
            let (niche_off, niche_val, niche_ir, other_off, other_val, other_ir) = if tag.offset
                == f0
            {
                (f0, a, a_ir, f1, b, b_ir)
            } else if tag.offset == f1 {
                (f1, b, b_ir, f0, a, a_ir)
            } else {
                return Err("Zip::next Option niche offset matches neither tuple field".to_owned());
            };
            // The niche field MUST be a pointer (a slice side): a `(val, val)`
            // tuple has no niche and never reaches here, but re-check so a wrong
            // (scalar) field is never mis-encoded as the discriminant.
            if !matches!(niche_ir, TrustIrTy::Ptr) {
                return Err("Zip::next Option niche field is not a pointer".to_owned());
            }

            let none_rel = none_variant.as_u32() as u128 - niche_variants_start.as_u32() as u128;
            let none_niche = niche_start.wrapping_add(none_rel);

            // Materialize the `None` niche pointer.
            let none_int = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I64,
                    value: Constant::Int(none_niche as i128),
                })
                .with_result(none_int),
            );
            let none_ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Cast {
                    op: CastOp::IntToPtr,
                    src_ty: TrustIrTy::I64,
                    dst_ty: TrustIrTy::Ptr,
                    operand: none_int,
                })
                .with_result(none_ptr),
            );
            // Niche field: cond ? element_ptr : none_niche (this IS the discriminant).
            let chosen = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Ptr,
                    cond,
                    then_val: niche_val,
                    else_val: none_ptr,
                })
                .with_result(chosen),
            );
            let niche_addr = iter_field_addr(ctx, block, slot_ptr, niche_off);
            emit_typed_store(block, niche_addr, TrustIrTy::Ptr, chosen);

            // Other field: written unconditionally (dead on None).
            let other_addr = iter_field_addr(ctx, block, slot_ptr, other_off);
            emit_typed_store(block, other_addr, other_ir, other_val);
            Ok(())
        }
        // Niche-tagged `Option<(&T, &[T])>` (from `<[T]>::split_first`/`split_last`):
        // field 0 is a thin `&T`, field 1 a fat `&[T]` (`{data, len}`). The niche
        // is whichever non-null pointer field rustc chose (the `&T`, or the tail's
        // data pointer). The tail LEN (field 1 + the `&[T]`'s rustc metadata
        // offset) is always written; the niche
        // field carries the `Some`/`None` discriminant; the other pointer is
        // written unconditionally (dead on `None`).
        (
            MemoryTagEncoding::Niche {
                untagged_variant,
                niche_variants_start,
                niche_start,
                ..
            },
            OptionPayload::RefAndSlice {
                first_ptr,
                tail_data,
                tail_len,
            },
        ) => {
            if *untagged_variant != some_variant {
                return Err("Option<(&T,&[T])> niche untagged variant is not Some".to_owned());
            }
            let tuple_ty = ctx.monomorphize_ty(some_field_ty);
            let ty::Tuple(elems) = tuple_ty.kind() else {
                return Err("split_first Option payload is not a tuple".to_owned());
            };
            if elems.len() != 2 {
                return Err("split_first Option payload tuple is not a 2-tuple".to_owned());
            }
            let tuple_layout = ctx
                .tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(tuple_ty))
                .map_err(|e| format!("split_first tuple layout_of failed: {e:?}"))?;
            let rustc_abi::FieldsShape::Arbitrary { .. } = tuple_layout.fields else {
                return Err("split_first Option payload tuple is not a field struct".to_owned());
            };
            // field 0 = `&T` (thin), field 1 = `&[T]` (fat: data at +0, len at its
            // metadata offset — +8 on a 64-bit target, +4 on wasm32).
            let f0 = some_field_offset + tuple_layout.fields.offset(0).bytes();
            let f1 = some_field_offset + tuple_layout.fields.offset(1).bytes();
            let tail_len_off = split_ends_tail_len_offset(ctx.tcx, elems[1], f1)?;

            let none_rel = none_variant.as_u32() as u128 - niche_variants_start.as_u32() as u128;
            let none_niche = niche_start.wrapping_add(none_rel);
            let none_int = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I64,
                    value: Constant::Int(none_niche as i128),
                })
                .with_result(none_int),
            );
            let none_ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Cast {
                    op: CastOp::IntToPtr,
                    src_ty: TrustIrTy::I64,
                    dst_ty: TrustIrTy::Ptr,
                    operand: none_int,
                })
                .with_result(none_ptr),
            );

            // The tail length lane is always valid.
            let len_addr = iter_field_addr(ctx, block, slot_ptr, tail_len_off);
            emit_usize_field_store(ctx, block, len_addr, tail_len);

            // The niche is the `&T` (f0) or the tail's data ptr (f1). Select the
            // discriminant into that field; write the remaining pointer plainly.
            if tag.offset == f0 {
                let chosen = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::Ptr,
                        cond,
                        then_val: first_ptr,
                        else_val: none_ptr,
                    })
                    .with_result(chosen),
                );
                let niche_addr = iter_field_addr(ctx, block, slot_ptr, f0);
                emit_typed_store(block, niche_addr, TrustIrTy::Ptr, chosen);
                let data_addr = iter_field_addr(ctx, block, slot_ptr, f1);
                emit_typed_store(block, data_addr, TrustIrTy::Ptr, tail_data);
            } else if tag.offset == f1 {
                let chosen = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Select {
                        ty: TrustIrTy::Ptr,
                        cond,
                        then_val: tail_data,
                        else_val: none_ptr,
                    })
                    .with_result(chosen),
                );
                let niche_addr = iter_field_addr(ctx, block, slot_ptr, f1);
                emit_typed_store(block, niche_addr, TrustIrTy::Ptr, chosen);
                let fp_addr = iter_field_addr(ctx, block, slot_ptr, f0);
                emit_typed_store(block, fp_addr, TrustIrTy::Ptr, first_ptr);
            } else {
                return Err(
                    "split_first Option niche offset matches neither tuple field".to_owned(),
                );
            }
            Ok(())
        }
        // Niche-tagged `Option<&[T]>` (from `<[T]>::windows`/`chunks` `next`): the
        // payload is a single fat `&[T]` = `{ data, len }`. The niche is the `data`
        // pointer (a `NonNull<T>`): `Some` stores the non-null `data`, `None` the
        // null niche value. `len` (the OTHER pointer-width lane of the `&[T]`) is
        // written unconditionally (dead on `None`). Robust to field order —
        // `data`/`len` are the two lanes within the `&[T]` payload, at 0 and its
        // rustc metadata offset; whichever the niche byte offset lands in is
        // `data`, the other is `len`.
        (
            MemoryTagEncoding::Niche {
                untagged_variant,
                niche_variants_start,
                niche_start,
                ..
            },
            OptionPayload::Slice { data, len },
        ) => {
            if *untagged_variant != some_variant {
                return Err("Option<&[T]> niche untagged variant is not Some".to_owned());
            }
            let slot_a = some_field_offset;
            let slot_b = some_field_offset
                + fat_ptr_metadata_offset(ctx.tcx, ctx.monomorphize_ty(some_field_ty))?;
            let (data_off, len_off) = if tag.offset == slot_a {
                (slot_a, slot_b)
            } else if tag.offset == slot_b {
                (slot_b, slot_a)
            } else {
                return Err("Option<&[T]> niche offset matches neither slice lane".to_owned());
            };
            let none_rel = none_variant.as_u32() as u128 - niche_variants_start.as_u32() as u128;
            let none_niche = niche_start.wrapping_add(none_rel);
            let none_int = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: TrustIrTy::I64,
                    value: Constant::Int(none_niche as i128),
                })
                .with_result(none_int),
            );
            let none_ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Cast {
                    op: CastOp::IntToPtr,
                    src_ty: TrustIrTy::I64,
                    dst_ty: TrustIrTy::Ptr,
                    operand: none_int,
                })
                .with_result(none_ptr),
            );
            let len_addr = iter_field_addr(ctx, block, slot_ptr, len_off);
            emit_usize_field_store(ctx, block, len_addr, len);
            let chosen = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Select {
                    ty: TrustIrTy::Ptr,
                    cond,
                    then_val: data,
                    else_val: none_ptr,
                })
                .with_result(chosen),
            );
            let data_addr = iter_field_addr(ctx, block, slot_ptr, data_off);
            emit_typed_store(block, data_addr, TrustIrTy::Ptr, chosen);
            Ok(())
        }
        _ => Err("iterator next Option payload / encoding mismatch".to_owned()),
    }
}

/// The byte offset, within the `Option<(&T, &[T])>` image, of the tail slice's
/// length lane: the tail field's offset `f1` plus the `&[T]`'s rustc metadata
/// offset (8 on a 64-bit target, 4 on wasm32). Shared by the split_first /
/// split_last store and its value refinement so both name the same cell.
fn split_ends_tail_len_offset<'tcx>(
    tcx: TyCtxt<'tcx>,
    tail_ty: Ty<'tcx>,
    f1: u64,
) -> Result<u64, String> {
    let meta_off = fat_ptr_metadata_offset(tcx, tail_ty)?;
    f1.checked_add(meta_off)
        .ok_or_else(|| "split_first tail length offset overflow".to_owned())
}

/// The `DefId` of the `Option` enum for a `dest_ty` that is `Option<…>`.
fn option_did<'tcx>(tcx: TyCtxt<'tcx>, dest_ty: Ty<'tcx>) -> Result<DefId, String> {
    let _ = tcx;
    match dest_ty.kind() {
        ty::Adt(adt, _) => Ok(adt.did()),
        other => Err(format!(
            "iterator next destination is not an enum: {other:?}"
        )),
    }
}

/// Locate the `Some` / `None` variants of an `Option<…>` destination and the
/// byte offset + type of `Some`'s payload field. `Some` is the single
/// payload-carrying variant; `None` is the empty one.
fn option_some_none_variants<'tcx>(
    tcx: TyCtxt<'tcx>,
    dest_ty: Ty<'tcx>,
) -> Result<(VariantIdx, VariantIdx, u64, Ty<'tcx>), String> {
    let ty::Adt(adt, args) = dest_ty.kind() else {
        return Err(format!(
            "iterator next destination is not an enum: {dest_ty:?}"
        ));
    };
    if adt.variants().len() != 2 {
        return Err("iterator next destination Option does not have 2 variants".to_owned());
    }
    let cx = LayoutCx(tcx);
    let base_layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(dest_ty))
        .map_err(|e| format!("Option layout_of failed: {e:?}"))?;

    let mut some = None;
    let mut none = None;
    for (variant_index, variant) in adt.variants().iter_enumerated() {
        if variant.fields.is_empty() {
            none = Some(variant_index);
        } else if variant.fields.len() == 1 {
            let field_ty = ctx_field_ty(tcx, variant, *args, 0);
            let vl = base_layout.for_variant(&cx, variant_index);
            let offset = vl.fields.offset(0).bytes();
            some = Some((variant_index, offset, field_ty));
        } else {
            return Err("iterator next Option Some variant has != 1 field".to_owned());
        }
    }
    match (some, none) {
        (Some((sv, off, fty)), Some(nv)) => Ok((sv, nv, off, fty)),
        _ => Err("iterator next destination is not a Some/None Option".to_owned()),
    }
}

/// The monomorphized RETURN type of a (ZST or capturing) closure — the `Option<U>`
/// a `filter_map`/`scan` closure yields, or the `bool` a `take_while` predicate
/// yields.
fn closure_output_ty<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    closure_ty: Ty<'tcx>,
) -> Result<Ty<'tcx>, String> {
    let ty::Closure(_, cargs) = closure_ty.kind() else {
        return Err("closure_output_ty: not a closure".to_owned());
    };
    let sig = ctx
        .tcx
        .instantiate_bound_regions_with_erased(cargs.as_closure().sig());
    Ok(ctx.monomorphize_ty(sig.output()))
}

/// Validate that `opt_ty` is a `filter_map`/`scan` closure's `Option<U>` return
/// whose `Some` payload `U` is a by-value SCALAR the drive can dissect and yield:
/// a DIRECT-tagged, register-pair-returnable (`<= 16` byte) Option with a scalar
/// (integer/bool/float leaf, non-reference, non-tuple) payload. Returns the
/// `ChainItem` for `U` (what the adapter yields on `Some`). A niche-encoded Option
/// (`Option<&T>`/`Option<NonZero>`/`Option<bool>`), an sret-sized (`> 16` byte)
/// return, or a reference/aggregate payload FAILS CLOSED here so every downstream
/// path (resolve, slot-sizing, the drive) is uniformly fail-closed.
fn option_payload_scalar_item<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    opt_ty: Ty<'tcx>,
) -> Result<ChainItem<'tcx>, String> {
    let Some(layout) = memory_aggregate_layout_shared(ctx.tcx, opt_ty)? else {
        return Err("filter_map/scan Option return has no memory layout".to_owned());
    };
    let Some(tag) = &layout.tag else {
        return Err("filter_map/scan Option return is not a tagged enum".to_owned());
    };
    if !matches!(tag.encoding, MemoryTagEncoding::Direct) {
        return Err("filter_map/scan over a niche-encoded Option return \
             (Option<&T>/NonZero/bool) is not modeled"
            .to_owned());
    }
    if layout.size > 16 {
        return Err(
            "filter_map/scan Option return is too large for a register-pair ABI".to_owned(),
        );
    }
    let (_some_vidx, _none_vidx, _some_off, some_fty) = option_some_none_variants(ctx.tcx, opt_ty)?;
    let some_fty = ctx.monomorphize_ty(some_fty);
    if matches!(some_fty.kind(), ty::Ref(..)) {
        return Err("filter_map/scan closure returning Option<&T> is not modeled".to_owned());
    }
    let out_ir = rust_ty_to_trust_ir_ty(ctx.tcx, some_fty)?;
    if out_ir.bit_width().is_none() {
        return Err("filter_map/scan closure Option payload is not a scalar".to_owned());
    }
    Ok(ChainItem {
        rust_ty: some_fty,
        ir_ty: out_ir,
        deref_elem_ir: None,
        tuple: None,
    })
}

/// Dissect a `filter_map`/`scan` closure's by-value `Option<U>` return (`opt_val`,
/// the SSA call result — a register-pair aggregate) into `(is_some, payload,
/// payload_ir)`. Mirrors `lower_iter_try_fold`'s proven `ssa_cf` ExtractField path:
/// a DIRECT-tagged, register-pair-returnable (`<= 16` byte) Option with a
/// lane-aligned integer tag + a lane-aligned lane-fitting SCALAR payload. Any niche
/// encoding, an sret-sized (`> 16` byte) return (where `opt_val` would be a POINTER,
/// not the bytes — ExtractField would read garbage), an unaligned tag/payload, or a
/// non-scalar payload FAILS CLOSED (a wrong dissection silently miscomputes).
fn emit_option_step<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    opt_ty: Ty<'tcx>,
    opt_val: ValueId,
) -> Result<(ValueId, ValueId, TrustIrTy), String> {
    let ty::Adt(opt_adt, _) = opt_ty.kind() else {
        return Err("filter_map/scan Option return is not an ADT".to_owned());
    };
    let Some(layout) = memory_aggregate_layout_shared(ctx.tcx, opt_ty)? else {
        return Err("filter_map/scan Option return has no memory layout".to_owned());
    };
    let Some(tag) = layout.tag.clone() else {
        return Err("filter_map/scan Option return is not a tagged enum".to_owned());
    };
    if !matches!(tag.encoding, MemoryTagEncoding::Direct) {
        return Err("filter_map/scan over a niche-encoded Option return is not modeled".to_owned());
    }
    if layout.size > 16 {
        return Err(
            "filter_map/scan Option return is too large for a register-pair ABI".to_owned(),
        );
    }
    let align = layout.align;
    let (lane_ty, lane_size) = memory_aggregate_lane(align)
        .map_err(|_| format!("filter_map/scan Option alignment {align} unsupported"))?;
    if layout.size % lane_size != 0 {
        return Err("filter_map/scan Option size is not a lane multiple".to_owned());
    }
    let lanes = layout.size / lane_size;
    let (some_vidx, _none_vidx, some_off, some_fty) = option_some_none_variants(ctx.tcx, opt_ty)?;
    let some_fty = ctx.monomorphize_ty(some_fty);
    if matches!(some_fty.kind(), ty::Ref(..)) {
        return Err("filter_map/scan Option payload is a reference (not modeled)".to_owned());
    }
    let payload_ir = rust_ty_to_trust_ir_ty(ctx.tcx, some_fty)?;
    let lane_fits = |t: &TrustIrTy| -> bool {
        match (t.bit_width(), lane_ty.bit_width()) {
            (Some(a), Some(b)) => a <= b,
            _ => false,
        }
    };
    if payload_ir.bit_width().is_none() || !lane_fits(&payload_ir) {
        return Err("filter_map/scan Option payload is not a lane-fitting scalar".to_owned());
    }
    if !tag.ty.is_integer() || !lane_fits(&tag.ty) {
        return Err("filter_map/scan Option tag is not a lane-fitting integer".to_owned());
    }
    if tag.offset % lane_size != 0 || some_off % lane_size != 0 {
        return Err("filter_map/scan Option tag/payload is not lane-aligned".to_owned());
    }
    let tag_lane = tag.offset / lane_size;
    let some_lane = some_off / lane_size;
    if tag_lane >= lanes || some_lane >= lanes {
        return Err("filter_map/scan Option tag/payload lane out of range".to_owned());
    }
    let extract_lane =
        |ctx: &mut MirLoweringCtx<'tcx>, blk: &mut Block, lane: u64| -> Result<ValueId, String> {
            let v = ctx.fresh_value();
            let lane = u32::try_from(lane)
                .map_err(|_| format!("filter_map/scan Option lane {lane} out of u32 range"))?;
            emit_lane_value_read(ctx, blk, &layout.slot_ty, opt_val, lane, v)?;
            Ok(v)
        };
    // is_some = (tag == Some's discriminant).
    let tag_lane_val = extract_lane(ctx, block, tag_lane)?;
    let tag_val = convert_scalar(ctx, block, tag_lane_val, &lane_ty, &tag.ty);
    let some_discr = adt_discriminant_value(ctx.tcx, opt_adt.did(), some_vidx)?;
    let some_c = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Const {
            ty: tag.ty.clone(),
            value: Constant::Int(some_discr),
        })
        .with_result(some_c),
    );
    let is_some = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: tag.ty.clone(),
            lhs: tag_val,
            rhs: some_c,
        })
        .with_result(is_some),
    );
    // payload = the Some field's lane, converted to its scalar ir.
    let payload_lane = extract_lane(ctx, block, some_lane)?;
    let payload = convert_scalar(ctx, block, payload_lane, &lane_ty, &payload_ir);
    Ok((is_some, payload, payload_ir))
}

/// The monomorphized type of `variant`'s field `idx`.
fn ctx_field_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    variant: &ty::VariantDef,
    args: crate::fn_items::GenericArgsRef<'tcx>,
    idx: usize,
) -> Ty<'tcx> {
    variant.fields[FieldIdx::from_usize(idx)]
        .ty(tcx, args)
        .skip_normalization()
}

fn lower_direct_call_args<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    callee: Instance<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
    call_source_info: mir::SourceInfo,
) -> Result<(Vec<ValueId>, Vec<MutableReferenceArgReload>), String> {
    let callee_ty = callee.ty(ctx.tcx, ty::TypingEnv::fully_monomorphized());
    // A COROUTINE-body callee (the `resume` fn) has no `Ty::fn_sig` (it ICEs); its
    // input types are the resume body's MIR parameter `local_decls` — the same
    // source `func_ty_for_instance` reads, so the lowered args match the declared
    // ABI params exactly (`Pin<&mut C>` receiver + `ResumeTy` resume arg).
    if matches!(callee_ty.kind(), ty::Coroutine(..)) {
        let callee_body = ctx.tcx.instance_mir(callee.def);
        let inputs: Vec<Ty<'tcx>> = callee_body
            .args_iter()
            .map(|arg| ctx.monomorphize_ty(callee_body.local_decls[arg].ty))
            .collect();
        return lower_call_args_from_inputs(
            ctx,
            body,
            block,
            &inputs,
            args,
            (RustcFnAbiSource::Instance(callee), 0),
        );
    }
    let sig = callee_ty.fn_sig(ctx.tcx);
    let sig = ctx.tcx.instantiate_bound_regions_with_erased(sig);
    let variadic_args = if sig.c_variadic() {
        variadic::call(ctx, body, block, callee, sig.inputs(), args)?
    } else {
        None
    };
    let (mut values, mutable_reloads) = if let Some(lowered) = variadic_args {
        lowered
    } else if sig.abi() == rustc_abi::ExternAbi::RustCall {
        // The callee is declared untupled (`func_ty_for_instance`).
        lower_rust_call_args(
            ctx,
            body,
            block,
            sig.inputs(),
            args,
            RustcFnAbiSource::Instance(callee),
        )?
    } else {
        lower_call_args_from_inputs(
            ctx,
            body,
            block,
            sig.inputs(),
            args,
            (RustcFnAbiSource::Instance(callee), 0),
        )?
    };
    // rustc's hidden trailing `&'static Location` argument, which the MIR call
    // args do NOT include (rustc's own codegen injects it), matching the
    // declaration `func_ty_for_instance` makes for the same instance. See
    // `instance_abi_has_caller_location`. The value is exactly rustc's own
    // `FunctionCx::codegen_call_terminator` choice: `call_source_info` is the
    // call's `fn_span` with the terminator's SCOPE, and the scope decides
    // whether this call sits in an inlined `#[track_caller]` frame.
    if instance_abi_has_caller_location(ctx.tcx, callee) {
        values.push(caller_location_for_call(
            ctx,
            body,
            block,
            call_source_info,
        )?);
    }
    Ok((values, mutable_reloads))
}

/// The arguments of a call to an `extern "rust-call"` callable, in rustc's
/// UNTUPLED convention (`rust_call_spread`): the leading inputs exactly as any
/// call passes them (`lower_call_args_from_inputs`), then each element of the
/// argument-tuple operand as its own argument at its own `FnAbi` index
/// (`spread_fn_call_tuple_untupled`, the one reader of a tuple operand, which
/// builds each element through the one closure-argument builder). `inputs` and
/// `args` are the call's TUPLED lists, as MIR spells them. Shared by the direct
/// and the `fn`-pointer lanes; the virtual lane builds its hand-built
/// declaration from the same two halves.
fn lower_rust_call_args<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    inputs: &[Ty<'tcx>],
    args: &[rustc_span::Spanned<Operand<'tcx>>],
    source: RustcFnAbiSource<'tcx>,
) -> Result<(Vec<ValueId>, Vec<MutableReferenceArgReload>), String> {
    if inputs.len() != args.len() {
        return Err(format!(
            "TerminatorKind::Call argument count {} does not match callee input count {}",
            args.len(),
            inputs.len()
        ));
    }
    let (Some((_, leading_inputs)), Some((tuple, leading_args))) =
        (inputs.split_last(), args.split_last())
    else {
        return Err(
            "[TCG-ARG-ABI] a call of an `extern \"rust-call\"` callable has no argument \
             tuple; failing closed"
                .to_owned(),
        );
    };
    let (mut values, mutable_reloads) =
        lower_call_args_from_inputs(ctx, body, block, leading_inputs, leading_args, (source, 0))?;
    let (_, spread_values, _) =
        spread_fn_call_tuple_untupled(ctx, body, block, &tuple.node, source, leading_inputs.len())?;
    values.extend(spread_values);
    Ok((values, mutable_reloads))
}

/// The `{ data, len }` SLOT of a slice / `str` fat-pointer call argument, for both
/// ways such an argument is passed: its address (the whole-slot convention a
/// closure body or a non-x86-64 callee declares) or its two lanes read out of it
/// (the x86-64 `PassMode::Pair` lane, `scalar_pair_param_plan`). Three operand
/// shapes, each with its own named refusal: a whole memory-backed local (its
/// slot); a `Field`-projected element of a memory-backed tupled-args place (the
/// `const_eval_select` remap — the pair's address inside that slot); a const
/// slice literal (a fresh slot filled from the const allocation and length).
fn slice_fat_ptr_call_arg_slot<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    index: usize,
    operand: &Operand<'tcx>,
    expected_ty: Ty<'tcx>,
) -> Result<ValueId, String> {
    let slot_ptr = match operand {
        Operand::Copy(place) | Operand::Move(place) if place.projection.is_empty() => {
            ctx.memory_slots
                .get(&place.local)
                .cloned()
                .ok_or_else(|| {
                    format!(
                        "direct call slice fat-pointer arg {index} has no `{{ data, len }}` \
                     slot (un-materialized runtime slice)"
                    )
                })?
                .ptr
        }
        // A FIELD-PROJECTED slice argument, `rt_fn(move (_t.0), ..)`:
        // rustc's `remap_mir_for_const_eval_select` rewrites
        // `const_eval_select((args..), const_fn, rt_fn)` into a call whose
        // every argument is a `Field` of the tupled-args place
        // (`CStr::from_bytes_with_nul_unchecked`, `run_utf8_validation`,
        // `memchr_aligned`). An ordinary `f(x.buf)` is spilled to a temp at
        // every optimization level (`bridge_corpus/fix_q_slice_arg_from_struct_field`),
        // so this remap is the only measured producer. A `&[T]` / `&str` FIELD
        // of a memory-backed aggregate is already stored as the two lanes
        // `{ data @ off, len @ off+8 }` (the invariant `store_fat_ptr_slot_field`
        // / `load_fat_ptr_data_at` maintain), so the field's own byte ADDRESS is a
        // `{ data, len }` slot pointer — exactly what the whole-slot arm above
        // passes. Nothing is rebuilt or copied.
        //
        // Each precondition is read off rustc's OWN layout: the projection must
        // be `Field`s only (one static byte offset: no `Index`, `Deref` or
        // `Downcast`) over a memory-backed base; the projected leaf must be a
        // bare slice / `str` fat pointer (never a `repr(transparent)` carrier or
        // a slice-tail DST reference) and EXACTLY the declared type, at an
        // 8-aligned offset; and its metadata lane must sit at offset 8 within a
        // 16-byte field. Anything else keeps the refusal.
        Operand::Copy(place) | Operand::Move(place)
            if !place.projection.is_empty()
                && place
                    .projection
                    .iter()
                    .all(|p| matches!(p, ProjectionElem::Field(..)))
                && local_is_memory_backed(ctx, place.local) =>
        {
            let base_ty = local_rust_ty(ctx, body, place.local);
            let (offset, sub_ty) =
                walk_memory_projection_offset_raw(ctx, base_ty, &place.projection)?;
            let sub_ty = ctx.monomorphize_ty(sub_ty);
            if !is_slice_or_str_fat_ptr_ty(sub_ty) || sub_ty != expected_ty || offset % 8 != 0 {
                return Err(format!(
                    "direct call slice fat-pointer arg {index} projects to `{sub_ty:?}` at \
                     byte offset {offset}, not the declared `{expected_ty:?}` at an \
                     8-byte offset — failing closed"
                ));
            }
            if fat_ptr_metadata_offset(ctx.tcx, sub_ty)? != 8 || layout_size_of(ctx, sub_ty)? != 16
            {
                return Err(format!(
                    "direct call slice fat-pointer arg {index} field {sub_ty:?} is not a \
                     16-byte {{ data @0, len @8 }} pair; refusing to pass its address as a \
                     `{{ data, len }}` slot"
                ));
            }
            let slot = memory_slot_ptr(ctx, place.local)?;
            iter_field_addr(ctx, block, slot, offset)
        }
        // A CONST `&str` / `&[T]` literal argument (`f("hello")`): build a
        // fresh `{ data, len }` slot from the const-alloc data pointer and
        // the const-known length, and pass it.
        Operand::Constant(constant) => {
            let evaluated = ctx.eval_const_operand(constant);
            let mir::Const::Val(ConstValue::Slice { alloc_id, meta }, _) = evaluated else {
                return Err(format!(
                    "direct call slice fat-pointer arg {index} const is not a slice literal"
                ));
            };
            let data = emit_const_alloc_addr(ctx, block, alloc_id, 0, TrustIrTy::Ptr)?;
            let len = emit_i64_const(ctx, block, i128::from(meta));
            let arg_slot = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: fat_ptr_slot_ty(),
                    count: None,
                    align: Some(8),
                })
                .with_result(arg_slot),
            );
            store_fat_ptr_slot_into(ctx, block, arg_slot, data, len);
            arg_slot
        }
        other => {
            // DIAGNOSTIC ONLY (`bridge-notes`): the operand SHAPE that was
            // refused. The default text is byte-identical.
            let note = if bridge_notes_enabled() {
                format!(" [operand: {other:?}]")
            } else {
                String::new()
            };
            return Err(format!(
                "direct call slice fat-pointer arg {index} is not a whole-slice place \
                 or const-slice literal{note}"
            ));
        }
    };
    Ok(slot_ptr)
}

/// Lower call arguments against an explicit list of input types (the callee's
/// signature inputs). Shared by direct calls (callee `Instance`) and indirect
/// calls (callee `fn`-pointer signature). Drops ZST args and expands `&dyn`
/// fat-pointer args to two scalars, matching `func_ty_for_instance`.
///
/// `abi` is how this call reaches rustc's OWN `FnAbi` for the callee, plus the
/// offset between an index into `inputs` and the matching index in
/// `FnAbi::args` (the virtual-call lane lowers the NON-receiver inputs, so its
/// offset is 1). It is what lets the two-value `PassMode::Pair` ARGUMENT lane
/// supply the two values the callee's declaration takes — and it is threaded
/// rather than re-derived precisely so that the call site and the declaration
/// ask the one `scalar_pair_param_plan` the same question. It is REQUIRED, not
/// optional: every caller of this builder names the callee's `FnAbi` source, so
/// no call site can choose an argument lane without rustc's placement to check
/// it against (the declaration side, `classify_func_ty`, takes the same
/// required source).
fn lower_call_args_from_inputs<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    inputs: &[Ty<'tcx>],
    args: &[rustc_span::Spanned<Operand<'tcx>>],
    abi: (RustcFnAbiSource<'tcx>, usize),
) -> Result<(Vec<ValueId>, Vec<MutableReferenceArgReload>), String> {
    let (source, index_offset) = abi;
    if inputs.len() != args.len() {
        return Err(format!(
            "TerminatorKind::Call argument count {} does not match callee input count {}",
            args.len(),
            inputs.len()
        ));
    }

    let mut values = Vec::with_capacity(args.len());
    let mut mutable_reloads = Vec::new();
    for (index, (arg, expected_ty)) in args.iter().zip(inputs.iter().copied()).enumerate() {
        let expected_ty = ctx.monomorphize_ty(expected_ty);
        // A zero-sized argument (`()` and other ZSTs) occupies no ABI slot, so it
        // is not passed. The callee's `func_ty_for_instance` drops the matching
        // parameter, so emitting a value here would desync arg/param counts and
        // try to materialize a non-existent unit value (the `_3 = call()` ->
        // `report(move _3)` chain where `_3: ()`). Skip it.
        if is_zero_sized_call_ty(ctx.tcx, expected_ty) {
            continue;
        }
        // THE INDIRECT ARGUMENT, caller half (`indirect_arg_param_plan`): the
        // callee's declaration takes ONE pointer for this parameter — decided by
        // the same function from the same three facts — so pass the address of a
        // FRESH copy of the argument's bytes in rustc's layout. Checked before
        // every other arm: a whole-slot aggregate and this pointer are both ONE
        // value, so the adapter's arity check could not tell them apart.
        let want_ty = ctx.normalize_ty(expected_ty);
        let indirect = ctx
            .indirect_arg_param_plan(expected_ty, index + index_offset, source)?
            .filter(|plan| plan.ty == want_ty);
        if let Some(plan) = indirect {
            values.push(lower_indirect_call_arg_copy(
                ctx, body, block, index, &arg.node, &plan,
            )?);
            continue;
        }
        // THE PADDED-SCALAR AAPCS64 BLOCK, caller half (the callee's declaration
        // asked the same `aapcs64_scalar_block_param_plan`): the scalar operand
        // is stored into a fresh zero-filled 16-byte copy whose address the
        // backend's adapter reads as the declared two `I64` units.
        if let Some(plan) =
            ctx.aapcs64_scalar_block_param_plan(expected_ty, index + index_offset, source)?
        {
            let value = lower_operand_to_value(ctx, body, block, &arg.node)?;
            values.push(plan.argument(ctx, block, value));
            continue;
        }
        // THE TWO-VALUE `PassMode::Pair` ARGUMENT, caller half. The callee's
        // declaration takes TWO ABI values for this parameter — decided by the
        // SAME `scalar_pair_param_plan`, from the SAME three facts, so the two
        // sides cannot disagree about the arity — and each is rustc's own lane,
        // LOADED out of the argument's slot at rustc's own offset and widened to
        // its carrier (`load_lane_carrier`: the 32-bit `ZExt` an LLVM callee
        // compiled against `zeroext` reads). The bytes are identical to the
        // whole-slot pointer this would otherwise pass; only the registers they
        // ride change, which is the entire point of the lane.
        //
        // It is checked BEFORE the fat-pointer / reference / by-value branches
        // below so that a parameter the callee declares as two values can never
        // leave this loop having pushed one: any shape this lane claims but
        // cannot materialize a slot for is a NAMED refusal, not a silent arity
        // mismatch.
        if unsized_arguments::plan(ctx, expected_ty, index + index_offset, source)? {
            let (data, len) = unsized_arguments::operand(ctx, body, block, &arg.node, expected_ty)?;
            values.extend([data, len]);
            continue;
        }
        // THE wasm32 ARGUMENT THROUGH MEMORY, caller half (`Wasm32IndirectCarrier`):
        // the callee's declaration takes the address of a caller-made copy (the same
        // `wasm32_indirect_carrier_param`), so copy the value — its slot's bytes, or
        // its carrier — into a fresh buffer of rustc's size and alignment and pass
        // the buffer's address. wasm32 only, so it never meets the x86-64 / AArch64
        // `indirect_arg_param_plan` lane above.
        if let Some(plan) =
            ctx.wasm32_indirect_carrier_param(expected_ty, index + index_offset, source)?
        {
            if plan.carrier.is_none() {
                let Some(bytes) = lower_memory_aggregate_byval_call_arg(
                    ctx,
                    body,
                    block,
                    index,
                    &arg.node,
                    expected_ty,
                )?
                else {
                    return Err(format!(
                        "[TCG-WASM32-BYVAL-ABI] by-value argument {index} `{expected_ty:?}` \
                         is passed through memory, but this call site could not \
                         materialize its bytes as an aggregate slot; failing closed"
                    ));
                };
                let layout = plan.slot_layout(ctx.tcx, want_ty)?;
                let buffer = plan.emit_buffer(ctx, block)?;
                copy_aggregate_slot_bytes(ctx, block, &layout, bytes, buffer)?;
                values.push(buffer);
                continue;
            }
            let carrier = lower_operand_to_value(ctx, body, block, &arg.node)?;
            values.push(plan.emit_argument_copy(ctx, block, carrier)?);
            continue;
        }
        let pair_plan = ctx
            .scalar_pair_param_plan(expected_ty, index + index_offset, source)?
            .filter(|plan| plan.ty == want_ty);
        if let Some(plan) = pair_plan {
            // The slice / `str` fat-pointer family (every lane target): its `{ data, len }`
            // pair is resolved exactly as the whole-slot arm below resolves it
            // (a memory-backed local's slot, a field of a memory-backed
            // tupled-args place, a const literal — `slice_fat_ptr_call_arg_slot`,
            // with that arm's refusals), then both lanes are read through the
            // slot's OWN access convention (its `fat_ptr_slot_ty()` lane words,
            // `load_fat_ptr_slot_lane`, the layout every writer of such a slot uses)
            // and passed as rustc's two `Pair` scalars. The carriers must be
            // exactly `Ptr` and one pointer-width length lane (`pointer_lane_ty`:
            // `I64`, or `I32` on wasm32) with no extension — anything else is not
            // this shape and refuses by name rather than pass a re-typed lane.
            // A slice-tail DST reference has the same `{ data, len }` slot.
            if is_slice_fat_ptr_or_carrier(ctx.tcx, expected_ty)
                || is_length_metadata_wide_ptr_ty(ctx.tcx, expected_ty)
            {
                let [carrier0, carrier1] = plan.declared();
                if carrier0 != TrustIrTy::Ptr
                    || carrier1 != pointer_lane_ty()
                    || plan.plan.lane_ext.iter().any(Option::is_some)
                {
                    return Err(format!(
                        "[TCG-ARG-ABI] slice fat-pointer argument {index} `{expected_ty:?}` \
                         rides rustc's `PassMode::Pair`, but its planned carriers are \
                         {carrier0:?} / {carrier1:?}, not the `Ptr` / `I64` pair of a \
                         `{{ data, len }}` slot — failing closed rather than re-typing a lane"
                    ));
                }
                let slot_ptr =
                    slice_fat_ptr_call_arg_slot(ctx, body, block, index, &arg.node, expected_ty)?;
                let data = load_fat_ptr_data_at(ctx, block, slot_ptr)?;
                let len = load_fat_ptr_meta_at(ctx, block, slot_ptr);
                values.push(data);
                values.push(len);
                continue;
            }
            let Some(slot_ptr) = lower_memory_aggregate_byval_call_arg(
                ctx,
                body,
                block,
                index,
                &arg.node,
                expected_ty,
            )?
            else {
                return Err(format!(
                    "[TCG-ARG-ABI] by-value argument {index} `{expected_ty:?}` rides \
                     rustc's TWO `PassMode::Pair` registers, so the callee's declaration \
                     takes two ABI values for it, but this call site could not \
                     materialize the argument's bytes as a by-value aggregate slot to \
                     load those two lanes out of. Failing closed rather than passing one \
                     value where the declaration takes two. Options: (1) bind the value \
                     to a plain local immediately before the call, so it owns a slot; \
                     (2) pass it by reference (`fn f(v: &T)`), which crosses no by-value \
                     argument convention; (3) report this — the lane is \
                     `scalar_pair_param_plan` and this argument shape does not reach \
                     `lower_memory_aggregate_byval_call_arg`."
                ));
            };
            for lane in 0..2 {
                let addr = slot_byte_ptr(ctx, block, slot_ptr, plan.plan.lanes[lane].1);
                values.push(plan.plan.load_lane_carrier(ctx, block, addr, lane));
            }
            continue;
        }
        // THE ONE-INTEGER `small_cast_param_plan` ARGUMENT, caller half (wasm32's
        // one-`i32` `PassMode::Cast`, or a C-ABI one-lane value rustc extends):
        // the callee's declaration takes that integer for this parameter,
        // assembled from the argument's slot. Its scope never meets the native
        // Rust-ABI `narrow_cast_param_plan` below.
        if let Some(plan) = ctx.small_cast_param_plan(expected_ty, index + index_offset, source)? {
            let Some(slot_ptr) = lower_memory_aggregate_byval_call_arg(
                ctx,
                body,
                block,
                index,
                &arg.node,
                expected_ty,
            )?
            else {
                return Err(format!(
                    "[TCG-ARG-ABI] by-value argument {index} `{expected_ty:?}` rides \
                     rustc's wasm32 one-integer `PassMode::Cast`, so the callee's \
                     declaration takes one `i32` for it, but this call site could not \
                     materialize the argument's bytes as a by-value aggregate slot to \
                     assemble that integer from. Failing closed rather than passing the \
                     slot address where the declaration takes its bytes. Options: \
                     (1) bind the value to a plain local immediately before the call; \
                     (2) pass it by reference (`fn f(v: &T)`)."
                ));
            };
            values.push(plan.load_carrier(ctx, block, slot_ptr));
            continue;
        }
        // THE NARROW `Cast` ARGUMENT, caller half (`narrow_cast_param_plan`, the
        // same decision the callee's declaration asked): the argument crosses as
        // ONE integer assembled from width-exact loads of its slot.
        let narrow_plan = ctx
            .narrow_cast_param_plan(expected_ty, index + index_offset, source)?
            .filter(|plan| plan.ty == want_ty);
        if let Some(plan) = narrow_plan {
            let Some(slot_ptr) = lower_memory_aggregate_byval_call_arg(
                ctx,
                body,
                block,
                index,
                &arg.node,
                expected_ty,
            )?
            else {
                return Err(format!(
                    "[TCG-ARG-ABI] by-value argument {index} `{expected_ty:?}` crosses as the \
                     one integer rustc passes for it (`PassMode::Cast`), but this call site \
                     could not materialize its bytes as a slot to assemble that integer from. \
                     Failing closed rather than passing the slot where the declaration takes \
                     the integer. Options: (1) bind the value to a plain local immediately \
                     before the call; (2) pass it by reference (`&T`)."
                ));
            };
            values.push(plan.load_carrier(ctx, block, slot_ptr));
            continue;
        }
        // A `&dyn Trait` fat-pointer argument is passed as TWO pointer-width
        // scalars (data, vtable), matching the two-word parameter expansion in
        // `func_ty_for_instance`. `_5 = closure as &dyn Fn` is bound as a
        // 2-field projected aggregate (field 0 = data ptr, field 1 = vtable
        // ptr); pass both fields in order.
        // The same two halves for a pointer to a `dyn`-tailed struct, which the
        // callee declares as two `Ptr` parameters (`dyn_tail`); only a whole local
        // carrying both halves is admitted, as for `&dyn Trait`.
        if is_vtable_pair_abi_ref_ty(ctx.tcx, expected_ty) {
            let (Operand::Copy(place) | Operand::Move(place)) = &arg.node else {
                return Err(format!(
                    "direct call trait-object fat-pointer arg {index} is not a place operand"
                ));
            };
            if !place.projection.is_empty() {
                return Err(format!(
                    "direct call trait-object fat-pointer arg {index} uses projected operand"
                ));
            }
            let (data, vtable) =
                dyn_fat_ptr_halves_of_local(ctx, block, place.local).ok_or_else(|| {
                    format!("trait-object call argument {index} has no two-lane binding")
                })?;
            values.push(data);
            values.push(vtable);
            continue;
        }
        // A `&[T]` / `&str` slice fat-pointer argument the `PassMode::Pair` lane
        // above did not claim (a non-x86-64 target, a C-ABI callee, a declined
        // plan): pass the ADDRESS of the argument slice's `{ data, len }` slot.
        // The callee declares this parameter as the `{ Ptr, I64 }` lane tuple (`func_ty_for_instance`), so
        // the backend's adapter seeds that aggregate type onto the argument Value
        // and the verified SysV eightbyte classifier places data+len in a
        // register pair — exactly matching the callee-side fat-pointer parameter
        // ABI. The slice arg local is memory-backed (see
        // `compute_memory_backed_locals` 3b), so its slot pointer is the value.
        if is_slice_fat_ptr_or_carrier(ctx.tcx, expected_ty)
            || is_length_metadata_wide_ptr_ty(ctx.tcx, expected_ty)
        {
            // THE CALLER HALF of the transparent wide-slice newtype lane: once the
            // callee declares the 16-byte slot for `as_ptr(self: NonNull<[T]>)` /
            // `cast`, this is the only arm that passes a pointer to 16 bytes the
            // adapter re-types as the aggregate. A newtype operand must never fall
            // through to the by-value / scalar branches below: a DATA pointer
            // passed where the adapter expects a slot address is a silent wrong
            // length. A reference to a slice-tail DST (`is_length_metadata_wide_ptr_ty`)
            // is the same `{ data, len }` image and takes the same arm.
            // The slice's `{ data, len }` slot pointer is the argument; the
            // module's edge legalization (`abi_edges`, WS7.3-pre) loads the
            // declared `{ I64, I64 }` aggregate from it at the call, so the verified
            // SysV eightbyte classifier loads data+len into the register pair (or
            // RAX:RDX on return). The slot's own field reads and writes go through
            // `slot_byte_ptr`'s normalized plain-`Ptr` address, never a raw
            // `Store`/`Load` through the slot pointer itself, so the aggregate type
            // the ABI seeds onto the slot pointer does not conflict with them —
            // exactly the convention the
            // existing by-value aggregate call-arg path relies on.
            let slot_ptr =
                slice_fat_ptr_call_arg_slot(ctx, body, block, index, &arg.node, expected_ty)?;
            values.push(slot_ptr);
            continue;
        }
        call_references::check_stable_address(ctx, &arg.node, expected_ty, index)?;
        if let Some(prepared) =
            lower_aggregate_reference_call_arg(ctx, body, block, index, &arg.node, expected_ty)?
        {
            values.push(prepared.value);
            mutable_reloads.extend(prepared.mutable_reloads);
            continue;
        }
        if let Some(prepared) =
            lower_scalar_reference_call_arg(ctx, body, block, index, &arg.node, expected_ty)?
        {
            values.push(prepared.value);
            mutable_reloads.extend(prepared.mutable_reloads);
            continue;
        }
        // A by-value memory-aggregate argument: pass the ADDRESS of the
        // aggregate's bytes (its stack slot). The callee's declared parameter
        // type IS the flat integer-lane tuple `slot_ty` (see
        // `func_ty_for_instance`), so the backend's adapter seeds that aggregate
        // type onto the argument Value from the callee signature and ISel applies
        // the verified System V eightbyte register-pair / sret / stack placement
        // — exactly matching the callee-side by-value parameter ABI. (Reference
        // passing and by-value PARAMETERS were already supported; this closes the
        // by-value ARGUMENT side.)
        if let Some(prepared) =
            lower_memory_aggregate_byval_call_arg(ctx, body, block, index, &arg.node, expected_ty)?
        {
            values.push(prepared);
            continue;
        }

        if let Some(value) = scalarized_projected_call_arg(ctx, body, &arg.node, expected_ty)? {
            values.push(value);
            continue;
        }
        values.push(lower_operand_to_value(ctx, body, block, &arg.node)?);
    }

    Ok((values, mutable_reloads))
}

/// A scalar sibling of a projected aggregate uses the enclosing tuple's flat
/// leaf index, not its MIR field number. Match the construction's DFS leaf list
/// to rustc byte offsets before selecting a binding (for example, the bool in
/// `(Layout, bool)` is leaf 2, although it is MIR field 1).
fn scalarized_projected_call_arg<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
    expected_ty: Ty<'tcx>,
) -> Result<Option<ValueId>, String> {
    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        return Ok(None);
    };
    if place.projection.is_empty()
        || !place
            .projection
            .iter()
            .all(|p| matches!(p, ProjectionElem::Field(..)))
        || local_is_memory_backed(ctx, place.local)
        || ctx.scalar_cells.contains_key(&place.local)
    {
        return Ok(None);
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    let Some(flat) = scalar_field_aggregate_trust_ir_fields(ctx.tcx, base_ty)? else {
        return Ok(None);
    };
    let cx = LayoutCx(ctx.tcx);
    let base = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("projected scalar call source layout_of failed: {e:?}"))?;
    if !matches!(base.layout.variants(), rustc_abi::Variants::Single { .. }) {
        return Ok(None);
    }
    let variant = base.for_variant(&cx, rustc_abi::FIRST_VARIANT);
    let recursive = (0..variant.fields.count()).any(|i| {
        scalar_field_aggregate_trust_ir_fields(ctx.tcx, variant.field(&cx, i).ty)
            .map(|shape| shape.is_some())
            .unwrap_or(false)
    });
    if !recursive {
        return Ok(None);
    }
    let (offset, actual_ty) = walk_memory_projection_offset_raw(ctx, base_ty, &place.projection)?;
    if ctx.monomorphize_ty(actual_ty) != expected_ty {
        return Err("projected scalar call argument type disagrees with its callee".into());
    }
    let lane_ty = memory_scalar_leaf_ty(ctx.tcx, actual_ty)?;
    let mut leaves = Vec::new();
    if enumerate_scalar_leaf_offsets(ctx.tcx, &cx, &base, 0, &mut leaves)?.is_none()
        || leaves.len() != flat.len()
        || leaves
            .iter()
            .zip(&flat)
            .any(|((_, lane), field)| lane != field)
    {
        return Err("projected scalar call source layout disagrees with its flat bindings".into());
    }
    let field = leaves
        .iter()
        .position(|(at, lane)| *at == offset && *lane == lane_ty)
        .ok_or_else(|| "projected scalar call argument has no matching leaf".to_owned())?;
    let field =
        u32::try_from(field).map_err(|_| "projected scalar call field exceeds u32".to_owned())?;
    value_for_scalar_binding(
        ctx,
        ScalarPlaceBinding::Projection {
            local: place.local,
            field,
        },
    )
    .map(Some)
}

/// Whether a Rust type is zero-sized for ABI purposes (`()` / `Never` / a
/// field-less struct, an all-ZST closure env), so it occupies no argument or
/// parameter slot. Zero-sized is decided on the trust-ir type by
/// `trust_ir_ty_is_zero_sized` — the same predicate the param-dropping in
/// `func_ty_for_instance` uses — so an argument is skipped exactly when the
/// callee's signature has no slot for it.
fn is_zero_sized_call_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    matches!(
        rust_ty_to_trust_ir_ty(tcx, ty),
        Ok(ty) if trust_ir_ty_is_zero_sized(&ty)
    )
}

fn lower_aggregate_reference_call_arg<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    index: usize,
    operand: &Operand<'tcx>,
    expected_ty: Ty<'tcx>,
) -> Result<Option<PreparedCallArg>, String> {
    let expected_ty = ctx.monomorphize_ty(expected_ty);
    let ty::Ref(_, inner, expected_mutability) = expected_ty.kind() else {
        return Ok(None);
    };
    let inner = ctx.monomorphize_ty(*inner);
    // A `&E` / `&mut E` to a MULTI-VARIANT memory-eligible enum, OR a `&S` / `&mut S`
    // to a NESTED-AGGREGATE struct whose scalar-field flattening FAILS (a field is
    // itself a multi-field aggregate — e.g. `&mut Rev<Range<i32>>`, whose single
    // field is the multi-field `Range`): BOTH are THIN pointers (the slot address),
    // not a scalarized field bundle. The borrowing `_r = &local` (case 8853) /
    // `_r = &mut memory_local` bound `_r`'s scalar value to the slot pointer, so the
    // argument is just that pointer value — pass it directly. The callee decodes the
    // tag / payload / fields through the pointer at rustc offsets
    // (`lower_reference_deref_discriminant` / `memory_aggregate_ref_address`) —
    // exactly what `func_ty_for_instance` declares: `reference_pointee_to_trust_ir_ty`
    // maps such a pointee to the lane-tuple thin pointer on its `Err` -> lane-tuple
    // fallback, so the declared param IS this thin pointer. This is what lets the real
    // libcore `<Rev<Range<i32>> as Iterator>::next(&mut self)` be CALLED (its `self`
    // is a `&mut Rev<Range>`, a nested-aggregate thin pointer). Mutability is checked
    // through the borrow.
    //
    // The struct arm fires ONLY on the `Err` (genuine nested aggregate) case — NOT the
    // `Ok(None)` intercepted-collection (`Vec`/`String`/`BTreeMap`/`HashMap`) pointees,
    // whose `reference_pointee_to_trust_ir_ty` is a bare `Ptr` (not a lane tuple) and
    // which keep their existing pointer-passing path below.
    let nested_aggregate_thin_ref = aggregate_reference_pointee_to_trust_ir_ty(ctx.tcx, inner)
        .is_err()
        && memory_aggregate_reference_pointee_lane_ty(ctx.tcx, inner)?.is_some();
    // A `&U` / `&mut U` to a memory-backed UNION (`&mut MaybeUninit<T>` — the
    // receiver of `MaybeUninit::as_mut_ptr` / the `&raw const self` inside
    // `assume_init`): exactly like the memory enum / nested-aggregate case, the
    // reference value is just the union slot's pointer. The borrow `_r = &mut
    // memory_union` bound `_r`'s scalar to that slot pointer (Rvalue::Ref of a
    // memory-backed local), and `func_ty_for_instance` declares the param as a thin
    // `Ref`/`RefMut` (`reference_pointee_to_trust_ir_ty` maps the union to its scalar
    // ABI carrier), so pass the bound pointer directly. A NON-scalar union pointee
    // makes the callee's own signature fail closed (`reference_pointee_to_trust_ir_ty`
    // errors), so this never reaches a wrongly-shaped call.
    let memory_union_thin_ref = matches!(inner.kind(), ty::Adt(adt, _) if adt.is_union())
        && union_memory_layout(ctx.tcx, inner)?.is_some();
    if memory_enum_reference_pointee_lane_ty(ctx.tcx, inner)?.is_some()
        || nested_aggregate_thin_ref
        || memory_union_thin_ref
    {
        // A const-pointer enum/union reference arg (O1 promotes `&E::A(7)` to a
        // `const &E`): immutable, no writeback. The const-eval allocation holds the
        // enum's tag+payload bytes at their layout offsets, so its ADDRESS is a
        // valid `&E` the callee matches through. Emit it directly.
        if matches!(expected_mutability, rustc_hir::Mutability::Not) {
            if let Operand::Constant(constant) = operand {
                let evaluated = ctx.eval_const_operand(constant);
                if let Some((alloc_id, offset)) = const_pointer_target(ctx, &evaluated)? {
                    let addr = emit_const_alloc_addr(ctx, block, alloc_id, offset, TrustIrTy::Ptr)?;
                    return Ok(Some(PreparedCallArg {
                        value: addr,
                        mutable_reloads: Vec::new(),
                    }));
                }
            }
        }
        let (Operand::Copy(place) | Operand::Move(place)) = operand else {
            return Err(format!(
                "direct call enum reference arg {index} is not a place operand"
            ));
        };
        if !place.projection.is_empty() {
            return Err(format!(
                "direct call enum reference arg {index} uses projected reference operand"
            ));
        }
        if matches!(expected_mutability, rustc_hir::Mutability::Mut) {
            if let Some(binding) = ctx.borrowed_scalars.get(&place.local).copied() {
                if !binding.mutable {
                    return Err(format!(
                        "direct call mutable enum reference arg {index} from shared borrow"
                    ));
                }
            }
        }
        if !ctx.scalar_values.contains_key(&place.local)
            && !ctx.scalar_cells.contains_key(&place.local)
            && !is_entry_arg(body, place.local)
        {
            return Err(format!(
                "direct call enum reference arg {index} before reference pointer binding"
            ));
        }
        let value = value_for_runtime_scalar_local(ctx, block, place.local)?;
        return Ok(Some(PreparedCallArg {
            value,
            mutable_reloads: Vec::new(),
        }));
    }
    let Some(pointee_ty) = aggregate_reference_pointee_to_trust_ir_ty(ctx.tcx, inner)? else {
        return Ok(None);
    };
    // A zero-sized leaf (the `Unit` upvar slot of a captured non-capturing
    // closure — `apply(h: H, v) { h(v) }` passing `&h` where every upvar of `H`
    // is a ZST) has no scalar value bound and no bytes to store or reload: the
    // materialized slot keeps its rustc field INDICES (the callee reads
    // `(*env).N` by index) but only the sized leaves are written. The same
    // predicate that drops a ZST from every ABI slot (`trust_ir_ty_is_zero_sized`)
    // decides it here.
    let fields: Vec<(u32, TrustIrTy)> = aggregate_memory_field_tys(&pointee_ty)?
        .into_iter()
        .filter(|(_, field_ty)| !trust_ir_ty_is_zero_sized(field_ty))
        .collect();

    // A CONST-pointer aggregate reference arg — e.g. `f(&P { .. })` where O1
    // promotes the `&P{..}` to a `const &P` (O0/O2/O3 pass a place). It is an
    // IMMUTABLE `&T` (no writeback); the evaluated const points into a const-eval
    // allocation holding the struct's bytes at their layout offsets, so its
    // ADDRESS is a valid `&T` the callee reads fields through. Emit it directly.
    if matches!(expected_mutability, rustc_hir::Mutability::Not) {
        if let Operand::Constant(constant) = operand {
            let evaluated = ctx.eval_const_operand(constant);
            if let Some((alloc_id, offset)) = const_pointer_target(ctx, &evaluated)? {
                let addr = emit_const_alloc_addr(ctx, block, alloc_id, offset, TrustIrTy::Ptr)?;
                return Ok(Some(PreparedCallArg {
                    value: addr,
                    mutable_reloads: Vec::new(),
                }));
            }
        }
    }

    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        return Err(format!(
            "direct call aggregate reference arg {index} is not a place operand"
        ));
    };
    if !place.projection.is_empty() {
        return Err(format!(
            "direct call aggregate reference arg {index} uses projected reference operand"
        ));
    }

    let Some(binding) = ctx.borrowed_aggregates.get(&place.local).copied() else {
        if is_entry_arg(body, place.local)
            || ctx.scalar_values.contains_key(&place.local)
            || ctx.scalar_cells.contains_key(&place.local)
        {
            let value = lower_operand_to_value(ctx, body, block, operand)?;
            return Ok(Some(PreparedCallArg {
                value,
                mutable_reloads: Vec::new(),
            }));
        }
        return Err(format!(
            "direct call aggregate reference arg {index} before aggregate borrow binding"
        ));
    };
    if matches!(expected_mutability, rustc_hir::Mutability::Mut) && !binding.mutable {
        return Err(format!(
            "direct call mutable aggregate reference arg {index} from shared borrow"
        ));
    }
    // A SHARED borrow of a scalarized aggregate with INTERIOR MUTABILITY: the
    // materialized temp below is never reloaded for a shared reference, so a
    // `Cell::set` / `RefCell::borrow_mut` write the callee performs through it is
    // lost. `compute_memory_backed_locals` (4i) gives such a local a real slot
    // whenever the memory model can lay it out; reaching here means it could not.
    // Refuse rather than snapshot (`ty.is_freeze()` is rustc's own predicate).
    if matches!(expected_mutability, rustc_hir::Mutability::Not)
        && !inner.is_freeze(ctx.tcx, ty::TypingEnv::fully_monomorphized())
    {
        return Err(format!(
            "[TCG-INTERIOR-MUT-SNAPSHOT] direct call shared aggregate reference arg {index} \
             borrows a scalarized `{inner:?}`, which has interior mutability (`!Freeze`): a \
             materialized snapshot would drop every write the callee makes through it. \
             Options: (1) make the referent's layout memory-eligible so it gets a real slot, \
             (2) pass `&mut` (reloaded after the call), (3) keep the caller on the LLVM backend"
        ));
    }

    let source_ty = local_rust_ty(ctx, body, binding.source);
    let Some(source_pointee_ty) = aggregate_reference_pointee_to_trust_ir_ty(ctx.tcx, source_ty)?
    else {
        return Err(format!(
            "direct call aggregate reference arg {index} source is not an aggregate: {source_ty:?}"
        ));
    };
    if source_pointee_ty != pointee_ty {
        return Err(format!(
            "direct call aggregate reference arg {index} type mismatch: source \
             {source_pointee_ty:?}, callee pointee {pointee_ty:?}"
        ));
    }
    // The temp below is laid out as the declaration-order tuple image; the callee
    // reads (and a raw-pointer cast or a whole-object copy observes) rustc's
    // layout. A pointee whose image diverges is memory-backed by
    // `compute_memory_backed_locals` (4b) when the memory model can lay it out;
    // reaching here means it could not.
    if pointee_tuple_image_diverges_from_rustc_layout(ctx.tcx, inner) {
        return Err(tuple_image_layout_refusal(
            &format!("direct call aggregate reference arg {index} materializes"),
            inner,
        ));
    }

    // The aggregate's borrow home: one slot for every materialization of this
    // local, refreshed with its current leaves before each call.
    let ptr = borrow_home_slot(
        ctx,
        BorrowHomeKey::Aggregate(binding.source),
        pointee_ty.clone(),
        None,
        None,
    )?;
    for (field, _) in &fields {
        let value = value_for_scalar_binding(
            ctx,
            ScalarPlaceBinding::Projection {
                local: binding.source,
                field: *field,
            },
        )?;
        emit_aggregate_field_store(ctx, block, pointee_ty.clone(), ptr, *field, value)?;
    }

    let mutable_reloads = matches!(expected_mutability, rustc_hir::Mutability::Mut)
        .then(|| {
            vec![MutableReferenceArgReload::Aggregate {
                ptr,
                ty: pointee_ty,
                source: binding.source,
                fields,
            }]
        })
        .unwrap_or_default();

    Ok(Some(PreparedCallArg {
        value: ptr,
        mutable_reloads,
    }))
}

/// Lower a BY-VALUE memory-aggregate call argument (a constructed struct / tuple
/// / Direct-tagged enum passed by value). Returns `Some(addr)` — the ADDRESS of
/// the aggregate's bytes — when `expected_ty` is a memory aggregate, else `None`
/// (so a scalar / interception argument keeps its existing path).
///
/// The callee declares this parameter as the flat integer-lane tuple `slot_ty`
/// (`func_ty_for_instance`); the backend's adapter seeds that aggregate type onto
/// the argument Value from the callee signature, and the verified System V
/// eightbyte classifier places it in a register pair (<=16 B), via sret (>16 B
/// returns), or on the stack (>16 B MEMORY-class args) — identical to the
/// already-supported callee-side by-value parameter ABI. We never mutate the
/// source: by-value passing READS the bytes into the ABI registers/stack, so for
/// both `Copy` and `Move` the source slot's pointer is the argument.
///
/// Supported sources (each produces a pointer to the contiguous `slot_ty` bytes):
///   * a memory-backed aggregate local (the slot pointer) — the address-taken /
///     mutated-through-`&mut` case.
///   * a SCALARIZED aggregate local: its leaf fields are held as separate SSA
///     values (the common `let s = S { .. }; f(s);` case, where `s` is never
///     address-taken). We materialize a fresh stack slot and store each scalar
///     leaf into it, then pass the slot pointer — mirroring the by-reference
///     materialization in `lower_aggregate_reference_call_arg`.
///   * a fixed field projection into either representation: assemble scalarized
///     source bytes when needed, then copy the field at its rustc layout offset.
/// Anything else fails closed (a precise diagnostic), so an un-modeled shape
/// aborts rather than miscompiles.
fn lower_memory_aggregate_byval_call_arg<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    index: usize,
    operand: &Operand<'tcx>,
    expected_ty: Ty<'tcx>,
) -> Result<Option<ValueId>, String> {
    let expected_ty = ctx.monomorphize_ty(expected_ty);
    // Only by-value aggregate parameters route here; references were handled by
    // `lower_aggregate_reference_call_arg` before this is reached.
    if matches!(expected_ty.kind(), ty::Ref(..) | ty::RawPtr(..)) {
        return Ok(None);
    }
    // A capturing closure passed by value (into a generic `fn apply<F: Fn(..)>`)
    // crosses the boundary as its env aggregate (its slot pointer addresses the
    // contiguous lane bytes the callee ABI expects), so it routes here too. An
    // AGGREGATE union (`MaybeUninit<(i64,i64)>` passed by value into `assume_init`)
    // also routes here: its slot lane tuple IS the by-value ABI value.
    if memory_aggregate_layout_shared(ctx.tcx, expected_ty)?.is_none()
        && closure_memory_layout(ctx.tcx, expected_ty)?.is_none()
        && nonscalar_union_memory_layout(ctx.tcx, expected_ty)?.is_none()
    {
        return Ok(None);
    }

    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        // A by-value CONSTANT aggregate argument (`f(const Range { start, end })`):
        // the inlined iterator-adapter chains rustc emits at `-O` const-fold the
        // initial `Range`/tuple/struct seed into a bare aggregate constant that is
        // passed straight into the first adapter call (`Range::zip(const Range {..},
        // const Range {..})`, `<Range as Iterator>::fold(move _2, ..)`). The const's
        // in-memory image is a fixed byte allocation, so materialize a fresh slot
        // from those bytes and hand the call the same fresh-aggregate pointer every
        // other by-value aggregate arg uses. Build it in TWO allocas to keep types
        // clean: a scratch slot receives the const bytes via plain byte `Store`s
        // (its pointer is only ever a raw byte address), then a fresh aggregate
        // alloca whose pointer carries the aggregate `slot_ty` cleanly (never itself
        // a `Store` address) is filled lane-by-lane from the scratch slot. Sound
        // because the bytes written are exactly the const's allocation image and the
        // provenance / shape are re-checked by the byte-copy helper (a const carrying
        // a pointer relocation, or one that is not an in-memory allocation, makes the
        // helper return `false` and we fail closed rather than drop a relocation).
        if let Operand::Constant(_) = operand {
            let layout = if matches!(expected_ty.kind(), ty::Closure(..)) {
                closure_memory_layout(ctx.tcx, expected_ty)?
            } else {
                memory_aggregate_layout(ctx.tcx, expected_ty)?
            };
            let Some(layout) = layout else {
                return Err(format!(
                    "by-value aggregate call argument {index} const has no aggregate layout"
                ));
            };
            // Scratch slot: receives the const's allocation bytes. Its pointer is
            // only ever a plain byte `Store` address, so it carries a flat `Ptr`.
            let scratch = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: layout.slot_ty.clone(),
                    count: None,
                    align: Some(layout.align),
                })
                .with_result(scratch),
            );
            // A Direct-tagged enum const (the ubiquitous case: `Ordering::Relaxed`
            // passed by value into libstd's `atomic_load::<T>(ptr, order)` /
            // `atomic_store` wrapper when the atomic method inlines at -O2/-O3, and
            // any other by-value fieldless-enum arg like `f(E::B)`) writes the exact
            // in-memory image — the discriminant tag word for a fieldless variant, or
            // the tag+payload allocation image for a payload variant. This is
            // byte-for-byte what rustc's own backend stores, so a subsequent `match`
            // / `discriminant` read (at the SAME layout) reads back the intended
            // value. `store_whole_const_enum_image_into_slot` fails closed (returns
            // `Ok(false)`) for any const it cannot copy soundly (pointer provenance,
            // float payload, or a const that is neither an in-memory allocation nor a
            // whole-value scalar) — those fall through to the fail-closed Err below,
            // never dropping a relocation. A TAGLESS aggregate (struct / tuple /
            // single-variant enum) has no tag and takes the plain byte-copy path.
            let stored = if layout.tag.is_some() {
                store_whole_const_enum_image_into_slot(
                    ctx,
                    block,
                    scratch,
                    expected_ty,
                    layout.size,
                    operand,
                )?
            } else {
                store_const_aggregate_bytes_into_memory_at(
                    ctx,
                    block,
                    scratch,
                    0,
                    expected_ty,
                    operand,
                )?
            };
            if !stored {
                return Err(format!(
                    "by-value aggregate call argument {index} const is not an in-memory \
                     allocation (or carries a pointer relocation / tagged-enum image \
                     the byte copy cannot reproduce soundly)"
                ));
            }
            // Fresh aggregate: filled lane-by-lane from the scratch slot; its pointer
            // carries the aggregate `slot_ty` cleanly for the by-value ABI adapter.
            let fields = aggregate_memory_field_tys(&layout.slot_ty)?;
            let (_lane_ty, lane_size) = memory_aggregate_lane(layout.align)?;
            let agg = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: layout.slot_ty.clone(),
                    count: None,
                    align: Some(layout.align),
                })
                .with_result(agg),
            );
            for (field, field_ty) in &fields {
                let lane_addr = slot_byte_ptr(ctx, block, scratch, u64::from(*field) * lane_size);
                let value = emit_typed_load(ctx, block, lane_addr, field_ty.clone());
                emit_aggregate_field_store(ctx, block, layout.slot_ty.clone(), agg, *field, value)?;
            }
            // A fresh `Alloca` holding the const's byte image (rustc's layout).
            ctx.fresh_arg_copies.insert(agg);
            return Ok(Some(agg));
        }
        return Err(format!(
            "by-value aggregate call argument {index} is not a place operand"
        ));
    };
    // A by-value aggregate read through a DEREF (`move (*_p)` where `_p` is a
    // pointer/reference to the aggregate): the aggregate's bytes live AT the
    // address `_p` holds. This is exactly the shape of the `FnOnce::call_once`
    // vtable shim `lang_start` dispatches through (`_0 = call_once(move (*_1), ..)`,
    // `_1: *mut Closure`), so handling it is what lets a std `fn main` run rather
    // than trap. Materialize a FRESH aggregate (load each lane from `*_p`,
    // store it into a fresh alloca whose pointer carries the aggregate type
    // cleanly) and pass it — the same shape every other by-value aggregate arg
    // uses. The base pointer is read as a scalar value; lanes are loaded from it.
    if let [ProjectionElem::Deref] = place.projection.as_ref() {
        let layout = if matches!(expected_ty.kind(), ty::Closure(..)) {
            closure_memory_layout(ctx.tcx, expected_ty)?
        } else {
            memory_aggregate_layout(ctx.tcx, expected_ty)?
        };
        let Some(layout) = layout else {
            return Err(format!(
                "by-value aggregate call argument {index} deref has no aggregate layout"
            ));
        };
        let base_ptr = value_for_scalar_binding(ctx, ScalarPlaceBinding::Local(place.local))?;
        let fields = aggregate_memory_field_tys(&layout.slot_ty)?;
        let (_, lane_size) = memory_aggregate_lane(layout.align)?;
        let agg = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: layout.slot_ty.clone(),
                count: None,
                align: Some(layout.align),
            })
            .with_result(agg),
        );
        // The slot is contiguous `memory_aggregate_lane`-wide lanes, so lane
        // `field` is at byte offset `field * lane_size` from the base pointer.
        for (field, field_ty) in &fields {
            let lane_addr = iter_field_addr(ctx, block, base_ptr, u64::from(*field) * lane_size);
            let value = emit_typed_load(ctx, block, lane_addr, field_ty.clone());
            emit_aggregate_field_store(ctx, block, layout.slot_ty.clone(), agg, *field, value)?;
        }
        // A fresh `Alloca` holding the pointee's bytes (rustc's layout).
        ctx.fresh_arg_copies.insert(agg);
        return Ok(Some(agg));
    }
    // A by-value aggregate read out of a PROJECTED SUB-PLACE of a MEMORY-BACKED
    // local: `move (_4.0: Layout)`, where `_4` is the argument tuple
    // `const_eval_select` takes. That is the shape of every
    // `Global::{alloc,grow,shrink,deallocate}_impl` and of `handle_alloc_error`
    // (`const_eval_select((layout, zeroed), ct, rt)` lowers at runtime to
    // `rt(move (_4.0: Layout), move (_4.1: bool))`).
    //
    // Nothing new is modelled here. The sub-aggregate's bytes are ALREADY in the
    // base local's slot at the projection's rustc layout offset — that is what
    // `lower_memory_aggregate_construct` wrote (`store_operand_into_memory_at`
    // recurses field-by-field at `variant_layout.fields.offset`) and what every
    // other projected read of a memory slot addresses, through the SAME walker
    // asked here. So the lane loader below is the whole-local loader further down
    // this function with the sub-place's offset added: load `layout.size / lane`
    // lanes and store them (`emit_aggregate_field_store`: field address + `Store`)
    // into a fresh alloca carrying `slot_ty`, which is exactly the by-value ABI
    // value the callee declares
    // (`fat_ptr_or_memory_aggregate_layout`).
    //
    // Every precondition DECLINES to the refusal below rather than guessing:
    //   * the base local must own a memory slot (no slot, no bytes to read);
    //   * the projection must fold to a CONSTANT byte offset — a runtime
    //     array/slice index does not (`projection_has_index_element`), and the
    //     walker itself refuses a non-leading `Deref` / `OpaqueCast`;
    //   * the sub-place's own type must BE the parameter type, so the bytes read
    //     are the argument's and not a prefix of something larger;
    //   * the sub-place must lie wholly inside the base type's layout, and at an
    //     offset the lane width can address aligned.
    // Why the widening declined, when it did — so the refusal below names the
    // precondition that failed instead of only the shape (design principle 10).
    let mut projected_decline = String::new();
    let projected_sub_place = if place.projection.is_empty() {
        false
    } else if projection_has_index_element(place.projection.as_ref()) {
        projected_decline =
            "the projection contains a runtime array/slice index, which folds to no \
             constant byte offset"
                .to_owned();
        false
    } else {
        true
    };
    // THE SCALARIZED HALF. The base local holds no slot at all: its scalar leaves are
    // SSA values bound in `projected_values`. This is the shape the measured roots
    // actually have — `const_eval_select`'s argument tuple is scalarized, not
    // memory-backed — and the sub-place is the CONTIGUOUS RUN of those leaves whose
    // rustc byte offsets fall inside the sub-place's extent.
    //
    // The run is not assumed to be the right one: it is checked leaf for leaf against
    // `enumerate_scalar_leaf_offsets` of the PARAMETER's own type — same offsets
    // (re-based to the sub-place's start), same leaf types, same count — before a
    // single value is packed. So a projection that lands mid-leaf, a padding
    // mismatch, or a leaf the base binds differently from the parameter's own
    // flattening all decline instead of packing the wrong bytes.
    if projected_sub_place && !ctx.memory_slots.contains_key(&place.local) {
        let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
        let folded = walk_memory_projection_offset_raw(ctx, base_ty, place.projection.as_ref());
        let sub_layout = memory_aggregate_layout_shared(ctx.tcx, expected_ty)?;
        match (&folded, &sub_layout) {
            (Err(why), _) => {
                projected_decline = format!(
                    "the base local is scalarized and the projection does not fold to a \
                     constant byte offset ({why})"
                );
            }
            (_, None) => {
                projected_decline = format!(
                    "the base local is scalarized and the parameter type \
                     `{expected_ty:?}` has no memory-aggregate slot layout"
                );
            }
            _ => {}
        }
        if let (Ok((offset, projected_ty)), Some(sub_layout)) = (folded, sub_layout) {
            let projected_ty = ctx.monomorphize_ty(projected_ty);
            if projected_ty != expected_ty {
                projected_decline = format!(
                    "the base local is scalarized and the sub-place's own type is \
                     `{projected_ty:?}`, not the parameter type `{expected_ty:?}`"
                );
            } else {
                // What the PARAMETER's own flattening says its leaves are, at offsets
                // relative to its own start. This is the reference the selected run
                // must equal.
                let cx = LayoutCx(ctx.tcx);
                let mut want: Vec<(u64, TrustIrTy)> = Vec::new();
                let want_ok = match ctx
                    .tcx
                    .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(expected_ty))
                {
                    Ok(sub) => {
                        enumerate_scalar_leaf_offsets(ctx.tcx, &cx, &sub, 0, &mut want)?.is_some()
                    }
                    Err(_) => false,
                };
                // THE PRECONDITION THIS LANE CANNOT SKIP — see
                // `scalarized_field_indices_are_flat_identity`. Admitting a sub-place
                // of a local whose MIR-field and FLAT-leaf indexings disagree lets a
                // SIBLING scalar argument of the same call read the wrong leaf, which
                // is a measured silent wrong value, not a refusal.
                let sibling_reads_are_sound =
                    scalarized_field_reads_name_their_own_leaf(ctx.tcx, base_ty)?;
                if !sibling_reads_are_sound {
                    projected_decline = format!(
                        "the base local is scalarized and a SIBLING scalar argument of this \
                         call would read the wrong leaf of `{base_ty:?}`: its projected \
                         bindings are keyed neither at MIR field indices that coincide with \
                         its flat leaf indices, nor by the recursive flat binder that \
                         `projected_field_index` maps through. Admitting the sub-place here \
                         would turn that fail-closed into a silent wrong value. Options: \
                         (1) memory-back the base local, so every access goes through the \
                         byte-offset walker; (2) extend the MIR-field-to-leaf mapping in \
                         `flat_leaf_field_for_mir_field` to this local's binding scheme — \
                         the ARRAY schemes (`lower_array_aggregate_operand_values`, whose \
                         multi-leaf element stride is not yet mapped) are the ones left"
                    );
                }
                let base_leaves = if sibling_reads_are_sound {
                    scalarized_aggregate_leaf_values(ctx, place.local, base_ty)?
                } else {
                    None
                };
                if sibling_reads_are_sound {
                    match (want_ok, base_leaves) {
                        (true, Some(base_leaves)) => {
                            let end = offset.saturating_add(sub_layout.size);
                            let selected: Vec<(u64, TrustIrTy, ValueId)> = base_leaves
                                .into_iter()
                                .filter(|(leaf_offset, _, _)| {
                                    *leaf_offset >= offset && *leaf_offset < end
                                })
                                .map(|(leaf_offset, leaf_ty, value)| {
                                    (leaf_offset - offset, leaf_ty, value)
                                })
                                .collect();
                            let agrees = selected.len() == want.len()
                                && selected.iter().zip(want.iter()).all(
                                    |((got_offset, got_ty, _), (want_offset, want_ty))| {
                                        got_offset == want_offset && got_ty == want_ty
                                    },
                                );
                            if agrees {
                                // A sub-place is a field range: it never holds the
                                // base's tag word, so no tag is written.
                                let agg = pack_leaf_values_into_byval_slot(
                                    ctx,
                                    block,
                                    &selected,
                                    &sub_layout,
                                    None,
                                )?;
                                // A fresh `Alloca`, every leaf at its rustc byte offset.
                                ctx.fresh_arg_copies.insert(agg);
                                return Ok(Some(agg));
                            }
                            projected_decline = format!(
                                "the base local is scalarized and the {} leaf value(s) its \
                             flattening puts inside the sub-place do not match the {} leaf \
                             (offset, type) pair(s) `{expected_ty:?}`'s own flattening \
                             expects",
                                selected.len(),
                                want.len()
                            );
                        }
                        (false, _) => {
                            projected_decline = format!(
                                "the base local is scalarized and the parameter type \
                             `{expected_ty:?}` has no scalar-leaf flattening to pack into"
                            );
                        }
                        (_, None) => {
                            projected_decline =
                                "the base local is scalarized but its scalar leaves are not all \
                             bound as projected values (or its layout is multi-variant / has \
                             a non-scalar leaf)"
                                    .to_owned();
                        }
                    }
                }
            }
        }
    }
    // THE MEMORY-BACKED HALF: the sub-aggregate's bytes are already in the base
    // local's slot at the projection's rustc layout offset.
    let projected_byval_slot = if !projected_sub_place {
        None
    } else {
        ctx.memory_slots.get(&place.local).cloned()
    };
    if let Some(slot) = projected_byval_slot {
        let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
        let projected =
            walk_memory_projection_offset_raw(ctx, base_ty, place.projection.as_ref()).ok();
        let layout = match memory_aggregate_layout(ctx.tcx, expected_ty)? {
            Some(layout) => Some(layout),
            None => match closure_memory_layout(ctx.tcx, expected_ty)? {
                Some(layout) => Some(layout),
                None => nonscalar_union_memory_layout(ctx.tcx, expected_ty)?,
            },
        };
        match (&projected, &layout) {
            (None, _) => {
                projected_decline =
                    "the projection does not fold to a constant byte offset in the base \
                     local's layout"
                        .to_owned();
            }
            (_, None) => {
                projected_decline = format!(
                    "the parameter type `{expected_ty:?}` has no memory-aggregate, \
                     closure or non-scalar-union slot layout"
                );
            }
            _ => {}
        }
        if let (Some((offset, projected_ty)), Some(layout)) = (projected, layout) {
            let base_size = ctx
                .tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
                .map(|base| base.size.bytes())
                .unwrap_or(0);
            let (_lane_ty, lane_size) = memory_aggregate_lane(layout.align)?;
            let projected_ty = ctx.monomorphize_ty(projected_ty);
            if projected_ty != expected_ty {
                projected_decline = format!(
                    "the sub-place's own type is `{projected_ty:?}`, not the parameter type \
                     `{expected_ty:?}`"
                );
            } else if lane_size == 0 || offset % lane_size != 0 {
                projected_decline = format!(
                    "the sub-place sits at byte offset {offset}, which the {lane_size}-byte \
                     lane width cannot address aligned"
                );
            } else if offset.saturating_add(layout.size) > base_size {
                projected_decline = format!(
                    "the sub-place ({} bytes at offset {offset}) does not lie wholly inside \
                     the base local's {base_size}-byte layout",
                    layout.size
                );
            }
            if projected_ty == expected_ty
                && lane_size != 0
                && offset % lane_size == 0
                && offset.saturating_add(layout.size) <= base_size
            {
                let fields = aggregate_memory_field_tys(&layout.slot_ty)?;
                let agg = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Alloca {
                        ty: layout.slot_ty.clone(),
                        count: None,
                        align: Some(layout.align),
                    })
                    .with_result(agg),
                );
                for (field, field_ty) in &fields {
                    let lane_addr =
                        slot_byte_ptr(ctx, block, slot.ptr, offset + u64::from(*field) * lane_size);
                    let value = emit_typed_load(ctx, block, lane_addr, field_ty.clone());
                    emit_aggregate_field_store(
                        ctx,
                        block,
                        layout.slot_ty.clone(),
                        agg,
                        *field,
                        value,
                    )?;
                }
                // A fresh `Alloca` holding the sub-place's bytes (rustc's layout).
                ctx.fresh_arg_copies.insert(agg);
                return Ok(Some(agg));
            }
        }
    }
    if !place.projection.is_empty() {
        return Err(format!(
            "by-value aggregate call argument {index} uses a projected operand: {projected_decline}. \
             A constant-offset sub-place of a MEMORY-BACKED local whose type IS the \
             parameter's is lowered by value (its lanes are loaded out of the base slot at \
             the projection's layout offset); a whole aggregate local always is. Options: \
             (1) bind the sub-place to its own local immediately before the call, so it owns \
             a whole-local slot; (2) pass it by reference, which needs no by-value materialization; \
             (3) extend this lane to the declined case above — the loader is right here and the \
             precondition it needs is named."
        ));
    }

    // A memory-backed CLOSURE env passed by value (into a generic
    // `fn apply<F: Fn(..)>`): the slot pointer cannot be passed directly because
    // the call adapter retypes the by-value argument Value to the aggregate
    // `slot_ty`, which would clash with the raw `Store` addresses used to BUILD
    // the env (a `Store` address must be a plain I64 pointer carrier). So
    // materialize a FRESH aggregate value: load each lane from the env slot and
    // store it into a fresh alloca, whose pointer carries the aggregate type
    // cleanly (its lane writes go through `slot_byte_ptr`'s normalized address, so
    // it is never itself a `Store` address) — exactly the scalarized by-value
    // path's shape.
    if matches!(expected_ty.kind(), ty::Closure(..)) {
        if let Some(slot) = ctx.memory_slots.get(&place.local).cloned() {
            // The callee declares the by-value closure param as the flat
            // integer-lane tuple `slot_ty` (see `func_ty_for_instance` ->
            // `fat_ptr_or_memory_aggregate_layout`), so the fresh aggregate must
            // be that same lane tuple. Copy each 8-byte lane from the env slot.
            let Some(layout) = closure_memory_layout(ctx.tcx, expected_ty)? else {
                return Err("by-value closure call argument without closure layout".to_owned());
            };
            let fields = aggregate_memory_field_tys(&layout.slot_ty)?;
            let (_, lane_size) = memory_aggregate_lane(layout.align)?;
            let agg = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: layout.slot_ty.clone(),
                    count: None,
                    align: Some(layout.align),
                })
                .with_result(agg),
            );
            // The slot is `size/lane_size` lanes of the `memory_aggregate_lane`
            // type, laid out contiguously, so lane `field` is at byte offset
            // `field*lane_size`.
            for (field, field_ty) in &fields {
                let lane_addr =
                    iter_field_addr(ctx, block, slot.ptr, u64::from(*field) * lane_size);
                let value = emit_typed_load(ctx, block, lane_addr, field_ty.clone());
                emit_aggregate_field_store(ctx, block, layout.slot_ty.clone(), agg, *field, value)?;
            }
            return Ok(Some(agg));
        }
    }

    // A memory-backed aggregate local passed BY VALUE: materialize a FRESH
    // aggregate value (load each lane from the slot, store it into a fresh
    // alloca) rather than passing the slot pointer directly. The call adapter
    // re-types the by-value argument Value to the aggregate `slot_ty`; if we passed
    // the slot pointer, that same Value would ALSO be used as a plain `Ptr` byte
    // address wherever the slot is read/written field-wise in this function (the
    // `?`-operator case: `_3 = helper(); _2 = branch(_3)` — `_3`'s slot is both
    // written by the helper-result store and passed by value to `branch`), making
    // the pointer carry two conflicting types and tripping ISel. The fresh
    // aggregate's pointer is never itself a `Store` address (its lane writes go
    // through `slot_byte_ptr`), so it carries the aggregate type cleanly — exactly
    // the closure-by-value path's shape.
    if let Some(slot) = ctx.memory_slots.get(&place.local).cloned() {
        // An AGGREGATE union uses its slot lane tuple (`nonscalar_union_memory_layout`);
        // `memory_aggregate_layout` deliberately excludes unions. Materialize a fresh
        // aggregate from the slot lanes either way (a raw slot-pointer pass would make
        // the pointer carry both a byte-`Store` address — the `_9 = copy _1` union copy
        // — and the aggregate type, tripping ISel; see the comment above).
        let layout = match memory_aggregate_layout(ctx.tcx, expected_ty)? {
            Some(layout) => layout,
            None => match nonscalar_union_memory_layout(ctx.tcx, expected_ty)? {
                Some(layout) => layout,
                // No aggregate/union layout (only a closure layout, handled above):
                // fall back to the slot pointer.
                None => return Ok(Some(slot.ptr)),
            },
        };
        let fields = aggregate_memory_field_tys(&layout.slot_ty)?;
        let (_lane_ty, lane_size) = memory_aggregate_lane(layout.align)?;
        let agg = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: layout.slot_ty.clone(),
                count: None,
                align: Some(layout.align),
            })
            .with_result(agg),
        );
        for (field, field_ty) in &fields {
            let lane_addr = slot_byte_ptr(ctx, block, slot.ptr, u64::from(*field) * lane_size);
            let value = emit_typed_load(ctx, block, lane_addr, field_ty.clone());
            emit_aggregate_field_store(ctx, block, layout.slot_ty.clone(), agg, *field, value)?;
        }
        return Ok(Some(agg));
    }

    // A scalarized aggregate local whose callee parameter is a MEMORY-BACKED struct
    // (named ADT, `memory_aggregate_layout` is `Some`): the callee reads each field at
    // rustc's BYTE offset, and rustc REORDERS struct fields by descending alignment
    // (`struct{a:i32,b:f64}` -> `b@0, a@8`). The flat declaration-order `pointee_ty`
    // tuple path below would place projected field `i` at lane `i`, mispacking every
    // reordered struct (#69). Pack each scalar-leaf projected field at its rustc byte
    // offset into a fresh `slot_ty` slot instead, exactly as the callee reads it.
    // A scalarized TAGGED single-variant enum (`#[repr(C)] enum F { A(u8, u32) }`)
    // packs the same way, with its tag word written at rustc's tag offset.
    let source_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    let callee_slot_layout = memory_aggregate_layout_shared(ctx.tcx, expected_ty)?;
    if let Some(layout) = &callee_slot_layout {
        if layout.tag.is_none() || is_tagged_univariant_enum(ctx.tcx, expected_ty) {
            if let Some(agg) =
                pack_scalarized_aggregate_byval_slot(ctx, block, place.local, expected_ty, layout)?
            {
                // A fresh `Alloca`, every scalar leaf at its rustc byte offset.
                ctx.fresh_arg_copies.insert(agg);
                return Ok(Some(agg));
            }
        }
    }
    // Otherwise (a tuple — which the callee also keeps in declaration-order scalar
    // form — or a shape the rustc-offset packer declines): materialize a fresh stack
    // slot from the leaf field SSA values via the flat trust-ir tuple type. That
    // image is the callee's only when the callee does not read a rustc-layout slot,
    // or when rustc lays the value out exactly as the tuple; otherwise every field
    // would cross at the wrong byte, so it is refused.
    if callee_slot_layout.is_some()
        && pointee_tuple_image_diverges_from_rustc_layout(ctx.tcx, source_ty)
    {
        return Err(tuple_image_layout_refusal(
            &format!("by-value call argument {index} materializes"),
            source_ty,
        ));
    }
    if let Some(pointee_ty) = aggregate_reference_pointee_to_trust_ir_ty(ctx.tcx, source_ty)? {
        let fields = aggregate_memory_field_tys(&pointee_ty)?;
        let ptr = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: pointee_ty.clone(),
                count: None,
                align: None,
            })
            .with_result(ptr),
        );
        for (field, _) in &fields {
            let value = value_for_scalar_binding(
                ctx,
                ScalarPlaceBinding::Projection {
                    local: place.local,
                    field: *field,
                },
            )?;
            emit_aggregate_field_store(ctx, block, pointee_ty.clone(), ptr, *field, value)?;
        }
        return Ok(Some(ptr));
    }

    Err(format!(
        "by-value aggregate call argument {index} has neither a memory slot nor a \
         scalarized field binding (constructed aggregate not materialized before the call)"
    ))
}

/// Pack a SCALARIZED single-variant all-scalar-leaf aggregate `local`'s projected
/// field SSA values into a fresh `slot_ty` (flat lane tuple) slot at rustc's field
/// BYTE offsets, so a field-reordering struct (`{a:i32,b:f64}` -> `b@0, a@8`) is laid
/// out exactly as the by-value memory-backed callee reads it (#69). Each scalar leaf
/// is written into a scratch slot at its rustc offset; the lanes are then copied into
/// a fresh aggregate whose pointer carries `slot_ty` cleanly for the by-value ABI
/// adapter (mirroring the const-aggregate arg path's scratch+copy, which avoids a slot
/// pointer carrying both a raw `Store` address type and the aggregate type).
///
/// Assemble scalarized field bindings into bytes at rustc's layout offsets.
/// Returns `Ok(None)` for an aggregate that is neither a single-variant struct /
/// tuple nor a Direct-tagged single-variant enum (`is_tagged_univariant_enum`,
/// whose variant's discriminant belongs in the tag word), an unsupported leaf,
/// or a missing binding. The returned pointer is a plain memory address.
fn materialize_scalarized_aggregate_bytes<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    local: Local,
    ty: Ty<'tcx>,
    layout: &MemoryAggregateLayout,
) -> Result<Option<ValueId>, String> {
    let Some(direct_tag) = scalarized_direct_tag(ctx.tcx, ty, layout)? else {
        return Ok(None);
    };
    let Some(leaves) = scalarized_aggregate_leaf_values(ctx, local, ty)? else {
        return Ok(None);
    };
    let direct_tag = direct_tag
        .as_ref()
        .map(|(tag, discriminant)| (tag, *discriminant));
    materialize_leaf_values_bytes(ctx, block, &leaves, layout, direct_tag).map(Some)
}

/// Whether every top-level MIR field of the scalarized aggregate `ty` sits at a FLAT
/// leaf index equal to its OWN MIR field index.
///
/// # Why any lane that admits a projected sub-place has to ask this
///
/// A scalarized aggregate's leaves are bound in `projected_values`, and
/// `projected_field_index` keys a scalar read `(_n.k: T)` by the MIR FIELD index `k`
/// — while a construction that went through
/// `lower_recursive_scalar_field_aggregate_operands` (any aggregate with a
/// scalar-field-aggregate field) bound each FLATTENED leaf at a running FLAT index.
/// Where the two disagree, a sibling scalar read of the SAME local reads the wrong
/// leaf. MEASURED 2026-09-25 on a 16-line program (`t1d_ces_sametype.rs`):
/// `const_eval_select((Lay3 { a, b, c }, k), ..)` with `a=1 b=2 c=3 k=7` returned
/// **80** under trust-cg and **85** under the LLVM oracle at `-O0` — `k` (flat 3) was
/// read at MIR index 1 and picked up `b`. The `bool`-typed twin is caught by the
/// adapter's type check ("Call argument 1 type mismatch: got U64, expected Bool"); the
/// same-typed one is NOT caught by anything.
///
/// That defect is OLDER than this lane and lives in `projected_field_index`. It was
/// unreachable in `library/alloc` only because the by-value projected-sub-place
/// argument refused first, so WIDENING that refusal without this gate converts a
/// fail-closed into a silent wrong value. This gate is therefore a precondition of
/// the widening, not a nicety: identity of the two indexings is exactly the statement
/// that every projected read of this local — the widening's own, and every sibling's —
/// addresses the leaf it names.
///
/// It admits the two `library/alloc` shapes whose sibling reads are sound
/// (`handle_alloc_error`'s `(Layout,)`; `Global::deallocate_impl`'s
/// `(NonNull<u8>, Layout)` — one leaf, then the sub-place) and refuses the three whose
/// trailing scalar sits past a multi-leaf field (`alloc_impl`'s `(Layout, bool)`,
/// `grow_impl` / `shrink_impl`'s five-element tuple). A ZST field shifts the flat
/// indices too, which is the same FUZZ-6 hazard `pack_scalarized_aggregate_byval_slot`
/// documents, and it fails this check for the same reason.
/// Whether EVERY projected scalar read of a scalarized `ty` local resolves to the leaf
/// it names — the precondition the by-value projected-sub-place argument lane cannot
/// skip, because admitting a sub-place of a local whose SIBLING reads are misaddressed
/// converts a fail-closed into a silent wrong value (a measured 80-vs-85 divergence;
/// see [`flat_leaf_field_for_mir_field`]).
///
/// Two ways it can hold, and they are the two binding schemes:
///
///   * the RECURSIVE FLAT binder is in force and `projected_field_index` maps each MIR
///     field index through [`flat_leaf_field_for_mir_field`], so a sibling read lands
///     on its own leaf by construction (and a field with no single leaf — a ZST, a
///     nested aggregate — fails closed there rather than answering with a fragment);
///   * or the binding is by MIR field index and the two indexings COINCIDE
///     ([`scalarized_field_indices_are_flat_identity`]).
///
/// Everything else still refuses: an ARRAY of multi-leaf elements (whose `[Index]` key
/// is the element index, not `index * leaves_per_element`), a union, a multi-variant
/// enum. Those are not mapped, so they are not admitted.
fn scalarized_field_reads_name_their_own_leaf<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    if recursive_flat_binding_in_force(tcx, ty)? {
        return Ok(true);
    }
    scalarized_field_indices_are_flat_identity(tcx, ty)
}

fn scalarized_field_indices_are_flat_identity<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    let fields: Vec<Ty<'tcx>> = match ty.kind() {
        ty::Tuple(elems) if !elems.is_empty() => elems.iter().collect(),
        ty::Adt(adt, args) if adt.is_struct() || (adt.is_enum() && adt.variants().len() == 1) => {
            adt.variant(VariantIdx::new(0))
                .fields
                .iter()
                .map(|field| normalized_adt_field_ty(tcx, field, *args))
                .collect()
        }
        ty::Closure(_, args) => args.as_closure().upvar_tys().iter().collect(),
        _ => return Ok(false),
    };
    let mut flat = 0usize;
    for (index, field_ty) in fields.into_iter().enumerate() {
        if flat != index {
            return Ok(false);
        }
        // A ZST contributes NO leaf, so it shifts every later field's flat index.
        if is_zero_sized_ty(tcx, field_ty) {
            continue;
        }
        flat += match scalar_field_aggregate_trust_ir_fields(tcx, field_ty) {
            Ok(Some(leaves)) => leaves.len(),
            Ok(None) => 1,
            // A leaf the flattener refuses: no statement can be made about the
            // binding, so decline.
            Err(_) => return Ok(false),
        };
    }
    Ok(true)
}

/// The `(rustc byte offset, scalar-leaf trust-ir type, bound SSA value)` of every
/// flattened scalar leaf of the SCALARIZED aggregate local `local` (whose Rust type
/// is `ty`) — the collection half of [`pack_scalarized_aggregate_byval_slot`], split
/// out so a PROJECTED SUB-PLACE of the same local can be packed from the same leaves
/// (`lower_memory_aggregate_byval_call_arg`'s `move (_4.0: Layout)` lane) instead of
/// re-deriving either binding scheme.
///
/// `Ok(None)` — the caller falls back / fails closed — when the aggregate is not a
/// `Single`-variant layout, has a non-scalar leaf, or any leaf lacks a bound
/// projected value.
fn scalarized_aggregate_leaf_values<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    local: Local,
    ty: Ty<'tcx>,
) -> Result<Option<Vec<(u64, TrustIrTy, ValueId)>>, String> {
    use rustc_abi::Variants;
    let cx = LayoutCx(ctx.tcx);
    let base = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("scalarized by-value pack layout_of failed: {e:?}"))?;
    // A single-variant layout, or a single-variant enum rustc gives a tag
    // (`is_tagged_univariant_enum`): its one variant's fields are the leaves, and
    // the tag word is written by the caller that knows the slot
    // (`scalarized_direct_tag`).
    if !matches!(base.layout.variants(), Variants::Single { .. })
        && !is_tagged_univariant_enum(ctx.tcx, ty)
    {
        return Ok(None);
    }
    // Collect (rustc byte offset, leaf type, projected SSA value) for every scalar
    // leaf, keyed EXACTLY as the aggregate's CONSTRUCTION bound its
    // `projected_values` (`lower_adt_aggregate` / `lower_tuple_aggregate`). Those two
    // constructors pick one of two field-binding schemes, and the projected-value KEY
    // differs between them — so the by-value repack MUST use the matching scheme or a
    // ZST field silently mis-maps a later scalar field (the FUZZ-6 clang-oracle
    // divergence: `#[repr(C)] struct { a: u64, _z: (), b: u64 }` passed by value read
    // `b` from the ZST's stale index-1 binding, a wrong ABI value at the boundary):
    //
    //   * If ANY top-level field is itself a scalar-field aggregate (a nested
    //     struct/tuple/newtype), construction used
    //     `lower_recursive_scalar_field_aggregate_operands`, which binds each
    //     FLATTENED leaf at a running FLAT index (ZST fields skipped, nested fields
    //     expanded depth-first). `enumerate_scalar_leaf_offsets` walks leaves in that
    //     same DFS order, so the flat enumerate position IS the projected key.
    //
    //   * Otherwise (a FLAT struct/tuple whose every field is a single scalar or a
    //     ZST) construction used the else-branch, which binds each field operand at
    //     its MIR FIELD INDEX — INCLUDING ZST fields (bound to an unused value). A
    //     leading/interior ZST field therefore SHIFTS the MIR index of every later
    //     field past its ZST-skipped flat position, so each non-ZST scalar leaf must
    //     be looked up by its MIR field index, not the flat leaf position.
    //
    // Either scheme bails (`Ok(None)` -> the caller falls back) on a non-single-
    // variant layout, a non-scalar leaf, or any unbound field, so it can never
    // mispack; the SysV classifier then places the byte-exact fresh slot identically
    // to the callee's by-value parameter.
    let variant = base.for_variant(&cx, rustc_abi::FIRST_VARIANT);
    let uses_recursive_flat_binding = (0..variant.fields.count()).any(|i| {
        scalar_field_aggregate_trust_ir_fields(ctx.tcx, variant.field(&cx, i).ty)
            .map(|shape| shape.is_some())
            .unwrap_or(false)
    });
    let mut leaves: Vec<(u64, TrustIrTy, ValueId)> = Vec::new();
    if uses_recursive_flat_binding {
        let mut leaf_offsets: Vec<(u64, TrustIrTy)> = Vec::new();
        if enumerate_scalar_leaf_offsets(ctx.tcx, &cx, &variant, 0, &mut leaf_offsets)?.is_none() {
            return Ok(None);
        }
        for (flat, (offset, leaf_ty)) in leaf_offsets.into_iter().enumerate() {
            let flat_u32 = u32::try_from(flat)
                .map_err(|_| "scalarized by-value pack flat index out of u32 range".to_owned())?;
            let Some(value) = ctx.projected_values.get(&(local, flat_u32)).copied() else {
                return Ok(None);
            };
            leaves.push((offset, leaf_ty, value));
        }
    } else {
        // MIR-field-index binding: each non-ZST field is one scalar leaf at its rustc
        // byte offset, looked up by its (ZST-preserving) MIR field index.
        for i in 0..variant.fields.count() {
            let field_layout = variant.field(&cx, i);
            if is_zero_sized_ty(ctx.tcx, field_layout.ty) {
                continue;
            }
            let Ok(leaf_ty) = memory_scalar_leaf_ty(ctx.tcx, field_layout.ty) else {
                return Ok(None);
            };
            let offset = variant.fields.offset(i).bytes();
            let field_u32 = u32::try_from(i)
                .map_err(|_| "scalarized by-value pack field index out of u32 range".to_owned())?;
            let Some(value) = ctx.projected_values.get(&(local, field_u32)).copied() else {
                return Ok(None);
            };
            leaves.push((offset, leaf_ty, value));
        }
    }

    Ok(Some(leaves))
}

/// Materialize the by-value ABI value for an aggregate whose bytes are held in SSA
/// leaves: store each leaf into a scratch slot at its byte offset within the
/// aggregate, then copy that slot's lanes into a fresh `slot_ty` alloca. The
/// packing half of [`pack_scalarized_aggregate_byval_slot`].
///
/// `leaves` offsets are relative to the aggregate `layout` describes, so a PROJECTED
/// sub-place packs by re-basing its leaves to its own start.
fn materialize_leaf_values_bytes(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    leaves: &[(u64, TrustIrTy, ValueId)],
    layout: &MemoryAggregateLayout,
    direct_tag: Option<(&MemoryEnumTag, i128)>,
) -> Result<ValueId, String> {
    // Scratch slot: receives each leaf at its rustc byte offset (its pointer is only
    // ever a plain `Store`/`Load` byte address, so it carries a flat `Ptr` cleanly).
    let scratch = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: layout.slot_ty.clone(),
            count: None,
            align: Some(layout.align),
        })
        .with_result(scratch),
    );
    for (offset, leaf_ty, value) in leaves {
        let addr = if *offset == 0 {
            scratch
        } else {
            slot_byte_ptr(ctx, block, scratch, *offset)
        };
        emit_typed_store(block, addr, leaf_ty.clone(), *value);
    }
    if let Some((tag, discriminant)) = direct_tag {
        store_memory_enum_tag_at_base(ctx, block, scratch, tag, discriminant);
    }

    Ok(scratch)
}

fn pack_leaf_values_into_byval_slot(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    leaves: &[(u64, TrustIrTy, ValueId)],
    layout: &MemoryAggregateLayout,
    direct_tag: Option<(&MemoryEnumTag, i128)>,
) -> Result<ValueId, String> {
    let scratch = materialize_leaf_values_bytes(ctx, block, leaves, layout, direct_tag)?;
    // Fresh aggregate: copy each lane from the scratch slot. Its pointer is never
    // itself a `Store` address (lane writes go through `slot_byte_ptr`), so it
    // carries the aggregate `slot_ty` cleanly for the by-value ABI adapter.
    let fields = aggregate_memory_field_tys(&layout.slot_ty)?;
    let (_lane_ty, lane_size) = memory_aggregate_lane(layout.align)?;
    let agg = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: layout.slot_ty.clone(),
            count: None,
            align: Some(layout.align),
        })
        .with_result(agg),
    );
    for (field, field_ty) in &fields {
        let lane_addr = slot_byte_ptr(ctx, block, scratch, u64::from(*field) * lane_size);
        let value = emit_typed_load(ctx, block, lane_addr, field_ty.clone());
        emit_aggregate_field_store(ctx, block, layout.slot_ty.clone(), agg, *field, value)?;
    }
    Ok(agg)
}

fn pack_scalarized_aggregate_byval_slot<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    local: Local,
    ty: Ty<'tcx>,
    layout: &MemoryAggregateLayout,
) -> Result<Option<ValueId>, String> {
    let Some(direct_tag) = scalarized_direct_tag(ctx.tcx, ty, layout)? else {
        return Ok(None);
    };
    let Some(leaves) = scalarized_aggregate_leaf_values(ctx, local, ty)? else {
        return Ok(None);
    };
    let direct_tag = direct_tag
        .as_ref()
        .map(|(tag, discriminant)| (tag, *discriminant));
    pack_leaf_values_into_byval_slot(ctx, block, &leaves, layout, direct_tag).map(Some)
}

/// The tag word the bytes of the scalarized aggregate `ty` carry besides its
/// leaves, given the slot `layout` they are assembled into: `Some(None)` for a
/// single-variant layout with no tag, `Some(Some((tag, discriminant)))` for a
/// single-variant enum rustc gives a DIRECT tag (`is_tagged_univariant_enum`),
/// whose one variant's discriminant belongs in that word, and `None` (decline)
/// for anything else.
fn scalarized_direct_tag<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    layout: &MemoryAggregateLayout,
) -> Result<Option<Option<(MemoryEnumTag, i128)>>, String> {
    use rustc_abi::Variants;
    let base = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("scalarized aggregate layout_of failed: {e:?}"))?;
    Ok(match (base.layout.variants(), &layout.tag) {
        (Variants::Single { .. }, None) => Some(None),
        (Variants::Multiple { .. }, Some(tag))
            if is_tagged_univariant_enum(tcx, ty)
                && matches!(tag.encoding, MemoryTagEncoding::Direct) =>
        {
            let discriminant = enumlike_discriminant_value(tcx, ty, rustc_abi::FIRST_VARIANT)?;
            Some(Some((tag.clone(), discriminant)))
        }
        _ => None,
    })
}

/// The `projected_values` KEY under which a SCALARIZED local of type `ty` holds each
/// of its sized scalar leaves, listed in the leaf order `enumerate_scalar_leaf_offsets`
/// and `scalar_leaf_offsets` produce (declaration-order, depth-first, zero-sized
/// fields skipped). `leaf_count` is the length of the caller's leaf list; a scheme
/// that does not account for exactly that many leaves is an error.
///
/// The key scheme is a function of the TYPE alone (the same decision
/// [`flat_leaf_field_for_mir_field`] reproduces for single-field reads):
///
///   * RECURSIVE FLAT ([`recursive_flat_binding_in_force`]: the aggregate flattens and
///     some top-level field is itself a scalar-field aggregate). The recursive binder
///     `lower_recursive_scalar_field_aggregate_operands` keys each leaf by a running
///     flat index that skips zero-sized fields at EVERY nesting level, so leaf `i`'s
///     key is `i`. The const writer, the memory and through-pointer loads, the
///     nested-field load (`lower_memory_nested_aggregate_field_use`) and whole-local
///     copies key the same way.
///   * MIR FIELD INDEX (every other struct / tuple / closure / single-variant enum:
///     each top-level field is one scalar leaf or zero-sized). `lower_adt_aggregate`,
///     `lower_tuple_aggregate` and `lower_closure_aggregate` key each field by its MIR
///     field index, which COUNTS the zero-sized fields (the tuple and closure binders
///     even bind a unit value there), so a leaf after a ZST is keyed past its leaf
///     position: `{ z: (), a, b }` holds `a` at key 1 and `b` at key 2. Field writes
///     (`projected_field_index`) and the const writer key the same way, and the
///     memory and through-pointer loads key through this function.
///   * An ARRAY: its binders key element `k` at `k` (scalar elements) or at its
///     leaves' flat positions (aggregate elements), the leaf order itself.
///
/// A value with no sized leaf has no key to state. Anything else (a union, a
/// multi-variant enum) has no key scheme stated here and is refused by name.
fn scalarized_leaf_binding_keys<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    leaf_count: usize,
) -> Result<Vec<u32>, String> {
    let position_keys = || -> Result<Vec<u32>, String> {
        (0..leaf_count)
            .map(|leaf| {
                u32::try_from(leaf)
                    .map_err(|_| format!("scalar leaf {leaf} of `{ty:?}` out of u32 range"))
            })
            .collect()
    };
    // No sized leaf (a zero-sized value such as a capture-free closure): no key.
    if leaf_count == 0 || matches!(ty.kind(), ty::Array(..)) {
        return position_keys();
    }
    // The scheme is decided on NORMALIZED field types (`normalized_adt_field_ty`), the
    // view the binders take. A field type that still carries an alias did not
    // normalize, so whether it is a nested aggregate (and with it the scheme) is not
    // known: refuse rather than pick one.
    use rustc_middle::ty::TypeVisitableExt;
    let unnormalized = recursive_flat_binding_field_tys(tcx, ty).and_then(|field_tys| {
        field_tys
            .into_iter()
            .find(|field_ty| field_ty.has_aliases())
    });
    if let Some(alias) = unnormalized {
        return Err(format!(
            "[TCG-ZST-LANE-INDEX] scalarized `{ty:?}` has a field type `{alias:?}` that \
             does not normalize, so its projected-value key scheme cannot be stated; \
             failing closed rather than guessing which binding holds each leaf"
        ));
    }
    if recursive_flat_binding_in_force(tcx, ty)? {
        return position_keys();
    }
    let Some(field_tys) = recursive_flat_binding_field_tys(tcx, ty) else {
        return Err(format!(
            "[TCG-ZST-LANE-INDEX] scalarized `{ty:?}` has no stated projected-value key \
             scheme (not a struct, tuple, closure, single-variant enum or array); failing \
             closed rather than guessing which binding holds each leaf"
        ));
    };
    let mut keys = Vec::with_capacity(leaf_count);
    for (index, field_ty) in field_tys.iter().enumerate() {
        if is_zero_sized_ty(tcx, *field_ty) {
            continue;
        }
        keys.push(
            u32::try_from(index)
                .map_err(|_| format!("field {index} of `{ty:?}` out of u32 range"))?,
        );
    }
    if keys.len() != leaf_count {
        return Err(format!(
            "[TCG-ZST-LANE-INDEX] scalarized `{ty:?}` keys {} sized fields by MIR field \
             index but its leaf walk has {leaf_count} leaves; failing closed rather than \
             reading a neighbouring binding",
            keys.len()
        ));
    }
    Ok(keys)
}

/// Recursively enumerate `(rustc byte offset, scalar-leaf trust-ir type)` for every
/// flattened scalar leaf of a SCALARIZED single-variant aggregate layout, descending
/// into nested scalar-field-aggregate fields (nested struct / tuple / single-variant
/// enum / newtype, and array elements) at their layout byte offsets. `ty_and_layout`
/// is the (sub)aggregate being flattened; `base_offset` is its byte offset within the
/// enclosing slot.
///
/// The traversal order is IDENTICAL to `scalar_field_aggregate_trust_ir_fields`
/// (declaration-order, depth-first, ZST-skipping), the order
/// `lower_recursive_scalar_field_aggregate_operands` assigns flat `projected_values`
/// indices in. The flat construction path (no nested scalar-field-aggregate field)
/// instead binds by MIR field index, which counts ZST fields, so a caller reading a
/// scalarized local's bindings maps leaf position `i` to its key through
/// [`scalarized_leaf_binding_keys`], never by using `i` as the key.
/// The byte offset comes from the authoritative rustc layout (correct under field
/// reordering). This lets a caller
/// map flat scalar bindings <-> slot byte offsets for a nested-aggregate-containing
/// struct in BOTH directions (pack scalarized fields into a by-value slot; load slot
/// bytes back into scalarized fields).
///
/// Returns `Ok(None)` (caller falls back / fails closed) on any non-single-variant
/// layout or non-scalar leaf, so a mispack/misload is impossible: the worst case is
/// a sound fail-closed, never a wrong-byte miscompile.
fn enumerate_scalar_leaf_offsets<'tcx>(
    tcx: TyCtxt<'tcx>,
    cx: &LayoutCx<'tcx>,
    ty_and_layout: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
    base_offset: u64,
    out: &mut Vec<(u64, TrustIrTy)>,
) -> Result<Option<()>, String> {
    use rustc_abi::Variants;
    if !matches!(
        ty_and_layout.layout.variants(),
        Variants::Single { .. } | Variants::Empty
    ) {
        return Ok(None);
    }
    let variant = ty_and_layout.for_variant(cx, rustc_abi::FIRST_VARIANT);
    for i in 0..variant.fields.count() {
        let field_layout = variant.field(cx, i);
        if is_zero_sized_ty(tcx, field_layout.ty) {
            continue;
        }
        let field_offset = base_offset + variant.fields.offset(i).bytes();
        // A field that is itself a scalar-field aggregate (nested struct / tuple /
        // single-variant enum / newtype) contributes its OWN flattened leaves, in
        // the same DFS order the flat binding indices were assigned — recurse at the
        // field's byte offset. (Arrays are not `scalar_field_aggregate` types, so an
        // array field bottoms out as a leaf below only when its element is a memory
        // scalar; a nested-aggregate array element declines and fails closed.)
        if scalar_field_aggregate_trust_ir_fields(tcx, field_layout.ty)?.is_some() {
            if enumerate_scalar_leaf_offsets(tcx, cx, &field_layout, field_offset, out)?.is_none() {
                return Ok(None);
            }
            continue;
        }
        let Ok(leaf_ty) = memory_scalar_leaf_ty(tcx, field_layout.ty) else {
            return Ok(None);
        };
        out.push((field_offset, leaf_ty));
    }
    Ok(Some(()))
}

fn lower_scalar_reference_call_arg<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    index: usize,
    operand: &Operand<'tcx>,
    expected_ty: Ty<'tcx>,
) -> Result<Option<PreparedCallArg>, String> {
    let expected_ty = ctx.monomorphize_ty(expected_ty);
    let ty::Ref(_, inner, expected_mutability) = expected_ty.kind() else {
        return Ok(None);
    };
    let inner = ctx.monomorphize_ty(*inner);
    // A reference to a ZERO-SIZED pointee (`&[u8; 0]` — `<[u8; 0] as AsRef<[u8]>>
    // ::as_ref(&self)`, `ByteStr::new::<[u8; 0]>`): the argument is a plain
    // pointer scalar that nothing ever reads through (a ZST has no bytes), bound
    // by `lower_scalar_ref`'s ZST arm (rustc's aligned dangling constant) or an
    // entry arg. It is neither a scalarized aggregate to snapshot nor a scalar to
    // spill into an `Alloca`; decline here so the generic operand path passes the
    // pointer value as-is. Scoped to a sized ZST pointee; every non-ZST shape
    // keeps its existing classification below.
    if is_zero_sized_ty(ctx.tcx, inner) {
        return Ok(None);
    }
    if let Some(kind_name) = scalarized_aggregate_kind_name(ctx.tcx, inner)? {
        // A reference argument whose value is ALREADY a genuine address — an
        // entry-arg reference forwarded as-is (`&self` handed on), or a bound
        // scalar pointer (a `&(*p)` reborrow, the slot address of a memory-backed
        // local, a `&(*p).field` GEP, the never-read placeholder a `&ZST` borrow
        // binds) — is passed through unchanged, whatever its pointee: a ZST
        // (`&EscapeByte`, a zero-upvar closure's `&self`), or an aggregate
        // `aggregate_reference_pointee_to_trust_ir_ty` declines (`Ok(None)`) that
        // is not one of the intercepted collections it declines FOR. The callee
        // reads the pointee THROUGH MEMORY, exactly as it does for the entry-arg /
        // bound-pointer pass-through `lower_aggregate_reference_call_arg` already
        // performs for flat pointees. EXCLUDED, so the register model is never
        // handed out as an address: a `borrowed_scalars` / `borrowed_aggregates`
        // binding (a scalarized referent with no stable address — those need the
        // materialize-and-reload path or the refusal below), and a const-slice
        // `pointer_metadata_lengths` binding (data pointer + side-table length,
        // not a plain thin pointer).
        if let Operand::Copy(place) | Operand::Move(place) = operand {
            if place.projection.is_empty()
                && !ctx.borrowed_scalars.contains_key(&place.local)
                && !ctx.borrowed_aggregates.contains_key(&place.local)
                && !ctx.pointer_metadata_lengths.contains_key(&place.local)
                && (ctx.scalar_values.contains_key(&place.local) || is_entry_arg(body, place.local))
            {
                let value = lower_operand_to_value(ctx, body, block, operand)?;
                return Ok(Some(PreparedCallArg {
                    value,
                    mutable_reloads: Vec::new(),
                }));
            }
        }
        return Err(format!(
            "direct call aggregate reference arg {index} target is unsupported {kind_name}: {inner:?}"
        ));
    }
    // A reference whose POINTEE is itself a `&dyn Trait` FAT POINTER
    // (`fn thru(r: &&dyn Shape)`): the pointee is a two-lane 16-byte
    // `{data, vtable}` image, not a scalar, so the snapshot-into-an-`Alloca`-
    // and-reload machinery below — which assumes ONE typed load and ONE typed
    // store of the pointee — cannot carry it without truncating a lane.
    //
    // The argument's VALUE is already a genuine address whenever the referent
    // is memory-backed (rule (4-fat) gives an address-taken `&dyn` local a real
    // 16-byte slot, and `lower_scalar_ref` binds `&d` to that slot pointer) or
    // the reference is an entry argument forwarded on. Pass that pointer
    // through unchanged and let the callee read both lanes through it — exactly
    // the pass-through the scalarized-aggregate arm above performs.
    //
    // Scoped to a `&dyn` pointee, which fails closed here today; a `&&[T]` /
    // `&&str` pointee keeps its existing handling
    // (`local_is_thin_ref_to_slice_fat_ptr` and the const-slice machinery own
    // that shape). Any other source binding (a scalarized referent with no
    // stable address) falls through to the refusal below rather than hand out
    // a register model as an address.
    if is_trait_object_reference_ty(inner) {
        if let Operand::Copy(place) | Operand::Move(place) = operand {
            if place.projection.is_empty()
                && !ctx.borrowed_scalars.contains_key(&place.local)
                && !ctx.borrowed_aggregates.contains_key(&place.local)
                && (ctx.scalar_values.contains_key(&place.local) || is_entry_arg(body, place.local))
            {
                let value = lower_operand_to_value(ctx, body, block, operand)?;
                return Ok(Some(PreparedCallArg {
                    value,
                    mutable_reloads: Vec::new(),
                }));
            }
        }
        return Err(format!(
            "direct call arg {index} is a `&&dyn Trait` whose referent has no stable \
             address (the `{{data, vtable}}` pair is register-held); failing closed \
             rather than passing a pointer to a two-lane image that does not exist"
        ));
    }
    let pointee_ty = rust_ty_to_trust_ir_ty(ctx.tcx, inner)?;
    // A reference to a ZERO-SIZED pointee (`&f` / `&mut f` of a fn ITEM — the
    // `self` of an `Fn`/`FnMut` shim call `<fn item as FnMut>::call_mut(&mut f, ..)`
    // — mapped to `Unit`, and `size == 0` by rustc's layout): there is no pointee
    // value to snapshot into an `Alloca` and nothing to reload after the call. The
    // reference IS its already-bound pointer value (the dangling aligned address
    // `lower_scalar_ref` materialized for it), so decline here and let the generic
    // operand path below pass that value through unchanged. A non-ZST `Unit`-typed
    // pointee cannot occur (`Unit` is only produced for `size == 0` types), so the
    // fail-closed arm right after is unchanged for every other shape.
    if matches!(pointee_ty, TrustIrTy::Unit | TrustIrTy::Never) && is_zero_sized_ty(ctx.tcx, inner)
    {
        return Ok(None);
    }
    // Pointer-like pointees are 64-bit scalar carriers on every target this
    // backend emits; trust-ir 6ed4bf0 made bit_width() return None for them
    // (same class as the Rvalue::Ref gate fix — e.g. `&mut v` of an
    // intercepted Vec local, whose value IS a Ptr, passed to a helper fn).
    if pointee_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(&pointee_ty) {
        return Err(format!(
            "direct call scalar reference arg {index} target is not scalarizable: {pointee_ty:?}"
        ));
    }

    // A CONST-pointer scalar reference arg — e.g. `unwrap_or(&0)` where `&0` is
    // promoted to a `&'static` const (the O1 shape; O0/O2/O3 pass a place). It is
    // an IMMUTABLE `&T` (no writeback), so emit the const-eval allocation address
    // and pass it directly. Only for a shared reference; a `&mut` const is not a
    // valid Rust shape and stays fail-closed below.
    if matches!(expected_mutability, rustc_hir::Mutability::Not) {
        if let Operand::Constant(constant) = operand {
            let evaluated = ctx.eval_const_operand(constant);
            if let Some((alloc_id, offset)) = const_pointer_target(ctx, &evaluated)? {
                let addr = emit_const_alloc_addr(ctx, block, alloc_id, offset, TrustIrTy::Ptr)?;
                return Ok(Some(PreparedCallArg {
                    value: addr,
                    mutable_reloads: Vec::new(),
                }));
            }
        }
    }

    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        return Err(format!(
            "direct call scalar reference arg {index} is not a place operand"
        ));
    };
    if !place.projection.is_empty() {
        return Err(format!(
            "direct call scalar reference arg {index} uses projected reference operand"
        ));
    }

    let Some(binding) = ctx.borrowed_scalars.get(&place.local).copied() else {
        if is_entry_arg(body, place.local) || ctx.scalar_values.contains_key(&place.local) {
            return Ok(None);
        }
        return Err(format!(
            "direct call scalar reference arg {index} before scalar borrow binding"
        ));
    };
    if matches!(expected_mutability, rustc_hir::Mutability::Mut) && !binding.mutable {
        return Err(format!(
            "direct call mutable reference arg {index} from shared scalar borrow"
        ));
    }
    // Same interior-mutability rule as the aggregate arg: a shared borrow of a
    // scalarized `!Freeze` scalar (`Cell<u32>`, `UnsafeCell<u8>`) is a snapshot
    // the callee's writes never reach. `compute_scalar_cell_locals` cells such a
    // local when its `&c` is a call argument, so this fires only for a shape that
    // pass did not cover — refuse rather than snapshot.
    if matches!(expected_mutability, rustc_hir::Mutability::Not)
        && !inner.is_freeze(ctx.tcx, ty::TypingEnv::fully_monomorphized())
    {
        return Err(format!(
            "[TCG-INTERIOR-MUT-SNAPSHOT] direct call shared scalar reference arg {index} \
             borrows a scalarized `{inner:?}`, which has interior mutability (`!Freeze`): a \
             materialized snapshot would drop every write the callee makes through it. \
             Options: (1) let the referent be celled (pass `&c` directly to the accessor), \
             (2) pass `&mut` (reloaded after the call), (3) keep the caller on the LLVM backend"
        ));
    }
    // FAIL-CLOSED: a MUTABLE scalar reference whose borrow binding is BRANCH-VARYING
    // (a block-param-threaded borrow — the self-placeholder `Local(ref)` installed
    // when a borrowed scalar crosses a value-divergent join) has NO resolvable
    // pointee target: the post-call reload would rebind the placeholder (the ref
    // local itself) instead of the borrowed local, and the callee's `*dst = ..`
    // write-back would be SILENTLY DROPPED (found by the differential fuzz hunt:
    // `put(&mut acc, ..)` where `&mut acc` is taken BEFORE a diamond that also calls
    // `put` on both arms — the post-join call's mutation vanished, wrong value at
    // O2/O3 while O0's shape lowered correctly). The same placeholder is already
    // rejected on the STORE path ([TCG-PTRSEL-STORE]); this is the call-arg twin.
    // A SHARED (read-only) threaded borrow is fine — its pointee-value snapshot is
    // correct and no write-back exists.
    if matches!(expected_mutability, rustc_hir::Mutability::Mut) && binding.branch_varying {
        return Err(format!(
            "[TCG-MUTREF-ARG-PHI] direct call mutable scalar reference arg {index} has a \
             branch-varying (block-threaded) borrow binding — the post-call write-back \
             cannot be rebound to the borrowed local and would be silently dropped; \
             failing closed rather than miscompiling"
        ));
    }

    let source_ty = scalar_binding_trust_ir_ty(ctx, body, binding.target)?;
    if source_ty != pointee_ty {
        return Err(format!(
            "direct call scalar reference arg {index} type mismatch: source {source_ty:?}, \
             callee pointee {pointee_ty:?}"
        ));
    }

    let current = value_for_borrow_target(ctx, binding.target)?;
    let referent_ty = ctx.monomorphize_ty(inner);
    // The referent's HOME (`borrow_home_scalar_leaf_slot`): one frame slot per
    // referent, shared by every `&` of it, with rustc's extent at rustc's ABI
    // alignment (`scalar_leaf_object_extent`), so an over-aligned scalar newtype
    // (`&A16`) is promised rustc's alignment and extent with the scalar at offset
    // 0. A 64-bit frame honours an `Alloca` alignment only up to
    // `TARGET_STACK_ALIGN_BYTES`, so an over-aligned scalar newtype aligned above
    // that (`#[repr(align(128))] struct CP(u64)`), which the home would refuse,
    // takes `padded_scalar_home_extent`'s over-allocated, rounded-up temporary
    // instead (`alloca_rustc_extent`).
    let ptr = match padded_scalar_home_extent(ctx, referent_ty, &pointee_ty) {
        Some((size, align)) if align > TARGET_STACK_ALIGN_BYTES => {
            alloca_rustc_extent(ctx, block, size, align)
        }
        _ => borrow_home_scalar_leaf_slot(ctx, binding.target, referent_ty, &pointee_ty)?,
    };
    block.body.push(InstrNode::new(Inst::Store {
        ty: pointee_ty.clone(),
        ptr,
        value: current,
        volatile: false,
        align: None,
    }));

    let mutable_reloads = matches!(expected_mutability, rustc_hir::Mutability::Mut)
        .then(|| {
            vec![MutableReferenceArgReload::Scalar {
                ptr,
                ty: pointee_ty,
                binding: binding.target,
            }]
        })
        .unwrap_or_default();
    Ok(Some(PreparedCallArg {
        value: ptr,
        mutable_reloads,
    }))
}

fn reload_mutable_reference_call_args(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    reloads: Vec<MutableReferenceArgReload>,
) -> Result<(), String> {
    for reload in reloads {
        match reload {
            MutableReferenceArgReload::Scalar { ptr, ty, binding } => {
                let value = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Load {
                        ty,
                        ptr,
                        volatile: false,
                        align: None,
                    })
                    .with_result(value),
                );
                if crate::knobs::is_enabled(crate::knobs::MUTRELOAD_TRACE) {
                    eprintln!("MUTRELOAD rebind {binding:?} -> {value:?}");
                }
                bind_value_for_scalar_binding(ctx, binding, value);
            }
            MutableReferenceArgReload::Aggregate {
                ptr,
                ty,
                source,
                fields,
            } => {
                for (field, field_ty) in fields {
                    let value = ctx.fresh_value();
                    emit_aggregate_field_load(
                        ctx,
                        block,
                        AggregateFieldMemoryAccess {
                            ptr,
                            aggregate_ty: ty.clone(),
                            field,
                            field_ty,
                        },
                        value,
                    )?;
                    ctx.bind_projected_value(source, field, value);
                }
            }
        }
    }
    Ok(())
}

/// Does this target use the REAL-ADDRESS reference model — i.e. does a `&`-typed
/// referent get a CELL holding a pointer at its own address?
///
/// One predicate, two callers, on purpose. The model's own gate lives in the `&raw`
/// pre-pass (`ref_referent_cell_target`) and
/// [`lower_promoted_scalar_ref_return_call`] must agree with it: the promotion there
/// selects a snapshot PONTEE value, and its doc says that with real addresses an
/// address-taken result reference "must store the returned pointer in its cell, not a
/// selected pointee value". So the promotion has to be OFF exactly where the cell
/// model is ON.
///
/// They did NOT agree between 2026-09-29's two changes. Celling was extended from
/// aarch64 Linux to x86-64 Linux, while the promotion's early return kept the
/// aarch64-only arch test — leaving x86-64 with real addresses AND the promotion, the
/// one combination the promotion's doc rules out. This helper is what makes the two
/// move together; do not re-inline either copy.
///
/// The `no-x86-ref-referent-cell` opt-out is deliberately read here too, so disabling
/// the cell model on x86-64 also restores the promotion, and the pair stays coherent
/// in BOTH knob positions rather than only the default one.
fn uses_real_address_reference_model(tcx: TyCtxt<'_>) -> bool {
    tcx.sess.target.os == rustc_target::spec::Os::Linux
        && (tcx.sess.target.arch.desc() == "aarch64"
            || (tcx.sess.target.arch.desc() == "x86_64"
                && !crate::knobs::is_enabled(crate::knobs::NO_X86_REF_REFERENT_CELL)))
}

fn lower_promoted_scalar_ref_return_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    // This promotion selects snapshot referent values. With real addresses,
    // preserve pointer identity through the ordinary call and return path.
    // In particular, an address-taken result reference must store the returned
    // pointer in its cell, not a selected pointee value.
    if uses_real_address_reference_model(ctx.tcx)
        && !call_passes_borrowed_binding_arg(ctx, call.args)
    {
        return Ok(false);
    }
    let Some(promotion) = direct_scalar_ref_select_return(ctx, body, callee, call.args)? else {
        return Ok(false);
    };

    let cond_operand = call.args.get(promotion.cond_arg).ok_or_else(|| {
        format!(
            "promoted scalar reference return cond arg {} out of range",
            promotion.cond_arg
        )
    })?;
    let then_operand = call.args.get(promotion.then_arg).ok_or_else(|| {
        format!(
            "promoted scalar reference return then arg {} out of range",
            promotion.then_arg
        )
    })?;
    let else_operand = call.args.get(promotion.else_arg).ok_or_else(|| {
        format!(
            "promoted scalar reference return else arg {} out of range",
            promotion.else_arg
        )
    })?;

    let then_binding = borrowed_scalar_call_operand_binding(ctx, body, &then_operand.node, "then")?;
    let else_binding = borrowed_scalar_call_operand_binding(ctx, body, &else_operand.node, "else")?;
    let then_ty = scalar_binding_trust_ir_ty(ctx, body, then_binding.target)?;
    let else_ty = scalar_binding_trust_ir_ty(ctx, body, else_binding.target)?;
    if then_ty != promotion.pointee_ty || else_ty != promotion.pointee_ty {
        return Err(format!(
            "promoted scalar reference return type mismatch: then {then_ty:?}, else {else_ty:?}, \
             callee pointee {:?}",
            promotion.pointee_ty
        ));
    }

    if !call.destination.projection.is_empty() {
        return Err("promoted scalar reference return destination projection".to_owned());
    }
    if !matches!(
        place_rust_ty(ctx, body, call.destination).kind(),
        ty::Ref(..)
    ) {
        return Err("promoted scalar reference return with non-reference destination".to_owned());
    }

    let cond = lower_operand_to_value(ctx, body, block, &cond_operand.node)?;
    let then_value = value_for_borrow_target(ctx, then_binding.target)?;
    let else_value = value_for_borrow_target(ctx, else_binding.target)?;
    let selected = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Select {
            ty: promotion.pointee_ty,
            cond,
            then_val: then_value,
            else_val: else_value,
        })
        .with_result(selected),
    );

    ctx.clear_full_place_bindings(call.destination.local);
    ctx.bind_borrowed_scalar(
        call.destination.local,
        BorrowedScalarBinding {
            target: ScalarPlaceBinding::Local(call.destination.local),
            mutable: false,
            branch_varying: true,
        },
    );
    // The `Select` is the REFERENT's value, not an address: keep it out of
    // `scalar_values` (see `placeholder_borrow_values`).
    ctx.placeholder_borrow_values
        .insert(call.destination.local, selected);

    if let Some(target) = call.target {
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        block.body.push(InstrNode::new(Inst::Unreachable));
    }
    Ok(true)
}

fn borrowed_scalar_call_operand_binding(
    ctx: &MirLoweringCtx<'_>,
    body: &Body<'_>,
    operand: &Operand<'_>,
    role: &str,
) -> Result<BorrowedScalarBinding, String> {
    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        return Err(format!(
            "promoted scalar reference return {role} arg is not a place operand"
        ));
    };
    if !place.projection.is_empty() {
        return Err(format!(
            "promoted scalar reference return {role} arg uses projected reference operand"
        ));
    }
    ctx.borrowed_scalars
        .get(&place.local)
        .copied()
        .ok_or_else(|| {
            if is_entry_arg(body, place.local) || ctx.scalar_values.contains_key(&place.local) {
                format!(
                "promoted scalar reference return {role} arg requires scalar borrow materialization"
            )
            } else {
                format!("promoted scalar reference return {role} arg before scalar borrow binding")
            }
        })
}

fn lower_elided_scalar_return_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    destination: &Place<'tcx>,
    target: Option<mir::BasicBlock>,
    value: ValueId,
) -> Result<(), String> {
    let destination_ty = place_trust_ir_ty(ctx, body, destination)?;
    if trust_ir_ty_is_zero_sized(&destination_ty) {
        return Err("elided scalar-return call with non-scalar destination".to_owned());
    }

    let target_binding = prepare_assign_target(ctx, destination)?;
    if value != target_binding.value {
        block.body.push(
            InstrNode::new(Inst::Copy {
                ty: destination_ty,
                operand: value,
            })
            .with_result(target_binding.value),
        );
    }
    finish_assign_target(ctx, body, block, destination, target_binding)?;

    if let Some(target) = target {
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        block.body.push(InstrNode::new(Inst::Unreachable));
    }
    Ok(())
}

fn lower_borrowed_return_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    destination: &Place<'tcx>,
    target: Option<mir::BasicBlock>,
    binding: BorrowedScalarBinding,
) -> Result<(), String> {
    if !destination.projection.is_empty() {
        return Err("borrowed reference call destination projection".to_owned());
    }
    if !matches!(place_rust_ty(ctx, body, destination).kind(), ty::Ref(..)) {
        return Err("borrowed reference call with non-reference destination".to_owned());
    }

    ctx.clear_full_place_bindings(destination.local);
    ctx.bind_borrowed_scalar(destination.local, binding);
    if let Some(target) = target {
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
    } else {
        block.body.push(InstrNode::new(Inst::Unreachable));
    }
    Ok(())
}

fn borrowed_return_binding_for_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    callee: Instance<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
) -> Result<Option<BorrowedScalarBinding>, String> {
    let Some(arg_index) = direct_ref_return_arg_index(ctx, callee)? else {
        return Ok(None);
    };
    let Some(arg) = args.get(arg_index) else {
        return Err(format!(
            "reference-returning callee arg index {arg_index} out of range"
        ));
    };
    let (Operand::Copy(place) | Operand::Move(place)) = &arg.node else {
        return Ok(None);
    };
    if !place.projection.is_empty() {
        return Ok(None);
    }
    Ok(ctx.borrowed_scalars.get(&place.local).copied())
}

/// DIAGNOSTIC ONLY (`bridge-notes`): the REFERENT types behind the borrowed
/// bindings that made `call_passes_borrowed_binding_arg` true.
///
/// The two refusals this annotates name the SHAPE (a `&`/`&mut` of a scalarized
/// local reaching a reference-returning callee) but not the TYPE that could not
/// be celled — and the type is the whole question, because the cure is to widen
/// `compute_scalar_cell_locals` to exactly the referents the memory model can
/// give a real address to. Returns the empty string unless `bridge-notes` is on,
/// so the default message stays byte-identical for tests and the census.
fn borrowed_binding_arg_note<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
) -> String {
    if !bridge_notes_enabled() {
        return String::new();
    }
    let mut notes: Vec<String> = Vec::new();
    for (index, arg) in args.iter().enumerate() {
        let (Operand::Copy(p) | Operand::Move(p)) = &arg.node else {
            continue;
        };
        if !p.projection.is_empty() {
            continue;
        }
        let referent = if let Some(binding) = ctx.borrowed_scalars.get(&p.local) {
            match binding.target {
                ScalarPlaceBinding::Local(local) => Some((local, "scalar")),
                ScalarPlaceBinding::Projection { local, .. } => Some((local, "scalar-field")),
            }
        } else {
            ctx.borrowed_aggregates
                .get(&p.local)
                .map(|binding| (binding.source, "aggregate"))
        };
        let Some((referent, kind)) = referent else {
            continue;
        };
        let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
        notes.push(format!(
            "arg {index} = _{} ({kind} borrow of _{} : {referent_ty:?})",
            p.local.as_u32(),
            referent.as_u32()
        ));
    }
    if notes.is_empty() {
        String::new()
    } else {
        format!(" [borrowed bindings: {}]", notes.join("; "))
    }
}

/// Whether any argument of a call is an un-projected place carrying a
/// `borrowed_scalars` / `borrowed_aggregates` binding — a `&x` / `&mut x` of a
/// SCALARIZED (register-held) local, which `lower_scalar_reference_call_arg`
/// passes by MATERIALIZING the value into a temp alloca and (for `&mut`)
/// RELOADING the register binding from that temp after the call. Such a
/// reference is not a stable address the caller keeps reading through; the
/// temp is dead once the reload has happened.
fn call_passes_borrowed_binding_arg<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
) -> bool {
    args.iter().any(|arg| match &arg.node {
        Operand::Copy(p) | Operand::Move(p) if p.projection.is_empty() => {
            ctx.borrowed_scalars.contains_key(&p.local)
                || ctx.borrowed_aggregates.contains_key(&p.local)
        }
        _ => false,
    })
}

fn direct_scalar_ref_select_return<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    instance: Instance<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
) -> Result<Option<PromotedScalarRefReturn>, String> {
    // A FOREIGN callee (`extern "C" { fn ... }`) has no MIR body; the
    // `tcx.instance_mir` below would ICE type-checking a body-less foreign fn.
    // `is_foreign_item` items are `is_local()`, so reject them explicitly.
    if !instance.def_id().is_local() || ctx.tcx.is_foreign_item(instance.def_id()) {
        return Ok(None);
    }
    // `Ty::fn_sig` ICEs on a coroutine resume body (`ty::Coroutine`, local). Bail
    // for any non-`fn` callee — this scalar-ref-return promotion only applies to
    // ordinary functions.
    let instance_ty = instance.ty(ctx.tcx, ty::TypingEnv::fully_monomorphized());
    if !matches!(instance_ty.kind(), ty::FnDef(..) | ty::FnPtr(..)) {
        return Ok(None);
    }
    let sig = instance_ty.fn_sig(ctx.tcx);
    let sig = ctx.tcx.instantiate_bound_regions_with_erased(sig);
    let ty::Ref(_, inner, mutability) = sig.output().kind() else {
        return Ok(None);
    };
    // This is a PATTERN RECOGNIZER for the `if c { a } else { b }` scalar-ref
    // selector; a callee it does not recognize must DECLINE (`Ok(None)`) into the
    // general direct-call path, which passes and returns references as real
    // pointer values. It used to REFUSE every `&mut` return outright, which — when
    // compiling `core` itself, where every callee is local — rejected every
    // `as_mut`/`get_mut`/`deref_mut`-shaped call (124 census roots). The refusal
    // is only WARRANTED in one configuration: the call passes a borrow of a
    // SCALARIZED local (`borrowed_scalars` / `borrowed_aggregates`). That borrow
    // reaches the callee as a temp alloca whose contents are reloaded into the
    // register binding right after the call, so a `&mut` the callee derives from
    // it aliases a dead temp and every later `*ret = v` store is silently lost
    // (the miscompile [TCG-REFRET-WRAP] below guards for the WRAPPED form). Keep
    // that refusal, verbatim; with no such argument every reference the callee
    // receives is a genuine address (a memory-backed slot, a celled scalar, an
    // entry-arg or bound pointer) and the returned `&mut` is a genuine address
    // too, so the general path is sound.
    if matches!(mutability, rustc_hir::Mutability::Mut) {
        if call_passes_borrowed_binding_arg(ctx, args) {
            return Err(format!(
                "promoted mutable scalar reference return is unsupported{}",
                borrowed_binding_arg_note(ctx, body, args)
            ));
        }
        return Ok(None);
    }
    let inner = ctx.monomorphize_ty(*inner);
    // A callee returning a FAT reference — `&[T]` / `&str` / `&dyn Trait` / a
    // reference to an unsized-tail struct (`&CStr`, `&ByteStr`) — is NOT a
    // candidate for this promotion at all: the promotion `Select`s ONE scalar
    // pointer between two `&scalar` arguments, whereas a fat reference is a
    // `{ data, metadata }` pair the ordinary direct-call path already returns
    // through the memory-backed `{ data, len }` slot machinery (rule (3) of
    // `compute_memory_backed_locals` + `fat_ptr_or_memory_aggregate_layout`).
    // Before this check, every call to such a callee died here on the pointee's
    // OWN type-mapping refusal (`Ty::[u8]` / `Ty::str` — an unsized type has no
    // scalar mapping), which turned an inapplicable pattern into a hard refusal
    // of the whole caller (132 `core` roots at the first census). Declining the
    // promotion is the only change: nothing about the call is decided here, so
    // an unsized return the ordinary path cannot lower still fails closed THERE,
    // with its own message.
    if !inner.is_sized(ctx.tcx, ty::TypingEnv::fully_monomorphized()) {
        return Ok(None);
    }
    // ...and a referent that is itself a WIDE POINTER (`&&dyn Debug`, `&&[T]`).
    // Such a referent IS sized, so the guard above lets it through, but it is TWO
    // lanes — and the `Select` below threads ONE scalar referent value, so the
    // promotion cannot represent it. Declining is the same disposition the unsized
    // case gets and for the same reason; the ordinary call path still handles the
    // reference, or fails closed THERE with its own message.
    //
    // Before this, such a referent died on the pointee's own type-mapping refusal
    // (`Ty::dyn …`), which turned an INAPPLICABLE pattern into a hard refusal of
    // the whole caller — the identical failure mode, and the identical fix, as the
    // unsized guard directly above (which was worth 132 `core` roots at the first
    // census). `<slice::Iter<&dyn Debug> as Iterator>::next` is the measured case.
    if is_wide_pointer_memory_leaf_ty(ctx.tcx, inner) {
        return Ok(None);
    }
    // A shared reference to a (sized) AGGREGATE pointee is never selected by
    // VALUE here (the `Select` below threads a single scalar referent); it is a
    // pointer the general call path already handles — decline rather than
    // refuse, UNLESS the call passes a borrow of a SCALARIZED local
    // (`borrowed_scalars` / `borrowed_aggregates`). That borrow reaches the
    // callee as a materialized temp, so a `&Aggregate` the callee derives from it
    // is the TEMP's address: "a shared reference cannot be stored through" was
    // the argument for declining unconditionally, and it is false for interior
    // mutability — the review's `adv_ref6g_cell_ret.rs` (`view(&s).c.set(60)`)
    // wrote the temp and the register copy never saw it (`b=1` for `b=60`).
    // `compute_memory_backed_locals` (4i)/(4j) now memory-backs a `!Freeze`
    // referent and any referent whose `&` reaches a reference-returning callee,
    // so a `borrowed_*` binding here means the memory model could NOT represent
    // the referent — the baseline refusal is the right disposition for it.
    // A wide-pointer referent is also a memory value with two lanes. The
    // returned reference is thin and must keep the address of that pair;
    // selecting one scalar referent here would lose its metadata. Leave it
    // to the ordinary call path, retaining the temporary-borrow refusal.
    if is_fat_pointer_memory_leaf_ty(inner)
        || scalarized_aggregate_kind_name(ctx.tcx, inner)?.is_some()
    {
        if call_passes_borrowed_binding_arg(ctx, args) {
            return Err(format!(
                "promoted shared aggregate reference return from a scalarized borrow is \
                 unsupported (the callee would return the address of a call temp){}",
                borrowed_binding_arg_note(ctx, body, args)
            ));
        }
        return Ok(None);
    }
    let pointee_ty = rust_ty_to_trust_ir_ty(ctx.tcx, inner)?;
    if pointee_ty.bit_width().is_none() {
        // A THIN pointer referent (`*const T` / `&T` with `T: Sized`) is a plain
        // pointer-width scalar — the `Select` in
        // `lower_promoted_scalar_ref_return_call` threads the referent VALUE
        // exactly like an integer referent, which this gate already accepts.
        // trust-ir 6ed4bf0 made `bit_width()` None for pointer-likes,
        // mechanically false-rejecting this scalarizable case.
        // A FAT pointer referent (`&str`/`&[T]`/`&dyn`) is a two-lane value that
        // would lose its metadata lane if selected as one scalar —
        // `layout_is_thin_pointer_value` discriminates by rustc's layout, which
        // catches every fat form (slice/str/dyn/unsized-struct), not just the
        // slice/str ones `is_slice_reference_ty` knows.
        let inner_is_thin_pointer = is_pointer_like_trust_ir_ty(&pointee_ty)
            && layout_is_thin_pointer_value(ctx.tcx, inner);
        if !inner_is_thin_pointer {
            return Err(format!(
                "promoted scalar reference return target is not scalarizable: {pointee_ty:?}"
            ));
        }
    }

    let body = ctx.tcx.instance_mir(instance.def);
    let start = body
        .basic_blocks
        .get(mir::START_BLOCK)
        .ok_or_else(|| "promoted scalar reference return missing start block".to_owned())?;
    let TerminatorKind::SwitchInt { discr, targets } = &start.terminator().kind else {
        return Ok(None);
    };
    let Some(cond_arg) = operand_arg_index(body, discr) else {
        return Ok(None);
    };
    if !matches!(sig.inputs()[cond_arg].kind(), ty::Bool) {
        return Ok(None);
    }

    let Some((then_target, else_target)) = bool_switch_targets(targets) else {
        return Ok(None);
    };
    let Some((then_arg, then_join)) = returned_ref_arg_from_block(body, then_target)? else {
        return Ok(None);
    };
    let Some((else_arg, else_join)) = returned_ref_arg_from_block(body, else_target)? else {
        return Ok(None);
    };
    if then_join != else_join {
        return Ok(None);
    }
    if let Some(join) = then_join {
        let join_data = &body.basic_blocks[join];
        if !join_data.statements.iter().all(is_storage_statement)
            || !matches!(join_data.terminator().kind, TerminatorKind::Return)
        {
            return Ok(None);
        }
    }

    validate_scalar_ref_return_arg(ctx, &sig, then_arg, inner)?;
    validate_scalar_ref_return_arg(ctx, &sig, else_arg, inner)?;

    Ok(Some(PromotedScalarRefReturn {
        cond_arg,
        then_arg,
        else_arg,
        pointee_ty,
    }))
}

fn operand_arg_index(body: &Body<'_>, operand: &Operand<'_>) -> Option<usize> {
    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        return None;
    };
    if !place.projection.is_empty() {
        return None;
    }
    callee_arg_index(body, place.local)
}

fn bool_switch_targets(targets: &mir::SwitchTargets) -> Option<(mir::BasicBlock, mir::BasicBlock)> {
    let mut then_target = None;
    let mut else_target = None;
    for (value, target) in targets.iter() {
        match value {
            0 => else_target = Some(target),
            1 => then_target = Some(target),
            _ => return None,
        }
    }
    match (then_target, else_target) {
        (None, Some(else_target)) => Some((targets.otherwise(), else_target)),
        (Some(then_target), None) => Some((then_target, targets.otherwise())),
        _ => None,
    }
}

fn returned_ref_arg_from_block(
    body: &Body<'_>,
    bb: mir::BasicBlock,
) -> Result<Option<(usize, Option<mir::BasicBlock>)>, String> {
    let data = &body.basic_blocks[bb];
    let mut returned_arg = None;
    for statement in &data.statements {
        let StatementKind::Assign(boxed) = &statement.kind else {
            if is_storage_statement(statement) {
                continue;
            }
            return Ok(None);
        };
        if returned_arg.is_some() {
            return Ok(None);
        }

        let (place, rvalue) = &**boxed;
        if place.local != Local::new(0) || !place.projection.is_empty() {
            return Ok(None);
        }
        let Rvalue::Use(Operand::Copy(source) | Operand::Move(source), _) = rvalue else {
            return Ok(None);
        };
        if !source.projection.is_empty() {
            return Ok(None);
        }
        let Some(arg_index) = callee_arg_index(body, source.local) else {
            return Ok(None);
        };
        returned_arg = Some(arg_index);
    }

    let Some(arg_index) = returned_arg else {
        return Ok(None);
    };
    if let Some(goto) = crate::mir_goto::view(&data.terminator().kind) {
        Ok(Some((arg_index, Some(goto.target()))))
    } else {
        match &data.terminator().kind {
            TerminatorKind::Return => Ok(Some((arg_index, None))),
            _ => Ok(None),
        }
    }
}

fn is_storage_statement(statement: &mir::Statement<'_>) -> bool {
    matches!(
        statement.kind,
        StatementKind::StorageLive(_) | StatementKind::StorageDead(_)
    )
}

fn validate_scalar_ref_return_arg<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    sig: &ty::FnSig<'tcx>,
    arg_index: usize,
    expected_inner: Ty<'tcx>,
) -> Result<(), String> {
    let Some(arg_ty) = sig.inputs().get(arg_index).copied() else {
        return Err(format!(
            "promoted scalar reference return arg index {arg_index} out of range"
        ));
    };
    let ty::Ref(_, inner, mutability) = arg_ty.kind() else {
        return Ok(());
    };
    if matches!(mutability, rustc_hir::Mutability::Mut) {
        return Err("promoted mutable scalar reference return arg is unsupported".to_owned());
    }
    let inner = ctx.monomorphize_ty(*inner);
    if inner != expected_inner {
        return Err(format!(
            "promoted scalar reference return arg type mismatch: {inner:?} vs {expected_inner:?}"
        ));
    }
    Ok(())
}

fn direct_ref_return_arg_index<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    instance: Instance<'tcx>,
) -> Result<Option<usize>, String> {
    // A FOREIGN callee (`extern "C" { fn ... }`) has no MIR body; the
    // `tcx.instance_mir` below would ICE type-checking a body-less foreign fn.
    // `is_foreign_item` items are `is_local()`, so reject them explicitly.
    if !instance.def_id().is_local() || ctx.tcx.is_foreign_item(instance.def_id()) {
        return Ok(None);
    }
    // `Ty::fn_sig` ICEs on a coroutine resume body (`ty::Coroutine`, local). Bail
    // for any non-`fn` callee.
    let instance_ty = instance.ty(ctx.tcx, ty::TypingEnv::fully_monomorphized());
    if !matches!(instance_ty.kind(), ty::FnDef(..) | ty::FnPtr(..)) {
        return Ok(None);
    }
    let sig = instance_ty.fn_sig(ctx.tcx);
    let sig = ctx.tcx.instantiate_bound_regions_with_erased(sig);
    if !matches!(sig.output().kind(), ty::Ref(..)) {
        return Ok(None);
    }

    let body = ctx.tcx.instance_mir(instance.def);
    // Call elision is only sound for a literal identity helper. Branches,
    // loops, and unreachable blocks must use the normal call path and fail
    // closed until references have real ABI/memory lowering.
    let mut blocks = body.basic_blocks.iter();
    let Some(data) = blocks.next() else {
        return Ok(None);
    };
    if blocks.next().is_some() || !matches!(data.terminator().kind, TerminatorKind::Return) {
        return Ok(None);
    }

    let mut returned_arg = None;
    for statement in &data.statements {
        let StatementKind::Assign(boxed) = &statement.kind else {
            if matches!(
                &statement.kind,
                StatementKind::StorageLive(_) | StatementKind::StorageDead(_)
            ) {
                continue;
            }
            return Ok(None);
        };
        if returned_arg.is_some() {
            return Ok(None);
        }

        let (place, rvalue) = &**boxed;
        if place.local != Local::new(0) || !place.projection.is_empty() {
            return Ok(None);
        }
        let Rvalue::Use(Operand::Copy(source) | Operand::Move(source), _) = rvalue else {
            return Ok(None);
        };
        if !source.projection.is_empty() {
            return Ok(None);
        }
        let Some(arg_index) = body.args_iter().position(|arg| arg == source.local) else {
            return Ok(None);
        };
        returned_arg = Some(arg_index);
    }
    Ok(returned_arg)
}

fn direct_uniform_union_call_result<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    caller_body: &Body<'tcx>,
    block: &mut Block,
    callee: Instance<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
) -> Result<Option<ValueId>, String> {
    // A FOREIGN callee (declared in an `extern "C" { fn ... }` block) has NO MIR
    // body: the `tcx.instance_mir(callee.def)` below would trigger `mir_built` ->
    // typeck of a body-less foreign fn, which ICEs ("can't type-check body of
    // ..."). A foreign item is `is_local()` (it is declared in this crate), so the
    // local check alone lets it through — reject it explicitly. It cannot be a
    // scalarized-union return helper anyway; it falls through to the generic
    // external-symbol call emission.
    if !callee.def_id().is_local() || ctx.tcx.is_foreign_item(callee.def_id()) {
        return Ok(None);
    }

    // `Ty::fn_sig` ICEs on a callee whose type is NOT a `FnDef`/`FnPtr` — a
    // coroutine body (the post-`StateTransform` `resume` fn) is `ty::Coroutine`,
    // which has no `fn_sig`. This union-result helper only applies to ordinary
    // named functions, so bail for any non-`fn`-typed callee (the resume body then
    // falls through to the generic direct-call emission).
    let callee_ty = callee.ty(ctx.tcx, ty::TypingEnv::fully_monomorphized());
    if !matches!(callee_ty.kind(), ty::FnDef(..) | ty::FnPtr(..)) {
        return Ok(None);
    }
    let sig = callee_ty.fn_sig(ctx.tcx);
    let sig = ctx.tcx.instantiate_bound_regions_with_erased(sig);
    let callee_body = ctx.tcx.instance_mir(callee.def);
    let mut blocks = callee_body.basic_blocks.iter();
    let Some(data) = blocks.next() else {
        return Ok(None);
    };
    if blocks.next().is_some() || !matches!(data.terminator().kind, TerminatorKind::Return) {
        return Ok(None);
    }

    let mut return_rvalue = None;
    for statement in &data.statements {
        let StatementKind::Assign(boxed) = &statement.kind else {
            if matches!(
                &statement.kind,
                StatementKind::StorageLive(_) | StatementKind::StorageDead(_)
            ) {
                continue;
            }
            return Ok(None);
        };
        let (place, rvalue) = &**boxed;
        if place.local != Local::new(0) || !place.projection.is_empty() {
            return Ok(None);
        }
        if return_rvalue.replace(rvalue).is_some() {
            return Ok(None);
        }
    }

    let Some(return_rvalue) = return_rvalue else {
        return Ok(None);
    };
    match return_rvalue {
        Rvalue::Aggregate(kind, operands) if matches!(&**kind, mir::AggregateKind::Adt(..)) => {
            let mir::AggregateKind::Adt(def_id, _, _, _, active_field) = &**kind else {
                unreachable!();
            };
            let adt = ctx.tcx.adt_def(*def_id);
            if !adt.is_union() || active_field.is_none() || operands.len() != 1 {
                return Ok(None);
            }
            let Ok(Some(_)) = uniform_scalar_union_layout(ctx.tcx, sig.output()) else {
                return Ok(None);
            };
            let Some(value) = lower_callee_arg_operand_to_call_value(
                ctx,
                caller_body,
                block,
                callee_body,
                args,
                &operands[FieldIdx::new(0)],
            )?
            else {
                return Ok(None);
            };
            Ok(Some(value))
        }
        Rvalue::Use(Operand::Copy(source) | Operand::Move(source), _) => {
            let Some(arg_index) = callee_arg_index(callee_body, source.local) else {
                return Ok(None);
            };
            let Some(arg_ty) = sig.inputs().get(arg_index).copied() else {
                return Ok(None);
            };
            if source.projection.is_empty() {
                return Ok(None);
            }
            let Ok(Some(_)) = uniform_scalar_union_layout(ctx.tcx, arg_ty) else {
                return Ok(None);
            };
            if !matches!(
                source.projection.as_ref(),
                [ProjectionElem::Field(_, _)]
                    | [ProjectionElem::Downcast(_, _), ProjectionElem::Field(_, _)]
            ) {
                return Ok(None);
            }
            let Some(arg) = args.get(arg_index) else {
                return Err(format!(
                    "uniform-union helper arg index {arg_index} out of range"
                ));
            };
            lower_operand_to_value(ctx, caller_body, block, &arg.node).map(Some)
        }
        _ => Ok(None),
    }
}

fn lower_callee_arg_operand_to_call_value<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    caller_body: &Body<'tcx>,
    block: &mut Block,
    callee_body: &Body<'tcx>,
    args: &[rustc_span::Spanned<Operand<'tcx>>],
    operand: &Operand<'tcx>,
) -> Result<Option<ValueId>, String> {
    let (Operand::Copy(source) | Operand::Move(source)) = operand else {
        return Ok(None);
    };
    if !source.projection.is_empty() {
        return Ok(None);
    }
    let Some(arg_index) = callee_arg_index(callee_body, source.local) else {
        return Ok(None);
    };
    let Some(arg) = args.get(arg_index) else {
        return Err(format!(
            "uniform-union helper arg index {arg_index} out of range"
        ));
    };
    lower_operand_to_value(ctx, caller_body, block, &arg.node).map(Some)
}

fn callee_arg_index(body: &Body<'_>, local: Local) -> Option<usize> {
    body.args_iter().position(|arg| arg == local)
}

/// Whether a call's `func` operand names its callee STATICALLY: a `const fn`
/// item constant, OR a place (`move _1` / `copy (*_1)`) whose type is a
/// zero-sized function ITEM (`ty::FnDef`). The second form is exactly the
/// `self(args…)` of rustc's `FnPtrShim` `call` / `call_mut` / `call_once` bodies
/// over a fn item (`<fn(u32) -> IpAddr {IpAddr::V4} as FnOnce<(u32,)>>::call_once`):
/// the receiver is the ZST fn item, so the callee is fixed by its TYPE and the
/// call is a DIRECT call, not an indirect call through a loaded fn POINTER
/// (`ty::FnPtr`, a real address — that stays on `lower_indirect_call_terminator`).
///
/// A constant callee is static only when its TYPE is a fn item. A constant
/// of `fn(..)` POINTER type (`const F: fn(u32) -> u32 = f; F(x)`, an
/// associated `(T::OP)(x)`) is a pointer VALUE: rustc calls it through
/// `fn_abi_of_fn_ptr`, and so does the indirect lane, which materializes the
/// constant as the function's code address (`emit_const_alloc_addr`).
fn call_func_is_static_fn_item<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    func: &Operand<'tcx>,
) -> bool {
    match func {
        Operand::Constant(constant) => matches!(
            ctx.monomorphize_ty(constant.const_.ty()).kind(),
            ty::FnDef(..)
        ),
        Operand::Copy(place) | Operand::Move(place) => {
            matches!(
                ctx.monomorphize_ty(place_rust_ty(ctx, body, place)).kind(),
                ty::FnDef(..)
            )
        }
        // A compile-time `bool` (`RuntimeChecks(..)`) is never a callee.
        Operand::RuntimeChecks(_) => false,
    }
}

fn direct_callee_instance<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    func: &Operand<'tcx>,
    span: rustc_span::Span,
) -> Result<Instance<'tcx>, String> {
    let callee_ty = match func {
        Operand::Constant(constant) => ctx.monomorphize_ty(constant.const_.ty()),
        // A PLACE callee of function-ITEM type (see `call_func_is_static_fn_item`):
        // the ZST value carries nothing — the instance is resolved from the TYPE
        // exactly as for a constant. A place of any other type (a loaded `fn`
        // POINTER) is not a static callee and is refused here, as before.
        Operand::Copy(place) | Operand::Move(place) => {
            let place_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, place));
            if !matches!(place_ty.kind(), ty::FnDef(..)) {
                return Err("TerminatorKind::Call with non-constant callee".to_owned());
            }
            place_ty
        }
        Operand::RuntimeChecks(_) => {
            return Err("TerminatorKind::Call with non-constant callee".to_owned());
        }
    };
    let Some(item) = fn_items::view(callee_ty.kind()) else {
        return Err(format!(
            "TerminatorKind::Call with unsupported callee type {:?}",
            callee_ty
        ));
    };
    Ok(Instance::expect_resolve(
        ctx.tcx,
        ty::TypingEnv::fully_monomorphized(),
        item.def_id(),
        item.require_unbound_args("direct callee")?,
        span,
    ))
}

fn operand_rust_ty<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Result<Ty<'tcx>, String> {
    match operand {
        Operand::Copy(place) | Operand::Move(place) => Ok(place_rust_ty(ctx, body, place)),
        Operand::Constant(constant) => Ok(ctx.monomorphize_ty(constant.const_.ty())),
        // A `RuntimeChecks` operand is a compile-time `bool` (whether the session
        // enabled the corresponding runtime-check class), exactly as rustc models
        // it. Returning `bool` lets a `switchInt(RuntimeChecks(..))` discriminant
        // (the `unchecked_*::precondition_check` guard inside `wrapping_shl` and
        // friends) take the canonical bool-switch lowering path instead of failing
        // closed and dropping the reachable std helper to an undefined symbol.
        Operand::RuntimeChecks(_) => Ok(ctx.tcx.types.bool),
    }
}

fn rust_binop_to_trust_ir_binop(
    op: mir::BinOp,
    lhs_ty: Ty<'_>,
) -> Result<Option<TrustIrBinOp>, String> {
    let op = match op {
        mir::BinOp::Add | mir::BinOp::AddUnchecked => TrustIrBinOp::Add,
        mir::BinOp::Sub | mir::BinOp::SubUnchecked => TrustIrBinOp::Sub,
        mir::BinOp::Mul | mir::BinOp::MulUnchecked => TrustIrBinOp::Mul,
        mir::BinOp::Div if is_signed_integer(lhs_ty) => TrustIrBinOp::SDiv,
        mir::BinOp::Div => TrustIrBinOp::UDiv,
        mir::BinOp::Rem if is_signed_integer(lhs_ty) => TrustIrBinOp::SRem,
        mir::BinOp::Rem => TrustIrBinOp::URem,
        mir::BinOp::BitXor => TrustIrBinOp::Xor,
        mir::BinOp::BitAnd => TrustIrBinOp::And,
        mir::BinOp::BitOr => TrustIrBinOp::Or,
        mir::BinOp::Shl | mir::BinOp::ShlUnchecked => TrustIrBinOp::Shl,
        mir::BinOp::Shr | mir::BinOp::ShrUnchecked if is_signed_integer(lhs_ty) => {
            TrustIrBinOp::AShr
        }
        mir::BinOp::Shr | mir::BinOp::ShrUnchecked => TrustIrBinOp::LShr,
        mir::BinOp::Eq
        | mir::BinOp::Lt
        | mir::BinOp::Le
        | mir::BinOp::Ne
        | mir::BinOp::Ge
        | mir::BinOp::Gt => return Ok(None),
        other => return Err(format!("BinOp::{other:?}")),
    };
    Ok(Some(op))
}

fn rust_binop_to_trust_ir_overflow_op(op: mir::BinOp) -> Option<OverflowOp> {
    match op {
        mir::BinOp::AddWithOverflow => Some(OverflowOp::AddOverflow),
        mir::BinOp::SubWithOverflow => Some(OverflowOp::SubOverflow),
        mir::BinOp::MulWithOverflow => Some(OverflowOp::MulOverflow),
        _ => None,
    }
}

fn rust_binop_to_trust_ir_icmp(op: mir::BinOp, lhs_ty: Ty<'_>) -> Result<ICmpOp, String> {
    Ok(match op {
        mir::BinOp::Eq => ICmpOp::Eq,
        mir::BinOp::Ne => ICmpOp::Ne,
        mir::BinOp::Lt if is_signed_integer(lhs_ty) => ICmpOp::Slt,
        mir::BinOp::Lt => ICmpOp::Ult,
        mir::BinOp::Le if is_signed_integer(lhs_ty) => ICmpOp::Sle,
        mir::BinOp::Le => ICmpOp::Ule,
        mir::BinOp::Gt if is_signed_integer(lhs_ty) => ICmpOp::Sgt,
        mir::BinOp::Gt => ICmpOp::Ugt,
        mir::BinOp::Ge if is_signed_integer(lhs_ty) => ICmpOp::Sge,
        mir::BinOp::Ge => ICmpOp::Uge,
        other => return Err(format!("BinOp::{other:?}")),
    })
}

fn rust_float_binop_to_trust_ir_binop(op: mir::BinOp) -> Result<Option<TrustIrBinOp>, String> {
    let op = match op {
        mir::BinOp::Add => TrustIrBinOp::FAdd,
        mir::BinOp::Sub => TrustIrBinOp::FSub,
        mir::BinOp::Mul => TrustIrBinOp::FMul,
        mir::BinOp::Div => TrustIrBinOp::FDiv,
        // Floating-point remainder (`a % b`) has no native instruction. The
        // trust-ir adapter lowers `BinOp::FRem` to a call to the libm
        // `fmod`/`fmodf` symbol (resolved by the linker), which matches Rust's
        // IEEE-754 `%` semantics (sign of the dividend, NaN propagation).
        mir::BinOp::Rem => TrustIrBinOp::FRem,
        mir::BinOp::Eq
        | mir::BinOp::Lt
        | mir::BinOp::Le
        | mir::BinOp::Ne
        | mir::BinOp::Ge
        | mir::BinOp::Gt => return Ok(None),
        other => return Err(format!("BinOp::{other:?} on float operands")),
    };
    Ok(Some(op))
}

fn rust_binop_to_trust_ir_fcmp(op: mir::BinOp) -> Result<FCmpOp, String> {
    Ok(match op {
        mir::BinOp::Eq => FCmpOp::OEq,
        mir::BinOp::Ne => FCmpOp::UNe,
        mir::BinOp::Lt => FCmpOp::OLt,
        mir::BinOp::Le => FCmpOp::OLe,
        mir::BinOp::Gt => FCmpOp::OGt,
        mir::BinOp::Ge => FCmpOp::OGe,
        other => return Err(format!("BinOp::{other:?}")),
    })
}

fn rust_cast_to_trust_ir_cast(
    kind: mir::CastKind,
    src_rust_ty: Ty<'_>,
    src_ty: &TrustIrTy,
    dst_rust_ty: Ty<'_>,
    dst_ty: &TrustIrTy,
) -> Result<Option<CastOp>, String> {
    match kind {
        mir::CastKind::IntToInt => integer_cast_op(src_rust_ty, src_ty, dst_ty)
            .ok_or_else(|| format!("CastKind::IntToInt {src_ty:?} -> {dst_ty:?}")),
        mir::CastKind::IntToFloat => Err("CastKind::IntToFloat single-op lowering".to_owned()),
        mir::CastKind::FloatToInt => float_to_int_cast_op(dst_rust_ty, src_ty, dst_ty)
            .map(Some)
            .ok_or_else(|| format!("CastKind::FloatToInt {src_ty:?} -> {dst_ty:?}")),
        mir::CastKind::FloatToFloat => float_cast_op(src_ty, dst_ty)
            .ok_or_else(|| format!("CastKind::FloatToFloat {src_ty:?} -> {dst_ty:?}")),
        // A pointer-to-pointer cast (`*const T as *const U`) is the identity on
        // the pointer address. The trust-ir adapter lowers `CastOp::PtrToPtr` to
        // a machine Copy. Keep the typed source/result transition explicit in
        // TrustIR: the final Copy canonicalizer inserts PtrToPtr when needed.
        mir::CastKind::PtrToPtr
            if is_pointer_like_trust_ir_ty(src_ty) && is_pointer_like_trust_ir_ty(dst_ty) =>
        {
            Ok(None)
        }
        // The function item has already been reified to a code address. Rust's
        // `fn_ptr as *const T` cast transports that address to a thin raw pointer;
        // it neither reads code bytes nor supplies pointee access authority.
        mir::CastKind::FnPtrToPtr
            if matches!(src_rust_ty.kind(), ty::FnPtr(..))
                && matches!(dst_rust_ty.kind(), ty::RawPtr(..))
                && pointer_casts::can_transport_address(src_ty, dst_ty) =>
        {
            Ok(None)
        }
        // `Transmute` between layout-compatible scalars. This is how the `Box`
        // niche pointer is read (`NonNull<T> as *const T`) and how the MIR's
        // alignment/null debug-asserts reinterpret a pointer as a `usize` and
        // back. We map it to the matching concrete cast op the adapter lowers
        // (never `CastOp::Transmute`: the adapter lowers that only as an
        // equal-size reinterpretation and refuses validity-carrying leaves, so
        // the bridge keeps scalar transmutes on the concrete cast ops):
        //   * ptr  <-> ptr  : identity (no-op).
        //   * ptr  ->  int  : `PtrToInt` (same pointer width).
        //   * int  ->  ptr  : `IntToPtr`.
        //   * int  <-> int  : same-width reinterpret -> identity; differing width
        //                     is not a valid transmute and falls through to err.
        mir::CastKind::Transmute => transmute_cast_op(src_ty, dst_ty),
        // `fn(..) as unsafe fn(..)` — a safe-to-unsafe fn-pointer coercion. The
        // value is unchanged (both carriers are a pointer-width code pointer); the
        // coercion only relaxes the type. Identity copy (no instruction).
        mir::CastKind::PointerCoercion(PointerCoercion::UnsafeFnPointer, _)
            if is_pointer_like_trust_ir_ty(src_ty) && is_pointer_like_trust_ir_ty(dst_ty) =>
        {
            Ok(None)
        }
        // `ptr as usize` (`PointerExposeProvenance`) / `usize as *ptr`
        // (`PointerWithExposedProvenance`): a pointer<->integer reinterpret. Both
        // carriers are the same 64-bit address value; the provenance bookkeeping
        // these casts model has no machine effect. Map to the proven
        // `PtrToInt`/`IntToPtr` cast ops (the adapter lowers each to a register
        // move, the same encoding `Transmute` ptr<->int already uses). Width-guarded
        // to a 64-bit integer (the only valid pointer width on x86-64); any other
        // width is not a valid pointer reinterpret and falls through to err.
        mir::CastKind::PointerExposeProvenance
            if is_pointer_like_trust_ir_ty(src_ty)
                && dst_ty.is_integer()
                && dst_ty.bit_width() == Some(session_pointer_bits()) =>
        {
            Ok(Some(CastOp::PtrToInt))
        }
        mir::CastKind::PointerWithExposedProvenance
            if src_ty.is_integer()
                && src_ty.bit_width() == Some(session_pointer_bits())
                && is_pointer_like_trust_ir_ty(dst_ty) =>
        {
            Ok(Some(CastOp::IntToPtr))
        }
        other => Err(format!("CastKind::{other:?}")),
    }
}

/// `true` iff the trust-ir type occupies zero bytes: `Unit`/`Never`, or an
/// aggregate composed entirely of zero-sized fields (e.g. the
/// `Tuple([Unit, Unit])` env of a COMPOSED pair of non-capturing closures —
/// the `.map(F).filter(P)` fold glue's single upvar). Nothing is ever read
/// out of a zero-sized value, so it needs no memory-scalar representation.
fn trust_ir_ty_is_zero_sized(ty: &TrustIrTy) -> bool {
    match ty {
        TrustIrTy::Unit | TrustIrTy::Never => true,
        TrustIrTy::Tuple(fields) => fields.iter().all(trust_ir_ty_is_zero_sized),
        _ => false,
    }
}

/// Whether `ty` is a pointer-width pointer-like scalar (a thin pointer,
/// reference, or raw pointer). Plain `Ty::Ptr` plus the typed pointer variants.
fn is_pointer_like_trust_ir_ty(ty: &TrustIrTy) -> bool {
    runtime_pointer_value::is_thin_pointer(ty)
}

/// Map a `CastKind::Transmute` between two scalar trust-ir types to the concrete
/// cast op the adapter lowers, or `Ok(None)` for an identity reinterpret. Fails
/// closed for unsupported scalar reinterpretations and width changes.
fn transmute_cast_op(src_ty: &TrustIrTy, dst_ty: &TrustIrTy) -> Result<Option<CastOp>, String> {
    // An initialized scalar-union Bool carrier returned by `assume_init` has
    // the same value and representation as its Bool destination. This does not
    // admit an integer-to-Bool transmute or impose validity on arbitrary bytes.
    if *src_ty == TrustIrTy::Bool && *dst_ty == TrustIrTy::Bool {
        return Ok(None);
    }
    let src_ptr = is_pointer_like_trust_ir_ty(src_ty);
    let dst_ptr = is_pointer_like_trust_ir_ty(dst_ty);
    match (src_ptr, dst_ptr) {
        (true, true) => Ok(None),
        (true, false)
            if dst_ty.is_integer() && dst_ty.bit_width() == Some(session_pointer_bits()) =>
        {
            Ok(Some(CastOp::PtrToInt))
        }
        (false, true)
            if src_ty.is_integer() && src_ty.bit_width() == Some(session_pointer_bits()) =>
        {
            Ok(Some(CastOp::IntToPtr))
        }
        (false, false)
            if src_ty.is_integer()
                && dst_ty.is_integer()
                && src_ty.bit_width() == dst_ty.bit_width() =>
        {
            Ok(None)
        }
        // Same-width float<->int (and float<->float) bit reinterpret — e.g.
        // `f64::to_bits()` (F64->U64) / `f64::from_bits()` (U64->F64), `f32`
        // likewise, and the float predicates that lower through them. A scalar
        // float and a same-width integer occupy different register classes
        // (XMM vs GPR), so this is NOT a no-op: the adapter lowers `Bitcast` to
        // the cross-class move (MOVQ/MOVD xmm<->gpr) the x86 ISel emits via
        // `select_bitcast`, and that move is proven bit-preserving
        // ("MOVQ r64,xmm preserves bits", etc.). Width-changing or non-scalar
        // transmutes fall through to the error below.
        (false, false)
            if src_ty.bit_width() == dst_ty.bit_width()
                && (src_ty.is_float() || dst_ty.is_float())
                && (src_ty.is_float() || src_ty.is_integer())
                && (dst_ty.is_float() || dst_ty.is_integer()) =>
        {
            Ok(Some(CastOp::Bitcast))
        }
        _ => Err(format!(
            "CastKind::Transmute {src_ty:?} -> {dst_ty:?} (only equal-width ptr/int/float reinterprets)"
        )),
    }
}

/// Cast-relevant bit width of an integer-like trust-ir scalar, treating `Bool`
/// as 8 bits.
///
/// A Rust `bool` occupies a full byte holding `{0,1}`, and the trust-ir->machine
/// adapter sizes `Bool` as that byte (`cast_scalar_bits(Bool) == 8`) while
/// `Ty::bit_width` reports `1` for the abstract `i1`. Reading `Bool` as 8 bits
/// here makes `bool as u8` / `bool as i8` the same-width case, which
/// [`integer_cast_op`] spells as a `ZExt` of the canonical 0/1 (the one
/// spelling trust-ir admits; see there), while `bool as u16/u32/...` stays an
/// ordinary widening `ZExt`.
fn cast_int_bit_width(ty: &TrustIrTy) -> Option<u32> {
    if matches!(ty, TrustIrTy::Bool) {
        return Some(8);
    }
    ty.bit_width()
}

fn integer_cast_op(
    src_rust_ty: Ty<'_>,
    src_ty: &TrustIrTy,
    dst_ty: &TrustIrTy,
) -> Option<Option<CastOp>> {
    let src_width = cast_int_bit_width(src_ty)?;
    let dst_width = cast_int_bit_width(dst_ty)?;
    if src_width == dst_width && *src_ty == TrustIrTy::Bool {
        // `bool as u8` / `bool as i8`, on every target. trust-ir gives `Bool`
        // one bit of value in one byte of storage and defines no bit-image
        // reinterpretation of a bool lane: the validator refuses a `Bitcast`
        // from `Bool` (`CastLayoutUnsupported`, "spell int<->bool as
        // trunc/zext"), as do the reference interpreter and the wasm lane.
        // `ZExt` of the canonical 0/1 is the same value. The native adapter
        // admits `ZExt` from `Bool` to any wider integer, `I8`/`U8` included,
        // and lowers it to `Uextend` from `B1`, a copy of the 0/1 register: the
        // value the old same-width `Bitcast` moved.
        return Some(Some(CastOp::ZExt));
    }
    if src_width == dst_width {
        // Same width: identical types are a plain `Copy`; a signedness change
        // (`u64 as i64`) is a canonical `Bitcast` — the validator rejects a
        // `Copy` whose declared type differs from its operand's
        // (`OperandTypeMismatch`), which every corpus CGU used to carry.
        // Lowering is identical: isel emits a GPR `MovR` for an equal-width
        // integer `Bitcast`, and the refinement model treats it as identity.
        return Some(if src_ty == dst_ty {
            None
        } else {
            Some(CastOp::Bitcast)
        });
    }
    if dst_width < src_width {
        return Some(Some(CastOp::Trunc));
    }
    if is_signed_integer(src_rust_ty) {
        Some(Some(CastOp::SExt))
    } else {
        Some(Some(CastOp::ZExt))
    }
}

/// The trust-ir cast of MIR `Cast(FloatToInt)`, Rust's `x as {iN,uN}`: it
/// SATURATES (NaN -> 0, out of range -> MIN/MAX, else toward zero; Rust 1.45),
/// which is trust-ir's `FPToSISat`/`FPToUISat` (the destination's signedness
/// picks) at every width. Never the raw `FPToSI`/`FPToUI`: those are UNDEFINED
/// for NaN and out-of-range values (pinned trust-ir `CastOp::FPToSISat` doc,
/// `docs/ub-numerics-policy.md` §2; its reference interpreter reports UB), so
/// they would add UB the Rust program does not have, whatever one backend's
/// lowering of the raw op happens to do.
fn float_to_int_cast_op(
    dst_rust_ty: Ty<'_>,
    src_ty: &TrustIrTy,
    dst_ty: &TrustIrTy,
) -> Option<CastOp> {
    if !src_ty.is_float() || !dst_ty.is_integer() {
        return None;
    }
    if is_signed_integer(dst_rust_ty) {
        Some(CastOp::FPToSISat)
    } else {
        Some(CastOp::FPToUISat)
    }
}

fn float_cast_op(src_ty: &TrustIrTy, dst_ty: &TrustIrTy) -> Option<Option<CastOp>> {
    if !src_ty.is_float() || !dst_ty.is_float() {
        return None;
    }
    let src_width = src_ty.bit_width()?;
    let dst_width = dst_ty.bit_width()?;
    if src_width == dst_width {
        return Some(None);
    }
    if dst_width > src_width {
        Some(Some(CastOp::FPExt))
    } else {
        Some(Some(CastOp::FPTrunc))
    }
}

fn integer_trust_ir_ty_for_width(signed: bool, width: u64) -> Option<TrustIrTy> {
    Some(match (signed, width) {
        (true, 32) => TrustIrTy::I32,
        (true, 64) => TrustIrTy::I64,
        (true, 128) => TrustIrTy::I128,
        (false, 32) => TrustIrTy::U32,
        (false, 64) => TrustIrTy::U64,
        (false, 128) => TrustIrTy::U128,
        _ => return None,
    })
}

fn pointer_metadata_len_from_operand<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Result<u64, String> {
    match operand {
        Operand::Copy(place) | Operand::Move(place) => {
            pointer_metadata_len_from_place(ctx, body, place)
        }
        // The length metadata of a const slice / array reference. A `&str` /
        // `&[T]` slice literal carries it directly as `ConstValue::Slice { meta }`
        // (what `str::len` / a slice bounds check reads); a const `&[T; N]`
        // pointer being unsized to `&[T]` contributes the array's static length.
        Operand::Constant(constant) => {
            let evaluated = ctx.eval_const_operand(constant);
            if let Some(meta) = const_slice_metadata_len(&evaluated) {
                return Ok(meta);
            }
            let operand_ty = ctx.monomorphize_ty(constant.const_.ty());
            if let Some(len) = static_array_len_from_ty(ctx, operand_ty)? {
                return Ok(len);
            }
            Err("UnOp::PtrMetadata constant operand".to_owned())
        }
        Operand::RuntimeChecks(_) => Err("Operand::RuntimeChecks".to_owned()),
    }
}

/// The slice-length metadata of a `&str` / `&[T]` const slice literal, if the
/// constant is a `ConstValue::Slice` (a fat pointer whose `meta` is the length).
fn const_slice_metadata_len(const_: &mir::Const<'_>) -> Option<u64> {
    match const_ {
        mir::Const::Val(ConstValue::Slice { meta, .. }, _) => Some(*meta),
        _ => None,
    }
}

fn pointer_metadata_len_from_place<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> Result<u64, String> {
    if !place.projection.is_empty() {
        return Err("pointer metadata operand projection".to_owned());
    }
    if let Some(len) = ctx.pointer_metadata_lengths.get(&place.local).copied() {
        return Ok(len);
    }
    if let Some(len) = static_array_len_from_place(ctx, body, place)? {
        return Ok(len);
    }

    let ty = place_rust_ty(ctx, body, place);
    if is_slice_reference_ty(ty) {
        return Err("slice pointer metadata before known array length".to_owned());
    }
    Err(format!("pointer metadata unsupported operand type {ty:?}"))
}

fn static_array_len_from_place<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> Result<Option<u64>, String> {
    if !place.projection.is_empty() {
        return Ok(None);
    }
    static_array_len_from_ty(ctx, place_rust_ty(ctx, body, place))
}

fn static_array_len_from_ty<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<u64>, String> {
    let ty = ctx.monomorphize_ty(ty);
    match ty.kind() {
        ty::Array(_, len) => len
            .try_to_target_usize(ctx.tcx)
            .map(Some)
            .ok_or_else(|| format!("array length is not target-usize evaluable: {ty:?}")),
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => static_array_len_from_ty(ctx, *inner),
        _ => Ok(None),
    }
}

fn is_slice_reference_ty(ty: Ty<'_>) -> bool {
    if slice_tail::is_pointer(ty) {
        return true;
    }
    match ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => {
            matches!(inner.kind(), ty::Slice(_) | ty::Str)
                || pointee_is_transparent_unsized_slice_wrapper(*inner)
        }
        _ => false,
    }
}

/// Whether a reference POINTEE is a `#[repr(transparent)]` UNSIZED struct that
/// wraps a slice / `str` — `core::ffi::CStr { inner: [c_char] }`,
/// `core::bstr::ByteStr([u8])`, `std::ffi::OsStr { inner: Slice { inner: [u8] } }`,
/// `std::path::Path { inner: OsStr }` — so that a `&CStr` / `*const Path` is the
/// SAME `{ data, len }` `ScalarPair` as the `&[T]` / `&str` it wraps.
///
/// # Why this exists
///
/// Every fat-pointer decision in the bridge keys on `is_slice_reference_ty`, and
/// that predicate used to answer "slice" only for a SYNTACTIC `[T]` / `str`
/// pointee. A `&CStr` therefore read as a THIN reference to an aggregate, the
/// pointee flattener descended into the struct, and the first field it met was
/// the unsized tail `[i8]` — which has no scalar type, so every consumer that
/// typed the reference at all (`_4 = const Slice {..}: &CStr`, a `&CStr`
/// parameter in `classify_func_ty`, a const `&CStr` call argument) refused with
/// the bare `Ty::[i8]`. That refusal is what stopped the stage1 `library/std`
/// build at `std_detect::detect::os::detect_features` (the darwin aarch64
/// `_sysctlbyname(c"hw.optional.…")` probes, MIR-inlined into their caller).
///
/// # Why it is sound to answer "slice"
///
/// `repr(transparent)` is rustc's guarantee that the struct has the layout and
/// ABI of its single non-1-ZST field; for an UNSIZED such struct that field is
/// the unsized tail, it sits at byte offset 0, and the pointer metadata of
/// `&Wrapper` IS the tail's metadata (a `usize` length for a slice/`str` tail).
/// So the data pointer, the length, and the two-lane image are byte-identical
/// to the wrapped slice's, and every fat-pointer path — the const-slice binding,
/// the `{ data, len }` slot, the register-pair ABI, `PtrMetadata` — is exactly
/// right for it. `transparent_unsized_wrapper_tail_field` still reads the
/// offset off `tcx.layout_of` rather than assuming it, and fails closed (no
/// peel, so the pointer stays refused as before) on anything else: a sized or
/// generic wrapper, a tail that is not a slice/`str` (a `dyn Trait` tail keeps
/// the trait-object path), more than one unsized field, or a layout rustc
/// cannot produce.
///
/// # Why the `TyCtxt` comes from the implicit context
///
/// `is_slice_reference_ty` / `is_slice_or_str_fat_ptr_ty` have ~60 callers,
/// many of them `match` guards with no `tcx` in scope, and the peel needs the
/// wrapper's FIELD type — a `type_of` query. Threading a `tcx` through every
/// caller is a mechanical rewrite of the whole fat-pointer surface for one
/// predicate; the implicit context is what rustc's own `Debug for Ty` uses, and
/// this bridge formats a `Ty` in nearly every diagnostic it emits, so on every
/// thread where this predicate can run the context is already set. When it is
/// NOT (`with_opt` -> `None`) the answer is `false`: the reference stays a
/// refused thin-to-unsized pointer, never a fat pointer read as thin.
///
/// Only a NON-generic wrapper is peeled (`args.is_empty()`), so the DefId-based
/// re-derivation inside the context closure names exactly the same interned
/// type as the `Ty` the caller holds.
fn pointee_is_transparent_unsized_slice_wrapper(pointee: Ty<'_>) -> bool {
    let ty::Adt(adt, args) = pointee.kind() else {
        return false;
    };
    if !adt.is_struct() || !adt.repr().transparent() || !args.is_empty() {
        return false;
    }
    let did = adt.did();
    rustc_middle::ty::tls::with_opt(|tcx| {
        let Some(tcx) = tcx else {
            // Fail-closed (the reference stays refused as thin-to-unsized), but
            // never silently: a missing context here flips a FAT pointer's
            // classification, and the only thing keeping that from becoming a
            // truncated read is that the thin arm still refuses — an invariant
            // nothing pins. Say so where it can be seen.
            if bridge_notes_enabled() {
                eprintln!(
                    "rustc_codegen_trust_cg: no TyCtxt in implicit context while classifying \
                     a repr(transparent) unsized wrapper pointee; answering `false` (thin)"
                );
            }
            return false;
        };
        let wrapper = Ty::new_adt(tcx, tcx.adt_def(did), tcx.mk_args(&[]));
        transparent_unsized_wrapper_slice_or_str(tcx, wrapper).is_some()
    })
}

/// ONE peel step of `pointee_is_transparent_unsized_slice_wrapper`: the
/// `(field index, field type)` of the single UNSIZED field of a non-generic
/// `#[repr(transparent)]` unsized struct, verified to sit at byte offset 0 of
/// rustc's own layout. `None` for anything else (fail closed).
fn transparent_unsized_wrapper_tail_field<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<(FieldIdx, Ty<'tcx>)> {
    let env = ty::TypingEnv::fully_monomorphized();
    let ty::Adt(adt, args) = ty.kind() else {
        return None;
    };
    if !adt.is_struct() || !adt.repr().transparent() || !args.is_empty() {
        return None;
    }
    if ty.is_sized(tcx, env) {
        return None;
    }
    let mut tail = None;
    for (idx, field) in adt.non_enum_variant().fields.iter_enumerated() {
        let field_ty = field.ty(tcx, *args).skip_normalization();
        if field_ty.is_sized(tcx, env) {
            continue;
        }
        if tail.is_some() {
            return None;
        }
        tail = Some((idx, field_ty));
    }
    let (idx, field_ty) = tail?;
    // `repr(transparent)` puts the one non-ZST field at offset 0; read it off the
    // layout rather than assume it, and refuse any layout shape that is not a
    // plain struct.
    let layout = tcx.layout_of(env.as_query_input(ty)).ok()?;
    let rustc_abi::FieldsShape::Arbitrary { .. } = layout.fields else {
        return None;
    };
    if layout.fields.offset(idx.index()).bytes() != 0 {
        return None;
    }
    Some((idx, field_ty))
}

/// The `[T]` / `str` a `#[repr(transparent)]` unsized-wrapper chain bottoms out
/// at (`CStr` -> `[c_char]`; `Path` -> `OsStr` -> `Slice` -> `[u8]`), or `None`
/// when `ty` is not such a wrapper. A bare `[T]` / `str` is NOT a wrapper and
/// returns `None` — callers that also accept the bare slice test for it first.
/// Bounded: a wrapper chain deeper than this is not a shape we model.
fn transparent_unsized_wrapper_slice_or_str<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<Ty<'tcx>> {
    let mut cur = ty;
    let mut peeled = 0usize;
    for _ in 0..8 {
        match cur.kind() {
            ty::Slice(_) | ty::Str => return (peeled > 0).then_some(cur),
            ty::Adt(..) => {
                let (_, tail) = transparent_unsized_wrapper_tail_field(tcx, cur)?;
                cur = tail;
                peeled += 1;
            }
            _ => return None,
        }
    }
    None
}

/// `(*c).inner` / `(*p).inner.inner…` — the projection of a slice/`str` reborrow
/// (`&raw const (*c).inner` — `CStr::as_ptr`'s `self.inner.as_ptr()`; `&(*c).inner`
/// — `CStr::count_bytes`'s `self.inner.len()`; the `Path` -> `OsStr` -> `Slice`
/// chain) that reaches the slice THROUGH the unsized tail field(s) of a
/// `#[repr(transparent)]` wrapper fat pointer `c`. Every admitted step is the
/// wrapper's single unsized field at byte offset 0
/// (`transparent_unsized_wrapper_tail_field`), and the metadata of an unsized
/// field projection is the base pointer's own, so the projected place denotes
/// EXACTLY the `{ data, len }` pair `c` carries: the reborrow is the identity on
/// the fat pointer, and the consumers that copy a `(*fat)` reborrow's two lanes
/// (rule 3b's slot classification, `lower_memory_slice_assign`'s reborrow arm)
/// are exactly right for it. `false` for the bare `(*c)` reborrow (the callers'
/// existing arm), for a base that is not a fat pointer, for a `Field` that is not
/// the wrapper's unsized tail, for any other projection element, and for a chain
/// that does not bottom out at a slice/`str` — all of which keep their existing
/// (fail-closed) handling.
fn fat_ptr_tail_reborrow_projection<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    src: &Place<'tcx>,
) -> bool {
    let [ProjectionElem::Deref, fields @ ..] = src.projection.as_ref() else {
        return false;
    };
    if fields.is_empty() {
        return false;
    }
    let src_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
    if !is_slice_or_str_fat_ptr_ty(src_ty) {
        return false;
    }
    let (ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _)) = src_ty.kind() else {
        return false;
    };
    let mut cur = ctx.monomorphize_ty(*pointee);
    for elem in fields {
        let ProjectionElem::Field(idx, _) = elem else {
            return false;
        };
        let Some((tail_idx, tail_ty)) = transparent_unsized_wrapper_tail_field(ctx.tcx, cur) else {
            return false;
        };
        if *idx != tail_idx {
            return false;
        }
        cur = ctx.monomorphize_ty(tail_ty);
    }
    matches!(cur.kind(), ty::Slice(_) | ty::Str)
        || transparent_unsized_wrapper_slice_or_str(ctx.tcx, cur).is_some()
}

// ── Runtime fat-pointer (`&[T]` / `&str`) VALUES ────────────────────────────
//
// A `&[T]` / `&mut [T]` / `&str` (or the raw `*const [T]` / `*mut [T]` / `*const
// str`) is a *fat* pointer: a `{ data: *const T, meta: usize }` two-eightbyte
// value. The CONST-slice path (a slice whose length is a compile-time constant
// and that never crosses a real function boundary) represents the value as just
// its DATA half (a `Ptr` scalar in `scalar_values`) plus the length in the
// `pointer_metadata_lengths` side table — see `lower_const_slice_use` /
// `lower_pointer_unsize`. That representation is kept INTACT for the inlined /
// const-length corpus cases.
//
// When a slice fat pointer crosses a real function boundary — a PARAMETER, a
// RETURN, a CALL argument, or it is otherwise materialized into a real local /
// is address-taken — its length is a RUNTIME value, so the data-only
// representation is insufficient. Such a boundary-crossing slice local is
// instead MEMORY-BACKED with a 16-byte / 8-aligned `{ data: Ptr, meta: I64 }`
// slot (`fat_ptr_slot_ty`). Reusing the memory-aggregate slot machinery means
// the SAME verified SysV two-eightbyte register-pair / sret / stack ABI that
// already carries `Result<i64,i64>`-shaped by-value aggregates carries the fat
// pointer (data in the first eightbyte, len in the second), with NO new ABI
// classification code.
//
// `fat_ptr_slice_or_str_pointee` returns the element type of the slice/str a
// fat-pointer type points at (the `str` case loads bytes, element type `u8`);
// `is_slice_or_str_fat_ptr_ty` is the predicate that a type is a slice/str fat
// pointer at all.

/// The element type a `&[T]` / `&str` (and raw-pointer / `&mut` variants) fat
/// pointer addresses: `T` for `[T]`, `u8` for `str`. Returns `None` for any
/// non-slice/str pointer (a thin reference) so callers fall through.
fn fat_ptr_slice_or_str_pointee<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    match ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => match inner.kind() {
            ty::Slice(element) => Some(*element),
            ty::Str => Some(tcx.types.u8),
            _ => None,
        },
        _ => None,
    }
}

/// A bounded wrapper chain whose image is a pointer with length metadata.
/// Transparent structs inherit their payload's representation. Linux AArch64
/// also admits a nontransparent struct when rustc proves a single non-ZST
/// field at offset zero with identical 16-byte, 8-aligned ScalarPair layout.
/// This includes owning carriers such as Box/Rc/Arc without relying on names.
///
/// # Why this is separate from `is_slice_or_str_fat_ptr_ty`
///
/// That predicate has ~55 callers driving lowering decisions all over the bridge.
/// Teaching IT to peel newtypes would make `NonNull<[u8]>` read as a slice fat
/// pointer in every one of them at once — a far larger behavioural change than
/// the hole being closed. This predicate is used at exactly ONE site (the
/// memory-aggregate LEAF classification), where the question is purely "does this
/// field have the two-lane `{data, len}` layout the leaf walker can load and
/// store", and the answer for a transparent newtype is the same as for the
/// pointer it wraps.
///
/// `repr(transparent)` is what makes this sound: rustc guarantees such a struct
/// has the SAME layout and ABI as its single non-zero-sized field, so
/// `NonNull<[u8]>` genuinely IS the `*const [u8]` `ScalarPair`. The caller
/// separately requires `BackendRepr::ScalarPair`, so a newtype whose layout is
/// anything else still falls through.
///
/// Peels `ty::Pat` too (`NonNull`'s field is `*const T is !null`, a pattern type
/// over the raw pointer), mirroring the `ty::Pat` arm in `rust_ty_to_trust_ir_ty`.
fn transparent_newtype_is_slice_fat_ptr<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    peel_transparent_to_slice_fat_ptr(tcx, ty).is_some()
}

/// The slice/`str` fat pointer a `repr(transparent)` newtype chain WRAPS, or
/// `ty` itself when it already is one. `None` when the chain bottoms out at
/// anything else.
///
/// This is the value form of [`transparent_newtype_is_slice_fat_ptr`] (which is
/// now `.is_some()` of it) and of [`is_slice_fat_ptr_carrier_ty`]. Callers that
/// need the ELEMENT type — slice element addressing, a `len` — go through
/// [`slice_fat_ptr_carrier_pointee`], which peels and then asks
/// `fat_ptr_slice_or_str_pointee` of the result, so exactly one peel loop
/// exists.
fn peel_transparent_to_slice_fat_ptr<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    let mut cur = ty;
    // Bounded: a newtype chain deeper than this is not a shape we model.
    for _ in 0..8 {
        if is_slice_reference_ty(cur) {
            return Some(cur);
        }
        match cur.kind() {
            // A pattern type refines validity, never representation.
            ty::Pat(base, _) => cur = *base,
            ty::Adt(adt, args) if adt.is_struct() => {
                let checked_image = if adt.repr().transparent() {
                    None
                } else {
                    // Owning carriers such as Box/Rc/Arc are not necessarily
                    // repr(transparent). Admit their image only where the
                    // concrete layout proves the same two-word payload.
                    if tcx.sess.target.arch.desc() != "aarch64"
                        || tcx.sess.target.os != rustc_target::spec::Os::Linux
                    {
                        return None;
                    }
                    let Ok(layout) =
                        tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(cur))
                    else {
                        return None;
                    };
                    if crate::scalar_pair::view(layout.backend_repr).is_none()
                        || layout.size.bytes() != 16
                        || layout.align.bytes() != 8
                    {
                        return None;
                    }
                    Some(layout)
                };
                let variant = adt.non_enum_variant();
                let mut next = None;
                for (index, field) in variant.fields.iter().enumerate() {
                    let fty = field.ty(tcx, *args).skip_normalization();
                    let Ok(flayout) =
                        tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(fty))
                    else {
                        return None;
                    };
                    if !flayout.is_zst() {
                        if next.is_some() {
                            return None; // not actually single-field: bail
                        }
                        if let Some(layout) = checked_image {
                            if layout.fields.offset(index).bytes() != 0
                                || layout.size != flayout.size
                                || layout.align.bytes() != flayout.align.bytes()
                                || layout.backend_repr != flayout.backend_repr
                            {
                                return None;
                            }
                        }
                        next = Some(fty);
                    }
                }
                match next {
                    Some(f) => cur = f,
                    None => return None,
                }
            }
            _ => return None,
        }
    }
    None
}

fn is_slice_or_str_fat_ptr_ty(ty: Ty<'_>) -> bool {
    is_slice_reference_ty(ty)
}

/// The shared boundary/slot layout for a checked wrapper over a length-metadata
/// pointer. Bare pointers retain their existing construction paths. Every
/// admitted carrier must have rustc's concrete two-pointer-word ScalarPair
/// image (16 bytes / 8-aligned natively, 8 / 4 on wasm32 — the image
/// `fat_ptr_memory_layout` describes for the session); the existing FnAbi checks
/// still validate its argument/return lanes.
fn wide_slice_carrier_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<MemoryAggregateLayout> {
    // A BARE slice / `str` fat pointer is not a newtype: the peeler answers
    // `true` for it at depth 0, but every caller of this helper has its own,
    // older arm for that shape (and rule (3b)'s newtype sub-arm must not steal a
    // plain `&[T]` / `*mut [T]` destination from the construction arms — measured
    // 2026-09-22: `_7 = &(*_5)` over a `*mut [u8]` call result lost its slot).
    if is_slice_or_str_fat_ptr_ty(ty) || !transparent_newtype_is_slice_fat_ptr(tcx, ty) {
        return None;
    }
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .ok()?;
    let image = fat_ptr_memory_layout();
    if !crate::scalar_pair::view(layout.backend_repr)
        .is_some_and(|pair| pair.second_offset(&tcx).bytes() == session_pointer_bytes())
        || layout.size.bytes() != image.size
        || layout.align.bytes() != image.align
    {
        return None;
    }
    Some(image)
}

/// `is_slice_or_str_fat_ptr_ty` OR the checked wrapper chain above. Consulted
/// at the lockstep BOUNDARY / SLOT sites only (the two classifiers, the
/// memory-backed assignment dispatch, the slot-pointer call-argument branch);
/// NEVER a substitute for the slice predicate itself — element addressing,
/// `PtrMetadata`, subslicing, the reborrow chain walker, the data-half read
/// gates and the memory-backing rules keep asking the narrow one, so a
/// scalarized `NonNull<[T]>` local keeps today's data-pointer-plus-side-table
/// model (`box_into_vec_fat_elem`).
fn is_slice_fat_ptr_or_carrier<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    is_slice_or_str_fat_ptr_ty(ty) || wide_slice_carrier_layout(tcx, ty).is_some()
}

/// Whether `ty` CARRIES a slice/`str` `{ data, len }` fat pointer: either it IS
/// one (`&[T]`, `*mut str`), or it is a `repr(transparent)` newtype chain over
/// one (`NonNull<[T]>`, `NonNull<str>`, `Unique<[T]>`).
///
/// # Why a carrier is the same thing as the pointer it wraps
///
/// `repr(transparent)` is rustc's own guarantee that the struct has the SAME
/// layout and ABI as its single non-zero-sized field, so `NonNull<[u8]>` genuinely
/// IS the `*const [u8]` `{ data, len }` `ScalarPair` — same two eightbytes, same
/// offsets, same register pair. A model that admits the pointer but not the
/// carrier represents ONE of two spellings of one value, and the other silently
/// collapses to a single `Ptr` with the length dropped.
///
/// # Why this is separate from `is_slice_or_str_fat_ptr_ty`
///
/// That predicate has ~65 callers driving lowering decisions all over this file,
/// many of which are slice-SEMANTICS decisions (element addressing, subslicing,
/// `Unsize`) for which a carrier is not interchangeable — a `NonNull<[T]>` has no
/// `(*s)[i]`. This one is consulted only where the question is the two-LANE
/// REPRESENTATION: does this local need a `{ data, len }` slot, and can both
/// lanes be recovered from it. Callers that mean the slice itself keep asking the
/// original.
fn is_slice_fat_ptr_carrier_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    is_slice_or_str_fat_ptr_ty(ty) || transparent_newtype_is_slice_fat_ptr(tcx, ty)
}

/// The `[T]` / `str` TAIL of a DYNAMICALLY-SIZED struct / tuple pointee, and the
/// byte OFFSET of that tail inside the pointee: `([u8], 0)` for
/// `core::bstr::ByteStr(pub [u8])` and `core::wtf8::Wtf8 { bytes: [u8] }`,
/// `([c_char], 0)` for `core::ffi::CStr`, `([MaybeUninit<char>], 16)` for
/// `PolymorphicIter<[MaybeUninit<char>]>` (whose `alive: IndexRange` prefix is two
/// `usize`s).
///
/// # Why a DST pointee is the same REPRESENTATION question as a slice pointee
///
/// Rust has exactly two pointer-metadata kinds, and a struct whose last field is a
/// `[T]` / `str` inherits the SLICE one: `&ByteStr` is a
/// `BackendRepr::ScalarPair` `{ data, len }` whose `len` is the TAIL's element
/// count, byte-for-byte the image a `&[u8]` has. So every two-LANE decision — does
/// this local need a 16-byte slot, does this parameter ride `PassMode::Pair`, can
/// both lanes be recovered — has the same answer for both, which is what
/// [`is_length_metadata_wide_ptr_ty`] is for.
///
/// # What this deliberately does NOT answer
///
/// The metadata's MEANING is NOT interchangeable with a slice's. A `&[T]`'s data
/// pointer addresses element 0; a `&Hdr { n: u32, tail: [u8] }`'s data pointer
/// addresses `n`, and element `i` of the tail is at `data + offset + i*size`. That
/// is why this returns the OFFSET alongside the element type, and why
/// `is_slice_or_str_fat_ptr_ty` / `slice_fat_ptr_carrier_pointee` — the
/// slice-SEMANTICS predicates that ~65 element-addressing / subslicing / `Unsize`
/// callers ask — are left alone: for a prefix-carrying DST a carrier is not
/// interchangeable with the slice it ends in.
///
/// A `dyn` TAIL is NOT admitted: its metadata is a VTABLE, not a length
/// (`core::error::Request<'a>(Tagged<dyn Erased<'a>>)` is the one such pointee in
/// `library/core`), and it keeps failing closed with its own reason.
///
/// Total and fail-closed: `is_sized` is rustc's own definition, the tail is found
/// by asking which field is UNSIZED (never by assuming it is the last declared
/// one), a pointee with more than one unsized field or no computable layout
/// answers `None`, and the newtype chain is depth-bounded.
fn slice_tail_dst_pointee<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<(Ty<'tcx>, u64)> {
    let env = ty::TypingEnv::fully_monomorphized();
    if ty.is_sized(tcx, env) {
        return None;
    }
    let cx = LayoutCx(tcx);
    let mut cur = ty;
    let mut offset: u64 = 0;
    for _ in 0..8 {
        match cur.kind() {
            ty::Slice(element) => return Some((*element, offset)),
            ty::Str => return Some((tcx.types.u8, offset)),
            ty::Adt(adt, _) if adt.is_struct() => {}
            ty::Tuple(fields) if !fields.is_empty() => {}
            // `dyn Trait` (a vtable, not a length), a foreign type, a bare
            // primitive: not this shape.
            _ => return None,
        }
        let layout = tcx.layout_of(env.as_query_input(cur)).ok()?;
        let mut tail = None;
        for i in 0..layout.fields.count() {
            let field = layout.field(&cx, i);
            if field.ty.is_sized(tcx, env) {
                continue;
            }
            if tail.is_some() {
                // Two unsized fields cannot occur in valid Rust; refuse rather
                // than pick one.
                return None;
            }
            tail = Some(i);
        }
        let i = tail?;
        offset = offset.checked_add(layout.fields.offset(i).bytes())?;
        cur = layout.field(&cx, i).ty;
    }
    None
}

/// Whether `place` is `(*r).tail[i]` — an ELEMENT of the `[T]` / `str` TAIL of a
/// slice-tail DST, addressed through the DST's own fat reference. This is the
/// `-O2` form of a tail write: with `<[T]>::index_mut` inlined, `s[n-1] = v` on a
/// `let s = &mut b.0` becomes one statement `((*_1).0: [u8])[_6] = copy _2`, with
/// no intermediate `&mut [u8]` for the tail-borrow arm to serve.
///
/// Requires the FIELD chain between the `Deref` and the index to land on exactly
/// the tail `slice_tail_dst_pointee` identified (same byte offset, same element
/// type) — a sized prefix field, or a nested array that is not the tail, answers
/// `false` and keeps failing closed. A bare `[Deref, Index]` is NOT this shape
/// (that is an ordinary slice element and belongs to
/// `lower_memory_slice_element_store`).
fn is_slice_tail_dst_element_place<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> bool {
    let [ProjectionElem::Deref, rest @ ..] = place.projection.as_ref() else {
        return false;
    };
    let Some((last, fields)) = rest.split_last() else {
        return false;
    };
    if !matches!(
        last,
        ProjectionElem::Index(_) | ProjectionElem::ConstantIndex { .. }
    ) {
        return false;
    }
    if fields.is_empty()
        || !fields
            .iter()
            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
    {
        return false;
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    let Some((pointee, tail_element, tail_offset)) = slice_tail_dst_ref_pointee(ctx.tcx, base_ty)
    else {
        return false;
    };
    let mut prefix: Vec<ProjectionElem<Local, Ty<'tcx>>> = Vec::with_capacity(fields.len() + 1);
    prefix.push(ProjectionElem::Deref);
    prefix.extend(fields.iter().cloned());
    let Ok((offset, leaf_ty)) = walk_memory_projection_offset_raw(ctx, pointee, &prefix) else {
        return false;
    };
    if offset != tail_offset {
        return false;
    }
    let element = match leaf_ty.kind() {
        ty::Slice(element) => *element,
        ty::Str => ctx.tcx.types.u8,
        _ => return false,
    };
    ctx.monomorphize_ty(element) == ctx.monomorphize_ty(tail_element)
}

/// Whether `place` is `(*r).n` / `(*r).hdr.n` — a SIZED field of the SIZED PREFIX
/// of a slice-tail DST, addressed through the DST's own fat reference `r`. The
/// PREFIX sibling of [`is_slice_tail_dst_element_place`], which recognises the
/// tail's ELEMENTS.
///
/// # Why a sized leaf reached only by `Field` cannot be the tail
///
/// rustc lays a slice-tail DST out as a sized prefix followed by the `[T]` / `str`
/// tail, and the tail is the struct's ONLY unsized field (two would not be valid
/// Rust). A `Field` projection whose leaf type is SIZED therefore names a prefix
/// field by construction — the tail's own type is unsized, so projecting to it
/// answers `false` here, and there is no `Field` projection INTO a slice at all.
/// Admitting no `Index` / `ConstantIndex` / `Subslice` / mid-chain `Deref` element
/// keeps it that way: every offset this predicate admits is a static
/// `tcx.layout_of` offset inside the prefix.
///
/// The leaf is required SIZED here and required SCALAR by the store itself, so a
/// bulk aggregate prefix write is not this shape and stays fail-closed.
///
/// `walk_memory_projection_offset_raw` is the same walker the matching READ uses,
/// over the same POINTEE layout, so the write lands on the byte the read loads —
/// the two paths cannot disagree about an offset because they compute it once, in
/// one place.
fn is_slice_tail_dst_prefix_scalar_place<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> bool {
    let [ProjectionElem::Deref, rest @ ..] = place.projection.as_ref() else {
        return false;
    };
    if rest.is_empty()
        || !rest
            .iter()
            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
    {
        return false;
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    let Some((pointee, _, tail_offset)) = slice_tail_dst_ref_pointee(ctx.tcx, base_ty) else {
        return false;
    };
    let Ok((offset, leaf_ty)) = walk_memory_projection_offset_raw(ctx, pointee, &place.projection)
    else {
        return false;
    };
    let leaf_ty = ctx.monomorphize_ty(leaf_ty);
    let env = ty::TypingEnv::fully_monomorphized();
    if !leaf_ty.is_sized(ctx.tcx, env) {
        return false;
    }
    // Belt and braces on top of "a sized leaf is not the tail": the leaf's own
    // byte range must end at or before where the tail starts, read from the same
    // layout. A leaf whose size is unknown answers `false`.
    let Ok(size) = layout_size_of(ctx, leaf_ty) else {
        return false;
    };
    offset
        .checked_add(size)
        .is_some_and(|end| end <= tail_offset)
}

/// The tail ARRAY LENGTH a `&S<[T; N]> -> &S<[T]>` unsize coercion turns into the
/// destination reference's metadata, or `None` when this is not that coercion.
///
/// This is `core::array::IntoIter::unsize` / `unsize_mut`
/// (`&PolymorphicIter<[MaybeUninit<T>; N]> -> &PolymorphicIter<[MaybeUninit<T>]>`)
/// — the built-in `Unsize` of a struct whose last field is unsized. The DATA
/// pointer is UNCHANGED (both references address the same bytes); only the
/// metadata appears, and it is rustc's own array length, read from the const,
/// never derived.
///
/// Walks BOTH pointees in lockstep, level by level, and requires at each level:
/// the same field count, exactly one unsized field on the destination side, and
/// the SAME byte offset for that field on both sides — which is what makes
/// keeping the data pointer correct. The walk bottoms out at a
/// `[T; N]` / `[T]` pair with the identical element type. Anything else answers
/// `None` and the coercion keeps its existing refusal.
fn slice_tail_dst_unsize_len<'tcx>(
    tcx: TyCtxt<'tcx>,
    src_pointee: Ty<'tcx>,
    dst_pointee: Ty<'tcx>,
) -> Option<u64> {
    let env = ty::TypingEnv::fully_monomorphized();
    if !src_pointee.is_sized(tcx, env) || dst_pointee.is_sized(tcx, env) {
        return None;
    }
    let cx = LayoutCx(tcx);
    let mut src = src_pointee;
    let mut dst = dst_pointee;
    for _ in 0..8 {
        let dst_layout = tcx.layout_of(env.as_query_input(dst)).ok()?;
        let src_layout = tcx.layout_of(env.as_query_input(src)).ok()?;
        if dst_layout.fields.count() != src_layout.fields.count() {
            return None;
        }
        let mut tail = None;
        for i in 0..dst_layout.fields.count() {
            if dst_layout.field(&cx, i).ty.is_sized(tcx, env) {
                continue;
            }
            if tail.is_some() {
                return None;
            }
            tail = Some(i);
        }
        let i = tail?;
        if dst_layout.fields.offset(i) != src_layout.fields.offset(i) {
            return None;
        }
        let dst_field = dst_layout.field(&cx, i).ty;
        let src_field = src_layout.field(&cx, i).ty;
        match (dst_field.kind(), src_field.kind()) {
            (ty::Slice(dst_element), ty::Array(src_element, len)) => {
                if *dst_element != *src_element {
                    return None;
                }
                return len.try_to_target_usize(tcx);
            }
            _ => {
                dst = dst_field;
                src = src_field;
            }
        }
    }
    None
}

/// Whether `ty` is a reference / raw pointer whose pointee is a slice-tail DST
/// (see [`slice_tail_dst_pointee`]) — i.e. a `{ data, len }` FAT pointer that
/// neither `is_slice_or_str_fat_ptr_ty` (the pointee is a named struct, not
/// `[T]`) nor `is_trait_object_reference_ty` (the metadata is a length, not a
/// vtable) recognizes.
fn is_slice_tail_dst_ref_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    slice_tail_dst_ref_pointee(tcx, ty).is_some()
}

/// The POINTEE, its tail ELEMENT type and the tail's byte OFFSET, for a reference
/// / raw pointer to a slice-tail DST. `None` for every other type.
fn slice_tail_dst_ref_pointee<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Option<(Ty<'tcx>, Ty<'tcx>, u64)> {
    let (ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _)) = ty.kind() else {
        return None;
    };
    let (element, offset) = slice_tail_dst_pointee(tcx, *pointee)?;
    Some((*pointee, element, offset))
}

/// Whether `ty` is a WIDE pointer whose metadata is a LENGTH: a `&[T]` / `&str`
/// / `repr(transparent)` carrier of one, or a reference / raw pointer to a
/// slice-tail DST. This is the REPRESENTATION predicate — "does this value need a
/// `{ data, len }` two-lane slot, and can both lanes be recovered from it" — and
/// is the only question the two-lane machinery asks. Callers that mean the SLICE
/// (element addressing, `len`, subslicing, `Unsize`) keep asking
/// `is_slice_or_str_fat_ptr_ty` / `is_slice_fat_ptr_carrier_ty`, for which a DST
/// with a sized prefix is NOT interchangeable.
fn is_length_metadata_wide_ptr_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    is_slice_fat_ptr_carrier_ty(tcx, ty) || is_slice_tail_dst_ref_ty(tcx, ty)
}

/// The byte OFFSET of the `[T]` / `str` TAIL in `(*r).tail…` — a borrow of the
/// UNSIZED TAIL FIELD of a slice-tail DST through its fat reference `r`. `None`
/// for every other place.
///
/// # Why the reference's OWN metadata is the borrowed slice's length
///
/// Rust defines the pointer metadata of a `&S` whose last field is a `[T]` to BE
/// that tail's element count — it is the same word, which is why
/// `slice_from_raw_parts(p, n) as *const S` is how such a reference is built at
/// all. So `&(*r).tail` keeps `r`'s metadata VERBATIM and moves only the data
/// half, by the tail field's layout offset. Nothing is derived, scaled or
/// invented: `offset` comes from `tcx.layout_of` and the length is copied.
///
/// # What it refuses, and why each refusal matters
///
///   * a place that is NOT the tail (a sized PREFIX field, `(*r).n`): its
///     borrow is a THIN pointer and carries no length at all — handing it the
///     DST's metadata would manufacture one;
///   * a tail reached at a DIFFERENT offset, or whose element type is not the
///     one `slice_tail_dst_pointee` identified: a second, nested `[U]` whose
///     count is unrelated to `r`'s metadata;
///   * any `Index` / `Subslice` / mid-chain `Deref` element (the walker refuses
///     them), so a `&(*r).tail[i..]` never silently keeps the WHOLE length.
///
/// Layout failure answers `None` (the caller then fails closed with its own
/// named reason) rather than propagating an error out of a match guard.
fn slice_tail_dst_tail_borrow_offset<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    src: &Place<'tcx>,
) -> Option<u64> {
    let [ProjectionElem::Deref, rest @ ..] = src.projection.as_ref() else {
        return None;
    };
    if rest.is_empty()
        || !rest
            .iter()
            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
    {
        return None;
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
    let (pointee, tail_element, tail_offset) = slice_tail_dst_ref_pointee(ctx.tcx, base_ty)?;
    let (offset, leaf_ty) =
        walk_memory_projection_offset_raw(ctx, pointee, &src.projection).ok()?;
    if offset != tail_offset {
        return None;
    }
    let element = match leaf_ty.kind() {
        ty::Slice(element) => *element,
        ty::Str => ctx.tcx.types.u8,
        _ => return None,
    };
    if ctx.monomorphize_ty(element) != ctx.monomorphize_ty(tail_element) {
        return None;
    }
    Some(offset)
}

/// The byte OFFSET of a SIZED PREFIX FIELD in `(*r).field…` — a borrow (`&` or
/// `&raw`) of a field that lives entirely BEFORE the `[T]` / `str` TAIL of a
/// slice-tail DST, reached through the DST's own `{ data, len }` fat pointer `r`.
/// `None` for every other place.
///
/// # The exact complement of [`slice_tail_dst_tail_borrow_offset`]
///
/// That function serves the TAIL borrow, whose result is FAT and keeps `r`'s
/// metadata verbatim. This one serves the prefix, whose result is THIN and
/// carries NO metadata at all — which is precisely the case that function's own
/// doc lists as a refusal ("a sized PREFIX field … its borrow is a THIN pointer
/// and carries no length at all — handing it the DST's metadata would manufacture
/// one"). The two are disjoint by the `offset == tail_offset` / `offset + size <=
/// tail_offset` tests and must stay so: swapping them would either drop a length
/// or invent one.
///
/// `alloc::rc::RcInner<[u8]> { strong: Cell<usize>, weak: Cell<usize>, value:
/// [u8] }` is the shape — `Rc::try_allocate_for_layout` and
/// `Arc::initialize_arcinner` write their two refcounts through
/// `&raw mut ((*inner).0: Cell<usize>)` / `(… .1)`, whose base is a
/// `*mut RcInner<[u8]>` held in a two-lane slot.
///
/// # What makes the CONSTANT offset sound
///
/// rustc lays a DST's sized prefix out first and its unsized tail last, so a
/// SIZED field's offset does not depend on the tail's runtime length. This
/// function does not take that on trust: it requires the projected leaf type to
/// be `Sized` AND `offset + size_of(leaf) <= tail_offset`, so a leaf that
/// overlaps or follows the tail is refused rather than addressed. Every offset
/// comes from `tcx.layout_of`; nothing is derived here.
///
/// A layout failure, a non-`Field` projection element, an empty field chain, or a
/// leaf not provably inside the prefix all answer `None`, and the caller keeps
/// its existing named refusal.
fn slice_tail_dst_prefix_field_borrow_offset<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    src: &Place<'tcx>,
) -> Option<u64> {
    let [ProjectionElem::Deref, rest @ ..] = src.projection.as_ref() else {
        return None;
    };
    if rest.is_empty()
        || !rest
            .iter()
            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
    {
        return None;
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
    let (pointee, _tail_element, tail_offset) = slice_tail_dst_ref_pointee(ctx.tcx, base_ty)?;
    let (offset, leaf_ty) =
        walk_memory_projection_offset_raw(ctx, pointee, &src.projection).ok()?;
    let env = ty::TypingEnv::fully_monomorphized();
    let leaf_ty = ctx.monomorphize_ty(leaf_ty);
    if !leaf_ty.is_sized(ctx.tcx, env) {
        return None;
    }
    let leaf_size = ctx
        .tcx
        .layout_of(env.as_query_input(leaf_ty))
        .ok()?
        .size
        .bytes();
    if offset.checked_add(leaf_size)? > tail_offset {
        return None;
    }
    Some(offset)
}

/// The ELEMENT type addressed by the slice/`str` fat pointer a carrier holds:
/// `T` for a `&[T]` / `NonNull<[T]>`, `u8` for a `&str` / `NonNull<str>`. `None`
/// for anything that carries no slice fat pointer.
fn slice_fat_ptr_carrier_pointee<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<Ty<'tcx>> {
    fat_ptr_slice_or_str_pointee(tcx, peel_transparent_to_slice_fat_ptr(tcx, ty)?)
}

/// Whether `ty` is a THIN pointer by LAYOUT — a reference / raw pointer whose
/// pointee is `Sized`, so the value is ONE address word with no metadata. This is
/// the destination half of the fat -> thin cast seam
/// (`lower_wide_to_thin_ptr_cast`), and it is the layout question, not the kind
/// question: a `*const ByteStr` is NOT thin even though neither
/// `is_slice_or_str_fat_ptr_ty` nor `is_trait_object_reference_ty` recognizes it.
fn is_thin_pointer_by_layout_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    matches!(ty.kind(), ty::Ref(..) | ty::RawPtr(..)) && !is_wide_pointer_memory_leaf_ty(tcx, ty)
}

/// Whether a `(*r).field…` DEREF BASE of type `ty` is a wide pointer whose SINGLE
/// scalar value is NOT the pointee's address, so a field address cannot be formed
/// from it. The precondition of every site that takes a base local's one scalar
/// value (`ctx.scalar_values[local]`, or the entry-arg fallback
/// `ValueId(local.index())`) and folds a field offset onto it.
///
/// # Why this is NOT simply "is the pointer wide"
///
/// The two pointer-metadata kinds are NOT symmetric here, and the difference is a
/// fact about this backend's own ABI, not about Rust:
///
/// * **LENGTH metadata** (`&[T]`, `&str`, `&Hdr<[u8]>`, `&CStr`, a
///   `repr(transparent)` unsized wrapper). No site declares such a parameter as
///   two `Ptr` lanes, so the local's one value is its 16-byte `{ data, len }`
///   SLOT — a lane tuple, or the slot's own address. Folding an offset onto it
///   addresses memory that has nothing to do with the pointee. MEASURED at
///   `-Copt-level=0` on the pre-refusal tree: `&mut (*p).a` on a `&mut Hdr<[u8]>`
///   LOST the write (LLVM `a=90 b=…856 c=65261`, bridge `a=0 b=0 c=0`) and the
///   read returned `6103427808` for `72623859790382856`; the `&raw mut` spelling
///   of the same three fields SIGSEGV'd (exit 139); and the `repr(transparent)`
///   `Hdr<BStr>` variant lost its write too (`b=0` for `99`, read `6092319456`).
///   Those are what this refusal exists for.
///
/// * **VTABLE metadata** (`&dyn Trait`, and a `&Tagged<dyn Trait>` whose struct
///   TAIL is `dyn` — the `core::error::Request` shape). The entry-arg loop
///   declares exactly this class (`is_vtable_pair_abi_ref_ty`) as TWO `Ptr` block
///   params with `ValueId(arg.index())` pushed FIRST as the DATA lane, so the
///   value `value_for_scalar_binding` hands back for such a local IS the pointee's
///   address, by construction at the declaration site. MEASURED on the same tree,
///   the same struct layout with a `dyn` tail instead of a `[u8]` tail: writes AND
///   reads at three distinct prefix offsets matched LLVM exactly, in BOTH the `&`
///   and the `&raw` spelling, through an entry-arg base AND through a
///   `&mut *p` local reborrow. Refusing them buys nothing and costs a working,
///   executable-verified capability — and the refusal's own message ("its single
///   scalar value is not the pointee's address") is FALSE of them.
///
/// Strictly a narrowing of [`is_wide_pointer_memory_leaf_ty`]: the exemption is
/// `is_vtable_pair_abi_ref_ty`, which is `is_trait_object_reference_ty ||
/// is_dyn_tail_fat_ref_ty` and therefore implies a `dyn` pointee or a `dyn` struct
/// tail. No length-metadata carrier — `&[T]`, `&str`, a slice-tail DST, a
/// `repr(transparent)` unsized wrapper, a `ty::Pat`-refined pointer to any of them
/// — can satisfy it, so nothing this predicate admits was ever in the
/// length-metadata class the refusal was measured against.
///
/// ONE predicate for BOTH spellings on purpose. The `&` / `&mut` spelling reaches
/// `memory_aggregate_ref_address` and the `&raw` spelling reaches `lower_assign`'s
/// through-reference `Rvalue::RawPtr` arm; they must refuse and admit the same
/// set, or one spelling of a program compiles while the other does not (which is
/// exactly how the vtable capability was withdrawn from the `&raw` side while a
/// fix to the `&` side alone left it withdrawn).
fn wide_deref_base_value_is_not_pointee_addr<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    is_wide_pointer_memory_leaf_ty(tcx, ty) && !is_vtable_pair_abi_ref_ty(tcx, ty)
}

/// [TCG-DEREF-BASE-ADDR] Whether a `(*r)…` deref BASE `r` of type `ty` carries the
/// POINTEE'S ADDRESS as its one scalar value — the precondition of every site that
/// folds a field offset onto `value_for_scalar_binding(Local(r))`.
///
/// # This is the ADDRESS question, not the THIN question
///
/// Two different questions used to share one enumerated spelling
/// (`!is_slice_or_str_fat_ptr_ty(ty) && !is_trait_object_reference_ty(ty)`), and
/// that spelling answers NEITHER correctly:
///
///   * "is this pointer ONE scalar with no metadata" (a DESTINATION /
///     representation question — may a borrow result be bound to one value?) is
///     SIZEDNESS: `is_thin_pointer_ref_ty` / `is_thin_pointer_by_layout_ty`;
///   * "is this pointer's one bound VALUE the pointee's address" (a BASE question —
///     may a field offset be folded onto it?) is THIS predicate, and it is
///     sizedness with the VTABLE-metadata class carved back in, for exactly the
///     reason `wide_deref_base_value_is_not_pointee_addr` documents: the entry-arg
///     loop declares a `&Tagged<dyn Trait>` as two `Ptr` params with the DATA lane
///     first, so that local's value IS the pointee's address.
///
/// The enumeration called a reference to a slice-tail DST STRUCT (`&H<[u32]>`,
/// `&H<str>`) "not fat" because its pointee is a named struct rather than a bare
/// `[T]` / `str`; that local's one value is its `{ data, len }` lane TUPLE (or its
/// slot's address), never the pointee. MEASURED at the lane tip `572c4ce34` with
/// NO patch applied, every one an executed silent wrong answer rather than a
/// refusal, each since pinned to its site by reverting that site alone:
///
///     fn get_i(h: &H<[u32]>) -> Inner { h.i }   // whole-aggregate deref read,
///         // O0+O2: LLVM `11 22 33`, bridge `6100986152 3 1806018856`
///     fn get_arr(h: &H<[u8]>) -> u64 { let a = h.arr; .. }   // projected array,
///         // O2: LLVM `arr 123`, bridge `arr 613519592820`
///     fn wrap_s(h: &H<[u32]>) -> W { W { k: 9, s: h.i.s } }  // fat-leaf read,
///         // O0+O2: LLVM `wrap 9 6 21`, bridge `wrap 9 2 346` (a wrong LENGTH)
///     fn disc(h: &H<[u8]>) -> u64 { match h.e { .. } }  // deref discriminant,
///         // O0+O2: LLVM `disc 55 1009`, bridge `disc 0 0` — that site asked
///         // nothing at all before this predicate existed
///
/// # Exactly what it admits, stated as a set
///
/// `Ref | RawPtr`, NOT a bare `&dyn Trait`, and NOT a pointer whose pointee is
/// unsized-and-not-vtable-tailed. So it is the old enumeration MINUS the
/// length-metadata DST structs (and `extern type` pointees, whose sizedness is
/// likewise unknown): it can only ever NARROW a site that asked the enumeration,
/// never widen one — a `&[T]` / `&str` (or a `repr(transparent)` unsized wrapper of
/// one) is unsized and not vtable-tailed, so it is excluded here exactly as the
/// enumeration excluded it, and a bare `&dyn` is excluded by its own conjunct. The
/// VTABLE-tailed struct class (`&Tagged<dyn Erased>`) keeps the answer the
/// enumeration gave it, which is the capability measured LLVM-exact at the tip
/// (reads AND writes of sized and wide prefix fields through it).
///
/// A declined site keeps its own fall-through: a SLOT-backed slice-tail DST base
/// reaches `memory_place_walk_base`, which loads the DATA lane; anything else is
/// refused by name.
fn deref_base_scalar_is_pointee_addr<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    matches!(ty.kind(), ty::Ref(..) | ty::RawPtr(..))
        && !is_trait_object_reference_ty(ty)
        && !wide_deref_base_value_is_not_pointee_addr(tcx, ty)
}

/// Whether `local` is a THIN `&` / raw-pointer local whose POINTEE is itself a
/// `&[T]` / `&str` slice fat pointer — a `&&[i32]` / `&&str`. This is the base
/// shape a ptr-bearing `static NUMS: &[i32]` / `static GREETING: &str` read
/// produces: `_p = const {alloc: &&[i32]}; s = copy (*_p)` (the MIR constant is
/// a pointer TO the static's memory and the read derefs it), where the loaded
/// value is the WHOLE 16-byte `{ data, len }` fat pointer.
fn local_is_thin_ref_to_slice_fat_ptr<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    local: Local,
) -> bool {
    let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
    match ty.kind() {
        // The pointee may be the fat pointer itself (`&&[T]`, `&&str`) or a
        // `repr(transparent)` CARRIER of one (`&NonNull<str>` — the `&self`
        // receiver of `NonNull::<str>::as_ref`). Both have the identical
        // `{ data, len }` bytes at the pointee address, which is all this
        // predicate's caller loads.
        // ...or a slice-tail DST reference (`&&Wtf8` — the `&self` receiver of a
        // `&Wtf8` method reached through another reference). All three have the
        // identical `{ data, len }` bytes at the pointee address, which is all
        // this predicate's caller loads.
        ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _) => {
            is_length_metadata_wide_ptr_ty(ctx.tcx, ctx.monomorphize_ty(*pointee))
        }
        _ => false,
    }
}

/// The byte offset of the length lane of the length-metadata wide pointer that
/// the THIN reference / raw pointer `local` points at: rustc's `ScalarPair`
/// metadata offset (8 on a 64-bit target, 4 on wasm32). The pointee may be the
/// `&[T]` / `&str` itself or a slice-tail DST reference ([`fat_ptr_metadata_offset`]),
/// or a `repr(transparent)` CARRIER of one (`&NonNull<str>`), whose rustc layout
/// is the same two-pointer-word `ScalarPair` and whose metadata offset is that
/// pair's second-scalar offset — every pointee `local_is_thin_ref_to_slice_fat_ptr`
/// and `is_wide_slice_newtype_deref_read` admit. Any other `local` is refused.
fn thin_ref_slice_pointee_meta_offset<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    local: Local,
) -> Result<u64, String> {
    use rustc_abi::Primitive;
    let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
    let (ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _)) = ty.kind() else {
        return Err(format!(
            "slice fat-pointer access through `{ty:?}`, which is not a reference or raw pointer"
        ));
    };
    let pointee = ctx.monomorphize_ty(*pointee);
    if !is_length_metadata_wide_ptr_ty(ctx.tcx, pointee) {
        return Err(format!(
            "slice fat-pointer access through `{ty:?}`: the pointee is not a slice / str \
             fat pointer, a carrier of one, or a slice-tail DST reference"
        ));
    }
    if is_slice_or_str_fat_ptr_ty(pointee) || is_slice_tail_dst_ref_ty(ctx.tcx, pointee) {
        return fat_ptr_metadata_offset(ctx.tcx, pointee);
    }
    // A `repr(transparent)` carrier has ONE layout field (the pointer it wraps),
    // so read the metadata offset off its `ScalarPair` the way rustc does
    // (`rustc_codegen_ssa::mir::operand`), after checking it is the
    // {pointer, pointer-sized metadata} pair of two pointer words.
    let layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(pointee))
        .map_err(|e| format!("slice fat-pointer carrier layout_of({pointee:?}) failed: {e:?}"))?;
    let ptr_size = ctx.tcx.data_layout.pointer_size();
    match crate::scalar_pair::view(layout.backend_repr) {
        Some(pair)
            if matches!(pair.a.primitive(), Primitive::Pointer(_))
                && pair.a.size(&ctx.tcx) == ptr_size
                && pair.b.size(&ctx.tcx) == ptr_size
                && layout.size == ptr_size * 2 =>
        {
            Ok(pair.second_offset(&ctx.tcx).bytes())
        }
        _ => Err(format!(
            "slice fat-pointer carrier `{pointee:?}` is not a {{pointer, pointer-sized \
             metadata}} pair of two pointer words ({:?}); refusing to place its \
             metadata lane at a guessed offset",
            layout.backend_repr
        )),
    }
}

/// A whole newtype image read through a thin pointer. Optimized MIR can
/// project through checked carrier fields; each such field must retain the
/// same validated two-lane image at offset zero. Scalarized constructions and
/// dereference stores do not use this read-only predicate.
fn is_wide_slice_newtype_deref_read<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> bool {
    let [ProjectionElem::Deref, fields @ ..] = place.projection.as_ref() else {
        return false;
    };
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    let (ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _)) = base_ty.kind() else {
        return false;
    };
    let mut current = ctx.monomorphize_ty(*pointee);
    if wide_slice_carrier_layout(ctx.tcx, current).is_none() {
        return false;
    }
    for projection in fields {
        let ProjectionElem::Field(index, field_ty) = projection else {
            return false;
        };
        let ty::Adt(adt, _) = current.kind() else {
            return false;
        };
        if !adt.is_struct() {
            return false;
        }
        let Ok(layout) = ctx
            .tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(current))
        else {
            return false;
        };
        if index.index() >= layout.fields.count()
            || layout.fields.offset(index.index()).bytes() != 0
        {
            return false;
        }
        current = ctx.monomorphize_ty(*field_ty);
        if wide_slice_carrier_layout(ctx.tcx, current).is_none() {
            return false;
        }
    }
    true
}

/// The 16-byte / 8-aligned slot type a boundary-crossing slice fat pointer is
/// memory-backed by: two `I64` eightbyte lanes (lane 0 = data pointer, lane 1 =
/// length metadata). Mirrors the uniform integer-lane tuple `memory_slot_lane_ty`
/// produces for every other memory aggregate, so the alloca result is an
/// I64-pointer carrier the ISel treats as a slot address (a mixed `Ptr`/`I64`
/// lane tuple is not a valid slot-address carrier). The data pointer is stored
/// as a `Ptr`-typed value into lane 0 (pointer width == I64 on the target), so
/// no provenance is lost. The lane tuple is exactly the SysV two-eightbyte
/// aggregate ABI type so `func_ty_for_instance` / the call adapter place data+len
/// in a register pair (or RAX:RDX on return).
///
/// SPELLED BY `memory_slot_lane_ty`, never by hand. This used to be a literal
/// `Tuple([I64, I64])` that "mirrored" `memory_slot_lane_ty` — and the mirror
/// drifted when `eec3b918` taught `memory_slot_lane_ty` the `Ty::Array(lane, n)`
/// spelling. The two spellings are the same TYPE by construction (same size,
/// align and element offsets, pinned by
/// `array_indexes_identically_to_the_uniform_struct_spelling`) but they are not
/// the same `Ty`, and the adapter's entry-vs-signature check compares `Ty`s.
/// `Box<dyn Trait>` is the shape where the two met: its SLOT, and so the
/// entry-block parameter stored into it, comes from `memory_backed_local_layout`
/// (whose `Box<dyn>` arm answers `fat_ptr_memory_layout()`, i.e. this function),
/// while its SIGNATURE, its memory-backing decision and its call-return check
/// come from `fat_ptr_or_memory_aggregate_layout`, which has no `Box<dyn>` arm
/// and falls through to the generic `memory_aggregate_layout` walk, i.e.
/// `memory_slot_lane_ty(16, 8)`. The result was `[TCG-REGALLOC-063] entry
/// parameter 0 has type Struct([I64, I64]), signature parameter has type
/// Array(I64, 2)` on `panic_unwind::imp::panic`, and the return-side twin
/// (`memory aggregate call return type does not match destination slot layout`)
/// on every `-> Box<dyn Trait>` call destination. Deriving the spelling from the
/// one function that owns it makes both sides agree whatever
/// `slot-array-min-lanes` says; `fat_ptr_slot_ty_is_the_memory_slot_spelling`
/// pins it against being hand-written again.
fn fat_ptr_slot_ty() -> TrustIrTy {
    // Two pointer-width lanes: 16 bytes / 8-aligned `[I64; 2]` on a 64-bit
    // target, 8 bytes / 4-aligned `[I32; 2]` on wasm32 — rustc's own
    // `ScalarPair` image of a fat pointer. Infallible: both alignments are
    // seeded lanes, the size is twice the alignment, and the lane count is 2 —
    // every `Err` arm of `memory_slot_lane_ty` is excluded.
    let word = session_pointer_bytes();
    memory_slot_lane_ty(2 * word, word)
        .expect("a two-pointer-word fat-pointer image is always a two-lane memory slot")
}

/// The session's pointer width in bits (see `SESSION_POINTER_BITS`).
fn session_pointer_bits() -> u32 {
    SESSION_POINTER_BITS.load(std::sync::atomic::Ordering::Relaxed)
}

/// The session's pointer width in bytes (see `SESSION_POINTER_BITS`).
fn session_pointer_bytes() -> u64 {
    u64::from(SESSION_POINTER_BITS.load(std::sync::atomic::Ordering::Relaxed)) / 8
}

/// Drop the queued jobs of a pointer-word value lane in a session whose
/// pointer width the lanes' word model does not describe
/// (`mem_refine::word_model_describes`): such an obligation would be a
/// statement about 8-byte cells and 64-bit address arithmetic the session does
/// not execute, so no obligation is stated and no coverage is credited. The
/// obligation builders refuse the same sessions; this names the reason. Each
/// job goes through [`refinement_job_unmodeled`]: the strict lane fails closed
/// on the first, the default lanes skip them all.
fn drop_jobs_outside_word_model<J: TvValueJob>(
    jobs: &mut Vec<J>,
    strict: bool,
    trace: bool,
    symbol: &str,
) -> Result<(), String> {
    drop_jobs_outside_word_model_at(session_pointer_bytes(), jobs, strict, trace, symbol)
}

/// [`drop_jobs_outside_word_model`] for an explicit pointer width.
fn drop_jobs_outside_word_model_at<J: TvValueJob>(
    pointer_bytes: u64,
    jobs: &mut Vec<J>,
    strict: bool,
    trace: bool,
    symbol: &str,
) -> Result<(), String> {
    if mem_refine::word_model_describes(pointer_bytes) {
        return Ok(());
    }
    let what =
        format!("the 64-bit word model does not describe a {pointer_bytes}-byte-pointer session");
    for job in jobs.iter() {
        refinement_job_unmodeled(strict, trace, symbol, J::LANE, job.name(), &what)?;
    }
    jobs.clear();
    Ok(())
}

/// Refuse a lowering whose model is written for 64-bit pointers only (it
/// stores native-width lanes the wasm32 word pass cannot size).
fn require_64bit_model(what: &str) -> Result<(), String> {
    if session_pointer_bytes() == 8 {
        return Ok(());
    }
    Err(format!(
        "[TCG-WASM32-MODEL] {what} is modeled for 64-bit targets only and is not ported to \
         wasm32; failing closed"
    ))
}

/// Admit a pointer width for data images (vtables, const allocations,
/// pointer-bearing statics) and the vtable-slot loads that read them: 8 bytes
/// on the native targets, or 4 bytes in a 32-bit session — which only wasm32
/// reaches, and whose wasm object lane lays `Ptr` out as 4 bytes. Any other
/// width fails closed with `what` named.
fn check_image_pointer_size(ptr_size: u64, what: &str) -> Result<(), String> {
    if ptr_size == 8 || (ptr_size == 4 && session_pointer_bytes() == 4) {
        return Ok(());
    }
    Err(format!(
        "{what} supports only 64-bit pointer targets and wasm32, got {ptr_size}-byte pointers"
    ))
}

/// The integer type of one pointer-width lane of a fat-pointer slot: `I64` on
/// a 64-bit target, `I32` on wasm32.
fn pointer_lane_ty() -> TrustIrTy {
    if session_pointer_bytes() == 4 {
        TrustIrTy::I32
    } else {
        TrustIrTy::I64
    }
}

/// Reinterpret a pointer-width integer onto the fat-pointer lane type via a
/// same-width `Copy` (the 32-bit twin of [`coerce_to_i64`] on wasm32).
fn coerce_to_pointer_lane(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    value: ValueId,
) -> ValueId {
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: pointer_lane_ty(),
            operand: value,
        })
        .with_result(result),
    );
    result
}

/// The memory-aggregate layout of a boundary-crossing slice fat pointer: a
/// 16-byte / 8-aligned `{ Ptr, I64 }` slot, no enum tag. This is the layout the
/// boundary helpers (`func_ty_for_instance`, the by-value call-arg / call-dest
/// paths, the return path) consume so the fat pointer reuses the verified
/// by-value aggregate ABI unchanged.
fn fat_ptr_memory_layout() -> MemoryAggregateLayout {
    MemoryAggregateLayout {
        slot_ty: fat_ptr_slot_ty(),
        size: 2 * session_pointer_bytes(),
        align: session_pointer_bytes(),
        tag: None,
        // This layout IS itself a bare fat pointer (the top-level `&[T]`/`&str`
        // boundary-crossing case, unrelated to the struct-field fat-leaf feature),
        // so it trivially "contains" one fat leaf.
        has_fat_pointer_leaf: true,
        has_nested_enum_leaf: false,
        has_nested_niche_enum_leaf: false,
    }
}

/// Whether a C-ABI by-value aggregate `ty` has any (possibly nested) SCALAR field
/// lying at a byte offset NOT divisible by that scalar's own ABI alignment — i.e. a
/// `#[repr(packed)]` aggregate with a MISALIGNED wide field. The bridge lowers a
/// by-value register aggregate's ABI through a uniform lane tuple keyed on the
/// aggregate's (reduced, packed) alignment (`memory_slot_lane_ty` -> `I8`/`I16`
/// lanes for a packed struct); the System V C ABI instead packs the bytes into full
/// INTEGER eightbytes passed in GPRs, and a misaligned wide field straddles the
/// bridge's sub-eightbyte lane granularity, so the by-value marshaling DIVERGES from
/// independently-compiled clang/LLVM (a silent wrong value at the boundary — the
/// FUZZ-6 clang-oracle divergence on `#[repr(C, packed)] struct { a: u8, b: u64 }`,
/// where `b` sits at offset 1). This is self-consistent inside a pure-bridge program
/// (the Rust ABI passes both sides the same way) but WRONG at a real ABI boundary.
///
/// Returns `false` for a packed aggregate whose fields all happen to be naturally
/// aligned (`#[repr(C, packed)] struct { a: u64, b: u64 }` — offsets 0 and 8, both
/// aligned), which marshals byte-identically to clang and stays working, and for any
/// non-aggregate / shape the field walk cannot analyze exactly (multi-variant enum,
/// etc.), which is handled — and, if unsupported, fails closed — elsewhere.
fn c_abi_aggregate_has_misaligned_scalar_field<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    if !matches!(ty.kind(), ty::Adt(..) | ty::Tuple(..) | ty::Array(..)) {
        return false;
    }
    let cx = LayoutCx(tcx);
    let Ok(tl) = tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty)) else {
        return false;
    };
    misaligned_scalar_field_walk(tcx, &cx, tl, 0)
}

/// Recursive worker for [`c_abi_aggregate_has_misaligned_scalar_field`]: `true` iff
/// some scalar leaf of the aggregate layout `tl` at absolute byte `base` sits at an
/// offset not a multiple of its own ABI alignment.
fn misaligned_scalar_field_walk<'tcx>(
    tcx: TyCtxt<'tcx>,
    cx: &LayoutCx<'tcx>,
    tl: rustc_middle::ty::layout::TyAndLayout<'tcx>,
    base: u64,
) -> bool {
    use rustc_abi::Variants;
    match tl.ty.kind() {
        ty::Bool
        | ty::Char
        | ty::Int(_)
        | ty::Uint(_)
        | ty::Float(_)
        | ty::RawPtr(..)
        | ty::Ref(..)
        | ty::FnPtr(..) => {
            let align = tl.align.bytes().max(1);
            base % align != 0
        }
        ty::Tuple(_) | ty::Array(..) => (0..tl.fields.count()).any(|i| {
            let off = tl.fields.offset(i).bytes();
            misaligned_scalar_field_walk(tcx, cx, tl.field(cx, i), base + off)
        }),
        ty::Adt(adt, _) if adt.is_struct() => {
            if !matches!(tl.variants, Variants::Single { .. }) {
                return false;
            }
            (0..tl.fields.count()).any(|i| {
                let off = tl.fields.offset(i).bytes();
                misaligned_scalar_field_walk(tcx, cx, tl.field(cx, i), base + off)
            })
        }
        ty::Adt(adt, _) if adt.is_union() => (0..tl.fields.count()).any(|i| {
            // Union fields all overlap at offset 0; a misaligned wide member is
            // still a packed-marshaling hazard.
            misaligned_scalar_field_walk(tcx, cx, tl.field(cx, i), base)
        }),
        _ => false,
    }
}

/// Whether a C-ABI by-value UNION `ty` has MIXED System V member classes — at least
/// one floating-point member AND at least one non-floating-point (integer / pointer)
/// member. The System V C ABI classifies a union by MERGING every member's class into
/// the shared eightbyte(s), and "INTEGER wins": a `union { double d; uint64_t i; }`
/// eightbyte is INTEGER, so clang/LLVM pass it in a GENERAL-PURPOSE register. The
/// bridge, however, represents such a scalar-carrier union by its (possibly FLOAT)
/// scalar carrier and passes it in an XMM register — a register-class mismatch that
/// reads garbage from the GPR at the boundary (the FUZZ-6 clang-oracle divergence on
/// `union { f64, u64 }`, wrong at O0 for a float-active value and at O2/O3 always).
///
/// A PURE-integer union (`union { u64, [u32;2], u8 }`) is unambiguously INTEGER (its
/// carrier is a GPR value — stays working) and a PURE-float union is unambiguously
/// SSE, so only the MIXED case is flagged; the caller fails closed on it.
fn c_abi_union_has_mixed_member_classes<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, args) = ty.kind() else {
        return false;
    };
    if !adt.is_union() {
        return false;
    }
    let mut has_float = false;
    let mut has_non_float = false;
    for field in adt.all_fields() {
        let field_ty = field.ty(tcx, *args).skip_normalization();
        if is_zero_sized_ty(tcx, field_ty) {
            continue;
        }
        if type_contains_float_leaf(tcx, field_ty) {
            has_float = true;
        }
        if type_contains_non_float_leaf(tcx, field_ty) {
            has_non_float = true;
        }
    }
    has_float && has_non_float
}

/// Recursively OR every NON-floating-point scalar leaf of `ty` (the dual of
/// [`type_contains_float_leaf`]). Used to detect a union member that forces an
/// INTEGER eightbyte class.
fn type_contains_non_float_leaf<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    match ty.kind() {
        ty::Bool
        | ty::Char
        | ty::Int(_)
        | ty::Uint(_)
        | ty::RawPtr(..)
        | ty::Ref(..)
        | ty::FnPtr(..) => true,
        ty::Float(_) => false,
        ty::Tuple(fields) => fields.iter().any(|f| type_contains_non_float_leaf(tcx, f)),
        ty::Array(elem, _) => type_contains_non_float_leaf(tcx, *elem),
        ty::Adt(adt, args) if adt.is_struct() || adt.is_union() => adt
            .all_fields()
            .any(|f| type_contains_non_float_leaf(tcx, f.ty(tcx, *args).skip_normalization())),
        // A shape we cannot classify (multi-variant enum, etc.) conservatively counts
        // as a non-float leaf so a union mixing it with a float fails closed.
        _ => true,
    }
}

/// The memory-slot layout for `ty` IFF it is a NON-scalar (aggregate) union whose
/// active field bottoms out at memory scalars — the `MaybeUninit<T>` shape for a
/// MULTI-FIELD `T` (a tuple / struct / array). A SCALAR union (`MaybeUninit<i64>`,
/// `scalar_union_abi_layout` -> `Ok(Some)`) returns `None`: it keeps its dedicated
/// single-scalar-carrier ABI / construct / return path (unchanged). A non-union
/// type returns `None`. This is the ONE gate that routes an aggregate union onto
/// the SAME verified memory-aggregate by-value ABI + construct + read machinery a
/// same-sized struct/tuple already uses (its overlapping fields all start at byte
/// offset 0, so the active field's leaves ARE the slot's bytes). Sound because a
/// non-scalar union has no scalarized representation at all today (it fails closed
/// everywhere), so forcing it onto the memory-aggregate path steals no working
/// case — the worst case is the same fail-closed.
fn nonscalar_union_memory_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    // A scalar-ABI union keeps its own path; only an aggregate union rides here.
    // `scalar_union_abi_layout` returns `Err` for an aggregate union (its active
    // `ManuallyDrop<multi-field>` field has no scalar ABI), which `matches!` treats
    // as "not a scalar union" -> fall through to the memory layout.
    if matches!(scalar_union_abi_layout(tcx, ty), Ok(Some(_))) {
        return Ok(None);
    }
    union_memory_layout(tcx, ty)
}

/// Recursively OR every floating-point leaf of `ty`. A conservative fallback used
/// by [`sysv_register_aggregate_has_sse_eightbyte`] when the precise per-eightbyte
/// walk cannot model a shape exactly (multi-variant enum payload, a leaf straddling
/// an eightbyte): if any float leaf exists it COULD land in an SSE eightbyte, so
/// treat the shape as SSE-risk and fail closed.
fn type_contains_float_leaf<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    match ty.kind() {
        ty::Float(_) => true,
        ty::Tuple(fields) => fields.iter().any(|f| type_contains_float_leaf(tcx, f)),
        ty::Array(elem, _) => type_contains_float_leaf(tcx, *elem),
        ty::Adt(adt, args) if !adt.is_union() => adt
            .all_fields()
            .any(|f| type_contains_float_leaf(tcx, f.ty(tcx, *args).skip_normalization())),
        ty::Adt(adt, args) if adt.is_union() => adt
            .all_fields()
            .any(|f| type_contains_float_leaf(tcx, f.ty(tcx, *args).skip_normalization())),
        _ => false,
    }
}

/// Merge one scalar leaf `[base, base+size)`'s class into the eightbyte accumulator
/// it lies in. `ebs[i]` is `None` (only padding so far), `Some(true)` (every
/// covering leaf is float — an SSE eightbyte candidate), or `Some(false)` (a
/// non-float leaf makes the eightbyte INTEGER — the psABI "INTEGER wins" merge).
/// Returns `false` if the leaf straddles the eightbyte boundary or lies outside the
/// two eightbytes (shape not modeled exactly — caller falls back conservatively).
fn merge_sysv_eightbyte_float_class(
    ebs: &mut [Option<bool>; 2],
    base: u64,
    size: u64,
    is_float: bool,
) -> bool {
    if size == 0 {
        return true; // a ZST leaf occupies no eightbyte
    }
    let lo = base / 8;
    let hi = (base + size - 1) / 8;
    if lo != hi || hi > 1 {
        return false;
    }
    let slot = &mut ebs[lo as usize];
    *slot = Some(match (*slot, is_float) {
        // INTEGER (a non-float leaf) always wins the eightbyte.
        (Some(false), _) | (_, false) => false,
        (None, true) | (Some(true), true) => true,
    });
    true
}

/// Walk every scalar leaf of the aggregate layout `tl` at absolute byte `base`,
/// merging each leaf's SysV class into the eightbyte it occupies. Returns `false`
/// if the shape cannot be modeled exactly (the caller then falls back to a
/// conservative any-float-leaf check).
fn collect_sysv_eightbyte_float_classes<'tcx>(
    tcx: TyCtxt<'tcx>,
    cx: &LayoutCx<'tcx>,
    tl: rustc_middle::ty::layout::TyAndLayout<'tcx>,
    base: u64,
    ebs: &mut [Option<bool>; 2],
) -> bool {
    use rustc_abi::Variants;
    match tl.ty.kind() {
        ty::Float(_) => merge_sysv_eightbyte_float_class(ebs, base, tl.size.bytes(), true),
        ty::Bool
        | ty::Char
        | ty::Int(_)
        | ty::Uint(_)
        | ty::RawPtr(..)
        | ty::Ref(..)
        | ty::FnPtr(..) => merge_sysv_eightbyte_float_class(ebs, base, tl.size.bytes(), false),
        // A struct / tuple / array: descend into each field at its layout offset.
        // (Arrays report their element layout via `field(_, i)` for every `i`.)
        ty::Tuple(_) | ty::Array(..) => {
            for i in 0..tl.fields.count() {
                let off = tl.fields.offset(i).bytes();
                if !collect_sysv_eightbyte_float_classes(tcx, cx, tl.field(cx, i), base + off, ebs)
                {
                    return false;
                }
            }
            true
        }
        ty::Adt(adt, _) if adt.is_struct() => {
            if !matches!(tl.variants, Variants::Single { .. }) {
                return false;
            }
            for i in 0..tl.fields.count() {
                let off = tl.fields.offset(i).bytes();
                if !collect_sysv_eightbyte_float_classes(tcx, cx, tl.field(cx, i), base + off, ebs)
                {
                    return false;
                }
            }
            true
        }
        ty::Adt(adt, _) if adt.is_union() => {
            // All union fields overlap at offset 0; SysV merges each field's class
            // into the shared eightbytes.
            for i in 0..tl.fields.count() {
                if !collect_sysv_eightbyte_float_classes(tcx, cx, tl.field(cx, i), base, ebs) {
                    return false;
                }
            }
            true
        }
        // Multi-variant enums, coroutines, etc. — not modeled exactly here.
        _ => false,
    }
}

/// System V AMD64 eightbyte classification at the Rust-type level: `true` iff `ty`
/// is a register-passed aggregate (1..=16 bytes) with at least one eightbyte whose
/// covering leaves are ALL floating-point — an SSE eightbyte.
///
/// The by-value aggregate ABI type the bridge builds for a register aggregate
/// (`memory_slot_lane_ty`) uses UNIFORM INTEGER lanes, so the isel's SysV
/// classifier sees only INTEGER eightbytes and marshals every eightbyte through a
/// general-purpose register. For an SSE eightbyte the System V C ABI instead
/// mandates an XMM register. That divergence is self-consistent inside a
/// pure-bridge program (caller and callee both use GPRs) but WRONG at any real ABI
/// boundary — an `extern "C"` / FFI / cross-object call to or from an
/// independently-compiled (clang / LLVM) function reads the SSE eightbyte from the
/// XMM register and gets garbage (found by the FUZZ-5 clang-oracle differential:
/// `{ f64, i64 }` / `{ i64, f64 }` / `{ f32, f32, f32, f32 }` all diverged). The
/// boundary type builder fails closed on this shape rather than emit
/// ABI-nonconformant (silently miscompiling) code.
///
/// `>16`-byte (MEMORY / sret, stack byte-copied) aggregates and all-INTEGER
/// aggregates — including an INTEGER-merged mixed eightbyte such as `{ f32, i32 }`,
/// whose float shares its eightbyte with an integer and is correctly GPR-passed —
/// return `false`.
fn sysv_register_aggregate_has_sse_eightbyte<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    // Only aggregates are register-classified here; a bare scalar `f32`/`f64`
    // already takes the correct XMM path.
    if !matches!(ty.kind(), ty::Adt(..) | ty::Tuple(..) | ty::Array(..)) {
        return false;
    }
    let cx = LayoutCx(tcx);
    let Ok(tl) = tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty)) else {
        // Cannot lay it out — leave the decision to the downstream layout path,
        // which will itself fail closed if it cannot model the type.
        return false;
    };
    let size = tl.size.bytes();
    if size == 0 || size > 16 {
        return false;
    }
    let mut ebs: [Option<bool>; 2] = [None, None];
    if collect_sysv_eightbyte_float_classes(tcx, &cx, tl, 0, &mut ebs) {
        ebs.iter().any(|e| *e == Some(true))
    } else {
        // Shape not modeled exactly — any float leaf could occupy an SSE eightbyte.
        type_contains_float_leaf(tcx, ty)
    }
}

/// The CLASS-CORRECT System V eightbyte lane tuple for a C-ABI (`extern "C"`,
/// `"sysv64"`, `"system"`, …) by-value register aggregate whose byte layout has at
/// least one PURE-SSE (all-floating-point) eightbyte. `Some(tuple)` is the ABI
/// param / return / block-param type the bridge must use so the (already SSE-aware)
/// isel SysV classifier passes the SSE eightbyte in an XMM register, exactly as the
/// System V C ABI (and clang / LLVM) mandate — instead of the uniform INTEGER-lane
/// `memory_slot_lane_ty` tuple, which erases the float fields and marshals every
/// eightbyte through a general-purpose register (the FUZZ-5 miscompile).
///
/// The returned tuple has the SAME lane STRUCTURE as `memory_slot_lane_ty(size,
/// align)` (`size / align` lanes of `align` bytes each, at offsets `i * align`), so
/// every by-value marshaling site that iterates the uniform lanes (the memory slot,
/// `store_incoming_aggregate_param`, the by-value call-arg / call-result copies)
/// stays byte-for-byte consistent — the ONLY difference is that a lane lying in a
/// pure-SSE eightbyte is a FLOAT (`F64` for an 8-aligned lane, `F32` for a 4-aligned
/// lane) rather than the corresponding integer. Reading/writing those lanes moves
/// the same 8 (resp. 4) bytes; only the register CLASS (XMM vs GPR) and the mov
/// opcode change.
///
/// Returns `None` — leaving the caller on the existing (all-integer `slot_ty`) path,
/// or, for a shape with an SSE eightbyte it cannot model exactly, on the sound
/// `[TCG-SYSV-SSE-AGGREGATE]` fail-closed — for: a non-aggregate; a type the bridge
/// does not slot-back as a plain memory aggregate (a bare-scalar newtype already
/// takes the correct XMM path; a union / fat pointer / closure env stays
/// fail-closed); a Direct-tagged enum (overlapping payload); a `>16`-byte MEMORY /
/// sret aggregate; an all-INTEGER aggregate (including an INTEGER-merged mixed
/// eightbyte such as `{ f32, i32 }`, correctly GPR-passed and unchanged); an
/// eightbyte the per-eightbyte walk cannot classify exactly; or an alignment other
/// than 4 / 8 (an SSE eightbyte requires a `>=4`-byte float leaf, so `align >= 4`;
/// `align == 16` is an `i128`, never SSE).
fn sysv_c_abi_aggregate_lane_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<TrustIrTy>, String> {
    // Only a plain register aggregate (struct / tuple / array). This intentionally
    // does NOT match a bare scalar (a single-`f64` newtype the bridge scalarizes
    // takes the scalar XMM path already) or a union (`memory_aggregate_layout`
    // excludes unions, so a C-ABI union with a float stays fail-closed).
    if !matches!(ty.kind(), ty::Adt(..) | ty::Tuple(..) | ty::Array(..)) {
        return Ok(None);
    }
    // Must be a by-value memory aggregate the bridge slot-backs; this gives the
    // authoritative (size, align) whose uniform-lane structure we mirror, and
    // excludes fat pointers / closures / unions (routed elsewhere).
    let Some(layout) = memory_aggregate_layout_shared(tcx, ty)? else {
        return Ok(None);
    };
    // A Direct-tagged enum's payload eightbyte float classification is not modeled
    // here; leave it to the fail-closed path.
    if layout.tag.is_some() {
        return Ok(None);
    }
    let size = layout.size;
    let align = layout.align;
    if size == 0 || size > 16 || size % align != 0 {
        return Ok(None);
    }
    // Per-eightbyte SSE / INTEGER classification (the same precise Rust-layout walk
    // the has-SSE predicate uses). A `false` return means the shape straddles an
    // eightbyte or is otherwise not modeled exactly — bail (the caller fails closed
    // if it has an SSE eightbyte).
    let cx = LayoutCx(tcx);
    let Ok(tl) = tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty)) else {
        return Ok(None);
    };
    let mut ebs: [Option<bool>; 2] = [None, None];
    if !collect_sysv_eightbyte_float_classes(tcx, &cx, tl, 0, &mut ebs) {
        return Ok(None);
    }
    // No pure-SSE eightbyte → the uniform integer `slot_ty` is already correct
    // (and matches clang for an INTEGER / INTEGER-merged aggregate).
    if !ebs.iter().any(|e| *e == Some(true)) {
        return Ok(None);
    }
    // A float lane exists only for a 4- or 8-aligned aggregate.
    let (sse_lane, int_lane) = match align {
        8 => (TrustIrTy::F64, TrustIrTy::I64),
        4 => (TrustIrTy::F32, TrustIrTy::I32),
        _ => return Ok(None),
    };
    let lanes = (size / align) as usize;
    if lanes == 0 {
        return Ok(None);
    }
    let mut lane_tys = Vec::with_capacity(lanes);
    for i in 0..lanes {
        let off = i as u64 * align;
        let eightbyte = (off / 8) as usize;
        // A lane whose eightbyte is PURE-SSE becomes a float lane; every other lane
        // keeps the integer type `memory_slot_lane_ty` would have used, so the
        // structure is identical and only SSE eightbytes route to XMM.
        let is_sse = ebs.get(eightbyte).copied().flatten() == Some(true);
        lane_tys.push(if is_sse {
            sse_lane.clone()
        } else {
            int_lane.clone()
        });
    }
    Ok(Some(TrustIrTy::Tuple(lane_tys)))
}

/// WHERE a callee leaves a returned value — now a LANE LIST, not a bare
/// "registers vs buffer" verdict.
///
/// `822fdc69` shipped this type with exactly two variants and said so in its own
/// commit message: *"a register-CLASS disagreement is still outside this gate's
/// reach — a `PassMode::Pair` of floats bound for `d0`/`d1`, or a Pair of 32-bit
/// scalars packed into one register, are both 'the return REGISTERS' to
/// `ReturnPlacement`, so it cannot see them."* Both were CONFIRMED live, silent
/// wrong values across a real codegen boundary. The definition now lives in
/// [`abi_reg_lanes`], which carries the class, the count, the per-lane width and
/// the per-lane value offset, so those two cases are exactly what it reports.
use abi_reg_lanes::{
    ArgPlacementVerdict, ReturnPlacement, TrustCgAbiTarget, lanes_disagreement, trust_cg_abi_target,
};

/// Capture real compiler facts for the bounded aggregate ABI policy. This is
/// deliberately called only from aggregate/carrier/sret paths, not scalar-only
/// signatures. The classifier model's architecture enum alone is not admission.
fn check_aggregate_abi_scope<'tcx>(
    tcx: TyCtxt<'tcx>,
    fn_abi: &rustc_target::callconv::FnAbi<'tcx, Ty<'tcx>>,
) -> Result<abi_reg_lanes::TrustCgAbiTarget, String> {
    abi_reg_lanes::aggregate_abi_scope(abi_reg_lanes::AggregateAbiScope {
        arch: tcx.sess.target.arch.desc(),
        target_os: tcx.sess.target.os.desc(),
        is_like_windows: tcx.sess.target.is_like_windows,
        is_like_darwin: tcx.sess.target.is_like_darwin,
        host_os: std::env::consts::OS,
        pointer_bytes: tcx.data_layout.pointer_size().bytes(),
        conv: fn_abi.conv,
        c_variadic: fn_abi.c_variadic,
    })
}

/// Where RUSTC places the return value, read from its own `PassMode` and its own
/// layout — never from the type, its size, or a re-derived rule. `Ok(None)` means
/// rustc passes nothing at all (`PassMode::Ignore`: a ZST / uninhabited return),
/// which is not a placement and is compared separately.
fn rustc_return_placement<'tcx>(
    tcx: TyCtxt<'tcx>,
    ret: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
) -> Result<Option<ReturnPlacement>, String> {
    let placement = abi_reg_lanes::rustc_placement(
        &tcx,
        &ret.mode,
        ret.layout.backend_repr,
        ret.layout.size.bytes(),
        "[TCG-RET-ABI]",
        "return",
    )?;
    // A return is never classified `on_stack` by any target rustc supports (that
    // mode describes an ARGUMENT copied into the outgoing argument area). Refuse
    // rather than map it onto any placement.
    if matches!(placement, Some(ReturnPlacement::StackByValue)) {
        return Err(
            "[TCG-RET-ABI] rustc's FnAbi returns this value with `PassMode::Indirect \
             { on_stack: true }`, a stack-slot return convention trust-cg does not \
             implement and this bridge will not guess at. Failing closed."
                .to_owned(),
        );
    }
    Ok(placement)
}

/// Where TRUST-CG will place the value a function declares as `returns`.
///
/// `returns` is the trust-ir return list `classify_func_ty` is ABOUT TO DECLARE —
/// the same list the backend's own classifier receives — so this is not a
/// re-derivation of trust-cg's rule but a reading of it. On AArch64 it literally
/// calls `AppleAArch64ABI::classify_returns`, the function the instruction
/// selector calls; on x86-64 it applies the System V eightbyte rule the x86-64
/// selector implements. Any other architecture is refused by name rather than
/// compared against a guess.
///
/// `value_offsets` states, per declared return VALUE, which byte of the returned
/// value it carries. One value always starts at 0; the two-register
/// `PassMode::Pair` lane states rustc's own per-lane offsets.
fn trust_cg_return_placement(
    tcx: TyCtxt<'_>,
    returns: &[TrustIrTy],
    value_offsets: &[u64],
) -> Result<ReturnPlacement, String> {
    let arch = tcx.sess.target.arch.desc();
    let Some(target) = trust_cg_abi_target(arch) else {
        return Err(format!(
            "[TCG-RET-REGCLASS] this function returns a by-value aggregate, but trust-cg's \
             register-placement rules for target architecture `{arch}` are not stated by the \
             return-ABI gate, so the gate cannot prove that what the backend emits matches \
             rustc's `FnAbi`. Failing closed rather than emitting a return whose register \
             class or count may silently differ from every independently-compiled caller. \
             Options: (1) build for `aarch64` or `x86_64`, whose placements the gate states \
             exactly; (2) return the value through an explicit out-parameter \
             (`fn f(out: &mut T)`), which crosses no return convention; (3) teach \
             `abi_reg_lanes::trust_cg_return_placement` this architecture's classifier."
        ));
    };
    abi_reg_lanes::trust_cg_return_placement(target, returns, value_offsets, &slot_lane_ty_table())
        .map_err(|why| format!("[TCG-RET-REGCLASS] {why}"))
}

/// The canonical `Module::types` prefix every bridge-built module is seeded with
/// (`seed_slot_lane_types`), rebuilt from the SAME `slot_lane_ty_by_id` mapping
/// rather than read out of a module.
///
/// The ABI gates need it because a uniform memory-slot ABI type is spelled
/// `Ty::Array(TyId, n)` — an O(1) spelling of the lane tuple — and the `TyId`
/// only resolves against this table. Reading it from `self.module` instead would
/// tie the gate to a mutable borrow at three call sites for no added authority:
/// the table is a constant, and `slot_lane_ty_ids_round_trip` pins it.
fn slot_lane_ty_table() -> Vec<TrustIrTy> {
    (0..SLOT_LANE_TY_COUNT)
        .map(|index| slot_lane_ty_by_id(index).expect("lane id below the count resolves"))
        .collect()
}

/// Refuse, in a wasm32 session, a foreign item whose link name is an LLVM
/// intrinsic (`#[link_name = "llvm.wasm.memory.grow.i32"]`, the declarations
/// behind `core::arch::wasm32::memory_size` / `memory_grow`). rustc's LLVM
/// backend turns such a declaration into the intrinsic's instruction; to this
/// backend it is an ordinary import no object defines, so the link would fail
/// on an undefined `llvm.*` symbol. trust-ir has no construct for these
/// instructions (the wasm lane emits no `memory.size` / `memory.grow`: its
/// memory never grows under the code's feet), so the call is refused by name
/// at compile time instead.
fn refuse_wasm32_llvm_intrinsic_import<'tcx>(
    tcx: TyCtxt<'tcx>,
    instance: Instance<'tcx>,
    symbol: &str,
) -> Result<(), String> {
    if session_is_wasm32(tcx)
        && symbol.starts_with("llvm.")
        && tcx.is_foreign_item(instance.def_id())
    {
        return Err(format!(
            "[TCG-WASM32-LLVM-INTRINSIC] `{}` is the LLVM intrinsic `{symbol}`, which rustc's \
             LLVM backend lowers to an instruction; trust-ir has no construct for it (the \
             wasm lane emits no `memory.size` / `memory.grow` and the other `llvm.*` \
             intrinsics are not modeled), so a call would be an import no object defines. \
             Failing closed at compile time rather than at link time.",
            tcx.def_path_str(instance.def_id())
        ));
    }
    Ok(())
}

/// How to reach rustc's OWN `FnAbi` for the callable being classified. The
/// bridge builds its trust-ir signature from the Rust *types*; the RETURN
/// CONVENTION, however, is an ABI fact that only `FnAbi`/`PassMode` may state —
/// see `check_aggregate_return_abi_matches_rustc`.
#[derive(Clone, Copy)]
enum RustcFnAbiSource<'tcx> {
    /// A resolved callee (a defined body, a shim, a `Virtual` vtable entry).
    Instance(Instance<'tcx>),
    /// An indirect call through a `fn(..)` pointer of this signature.
    FnPtr(ty::PolyFnSig<'tcx>),
    /// The CALL-SITE `FnAbi` of a C-variadic callee: its signature plus the
    /// types of the anonymous arguments one call passes (`fn_abi_of_instance`
    /// with `extra_args`), so its `args` are the fixed arguments followed by the
    /// anonymous ones (`variadic::call`). Only that query describes an
    /// anonymous argument.
    VariadicCall(Instance<'tcx>, &'tcx ty::List<Ty<'tcx>>),
}

impl<'tcx> RustcFnAbiSource<'tcx> {
    fn query(
        self,
        tcx: TyCtxt<'tcx>,
    ) -> Result<&'tcx rustc_target::callconv::FnAbi<'tcx, Ty<'tcx>>, String> {
        let env = ty::TypingEnv::fully_monomorphized();
        match self {
            RustcFnAbiSource::Instance(instance) => tcx
                .fn_abi_of_instance(env.as_query_input((instance, ty::List::empty())))
                .map_err(|err| {
                    format!("[TCG-RET-ABI] rustc FnAbi query failed for {instance:?}: {err:?}")
                }),
            RustcFnAbiSource::FnPtr(sig) => tcx
                .fn_abi_of_fn_ptr(env.as_query_input((sig, ty::List::empty())))
                .map_err(|err| {
                    format!(
                        "[TCG-RET-ABI] rustc FnAbi query failed for fn pointer {sig:?}: {err:?}"
                    )
                }),
            RustcFnAbiSource::VariadicCall(instance, extra) => tcx
                .fn_abi_of_instance(env.as_query_input((instance, extra)))
                .map_err(|err| {
                    format!(
                        "[TCG-RET-ABI] rustc FnAbi query failed for the variadic call of \
                         {instance:?} with {extra:?}: {err:?}"
                    )
                }),
        }
    }
}

/// REFUSE any by-value AGGREGATE return whose placement trust-cg's own
/// classifier would disagree with rustc's `FnAbi` about.
///
/// WHY THIS GATE EXISTS. The bridge declares an aggregate return as its flat
/// lane tuple (`MemoryAggregateLayout::slot_ty`) and lets trust-cg's AAPCS64 /
/// System V classifier place it: register pair up to
/// `TRUST_CG_REGISTER_RETURN_MAX_BYTES`, hidden return buffer above it. That is
/// the C rule, and for an `extern "C"` function it is exactly rustc's rule. It
/// is NOT rustc's RUST-ABI rule. `FnAbi::adjust_for_rust_abi` casts a
/// `BackendRepr::Memory` aggregate to an integer register only when it fits in
/// ONE pointer; every larger Memory aggregate keeps `PassMode::Indirect`, so a
/// 9–16 byte one — `Option<i64>`, `[i64; 2]`, a 12-byte struct, and
/// `core::fmt::rt::Argument` / `rt::ArgumentType` — is returned through the
/// `x8` buffer while trust-cg returns it in `x0`/`x1`.
///
/// Measured on this host, 2026-09-10, for `fn(&i32) -> ArgTy<'_>` (the
/// `rt::ArgumentType` shape) at `-Copt-level=0`:
///
/// ```text
/// LLVM      str x8, [sp, #0x8] ... str x0, [x9] ; str x8, [x9, #0x8]   ; writes THROUGH x8
/// trust-cg  ldr x0, [x19] ; ldr x1, [x19, #0x8] ; ret                  ; returns in x0/x1
/// ```
///
/// Both sides are internally consistent, so every WHOLE-PROGRAM differential in
/// this repo passes on it — the disagreement is only observable when a call
/// crosses a codegen boundary, which is the normal state during a staged
/// self-host and was measured as a SIGSEGV in both mixed-link directions
/// (`benchmarks/fmt-selfhost/README.md`). A refusal is always acceptable; a
/// silently divergent ABI is not.
///
/// This gate reads the placement from rustc's `PassMode` and nothing else. It
/// does not re-derive the rule from the type, its size, or its `BackendRepr`.
fn check_aggregate_return_abi_matches_rustc<'tcx>(
    tcx: TyCtxt<'tcx>,
    output: Ty<'tcx>,
    slot_size: u64,
    fn_abi: &rustc_target::callconv::FnAbi<'tcx, Ty<'tcx>>,
    declared_returns: &[TrustIrTy],
    declared_return_offsets: &[u64],
) -> Result<(), String> {
    // Placement kind or lane equality cannot establish calling-convention
    // equality: a Win64 caller buffer uses RCX, not System V's RDI, and the
    // special Rust conventions can change preserved registers even when every
    // returned lane looks identical.
    check_aggregate_abi_scope(tcx, fn_abi)?;
    // The ArgAbi must describe the very type the bridge is classifying;
    // otherwise this is not the return we are about to emit and the comparison
    // would be meaningless. (`FnAbi::ret` is by construction the signature's
    // output; the assertion costs one pointer compare and fails closed.)
    if fn_abi.ret.layout.ty != output {
        return Err(format!(
            "[TCG-RET-ABI] rustc's FnAbi return type `{:?}` does not describe the bridge's \
             classified return `{output:?}`; refusing rather than comparing two different \
             conventions. Options: (1) report this — it is a bridge bug, not a program bug; \
             (2) give the function an `extern \"C\"` ABI, whose return classification trust-cg \
             implements exactly.",
            fn_abi.ret.layout.ty
        ));
    }
    let bridge = trust_cg_return_placement(tcx, declared_returns, declared_return_offsets)?;
    let abi_target = trust_cg_abi_target(tcx.sess.target.arch.desc());
    let rustc_place = rustc_return_placement(tcx, &fn_abi.ret)?;
    let rustc_place = match abi_target {
        Some(target) => abi_reg_lanes::rustc_placement_for_target(target, rustc_place, true),
        None => rustc_place,
    };
    let Some(rustc_place) = rustc_place else {
        // `PassMode::Ignore` — rustc returns NOTHING. The bridge only reaches
        // this gate for a non-zero-sized aggregate slot, so it would return a
        // value the caller never reads a register for.
        return Err(format!(
            "[TCG-RET-ABI] rustc's FnAbi returns `{output:?}` with `PassMode::Ignore` (no ABI \
             slot at all), but the bridge classified it as a {slot_size}-byte by-value \
             aggregate return. Failing closed rather than returning a value no caller reads. \
             Options: (1) return `()` explicitly; (2) report this — an `Ignore`-moded \
             non-zero-sized return is a bridge classification bug."
        ));
    };
    // Same PLACEMENT KIND, then the same LANES. Splitting the two reports keeps
    // the pre-existing "registers vs x8 buffer" message for the case `822fdc69`
    // closed, and adds the class/count detail only where that is the actual
    // disagreement.
    let detail = match (&rustc_place, &bridge) {
        (ReturnPlacement::Registers(want), ReturnPlacement::Registers(got)) => {
            let disagreement = match abi_target {
                Some(target) => abi_reg_lanes::lanes_disagreement_for(target, want, got),
                None => lanes_disagreement(want, got),
            };
            match disagreement {
                None => return Ok(()),
                Some(detail) => detail,
            }
        }
        (a, b) if a == b => return Ok(()),
        _ => "the two classifiers do not even agree on the KIND of placement".to_owned(),
    };
    let options = abi_reg_lanes::ret_abi_options(abi_target);
    Err(format!(
        "[TCG-RET-ABI] by-value aggregate return `{output:?}` ({slot_size} bytes): rustc's own \
         FnAbi places it in {rustc_target}, but trust-cg would place it in {bridge_target} — \
         {detail} (rustc `PassMode::{mode:?}`; bridge return type {declared_returns:?}). \
         Emitting it would disagree with every independently-compiled (LLVM) caller or callee \
         of this function — a wrong value, {misread}, or a corrupted return buffer at a real \
         ABI boundary, and one no whole-program differential can see because both sides of \
         such a test are built by the same backend. Failing closed rather than emitting an \
         ABI-nonconformant return. {options}",
        rustc_target = rustc_place.describe_for(abi_target),
        bridge_target = bridge.describe_for(abi_target),
        misread = abi_reg_lanes::boundary_misread(abi_target),
        mode = fn_abi.ret.mode,
    ))
}

/// The per-parameter attribute vector for a callable whose parameter 0 is the
/// hidden return buffer.
///
/// trust-ir's `ParamAttrs::sret` is the ABI-PINNING half of its parameter
/// attributes: unlike `noalias`/`readonly`, which are discardable hints,
/// disagreement about `sret` changes the call's byte-level ABI. The buffer
/// pointer is also non-null and does not alias the callee's other arguments —
/// rustc puts exactly those attributes on its own indirect return — so they are
/// stated here too, where they are true by construction.
fn sret_leading_param_attrs() -> Vec<trust_ir::ParamAttrs> {
    vec![trust_ir::ParamAttrs {
        sret: true,
        nonnull: true,
        noalias: true,
        ..trust_ir::ParamAttrs::default()
    }]
}

/// The hidden return-buffer plan for the function currently being lowered.
///
/// `layout` is the bridge's own slot layout for the returned aggregate (the
/// same one the body's `_0` slot uses), and `ptr` is the trust-ir value the
/// entry block binds the CALLER's buffer address to. `TerminatorKind::Return`
/// copies the slot's bytes through `ptr` and then returns no value at all.
#[derive(Clone, Debug)]
struct SretBodyPlan {
    layout: MemoryAggregateLayout,
    ptr: ValueId,
}

/// A `PassMode::Pair` return the bridge lowers as TWO ABI VALUES.
///
/// # Why two values and not one lane tuple
///
/// rustc classifies a `BackendRepr::ScalarPair` aggregate `PassMode::Pair`,
/// which means two independent ABI values of the scalars' OWN classes and
/// widths. LLVM's `RetCC_AArch64_AAPCS` then assigns each one the next return
/// register of its class: `{i32,i32}` comes back in `w0` AND `w1`, `{i16,i16}`
/// in `w0` and `w1`, `{i32,f64}` in `w0` and `d0`.
///
/// The bridge used to declare ONE value — the slot's uniform lane tuple — and
/// trust-cg's classifier then applied the C rule for a composite of that SIZE:
/// an aggregate of 8 bytes or fewer goes WHOLE into ONE register. MEASURED
/// 2026-09-11 across a real codegen boundary, `struct Q { a: i32, b: i32 }`:
/// LLVM's callee is `ldr w0 / ldur w1 / ret`, trust-cg's was `ldr x0,[x1]`, and
/// the mixed links exited 188/28 and 20 where the oracle exits 42.
///
/// `AppleAArch64ABI::classify_returns` already allocates a LIST of return values
/// correctly — integer results take `w0`,`w1`,… and floating results their own
/// `d0`,`d1`,… sequence — so declaring the two scalars as two return values is
/// all it takes to land on rustc's registers. The callee loads each lane from
/// its return slot at the layout offset rustc states; the caller stores each
/// result back at the same offset. The BYTES are identical to what the one-value
/// lane tuple moved; only the register placement changes.
///
/// `offsets` are rustc's, not the bridge's: lane 0 at 0, lane 1 at the first
/// scalar's size rounded up to the second's ABI alignment — the same rule
/// `rustc_codegen_ssa` uses to store an `OperandValue::Pair`.
#[derive(Clone, Debug)]
struct ScalarPairAbiPlan {
    /// `(trust-ir lane type, byte offset within the value)`, in ABI order.
    lanes: [(TrustIrTy, u64); 2],
    /// The ABI VALUE each lane travels as. This is the lane type itself except
    /// where rustc's `ArgAttributes::arg_ext` requires an integer lane narrower
    /// than 32 bits to be zero- or sign-EXTENDED across the boundary — the
    /// `Zext` rustc puts on a `bool`-valued lane such as an `Option`/`Result`
    /// tag — in which case it is the 32-bit carrier the lane is extended into.
    /// That matters on x86-64: a narrow lane's register upper bits are
    /// otherwise unspecified, and an LLVM caller compiled against `zeroext`
    /// reads the whole 32-bit register. On AArch64 the narrow lane loads
    /// (`LDRB`/`LDRH`) already zero-extend into the W register and the
    /// classifier places a W-carrier the same way, so the carrier is the lane
    /// type there and the qualified AArch64 behavior is unchanged.
    carriers: [TrustIrTy; 2],
    /// The extension that turns lane `i` into `carriers[i]`; `None` when the
    /// carrier IS the lane type.
    lane_ext: [Option<CastOp>; 2],
    /// Whether lane `i` is a `bool`-valued scalar (rustc `Scalar::is_bool`:
    /// an integer with valid range `0..=1`, the tag of `Option<u8>`,
    /// `Result<u8, _>`, `(u8, bool)`), on the targets where that matters.
    ///
    /// LLVM lowers such a lane as an `i1`. Measured 2026-09-20 on x86-64
    /// Linux: an LLVM-compiled `fn res_u8(n: u32) -> Result<u8, u8>` at O1
    /// returns with `al` holding the whole input `n` and only its bit 0
    /// meaning the tag (`mov %edi,%eax; test $1,%al; ...; ret`); LLVM's own
    /// callers mask. A consumer that stores the full byte reads a tag that is
    /// neither 0 nor 1 and traps on the unreachable arm. The caller half
    /// therefore keeps bit 0 only (`Trunc` to `Bool`, then `ZExt` back to
    /// the lane type) before storing such a lane. The callee half is
    /// unchanged: it loads a canonical 0/1 and extends it fully, which is
    /// stronger than what an LLVM caller relies on.
    lane_bool: [bool; 2],
    /// The bridge's slot layout for the aggregate — the same one the body's
    /// `_0` uses and the caller's destination must match.
    layout: MemoryAggregateLayout,
}

impl ScalarPairAbiPlan {
    /// Load lane `lane` from `addr` (its slot address at rustc's offset) and
    /// widen it to the ABI carrier the signature declares — the callee half.
    fn load_lane_carrier(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        addr: ValueId,
        lane: usize,
    ) -> ValueId {
        let (lane_ty, _) = &self.lanes[lane];
        let loaded = emit_typed_load(ctx, block, addr, lane_ty.clone());
        let Some(op) = self.lane_ext[lane] else {
            return loaded;
        };
        let widened = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op,
                src_ty: lane_ty.clone(),
                dst_ty: self.carriers[lane].clone(),
                operand: loaded,
            })
            .with_result(widened),
        );
        widened
    }

    /// Narrow the ABI carrier value `carrier` of lane `lane` back to the lane
    /// type so it can be stored at rustc's offset — the caller half.
    fn narrow_carrier(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        lane: usize,
        carrier: ValueId,
    ) -> ValueId {
        let lane_ty = self.lanes[lane].0.clone();
        let carrier_ty = self.carriers[lane].clone();
        // Keep bit 0 only for a `bool`-valued lane (see `lane_bool`): an
        // integer AND at the carrier's width, which every selector lowers,
        // rather than a `Bool` round trip (the x86-64 selector has no
        // `Uextend { from: B1 }` form).
        let carrier = if self.lane_bool[lane] {
            let one = emit_typed_const(ctx, block, carrier_ty.clone(), 1);
            let masked = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::And,
                    ty: carrier_ty.clone(),
                    lhs: carrier,
                    rhs: one,
                })
                .with_result(masked),
            );
            masked
        } else {
            carrier
        };
        if self.lane_ext[lane].is_none() {
            return carrier;
        }
        let narrowed = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::Trunc,
                src_ty: carrier_ty,
                dst_ty: lane_ty,
                operand: carrier,
            })
            .with_result(narrowed),
        );
        narrowed
    }
}

/// The ARGUMENT twin of [`ScalarPairAbiPlan`]: a by-value aggregate parameter
/// the bridge declares as rustc's TWO `PassMode::Pair` ABI values instead of
/// one whole-slot value.
///
/// # Why arguments need their own type
///
/// The plan is applied at THREE independent sites — the declaration
/// (`classify_func_ty`), the callee body's entry block, and every call site —
/// and a parameter declaration is GLOBAL to the callee, so all three must reach
/// the same decision or the trust-ir module is arity-inconsistent. They do,
/// because all three call the ONE decision function
/// (`MirLoweringCtx::scalar_pair_param_plan`) with the same three facts. The
/// `ty` field is the belt to that braces: every consumer checks it against the
/// parameter it is about to apply the plan to, so a plan can never be applied to
/// a parameter other than the one rustc's `ArgAbi` described — which is what
/// keeps an index-mapping slip (MIR arg local vs. the bridge's unflattened
/// `inputs` index) a loud refusal rather than a wrong register.
///
/// # What travels
///
/// The two declared values are the plan's CARRIERS, exactly as on the return
/// side: on x86-64 a `Zext` lane narrower than 32 bits travels as its
/// zero-extended 32-bit carrier (what an LLVM callee compiled against
/// `zeroext i1`/`i8`/`i16` reads), and the callee half masks a `bool`-valued
/// lane to bit 0 before storing it (`ScalarPairAbiPlan::narrow_carrier`) for
/// the measured LLVM `i1` convention. On AArch64 the carriers ARE the lane
/// types, so the AArch64-measured behaviour (62befd1db) is unchanged.
#[derive(Clone, Debug)]
struct ScalarPairParamPlan<'tcx> {
    /// The normalized Rust type this plan was computed for.
    ty: Ty<'tcx>,
    /// The lanes, carriers, extensions and slot layout — one plan, shared with
    /// the return side so the two lanes cannot drift on anything.
    plan: ScalarPairAbiPlan,
}

impl ScalarPairParamPlan<'_> {
    /// The two ABI values the parameter is declared as.
    fn declared(&self) -> [TrustIrTy; 2] {
        self.plan.carriers.clone()
    }

    /// rustc's own byte offset of each lane within the argument.
    fn offsets(&self) -> [u64; 2] {
        [self.plan.lanes[0].1, self.plan.lanes[1].1]
    }
}

/// A byte home, in the refusal text of the whole-signature placement check.
fn describe_byte_home(home: Option<abi_reg_lanes::ByteHome>) -> String {
    use abi_reg_lanes::ByteHome;
    match home {
        None => "no home at all".to_owned(),
        Some(ByteHome::Gpr { reg, byte }) => format!("integer argument register {reg} byte {byte}"),
        Some(ByteHome::Fpr { reg, byte }) => {
            format!("floating/vector argument register {reg} byte {byte}")
        }
        Some(ByteHome::Stack { offset }) => format!("the outgoing argument area at +{offset}"),
    }
}

/// The byte offsets below `live_bytes` that some scalar of the value laid out as
/// `layout` covers, ascending — the bytes a narrow-`Cast` caller reads
/// (`NarrowCastPlan`) — or `None` when that set is not a fact of the type: a
/// union, or an enum with more than one variant, whose initialized bytes depend
/// on the value (such a value gets no narrow-cast plan). Read
/// from rustc's layout alone (field offsets, array strides), so field
/// reordering, nested aggregates and arrays inside structs are covered alike;
/// every other byte is padding.
fn narrow_cast_field_bytes<'tcx>(
    tcx: TyCtxt<'tcx>,
    layout: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
    live_bytes: u64,
) -> Option<Vec<u64>> {
    fn cover<'tcx>(
        cx: &LayoutCx<'tcx>,
        layout: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
        base: u64,
        covered: &mut [bool],
    ) -> Option<()> {
        use rustc_abi::{FieldsShape, Variants};
        if !matches!(layout.variants, Variants::Single { .. }) {
            return None;
        }
        match &layout.fields {
            FieldsShape::Primitive => {
                let end = base.checked_add(layout.size.bytes())?;
                for byte in base..end {
                    *covered.get_mut(usize::try_from(byte).ok()?)? = true;
                }
            }
            FieldsShape::Union(_) => return None,
            FieldsShape::Array { stride, count } => {
                if *count > 0 {
                    let element = layout.field(cx, 0);
                    for i in 0..*count {
                        let offset = base.checked_add(stride.bytes().checked_mul(i)?)?;
                        cover(cx, &element, offset, covered)?;
                    }
                }
            }
            FieldsShape::Arbitrary { offsets, .. } => {
                for (i, offset) in offsets.iter().enumerate() {
                    let field = layout.field(cx, i);
                    cover(cx, &field, base.checked_add(offset.bytes())?, covered)?;
                }
            }
        }
        Some(())
    }
    let mut covered = vec![false; usize::try_from(live_bytes).ok()?];
    cover(&LayoutCx(tcx), layout, 0, &mut covered)?;
    let bytes: Vec<u64> = (0..live_bytes)
        .filter(|&byte| covered[byte as usize])
        .collect();
    (!bytes.is_empty()).then_some(bytes)
}

/// A by-value argument rustc passes as ONE INTEGER of its own size — a Rust-ABI
/// `PassMode::Cast` whose single integer unit spans the whole value (`[u8; 4]`
/// -> `i32`, `struct { u8, u8, u8 }` -> `i24`, `[u16; 1]` -> `i16`) — decided
/// ONCE by `MirLoweringCtx::narrow_cast_param_plan` (whose `PassMode` half is
/// the pure `integer_cast_args::plan`) and applied, from the same three facts,
/// by the declaration, the callee's entry block and every call site (trust-ir
/// §17: the crossing is spelled as what rustc passes, never as the memory slot).
///
/// The bridge keeps the value in its memory slot on both sides; only the
/// crossing changes. The caller assembles the carrier from one-byte loads of
/// the value's FIELD bytes (`field_bytes`, from rustc's own layout,
/// `narrow_cast_field_bytes`): a padding byte is never read and travels as
/// zero, so a struct's padding is not loaded (trust-ir's plain scalar load of
/// an uninitialized byte yields poison, and inspecting it is undefined
/// behaviour), and no load is wider than the slot's alignment. A union or a
/// multi-variant enum, whose initialized bytes depend on the value, gets no
/// plan: one uninitialized byte packed into the carrier would make the whole
/// carrier poison, so it keeps its slot. The callee splits the carrier
/// back into the value's `live_bytes` bytes and stores each into the
/// parameter's slot, never past it (not even the fourth byte of a three-byte
/// `i24`).
#[derive(Clone, Debug)]
struct NarrowCastPlan<'tcx> {
    /// The normalized Rust type this plan was computed for.
    ty: Ty<'tcx>,
    /// The integer LLVM legalizes rustc's `iN` to (`integer_cast_args::plan`):
    /// `U8` (1 byte), `U16` (2), `U32` (3, 4), `U64` (5..=8).
    carrier: TrustIrTy,
    /// The value's size in bytes: the carrier's live low bytes.
    live_bytes: u64,
    /// The byte offsets some scalar field of the value covers, ascending;
    /// every other byte below `live_bytes` is padding.
    field_bytes: Vec<u64>,
}

impl NarrowCastPlan<'_> {
    /// CALLER half: the carrier assembled from the value's field bytes in the
    /// slot `slot_ptr` (little-endian: byte `k` lands at bit `8k`; padding
    /// bits stay zero).
    fn load_carrier(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        slot_ptr: ValueId,
    ) -> ValueId {
        let ty = self.carrier.clone();
        let mut packed = emit_typed_const(ctx, block, ty.clone(), 0);
        for &byte in &self.field_bytes {
            let addr = slot_byte_ptr(ctx, block, slot_ptr, byte);
            let loaded = emit_typed_load(ctx, block, addr, TrustIrTy::U8);
            let widened = if ty == TrustIrTy::U8 {
                loaded
            } else {
                let value = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::ZExt,
                        src_ty: TrustIrTy::U8,
                        dst_ty: ty.clone(),
                        operand: loaded,
                    })
                    .with_result(value),
                );
                value
            };
            let shifted = if byte == 0 {
                widened
            } else {
                let shift = emit_typed_const(ctx, block, ty.clone(), i128::from(byte * 8));
                let value = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Shl,
                        ty: ty.clone(),
                        lhs: widened,
                        rhs: shift,
                    })
                    .with_result(value),
                );
                value
            };
            let value = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::BinOp {
                    op: TrustIrBinOp::Or,
                    ty: ty.clone(),
                    lhs: packed,
                    rhs: shifted,
                })
                .with_result(value),
            );
            packed = value;
        }
        packed
    }

    /// CALLEE half: split the incoming `carrier` value back into the value's
    /// `live_bytes` bytes and store them into the parameter's slot `slot_ptr`.
    fn store_carrier(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        carrier: ValueId,
        slot_ptr: ValueId,
    ) {
        let ty = self.carrier.clone();
        for byte in 0..self.live_bytes {
            let shifted = if byte == 0 {
                carrier
            } else {
                let shift = emit_typed_const(ctx, block, ty.clone(), i128::from(byte * 8));
                let value = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::LShr,
                        ty: ty.clone(),
                        lhs: carrier,
                        rhs: shift,
                    })
                    .with_result(value),
                );
                value
            };
            let narrowed = if ty == TrustIrTy::U8 {
                shifted
            } else {
                let value = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::Trunc,
                        src_ty: ty.clone(),
                        dst_ty: TrustIrTy::U8,
                        operand: shifted,
                    })
                    .with_result(value),
                );
                value
            };
            let addr = slot_byte_ptr(ctx, block, slot_ptr, byte);
            emit_typed_store(block, addr, TrustIrTy::U8, narrowed);
        }
    }
}

/// A by-value argument rustc passes as `PassMode::Indirect { on_stack: false }`
/// — one pointer to a caller-made copy — decided ONCE by
/// `MirLoweringCtx::indirect_arg_param_plan` and applied, from the same three
/// facts, by the declaration, the callee's entry block and every call site.
/// `ty` is the belt to that braces, as on `ScalarPairParamPlan`: every consumer
/// checks it against the parameter it is about to apply the plan to.
#[derive(Clone, Debug)]
struct IndirectArgPlan<'tcx> {
    /// The normalized Rust type this plan was computed for.
    ty: Ty<'tcx>,
    /// rustc's size and ABI alignment of the value: the extent and alignment of
    /// the copy the caller makes (`ArgAttributes::pointee_size` /
    /// `pointee_align`, checked equal to the bridge's slot layout).
    size: u64,
    align: u64,
    /// `None`: the bridge models the value as a memory slot, copied lane by lane
    /// on both sides. `Some(leaf)`: THE SCALAR SUB-LANE — the bridge models the
    /// value as the one scalar `leaf` (an over-aligned single-scalar newtype,
    /// `padded_scalar_newtype_leaf`), which sits at byte offset 0 of rustc's
    /// padded layout: the caller stores it there in a fresh copy of `size` /
    /// `align`, the callee loads it back from the incoming pointer.
    scalar: Option<TrustIrTy>,
}

/// Whether rustc lays `ty` out as a sized `BackendRepr::Memory` value — the only
/// representation its Rust ABI passes as an aggregate (`Indirect` above a
/// pointer, a `Cast` to one integer register at or below). A cheap, cached
/// pre-filter: an ordinary scalar is `BackendRepr::Scalar` and never needs its
/// `FnAbi` read on the scalar arms.
fn rustc_layout_is_memory<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .is_ok_and(|layout| {
            matches!(
                layout.backend_repr,
                rustc_abi::BackendRepr::Memory { sized: true }
            )
        })
}

/// Whether the bridge's ONE `Ptr` for a by-value `ty` is the address of its OWN
/// intercepted-collection slot rather than the value's bytes: `Vec` / `String` /
/// `BTreeMap` / `HashMap` and the dead `HashMap` internals (the arms of
/// `rust_ty_to_trust_ir_ty_inner` that type each as a bare `Ptr`), or a struct
/// or union whose only non-zero-sized field is, transitively, one of them
/// (`struct S { v: Vec<u64> }`, `ManuallyDrop<Vec<u64>>`, `MaybeUninit<String>`,
/// which the mapper collapses to that field's `Ptr`).
///
/// Decided by IDENTITY — the interception predicates the type mapper itself keys
/// on — and never by the declared type: a padded raw pointer, `&T`, `Box`, `fn`
/// pointer, `NonNull` or `AtomicPtr` newtype, or a pointer-carrier union, is ONE
/// `Ptr` to the bridge too, but that pointer IS its bytes, so rustc's mode for it
/// must be honoured. The scalar arms' refusals (`refuse_scalar_declared_memory_arg`,
/// `check_scalar_return_abi`, the `dyn Fn*` spread) exempt exactly these types:
/// a collection passed or returned by value across a real backend boundary is a
/// separate known gap (`LIMITATIONS.md`, measured 139 in both directions) that a
/// refusal at the scalar arm would not close.
fn is_intercepted_collection_value_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let typing_env = ty::TypingEnv::fully_monomorphized();
    let mut cur = ty;
    // A newtype chain is short; running out of the bound declines (not exempt).
    for _ in 0..16 {
        if vec_element_ty(tcx, cur).is_some()
            || is_string_ty(tcx, cur)
            || btreemap_kv_ty(tcx, cur).is_some()
            || any_hashmap_kv_ty(tcx, cur).is_some()
            || is_hashmap_dead_internal_ty(tcx, cur)
        {
            return true;
        }
        let ty::Adt(adt, args) = cur.kind() else {
            return false;
        };
        if !adt.is_struct() && !adt.is_union() {
            return false;
        }
        let mut only = None;
        for field in adt.non_enum_variant().fields.iter() {
            let field_ty = tcx.normalize_erasing_regions(typing_env, field.ty(tcx, *args));
            if is_zero_sized_ty(tcx, field_ty) {
                continue;
            }
            if only.is_some() {
                return false;
            }
            only = Some(field_ty);
        }
        let Some(next) = only else {
            return false;
        };
        cur = next;
    }
    false
}

/// THE SCALAR SUB-LANE's shape test (`MirLoweringCtx::indirect_arg_param_plan`).
///
/// `Some(leaf)` exactly when the bridge's type mapper gives `ty` ONE scalar
/// `leaf` (`rust_ty_to_trust_ir_ty`) while rustc's own layout is a sized
/// `BackendRepr::Memory` value LARGER than a pointer whose only non-zero-sized
/// content is that scalar at byte offset 0 — a chain of single-non-ZST-field
/// structs over one `BackendRepr::Scalar` of the leaf's byte width and register
/// class. That is an OVER-ALIGNED single-scalar newtype: `#[repr(C, align(16))]
/// struct A16 { a: u64 }`, `#[repr(align(128))] struct CachePadded(u64)`,
/// `#[repr(align(16))] struct A8(u8)`, `#[repr(align(16))] struct F(f64)`, whose
/// `repr(align)` pads it past the scalar, so rustc no longer passes the scalar.
///
/// Every fact is read from rustc's layout (offsets, field count, the leaf's
/// `Primitive`), never from the type's name. `None` for anything else — in
/// particular for the intercepted collections (`Vec` / `String` / the maps),
/// which the bridge types as one `Ptr` to its OWN slot while rustc's layout has
/// several fields: that is not a scalar inside padding, and this lane must not
/// claim it.
fn padded_scalar_newtype_leaf<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Option<TrustIrTy> {
    let (leaf, size, _align) = padded_scalar_at_offset_zero(tcx, ty, false)?;
    (size > tcx.data_layout.pointer_size().bytes()).then_some(leaf)
}

/// The EXTENT (`size`, `align`) a stack HOME of `ty` must have when the bridge
/// keeps `ty` as the one scalar `leaf` but rustc's layout pads it — `None` when
/// the leaf's own natural extent (the one `Alloca { ty: leaf, align: None }`
/// gets) already covers rustc's.
///
/// An over-aligned single-scalar newtype (`#[repr(C, align(16))] struct A16 { a:
/// u64 }`, `#[repr(align(128))] struct CachePadded(u64)`) or single-field union
/// is ONE scalar to the bridge, so every stack home it gets — a scalar cell, the
/// temporary behind a `&x` passed to a call, the data half of a `&x as &dyn
/// Trait` — used to be an `Alloca` of the scalar: 8 bytes, 8-aligned. A
/// reference to it is a `&A16`, which rustc promises is 16-aligned and points at
/// 16 bytes. MEASURED before (review finding, 2026-09-28, x86-64): a probe
/// flagging a misaligned `&A16` gave 8 (none) for LLVM x LLVM and 13 / 10 / 15
/// in the rlib x bin cells with a bridge side, and an LLVM `-O2` callee
/// `store(r: &N16)` that loads the promised 16 aligned bytes SIGSEGV'd on a
/// bridge local (6 against 139). The home is now `alloca_rustc_extent(size,
/// align)` with the scalar at offset 0 (where rustc's layout puts it,
/// `padded_scalar_at_offset_zero`). Scoped like the indirect argument lane
/// (`rust_abi_indirect_lane_target`: x86-64 and AArch64, not Windows).
fn padded_scalar_home_extent<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
    leaf: &TrustIrTy,
) -> Option<(u64, u64)> {
    if !ctx.indirect_arg_lane_scope() {
        return None;
    }
    let ty = ctx.normalize_ty(ty);
    let (walked, size, align) = padded_scalar_at_offset_zero(ctx.tcx, ty, true)?;
    if walked != *leaf {
        return None;
    }
    let natural = trust_cg_lower::adapter::translate_type(leaf).ok()?;
    (size > u64::from(natural.bytes()) || align > u64::from(natural.align()))
        .then_some((size, align))
}

/// The layout walk behind `padded_scalar_newtype_leaf` (the argument sub-lane)
/// and `padded_scalar_home_extent` (a scalar's stack home): `Some((leaf, size,
/// align))` when rustc lays `ty` out as a sized `BackendRepr::Memory` value of
/// `size` bytes aligned to `align` whose only non-zero-sized content is the one
/// scalar the bridge's type mapper gives it (`leaf`), at byte offset 0 — a chain
/// of single-non-ZST-field structs (and, with `allow_union`, single-non-ZST-field
/// unions, every field of which is at offset 0) over one `BackendRepr::Scalar`
/// of the leaf's byte width and register class.
fn padded_scalar_at_offset_zero<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    allow_union: bool,
) -> Option<(TrustIrTy, u64, u64)> {
    use rustc_abi::{BackendRepr, FieldsShape, Primitive, Variants};
    let typing_env = ty::TypingEnv::fully_monomorphized();
    let outer = tcx.layout_of(typing_env.as_query_input(ty)).ok()?;
    if !matches!(outer.backend_repr, BackendRepr::Memory { sized: true }) {
        return None;
    }
    let (size, align) = (outer.size.bytes(), outer.align.bytes());
    let leaf = rust_ty_to_trust_ir_ty(tcx, ty).ok()?;
    let leaf_is_float = matches!(leaf, TrustIrTy::F32 | TrustIrTy::F64);
    let leaf_bytes = match leaf.bit_width() {
        Some(bits) => u64::from(bits).div_ceil(8),
        None if is_pointer_like_trust_ir_ty(&leaf) => tcx.data_layout.pointer_size().bytes(),
        None => return None,
    };
    let cx = LayoutCx(tcx);
    let mut layout = outer;
    // A newtype chain is short; the bound only keeps a malformed layout from
    // looping, and running out of it declines the shape.
    for _ in 0..16 {
        match layout.backend_repr {
            BackendRepr::Scalar(scalar) => {
                let is_float = matches!(scalar.primitive(), Primitive::Float(_));
                return (scalar.size(&cx).bytes() == leaf_bytes && is_float == leaf_is_float)
                    .then_some((leaf, size, align));
            }
            BackendRepr::Memory { sized: true } => {}
            _ => return None,
        }
        let fields_ok = match layout.fields {
            FieldsShape::Arbitrary { .. } => true,
            FieldsShape::Union(_) => allow_union,
            _ => false,
        };
        if !matches!(layout.variants, Variants::Single { .. }) || !fields_ok {
            return None;
        }
        let mut only = None;
        for index in 0..layout.fields.count() {
            let field = layout.field(&cx, index);
            if field.is_zst() {
                continue;
            }
            if only.is_some() {
                return None;
            }
            only = Some((index, field));
        }
        let (index, field) = only?;
        if layout.fields.offset(index).bytes() != 0 {
            return None;
        }
        layout = field;
    }
    None
}

/// A mismatch this guard finds between rustc's `mode` and the bridge's ONE
/// scalar declaration. `None` means none of these refusal conditions applies;
/// the whole-signature check remains separate. Shared by the argument
/// (`refuse_scalar_declared_memory_arg`) and return (`check_scalar_return_abi`)
/// scalar arms, which consult it only for a `BackendRepr::Memory` value.
///
/// * `Indirect` places no scalar at all: a pointer to a copy (`on_stack: false`,
///   also the hidden return buffer) or a `byval` stack copy (`on_stack: true`).
/// * `Cast` places the bytes in registers of the cast's kinds; a scalar carrier
///   of the other register file (a float scalar where rustc casts to an INTEGER
///   register, or the reverse) is read from the wrong file. A narrower carrier of
///   the SAME file is fine: the cast's bytes above the scalar are the padding the
///   `repr(align)` added, which neither side reads.
/// * Leading padding adds ABI arguments absent from the scalar declaration.
///   Matching value register classes does not establish a matching signature.
fn scalar_declared_mode_disagreement(
    mode: &rustc_target::callconv::PassMode,
    declared: &TrustIrTy,
) -> Option<String> {
    crate::scalar_abi_admission::scalar_declared_mode_disagreement(mode, declared)
}

/// Copy `layout.size` bytes from `src` into the aggregate at `dst` in
/// `layout.align`-wide lanes: a typed `Load` from `src + k * lane` and a write of
/// lane `k` into `dst` through `emit_aggregate_field_store` (the lane's byte
/// address plus a typed `Store`, never a store-form `InsertField`, which trust-ir
/// does not define). `dst`
/// must be the uniform lane tuple `memory_slot_lane_ty` builds, which is checked
/// rather than assumed, so the copy is byte-exact, padding included.
fn copy_aggregate_lanes(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    src: ValueId,
    dst: ValueId,
    layout: &MemoryAggregateLayout,
) -> Result<(), String> {
    let shape = closure_body_abi::lane_copy_shape(layout)?;
    closure_body_abi::emit_lane_copy(ctx, block, src, dst, layout, shape)
}

/// A FRESH caller-made copy of the argument bytes at `src`: a new `Alloca` of the
/// slot's size and alignment filled by `copy_aggregate_lanes` and registered in
/// `fresh_arg_copies`. Its address is what an indirect argument passes.
fn materialize_fresh_arg_copy(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    src: ValueId,
    layout: &MemoryAggregateLayout,
) -> Result<ValueId, String> {
    let copy = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: layout.slot_ty.clone(),
            count: None,
            align: Some(layout.align),
        })
        .with_result(copy),
    );
    copy_aggregate_lanes(ctx, block, src, copy, layout)?;
    ctx.fresh_arg_copies.insert(copy);
    Ok(copy)
}

/// THE SCALAR SUB-LANE, caller half: a FRESH copy of rustc's padded extent
/// (`size` bytes, aligned to `align`, `alloca_rustc_extent`) holding `value:
/// leaf` at offset 0, whose address is the argument; registered in
/// `fresh_arg_copies`. The callee is promised (`ArgAttributes::pointee_align`) a
/// pointer of rustc's alignment and an LLVM callee may rely on it.
fn materialize_fresh_scalar_arg_copy(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    value: ValueId,
    leaf: TrustIrTy,
    size: u64,
    align: u64,
) -> ValueId {
    let copy = alloca_rustc_extent(ctx, block, size, align);
    emit_typed_store(block, copy, leaf, value);
    ctx.fresh_arg_copies.insert(copy);
    copy
}

/// A stack region of `size` bytes whose ADDRESS is aligned to `align` — the
/// extent and alignment of a value in rustc's own layout, for a value the
/// bridge otherwise keeps as one narrower, less-aligned scalar.
///
/// trust-cg's frame layout honours an `Alloca`'s alignment only up to
/// `TARGET_STACK_ALIGN_BYTES`, so a larger alignment (`#[repr(align(128))]`, the
/// `CachePadded` shape) over-allocates by the difference and rounds the address
/// up explicitly. Shared by the scalar sub-lane's fresh argument copy
/// (`materialize_fresh_scalar_arg_copy`) and by every stack HOME of an
/// over-aligned scalar (`padded_scalar_home_extent`): a scalar cell, and the
/// temporary behind a `&x` handed to a call or to a `&dyn` data pointer.
fn alloca_rustc_extent(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    size: u64,
    align: u64,
) -> ValueId {
    let align = align.max(1);
    let slack = align.saturating_sub(TARGET_STACK_ALIGN_BYTES);
    let count = emit_i64_const(ctx, block, i128::from(size + slack));
    let raw = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I8,
            count: Some(count),
            align: Some(align.min(TARGET_STACK_ALIGN_BYTES)),
        })
        .with_result(raw),
    );
    let copy = if slack == 0 {
        raw
    } else {
        // `(addr + align - 1) & -align`: inside the over-allocation by
        // construction (`slack = align - TARGET_STACK_ALIGN_BYTES` covers the
        // largest round-up from a `TARGET_STACK_ALIGN_BYTES`-aligned base).
        let base = coerce_to_plain_ptr(ctx, block, raw);
        let base_int = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::PtrToInt,
                src_ty: TrustIrTy::Ptr,
                dst_ty: TrustIrTy::I64,
                operand: base,
            })
            .with_result(base_int),
        );
        let bump = emit_i64_const(ctx, block, i128::from(align - 1));
        let bumped = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::Add,
                ty: TrustIrTy::I64,
                lhs: base_int,
                rhs: bump,
            })
            .with_result(bumped),
        );
        let mask = emit_i64_const(ctx, block, -i128::from(align));
        let aligned_int = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::And,
                ty: TrustIrTy::I64,
                lhs: bumped,
                rhs: mask,
            })
            .with_result(aligned_int),
        );
        let aligned = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Cast {
                op: CastOp::IntToPtr,
                src_ty: TrustIrTy::I64,
                dst_ty: TrustIrTy::Ptr,
                operand: aligned_int,
            })
            .with_result(aligned),
        );
        aligned
    };
    copy
}

/// THE INDIRECT ARGUMENT, caller half (`MirLoweringCtx::indirect_arg_param_plan`):
/// the address of a FRESH copy of the argument's bytes in rustc's own layout.
///
/// * A whole memory-backed local (the common shape, `Copy` and `Move` alike): its
///   slot's bytes are copied into a new `Alloca` (`materialize_fresh_arg_copy`).
///   rustc passes a `Move` operand's own place; the fresh copy needs no liveness
///   argument and leaves the local intact whatever the callee writes.
/// * A constant, a `*p` read, a constant-offset SUB-PLACE (of a memory-backed or
///   a scalarized base) and a SCALARIZED local packed at rustc's field offsets:
///   `lower_memory_aggregate_byval_call_arg`, whose arms for those shapes each
///   build and register a fresh `Alloca` in rustc's layout.
/// * Anything else — a scalarized local the rustc-offset packer declines (its
///   flat declaration-order tuple is NOT rustc's layout), a memory-backed local
///   with no aggregate layout (the non-fresh `slot.ptr` fallback) — is refused by
///   name.
fn lower_indirect_call_arg_copy<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    index: usize,
    operand: &Operand<'tcx>,
    plan: &IndirectArgPlan<'tcx>,
) -> Result<ValueId, String> {
    let refuse = |why: &str| {
        format!(
            "[TCG-ARG-ABI] by-value argument {index} `{:?}` ({} bytes) travels as rustc's \
             `PassMode::Indirect` — a POINTER to a copy the caller makes — but {why}. \
             Failing closed rather than passing an address whose bytes are not a fresh copy \
             in rustc's layout. Options: (1) bind the value to a plain local immediately \
             before the call, so it owns a slot; (2) pass it by reference (`&T`), which is \
             one pointer on both sides; (3) report the shape.",
            plan.ty, plan.size
        )
    };
    // THE SCALAR SUB-LANE: the operand is the one scalar the bridge types the
    // value as (the scalar path every other scalar argument takes), stored at
    // offset 0 of a fresh copy of rustc's padded extent.
    if let Some(leaf) = &plan.scalar {
        let value = lower_operand_to_value(ctx, body, block, operand)?;
        return Ok(materialize_fresh_scalar_arg_copy(
            ctx,
            block,
            value,
            leaf.clone(),
            plan.size,
            plan.align,
        ));
    }
    let Some(layout) = fat_ptr_or_memory_aggregate_layout(ctx.tcx, plan.ty)? else {
        return Err(refuse("the bridge has no memory layout for it"));
    };
    if layout.size != plan.size || layout.align != plan.align {
        return Err(refuse("its slot layout is not rustc's size and alignment"));
    }
    if let Operand::Copy(place) | Operand::Move(place) = operand {
        if place.projection.is_empty() && local_is_memory_backed(ctx, place.local) {
            let local_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
            let same_bytes = memory_backed_local_layout(ctx.tcx, local_ty)?
                .is_some_and(|slot| slot.size == plan.size && slot.align == plan.align);
            if !same_bytes {
                return Err(refuse(&format!(
                    "the operand local's slot (`{local_ty:?}`) is not rustc's size and \
                     alignment for it"
                )));
            }
            let src = memory_slot_ptr(ctx, place.local)?;
            return materialize_fresh_arg_copy(ctx, block, src, &layout);
        }
    }
    let Some(value) =
        lower_memory_aggregate_byval_call_arg(ctx, body, block, index, operand, plan.ty)?
    else {
        return Err(refuse(
            "the operand is not a by-value aggregate the bridge can copy",
        ));
    };
    if !ctx.fresh_arg_copies.contains(&value) {
        return Err(refuse(
            "this operand shape does not produce a fresh copy of its bytes in rustc's layout",
        ));
    }
    Ok(value)
}

/// THE SCALAR SUB-LANE, callee half: whether the entry block receives the MIR
/// argument `arg` — which it types as the one scalar `declared` — as rustc's
/// POINTER to a padded copy (`IndirectArgPlan::scalar`). Asked with the facts
/// `func_ty_for_instance` used for this body's declaration (its own instance,
/// `rustc_fn_abi_arg_index_for_mir_arg`), so the entry and the declaration take
/// one decision. `Some(leaf)` is the scalar the entry loads from offset 0.
///
/// A plan whose representation is not this scalar (a memory-slot plan for a
/// local the entry types as a scalar, or another leaf) would make the entry and
/// the declaration disagree, so it is refused by name rather than guessed.
fn entry_scalar_sub_lane<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    arg: Local,
    declared: &TrustIrTy,
) -> Result<Option<TrustIrTy>, String> {
    let Some(abi_arg_index) = rustc_fn_abi_arg_index_for_mir_arg(arg) else {
        return Ok(None);
    };
    let arg_ty = ctx.normalize_ty(ctx.monomorphize_ty(local_rust_ty(ctx, body, arg)));
    let Some(plan) = ctx.indirect_arg_param_plan(
        arg_ty,
        abi_arg_index,
        RustcFnAbiSource::Instance(ctx.instance),
    )?
    else {
        return Ok(None);
    };
    match plan.scalar {
        Some(leaf) if plan.ty == arg_ty && leaf == *declared => Ok(Some(leaf)),
        other => Err(format!(
            "[TCG-ARG-ABI] entry parameter {} `{arg_ty:?}` is typed as the scalar {declared:?}, \
             but the indirect argument decision for it is {} — the declaration and the entry \
             block would disagree. Failing closed. Report this — it is a bridge lane defect.",
            abi_arg_index,
            match other {
                Some(leaf) => format!("the scalar sub-lane over {leaf:?}"),
                None => "a memory-slot copy".to_owned(),
            }
        )),
    }
}

/// THE PADDED-SCALAR AAPCS64 BLOCK, callee half: the plan the declaration of
/// this body took for the MIR argument `arg`, which the entry block types as
/// the one scalar `declared` — `None` when it took none. A plan whose leaf is
/// not `declared` would make the declaration and the entry block disagree, and
/// is refused by name.
fn entry_scalar_block<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    arg: Local,
    declared: &TrustIrTy,
) -> Result<Option<Aapcs64ScalarBlock>, String> {
    let Some(abi_arg_index) = rustc_fn_abi_arg_index_for_mir_arg(arg) else {
        return Ok(None);
    };
    let arg_ty = ctx.normalize_ty(ctx.monomorphize_ty(local_rust_ty(ctx, body, arg)));
    let Some(plan) = ctx.aapcs64_scalar_block_param_plan(
        arg_ty,
        abi_arg_index,
        RustcFnAbiSource::Instance(ctx.instance),
    )?
    else {
        return Ok(None);
    };
    if plan.leaf != *declared {
        return Err(format!(
            "[TCG-ARG-ABI] entry parameter {abi_arg_index} `{arg_ty:?}` is typed as the scalar \
             {declared:?}, but its AAPCS64 block plan carries {:?} — the declaration and the \
             entry block would disagree. Failing closed. Report this — it is a bridge lane \
             defect.",
            plan.leaf
        ));
    }
    Ok(Some(plan))
}

/// THE INDIRECT ARGUMENT, callee half: the parameter arrives as `incoming`, a
/// POINTER to the caller's copy, and its pointee is copied into the parameter
/// local's own slot so the body reads it like every other aggregate parameter.
fn copy_indirect_param_into_slot<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    arg: Local,
    plan: &IndirectArgPlan<'tcx>,
    incoming: ValueId,
) -> Result<(), String> {
    let arg_ty = local_rust_ty(ctx, body, arg);
    let Some(layout) = memory_backed_local_layout(ctx.tcx, arg_ty)? else {
        return Err(format!(
            "[TCG-ARG-ABI] indirect parameter `{:?}` has no memory slot layout; failing \
             closed",
            plan.ty
        ));
    };
    if layout.size != plan.size || layout.align != plan.align {
        return Err(format!(
            "[TCG-ARG-ABI] indirect parameter `{:?}`: its slot is {} bytes / align {} but \
             rustc's copy is {} bytes / align {}; failing closed",
            plan.ty, layout.size, layout.align, plan.size, plan.align
        ));
    }
    let dst = memory_slot_ptr(ctx, arg)?;
    copy_aggregate_lanes(ctx, block, incoming, dst, &layout)
}

/// THE LAST LINE OF DEFENCE for the indirect argument lane. A whole-slot
/// aggregate argument and an indirect pointer are both ONE ABI value, so the
/// adapter's call-arity check cannot see a call site that missed
/// `indirect_arg_param_plan`: it would pass an address the callee takes for ITS
/// copy while the bytes are the caller's live local (which an LLVM callee may
/// write), or bytes in the wrong layout. Every `Call` / `Invoke` of a callee
/// this function declared with indirect positions (`indirect_arg_callees`:
/// `extern_callee`, and `FuncId(0)` for a self-call) must carry, at each such
/// position, a value registered in `fresh_arg_copies`. A `CallIndirect` builds
/// its signature at the call site from the same decision (`classify_func_ty` /
/// the virtual lane's `param_tys`) and its arguments from
/// `lower_call_args_from_inputs`, so it has no second party to disagree with.
fn check_indirect_arg_call_args(
    ctx: &MirLoweringCtx<'_>,
    func: &TrustIrFunction,
) -> Result<(), String> {
    if ctx.indirect_arg_callees.is_empty() {
        return Ok(());
    }
    for block in &func.blocks {
        for node in &block.body {
            let (callee, args) = match &node.inst {
                Inst::Call { callee, args } | Inst::Invoke { callee, args, .. } => (callee, args),
                _ => continue,
            };
            let Some(positions) = ctx.indirect_arg_callees.get(callee) else {
                continue;
            };
            for &position in positions {
                if args
                    .get(position)
                    .is_some_and(|value| ctx.fresh_arg_copies.contains(value))
                {
                    continue;
                }
                let name = ctx
                    .extern_callees
                    .iter()
                    .find(|(_, id)| *id == callee)
                    .map_or("<unknown>", |(name, _)| name.as_str());
                return Err(format!(
                    "[TCG-ARG-ABI] a call to `{name}` passes, at argument position {position} \
                     — which the callee declares as rustc's `PassMode::Indirect` pointer to a \
                     caller-made copy — a value that is not a fresh copy made for this call (a \
                     call lane that does not consult `indirect_arg_param_plan`). Failing closed \
                     rather than hand the callee an address it may write through, or bytes in \
                     the wrong layout. Report this — it is a bridge lane defect, not a program \
                     one."
                ));
            }
        }
    }
    Ok(())
}

/// WS7.1 (b), review: the value-type gate of the historical store-form
/// `InsertField`, restored for the lane `Store`s that replaced it.
///
/// The adapter refused a store-form `InsertField` whose value's type was not
/// the field's type ("InsertField value type .. does not match field type"),
/// and it refuses an unknown value type. A `Store` gets no such check there:
/// its value/declared-type agreement is a trust-ir validator finding, and the
/// adapter's codegen admission deliberately tolerates the validator's
/// residual findings (`validate_codegen_prerequisites`). Measured: the CLI
/// compiles `store i64 %v` of an `i32` value (AArch64: `mov w0, w0`). Without
/// this check the migration to `Store` would have turned a fail-closed refusal
/// into a silently mistyped write for every bridge field write.
///
/// Scope, stated rather than implied: exactly the `Store`s in `func` whose
/// address is a field address recorded by `emit_aggregate_field_store` /
/// `emit_slot_word_store` (`MirLoweringCtx::field_store_types`). A store in a
/// block the reachability pass cleared is gone and is not checked.
fn check_field_store_value_types(
    ctx: &MirLoweringCtx<'_>,
    func: &TrustIrFunction,
) -> Result<(), String> {
    field_store_value_type_errors(&ctx.module, func, &ctx.field_store_types)
}

/// The module-level half of [`check_field_store_value_types`], separated so it
/// can be tested without a `TyCtxt`. A value's type is its block-parameter type
/// or its defining instruction's declared result type (`InstrNode::result_tys`;
/// a self-call reads `func`'s own signature, which `module` may not hold yet),
/// except for an `ExtractField`, whose result is typed as the adapter types it
/// ([`extract_field_result_ty`]: the bridge's historical spelling declares the
/// aggregate type). A recorded store whose value is not defined in `func`, or
/// whose declared type is not the recorded field type, is refused too.
fn field_store_value_type_errors(
    module: &TrustIrModule,
    func: &TrustIrFunction,
    field_stores: &HashMap<ValueId, TrustIrTy>,
) -> Result<(), String> {
    if field_stores.is_empty() {
        return Ok(());
    }
    let mut value_tys: HashMap<ValueId, TrustIrTy> = HashMap::new();
    // (result, declared ty, aggregate operand, field) of every `ExtractField`.
    let mut extracts: Vec<(ValueId, &TrustIrTy, ValueId, u32)> = Vec::new();
    for block in &func.blocks {
        for (value, ty) in &block.params {
            value_tys.insert(*value, ty.clone());
        }
        for node in &block.body {
            let result_tys = match &node.inst {
                Inst::Call { callee, .. } | Inst::Invoke { callee, .. }
                    if *callee == func.id && module.function_by_id(*callee).is_none() =>
                {
                    module
                        .func_type(func.ty)
                        .map(|sig| sig.returns.clone())
                        .unwrap_or_default()
                }
                _ => node.result_tys(module),
            };
            for (value, ty) in node.results.iter().zip(result_tys) {
                value_tys.insert(*value, ty);
            }
            if let (
                Inst::ExtractField {
                    ty,
                    aggregate,
                    field,
                },
                [result],
            ) = (&node.inst, node.results.as_slice())
            {
                extracts.push((*result, ty, *aggregate, *field));
            }
        }
    }
    // `InstrNode::result_tys` reads an `ExtractField`'s declared `ty` as its
    // RESULT type (trust-ir's spelling). The bridge spells most extracts the
    // historical way, declaring the AGGREGATE type, and the adapter accepts both
    // (`field_extract_types`): an aggregate operand's OWN type decides the
    // result, and a declared type that is neither that operand type nor the
    // result is refused. Type each extract the same way, or a lane value
    // extracted from an aggregate block parameter would read as the whole
    // aggregate and be refused here although the adapter's store-form
    // `InsertField` gate admitted it ([`extract_field_result_ty`]). Re-derived
    // to a fixpoint because an extract's operand may itself be an extract; SSA
    // makes the operand chain acyclic, so `extracts.len() + 1` rounds suffice,
    // and a run that has not settled by then leaves every extract result
    // untyped (a field store of one is then refused).
    let mut settled = extracts.is_empty();
    for _ in 0..=extracts.len() {
        if settled {
            break;
        }
        settled = true;
        for (result, declared, aggregate, field) in &extracts {
            let resolved = extract_field_result_ty(declared, value_tys.get(aggregate), *field);
            if value_tys.get(result) != resolved.as_ref() {
                settled = false;
                match resolved {
                    Some(ty) => value_tys.insert(*result, ty),
                    None => value_tys.remove(result),
                };
            }
        }
    }
    if !settled {
        for (result, ..) in &extracts {
            value_tys.remove(result);
        }
    }
    // An `ExtractElement` reads an element of an array, vector or sequence only
    // (`Ty::supports_element_ops`; trust-ir refuses any other operand as
    // `InvalidVectorElementOp`). The lane spells a lane read as one when the
    // aggregate it NAMES is a slot-lane `Array` (`emit_lane_value_read`); over an
    // operand of another type (a `Tuple` parameter read through its slot's lane
    // image) the declared element type says nothing about the bytes read, so
    // the result is untyped here and a field store of it is refused, as the
    // `ExtractField` spelling of the same read was.
    for block in &func.blocks {
        for node in &block.body {
            let (Inst::ExtractElement { array, .. }, [result]) =
                (&node.inst, node.results.as_slice())
            else {
                continue;
            };
            if value_tys
                .get(array)
                .is_some_and(|ty| !ty.supports_element_ops())
            {
                value_tys.remove(result);
            }
        }
    }
    for block in &func.blocks {
        for node in &block.body {
            let Inst::Store { ty, ptr, value, .. } = &node.inst else {
                continue;
            };
            let Some(field_ty) = field_stores.get(ptr) else {
                continue;
            };
            if ty != field_ty {
                return Err(format!(
                    "[TCG-FIELD-STORE-TYPE] in `{}` {:?}: the field store through {ptr:?} \
                     declares {ty:?}, but the field it was emitted for is {field_ty:?}; \
                     failing closed. Report this — it is a bridge lane defect.",
                    func.name, block.id
                ));
            }
            match value_tys.get(value) {
                Some(actual) if actual == field_ty => {}
                actual => {
                    return Err(format!(
                        "[TCG-FIELD-STORE-TYPE] in `{}` {:?}: the field store through \
                         {ptr:?} writes {value:?} of type {}, but the field is {field_ty:?} \
                         (the value-type gate of the store-form `InsertField` this store \
                         replaced); failing closed rather than emit a mistyped write. \
                         Report this — it is a bridge lane defect.",
                        func.name,
                        block.id,
                        actual.map_or_else(|| "<unknown>".to_owned(), |ty| format!("{ty:?}"))
                    ));
                }
            }
        }
    }
    Ok(())
}

/// The type the adapter gives an `ExtractField { ty: declared, field, .. }`
/// result whose aggregate operand has type `operand` (`None`: unknown), for the
/// field-store gate. Mirrors `trust_cg_lower`'s `field_extract_types`:
///
/// * An AGGREGATE operand (or a closure) decides: the result is its field, and
///   a declared type that is neither the operand's (the bridge's historical
///   spelling) nor the field's (trust-ir's) is refused there, so unknown here.
///   For an aggregate the gate cannot lay out, only trust-ir's spelling is
///   typed (as `declared`).
/// * A POINTER-CARRIED operand (the adapter's pointer carriers, and `I64` /
///   `U64`) under a declared aggregate reads through the pointer: the result is
///   the DECLARED aggregate's field.
/// * Anything else, and an unknown operand, is unknown.
///
/// "Lay out" means [`slot_lane_field_ty`]: a bridge `Tuple` or a seeded
/// slot-lane `Array`. Unknown refuses a field store.
fn extract_field_result_ty(
    declared: &TrustIrTy,
    operand: Option<&TrustIrTy>,
    field: u32,
) -> Option<TrustIrTy> {
    let operand = operand?;
    match operand {
        TrustIrTy::Struct(_)
        | TrustIrTy::Tuple(_)
        | TrustIrTy::Array(..)
        | TrustIrTy::Record(_)
        | TrustIrTy::Enum(_)
        | TrustIrTy::Closure(_) => match slot_lane_field_ty(operand, field) {
            Some(field_ty) => (declared == operand || *declared == field_ty).then_some(field_ty),
            None => (declared != operand).then(|| declared.clone()),
        },
        TrustIrTy::Ptr
        | TrustIrTy::FatPtr(_)
        | TrustIrTy::Func(_)
        | TrustIrTy::Ref(_)
        | TrustIrTy::RefMut(_)
        | TrustIrTy::PtrConst(_)
        | TrustIrTy::PtrMut(_)
        | TrustIrTy::Rc(_)
        | TrustIrTy::I64
        | TrustIrTy::U64 => slot_lane_field_ty(declared, field),
        _ => None,
    }
}

/// Field `field` of a bridge `Tuple`, or the lane of a slot-lane `Array`
/// (`slot_lane_ty_by_id`; the bridge seeds exactly those `TyId`s and defines no
/// other): the aggregates [`aggregate_field_store_layout`] resolves for the
/// stores the field-store gate checks. `None` for anything else, including a
/// field out of range.
fn slot_lane_field_ty(ty: &TrustIrTy, field: u32) -> Option<TrustIrTy> {
    match ty {
        TrustIrTy::Tuple(fields) => fields.get(field as usize).cloned(),
        TrustIrTy::Array(elem, len) if u64::from(field) < *len => slot_lane_ty_by_id(elem.index()),
        _ => None,
    }
}

/// The ABI carrier for one `PassMode::Pair` lane and the extension that
/// produces it from the lane value.
///
/// rustc's `ArgExtension` is LLVM's `zeroext`/`signext`: the callee extends
/// the value to the target's `int` width (32 bits on both x86-64 and
/// AArch64) and the caller may read the extended register. Only an integer
/// lane narrower than 32 bits can differ from its carrier, and only on
/// x86-64 does the bridge widen it — on AArch64 the narrow lane load already
/// zero-extends into the W register (see `ScalarPairAbiPlan::carriers`).
fn scalar_pair_lane_carrier(
    lane: &TrustIrTy,
    ext: rustc_target::callconv::ArgExtension,
    widen_narrow_lanes: bool,
) -> (TrustIrTy, Option<CastOp>) {
    use rustc_target::callconv::ArgExtension;
    if !widen_narrow_lanes || !matches!(lane, TrustIrTy::I8 | TrustIrTy::I16) {
        return (lane.clone(), None);
    }
    match ext {
        ArgExtension::None => (lane.clone(), None),
        ArgExtension::Zext => (TrustIrTy::I32, Some(CastOp::ZExt)),
        ArgExtension::Sext => (TrustIrTy::I32, Some(CastOp::SExt)),
    }
}

/// The trust-ir scalar type for one `Primitive` of a `ScalarPair`, or `None`
/// when the bridge has no admitted scalar carrier for it.
///
/// This is the RETURN lane's table, also used for x86-64 arguments. `I128` is
/// absent here: a return would have to give ONE of two return values a
/// register pair, which the return plan's single-register lane model does not
/// state. The AArch64 ARGUMENT lane, and an x86-64 integer-pair argument
/// (`x86_64_pair_arg_admits_i128_lanes`), admit it through
/// [`scalar_pair_param_lane_ty`]. `F16`/`F128` lanes have no carrier here.
/// Every rejection leaves the value on its existing path, where the ABI gates
/// decide it.
fn scalar_pair_lane_ty(primitive: rustc_abi::Primitive) -> Option<TrustIrTy> {
    crate::scalar_abi_admission::scalar_pair_lane_ty(primitive)
}

/// [`scalar_pair_lane_ty`] for an ARGUMENT lane, which admits exactly one
/// carrier the return lane refuses: `I128`.
///
/// The return lane refuses it because `AppleAArch64ABI::classify_returns` would
/// have to give ONE of two return values a register PAIR, which the return
/// plan's single-register lane model does not state. The ARGUMENT classifier
/// states it exactly — `classify_params` returns `ArgLocation::RegPair(x_n,
/// x_n+1)` for `Type::I128`, and `abi_reg_lanes::aarch64_location_lanes` already
/// models a `RegPair` as its two 8-byte lanes at +0 and +8. So the two-value
/// plan for `Option<u128>`'s `{i128, i128}` states four lanes at 0/8/16/24,
/// which is what rustc's own `FnAbi` requires for it.
///
/// This table does not DECIDE anything: `check_param_abi_lanes` compares the
/// resulting placement against rustc's and refuses any disagreement, so a
/// carrier admitted here that trust-cg would place differently is a named
/// refusal, not a wrong register.
///
/// Consulted on AArch64 only, where the `I128` lane was measured (Apple and
/// Linux, whose classification keeps each I128 one ABI value in a register pair
/// with even-register starts and 16-byte stack alignment), and on x86-64 for an
/// integer pair (`x86_64_pair_arg_admits_i128_lanes`); any other x86-64 argument
/// keeps the RETURN table (`scalar_pair_param_plan`).
fn scalar_pair_param_lane_ty(primitive: rustc_abi::Primitive) -> Option<TrustIrTy> {
    use rustc_abi::{Integer, Primitive};
    if matches!(primitive, Primitive::Int(Integer::I128, _)) {
        return Some(TrustIrTy::I128);
    }
    scalar_pair_lane_ty(primitive)
}

/// The two-value plan for a value whose rustc `ArgAbi` is a `PassMode::Pair` —
/// `Ok(None)` when this lane does not apply and the value stays on its existing
/// (one lane-tuple value) path, where the ABI gates decide whether that
/// placement is conformant.
///
/// Every fact is rustc's: WHETHER the lane applies is `arg_abi.mode`; the two
/// lanes' classes, widths and offsets are the layout's own `ScalarPair` scalars.
///
/// SCOPE. AArch64 and x86-64, stated as a target check rather than assumed.
/// The backend's AArch64 classifier allocates a multi-value return across the
/// integer and floating register sequences exactly as AAPCS64 requires, and
/// that is the placement this lane was first measured against. The System V
/// x86-64 selector's scalar-return classifier
/// (`classify_x86_scalar_return_locations`, shared by `lower_return` and the
/// call-site result metadata) allocates integer results RAX then RDX and SSE
/// results XMM0 then XMM1 from independent sequences — the registers rustc's
/// `PassMode::Pair` names on that target — and
/// `abi_reg_lanes::trust_cg_return_placement` reads that classifier for a
/// multi-value x86-64 return, so `[TCG-RET-ABI]` checks the placement there
/// exactly as on AArch64. On x86-64 a `Zext`/`Sext` lane narrower than 32
/// bits is declared as its extended 32-bit carrier (see
/// `scalar_pair_lane_carrier`).
/// Whether an x86-64 `PassMode::Pair` ARGUMENT may keep its 128-bit INTEGER
/// scalar(s) as declared `I128` values — the `Option<u128>` / `Option<i128>` /
/// `(u128, bool)` / `(u64, u128)` family, which rustc passes in three or four
/// INTEGER eightbytes (`core`: `Option::<u128>::unwrap_unchecked`, and
/// `fmt::num::exp_u128` calling it).
///
/// rustc's `Pair` is two INDEPENDENT LLVM arguments: `fn o5(a..e: u64, x:
/// Option<u128>, z: u64)` is five `i64`s, then `i128 %0, i128 %1, i64 %z` — the
/// signature of `fn t5(a..e: u64, x: u128, y: u128, z: u64)`. trust-cg's System V
/// selector places a declared `I128` formal as LLVM places an `i128`, and
/// `x86_64_type_lanes` states the same two INTEGER lanes, so
/// `check_param_abi_lanes` still compares class, count, extent and offset
/// against rustc's lanes before the plan is used. MEASURED 2026-09-27 across a
/// real codegen boundary (rlib x bin, O0-O3): `fn(a1..ak: u64, x: u128, y: u128,
/// z: u64)` for every k in 0..=6 agrees with LLVM, and the pair shapes
/// themselves at k = 0, 1, 3, 4, 5, 6 (`opt_u128_pair_args.rs`).
///
/// Limits: ARGUMENTS only (a pair with a 128-bit lane is at least 32 bytes and
/// returns indirectly); BOTH scalars INTEGERS (a float or pointer beside a
/// 128-bit lane has not been measured and keeps the whole-slot refusal).
fn x86_64_pair_arg_admits_i128_lanes(
    arch: &str,
    arg_abi: &rustc_target::callconv::ArgAbi<'_, Ty<'_>>,
) -> bool {
    use rustc_abi::{Integer, Primitive};
    let Some(pair) = crate::scalar_pair::view(arg_abi.layout.backend_repr) else {
        return false;
    };
    let (a, b) = (pair.a, pair.b);
    let (a, b) = (a.primitive(), b.primitive());
    arch == "x86_64"
        && matches!((a, b), (Primitive::Int(..), Primitive::Int(..)))
        && (matches!(a, Primitive::Int(Integer::I128, _))
            || matches!(b, Primitive::Int(Integer::I128, _)))
}

fn scalar_pair_abi_plan<'tcx>(
    tcx: TyCtxt<'tcx>,
    output: Ty<'tcx>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
) -> Result<Option<ScalarPairAbiPlan>, String> {
    scalar_pair_abi_plan_with(tcx, output, arg_abi, scalar_pair_lane_ty)
}

/// [`scalar_pair_abi_plan`] over an explicit lane-carrier table.
///
/// The RETURN lane passes `scalar_pair_lane_ty`; the ARGUMENT lane passes
/// `scalar_pair_param_lane_ty`, which admits one carrier more. Everything else
/// — which lanes exist, how wide they are and where they start — is read from
/// rustc's `ArgAbi` identically for both, so the two lanes cannot drift apart on
/// anything but the carrier table this argument names.
fn scalar_pair_abi_plan_with<'tcx>(
    tcx: TyCtxt<'tcx>,
    output: Ty<'tcx>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
    lane_ty: fn(rustc_abi::Primitive) -> Option<TrustIrTy>,
) -> Result<Option<ScalarPairAbiPlan>, String> {
    use rustc_abi::HasDataLayout;
    use rustc_target::callconv::PassMode;
    let arch = tcx.sess.target.arch.desc();
    let widen_narrow_lanes = match arch {
        "x86_64" => true,
        // wasm32: each lane is its own wasm parameter of the lane's type; the
        // wasm lane keeps narrow values in canonical (extended) `i32` carriers,
        // which is what rustc's `zext`/`sext` lane attributes ask of LLVM.
        "aarch64" | "arm64" | "wasm32" => false,
        _ => return Ok(None),
    };
    let PassMode::Pair(a_attrs, b_attrs) = &arg_abi.mode else {
        return Ok(None);
    };
    if arg_abi.layout.ty != output {
        return Ok(None);
    }
    let Some(pair) = crate::scalar_pair::view(arg_abi.layout.backend_repr) else {
        return Ok(None);
    };
    let (a, b) = (pair.a, pair.b);
    // Only a value the bridge models as a memory-backed aggregate slot: the
    // lanes are LOADED from that slot by the callee and STORED into it by the
    // caller, so without a slot there are no bytes to move.
    let Some(layout) = fat_ptr_or_memory_aggregate_layout(tcx, output)? else {
        return Ok(None);
    };
    let (Some(lane_a), Some(lane_b)) = (lane_ty(a.primitive()), lane_ty(b.primitive())) else {
        return Ok(None);
    };
    let dl = tcx.data_layout();
    let a_size = a.size(&dl).bytes();
    let b_size = b.size(&dl).bytes();
    let b_offset = pair.second_offset(&dl).bytes();
    // Both lanes must lie WHOLLY inside the slot, and each carrier must be
    // exactly as wide as the scalar rustc named — a narrower carrier would drop
    // bits and a wider one would read past the field.
    let lane_bytes = |ty: &TrustIrTy| -> Option<u64> {
        if *ty == TrustIrTy::Ptr {
            return Some(u64::from(tcx.data_layout.pointer_size().bits()) / 8);
        }
        ty.bit_width().map(|bits| u64::from(bits) / 8)
    };
    if lane_bytes(&lane_a) != Some(a_size) || lane_bytes(&lane_b) != Some(b_size) {
        return Ok(None);
    }
    if a_size == 0 || b_size == 0 || b_offset < a_size || b_offset + b_size > layout.size {
        return Ok(None);
    }
    let (carrier_a, ext_a) = scalar_pair_lane_carrier(&lane_a, a_attrs.arg_ext, widen_narrow_lanes);
    let (carrier_b, ext_b) = scalar_pair_lane_carrier(&lane_b, b_attrs.arg_ext, widen_narrow_lanes);
    // Bit-0 masking of `bool`-valued lanes is applied where the carriers are
    // widened (x86-64); the qualified AArch64 lane keeps its measured
    // behavior and is re-measured separately (see the Linux x86-64 plan).
    let lane_bool = [
        widen_narrow_lanes && a.is_bool(),
        widen_narrow_lanes && b.is_bool(),
    ];
    Ok(Some(ScalarPairAbiPlan {
        lanes: [(lane_a, 0), (lane_b, b_offset)],
        carriers: [carrier_a, carrier_b],
        lane_ext: [ext_a, ext_b],
        lane_bool,
        layout,
    }))
}

/// A wasm32 `PassMode::Cast` by-value aggregate the bridge lowers as ONE `i32`
/// ABI value.
///
/// rustc's Rust ABI (`adjust_for_rust_abi`) casts a `BackendRepr::Memory`
/// aggregate no larger than a pointer to ONE integer of its own size
/// (`Reg { kind: Integer, size }`): on wasm32 that is every such aggregate of
/// 1-4 bytes — `[u8; 4]` from `to_le_bytes`, `[u8; 2]`, `[u16; 2]`, a 3-byte
/// struct, `RangeInclusive<u8>`, `Ipv4Addr`, a small niche enum — and LLVM's
/// wasm32 lowering carries that `i8`..`i32` as one `i32` parameter or result.
/// The whole-slot classification passes such a value by address (a parameter)
/// or through `sret` (a return), which is a different wasm signature.
///
/// The carrier is the value's bytes in little-endian order in the low bits of
/// the `i32`, exactly the integer rustc's own codegen loads from the value's
/// memory. It is assembled from, and split back into, the slot's own
/// natural-alignment lanes (`layout.align` bytes each, the lanes
/// `memory_slot_lane_ty` tiles the slot with), so no access reaches past the
/// value. Bits above `8 * size` are unspecified in a carrier the bridge
/// receives (LLVM's `anyext` of an `i24`) and zero in one it produces; the
/// receiving half never reads them.
///
/// Every fact is rustc's: WHETHER the plan applies is the `ArgAbi`'s own
/// `PassMode::Cast`, and its extent is `CastTarget::rest`. The declared carrier
/// is re-checked against rustc's placement by the `[TCG-ARG-ABI]` /
/// `[TCG-RET-ABI]` gates like every other declaration.
///
/// The same plan carries the EXTENDED ONE-LANE form ([`direct_extension_plan`],
/// every target): a C-ABI value whose `BackendRepr::Scalar` is an 8- or 16-bit
/// integer that the bridge holds in a one-lane memory slot (`Option<NonZeroU8>`,
/// `Option<#[repr(u8)] enum>`, `(u8,)`), which rustc passes and returns as
/// `PassMode::Direct` with an `ArgExtension`. Its carrier is the lane scalar of
/// the extension's signedness (`U8`/`U16` for `Zext`, `I8`/`I16` for `Sext`),
/// which every lane widens to its register or wasm value as that signedness
/// says; the slot's own lane type states no signedness.
///
/// And the AAPCS64 UNADJUSTED-ALIGNMENT block ([`aapcs64_unadjusted_block_plan`],
/// C-ABI arguments on AArch64 ELF targets): a 16-byte composite whose
/// `#[repr(align(16))]` makes the bridge's slot one 16-aligned `I128` lane,
/// which rustc's Linux `FnAbi` casts to `[2 x i64]` because AAPCS64 places a
/// composite by its NATURAL alignment (the `repr(align)` is not counted). Its
/// carrier is the slot's bytes as two `I64` lanes, an aggregate the backend
/// places like rustc's block: consecutive registers from any NGRN, all on the
/// stack when fewer than two remain, an 8-aligned stack slot.
#[derive(Clone, Debug)]
struct SmallAggregateCastPlan {
    /// The bridge's slot layout for the aggregate: `size` equals the cast
    /// extent, and `align` (1, 2 or 4) is the lane width the carrier is split
    /// into (16 for the AAPCS64 block, whose lanes are its own 8-byte units).
    layout: MemoryAggregateLayout,
    /// `Some(scalar)` for the extended one-lane form: the carrier, which is
    /// also the slot's one lane. `None` for the one-`i32` cast.
    extended_scalar: Option<TrustIrTy>,
    /// `Some(units)` for the AAPCS64 unadjusted-alignment block: the carrier
    /// is `units` `I64` lanes of the slot's bytes, in address order.
    integer_block: Option<u64>,
}

impl SmallAggregateCastPlan {
    /// The ABI value the aggregate travels as.
    fn carrier(&self) -> TrustIrTy {
        if let Some(units) = self.integer_block {
            return TrustIrTy::Tuple(vec![TrustIrTy::I64; units as usize]);
        }
        self.extended_scalar.clone().unwrap_or(TrustIrTy::I32)
    }

    /// The slot's lanes, `(lane type, byte offset)`, in address order.
    fn lanes(&self) -> Vec<(TrustIrTy, u64)> {
        if let Some(units) = self.integer_block {
            return (0..units).map(|unit| (TrustIrTy::I64, unit * 8)).collect();
        }
        if let Some(scalar) = &self.extended_scalar {
            return vec![(scalar.clone(), 0)];
        }
        let lane_ty = match self.layout.align {
            1 => TrustIrTy::I8,
            2 => TrustIrTy::I16,
            _ => TrustIrTy::I32,
        };
        (0..self.layout.size / self.layout.align)
            .map(|lane| (lane_ty.clone(), lane * self.layout.align))
            .collect()
    }

    /// Assemble the `i32` carrier from the value's bytes at `slot_ptr` — the
    /// sending half (a caller's argument, a callee's return value).
    ///
    /// The AAPCS64 block is an aggregate carrier, passed as every by-value
    /// aggregate argument is (`lower_memory_aggregate_byval_call_arg`): by the
    /// address of its bytes, which the backend's adapter reads as the declared
    /// lane tuple. The address is a fresh value derived from the slot, so the
    /// tuple type the adapter gives it never meets the slot pointer's own
    /// `slot_ty` accesses.
    fn load_carrier(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        slot_ptr: ValueId,
    ) -> ValueId {
        if self.integer_block.is_some() {
            return slot_byte_ptr(ctx, block, slot_ptr, 0);
        }
        let mut carrier: Option<ValueId> = None;
        for (lane_ty, offset) in self.lanes() {
            let addr = slot_byte_ptr(ctx, block, slot_ptr, offset);
            let lane = emit_typed_load(ctx, block, addr, lane_ty.clone());
            let mut widened = lane;
            if lane_ty != self.carrier() {
                widened = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::ZExt,
                        src_ty: lane_ty,
                        dst_ty: TrustIrTy::I32,
                        operand: lane,
                    })
                    .with_result(widened),
                );
            }
            if offset != 0 {
                let amount = emit_typed_const(ctx, block, TrustIrTy::I32, i128::from(offset * 8));
                let shifted = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::Shl,
                        ty: TrustIrTy::I32,
                        lhs: widened,
                        rhs: amount,
                    })
                    .with_result(shifted),
                );
                widened = shifted;
            }
            carrier = Some(match carrier {
                None => widened,
                Some(acc) => {
                    let merged = ctx.fresh_value();
                    block.body.push(
                        InstrNode::new(Inst::BinOp {
                            op: TrustIrBinOp::Or,
                            ty: TrustIrTy::I32,
                            lhs: acc,
                            rhs: widened,
                        })
                        .with_result(merged),
                    );
                    merged
                }
            });
        }
        carrier.unwrap_or_else(|| emit_typed_const(ctx, block, TrustIrTy::I32, 0))
    }

    /// Split the `i32` `carrier` back into the value's bytes at `slot_ptr` —
    /// the receiving half (a callee's parameter, a caller's result). The
    /// AAPCS64 block's lanes are read out of the incoming aggregate by field,
    /// as `store_incoming_aggregate_param` reads a whole-slot parameter, and
    /// stored at their own offsets.
    fn store_carrier(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        slot_ptr: ValueId,
        carrier: ValueId,
    ) {
        if self.integer_block.is_some() {
            // trust-ir's `extract_field` declares the FIELD's type (here the
            // `I64` lane), not the aggregate's: declaring the carrier tuple
            // typed the lane as `(i64, i64)`, so the validator refused both the
            // read and the lane's `i64` store ("extract_field field type
            // mismatch", "store value type mismatch: expected i64, got (i64,
            // i64)"). The same eight bytes are read and stored either way; the
            // adapter resolves the field's offset from the operand's own type.
            for (field, (lane_ty, offset)) in self.lanes().into_iter().enumerate() {
                let lane = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::ExtractField {
                        ty: lane_ty.clone(),
                        aggregate: carrier,
                        field: field as u32,
                    })
                    .with_result(lane),
                );
                let addr = slot_byte_ptr(ctx, block, slot_ptr, offset);
                emit_typed_store(block, addr, lane_ty, lane);
            }
            return;
        }
        for (lane_ty, offset) in self.lanes() {
            let mut lane = carrier;
            if offset != 0 {
                let amount = emit_typed_const(ctx, block, TrustIrTy::I32, i128::from(offset * 8));
                let shifted = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::BinOp {
                        op: TrustIrBinOp::LShr,
                        ty: TrustIrTy::I32,
                        lhs: lane,
                        rhs: amount,
                    })
                    .with_result(shifted),
                );
                lane = shifted;
            }
            if lane_ty != self.carrier() {
                let narrowed = ctx.fresh_value();
                block.body.push(
                    InstrNode::new(Inst::Cast {
                        op: CastOp::Trunc,
                        src_ty: TrustIrTy::I32,
                        dst_ty: lane_ty.clone(),
                        operand: lane,
                    })
                    .with_result(narrowed),
                );
                lane = narrowed;
            }
            let addr = slot_byte_ptr(ctx, block, slot_ptr, offset);
            emit_typed_store(block, addr, lane_ty, lane);
        }
    }
}

/// The one-`i32` plan for a value whose rustc `ArgAbi` is a wasm32 integer
/// `PassMode::Cast` of a small memory aggregate — `Ok(None)` when it does not
/// apply (any other target or pass mode, a prefix/padding/offset cast, a cast
/// wider than one `i32`, or a value with no memory slot whose lanes tile the
/// cast extent), leaving the value on its existing path for the ABI gates to
/// decide.
fn small_aggregate_cast_plan<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
) -> Result<Option<SmallAggregateCastPlan>, String> {
    use rustc_abi::RegKind;
    use rustc_target::callconv::ArgExtension;
    if !session_is_wasm32(tcx) {
        return Ok(None);
    }
    let Some(view) = crate::cast_abi::view(&arg_abi.mode) else {
        return Ok(None);
    };
    let cast = view.target;
    if view.has_padding()
        || !cast.prefix.is_empty()
        || cast.rest_offset.is_some()
        || cast.rest.unit.kind != RegKind::Integer
        || cast.attrs.arg_ext != ArgExtension::None
    {
        return Ok(None);
    }
    let total = cast.rest.total.bytes();
    if cast.rest.unit.size.bytes() != total || !(1..=4).contains(&total) {
        return Ok(None);
    }
    if arg_abi.layout.ty != ty || arg_abi.layout.size.bytes() != total {
        return Ok(None);
    }
    let Some(layout) = fat_ptr_or_memory_aggregate_layout(tcx, ty)? else {
        return Ok(None);
    };
    if layout.size != total || !matches!(layout.align, 1 | 2 | 4) || total % layout.align != 0 {
        return Ok(None);
    }
    Ok(Some(SmallAggregateCastPlan {
        layout,
        extended_scalar: None,
        integer_block: None,
    }))
}

/// The extended one-lane form of [`SmallAggregateCastPlan`] for a value of type
/// `ty` whose `ArgAbi` is `arg_abi` — `Ok(None)` when it does not apply.
///
/// It applies where rustc passes or returns the value `PassMode::Direct` with an
/// `ArgExtension` over an 8- or 16-bit integer `BackendRepr::Scalar` (every C
/// ABI that widens narrow integers: wasm32, Apple AArch64, x86-64) and the
/// bridge holds the value in a memory slot of exactly that one lane. Its
/// carrier is the scalar of the extension's signedness: a slot lane states no
/// signedness, so passing the lane itself widens it however the lane's own
/// type happens to load (sign-extended on wasm32, zero-extended by an AArch64
/// `LDRB`), which is wrong for one of the two extensions on each target.
fn direct_extension_plan<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
) -> Result<Option<SmallAggregateCastPlan>, String> {
    let Some(scalar) = direct_extension_scalar(arg_abi) else {
        return Ok(None);
    };
    if arg_abi.layout.ty != ty {
        return Ok(None);
    }
    let Some(layout) = fat_ptr_or_memory_aggregate_layout(tcx, ty)? else {
        return Ok(None);
    };
    let bytes = arg_abi.layout.size.bytes();
    if layout.size != bytes || layout.align != bytes {
        return Ok(None);
    }
    Ok(Some(SmallAggregateCastPlan {
        layout,
        extended_scalar: Some(scalar),
        integer_block: None,
    }))
}

/// The AAPCS64 unadjusted-alignment block of [`SmallAggregateCastPlan`] for a
/// C-ABI ARGUMENT of type `ty` whose `ArgAbi` is `arg_abi` — `Ok(None)` when it
/// does not apply.
///
/// AAPCS64 (IHI 0055 §6.4.2 C.10/C.16 with §5.4's natural alignment) and
/// rustc's Linux `FnAbi` (`unadjusted_abi_align`) place a non-HFA composite of
/// at most 16 bytes by the alignment of its most-aligned MEMBER; a
/// `#[repr(C, align(16))]` attribute does not count. So `#[repr(C,
/// align(16))] struct { u64, u64 }` (or `{ u32 }`, `{ u32, u32, u32 }`) is cast
/// to `[2 x i64]`: two consecutive registers from ANY NGRN (x1:x2 after one
/// integer), and an 8-aligned slot on the stack. The bridge's slot for such a
/// value is one 16-aligned `I128` lane (`memory_slot_lane_ty`), which
/// trust-cg's classifier starts on an even register and a 16-aligned stack
/// slot — DarwinPCS's reading, which uses the adjusted alignment. Declared as
/// that slot, the argument was a silent wrong value in both mixed pairings on
/// Linux (measured 2026-10-04 at 615514fa4's base: `take(u64, Al16, u64)` read
/// `p1` from x2:x3 and `p2` from x4, O0-O3) until the whole-signature check
/// (`check_signature_placement`) refused it by name at an odd NGRN or an
/// 8-mod-16 NSAA. This plan declares the two `I64` units rustc lists instead.
///
/// It applies exactly when: the target is AArch64 with the base AAPCS64
/// variant (ELF; Darwin keeps the adjusted alignment, `Reg::i128`); rustc's
/// mode is a `PassMode::Cast` with no prefix, no rest offset, no padding
/// register and no extension, whose rest is a uniform INTEGER block of 8-byte
/// units covering exactly the 16-byte value; and the bridge's slot is that
/// value, 16 bytes and 16-aligned. A composite whose member is itself
/// 16-aligned is cast to `i128` by rustc and keeps its slot, which the
/// classifier already places as rustc does. The carrier passes
/// `[TCG-ARG-ABI]` and the whole-signature check like every declaration.
fn aapcs64_unadjusted_block_plan<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
) -> Result<Option<SmallAggregateCastPlan>, String> {
    if arg_abi.layout.ty != ty || !aapcs64_unadjusted_block_cast(tcx, arg_abi) {
        return Ok(None);
    }
    let Some(layout) = fat_ptr_or_memory_aggregate_layout(tcx, ty)? else {
        return Ok(None);
    };
    if layout.size != 16 || layout.align != 16 {
        return Ok(None);
    }
    Ok(Some(SmallAggregateCastPlan {
        layout,
        extended_scalar: None,
        integer_block: Some(2),
    }))
}

/// Whether rustc's `ArgAbi` is the AAPCS64 unadjusted-alignment block: an
/// AArch64 target with the base AAPCS64 variant (ELF; Darwin casts the same
/// value to `i128` by its adjusted alignment), and a 16-byte, 16-aligned value
/// cast with no prefix, rest offset, padding register or extension to a
/// uniform INTEGER block of two 8-byte units (`[2 x i64]`). Shared by the
/// memory-slot form ([`aapcs64_unadjusted_block_plan`]) and the padded-scalar
/// form (`MirLoweringCtx::aapcs64_scalar_block_param_plan`).
fn aapcs64_unadjusted_block_cast<'tcx>(
    tcx: TyCtxt<'tcx>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
) -> bool {
    use rustc_abi::RegKind;
    use rustc_target::callconv::ArgExtension;
    if trust_cg_abi_target(tcx.sess.target.arch.desc()) != Some(TrustCgAbiTarget::AArch64)
        || trust_cg_lower::AArch64AbiVariant::from_target_triple(
            &tcx.sess.opts.target_triple.to_string(),
        ) != Ok(trust_cg_lower::AArch64AbiVariant::Aapcs64)
    {
        return false;
    }
    let Some(view) = crate::cast_abi::view(&arg_abi.mode) else {
        return false;
    };
    let cast = view.target;
    !view.has_padding()
        && cast.prefix.is_empty()
        && cast.rest_offset.is_none()
        && cast.rest.unit.kind == RegKind::Integer
        && cast.rest.unit.size.bytes() == 8
        && cast.rest.total.bytes() == 16
        && cast.attrs.arg_ext == ArgExtension::None
        && arg_abi.layout.size.bytes() == 16
        && arg_abi.layout.align.bytes() == 16
}

/// THE PADDED-SCALAR FORM of the AAPCS64 unadjusted-alignment block: an
/// over-aligned single-scalar newtype (`#[repr(C, align(16))] struct { u64 }`,
/// `{ u32 }`, `{ u8 }`) that the bridge's type mapper keeps as its one scalar
/// `leaf` while rustc's Linux C `FnAbi` passes its 16 padded bytes as
/// `[2 x i64]` (see [`aapcs64_unadjusted_block_plan`]). Declared as the same two
/// `I64` units ([`Self::carrier`]): the caller stores the scalar at offset 0 of
/// a fresh, zero-filled, 16-aligned 16-byte copy and passes its address, which
/// the backend's adapter reads as the declared lanes; the callee stores the two
/// incoming lanes into such a copy and loads the scalar back from offset 0.
/// Declared as the scalar, it was refused by name by the whole-signature check
/// (the scalar's register holds 4 or 8 of rustc's 16 bytes).
#[derive(Clone, Debug)]
struct Aapcs64ScalarBlock {
    leaf: TrustIrTy,
}

impl Aapcs64ScalarBlock {
    const UNITS: u64 = 2;

    fn carrier(&self) -> TrustIrTy {
        TrustIrTy::Tuple(vec![TrustIrTy::I64; Self::UNITS as usize])
    }

    /// The caller half: the address of a fresh 16-byte, 16-aligned copy whose
    /// bytes are zero except the scalar `value` at offset 0.
    fn argument(&self, ctx: &mut MirLoweringCtx<'_>, block: &mut Block, value: ValueId) -> ValueId {
        let copy = alloca_rustc_extent(ctx, block, Self::UNITS * 8, 16);
        let zero = emit_i64_const(ctx, block, 0);
        for unit in 0..Self::UNITS {
            let addr = slot_byte_ptr(ctx, block, copy, unit * 8);
            emit_typed_store(block, addr, TrustIrTy::I64, zero);
        }
        let leaf_addr = slot_byte_ptr(ctx, block, copy, 0);
        emit_typed_store(block, leaf_addr, self.leaf.clone(), value);
        // A fresh derived address: the lane tuple type the adapter gives it
        // never meets the copy's own byte stores.
        slot_byte_ptr(ctx, block, copy, 0)
    }

    /// The callee half: the scalar of the incoming `carrier`, as `result`.
    fn bind_parameter(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        carrier: ValueId,
        result: ValueId,
    ) {
        let copy = alloca_rustc_extent(ctx, block, Self::UNITS * 8, 16);
        for unit in 0..Self::UNITS {
            // The field's type, `I64`, as `SmallAggregateCastPlan::store_carrier`
            // reads its lanes (trust-ir's `extract_field` declares the result
            // type, not the carrier tuple's).
            let lane = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ExtractField {
                    ty: TrustIrTy::I64,
                    aggregate: carrier,
                    field: unit as u32,
                })
                .with_result(lane),
            );
            let addr = slot_byte_ptr(ctx, block, copy, unit * 8);
            emit_typed_store(block, addr, TrustIrTy::I64, lane);
        }
        let leaf_addr = slot_byte_ptr(ctx, block, copy, 0);
        block.body.push(
            InstrNode::new(Inst::Load {
                ty: self.leaf.clone(),
                ptr: leaf_addr,
                volatile: false,
                align: None,
            })
            .with_result(result),
        );
    }
}

/// The trust-ir integer scalar that carries `arg_abi`'s value with rustc's own
/// extension: `Some` exactly when rustc passes it `PassMode::Direct` with an
/// `ArgExtension` over an 8- or 16-bit integer `BackendRepr::Scalar`.
fn direct_extension_scalar(
    arg_abi: &rustc_target::callconv::ArgAbi<'_, Ty<'_>>,
) -> Option<TrustIrTy> {
    use rustc_abi::{BackendRepr, Integer, Primitive};
    use rustc_target::callconv::{ArgExtension, PassMode};
    let PassMode::Direct(attrs) = &arg_abi.mode else {
        return None;
    };
    let BackendRepr::Scalar(scalar) = arg_abi.layout.backend_repr else {
        return None;
    };
    let Primitive::Int(int, _) = scalar.primitive() else {
        return None;
    };
    Some(match (int, attrs.arg_ext) {
        (Integer::I8, ArgExtension::Zext) => TrustIrTy::U8,
        (Integer::I8, ArgExtension::Sext) => TrustIrTy::I8,
        (Integer::I16, ArgExtension::Zext) => TrustIrTy::U16,
        (Integer::I16, ArgExtension::Sext) => TrustIrTy::I16,
        _ => return None,
    })
}

/// A wasm32 by-value aggregate that rustc's `FnAbi` passes or returns through
/// memory (`PassMode::Indirect`: rustc's wasm32 C ABI makes every aggregate
/// that is not a same-size homogeneous unit indirect, and its Rust ABI every
/// `Memory` aggregate it does not cast to an integer) but that the bridge's
/// own declaration would not hand over as rustc's pointer:
///
/// * a value the bridge carries as ONE scalar — a scalar-carrier union
///   (`union { u32, u16 }`), or a struct around one (`rust_ty_to_trust_ir_ty`)
///   — which the wasm lane passes and returns as a wasm value;
/// * a value in a memory slot of ONE lane (`union { u64, [u8; 8] }`,
///   `#[repr(C, align(16))] struct { u32, u64 }`), which the lane passes as
///   that lane's scalar;
/// * a value in a memory slot aligned above its 16-byte lanes
///   (`#[repr(align(32))]`, under either ABI), which the lane passes by the
///   address of a copy aligned only to the lane type, while rustc promises the
///   callee (which may use the pointer as the value's own address) the
///   value's alignment.
///
/// The plan states rustc's convention instead, in trust-ir the lane lowers
/// exactly:
///
/// * a PARAMETER is declared `Ptr`: the caller copies the value into a fresh
///   buffer of rustc's size and alignment and passes its address; the callee's
///   entry block copies it back out (a carrier load, or the slot's bytes);
/// * a RETURN of a scalar carrier is a hidden LEADING `Ptr` parameter and no
///   return value: the caller passes a fresh buffer and loads the carrier out
///   of it after the call; the callee stores the carrier through it at
///   `Return`. A slot value's return is not this plan's: the hidden-buffer
///   convention of memory aggregates (`sret_return_plan_for_abi`,
///   `indirect_aggregate_return_plan`) already hands the callee a slot of
///   rustc's alignment.
///
/// A carrier covers every field's bytes at offset 0 (the scalar-union
/// carrier-coverage invariant), so the bytes an LLVM peer reads or writes at
/// the value's fields are exactly the carrier's. A `CanonAbi::C` callable
/// takes the plan for all three shapes. A `CanonAbi::Rust` callable takes it
/// for all three as well, within the structural scope of the other wasm32
/// Rust-ABI plans: a parameter only where every call list asks the plan
/// (`wasm32_rust_abi_indirect_param_in_scope`), and a carrier return only
/// where no hand-built closure call reads the result
/// (`wasm32_rust_abi_carrier_return_in_scope`). Every lane that reaches such a
/// callable — a direct call, a `fn` pointer of its type, a vtable slot, a
/// hand-built closure call (`closure_body_call_args`, the MIR closure call), a
/// call from another crate — derives the same convention from the same
/// `FnAbi`. A value outside that scope keeps its one-value declaration, which
/// the `[TCG-WASM32-BYVAL-ABI]` gates (`check_param_abi`,
/// `check_return_abi_for_output`) refuse wherever it departs from rustc's
/// `FnAbi`.
#[derive(Clone, Debug, PartialEq, Eq)]
struct Wasm32IndirectCarrier {
    /// `Some(carrier)`: the bridge holds the value as this one scalar. `None`:
    /// the value lives in a memory slot of rustc's layout, whose bytes are
    /// copied.
    carrier: Option<TrustIrTy>,
    /// rustc's size and alignment of the value: the buffer's extent.
    size: u64,
    align: u64,
}

impl Wasm32IndirectCarrier {
    /// A fresh buffer of rustc's size and alignment for the value's bytes,
    /// owned by the calling frame.
    fn emit_buffer(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
    ) -> Result<ValueId, String> {
        let ptr = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: memory_slot_lane_ty(self.size, self.align)?,
                count: None,
                align: Some(self.align),
            })
            .with_result(ptr),
        );
        Ok(ptr)
    }

    /// The scalar carrier, or a named refusal for a slot value (whose bytes
    /// are copied, never loaded as one scalar).
    fn carrier_ty(&self) -> Result<TrustIrTy, String> {
        self.carrier.clone().ok_or_else(|| {
            "[TCG-WASM32-BYVAL-ABI] a by-memory slot value has no scalar carrier; failing closed"
                .to_owned()
        })
    }

    /// The caller-made copy of a carrier argument: a fresh buffer holding
    /// `carrier` at offset 0. Its address is the argument.
    fn emit_argument_copy(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        carrier: ValueId,
    ) -> Result<ValueId, String> {
        let ty = self.carrier_ty()?;
        let buffer = self.emit_buffer(ctx, block)?;
        let addr = slot_byte_ptr(ctx, block, buffer, 0);
        emit_typed_store(block, addr, ty, carrier);
        Ok(buffer)
    }

    /// Emit `result = load carrier, buffer` (offset 0).
    fn emit_load_into(
        &self,
        ctx: &mut MirLoweringCtx<'_>,
        block: &mut Block,
        buffer: ValueId,
        result: ValueId,
    ) -> Result<(), String> {
        let ty = self.carrier_ty()?;
        let addr = slot_byte_ptr(ctx, block, buffer, 0);
        block.body.push(
            InstrNode::new(Inst::Load {
                ty,
                ptr: addr,
                volatile: false,
                align: None,
            })
            .with_result(result),
        );
        Ok(())
    }

    /// The memory-slot layout of a slot value `ty`, checked against the plan's
    /// extent.
    fn slot_layout<'tcx>(
        &self,
        tcx: TyCtxt<'tcx>,
        ty: Ty<'tcx>,
    ) -> Result<MemoryAggregateLayout, String> {
        match fat_ptr_or_memory_aggregate_layout(tcx, ty)? {
            Some(layout) if layout.size == self.size && layout.align == self.align => Ok(layout),
            _ => Err(format!(
                "[TCG-WASM32-BYVAL-ABI] `{ty:?}` has no memory slot of rustc's {}-byte, \
                 {}-aligned layout to copy through; failing closed",
                self.size, self.align
            )),
        }
    }
}

/// THE decision for [`Wasm32IndirectCarrier`]: `Some` when this session is
/// wasm32, `arg_abi` (an argument or the return of `fn_abi`, of convention
/// `CanonAbi::C`, `Rust` or `RustCold`) describes `ty` and is
/// `PassMode::Indirect` without metadata, and the bridge holds `ty` in a
/// memory slot aligned above its lanes, in a memory slot of one lane, or as
/// one sized scalar carrier. The declaration, the callee's entry block and
/// `Return`, and every call lane ask this with the same facts.
fn wasm32_indirect_carrier_plan<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    fn_abi: &rustc_target::callconv::FnAbi<'tcx, Ty<'tcx>>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
) -> Result<Option<Wasm32IndirectCarrier>, String> {
    if !matches!(
        fn_abi.conv,
        rustc_abi::CanonAbi::C | rustc_abi::CanonAbi::Rust | rustc_abi::CanonAbi::RustCold
    ) {
        return Ok(None);
    }
    if !session_is_wasm32(tcx)
        || !matches!(
            ty.kind(),
            ty::Adt(..) | ty::Array(..) | ty::Tuple(..) | ty::Closure(..)
        )
        || arg_abi.layout.ty != ty
        || !crate::indirect_abi::checked(&arg_abi.mode)
            .map_err(|why| format!("[TCG-WASM32-ABI] `{ty:?}` uses {why}"))?
            .is_some_and(|view| view.is_sized_pointer())
        || !arg_abi.layout.is_sized()
    {
        return Ok(None);
    }
    let size = arg_abi.layout.size.bytes();
    let align = arg_abi.layout.align.bytes();
    let carrier = match fat_ptr_or_memory_aggregate_layout(tcx, ty)? {
        Some(layout) => {
            if layout.size != size || layout.align != align {
                return Ok(None);
            }
            let lanes = aggregate_memory_field_tys(&layout.slot_ty)?.len();
            let (_, lane_bytes) = memory_aggregate_lane(layout.align)?;
            let over_aligned = lane_bytes < layout.align;
            if !over_aligned && lanes != 1 {
                return Ok(None);
            }
            None
        }
        None => {
            let carrier = rust_ty_to_trust_ir_ty(tcx, ty)?;
            let Some(carrier_bytes) = trust_ir_leaf_byte_size(&carrier).filter(|&b| b != 0) else {
                return Ok(None);
            };
            if carrier_bytes > size {
                return Err(format!(
                    "[TCG-WASM32-BYVAL-ABI] `{ty:?}` is carried as {carrier:?} \
                     ({carrier_bytes} bytes), wider than rustc's {size}-byte layout; refusing \
                     rather than copying past the caller's buffer"
                ));
            }
            Some(carrier)
        }
    };
    Ok(Some(Wasm32IndirectCarrier {
        carrier,
        size,
        align,
    }))
}

/// The Rust-ABI scope of [`wasm32_indirect_carrier_return`]: every callable
/// whose callers all ask the plan — a direct call, a call through a `fn(..)`
/// pointer, a vtable slot of an ordinary trait method — but not a closure
/// body or an `Fn`-family trait method (a closure shim, a `dyn Fn*` dispatch,
/// a fn item's `Fn*` shim), whose results the hand-built closure calls
/// (`closure_body_call_args`, the MIR closure call, the iterator models) read
/// as the declared return values. Such a callable keeps its one-value return
/// and the `[TCG-WASM32-BYVAL-ABI]` return gate.
fn wasm32_rust_abi_carrier_return_in_scope<'tcx>(
    tcx: TyCtxt<'tcx>,
    source: RustcFnAbiSource<'tcx>,
) -> bool {
    match source {
        RustcFnAbiSource::FnPtr(_) => true,
        RustcFnAbiSource::Instance(instance) => {
            let instance_ty = instance.ty(tcx, ty::TypingEnv::fully_monomorphized());
            let fn_family_method = tcx
                .trait_of_assoc(instance.def_id())
                .is_some_and(|trait_id| tcx.fn_trait_kind_from_def_id(trait_id).is_some());
            !fn_family_method
                && !matches!(
                    instance_ty.kind(),
                    ty::Closure(..) | ty::CoroutineClosure(..) | ty::Coroutine(..)
                )
        }
        // A C-variadic call is a C-ABI call, never a Rust-ABI one.
        RustcFnAbiSource::VariadicCall(..) => false,
    }
}

/// Whether the callable `source` reaches is declared with a non-Rust ABI (read
/// from its signature, without a `FnAbi` query): the callables whose every
/// by-memory shape [`wasm32_indirect_carrier_plan`] can claim, whose own test
/// is the `FnAbi`'s convention.
fn fn_abi_source_is_c_compatible<'tcx>(tcx: TyCtxt<'tcx>, source: RustcFnAbiSource<'tcx>) -> bool {
    match source {
        RustcFnAbiSource::Instance(instance) => instance_abi_is_c_compatible(tcx, instance),
        RustcFnAbiSource::FnPtr(sig) => !sig.skip_binder().abi().is_rustic_abi(),
        // A C-variadic call is a C-ABI call (`variadic::call` checks it).
        RustcFnAbiSource::VariadicCall(..) => true,
    }
}

/// [`wasm32_indirect_carrier_plan`] for the RETURN of the callable
/// `abi_source` reaches, whose output type is `output`: a scalar carrier only
/// (a slot value returns through the memory-aggregate buffer convention), of
/// a C-compatible callable or of a Rust-ABI one in
/// [`wasm32_rust_abi_carrier_return_in_scope`].
fn wasm32_indirect_carrier_return<'tcx>(
    tcx: TyCtxt<'tcx>,
    output: Ty<'tcx>,
    abi_source: RustcFnAbiSource<'tcx>,
) -> Result<Option<Wasm32IndirectCarrier>, String> {
    if !session_is_wasm32(tcx)
        || !matches!(
            output.kind(),
            ty::Adt(..) | ty::Array(..) | ty::Tuple(..) | ty::Closure(..)
        )
        || !(fn_abi_source_is_c_compatible(tcx, abi_source)
            || wasm32_rust_abi_carrier_return_in_scope(tcx, abi_source))
    {
        return Ok(None);
    }
    let fn_abi = abi_source.query(tcx)?;
    Ok(
        wasm32_indirect_carrier_plan(tcx, output, fn_abi, &fn_abi.ret)?
            .filter(|plan| plan.carrier.is_some()),
    )
}

/// WHERE this target expects the hidden return-buffer pointer, named for the
/// human reading a refusal. `Err` for a target whose convention this bridge does
/// not implement — a refusal, never a guess.
///
/// The two implemented conventions are genuinely different, which is exactly why
/// this is read per target rather than assumed:
///
/// * **AAPCS64 §6.9** reserves **X8**, a register OUTSIDE the X0-X7 argument
///   bank. The hidden pointer therefore shifts nothing: ordinary arguments are
///   numbered as if it did not exist. trust-cg's AArch64 selector places it from
///   `Function::abi_sret_param` (see `trust_cg_lower::function::AbiSretParam`).
/// * **System V x86-64 (AMD64 psABI §3.2.3)** passes it as if it were a hidden
///   FIRST argument of class INTEGER, i.e. in **RDI**, and every real argument
///   moves one register along. A leading pointer parameter already lands exactly
///   there, so the structural shape this bridge emits is correct on that target
///   by construction — the selector only CHECKS it rather than placing it.
fn sret_return_register_for_target(tcx: TyCtxt<'_>) -> Result<&'static str, String> {
    match tcx.sess.target.arch.desc() {
        "aarch64" | "arm64" => Ok("x8 (AAPCS64 \u{a7}6.9 indirect result register)"),
        "x86_64" => Ok("rdi (System V: a hidden leading INTEGER-class argument)"),
        // The wasm32 C ABI passes the buffer address as the hidden FIRST `i32`
        // parameter, which is exactly the leading pointer parameter this
        // bridge declares; trust-cg's wasm lane gives it no special treatment.
        "wasm32" => Ok("the first i32 parameter (the wasm32 ABI's hidden leading sret pointer)"),
        other => Err(format!(
            "[TCG-SRET-ABI] rustc returns this value through a caller-allocated buffer \
             (`PassMode::Indirect`), but trust-cg does not implement the hidden \
             return-buffer register convention for target architecture `{other}`. Failing \
             closed rather than guessing which register carries the buffer address. \
             Options: (1) build for `aarch64` or `x86_64`, whose conventions are \
             implemented; (2) return the value through an explicit out-parameter \
             (`fn f(out: &mut T)`), which crosses no return convention; (3) teach \
             `sret_return_register_for_target` and the target's instruction selector \
             this architecture's convention."
        )),
    }
}

/// The hidden return-buffer plan for a callable whose rustc `FnAbi` returns
/// `output` — `Ok(None)` when the value comes back in REGISTERS and the ordinary
/// lane-tuple return applies.
///
/// Every fact here is rustc's:
///
/// * WHETHER the convention applies is `fn_abi.ret.mode` alone
///   (`rustc_return_placement`), never a size rule of the bridge's own.
/// * HOW BIG the buffer is, and how it must be ALIGNED, is cross-checked against
///   the `pointee_size` / `pointee_align` rustc itself put on the indirect
///   return's `ArgAttributes`. If the bridge's slot layout for the same type
///   disagrees with rustc about either, that is a bridge layout bug and the
///   function is refused — a caller-allocated buffer of the wrong size is a
///   stack overwrite at a real ABI boundary, not a wrong value.
///
/// A return the bridge does not slot-back as a memory aggregate returns
/// `Ok(None)` and stays on its existing path; the `[TCG-RET-ABI]` gate then
/// still compares the two placements and refuses any disagreement.
fn sret_return_plan_for_abi<'tcx>(
    tcx: TyCtxt<'tcx>,
    output: Ty<'tcx>,
    fn_abi: &rustc_target::callconv::FnAbi<'tcx, Ty<'tcx>>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    // Only a return the bridge models as a memory-backed aggregate slot. A
    // scalar / scalar-pair / HFA return is not this convention's business.
    let Some(layout) = fat_ptr_or_memory_aggregate_layout(tcx, output)? else {
        return Ok(None);
    };
    // The ArgAbi must describe the very type being classified (the same guard
    // `check_aggregate_return_abi_matches_rustc` makes, for the same reason).
    if fn_abi.ret.layout.ty != output {
        return Ok(None);
    }
    if !rustc_return_placement(tcx, &fn_abi.ret)?
        .is_some_and(|placement| placement.is_caller_buffer())
    {
        return Ok(None);
    }
    // This must precede constructing the hidden-pointer ABI, not merely the
    // final CallerBuffer==CallerBuffer comparison.
    check_aggregate_abi_scope(tcx, fn_abi)?;
    let Some(indirect) = crate::indirect_abi::checked(&fn_abi.ret.mode)
        .map_err(|why| format!("[TCG-SRET-ABI] return `{output:?}` uses {why}"))?
    else {
        // `rustc_return_placement` maps only `Indirect` to `CallerBuffer`, so
        // this is unreachable; refuse rather than assume it stays that way.
        return Err(format!(
            "[TCG-SRET-ABI] return `{output:?}` classified as a caller-allocated buffer by a \
             `PassMode` that is not `Indirect` ({:?}); refusing rather than inventing a \
             buffer for it.",
            fn_abi.ret.mode
        ));
    };
    // An UNSIZED indirect return carries metadata alongside the buffer pointer.
    // Rust has no such return today; refuse rather than drop the metadata.
    if indirect.meta_attrs.is_some() {
        return Err(format!(
            "[TCG-SRET-ABI] return `{output:?}` is an UNSIZED indirect return (its hidden \
             buffer pointer carries metadata); trust-cg passes only a thin buffer pointer. \
             Failing closed rather than dropping the metadata half."
        ));
    }
    // The buffer the CALLER allocates must be exactly the size and alignment
    // rustc told the callee to expect. This is the cross-check that keeps a
    // bridge layout bug from becoming a stack overwrite.
    let attrs = indirect.attrs;
    let Some(pointee_size) = attrs.pointee_size.bytes_usize().try_into().ok() else {
        return Err(format!(
            "[TCG-SRET-ABI] rustc's indirect-return pointee size for `{output:?}` does not fit \
             a u64; failing closed."
        ));
    };
    let pointee_size: u64 = pointee_size;
    let pointee_align = attrs.pointee_align.map(|a| a.bytes());
    if pointee_size != layout.size || pointee_align.is_some_and(|a| a != layout.align) {
        return Err(format!(
            "[TCG-SRET-ABI] the bridge's slot layout for return `{output:?}` is {} bytes / \
             align {}, but rustc's own indirect-return attributes say {pointee_size} bytes / \
             align {pointee_align:?}. A caller-allocated buffer of the wrong size overwrites \
             the caller's frame, so this is refused rather than emitted. Report this — it is \
             a bridge LAYOUT bug, not a program bug.",
            layout.size, layout.align
        ));
    }
    // The target must have an implemented register for the buffer address.
    sret_return_register_for_target(tcx)?;
    Ok(Some(layout))
}

/// [`check_aggregate_return_abi_matches_rustc`] for a caller that holds only the
/// output type and a way to reach the `FnAbi`: it engages ONLY when the bridge
/// would classify `output` as a by-value aggregate return (the case whose
/// placement the two classifiers can disagree about), so a scalar return costs
/// no `FnAbi` query at all.
fn check_return_abi_for_output<'tcx>(
    tcx: TyCtxt<'tcx>,
    output: Ty<'tcx>,
    abi_source: RustcFnAbiSource<'tcx>,
    declared_returns: &[TrustIrTy],
    declared_return_offsets: &[u64],
) -> Result<(), String> {
    let Some(layout) = fat_ptr_or_memory_aggregate_layout(tcx, output)? else {
        // An aggregate with no memory slot — a scalar-carrier union (`union {
        // u32, u16 }`), or a struct around one — is returned as its carrier,
        // because the hidden-buffer convention only claims slot-backed values.
        // rustc's wasm32 ABI returns a heterogeneous union through a caller
        // buffer (`sret`): a carrier return in the scope of
        // `Wasm32IndirectCarrier` takes that buffer; one the lane would return
        // as a wasm value is refused, whoever its callers are.
        if session_is_wasm32(tcx)
            && !declared_returns.is_empty()
            && matches!(
                output.kind(),
                ty::Adt(..) | ty::Array(..) | ty::Tuple(..) | ty::Closure(..)
            )
        {
            let fn_abi = abi_source.query(tcx)?;
            let rustc_buffer = fn_abi.ret.layout.ty == output
                && rustc_return_placement(tcx, &fn_abi.ret)?
                    .is_some_and(|placement| placement.is_caller_buffer());
            let bridge = trust_cg_return_placement(tcx, declared_returns, declared_return_offsets)?;
            if rustc_buffer && !bridge.is_caller_buffer() {
                return Err(format!(
                    "[TCG-WASM32-BYVAL-ABI] rustc's wasm32 ABI returns `{output:?}` through a \
                     caller-allocated buffer (`sret`), but the bridge returns it as the carrier \
                     {declared_returns:?}, which the wasm lane returns as a wasm value; a \
                     caller would find the value \
                     in neither place. Failing closed; write it through a `&mut` parameter \
                     instead."
                ));
            }
        }
        // A padded scalar the bridge returns as one scalar where rustc does not
        // (`check_scalar_return_abi`, scoped to the indirect-lane targets).
        return check_scalar_return_abi(tcx, output, abi_source, declared_returns);
    };
    let fn_abi = abi_source.query(tcx)?;
    if fn_abi.ret.layout.ty == output {
        if let Some(detail) = extension_disagreement(tcx, &fn_abi.ret, declared_returns) {
            return Err(format!(
                "[TCG-RET-ABI] by-value return `{output:?}`: {detail}; a caller compiled by the \
                 other backend reads a differently extended value. Failing closed. Options: \
                 (1) return the inner integer instead; (2) report the shape."
            ));
        }
    }
    check_aggregate_return_abi_matches_rustc(
        tcx,
        output,
        layout.size,
        fn_abi,
        declared_returns,
        declared_return_offsets,
    )
}

/// FAIL CLOSED on a narrow-integer EXTENSION the declaration does not carry.
///
/// rustc's C ABIs that widen narrow integers (wasm32, Apple AArch64, x86-64)
/// mark an 8- or 16-bit `BackendRepr::Scalar` `PassMode::Direct` with
/// `ArgExtension::Zext` or `Sext`, and code compiled by the other backend
/// relies on it: the receiving side of an argument, and the caller of a
/// return, reads the widened value without re-extending it. The register and
/// lane classifiers compare class, width and offset only, so the extension is
/// checked here: the declaration must be the one integer scalar of rustc's
/// signedness (a `bool` for a zero-extended `bool`), which every lane widens
/// by its signedness. A memory-slot lane states no signedness and is refused.
/// Where every valid value of the scalar is below the sign bit, both
/// extensions give the same value and any declaration agrees.
fn extension_disagreement<'tcx>(
    tcx: TyCtxt<'tcx>,
    arg_abi: &rustc_target::callconv::ArgAbi<'tcx, Ty<'tcx>>,
    declared: &[TrustIrTy],
) -> Option<String> {
    let required = direct_extension_scalar(arg_abi)?;
    let rustc_abi::BackendRepr::Scalar(scalar) = arg_abi.layout.backend_repr else {
        return None;
    };
    let bits = scalar.size(&tcx).bits();
    let range = scalar.valid_range(&tcx);
    if range.start <= range.end && range.end < (1u128 << (bits - 1)) {
        return None;
    }
    match declared {
        [ty] if *ty == required => None,
        [TrustIrTy::Bool] if required == TrustIrTy::U8 => None,
        _ => Some(format!(
            "rustc passes it `PassMode::Direct` extended to 32 bits as {required:?} (`{:?}`), \
             but trust-cg declares {declared:?}, which does not carry that extension",
            arg_abi.mode
        )),
    }
}

/// The targets on which the bridge lowers rustc's Rust-ABI
/// `PassMode::Indirect { on_stack: false }` ARGUMENT — one pointer to a
/// caller-made copy — as rustc does (the indirect argument lane,
/// `MirLoweringCtx::indirect_arg_param_plan`), and on which the refusal that
/// comes with it applies: a padded scalar returned by value
/// (`check_scalar_return_abi`). ONE predicate, so the lane and its refusal
/// never cover different targets.
///
/// x86-64 System V / Darwin and AArch64 (Apple and ELF), not Windows (whose x64
/// aggregate ABI `check_aggregate_abi_scope` refuses first). AArch64 joined on
/// 2026-09-28, measured on an AArch64 Darwin host: before, a by-value `struct
/// Tri { u8, i64, u16 }`, a `{u32; 3}` struct or a `union { u128, u64 }` passed
/// from a bridge-built caller to an LLVM-built callee SIGSEGV'd (the callee read
/// the value's bytes as the copy's address), and a `#[repr(align(16))]` newtype
/// returned by an LLVM callee through the hidden `x8` buffer was read out of
/// `x0` (a bus error) — the Trust run-make `trust-ir-cg-layout-abi-authority`.
fn rust_abi_indirect_lane_target(tcx: TyCtxt<'_>) -> bool {
    matches!(tcx.sess.target.arch.desc(), "x86_64" | "aarch64" | "arm64")
        && !tcx.sess.target.is_like_windows
}

/// FAIL CLOSED: a return the bridge declares as ONE SCALAR (a pointer included)
/// while rustc's own `FnAbi` returns it some other way — the return twin of
/// `MirLoweringCtx::refuse_scalar_declared_memory_arg`, reached from
/// `check_return_abi_for_output` for every return that is not a memory aggregate.
///
/// An over-aligned single-scalar newtype is one scalar to the bridge's type
/// mapper but a padded `BackendRepr::Memory` value to rustc, whose Rust ABI
/// returns it through the hidden caller-allocated buffer (`PassMode::Indirect`,
/// sret) when it is larger than a pointer — `#[rustc_abi(debug)]`, 2026-09-28:
/// `#[repr(align(128))] struct CP(u64)`, `#[repr(C, align(16))] struct A16 { a:
/// u64 }` and `#[repr(align(16))] struct A8(u8)` all return `Indirect` — and
/// `Cast` to one INTEGER register at or below a pointer (`#[repr(align(8))]
/// struct F8(f32)`: the bridge's float scalar would come back in XMM0, rustc's
/// value in RAX). MEASURED before (the review's `mkcp(k) -> CP`, oracle 16): LLVM
/// rlib + bridge bin SIGSEGV, bridge rlib + LLVM bin 0 — the bridge returned the
/// scalar in RAX and never wrote the buffer.
///
/// The hidden-buffer return is not lowered for a scalar (the sret lane is the
/// memory-aggregate slot's, `sret_return_plan_for_abi`), so both shapes are
/// refused by name. A POINTER carrier is no exception: `#[repr(C, align(16))]
/// struct AP { p: *const u64 }`, `#[repr(align(16))] struct AR(&'static u64)`
/// and `#[repr(C, align(16))] union UP { p: *const u64 }` all return through
/// the buffer, and MEASURED before (review finding, 2026-09-28, `mk_ap` /
/// `mk_ar`, oracle 30; `mk_up`, oracle 33) the bridge returned the pointer in
/// RAX — LLVM rlib + bridge bin a bus error (138), bridge rlib + LLVM bin a
/// silent 0 / 3, at O0 and O2 — because a pointer declaration used to be exempt
/// here. Only the intercepted collection family is left alone, by IDENTITY
/// (`is_intercepted_collection_value_ty`): its `Ptr` is the address of the
/// bridge's OWN slot, a separate known gap `LIMITATIONS.md` records. Only a
/// `Memory`-repr return is queried, so an ordinary scalar return still costs no
/// `FnAbi` query. Scoped to the targets of the indirect argument lane
/// (`rust_abi_indirect_lane_target`: x86-64 and AArch64, not Windows).
fn check_scalar_return_abi<'tcx>(
    tcx: TyCtxt<'tcx>,
    output: Ty<'tcx>,
    abi_source: RustcFnAbiSource<'tcx>,
    declared_returns: &[TrustIrTy],
) -> Result<(), String> {
    let [declared] = declared_returns else {
        return Ok(());
    };
    if !rust_abi_indirect_lane_target(tcx)
        || !rustc_layout_is_memory(tcx, output)
        || (is_pointer_like_trust_ir_ty(declared)
            && is_intercepted_collection_value_ty(tcx, output))
    {
        return Ok(());
    }
    let fn_abi = abi_source.query(tcx)?;
    if fn_abi.ret.layout.ty != output {
        return Ok(());
    }
    match scalar_declared_mode_disagreement(&fn_abi.ret.mode, declared) {
        None => Ok(()),
        Some(detail) => Err(format!(
            "[TCG-RET-ABI] by-value return `{output:?}` ({} bytes, align {}): the bridge types \
             it as the one scalar {declared:?}, but rustc's layout pads it \
             (`BackendRepr::Memory`) and its FnAbi returns it {detail} (`PassMode::{:?}`); an \
             independently compiled caller or callee would read the result from another place \
             than this function writes it. Failing closed rather than emitting an \
             ABI-nonconformant signature. Options: (1) return it through an explicit \
             out-parameter (`fn f(out: &mut T)`); (2) drop the `#[repr(align)]` that pads the \
             scalar, or return the inner scalar; (3) keep this function on the LLVM backend.",
            fn_abi.ret.layout.size.bytes(),
            fn_abi.ret.layout.align.bytes(),
            fn_abi.ret.mode,
        )),
    }
}

/// The memory-aggregate layout for `ty` IF it is a boundary-crossing slice fat
/// pointer OR a `memory_aggregate_layout` aggregate OR a non-scalar union. Used by
/// the by-value boundary helpers so a `&[T]` / `&str` / `MaybeUninit<(i64,i64)>`
/// flows through the same register-pair ABI as a `Result<i64,i64>`-shaped aggregate.
fn fat_ptr_or_memory_aggregate_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    if let Some(layout) = real_vec_string_header_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    if is_trait_object_reference_ty(ty) {
        // The pair's size, alignment and metadata offset must be the session's
        // two-pointer-word image that `fat_ptr_memory_layout` spells.
        trait_object_pair_layout_tcx(tcx, ty)?;
        return Ok(Some(fat_ptr_memory_layout()));
    }
    // A `core::fmt` plumbing type (`Argument` / `Arguments` / `ArgumentType`) is
    // NOT assumed away here, whichever crate defines it. Whether a plumbing LOCAL
    // is decoded statically is `ctx.fmt_dead_locals`' question, answered per
    // local (`compute_fmt_dead_locals`): a dead one never reaches a layout query
    // (its statements are skipped), and a LIVE one — a `Formatter`-receiver
    // `write_fmt`'s `Arguments`, or `core` compiling itself — is lowered from
    // rustc's own layout, whose niche-encoded `ArgumentType` enum the
    // memory-aggregate machinery already models (the same shape, spelled as a
    // crate-local mirror, lowers and runs at -O0 and -O3). A type-keyed `None`
    // here left a live value with no layout at all, which surfaced as the bare
    // `Ty::core::fmt::rt::ArgumentType` refusal on every `write!(f, ..)`.
    if is_slice_or_str_fat_ptr_ty(ty) {
        return Ok(Some(fat_ptr_memory_layout()));
    }
    // A `repr(transparent)` newtype chain over a slice / `str` fat pointer
    // (`NonNull<[T]>`, `NonNull<str>`, `Unique<[T]>`): rustc gives it the
    // identical `ScalarPair` layout and `PassMode::Pair`, so it takes the SAME
    // 16-byte `{ data, len }` slot `&[T]` has — `check_param_abi` /
    // `[TCG-RET-ABI]` still compare the declared lanes against rustc's own
    // `FnAbi` for the concrete type. Measured before this arm (2026-09-22):
    // `fn ident(p: NonNull<[u8]>) -> NonNull<[u8]>` was emitted as one register
    // in, one out; the boundary guard then refused 47 `library/core` roots by
    // name. LOCKSTEP with `memory_backed_local_layout`.
    if let Some(layout) = wide_slice_carrier_layout(tcx, ty) {
        return Ok(Some(layout));
    }
    // A reference / raw pointer to a slice-tail DST is the same `{ data, len }`
    // two-eightbyte image, so it crosses a by-value boundary the same way: rustc's
    // own `FnAbi` gives it `PassMode::Pair`, and `check_param_abi` /
    // `check_return_abi` compare these lanes against that — so a wrong
    // classification here is REFUSED by the ABI oracle rather than emitted. (A
    // BORROWED TRAIT OBJECT, the `{ data, vtable }` sibling, is classified at the
    // top of this function, with rustc's own layout checked.)
    if is_slice_tail_dst_ref_ty(tcx, ty) {
        return Ok(Some(fat_ptr_memory_layout()));
    }
    // A capturing (non-ZST) closure passed BY VALUE (e.g. into a generic
    // `fn apply<F: Fn(..)>(f: F, ..)`) crosses the call boundary as its env
    // aggregate: the SysV eightbyte classifier passes it like a same-sized
    // struct. Classify it with its closure slot layout so the param type and the
    // by-value argument use the same register-pair / sret placement.
    if let Some(layout) = closure_memory_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    // A NON-scalar (aggregate) union (`MaybeUninit<(i64,i64)>`) crosses a by-value
    // boundary as its slot's flat integer-lane tuple, exactly like a same-sized
    // struct: its overlapping fields all begin at byte offset 0, so the active
    // field's leaves ARE the slot bytes. (A scalar union keeps its scalar-carrier
    // ABI — `nonscalar_union_memory_layout` returns `None` for it.)
    if let Some(layout) = nonscalar_union_memory_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    memory_aggregate_layout(tcx, ty)
}

/// Store the `{ data, meta }` pair of a slice fat pointer into a memory-backed
/// slice local's slot: field 0 = data, field 1 = meta, each a typed `Store` through
/// `slot_byte_ptr`'s normalized address (never through the slot pointer itself),
/// and read back by `load_fat_ptr_slot_lane` the same way, so the slot pointer is
/// never itself a `Store` address — which means it can also carry the aggregate `{ I64, I64 }`
/// type the call ABI seeds onto it when the slice is passed by value, with no
/// type conflict between the slot's own field writes and the call argument. The
/// data pointer is stored into an `I64` lane (it is `PtrToInt`-cast first); on
/// read it is `IntToPtr`-recovered (`load_fat_ptr_data`).
fn store_fat_ptr_slot(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    local: Local,
    data: ValueId,
    meta: ValueId,
) -> Result<(), String> {
    let slot_ptr = ctx
        .memory_slots
        .get(&local)
        .cloned()
        .ok_or_else(|| "slice fat-pointer store to non-memory local".to_owned())?
        .ptr;
    store_fat_ptr_slot_into(ctx, block, slot_ptr, data, meta);
    Ok(())
}

/// Store `{ data, meta }` into the `{ data, len }` slot at `slot_ptr` (a fresh /
/// argument slot, not tied to a local). The data pointer is `PtrToInt`-cast into
/// the pointer-width lane 0 (byte 0); `meta` goes into lane 1 (byte 8, or 4 on
/// wasm32). Each lane is a typed `Store` through `slot_byte_ptr` (WS7.1 (b): it
/// used to be the invalid store form of `InsertField` over `slot_ptr`).
fn store_fat_ptr_slot_into(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    slot_ptr: ValueId,
    data: ValueId,
    meta: ValueId,
) {
    let data_ptr = coerce_to_plain_ptr(ctx, block, data);
    let data_int = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::PtrToInt,
            src_ty: TrustIrTy::Ptr,
            dst_ty: pointer_lane_ty(),
            operand: data_ptr,
        })
        .with_result(data_int),
    );
    // The length metadata is a `usize` value, which may be typed `U64` (e.g. a
    // subslice `hi - lo` length) while the slot's lane 1 is declared `I64`. They
    // are the same 64-bit carrier, so reinterpret with a same-width `Copy` (a
    // register move) so the lane `Store`'s value type matches the lane type.
    // One pointer word per lane: `[I64; 2]` at bytes 0/8 on a 64-bit target,
    // `[I32; 2]` at bytes 0/4 on wasm32 (`fat_ptr_slot_ty`).
    let meta_lane = coerce_to_pointer_lane(ctx, block, meta);
    let word = session_pointer_bytes();
    emit_slot_word_store(ctx, block, slot_ptr, 0, word, pointer_lane_ty(), data_int);
    emit_slot_word_store(ctx, block, slot_ptr, 1, word, pointer_lane_ty(), meta_lane);
}

/// Read BOTH `{ data, len }` lanes of a fat pointer stored at an arbitrary byte
/// `addr` (a slot pointer, or a field address `slot + offset`). Returns
/// `(data: Ptr, meta: I64)`, the inverse of `store_fat_ptr_slot_into`. Each lane
/// is a typed `Load` at its word address ([`load_fat_ptr_slot_lane`]).
fn load_fat_ptr_at_addr(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    addr: ValueId,
) -> (ValueId, ValueId) {
    let data_int = load_fat_ptr_slot_lane(ctx, block, addr, 0);
    let data = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::IntToPtr,
            src_ty: pointer_lane_ty(),
            dst_ty: TrustIrTy::Ptr,
            operand: data_int,
        })
        .with_result(data),
    );
    let meta = load_fat_ptr_slot_lane(ctx, block, addr, 1);
    (data, meta)
}

/// Recover BOTH `{ data, meta }` lanes of a FAT-POINTER (`&str`/`&[T]`) source
/// operand for a field WRITE, or `Ok(None)` when the source form is not one both
/// lanes can be recovered from (the caller then fails closed rather than write a
/// torn pointer). Two sound forms: a MEMORY-BACKED fat place — a whole slice local
/// (`s.name = other`) or a fat-pointer FIELD of a memory-backed aggregate
/// (`t.0 = t.1`), including checked wrapper images, whose byte address holds
/// `{data,len}`; and a const `&str`/`&[T]`
/// LITERAL (`s.name = "x"`). A scalarized / celled / otherwise-unrecoverable source
/// returns `None`.
fn fat_ptr_source_data_meta<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    operand: &Operand<'tcx>,
) -> Result<Option<(ValueId, ValueId)>, String> {
    match operand {
        Operand::Copy(src) | Operand::Move(src)
            if local_is_memory_backed(ctx, src.local)
                && !projection_has_index_element(&src.projection)
                && is_length_metadata_wide_ptr_ty(
                    ctx.tcx,
                    ctx.monomorphize_ty(place_rust_ty(ctx, body, src)),
                ) =>
        {
            let addr = memory_place_address_raw(ctx, body, block, src)?;
            Ok(Some(load_fat_ptr_at_addr(ctx, block, addr)))
        }
        Operand::Constant(_) => match resolve_slice_source_data_len(ctx, body, block, operand) {
            Ok(data_meta) => Ok(Some(data_meta)),
            Err(_) => Ok(None),
        },
        _ => Ok(None),
    }
}

/// Load the DATA pointer (lane 0) of a memory-backed slice local's `{ data, len }`
/// slot ([`load_fat_ptr_slot_lane`]), recovering the `Ptr` from the I64 lane.
fn load_fat_ptr_data(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    local: Local,
) -> Result<ValueId, String> {
    let slot_ptr = ctx
        .memory_slots
        .get(&local)
        .cloned()
        .ok_or_else(|| "slice fat-pointer data load from non-memory local".to_owned())?
        .ptr;
    let data_int = load_fat_ptr_slot_lane(ctx, block, slot_ptr, 0);
    let data = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::IntToPtr,
            src_ty: pointer_lane_ty(),
            dst_ty: TrustIrTy::Ptr,
            operand: data_int,
        })
        .with_result(data),
    );
    Ok(data)
}

/// Load the LENGTH metadata (lane 1) of a memory-backed slice local's
/// `{ data, len }` slot ([`load_fat_ptr_slot_lane`]).
fn load_fat_ptr_meta(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    local: Local,
) -> Result<ValueId, String> {
    let slot_ptr = ctx
        .memory_slots
        .get(&local)
        .cloned()
        .ok_or_else(|| "slice fat-pointer meta load from non-memory local".to_owned())?
        .ptr;
    Ok(load_fat_ptr_slot_lane(ctx, block, slot_ptr, 1))
}

/// Load the DATA pointer (lane 0) of a `{ data, len }` fat pointer located at an
/// ARBITRARY slot address `slot_ptr` (not tied to a local) — e.g. one half of a
/// `(&[T], &[T])` split tuple at its field offset. Recovers the `Ptr` from the
/// I64 lane exactly as `load_fat_ptr_data`.
fn load_fat_ptr_data_at(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    slot_ptr: ValueId,
) -> Result<ValueId, String> {
    let data_int = load_fat_ptr_slot_lane(ctx, block, slot_ptr, 0);
    let data = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::IntToPtr,
            src_ty: pointer_lane_ty(),
            dst_ty: TrustIrTy::Ptr,
            operand: data_int,
        })
        .with_result(data),
    );
    Ok(data)
}

/// Load the LENGTH metadata (lane 1) of a `{ data, len }` fat pointer at an
/// ARBITRARY slot address `slot_ptr`.
fn load_fat_ptr_meta_at(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    slot_ptr: ValueId,
) -> ValueId {
    load_fat_ptr_slot_lane(ctx, block, slot_ptr, 1)
}

/// Whether `ty` is a reference / raw pointer carrying `(data, vtable)`: a
/// `dyn Trait` object or an admitted struct chain ending in one. Both use the
/// two-word ABI; a struct pointer's data lane still addresses the whole struct.
fn is_trait_object_reference_ty(ty: Ty<'_>) -> bool {
    if rustc_middle::ty::tls::with_opt(|tcx| {
        tcx.is_some_and(|tcx| dyn_tail::is_pointer(tcx, tcx.lift(ty)))
    }) {
        return true;
    }
    match ty.kind() {
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _) => matches!(inner.kind(), ty::Dynamic(..)),
        _ => false,
    }
}

/// A reference / raw pointer to a DST whose unsized TAIL is `dyn Trait` —
/// `&core::error::Request` (`Request<'a>(Tagged<dyn Erased<'a>>)`, and
/// `Tagged<E: ?Sized> { tag_id: TypeId, value: E }`).
///
/// Rust has exactly two pointer-metadata kinds, so an unsized pointee is either
/// LENGTH-tailed (`[T]` / `str`, handled by `is_length_metadata_wide_ptr_ty`) or
/// VTABLE-tailed, which is this. The tail is asked of RUSTC —
/// `struct_tail_for_codegen`, whose own doc says its type "can be used to
/// determine unsizing strategy" — rather than re-walked here.
///
/// # Deliberately DISJOINT from `is_trait_object_reference_ty`
///
/// A bare `&dyn Trait` returns `false` from this predicate. The two are combined
/// only by `is_vtable_pair_abi_ref_ty`, and only at the sites that need the
/// two-lane REPRESENTATION. That separation is the point: a `&Tagged<dyn Er>` is
/// a `{data, vtable}` pair for ABI purposes, but it is NOT a dispatchable
/// trait-object receiver — its vtable is the TAIL's (`Erased`'s), and the struct
/// around the tail has no trait of its own. `is_trait_object_reference_ty` has 37
/// call sites, many of them virtual-call / upcast / vtable-slot DISPATCH, and
/// widening it in place would quietly make every one of those treat a dyn-tailed
/// struct as dispatchable.
fn is_dyn_tail_fat_ref_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    // ONE predicate for every site that must agree on the two-lane ABI shape (the
    // declaration, the callee's entry params, the call-argument expansion): the
    // `dyn_tail` module's, which also requires rustc's 16-byte / 8-aligned
    // `ScalarPair` with the vtable at offset 8, and whose projection walkers refuse
    // a field whose offset the vtable decides at run time.
    dyn_tail::is_pointer(tcx, ty)
}

/// Whether `ty` is passed as the TWO pointer-width ABI lanes `{data, vtable}`:
/// a bare `&dyn Trait`, or a reference to a DST with a `dyn` tail.
///
/// This is a REPRESENTATION question, not a dispatch one. Use it only where the
/// ABI shape is what matters — the declaration (`classify_func_ty`), the callee's
/// entry-block params, and the call-argument expansion — which are exactly the
/// three places that must agree or the argument count diverges. Every
/// vtable-DISPATCH site keeps `is_trait_object_reference_ty`.
fn is_vtable_pair_abi_ref_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    is_trait_object_reference_ty(ty) || is_dyn_tail_fat_ref_ty(tcx, ty)
}

/// Whether `ty` is a WIDE (fat) pointer the memory LEAF model can place as TWO
/// pointer-width lanes: a `&[T]` / `&str` `{ data, len }`, or a `&dyn Trait`
/// `{ data, vtable }`. These are the only two pointer-metadata kinds Rust has,
/// and both have the identical in-memory shape — a `BackendRepr::ScalarPair` of
/// the data pointer and one metadata word — which is why one predicate covers
/// them and one two-lane load/store covers both.
///
/// # Why this is separate from `is_slice_or_str_fat_ptr_ty`
///
/// That predicate answers "is this a SLICE fat pointer", and ~55 callers use it
/// to reach slice-specific machinery (element addressing, `len`, subslicing) for
/// which a vtable is not a length and a `&dyn` would be a miscompile. This one
/// answers the strictly narrower question the LEAF model asks — "does this field
/// occupy two pointer-width lanes whose second lane is metadata" — to which both
/// kinds answer yes. Callers that need to know WHICH metadata kind keep asking
/// the specific predicates.
///
/// Purely a shape test: every byte offset still comes from `tcx.layout_of`
/// (`fat_ptr_metadata_offset`), and every admission site separately requires
/// rustc's `BackendRepr::ScalarPair`, so a wide pointer laid out any other way
/// fails closed.
fn is_fat_pointer_memory_leaf_ty(ty: Ty<'_>) -> bool {
    is_slice_or_str_fat_ptr_ty(ty) || is_trait_object_reference_ty(ty)
}

/// The LAYOUT-TRUE form of [`is_fat_pointer_memory_leaf_ty`]: whether `ty` is a
/// reference / raw pointer that rustc lays out WIDE, decided by asking whether
/// the POINTEE is `Sized` rather than by listing the pointee kinds that happen
/// to be unsized today.
///
/// # Why a second predicate rather than widening the first
///
/// `is_fat_pointer_memory_leaf_ty` takes a bare `Ty` with no `TyCtxt`, so it
/// cannot consult a layout; it enumerates `ty::Slice`/`ty::Str` and
/// `ty::Dynamic`. Those are the only pointee KINDS that are themselves unsized,
/// but they are NOT the only ways to reach a wide pointer: a struct whose LAST
/// FIELD is a `[T]` / `str` / `dyn` is itself unsized (`core::bstr::ByteStr(pub
/// [u8])`, `core::ffi::CStr { inner: [c_char] }`), and `&ByteStr` is a
/// `{ data, len }` `ScalarPair` that BOTH kind predicates answer `false` for.
///
/// Every caller that must decide "may this leaf occupy ONE pointer-width lane"
/// has to ask THIS question, because the answer for `&ByteStr` is no and the
/// kind predicates say yes. Callers that need to know WHICH metadata kind a
/// wide pointer carries (a length vs a vtable word — slice element addressing,
/// `len`, subslicing, dispatch) keep asking the specific kind predicates: this
/// one deliberately does not distinguish them.
///
/// Sizedness, not `layout_of`: `layout_of` on an unsized type is fallible and
/// the failure would have to be swallowed into a `bool`, which would answer
/// "not wide" for exactly the types this exists to catch. `is_sized` is total
/// and is rustc's own definition of which pointers carry metadata.
fn is_wide_pointer_memory_leaf_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    match ty.kind() {
        ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _) => {
            !pointee.is_sized(tcx, ty::TypingEnv::fully_monomorphized())
        }
        // A `ty::Pat` (`*const T is !null`) refines VALIDITY, never
        // REPRESENTATION, so for an UNSIZED `T` it IS a `{data, metadata}`
        // ScalarPair and belongs on the `true` side of this predicate.
        // `NonNull<T>` is `#[repr(transparent)] { pointer: *const T is !null }`,
        // so without this arm `NonNull<[T]>` / `NonNull<str>` / `NonNull<dyn
        // Trait>` are modeled as ONE thin `Ptr` scalar with the metadata
        // DROPPED — the silent-truncation channel (miscompile class `3b9b89a8`)
        // this predicate was widened to a LAYOUT test to close, reached through
        // the non-null niche. Measured at 2,965 leaf-walk visits on one
        // `library/core` compile.
        //
        // Landed together with the fat -> thin cast seam
        // (`lower_wide_to_thin_ptr_cast`), which is what the peel needs to exist:
        // the inlined `slice::Iter::new` narrows a `NonNull<[T]>` to a
        // `NonNull<T>` with `.cast()`, and before the seam that shape lost
        // codegen at `-O2` (a plain `for b in s { }` over a `&[u8]`). Re-measured
        // at BOTH opt levels with the seam in place.
        ty::Pat(base, _) => is_wide_pointer_memory_leaf_ty(tcx, *base),
        _ => false,
    }
}

/// The METADATA-lane byte offset of a length-metadata wide pointer, or of a
/// `repr(transparent)` CARRIER of one (`NonNull<[T]>`, `Unique<str>`,
/// `NonNull<CStr>`, and the `ty::Pat` validity refinement `*const T is !null`
/// inside them).
///
/// # Why a carrier cannot be asked directly
///
/// [`fat_ptr_metadata_offset`] reads `layout.fields.offset(1)` and requires a
/// TWO-field `ScalarPair` layout. A carrier's own layout has the CARRIER's field
/// count -- `NonNull<T>` declares ONE field -- so asking it directly returns the
/// "expected 2" `Err` for a value whose image is a perfectly ordinary
/// `{ data, len }` pair. `repr(transparent)` is what makes the peel exact: rustc
/// guarantees the carrier has the layout and ABI of its single non-ZST field, at
/// offset 0, so the wrapped pointer's metadata offset IS the carrier's.
///
/// A type that is not a length-metadata carrier is passed through UNCHANGED, so
/// `&dyn Trait` / `*mut dyn Trait` keep asking `fat_ptr_metadata_offset` of
/// themselves and every existing answer is byte-identical. Still fails closed:
/// the underlying helper refuses a non-`ScalarPair` layout rather than guessing.
fn wide_ptr_or_carrier_metadata_offset<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<u64, String> {
    let peeled = peel_transparent_to_slice_fat_ptr(tcx, ty).unwrap_or(ty);
    fat_ptr_metadata_offset(tcx, peeled)
}

/// The byte offset of a fat pointer's METADATA half (the length of a
/// `&[T]`/`&str`, the vtable pointer of a `&dyn Trait`) within its own
/// two-pointer-word image, read in rustc's scalar-pair memory order:
/// 8 on a 64-bit target, 4 on wasm32. A site that hard-codes `+ 8` is correct
/// only in a 64-bit session; fat-pointer lane code asks here (or gates itself
/// with `require_64bit_model`).
///
/// Fails closed rather than guessing: a wide pointer whose layout is not a
/// two-field `ScalarPair` (which would mean rustc changed the representation out
/// from under the two-lane model) returns `Err`, so the caller refuses instead of
/// writing one lane at a fabricated offset.
fn fat_ptr_metadata_offset<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<u64, String> {
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("fat pointer metadata layout_of({ty:?}) failed: {e:?}"))?;
    let Some(pair) = crate::scalar_pair::view(layout.backend_repr) else {
        return Err(format!(
            "fat pointer {ty:?} is not a ScalarPair (data, metadata); refusing to \
             place its metadata lane at a guessed offset"
        ));
    };
    if layout.fields.count() != 2 {
        return Err(format!(
            "fat pointer {ty:?} has {} layout fields, expected 2 (data, metadata)",
            layout.fields.count()
        ));
    }
    Ok(pair.second_offset(&tcx).bytes())
}

/// The `(size, metadata_offset)` of a trait-object fat pointer `ty` (`&dyn T`,
/// `*const dyn T`, a `NonNull<dyn T>` newtype, ...), read from rustc's layout
/// and admitted only as the two-pointer-word `ScalarPair` every trait-object
/// lowering in this file models: `(16, 8)` 8-aligned on a 64-bit target,
/// `(8, 4)` 4-aligned on wasm32. Any other shape fails closed with `ty` named
/// rather than placing a lane at a guessed offset.
fn trait_object_pair_layout_tcx<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<(u64, u64), String> {
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("trait-object pointer layout_of({ty:?}) failed: {e:?}"))?;
    let word = session_pointer_bytes();
    let Some(pair) = crate::scalar_pair::view(layout.backend_repr) else {
        return Err(format!(
            "unsupported trait-object pointer memory layout: {ty:?}"
        ));
    };
    let (data, metadata) = (pair.a, pair.b);
    // Read the ABI memory offset even for a one-field transparent newtype.
    // The modern pair declares it; only the legacy API derives it.
    let dl = &tcx.data_layout;
    let metadata_offset = pair.second_offset(dl).bytes();
    if layout.size.bytes() != 2 * word
        || layout.align.bytes() != word
        || data.size(dl).bytes() != word
        || metadata.size(dl).bytes() != word
        || metadata_offset != word
    {
        return Err(format!(
            "unsupported trait-object pointer memory layout: {ty:?}"
        ));
    }
    Ok((2 * word, metadata_offset))
}

/// [`trait_object_pair_layout_tcx`] for a lowering context.
fn trait_object_pair_layout<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    ty: Ty<'tcx>,
) -> Result<(u64, u64), String> {
    trait_object_pair_layout_tcx(ctx.tcx, ty)
}

/// Whether a reference / raw pointer's POINTEE is SIZED — i.e. whether the
/// pointer is one address word and nothing else.
///
/// A pointee whose layout rustc cannot compute (one still carrying generic
/// parameters, or an unrepresentable shape) answers `false`, NOT an error: every
/// caller uses the answer to ADMIT a single-scalar fast path, so `false` keeps
/// that caller's existing fail-closed route — the conservative direction.
fn reference_pointee_is_sized<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let (ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _)) = ty.kind() else {
        return false;
    };
    // Read sizedness off rustc's OWN layout, the same way every other layout
    // question in this file is asked. A pointee whose layout cannot be computed
    // (a type still carrying generic parameters, an unrepresentable shape) yields
    // `Err` and therefore `false` — "not thin" — which keeps the caller on its
    // existing fail-closed route rather than admitting an address it guessed.
    tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(*pointee))
        .map_or(false, |l| l.is_sized())
}

/// Whether `ty` is a THIN pointer / reference: a `&T` / `&mut T` / `*const T` /
/// `*mut T` whose pointee carries NO pointer metadata, so its whole value is ONE
/// address scalar and a reborrow `&(*p)` is the same address as `p`.
///
/// # This is the REPRESENTATION question — see the BASE-ADDRESS sibling
///
/// "May this pointer be bound to / carried as ONE scalar" (a reborrow's or a
/// field borrow's DESTINATION, a memory-backing rule keyed on a sized pointee) is
/// sizedness, and that is what this answers. "May a field offset be folded onto
/// this `(*r)` base's one bound VALUE" is a DIFFERENT question, and the sites that
/// ask it — the fat-leaf read and store, the whole-aggregate and projected-array
/// deref reads, the deref discriminant — ask
/// [`deref_base_scalar_is_pointee_addr`] instead. The two differ on exactly one
/// class, the vtable-tailed struct reference (`&Tagged<dyn Erased>`): it is NOT
/// thin (two ABI lanes, and binding it to one scalar would drop the vtable), but
/// its one bound value IS the data lane, so it is a sound deref base. Answering
/// the base question with sizedness withdrew a capability that matched LLVM at
/// the tip (`(*t).i.s = v` on `t: &mut T<dyn Er>`); answering the representation
/// question with the base predicate would bind a two-lane value to one scalar.
///
/// # [TCG-THIN-REF-DST] Why the pointee's SIZEDNESS is the question
///
/// This predicate used to ask only `!is_slice_or_str_fat_ptr_ty && !is_trait_
/// object_reference_ty`, which enumerates the two BUILTIN fat forms — `&[T]` /
/// `&str` and `&dyn Trait`. That is not what thin MEANS. A reference to a
/// **slice-tail DST STRUCT** (`&mut H<'_, [u32]>`, where `H`'s last field is the
/// `[u32]` tail) is equally FAT — a `{ data, len }` two-lane value — and both
/// enumerated clauses answer "not one of mine", so the old predicate called it
/// THIN. A `dyn`-tail struct and an `extern type` pointee fail the same way.
///
/// Measured consequence, 2026-09-27, at the current lane tip and with NO patch
/// applied: `lower_memory_fat_leaf_store`'s `deref_leading &&
/// is_thin_pointer_ref_ty(tcx, place_local_ty)` branch accepted
/// `(*h).i.s = v` on `h: &mut H<'_, [u32]>` (a trace at the branch printed
/// `thin=true dst=true`) and then addressed the store through
/// `value_for_scalar_binding(h)` — `h`'s single-scalar binding — instead of the
/// DATA lane of `h`'s two-lane slot. The 16-byte fat store went nowhere:
/// `b2d_only_fat_store` printed `only len 4` where LLVM printed `only len 7`,
/// and `b2b_bytes` showed the data half unchanged too. A stale, LONGER length
/// left behind that way is an EXECUTED out-of-bounds read
/// (`b11_stale_len_oob`: `len 64 sum 448` off a 2-byte static, vs `len 2 sum 3`).
///
/// So the clause added here is not a third enumerated shape, it is the actual
/// definition: **thin iff the pointee is sized**. `is_sized` subsumes both older
/// clauses (`[T]`, `str` and `dyn Trait` are all unsized); they are kept because
/// they cost nothing and state the intent for a reader, not because sizedness
/// needs their help.
///
/// (That measured branch, `lower_memory_fat_leaf_store`'s deref base, is a BASE
/// question and now asks `deref_base_scalar_is_pointee_addr`, which excludes the
/// slice-tail DST reference for the same reason and keeps the vtable-tailed one.)
///
/// Every remaining call site uses this in POSITIVE polarity, as the gate on a
/// single-scalar fast path — so narrowing it can only ever move a shape ONTO a
/// fail-closed route, never off one. The remaining sites, and why sizedness is
/// the right question at each: the identity reborrow `_d = &(*_s)` (its
/// DESTINATION is bound to one scalar, and `_d`/`_s` share a pointee type, so one
/// answer serves both); the two `&(*r).field…` borrows and the slot-backed field
/// borrow (DESTINATION bound to one scalar); the slice- and trait-object-unsize
/// SOURCES (an `Unsize` source is sized except for a trait UPCAST, and the one
/// unsized source that can reach them — a dyn-tailed struct upcast `&T<dyn A>`
/// -> `&T<dyn B>` — is refused before them: "dyn-tail DST unsize source tail …
/// is itself unsized; there is no concrete self type to build a vtable for",
/// measured on the tip and with this change); the `(3f)` enum copy-out memory
/// rule (the pointee IS the sized enum), the fat-field memory-backing rule (its
/// pointee must have a `memory_aggregate_layout`, which no unsized type has) and
/// the scalar-cell reference chain (each link's pointee is the next link, a
/// reference or a primitive). Two more sites reached `main` after that audit,
/// and both are DESTINATION questions too: the transparent wide-slice newtype
/// FIELD borrow in `lower_scalar_ref` (`&(*self).filename`, whose result is bound
/// to one scalar), and `lower_cast`'s trait-object -> thin raw pointer
/// `PtrToPtr` (the result keeps only the data lane, which is right only for a
/// sized pointee).
fn is_thin_pointer_ref_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    matches!(ty.kind(), ty::Ref(..) | ty::RawPtr(..))
        && !is_slice_or_str_fat_ptr_ty(ty)
        && !is_trait_object_reference_ty(ty)
        && reference_pointee_is_sized(tcx, ty)
}

fn is_signed_integer(ty: Ty<'_>) -> bool {
    matches!(ty.kind(), ty::Int(_))
}

fn is_integer(ty: Ty<'_>) -> bool {
    matches!(ty.kind(), ty::Int(_) | ty::Uint(_))
}

/// A Vec/slice element type the BYTE-MOVEMENT lowerings (collect / extend / append /
/// extend_from_within / repeat / to_vec / box_into_vec) can move: an integer, a float,
/// or `char`. A `char` is a 4-byte Unicode scalar mapped to `U32` (see
/// `rust_ty_to_trust_ir_ty`), byte-identical to a `u32` element — the byte movers only
/// copy element bytes (never interpret them), and the char validity invariant is the
/// producer's, preserved by an exact byte copy. This is the same class the float
/// widening added; `char` extends it to the third proven-byte-identical scalar. (Value-
/// COMPUTING ops — e.g. `resize`'s `coerce_to_i64` fill — keep their integer/float gate.)
fn is_scalar_movable_element(ty: Ty<'_>) -> bool {
    is_integer(ty) || ty.is_floating_point() || matches!(ty.kind(), ty::Char | ty::Bool)
}

/// The thin-pointer POINTEE type of a `&dyn Trait` / `*const dyn Trait` value
/// held behind a pointer — `&&dyn Trait`, `*const &dyn Trait`,
/// `NonNull<&dyn Trait>` — and `None` for every other pointee.
///
/// ONE spelling for both the `Ref` and the `RawPtr` arm of the type mapper
/// (`reference_pointee_to_trust_ir_ty`, `rust_ty_to_trust_ir_ty_inner`), so the
/// two cannot drift the way `Struct([I64, I64])` and `Array(I64, 2)` once did
/// for the same 16 bytes (the `[TCG-REGALLOC-063]` lesson). The answer is the
/// fat pointer's 16-byte / 8-aligned two-lane image (`fat_ptr_slot_ty`), which
/// is ONLY the ABI/thin-pointer shell: every access through such a pointer reads
/// or writes the two lanes at rustc's own fat-pointer offsets
/// (`fat_ptr_metadata_offset`), the element stride of a `*const &dyn` cursor is
/// `layout_size_of(&dyn)` = 16 from rustc, and no consumer derives an offset
/// from this tuple. Scoped to a trait-object pointee: a `&&[T]` / `&&str` pointee
/// keeps its own machinery (`local_is_thin_ref_to_slice_fat_ptr`, the
/// const-slice side table).
fn dyn_reference_pointee_slot_ty(pointee: Ty<'_>) -> Option<TrustIrTy> {
    is_trait_object_reference_ty(pointee).then(fat_ptr_slot_ty)
}

/// Size/alignment-only pointee images for f16 storage. These are consulted
/// exclusively by reference/raw-pointer typing; f16 values and SIMD values
/// still require their own value and ABI lowering. All arithmetic and memory
/// accesses continue to ask for the actual Rust element type and layout.
fn f16_pointee_shell_lane_ty<'tcx>(tcx: TyCtxt<'tcx>, pointee: Ty<'tcx>) -> Option<TrustIrTy> {
    let (elements, vector) = match pointee.kind() {
        ty::Float(ty::FloatTy::F16) => (1, false),
        ty::Array(element, len) if matches!(element.kind(), ty::Float(ty::FloatTy::F16)) => {
            (len.try_to_target_usize(tcx)?, false)
        }
        ty::Adt(adt, args) if adt.is_struct() && adt.repr().simd() => {
            let fields = &adt.non_enum_variant().fields;
            if fields.len() != 1 {
                return None;
            }
            let field = fields.iter().next()?.ty(tcx, *args).skip_normalization();
            let ty::Array(element, len) = field.kind() else {
                return None;
            };
            if !matches!(element.kind(), ty::Float(ty::FloatTy::F16)) {
                return None;
            }
            let elements = len.try_to_target_usize(tcx)?;
            if !matches!(elements, 4 | 8) {
                return None;
            }
            (elements, true)
        }
        _ => return None,
    };
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(pointee))
        .ok()?;
    let expected_size = elements.checked_mul(2)?;
    if expected_size == 0 || !layout.is_sized() || layout.size.bytes() != expected_size {
        return None;
    }
    if vector {
        if simd_lanes::count(&layout.backend_repr) != Some(elements)
            || layout.align.bytes() != expected_size
        {
            return None;
        }
    } else if layout.align.bytes() != 2 {
        return None;
    }
    memory_slot_lane_ty(expected_size, layout.align.bytes()).ok()
}

fn reference_pointee_to_trust_ir_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<TrustIrTy, String> {
    // A `&&dyn Trait` / `&mut &dyn Trait` (or raw-pointer equivalent): the
    // POINTEE is itself a `{ data, vtable }` FAT pointer — the shape a closure
    // that captures a `&dyn Trait` BY REFERENCE has for its upvar, and the shape
    // `&`-ing a `&dyn` local produces. The pointee has no single scalar type, but
    // it is a fixed 16-byte / 8-aligned two-lane image, so type the reference as a
    // THIN pointer to that image's flat lane tuple — exactly as a multi-variant
    // enum / nested-field struct / non-scalar union pointee is typed below. The
    // lane tuple is ONLY the ABI/thin-pointer shell: every access through it reads
    // or writes the two lanes at rustc's own fat-pointer offsets
    // (`fat_ptr_metadata_offset`), never this tuple.
    //
    // Answered FIRST because it is the only right answer for this pointee and
    // every path below fails closed on it: the scalar-field flattening reports an
    // `Err` it cannot recover from, so a later check would never be reached.
    //
    // Scoped to a `&dyn`/`*dyn` pointee. A `&&[T]` / `&&str` pointee is NOT
    // routed here: `local_is_thin_ref_to_slice_fat_ptr` and the const-slice
    // machinery already own that shape, and re-typing it would change a working
    // representation rather than add a missing one.
    if let Some(slot) = dyn_reference_pointee_slot_ty(ty) {
        return Ok(slot);
    }
    if let Some(shell) = f16_pointee_shell_lane_ty(tcx, ty) {
        return Ok(shell);
    }
    match aggregate_reference_pointee_to_trust_ir_ty(tcx, ty) {
        Ok(Some(aggregate_ty)) => return Ok(aggregate_ty),
        Ok(None) => {}
        // The scalar-field flattening cannot represent the pointee: it descended into
        // a field that is itself an aggregate — a NESTED struct (`Outer { a, b: Inner
        // }`) or an ARRAY field (`S { arr: [i64; N], n }`) — whose
        // `rust_ty_to_trust_ir_ty` has no flat-scalar mapping. Such a `&S` / `&mut S`
        // pointee is still wholly byte-addressable at rustc layout offsets, so type the
        // reference as a thin `Ref`/`RefMut` to the flat memory-aggregate slot (lane
        // tuple) and let the body route every `(*r).field…` / `(*r)[i]` projection
        // through the byte walker (`memory_aggregate_ref_pointee` ->
        // `memory_aggregate_ref_address` ->
        // `walk_memory_projection_{offset,runtime_address}`), EXACTLY as a multi-
        // variant enum pointee is below. The lane tuple is ONLY the ABI/thin-pointer
        // shell; every leaf access uses the REAL aggregate layout, never this tuple.
        // Fail closed to the original flattening error for any shape the byte-offset
        // memory model also cannot represent.
        Err(aggregate_err) => {
            return match memory_aggregate_reference_pointee_lane_ty_reasoned(tcx, ty)? {
                Ok(lane_tuple) => Ok(lane_tuple),
                // BOTH causes, always. The flattening error alone names the type the
                // FLATTENING tripped on, which is routinely not the type the lane
                // fallback refused — a reasonless decline here mis-attributed fifteen
                // `core` roots to `IndexRange`'s type mapping when probes of that exact
                // shape compiled fine (measured 2026-09-14). Design principle 10: a
                // refusal carries the fix, and it cannot if it names the wrong thing.
                Err(lane_decline) => Err(format!(
                    "{aggregate_err} [and the memory-aggregate lane fallback declined: \
                     {lane_decline}]"
                )),
            };
        }
    }
    // A `&E` / `&mut E` to a MULTI-VARIANT memory-eligible enum cannot be flattened
    // to a fixed scalar-field tuple (its inhabited fields differ per variant), so
    // `aggregate_reference_pointee_to_trust_ir_ty` returns `None` for it. The enum
    // value lives in memory and is decoded THROUGH the pointer by the memory model
    // (`discriminant((*r))` reads the tag at its layout offset; `&(((*r) as V).f)`
    // computes the payload-field address by rustc-layout offsets). So the pointee's
    // trust-ir type is just its byte image — the slot's flat integer-lane tuple —
    // and the reference is a thin `Ref`/`RefMut` (a single `Ptr` scalar) to it. The
    // lane tuple is ONLY the ABI/thin-pointer shell: every field/tag access uses
    // `walk_memory_projection_offset` over the REAL enum layout, never this tuple.
    if let Some(lane_tuple) = memory_enum_reference_pointee_lane_ty(tcx, ty)? {
        return Ok(lane_tuple);
    }
    // A `&U` / `&mut U` to a NON-scalar (aggregate) union (`&mut MaybeUninit<(i64,i64)>`
    // — the `as_mut_ptr` / `assume_init` receiver): the union lives in a slot and is
    // accessed THROUGH the pointer (a raw-pointer cast to a field type). Its thin
    // pointee type is the union's slot lane tuple, exactly like a multi-variant enum /
    // nested-field struct pointee; every access uses the real union layout, never this
    // tuple. A SCALAR union keeps its scalar-carrier pointee below
    // (`nonscalar_union_memory_layout` returns `None` for it).
    if let Some(layout) = nonscalar_union_memory_layout(tcx, ty)? {
        return Ok(layout.slot_ty);
    }
    rust_ty_to_trust_ir_ty(tcx, ty)
}

/// The flat integer-lane tuple (`MemoryAggregateLayout::slot_ty`) of a
/// MULTI-VARIANT or TAGGED single-variant ([`is_tagged_univariant_enum`])
/// memory-eligible enum pointee, used as the thin-pointer pointee type of a `&E` /
/// `&mut E` the scalarized-flattening path cannot represent. Returns `Ok(None)` for
/// any other type (a struct / tuple / array / untagged single-variant enum —
/// handled by `aggregate_reference_pointee_to_trust_ir_ty` — or a type with no
/// supported memory layout), so this is purely additive.
fn memory_enum_reference_pointee_lane_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<TrustIrTy>, String> {
    // A post-`StateTransform` COROUTINE FRAME pointee (`&mut {coroutine@...}` — the
    // `Pin<&mut g>` the driver passes to `resume`, and the resume fn's `(*frame)`
    // base): its value lives in a slot and is read/written THROUGH the pointer
    // (`discriminant((*frame))` / `SetDiscriminant`), exactly like a multi-variant
    // enum. The thin-pointer pointee type is the frame's flat lane tuple; every
    // tag/field access uses the real coroutine layout, never this tuple.
    if matches!(ty.kind(), ty::Coroutine(..)) {
        return match coroutine_memory_layout(tcx, ty) {
            Ok(Some(layout)) => Ok(Some(layout.slot_ty)),
            Ok(None) | Err(_) => Ok(None),
        };
    }
    let ty::Adt(adt, _) = ty.kind() else {
        return Ok(None);
    };
    // A single-variant enum whose repr keeps a TAG (`single_variant_enum_keeps_tag`)
    // is laid out, and modeled, exactly like a multi-variant one.
    if !adt.is_enum()
        || (adt.variants().len() <= 1
            && !single_variant_enum_keeps_tag(tcx, ty)
            && single_variant_enum_lanes_match_rustc_offsets(tcx, ty))
    {
        return Ok(None);
    }
    match memory_aggregate_layout_shared(tcx, ty) {
        Ok(Some(layout)) => Ok(Some(layout.slot_ty.clone())),
        Ok(None) | Err(_) => Ok(None),
    }
}

/// The flat integer-lane tuple (`MemoryAggregateLayout::slot_ty`) of an AGGREGATE
/// POINTEE that the scalar-field flattening
/// (`aggregate_reference_pointee_to_trust_ir_ty`) cannot represent — a multi-field
/// struct one of whose fields is itself an aggregate (`Outer { a, b: Inner }`) or an
/// array (`S { arr: [i64; N], n }`); an ARRAY whose element the flattening cannot
/// map (`[Option<i64>; 3]`, `[[u8; 16]; N]`, `[(u16, [u16; 3]); N]`); a bare TUPLE
/// whose fields it cannot map (`(u16, [u16; 3])`); or a CLOSURE ENVIRONMENT holding
/// an upvar it cannot map. Such a `&S` / `&mut S` / `*const S` / `*mut S`
/// pointee is still wholly byte-addressable at rustc layout offsets, so it is typed as
/// a thin pointer to the flat memory-aggregate slot and every `(*r).field…` /
/// `(*r)[i]` projection routes through the byte walker
/// (`memory_aggregate_ref_pointee` -> `memory_aggregate_ref_address` ->
/// `walk_memory_projection_{offset,runtime_address}`), EXACTLY as a multi-variant enum
/// pointee is (`memory_enum_reference_pointee_lane_ty`). The lane tuple is ONLY the
/// ABI/thin-pointer shell; every leaf access uses the REAL aggregate layout.
///
/// ONE TEST, NOT A LIST OF SHAPES. Every arm fires on the SAME property — "the
/// scalar-field flattening FAILS for this pointee, and the byte-offset memory model
/// can lay it out" — because the array arm used to enumerate three shapes instead
/// and the enumeration was what left `&[(u16, [u16; 3]); N]` and `&(u16, [u16; 3])`
/// refusing. Do not re-narrow an arm to a shape list.
///
/// Returns `Ok(None)` for anything else — purely additive, NARROW:
///   * a multi-variant enum (handled by `memory_enum_reference_pointee_lane_ty`) or
///     any other kind that is not a struct / array / non-empty tuple / closure,
///   * a pointee the scalar-field flattening CAN already represent (a flat
///     scalar-leaf struct, e.g. `Inner { x, y }`, `(u16, i16)`, or a scalar-element
///     array `[u8; 16]`) — left untouched on the scalarized path, or a single-field
///     newtype that maps to a bare scalar,
///   * a tuple with a zero-sized field before a sized one (`[TCG-ZST-LANE-INDEX]`,
///     refused by the flat lane and not re-admitted here),
///   * a pointee with no supported byte-offset memory layout (a wide / niche /
///     non-scalar leaf), which keeps its existing fail-closed handling — except an
///     OVER-ALIGNED struct (align 32 / 64: core_arch's `__m256*` / `__m512*`), whose
///     only failure is alignment and which is typed as a 16-byte-lane SHELL
///     (`over_aligned_pointee_shell_lane_ty`: address-preserving casts only).
///
/// EVERY DECLINE CARRIES ITS REASON — see
/// [`memory_aggregate_reference_pointee_lane_ty_reasoned`], which this is the
/// `Option` face of. A new arm MUST return `Ok(Err(reason))`, never a bare decline:
/// the 45-root DST diagnosis is read off those strings.
fn memory_aggregate_reference_pointee_lane_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<TrustIrTy>, String> {
    Ok(memory_aggregate_reference_pointee_lane_ty_reasoned(tcx, ty)?.ok())
}

/// [`memory_aggregate_reference_pointee_lane_ty`], but every DECLINE carries the
/// reason it declined (the inner `Err`) instead of collapsing to a bare `None`.
///
/// WHY THIS EXISTS. The bare-`Option` form is consulted at
/// `reference_pointee_to_trust_ir_ty`'s LAST RESORT: the scalar-field flattening
/// has already failed, and if this helper also declines, the flattening's error
/// is what the user sees. That error names whatever type the FLATTENING tripped
/// on, which is routinely not the type this helper refused — so a whole family of
/// refusals gets attributed to the wrong cause. Measured 2026-09-14 by the
/// tail lane: fifteen `library/core` roots reported
/// `Ty::Adt multi-field struct ops::index_range::IndexRange`, and synthetic
/// probes of that exact `IndexRange` shape ALL compiled — the type mapping was
/// never the blocker; a reasonless `None` here was. That is the same defect class
/// as an anonymous catch-all bucket, and it cost two independent diagnoses a
/// wrong "architectural, -0" verdict.
///
/// The outer `Err` is unchanged (a hard failure of the layout query); the inner
/// `Err` is the decline reason, which the caller appends to the flattening error
/// so BOTH causes are named.
fn memory_aggregate_reference_pointee_lane_ty_reasoned<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Result<TrustIrTy, String>, String> {
    // An ARRAY POINTEE THE SCALAR-FIELD FLATTENING CANNOT REPRESENT. The byte-
    // offset memory model lays such an array out (every leaf a fixed-offset
    // memory scalar; `validate_memory_aggregate_field_leaves` descends through
    // element aggregates), so type it as the flat slot lane tuple exactly like
    // the nested-field STRUCT below / the bare enum pointee
    // (`memory_enum_reference_pointee_lane_ty`). Every element access through the
    // reference routes over the REAL array/element layout (the runtime-index byte
    // walker + tag decode), never this tuple.
    //
    // THIS USED TO BE A LIST OF SHAPES, AND THE LIST WAS THE BUG. The trigger was
    // `has_nested_enum_leaf || has_nested_niche_enum_leaf || <element is itself an
    // array>` -- three shapes, covering `&[Option<i64>; 3]` (the `for e in &a` /
    // `a.iter()` IntoIterator argument) and `&[[u8; 16]; N]` (the
    // `bitset_chunk_idx` table `core::unicode::bitset_search` indexes as
    // `t[i][j]`). All three are instances of ONE property -- the flattening
    // fails -- and enumerating them by shape left a fourth instance refusing for
    // no reason: `&[(u16, [u16; 3]); N]`, the
    // `core::unicode::unicode_data::conversions` multi-character case-mapping
    // table, whose element is a TUPLE CONTAINING AN ARRAY. Its flattening fails
    // exactly like `[[u8; 16]; N]`'s does (`scalar_leaf_trust_ir_fields` has no
    // mapping for the inner `[u16; 3]`), and the memory model lays it out exactly
    // as well (the descent walks the tuple, then the inner array, to `u16`
    // leaves). So the trigger is now the PROPERTY, tested directly -- the SAME
    // discipline the closure arm below and the struct arm below it already use
    // ("fire ONLY where the flattening FAILS"). The three shape triggers are a
    // strict SUBSET of this test (each one makes the flattening fail), so nothing
    // that fired before stops firing, and every array pointee the flattening CAN
    // still represent keeps its exact existing representation.
    //
    // NO SIZE CLIFF IS INTRODUCED HERE, and the direction is the safe one: the
    // slot lane type is spelled `Ty::Array(lane, n)` in O(1) by
    // `memory_slot_lane_ty`, and its leaf validation short-circuits a uniform
    // array, whereas the scalarized flattening this arm CATCHES is the O(len) one
    // (one leaf per element). Routing more array pointees here moves them OFF the
    // expensive spelling, never onto it. Measured: an 8192-entry
    // `[(u16, [u16; 3]); N]` table (64 KiB, spelled as 32768 `I16` lanes) compiles
    // in 0.51 s / 178 MB against LLVM's 0.30 s / 158 MB, and a `&[u8; 262144]`
    // pointee -- whose flattening SUCCEEDS, so this arm does not fire -- is
    // byte-for-byte unchanged at 0.47 s on both sides of the change.
    //
    // ONE SHAPE THIS NEWLY ADMITS IS WORTH NAMING: `&[f16; N]`. An `f16` leaf has
    // `FieldsShape::Primitive` with zero sub-fields, so the leaf descent finds no
    // leaves and reports "all leaves fine" -- the same pre-existing hole this
    // function's own `&dyn` note describes. What that buys is exactly
    // `core_arch`'s `float16x4_t::as_array`, which is a pointer cast returning a
    // reference and moves no `f16` VALUE; every `f16` value operation still fails
    // closed on `Ty::Float(f16)` (measured: reading an element out of the returned
    // `&[f16; 4]` still refuses), and the register-class question at a by-value
    // boundary is independently gated by the `[TCG-ARG-ABI]` / return-ABI oracle
    // against rustc's own `FnAbi`.
    if let ty::Array(..) = ty.kind() {
        if matches!(
            aggregate_reference_pointee_to_trust_ir_ty(tcx, ty),
            Ok(Some(_))
        ) {
            return Ok(Err(format!(
                "array pointee `{ty:?}` already flattens to scalar elements; it keeps that \
                 representation"
            )));
        }
        return match memory_aggregate_layout_shared(tcx, ty) {
            Ok(Some(layout)) => Ok(Ok(layout.slot_ty.clone())),
            Ok(None) => Ok(Err(format!(
                "array pointee `{ty:?}` has no memory-aggregate layout (a direct \
                 `rust_ty_to_trust_ir_ty` mapping already covers it, or it is zero-sized)"
            ))),
            Err(e) => Ok(Err(format!(
                "array pointee `{ty:?}` has no addressable memory layout: {e}"
            ))),
        };
    }
    // A bare TUPLE pointee the scalar-field flattening cannot represent -- a tuple
    // with an ARRAY field (`&(u16, [u16; 3])`, the element reference
    // `<[(u16, [u16; 3])]>::get_unchecked` hands back from that same `conversions`
    // table, and the `([ascii::Char; N], Range<u8>)` pair `core::escape`'s
    // `backslash` / `hex_escape` / `escape_unicode` return). Its
    // `reference_pointee_lane_field_ty` has no mapping for the array field, so the
    // flattening errors; the byte-offset memory model lays the tuple out from
    // `tcx.layout_of` (rustc's own field offsets, which for a tuple may REORDER
    // fields -- `memory_aggregate_layout` reads them, it never assumes declaration
    // order), and every `(*r).N` / `(*r).N[i]` access routes through the same byte
    // walker a nested-field STRUCT pointee already uses. Tuples and named structs
    // are laid out by the identical univariant rustc logic, so this is the struct
    // arm below applied to the shape it was always true of.
    //
    // Scoped the same way as the struct arm: fire ONLY where the flattening FAILS,
    // so every tuple pointee that flattens today keeps its exact representation,
    // and a tuple whose layout the byte model cannot address (a wide / niche /
    // non-scalar leaf) keeps failing closed.
    if matches!(ty.kind(), ty::Tuple(fields) if !fields.is_empty()) {
        if matches!(
            aggregate_reference_pointee_to_trust_ir_ty(tcx, ty),
            Ok(Some(_))
        ) {
            return Ok(Err(format!(
                "tuple pointee `{ty:?}` already flattens to scalar fields; it keeps that \
                 representation"
            )));
        }
        // Keep the `[TCG-ZST-LANE-INDEX]` disposition by name: a ZST before a sized
        // field stays refused here, exactly as the flat lane refuses it.
        if let ty::Tuple(fields) = ty.kind() {
            if zero_sized_field_precedes_sized_field(tcx, fields.iter()) {
                return Ok(Err(zst_lane_index_refusal("tuple pointee", ty)));
            }
        }
        return match memory_aggregate_layout_shared(tcx, ty) {
            Ok(Some(layout)) => Ok(Ok(layout.slot_ty.clone())),
            // CLASSIFY THE DECLINE, exactly as the struct arm below does, and for
            // the same reason: an UNSIZED pointee is the architectural blocker the
            // 45-root DST diagnosis is read off, and a generic "no layout" string
            // here would drop a `(A, [T])` tuple pointee out of that count without
            // saying so. (The ARRAY arm above needs no such clause: `[T; N]`
            // requires `T: Sized` and is always sized, so it can never reach this
            // exit as a DST.)
            Ok(None) => Ok(Err(
                if !ty.is_sized(tcx, ty::TypingEnv::fully_monomorphized()) {
                    format!(
                        "tuple pointee `{ty:?}` is UNSIZED (a DST with a `[T]` / `str` \
                         tail): the byte-offset memory model needs a fixed size and \
                         alignment, and a reference to it is a FAT pointer, not the thin \
                         pointer this lane types. Fix options: give the DST pointee a \
                         two-lane (`{{data, len}}`) reference model, or keep the caller on \
                         a sized view of the tail"
                    )
                } else {
                    format!(
                        "tuple pointee `{ty:?}` has no memory-aggregate layout (a direct \
                         `rust_ty_to_trust_ir_ty` mapping already covers it, or it is \
                         zero-sized)"
                    )
                },
            )),
            Err(e) => Ok(Err(format!(
                "tuple pointee `{ty:?}` has no addressable memory layout: {e}"
            ))),
        };
    }
    // A CLOSURE ENVIRONMENT pointee whose upvar set the scalar-field flattening
    // cannot represent — specifically one holding a FAT-POINTER upvar (`&dyn
    // Trait`, `&[T]`, `&str`). The env is a single-variant aggregate that
    // `closure_memory_layout` lays out from rustc's layout (and whose leaf
    // validation already admits a fat upvar as two lanes), and the closure body
    // reads each upvar as `(*env).N` through the byte walker, so type the `&env`
    // parameter as a thin pointer to that slot's flat lane tuple — exactly as a
    // nested-field struct pointee is typed below. The lane tuple is ONLY the
    // ABI/thin-pointer shell; every upvar access uses the REAL closure layout.
    //
    // Scoped the same way as the struct arm: fire ONLY where the flattening
    // FAILS, so every closure whose upvars flatten today keeps its exact existing
    // representation, and a closure whose layout the byte model cannot express
    // (`Err`) keeps failing closed.
    if matches!(ty.kind(), ty::Closure(..)) {
        if matches!(
            aggregate_reference_pointee_to_trust_ir_ty(tcx, ty),
            Ok(Some(_))
        ) {
            return Ok(Err(format!(
                "closure env pointee `{ty:?}` already flattens to scalar upvars; it keeps \
                 that representation"
            )));
        }
        return match closure_memory_layout(tcx, ty) {
            Ok(Some(layout)) => Ok(Ok(layout.slot_ty)),
            Ok(None) => Ok(Err(format!(
                "closure env pointee `{ty:?}` has no closure memory layout"
            ))),
            Err(e) => Ok(Err(format!(
                "closure env pointee `{ty:?}` has no addressable closure layout: {e}"
            ))),
        };
    }
    // Narrow to a STRUCT pointee — arrays, non-empty tuples and closures are
    // answered by their own arms above. Multi-variant enums are handled by
    // `memory_enum_reference_pointee_lane_ty`.
    let ty::Adt(adt, _) = ty.kind() else {
        return Ok(Err(format!(
            "pointee `{ty:?}` is not a named ADT, an array, a non-empty tuple or a \
             closure; only those are typed as a memory-aggregate lane tuple here (a \
             multi-variant enum goes through `memory_enum_reference_pointee_lane_ty`)"
        )));
    };
    let single_variant_enum = adt.is_enum()
        && adt.variants().len() == 1
        && tcx.sess.target.arch.desc() == "aarch64"
        && tcx.sess.target.os == rustc_target::spec::Os::Linux;
    if !adt.is_struct() && !single_variant_enum {
        return Ok(Err(format!(
            "pointee `{ty:?}` is not a struct or supported single-variant enum"
        )));
    }
    // A single-variant enum with nested fields has the same checked byte
    // image as a struct. Its pointer shell does not assign field offsets;
    // whole copies and projected accesses still consult rustc's layout.
    // Only fire where the scalar-field flattening FAILS (a nested-aggregate / array
    // field). A flat scalar-leaf struct it can represent (`Ok(Some(..))`) stays on the
    // scalarized path verbatim — no change of mechanism for any working case.
    if matches!(
        aggregate_reference_pointee_to_trust_ir_ty(tcx, ty),
        Ok(Some(_))
    ) {
        return Ok(Err(format!(
            "struct pointee `{ty:?}` already flattens to scalar fields; it keeps that \
             representation"
        )));
    }
    // The byte-offset memory model must be able to lay the pointee out (size/align +
    // every leaf a fixed-offset memory scalar). `memory_aggregate_layout` returns
    // `Ok(None)` when `rust_ty_to_trust_ir_ty` already maps the type (a single-field
    // newtype scalar) — leave that to the direct mapping — and `Err` for a shape the
    // byte model cannot address (wide / niche / non-scalar leaf), which fails closed
    // — EXCEPT the one `Err` that is only about ALIGNMENT: an over-aligned struct
    // pointee gets its 16-byte-lane shell (`over_aligned_pointee_shell_lane_ty`).
    match memory_aggregate_layout_shared(tcx, ty) {
        Ok(Some(layout)) => Ok(Ok(layout.slot_ty.clone())),
        // `memory_aggregate_layout` answers `Ok(None)` for FOUR different reasons and
        // they are not interchangeable — the DST one is a real architectural blocker
        // and the other three are "something else already owns this type". Classify
        // it, or the reader learns only that a helper said no.
        Ok(None) => Ok(Err(
            if !ty.is_sized(tcx, ty::TypingEnv::fully_monomorphized()) {
                format!(
                    "struct pointee `{ty:?}` is UNSIZED (a DST with a `[T]` / `str` tail): \
                     the byte-offset memory model needs a fixed size and alignment, and a \
                     reference to it is a FAT pointer, not the thin pointer this lane types. \
                     Fix options: give the DST pointee a two-lane (`{{data, len}}`) reference \
                     model, or keep the caller on a sized view of the tail"
                )
            } else if is_zero_sized_ty(tcx, ty) {
                format!("struct pointee `{ty:?}` is zero-sized")
            } else if rust_ty_to_trust_ir_ty(tcx, ty).is_ok() {
                format!(
                    "struct pointee `{ty:?}` already has a direct `rust_ty_to_trust_ir_ty` \
                     mapping (a single-field newtype scalar), which is left to own it"
                )
            } else {
                format!("struct pointee `{ty:?}` has no memory-aggregate layout")
            },
        )),
        // The one `Err` that is only about ALIGNMENT gets the over-aligned shell;
        // every other layout failure is a reasoned decline.
        Err(e) => match over_aligned_pointee_shell_lane_ty(tcx, ty)? {
            Some(shell) => Ok(Ok(shell)),
            None => Ok(Err(format!(
                "struct pointee `{ty:?}` has no addressable memory-aggregate layout: {e}"
            ))),
        },
    }
}

/// The thin-pointer SHELL of an OVER-ALIGNED struct pointee — `&__m256i` /
/// `*const __m512d` in core_arch's `as_array` (`&*(self as *const Self as *const
/// [T; N])`, ten `library/core` roots), a `#[repr(C, align(32))]` wrapper — whose
/// alignment exceeds the 16-byte stack alignment the memory model's slot lanes
/// cover on a 64-bit session (`memory_slot_lane_ty` refuses align 32 / 64 there,
/// and the native frame clamps an `Alloca` at 16). `Ok(None)` for every other
/// type. A wasm32 session gives such a struct a real slot
/// (`memory_aggregate_lane`), so there the layout query answers first for every
/// struct the byte model can lay out; the two spell the same
/// `Array(I128, size / 16)`.
///
/// WHAT THE SHELL IS, AND IS NOT. It is the ABI / thin-pointer spelling
/// `Array(I128, size / 16)` of a pointee that only ever has its ADDRESS
/// preserved: the cast to `*const [T; N]` and the reborrow, whose result then
/// flattens as an ordinary array reference. It is NOT a slot: an over-aligned
/// LOCAL, parameter, return or call destination keeps refusing at
/// `memory_slot_lane_ty` (this helper is consulted by the pointee typing only,
/// never by `memory_backed_local_layout`), and a FIELD read through the shell
/// (`(*r).0[i]`) keeps refusing because `memory_aggregate_ref_pointee` finds no
/// layout to address it with — so the 16-byte lane stride the shell spells can
/// never be used to compute an offset. Measured: the control fixture reading
/// `(*r).0[1]` through a `&A32` refuses, the cast-and-reborrow program agrees
/// with LLVM.
///
/// The gates are those of `memory_aggregate_layout_uncached`'s single-variant
/// arm — sized, `Variants::Single`, every field validated by
/// `validate_memory_aggregate_field_leaves` with the same uniform-element short
/// circuit — plus: alignment strictly above the stack alignment (below it the
/// real layout already answered or refused), and a size that is a multiple of
/// 16 so the shell tiles exactly. A fat-pointer / nested-enum / niche leaf
/// declines: the shell has no lane model for them and nothing here needs one.
fn over_aligned_pointee_shell_lane_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<TrustIrTy>, String> {
    let ty::Adt(adt, _) = ty.kind() else {
        return Ok(None);
    };
    if !adt.is_struct() {
        return Ok(None);
    }
    let cx = LayoutCx(tcx);
    let Ok(layout) = tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty)) else {
        return Ok(None);
    };
    if !layout.is_sized() {
        return Ok(None);
    }
    let size = layout.size.bytes();
    let align = layout.align.bytes();
    if align <= TARGET_STACK_ALIGN_BYTES || size == 0 || size % TARGET_STACK_ALIGN_BYTES != 0 {
        return Ok(None);
    }
    use rustc_abi::Variants;
    if !matches!(layout.variants, Variants::Single { .. }) {
        return Ok(None);
    }
    let variant = layout.for_variant(&cx, rustc_abi::FIRST_VARIANT);
    let mut leaves = Vec::new();
    match variant.fields {
        rustc_abi::FieldsShape::Array { count: 0, .. } => {}
        rustc_abi::FieldsShape::Array { .. } => {
            leaves.push(validate_memory_aggregate_field_leaves(
                tcx,
                &cx,
                &variant.field(&cx, 0),
            )?);
        }
        _ => {
            for field in 0..variant.fields.count() {
                let field_layout = variant.field(&cx, field);
                if field_layout.is_zst() {
                    continue;
                }
                leaves.push(validate_memory_aggregate_field_leaves(
                    tcx,
                    &cx,
                    &field_layout,
                )?);
            }
        }
    }
    if leaves.iter().any(|info| {
        info.has_fat_pointer_leaf || info.has_nested_enum_leaf || info.has_nested_niche_enum_leaf
    }) {
        return Ok(None);
    }
    Ok(Some(memory_slot_lane_ty(size, TARGET_STACK_ALIGN_BYTES)?))
}

/// FAIL CLOSED when a ZERO-SIZED field sits BEFORE a sized field in an aggregate
/// whose by-reference pointee is modeled as the flat lane tuple of its SIZED
/// fields only. That tuple drops every ZST lane, so a lane index equals the MIR
/// field index only while no ZST precedes the field being accessed; every
/// consumer that turns a `(*r).N` / `(*r as V).N` MIR field index into a lane
/// (`aggregate_field_memory_access`, the by-ref materialization in
/// `lower_aggregate_reference_call_arg`, `nested_array_aggregate_deref_field_index`)
/// indexes by the MIR number. The review measured the divergence: `struct S1 {
/// w: W16(()), a: u8, b: u8 }` read through `&S1` returned `b` for `s.a`
/// (`adv_zst4_field_index.rs`, `4 6` for `3 5`), a `struct P2 { z: [u8; 0], a,
/// b }` returned `b` for `p.a`, and `&([u8; 0], u32, u32)` at -O2 read the wrong
/// element. A trailing ZST (`PhantomData` last, the `Vec`/`RawVec`/`slice::Iter`
/// shapes) shifts nothing and stays admitted; the by-VALUE scalarized path keys
/// its projected values by MIR index on both sides and is not affected. Refusing
/// here — rather than remapping every consumer — is the fail-closed disposition
/// for a lane/index disagreement.
///
/// WHAT REFUSING HERE NOW MEANS, and it is no longer "the program refuses".
/// This function rejects the FLAT LANE TUPLE only. Its callers answer that
/// rejection by typing the pointee as the rustc-layout MEMORY SLOT instead
/// (`memory_aggregate_reference_pointee_lane_ty`), where every field is
/// addressed at its own layout offset and the lane/index question does not
/// arise — that was already true for a STRUCT pointee, and as of 2026-09-14
/// (the sized-array value-type lane) it is true for a bare TUPLE and an ARRAY
/// pointee as well. So `&([u8; 0], u32, u32)` compiles and reads correctly
/// (`fix_e_zst_tuple_by_ref.rs`, measured `10 20` at -O0 and -O2, matching
/// LLVM), and the refusal is what keeps it OFF the short tuple while it does
/// so. A shape the memory model ALSO cannot lay out still fails closed by this
/// name.
fn zero_sized_field_precedes_sized_field<'tcx>(
    tcx: TyCtxt<'tcx>,
    field_tys: impl IntoIterator<Item = Ty<'tcx>>,
) -> bool {
    let mut seen_zst = false;
    for field_ty in field_tys {
        if is_zero_sized_ty(tcx, field_ty) {
            seen_zst = true;
        } else if seen_zst {
            return true;
        }
    }
    false
}

fn zst_lane_index_refusal(what: &str, ty: Ty<'_>) -> String {
    format!(
        "[TCG-ZST-LANE-INDEX] {what} `{ty:?}` has a zero-sized field BEFORE a sized field: \
         its by-reference lane tuple drops the ZST lane, so a MIR field index and a lane \
         index disagree and a `(*r).field` access would read the neighbouring field; \
         failing closed rather than miscompiling. Options: (1) move the zero-sized \
         field(s) after every sized field, (2) access the value by value rather than \
         through a reference, (3) `#[repr(C)]` with the ZST last"
    )
}

/// One LANE of a by-reference pointee's flat lane tuple, for a field whose lane
/// index is its MIR field index.
///
/// Identical to `rust_ty_to_trust_ir_ty` EXCEPT that a FAT POINTER field
/// (`&[T]` / `&str` / `&dyn Trait`) is refused by name. That exception is the
/// whole point of the helper: `rust_ty_to_trust_ir_ty` maps a `&str` / `&[T]`
/// to a plain `Ptr` — the SAME single lane a thin `&T` gets — so a struct
/// holding one flattens to a lane tuple that is 8 bytes SHORT per fat field and
/// whose later lanes therefore sit at the wrong byte offsets. The callee then
/// reads `(*r).field` at rustc's real layout offsets
/// (`walk_memory_projection_offset_raw`) while the caller materialized the
/// short tuple, and the two disagree — a SILENT MISCOMPILE, measured: `struct
/// Rec { head: i64, name: &str, tail: i64 }` read through `&Rec` returned a
/// text-segment ADDRESS for `head` (`4.3e9` for `11`), and `b.name.len()`
/// returned the data pointer.
///
/// Refusing here is not a capability loss: `reference_pointee_to_trust_ir_ty`
/// answers an `Err` from the flattening by typing the pointee as the
/// memory-aggregate SLOT lane tuple instead (`memory_aggregate_reference_
/// pointee_lane_ty`), which is laid out from `tcx.layout_of` and addressed by
/// the same byte walker the body uses. That is exactly the path a `&dyn
/// Trait` field already takes today — `rust_ty_to_trust_ir_ty` has no `dyn`
/// mapping, so the flattening errors and the aggregate lands on the byte path,
/// which is why the `&dyn` leaf work is correct and the `&str` / `&[T]` leaf
/// was not. Both metadata kinds are named here so the disposition is stated
/// rather than inherited from an unrelated error.
///
/// The NESTED descent (`scalar_leaf_trust_ir_fields`) already carries this
/// guard for the same reason; this is the TOP-LEVEL field that was missing it.
fn reference_pointee_lane_field_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    field_ty: Ty<'tcx>,
) -> Result<TrustIrTy, String> {
    // Both the KIND test (`&[T]` / `&str` / `&dyn`) and the LAYOUT-true one (a
    // reference to ANY unsized pointee — a struct with a `[T]` / `str` TAIL:
    // `&ByteStr`, `&CStr`, `&Wtf8`). The second is what keeps this guard correct
    // now that such a reference HAS a `rust_ty_to_trust_ir_ty` mapping: without
    // it the mapping below answers `Ptr` and the pointee flattens to a lane tuple
    // that is 8 bytes SHORT at that field, putting every later field at the wrong
    // byte offset. Identical reasoning, identical predicate and identical
    // disposition to `scalar_leaf_trust_ir_fields`'s nested-descent guard.
    //
    // A `repr(transparent)` newtype over a slice/str pointer (`NonNull<str>`,
    // `core::panic::Location::filename`) is the same two-lane leaf, and neither
    // test above sees through the ADT: `rust_ty_to_trust_ir_ty` collapsed it to
    // ONE `Ptr`, so every later field was read 8 bytes early (`Location::line()`
    // returned the filename's length).
    if is_fat_pointer_memory_leaf_ty(field_ty)
        || is_wide_pointer_memory_leaf_ty(tcx, field_ty)
        || transparent_newtype_is_slice_fat_ptr(tcx, field_ty)
    {
        return Err(format!(
            "[TCG-FAT-POINTEE-LANE] by-reference pointee field `{field_ty:?}` is a FAT \
             pointer (two lanes: data + metadata); a one-lane-per-field pointee tuple \
             would place every later field at the wrong byte offset, so this pointee is \
             not flattenable. Options: (1) it is typed from the rustc memory layout \
             instead (automatic — see `memory_aggregate_reference_pointee_lane_ty`), \
             (2) pass the aggregate by value, (3) split the fat field into its data \
             pointer and length/vtable"
        ));
    }
    rust_ty_to_trust_ir_ty(tcx, field_ty)
}

fn aggregate_reference_pointee_to_trust_ir_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<TrustIrTy>, String> {
    // An intercepted `Vec<T>` / `String` pointee is NOT a scalarized aggregate:
    // the value is itself a single `Ptr` (its `{ptr,cap,len}` slot address), so
    // `&Vec`/`&mut Vec`/`&String` carries that pointer scalar. Return `None` so the
    // caller falls through to `rust_ty_to_trust_ir_ty` -> `Ptr`, never flattening
    // the `Vec`/`RawVec`/`String` struct field-wise. An intercepted
    // `BTreeMap<K, V>` pointee is likewise a single `Ptr` (`&BTreeMap`/
    // `&mut BTreeMap` carries the slot address).
    if vec_element_ty(tcx, ty).is_some()
        || btreemap_kv_ty(tcx, ty).is_some()
        || any_hashmap_kv_ty(tcx, ty).is_some()
        || is_string_ty(tcx, ty)
    {
        return Ok(None);
    }
    // A SINGLE-SCALAR-FIELD struct / single-variant single-field enum
    // (`struct C { n: i32 }` — a NEWTYPE) is represented as its BARE SCALAR, not a
    // 1-field aggregate: `adt_maps_to_single_scalar` routes its value through the
    // scalar path (the construct binds the whole local as one scalar, not a
    // per-field projection), and the borrowing `_r = &c` binds `_r` as a
    // `borrowed_scalar`. So `&C` / `&mut C` must be a THIN pointer to that scalar
    // (exactly like `&i32`), NOT a flattened 1-field tuple. Returning `None` keeps
    // all three consumers in ABI agreement — the callee's `&self` param typing
    // (`reference_pointee_to_trust_ir_ty`, which delegates here first) and the
    // caller's call-arg handler (`lower_aggregate_reference_call_arg`) both fall
    // through to the scalar-reference path that already lowers a NEWTYPE getter /
    // setter (`c.get(&self)` / `c.set(&mut self)`, `&mut` write-back included).
    // Multi-field structs are unaffected (`adt_maps_to_single_scalar` is false).
    if adt_maps_to_single_scalar(tcx, ty) {
        return Ok(None);
    }
    // Zero-sized fields (`PhantomData`, `Global`, `()`) occupy no bytes and carry
    // no scalar leaf, so they are dropped from the flattened pointee layout
    // rather than rejected for being non-memory-scalar.
    match ty.kind() {
        ty::Tuple(fields) if !fields.is_empty() => {
            if zero_sized_field_precedes_sized_field(tcx, fields.iter()) {
                return Err(zst_lane_index_refusal("by-reference tuple pointee", ty));
            }
            let fields = fields
                .iter()
                .filter(|field_ty| !is_zero_sized_ty(tcx, *field_ty))
                .map(|field_ty| reference_pointee_lane_field_ty(tcx, field_ty))
                .collect::<Result<Vec<_>, _>>()?;
            if fields.is_empty() {
                return Ok(None);
            }
            for (field, field_ty) in fields.iter().enumerate() {
                // Pointer-like field = valid memory scalar (bit_width()==None after
                // trust-ir 6ed4bf0 made pointer width target-dependent); mirror the
                // closure-upvar fix / memory_scalar_leaf_ty / site ~16722.
                if field_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(field_ty) {
                    return Err(format!(
                        "aggregate reference tuple field {field} is not memory-scalar: \
                         {field_ty:?}"
                    ));
                }
            }
            Ok(Some(TrustIrTy::Tuple(fields)))
        }
        ty::Array(element, len) => {
            let len = len
                .try_to_target_usize(tcx)
                .ok_or_else(|| format!("array length is not target-usize evaluable: {ty:?}"))?;
            let len = usize::try_from(len)
                .map_err(|_| format!("array length {len} out of usize range"))?;
            if len == 0 {
                return Ok(None);
            }
            // An array is scalarized into ONE LEAF PER ELEMENT, so this is O(len)
            // in both time and memory. Unbounded, that is a hazard rather than a
            // slowdown: a `[u8; 4 << 20]` local drove the compiler to 640MB RSS
            // and 2.0s (LLVM: 98MB, 0.11s, FLAT in the array size), and it grows
            // from there — the leaf vector is the whole array.
            //
            // Past a few thousand leaves, field-wise modelling is also simply the
            // wrong model: `Ok(None)` routes the aggregate down the MEMORY path,
            // which is what a large array wants and what LLVM effectively does.
            // The bound is set well above anything real: the largest array in the
            // benchmarks or bridge tests is 8192 elements (v2_memfill), so every
            // shape exercised today keeps its exact current lowering.
            if let Some(element_fields) = scalar_field_aggregate_trust_ir_fields(tcx, *element)? {
                let mut fields = Vec::with_capacity(element_fields.len() * len);
                for _ in 0..len {
                    fields.extend(element_fields.iter().cloned());
                }
                return Ok(Some(TrustIrTy::Tuple(fields)));
            }
            let element_ty = reference_pointee_lane_field_ty(tcx, *element)?;
            // Pointer-like element is a valid memory scalar (see closure-upvar fix).
            if element_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(&element_ty) {
                return Err(format!(
                    "aggregate reference array element is not memory-scalar: {element_ty:?}"
                ));
            }
            Ok(Some(TrustIrTy::Tuple(vec![element_ty; len])))
        }
        ty::Adt(adt, args) if adt.is_struct() => {
            let variant = adt.variant(VariantIdx::new(0));
            if variant.fields.is_empty() {
                return Ok(None);
            }
            if zero_sized_field_precedes_sized_field(
                tcx,
                variant
                    .fields
                    .iter()
                    .map(|field| normalized_adt_field_ty(tcx, field, *args)),
            ) {
                return Err(zst_lane_index_refusal("by-reference struct pointee", ty));
            }
            let fields = variant
                .fields
                .iter()
                .map(|field| normalized_adt_field_ty(tcx, field, *args))
                .filter(|field_ty| !is_zero_sized_ty(tcx, *field_ty))
                .map(|field_ty| reference_pointee_lane_field_ty(tcx, field_ty))
                .collect::<Result<Vec<_>, _>>()?;
            if fields.is_empty() {
                return Ok(None);
            }
            for (field, field_ty) in fields.iter().enumerate() {
                if field_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(field_ty) {
                    return Err(format!(
                        "aggregate reference struct field {field} is not memory-scalar: \
                         {field_ty:?}"
                    ));
                }
            }
            Ok(Some(TrustIrTy::Tuple(fields)))
        }
        ty::Adt(adt, args) if adt.is_enum() => {
            if adt.variants().len() != 1 {
                // A MULTI-VARIANT enum has no single flat scalar-field tuple (its
                // inhabited fields differ per variant). It is NOT flattenable here;
                // return `None` so `reference_pointee_to_trust_ir_ty` falls through
                // to the thin-pointer lane-tuple representation
                // (`memory_enum_reference_pointee_lane_ty`) and the enum is decoded
                // through the pointer by the memory model. (Single-variant enums
                // still flatten below.)
                return Ok(None);
            }
            // A single-variant enum whose repr keeps a TAG is laid out like its
            // multi-variant siblings (tag first, payload after it), so its
            // declared fields are NOT its pointee lanes: decode it through the
            // same memory-enum pointee lane. MEASURED (2026-09-28, AArch64, the
            // `m145` `tag_c_ref` row): a bridge-built `fn tc_read(v: &TagC) ->
            // u64 { match *v { TagC::V(x) => x as u64 } }` over `#[repr(C)] enum
            // TagC { V(i64) }` read the TAG as the payload and answered 0.
            if single_variant_enum_keeps_tag(tcx, ty) {
                return Ok(None);
            }
            // Likewise one whose sized fields rustc REORDERED (`repr(Rust)` lays
            // an enum variant out by descending alignment): declaration-order
            // lanes would address the wrong bytes. MEASURED (2026-09-28, AArch64,
            // the `m145` `reorder_ref` row): `fn rd_read(v: &Reord) -> u64` over
            // `enum Reord { V(u8, i64) }` (the `i64` at 0, the `u8` at 8) read
            // garbage — through a bridge-built reference too, so every
            // all-bridge program agreed with nothing.
            if !single_variant_enum_lanes_match_rustc_offsets(tcx, ty) {
                return Ok(None);
            }
            let variant = adt.variant(VariantIdx::new(0));
            if variant.fields.is_empty() {
                return Ok(None);
            }
            if zero_sized_field_precedes_sized_field(
                tcx,
                variant
                    .fields
                    .iter()
                    .map(|field| normalized_adt_field_ty(tcx, field, *args)),
            ) {
                return Err(zst_lane_index_refusal(
                    "by-reference single-variant enum pointee",
                    ty,
                ));
            }
            let fields = variant
                .fields
                .iter()
                .map(|field| normalized_adt_field_ty(tcx, field, *args))
                .filter(|field_ty| !is_zero_sized_ty(tcx, *field_ty))
                .map(|field_ty| reference_pointee_lane_field_ty(tcx, field_ty))
                .collect::<Result<Vec<_>, _>>()?;
            if fields.is_empty() {
                return Ok(None);
            }
            for (field, field_ty) in fields.iter().enumerate() {
                if field_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(field_ty) {
                    return Err(format!(
                        "aggregate reference enum field {field} is not memory-scalar: \
                         {field_ty:?}"
                    ));
                }
            }
            Ok(Some(TrustIrTy::Tuple(fields)))
        }
        // `&closure`: the pointee is an anonymous struct of the captured upvars.
        ty::Closure(_, args) => {
            let upvars: Vec<Ty<'tcx>> = args.as_closure().upvar_tys().iter().collect();
            if upvars.is_empty() {
                return Ok(None);
            }
            // The closure body reads `(*env).N` by UPVAR index; the same
            // lane/index disagreement as a struct with a leading ZST field.
            if zero_sized_field_precedes_sized_field(tcx, upvars.iter().copied()) {
                return Err(zst_lane_index_refusal(
                    "by-reference closure environment",
                    ty,
                ));
            }
            let mut fields: Vec<TrustIrTy> = Vec::new();
            for upvar_ty in upvars.iter().copied() {
                if is_zero_sized_ty(tcx, upvar_ty) {
                    continue;
                }
                match reference_pointee_lane_field_ty(tcx, upvar_ty) {
                    Ok(mapped) => fields.push(mapped),
                    Err(scalar_err) => {
                        // An upvar that is ITSELF a scalar-field aggregate (a
                        // multi-field struct captured by value) has no single-scalar
                        // mapping. Nest its leaves as ONE tuple field rather than
                        // splicing them in flat: the closure body reads its captures
                        // as `(*env).N` where N is the UPVAR index, so flattening
                        // would shift every later upvar's index and read the WRONG
                        // capture — a miscompile, not a refusal.
                        //
                        // Recursing into THIS function (rather than
                        // `scalar_field_aggregate_trust_ir_fields`) reuses the arms
                        // that already type a struct / tuple / ARRAY pointee, so an
                        // `[i64; 4]` upvar is handled by the same code that types
                        // `&[i64; 4]`, and its own memory-scalar leaf checks apply.
                        match aggregate_reference_pointee_to_trust_ir_ty(tcx, upvar_ty)? {
                            Some(nested) => fields.push(nested),
                            None => return Err(scalar_err),
                        }
                    }
                }
            }
            if fields.is_empty() {
                return Ok(None);
            }
            for (field, field_ty) in fields.iter().enumerate() {
                // A pointer-like field is a valid memory scalar even though its
                // `bit_width()` is `None` after trust-ir made pointer width
                // target-dependent (commit 6ed4bf0). Mirror `memory_scalar_leaf_ty`
                // / site ~16722, which already accept pointer-like leaves — WITHOUT
                // this clause the std `lang_start` FnOnce closure (whose upvar is a
                // `Ptr`) fails closed, so EVERY std `fn main()` program fails to
                // compile.
                if field_ty.bit_width().is_none()
                    && !is_pointer_like_trust_ir_ty(field_ty)
                    && !matches!(field_ty, TrustIrTy::Tuple(_))
                {
                    return Err(format!(
                        "aggregate reference closure upvar {field} is not memory-scalar: \
                         {field_ty:?}"
                    ));
                }
            }
            Ok(Some(TrustIrTy::Tuple(fields)))
        }
        _ => Ok(None),
    }
}

/// Whether a single-variant enum KEEPS A TAG in rustc's layout
/// (`Variants::Multiple`): a `#[repr(C)]` / `#[repr(uN)]` / `#[repr(iN)]`
/// single-variant enum is laid out like its multi-variant siblings, tag first —
/// `#[repr(C)] enum TagC { V(i64) }` is 16 bytes, a 4-byte tag at 0 and the
/// payload at 8 — whereas a plain `enum E { V(i64) }` is `Variants::Single` and
/// exactly its payload. The declared fields never list the tag, so every
/// field-walking flattening of such an enum drops it and puts the payload at
/// offset 0. MEASURED (2026-09-28, AArch64, rlib x bin): `tc_read(&TagC::V(-51))`
/// with the reader built by LLVM answered 0 at O0 and O3 — the bridge typed
/// `TagC` as the one scalar `I64`, so `&TagC` pointed at an 8-byte cell holding
/// the payload where LLVM reads the tag. A tagged single-variant enum is
/// therefore never a scalar-field aggregate: the type mapper declines it (a
/// payload-free one falls to the tag-only arm, which models exactly the tag),
/// and the memory lane models it from the same layout as any Direct-tagged enum.
fn single_variant_enum_keeps_tag<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, _) = ty.kind() else {
        return false;
    };
    if !adt.is_enum() || adt.variants().len() != 1 {
        return false;
    }
    // A layout error is not evidence of a tag-free layout; decline the
    // flattening (fail closed) rather than assume one.
    tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_or(true, |layout| {
            matches!(
                layout.layout.variants(),
                rustc_abi::Variants::Multiple { .. }
            )
        })
}

/// Whether a TAG-FREE single-variant enum's sized fields, laid as lanes in
/// DECLARATION order (each at its natural alignment — the scalar-field pointee
/// tuple `aggregate_reference_pointee_to_trust_ir_ty` builds), sit exactly at
/// rustc's own field offsets. `false` for anything rustc laid out otherwise
/// (a `repr(Rust)` reordering, a tag, an unknown layout) — the memory-enum
/// pointee lane then addresses every field at rustc's offset instead.
fn single_variant_enum_lanes_match_rustc_offsets<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    let ty::Adt(adt, args) = ty.kind() else {
        return false;
    };
    if !adt.is_enum() || adt.variants().len() != 1 {
        return false;
    }
    let typing_env = ty::TypingEnv::fully_monomorphized();
    let Ok(layout) = tcx.layout_of(typing_env.as_query_input(ty)) else {
        return false;
    };
    if !matches!(layout.layout.variants(), rustc_abi::Variants::Single { .. }) {
        return false;
    }
    let mut end = 0u64;
    for (index, field) in adt.variant(VariantIdx::new(0)).fields.iter().enumerate() {
        let field_ty = field.ty(tcx, *args).skip_normalization();
        let Ok(field_layout) = tcx.layout_of(typing_env.as_query_input(field_ty)) else {
            return false;
        };
        if field_layout.is_zst() {
            continue;
        }
        let natural = end.next_multiple_of(field_layout.align.bytes());
        if index >= layout.fields.count() || layout.fields.offset(index).bytes() != natural {
            return false;
        }
        end = natural + field_layout.size.bytes();
    }
    true
}

fn single_variant_enum_tag_refusal(ty: Ty<'_>) -> String {
    format!(
        "[TCG-LAYOUT-IMAGE] single-variant enum `{ty:?}` keeps a TAG in rustc's layout \
         (its repr is `C` or a primitive), which its declared fields do not list, so it has \
         no field-by-field scalar image: flattening the fields would drop the tag and move \
         the payload to offset 0. Only the tagged memory-enum model represents it; this \
         position asked for a scalar image, so it fails closed. Options: (1) drop the \
         `#[repr]` (a plain single-variant enum is exactly its payload); (2) pass or hold \
         the value by reference; (3) keep this function on the LLVM backend"
    )
}

/// DIAGNOSTIC ONLY (`bridge-notes`): which call site asked this aggregate to
/// flatten. The sibling of `rust_ty_to_trust_ir_ty`'s `[ty site:]` note, and
/// needed for the same reason — an `Err` out of this family names the LEAF that
/// has no scalar form, never the QUESTION, and a flattening decline is a hard
/// stop from one caller and a "try the memory lane" signal from another. The
/// default message is byte-identical (census reason keys and UI tests do not
/// move); `#[track_caller]` makes the location the CALLER's and CHAINS through
/// the mutual recursion with `scalar_leaf_trust_ir_fields`, so a whole descent
/// prints one site per frame. The location is captured in THIS function's own
/// body, not inside the closure — the same trap `memory_scalar_leaf_ty::site`
/// documents.
#[track_caller]
fn scalar_field_aggregate_trust_ir_fields<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<Vec<TrustIrTy>>, String> {
    let call_site = std::panic::Location::caller();
    scalar_field_aggregate_trust_ir_fields_inner(tcx, ty).map_err(move |e| {
        if bridge_notes_enabled() {
            format!("{e} [agg site: {}:{}]", call_site.file(), call_site.line())
        } else {
            e
        }
    })
}

fn scalar_field_aggregate_trust_ir_fields_inner<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<Vec<TrustIrTy>>, String> {
    // A zero-sized field (`PhantomData`, `Global`, `()`) occupies no bytes and
    // contributes no scalar leaf, so it is dropped from the flattened layout
    // rather than failing closed on its `Unit` trust-ir type. This is what lets
    // `Vec`/`RawVec`-shaped structs (whose `PhantomData<T>` / `Global`
    // marker fields surround the real `ptr`/`cap` scalars) flatten to their
    // genuine scalar leaves.
    match ty.kind() {
        ty::Tuple(fields) if !fields.is_empty() => {
            let mut flattened = Vec::new();
            for field_ty in fields.iter() {
                if is_zero_sized_ty(tcx, field_ty) {
                    continue;
                }
                flattened.extend(scalar_leaf_trust_ir_fields(tcx, field_ty)?);
            }
            Ok(Some(flattened))
        }
        ty::Adt(adt, args) if adt.is_struct() => {
            let variant = adt.variant(VariantIdx::new(0));
            if variant.fields.is_empty() {
                return Ok(None);
            }
            let mut flattened = Vec::new();
            for field in variant.fields.iter() {
                let field_ty = normalized_adt_field_ty(tcx, field, *args);
                if is_zero_sized_ty(tcx, field_ty) {
                    continue;
                }
                flattened.extend(scalar_leaf_trust_ir_fields(tcx, field_ty)?);
            }
            Ok(Some(flattened))
        }
        ty::Adt(adt, args) if adt.is_enum() && adt.variants().len() == 1 => {
            // A single-variant enum whose repr keeps a TAG has a tag field the
            // declared fields do not list; flattening them would drop it.
            if single_variant_enum_keeps_tag(tcx, ty) {
                return Err(single_variant_enum_tag_refusal(ty));
            }
            let variant = adt.variant(VariantIdx::new(0));
            if variant.fields.is_empty() {
                return Ok(None);
            }
            let mut flattened = Vec::new();
            for field in variant.fields.iter() {
                let field_ty = normalized_adt_field_ty(tcx, field, *args);
                if is_zero_sized_ty(tcx, field_ty) {
                    continue;
                }
                flattened.extend(scalar_leaf_trust_ir_fields(tcx, field_ty)?);
            }
            Ok(Some(flattened))
        }
        ty::Closure(_, args) => {
            let upvars: Vec<Ty<'tcx>> = args.as_closure().upvar_tys().iter().collect();
            if upvars.is_empty() {
                return Ok(None);
            }
            let mut flattened = Vec::new();
            for upvar_ty in upvars {
                if is_zero_sized_ty(tcx, upvar_ty) {
                    continue;
                }
                flattened.extend(scalar_leaf_trust_ir_fields(tcx, upvar_ty)?);
            }
            Ok(Some(flattened))
        }
        _ => Ok(None),
    }
}

/// DIAGNOSTIC ONLY (`bridge-notes`): the `[leaf site:]` half of the pair
/// documented on [`scalar_field_aggregate_trust_ir_fields`]. Together the two
/// notes print the whole flattening descent, innermost frame first — which is
/// how the `library/core` census located the OUTERMOST consumer of a union-leaf
/// refusal (`lower_recursive_scalar_field_aggregate_operands`) in one run.
#[track_caller]
fn scalar_leaf_trust_ir_fields<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Vec<TrustIrTy>, String> {
    let call_site = std::panic::Location::caller();
    // `with_no_visible_paths!`, as in `rust_ty_to_trust_ir_ty`: the refusals
    // this descent builds embed `{ty:?}` renderings, and the visible-path
    // printer's first use computes `visible_parent_map` (a sweep of every
    // crate's `module_children`). `compute_memory_backed_locals` asks
    // `.is_ok()` of this for every local and discards the string, and the fat
    // pointer refusal below reached that sweep on every std `fn main`
    // (`lang_start::<()>`'s `&dyn Fn() -> i32 + Sync + RefUnwindSafe` capture).
    // The sweep is paid once, by whichever eager renderer runs first (this one,
    // then the vtable site in `emit_vtable_global_at_depth`); an attribution
    // run on `h1_vec_push_sum` (aarch64-apple-darwin, L14-P10, `vmmap`; its log
    // was not retained) put it at about 5.4 MB of `.rmeta` pages and 4.8 MB of
    // heap, all of it at the compiler's peak. The
    // surfaced text names the defining crate's path (`core::…` for `std::…`),
    // equally precise; no caller branches on it and binary output never
    // contains it.
    rustc_middle::ty::print::with_no_visible_paths!(scalar_leaf_trust_ir_fields_inner(tcx, ty))
        .map_err(move |e| {
            if bridge_notes_enabled() {
                format!("{e} [leaf site: {}:{}]", call_site.file(), call_site.line())
            } else {
                e
            }
        })
}

fn scalar_leaf_trust_ir_fields_inner<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Vec<TrustIrTy>, String> {
    if let Some(fields) = scalar_field_aggregate_trust_ir_fields(tcx, ty)? {
        return Ok(fields);
    }
    // A fat pointer (`&str` / `&[T]` / `&mut [T]`, `&dyn Trait`, or a reference
    // to any other unsized pointee such as a struct with a `[T]` / `str` TAIL)
    // is a 2-lane `{data,meta}` `ScalarPair`, not scalarizable to a single flat
    // SSA leaf — the caller's per-leaf projected-value binding model has no way
    // to carry two lanes under one flat index. This is a TRIGGER of this
    // function's existing fail-closed contract (it already errors on other
    // non-scalarizable nested shapes), closing a silent-truncation channel:
    // without this guard, `rust_ty_to_trust_ir_ty` below maps a fat pointer to a
    // plain `Ptr` (the SAME trust-ir type a thin reference gets) and
    // `is_pointer_like_trust_ir_ty` would accept it, silently binding only the
    // data half and dropping the metadata, and every LATER field of the
    // aggregate would then sit 8 bytes off — the miscompile class `3b9b89a8`
    // closed for the slice/`str` half of this model. A struct/tuple/closure
    // containing a fat leaf must instead be memory-backed (a real 2-lane slot),
    // never scalarized.
    //
    // Decided by LAYOUT (`is_wide_pointer_memory_leaf_ty` — is the pointee
    // `Sized`), not by pointee KIND. The kind test covered `&[T]` / `&str` only,
    // so a `&dyn Trait` leaf avoided single-lane binding purely because
    // `rust_ty_to_trust_ir_ty(&dyn ..)` happens to fail today, and a reference to
    // a custom DST (`&core::bstr::ByteStr`, `&core::ffi::CStr`) avoided it
    // the same way. Neither is an argument: the moment either acquires a
    // trust-ir mapping the guard must already be the layout one, or the first
    // such mapping silently reintroduces the miscompile. Refusing here is
    // fail-closed in both directions — a leaf this rejects has no correct
    // one-lane binding to lose.
    if is_wide_pointer_memory_leaf_ty(tcx, ty) {
        return Err(format!(
            "aggregate reference nested field is a fat pointer (ScalarPair {{data,meta}}), \
             not scalarizable: {ty:?}"
        ));
    }
    let field_ty = rust_ty_to_trust_ir_ty(tcx, ty)?;
    // Pointer-like nested field is a valid memory scalar (see closure-upvar fix).
    if field_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(&field_ty) {
        return Err(format!(
            "aggregate reference nested field is not memory-scalar: {field_ty:?}"
        ));
    }
    Ok(vec![field_ty])
}

fn reference_local_pointee_to_trust_ir_ty<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    local: Local,
) -> Result<Option<TrustIrTy>, String> {
    let base_ty = local_rust_ty(ctx, body, local);
    let ty::Ref(_, inner, _) = base_ty.kind() else {
        return Ok(None);
    };
    Ok(Some(reference_pointee_to_trust_ir_ty(
        ctx.tcx,
        ctx.monomorphize_ty(*inner),
    )?))
}

fn aggregate_memory_field_tys(ty: &TrustIrTy) -> Result<Vec<(u32, TrustIrTy)>, String> {
    match ty {
        // The array spelling of a uniform lane tuple -- see `memory_slot_lane_ty`.
        // Enumerated identically: lane `k` of `Array(l, n)` IS field `k` of
        // `Tuple([l; n])`, same type at the same offset.
        TrustIrTy::Array(elem, len) if *len > 0 => {
            let lane = slot_lane_ty_by_id(elem.index()).ok_or_else(|| {
                format!("aggregate array element TyId {elem:?} is not a slot lane")
            })?;
            let len = u32::try_from(*len)
                .map_err(|_| format!("aggregate array length {len} out of u32 range"))?;
            Ok((0..len).map(|field| (field, lane.clone())).collect())
        }
        TrustIrTy::Tuple(fields) if !fields.is_empty() => fields
            .iter()
            .enumerate()
            .map(|(field, field_ty)| {
                let field = u32::try_from(field)
                    .map_err(|_| format!("aggregate tuple field {field} out of u32 range"))?;
                Ok((field, field_ty.clone()))
            })
            .collect(),
        other => Err(format!(
            "aggregate reference memory type is unsupported: {other:?}"
        )),
    }
}

/// Re-word a `lower_union_adt_aggregate` refusal whose cause is a union FIELD
/// with no scalar trust-ir type (the bare `Ty::..` text), per design principle 10
/// / spec-surface v7/D3. TEXT ONLY: `Err` stays `Err`; any other refusal text is
/// returned unchanged.
///
/// Measured (frozen r3, `trace-ty=1`): `core::num::imp::flt2dec::{digits_to_dec_str,
/// digits_to_exp_str, to_shortest_str, to_exact_exp_str, to_exact_fixed_str}` at
/// -O3 refuse `_4 = MaybeUninit::<Part<'_>> { uninit: move _29 }` with
/// `Ty::num::imp::fmt::Part<'_>`: the union aggregate goes only through the scalar
/// carrier lane, and `Part` (`Zero(usize) | Num(u16) | Copy(&[u8])`) is a 24-byte
/// data-carrying enum with a fat payload. The refusal is correct — no lane holds
/// the value (the -O0 spelling is the memory union lane's "fat-pointer union fields
/// are not yet supported") — so only the text changes.
fn explain_union_aggregate_refusal<'tcx>(
    union_ty: Ty<'tcx>,
    active_ty: Ty<'tcx>,
    err: String,
) -> String {
    if !err.starts_with("Ty::") {
        return err;
    }
    rustc_middle::ty::print::with_no_visible_paths!(format!(
        "[TCG-UNION-AGGREGATE-NONSCALAR] constructing the union `{union_ty:?}` (active \
         field type `{active_ty:?}`) goes through the SCALAR-carrier union lane, which \
         needs one scalar trust-ir type shared by every non-zero-sized field; a field \
         has none ({err}). A union holding a data-carrying enum with a fat-pointer \
         payload (`MaybeUninit<core::num::imp::fmt::Part<'_>>` in flt2dec) has no \
         scalar carrier, and the memory union lane (`nonscalar_union_memory_layout`) \
         refuses fat-pointer fields too, so no lane can hold the value — failing closed \
         rather than truncating it. Ways forward: (a) backend: lower a NON-scalar union \
         aggregate into a memory slot laid out by rustc's union layout — an `uninit: \
         ()` construction writes nothing, a `value: ManuallyDrop(v)` construction \
         stores `v` at offset 0 with the memory-enum / two-lane fat-leaf writers — and \
         admit the two-lane fat leaf in `nonscalar_union_memory_layout`; (b) program: \
         avoid `MaybeUninit<E>` for such an enum (use an initialized `[E; N]`, or keep \
         the slice as `(ptr, len)` scalars); (c) build this crate with the LLVM backend \
         (omit `-Zcodegen-backend=trust-ir-cg`)."
    ))
}

fn scalar_union_abi_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    union_ty: Ty<'tcx>,
) -> Result<Option<ScalarUnionLayout>, String> {
    scalar_union_abi_layout_with_diagnostic(tcx, union_ty, "Ty::Adt union", true)
}

fn scalar_union_abi_layout_with_diagnostic<'tcx>(
    tcx: TyCtxt<'tcx>,
    union_ty: Ty<'tcx>,
    diagnostic_kind: &str,
    include_def_path: bool,
) -> Result<Option<ScalarUnionLayout>, String> {
    let ty::Adt(adt, args) = union_ty.kind() else {
        return Ok(None);
    };
    if !adt.is_union() {
        return Ok(None);
    }

    let fields = &adt.non_enum_variant().fields;
    let diagnostic_subject = if include_def_path {
        format!("{diagnostic_kind} {}", tcx.def_path_str(adt.did()))
    } else {
        diagnostic_kind.to_owned()
    };
    // Build the per-field trust-ir types, SKIPPING zero-sized fields. A ZST union
    // field (e.g. `MaybeUninit<T>`'s `uninit: ()`) occupies no storage, contributes
    // nothing to the union's shared scalar carrier, and has no cast to/from the ABI
    // scalar — so the carrier is the first NON-zero-sized field. A union of only ZST
    // fields has no scalar ABI. (A union with no ZST fields is unaffected — its
    // first field is still field 0.)
    let mut field_tys: Vec<(u32, TrustIrTy)> = Vec::with_capacity(fields.len());
    for (field, field_def) in fields.iter_enumerated() {
        let field_ty = field_def.ty(tcx, *args).skip_normalization();
        let field_is_zst = tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(field_ty))
            .map(|l| l.is_zst())
            .unwrap_or(false);
        if field_is_zst {
            continue;
        }
        // A WIDE (fat) member is TWO eightbytes; the carrier-coverage invariant
        // below is expressed in trust-ir bit widths, where a `Ptr` reports 64 (or
        // nothing), so it cannot see the second lane. Refuse by LAYOUT before a
        // carrier is chosen, rather than pick one that silently covers half the
        // member. (Unreachable for this family before it had a
        // `rust_ty_to_trust_ir_ty` mapping; stated rather than inherited.)
        if is_wide_pointer_memory_leaf_ty(tcx, field_ty) {
            return Err(format!(
                "{diagnostic_subject} field {} is a WIDE pointer (two eightbytes: data + \
                 metadata); no single scalar ABI carrier covers it",
                field.index()
            ));
        }
        let field_trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, field_ty)?;
        if matches!(field_trust_ir_ty, TrustIrTy::Never | TrustIrTy::Unit) {
            return Err(format!(
                "{diagnostic_subject} field {} has unsupported scalar ABI type {field_trust_ir_ty:?}",
                field.index()
            ));
        }
        field_tys.push((field.index() as u32, field_trust_ir_ty));
    }
    let Some((_, first_trust_ir_ty)) = field_tys.first().cloned() else {
        return Err(format!("{diagnostic_subject} has no non-zero-sized fields"));
    };

    let mut abi_ty = first_trust_ir_ty;
    if field_tys.iter().all(|(_, field_ty)| field_ty.is_integer()) {
        for (_, field_trust_ir_ty) in field_tys.iter().skip(1) {
            if field_trust_ir_ty.bit_width().unwrap_or(0) > abi_ty.bit_width().unwrap_or(0) {
                abi_ty = field_trust_ir_ty.clone();
            }
        }
    }

    // Carrier-coverage invariant, pinned LOCALLY rather than left to emerge from
    // union_projection_cast_op: the chosen ABI carrier must be at least as wide as
    // the WIDEST field, or reading a wider sibling would fabricate/lose high bits.
    // The all-integer branch above already guarantees this (widest wins); this also
    // pins it for the mixed-kind / float case, so a future loosening of
    // union_projection_cast_op (e.g. accepting an f64<->u64 or Ptr<->u64 pun) cannot
    // silently produce a too-narrow union carrier. (Pointer-like carriers cover 64.)
    let abi_bits = abi_ty.bit_width().unwrap_or(64);
    for (field, field_trust_ir_ty) in &field_tys {
        if field_trust_ir_ty.bit_width().unwrap_or(64) > abi_bits {
            return Err(format!(
                "{diagnostic_subject} field {field} type {field_trust_ir_ty:?} is wider than the \
                 chosen ABI carrier {abi_ty:?} — the carrier cannot hold it"
            ));
        }
        if union_projection_cast_op(&abi_ty, field_trust_ir_ty).is_none() {
            return Err(format!(
                "{diagnostic_subject} field {field} type {field_trust_ir_ty:?} differs from ABI type \
                 {abi_ty:?}"
            ));
        }
    }

    Ok(Some(ScalarUnionLayout { abi_ty, field_tys }))
}

fn uniform_scalar_union_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    union_ty: Ty<'tcx>,
) -> Result<Option<ScalarUnionLayout>, String> {
    let ty::Adt(adt, _) = union_ty.kind() else {
        return Ok(None);
    };
    if !adt.is_union() {
        return Ok(None);
    }

    let layout = scalar_union_abi_layout(tcx, union_ty)?;
    let Some(layout) = layout else {
        return Ok(None);
    };
    for (field, field_trust_ir_ty) in layout.field_tys.iter().skip(1) {
        if *field_trust_ir_ty != layout.abi_ty {
            return Err(format!(
                "Ty::Adt union {} field {} type {field_trust_ir_ty:?} differs from field {} type \
                 {:?}",
                tcx.def_path_str(adt.did()),
                field,
                0,
                layout.abi_ty
            ));
        }
    }

    Ok(Some(layout))
}

thread_local! {
    /// The set of `Ty` identities currently being resolved on the ACTIVE
    /// `rust_ty_to_trust_ir_ty` descent stack (keyed by the interned `TyKind`
    /// address, which is stable and unique per distinct type).
    ///
    /// The type-classification cluster (`rust_ty_to_trust_ir_ty` and its
    /// mutually-recursive helpers `aggregate_reference_pointee_to_trust_ir_ty` /
    /// `memory_aggregate_reference_pointee_lane_ty` / `memory_aggregate_layout` /
    /// `validate_memory_aggregate_field_leaves` / `memory_scalar_leaf_ty` / …)
    /// FOLLOWS A POINTER FIELD into its pointee to build the pointee trust-ir type
    /// (`*const S` -> `PtrConst(<pointee lane tuple>)`) so a `(*p).field` deref can be
    /// byte-addressed. For a SELF-REFERENTIAL type reached THROUGH raw pointers — the
    /// `BTreeMap` node graph, whose `struct LeafNode { parent: Option<NonNull<InternalNode>>, … }`
    /// and `struct InternalNode { data: LeafNode, edges: [NonNull<LeafNode>; …] }`
    /// point back into each other — this descent has no fixpoint and recurses until
    /// the stack overflows (a raw SIGBUS with NO diagnostic).
    ///
    /// Every back-edge in the type graph passes through `rust_ty_to_trust_ir_ty`
    /// (a pointer field's type is always resolved here, and the layout walker reaches
    /// a pointer leaf only via `memory_scalar_leaf_ty` -> `rust_ty_to_trust_ir_ty`),
    /// so tracking the active types HERE is sufficient to break EVERY cycle. Re-entry
    /// with a `Ty` already on the active stack is, by definition, an infinite cycle —
    /// a finite type never requires resolving itself in order to resolve itself — so
    /// this NEVER fires for a finite (acyclic) type and the finite-type path is
    /// unchanged. Entries are pushed on entry and popped by a `Drop` guard, so the set
    /// is empty at steady state.
    static TY_LOWER_ACTIVE: std::cell::RefCell<Vec<usize>> = const { std::cell::RefCell::new(Vec::new()) };
}

/// A pointer/reference type whose pointee cycles back into a type already being
/// resolved is fundamentally still a pointer-sized address; the bridge cannot,
/// however, build a finite trust-ir *pointee* type for it. Rather than crash
/// (SIGBUS via stack overflow), fail closed with a precise diagnostic. Soundness
/// over completeness: a cyclic aggregate (a B-tree/linked node) is rejected, never
/// miscompiled. `BTreeMap`/`HashMap`/`Vec`/`String` themselves stay COMPILABLE via
/// their dedicated intercepts (they map to a bare `Ptr` BEFORE any pointee descent).
#[track_caller]
fn rust_ty_to_trust_ir_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<TrustIrTy, String> {
    // DIAGNOSTIC ONLY (`bridge-notes`): which call site asked for this type's
    // single trust-ir mapping. A `Ty::…` refusal names the TYPE but not the
    // QUESTION, and the two have very different answers: the same
    // `Ty::Adt multi-field struct X` is a hard stop from a signature slot and a
    // recoverable probe from an aggregate-flattening descent (whose callers fall
    // back to the memory lane). The default message is byte-identical, so no
    // test or census reason key moves; `#[track_caller]` makes the location the
    // CALLER's, and it chains through this function's own recursion so a nested
    // descent reports the line that recursed.
    // Captured HERE, in the `#[track_caller]` function's OWN body: the implicit
    // caller location is not propagated into a nested closure, so reading it
    // inside one would report a line in this function (true, useless, and easy
    // to believe). Same trap `memory_scalar_leaf_ty::site` documents.
    let call_site = std::panic::Location::caller();
    let caller_site = move |err: String| -> String {
        if bridge_notes_enabled() {
            format!("{err} [ty site: {}:{}]", call_site.file(), call_site.line())
        } else {
            err
        }
    };
    // The interned `TyKind` address is a stable, collision-free identity for the
    // type (interning guarantees one allocation per distinct type), with no lifetime
    // to thread and no `unsafe`.
    let ty_key = ty.kind() as *const ty::TyKind<'tcx> as usize;
    let entered = TY_LOWER_ACTIVE.with(|active| {
        let mut active = active.borrow_mut();
        if active.contains(&ty_key) {
            false
        } else {
            active.push(ty_key);
            true
        }
    });
    if !entered {
        if crate::knobs::is_enabled(crate::knobs::TYCYCLE_TRACE) {
            eprintln!("[TCG-TYPE-CYCLE] re-entry on Ty::{ty:?}");
        }
        return Err(format!(
            "[TCG-TYPE-CYCLE] self-referential type `{ty:?}` recurses through a cyclic \
             pointer graph (a field points back into the same type, e.g. a B-tree / \
             linked node); the bridge cannot build a finite pointee layout for it — \
             failing closed"
        ));
    }
    // Pop THIS entry on EVERY exit path (including the `?`/`return Err(..)` early
    // returns inside the body). LIFO: nested calls push+pop their own key first, so
    // our key is the top when this guard drops.
    struct PopActiveTy(usize);
    impl Drop for PopActiveTy {
        fn drop(&mut self) {
            TY_LOWER_ACTIVE.with(|active| {
                let mut active = active.borrow_mut();
                debug_assert_eq!(active.last().copied(), Some(self.0));
                active.pop();
            });
        }
    }
    let _pop = PopActiveTy(ty_key);
    // `with_no_visible_paths!`: the error strings this family builds embed
    // `{ty:?}` renderings, and for `dyn Trait`-bearing types the Debug impl
    // walks rustc's visible-def-path printer, whose first use computes
    // `visible_parent_map` (399 `module_children` metadata decodes, ~4 ms —
    // gdb-pinned: `try_print_visible_def_path_recur` reached from this
    // function via `compute_memory_backed_locals` on every real compile).
    // Many callers use the Result as a pure lowerability CLASSIFIER and
    // discard the string, so the rendering must be cheap; the strings that do
    // surface are fail-closed compile diagnostics where the crate-local path
    // (`alloc::boxed::Box` vs `std::boxed::Box`) is equally precise. Binary
    // output never contains these strings.
    //
    // A POINTER / REFERENCE refusal is re-worded by `explain_pointer_type_refusal`
    // (text only: `Err` stays `Err`) so the surfaced diagnostic names the rule that
    // was broken rather than the innermost type the descent happened to stop at.
    // `caller_site` then appends the `bridge-notes` call-site tag to whatever text
    // that produced — OUTSIDE the re-wording, so the re-wording still sees the
    // descent's own string (it branches on its `[`/`Ty::` prefix) and the site note
    // stays last in the surfaced message. Both are text-only: `Err` stays `Err` and
    // `Ok` is untouched by either.
    rustc_middle::ty::print::with_no_visible_paths!(
        rust_ty_to_trust_ir_ty_inner(tcx, ty)
            .map_err(|err| explain_pointer_type_refusal(tcx, ty, err))
    )
    .map_err(caller_site)
}

/// Marker of the generic pointee note appended by `explain_pointer_type_refusal`;
/// its presence stops an enclosing pointer level from appending it again.
const POINTEE_LANES_REFUSAL_TAG: &str = "[TCG-POINTEE-LANES]";

/// Re-word the refusal of a POINTER / REFERENCE type that
/// `rust_ty_to_trust_ir_ty_inner` could not type, so the diagnostic that surfaces
/// names the rule actually broken and enumerates the ways forward (design
/// principle 10, spec-surface v7/D3). TEXT ONLY: an `Err` maps to an `Err`, no
/// acceptance changes, and no caller branches on these strings.
///
/// Why: on the round-3 checkpoint-A census of `library/std` through trust-ir-cg the
/// bare `Ty::..` texts named the wrong thing, measured on the frozen r3 compiler
/// with `trace-ty=1`:
///
/// * `Ty::[u8]` (`Rc<[u8]>`/`Arc<[u8]>::{allocate_for_slice, copy_from_slice}`,
///   `Wtf8::into_rc`/`into_arc`) and `Ty::Adt multi-field struct IndexRange`
///   (`array::iter::iter_inner::PolymorphicIter<[MaybeUninit<char>]>::next`): the
///   value is `*mut RcInner<[u8]>` / `&mut PolymorphicIter<[..]>`, a FAT pointer to
///   a struct with an unsized slice TAIL. Also `*const Cell<[u8]>` in miniz_oxide's
///   `apply_match` (`Cell::as_slice_of_cells`), a GENERIC transparent wrapper.
/// * `Ty::dyn Debug` (`slice::Iter<&dyn Debug>::{next, size_hint}`,
///   `Formatter::debug_tuple_fields_finish`): `*const &dyn Debug`, a raw pointer
///   whose POINTEE is a `{data, vtable}` pointer.
/// * `Ty::Option<NonNull<InternalNode<u64, Abbreviation>>>` (B-tree `search_node`,
///   `descend` over gimli's abbreviation map): the FIRST field the flat attempt met
///   in `*mut LeafNode<..>`; the real blocker is the value type, which owns a `Vec`
///   inside a data-carrying enum — the same node methods compile for a scalar-leaf
///   value (`BTreeMap<u64, Small>`). `Ty::Attributes` (`&mut Attributes`) likewise.
///
/// Cost: only the `Err` path of a `Ref`/`RawPtr` type runs this. The unsized-tail
/// diagnosis renders types (a rare shape); the other two append static text to the
/// existing string and render nothing, because this function also serves as a hot
/// lowerability classifier whose error string is usually discarded.
fn explain_pointer_type_refusal<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, err: String) -> String {
    let pointee = match ty.kind() {
        ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _) => *pointee,
        _ => return err,
    };
    // An already-explained refusal — a nested pointer level, or a tagged diagnostic
    // such as `[TCG-TYPE-CYCLE]` — is the most precise text available: keep it.
    if err.starts_with('[') || err.contains(POINTEE_LANES_REFUSAL_TAG) {
        return err;
    }
    if let ty::Adt(adt, _) = pointee.kind() {
        if adt.is_struct() && !pointee.is_sized(tcx, ty::TypingEnv::fully_monomorphized()) {
            let tail = unsized_struct_tail_for_diagnostic(tcx, pointee);
            return format!(
                "[TCG-POINTEE-UNSIZED-TAIL] `{ty:?}` is a FAT pointer {{data, metadata}} to \
                 `{pointee:?}`, a struct whose last field is the unsized `{tail:?}`. \
                 This pointer shape has no admitted two-lane representation here. \
                 Admitted slice/str tails use length metadata; unpacked trait-object \
                 struct tails use vtable metadata and runtime alignment. This layout \
                 falls outside those checked families. Treating it as a thin pointer would lose \
                 metadata read by `size_of_val` and tail reborrows. Pass the sized \
                 header and tail separately, or use the LLVM backend until this \
                 shape is supported. (descent stopped at: {err})"
            );
        }
    }
    if matches!(pointee.kind(), ty::Dynamic(..)) {
        return format!(
            "[TCG-POINTEE-DYN-VALUE] a trait-object pointer (`&dyn Trait` / `*const dyn \
             Trait`: two words, {{data, vtable}}) was asked for ONE trust-ir value type, \
             which it does not have ({err}). The bridge carries it as two lanes wherever \
             it knows it holds two — call arguments and entry params \
             (`is_vtable_pair_abi_ref_ty`), memory leaves \
             (`is_fat_pointer_memory_leaf_ty`), a `&&dyn Trait` / `*const &dyn Trait` / \
             `NonNull<&dyn Trait>` POINTEE (`dyn_reference_pointee_slot_ty` and the \
             `RawPtr` arm's `fat_ptr_slot_ty()`), a fat -> thin narrowing cast \
             (`lower_dyn_fat_to_thin_ptr_cast`) and its fat -> fat twin \
             (`lower_dyn_fat_to_fat_ptr_cast`), a fat <-> fat `Transmute` \
             (`try_recover_dyn_fat_ptr_place`, and through a thin reference \
             `lower_deref_field_dyn_fat_ptr_transmute`), an ADT `Unsize` into a \
             slot (`adt_pointer_unsize_plan`) — but a site that needs the WHOLE \
             two-lane value to have a single trust-ir type has no answer, and a \
             one-word type would drop the vtable, so this fails closed. \
             \
             Rerun with `-Ztrust-ir-cg-args=bridge-notes` to get the `[ty site: \
             lib.rs:LINE]` of the caller that asked — that line, not this type, is what \
             has to change. (The two `library/alloc` roots measured here on 2026-09-26 \
             — `Box<dyn Error + Sync + Send>`'s drop glue and its `Drop::drop` — were \
             cleared by giving each of their `*mut dyn` statements a two-lane lowering \
             and `size_of_val`/`align_of_val` a vtable read, pinned under a heap check by \
             `dyn_fat_leaf_differential`'s `box_dyn_drop_heap_layout`.) Typing the value \
             as one `Ptr` instead would be the silent-metadata-truncation class \
             (`3b9b89a8`). Ways forward: (a) backend: give the asking statement its own \
             two-lane lowering through the shared readers above and pin it \
             differentially against LLVM — a dropped vtable lane shows up as a wrong \
             `size_of_val` in a deallocation, which corrupts the allocator rather than \
             printing a wrong number, so the fixture must run under a heap check; (b) \
             program: avoid a bare `*mut dyn Trait` value \
             on this path — keep the trait object behind a `&dyn` / `Box<dyn>` whose two \
             lanes the bridge already tracks, or dispatch through a concrete type or an \
             enum; (c) build this crate with the LLVM backend (omit \
             `-Zcodegen-backend=trust-ir-cg`)."
        );
    }
    if err.starts_with("Ty::") {
        return format!(
            "{err} {tag} (raised while typing a pointer/reference \
             POINTEE: the flat scalar-field, memory-enum, byte-offset struct/tuple and union \
             pointee lanes all declined it, and the type named first is only where the \
             FLAT attempt stopped — often the pointee's first non-scalar field — not \
             necessarily what the byte-offset lane rejected. Measured: `*mut LeafNode<u64, \
             gimli::read::abbrev::Abbreviation>` names its `parent: \
             Option<NonNull<InternalNode<..>>>` field, while the blocker is the value type \
             owning a `Vec` inside a data-carrying enum; the same B-tree node methods \
             compile for a scalar-leaf value. Rerun with `-Ztrust-ir-cg-args=trace-ty=1` \
             for the descent. Ways forward: (a) backend: make the rejecting leaf \
             memory-addressable in `memory_aggregate_layout` — an owned `Vec`/`String` \
             leaf, or a multi-variant enum whose payload holds one, are the common \
             blockers (an OVER-ALIGNED struct pointee — align 32 / 64 — is typed as a \
             16-byte-lane shell for address-preserving casts only; an `f16` / `f128` \
             element has no trust-ir value mapping); (b) program: move such a field \
             behind a `Box` or an index so the pointee is scalar-leaf; (c) build this \
             crate with the LLVM backend.)",
            tag = POINTEE_LANES_REFUSAL_TAG
        );
    }
    err
}

/// The unsized TAIL of an unsized struct, for diagnostics only: follows the last
/// field through nested structs (`Cell<[u8]>` -> `UnsafeCell<[u8]>` -> `[u8]`,
/// `RcInner<[u8]>` -> `[u8]`). Bounded; stops at the first non-struct.
fn unsized_struct_tail_for_diagnostic<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Ty<'tcx> {
    let mut cur = ty;
    for _ in 0..16 {
        let ty::Adt(adt, args) = cur.kind() else {
            break;
        };
        if !adt.is_struct() {
            break;
        }
        let Some(last) = adt.non_enum_variant().fields.iter().last() else {
            break;
        };
        cur = last.ty(tcx, *args).skip_normalization();
    }
    cur
}

fn rust_ty_to_trust_ir_ty_inner<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<TrustIrTy, String> {
    Ok(match ty.kind() {
        ty::Bool => TrustIrTy::Bool,
        ty::Char => TrustIrTy::U32,
        ty::Float(ty::FloatTy::F32) => TrustIrTy::F32,
        ty::Float(ty::FloatTy::F64) => TrustIrTy::F64,
        ty::Float(float_ty) => return Err(format!("Ty::Float({float_ty:?})")),
        ty::Int(int_ty) => match int_ty.bit_width() {
            Some(8) => TrustIrTy::I8,
            Some(16) => TrustIrTy::I16,
            Some(32) => TrustIrTy::I32,
            Some(64) => TrustIrTy::I64,
            Some(128) => TrustIrTy::I128,
            None => pointer_sized_trust_ir_ty(tcx, true),
            Some(width) => return Err(format!("Ty::Int({width})")),
        },
        ty::Uint(uint_ty) => match uint_ty.bit_width() {
            Some(8) => TrustIrTy::U8,
            Some(16) => TrustIrTy::U16,
            Some(32) => TrustIrTy::U32,
            Some(64) => TrustIrTy::U64,
            Some(128) => TrustIrTy::U128,
            None => pointer_sized_trust_ir_ty(tcx, false),
            Some(width) => return Err(format!("Ty::Uint({width})")),
        },
        ty::Never => TrustIrTy::Never,
        ty::Tuple(fields) if fields.is_empty() => TrustIrTy::Unit,
        // A tuple of zero-sized fields has no ABI bits, even when it is the
        // nonempty argument tuple of a generic Fn* call. Keep its field types
        // in MIR for projections and drop glue; only its value carrier is Unit.
        ty::Tuple(..)
            if tcx.sess.target.arch.desc() == "aarch64"
                && tcx.sess.target.os == rustc_target::spec::Os::Linux
                && is_zero_sized_ty(tcx, ty) =>
        {
            TrustIrTy::Unit
        }
        // A ZERO-LENGTH array `[T; 0]` is a ZST exactly like `()` / a field-less
        // struct (the `None => TrustIrTy::Unit` of the ADT arm below): it has no
        // element to read or write, occupies no bytes, and takes no ABI slot. Map
        // it to `Unit` so a `fn f() -> [u8; 0]` return / a `&[u8; 0]` pointee /
        // an `[T; 0]` field types like any other ZST (`std::slice::Iter::default`,
        // `<[u8; 0] as AsRef<[u8]>>::as_ref`, `ByteStr::new::<[u8; 0]>` in
        // `core`). Its unsize to `&[T]` keeps its length from rustc's own const
        // (`pointer_metadata_len_from_operand`), never from this mapping. The
        // length must be target-usize EVALUABLE and exactly 0: a generic /
        // unevaluated length falls through to the fail-closed arm as before.
        ty::Array(_, len) if len.try_to_target_usize(tcx) == Some(0) => TrustIrTy::Unit,
        // Nonempty arrays of ZST elements also carry no ABI bits. Preserve
        // their actual length in projection/metadata lowering; Unit describes
        // only the storage. This includes uninhabited [Never; N > 0].
        ty::Array(..) if is_zero_sized_ty(tcx, ty) => TrustIrTy::Unit,
        ty::FnPtr(..) => TrustIrTy::Ptr,
        // A function ITEM type (`fn(..) {name}` — `ty::FnDef`) is a ZERO-SIZED
        // value: the callee it names is fixed by the TYPE alone (def-id + generic
        // args), so the value carries no bits and nothing is ever read out of it.
        // A local / by-value param / closure upvar of this type therefore occupies
        // no bytes and no ABI slot, exactly like `()` — which is what lets a
        // function item be PASSED as the `F` of a generic combinator
        // (`opt.map(IpAddr::V4)`, `apply(twice, x)`) rather than failing the whole
        // caller closed on `Ty::FnDef(..)`. Every USE of such a value is resolved
        // from the type, never from the (empty) value: a call through it is a
        // DIRECT call of the statically-resolved instance
        // (`direct_callee_instance` accepts a `FnDef`-typed place operand — the
        // `self(args…)` of rustc's `FnPtrShim` `call*` bodies over a fn item), and a
        // `ReifyFnPointer` cast of it takes the resolved symbol's address
        // (`lower_cast` reads the SOURCE TYPE). Sound by rustc's own layout: a
        // `FnDef` is `size == 0` with `Variants::Single`; a fn POINTER (`ty::FnPtr`,
        // which does carry an address) is a different `TyKind` and keeps its `Ptr`
        // arm above.
        ty::FnDef(..) => TrustIrTy::Unit,
        // A reference / raw pointer to a SLICE or `str` is a *fat* pointer
        // `{ data, len }`. The bridge models the value as its DATA-pointer half (a
        // single `Ptr` scalar) and tracks the length separately in
        // `pointer_metadata_lengths` — the same split the existing slice
        // machinery (`Rvalue::Ref` of an array / `PointerCoercion::Unsize` /
        // `UnOp::PtrMetadata`) already maintains. Mapping the TYPE to `Ptr` lets a
        // `&str` / `&[T]` const-data reference be typed and bound as a pointer
        // scalar (its `data` is a `SymbolAddr` global), with the length in the
        // side table. Indexing through such a slice is still only supported for
        // the constant-index / known-length shapes the slice machinery models.
        //
        // Decided by the SAME predicate every fat-pointer consumer uses
        // (`is_slice_reference_ty`), never by a local `inner.kind()` test, so a
        // `#[repr(transparent)]` unsized wrapper (`&CStr`, `&Path`) is a fat
        // pointer HERE exactly when it is one everywhere else — the type mapper
        // and the `{ data, len }` machinery cannot disagree about it. (Before
        // this, `&CStr` fell through to the thin-reference arm below, whose
        // pointee flattening met the unsized tail and refused with `Ty::[i8]`.)
        ty::Ref(..) | ty::RawPtr(..) if is_slice_reference_ty(ty) => TrustIrTy::Ptr,
        // A reference / raw pointer to a DST STRUCT / TUPLE whose unsized TAIL is
        // a `[T]` / `str` (`&core::bstr::ByteStr`, `&core::ffi::CStr`,
        // `&core::wtf8::Wtf8`, `&PolymorphicIter<[MaybeUninit<char>]>`). rustc lays
        // this out as the IDENTICAL `{ data, len }` `ScalarPair` the arm above
        // describes — the metadata is the TAIL's element count — so it takes the
        // identical representation: the DATA-pointer half as the trust-ir value,
        // with the length in the `{ data, len }` slot every such local is
        // memory-backed by (`memory_backed_local_layout`), or in the
        // `pointer_metadata_lengths` side table for a compile-time length.
        //
        // Before this arm the whole family had NO mapping at all and failed closed
        // (46 `library/core` roots, measured), so nothing that compiles today is
        // re-typed. A `dyn`-tailed DST (`core::error::Request`) is NOT admitted —
        // its metadata is a vtable — and keeps its own refusal.
        ty::Ref(_, inner, _) | ty::RawPtr(inner, _)
            if slice_tail_dst_pointee(tcx, *inner).is_some() =>
        {
            TrustIrTy::Ptr
        }
        ty::RawPtr(inner, mutability) => {
            // The pointee mapping. We try the DIRECT mapping FIRST so every pointee
            // the prior code already handled (a scalar, a single-scalar-leaf newtype,
            // a `Vec`-as-`Ptr`, …) keeps its EXACT prior trust-ir type — this change
            // is purely additive and steals no working case. ONLY when the direct
            // mapping fails (a multi-field struct / tuple / array pointee, which the
            // old code rejected outright) do we fall back to flattening the pointee
            // to its scalar-leaf tuple, exactly as `&S` does
            // (`reference_pointee_to_trust_ir_ty`). This is what lets a
            // `Box<Aggregate>` value — whose payload readback transmutes the box's
            // `NonNull<S>` to `*const S` and reads `(*p).field` — be typed; the leaf
            // reads/writes through it are addressed by rustc-exact byte offsets
            // (`memory_aggregate_ref_*`). If the scalar-leaf flattening ALSO cannot
            // represent the pointee (a NESTED struct / struct-with-array field — it
            // descends into an aggregate field and fails), fall back a final step to
            // the flat memory-aggregate slot lane tuple, so a `(*p).field…` / `(*p)[i]`
            // deref is byte-addressed at rustc layout offsets exactly as the `&S` thin
            // pointer is (`memory_aggregate_reference_pointee_lane_ty`). A pointee none
            // of these can represent (a fat / unsized pointee) still surfaces the
            // direct mapping's precise error (fail closed).
            let inner = *inner;
            // A `&dyn Trait` POINTEE behind the raw pointer — `*const &dyn Debug`,
            // `*mut &dyn Debug`, `NonNull<&dyn Debug>` (through the `ty::Pat`
            // arm): the element cursor of `slice::Iter<'_, &dyn Trait>` walking a
            // `&[&dyn Trait]`, as `Formatter::debug_tuple_fields_finish` does
            // (16 `library/core` roots). Answered FIRST, with the SAME two-lane
            // image `reference_pointee_to_trust_ir_ty` gives `&&dyn`
            // (`dyn_reference_pointee_slot_ty`): the direct mapping below has no
            // arm for it (a `&dyn` has no single scalar type) and every fallback
            // declines a non-aggregate pointee, so this pointee used to surface
            // the `[TCG-POINTEE-DYN-VALUE]` refusal. The pointer stays THIN; the
            // tuple is only its ABI shell. A `*const dyn Trait` — the FAT pointer
            // VALUE itself — is not this shape and keeps failing closed.
            let pointee = match dyn_reference_pointee_slot_ty(inner)
                .or_else(|| f16_pointee_shell_lane_ty(tcx, inner))
                .ok_or(())
                .or_else(|()| rust_ty_to_trust_ir_ty(tcx, inner))
            {
                Ok(pointee) => pointee,
                Err(direct_err) => match aggregate_reference_pointee_to_trust_ir_ty(tcx, inner) {
                    Ok(Some(aggregate)) => aggregate,
                    Ok(None) | Err(_) => {
                        // A `*const E` / `*mut E` to a MULTI-VARIANT memory-eligible
                        // enum (`*const Option<i64>` / the slice iterator's
                        // `NonNull<Option<i64>>` internals): type the pointee as the
                        // enum's slot lane tuple, exactly as the `&E` reference chain
                        // does (`reference_pointee_to_trust_ir_ty`). Every access
                        // through it uses the real enum layout (tag decode + payload
                        // offsets), never this tuple.
                        if let Some(lane_tuple) = memory_enum_reference_pointee_lane_ty(tcx, inner)?
                        {
                            lane_tuple
                        } else {
                            match memory_aggregate_reference_pointee_lane_ty(tcx, inner)? {
                                Some(lane_tuple) => lane_tuple,
                                // A `*const U` / `*mut U` to a NON-scalar (aggregate) union
                                // (`*mut MaybeUninit<(i64,i64)>` — the `&raw mut (*self)`
                                // inside `as_mut_ptr`, and the `self as *mut T` cast's source):
                                // type the pointee as the union's slot lane tuple, exactly as
                                // the reference (`&U`) case does. Every access through it uses
                                // the real union layout, never this tuple.
                                None => match nonscalar_union_memory_layout(tcx, inner)? {
                                    Some(layout) => layout.slot_ty,
                                    // A `*const/*mut (&dyn Trait)` — the pointee is
                                    // ITSELF a `{data, vtable}` fat pointer, a fixed
                                    // 16-byte / 8-aligned two-lane image. This is the
                                    // SAME answer `reference_pointee_to_trust_ir_ty`
                                    // already gives the `&&dyn Trait` pointee; the raw-
                                    // pointer arm simply never asked. No metadata is
                                    // dropped: every access reads/writes both lanes at
                                    // `fat_ptr_metadata_offset`, and `BinOp::Offset`
                                    // strides by `layout_size_of` (16), not by this type.
                                    None if is_trait_object_reference_ty(inner) => {
                                        fat_ptr_slot_ty()
                                    }
                                    None => return Err(direct_err),
                                },
                            }
                        }
                    }
                },
            };
            match mutability {
                rustc_hir::Mutability::Not => TrustIrTy::PtrConst(Box::new(pointee)),
                rustc_hir::Mutability::Mut => TrustIrTy::PtrMut(Box::new(pointee)),
            }
        }
        ty::Ref(_, inner, mutability) => match mutability {
            rustc_hir::Mutability::Not => {
                TrustIrTy::Ref(Box::new(reference_pointee_to_trust_ir_ty(tcx, *inner)?))
            }
            rustc_hir::Mutability::Mut => {
                TrustIrTy::RefMut(Box::new(reference_pointee_to_trust_ir_ty(tcx, *inner)?))
            }
        },
        // A zero-sized union has no ABI bits, including inhabited unions such
        // as MaybeUninit<Never>. Use rustc's whole layout, not the validity of
        // any individual field: a union may be inhabited even when one of its
        // fields is not. Nonzero unions retain their scalar/aggregate checks.
        ty::Adt(adt, _) if adt.is_union() && is_zero_sized_ty(tcx, ty) => TrustIrTy::Unit,
        ty::Adt(adt, _) if adt.is_union() => {
            let layout = scalar_union_abi_layout(tcx, ty)?
                .ok_or_else(|| format!("Ty::Adt union {}", tcx.def_path_str(adt.did())))?;
            layout.abi_ty
        }
        // A closure value is, at the layout level, an anonymous struct of its
        // captured upvars. Map it to the aggregate tuple of upvar types so a
        // closure local / a `&closure` reference can be typed and scalarized like
        // any struct. The closure body fn reads captures through `(*env).N`.
        ty::Closure(_, args) => {
            let upvars: Vec<Ty<'tcx>> = args.as_closure().upvar_tys().iter().collect();
            if upvars.is_empty() {
                TrustIrTy::Unit
            } else {
                // A WIDE (fat) upvar — `&[T]`, `&str`, `&dyn Trait`, or a
                // reference to a `[T]`/`str`-tailed DST — occupies TWO lanes and
                // must not be bound into one. Such a closure is memory-backed
                // instead (`closure_memory_layout`, whose leaf validation admits a
                // fat upvar as two lanes). Refused HERE by layout rather than left
                // to the width check below, which accepts any pointer-like type:
                // before `&ByteStr` &co. had a `rust_ty_to_trust_ir_ty` mapping
                // this could not arise, and the moment they did the check would
                // have silently taken the data half alone.
                for upvar_ty in &upvars {
                    if is_wide_pointer_memory_leaf_ty(tcx, *upvar_ty) {
                        return Err(format!(
                            "closure upvar `{upvar_ty:?}` is a WIDE pointer (two lanes: data \
                             + metadata); a one-lane-per-upvar closure tuple would drop its \
                             metadata and place every later upvar at the wrong byte offset. \
                             Options: (1) the closure is typed from its rustc memory layout \
                             instead (automatic — see `closure_memory_layout`), (2) capture \
                             the data pointer and the length/vtable separately"
                        ));
                    }
                }
                let fields = upvars
                    .iter()
                    .map(|upvar_ty| rust_ty_to_trust_ir_ty(tcx, *upvar_ty))
                    .collect::<Result<Vec<_>, _>>()?;
                for (field, field_ty) in fields.iter().enumerate() {
                    // A zero-sized upvar (`Unit` / a captured fn-item or `PhantomData`,
                    // e.g. the phantom capture of a non-capturing `|x| ..` map/filter
                    // closure) carries no data. Keep it in the tuple so upvar field
                    // INDICES are preserved (the body reads `(*env).N` by index), but
                    // don't require it to be a memory scalar — nothing is ever read out
                    // of a ZST capture.
                    if trust_ir_ty_is_zero_sized(field_ty) {
                        continue;
                    }
                    if field_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(field_ty) {
                        return Err(format!(
                            "closure upvar {field} is not memory-scalar: {field_ty:?}"
                        ));
                    }
                }
                // A SINGLE-UPVAR closure IS its upvar, and must map like one.
                //
                // The arm above treats a closure as an anonymous struct of its
                // upvars — but the STRUCT arm collapses a single-scalar-leaf
                // aggregate to that leaf (`Some(fields) if fields.len() == 1`),
                // and this one did not. The asymmetry is observable: a
                // `struct FromFn<F>(F)` wrapping a one-upvar closure maps to the
                // upvar's scalar (the struct arm flattens THROUGH the closure via
                // `scalar_leaf_trust_ir_fields`), while the closure itself maps to
                // `Tuple([<that same scalar>])`, which `memory_scalar_leaf_ty`
                // rejects — so every place-address walk that bottoms out at the
                // closure field failed closed with "memory leaf type is not a
                // scalar: Tuple([Ref(I32)])". Measured on `library/core` as three
                // roots, all `fmt::builders::from_fn::<closure>` instantiations.
                //
                // SOUNDNESS is rustc's own layout, not an inference from the upvar
                // count: the collapse requires the closure to have exactly ONE
                // upvar, that upvar to sit at offset 0, and the closure's total
                // SIZE to equal the leaf's byte size — i.e. the closure occupies
                // exactly the upvar's bytes and nothing else. A capture list with
                // padding, alignment slack, or more than one upvar keeps the tuple
                // (and with it the `(*env).N` index scheme the body reads through).
                if fields.len() == 1 {
                    if let Some(leaf_size) = fields[0].bit_width().map(|w| u64::from(w) / 8).or(
                        if is_pointer_like_trust_ir_ty(&fields[0]) {
                            Some(8)
                        } else {
                            None
                        },
                    ) {
                        let layout = tcx
                            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
                            .map_err(|e| format!("Ty::Closure layout_of({ty:?}) failed: {e:?}"))?;
                        if layout.size.bytes() == leaf_size
                            && layout.fields.count() == 1
                            && layout.fields.offset(0).bytes() == 0
                        {
                            return Ok(fields.into_iter().next().unwrap());
                        }
                    }
                }
                TrustIrTy::Tuple(fields)
            }
        }
        // `Vec<T, Global>` for a scalar element `T` is INTERCEPTED by the bridge:
        // a `Vec` local is given a real 3-word `{ ptr, cap, len }` stack slot and
        // its methods (`new`/`with_capacity`/`push`/`len`/index/`Drop`) are
        // synthesized directly against `__rust_alloc`/`__rust_realloc`/
        // `__rust_dealloc`. At the trust-ir type level the `Vec` value is exactly
        // the *address* of that slot — a single `Ptr` scalar — so the local types,
        // passes, and flows like any pointer (and a `&Vec`/`&mut Vec` is the same
        // slot address). This is checked BEFORE the generic multi-field-struct
        // path so the `Vec`/`RawVec` aggregate is never scalarized field-wise.
        ty::Adt(..) if vec_element_ty(tcx, ty).is_some() => TrustIrTy::Ptr,
        // `BTreeMap<K, V>` for integer `K`/`V` is INTERCEPTED exactly like `Vec`:
        // the map value is the *address* of a `{ ptr, cap, len }` slot — a single
        // `Ptr` scalar — so it (and every `&BTreeMap`/`&mut BTreeMap`) flows like a
        // pointer. Checked before the generic struct path so the B-tree aggregate
        // is never scalarized field-wise.
        ty::Adt(..) if btreemap_kv_ty(tcx, ty).is_some() => TrustIrTy::Ptr,
        // `HashMap<K, V>` for integer `K`/`V` is INTERCEPTED exactly like
        // `BTreeMap`: the map value is the *address* of a `{ ptr, cap, len }` slot
        // — a single `Ptr` scalar — and shares the same flat entry backing store.
        // This covers both the public `std::collections::HashMap` and (at `-O3`)
        // the inner `hashbrown::map::HashMap`, whose `&mut self` is a projection of
        // the outer map local. Checked before the generic struct path.
        ty::Adt(..) if any_hashmap_kv_ty(tcx, ty).is_some() => TrustIrTy::Ptr,
        // The dead INTERNAL types of an inlined `HashMap::new()` chain
        // (`RawTable` / `RawTableInner` / `RandomState`) feed only the intercepted
        // outer `HashMap { base }` aggregate, which synthesizes its slot fresh and
        // never reads them. Map each to a single `Ptr` scalar so their (no-op'd)
        // construction flows like one dead pointer rather than a flattened struct.
        ty::Adt(..) if is_hashmap_dead_internal_ty(tcx, ty) => TrustIrTy::Ptr,
        // `String` is INTERCEPTED exactly like `Vec<u8>`: a `String` local is a
        // 3-word `{ ptr, cap, len }` stack slot and its value is the *address* of
        // that slot — a single `Ptr` scalar. The `format!`/`write!` machinery
        // synthesizes the formatted bytes into that slot; `String::len`/`as_str`/
        // `Drop` read/free it. Checked before the generic struct path so the
        // `String`/`Vec<u8>`/`RawVec` aggregate is never scalarized field-wise.
        ty::Adt(..) if is_string_ty(tcx, ty) => TrustIrTy::Ptr,
        // A single-field newtype struct / single-variant enum whose only leaf is
        // a scalar (e.g. `std::process::ExitCode`, which is
        // `ExitCode(imp::ExitCode(u8))`) has the memory representation of that one
        // scalar. Map it to the leaf type so such a value can be returned /
        // passed / projected as a scalar. Multi-field structs stay aggregate and
        // are handled by the scalarized-aggregate machinery, so we do not map
        // them here.
        // A ZERO-SIZED ENUM, decided by rustc's OWN layout (`size == 0`), never by
        // inspecting variants: `convert::Infallible` (`Variants::Empty`, no variant
        // at all), the `?`-residuals `Option<Infallible>` / `Result<Infallible, ()>`
        // / `Result<Infallible, Infallible>` (a `Variants::Single` layout whose one
        // inhabited variant has no payload bytes), and
        // `ControlFlow<NeverShortCircuitResidual, Infallible>` (every variant
        // uninhabited). Such a value carries no bits, so — exactly like `()` — it
        // occupies no ABI slot and nothing is ever read out of it. Its DISCRIMINANT,
        // where rustc still emits a `discriminant(x)` over it, is STATIC and comes
        // from the layout's `Variants::Single { index }` (`lower_discriminant`'s
        // bare-enum-local arm), never from this type. An enum with payload bytes,
        // even one whose OTHER variants are uninhabited (`Result<Infallible,
        // ParseIntError>`), has `size != 0` and does NOT match here; it keeps its
        // memory-backed enum path. Placed BEFORE the single-variant-enum flattening
        // arm below so a ZST `Result<Infallible, E>` never descends into its
        // uninhabited variant's fields.
        ty::Adt(adt, _) if adt.is_enum() && !adt.is_union() && is_zero_sized_ty(tcx, ty) => {
            TrustIrTy::Unit
        }
        ty::Adt(adt, _)
            if (adt.is_struct()
                || (adt.is_enum()
                    && adt.variants().len() == 1
                    && !single_variant_enum_keeps_tag(tcx, ty)))
                && !adt.is_union() =>
        {
            match scalar_field_aggregate_trust_ir_fields(tcx, ty)? {
                Some(fields) if fields.len() == 1 => fields.into_iter().next().unwrap(),
                // A struct whose fields are ALL zero-sized (`PhantomCovariantLifetime
                // (PhantomData<..>)`, `TryFromCharError(())`, `FromBytesUntilNulError
                // (())`) flattens to ZERO leaves — the same representation as the
                // field-less case below — and is a ZST exactly like it. It used to
                // land in the `Some(_)` "multi-field" refusal by having a field list
                // at all. Only a type whose LAYOUT is zero-sized is admitted here: a
                // `#[repr(align(N))]` wrapper of ZSTs has zero leaves but a nonzero
                // size, and keeps failing closed rather than being modeled as unit.
                Some(fields) if fields.is_empty() && is_zero_sized_ty(tcx, ty) => TrustIrTy::Unit,
                Some(_) => return Err(format!("Ty::Adt multi-field struct {ty:?}")),
                // A field-less struct / single-variant enum is a ZST -> unit.
                None => TrustIrTy::Unit,
            }
        }
        // A *pattern type* (`pattern_type!(T is <pat>)`) is a refinement of a base
        // type `T` carrying a validity invariant (e.g. the `!null` niche of
        // `NonNull<T>`'s field, `*const T is !null`). It has the *identical*
        // layout and ABI as its base type — the pattern only constrains which bit
        // patterns are valid, not the representation — so for codegen we map it to
        // the base type. This is what makes `Box<T>` (a single-field newtype chain
        // `Box(Unique(NonNull(*const T is !null)))`) collapse to a plain pointer
        // scalar: the niche becomes `*const T -> Ty::PtrConst`. Sound because the
        // backend never relies on the niche being non-null (the MIR's own
        // null-/alignment-check asserts guard every deref), and the runtime
        // representation is bit-identical.
        ty::Pat(base, _) => return rust_ty_to_trust_ir_ty(tcx, *base),
        // A fully-monomorphic instance can still carry an unresolved associated
        // type (`FnOnce::Output` in the `call_once` shims). Normalizing it
        // against the monomorphized typing env resolves it to the concrete type;
        // re-enter on the result. Guard against a normalization no-op to avoid
        // looping on a genuinely opaque alias.
        // `core::cmp::Ordering` — the three-way-comparison result enum, `#[repr(i8)]`
        // with `Less = -1, Equal = 0, Greater = 1`. It is a fieldless enum whose
        // VALUE is exactly its `i8` discriminant, so model it as an `I8` scalar: the
        // `Cmp` binop produces that `i8` directly (see `lower_binary_op`),
        // `discriminant(ordering)` is the identity on it, and `ordering as iN` is a
        // plain integer cast. Narrowed to THIS enum by its diagnostic item, so no
        // other multi-variant enum is affected.
        ty::Adt(adt, _) if tcx.lang_items().ordering_enum() == Some(adt.did()) => TrustIrTy::I8,
        // A TAG-ONLY enum whose layout is a plain integer scalar: every variant
        // carries only ZERO-SIZED fields, so its VALUE *is* its declared
        // discriminant and it is modeled as that integer. This is the general
        // form of the `core::cmp::Ordering` arm directly above, reached by any
        // such enum rather than one named type.
        //
        // ZERO-SIZED FIELDS, NOT NO FIELDS. This gate used to read
        // `v.fields.is_empty()`, which `Result<(), fmt::Error>` fails by HAVING
        // a field — a zero-sized one (`Ok(())` / `Err(fmt::Error)`, both
        // payloads ZST, `size == 1`, one Direct `u8` tag). That is the return
        // type of every `core::fmt::Write`/`Debug` method, and the census
        // measured 16 `library/core` roots stopping on it, all in
        // `core::fmt::builders`. `enum_all_variant_fields_zero_sized` is why
        // this widening is not the repr-only one that would also admit
        // `Option<NonZeroU8>` — read its doc before touching this.
        //
        // MOTIVATING HOLE: `std::mem::alignment::AlignmentEnum` — a `#[repr(usize)]`
        // fieldless enum whose discriminants are the powers of two. It appears as a
        // FIELD of std's `Layout`/`RawVecInner`, so at `-Copt-level=2/3` ANY program
        // calling `slice::to_vec()` reached `RawVecInner::{current_memory,
        // try_allocate_in}` and failed the whole function closed on
        // `Ty::std::mem::alignment::AlignmentEnum`. The same program compiled at O0,
        // because O0 monomorphizes a different std path — an opt-level-dependent
        // refusal, which is the worst kind to leave in place.
        //
        // WHY THIS IS A LAYOUT QUESTION, NOT A MATCH QUESTION. Instrumenting with
        // `trace-ty` shows the request arriving from
        // `aggregate_reference_pointee_to_trust_ir_ty`,
        // `validate_memory_aggregate_field_leaves`, `memory_aggregate_layout` and
        // `scalar_leaf_trust_ir_fields` — i.e. "what scalar is this struct field",
        // not "read this enum's discriminant". So this arm deliberately does NOT
        // generalize the `Ordering`-restricted discriminant/niche decoding in
        // `lower_discriminant`; an unsupported OPERATION on such an enum still hits
        // its own fail-closed and refuses, rather than being silently miscompiled by
        // a type mapping that outran the operations supporting it.
        //
        // SOUNDNESS. The width and signedness come from rustc's own layout, never
        // from the variant count or the `repr` attribute, so a tag rustc widened or
        // narrowed is followed exactly. `BackendRepr::Scalar` + `Primitive::Int` is
        // required: an enum rustc lays out as an aggregate or a pointer-primitive
        // falls through to the fail-closed arm. A zero-variant (uninhabited) enum is
        // excluded — it has no value to model.
        ty::Adt(adt, _)
            if adt.is_enum()
                && !adt.variants().is_empty()
                && enum_all_variant_fields_zero_sized(tcx, ty) =>
        {
            use rustc_abi::{BackendRepr, Primitive, TagEncoding, Variants};
            let layout = tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
                .map_err(|e| format!("Ty::Adt tag-only enum layout_of({ty:?}) failed: {e:?}"))?;
            // BELT AND BRACES over `enum_all_variant_fields_zero_sized`. A
            // variant with no payload bytes offers no niche, so rustc cannot
            // have chosen `TagEncoding::Niche` here — but the model's whole
            // claim is "the scalar IS the declared discriminant", which is true
            // only of a Direct encoding, so read that off the layout rather
            // than inferring it. `Option<NonZeroU8>` has this arm's exact
            // `BackendRepr`, and under a niche encoding its scalar is the
            // PAYLOAD; admitting it would miscompile every `Some(x)`.
            if !matches!(
                layout.layout.variants(),
                Variants::Multiple {
                    tag_encoding: TagEncoding::Direct,
                    ..
                }
            ) {
                return Err(format!(
                    "Ty::Adt tag-only enum without a Direct tag encoding {ty:?}"
                ));
            }
            let BackendRepr::Scalar(scalar) = layout.backend_repr else {
                return Err(format!("Ty::Adt tag-only enum non-scalar layout {ty:?}"));
            };
            let Primitive::Int(int, signed) = scalar.primitive() else {
                return Err(format!("Ty::Adt tag-only enum non-integer tag {ty:?}"));
            };
            // SIGNEDNESS IS LOAD-BEARING, not cosmetic. `AlignmentEnum` is
            // `#[repr(usize)]`, so its tag is UNSIGNED and its largest
            // discriminant is `1 << 63` — a value whose raw i64 pattern is
            // NEGATIVE. Typing it `I64` would present that carrier as a negative
            // signed integer and a constant of that variant would be rejected
            // downstream as a type mismatch. Mirror the `ty::Uint` arm above
            // (which maps to `U8/U16/U32/U64`) and follow rustc's own
            // `Primitive::Int` signedness rather than assuming signed.
            match (int.size().bits(), signed) {
                (8, true) => TrustIrTy::I8,
                (8, false) => TrustIrTy::U8,
                (16, true) => TrustIrTy::I16,
                (16, false) => TrustIrTy::U16,
                (32, true) => TrustIrTy::I32,
                (32, false) => TrustIrTy::U32,
                (64, true) => TrustIrTy::I64,
                (64, false) => TrustIrTy::U64,
                (other, _) => {
                    return Err(format!(
                        "Ty::Adt tag-only enum tag width {other} bits {ty:?}"
                    ));
                }
            }
        }
        ty::Alias(..) => {
            let normalized = tcx.normalize_erasing_regions(
                ty::TypingEnv::fully_monomorphized(),
                ty::Unnormalized::new_wip(ty),
            );
            if normalized == ty {
                return Err(format!("Ty::{ty:?}"));
            }
            return rust_ty_to_trust_ir_ty(tcx, normalized);
        }
        other => {
            let _ = tcx;
            if crate::knobs::is_enabled(crate::knobs::TRACE_TY) {
                eprintln!(
                    "TCG_TRACE_TY Ty::{other:?}\n{}",
                    std::backtrace::Backtrace::force_capture()
                );
            }
            return Err(format!("Ty::{other:?}"));
        }
    })
}

/// Detect a *provably-dead* enum-variant field read: a place projecting
/// `(local as VariantN).field` where `local`'s scalarized enum was constructed
/// (and is statically known) to be a *different* variant than `VariantN`.
///
/// rustc lowers a `match` into a `SwitchInt(discriminant(local))` that routes to
/// one block per variant; the bridge lowers every CFG-reachable block, including
/// the variant arms whose discriminant case can never be taken when the
/// constructed variant is statically known (e.g. matching `None` still emits the
/// `(local as Some).0` read in the unreachable `Some` arm). Those reads touch a
/// payload field that was never bound (the local holds a *different* variant), so
/// the normal projected-value lookup fails closed. Because the guarding
/// `SwitchInt` provably never branches into this arm, *any* value is observably
/// correct here — we emit a typed default so the dead block lowers, mirroring the
/// `Unreachable`-terminator handling. This is sound: it only fires when the bound
/// discriminant's `variant_index` differs from the downcast variant.
///
/// Returns `Ok(Some(value))` with a typed default emitted into `block` for a dead
/// read; `Ok(None)` when the place is not such a dead variant-field read (so the
/// caller proceeds with the normal scalar-binding lookup).
fn dead_variant_field_default<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<Option<ValueId>, String> {
    // Only `(local as Variant).field` — a downcast immediately followed by a
    // field projection — is an enum-variant payload read. Any other projection
    // shape (deref, nested, plain field on a struct) is handled elsewhere.
    let [
        ProjectionElem::Downcast(_, variant_index),
        ProjectionElem::Field(_, _),
    ] = place.projection.as_ref()
    else {
        return Ok(None);
    };

    // The local must carry a statically-known discriminant binding from a literal
    // enum-variant construction. If absent, we cannot prove the read is dead.
    let Some(binding) = ctx.adt_discriminants.get(&place.local).copied() else {
        return Ok(None);
    };

    // If the bound variant equals the downcast variant, this is a *live* read of a
    // bound payload field — not dead; let the normal lookup handle it.
    if binding.variant_index == *variant_index {
        return Ok(None);
    }

    // Provably-dead read. Emit a typed default. We can only synthesize a default
    // for scalar (integer / bool / pointer) field types; for anything else, fail
    // closed rather than guess a representation.
    let field_ty = place_trust_ir_ty(ctx, body, place)?;
    let value = match field_ty {
        TrustIrTy::Bool
        | TrustIrTy::I8
        | TrustIrTy::I16
        | TrustIrTy::I32
        | TrustIrTy::I64
        | TrustIrTy::I128
        | TrustIrTy::U8
        | TrustIrTy::U16
        | TrustIrTy::U32
        | TrustIrTy::U64
        | TrustIrTy::U128
        | TrustIrTy::Ptr => {
            let result = ctx.fresh_value();
            let constant = if field_ty == TrustIrTy::Bool {
                Constant::Bool(false)
            } else {
                Constant::Int(0)
            };
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: field_ty,
                    value: constant,
                })
                .with_result(result),
            );
            result
        }
        // A FLOAT field: the read is still provably dead (never observed), so any typed
        // value is sound — but it must be a FLOAT zero (an integer `0` would be wrong-
        // typed for an `F32`/`F64` field). Mirrors the `lower_unreachable_terminator`
        // float case. (F16 stays in the fail-closed `other` arm — a rarer const width.)
        TrustIrTy::F32 | TrustIrTy::F64 => {
            let result = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Const {
                    ty: field_ty,
                    value: Constant::Float(0.0),
                })
                .with_result(result),
            );
            result
        }
        other => {
            return Err(format!(
                "dead enum-variant field read of non-scalar type {other:?} \
                 (variant {} of local, bound variant {})",
                variant_index.index(),
                binding.variant_index.index()
            ));
        }
    };
    Ok(Some(value))
}

// ============================================================================
// Memory-model lowering.
//
// A local whose type is a non-trivially-scalarizable AGGREGATE — a Direct-tagged
// enum with scalar-leaf payloads (e.g. `Result<i64,i64>`), or a multi-field
// scalar struct / tuple — is given a real STACK SLOT (an `Inst::Alloca`) at
// function entry instead of being scalarized into per-field SSA side tables.
// Reads become `Inst::Load`s from the slot at the field's layout offset; writes
// become `Inst::Store`s; the whole aggregate crosses a call boundary by value
// through the backend's already-verified SysV aggregate-ABI (small aggregates in
// RAX:RDX, larger via sret). Field offsets, the discriminant tag offset/value,
// and the slot's size/alignment all come from `tcx.layout_of`, so the byte
// layout is exactly Rust's.
//
// This path is gated to fire ONLY for aggregates the existing scalarization path
// CANNOT represent (it fails `rust_ty_to_trust_ir_ty` today and so fails closed):
// purely-scalar, never-memory locals keep their fast scalarization path
// untouched. Memory-backed locals are orthogonal to the scalarization dataflow —
// their identity is a single stable alloca `ValueId`, so they never enter the
// snapshot / merge / phi machinery (those tables only hold scalar locals).
// ============================================================================

/// A `LayoutOf` context that answers `tcx.layout_of` / `.field` / `.for_variant`
/// in a fully-monomorphized typing env (mirrors cranelift's
/// `FullyMonomorphizedLayoutCx`). Used only for byte-accurate field/tag offsets.
struct LayoutCx<'tcx>(TyCtxt<'tcx>);

impl<'tcx> rustc_middle::ty::layout::LayoutOfHelpers<'tcx> for LayoutCx<'tcx> {
    fn handle_layout_err(
        &self,
        err: rustc_middle::ty::layout::LayoutError<'tcx>,
        span: rustc_span::Span,
        ty: Ty<'tcx>,
    ) -> ! {
        // rustc's layout callback can receive ordinary size/normalization
        // errors. Report them through the driver's fatal-diagnostic protocol,
        // as the native rustc backends do, instead of manufacturing an ICE.
        self.0.dcx().span_fatal(
            span,
            format!("trust-cg memory model: layout_of({ty:?}) failed: {err:?}"),
        )
    }
}
impl<'tcx> rustc_middle::ty::layout::HasTyCtxt<'tcx> for LayoutCx<'tcx> {
    fn tcx(&self) -> TyCtxt<'tcx> {
        self.0
    }
}
impl<'tcx> rustc_abi::HasDataLayout for LayoutCx<'tcx> {
    fn data_layout(&self) -> &rustc_abi::TargetDataLayout {
        self.0.data_layout()
    }
}
impl<'tcx> rustc_middle::ty::layout::HasTypingEnv<'tcx> for LayoutCx<'tcx> {
    fn typing_env(&self) -> ty::TypingEnv<'tcx> {
        ty::TypingEnv::fully_monomorphized()
    }
}

/// How the discriminant of a memory-backed enum is encoded into its tag field.
///
/// `Direct` is a plain tag word whose value IS the discriminant the `SwitchInt`
/// compares. `Niche` stores the discriminant inside an otherwise-invalid bit
/// pattern of a payload field (the niche), e.g. a null pointer for `Option<&T>`'s
/// `None`; one variant (`untagged_variant`) is encoded by the field holding its
/// own valid payload value, and each `niche_variant` is encoded by a reserved
/// niche value `niche_start + (variant - niche_variants_start)`.
#[derive(Clone, Debug)]
enum MemoryTagEncoding {
    Direct,
    Niche {
        /// The variant encoded by the niche field holding a valid payload value
        /// (e.g. `Some` for `Option<&T>`).
        untagged_variant: VariantIdx,
        /// First/last variant index carried as a reserved niche value.
        niche_variants_start: VariantIdx,
        niche_variants_end: VariantIdx,
        /// The reserved niche value assigned to `niche_variants_start`.
        niche_start: u128,
    },
}

/// Description of the discriminant tag of a multi-variant memory-backed enum.
#[derive(Clone, Debug)]
struct MemoryEnumTag {
    /// Byte offset of the tag (Direct) / niche field (Niche) within the slot.
    offset: u64,
    /// Trust-IR scalar type of the tag / niche field (its in-memory width).
    ty: TrustIrTy,
    /// How the discriminant is encoded into the tag field.
    encoding: MemoryTagEncoding,
}

/// The byte layout of a memory-backed aggregate local, derived from
/// `tcx.layout_of`. `slot_ty` is the `Alloca` element type: a tuple of
/// natural-aligned integer lanes covering exactly `size` bytes with the layout's
/// alignment, so the slot is byte- and alignment-accurate. It is ALSO the ABI
/// return/parameter type when the aggregate crosses a call boundary by value.
#[derive(Clone, Debug)]
struct MemoryAggregateLayout {
    slot_ty: TrustIrTy,
    size: u64,
    align: u64,
    /// `Some` for a Direct-tagged enum; `None` for a struct/tuple/single-variant.
    tag: Option<MemoryEnumTag>,
    /// Whether this aggregate contains (at any nesting depth) at least one
    /// `&str`/`&[T]` fat-pointer leaf field. Such a field has NO scalarized
    /// representation (see `scalar_leaf_trust_ir_fields`'s exclusion) — it can
    /// only be realized as two lanes in a real memory slot — so
    /// `compute_memory_backed_locals` rule 0c consults this to unconditionally
    /// force memory-backing for any local of this type, even one that would
    /// otherwise stay scalarized (a plain non-escaping `let r = Rec{..}`).
    has_fat_pointer_leaf: bool,
    /// Whether this aggregate contains (at any nesting depth) at least one
    /// Direct-tag (no-niche), non-drop, all-scalar-leaf nested MULTI-VARIANT
    /// ENUM field (e.g. `Option<i64>` inside `struct W{opt:Option<i64>,n:i64}`).
    /// Such a field has NO scalarized representation (`scalar_leaf_trust_ir_fields`
    /// unconditionally treats a multi-variant enum as "not a scalar") -- it can
    /// only be realized as tag+payload bytes in a real memory slot -- so
    /// `compute_memory_backed_locals` rule (0d) consults this to unconditionally
    /// force memory-backing for any local of this type, even a plain
    /// non-escaping `let w = W{..}`. Scoped to Direct-tag + !needs_drop
    /// (mirrors `vec_enum_element_admissible`'s scope); a Niche-tagged or
    /// needs-drop nested enum field does NOT set this (stays fail-closed).
    has_nested_enum_leaf: bool,
    /// The PARALLEL flag for a NICHE-tagged (e.g. `Option<&T>` / `Option<bool>`),
    /// non-drop, nested MULTI-VARIANT ENUM field. Tracked separately from
    /// `has_nested_enum_leaf` so its consultation stays narrowly scoped:
    /// `memory_aggregate_layout`'s tuple admission accepts a niche-leaf tuple
    /// (`(Option<&i64>, i64)`), `compute_memory_backed_locals` rule (0d)
    /// memory-backs such a local ONLY when its type is a TUPLE (a struct with a
    /// niche field keeps its working scalarized path), and rule (3c)'s
    /// tuple-destination gate accepts it. All downstream niche mechanisms (niche
    /// tag store, niche decode, lane copy) are the SAME already-live machinery a
    /// bare niche enum local uses.
    has_nested_niche_enum_leaf: bool,
}

/// A flat integer-lane tuple covering `size` bytes at `align` (one of 1/2/4/8).
/// `size` is always a multiple of `align` for a valid layout, so this is exact.
/// How many lane types [`memory_slot_lane_ty`] can pick from.
const SLOT_LANE_TY_COUNT: u32 = 5;

/// THE mapping from a fixed `TyId` to its lane type.
///
/// These are seeded into EVERY bridge-built module at ids `0..SLOT_LANE_TY_COUNT`
/// so a slot type can name its element without threading module context down to
/// `memory_slot_lane_ty` (a free function of `(size, align)`). The bridge
/// otherwise never touches `Module::types`, so these ids are ours to define, and
/// `merge_modules` hash-conses the tables structurally -- the identical prefixes
/// across merged modules collapse back to one set with the `TyId`s remapped.
///
/// [`slot_lane_ty_id`] is the inverse and is derived from THIS match, pinned by
/// `slot_lane_ty_ids_round_trip`. Two hand-written directions would be one more
/// instance of the duplicated-decision bug this file keeps paying for.
fn slot_lane_ty_by_id(index: u32) -> Option<TrustIrTy> {
    Some(match index {
        0 => TrustIrTy::I8,
        1 => TrustIrTy::I16,
        2 => TrustIrTy::I32,
        3 => TrustIrTy::I64,
        4 => TrustIrTy::I128,
        _ => return None,
    })
}

/// The fixed `TyId` for a lane type, or `None` if it is not one of them.
fn slot_lane_ty_id(lane: &TrustIrTy) -> Option<trust_ir::TyId> {
    (0..SLOT_LANE_TY_COUNT)
        .find(|&index| slot_lane_ty_by_id(index).as_ref() == Some(lane))
        .map(trust_ir::TyId::new)
}

/// Seed the lane types into a freshly created bridge module.
///
/// INVARIANT: any module that can carry a MEMORY SLOT type must be seeded,
/// because a slot spells its element as a fixed `TyId` into this table. Today
/// that is exactly the MIR-lowering module (`MirLoweringCtx::new`); the other
/// bridge modules are hand-built and slot-free -- the trap/no-op function stubs
/// (`Unreachable` / `Return` bodies) and the static-data modules (globals typed
/// `Ptr`), none of which run `memory_aggregate_layout`. A wasm32 static-data
/// module is seeded when it is created, because it declares the functions whose
/// addresses it stores (`define_static_fn_pointer_targets`) and their
/// signatures may name a slot-lane array.
///
/// Getting this wrong FAILS CLOSED rather than miscompiling: an unseeded table
/// makes the adapter reject the `TyId` with "types table 0 entries, index out
/// of range" at translation time.
fn seed_slot_lane_types(module: &mut TrustIrModule) -> Result<(), trust_ir::IdSpaceExhausted> {
    debug_assert!(
        module.types.is_empty(),
        "slot lane types must occupy the first TyIds"
    );
    for index in 0..SLOT_LANE_TY_COUNT {
        let lane = slot_lane_ty_by_id(index).expect("lane id below the count resolves");
        module.add_type(lane)?;
    }
    Ok(())
}

/// Smallest lane count spelled as `Ty::Array` rather than an inline
/// `Ty::Tuple`. Both are the SAME type -- `Array(l, n)` and `Tuple([l; n])`
/// agree on size (`n * l.bytes()`, since every lane type has
/// `bytes() == align()`) and on alignment (`l.align()`) -- but the tuple
/// materializes one `Ty` per lane and the array does not.
/// Smallest lane count spelled as `Ty::Array` rather than an inline
/// `Ty::Tuple`. The default is 1, i.e. ALWAYS the array spelling; the knob
/// exists to bisect a suspected divergence back onto the tuple path, and
/// raising it is always safe because the tuple spelling is the older one.
///
/// This sits on the per-type layout path. The request-scoped override layer is
/// intentionally consulted on every call so a long-lived compiler service does
/// not inherit the first request's scheduling policy.
fn slot_array_min_lanes() -> usize {
    // `Shape::Uint`: a non-numeric value is refused fatally at parse, so the
    // `ok()` below can only be `Some` for a knob that was given. Before the
    // grammar existed, `slot-array-min-lanes=two` silently meant 1.
    crate::knobs::raw(crate::knobs::SLOT_ARRAY_MIN_LANES)
        .and_then(|v| v.parse().ok())
        .unwrap_or(1)
}

fn memory_slot_lane_ty(size: u64, align: u64) -> Result<TrustIrTy, String> {
    let (lane, lane_bytes) = memory_aggregate_lane(align)
        .map_err(|_| format!("memory slot alignment {align} unsupported"))?;
    if size % align != 0 {
        return Err(format!(
            "memory slot size {size} not a multiple of alignment {align}"
        ));
    }
    let lanes = (size / lane_bytes) as usize;
    if lanes == 0 {
        return Err("memory slot is zero-sized".to_owned());
    }
    // A slot is `size / align` lanes. Spelled inline as a tuple that vector is
    // as large as the slot itself -- for a `[u8; N]` local, align is 1, so it
    // is one `Ty` PER BYTE, and every later walk of the type re-traverses it.
    // That was the dominant cost of compiling a large stack array: 625MB of
    // compiler RSS and 2.0s for `[0u8; 4 << 20]`, against LLVM's 98MB and
    // 0.12s, with LLVM FLAT in the array size where this was linear.
    //
    // `Ty::Array(elem, n)` is the same type in O(1). It is used above a lane
    // threshold rather than universally only so the threshold can be lowered to
    // 1 in testing to prove the two spellings really are interchangeable; both
    // paths are exact.
    if lanes >= slot_array_min_lanes() {
        if let Some(lane_id) = slot_lane_ty_id(&lane) {
            return Ok(TrustIrTy::Array(lane_id, lanes as u64));
        }
    }
    Ok(TrustIrTy::Tuple(vec![lane; lanes]))
}

/// Whether a Rust type is a scalar leaf the memory model can load/store directly
/// (an integer / float / bool / char / thin pointer / reference). Returns the
/// trust-ir type, or `Err` if not a supported memory scalar.
///
/// A `&str` / `&[T]` / `&mut [T]` (or raw-pointer equivalent) is explicitly
/// EXCLUDED here, even though `rust_ty_to_trust_ir_ty` maps it to a single `Ptr`
/// trust-ir type indistinguishable from a thin `&i64`: its REAL ABI is a
/// 2-eightbyte `{ data, len }` `BackendRepr::ScalarPair`, so treating it as "one
/// scalar" silently drops the length half — a truncated fat pointer whose
/// resulting length-less "slice" is a live OOB-read hazard for any consumer that
/// later indexes/bounds-checks it. This is the ROOT predicate ~30 call sites
/// across this file consult to decide "can I load/store this leaf with one typed
/// access" — excluding the fat-pointer shape here closes the truncation channel
/// at every one of those call sites by construction, rather than requiring each
/// to be individually audited/guarded. The one legitimate exception (a `{data,
/// len}` fat leaf really is representable, just as TWO lanes, not one) is
/// `validate_memory_aggregate_field_leaves`, which checks
/// `is_slice_or_str_fat_ptr_ty` directly and independently of this function so it
/// is unaffected by the exclusion here. Callers that consult this function for
/// array-element / cell / projection-leaf eligibility correctly (and safely) now
/// fall back to their aggregate-recursion or fail-closed arms for a fat-pointer
/// element/field instead of mis-treating it as a bare scalar.
///
/// `#[track_caller]`: this predicate has ~38 call sites and its `Err` string is
/// what a refusal ultimately REPORTS, so a reader of
/// `[TCG-MIR-UNSUPPORTED] ... memory leaf type is a fat pointer` learned which
/// function was refused but nothing about which lowering path refused it — and
/// with 38 candidates that is not a starting point, it is a search. Under
/// `bridge-notes` the message now names the site. Design principle 10: a refusal
/// carries the fix.
#[track_caller]
fn memory_scalar_leaf_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<TrustIrTy, String> {
    /// The caller's source location, appended only under `bridge-notes` so the
    /// default refusal text (which tests match on) is byte-identical.
    ///
    /// `#[track_caller]` here too, and it is load-bearing: the attribute CHAINS,
    /// so `Location::caller()` inside this helper resolves to the caller of
    /// `memory_scalar_leaf_ty` rather than to this call. Without it the location
    /// would be a line inside this function — true, useless, and easy to believe.
    #[track_caller]
    fn site() -> String {
        if bridge_notes_enabled() {
            let at = std::panic::Location::caller();
            format!(" [lowering site: {}:{}]", at.file(), at.line())
        } else {
            String::new()
        }
    }
    if is_slice_or_str_fat_ptr_ty(ty) {
        return Err(format!(
            "memory leaf type is a fat pointer (ScalarPair {{data,len}}), not a single scalar: {ty:?}{}",
            site()
        ));
    }
    // The transparent wide-slice NEWTYPE chain (`NonNull<[T]>` / `NonNull<str>` /
    // `Unique<[T]>`) is the same two-lane `{data,len}` image once it is
    // slot-backed (`wide_slice_carrier_layout`), but the type
    // mapper collapses it to one `Ptr` through its `ty::Pat` field. Answering
    // `Ptr` here let every GENERIC one-lane path — a whole-value read of a
    // slotted newtype local, the leaf store of a `NonNull<[T]>`-typed struct
    // field, the deref-store through `&mut NonNull<[T]>` — load or store lane 0
    // alone while the slot readers (`lower_memory_slice_assign`, the boundary)
    // read both lanes: measured 2026-09-22 as a silent stale / uninitialized
    // length (`set(slot: &mut NonNull<[u8]>, p)`, a `Holder { p, n }` field
    // read back two-lane). Refuse by name, as for the bare slice: the two-lane
    // arms are the only readers and writers of this shape.
    if wide_slice_carrier_layout(tcx, ty).is_some() {
        return Err(format!(
            "memory leaf type is a wide-slice carrier (a two-lane {{data,len}} \
             image), not a single scalar: {ty:?}{}",
            site()
        ));
    }
    // ...and the LAYOUT-true form of the same question, which the kind test above
    // cannot ask: a reference to ANY unsized pointee is a `{ data, metadata }`
    // `ScalarPair`, including a struct with a `[T]` / `str` TAIL (`&ByteStr`,
    // `&CStr`, `&Wtf8`) and a `&dyn Trait`. Before those acquired a
    // `rust_ty_to_trust_ir_ty` mapping this arm was unreachable for them — the
    // mapping below simply failed — so the guard's kind test was sufficient BY
    // ACCIDENT. It no longer is: the mapping now answers `Ptr` (the same single
    // lane a THIN reference gets), `is_pointer_like_trust_ir_ty` accepts it, and
    // a two-lane value would be bound into one lane with the metadata dropped and
    // every later field of the enclosing aggregate 8 bytes off — miscompile class
    // `3b9b89a8`. This is the same guard `scalar_leaf_trust_ir_fields` already
    // carries for the nested descent, on the same predicate, for the same stated
    // reason.
    if is_wide_pointer_memory_leaf_ty(tcx, ty) {
        return Err(format!(
            "memory leaf type is a WIDE pointer to an unsized pointee (ScalarPair \
             {{data,metadata}}), not a single scalar: {ty:?}{}",
            site()
        ));
    }
    let trust_ir_ty = rust_ty_to_trust_ir_ty(tcx, ty)?;
    if trust_ir_ty.bit_width().is_some() || is_pointer_like_trust_ir_ty(&trust_ir_ty) {
        Ok(trust_ir_ty)
    } else {
        Err(format!(
            "memory leaf type is not a scalar: {trust_ir_ty:?}{}",
            site()
        ))
    }
}

/// Whether `ty` is an INTERIOR-MUTABLE SCALAR CELL — an aggregate that contains an
/// `UnsafeCell` (so it is NOT `Freeze`) yet maps to a single non-pointer memory scalar
/// leaf (`Cell<i32>` / `UnsafeCell<u64>`, `#[repr(transparent)]` over the scalar).
///
/// For such a type a SHARED reference `&c` is a legitimate mutation channel:
/// `Cell::set(&self, v)` / `Cell::replace(&self, v)` write through a `&self` shared
/// borrow. The scalarized SNAPSHOT model — which records only the borrowed value at the
/// borrow point and only reloads for a `&mut` writeback — is therefore UNSOUND for it: a
/// write through the shared reference would be dropped, so a later `c.get()` reads the
/// stale snapshot (the interior-mutability stale-read class). Celling the referent routes
/// every read/write through a stable slot with no register caching across the accessor
/// call, which is the sound representation. Celling is semantically inert for a plain
/// (non-cell) scalar, so this predicate is exactly the interior-mutability test that
/// decides when a `&cell` borrow MUST be celled rather than snapshotted.
///
/// A `Freeze` newtype (`struct W(u32)`) is excluded (immutable through `&`, the snapshot
/// is correct); a non-scalar cell (`Cell<(u32, u32)>`) and a pointer-like cell
/// (`Cell<*mut T>`) are excluded (not a single non-pointer leaf) and keep failing closed.
fn is_interior_mutable_scalar_cell<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    if ty.is_freeze(tcx, ty::TypingEnv::fully_monomorphized()) {
        return false;
    }
    matches!(
        rust_ty_to_trust_ir_ty(tcx, ty),
        Ok(t) if t.bit_width().is_some() && !is_pointer_like_trust_ir_ty(&t)
    )
}

/// The two independently-tracked "this leaf subtree needs a real memory slot"
/// bits `validate_memory_aggregate_field_leaves` accumulates while descending
/// an aggregate's fields.
struct MemoryAggregateFieldLeafInfo {
    /// At least one `&str`/`&[T]` fat-pointer leaf (see `MemoryAggregateLayout::has_fat_pointer_leaf`).
    has_fat_pointer_leaf: bool,
    /// At least one Direct-tag, non-drop, nested multi-variant-enum leaf (see
    /// `MemoryAggregateLayout::has_nested_enum_leaf`).
    has_nested_enum_leaf: bool,
    /// At least one NICHE-tag, non-drop, nested multi-variant-enum leaf (see
    /// `MemoryAggregateLayout::has_nested_niche_enum_leaf`).
    has_nested_niche_enum_leaf: bool,
}

/// Whether `layout` is a `#[repr(C)]`-inhibited NEWTYPE over a scalar: a sized
/// `Variants::Single` struct whose `BackendRepr` is `Memory` while its bytes are
/// exactly one `Scalar` — the shape rustc's `univariant` would have unpacked to
/// that scalar's ABI had `repr(C)` not vetoed it (`ReprFlags::ABI_UNOPTIMIZABLE`).
/// Re-derives rustc's own preconditions for the unpack, from the layout alone:
///   * exactly ONE non-ZST field (a ZST sibling such as `PhantomData` is fine —
///     rustc skips ZSTs the same way),
///   * that field at byte offset 0,
///   * the field's size AND ABI alignment equal to the wrapper's (so a
///     `#[repr(C, align(16))]` wrapper of a `u64`, whose bytes are NOT the
///     scalar's bytes, and a `packed` wrapper, whose alignment is not, both
///     refuse — as they do in rustc),
///   * and the field itself either `Scalar`, or another such newtype (the
///     `Atomic<usize>` -> `UnsafeCell<Align8<usize>>` -> `Align8<usize>` -> `usize`
///     chain: `repr(transparent)` copies its field's `Memory` ABI upward, so every
///     level is `Memory` and the walk has to descend to the scalar).
/// A `ScalarPair` at any level, a union (`FieldsShape::Union`), an array
/// (`FieldsShape::Array`), a multi-variant or multi-field layout, or a
/// mismatch in offset/size/alignment answers `false`, and the caller keeps
/// failing closed exactly as before. When it answers `true`, the wrapper's
/// collapsed trust-ir type (`memory_scalar_leaf_ty`, which the caller has
/// already required to succeed) is cross-checked against the layout size where
/// it has a bit width, so the type-level collapse and the layout agree on the
/// width of the one access the memory model will emit.
fn repr_c_newtype_scalar_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    cx: &LayoutCx<'tcx>,
    layout: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
) -> bool {
    use rustc_abi::{BackendRepr, FieldsShape, Variants};
    fn sole_scalar_at_zero<'tcx>(
        cx: &LayoutCx<'tcx>,
        layout: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
    ) -> bool {
        if !matches!(layout.backend_repr, BackendRepr::Memory { sized: true }) {
            return false;
        }
        if !matches!(layout.variants, Variants::Single { .. }) {
            return false;
        }
        if !matches!(layout.fields, FieldsShape::Arbitrary { .. }) {
            return false;
        }
        if layout.size.bytes() == 0 {
            return false;
        }
        let mut sole: Option<(usize, rustc_middle::ty::layout::TyAndLayout<'tcx>)> = None;
        for i in 0..layout.fields.count() {
            let field = layout.field(cx, i);
            if field.is_zst() {
                continue;
            }
            if sole.is_some() {
                return false;
            }
            sole = Some((i, field));
        }
        let Some((i, field)) = sole else {
            return false;
        };
        if layout.fields.offset(i).bytes() != 0
            || field.size != layout.size
            || field.align.bytes() != layout.align.bytes()
        {
            return false;
        }
        match field.backend_repr {
            BackendRepr::Scalar(_) => true,
            BackendRepr::Memory { sized: true } => sole_scalar_at_zero(cx, &field),
            _ => false,
        }
    }
    if !sole_scalar_at_zero(cx, layout) {
        return false;
    }
    // The type-level collapse (`rust_ty_to_trust_ir_ty` through the newtype's
    // single field) and the layout must name the same access width; a
    // pointer-like collapsed type has no `bit_width` and is target-pointer-sized,
    // which the offset-0 / equal-size checks above already pin to the layout.
    match memory_scalar_leaf_ty(tcx, layout.ty) {
        Ok(leaf) => match leaf.bit_width() {
            // Byte-ROUNDED: `Ty::Bool` reports a bit width of 1 while its layout is
            // one byte, so an exact `bits == bytes * 8` would spuriously refuse a
            // `#[repr(C)] struct W(bool)` that a bare `bool` leaf admits.
            Some(bits) => u64::from(bits).div_ceil(8) == layout.size.bytes(),
            None => is_pointer_like_trust_ir_ty(&leaf),
        },
        Err(_) => false,
    }
}

/// Recursively validate that every LEAF of an aggregate field type is either a
/// memory scalar the model can load/store with one typed access, OR a `&str` /
/// `&[T]` "fat leaf" the model can load/store as TWO lanes (`{data, len}`). A
/// field that is itself an aggregate (struct / Direct-tagged enum / tuple /
/// array) is descended into; only the bottom-most leaves must be scalars/fat
/// leaves. This is what lets `struct Outer { inner: Inner, z }` and
/// `Option<Result<i64,i64>>`-shaped nesting be addressed by accumulated byte
/// offsets in `memory_place_address`.
///
/// Returns `has_fat_pointer_leaf: true` when the subtree contains AT LEAST ONE
/// fat-pointer leaf (so the caller can force memory-backing — a fat leaf has no
/// scalarized representation, see `compute_memory_backed_locals` rule 0c), and
/// `has_nested_enum_leaf: true` when the subtree contains AT LEAST ONE
/// Direct-tag (no-niche), non-drop, nested MULTI-VARIANT ENUM field (so the
/// caller can force memory-backing — such a field has no scalarized
/// representation either, see `compute_memory_backed_locals` rule 0d).
///
/// Fails closed (precise diagnostic) for any shape the byte-offset addressing
/// cannot reach soundly: a non-scalar/non-fat-leaf leaf, an unsized field, a
/// union, or a Niche-encoded nested enum (its tag is not a plain word at a
/// layout offset).
fn validate_memory_aggregate_field_leaves<'tcx>(
    tcx: TyCtxt<'tcx>,
    cx: &LayoutCx<'tcx>,
    field_layout: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
) -> Result<MemoryAggregateFieldLeafInfo, String> {
    // A FAT leaf: a 2-lane `{data, metadata}` `ScalarPair` the memory model can
    // load/store as TWO typed accesses (see `store_fat_ptr_slot_field` /
    // `load_fat_ptr_data_at` / `load_fat_ptr_meta_at`). Checked BEFORE
    // `memory_scalar_leaf_ty` (which unconditionally rejects any fat pointer as
    // "not a single scalar").
    //
    // BOTH of Rust's pointer-metadata kinds qualify, and for the same reason:
    //   * `&[T]` / `&str` — metadata is a length;
    //   * `&dyn Trait` — metadata is a vtable pointer.
    // They have the IDENTICAL in-memory shape (data at the field offset,
    // metadata at `fat_ptr_metadata_offset`), so one two-lane access places
    // either. The `&dyn` half is what lets `struct Holder<'a> { s: &'a dyn
    // Shape, .. }`, a `&dyn` closure upvar and a `&dyn` tuple element be
    // byte-addressed; the store/load machinery for it already exists (the
    // `is_trait_object_reference_ty` arms in `lower_memory_aggregate_field_store`
    // / `lower_memory_dyn_array_assign`), it was only ever the LEAF MODEL that
    // did not admit the shape.
    //
    // Admitting `&dyn` here also CLOSES A HOLE rather than opening one. Before
    // this, a `&dyn Trait` field fell past `memory_scalar_leaf_ty` into the
    // "descend into a nested aggregate" arm below, where rustc's own
    // `TyAndLayout::field` answers field 0 of a wide pointer with `ty` = the
    // WHOLE wide pointer carrying the layout of a THIN `*mut ()`
    // (`FieldsShape::Primitive`, zero sub-fields) — so the walk found NO leaves
    // at all and returned `has_fat_pointer_leaf: false`. The aggregate was then
    // recorded as "all leaves are fine" while one leaf had no representation.
    // It is now classified as what it is.
    //
    // ...and the same shape reached through a checked wrapper image, with
    // representation established by transparency or concrete layout: `NonNull<[u8]>` (std's
    // `Allocator::allocate` return carrier) IS the `*const [u8]` ScalarPair. The
    // `BackendRepr::ScalarPair` requirement below still gates it, so a newtype
    // laid out any other way keeps failing closed. Every OTHER `ScalarPair` (a
    // `(i64,i64)` tuple leaf, a niche-optimized enum) keeps its existing arm
    // below / fails closed, unaffected.
    if is_fat_pointer_memory_leaf_ty(field_layout.ty)
        || transparent_newtype_is_slice_fat_ptr(tcx, field_layout.ty)
    {
        return match crate::scalar_pair::view(field_layout.backend_repr) {
            Some(_) => Ok(MemoryAggregateFieldLeafInfo {
                has_fat_pointer_leaf: true,
                has_nested_enum_leaf: false,
                has_nested_niche_enum_leaf: false,
            }),
            _ => Err(format!(
                "memory aggregate fat-pointer leaf {:?} has unexpected backend_repr \
                 (expected ScalarPair)",
                field_layout.ty
            )),
        };
    }
    // A scalar leaf: it must be a thin scalar the memory model can load/store with
    // a single typed access AND its layout must be a single `Scalar` (NOT a
    // `ScalarPair`). A wide reference that is NOT a slice/str fat pointer
    // (`&dyn Trait`, whose metadata is a vtable) maps to a `Ref`/`Ptr` trust-ir
    // type that `memory_scalar_leaf_ty` would otherwise accept, but its layout is
    // a two-field `ScalarPair` (data + metadata) that a single load would
    // truncate — so reject those here (this is what keeps `core::panic::PanicInfo`,
    // whose fields are wide references, fail-closed).
    // The containing-aggregate lane still refuses owned collection fields.
    // Default-Global Vec/String have a checked standalone rustc header, but a
    // nested owner also needs coordinated field storage, projection, constant
    // images, call/return transport and drop. Validating a leaf alone does not
    // establish those operations. Synthetic maps and custom allocators need
    // their own representations. Dedicated standalone-header paths must check
    // their root authority separately; do not relax this nested-field gate.
    {
        let leaf_ty = field_layout.ty;
        if vec_element_ty(tcx, leaf_ty).is_some()
            || is_string_ty(tcx, leaf_ty)
            || btreemap_kv_ty(tcx, leaf_ty).is_some()
            || any_hashmap_kv_ty(tcx, leaf_ty).is_some()
            || is_hashmap_dead_internal_ty(tcx, leaf_ty)
        {
            return Err(format!(
                "[TCG-COLLECTION-IMAGE] memory aggregate owns a collection field {leaf_ty:?}: \
                 default-Global Vec/String have a checked standalone header, but this containing \
                 aggregate's storage, projections, constant image, call/return ABI and drop do \
                 not yet share a qualified inline image. Synthetic maps and custom allocators \
                 need their own representation. Failing closed; extend the containing aggregate \
                 transport using rustc's actual layout and ownership semantics"
            ));
        }
    }
    if memory_scalar_leaf_ty(tcx, field_layout.ty).is_ok() {
        use rustc_abi::BackendRepr;
        return match field_layout.backend_repr {
            BackendRepr::Scalar(_) => Ok(MemoryAggregateFieldLeafInfo {
                has_fat_pointer_leaf: false,
                has_nested_enum_leaf: false,
                has_nested_niche_enum_leaf: false,
            }),
            // A `#[repr(C)]` NEWTYPE over a scalar — `AtomicUsize` is
            // `#[repr(C)] struct Atomic<usize> { v: UnsafeCell<Align8<usize>> }`
            // with `#[repr(C, align(8))] struct Align8<T>(T)` — carries
            // `BackendRepr::Memory` although its bytes ARE the one scalar:
            // rustc's `univariant` refuses to unpack the newtype ABI under
            // `repr(C)` ONLY because "that affects C ABIs"
            // (`rustc_abi/src/layout.rs`, `inhibit_newtype_abi_optimization`), a
            // by-value calling-convention concern that says nothing about the
            // bytes at a layout offset. This validator exists to keep a WIDE
            // leaf (a `ScalarPair` a single load would truncate) out of the
            // memory model — and it was refusing the thin case with it, which
            // stopped the stage1 `library/std` build at `std_detect`'s
            // `static CACHE: [Cache; 3]` (`Cache(AtomicUsize)`): the
            // `&CACHE[i]` element borrow reached `raw_ptr_aggregate_pointee_
            // addressable`, whose leaf walk refused `Cache` here, so the array
            // arm of `memory_aggregate_ref_pointee` declined and
            // `lower_scalar_ref` fell through to "Rvalue::Ref source projection
            // is not scalar-bindable". The ADDRESS-TAKEN LOCAL array path already
            // admits the same element (`array_memory_layout` skips this walk when
            // `memory_scalar_leaf_ty` collapses the element), so the two paths
            // disagreed about one type. `repr_c_newtype_scalar_layout` re-derives
            // exactly the preconditions rustc checked before `optimize_abi`
            // vetoed the unpack — one non-ZST field, at offset 0, same size and
            // alignment as the wrapper, bottoming at a `Scalar` — so the admitted
            // leaf's bytes are provably the scalar's bytes; every `ScalarPair` and
            // every genuinely multi-word `Memory` layout keeps failing closed here.
            BackendRepr::Memory { sized: true }
                if repr_c_newtype_scalar_layout(tcx, cx, field_layout) =>
            {
                Ok(MemoryAggregateFieldLeafInfo {
                    has_fat_pointer_leaf: false,
                    has_nested_enum_leaf: false,
                    has_nested_niche_enum_leaf: false,
                })
            }
            _ => Err(format!(
                "memory aggregate leaf {:?} is not a single scalar (wide/fat or non-scalar ABI)",
                field_layout.ty
            )),
        };
    }
    if !field_layout.is_sized() {
        return Err(format!(
            "memory aggregate has unsized nested field {:?}",
            field_layout.ty
        ));
    }
    // A nested aggregate: descend per its layout. Only Direct-tagged enums (tag ==
    // a plain word at a layout offset) are reachable by byte-offset addressing;
    // niche-encoded enums fail closed (their discriminant is not a tag word).
    use rustc_abi::Variants;
    match field_layout.layout.variants() {
        Variants::Single { .. } | Variants::Empty => {
            let mut info = MemoryAggregateFieldLeafInfo {
                has_fat_pointer_leaf: false,
                has_nested_enum_leaf: false,
                has_nested_niche_enum_leaf: false,
            };
            // An ARRAY (or SIMD vector) has one field SHAPE repeated `count`
            // times, so every element yields the IDENTICAL leaf info and the
            // loop below would OR the same three bools `count` times. Validate
            // one element and answer for all of them.
            //
            // This is not a heuristic — it is the same answer, reached in O(1)
            // instead of O(count). It matters because `count` is the array
            // LENGTH: a `[u8; 4 << 20]` local otherwise drives 4.2M recursive
            // layout descents, which is the dominant cost of compiling a large
            // stack array (645ms of a 2.0s compile, against LLVM's 122ms flat).
            if let rustc_abi::FieldsShape::Array { count, .. } = field_layout.fields {
                if count == 0 {
                    return Ok(info);
                }
                let element = field_layout.field(cx, 0);
                return validate_memory_aggregate_field_leaves(tcx, cx, &element);
            }
            for field in 0..field_layout.fields.count() {
                let inner = field_layout.field(cx, field);
                let inner_info = validate_memory_aggregate_field_leaves(tcx, cx, &inner)?;
                info.has_fat_pointer_leaf |= inner_info.has_fat_pointer_leaf;
                info.has_nested_enum_leaf |= inner_info.has_nested_enum_leaf;
                info.has_nested_niche_enum_leaf |= inner_info.has_nested_niche_enum_leaf;
            }
            Ok(info)
        }
        Variants::Multiple {
            tag_encoding,
            variants,
            tag_field,
            ..
        } => {
            // A niche-encoded nested enum field is byte-offset-addressable iff its
            // niche field is a single scalar (the identical precondition the top-level
            // `memory_aggregate_layout` niche arm enforces); its discriminant is then
            // decoded via the standard niche formula at its accumulated offset
            // (`emit_tag_discriminant_from_base`, driven by the sub-enum's OWN
            // `memory_aggregate_layout`). Any other (non-Direct, non-scalar-niche)
            // encoding still fails closed early and precisely.
            if !matches!(tag_encoding, rustc_abi::TagEncoding::Direct) {
                use rustc_abi::BackendRepr;
                let niche_field_layout = field_layout.field(cx, tag_field.index());
                if !matches!(niche_field_layout.backend_repr, BackendRepr::Scalar(_)) {
                    return Err(format!(
                        "memory aggregate niche-encoded nested enum field {:?} niche field is not a single scalar",
                        field_layout.ty
                    ));
                }
            }
            let mut info = MemoryAggregateFieldLeafInfo {
                has_fat_pointer_leaf: false,
                has_nested_enum_leaf: false,
                has_nested_niche_enum_leaf: false,
            };
            for (variant_index, variant_layout) in variants.iter_enumerated() {
                if variant_layout.is_uninhabited() {
                    continue;
                }
                let vl = field_layout.for_variant(cx, variant_index);
                for field in 0..vl.fields.count() {
                    let inner = vl.field(cx, field);
                    let inner_info = validate_memory_aggregate_field_leaves(tcx, cx, &inner)?;
                    info.has_fat_pointer_leaf |= inner_info.has_fat_pointer_leaf;
                    info.has_nested_enum_leaf |= inner_info.has_nested_enum_leaf;
                    info.has_nested_niche_enum_leaf |= inner_info.has_nested_niche_enum_leaf;
                }
            }
            // Mark THIS field as a nested-enum leaf only when Direct-tag +
            // !needs_drop (mirrors `vec_enum_element_admissible`'s scope). A
            // Niche-tagged or needs-drop nested enum field is intentionally NOT
            // marked -- it keeps today's fail-closed behavior for
            // `compute_memory_backed_locals` rule (0d) unless/until a
            // separately-scrutinized increment widens this. Note this is a
            // per-FIELD (not per-local) exclusion: a struct that ALSO has a
            // Direct-tag nested-enum field elsewhere will still be swept into
            // memory-backing by that other field, and this (excluded) Niche
            // field then rides along through the SAME already-proven
            // byte-offset machinery (its own validation above still requires
            // its niche field to be a single scalar) -- sound, just not the
            // trigger.
            if matches!(tag_encoding, rustc_abi::TagEncoding::Direct)
                && !field_layout
                    .ty
                    .needs_drop(tcx, ty::TypingEnv::fully_monomorphized())
            {
                info.has_nested_enum_leaf = true;
            } else if matches!(tag_encoding, rustc_abi::TagEncoding::Niche { .. })
                && !field_layout
                    .ty
                    .needs_drop(tcx, ty::TypingEnv::fully_monomorphized())
            {
                // The PARALLEL Niche-tag marking (same !needs_drop scope; the
                // niche field was already validated to be a single scalar
                // above). Consulted ONLY by the three narrowly-scoped sites
                // documented on `MemoryAggregateLayout::has_nested_niche_enum_leaf`;
                // a needs-drop niche enum field stays unmarked (fail-closed).
                info.has_nested_niche_enum_leaf = true;
            }
            Ok(info)
        }
    }
}

/// Flatten `ty`'s aggregate scalar leaves for the BY-VALUE TUPLE ELIGIBILITY check,
/// DESCENDING into ARRAY fields — the ONE shape
/// `scalar_field_aggregate_trust_ir_fields` / `scalar_leaf_trust_ir_fields`
/// deliberately fail closed on (they must, because the SCALARIZED projected-value
/// path binds each leaf by a FLAT INDEX and has no array-element addressing, so it
/// keeps array-containing aggregates off that path).
///
/// This helper is consulted SOLELY by `integer_byval_tuple_eligible` /
/// `scalar_byval_tuple_eligible` to decide whether every leaf of a by-value tuple is
/// an in-scope memory scalar, so that an array-containing tuple can ride the SAME
/// verified MEMORY-BACKED byte-offset ABI path a named struct with an array field
/// ALREADY uses (`memory_aggregate_layout` validates the layout via
/// `validate_memory_aggregate_field_leaves`, which descends arrays; the tuple is
/// then memory-backed by `compute_memory_backed_locals` and constructed / read by
/// `lower_memory_aggregate_construct` + the memory field machinery, every access
/// addressed by the RUSTC LAYOUT byte offset). Because the returned leaves are used
/// only for the in-scope PREDICATE and NEVER to bind a flat-leaf index, array
/// element strides and rustc field REORDERING are irrelevant to this flattening —
/// the offsets that matter all come from the rustc layout downstream.
///
/// Mirrors `scalar_field_aggregate_trust_ir_fields` exactly (same ZST-field
/// skipping, same pointer-like-leaf acceptance, same `None` = "not an aggregate /
/// keep existing path" signal) EXCEPT that a nested array field is descended into
/// `N` copies of its element's leaves instead of failing closed.
fn scalar_byval_eligibility_leaves<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<Vec<TrustIrTy>>, String> {
    match ty.kind() {
        ty::Tuple(fields) if !fields.is_empty() => {
            let mut flattened = Vec::new();
            for field_ty in fields.iter() {
                if is_zero_sized_ty(tcx, field_ty) {
                    continue;
                }
                flattened.extend(scalar_byval_eligibility_leaf(tcx, field_ty)?);
            }
            Ok(Some(flattened))
        }
        ty::Adt(adt, args)
            if (adt.is_struct() || (adt.is_enum() && adt.variants().len() == 1))
                && !adt.is_union() =>
        {
            let variant = adt.variant(VariantIdx::new(0));
            if variant.fields.is_empty() {
                return Ok(None);
            }
            let mut flattened = Vec::new();
            for field in variant.fields.iter() {
                let field_ty = normalized_adt_field_ty(tcx, field, *args);
                if is_zero_sized_ty(tcx, field_ty) {
                    continue;
                }
                flattened.extend(scalar_byval_eligibility_leaf(tcx, field_ty)?);
            }
            Ok(Some(flattened))
        }
        ty::Closure(_, args) => {
            let upvars: Vec<Ty<'tcx>> = args.as_closure().upvar_tys().iter().collect();
            if upvars.is_empty() {
                return Ok(None);
            }
            let mut flattened = Vec::new();
            for upvar_ty in upvars {
                if is_zero_sized_ty(tcx, upvar_ty) {
                    continue;
                }
                flattened.extend(scalar_byval_eligibility_leaf(tcx, upvar_ty)?);
            }
            Ok(Some(flattened))
        }
        _ => Ok(None),
    }
}

/// The array-descending analogue of `scalar_leaf_trust_ir_fields` used only for the
/// by-value tuple eligibility predicate (see `scalar_byval_eligibility_leaves`). A
/// nested aggregate field descends via `scalar_byval_eligibility_leaves`; a nested
/// ARRAY field expands to `N` copies of its element's leaves; anything else must be
/// a single memory scalar (or a pointer-like leaf, whose `bit_width()` is `None`).
fn scalar_byval_eligibility_leaf<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Vec<TrustIrTy>, String> {
    if let Some(fields) = scalar_byval_eligibility_leaves(tcx, ty)? {
        return Ok(fields);
    }
    if let ty::Array(element, len) = ty.kind() {
        let len = len
            .try_to_target_usize(tcx)
            .ok_or_else(|| format!("array length is not target-usize evaluable: {ty:?}"))?;
        let len =
            usize::try_from(len).map_err(|_| format!("array length {len} out of usize range"))?;
        // A `[T; 0]` or a `[ZST; N]` array occupies no bytes and contributes no
        // leaf (matching the ZST-field skipping above). A non-ZST element is
        // descended recursively (so `[S; N]` of a scalar-leaf struct `S`, or a
        // nested `[[T; M]; N]`, expands correctly).
        if len == 0 || is_zero_sized_ty(tcx, *element) {
            return Ok(Vec::new());
        }
        let element_leaves = scalar_byval_eligibility_leaf(tcx, *element)?;
        let mut leaves = Vec::with_capacity(element_leaves.len().saturating_mul(len));
        for _ in 0..len {
            leaves.extend(element_leaves.iter().cloned());
        }
        return Ok(leaves);
    }
    let field_ty = rust_ty_to_trust_ir_ty(tcx, ty)?;
    // Pointer-like leaf is a valid memory scalar even though its `bit_width()` is
    // `None` (target-dependent pointer width) — mirror `scalar_leaf_trust_ir_fields`.
    if field_ty.bit_width().is_none() && !is_pointer_like_trust_ir_ty(&field_ty) {
        return Err(format!(
            "aggregate reference nested field is not memory-scalar: {field_ty:?}"
        ));
    }
    Ok(vec![field_ty])
}

/// Whether `ty` is a BARE TUPLE of integer / bool / float scalar leaves, small
/// enough to ride the verified SysV aggregate-return / by-value-arg ABI (a register
/// pair for `<=16` bytes, sret otherwise) the SAME way a named scalar-leaf struct
/// does.
///
/// SCOPE (deliberately narrow — see the surrounding comment in
/// `memory_aggregate_layout`): the existing scalarization path represents most
/// tuples field-wise (the `(T, bool)` overflow-op result pair, small
/// `(scalar, scalar)` temporaries) and the corpus depends on that, so this fires
/// ONLY for a tuple whose every (non-ZST) leaf is an integer `i8..=i128`/`u8..=u128`,
/// a `bool`, or a 32-/64-bit float (`f32`/`f64`). A tuple with a POINTER/reference
/// or a NESTED aggregate leaf returns `false` → it keeps the scalarized
/// path (and fails closed there on its own terms if actually used at a boundary),
/// never miscompiling. A 128-bit integer leaf is admitted: the backend's verified
/// SysV classifier models an `i128` as two consecutive INTEGER eightbytes (register
/// pair when the whole aggregate is <=16 bytes, sret otherwise), and the memory slot
/// / lane copy address it as `I128` lanes (`memory_slot_lane_ty`), exactly matching.
///
/// FLOAT leaves are in scope because a float tuple is laid out by rustc IDENTICALLY
/// to a named `struct` of the same float fields (same size / offsets / SysV SSE
/// eightbyte classification), and the named-struct float-aggregate by-value path is
/// already verified-correct — so a `(f64, f64)` / `(i32, f64)` tuple reuses the
/// SAME proven `memory_aggregate_layout` machinery, differing only in the
/// `ty::Tuple`-vs-`ty::Adt` kind the byte-offset addressing is agnostic to.
///
/// The flattened leaf types are read via `scalar_field_aggregate_trust_ir_fields`
/// (which already flattens a `ty::Tuple`); the actual per-field BYTE OFFSETS used
/// for every load/store come from the rustc layout (rustc REORDERS tuple fields,
/// e.g. `(i8, i64)` → `i64@0, i8@8`), so this predicate only gates eligibility —
/// it never assumes declaration order.
fn integer_byval_tuple_eligible<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<bool, String> {
    let ty::Tuple(fields) = ty.kind() else {
        return Ok(false);
    };
    if fields.is_empty() {
        return Ok(false);
    }
    // Flatten to the scalar leaf trust-ir types, DESCENDING array fields (via
    // `scalar_byval_eligibility_leaves`, NOT the flat-index scalarized flatten) so an
    // array-containing tuple stays eligible for the memory-backed byte-offset path. A
    // leaf that does not flatten to a scalar (a non-scalar / fat-pointer field) is
    // surfaced as an `Err`; swallow it here and report ineligible (keep the
    // scalarized path) rather than failing the whole compile, since a `None` layout
    // is the "keep existing path" signal.
    let Ok(Some(leaves)) = scalar_byval_eligibility_leaves(tcx, ty) else {
        return Ok(false);
    };
    if leaves.is_empty() {
        // An all-ZST tuple has no ABI lanes — leave it to the existing path.
        return Ok(false);
    }
    // Every leaf must be an integer of width <= 128 bits, a bool, or a 32-/64-bit
    // float. A 128-bit integer leaf IS admitted: the backend's verified SysV
    // classifier models an `i128` as two consecutive INTEGER eightbytes (register
    // pair for a <=16-byte aggregate, sret otherwise), and the memory slot / lane
    // copy address it as `I128` lanes (`memory_slot_lane_ty`), so an `(i128, ..)`
    // tuple rides the SAME proven byte-offset ABI path a named struct with an i128
    // field uses. Pointer-like leaves stay on the scalarized / fail-closed path.
    //
    // FLOAT leaves (`f32`/`f64`) are admitted because a tuple of float scalars is
    // laid out by rustc IDENTICALLY to a named `struct` of the same float fields
    // (same size, same field offsets, same SysV SSE eightbyte classification), and
    // the named-struct float-aggregate path — `struct { a: f64, b: f64 }` returned
    // / passed by value, classified into XMM0:XMM1 — is already verified-correct at
    // O0 and O3. Routing a `(f64, f64)` (or mixed `(i32, f64)`) tuple through the
    // SAME `memory_aggregate_layout` machinery therefore reuses the proven
    // float-eightbyte construction/load/store + SysV classification; the only thing
    // that differs is the `ty::Tuple`-vs-`ty::Adt` kind, which the byte-offset
    // addressing is agnostic to. (Without this, a `fn -> (f64, f64)` fails closed at
    // O0 with `Ty::(f64, f64)` because the scalarized path cannot represent a whole
    // float-tuple value crossing a by-value ABI boundary.)
    let all_in_scope = leaves.iter().all(|leaf| {
        *leaf == TrustIrTy::Bool
            || (leaf.is_integer() && leaf.bit_width().map_or(false, |bits| bits <= 128))
            || matches!(leaf, TrustIrTy::F32 | TrustIrTy::F64)
    });
    Ok(all_in_scope)
}

/// Whether `ty` is a BARE TUPLE of integer / bool / FLOAT scalar leaves, eligible
/// to ride the verified SysV aggregate-return / by-value-arg ABI (a register pair
/// for `<=16` bytes — SysV places each eightbyte in RAX:RDX or XMM0:XMM1 by its
/// INTEGER/SSE class — or the stack MEMORY class otherwise) the SAME way a named
/// scalar-leaf struct already does.
///
/// This is the SUPERSET of `integer_byval_tuple_eligible` that ALSO admits `f32` /
/// `f64` leaves (so `(f64, f64)`, `(i32, f64)`, `(f64, i32)` returns / by-value
/// params compile instead of failing closed). It is sound because the downstream
/// machinery is identical to the named-struct path, which already memory-backs and
/// correctly returns float / mixed-class / >16B aggregates (verified differentially
/// for `struct { f64, f64 }`, `struct { i32, f64 }`, `struct { f32, i32 }`, the
/// 4×f64 sret case, …): the slot is a raw byte slot of `I64`/`I32`/… lanes
/// (`memory_slot_lane_ty`) and each field is loaded/stored with a TYPED access
/// (`F64`/`F32`/`iN`) at its rustc-LAYOUT byte offset, and the backend's verified
/// SysV eightbyte classifier picks the INTEGER vs SSE register for each eightbyte —
/// none of which depends on whether the source aggregate was spelled as a tuple or
/// a named struct.
///
/// ALSO admits a pointer / reference leaf (`&T` / thin `*T`) — the `(usize, &T)` /
/// `(&A, &B)` item an iterator `.enumerate()` / `.zip()` yields into a
/// tuple-pattern `.map` closure, and the `(&T, i64, i64)` rust-call tuple a
/// three-argument `ClosureOnceShim` receives. The pointer leaf rides an I64 lane
/// exactly like the proven fat-pointer / named-struct-with-references paths. A
/// `<=16`-byte tuple uses the verified register-pair path; a larger tuple uses the
/// same verified MEMORY-class stack path as an integer tuple or named struct of
/// identical layout.
///
/// A 128-bit integer leaf IS admitted (the backend classifies an `i128` as two
/// INTEGER eightbytes; the slot addresses it as `I128` lanes). Still EXCLUDED (kept
/// on the scalarized / fail-closed path): any NESTED-aggregate leaf that does not
/// flatten to scalars. Per-field BYTE OFFSETS always come from the rustc layout
/// (which reorders tuple fields), never declaration order.
fn scalar_byval_tuple_eligible<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<bool, String> {
    let ty::Tuple(fields) = ty.kind() else {
        return Ok(false);
    };
    if fields.is_empty() {
        return Ok(false);
    }
    // Flatten DESCENDING array fields (see `scalar_byval_eligibility_leaves`) so an
    // array-containing tuple stays eligible for the memory-backed byte-offset path.
    let Ok(Some(leaves)) = scalar_byval_eligibility_leaves(tcx, ty) else {
        return Ok(false);
    };
    if leaves.is_empty() {
        // An all-ZST tuple has no ABI lanes — leave it to the existing path.
        return Ok(false);
    }
    // Every leaf must be an integer (<= 64 bits) / bool / `f32` / `f64`, OR a
    // pointer-like leaf (`&T` / thin `*T`). A pointer-leaf tuple PREVIOUSLY failed
    // closed at every by-value boundary (the scalarization path cannot represent a
    // whole tuple-with-pointer crossing a call), so admitting it is purely additive:
    // it routes the shape through the SAME verified SysV aggregate path a named
    // struct with reference fields already uses. Up to 16 bytes that is the
    // register-pair path; above 16 bytes it is the MEMORY-class stack path already
    // exercised by integer tuples and named structs. In both cases the pointer leaf
    // round-trips through an I64 lane via the proven `PtrToInt`/`IntToPtr` lane
    // store/load, identical to the `slice::Iter` fat-pointer data lane. A 128-bit
    // integer leaf is admitted (two INTEGER eightbytes, `I128` lanes); only a
    // non-scalar leaf still keeps the existing path / fails closed.
    let all_in_scope = leaves.iter().all(|leaf| {
        *leaf == TrustIrTy::Bool
            || *leaf == TrustIrTy::F32
            || *leaf == TrustIrTy::F64
            || (leaf.is_integer() && leaf.bit_width().map_or(false, |bits| bits <= 128))
            || is_pointer_like_trust_ir_ty(leaf)
    });
    Ok(all_in_scope)
}

thread_local! {
    /// Memo for [`memory_aggregate_layout`], keyed by the interned `TyKind`
    /// address (the same stable, collision-free type identity `TY_LOWER_ACTIVE`
    /// uses).
    ///
    /// WHY: the layout's `slot_ty` is a tuple with ONE LANE PER `align` BYTES of
    /// the aggregate, so for a `[u8; N]` local it is an N-element vector — and
    /// the function is called ~10 times for the same type on one compile
    /// (`compute_memory_backed_locals` alone walks every local three times).
    /// Rebuilding a 4M-lane tuple ten times is what put a `[0u8; 4 << 20]`
    /// compile at 625MB RSS.
    ///
    /// ONLY CONTEXT-FREE RESULTS ARE CACHED — see the guard at the insert. This
    /// function sits in the mutually-recursive type-classification cluster that
    /// `TY_LOWER_ACTIVE` breaks cycles for, and its answer genuinely DEPENDS on
    /// that stack: it early-returns `Ok(None)` when `rust_ty_to_trust_ir_ty`
    /// succeeds, and that call returns the cycle `Err` instead when the type is
    /// already being resolved further up. A result computed mid-descent can
    /// therefore differ from the same type's top-level answer, so caching one
    /// would poison the other. Entries are only recorded when the active-descent
    /// stack is EMPTY, which is exactly the top-level classification the hot
    /// callers perform. Errors are never cached (they are the cheap fail-closed
    /// path, and the cycle `Err` is context-dependent by construction).
    static MEMORY_AGGREGATE_LAYOUT_MEMO: std::cell::RefCell<
        std::collections::HashMap<usize, Option<std::rc::Rc<MemoryAggregateLayout>>>,
    > = std::cell::RefCell::new(std::collections::HashMap::new());
}

/// Drop every memoized layout. Called once per function lowering so no entry can
/// outlive the arena that minted its key.
fn clear_memory_aggregate_layout_memo() {
    MEMORY_AGGREGATE_LAYOUT_MEMO.with(|m| m.borrow_mut().clear());
}

/// Whether any type classification is currently in progress on this thread. The
/// memo is only safe to populate when this is false — see the memo's doc.
fn ty_classification_descent_is_active() -> bool {
    TY_LOWER_ACTIVE.with(|active| !active.borrow().is_empty())
}

/// [`memory_aggregate_layout`], but handing back a shared `Rc` so a caller that
/// only needs the FLAGS (`has_fat_pointer_leaf`, …) or a `is_some()` test never
/// deep-clones the lane tuple.
fn memory_aggregate_layout_shared<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<std::rc::Rc<MemoryAggregateLayout>>, String> {
    let ty_key = ty.kind() as *const ty::TyKind<'tcx> as usize;
    if let Some(hit) = MEMORY_AGGREGATE_LAYOUT_MEMO.with(|m| m.borrow().get(&ty_key).cloned()) {
        return Ok(hit);
    }
    let computed = memory_aggregate_layout_uncached(tcx, ty)?.map(std::rc::Rc::new);
    if !ty_classification_descent_is_active() {
        MEMORY_AGGREGATE_LAYOUT_MEMO.with(|m| m.borrow_mut().insert(ty_key, computed.clone()));
    }
    Ok(computed)
}

/// Compute the memory-aggregate layout for `ty` IF it is a kind the memory model
/// supports AND the scalarization path cannot already represent it. Returns
/// `Ok(None)` for any type that should keep the existing (scalar / interception)
/// path, so this is purely additive and never steals a working case.
///
/// Prefer [`memory_aggregate_layout_shared`] when you only need the flags or an
/// `is_some()` test: this wrapper DEEP-CLONES the layout, and `slot_ty` is one
/// lane per `align` bytes, so for a big array local that clone is the size of
/// the array.
fn memory_aggregate_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    Ok(memory_aggregate_layout_shared(tcx, ty)?.map(|shared| (*shared).clone()))
}

fn memory_aggregate_layout_uncached<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    if let Some(layout) = real_vec_string_header_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    // A `core::fmt` plumbing type keeps its rustc-derived layout whichever crate
    // defines it (see `fat_ptr_or_memory_aggregate_layout`): deadness is a
    // per-LOCAL fact (`ctx.fmt_dead_locals`), never a per-type one.
    // Only consider types the existing scalar mapping rejects. If
    // `rust_ty_to_trust_ir_ty` succeeds (scalar, single-field newtype, Vec-as-Ptr,
    // union ABI, …) keep that path: the corpus depends on it.
    if rust_ty_to_trust_ir_ty(tcx, ty).is_ok() {
        return Ok(None);
    }
    // A std map whose integer lanes the map model refused has no representation
    // here either (its hasher and table fields are refused below as collection
    // fields); name the model's reason instead.
    if let Some(reason) = map_model_refusal(tcx, ty) {
        return Err(reason);
    }

    // Only named ADTs (structs / multi-variant enums) are memory-backed in this
    // increment. MOST bare tuples — including the `(T, bool)` overflow-op result
    // pair and small `(scalar, scalar)` temporaries — keep the existing
    // scalarization path (projected per-field SSA values), which the corpus depends
    // on. The ONE exception is a tuple of integer / bool / FLOAT scalar leaves that
    // crosses a by-value ABI boundary (a `fn -> (i64, i32)` / `fn -> (f64, f64)` /
    // `fn -> (i32, f64)` return, a `(i64, i32)` / `(f64, f64)` by-value param, a
    // tuple-returning call destination): the scalarized path cannot represent a
    // WHOLE-tuple value crossing a CALL boundary (it fails closed on `Ty::(i64,
    // i32)` / `Ty::(f64, f64)`), so route it through the SAME verified SysV
    // register-pair / sret machinery a named scalar-leaf struct uses — which
    // already memory-backs and returns float / mixed INTEGER+SSE class / >16B-sret
    // aggregates correctly (verified differentially for the equivalent named
    // structs). The compute-memory-backed gate only consults this for return locals
    // / by-value params / call dests, so a scalarized small-tuple temporary (never a
    // boundary) is untouched. The per-field byte offsets below come from the rustc
    // layout (which reorders tuple fields), never declaration order.
    let is_scalar_byval_tuple = scalar_byval_tuple_eligible(tcx, ty)?;
    let is_named_adt = matches!(
        ty.kind(),
        ty::Adt(adt, _) if (adt.is_struct() || adt.is_enum()) && !adt.is_union()
    );
    // A by-value array `[T; N]` whose element bottoms out at a memory scalar leaf.
    // The scalarized path handles array LOCALS (per-element projected values) but
    // cannot represent a WHOLE-array value crossing a CALL boundary (a by-value array
    // parameter / return / call destination — `Ty::[T; N]` fails closed). An array is
    // a single-variant aggregate whose `Variants::Single` "fields" are its N elements,
    // so the validation + slot-layout logic below handles it uniformly (each element
    // leaf validated, slot = N*size_of::<T>(), no tag). Plain array locals are NOT
    // params/returns/call-dests, so they stay on the scalarized path (untouched).
    let is_array = matches!(ty.kind(), ty::Array(..));
    // A general tuple containing a Direct-tag enum leaf (e.g. `(Option<i64>, i64)`)
    // is layout-identical to the equivalent named struct the memory path already
    // handles (rustc lays both out via the same univariant logic), so admit it and
    // let the nested-enum-leaf scope guard below keep every other tuple (scalar
    // tuples, fat-leaf tuples, needs-drop tuples) on their existing paths.
    let is_tuple = matches!(ty.kind(), ty::Tuple(..));
    if !is_named_adt && !is_array && !is_scalar_byval_tuple && !is_tuple {
        return Ok(None);
    }

    let cx = LayoutCx(tcx);
    let ty_and_layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("memory aggregate layout_of failed: {e:?}"))?;
    let layout = ty_and_layout.layout;
    if !layout.is_sized() {
        return Ok(None);
    }
    let size = layout.size().bytes();
    let align = layout.align().bytes();
    if size == 0 {
        return Ok(None);
    }

    // Every variant's every field must be a supported scalar leaf (so each
    // load/store is a single typed access). We do not yet model aggregate-in-
    // aggregate memory, so fail closed on a non-scalar field.
    use rustc_abi::Variants;
    let mut has_fat_pointer_leaf = false;
    let mut has_nested_enum_leaf = false;
    let mut has_nested_niche_enum_leaf = false;
    let tag = match &layout.variants {
        Variants::Single { .. } | Variants::Empty => {
            // A struct / single-variant enum: validate every field's leaves are
            // scalars, descending through nested aggregate fields.
            let variant = ty_and_layout.for_variant(&cx, rustc_abi::FIRST_VARIANT);
            // Uniform-element short circuit, exactly as in
            // `validate_memory_aggregate_field_leaves` -- this is the arm a
            // top-level `[T; N]` local takes, so without it the array length
            // drives the loop.
            let uniform_element_count =
                if let rustc_abi::FieldsShape::Array { count, .. } = variant.fields {
                    Some(count)
                } else {
                    None
                };
            match uniform_element_count {
                Some(0) => {}
                Some(_) => {
                    let element = variant.field(&cx, 0);
                    let info = validate_memory_aggregate_field_leaves(tcx, &cx, &element)?;
                    has_fat_pointer_leaf |= info.has_fat_pointer_leaf;
                    has_nested_enum_leaf |= info.has_nested_enum_leaf;
                    has_nested_niche_enum_leaf |= info.has_nested_niche_enum_leaf;
                }
                None => {
                    for field in 0..variant.fields.count() {
                        let field_layout = variant.field(&cx, field);
                        let info = validate_memory_aggregate_field_leaves(tcx, &cx, &field_layout)?;
                        has_fat_pointer_leaf |= info.has_fat_pointer_leaf;
                        has_nested_enum_leaf |= info.has_nested_enum_leaf;
                        has_nested_niche_enum_leaf |= info.has_nested_niche_enum_leaf;
                    }
                }
            }
            None
        }
        Variants::Multiple {
            tag,
            tag_encoding,
            tag_field,
            variants,
        } => {
            use rustc_abi::TagEncoding;
            // Both Direct (tag word == discriminant) and Niche (discriminant in an
            // otherwise-invalid bit pattern of a payload field, e.g. null for
            // `Option<&T>`'s `None`) encodings are modeled. Any other encoding (none
            // exist today) stays on the existing scalarization path / fails closed.
            let encoding = match tag_encoding {
                TagEncoding::Direct => MemoryTagEncoding::Direct,
                TagEncoding::Niche {
                    untagged_variant,
                    niche_variants,
                    niche_start,
                } => {
                    // The niche must be reachable by ONE typed access at
                    // `tag_offset`, which is the NICHE FIELD's own offset. A single
                    // `Scalar` field trivially is.
                    //
                    // A `ScalarPair` field qualifies ONLY when the niche lives in
                    // its FIRST lane — `Option<&[u8]>` / `Option<&mut [u8]>`, where
                    // `None` is the null DATA pointer of the `{data, len}` pair.
                    // Lane 0 begins exactly at the field's offset, so `tag_offset`
                    // already names it and no new offset arithmetic is introduced.
                    //
                    // The proof that it IS lane 0 and not lane 1 is rustc's own tag
                    // scalar: admit only when `tag` IS the pair's first scalar —
                    // same primitive AND same valid range. A niche in lane 1 would
                    // need `tag_offset + lane0_size` and is REFUSED here rather than
                    // read from the wrong eightbyte, which would decode a LENGTH as
                    // a discriminant.
                    let niche_field_layout = ty_and_layout.field(&cx, tag_field.index());
                    use rustc_abi::BackendRepr;
                    let niche_addressable = match niche_field_layout.backend_repr {
                        BackendRepr::Scalar(_) => true,
                        other => crate::scalar_pair::view(other).is_some_and(|pair| pair.a == *tag),
                    };
                    if !niche_addressable {
                        return Err(format!(
                            "memory niche enum {ty:?} niche field is neither a single scalar \
                             nor a ScalarPair whose FIRST lane is the niche"
                        ));
                    }
                    MemoryTagEncoding::Niche {
                        untagged_variant: *untagged_variant,
                        niche_variants_start: niche_variants.start,
                        niche_variants_end: niche_variants.last,
                        niche_start: *niche_start,
                    }
                }
            };
            let tag_offset = layout.fields().offset(tag_field.index()).bytes();
            let tag_ty = scalar_primitive_trust_ir_ty(tcx, tag)?;
            // Validate every inhabited variant's fields bottom out at scalar
            // leaves, descending through nested aggregate fields.
            for (variant_index, variant_layout) in variants.iter_enumerated() {
                if variant_layout.is_uninhabited() {
                    continue;
                }
                let vl = ty_and_layout.for_variant(&cx, variant_index);
                for field in 0..vl.fields.count() {
                    let field_layout = vl.field(&cx, field);
                    let info = validate_memory_aggregate_field_leaves(tcx, &cx, &field_layout)?;
                    has_fat_pointer_leaf |= info.has_fat_pointer_leaf;
                    has_nested_enum_leaf |= info.has_nested_enum_leaf;
                    has_nested_niche_enum_leaf |= info.has_nested_niche_enum_leaf;
                }
            }
            Some(MemoryEnumTag {
                offset: tag_offset,
                ty: tag_ty,
                encoding,
            })
        }
    };

    // Scope the general-tuple acceptance to ONLY nested-enum-leaf tuples this
    // increment: a scalar tuple stays on the (already correct) scalarized /
    // scalar-byval paths, and a fat-leaf tuple (`(&str, i64)`) is NOT admitted
    // here so it cannot newly sweep into the rule-0c memory-backing set — the
    // enum-leaf case is the one the O0/O3 tuple battery validates end to end.
    // A NICHE-tagged enum leaf (`(Option<&i64>, i64)`) is admitted the same way:
    // the tuple is layout-identical to the equivalent named struct, and all
    // downstream niche mechanisms (tag store/decode, lane copy) are the same
    // already-live machinery a bare niche enum local uses.
    //
    // ...and the ONE further tuple this admits is the tuple the SCALARIZED path
    // CANNOT SPELL AT ALL. `scalar_field_aggregate_trust_ir_fields` fails closed on a
    // tuple carrying a leaf with no flat scalar form — a nested ARRAY, or (measured
    // here) a UNION field whose own fields are not scalars, e.g.
    // `core::escape::MaybeEscapedCharacter<N> = union { escape_seq: [ascii::Char; N],
    // literal: char }` inside `EscapeIterInner<N, _>` inside `char::EscapeDebug`. On a
    // `library/core` census that was 4 failed roots, all in the `char::escape_*`
    // Display/iterator chain, and the refusal text they carried was the UNION FIELD's
    // (`Ty::[ascii::ascii_char::AsciiChar; 10_usize]`) rather than anything about the
    // tuple.
    //
    // This is the SAME predicate `compute_memory_backed_locals` rule (0e) already
    // applies to named aggregates — "no scalarized representation, but a memory one" —
    // so it cannot steal a working case: a tuple it newly admits has no scalarized
    // lowering to lose, and every leaf was already validated by
    // `validate_memory_aggregate_field_leaves` above with offsets from rustc's own
    // layout. A tuple the scalarized path CAN spell is untouched (the corpus depends
    // on that path).
    let scalarized_path_can_spell_tuple = is_tuple && scalar_leaf_trust_ir_fields(tcx, ty).is_ok();

    // A tupled closure argument can contain an aggregate whose fields need
    // memory, such as EscapeDefault's array. The existing closure-call path
    // packs each such element from the tuple slot; scalarizing the tuple would
    // lose the element's representation. Every field was validated above.
    // The query runs for EVERY tuple, including one admitted only because the
    // scalarized path cannot spell it: a field whose own classification errs
    // still refuses the whole tuple rather than being skipped.
    let has_memory_aggregate_field = if let ty::Tuple(fields) = ty.kind() {
        fields.iter().try_fold(false, |found, field| {
            Ok::<_, String>(found || memory_aggregate_layout_shared(tcx, field)?.is_some())
        })?
    } else {
        false
    };

    // Preserve the scalarized path for every other tuple. A tuple the scalarized
    // path cannot spell, a scalar ABI boundary, and a tuple with a supported
    // memory field (or a nested-enum / fat-pointer leaf) use this validated slot
    // layout.
    if is_tuple
        && scalarized_path_can_spell_tuple
        && !is_scalar_byval_tuple
        && !has_nested_enum_leaf
        && !has_nested_niche_enum_leaf
        && !has_fat_pointer_leaf
        && !has_memory_aggregate_field
    {
        return Ok(None);
    }
    let slot_ty = memory_slot_lane_ty(size, align)?;
    Ok(Some(MemoryAggregateLayout {
        slot_ty,
        size,
        align,
        tag,
        has_fat_pointer_leaf,
        has_nested_enum_leaf,
        has_nested_niche_enum_leaf,
    }))
}

/// The memory-slot layout for a CAPTURING (non-ZST) closure environment, treated
/// as a struct of its captured upvars (`Closure(def_id, args)` is laid out as an
/// anonymous struct of `upvar_tys()`). A capturing closure gets a real stack slot
/// so `&closure` / `&mut closure` is the address the closure body reads its
/// upvars through (`(*env).N`), and so an `FnMut` env's by-value upvar mutations
/// persist across calls (the slot is mutated in place).
///
/// Returns:
///   * `Ok(None)` — a ZST closure (no captures): it keeps the existing
///     scalarized path (its `&env` receiver is a harmless unused pointer); this
///     is the only closure shape the prior corpus exercised (`lang_start`'s
///     `move || main()`, which captures `main` as a ZST fn item).
///   * `Ok(Some(layout))` — a capturing closure whose every upvar leaf is a
///     memory scalar (integer / float / bool / char / thin pointer / reference),
///     which covers by-value `Copy` captures and by-reference (`&T` / `&mut T`)
///     captures.
///   * `Err(..)` — a capture this backend cannot model in a flat slot (a
///     non-scalar / wide / aggregate-by-value upvar, e.g. a moved `Vec` / `Box`),
///     so the caller fails closed rather than miscompiling.
fn closure_memory_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    let ty::Closure(_, args) = ty.kind() else {
        return Ok(None);
    };
    if is_zero_sized_ty(tcx, ty) {
        return Ok(None);
    }
    let cx = LayoutCx(tcx);
    let ty_and_layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("closure layout_of failed: {e:?}"))?;
    let layout = ty_and_layout.layout;
    if !layout.is_sized() {
        return Ok(None);
    }
    let size = layout.size().bytes();
    let align = layout.align().bytes();
    if size == 0 {
        return Ok(None);
    }
    // A closure is a single-variant aggregate: every upvar leaf must be a
    // single-scalar memory leaf addressable by one typed access at its offset.
    //
    // NOTE: a BY-VALUE intercepted-collection upvar (`move |..| ... v ...`
    // capturing a `Vec`/`BTreeMap`/`HashMap`/`String` by value) is deliberately NOT
    // accepted here. rustc lays such a captured value out as its full multi-word
    // `{ ptr, cap, len }` struct inline in the env, whereas the bridge models the
    // value as a single slot-address `Ptr`. Even though the env store / `(*env).N`
    // read would round-trip that one pointer correctly, a moved-in collection forces
    // the closure through the `FnOnce::call_once` dispatch shim, whose body the
    // bridge does not lower — an experiment that accepted this layout produced a
    // `ud2` trap stub for `call_once` and a runtime SIGILL (verified differential).
    // So a moved-in collection upvar fails closed at the leaf validation below
    // rather than reach an un-lowered shim. By-REFERENCE captures (`&Vec` /
    // `&mut Vec` / `&mut HashMap` …), whose upvar is a thin pointer that validates
    // cleanly and is invoked through the `Fn`/`FnMut` env path, DO work end to end.
    let _ = args;
    // A fat-pointer (`&str`/`&[T]`/`&dyn`) upvar composed with a closure
    // environment is a `ScalarPair {data,len}` upvar. It is now MODELED: the env
    // store round-trips both lanes atomically (store_operand_into_memory_at's
    // fat-leaf arm) and the closure body's `(*env).N` read reconstructs both lanes
    // (the fat-leaf Deref arm in the borrowed-env read path). A fat-ptr `&[T]`/
    // `&str`/`&dyn` upvar is `Copy`, so the closure stays `Fn`/`FnMut` on the
    // env-pointer path and never crosses the un-lowered `FnOnce::call_once`
    // by-value shim. We STILL call validate_memory_aggregate_field_leaves per
    // field so its OTHER rejections (a moved-in `Vec`/`String`/`Box` collection
    // upvar, a nested niche/enum leaf this path does not model, …) continue to
    // fire and fail closed; we only accumulate `has_fat_pointer_leaf` instead of
    // erroring on it.
    let mut has_fat_pointer_leaf = false;
    let variant = ty_and_layout.for_variant(&cx, rustc_abi::FIRST_VARIANT);
    for field in 0..variant.fields.count() {
        let field_layout = variant.field(&cx, field);
        let info = validate_memory_aggregate_field_leaves(tcx, &cx, &field_layout)?;
        has_fat_pointer_leaf |= info.has_fat_pointer_leaf;
    }
    let slot_ty = closure_slot_ty(tcx, &ty_and_layout, size, align)?;
    Ok(Some(MemoryAggregateLayout {
        slot_ty,
        size,
        align,
        tag: None,
        has_fat_pointer_leaf,
        has_nested_enum_leaf: false,
        has_nested_niche_enum_leaf: false,
    }))
}

/// The slot type of a capturing closure's environment, in the register FILE
/// rustc gives that environment.
///
/// A closure whose whole environment is ONE float scalar (`move |x| x * s`
/// over an `f64` or `f32`) has rustc's `BackendRepr::Scalar(Float)` layout, and
/// rustc passes and returns it `PassMode::Direct` in a FLOATING-POINT register.
/// Its slot is that one float as a one-lane aggregate (`(f64)` / `(f32)`), which
/// trust-cg's classifiers place where rustc places the float, as an argument and
/// as a return value: an AArch64 homogeneous float aggregate of one member
/// (`d0` / `s0` onwards), a System V SSE eightbyte (`xmm0` onwards). The integer
/// lane every other environment gets put it in a general-purpose register
/// instead, so every by-value crossing of such a closure (a generic `F: Fn`
/// argument, an `impl FnOnce` return, a by-value `FnOnce` body, the
/// `ClosureOnceShim` a `dyn Fn` vtable's `call_once` reaches) was refused
/// `[TCG-ARG-ABI]` / `[TCG-RET-ABI]`. Every site that declares, passes, returns
/// or stores the environment reads this one slot type, so they cannot disagree;
/// the per-argument gate and the whole-signature check still compare it with
/// rustc's `FnAbi` at every declaration.
///
/// Every other environment keeps its integer lanes: an integer or pointer
/// `Scalar` already sits in rustc's register file, and a `ScalarPair`
/// environment takes the two-value pair lane (`scalar_pair_param_plan`).
fn closure_slot_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty_and_layout: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
    size: u64,
    align: u64,
) -> Result<TrustIrTy, String> {
    use rustc_abi::{BackendRepr, Float, Primitive};
    if let BackendRepr::Scalar(scalar) = ty_and_layout.backend_repr {
        if scalar.size(&tcx).bytes() == size {
            match scalar.primitive() {
                Primitive::Float(Float::F32) => return Ok(TrustIrTy::Tuple(vec![TrustIrTy::F32])),
                Primitive::Float(Float::F64) => return Ok(TrustIrTy::Tuple(vec![TrustIrTy::F64])),
                _ => {}
            }
        }
    }
    memory_slot_lane_ty(size, align)
}

/// The memory-slot layout for a CONTUR (post-`StateTransform`) COROUTINE FRAME.
///
/// rustc lowers a generator/coroutine into a state machine BEFORE the bridge sees
/// it (`tcx.instance_mir` is post-transform, so there is no `Yield`). The frame
/// `{coroutine@...}` is laid out as a multi-variant enum: one `Variants::Multiple`
/// tag word (the resume STATE: `Unresumed` / `Suspend{n}` / `Returned` /
/// `Panicked`) plus, per state, the set of locals live across that suspension.
/// The resume fn reads the state via `discriminant((*frame))`, `switchInt`s on it,
/// and writes the next state via `SetDiscriminant`; the caller constructs the
/// frame with `AggregateKind::Coroutine` and takes `&mut frame` to drive it.
///
/// This reuses the EXACT enum-tag extraction `memory_aggregate_layout` uses for a
/// named multi-variant enum — the tag offset / encoding / width come straight from
/// `tcx.layout_of` (NEVER hand-guessed), and every variant's live-field leaves are
/// validated as memory scalars. A coroutine whose cross-suspend state includes a
/// non-scalar leaf (a captured `Vec`, a fat pointer, a niche-encoded nested enum)
/// fails closed here, exactly as the named-enum path does — a wrong frame layout
/// would be a silent miscompile, so anything not provably byte-exact is rejected.
///
/// Returns `Ok(None)` for a non-coroutine; `Err(..)` for a coroutine whose frame
/// the byte-offset memory model cannot represent soundly.
fn coroutine_memory_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    if !matches!(ty.kind(), ty::Coroutine(..)) {
        return Ok(None);
    }
    let cx = LayoutCx(tcx);
    let ty_and_layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("coroutine frame layout_of failed: {e:?}"))?;
    let layout = ty_and_layout.layout;
    if !layout.is_sized() {
        return Ok(None);
    }
    let size = layout.size().bytes();
    let align = layout.align().bytes();
    if size == 0 {
        // A 0-byte coroutine (no state, no upvars, no cross-suspend live locals):
        // every state is distinguished only by its tag, which is itself 0-byte
        // ZST-optimized away. There is nothing to load/store and `&frame` cannot
        // carry a runtime discriminant — fail closed rather than invent a slot.
        return Err(format!(
            "coroutine frame {ty:?} is zero-sized (no runtime state)"
        ));
    }

    // The coroutine frame is laid out as a multi-variant enum: extract the resume-
    // STATE tag exactly as the named-enum path does (`memory_aggregate_layout`'s
    // `Variants::Multiple` arm), and validate every state's live-field leaves are
    // memory scalars the byte machinery can load/store at their layout offsets.
    use rustc_abi::Variants;
    let tag = match &layout.variants {
        Variants::Single { .. } | Variants::Empty => {
            // A single-state coroutine (e.g. one that never suspends): no runtime
            // tag. Its sole "variant" fields must still be scalar leaves.
            let variant = ty_and_layout.for_variant(&cx, rustc_abi::FIRST_VARIANT);
            for field in 0..variant.fields.count() {
                let field_layout = variant.field(&cx, field);
                // A fat-pointer (`&str`/`&[T]`) cross-suspend coroutine live local is
                // NOT probed/verified by this backend (only top-level struct/tuple/
                // array fat leaves are) — fail closed rather than risk an unverified
                // interaction with the resume-state machinery.
                if validate_memory_aggregate_field_leaves(tcx, &cx, &field_layout)?
                    .has_fat_pointer_leaf
                {
                    return Err(format!(
                        "coroutine frame {ty:?} live field {:?} is a fat pointer \
                         (ScalarPair {{data,len}}); not yet supported",
                        field_layout.ty
                    ));
                }
            }
            None
        }
        Variants::Multiple {
            tag,
            tag_encoding,
            tag_field,
            variants,
        } => {
            use rustc_abi::TagEncoding;
            let encoding = match tag_encoding {
                TagEncoding::Direct => MemoryTagEncoding::Direct,
                TagEncoding::Niche {
                    untagged_variant,
                    niche_variants,
                    niche_start,
                } => {
                    let niche_field_layout = ty_and_layout.field(&cx, tag_field.index());
                    use rustc_abi::BackendRepr;
                    if !matches!(niche_field_layout.backend_repr, BackendRepr::Scalar(_)) {
                        return Err(format!(
                            "coroutine frame {ty:?} niche state field is not a single scalar"
                        ));
                    }
                    MemoryTagEncoding::Niche {
                        untagged_variant: *untagged_variant,
                        niche_variants_start: niche_variants.start,
                        niche_variants_end: niche_variants.last,
                        niche_start: *niche_start,
                    }
                }
            };
            let tag_offset = layout.fields().offset(tag_field.index()).bytes();
            let tag_ty = scalar_primitive_trust_ir_ty(tcx, tag)?;
            for (variant_index, variant_layout) in variants.iter_enumerated() {
                if variant_layout.is_uninhabited() {
                    continue;
                }
                let vl = ty_and_layout.for_variant(&cx, variant_index);
                for field in 0..vl.fields.count() {
                    let field_layout = vl.field(&cx, field);
                    if validate_memory_aggregate_field_leaves(tcx, &cx, &field_layout)?
                        .has_fat_pointer_leaf
                    {
                        return Err(format!(
                            "coroutine frame {ty:?} live field {:?} is a fat pointer \
                             (ScalarPair {{data,len}}); not yet supported",
                            field_layout.ty
                        ));
                    }
                }
            }
            Some(MemoryEnumTag {
                offset: tag_offset,
                ty: tag_ty,
                encoding,
            })
        }
    };

    let slot_ty = memory_slot_lane_ty(size, align)?;
    Ok(Some(MemoryAggregateLayout {
        slot_ty,
        size,
        align,
        tag,
        has_fat_pointer_leaf: false,
        has_nested_enum_leaf: false,
        has_nested_niche_enum_leaf: false,
    }))
}

/// The memory-slot layout for an address-taken `[T; N]` array whose elements
/// bottom out at SCALAR leaves. The slot's lane tuple covers `N *
/// size_of::<T>()` bytes at the array's alignment, so a `&array as &[T]`
/// slice's data pointer is the slot's real address and `data + i*size`
/// element-loads land in the slot. The element `T` may itself be a memory-
/// eligible aggregate — a NESTED ARRAY (`[[i32;2];2]`, addressed
/// `slot + i*innerstride + j*elemsize`) or a scalar-leaf struct / tuple
/// (`[(i32,i32);2]`, with a trailing `.field`); the runtime-address walker
/// descends `cur_layout` per Index/Field so multi-level addressing is exact.
/// Returns `None` for a non-array or an element whose leaves are not all
/// memory scalars (the latter keeps the existing scalarized path, fail-closed
/// on its own terms).
fn array_memory_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    let ty::Array(element, _) = ty.kind() else {
        return Ok(None);
    };
    // A scalar-leaf element is addressable lane-wise here. A `&dyn Trait`
    // element is a 16-byte / 8-aligned fat pointer `{ data, vtable }`; an array
    // of those is laid out as `N * 16` bytes of I64 lanes (two lanes per
    // element). Otherwise the element may be an AGGREGATE (nested array, or a
    // scalar-leaf struct / tuple) whose every leaf is a memory scalar — that is
    // still byte-addressable lane-wise (the walker descends per Index/Field), so
    // validate the element's leaves recursively rather than requiring a single
    // scalar. Any element with a non-scalar / fat / union / niche-enum leaf
    // keeps the existing path and falls through to the scalarized representation.
    if memory_scalar_leaf_ty(tcx, *element).is_err() && !is_trait_object_reference_ty(*element) {
        let cx = LayoutCx(tcx);
        let element_layout = tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(*element))
            .map_err(|e| format!("array element memory layout_of failed: {e:?}"))?;
        // A fat-pointer (`&str`/`&[T]`) element (directly, or nested inside a
        // struct/tuple element) is EXCLUDED from this ADDRESS-TAKEN array path:
        // the runtime element-address walker below has not been verified to emit
        // the two-lane fat-pointer load/store at a computed `slot + i*stride`
        // element address (only the fixed-offset struct/tuple-field construct
        // and field-projected-read paths were verified for a fat leaf) — fall
        // through to `Ok(None)` (the existing scalarized path, fail-closed on its
        // own terms) rather than risk an unverified addressing interaction.
        match validate_memory_aggregate_field_leaves(tcx, &cx, &element_layout) {
            Ok(info) if info.has_fat_pointer_leaf => return Ok(None),
            Err(_) => return Ok(None),
            Ok(_) => {}
        }
    }
    let ty_and_layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("array memory layout_of failed: {e:?}"))?;
    let size = ty_and_layout.layout.size().bytes();
    let align = ty_and_layout.layout.align().bytes();
    if size == 0 {
        return Ok(None);
    }
    let slot_ty = memory_slot_lane_ty(size, align)?;
    Ok(Some(MemoryAggregateLayout {
        slot_ty,
        size,
        align,
        tag: None,
        // Fat-pointer-leaf elements are excluded above (`Ok(true) => return
        // Ok(None)`), so this array's elements never contain one.
        has_fat_pointer_leaf: false,
        // This array shape is unrelated to the struct-nested-enum-leaf
        // admission (`compute_memory_backed_locals` rule 0d only consults
        // `memory_aggregate_layout`, not this address-taken-array helper).
        has_nested_enum_leaf: false,
        has_nested_niche_enum_leaf: false,
    }))
}

/// The memory-slot layout for ANY memory-backed local: a boundary-crossing slice
/// fat pointer (`{ Ptr, I64 }`), an address-taken scalar-element array, or a
/// `memory_aggregate_layout` struct/enum aggregate. This is the single source of
/// truth every slot-allocation / load / store / ABI helper consults so the three
/// memory-backed local kinds share one slot machinery.
fn memory_backed_local_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    if let Some(layout) = real_vec_string_header_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    if is_slice_or_str_fat_ptr_ty(ty) {
        return Ok(Some(fat_ptr_memory_layout()));
    }
    // LOCKSTEP with `fat_ptr_or_memory_aggregate_layout`: the transparent
    // wide-slice newtype chain gets the same `{ data, len }` slot on the SLOT
    // side — the entry block stores both incoming lanes into it
    // (`store_incoming_aggregate_param`), a call destination binds the pair
    // result into it, the return loads both lanes out of it. Two spellings of
    // one type is the `[TCG-REGALLOC-063]` `Box<dyn>` lesson.
    if let Some(layout) = wide_slice_carrier_layout(tcx, ty) {
        return Ok(Some(layout));
    }
    // A reference / raw pointer to a slice-tail DST (`&ByteStr`, `&CStr`,
    // `&Wtf8`, `&PolymorphicIter<[MaybeUninit<char>]>`): the SAME 16-byte /
    // 8-aligned `{ data, len }` slot as a slice fat pointer, because rustc lays it
    // out as the same `ScalarPair` with the same metadata kind. Listed here rather
    // than left to the generic `memory_aggregate_layout` below, which would descend
    // into the UNSIZED pointee and fail closed (that decline is what the 46-root
    // DST diagnosis was read off).
    if is_slice_tail_dst_ref_ty(tcx, ty) {
        return Ok(Some(fat_ptr_memory_layout()));
    }
    // A `&dyn Trait` / `&mut dyn Trait` / `*const dyn Trait` BORROWED trait
    // object: the SAME 16-byte / 8-aligned two-lane slot as a slice fat pointer,
    // with the vtable pointer in lane 1 instead of a length. A `&dyn` local is
    // ordinarily scalarized into its two projected halves and needs no slot; it
    // reaches here only when something takes its ADDRESS (`&d` where
    // `d: &dyn Debug` — what `format!("{:?}", d)` passes), because a pair of SSA
    // values has no address. Listed beside the `Box<dyn>` arm below because they
    // are the same image; the generic `memory_aggregate_layout` cannot produce it
    // (it would descend into the unsized `dyn` pointee and fail).
    if is_trait_object_reference_ty(ty) {
        return Ok(Some(fat_ptr_memory_layout()));
    }
    // A `Box<dyn Trait>` owning fat pointer: a 16-byte / 8-aligned `{ data,
    // vtable }` slot, identical in shape to a slice `{ data, len }` fat pointer.
    // Address-taken box locals — the `&box` receiver of a `Box<dyn Fn>` blanket
    // `call` — are memory-backed through this slot, into which
    // `lower_box_trait_object_unsize_into_memory` stores the halves.
    //
    // This arm used to claim the generic `memory_aggregate_layout` "would descend
    // into the unsized `dyn` field and fail". It does NOT: measured 2026-09-14, the
    // generic walk produces a `Box<dyn>` layout of its own — `memory_slot_lane_ty
    // (16, 8)` — and `fat_ptr_or_memory_aggregate_layout` (the SIGNATURE side) has
    // no `Box<dyn>` arm and reaches it. That is exactly how a by-value `Box<dyn>`
    // parameter came to have two spellings, `[TCG-REGALLOC-063]`. Both sides now
    // spell the slot through `memory_slot_lane_ty`; this arm stays only so the
    // slot's `fat_pointer` bookkeeping is the fat-pointer one.
    if box_dyn_dynamic_data(tcx, ty).is_some() {
        return Ok(Some(fat_ptr_memory_layout()));
    }
    // A `(&[T], &[T])` split-tuple: a raw byte slot covering both `{ data, len }`
    // halves (laid out as I64 lanes; each half is two 8-byte lanes). The general
    // `memory_aggregate_layout` rejects it (its fields are `ScalarPair` fat
    // pointers, not single scalars), so it is handled here from the rustc layout.
    if slice_pair_tuple_layout(tcx, ty)?.is_some() {
        let layout = tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
            .map_err(|e| format!("split_at tuple slot layout_of failed: {e:?}"))?;
        let size = layout.size.bytes();
        let align = layout.align.bytes();
        return Ok(Some(MemoryAggregateLayout {
            slot_ty: memory_slot_lane_ty(size, align)?,
            size,
            align,
            tag: None,
            // Both halves of the split-tuple are themselves fat pointers.
            has_fat_pointer_leaf: true,
            has_nested_enum_leaf: false,
            has_nested_niche_enum_leaf: false,
        }));
    }
    if let Some(layout) = array_memory_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    if let Some(layout) = closure_memory_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    // A post-`StateTransform` coroutine frame: a multi-variant (resume-state)
    // enum slot. Routed here (before the named-ADT path, which only matches
    // `ty::Adt`) so the frame gets a real stack slot the resume fn reads/writes
    // its state and live locals through.
    if let Some(layout) = coroutine_memory_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    if let Some(layout) = union_memory_layout(tcx, ty)? {
        return Ok(Some(layout));
    }
    memory_aggregate_layout(tcx, ty)
}

/// The memory-slot layout for a UNION whose every field bottoms out at a memory
/// scalar leaf or a `{data, metadata}` FAT leaf (or is zero-sized) and whose size
/// fits one memory-slot lane group —
/// the `MaybeUninit<T>` shape (a union of `value: ManuallyDrop<T>` and the ZST
/// `uninit: ()`). The slot is `size` raw bytes: a union has no single active field
/// the byte machinery tracks, and every typed access goes through a pointer CAST
/// to a field type (`&raw mut u as *mut T`), so the slot is opaque storage the cast
/// pointer reads/writes. `memory_aggregate_layout` deliberately excludes unions
/// (overlapping fields have no per-field offset to scalarize); this handles the
/// address-taken union the raw-pointer paths need a real slot for. Only
/// address-taken unions are memory-backed (`compute_memory_backed_locals`), so this
/// never disturbs the by-value register/ABI union path.
fn union_memory_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<MemoryAggregateLayout>, String> {
    let ty::Adt(adt, _) = ty.kind() else {
        return Ok(None);
    };
    if !adt.is_union() {
        return Ok(None);
    }
    let cx = LayoutCx(tcx);
    let ty_and_layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("union memory layout_of failed: {e:?}"))?;
    let size = ty_and_layout.layout.size().bytes();
    let align = ty_and_layout.layout.align().bytes();
    if size == 0 {
        return Ok(None);
    }
    // Every field must bottom out at a memory scalar leaf, a two-lane fat-pointer
    // leaf, or a nested memory-eligible enum (or be zero-sized): this keeps the
    // slot to bytes the byte machinery can load/store and excludes a union with
    // an unsized / slot-modeled-collection / non-scalar-niche field (the
    // validator's `Err`). The leaf FLAGS are accumulated across the fields and
    // carried on the layout exactly as `memory_aggregate_layout` carries them
    // for a struct, so every consumer that keys on `has_fat_pointer_leaf` (the
    // unconditional memory-backing of rule 0c, the fat-leaf refusals of the
    // field-wise element stores) sees the union for what it holds.
    //
    // WHY A FAT LEAF IS ADMITTED NOW. The union's every access is a lane copy of
    // the WHOLE slot (`copy_memory_aggregate_leaves`: `size` bytes at the slot's
    // own alignment) or a raw-pointer cast to the active field's type that the
    // dedicated fat-leaf machinery then addresses at rustc's own offsets — never
    // a per-field scalar store that could tear `{data, len}`. The shape is core's
    // `flt2dec` formatting buffer, `[MaybeUninit<Part>; 4]` with `Part::Copy(&[u8])`
    // (21 `library/core` roots on x86-64), filled element by element through
    // `&mut [MaybeUninit<Part>]` and read back through `assume_init_ref`'s cast.
    //
    // Both halves are measured: `tests/bridge_corpus/fix_mem_union_fat_leaf.rs`
    // compiles and matches LLVM at `-O0` and `-O2` (slice, `str` and fat-payload-enum
    // union fields, each read back through `assume_init_ref` with the LENGTH and a
    // following scalar field in the printed value, so a one-lane store or a shifted
    // lane diverges), while `MaybeUninit::<Part>::assume_init`'s by-value transmute
    // out of the slot still fails closed at its own site with its own reason.
    let mut has_fat_pointer_leaf = false;
    let mut has_nested_enum_leaf = false;
    let mut has_nested_niche_enum_leaf = false;
    for field in 0..ty_and_layout.fields.count() {
        let field_layout = ty_and_layout.field(&cx, field);
        if field_layout.is_zst() {
            continue;
        }
        let info = validate_memory_aggregate_field_leaves(tcx, &cx, &field_layout)?;
        has_fat_pointer_leaf |= info.has_fat_pointer_leaf;
        has_nested_enum_leaf |= info.has_nested_enum_leaf;
        has_nested_niche_enum_leaf |= info.has_nested_niche_enum_leaf;
    }
    let slot_ty = memory_slot_lane_ty(size, align)?;
    Ok(Some(MemoryAggregateLayout {
        slot_ty,
        size,
        align,
        tag: None,
        has_fat_pointer_leaf,
        has_nested_enum_leaf,
        has_nested_niche_enum_leaf,
    }))
}

/// The in-memory trust-ir scalar type of a layout `Scalar` tag primitive.
fn scalar_primitive_trust_ir_ty<'tcx>(
    tcx: TyCtxt<'tcx>,
    scalar: &rustc_abi::Scalar,
) -> Result<TrustIrTy, String> {
    use rustc_abi::{Integer, Primitive};
    Ok(match scalar.primitive() {
        Primitive::Int(int, signed) => match (int, signed) {
            (Integer::I8, true) => TrustIrTy::I8,
            (Integer::I8, false) => TrustIrTy::U8,
            (Integer::I16, true) => TrustIrTy::I16,
            (Integer::I16, false) => TrustIrTy::U16,
            (Integer::I32, true) => TrustIrTy::I32,
            (Integer::I32, false) => TrustIrTy::U32,
            (Integer::I64, true) => TrustIrTy::I64,
            (Integer::I64, false) => TrustIrTy::U64,
            (Integer::I128, true) => TrustIrTy::I128,
            (Integer::I128, false) => TrustIrTy::U128,
        },
        Primitive::Float(_) => return Err("enum tag is a float".to_owned()),
        Primitive::Pointer(_) => {
            let _ = tcx;
            TrustIrTy::Ptr
        }
    })
}

/// Whether an ADDRESS-TAKEN aggregate local of type `ty` genuinely needs a memory
/// slot, i.e. it is memory-eligible AND the EXISTING scalarized-aggregate
/// reference machinery cannot already represent `&ty`. A flat scalar-leaf struct
/// / single-variant enum (e.g. `Pair { u64, u64 }`) is left to the scalarized
/// path — taking its address there is a working corpus case. Only a shape that
/// path rejects (a multi-variant Direct enum, or an aggregate with nested
/// aggregate fields) is memory-backed on address-taking.
fn memory_aggregate_address_taken_needs_slot<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    // A `Box<dyn Trait>` is an OWNING fat pointer (`{ data, vtable }`). When its
    // address is taken (`&box`/`&mut box` — the `Box<dyn Fn>::call` receiver) it
    // must live in a real 16-byte slot so the reference is a genuine address; the
    // fat-pointer halves are stored/loaded at the fat-pointer offsets. The generic
    // aggregate layout below cannot lay out the unsized `dyn` field, so recognize
    // it here explicitly (its slot layout is `memory_backed_local_layout`'s
    // fat-pointer case).
    if box_dyn_dynamic_data(tcx, ty).is_some() {
        return Ok(true);
    }
    // Must be a memory-eligible aggregate (Direct-tagged scalar-leaf enum, or a
    // scalar-leaf struct, possibly with nested aggregate fields). A type the
    // memory model does NOT support — including one whose leaves are not memory
    // scalars (e.g. `core::panic::PanicInfo`, with `&str`/fat-pointer fields, for
    // which `memory_aggregate_layout` returns `Err`) — must NOT be memory-backed
    // here; it keeps the existing path (which fails closed on its own terms). So
    // an `Err`/`None` layout means "not memory-backable".
    if !matches!(memory_aggregate_layout_shared(tcx, ty), Ok(Some(_))) {
        return Ok(false);
    }
    // The scalarized reference path can flatten this pointee (a flat scalar-leaf
    // struct / single-variant enum) -> defer to it. A `None`/`Err` flattening
    // result means it CANNOT flatten the shape (a multi-variant enum, or a nested
    // aggregate field), which is precisely when the memory model takes over; we
    // do not propagate that flattening error.
    match aggregate_reference_pointee_to_trust_ir_ty(tcx, ty) {
        Ok(Some(_)) => Ok(false),
        Ok(None) | Err(_) => Ok(true),
    }
}

/// Decide which locals are memory-backed in this body.
///
/// SAFETY / SCOPE: the existing scalarization path already represents most
/// aggregates (structs, single-variant enums, small tuples) field-wise via
/// `projected_values` + per-block phi joins, and the corpus depends on that. The
/// memory model is therefore gated to fire ONLY for the cases scalarization
/// genuinely cannot represent. Concretely a local is memory-backed iff it has a
/// supported memory-aggregate layout (Direct-tagged scalar-leaf enum, or
/// scalar-leaf struct, possibly with nested aggregate fields) AND it is one of:
///   * the function's return local `_0` (when the return is such an aggregate),
///   * the destination of a `Call` returning such an aggregate by value,
///   * a by-value aggregate PARAMETER (the incoming SysV aggregate ABI value is
///     stored into the slot at entry so the body reads it from memory), or
///   * an ADDRESS-TAKEN aggregate local — one that is the source of an
///     `Rvalue::Ref` / `Rvalue::RawPtr` (which subsumes "passed by-ref", since
///     MIR materializes a `&local` temporary before the call). The `&local` /
///     `&mut local` lowers to the slot pointer, and reads/writes through the
///     reference target the slot.
/// Every other aggregate local keeps its scalarization fast path untouched, so
/// this increment is purely additive and never steals a working case.
/// If a slice-unsize operand (`&[T; N]` -> `&[T]`) borrows a LOCAL ARRAY (`_ref = &arr`),
/// return that array local. The constructed slice's `{ data, len }` data pointer IS that
/// array's address, so the array MUST be memory-backed (materialized in a slot) — a
/// scalarized array has no address, which is exactly the "source array not materialized in
/// memory" fail-closed case in `lower_pointer_unsize`. Only the DIRECT `&array` borrow is
/// traced (the `_ref` reference local assigned `&arr` with no projection, `arr` an array);
/// an indirect / projected / field borrow returns `None` and keeps the existing
/// fail-closed behaviour — forcing materialization is never a miscompile, only an enabler.
fn slice_unsize_source_array_local<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    operand: &Operand<'tcx>,
) -> Option<Local> {
    let ref_local = match operand {
        Operand::Copy(p) | Operand::Move(p) if p.projection.is_empty() => p.local,
        _ => return None,
    };
    for bb in body.basic_blocks.indices() {
        for stmt in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &stmt.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if dst.local != ref_local || !dst.projection.is_empty() {
                continue;
            }
            if let Rvalue::Ref(_, _, place) = rvalue {
                if place.projection.is_empty() {
                    let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
                    if matches!(ty.kind(), ty::Array(..)) {
                        return Some(place.local);
                    }
                }
            }
        }
    }
    None
}

/// Recognize `<[T; N] as Index<RangeFull>>::index(&arr, ..)` and the mutable
/// `<[T; N] as IndexMut<RangeFull>>::index_mut(&mut arr, ..)` — the un-inlined
/// (`-Copt-level=0`) forms of `&arr[..]` / `&mut arr[..]` over a LOCAL ARRAY. Both
/// yield the WHOLE-array slice `{ data: &arr, len: N }` with `N` statically known,
/// so they are lowered exactly as the inlined-at-O3 `&arr as &[T]` / `&mut arr as
/// &mut [T]` `PointerCoercion::Unsize` (`lower_pointer_unsize` keys off the
/// DESTINATION fat-pointer type — `&[T]` vs `&mut [T]` — so the SAME `{data, len}`
/// store serves both; the mutable destination simply additionally permits element
/// WRITES through the slot's data pointer). Matched ONLY for a `RangeFull` index
/// over an array receiver:
///   * a bounded `Range` / `RangeFrom` / ... is a runtime offset+len SUBSLICE this
///     whole-slice path does not compute (returns `false` → fail-closed, never a
///     wrong-length slice).
///
/// (An earlier experiment that BROADENED `lower_pointer_unsize` itself to special-
/// case the mutable destination regressed the working O3 `&mut` slice; the correct
/// fix — done here — leaves `lower_pointer_unsize` untouched and merely recognizes
/// the `index_mut` CALL at O0, where the destination type already distinguishes the
/// mutable slice. At O3 there is NO such call — `&mut arr[..]` inlines straight to a
/// `PointerCoercion::Unsize` statement — so this recognizer never fires at O3 and
/// cannot perturb the inlined path.)
fn is_full_slice_index_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    instance: ty::Instance<'tcx>,
) -> Result<bool, String> {
    let li = ctx.tcx.lang_items();
    // The resolved instance is usually the IMPL method (`<[T; N] as Index<RangeFull>>::index`),
    // for which `trait_of_assoc` is `None`; map it back to its trait method first (as
    // `is_from_residual_method` does), then take that method's trait. A trait-method def-id
    // resolves directly via `trait_of_assoc`.
    let def_id = instance.def_id();
    let trait_def_id = ctx.tcx.trait_of_assoc(def_id).or_else(|| {
        ctx.tcx
            .opt_associated_item(def_id)
            .and_then(|item| item.trait_item_def_id())
            .and_then(|trait_method| ctx.tcx.trait_of_assoc(trait_method))
    });
    let Some(trait_def_id) = trait_def_id else {
        return Ok(false);
    };
    // The shared `Index` operator (`&a[..]`) OR the mutable `IndexMut` operator
    // (`&mut a[..]`). Both route through the whole-slice unsize; `lower_pointer_unsize`
    // distinguishes the `&[T]` vs `&mut [T]` destination, and the mutable element-write
    // path goes through the resulting `{data, len}` slot exactly as for a `&mut [T]`
    // PARAMETER. (At O3 neither appears as a CALL — both inline to a `PointerCoercion::
    // Unsize` statement — so this recognizer is O0-only and cannot perturb the inlined path.)
    if Some(trait_def_id) != li.index_trait() && Some(trait_def_id) != li.index_mut_trait() {
        return Ok(false);
    }
    if call.args.len() != 2 {
        return Ok(false);
    }
    // The index argument must be `RangeFull` (whole-array slice; `len = N` static). A bounded
    // range yields a runtime offset+len subslice this whole-slice unsize does NOT compute.
    let idx_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let is_range_full = matches!(
        idx_ty.kind(),
        ty::Adt(adt, _) if Some(adt.did()) == li.range_full_struct()
    );
    if !is_range_full {
        return Ok(false);
    }
    // The receiver must be a reference to an ARRAY (`&[T; N]` / `&mut [T; N]`): the slice's
    // length is then the array's static length and its data pointer is the array's address.
    let recv_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let referent = match recv_ty.kind() {
        ty::Ref(_, t, _) => *t,
        _ => return Ok(false),
    };
    Ok(matches!(referent.kind(), ty::Array(..)))
}

/// Recognize `<[T; N] as Index<Range<usize>>>::index(&arr, start..end)` and the
/// mutable `<[T; N] as IndexMut<Range<usize>>>::index_mut(&mut arr, start..end)` —
/// the un-inlined (`-Copt-level=0`) BOUNDED subslice `&arr[i..j]` / `&mut arr[i..j]`
/// over a LOCAL ARRAY. The std array impl body unsizes `&arr -> &[T]` internally
/// (which the bridge cannot materialize: the impl's `&[T; N]` parameter has no
/// runtime slot), so we intercept the CALL in the caller and compute the subslice
/// `{ data: &arr + start*size, len: end - start }` directly — including the same
/// `start <= end <= N` bounds trap the impl raises — never descending into the
/// failing std impl.
///
/// Matched ONLY for a `Range<usize>` index over a `&[T; N]` array receiver:
///   * the index must be the half-open `Range` (the `RangeFrom` / `RangeTo` /
///     `RangeInclusive` variants encode a different field set and are not handled
///     here — they keep their fail-closed path, never a wrong-offset slice);
///   * the receiver must be a reference to an ARRAY (its static length `N` is the
///     upper bound; its slot address is the subslice's data base).
/// Anything else returns `false` (fail closed). At `-Copt-level=3` the subslice is
/// inlined to `Offset`/`RawPtr`-from-parts and never appears as such a CALL, so this
/// recognizer is O0-only.
fn is_local_array_range_subslice_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    instance: ty::Instance<'tcx>,
) -> Result<bool, String> {
    let li = ctx.tcx.lang_items();
    let def_id = instance.def_id();
    // Map the resolved IMPL method back to its trait (as `is_full_slice_index_call`).
    let trait_def_id = ctx.tcx.trait_of_assoc(def_id).or_else(|| {
        ctx.tcx
            .opt_associated_item(def_id)
            .and_then(|item| item.trait_item_def_id())
            .and_then(|trait_method| ctx.tcx.trait_of_assoc(trait_method))
    });
    let Some(trait_def_id) = trait_def_id else {
        return Ok(false);
    };
    if Some(trait_def_id) != li.index_trait() && Some(trait_def_id) != li.index_mut_trait() {
        return Ok(false);
    }
    if call.args.len() != 2 {
        return Ok(false);
    }
    // The index argument must be a half-open `Range<usize>` (a single integer index
    // leaf). `range_index_ty` returns the index type `T` for `Range<T>` with an
    // integer `T`; require `usize` (slice indices are `usize`).
    let idx_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let Some(index_ty) = range_index_ty(ctx.tcx, idx_ty) else {
        return Ok(false);
    };
    if !matches!(index_ty.kind(), ty::Uint(ty::UintTy::Usize)) {
        return Ok(false);
    }
    // The receiver must be a reference to an ARRAY `[T; N]` (the local-array case;
    // a `&[T]` slice receiver is the working `<[T] as Index<Range>>::index` std path
    // and is NOT intercepted here).
    let recv_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let referent = match recv_ty.kind() {
        ty::Ref(_, t, _) => *t,
        _ => return Ok(false),
    };
    if !matches!(referent.kind(), ty::Array(..)) {
        return Ok(false);
    }
    // The destination must be a bare slice fat pointer (`&[T]` / `&mut [T]`).
    if !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let dest_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, call.destination.local));
    Ok(is_slice_or_str_fat_ptr_ty(dest_ty))
}

/// Which `str` range-subslice form an intercepted `<str as Index<R>>::index`
/// call is (see `str_range_subslice_index_kind`). `RangeFull` is deliberately
/// ABSENT: `&s[..]` is an identity passthrough whose std impl already lowers
/// via the general path — intercepting it would replace a working path.
#[derive(Clone, Copy)]
enum StrSubsliceKind {
    /// `&s[a..b]` — `Range<usize>`: start = field 0, end = field 1.
    Range,
    /// `&s[a..]` — `RangeFrom<usize>`: start = field 0, end = the receiver len.
    From,
    /// `&s[..b]` — `RangeTo<usize>`: start = 0, end = field 0.
    To,
}

/// Recognize a `<str as Index<Range<usize> | RangeFrom<usize> | RangeTo<usize>>>::
/// index(&s, r)` call yielding a bare `&str` fat pointer — the un-inlined
/// (`-Copt-level=0`) `&s[a..b]` / `&s[a..]` / `&s[..b]`. The std impl subtree
/// (`core::str::traits` impl → `get` → `Option<&str>`) fails closed in this
/// backend: the `Option<&str>` intermediate is an aggregate with a fat
/// `ScalarPair` leaf the single-typed-access memory model rejects
/// (`validate_memory_aggregate_field_leaves`). So — like the array-subslice and
/// `split_at` interceptions above — the caller computes the subslice directly,
/// with the SAME order/bounds/char-boundary panics the std impl raises.
///
/// Gating is airtight without any name/crate matching:
///   * the resolved instance must map back to the `Index` LANG ITEM trait
///     (coherence forbids any user impl of `Index<R>` for `str`, so a match is
///     exactly the core impl); `IndexMut` is deliberately NOT matched for now —
///     the `&mut str` receiver representation is untested here, and index_mut
///     simply keeps its fail-closed path (never a wrong value);
///   * the receiver referent must be `ty::Str` (slice/array/Vec receivers are
///     structurally excluded and keep their existing arms);
///   * the index must be a usize-indexed `Range`/`RangeFrom`/`RangeTo` lang-item
///     struct — `RangeFull` falls through to its WORKING identity-passthrough
///     path, and `RangeInclusive`/`RangeToInclusive` keep their fail-closed path;
///   * the destination must be a bare (unprojected) str/slice fat pointer.
/// At `-Copt-level>=2` the subslice inlines to `Offset`/`RawPtr` statements with
/// no such CALL, so this recognizer is O0-only and cannot perturb that path.
fn str_range_subslice_index_kind<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    instance: ty::Instance<'tcx>,
) -> Result<Option<StrSubsliceKind>, String> {
    let li = ctx.tcx.lang_items();
    let def_id = instance.def_id();
    // Map the resolved IMPL method back to its trait (as `is_full_slice_index_call`).
    let trait_def_id = ctx.tcx.trait_of_assoc(def_id).or_else(|| {
        ctx.tcx
            .opt_associated_item(def_id)
            .and_then(|item| item.trait_item_def_id())
            .and_then(|trait_method| ctx.tcx.trait_of_assoc(trait_method))
    });
    let Some(trait_def_id) = trait_def_id else {
        return Ok(None);
    };
    if Some(trait_def_id) != li.index_trait() {
        return Ok(None);
    }
    if call.args.len() != 2 {
        return Ok(None);
    }
    // The receiver must be a reference whose referent is `str`.
    let recv_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let ty::Ref(_, referent, _) = recv_ty.kind() else {
        return Ok(None);
    };
    if !matches!(referent.kind(), ty::Str) {
        return Ok(None);
    }
    // The destination must be a bare str/slice fat pointer.
    if !call.destination.projection.is_empty() {
        return Ok(None);
    }
    let dest_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, call.destination.local));
    if !is_slice_or_str_fat_ptr_ty(dest_ty) {
        return Ok(None);
    }
    // The index type selects the form. `RangeFull` and the inclusive ranges fall
    // through (`Ok(None)`): RangeFull already works, the inclusive forms stay
    // fail-closed.
    let idx_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let ty::Adt(adt, args) = idx_ty.kind() else {
        return Ok(None);
    };
    let did = Some(adt.did());
    let kind = if did == li.range_struct() {
        StrSubsliceKind::Range
    } else if did == li.range_from_struct() {
        StrSubsliceKind::From
    } else if did == li.range_to_struct() {
        StrSubsliceKind::To
    } else {
        return Ok(None);
    };
    // The range's index type must be `usize` (the only `SliceIndex<str>` impls,
    // but gate structurally rather than assume).
    if !matches!(args.type_at(0).kind(), ty::Uint(ty::UintTy::Usize)) {
        return Ok(None);
    }
    Ok(Some(kind))
}

/// Recognize a `<Vec<T> as Index/IndexMut<R>>::index(_mut)(&vec, range)` call that
/// yields a BARE slice fat pointer at `-Copt-level=0` — the un-inlined `&vec[..k]`,
/// `&vec[k..]`, `&vec[..]` (and their `&mut` forms). The std `Vec` impl derefs
/// `&**self -> &[T]` and forwards to the slice range-index; lowering that NESTED
/// fat-pointer return at O0 drops the subslice LENGTH (the returned `{data, len}` slot
/// keeps `len = 0`/garbage), so `RangeTo`/`RangeFrom`/`RangeFull` silently miscompile
/// (wrong `len()`, out-of-bounds `iter()` → SIGSEGV). The bounded `Range` /
/// `RangeInclusive` variants already fail closed deeper in the impl (Struct-typed
/// pointer arithmetic on the fat pointer is an unsupported x86-64 opcode), so this
/// recognizer makes the WHOLE Vec-receiver slice-subslice family fail closed uniformly
/// rather than let three of its members return a wrong value. Found by the FUZZ-2
/// differential sweep (`&v[..k].len()` == 0 vs 5 at O0).
///
/// NARROW by construction:
///   * receiver referent must be `Vec<T>` (the `alloc::vec::Vec` diagnostic item) — a
///     `&[T]` slice receiver is the WORKING `<[T] as Index<..>>::index` std path and a
///     `&[T; N]` array receiver is handled by the interceptors above; neither matches.
///   * the destination must be a bare slice/str fat pointer, so single-element
///     `vec[i]` (which yields `&T`, a thin pointer) never matches.
/// At `-Copt-level>=2` the subslice inlines to `Offset`/`RawPtr`-from-parts with no
/// such CALL, so this recognizer is O0-only and cannot perturb the optimized path.
fn is_vec_subslice_index_fatptr_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    instance: ty::Instance<'tcx>,
) -> Result<bool, String> {
    let li = ctx.tcx.lang_items();
    let def_id = instance.def_id();
    // Map the resolved IMPL method back to its trait (as `is_full_slice_index_call`).
    let trait_def_id = ctx.tcx.trait_of_assoc(def_id).or_else(|| {
        ctx.tcx
            .opt_associated_item(def_id)
            .and_then(|item| item.trait_item_def_id())
            .and_then(|trait_method| ctx.tcx.trait_of_assoc(trait_method))
    });
    let Some(trait_def_id) = trait_def_id else {
        return Ok(false);
    };
    if Some(trait_def_id) != li.index_trait() && Some(trait_def_id) != li.index_mut_trait() {
        return Ok(false);
    }
    if call.args.len() != 2 {
        return Ok(false);
    }
    // The destination must be a BARE slice/str fat pointer (`&[T]` / `&mut [T]` /
    // `&str`). Single-element `vec[i]` yields `&T` (thin) and never matches.
    if !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let dest_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, call.destination.local));
    if !is_slice_or_str_fat_ptr_ty(dest_ty) {
        return Ok(false);
    }
    // The receiver must be a reference to a `Vec<T>` (the miscompiling deref-to-slice
    // case). A `&[T]` / `&[T; N]` receiver is handled elsewhere and stays untouched.
    let recv_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let referent = match recv_ty.kind() {
        ty::Ref(_, t, _) => *t,
        _ => return Ok(false),
    };
    Ok(matches!(
        referent.kind(),
        ty::Adt(adt, _) if std_def_is_interceptable(ctx.tcx, adt.did())
            && Some(adt.did()) == ctx.tcx.get_diagnostic_item(rustc_span::sym::Vec)
    ))
}

/// Which `Range*` form a `&vec[..]` subslice uses. Unlike `str` there are no
/// char-boundary constraints — a `Vec<T>` subslice is pure `{data + start*size,
/// end - start}` address arithmetic gated only by `start <= end <= len`, so it is
/// sound for EVERY element type (no element is read or stored, unlike the
/// slot-model move handler which must gate on integer-<=64-bit elements).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum VecSubsliceKind {
    Range, // &v[a..b]
    From,  // &v[a..]
    To,    // &v[..b]
    Full,  // &v[..]
}

/// Recognize a `<Vec<T> as Index/IndexMut<Range*>>::index(_mut)(&vec, range)` call
/// that yields a BARE slice fat pointer at `-Copt-level=0` and classify its range
/// form (the sibling of `str_range_subslice_index_kind`). Returns `Some(kind)` for
/// the four half-open/full forms this backend now lowers directly; `None` for the
/// `RangeInclusive`/`RangeToInclusive` forms (which keep the fail-closed path in
/// the caller, `is_vec_subslice_index_fatptr_call`) and for any non-matching call.
fn vec_range_subslice_index_kind<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    instance: ty::Instance<'tcx>,
) -> Result<Option<VecSubsliceKind>, String> {
    let li = ctx.tcx.lang_items();
    let def_id = instance.def_id();
    let trait_def_id = ctx.tcx.trait_of_assoc(def_id).or_else(|| {
        ctx.tcx
            .opt_associated_item(def_id)
            .and_then(|item| item.trait_item_def_id())
            .and_then(|trait_method| ctx.tcx.trait_of_assoc(trait_method))
    });
    let Some(trait_def_id) = trait_def_id else {
        return Ok(None);
    };
    if Some(trait_def_id) != li.index_trait() && Some(trait_def_id) != li.index_mut_trait() {
        return Ok(None);
    }
    if call.args.len() != 2 {
        return Ok(None);
    }
    if !call.destination.projection.is_empty() {
        return Ok(None);
    }
    let dest_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, call.destination.local));
    if !is_slice_or_str_fat_ptr_ty(dest_ty) {
        return Ok(None);
    }
    let recv_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let referent = match recv_ty.kind() {
        ty::Ref(_, t, _) => *t,
        _ => return Ok(None),
    };
    if !matches!(
        referent.kind(),
        ty::Adt(adt, _) if std_def_is_interceptable(ctx.tcx, adt.did())
            && Some(adt.did()) == ctx.tcx.get_diagnostic_item(rustc_span::sym::Vec)
    ) {
        return Ok(None);
    }
    let idx_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let ty::Adt(adt, args) = idx_ty.kind() else {
        return Ok(None);
    };
    let did = Some(adt.did());
    let kind = if did == li.range_struct() {
        VecSubsliceKind::Range
    } else if did == li.range_from_struct() {
        VecSubsliceKind::From
    } else if did == li.range_to_struct() {
        VecSubsliceKind::To
    } else if did == li.range_full_struct() {
        VecSubsliceKind::Full
    } else {
        return Ok(None);
    };
    // The bounded forms carry a `usize` index; `RangeFull` has no type parameter.
    if kind != VecSubsliceKind::Full
        && !matches!(args.type_at(0).kind(), ty::Uint(ty::UintTy::Usize))
    {
        return Ok(None);
    }
    Ok(Some(kind))
}

/// Lower an intercepted `<Vec<T> as Index/IndexMut<Range*>>::index(_mut)(&v, r)`
/// call into the subslice `{ data + start*size_of::<T>(), end - start }` (the
/// sibling of `lower_str_range_subslice_index_call`), guarded by the SAME
/// `start <= end <= len` bounds the std `Vec`->slice deref raises. The Vec's
/// runtime `{ptr, len}` come from its slot header (`VEC_FIELD_PTR`/`VEC_FIELD_LEN`);
/// the result is pure address arithmetic — no element is dereferenced — so this is
/// sound for every element type. The `{data,len}` store precedes the checks and is
/// dead on every fail edge (the `split_at`/array-subslice precedent). `RangeFull`
/// needs no bounds check (start=0, end=len).
fn lower_vec_range_subslice_index_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    kind: VecSubsliceKind,
) -> Result<(), String> {
    if !call.destination.projection.is_empty() {
        return Err("vec subslice index into projected destination".to_owned());
    }
    let recv_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let referent = match recv_ty.kind() {
        ty::Ref(_, t, _) => ctx.monomorphize_ty(*t),
        _ => return Err("vec subslice index receiver is not a reference".to_owned()),
    };
    let element_ty = vec_element_ty(ctx.tcx, referent)
        .ok_or_else(|| "vec subslice index receiver is not a Vec".to_owned())?;
    let element_size = layout_size_of(ctx, element_ty)?;

    // The Vec's runtime `{ptr, len}` from its slot header.
    let slot_ptr = vec_self_slot_addr(ctx, body, block, &call.args[0].node)?;
    let data = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_PTR);
    let len = emit_vec_field_load(ctx, block, slot_ptr, VEC_FIELD_LEN);

    let (start, end) = match kind {
        VecSubsliceKind::Full => (emit_i64_const(ctx, block, 0), len),
        _ => {
            // O1 mir-opt folds the range to a `const Range/RangeFrom/RangeTo`
            // argument (O2/O3 pass a bare local); read the usize bound constants
            // from its image. RangeFrom/RangeTo carry their single bound at field
            // 0; Range carries start@0, end@1. A non-constant / unreadable range
            // falls through to the bare-local path unchanged.
            let range_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
            let const_field = |ctx: &MirLoweringCtx<'tcx>, i: usize| {
                read_const_range_usize_field(ctx, &call.args[1].node, range_ty, i)
            };
            let const_bounds: Option<(i64, Option<i64>)> = match kind {
                VecSubsliceKind::Range => match (const_field(ctx, 0)?, const_field(ctx, 1)?) {
                    (Some(s), Some(e)) => Some((s as i64, Some(e as i64))),
                    _ => None,
                },
                VecSubsliceKind::From => const_field(ctx, 0)?.map(|s| (s as i64, None)),
                VecSubsliceKind::To => const_field(ctx, 0)?.map(|e| (0i64, Some(e as i64))),
                VecSubsliceKind::Full => None,
            };
            if let Some((s, e_opt)) = const_bounds {
                let start = emit_i64_const(ctx, block, i128::from(s));
                let end = match e_opt {
                    Some(e) => emit_i64_const(ctx, block, i128::from(e)),
                    None => len,
                };
                (start, end)
            } else {
                let range_local = match &call.args[1].node {
                    Operand::Copy(p) | Operand::Move(p) if p.projection.is_empty() => p.local,
                    _ => {
                        return Err(
                            "vec subslice index range argument is not a bare local".to_owned()
                        );
                    }
                };
                let usize_ty = ctx.tcx.types.usize;
                let range_field = |tcx: TyCtxt<'tcx>, i: usize| {
                    Operand::Copy(Place {
                        local: range_local,
                        projection: tcx
                            .mk_place_elems(&[ProjectionElem::Field(FieldIdx::new(i), usize_ty)]),
                    })
                };
                match kind {
                    VecSubsliceKind::Range => {
                        let s = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 0))?;
                        let e = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 1))?;
                        (coerce_to_i64(ctx, block, s), coerce_to_i64(ctx, block, e))
                    }
                    VecSubsliceKind::From => {
                        let s = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 0))?;
                        (coerce_to_i64(ctx, block, s), len)
                    }
                    VecSubsliceKind::To => {
                        let e = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 0))?;
                        (emit_i64_const(ctx, block, 0), coerce_to_i64(ctx, block, e))
                    }
                    VecSubsliceKind::Full => unreachable!(),
                }
            }
        }
    };

    // TRANSLATION-VALIDATION CAPTURE (Phase P1, Range/RangeFrom/RangeTo only):
    // record the block position BEFORE the subslice computation so the exact emitted
    // trust-ir (the `emit_element_addr` Mul/Add for the result pointer, the `Sub` for
    // the result length, the two `{data,len}` lane `Store`s, and the COMBINED
    // `start <= end <= len` bounds check) can be folded + refined against
    // `vec_range_subslice_spec` after the whole statement is built. The
    // `data`/`len`/`start`/`end` values are OUTSIDE the captured slice, so the fold
    // names them symbolically as the shared inputs. `RangeFull` (no bounds check) and
    // the diverging (no-target) path never reach the push below. See
    // `push_vec_range_subslice_refinement` + the `mir_to_trust_ir` drain.
    let refine = ctx.refinements_active();
    let refine_start = block.body.len();

    let sub_data = emit_element_addr(ctx, block, data, start, element_size);
    let sub_len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: end,
            rhs: start,
        })
        .with_result(sub_len),
    );
    if !local_is_memory_backed(ctx, call.destination.local) {
        return Err("vec subslice index destination is not memory-backed".to_owned());
    }
    ctx.clear_full_place_bindings(call.destination.local);
    let dest_slot = ctx.memory_slots.get(&call.destination.local).map(|s| s.ptr);
    store_fat_ptr_slot(ctx, block, call.destination.local, sub_data, sub_len)?;

    // `RangeFull` cannot fail: std's `<RangeFull as SliceIndex<[T]>>::index`
    // returns the slice, so std has no panic site to route a failure to.
    if kind == VecSubsliceKind::Full {
        let target = call
            .target
            .ok_or("vec `RangeFull` subslice index without a return target")?;
        block.body.push(InstrNode::new(Inst::Br {
            target: BlockId::new(target.index() as u32),
            args: Vec::new(),
        }));
        return Ok(());
    }
    let fail = std_panic_route::fail_target(
        ctx,
        body,
        call,
        std_panic_route::StdFailure::Helper {
            name: "slice_index_fail",
            payload: vec![
                std_panic_route::Payload::Scalar(start, ctx.tcx.types.usize),
                std_panic_route::Payload::Scalar(end, ctx.tcx.types.usize),
                std_panic_route::Payload::Scalar(len, ctx.tcx.types.usize),
            ],
        },
    )?;
    let Some(target) = call.target else {
        block.body.push(InstrNode::new(Inst::Br {
            target: fail,
            args: Vec::new(),
        }));
        return Ok(());
    };
    let target = BlockId::new(target.index() as u32);

    // `ok = (start <=u end) && (end <=u len)` — the two conditions the std impl
    // asserts (`slice_index_order_fail` and `slice_end_index_len_fail`).
    let start_le_end = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ule,
            ty: TrustIrTy::I64,
            lhs: start,
            rhs: end,
        })
        .with_result(start_le_end),
    );
    let end_le_len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ule,
            ty: TrustIrTy::I64,
            lhs: end,
            rhs: len,
        })
        .with_result(end_le_len),
    );
    let ok = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::And,
            ty: TrustIrTy::Bool,
            lhs: start_le_end,
            rhs: end_le_len,
        })
        .with_result(ok),
    );
    // Queue the range-subslice value-refinement job over the ops JUST emitted (the
    // `CondBr` below is NOT part of the folded slice). Gated on an active refinement
    // lane; a no-op otherwise. `RangeFull` returned early above (no bounds check).
    if refine {
        if let Some(dest_slot) = dest_slot {
            use trust_cg_verify::mir_semantics::RangeForm;
            let form = match kind {
                VecSubsliceKind::Range => RangeForm::Range,
                VecSubsliceKind::From => RangeForm::RangeFrom,
                VecSubsliceKind::To => RangeForm::RangeTo,
                VecSubsliceKind::Full => unreachable!("RangeFull returned before the bounds check"),
            };
            push_vec_range_subslice_refinement(
                ctx,
                &block.body[refine_start..],
                form,
                data,
                len,
                start,
                end,
                dest_slot,
                element_size,
            );
        }
    }
    block.body.push(InstrNode::new(Inst::CondBr {
        cond: ok,
        then_target: target,
        then_args: Vec::new(),
        else_target: fail,
        else_args: Vec::new(),
    }));
    Ok(())
}

/// Lower an intercepted `<[T; N] as Index/IndexMut<Range<usize>>>::index(_mut)(&arr,
/// start..end)` call (see `is_local_array_range_subslice_call`) into the bounded
/// subslice `{ data: &arr + start*size_of::<T>(), len: end - start }`, guarded by the
/// `start <= end && end <= N` bounds check rustc's impl performs. On a bounds
/// violation control branches to std's own raise for it
/// (`std_panic_route::fail_target`: `slice_index_fail(start, end, len)` with the
/// Location std's MIR passes it, honoring the call's unwind edge); otherwise
/// the computed `{data,len}` pair is stored into the destination slice's
/// memory-backed slot and control continues to the call's success target.
/// Read a usize field (0 = start, 1 = end) out of a CONSTANT `Range`/`RangeTo`/
/// `RangeFrom` operand's in-memory image, at its rustc layout offset. O2/O3 pass
/// the range as a bare local; O1 mir-opt folds `a..b` to a `const Range { start,
/// end }` operand — this recovers the bound constants so the subslice lowerings
/// need not require a bare local. Returns `None` (caller falls closed) for any
/// non-constant / non-`Indirect` / pointer-bearing const.
fn read_const_range_usize_field<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    operand: &Operand<'tcx>,
    range_ty: Ty<'tcx>,
    field_idx: usize,
) -> Result<Option<u64>, String> {
    let Operand::Constant(constant) = operand else {
        return Ok(None);
    };
    let evaluated = ctx.eval_const_operand(constant);
    // A single-field range (`RangeTo`/`RangeFrom`, one usize bound at field 0) is
    // a bare `ConstValue::Scalar`, not an in-memory aggregate — read it directly.
    if field_idx == 0 {
        if let Some(v) = const_to_scalar_i128(&evaluated) {
            return Ok(Some(v as u64));
        }
    }
    let mir::Const::Val(ConstValue::Indirect { alloc_id, offset }, _) = evaluated else {
        return Ok(None);
    };
    let Some(GlobalAlloc::Memory(const_alloc)) = ctx.tcx.try_get_global_alloc(alloc_id) else {
        return Ok(None);
    };
    let alloc = const_alloc.inner();
    if !alloc.provenance().ptrs().is_empty() {
        return Ok(None);
    }
    let layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(range_ty))
        .map_err(|e| format!("const range layout_of failed: {e:?}"))?;
    // Each bound is one `usize`: a target pointer word (8 bytes on a 64-bit
    // target, 4 on wasm32). A window that is not exactly that word, or that runs
    // past the allocation, is not a range bound this reader models — the caller
    // falls back instead of slicing out of range.
    let cx = LayoutCx(ctx.tcx);
    if field_idx >= layout.fields.count() {
        return Ok(None);
    }
    let word = ctx.tcx.data_layout.pointer_size().bytes();
    if layout.field(&cx, field_idx).size.bytes() != word {
        return Ok(None);
    }
    let Some(base) = offset
        .bytes()
        .checked_add(layout.fields.offset(field_idx).bytes())
    else {
        return Ok(None);
    };
    let Some(end) = base.checked_add(word) else {
        return Ok(None);
    };
    let (Ok(base), Ok(end)) = (usize::try_from(base), usize::try_from(end)) else {
        return Ok(None);
    };
    if end > alloc.len() {
        return Ok(None);
    }
    let raw = alloc.inspect_with_uninit_and_ptr_outside_interpreter(base..end);
    let v = read_target_uint(ctx.tcx.data_layout.endian, raw)
        .map_err(|e| format!("const range field read failed: {e:?}"))?;
    Ok(Some(v as u64))
}

/// The `(start, end)` of a CONSTANT `Range<T>` operand over an integer `T` of
/// at most 64 bits whose trust-ir type is `idx_ir`: each endpoint read from
/// the const allocation at its rustc layout offset with `T`'s own width, and
/// decoded with `T`'s signedness (`decode_scalar_int_constant`: a signed
/// value sign-extended, an unsigned one as its non-negative value). mir-opt
/// at -O1 and above folds `a..b` with constant endpoints into one such
/// operand. `None` (the caller fails closed) for any other constant: one that
/// is not an in-memory allocation, a `Range` whose fields are not two of
/// `T`'s size, a field outside the allocation, or an allocation with an
/// uninitialized endpoint byte or any pointer provenance.
fn read_const_range_int_endpoints<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    operand: &Operand<'tcx>,
    range_ty: Ty<'tcx>,
    idx_ty: Ty<'tcx>,
    idx_ir: &TrustIrTy,
) -> Result<Option<(i128, i128)>, String> {
    let Operand::Constant(constant) = operand else {
        return Ok(None);
    };
    if !idx_ir.is_integer() || idx_ir.bit_width().map_or(true, |w| w > 64) {
        return Ok(None);
    }
    let mir::Const::Val(ConstValue::Indirect { alloc_id, offset }, _) =
        ctx.eval_const_operand(constant)
    else {
        return Ok(None);
    };
    let Some(GlobalAlloc::Memory(const_alloc)) = ctx.tcx.try_get_global_alloc(alloc_id) else {
        return Ok(None);
    };
    let alloc = const_alloc.inner();
    if !alloc.provenance().ptrs().is_empty() {
        return Ok(None);
    }
    let width = layout_size_of(ctx, idx_ty)?;
    if Some(width) != trust_ir_leaf_byte_size(idx_ir) {
        return Ok(None);
    }
    let layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(range_ty))
        .map_err(|e| format!("const range layout_of failed: {e:?}"))?;
    let cx = LayoutCx(ctx.tcx);
    if layout.fields.count() != 2 {
        return Ok(None);
    }
    let mut endpoints = [0i128; 2];
    for (field_idx, endpoint) in endpoints.iter_mut().enumerate() {
        if layout.field(&cx, field_idx).size.bytes() != width {
            return Ok(None);
        }
        let Some(base) = offset
            .bytes()
            .checked_add(layout.fields.offset(field_idx).bytes())
        else {
            return Ok(None);
        };
        let Some(end) = base.checked_add(width) else {
            return Ok(None);
        };
        let (Ok(base), Ok(end)) = (usize::try_from(base), usize::try_from(end)) else {
            return Ok(None);
        };
        if end > alloc.len()
            || !(base..end).all(|i| alloc.init_mask().get(rustc_abi::Size::from_bytes(i)))
        {
            return Ok(None);
        }
        let raw = alloc.inspect_with_uninit_and_ptr_outside_interpreter(base..end);
        let bits = read_target_uint(ctx.tcx.data_layout.endian, raw)
            .map_err(|e| format!("const range field read failed: {e:?}"))?;
        *endpoint = decode_scalar_int_constant(idx_ir, bits, width)?;
    }
    Ok(Some((endpoints[0], endpoints[1])))
}

fn lower_local_array_subslice_index_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    // The array's static length `N` and element size, from the receiver `&[T; N]`.
    let recv_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let referent = match recv_ty.kind() {
        ty::Ref(_, t, _) => ctx.monomorphize_ty(*t),
        _ => return Err("subslice index receiver is not a reference".to_owned()),
    };
    let (element_ty, array_len) = match referent.kind() {
        ty::Array(elem, len) => {
            let n = len
                .try_to_target_usize(ctx.tcx)
                .ok_or_else(|| format!("subslice array length not target-usize: {referent:?}"))?;
            (ctx.monomorphize_ty(*elem), n)
        }
        _ => return Err("subslice index receiver is not an array reference".to_owned()),
    };
    let element_size = layout_size_of(ctx, element_ty)?;

    // The data BASE pointer is the source array's slot address (the array is forced
    // memory-backed in `compute_memory_backed_locals`). The receiver operand is a
    // `&arr` / `&mut arr` whose scalar value is that slot pointer.
    let base =
        slice_unsize_source_data_ptr(ctx, body, block, &call.args[0].node)?.ok_or_else(|| {
            "subslice index source array has no data pointer (not materialized in memory)"
                .to_owned()
        })?;

    // `start` and `end` from the `Range<usize>` argument's two integer fields. Build
    // projected field operands (`range.0` = start, `range.1` = end) and lower them —
    // `lower_operand_to_value` handles both a scalarized and a memory-backed range.
    // O1 mir-opt folds `a..b` to a `const Range { start, end }` argument (O2/O3
    // pass a bare local). Read the two usize bound constants from the const's
    // image; a non-constant / unreadable range falls through to the bare-local
    // path (or its fail-closed guard) unchanged.
    let range_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let (start, end) = if let (Some(s), Some(e)) = (
        read_const_range_usize_field(ctx, &call.args[1].node, range_ty, 0)?,
        read_const_range_usize_field(ctx, &call.args[1].node, range_ty, 1)?,
    ) {
        (
            emit_i64_const(ctx, block, i128::from(s)),
            emit_i64_const(ctx, block, i128::from(e)),
        )
    } else {
        let range_local = match &call.args[1].node {
            Operand::Copy(p) | Operand::Move(p) if p.projection.is_empty() => p.local,
            _ => return Err("subslice index range argument is not a bare local".to_owned()),
        };
        let usize_ty = ctx.tcx.types.usize;
        let start_place = Operand::Copy(Place {
            local: range_local,
            projection: ctx
                .tcx
                .mk_place_elems(&[ProjectionElem::Field(FieldIdx::new(0), usize_ty)]),
        });
        let end_place = Operand::Copy(Place {
            local: range_local,
            projection: ctx
                .tcx
                .mk_place_elems(&[ProjectionElem::Field(FieldIdx::new(1), usize_ty)]),
        });
        let start = lower_operand_to_value(ctx, body, block, &start_place)?;
        let end = lower_operand_to_value(ctx, body, block, &end_place)?;
        (
            coerce_to_i64(ctx, block, start),
            coerce_to_i64(ctx, block, end),
        )
    };

    // Bounds check: `ok = (start <=u end) && (end <=u N)`. Unsigned comparisons —
    // a `usize` start/end is never negative; this rejects `start > end` (the
    // `slice_index_order_fail` panic) and `end > N` (the `slice_end_index_len_fail`
    // panic), exactly the two conditions the std impl asserts. On `!ok` we trap.
    let len_const = emit_i64_const(ctx, block, i128::from(array_len));
    let start_le_end = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ule,
            ty: TrustIrTy::I64,
            lhs: start,
            rhs: end,
        })
        .with_result(start_le_end),
    );
    let end_le_n = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ule,
            ty: TrustIrTy::I64,
            lhs: end,
            rhs: len_const,
        })
        .with_result(end_le_n),
    );
    let ok = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::And,
            ty: TrustIrTy::Bool,
            lhs: start_le_end,
            rhs: end_le_n,
        })
        .with_result(ok),
    );

    // The subslice `{ data: base + start*size, len: end - start }`.
    let data = emit_element_addr(ctx, block, base, start, element_size);
    let len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: end,
            rhs: start,
        })
        .with_result(len),
    );
    // The destination slice local is memory-backed (forced in
    // `compute_memory_backed_locals`); store the `{ data, len }` pair into its slot.
    if !local_is_memory_backed(ctx, call.destination.local) {
        return Err("subslice index destination slice is not memory-backed".to_owned());
    }
    ctx.clear_full_place_bindings(call.destination.local);
    store_fat_ptr_slot(ctx, block, call.destination.local, data, len)?;

    // Branch on the bounds check: success -> the call's target (where the `{data,len}`
    // is already stored), failure -> std's own `slice_index_fail(start, end,
    // len)` raise (`std_panic_route::fail_target`). The slot store
    // above is emitted in THIS block; it is harmless on the failure edge (the raise/
    // trap diverges before any use), and the verified ISel keeps the store ahead of
    // the branch.
    let trap_block = std_panic_route::fail_target(
        ctx,
        body,
        call,
        std_panic_route::StdFailure::Helper {
            name: "slice_index_fail",
            payload: vec![
                std_panic_route::Payload::Scalar(start, ctx.tcx.types.usize),
                std_panic_route::Payload::Scalar(end, ctx.tcx.types.usize),
                std_panic_route::Payload::Scalar(len_const, ctx.tcx.types.usize),
            ],
        },
    )?;
    match call.target {
        Some(target) => {
            block.body.push(InstrNode::new(Inst::CondBr {
                cond: ok,
                then_target: BlockId::new(target.index() as u32),
                then_args: Vec::new(),
                else_target: trap_block,
                else_args: Vec::new(),
            }));
        }
        None => {
            // No success target (a diverging call): the only way out is the trap.
            block.body.push(InstrNode::new(Inst::Br {
                target: trap_block,
                args: Vec::new(),
            }));
        }
    }
    Ok(())
}

/// Lower an intercepted `<str as Index<Range*<usize>>>::index(&s, r)` call (see
/// `str_range_subslice_index_kind`) into the subslice `{ data + start, end -
/// start }` (byte element size 1), guarded by the EXACT panic conditions
/// `core::str::traits` raises:
///
///   * `Range`  (`&s[a..b]`): `start <= end` FIRST (std's `&&` order — `s[7..2]`
///     panics on the order gate even when both indices are char boundaries),
///     then `is_char_boundary(start)`, then `is_char_boundary(end)`;
///   * `RangeFrom` (`&s[a..]`): `is_char_boundary(start)` only (end = len);
///   * `RangeTo`   (`&s[..b]`): `is_char_boundary(end)` only (start = 0).
///
/// The boundary predicate is emitted faithfully by
/// `emit_str_char_boundary_check` (core's exact truth table, byte load only on
/// the `0 < idx < len` path). Every fail edge branches to the ONE target from
/// `std_panic_route::fail_target`: std's own `slice_error_fail(s, begin, end)`
/// with the Location std's MIR passes it, which itself tells the out-of-bounds,
/// order and char-boundary cases apart exactly as std's message does.
/// The `{data,len}` result store precedes the checks but is dead on every fail
/// edge (the raise/trap diverges before any use — the split_at precedent).
fn lower_str_range_subslice_index_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    kind: StrSubsliceKind,
) -> Result<(), String> {
    if !call.destination.projection.is_empty() {
        return Err("str subslice index into projected destination".to_owned());
    }
    // The receiver `&str`'s runtime `{ data, len }` (memory-backed fat local,
    // const literal, or const-length data-only binding).
    let (data, len) = resolve_slice_source_data_len(ctx, body, block, &call.args[0].node)?;

    // `start`/`end` from the `Range*<usize>` argument's projected usize fields
    // (the array-subslice template): `Range` = {start, end}, `RangeFrom` =
    // {start}, `RangeTo` = {end}.
    // O1 mir-opt folds `a..b` to a `const Range/RangeFrom/RangeTo` (O2/O3 pass a
    // bare local). Recover the usize bound constants; a non-constant range falls
    // through to the bare-local path unchanged.
    let range_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    let const_field = |ctx: &MirLoweringCtx<'tcx>, i: usize| {
        read_const_range_usize_field(ctx, &call.args[1].node, range_ty, i)
    };
    let const_bounds: Option<(i64, Option<i64>)> = match kind {
        StrSubsliceKind::Range => match (const_field(ctx, 0)?, const_field(ctx, 1)?) {
            (Some(s), Some(e)) => Some((s as i64, Some(e as i64))),
            _ => None,
        },
        StrSubsliceKind::From => const_field(ctx, 0)?.map(|s| (s as i64, None)),
        StrSubsliceKind::To => const_field(ctx, 0)?.map(|e| (0i64, Some(e as i64))),
    };
    let (start, end) = if let Some((s, e_opt)) = const_bounds {
        let start = emit_i64_const(ctx, block, i128::from(s));
        let end = match e_opt {
            Some(e) => emit_i64_const(ctx, block, i128::from(e)),
            None => len,
        };
        (start, end)
    } else {
        let range_local = match &call.args[1].node {
            Operand::Copy(p) | Operand::Move(p) if p.projection.is_empty() => p.local,
            _ => return Err("str subslice index range argument is not a bare local".to_owned()),
        };
        let usize_ty = ctx.tcx.types.usize;
        let range_field = |tcx: TyCtxt<'tcx>, i: usize| {
            Operand::Copy(Place {
                local: range_local,
                projection: tcx
                    .mk_place_elems(&[ProjectionElem::Field(FieldIdx::new(i), usize_ty)]),
            })
        };
        match kind {
            StrSubsliceKind::Range => {
                let s = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 0))?;
                let e = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 1))?;
                (coerce_to_i64(ctx, block, s), coerce_to_i64(ctx, block, e))
            }
            StrSubsliceKind::From => {
                let s = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 0))?;
                (coerce_to_i64(ctx, block, s), len)
            }
            StrSubsliceKind::To => {
                let e = lower_operand_to_value(ctx, body, block, &range_field(ctx.tcx, 0))?;
                (emit_i64_const(ctx, block, 0), coerce_to_i64(ctx, block, e))
            }
        }
    };

    // The result pair `{ data + start, end - start }` — byte-identical to std's
    // `get_unchecked` (`slice_from_raw_parts(as_ptr().add(start),
    // unchecked_sub(end, start))`). Pure address arithmetic, no dereference;
    // stored BEFORE the checks and dead on every fail edge (split_at precedent).
    let sub_data = emit_element_addr(ctx, block, data, start, 1);
    let sub_len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: end,
            rhs: start,
        })
        .with_result(sub_len),
    );
    if !local_is_memory_backed(ctx, call.destination.local) {
        return Err("str subslice index destination is not memory-backed".to_owned());
    }
    ctx.clear_full_place_bindings(call.destination.local);
    store_fat_ptr_slot(ctx, block, call.destination.local, sub_data, sub_len)?;

    let fail = std_panic_route::fail_target(
        ctx,
        body,
        call,
        std_panic_route::StdFailure::Helper {
            name: "slice_error_fail",
            payload: vec![
                std_panic_route::Payload::Str { data, len },
                std_panic_route::Payload::Scalar(start, ctx.tcx.types.usize),
                std_panic_route::Payload::Scalar(end, ctx.tcx.types.usize),
            ],
        },
    )?;
    let Some(target) = call.target else {
        // No success target (a diverging call): the only way out is the fail edge.
        block.body.push(InstrNode::new(Inst::Br {
            target: fail,
            args: Vec::new(),
        }));
        return Ok(());
    };
    let target = BlockId::new(target.index() as u32);

    // Enter the check chain: `Range` gates on `start <=u end` FIRST (std's
    // `slice_index_order_fail` condition precedes the boundary tests in the
    // `&&` chain); `RangeFrom`/`RangeTo` go straight to their one boundary check.
    let chain_id = ctx.fresh_block_id();
    match kind {
        StrSubsliceKind::Range => {
            let order_ok = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::ICmp {
                    op: ICmpOp::Ule,
                    ty: TrustIrTy::I64,
                    lhs: start,
                    rhs: end,
                })
                .with_result(order_ok),
            );
            block.body.push(InstrNode::new(Inst::CondBr {
                cond: order_ok,
                then_target: chain_id,
                then_args: Vec::new(),
                else_target: fail,
                else_args: Vec::new(),
            }));
        }
        StrSubsliceKind::From | StrSubsliceKind::To => {
            block.body.push(InstrNode::new(Inst::Br {
                target: chain_id,
                args: Vec::new(),
            }));
        }
    }
    // Boundary checks, per kind: `Range` -> start then end; `RangeFrom` -> start
    // (end = len is a boundary by definition); `RangeTo` -> end (start = 0 ditto).
    let mut cur = Block::new(chain_id);
    match kind {
        StrSubsliceKind::Range => {
            cur = emit_str_char_boundary_check(ctx, cur, data, len, start, fail);
            cur = emit_str_char_boundary_check(ctx, cur, data, len, end, fail);
        }
        StrSubsliceKind::From => {
            cur = emit_str_char_boundary_check(ctx, cur, data, len, start, fail);
        }
        StrSubsliceKind::To => {
            cur = emit_str_char_boundary_check(ctx, cur, data, len, end, fail);
        }
    }
    cur.body.push(InstrNode::new(Inst::Br {
        target,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(cur);
    Ok(())
}

/// `core::str::is_char_boundary(idx)` as control flow, branching to `fail` when
/// `idx` is NOT a boundary. Truth table (exactly core's, `core/src/str/mod.rs`):
///
///   * `idx == 0` or `idx == len` -> boundary;
///   * `idx > len` -> NOT a boundary (no byte is loaded);
///   * `0 < idx < len` -> boundary iff `(s.as_bytes()[idx] as i8) >= -64`
///     (`u8::is_utf8_char_boundary` — false exactly for the UTF-8 continuation
///     bytes `0b10xxxxxx`).
///
/// The byte load is emitted ONLY on the `0 < idx < len` path, so no
/// out-of-bounds read ever executes (an empty-`""` receiver's possibly-dangling
/// data pointer is never dereferenced). Consumes `entry` (pushed to
/// `ctx.extra_blocks`) and returns the open continuation block reached when
/// `idx` IS a boundary.
fn emit_str_char_boundary_check(
    ctx: &mut MirLoweringCtx<'_>,
    mut entry: Block,
    data: ValueId,
    len: ValueId,
    idx: ValueId,
    fail: BlockId,
) -> Block {
    // edge = (idx == 0) | (idx == len) -> boundary without touching memory.
    let zero = emit_i64_const(ctx, &mut entry, 0);
    let is_zero = ctx.fresh_value();
    entry.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: TrustIrTy::I64,
            lhs: idx,
            rhs: zero,
        })
        .with_result(is_zero),
    );
    let is_len = ctx.fresh_value();
    entry.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Eq,
            ty: TrustIrTy::I64,
            lhs: idx,
            rhs: len,
        })
        .with_result(is_len),
    );
    let edge = ctx.fresh_value();
    entry.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Or,
            ty: TrustIrTy::Bool,
            lhs: is_zero,
            rhs: is_len,
        })
        .with_result(edge),
    );
    let guard_id = ctx.fresh_block_id();
    let load_id = ctx.fresh_block_id();
    let next_id = ctx.fresh_block_id();
    entry.body.push(InstrNode::new(Inst::CondBr {
        cond: edge,
        then_target: next_id,
        then_args: Vec::new(),
        else_target: guard_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(entry);

    // guard: idx <u len, else fail (covers idx > len with NO byte read;
    // idx == len already succeeded above).
    let mut guard = Block::new(guard_id);
    let in_bounds = ctx.fresh_value();
    guard.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ult,
            ty: TrustIrTy::I64,
            lhs: idx,
            rhs: len,
        })
        .with_result(in_bounds),
    );
    guard.body.push(InstrNode::new(Inst::CondBr {
        cond: in_bounds,
        then_target: load_id,
        then_args: Vec::new(),
        else_target: fail,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(guard);

    // load: b = *(data + idx); boundary iff sext(b) >= -64.
    let mut loadb = Block::new(load_id);
    let addr = emit_element_addr(ctx, &mut loadb, data, idx, 1);
    let byte = ctx.fresh_value();
    loadb.body.push(
        InstrNode::new(Inst::Load {
            ty: TrustIrTy::I8,
            ptr: addr,
            volatile: false,
            align: None,
        })
        .with_result(byte),
    );
    let byte_i64 = ctx.fresh_value();
    loadb.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::SExt,
            src_ty: TrustIrTy::I8,
            dst_ty: TrustIrTy::I64,
            operand: byte,
        })
        .with_result(byte_i64),
    );
    let minus_64 = emit_i64_const(ctx, &mut loadb, -64);
    let not_continuation = ctx.fresh_value();
    loadb.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Sge,
            ty: TrustIrTy::I64,
            lhs: byte_i64,
            rhs: minus_64,
        })
        .with_result(not_continuation),
    );
    loadb.body.push(InstrNode::new(Inst::CondBr {
        cond: not_continuation,
        then_target: next_id,
        then_args: Vec::new(),
        else_target: fail,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(loadb);

    Block::new(next_id)
}

/// Whether `ty` is a 2-tuple `(&[T], &[T])` / `(&mut [T], &mut [T])` of SLICE FAT
/// POINTERS — the destination of an intercepted `<[T]>::split_at` /
/// `split_at_mut`. The fields are themselves `ScalarPair` fat pointers (so the
/// general `memory_aggregate_layout` rejects this tuple, since its leaves are not
/// single scalars), but the bridge can address each field as a `{ data, len }`
/// pair at the field's byte offset. Returns the element type `T` (shared by both
/// halves) and the two field byte offsets from the rustc layout.
fn slice_pair_tuple_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<(Ty<'tcx>, u64, u64)>, String> {
    let ty::Tuple(elems) = ty.kind() else {
        return Ok(None);
    };
    if elems.len() != 2 {
        return Ok(None);
    }
    // Both fields must be `&[T]` / `&mut [T]` slice fat pointers over the SAME
    // element type (the two halves of one split).
    let pointee0 = fat_ptr_slice_or_str_pointee(tcx, elems[0]);
    let pointee1 = fat_ptr_slice_or_str_pointee(tcx, elems[1]);
    let (Some(p0), Some(p1)) = (pointee0, pointee1) else {
        return Ok(None);
    };
    if p0 != p1 {
        return Ok(None);
    }
    // Reject a `&str` half (a `&[u8]`-shaped fat pointer with no `[T]` element):
    // `fat_ptr_slice_or_str_pointee` returns `u8` for `&str`, which is fine, but
    // `split_at` on `&str` returns `(&str, &str)` whose halves we still address as
    // `{data, len}` pairs — element size 1 — so this is acceptable. We keep both
    // halves' pointee equal above, which `&str`/`&str` satisfies.
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("split_at tuple layout_of failed: {e:?}"))?;
    let off0 = layout.fields.offset(0).bytes();
    let off1 = layout.fields.offset(1).bytes();
    Ok(Some((p0, off0, off1)))
}

/// Recognize an inherent SLICE method `<[T]>::first` / `<[T]>::last` /
/// `<[T]>::split_at` / `<[T]>::split_at_mut` over a `&[T]` / `&mut [T]` receiver.
/// Returns the method name if so (and the receiver is a slice fat pointer); else
/// `None` (the caller falls through to the general path). These inherent methods
/// live in `core` (`core::slice::<impl [T]>::first` etc.), so the std-crate gate
/// plus a slice-receiver check distinguishes them from a user method of the same
/// name on a user type, AND from the `Iterator::last` TERMINAL (whose receiver is
/// an iterator, not a slice fat pointer — so `iter.last()` is NOT matched here).
/// Recognize a `<[T; N]>::map(self, f)` call — a std/core callee named `map` whose
/// receiver (arg 0) is a fixed-size ARRAY `[T; N]` passed by value. The array self type
/// distinguishes it from `Iterator::map` (self = an iterator adapter), `Option::map` /
/// `Result::map` (self = an enum), and every user `map` method.
fn is_array_map_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    if callee_item_name_str(ctx.tcx, callee.def_id()).as_str() != "map" {
        return Ok(false);
    }
    if call.args.len() != 2 {
        return Ok(false);
    }
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    Ok(matches!(self_ty.kind(), ty::Array(..)))
}

/// `<[T; N]>::map(self, f)` where `f: FnMut(T) -> U`: apply `f` to each element in order,
/// producing `[U; N]`. Intercept the CALL — the real body descends into the
/// `Wrapped`/`ControlFlow` drain-guard `try_trait` machinery this backend cannot lower —
/// and synthesize `for i in 0..N { dest[i] = f(src[i]) }`. The moved source array and the
/// `[U; N]` destination are both memory-backed; the closure env is materialized ONCE
/// (loop-invariant, the `retain`/`resize_with` pattern). Each `f(src[i])` passes the
/// element BY VALUE (the closure takes `T`, not `&T`) and stores the returned `U`. `T`
/// and `U` are each a scalar whose one lane covers its layout, or a length-metadata wide
/// pointer carried as both lanes (`array_closure_elem`); a lowerable closure; else fail
/// closed.
fn lower_array_map<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 2 {
        return Err(format!("array map with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("array map into a projected destination".to_owned());
    }
    // Source `[T; N]` (moved self): element type `T` and length `N`.
    let src_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let (elem_t, n) = match src_ty.kind() {
        ty::Array(t, n) => (
            ctx.monomorphize_ty(*t),
            n.try_to_target_usize(ctx.tcx)
                .ok_or_else(|| format!("array map length not target-usize: {src_ty:?}"))?,
        ),
        _ => return Err("array map self is not an array".to_owned()),
    };
    // Destination `[U; N]`: element type `U`.
    let dest_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, call.destination.local));
    let elem_u = match dest_ty.kind() {
        ty::Array(u, _) => ctx.monomorphize_ty(*u),
        _ => return Err("array map destination is not an array".to_owned()),
    };
    // The per-element lanes of `T` (passed) and `U` (returned), and their strides.
    let (t_elem, size_t) = array_closure_elem(ctx.tcx, elem_t, "array map source")?;
    let (u_elem, size_u) = array_closure_elem(ctx.tcx, elem_u, "array map result")?;
    // The mapping closure + its env (materialized ONCE — loop-invariant; a ZST closure
    // gets a never-read placeholder). `closure_env_ptr` fails closed on an unmodeled
    // capture.
    let cty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[1].node)?);
    if !matches!(cty.kind(), ty::Closure(..)) {
        return Err("array map payload is not a closure — fail closed".to_owned());
    }
    // The callee owns `f`; the loop below runs no glue for it.
    refuse_unlowered_owned_drop(ctx.tcx, cty, "closure", "array::map")?;
    let env = if is_zero_sized_ty(ctx.tcx, cty) {
        let dummy = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: TrustIrTy::I8,
                count: None,
                align: None,
            })
            .with_result(dummy),
        );
        dummy
    } else {
        closure_env_ptr(ctx, body, block, &call.args[1].node)?
    };

    // The moved source array's storage address + the destination array's slot address
    // (both memory-backed: `compute_memory_backed_locals` forces a moved array backed,
    // and a returned `[U; N]` aggregate is slot-backed).
    let (Operand::Copy(sp) | Operand::Move(sp)) = &call.args[0].node else {
        return Err("array map self is not a place operand".to_owned());
    };
    if !sp.projection.is_empty() {
        return Err("array map self uses a projected place".to_owned());
    }
    let src = ctx
        .memory_slots
        .get(&sp.local)
        .cloned()
        .ok_or_else(|| "array map source array is not memory-backed".to_owned())?
        .ptr;
    let dest = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "array map destination array is not memory-backed".to_owned())?
        .ptr;

    let count = emit_i64_const(ctx, block, i128::from(n));
    let idx_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I64,
            count: None,
            align: None,
        })
        .with_result(idx_slot),
    );
    let zero = emit_i64_const(ctx, block, 0);
    emit_typed_store(block, idx_slot, TrustIrTy::I64, zero);
    // A wide-pointer `T` crosses the call as the `{ data, len }` slot a closure body's
    // by-value parameter declares; one slot, refilled per element, outside the loop.
    let source_arg = match t_elem {
        ArrayClosureElem::Scalar(t_ir) => ArrayMapSourceArg::Load(t_ir),
        ArrayClosureElem::LengthWidePtr => {
            ArrayMapSourceArg::WideSlot(emit_fat_ptr_arg_slot(ctx, block))
        }
    };

    let header_id = ctx.fresh_block_id();
    let body_id = ctx.fresh_block_id();
    let cont_id = ctx.fresh_block_id();
    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: Vec::new(),
    }));

    // header: `idx < N ? body : cont`.
    let mut header = Block::new(header_id);
    let idx_h = emit_typed_load(ctx, &mut header, idx_slot, TrustIrTy::I64);
    let lt = emit_i64_icmp(ctx, &mut header, ICmpOp::Slt, idx_h, count);
    header.body.push(InstrNode::new(Inst::CondBr {
        cond: lt,
        then_target: body_id,
        then_args: Vec::new(),
        else_target: cont_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(header);

    // body: `val = f(src[idx]); dest[idx] = val; idx += 1; goto header`. The source
    // element is passed BY VALUE (the closure takes `T`): a scalar is loaded, a wide
    // pointer's two lanes are copied into its argument slot. `idx` is reloaded AFTER the
    // call so a split (Invoke continuation under unwind) still addresses `dest` in the
    // continuation, where `val` is live.
    let mut bb = Block::new(body_id);
    let idx_b = emit_typed_load(ctx, &mut bb, idx_slot, TrustIrTy::I64);
    let src_addr = emit_element_addr(ctx, &mut bb, src, idx_b, size_t);
    let arg = match &source_arg {
        ArrayMapSourceArg::Load(t_ir) => emit_typed_load(ctx, &mut bb, src_addr, t_ir.clone()),
        ArrayMapSourceArg::WideSlot(slot) => {
            let (data, meta) = load_fat_ptr_at_addr(ctx, &mut bb, src_addr);
            store_fat_ptr_slot_into(ctx, &mut bb, *slot, data, meta);
            *slot
        }
    };
    let val = emit_array_closure_call(ctx, &mut bb, cty, env, vec![arg], &u_elem)?;
    let idx_b2 = emit_typed_load(ctx, &mut bb, idx_slot, TrustIrTy::I64);
    let dst_addr = emit_element_addr(ctx, &mut bb, dest, idx_b2, size_u);
    store_array_closure_result(ctx, &mut bb, dst_addr, val);
    let one = emit_i64_const(ctx, &mut bb, 1);
    let next = emit_i64_binop(ctx, &mut bb, TrustIrBinOp::Add, idx_b2, one);
    emit_typed_store(&mut bb, idx_slot, TrustIrTy::I64, next);
    bb.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(bb);

    let mut cont = Block::new(cont_id);
    emit_call_successor(&mut cont, call.target);
    ctx.extra_blocks.push(cont);
    Ok(())
}

/// Recognize a `core::array::from_fn::<T, N, F>(f)` call — a std/core callee named
/// `from_fn` whose DESTINATION is a fixed-size array `[T; N]`. The array destination
/// distinguishes it from `core::iter::from_fn` (whose result is an iterator).
fn is_array_from_fn_call<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    if callee_item_name_str(ctx.tcx, callee.def_id()).as_str() != "from_fn" {
        return Ok(false);
    }
    if call.args.len() != 1 || !call.destination.projection.is_empty() {
        return Ok(false);
    }
    let dest_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, call.destination.local));
    Ok(matches!(dest_ty.kind(), ty::Array(..)))
}

/// `core::array::from_fn::<T, N, F>(f)` where `f: FnMut(usize) -> T`: build `[T; N]` by
/// calling `f(i)` for each index `i` in order (`std::array::from_fn(|i| ...)`). Intercept
/// the CALL — the real body descends into the `Wrapped`/`ControlFlow` `try_trait` glue
/// this backend cannot lower — and synthesize `for i in 0..N { dest[i] = f(i) }`. Like
/// `<[T;N]>::map` but the closure receives the INDEX (a `usize`), not a source element,
/// so there is no source array to read. The `[T; N]` destination is forced memory-backed
/// by the `(0d-fromfn)` pre-pass entry; the closure env is materialized once
/// (loop-invariant). `T` is a scalar whose one lane covers its layout, or a
/// length-metadata wide pointer returned as both lanes (`array_closure_elem`); a
/// lowerable closure; else fail closed.
fn lower_array_from_fn<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("array from_fn with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("array from_fn into a projected destination".to_owned());
    }
    let dest_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, call.destination.local));
    let (elem_t, n) = match dest_ty.kind() {
        ty::Array(t, n) => (
            ctx.monomorphize_ty(*t),
            n.try_to_target_usize(ctx.tcx)
                .ok_or_else(|| format!("array from_fn length not target-usize: {dest_ty:?}"))?,
        ),
        _ => return Err("array from_fn destination is not an array".to_owned()),
    };
    let (t_elem, size_t) = array_closure_elem(ctx.tcx, elem_t, "array from_fn result")?;
    // The generator closure + its env (materialized ONCE — loop-invariant; a ZST closure
    // gets a never-read placeholder).
    let cty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    if !matches!(cty.kind(), ty::Closure(..)) {
        return Err("array from_fn payload is not a closure — fail closed".to_owned());
    }
    // The callee owns `cb`; the loop below runs no glue for it.
    refuse_unlowered_owned_drop(ctx.tcx, cty, "closure", "array::from_fn")?;
    let env = if is_zero_sized_ty(ctx.tcx, cty) {
        let dummy = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::Alloca {
                ty: TrustIrTy::I8,
                count: None,
                align: None,
            })
            .with_result(dummy),
        );
        dummy
    } else {
        closure_env_ptr(ctx, body, block, &call.args[0].node)?
    };

    let dest = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "array from_fn destination array is not memory-backed".to_owned())?
        .ptr;

    let count = emit_i64_const(ctx, block, i128::from(n));
    let idx_slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: TrustIrTy::I64,
            count: None,
            align: None,
        })
        .with_result(idx_slot),
    );
    let zero = emit_i64_const(ctx, block, 0);
    emit_typed_store(block, idx_slot, TrustIrTy::I64, zero);

    let header_id = ctx.fresh_block_id();
    let body_id = ctx.fresh_block_id();
    let cont_id = ctx.fresh_block_id();
    block.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: Vec::new(),
    }));

    // header: `idx < N ? body : cont`.
    let mut header = Block::new(header_id);
    let idx_h = emit_typed_load(ctx, &mut header, idx_slot, TrustIrTy::I64);
    let lt = emit_i64_icmp(ctx, &mut header, ICmpOp::Slt, idx_h, count);
    header.body.push(InstrNode::new(Inst::CondBr {
        cond: lt,
        then_target: body_id,
        then_args: Vec::new(),
        else_target: cont_id,
        else_args: Vec::new(),
    }));
    ctx.extra_blocks.push(header);

    // The closure's parameter is `usize`; pass the index in the `usize` IR lane (`U64`),
    // not the raw `I64` loop counter (the call arg type must match the callee param).
    let usize_ir = rust_ty_to_trust_ir_ty(ctx.tcx, ctx.tcx.types.usize)?;

    // body: `val = f(idx); dest[idx] = val; idx += 1; goto header`. The closure receives
    // the INDEX (a `usize`). `idx` is reloaded AFTER the call so a split (Invoke
    // continuation under unwind) still addresses `dest` in the continuation.
    let mut bb = Block::new(body_id);
    let idx_arg = emit_typed_load(ctx, &mut bb, idx_slot, usize_ir);
    let val = emit_array_closure_call(ctx, &mut bb, cty, env, vec![idx_arg], &t_elem)?;
    let idx_b2 = emit_typed_load(ctx, &mut bb, idx_slot, TrustIrTy::I64);
    let dst_addr = emit_element_addr(ctx, &mut bb, dest, idx_b2, size_t);
    store_array_closure_result(ctx, &mut bb, dst_addr, val);
    let one = emit_i64_const(ctx, &mut bb, 1);
    let next = emit_i64_binop(ctx, &mut bb, TrustIrBinOp::Add, idx_b2, one);
    emit_typed_store(&mut bb, idx_slot, TrustIrTy::I64, next);
    bb.body.push(InstrNode::new(Inst::Br {
        target: header_id,
        args: Vec::new(),
    }));
    ctx.extra_blocks.push(bb);

    let mut cont = Block::new(cont_id);
    emit_call_successor(&mut cont, call.target);
    ctx.extra_blocks.push(cont);
    Ok(())
}

/// How one array element of `<[T; N]>::map` / `core::array::from_fn` crosses the
/// hand-built closure call, as an argument or as the returned value.
#[derive(Clone)]
enum ArrayClosureElem {
    /// One trust-ir scalar whose width is the element's whole rustc layout.
    Scalar(TrustIrTy),
    /// A length-metadata wide pointer (`&str`, `&[T]`, `*const [T]`, `&CStr`,
    /// `&Path`, `NonNull<[T]>`): rustc's two-pointer-word `ScalarPair`
    /// `{ data, len }`, the length one pointer word after the data.
    /// `rust_ty_to_trust_ir_ty` types it as its data half alone, so it is carried
    /// as both lanes instead: as an argument, the `{ data, len }` slot a closure
    /// body's by-value parameter declares; as a result, rustc's two-value
    /// `PassMode::Pair` return.
    LengthWidePtr,
}

/// How `lower_array_map` hands each source element to the closure.
enum ArrayMapSourceArg {
    /// Load the element as this one scalar.
    Load(TrustIrTy),
    /// Copy the element's `{ data, len }` lanes into this argument slot.
    WideSlot(ValueId),
}

/// Classify array element type `elem` for the hand-built closure call of
/// `<[T; N]>::map` / `core::array::from_fn`, returning its lane form and its rustc
/// size (the element stride).
///
/// The single trust-ir type `rust_ty_to_trust_ir_ty` gives a value covers at most
/// one of a `ScalarPair`'s two lanes. A `ScalarPair` element is therefore admitted
/// only as a length-metadata wide pointer laid out as `{ data, len }` at offsets 0
/// and one pointer word; every other two-lane element (`&dyn Trait`, a newtype or
/// tuple around a wide pointer, `(u32, u32)`, `Option<u64>`) is refused by name. A
/// scalar element must have a lane exactly as wide as its layout, for the same
/// reason.
fn array_closure_elem<'tcx>(
    tcx: TyCtxt<'tcx>,
    elem: Ty<'tcx>,
    role: &str,
) -> Result<(ArrayClosureElem, u64), String> {
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(elem))
        .map_err(|e| format!("{role} element layout_of({elem:?}) failed: {e:?}"))?;
    let size = layout.size.bytes();
    let word = session_pointer_bytes();
    if crate::scalar_pair::view(layout.backend_repr).is_some() {
        if is_length_metadata_wide_ptr_ty(tcx, elem)
            && size == 2 * word
            && layout.align.bytes() == word
            && wide_ptr_or_carrier_metadata_offset(tcx, elem).ok() == Some(word)
        {
            return Ok((ArrayClosureElem::LengthWidePtr, size));
        }
        return Err(format!(
            "[TCG-ARRAY-ELEM-LANES] {role} element `{elem:?}` is a two-lane value (rustc \
             `ScalarPair`, {size} bytes) that is not a length-metadata `{{ data, len }}` \
             wide pointer; this intercept passes and stores an element as one scalar or as \
             a `&[T]` / `&str`-shaped pair, and one trust-ir scalar would carry only one of \
             its lanes. Failing closed rather than copying half of each element. Options: \
             (1) map over `&T` (`a.each_ref().map(..)`) or over the element's parts; (2) \
             use an explicit `for` loop over the array; (3) build this crate with the LLVM \
             backend."
        ));
    }
    let lane = rust_ty_to_trust_ir_ty(tcx, elem)
        .map_err(|e| format!("{role} element {elem:?} is not a scalar ({e}) — fail closed"))?;
    if !matches!(size, 1 | 2 | 4 | 8 | 16) {
        return Err(format!(
            "{role} element {elem:?} is not a 1/2/4/8/16-byte element — fail closed"
        ));
    }
    if let Some(lane_bytes) = trust_ir_leaf_byte_size(&lane) {
        if lane_bytes != size {
            return Err(format!(
                "[TCG-ARRAY-ELEM-LANES] {role} element `{elem:?}` occupies {size} bytes but its \
                 trust-ir value type {lane:?} is {lane_bytes} bytes; loading or storing it as \
                 that one value would drop the rest of the element. Failing closed."
            ));
        }
    }
    Ok((ArrayClosureElem::Scalar(lane), size))
}

/// A fresh `{ data, len }` slot (`fat_ptr_slot_ty`, pointer-aligned) to pass a
/// wide-pointer argument by value to a hand-built closure call.
fn emit_fat_ptr_arg_slot(ctx: &mut MirLoweringCtx<'_>, block: &mut Block) -> ValueId {
    let slot = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: fat_ptr_slot_ty(),
            count: None,
            align: Some(session_pointer_bytes()),
        })
        .with_result(slot),
    );
    slot
}

/// The value an array-element closure call returned (`emit_array_closure_call`).
enum ArrayClosureResult {
    /// One scalar of this type.
    Scalar(ValueId, TrustIrTy),
    /// The two `PassMode::Pair` values of a wide pointer, under the closure body's
    /// own return plan (lane types, carriers and byte offsets).
    WidePair(ScalarPairAbiPlan, [ValueId; 2]),
}

/// Emit `closure(env, args…)` for `<[T; N]>::map` / `core::array::from_fn`, binding
/// its result in the form `result` names.
///
/// A scalar result is the one value `emit_closure_call_n` binds; a body that returns
/// through any ABI plan (two values, a hidden buffer, a wasm32 cast carrier) is not
/// such a scalar and is refused by name. A wide-pointer result requires the body's
/// two-value `PassMode::Pair` return with the `{ data, len }` offsets of the element
/// slot it is stored into.
fn emit_array_closure_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    closure_ty: Ty<'tcx>,
    env_ptr: ValueId,
    args: Vec<ValueId>,
    result: &ArrayClosureElem,
) -> Result<ArrayClosureResult, String> {
    let instance = closure_body_instance(ctx, closure_ty)?;
    refuse_unthreaded_caller_location(ctx.tcx, instance)?;
    let callee = ctx.extern_callee(instance)?;
    refuse_hand_built_small_cast_return(ctx, instance)?;
    let pair = ctx.scalar_pair_returns.get(&instance).cloned();
    let buffer_return = ctx.sret_returns.contains_key(&instance)
        || ctx.carrier_sret_returns.contains_key(&instance);
    match result {
        ArrayClosureElem::Scalar(lane) => {
            if pair.is_some() || buffer_return {
                return Err(format!(
                    "[TCG-ARRAY-ELEM-LANES] the array closure `{}` returns its `{lane:?}` \
                     element through an ABI plan (two values or a hidden buffer), not as the \
                     one scalar this intercept binds. Failing closed.",
                    ctx.tcx.def_path_str(instance.def_id())
                ));
            }
            let value = emit_closure_call_n(ctx, block, closure_ty, env_ptr, args, lane.clone())?;
            Ok(ArrayClosureResult::Scalar(value, lane.clone()))
        }
        ArrayClosureElem::LengthWidePtr => {
            let word = session_pointer_bytes();
            let plan = pair
                .filter(|plan| {
                    !buffer_return
                        && plan.layout.size == 2 * word
                        && plan.layout.align == word
                        && plan.lanes[0].1 == 0
                        && plan.lanes[1].1 == word
                        && plan
                            .lanes
                            .iter()
                            .all(|(lane, _)| trust_ir_leaf_byte_size(lane) == Some(word))
                })
                .ok_or_else(|| {
                    format!(
                        "[TCG-ARRAY-ELEM-LANES] the array closure `{}` returns a wide-pointer \
                         element, but not as rustc's two-value `PassMode::Pair` with the \
                         `{{ data, len }}` lanes at offsets 0 and {word}; failing closed \
                         rather than storing a partial pointer.",
                        ctx.tcx.def_path_str(instance.def_id())
                    )
                })?;
            // Each argument as the bridge holds it (an element's slot for a
            // by-value aggregate); the one closure-argument builder places it
            // by `instance`'s own `FnAbi`.
            let call_args =
                closure_body_call_args_from_values(ctx, block, instance, Some(env_ptr), args)?;
            let results = [ctx.fresh_value(), ctx.fresh_value()];
            push_unwindable_intercept_call(ctx, block, callee, call_args, results);
            Ok(ArrayClosureResult::WidePair(plan, results))
        }
    }
}

/// Store an array-element closure result at its element address `dst_addr`: a
/// scalar as one value, a wide pointer as its two lanes at the plan's offsets.
fn store_array_closure_result(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    dst_addr: ValueId,
    result: ArrayClosureResult,
) {
    match result {
        ArrayClosureResult::Scalar(value, lane) => emit_typed_store(block, dst_addr, lane, value),
        ArrayClosureResult::WidePair(plan, results) => {
            for (lane, carrier) in results.into_iter().enumerate() {
                let value = plan.narrow_carrier(ctx, block, lane, carrier);
                let addr = slot_byte_ptr(ctx, block, dst_addr, plan.lanes[lane].1);
                emit_typed_store(block, addr, plan.lanes[lane].0.clone(), value);
            }
        }
    }
}

fn slice_first_last_split_method<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<Option<&'static str>, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(None);
    }
    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    let name = name.as_str();
    let which = match name {
        "first" => "first",
        "last" => "last",
        "split_at" => "split_at",
        "split_at_mut" => "split_at_mut",
        "split_first" => "split_first",
        "split_last" => "split_last",
        _ => return Ok(None),
    };
    // The receiver (arg 0) must be a `&[T]` / `&mut [T]` slice fat pointer. A
    // non-slice receiver (a user type with a `first`/`last`/`split_at` method, or
    // the `Iterator::last` terminal whose self is an iterator) is not ours.
    let Some(self_arg) = call.args.first() else {
        return Ok(None);
    };
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &self_arg.node)?);
    if fat_ptr_slice_or_str_pointee(ctx.tcx, self_ty).is_none() {
        return Ok(None);
    }
    Ok(Some(which))
}

/// Read the `{ data, len }` of a `&[T]` / `&mut [T]` slice-receiver argument (a
/// bare memory-backed fat-pointer place). Shared by the `first`/`last`/`split_at`
/// lowerings.
fn slice_receiver_data_len<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    operand: &Operand<'tcx>,
) -> Result<(ValueId, ValueId), String> {
    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
        return Err("slice method receiver is not a place operand".to_owned());
    };
    if !place.projection.is_empty() {
        return Err("slice method receiver uses a projected place".to_owned());
    }
    if !local_is_memory_backed(ctx, place.local) {
        return Err("slice method receiver is not a memory-backed slice".to_owned());
    }
    let data = load_fat_ptr_data(ctx, block, place.local)?;
    let len = load_fat_ptr_meta(ctx, block, place.local)?;
    Ok((data, len))
}

/// Which intercepted inherent `str` method a direct call is.
enum StrFatPtrMethod {
    Len,
    AsBytes,
}

/// Recognize a genuine `core::str::<impl str>::len` / `as_bytes` call: a std/core
/// callee of that name whose SINGLE argument is `&str`. The crate gate keeps every
/// user fn of the same name on its existing path; the `&str`-argument gate keeps
/// every other receiver (`&[T]` / `Vec` / `String` / user ADT) on its existing path
/// (`String::len`/`as_bytes` have their own `self_is_string` arms in
/// `lower_fmt_call`, whose self is `&String`, an ADT — never `&str`).
fn str_fat_ptr_method<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<Option<StrFatPtrMethod>, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(None);
    }
    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    let which = match name.as_str() {
        "len" => StrFatPtrMethod::Len,
        "as_bytes" => StrFatPtrMethod::AsBytes,
        _ => return Ok(None),
    };
    if call.args.len() != 1 {
        return Ok(None);
    }
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let is_str_ref = matches!(
        self_ty.kind(),
        ty::Ref(_, inner, _) if matches!(inner.kind(), ty::Str)
    );
    Ok(is_str_ref.then_some(which))
}

/// Recognize a `str::to_uppercase` / `to_lowercase` call (a std/core callee of that
/// name whose single argument is `&str`). These build a NEW heap `String` via a
/// per-char Unicode case-mapping iterator collected through a `RawVec` allocation
/// whose `ConvertVec::to_vec` helper the bridge cannot lower ("Place projection
/// field 0 before aggregate binding"); that helper is GC-dropped as unreachable,
/// leaving the emitted body to produce a GARBAGE / empty result (a SILENT
/// MISCOMPILE: `to_uppercase().len()` returns 0 or segfaults instead of the real
/// length). Full Unicode case mapping is out of scope — recognizing the call lets
/// the caller fail CLOSED (a clean compile error) rather than miscompile. Same
/// crate + `&str`-argument gating as `str_fat_ptr_method` (a user `to_uppercase`
/// or a non-`&str` receiver never matches).
fn str_case_conversion_method<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    call: &DirectCallTerminator<'_, 'tcx>,
    callee: Instance<'tcx>,
) -> Result<bool, String> {
    if !is_std_collection_method_callee(ctx.tcx, callee.def_id()) {
        return Ok(false);
    }
    let name = callee_item_name_str(ctx.tcx, callee.def_id());
    if name != "to_uppercase" && name != "to_lowercase" {
        return Ok(false);
    }
    if call.args.len() != 1 {
        return Ok(false);
    }
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    Ok(matches!(
        self_ty.kind(),
        ty::Ref(_, inner, _) if matches!(inner.kind(), ty::Str)
    ))
}

/// `true` iff `callee` is a `str::parse::<f64>()` or `<f64 as FromStr>::from_str`
/// call. The `f64` decimal-to-float parser (`core::num::dec2flt::<f64>`, the
/// Eisel-Lemire fast path + slow bignum path) is UNLOWERABLE by this backend, and
/// — unlike the `.parse::<f64>().unwrap_or(..)` shape, which SAFELY fails closed —
/// the `if let Ok(v) = s.parse::<f64>()` shape mis-lowers and its GC-dropped helper
/// ships a SIGSEGV-ing binary at EVERY opt level (the deferred-unlowerable GC-drop
/// hazard, the same class as `str::to_uppercase`). `f32` parse (`dec2flt::<f32>`)
/// IS correctly modeled (verified bit-identical vs LLVM across inputs), so ONLY
/// `f64` is matched — f32 is left enabled. Matches BOTH the `parse` entry (whose
/// first generic type is the target `F`) and the underlying `<F as
/// FromStr>::from_str` (whose first generic type is `Self == F`); a non-float
/// `from_str` (e.g. `fmt::Arguments::from_str`, integer `from_str`) has no `f64`
/// first type arg and is excluded.
fn float_parse_f64_method<'tcx>(ctx: &MirLoweringCtx<'tcx>, callee: Instance<'tcx>) -> bool {
    let tcx = ctx.tcx;
    let name = callee_item_name_str(tcx, callee.def_id());
    // The float type being parsed:
    //  * `str::parse::<F>()` — F is the method's first generic TYPE arg (present at
    //    -O0, where main calls `parse::<f64>` directly).
    //  * `<F as FromStr>::from_str` — F is the impl's SELF type (baked into the
    //    impl `impl FromStr for f64`, NOT an Instance generic arg; `.args.types()`
    //    is empty). This is the callee at -O2/-O3, where `parse` is inlined and
    //    main calls `core::num::float_parse::<impl FromStr for f64>::from_str`
    //    directly — so BOTH forms must be recognized to fail closed at every level.
    let target_ty = if name == "parse" {
        match callee.args.types().next() {
            Some(t) => ctx.monomorphize_ty(t),
            None => return false,
        }
    } else if name == "from_str" {
        let parent = tcx.parent(callee.def_id());
        if !matches!(tcx.def_kind(parent), rustc_hir::def::DefKind::Impl { .. }) {
            return false;
        }
        tcx.normalize_erasing_regions(
            ty::TypingEnv::fully_monomorphized(),
            tcx.type_of(parent).instantiate(tcx, callee.args),
        )
    } else {
        return false;
    };
    matches!(target_ty.kind(), ty::Float(ty::FloatTy::F64))
}

/// Resolve an intercepted-`str`-method RECEIVER operand (`&str`) to its runtime
/// length `ValueId`, mirroring `lower_ptr_metadata`'s resolution exactly:
///
///   * a bare MEMORY-BACKED `&str` local (the boundary-crossing case — a
///     `black_box`'d str, a `&str` parameter): the LEN lane (lane 1) of its
///     `{ data, len }` slot via `load_fat_ptr_meta` — ONLY the meta lane, no dead
///     data-lane extract.
///   * a const `&str` literal operand / a const-length side-table binding
///     (`pointer_metadata_lengths`): the compile-time length, through the SAME
///     `pointer_metadata_len_from_operand` fallback `lower_ptr_metadata` uses.
///
/// Anything else is `Err` (fail closed) — never a wrong length, and never the
/// DATA lane (lane 0 is the pointer; lane 1 is the length, the lane discipline
/// `store_fat_ptr_slot_into` writes).
fn resolve_str_receiver_len<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    operand: &Operand<'tcx>,
) -> Result<ValueId, String> {
    if let Operand::Copy(src) | Operand::Move(src) = operand {
        if src.projection.is_empty()
            && local_is_memory_backed(ctx, src.local)
            && is_slice_fat_ptr_carrier_ty(
                ctx.tcx,
                ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local)),
            )
        {
            return load_fat_ptr_meta(ctx, block, src.local);
        }
    }
    let len = pointer_metadata_len_from_operand(ctx, body, operand)
        .map_err(|e| format!("str method receiver has no resolvable length: {e}"))?;
    Ok(emit_i64_const(ctx, block, i128::from(len)))
}

/// Lower an intercepted `<str>::len(&self) -> usize`: the LEN lane (lane 1) of
/// the receiver's `{ data, len }` fat pointer — exactly what the force-inlined
/// slice form (`PtrMetadata`) reads. Destination binding mirrors `lower_vec_len`
/// (a same-width `Copy` typed with the destination's declared type).
fn lower_str_len_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("str::len with {} args", call.args.len()));
    }
    let len = resolve_str_receiver_len(ctx, body, block, &call.args[0].node)?;
    // `len()` returns `usize` (`U64`), the lane is `I64` — the same 64-bit
    // register value; bind the destination with ITS declared trust-ir type.
    let dest_ty = place_trust_ir_ty(ctx, body, call.destination).unwrap_or(TrustIrTy::I64);
    let target = prepare_assign_target(ctx, call.destination)?;
    block.body.push(
        InstrNode::new(Inst::Copy {
            ty: dest_ty,
            operand: len,
        })
        .with_result(target.value),
    );
    finish_assign_target(ctx, body, block, call.destination, target)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// Lower an intercepted `<str>::as_bytes(&self) -> &[u8]`: an IDENTITY view — at
/// the layout level `as_bytes` is a transmute (`&str` and `&[u8]` share the
/// `{ data, len }` fat-pointer repr), so the destination's pair IS the
/// receiver's. Resolve the receiver's `(data, len)` through the shared,
/// fail-closed `resolve_slice_source_data_len` and re-bind the destination slot,
/// mirroring `lower_vec_deref`'s slot binding.
fn lower_str_as_bytes_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!("str::as_bytes with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("str::as_bytes into a projected destination".to_owned());
    }
    let (data, len) = resolve_slice_source_data_len(ctx, body, block, &call.args[0].node)?;
    // The destination `&[u8]` local is memory-backed with a `{ data, len }` slot
    // (every call destination returning a slice fat pointer is — see
    // `fat_ptr_or_memory_aggregate_layout` / the call-destination slot rule).
    if !local_is_memory_backed(ctx, call.destination.local) {
        return Err("str::as_bytes destination slice is not memory-backed".to_owned());
    }
    ctx.clear_full_place_bindings(call.destination.local);
    store_fat_ptr_slot(ctx, block, call.destination.local, data, len)?;
    emit_call_successor(block, call.target);
    Ok(())
}

/// Lower `<[T]>::first(&self)` / `<[T]>::last(&self)` -> `Option<&T>`:
///
///     let n = self.len;
///     let cond = n != 0;
///     let p = first ? self.data : self.data + (n-1)*size_of::<T>();
///     Some(p) if cond else None        // niche: None == null pointer
///
/// Branchless — the `(n-1)` element address is computed unconditionally (its bytes
/// are dead when `cond` is false: the niche `None` stores the null pointer via the
/// `Select`, so the `data - size` underflow address is never dereferenced).
fn lower_slice_first_last_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    is_first: bool,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err(format!(
            "<[T]>::{} with {} args",
            if is_first { "first" } else { "last" },
            call.args.len()
        ));
    }
    if !call.destination.projection.is_empty() {
        return Err("<[T]>::first/last into projected destination".to_owned());
    }
    // Element type + size from the receiver `&[T]`.
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let element_ty = fat_ptr_slice_or_str_pointee(ctx.tcx, self_ty)
        .ok_or_else(|| "<[T]>::first/last receiver is not a slice".to_owned())?;
    let element_ty = ctx.monomorphize_ty(element_ty);
    let (element_size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    let (data, len) = slice_receiver_data_len(ctx, block, &call.args[0].node)?;
    let len = coerce_to_i64(ctx, block, len);

    // TRANSLATION-VALIDATION CAPTURE (Phase P1, first/last): record the block
    // position BEFORE the emptiness test + element-address + niche `Select`/store so
    // the exact emitted trust-ir can be folded + refined against
    // `slice_first_last_spec` after the whole statement is built. `data`/`len` are
    // OUTSIDE the captured slice, so the fold names them symbolically.
    let refine = ctx.refinements_active();
    let refine_start = block.body.len();

    // cond = len != 0 (the slice is non-empty).
    let zero = emit_i64_const(ctx, block, 0);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: len,
            rhs: zero,
        })
        .with_result(cond),
    );

    // The yielded element pointer: `first` -> data; `last` -> data + (len-1)*size.
    let ptr = if is_first {
        data
    } else {
        let one = emit_i64_const(ctx, block, 1);
        let last_idx = ctx.fresh_value();
        block.body.push(
            InstrNode::new(Inst::BinOp {
                op: TrustIrBinOp::Sub,
                ty: TrustIrTy::I64,
                lhs: len,
                rhs: one,
            })
            .with_result(last_idx),
        );
        emit_element_addr(ctx, block, data, last_idx, element_size)
    };

    // Write `Option<&T>` (niche: Some(p) = non-null p, None = null) into the
    // memory-backed destination slot.
    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::Reference { ptr },
    )?;

    if refine {
        use trust_cg_verify::mir_semantics::SliceEndKind;
        let kind = if is_first {
            SliceEndKind::First
        } else {
            SliceEndKind::Last
        };
        push_slice_first_last_refinement(
            ctx,
            &block.body[refine_start..],
            kind,
            data,
            len,
            call.destination.local,
            element_size,
        );
    }

    emit_call_successor(block, call.target);
    Ok(())
}

/// Lower `<[T]>::split_first(&self)` / `split_last(&self)` -> `Option<(&T, &[T])>`:
/// on a non-empty slice, `Some((head, tail))` where `split_first` = (first
/// element, all-but-first) and `split_last` = (last element, all-but-last); on an
/// empty slice, `None`. Pure `{ data, len }` address arithmetic (the element is
/// never loaded), so it is sound for EVERY element type. The niche-encoded
/// `Option<(&T, &[T])>` is written through `store_option_some_value`'s
/// `RefAndSlice` payload (the `&T` niche + the tail's `{data,len}` lanes).
fn lower_slice_split_first_last<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
    is_first: bool,
) -> Result<(), String> {
    if call.args.len() != 1 {
        return Err("<[T]>::split_first/last with != 1 args".to_owned());
    }
    if !call.destination.projection.is_empty() {
        return Err("<[T]>::split_first/last into projected destination".to_owned());
    }
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let element_ty = fat_ptr_slice_or_str_pointee(ctx.tcx, self_ty)
        .ok_or_else(|| "<[T]>::split_first/last receiver is not a slice".to_owned())?;
    let element_ty = ctx.monomorphize_ty(element_ty);
    let (element_size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    let (data, len) = slice_receiver_data_len(ctx, block, &call.args[0].node)?;
    let len = coerce_to_i64(ctx, block, len);

    // TRANSLATION-VALIDATION CAPTURE (Phase P1, lane 6 — split_first/split_last):
    // record the block position BEFORE the emptiness test + tail length + element
    // addresses + the RefAndSlice niche `Select`/stores so the exact emitted
    // trust-ir can be folded + refined against `split_first_last_spec` after the
    // whole statement is built. `data`/`len` are OUTSIDE the captured slice, so
    // the fold names them symbolically.
    let refine = ctx.refinements_active();
    let refine_start = block.body.len();

    // cond = len != 0 (non-empty => Some).
    let zero = emit_i64_const(ctx, block, 0);
    let cond = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ne,
            ty: TrustIrTy::I64,
            lhs: len,
            rhs: zero,
        })
        .with_result(cond),
    );

    // `tail_len = len - 1` (dead on the empty/None edge; a wrapped `-1` is unused).
    let one = emit_i64_const(ctx, block, 1);
    let tail_len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: len,
            rhs: one,
        })
        .with_result(tail_len),
    );

    // split_first: head = data[0], tail = data[1..]  -> first_ptr=data, tail_data=data+size.
    // split_last:  head = data[len-1], tail = data[..len-1] -> first_ptr=data+(len-1)*size,
    //              tail_data=data.
    let (first_ptr, tail_data) = if is_first {
        let tail_data = emit_element_addr(ctx, block, data, one, element_size);
        (data, tail_data)
    } else {
        let last_ptr = emit_element_addr(ctx, block, data, tail_len, element_size);
        (last_ptr, data)
    };

    let dest_ty = place_rust_ty(ctx, body, call.destination);
    store_option_some_value(
        ctx,
        body,
        block,
        call.destination.local,
        dest_ty,
        cond,
        OptionPayload::RefAndSlice {
            first_ptr,
            tail_data,
            tail_len,
        },
    )?;

    // Queue the lane-6 refinement job. The `Option<(&T, &[T])>` layout data is
    // re-derived INDEPENDENTLY through the same helpers the RefAndSlice arm used
    // — it already errored out above if the layout was missing, so these queries
    // succeed in practice; still every miss SKIPS (never turning a working
    // compile into an error just to capture).
    //
    // THE NICHE KEYSTONE: `niche_at_f0` is computed HERE from the LAYOUT's
    // designated tag offset (`tag.offset == f0`) — the obligations pin the
    // `ITE(len != 0, ptr, 0)` formula to that cell, NEVER to wherever the
    // emitted `Select` happened to flow — so a dropped/misplaced `Select`
    // REFUTES instead of being silently blessed.
    if refine {
        (|| -> Option<()> {
            use trust_cg_verify::mir_semantics::SliceEndKind;
            let layout = memory_aggregate_layout_shared(ctx.tcx, dest_ty)
                .ok()
                .flatten()?;
            let tag = layout.tag.clone()?;
            let MemoryTagEncoding::Niche {
                untagged_variant,
                niche_variants_start,
                niche_start,
                ..
            } = tag.encoding
            else {
                return None;
            };
            let (some_variant, none_variant, some_field_offset, some_field_ty) =
                option_some_none_variants(ctx.tcx, dest_ty).ok()?;
            if untagged_variant != some_variant {
                return None;
            }
            // The spec's `None` is the NULL (0) niche — any other encoding is
            // out of this lane's spec, so skip (sound).
            let none_rel = none_variant.as_u32() as u128 - niche_variants_start.as_u32() as u128;
            let none_niche = niche_start.wrapping_add(none_rel);
            if none_niche != 0 {
                return None;
            }
            // Recompute f0/f1 EXACTLY as the RefAndSlice arm did (the tuple's
            // LAYOUT offsets within the Option).
            let tuple_ty = ctx.monomorphize_ty(some_field_ty);
            let ty::Tuple(elems) = tuple_ty.kind() else {
                return None;
            };
            if elems.len() != 2 {
                return None;
            }
            let tuple_layout = ctx
                .tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(tuple_ty))
                .ok()?;
            let rustc_abi::FieldsShape::Arbitrary { .. } = tuple_layout.fields else {
                return None;
            };
            let f0 = some_field_offset + tuple_layout.fields.offset(0).bytes();
            let f1 = some_field_offset + tuple_layout.fields.offset(1).bytes();
            let tail_len_off = split_ends_tail_len_offset(ctx.tcx, elems[1], f1).ok()?;
            let niche_at_f0 = tag.offset == f0;
            if tag.offset != f0 && tag.offset != f1 {
                return None;
            }
            let dest_slot = ctx
                .memory_slots
                .get(&call.destination.local)
                .map(|s| s.ptr)?;
            let kind = if is_first {
                SliceEndKind::First
            } else {
                SliceEndKind::Last
            };
            push_split_ends_refinement(
                ctx,
                &block.body[refine_start..],
                kind,
                niche_at_f0,
                call.destination.local,
                dest_slot,
                f0,
                f1,
                tail_len_off,
                data,
                len,
                element_size,
            );
            Some(())
        })();
    }

    emit_call_successor(block, call.target);
    Ok(())
}

/// Lower `<[T]>::split_at(&self, mid)` / `split_at_mut(&mut self, mid)` ->
/// `(&[T], &[T])`:
///
///     assert!(mid <= self.len);                 // std panics on mid > len
///     left  = { data,                 mid };
///     right = { data + mid*size,      len - mid };
///
/// The destination tuple `(&[T], &[T])` is memory-backed (forced in
/// `compute_memory_backed_locals`) with a 4-lane `{data,len,data,len}` slot; the
/// two `{ data, len }` halves are stored at the tuple's field byte offsets. On a
/// bounds violation (`mid > len`) control branches to std's own raise for it
/// (`std_panic_route::fail_target`): `<[T]>::split_at`'s `panic!("mid > len")`
/// literal, and for a `str` receiver `str::split_at`'s
/// `slice_error_fail(self, 0, mid)`, each with the Location read from std's MIR.
fn lower_slice_split_at_call<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    call: &DirectCallTerminator<'_, 'tcx>,
) -> Result<(), String> {
    if call.args.len() != 2 {
        return Err(format!("<[T]>::split_at with {} args", call.args.len()));
    }
    if !call.destination.projection.is_empty() {
        return Err("<[T]>::split_at into projected destination".to_owned());
    }
    // Element type + size from the receiver `&[T]`.
    let self_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, &call.args[0].node)?);
    let element_ty = fat_ptr_slice_or_str_pointee(ctx.tcx, self_ty)
        .ok_or_else(|| "<[T]>::split_at receiver is not a slice".to_owned())?;
    let element_ty = ctx.monomorphize_ty(element_ty);
    let (element_size, _align) = element_layout_size_align(ctx.tcx, element_ty)?;

    // A `&str` receiver ALSO requires `is_char_boundary(mid)` — std's
    // `str::split_at` panics "byte index N is not a char boundary" when `mid`
    // falls inside a multibyte UTF-8 scalar. The plain `<[T]>::split_at` byte
    // split alone would SILENTLY return two invalid `&str` halves (a must-panic
    // program returns a value — a missing-trap miscompile). A `&[T]` receiver has
    // no such constraint (only `mid <= len`).
    let is_str = matches!(
        self_ty.kind(),
        ty::Ref(_, inner, _) if matches!(inner.kind(), ty::Str)
    );

    // The destination tuple `(&[T], &[T])` and its two field byte offsets.
    let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, call.destination));
    let (dest_elem, off0, off1) = slice_pair_tuple_layout(ctx.tcx, dest_ty)?.ok_or_else(|| {
        format!("<[T]>::split_at destination is not a (&[T], &[T]) tuple: {dest_ty:?}")
    })?;
    if ctx.monomorphize_ty(dest_elem) != element_ty {
        return Err("<[T]>::split_at destination element type mismatch".to_owned());
    }
    if !local_is_memory_backed(ctx, call.destination.local) {
        return Err("<[T]>::split_at destination tuple is not memory-backed".to_owned());
    }
    let dest_slot = ctx
        .memory_slots
        .get(&call.destination.local)
        .cloned()
        .ok_or_else(|| "<[T]>::split_at destination has no slot".to_owned())?
        .ptr;

    let (data, len) = slice_receiver_data_len(ctx, block, &call.args[0].node)?;
    let len = coerce_to_i64(ctx, block, len);

    // `mid` — the second argument (a `usize`).
    let mid = lower_operand_to_value(ctx, body, block, &call.args[1].node)?;
    let mid = coerce_to_i64(ctx, block, mid);

    // Bounds check: `ok = mid <=u len` (the `assert!(mid <= self.len())` std
    // `split_at` performs). Unsigned — a `usize` mid is never negative; this
    // rejects `mid > len`. On `!ok` we trap (matching the std panic abort).
    //
    // TRANSLATION-VALIDATION CAPTURE: record the block position BEFORE the split
    // computation so the exact emitted trust-ir (the bounds `ICmp`, the two
    // `{data,len}` lane `Store`s, `emit_element_addr`'s Mul/Add, the `Sub`)
    // can be folded and refined against `split_at_spec` after the whole statement
    // is built — see `push_split_at_refinement` and the `mir_to_trust_ir` drain.
    let refine_start = block.body.len();
    let ok = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ICmp {
            op: ICmpOp::Ule,
            ty: TrustIrTy::I64,
            lhs: mid,
            rhs: len,
        })
        .with_result(ok),
    );

    // left = { data, mid }.
    store_fat_ptr_slot_field(ctx, block, dest_slot, off0, data, mid);

    // right = { data + mid*size, len - mid }.
    let right_data = emit_element_addr(ctx, block, data, mid, element_size);
    let right_len = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: len,
            rhs: mid,
        })
        .with_result(right_len),
    );
    store_fat_ptr_slot_field(ctx, block, dest_slot, off1, right_data, right_len);

    // Queue the split_at value-refinement job over the ops JUST emitted (the
    // `CondBr`/`Br` below is NOT part of the folded slice). Gated on an active
    // refinement lane; a no-op otherwise.
    push_split_at_refinement(
        ctx,
        &block.body[refine_start..],
        data,
        len,
        mid,
        dest_slot,
        off0,
        off1,
        element_size,
    );

    // Branch on the bounds check: success -> the call's target (where the tuple is
    // already stored), failure -> std's own raise (`std_panic_route::fail_target`).
    // The slot stores above are emitted in THIS block; harmless on the failure
    // edge (the raise diverges before any use).
    //
    // `<[T]>::split_at[_mut]` fails through its `panic!("mid > len")` literal. A
    // `str` receiver fails, past the end and inside a char alike, through
    // `slice_error_fail(self, 0, mid)` (`str::split_at[_mut]`), whose message
    // std formats from the string and `mid`: the constant route would skip that
    // call and descend into a debug-only check below it.
    let failure = if is_str {
        std_panic_route::StdFailure::Helper {
            name: "slice_error_fail",
            payload: vec![
                std_panic_route::Payload::Str { data, len },
                std_panic_route::Payload::Constant(0, ctx.tcx.types.usize),
                std_panic_route::Payload::Scalar(mid, ctx.tcx.types.usize),
            ],
        }
    } else {
        std_panic_route::StdFailure::Constant
    };
    let trap_block = std_panic_route::fail_target(ctx, body, call, failure)?;
    match call.target {
        Some(target) => {
            let target_id = BlockId::new(target.index() as u32);
            if is_str {
                // `mid <= len` FIRST (an OOB `mid` is not a char boundary either, but
                // gate it explicitly so the boundary check's byte load is only reached
                // for `mid <= len`); THEN `is_char_boundary(mid)` as control flow (the
                // helper loads `bytes[mid]` ONLY on the `0 < mid < len` path, so no OOB
                // / dangling-empty-str read executes). Both violations -> the std panic.
                let bcheck_id = ctx.fresh_block_id();
                block.body.push(InstrNode::new(Inst::CondBr {
                    cond: ok,
                    then_target: bcheck_id,
                    then_args: Vec::new(),
                    else_target: trap_block,
                    else_args: Vec::new(),
                }));
                let bcheck = Block::new(bcheck_id);
                let mut cont =
                    emit_str_char_boundary_check(ctx, bcheck, data, len, mid, trap_block);
                cont.body.push(InstrNode::new(Inst::Br {
                    target: target_id,
                    args: Vec::new(),
                }));
                ctx.extra_blocks.push(cont);
            } else {
                block.body.push(InstrNode::new(Inst::CondBr {
                    cond: ok,
                    then_target: target_id,
                    then_args: Vec::new(),
                    else_target: trap_block,
                    else_args: Vec::new(),
                }));
            }
        }
        None => {
            block.body.push(InstrNode::new(Inst::Br {
                target: trap_block,
                args: Vec::new(),
            }));
        }
    }
    Ok(())
}

/// Store a `{ data, len }` fat-pointer pair into a memory slot at `field_offset`
/// (a `{data, len}` field within a larger aggregate, e.g. one half of a
/// `(&[T], &[T])` split tuple). Computes the field's byte address `slot_ptr +
/// field_offset` and reuses `store_fat_ptr_slot_into`.
fn store_fat_ptr_slot_field(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    slot_ptr: ValueId,
    field_offset: u64,
    data: ValueId,
    meta: ValueId,
) {
    let field_ptr = iter_field_addr(ctx, block, slot_ptr, field_offset);
    store_fat_ptr_slot_into(ctx, block, field_ptr, data, meta);
}

/// The `(9-join)` seeds of `compute_memory_backed_locals`: bare `&[T]` / `&str`
/// locals whose const-literal definitions carry a BRANCH-VARYING length into an
/// aggregate store. See that rule for why a `{ data, len }` slot is the
/// representation such a local needs.
///
/// The unit of decision is a COPY COMPONENT: bare slice/str locals connected by
/// whole-value `L = copy/move M` / `L = M as .. (Transmute)` edges (the -O0 temp
/// `_3 = copy _2` before `(move _3, ..)`). Rule (9) slot-backs a connected
/// component together, so it is gated together. A component qualifies only when:
///
///   * every definition of every member is `L = const <slice literal>` or an edge
///     from another member (a call destination or any other rvalue disqualifies),
///     and its const definitions span at least two blocks with at least two
///     distinct lengths (equal lengths survive the join already);
///   * some member is a bare operand of an `Adt` / `Tuple` aggregate whose
///     destination is a bare local ALREADY in `memory_backed` — the fat-leaf store
///     that refuses today;
///   * every other bare by-value use of every member is one a slot-backed slice
///     already serves: a call argument, an edge to another slice/str local, or a
///     `PtrMetadata` read. Uses THROUGH a member (`(*L)[i]`, a reborrow of `*L`)
///     are projections, not bare uses, and read the slot too;
///   * no member is a parameter or the return local (rules (1)/(2) own those).
///
/// Returns the members not already memory-backed, in index order.
fn join_carried_const_slice_locals<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    memory_backed: &HashSet<Local>,
) -> Vec<Local> {
    use rustc_middle::mir::UnOp;
    use rustc_middle::mir::visit::{MutatingUseContext, PlaceContext, Visitor};

    struct Uses<'a, 'tcx> {
        ctx: &'a MirLoweringCtx<'tcx>,
        body: &'a Body<'tcx>,
        memory_backed: &'a HashSet<Local>,
        aggregate_use: HashSet<Local>,
        disqualified: HashSet<Local>,
    }
    impl<'a, 'tcx> Visitor<'tcx> for Uses<'a, 'tcx> {
        fn visit_assign(
            &mut self,
            place: &Place<'tcx>,
            rvalue: &Rvalue<'tcx>,
            location: mir::Location,
        ) {
            let dst_is_bare_fat_slice = place.projection.is_empty()
                && is_slice_or_str_fat_ptr_ty(self.ctx.monomorphize_ty(local_rust_ty(
                    self.ctx,
                    self.body,
                    place.local,
                )));
            match rvalue {
                Rvalue::Aggregate(kind, operands) => {
                    let into_slot = place.projection.is_empty()
                        && matches!(
                            &**kind,
                            mir::AggregateKind::Adt(..) | mir::AggregateKind::Tuple
                        )
                        && self.memory_backed.contains(&place.local);
                    for operand in operands.iter() {
                        match operand {
                            Operand::Copy(src) | Operand::Move(src)
                                if src.projection.is_empty() =>
                            {
                                if into_slot {
                                    self.aggregate_use.insert(src.local);
                                } else {
                                    self.disqualified.insert(src.local);
                                }
                            }
                            other => self.visit_operand(other, location),
                        }
                    }
                }
                // Whole-value slice-to-slice edges: rule (9) slot-backs the other
                // endpoint, and `lower_memory_slice_assign` copies both lanes.
                Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                | Rvalue::Cast(
                    mir::CastKind::Transmute,
                    Operand::Copy(src) | Operand::Move(src),
                    _,
                ) if src.projection.is_empty() && dst_is_bare_fat_slice => {}
                // A length read: `ptr_metadata_len` loads lane 1 of a slot.
                Rvalue::UnaryOp(UnOp::PtrMetadata, Operand::Copy(src) | Operand::Move(src))
                    if src.projection.is_empty() => {}
                _ => self.visit_rvalue(rvalue, location),
            }
            self.visit_place(
                place,
                PlaceContext::MutatingUse(MutatingUseContext::Store),
                location,
            );
        }

        fn visit_terminator(
            &mut self,
            terminator: &mir::Terminator<'tcx>,
            location: mir::Location,
        ) {
            // A bare call argument: (3b) slot-backs every slice passed to a call.
            if let TerminatorKind::Call {
                func,
                args,
                destination,
                ..
            } = &terminator.kind
            {
                self.visit_operand(func, location);
                for arg in args.iter() {
                    match &arg.node {
                        Operand::Copy(src) | Operand::Move(src) if src.projection.is_empty() => {}
                        other => self.visit_operand(other, location),
                    }
                }
                self.visit_place(
                    destination,
                    PlaceContext::MutatingUse(MutatingUseContext::Call),
                    location,
                );
                return;
            }
            self.super_terminator(terminator, location);
        }

        fn visit_place(
            &mut self,
            place: &Place<'tcx>,
            context: PlaceContext,
            location: mir::Location,
        ) {
            // Every bare use not admitted above (and a call-destination def)
            // disqualifies. A bare `Store` is a definition, checked below.
            if place.projection.is_empty()
                && !matches!(
                    context,
                    PlaceContext::MutatingUse(MutatingUseContext::Store) | PlaceContext::NonUse(_)
                )
            {
                self.disqualified.insert(place.local);
            }
            self.super_place(place, context, location);
        }
    }

    let mut uses = Uses {
        ctx,
        body,
        memory_backed,
        aggregate_use: HashSet::new(),
        disqualified: HashSet::new(),
    };
    uses.visit_body(body);

    // Definitions of bare slice/str locals: a const literal (recorded with its
    // block and length), a whole-value edge between two such locals (unioned into
    // one component), or anything else (disqualifying).
    let is_fat_slice_local = |local: Local| {
        is_slice_or_str_fat_ptr_ty(ctx.monomorphize_ty(local_rust_ty(ctx, body, local)))
    };
    fn component_root(parent: &HashMap<Local, Local>, local: Local) -> Local {
        let mut root = local;
        while let Some(&next) = parent.get(&root) {
            root = next;
        }
        root
    }
    let mut parent: HashMap<Local, Local> = HashMap::new();
    let mut const_defs: HashMap<Local, Vec<(mir::BasicBlock, u64)>> = HashMap::new();
    let mut other_def: HashSet<Local> = HashSet::new();
    let mut members: HashSet<Local> = HashSet::new();
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (place, rvalue) = &**boxed;
            if !place.projection.is_empty() || !is_fat_slice_local(place.local) {
                continue;
            }
            let dst = place.local;
            members.insert(dst);
            match rvalue {
                Rvalue::Use(Operand::Constant(constant), _) => {
                    match ctx.eval_const_operand(constant) {
                        mir::Const::Val(ConstValue::Slice { meta, .. }, _) => {
                            const_defs.entry(dst).or_default().push((bb, meta));
                        }
                        _ => {
                            other_def.insert(dst);
                        }
                    }
                }
                Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                | Rvalue::Cast(
                    mir::CastKind::Transmute,
                    Operand::Copy(src) | Operand::Move(src),
                    _,
                ) if src.projection.is_empty() && is_fat_slice_local(src.local) => {
                    members.insert(src.local);
                    let dst_root = component_root(&parent, dst);
                    let src_root = component_root(&parent, src.local);
                    if dst_root != src_root {
                        parent.insert(dst_root, src_root);
                    }
                }
                _ => {
                    other_def.insert(dst);
                }
            }
        }
    }

    let mut components: HashMap<Local, Vec<Local>> = HashMap::new();
    for &local in &members {
        components
            .entry(component_root(&parent, local))
            .or_default()
            .push(local);
    }
    let return_local = Local::new(0);
    let mut seeds: Vec<Local> = Vec::new();
    for component in components.into_values() {
        let admissible = component.iter().all(|&local| {
            local != return_local
                && !body.args_iter().any(|arg| arg == local)
                && !other_def.contains(&local)
                && !uses.disqualified.contains(&local)
        });
        if !admissible
            || !component
                .iter()
                .any(|local| uses.aggregate_use.contains(local))
        {
            continue;
        }
        let sites: Vec<(mir::BasicBlock, u64)> = component
            .iter()
            .filter_map(|local| const_defs.get(local))
            .flatten()
            .copied()
            .collect();
        let blocks: HashSet<mir::BasicBlock> = sites.iter().map(|(bb, _)| *bb).collect();
        let lengths: HashSet<u64> = sites.iter().map(|(_, len)| *len).collect();
        if blocks.len() >= 2 && lengths.len() >= 2 {
            seeds.extend(
                component
                    .into_iter()
                    .filter(|local| !memory_backed.contains(local)),
            );
        }
    }
    seeds.sort_by_key(|local| local.index());
    seeds
}

/// Locals that FLOW BY VALUE somewhere — used as a BARE (empty-projection) whole
/// local in any non-Store, non-storage-marker context: a `Copy`/`Move` operand
/// (into a call / closure / aggregate / return), or a `&`/`&raw`/`&mut` borrow of
/// the whole local. A fat-pointer local used this way has its `{data,len}` passed
/// as a VALUE, where a memory-backed slot representation is not what the consumer
/// reads. The `(0d-slice)` memory-backing rule consults this to stay sound: it
/// memory-backs a slice-from-enum-payload local ONLY when the local is NEVER here
/// (i.e. every use is a `Deref`-based projection — index/len/iter THROUGH the slot).
/// A bare `Store` (the local's own definition) and `StorageLive`/`Dead` are benign.
fn locals_used_bare_by_value<'tcx>(body: &Body<'tcx>) -> HashSet<Local> {
    use rustc_middle::mir::UnOp;
    use rustc_middle::mir::visit::{MutatingUseContext, PlaceContext, Visitor};
    struct Scan {
        bare: HashSet<Local>,
    }
    impl<'tcx> Visitor<'tcx> for Scan {
        fn visit_rvalue(&mut self, rvalue: &Rvalue<'tcx>, location: mir::Location) {
            // `PtrMetadata(copy L)` (the bounds-check LENGTH read rustc inserts before
            // `(*L)[i]`) and `Len` read ONLY the length lane — which a memory-backed
            // slot serves correctly. A bare `L` there is NOT a by-value flow, so do not
            // descend into it (descending would flag `L` via `visit_place` and wrongly
            // exclude the common `if let Some(s){ s[i] }` case). Every OTHER rvalue is
            // walked normally, so a bare `L` in an aggregate / cast / use-into-value
            // still flags.
            if matches!(rvalue, Rvalue::UnaryOp(UnOp::PtrMetadata, _)) {
                return;
            }
            self.super_rvalue(rvalue, location);
        }
        fn visit_place(
            &mut self,
            place: &Place<'tcx>,
            context: PlaceContext,
            location: mir::Location,
        ) {
            if place.projection.is_empty() {
                let benign = matches!(
                    context,
                    PlaceContext::MutatingUse(MutatingUseContext::Store) | PlaceContext::NonUse(_)
                );
                if !benign {
                    self.bare.insert(place.local);
                }
            }
            self.super_place(place, context, location);
        }
    }
    let mut scan = Scan {
        bare: HashSet::new(),
    };
    scan.visit_body(body);
    scan.bare
}

/// A place a reference can address: a MIR local and a path into it (empty for
/// the whole local). A `Field` step is its field index; any other step before
/// the first `Deref` (an array index, a variant downcast, a subslice) is spelled
/// as [`OPAQUE_PLACE_STEP`] followed by the borrowing statement's location, so it
/// counts as a place distinct from every other borrow.
type BorrowedPlace = (Local, Vec<u32>);

const OPAQUE_PLACE_STEP: u32 = u32::MAX;

/// The most elements a derived [`BorrowedPlace`] path keeps. A reborrow of a
/// reborrow appends its own steps to its source's path, and a reborrow in a loop
/// whose source is its own previous value (`p = rest` under `[first, rest @ ..]
/// = p`, a `Subslice` of a slice of the same type) appends them once per pass,
/// so the fixpoint in [`address_identity_referents`] never converged: a single
/// such loop over a local array spun at every opt level (2026-10-08, trust-cg
/// main c5919a122; LLVM compiles it in 0.6 s). A path longer than this becomes
/// [`SATURATED_PLACE_PATH`].
const MAX_BORROWED_PLACE_PATH: usize = 24;

/// The path every over-long derived path collapses to: one place distinct from
/// every real one (a real opaque step names a reachable block, never
/// `u32::MAX`). Collapsing can merge places a deeper walk would keep apart,
/// which could only UNDER-count a base's distinct escaping places; so each
/// base whose path saturates is also reported as needing real storage
/// unconditionally (`saturated` in [`address_identity_referents`]).
const SATURATED_PLACE_PATH: [u32; 3] = [OPAQUE_PLACE_STEP, u32::MAX, u32::MAX];

/// The [`BorrowedPlace`] path of a `Deref`-free projection borrowed at `at`, or
/// `None` when the projection reads through a pointer.
fn borrowed_place_path(projection: &[mir::PlaceElem<'_>], at: mir::Location) -> Option<Vec<u32>> {
    let mut path = Vec::with_capacity(projection.len());
    for elem in projection {
        match elem {
            ProjectionElem::Field(field, _) => path.push(field.index() as u32),
            ProjectionElem::Deref => return None,
            _ => {
                path.extend([
                    OPAQUE_PLACE_STEP,
                    at.block.index() as u32,
                    at.statement_index as u32,
                ]);
                return Some(path);
            }
        }
    }
    Some(path)
}

/// ADDR-IDENTITY: the locals whose borrows would need two use-site
/// materializations with RELATED addresses, which one slot per referent
/// ([`MirLoweringCtx::borrow_homes`]) cannot give them.
///
/// A reference whose value leaves the register model — a call argument, an
/// aggregate or unsize operand, a cast, a value stored through memory, a raw
/// address — is materialized, and code that receives it can compare it or turn
/// it into an integer. Rust gives the borrowed local one address, so:
///   * borrows of TWO DIFFERENT places of one local (`&p` and `&p.a`, `&p.a` and
///     `&p.b`) that both escape need the local laid out in real storage, where
///     the places keep their layout relation;
///   * a reference that can address TWO DIFFERENT locals (`if c { &a } else
///     { &b }`) and escapes needs each of them in real storage, so the joined
///     reference is an ordinary pointer equal to the direct borrow it selects.
///
/// Returns those locals, and each reference that can address two or more
/// locals with its (sorted) referents. `compute_memory_backed_locals`
/// gives each local it can lay out a memory slot and
/// `compute_scalar_cell_locals` cells each one it can hold as a scalar leaf;
/// `borrow_home_slot` refuses what remains.
/// Borrows of one place escaping any number of times need nothing here: they
/// share that place's one borrow home.
fn address_identity_referents<'tcx>(
    body: &Body<'tcx>,
) -> (HashSet<Local>, HashMap<Local, Vec<Local>>) {
    use rustc_middle::mir::visit::{PlaceContext, Visitor};
    // `places[r]`: the places reference local `r` can address, seeded by
    // direct borrows and propagated through copies, casts and reborrows
    // (`&(*r)`, `&(*r).f`) to a fixpoint.
    let mut places: HashMap<Local, HashSet<BorrowedPlace>> = HashMap::new();
    // Bases whose derived path reached `MAX_BORROWED_PLACE_PATH`: reported as
    // needing real storage whatever the escape scan finds (see
    // `SATURATED_PLACE_PATH`). Paths are bounded, so the fixpoint terminates.
    let mut saturated: HashSet<Local> = HashSet::new();
    loop {
        let mut changed = false;
        for (bb, data) in body.basic_blocks.iter_enumerated() {
            for (statement_index, statement) in data.statements.iter().enumerate() {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                if !dst.projection.is_empty() {
                    continue;
                }
                let at = mir::Location {
                    block: bb,
                    statement_index,
                };
                let derived: Vec<BorrowedPlace> = match rvalue {
                    Rvalue::Ref(_, _, src) | Rvalue::RawPtr(_, src) => {
                        if let Some(path) = borrowed_place_path(&src.projection, at) {
                            vec![(src.local, path)]
                        } else if matches!(src.projection.first(), Some(ProjectionElem::Deref)) {
                            match (
                                borrowed_place_path(&src.projection[1..], at),
                                places.get(&src.local),
                            ) {
                                (Some(path), Some(bases)) => bases
                                    .iter()
                                    .map(|(base, prefix)| {
                                        let mut full = prefix.clone();
                                        full.extend(path.iter().copied());
                                        if full.len() > MAX_BORROWED_PLACE_PATH {
                                            saturated.insert(*base);
                                            full = SATURATED_PLACE_PATH.to_vec();
                                        }
                                        (*base, full)
                                    })
                                    .collect(),
                                _ => Vec::new(),
                            }
                        } else {
                            Vec::new()
                        }
                    }
                    Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                    | Rvalue::Cast(_, Operand::Copy(src) | Operand::Move(src), _)
                        if src.projection.is_empty() =>
                    {
                        places
                            .get(&src.local)
                            .map(|set| set.iter().cloned().collect())
                            .unwrap_or_default()
                    }
                    _ => Vec::new(),
                };
                if derived.is_empty() {
                    continue;
                }
                let entry = places.entry(dst.local).or_default();
                for place in derived {
                    changed |= entry.insert(place);
                }
            }
        }
        if !changed {
            break;
        }
    }
    if places.is_empty() {
        return (HashSet::new(), HashMap::new());
    }

    // Every reference local whose VALUE escapes: any use as a whole operand
    // except the pure `dst = copy r` edge already propagated above, plus a raw
    // address `&raw (*r)`. Reads and writes THROUGH `r` (a `Deref` projection)
    // are not escapes.
    struct Escapes<'a> {
        places: &'a HashMap<Local, HashSet<BorrowedPlace>>,
        escaped: HashSet<Local>,
    }
    impl<'tcx> Visitor<'tcx> for Escapes<'_> {
        fn visit_statement(&mut self, statement: &mir::Statement<'tcx>, location: mir::Location) {
            if let StatementKind::Assign(boxed) = &statement.kind {
                let (dst, rvalue) = &**boxed;
                if dst.projection.is_empty()
                    && matches!(
                        rvalue,
                        Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                            if src.projection.is_empty()
                    )
                {
                    return;
                }
            }
            self.super_statement(statement, location);
        }
        fn visit_rvalue(&mut self, rvalue: &Rvalue<'tcx>, location: mir::Location) {
            if let Rvalue::RawPtr(_, src) = rvalue {
                if matches!(src.projection.first(), Some(ProjectionElem::Deref))
                    && self.places.contains_key(&src.local)
                {
                    self.escaped.insert(src.local);
                }
            }
            self.super_rvalue(rvalue, location);
        }
        fn visit_operand(&mut self, operand: &Operand<'tcx>, location: mir::Location) {
            if let Operand::Copy(place) | Operand::Move(place) = operand {
                if place.projection.is_empty() && self.places.contains_key(&place.local) {
                    self.escaped.insert(place.local);
                }
            }
            self.super_operand(operand, location);
        }
        fn visit_place(&mut self, _: &Place<'tcx>, _: PlaceContext, _: mir::Location) {}
    }
    let mut scan = Escapes {
        places: &places,
        escaped: HashSet::new(),
    };
    scan.visit_body(body);

    let mut escaped_places: HashMap<Local, HashSet<Vec<u32>>> = HashMap::new();
    let mut referents: HashSet<Local> = HashSet::new();
    // Every multi-referent reference, escaping or not: a copy of one carries
    // its borrow binding (and so its materialization key) to the escaping use.
    let mut multi: HashMap<Local, Vec<Local>> = HashMap::new();
    for (reference, set) in &places {
        let mut bases: Vec<Local> = set.iter().map(|(base, _)| *base).collect();
        bases.sort_by_key(|local| local.index());
        bases.dedup();
        if bases.len() >= 2 {
            multi.insert(*reference, bases);
        }
    }
    for reference in &scan.escaped {
        let Some(set) = places.get(reference) else {
            continue;
        };
        if let Some(bases) = multi.get(reference) {
            referents.extend(bases.iter().copied());
        }
        for (base, path) in set {
            escaped_places
                .entry(*base)
                .or_default()
                .insert(path.clone());
        }
    }
    referents.extend(
        escaped_places
            .into_iter()
            .filter(|(_, paths)| paths.len() >= 2)
            .map(|(base, _)| base),
    );
    referents.extend(saturated);
    referents.remove(&mir::RETURN_PLACE);
    (referents, multi)
}

fn compute_memory_backed_locals<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
) -> Result<HashSet<Local>, String> {
    let mut locals: HashSet<Local> = HashSet::new();
    slice_tail::force_slots(ctx, body, &mut locals);
    dyn_tail::force_slots(ctx, body, &mut locals);

    // `core::fmt` plumbing locals (the `[Argument; M]` array, the `fmt::Arguments`
    // value, …) are decoded at compile time by the `format!`/`write!`
    // interception and never materialized at runtime. They must NOT be
    // memory-backed: their niche-encoded `ArgumentType` enum / `NonNull` template
    // fields have no lowerable memory layout (they would fail closed at
    // `allocate_memory_slots`). Collect them up front so the paths below can skip
    // adding them, keeping the set free of dead fmt-internal aggregates.
    //
    // Skipped only when the interception actually CLAIMED the local — i.e. it is
    // in `ctx.fmt_dead_locals`, computed before this pass for exactly this
    // question, whichever crate defines the type. A LIVE one (a
    // `Formatter`-receiver `write_fmt`'s `Arguments` chain, or `core` compiling
    // `rt::Argument::new_display` itself) gets a real slot from its rustc layout
    // and lowers instead of being silently dropped. For a body whose every
    // consumer is intercepted the dead set holds every fmt-typed local, so this
    // is unchanged for `println!` / `format!` / `write!(String, ..)`.
    let mut fmt_internal_locals: HashSet<Local> = body
        .local_decls
        .indices()
        .filter(|&l| {
            is_fmt_internal_ty(ctx.tcx, local_rust_ty(ctx, body, l))
                && ctx.fmt_dead_locals.contains(&l)
        })
        .collect();
    // The O3-inlined `format!` consumer's dead locals (the format closure, the
    // `Option<&str>` `as_str()` result) are decoded statically by the interception
    // and never used at runtime. They must NOT be memory-backed: the format
    // closure's `&Arguments` capture has no lowerable pointee layout (its niche
    // `ArgumentType` enum is not modeled), and the `Option<&str>` is dead. Fold
    // them into the skip set the cases below already consult.
    fmt_internal_locals.extend(compute_o3_format_consumer_dead_locals(ctx, body));
    for local in body.local_decls.indices() {
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if real_vec_string_header_layout(ctx.tcx, ty)?.is_some() {
            locals.insert(local);
        }
    }
    for local in call_references::address_taken_locals(ctx, body) {
        if fmt_internal_locals.contains(&local) {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if matches!(memory_backed_local_layout(ctx.tcx, ty), Ok(Some(_))) {
            locals.insert(local);
        }
    }

    // (0) Every NON-scalar (aggregate) union local (`MaybeUninit<(i64,i64)>`,
    // `MaybeUninit<[i64;3]>`, …). A non-scalar union has NO scalarized
    // representation — its overlapping fields cannot be held as disjoint
    // `projected_values`, and it has no single scalar ABI carrier — so it can ONLY
    // be realized in a real slot (its construct writes the active field's leaves at
    // offset 0, `assume_init` reads them back, a whole-union `_9 = copy _1` copies
    // the slot bytes, and it crosses a by-value ABI boundary as its slot lane tuple).
    // Forcing these memory-backed steals no working case: absent a slot the union
    // simply fails closed everywhere today. A SCALAR union (`MaybeUninit<i64>`) is
    // NOT matched (it keeps its scalar path, memory-backed only when address-taken).
    for local in body.local_decls.indices() {
        if fmt_internal_locals.contains(&local) {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if matches!(nonscalar_union_memory_layout(ctx.tcx, ty), Ok(Some(_))) {
            locals.insert(local);
        }
    }

    // (0c) Every local whose type is a `memory_aggregate_layout` aggregate
    // containing AT LEAST ONE fat-pointer (`&str`/`&[T]`) leaf field (e.g.
    // `struct Rec<'a> { name: &'a str, n: i64 }`). Such a leaf has NO
    // scalarized representation — `scalar_leaf_trust_ir_fields` explicitly
    // rejects it, and the untyped scalarization fallbacks
    // (`lower_adt_aggregate`'s per-field loop,
    // `lower_recursive_scalar_field_aggregate_operands`'s else-arm) also fail
    // closed on it rather than silently binding just the data half and
    // dropping the length — so it can ONLY be realized in a real 2-lane
    // memory slot. None of the OTHER triggers below fire for a plain
    // non-escaping local (`let r = Rec{..}` is not a return/param/call-dest/
    // address-taken local), so without this rule such a local would simply
    // fail closed everywhere (a live-probed confirmed gap: forcing
    // memory-backing here is what turns "fails closed" into "correct two-lane
    // construct/read"). Additive and safe: absent a slot, a fat-leaf-containing
    // aggregate has no working representation today at all.
    for local in body.local_decls.indices() {
        if fmt_internal_locals.contains(&local) {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if matches!(
            memory_aggregate_layout_shared(ctx.tcx, ty),
            Ok(Some(layout)) if layout.has_fat_pointer_leaf
        ) {
            locals.insert(local);
        }
    }

    // (0d) The moved array of a by-value `for x in a`: `<[T; N] as IntoIterator>::
    // into_iter(a)` returns `array::IntoIter<T, N>`, whose bridge lowering
    // (`lower_array_into_iter`) reads `a`'s slot address. A moved-by-value `[T; N]`
    // MIR local is otherwise SCALARIZED (no slot), so force it memory-backed here so
    // the interception has a stable base. Additive and safe: absent a slot the whole
    // `for x in a` fails closed today, and the array is dead after the move (it is
    // consumed by `into_iter`), so a slot steals no working case.
    for bb in body.basic_blocks.iter() {
        let Some(term) = &bb.terminator else {
            continue;
        };
        let TerminatorKind::Call {
            args, destination, ..
        } = &term.kind
        else {
            continue;
        };
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, destination));
        if array_intoiter_element_ty(ctx.tcx, dest_ty).is_none() {
            continue;
        }
        let Some(arg0) = args.first() else {
            continue;
        };
        if let Operand::Copy(p) | Operand::Move(p) = &arg0.node {
            if p.projection.is_empty()
                && matches!(
                    ctx.monomorphize_ty(local_rust_ty(ctx, body, p.local))
                        .kind(),
                    ty::Array(..)
                )
            {
                locals.insert(p.local);
            }
        }
    }

    // (0d-map) `<[T; N]>::map(self, f) -> [U; N]` (`[1,2,3].map(|x| x*x)`): the bridge
    // interception (`lower_array_map`) reads BOTH the moved source array's slot address
    // AND the destination `[U; N]` array's slot. Both are otherwise SCALARIZED (a moved
    // by-value array / a small register-returned array aggregate has no slot), so force
    // each memory-backed. PRECISELY gated to the `<[T;N]>::map` callee (a std/core
    // callee named `map` with an ARRAY arg0), so no generic array-by-value call is
    // affected. Additive: absent slots the map interception fails closed today.
    for bb in body.basic_blocks.iter() {
        let Some(term) = &bb.terminator else {
            continue;
        };
        let TerminatorKind::Call {
            func,
            args,
            destination,
            ..
        } = &term.kind
        else {
            continue;
        };
        let Some((did, name)) = call_callee_item_name(ctx, body, func) else {
            continue;
        };
        if name != "map" || !is_std_collection_method_callee(ctx.tcx, did) {
            continue;
        }
        let Some(arg0) = args.first() else {
            continue;
        };
        let (Operand::Copy(p) | Operand::Move(p)) = &arg0.node else {
            continue;
        };
        if !p.projection.is_empty()
            || !matches!(
                ctx.monomorphize_ty(local_rust_ty(ctx, body, p.local))
                    .kind(),
                ty::Array(..)
            )
        {
            continue;
        }
        // Confirmed `<[T;N]>::map`: force the source array + the destination array backed.
        locals.insert(p.local);
        if destination.projection.is_empty()
            && matches!(
                ctx.monomorphize_ty(local_rust_ty(ctx, body, destination.local))
                    .kind(),
                ty::Array(..)
            )
        {
            locals.insert(destination.local);
        }
    }

    // (0e) An aggregate local the SCALARIZED path cannot spell but the MEMORY
    // path can. The scalarized representation binds a local's leaves as
    // individual SSA values and has no spelling for an ARRAY field, so
    // `scalar_field_aggregate_trust_ir_fields` fails closed on `Ty::[T; N]`.
    //
    // This is the other half of rule 0f. Once `<[T; N] as IntoIterator>::
    // into_iter` inlines at -O2/-O3, the array-to-`MaybeUninit` transmute (0f)
    // is followed by the wrappers that CARRY the array — `PolymorphicIter`,
    // `ManuallyDrop`, `MaybeDangling` — each of which has an array field and so
    // has no scalarized form either. Both rules are needed: with only 0e the
    // transmute still declines, and with only 0f the wrapper construction does.
    //
    // The predicate is exactly "no scalarized representation, but a memory one",
    // so it cannot steal a working case: every local it adds would otherwise
    // fail closed wherever it is used. Bare arrays are excluded — they have
    // their own established handling (rules 0d / 3e and `memory_slot_lane_ty`),
    // and this must not redirect them.
    for local in body.local_decls.indices() {
        if fmt_internal_locals.contains(&local) || locals.contains(&local) {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if matches!(ty.kind(), ty::Array(..)) {
            continue;
        }
        if scalar_leaf_trust_ir_fields(ctx.tcx, ty).is_ok() {
            continue;
        }
        if matches!(memory_aggregate_layout_shared(ctx.tcx, ty), Ok(Some(_))) {
            locals.insert(local);
        }
    }

    // (0g) The slice/`str` fat-pointer DESTINATION of a projected fat-LEAF read:
    //
    //   _3 = copy ((_1 as Some).0: &[u8]);      // `<Option<&[u8]> as Try>::branch`
    //
    // `lower_memory_fat_leaf_use` loads BOTH lanes of such a leaf at rustc's own
    // offsets, but it can only install them if the destination owns a real
    // `{data, len}` slot — otherwise there is nowhere to put the pair, and it
    // deliberately falls through rather than bind the data half and SILENTLY DROP
    // THE LENGTH. A bare `&[T]` local is ordinarily scalarized (one `Ptr` value
    // plus a side-table length) and gets a slot only when its address is taken,
    // so this shape had no destination and failed closed at
    // `memory leaf type is a fat pointer (ScalarPair {data,len})`.
    //
    // Scoped to a source aggregate that actually CONTAINS a fat leaf
    // (`has_fat_pointer_leaf`), which is the whole population this serves, and to
    // a destination rustc lays out wide. Additive on the same argument as rules
    // 0c/0d/0f: absent a slot this statement fails closed TODAY, so adding one
    // steals no working case.
    //
    // The metadata-KIND match is left to `lower_memory_fat_leaf_use` (which
    // compares the walked leaf against the destination); this rule only decides
    // that a destination slot must exist, and an unused slot is exactly what an
    // address-taken local already has.
    for bb in body.basic_blocks.iter() {
        for statement in &bb.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (place, rvalue) = &**boxed;
            if !place.projection.is_empty() {
                continue;
            }
            // BOTH spellings of the same projected fat-leaf read: the
            // `Rvalue::Use` one this rule was written for, and the
            // `Rvalue::Cast(Transmute)` one the `Box<DST>` deref idiom emits
            // (`_d = copy ((_b.0: Unique<[T]>).0: NonNull<[T]>) as *const [T]`).
            // `lower_memory_slice_assign`'s `Rvalue::Cast(Transmute)` arm loads
            // the same two lanes for the second spelling, and it needs the same
            // destination slot: it is entered only for a memory-backed slice
            // destination, and a `{data, len}` slot is also the genuine ADDRESS
            // the `&raw mut (*_d)` reborrow that follows the idiom needs.
            //
            // Both halves are load-bearing and were measured separately on
            // `library/alloc`: with this rule alone the 9 roots move from
            // `aggregate reference nested field is a fat pointer` to
            // `memory-backed slice assignment Rvalue::Cast [cast Transmute ...]`
            // (they now reach that function); with the arm alone they never reach
            // it at all.
            let (Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
            | Rvalue::Cast(
                mir::CastKind::Transmute,
                Operand::Copy(src) | Operand::Move(src),
                _,
            )) = rvalue
            else {
                continue;
            };
            if src.projection.is_empty() {
                continue;
            }
            let dst_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
            if !is_length_metadata_wide_ptr_ty(ctx.tcx, dst_ty) {
                continue;
            }
            // The deref-led spelling of the transmute
            // (`_d = copy (((*r).0: Unique<[T]>).0: NonNull<[T]>) as *const [T]`,
            // `drop_glue::<Box<[T]>>`) reads its fat leaf out of the POINTEE, so
            // the pointee's layout decides; its arm in `lower_memory_slice_assign`
            // asks the same `deref_field_transmute_pointee`.
            let deref_transmute_pointee = match rvalue {
                Rvalue::Cast(mir::CastKind::Transmute, ..) => {
                    deref_field_transmute_pointee(ctx, body, src)
                }
                _ => None,
            };
            let src_base_ty = deref_transmute_pointee
                .unwrap_or_else(|| ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local)));
            let carries_fat_leaf = memory_aggregate_layout(ctx.tcx, src_base_ty)
                .ok()
                .flatten()
                .is_some_and(|layout| layout.has_fat_pointer_leaf);
            if !carries_fat_leaf {
                continue;
            }
            locals.insert(place.local);
        }
    }

    // (0h) An AGGREGATE whose REFERENCE VALUE ESCAPES. `_r = &_agg` / `&mut _agg`
    // (projection-free) where `_r` is then used as a BARE OPERAND — the reference
    // itself, not `*_r` — means the program needs `_agg`'s ADDRESS. A scalarized
    // aggregate has none (its fields are SSA values), which is exactly what
    // `RejectReason::BorrowedAggregateNoDeref` is right about:
    // "borrowed aggregate reference used without deref". Giving `_agg` a slot is
    // what makes the address exist; the reject stays for a referent that genuinely
    // cannot be memory-backed.
    //
    // Scoped to a reference whose value is USED bare. A borrow that is only ever
    // DEREFERENCED (`(*_r).f`) needs no address of its own and keeps the
    // scalarized path, so this steals no working case — and the whole shape fails
    // closed today, so a slot can only turn a refusal into a compile.
    // `<wtf8::EncodeWide as Iterator>::next` is the measured instance.
    {
        let mut ref_sources: HashMap<Local, Local> = HashMap::new();
        for bb in body.basic_blocks.iter() {
            for statement in &bb.statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                if !dst.projection.is_empty() {
                    continue;
                }
                if let Rvalue::Ref(_, _, source) | Rvalue::RawPtr(_, source) = rvalue {
                    if source.projection.is_empty() {
                        ref_sources.insert(dst.local, source.local);
                    }
                }
            }
        }
        if !ref_sources.is_empty() {
            let mut bare_used: HashSet<Local> = HashSet::new();
            let note_operand = |op: &Operand<'tcx>, out: &mut HashSet<Local>| {
                if let Operand::Copy(p) | Operand::Move(p) = op {
                    if p.projection.is_empty() {
                        out.insert(p.local);
                    }
                }
            };
            for bb in body.basic_blocks.iter() {
                for statement in &bb.statements {
                    if let StatementKind::Assign(boxed) = &statement.kind {
                        let (_, rvalue) = &**boxed;
                        match rvalue {
                            Rvalue::Use(op, _) => note_operand(op, &mut bare_used),
                            Rvalue::Aggregate(_, ops) => {
                                for op in ops.iter() {
                                    note_operand(op, &mut bare_used);
                                }
                            }
                            Rvalue::Cast(_, op, _) => note_operand(op, &mut bare_used),
                            // Reborrowing as a raw pointer also exposes the
                            // referent's address, even though MIR spells the
                            // operand with a Deref (`p = &raw const *r`).
                            Rvalue::RawPtr(_, source)
                                if matches!(
                                    source.projection.first(),
                                    Some(ProjectionElem::Deref)
                                ) =>
                            {
                                bare_used.insert(source.local);
                            }
                            _ => {}
                        }
                    }
                }
                if let mir::TerminatorKind::Call { args, .. } = &bb.terminator().kind {
                    for arg in args.iter() {
                        note_operand(&arg.node, &mut bare_used);
                    }
                }
            }
            // Visit in LOCAL order, never hash order: `memory_backed_local_layout`
            // can refuse (`[TCG-COLLECTION-IMAGE]` for an aggregate that owns a
            // `Vec`/`String`), the FIRST refusal is the one the function reports,
            // and walking the map made that refusal (and so the diagnostic) vary
            // from one compile of the same program to the next.
            let mut ref_sources: Vec<(Local, Local)> = ref_sources.into_iter().collect();
            ref_sources.sort_by_key(|(ref_local, _)| ref_local.index());
            for (ref_local, source) in ref_sources {
                if !bare_used.contains(&ref_local) || locals.contains(&source) {
                    continue;
                }
                let source_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, source));
                if memory_backed_local_layout(ctx.tcx, source_ty)?.is_some() {
                    locals.insert(source);
                }
            }
        }
    }

    // (0i) A BRANCH-VARYING slice/`str` fat pointer. A wide-pointer local whose
    // `(data, len)` the scalarized path carries as ONE `Ptr` value plus a
    // CONSTANT length in `pointer_metadata_lengths` cannot represent a local that
    // is assigned DIFFERENT slices on different paths — the length is not a
    // constant of the local, it is a constant of the branch. `core::fmt::num`'s
    // `exp_u64`/`exp_u128` hit exactly this: the exponent sign is `"+"`, `"-"` or
    // `""` (lengths 1, 1, 0) chosen by a branch, so NO single length is
    // recordable and every consumer that needs `(data, len)` — the bulk-append
    // source among them — failed closed with "no resolvable (data, len)
    // representation".
    //
    // A real `{ data, len }` SLOT represents it exactly: each branch stores its
    // own pair, and a reader loads both lanes. Scoped to a local with assignments
    // in TWO OR MORE distinct blocks, so a single-definition slice keeps its
    // existing scalar+side-table representation untouched — that is the shape the
    // corpus depends on.
    {
        let mut assign_blocks: HashMap<Local, HashSet<mir::BasicBlock>> = HashMap::new();
        for (bb, data) in body.basic_blocks.iter_enumerated() {
            for statement in &data.statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                if boxed.0.projection.is_empty() {
                    assign_blocks.entry(boxed.0.local).or_default().insert(bb);
                }
            }
        }
        // Local order, for the same reason as (0h): the layout query can refuse.
        let mut assign_blocks: Vec<(Local, HashSet<mir::BasicBlock>)> =
            assign_blocks.into_iter().collect();
        assign_blocks.sort_by_key(|(local, _)| local.index());
        for (local, blocks) in assign_blocks {
            if blocks.len() < 2 || locals.contains(&local) {
                continue;
            }
            let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
            if is_length_metadata_wide_ptr_ty(ctx.tcx, ty)
                && memory_backed_local_layout(ctx.tcx, ty)?.is_some()
            {
                locals.insert(local);
            }
        }
    }

    // (0f) Both sides of an AGGREGATE-to-AGGREGATE `Transmute`. rustc emits one
    // for `<[T; N] as IntoIterator>::into_iter` once it inlines (-O2/-O3):
    //
    //   _15 = copy _3 as [MaybeUninit<usize>; 5] (Transmute);
    //   _16 = PolymorphicIter { alive: const .., data: copy _15 };
    //
    // The scalarized path has no representation for a whole-array VALUE, so
    // `place_trust_ir_ty` fails closed on `Ty::[T; N]` and the whole program
    // declines — that is what made `for n in [0usize, 1, 2]` uncompilable at
    // -O2 while working at -O0/-O1 (rule 0d covers only the shape where
    // `into_iter` survives as a CALL to intercept).
    //
    // A transmute is a byte reinterpretation between two types of the SAME size,
    // and `copy_memory_aggregate_leaves` copies a slot by byte lanes without
    // consulting either type — so a slot on both sides IS the lowering (see the
    // Transmute arm in `lower_assign`).
    //
    // Scoped to the case where BOTH sides are non-scalar AND memory-representable:
    // that excludes the `int <-> [u8; N]` reinterpret (`to_le_bytes` and friends),
    // which has its own arm in `lower_assign` and must keep it. Additive on the
    // same argument as rules 0c/0d: absent slots this statement fails closed
    // today, so a slot steals no working case.
    for bb in body.basic_blocks.iter() {
        for statement in &bb.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (place, rvalue) = &**boxed;
            let Rvalue::Cast(mir::CastKind::Transmute, operand, dst_ty) = rvalue else {
                continue;
            };
            if !place.projection.is_empty() {
                continue;
            }
            let (Operand::Copy(src) | Operand::Move(src)) = operand else {
                continue;
            };
            if !src.projection.is_empty() {
                continue;
            }
            let dst_ty = ctx.monomorphize_ty(*dst_ty);
            let src_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
            let both_aggregate = rust_ty_to_trust_ir_ty(ctx.tcx, dst_ty).is_err()
                && rust_ty_to_trust_ir_ty(ctx.tcx, src_ty).is_err();
            if !both_aggregate {
                continue;
            }
            // A non-scalar union (including MaybeUninit<[T; N]>) already has
            // a checked byte-slot layout, but the ordinary aggregate classifier
            // deliberately excludes overlapping fields. Give both endpoints a
            // slot so the existing equal-size, weaker-alignment copy can run.
            let has_transmute_slot = |ty| {
                matches!(memory_aggregate_layout_shared(ctx.tcx, ty), Ok(Some(_)))
                    || (ctx.tcx.sess.target.arch.desc() == "aarch64"
                        && ctx.tcx.sess.target.os == rustc_target::spec::Os::Linux
                        && matches!(nonscalar_union_memory_layout(ctx.tcx, ty), Ok(Some(_))))
            };
            let representable = has_transmute_slot(dst_ty) && has_transmute_slot(src_ty);
            if !representable {
                continue;
            }
            locals.insert(place.local);
            locals.insert(src.local);
        }
    }

    // (0d-extend) `<Vec<T> as Extend>::extend(&mut self, [a, b, ..])` — a BY-VALUE array
    // source (`v.extend([3, 4, 5])`). `resolve_extend_source_data_len` reads the moved
    // array's slot address; force it memory-backed (a moved by-value array is otherwise
    // scalarized). PRECISELY gated to a std/core callee named `extend` whose arg1 is an
    // ARRAY local, so no other `extend` source shape is affected. Additive: absent a slot
    // the by-value-array extend fails closed today.
    for bb in body.basic_blocks.iter() {
        let Some(term) = &bb.terminator else {
            continue;
        };
        let TerminatorKind::Call { func, args, .. } = &term.kind else {
            continue;
        };
        let Some((did, name)) = call_callee_item_name(ctx, body, func) else {
            continue;
        };
        if name != "extend" || !is_std_collection_method_callee(ctx.tcx, did) {
            continue;
        }
        let Some(arg1) = args.get(1) else {
            continue;
        };
        if let Operand::Copy(p) | Operand::Move(p) = &arg1.node {
            if p.projection.is_empty()
                && matches!(
                    ctx.monomorphize_ty(local_rust_ty(ctx, body, p.local))
                        .kind(),
                    ty::Array(..)
                )
            {
                locals.insert(p.local);
            }
        }
    }

    // (0d-fromfn) `core::array::from_fn::<T, N, _>(f) -> [T; N]` (`array::from_fn(|i|..)`):
    // `lower_array_from_fn` writes into the destination `[T; N]` array's slot; force it
    // memory-backed (a small register-returned array aggregate is otherwise scalarized).
    // Gated to a std/core callee named `from_fn` with an ARRAY destination (distinguishing
    // it from `iter::from_fn`, whose result is an iterator). Additive.
    for bb in body.basic_blocks.iter() {
        let Some(term) = &bb.terminator else {
            continue;
        };
        let TerminatorKind::Call {
            func, destination, ..
        } = &term.kind
        else {
            continue;
        };
        let Some((did, name)) = call_callee_item_name(ctx, body, func) else {
            continue;
        };
        if name != "from_fn" || !is_std_collection_method_callee(ctx.tcx, did) {
            continue;
        }
        if destination.projection.is_empty()
            && matches!(
                ctx.monomorphize_ty(local_rust_ty(ctx, body, destination.local))
                    .kind(),
                ty::Array(..)
            )
        {
            locals.insert(destination.local);
        }
    }

    // (0d-slice) A bare `&[T]`/`&str` fat-pointer local bound from an ENUM VARIANT
    // PAYLOAD (`s = (opt as Some).0` — the `if let Some(s) = v.get(range)` / `match
    // opt { Some(s) => .. }` binding of a slice reference out of an `Option`/`Result`).
    // A bare fat-pointer local is otherwise SCALARIZED, so the `Downcast+Field` payload
    // read arm in `lower_memory_slice_assign` (which writes BOTH `{data,len}` lanes into
    // a slot) never fires and `s = (opt as Some).0` fails closed. Force such a local
    // memory-backed so that arm handles it and the subsequent `(*s)[i]`/`(*s).len()`
    // reads its lanes through the slot.
    //
    // SOUNDNESS — memory-back ONLY when the local NEVER flows BY VALUE
    // (`locals_used_bare_by_value`): a memory-backed slot passed as a value operand
    // into a call/closure/aggregate is mis-read (a bare `Copy` of the slot local into
    // an `Option::map` closure returned garbage — 139 vs 12 — before this guard). When
    // every use is a `Deref`-based projection (index/len/iter through the slot) the
    // slot representation is exactly right; otherwise leave the local scalarized (the
    // assign then fails closed — safe). Additive: absent a slot the assign fails closed
    // today, so a slot steals no working case.
    let bare_value_used = locals_used_bare_by_value(body);
    for bb in body.basic_blocks.iter() {
        for stmt in &bb.statements {
            let StatementKind::Assign(boxed) = &stmt.kind else {
                continue;
            };
            let (place, rvalue) = (&boxed.0, &boxed.1);
            if !place.projection.is_empty() || bare_value_used.contains(&place.local) {
                continue;
            }
            if !is_slice_or_str_fat_ptr_ty(ctx.monomorphize_ty(local_rust_ty(
                ctx,
                body,
                place.local,
            ))) {
                continue;
            }
            let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                continue;
            };
            if matches!(
                src.projection.as_ref(),
                [ProjectionElem::Downcast(_, _), ProjectionElem::Field(_, _)]
            ) {
                locals.insert(place.local);
            }
        }
    }

    // (0c-bis) `Vec::from([a, b, c])` — a by-value `[T; N]` array moved into a
    // `Vec`-returning call (`<Vec<T> as From<[T; N]>>::from`). The array's storage
    // is copied into the fresh Vec buffer (`resolve_slice_source_data_len`'s by-value
    // array arm reads `memory_slots[arr].ptr` + `N`), so the moved array must be
    // memory-backed rather than scalarized. Shape-gated (dest is a Vec, arg0 is a
    // bare array local); the array is consumed by the call, so a slot steals no case.
    for bb in body.basic_blocks.iter() {
        let Some(term) = &bb.terminator else {
            continue;
        };
        let TerminatorKind::Call {
            args, destination, ..
        } = &term.kind
        else {
            continue;
        };
        let dest_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, destination));
        if vec_element_ty(ctx.tcx, dest_ty).is_none() {
            continue;
        }
        let Some(arg0) = args.first() else {
            continue;
        };
        if let Operand::Copy(p) | Operand::Move(p) = &arg0.node {
            if p.projection.is_empty()
                && matches!(
                    ctx.monomorphize_ty(local_rust_ty(ctx, body, p.local))
                        .kind(),
                    ty::Array(..)
                )
            {
                locals.insert(p.local);
            }
        }
    }

    // (0d) Every local whose type is a `memory_aggregate_layout` aggregate
    // containing AT LEAST ONE nested no-niche (Direct-tag), non-drop
    // MULTI-VARIANT ENUM leaf field (e.g. `struct W{opt:Option<i64>,n:i64}`).
    // Such a field has NO scalarized representation (`scalar_leaf_trust_ir_fields`
    // unconditionally rejects a multi-variant enum via `rust_ty_to_trust_ir_ty`'s
    // generic-enum arm) -- it can ONLY be realized in a real memory slot
    // (construction writes tag+payload via `store_operand_into_memory_at`; a
    // field read walks the byte offset and decodes the discriminant the same way
    // a bare enum local already does). None of the OTHER triggers fire for a
    // plain non-escaping local (`let w = W{..}` is not a return/param/call-dest/
    // address-taken local), so without this rule such a local fails closed
    // everywhere (confirmed: artificially address-taking it routes it through
    // this SAME memory machinery and both construct+read work correctly).
    // Scoped to Direct-tag + !needs_drop nested-enum fields only (see
    // `has_nested_enum_leaf`'s doc comment); a struct with ONLY a Niche-tagged
    // (e.g. `Option<&T>`) or needs-drop (e.g. `Option<String>`) nested enum
    // field is NOT newly triggered here and stays on its existing path.
    // EXCEPTION: a TUPLE with a Niche-tagged !needs_drop enum leaf
    // (`(Option<&i64>, i64)`) IS triggered (via `has_nested_niche_enum_leaf`):
    // unlike the struct case, the scalarized tuple path has no working
    // representation for it (`lower_tuple_aggregate` fails closed via
    // `rust_ty_to_trust_ir_ty`), so memory-backing is the only route — and the
    // niche tag store/decode it needs is the same already-live machinery a bare
    // niche enum local uses. Structs with niche fields are deliberately NOT
    // widened (their scalarized path works today and must not be re-routed).
    for local in body.local_decls.indices() {
        if fmt_internal_locals.contains(&local) {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if matches!(
            memory_aggregate_layout_shared(ctx.tcx, ty),
            Ok(Some(layout)) if layout.has_nested_enum_leaf
                || (layout.has_nested_niche_enum_leaf && matches!(ty.kind(), ty::Tuple(..)))
        ) {
            locals.insert(local);
        }
    }

    // (0e) Every local that is `&mut`-BORROWED INTO A MUTABLE TRAIT-OBJECT UNSIZE
    // coercion (`_r = &mut _x; _t = _r as &mut dyn Trait (Unsize)`). A mutating
    // vtable method through that `&mut dyn` writes the pointee IN MEMORY, so the
    // pointee must live in a REAL slot: for a memory-backed `_x` the borrow binds
    // `_r` to the slot address (`lower_scalar_ref`'s memory arm) and
    // `materialize_trait_object_data_ptr` reuses that REAL address — the method's
    // store lands in `_x`'s slot and every later read of `_x` sees it. WITHOUT
    // this rule a scalarized `_x` reaches the copy-materializing branches, which
    // now FAIL CLOSED [TCG-DYN-MUT-COPY] (pre-guard they silently DROPPED the
    // store — the fuzz-found `&mut dyn` P0). Forcing memory-backing turns that
    // fail-close into a correct lowering. Additive and safe: these locals had NO
    // working `&mut dyn` representation before (fail-closed), and a pointee whose
    // type has no memory layout is simply not added (stays fail-closed). SHARED
    // `&dyn` coercions are NOT matched — read-only dispatch over the materialized
    // copy is correct and keeps its cheaper scalarized path.
    {
        // Pass 1: `ref_local -> borrowed_local` for every whole-local `&mut x`.
        let mut mut_ref_of: HashMap<Local, Local> = HashMap::new();
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                if !dst.projection.is_empty() {
                    continue;
                }
                let Rvalue::Ref(_, mir::BorrowKind::Mut { .. }, src) = rvalue else {
                    continue;
                };
                if src.projection.is_empty() {
                    mut_ref_of.insert(dst.local, src.local);
                }
            }
        }
        // Pass 2: for every `_t = _r as &mut dyn Trait (Unsize)` whose `_r` is a
        // collected `&mut x`, memory-back `x` (when its type has a memory layout).
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (_, rvalue) = &**boxed;
                let Rvalue::Cast(
                    mir::CastKind::PointerCoercion(PointerCoercion::Unsize, _),
                    Operand::Copy(p) | Operand::Move(p),
                    cast_ty,
                ) = rvalue
                else {
                    continue;
                };
                if !p.projection.is_empty() {
                    continue;
                }
                let Some(&borrowed) = mut_ref_of.get(&p.local) else {
                    continue;
                };
                if fmt_internal_locals.contains(&borrowed) {
                    continue;
                }
                let cast_ty = ctx.monomorphize_ty(*cast_ty);
                let (ty::Ref(_, inner, rustc_hir::Mutability::Mut)
                | ty::RawPtr(inner, rustc_hir::Mutability::Mut)) = cast_ty.kind()
                else {
                    continue;
                };
                if !matches!(inner.kind(), ty::Dynamic(..)) {
                    continue;
                }
                let borrowed_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, borrowed));
                if matches!(
                    memory_aggregate_layout_shared(ctx.tcx, borrowed_ty),
                    Ok(Some(_))
                ) {
                    locals.insert(borrowed);
                }
            }
        }
    }

    // (0b) The destination of `dst = copy/move (src.field...)` where `src` is a
    // memory-backed aggregate and the projected FIELD is itself a memory aggregate
    // (a nested struct / tuple, or the `ManuallyDrop<T>` transparent-newtype payload
    // read out of a union: `_2 = move (_1.value)` inside `MaybeUninit::assume_init`).
    // The nested-aggregate field copy (`lower_assign`'s projected-field arm) reads the
    // field's bytes from `src`'s slot and writes them into THIS local's slot, so it
    // must be memory-backed. Gated to a FIELD-only (no runtime index) projection whose
    // projected leaf has a `memory_aggregate_layout` (which only fires when the scalar
    // mapping fails, so a scalar field read `x = s.f: i64` keeps the scalarized path).
    // Additive: without a slot such a copy simply fails closed today.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if !dst.projection.is_empty() || fmt_internal_locals.contains(&dst.local) {
                continue;
            }
            let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                continue;
            };
            if src.projection.is_empty() || projection_has_index_element(&src.projection) {
                continue;
            }
            // `src` must be memory-backed for the field-copy path. The only source we
            // rely on here is a NON-scalar union (added by (0) above, so already in
            // `locals`) — the `MaybeUninit`'s `self.value` read. Skip otherwise.
            if !locals.contains(&src.local) {
                continue;
            }
            let projected_ty = ctx.monomorphize_ty(src.ty(body, ctx.tcx).ty);
            if matches!(
                memory_aggregate_layout_shared(ctx.tcx, projected_ty),
                Ok(Some(_))
            ) {
                locals.insert(dst.local);
            }
        }
    }

    // (1) The return local, when it is a by-value memory aggregate OR a slice fat
    // pointer (a `fn g() -> &[T]` returning its `{ data, len }` pair in RAX:RDX).
    let return_local = Local::new(0);
    let return_ty = local_rust_ty(ctx, body, return_local);
    if !fmt_internal_locals.contains(&return_local)
        && matches!(
            fat_ptr_or_memory_aggregate_layout(ctx.tcx, return_ty),
            Ok(Some(_))
        )
    {
        locals.insert(return_local);
    }

    // (2) By-value aggregate / slice-fat-pointer parameters: a function argument
    // whose type is a memory-eligible aggregate or a `&[T]` / `&str` fat pointer.
    // The incoming SysV two-eightbyte ABI value (data+len in a register pair, or
    // the aggregate lanes) is stored into the slot at function entry so the body
    // reads the parameter from memory like any other aggregate local.
    for arg in body.args_iter() {
        if fmt_internal_locals.contains(&arg) {
            continue;
        }
        let arg_ty = local_rust_ty(ctx, body, arg);
        if matches!(
            fat_ptr_or_memory_aggregate_layout(ctx.tcx, arg_ty),
            Ok(Some(_))
        ) {
            locals.insert(arg);
        }
    }

    // (3) Destinations of calls returning a by-value memory aggregate or a slice
    // fat pointer (`s = make_slice()` -> `&[T]`).
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        let Some(terminator) = &data.terminator else {
            continue;
        };
        if let TerminatorKind::Call {
            func,
            args,
            destination,
            target,
            unwind,
            fn_span,
            ..
        } = &terminator.kind
        {
            if !destination.projection.is_empty() {
                continue;
            }
            // A `core::fmt` plumbing destination (the `fmt::Arguments` value, an
            // `Argument` result) is decoded statically and never memory-backed —
            // its niche-enum layout would otherwise make this `?` fail closed.
            if fmt_internal_locals.contains(&destination.local) {
                continue;
            }
            let dest_ty = local_rust_ty(ctx, body, destination.local);
            // A `<[T; N] as Index/IndexMut<RangeFull>>::index(&arr, ..)` call (the O0 form of
            // `&arr[..]`) takes the constructed slice's data pointer from the SOURCE array's
            // address, so that array must be memory-backed (a scalarized array has no
            // address). The destination slice itself is memory-backed by the fat-pointer
            // path below; here we additionally force the source array. (At O3 this is a
            // `PointerCoercion::Unsize` handled by the statement loop above.)
            if let Ok(instance) = direct_callee_instance(ctx, body, func, *fn_span) {
                let probe = DirectCallTerminator {
                    func,
                    args,
                    destination,
                    target: *target,
                    unwind,
                    fn_span: *fn_span,
                    // A CLASSIFICATION probe: it is asked a yes/no question and
                    // never lowers anything, so it never reaches the caller-location
                    // lane that is the only reader of `source_info`; it carries the
                    // terminator's own `SourceInfo` all the same.
                    source_info: terminator.source_info,
                };
                if matches!(
                    is_full_slice_index_call(ctx, body, &probe, instance),
                    Ok(true)
                ) {
                    if let Some(array_local) =
                        slice_unsize_source_array_local(ctx, body, &args[0].node)
                    {
                        locals.insert(array_local);
                    }
                }
                // The bounded-subslice `<[T; N] as Index/IndexMut<Range<usize>>>::
                // index(&arr, i..j)` call (the O0 `&arr[i..j]` over a local array): its
                // data base is the SOURCE array's slot address, so force that array
                // memory-backed too (the destination slice is memory-backed by the
                // fat-pointer path below). See `lower_local_array_subslice_index_call`.
                if matches!(
                    is_local_array_range_subslice_call(ctx, body, &probe, instance),
                    Ok(true)
                ) {
                    if let Some(array_local) =
                        slice_unsize_source_array_local(ctx, body, &args[0].node)
                    {
                        locals.insert(array_local);
                    }
                }
            }
            // A call the bridge INTERCEPTS into SCALARIZED bindings must keep its
            // destination on the scalarized path: an `x.overflowing_add(y)` call (or
            // `overflowing_shl`/`overflowing_shr` — same `(iN, bool)` result) at
            // -Copt-level=0 returns `(T, bool)` by value, but the interception
            // (`lower_overflowing_method_call` / `lower_overflowing_shift_call`) binds
            // the destination's field 0/1 as
            // projected SSA values rather than storing the slot — so memory-backing
            // the destination here (now that an integer/bool tuple has a layout)
            // would make the later `_d.0`/`_d.1` reads load an UNWRITTEN slot and
            // miscompile (the `(T, bool)` overflow pair the scalarized path already
            // handles correctly). This ONLY matters for an integer/bool/float
            // by-value tuple destination (the new layout); probe the overflow
            // interception only then (a float tuple is never an overflow-method
            // result, so the probes harmlessly return `None` and the destination is
            // memory-backed as usual), and only for a real named associated fn
            // callee — `item_name`
            // ICEs on a closure/synthetic DefPath (e.g. the `lang_start` closure), so
            // we gate on `def_kind == AssocFn` exactly where the interception itself
            // is reachable in `lower_direct_call_terminator` (after the closure /
            // virtual / intrinsic cases are already filtered out). A resolution
            // error / non-assoc-fn callee means "not an intercepted overflow method",
            // so we do NOT skip.
            if matches!(func, Operand::Constant(_))
                && matches!(integer_byval_tuple_eligible(ctx.tcx, dest_ty), Ok(true))
            {
                if let Ok(callee_instance) = direct_callee_instance(ctx, body, func, *fn_span) {
                    let def_id = callee_instance.def_id();
                    let is_named_assoc_fn = matches!(
                        ctx.tcx.def_kind(def_id),
                        rustc_hir::def::DefKind::AssocFn | rustc_hir::def::DefKind::Fn
                    );
                    if is_named_assoc_fn {
                        let probe = DirectCallTerminator {
                            func,
                            args,
                            destination,
                            target: *target,
                            unwind,
                            fn_span: *fn_span,
                            // Classification only; see the sibling probe above.
                            source_info: terminator.source_info,
                        };
                        if matches!(
                            overflowing_binop_method(ctx, body, &probe, callee_instance),
                            Ok(Some(_))
                        ) || matches!(
                            overflowing_shift_method(ctx, body, &probe, callee_instance),
                            Ok(Some(_))
                        ) || matches!(
                            overflowing_divrem_method(ctx, body, &probe, callee_instance),
                            Ok(Some(_))
                        ) {
                            continue;
                        }
                    }
                }
            }
            // An intercepted `<[T]>::split_at` / `split_at_mut` destination tuple
            // `(&[T], &[T])`: a `ScalarPair`-field tuple the general aggregate
            // layout rejects, but which the split lowering writes as two
            // `{ data, len }` halves into a memory slot. Force it memory-backed (the
            // slot layout comes from `memory_backed_local_layout`'s split-tuple arm).
            if matches!(
                slice_pair_tuple_layout(ctx.tcx, ctx.monomorphize_ty(dest_ty)),
                Ok(Some(_))
            ) {
                locals.insert(destination.local);
                continue;
            }
            // A call destination whose aggregate layout the model does NOT support
            // (an `Err` — e.g. `Option<&str>` from the inlined `Arguments::as_str`
            // on the O3 `format!` path, which has a fat-pointer `&str` leaf) is
            // simply NOT memory-backed here: it keeps the scalarized path (and
            // fails closed there on its own terms IF actually lowered). On the
            // intercepted-format path it is dead and never lowered. Swallowing the
            // `Err` (rather than propagating it) keeps the enclosing function
            // lowerable; it can never miscompile (a genuinely-needed unsupported
            // aggregate still fails closed when its real use is lowered).
            if matches!(
                fat_ptr_or_memory_aggregate_layout(ctx.tcx, dest_ty),
                Ok(Some(_))
            ) {
                locals.insert(destination.local);
            }
        }
    }

    // (3c) The argument TUPLE of every call that passes it untupled — a CLOSURE
    // call (`|s: S| ..` invoked as `f(s)` -> `<C as Fn<(S,)>>::call(&c, (s,))`)
    // and every call of an `extern "rust-call"` callable (a `Fn*` shim or impl
    // method, a `dyn Fn*` / `Box<dyn Fn*>` dispatch, a `rust-call` `fn` pointer;
    // `rust_call_spread`) — when it carries a by-value AGGREGATE element. Each
    // element is built from the tuple's bytes (`lower_closure_call_terminator`,
    // `spread_fn_call_tuple_untupled`: the common selected field-copy plan, a
    // pointer to a fresh copy, two `Pair` lanes), so the tuple must be
    // memory-backed. A tuple whose elements are ALL scalar stays scalarized (the
    // per-element scalar path handles it) — only a tuple carrying at least one
    // by-value aggregate element (and itself having a memory layout) is forced.
    //
    // Scalarized, such a tuple is also built field-wise from an element that is
    // itself memory-backed whenever it is a by-value aggregate read out of a slot
    // (`_4 = move ((_1 as Some).0)`, rule (7)), which the scalarized construct
    // cannot read ("Place projection field 0 before aggregate binding");
    // memory-backed, the construct copies the element's bytes slot to slot
    // (`store_operand_into_memory_at`). MEASURED before this rule keyed on the ABI
    // (2026-09-30): a bridge bin's `f(*t)` through `&dyn Fn(T12)` was refused
    // "Fn-trait tuple element 0 `T12` needs a byte-backed tuple".
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        let Some(terminator) = &data.terminator else {
            continue;
        };
        let TerminatorKind::Call {
            func,
            args,
            fn_span,
            ..
        } = &terminator.kind
        else {
            continue;
        };
        // Whether this call takes its last operand untupled: a closure body
        // (receiver + tuple) or a `rust-call` callee — resolved statically, or a
        // `fn` pointer of a `rust-call` signature.
        let callee_ty = match func {
            Operand::Constant(constant) => Some(ctx.monomorphize_ty(constant.const_.ty())),
            Operand::Copy(place) | Operand::Move(place) => {
                Some(ctx.monomorphize_ty(place_rust_ty(&ctx, body, place)))
            }
            Operand::RuntimeChecks(_) => None,
        };
        let spreads_last = match callee_ty.map(|ty| ty.kind()) {
            Some(ty::FnPtr(sig_tys, hdr)) => {
                sig_tys.with(*hdr).abi() == rustc_abi::ExternAbi::RustCall
            }
            Some(ty::FnDef(..)) => match direct_callee_instance(&ctx, body, func, *fn_span) {
                Ok(callee_instance) => {
                    rust_call_spread::instance_is_rust_call_fn(ctx.tcx, callee_instance)
                        || (args.len() == 2
                            && matches!(
                                callee_instance
                                    .ty(ctx.tcx, ty::TypingEnv::fully_monomorphized())
                                    .kind(),
                                ty::Closure(..)
                            ))
                }
                Err(_) => false,
            },
            _ => false,
        };
        if !spreads_last {
            continue;
        }
        let Some(tuple_arg) = args.last() else {
            continue;
        };
        let (Operand::Copy(tuple_place) | Operand::Move(tuple_place)) = &tuple_arg.node else {
            continue;
        };
        if !tuple_place.projection.is_empty() || fmt_internal_locals.contains(&tuple_place.local) {
            continue;
        }
        let tuple_ty = ctx.monomorphize_ty(local_rust_ty(&ctx, body, tuple_place.local));
        let ty::Tuple(elem_tys) = tuple_ty.kind() else {
            continue;
        };
        // Only force memory-backing when at least one element is a by-value aggregate
        // (otherwise the scalar per-element path already works), AND the tuple itself
        // has a memory layout the slot machinery can build.
        let has_aggregate_elem = elem_tys.iter().any(|elem| {
            matches!(
                memory_aggregate_layout_shared(ctx.tcx, ctx.monomorphize_ty(elem)),
                Ok(Some(_))
            )
        });
        if has_aggregate_elem
            && matches!(
                memory_aggregate_layout_shared(ctx.tcx, tuple_ty),
                Ok(Some(_))
            )
        {
            locals.insert(tuple_place.local);
        }
    }

    // (3b) Slice fat-pointer locals that are CONSTRUCTED (an `Unsize` coercion, a
    // `RawPtr`-from-parts subslice, a whole-slice move) OR PASSED to a call. Such
    // a slice value must live in a `{ data, len }` slot so it can be passed in a
    // register pair and indexed/measured at runtime. A purely const-length,
    // never-boundary-crossing slice (the inlined corpus cases) is NOT matched
    // here and keeps the data-pointer + side-table-length representation.
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if !dst.projection.is_empty() {
                continue;
            }
            let dst_ty = local_rust_ty(ctx, body, dst.local);
            // A checked wide carrier copies its complete image from another
            // slot, including fixed fields of a larger memory-backed aggregate,
            // or a validated thin-pointer dereference. Scalarized sources keep
            // their existing data-plus-metadata side-table representation.
            // Constructors in slotted locals write both payload lanes together.
            if wide_slice_carrier_layout(ctx.tcx, dst_ty).is_some() {
                let copies_wide_image = match rvalue {
                    // Wrapper unsizing constructs a runtime pair, including a
                    // constant array length. Its later moves and calls must
                    // carry both words just like a bare slice coercion.
                    Rvalue::Cast(
                        mir::CastKind::PointerCoercion(PointerCoercion::Unsize, _),
                        ..,
                    ) => true,
                    Rvalue::Aggregate(kind, operands)
                        if matches!(&**kind, mir::AggregateKind::Adt(..)) =>
                    {
                        operands.iter().any(|operand| {
                            matches!(operand, Operand::Copy(src) | Operand::Move(src)
                                if locals.contains(&src.local))
                        })
                    }
                    Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) => {
                        (locals.contains(&src.local)
                            && src.projection.iter().all(|projection| {
                                matches!(
                                    projection,
                                    ProjectionElem::Field(..) | ProjectionElem::Downcast(..)
                                )
                            }))
                            || is_wide_slice_newtype_deref_read(ctx, body, src)
                            || wide_projection::is_deref_read(ctx, body, src)
                    }
                    // Inlined NonNull::new_unchecked transmutes a runtime fat
                    // pointer. Preserve its complete image before taking a
                    // reference to the newtype; spilling one scalar loses len.
                    Rvalue::Cast(
                        mir::CastKind::Transmute,
                        Operand::Copy(src) | Operand::Move(src),
                        _,
                    ) => {
                        src.projection.iter().all(|p| {
                            matches!(p, ProjectionElem::Field(..) | ProjectionElem::Downcast(..))
                        }) && locals.contains(&src.local)
                            && is_slice_fat_ptr_or_carrier(
                                ctx.tcx,
                                ctx.monomorphize_ty(place_rust_ty(ctx, body, src)),
                            )
                    }
                    _ => false,
                };
                if copies_wide_image {
                    locals.insert(dst.local);
                }
                continue;
            }
            // A reference / raw pointer to a slice-tail DST is the same `{ data, len }`
            // two-eightbyte image (`is_slice_tail_dst_ref_ty`) and is classified
            // alongside the slice itself.
            if !is_slice_or_str_fat_ptr_ty(dst_ty) && !is_slice_tail_dst_ref_ty(ctx.tcx, dst_ty) {
                continue;
            }
            let constructs_runtime_slice = match rvalue {
                // `&[T; N] -> &[T]` / `&str` unsize -> a runtime `{ data, len }`.
                Rvalue::Cast(mir::CastKind::PointerCoercion(PointerCoercion::Unsize, _), ..) => {
                    true
                }
                // A slice<->slice `Transmute` of a RUNTIME (memory-backed) slice
                // source preserves both fat-pointer halves (e.g. the inlined
                // `str::as_bytes`: `&str -> &[u8]`). A CONST-slice transmute is
                // handled by the const path and is NOT matched here.
                // A FAT -> FAT `PtrToPtr` cast out of an already-SLOTTED slice local
                // (`_2 = copy _1 as *const [T]` inside `NonNull::<[T]>::from_ref` /
                // `from_mut` — `transmute(r as *const T)` — with `_1` the `&[T]`
                // parameter slot rule (2) gave): the destination is the bitwise
                // `{ data, len }` copy `lower_memory_slice_assign`'s `PtrToPtr` arm
                // already lowers from a memory-backed source, and the `Transmute`
                // into the newtype return slot that follows needs it slotted. (A
                // fat -> fat cast never rescales the count — that would be
                // `from_raw_parts`, an `AggregateKind::RawPtr`. Without this arm the
                // destination was bound as a single SCALAR and the reborrow after it
                // failed closed: `<[MaybeUninit<T>]>::assume_init_ref` /
                // `assume_init_mut`, `<[AsciiChar]>::as_str`,
                // `str::from_utf8_unchecked_mut`.) Restricted to a source in the
                // work-in-progress set so a scalarized (const-length / side-table)
                // source keeps today's scalar path. A slice-tail DST reference is
                // the same image and rides the same arm.
                Rvalue::Cast(mir::CastKind::PtrToPtr, Operand::Copy(p) | Operand::Move(p), _) => {
                    let src_ty = local_rust_ty(ctx, body, p.local);
                    p.projection.is_empty()
                        && locals.contains(&p.local)
                        && (is_slice_or_str_fat_ptr_ty(src_ty)
                            || is_slice_tail_dst_ref_ty(ctx.tcx, src_ty))
                }
                // Also a transmute FROM an already-SLOTTED transparent wide-slice
                // newtype (`_2 = copy _1 as *mut [T]` inside `NonNull::<[T]>::len`
                // / `cast` once `as_ptr` inlines, with `_1` the parameter slot):
                // the WIP-set restriction is load-bearing — a SCALARIZED newtype
                // source (the inlined `Box::<[T]>::from_raw` chains) must not drag
                // its `*mut [T]` into the slot world.
                Rvalue::Cast(mir::CastKind::Transmute, operand, _) => match operand {
                    Operand::Copy(p) | Operand::Move(p) => {
                        (locals.contains(&p.local)
                            && p.projection.iter().all(|projection| {
                                matches!(
                                    projection,
                                    ProjectionElem::Field(..) | ProjectionElem::Downcast(..)
                                )
                            })
                            && is_slice_fat_ptr_or_carrier(
                                ctx.tcx,
                                ctx.monomorphize_ty(place_rust_ty(ctx, body, p)),
                            ))
                            || p.projection.is_empty()
                                && (is_slice_or_str_fat_ptr_ty(local_rust_ty(ctx, body, p.local))
                                    || (locals.contains(&p.local)
                                        && wide_slice_carrier_layout(
                                            ctx.tcx,
                                            local_rust_ty(ctx, body, p.local),
                                        )
                                        .is_some()))
                    }
                    _ => false,
                },
                // `*const [T] from (data, len)` raw-pointer-from-parts (a subslice).
                Rvalue::Aggregate(kind, _) => {
                    matches!(&**kind, mir::AggregateKind::RawPtr(..))
                }
                // `dst = &mut (*fat_raw)` / `&raw (*fat)` — a fat-pointer REBORROW
                // from another fat-pointer-typed local (the `-O3`-inlined
                // `<Vec as IndexMut>::index_mut` chain: `as_mut_slice` builds
                // `*mut [T]` from parts, then reborrows it to `&mut [T]` before the
                // slice write). The lowering already copies `{ data, len }` between
                // slot-backed fat locals; classify the DEST so it gets a slot.
                Rvalue::Ref(_, _, src) | Rvalue::RawPtr(_, src)
                    if matches!(src.projection.as_ref(), [ProjectionElem::Deref]) =>
                {
                    is_length_metadata_wide_ptr_ty(
                        ctx.tcx,
                        ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local)),
                    )
                }
                // `dst = &raw const (*c).inner` / `&(*c).inner` — the SAME fat-pointer
                // reborrow as the `(*fat)` arm above, reached through the offset-0
                // unsized tail field of a `#[repr(transparent)]` wrapper fat pointer
                // (`CStr::as_ptr` / `count_bytes` over `self.inner`, the `Path` ->
                // `OsStr` chain — see `fat_ptr_tail_reborrow_projection`). The
                // projected place IS `c`'s `{ data, len }`, so the DEST gets a slot
                // for the same reason and `lower_memory_slice_assign`'s reborrow arm
                // copies both lanes into it.
                Rvalue::Ref(_, _, src) | Rvalue::RawPtr(_, src)
                    if fat_ptr_tail_reborrow_projection(ctx, body, src) =>
                {
                    true
                }
                // `dst = &(*s)[from..]` / `&(*s)[..len-to]` — a SUBSLICE reborrow of a
                // slice/`str` fat-pointer local `s` (the `rest @ ..` / `head @ ..`
                // binding of a slice pattern: `<[T]>::split_first`, the sign-strip
                // match of `from_ascii_radix`). The destination is a runtime
                // `{ data + from*size, len - from - to }` pair computed from `s`'s
                // halves by `lower_memory_slice_assign`'s Subslice arm; classify the
                // DEST so it gets a slot. The SOURCE is not pulled in here: a
                // const-length source keeps its data-pointer + side-table binding
                // (the Subslice arm reads that binding directly), so no working
                // const-slice case is re-routed.
                Rvalue::Ref(_, _, src) | Rvalue::RawPtr(_, src)
                    if matches!(
                        src.projection.as_ref(),
                        [ProjectionElem::Deref, ProjectionElem::Subslice { .. }]
                    ) =>
                {
                    is_length_metadata_wide_ptr_ty(
                        ctx.tcx,
                        ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local)),
                    )
                }
                // `dst = &(*r).tail` — a borrow of the `[T]` / `str` TAIL of a
                // slice-tail DST through its fat reference. The destination's
                // `{ data, len }` is `r`'s data half at the tail's layout offset
                // paired with `r`'s own metadata, so the destination must itself be
                // slot-backed for `lower_memory_slice_assign`'s tail arm to serve
                // it. WITHOUT a slot the statement takes the SCALARIZED
                // `Rvalue::Ref` path, which asks for the trust-ir type of a bare
                // `[u8]` and fails closed there (measured: `Ty::[u8]`, 11 roots on
                // a `library/core` census) — so slot-backing it steals no working
                // case, and the two spellings of the one statement
                // (`<ByteStr as Deref>::deref`'s memory-backed return local and
                // `Wtf8::len`'s scalarized temp) now take the same arm.
                Rvalue::Ref(_, _, src) | Rvalue::RawPtr(_, src)
                    if slice_tail_dst_tail_borrow_offset(ctx, body, src).is_some() =>
                {
                    true
                }
                // `l = (split.0)` / `r = (split.1)` — a slice fat-pointer FIELD copy
                // out of a memory-backed `(&[T], &[T])` split tuple (the
                // `let (l, r) = a.split_at(n)` destructuring). The destination slice
                // gets its `{ data, len }` from the tuple field's slot bytes, so it
                // must itself be slot-backed (and `lower_memory_slice_assign`'s
                // field-copy arm reads the source field). The source must be a
                // memory-backed slice-pair tuple.
                //
                // ALSO: `t = (r.name)` / `t = (r.data)` — a fat-pointer FIELD copy
                // out of a memory-backed STRUCT/tuple carrying a `&str`/`&[T]` leaf
                // field (`struct Rec{name:&str,n:i64}`, forced memory-backed by rule
                // 0c above, which — being an earlier rule in this same pass — is
                // already reflected in the WIP `locals` set consulted here). This is
                // what makes `r.name.len()` / `r.data[i]` work: the field read first
                // materializes the WHOLE fat pointer into a temp (`t = copy r.name`)
                // before calling `.len()` or indexing through it, and that temp must
                // itself be slot-backed for `lower_memory_slice_assign`'s `s = src.K`
                // read arm to serve it (that arm requires ONLY that the destination
                // is recognized as memory-backed here). Without this, the temp stays
                // scalarized and the read fails closed (safe, but not a MATCH) at the
                // generic single-scalar assign path.
                Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                    if matches!(src.projection.as_ref(), [ProjectionElem::Field(_, _)]) =>
                {
                    matches!(
                        slice_pair_tuple_layout(
                            ctx.tcx,
                            ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local))
                        ),
                        Ok(Some(_))
                    ) || locals.contains(&src.local)
                }
                // `t = copy ((*r).name)` / `((*r).data)` — the SAME fat-pointer
                // FIELD copy as the arm above, but reached THROUGH A THIN
                // REFERENCE to the aggregate instead of out of an owned
                // memory-backed local: `fn read(b: &Both) -> i64 { b.slice.len()
                // + b.name.len() }`. The callee never owns the aggregate, so no
                // earlier rule slots it; the field's bytes live at
                // `*r + <rustc field offset>` and `lower_memory_fat_leaf_use`
                // reads both lanes from there — but only if THIS temp has a
                // `{data, len}` slot to receive them. Gated on a THIN reference
                // (so its scalar value really is the aggregate's address) whose
                // POINTEE the byte-offset memory model can lay out; anything else
                // keeps its existing handling. Previously fail-closed on every
                // path ("memory leaf type is a fat pointer"), so slot-backing it
                // steals no working case.
                Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                    if src.projection.len() >= 2
                        && matches!(src.projection.first(), Some(ProjectionElem::Deref))
                        && src.projection[1..].iter().all(|elem| {
                            matches!(
                                elem,
                                ProjectionElem::Field(..) | ProjectionElem::Downcast(..)
                            )
                        }) =>
                {
                    let src_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
                    // Thinness is EXACT here, and the base-address question
                    // (`deref_base_scalar_is_pointee_addr`) would change nothing:
                    // the arm also requires `memory_aggregate_layout_shared` of
                    // the POINTEE, which answers `None` for every unsized type
                    // (`memory_aggregate_layout_uncached`'s `!layout.is_sized()`
                    // exit), so no unsized-pointee base — slice-tail DST or
                    // vtable-tailed — can reach this rule under any predicate.
                    // Measured: giving this rule the base-address predicate, or
                    // the old enumeration, changed no probe's outcome either way.
                    match src_ty.kind() {
                        ty::Ref(_, pointee, _) | ty::RawPtr(pointee, _)
                            if is_thin_pointer_ref_ty(ctx.tcx, src_ty) =>
                        {
                            matches!(
                                memory_aggregate_layout_shared(
                                    ctx.tcx,
                                    ctx.monomorphize_ty(*pointee)
                                ),
                                Ok(Some(_))
                            )
                        }
                        _ => false,
                    }
                }
                // `s = copy (*p)` — the WHOLE fat pointer loaded from memory
                // through a thin `&&[T]` / `&&str` (the read of a ptr-bearing
                // `static NUMS: &[i32]` / `static GREETING: &str`:
                // `_p = const {alloc: &&[i32]}; s = copy (*_p)`). The loaded
                // `{ data, len }` must live in a slot so `PtrMetadata` /
                // element indexing / call-arg passing see both halves
                // (`lower_memory_slice_assign`'s thin-deref arm does the load).
                // This shape was previously fail-closed on every path (the
                // scalar deref-load rejects a 16-byte fat value), so slot-backing
                // it steals no working case.
                Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                    if matches!(src.projection.as_ref(), [ProjectionElem::Deref]) =>
                {
                    local_is_thin_ref_to_slice_fat_ptr(ctx, body, src.local)
                }
                _ => false,
            };
            if constructs_runtime_slice {
                locals.insert(dst.local);
                // A `&[T; N] -> &[T]` unsize takes the slice's data pointer from the
                // SOURCE array's address — so that array must also be memory-backed
                // (materialized in a slot), else the unsize fails closed for want of a
                // data pointer. Trace the borrowed array local and force it in too.
                if let Rvalue::Cast(
                    mir::CastKind::PointerCoercion(PointerCoercion::Unsize, _),
                    operand,
                    _,
                ) = rvalue
                {
                    if let Some(array_local) = slice_unsize_source_array_local(ctx, body, operand) {
                        locals.insert(array_local);
                    }
                }
            }
        }
        // A slice fat pointer passed as a CALL argument must be slot-backed.
        if let Some(terminator) = &data.terminator {
            if let TerminatorKind::Call { args, .. } = &terminator.kind {
                for arg in args.iter() {
                    if let Operand::Copy(place) | Operand::Move(place) = &arg.node {
                        if place.projection.is_empty()
                            && is_length_metadata_wide_ptr_ty(
                                ctx.tcx,
                                ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local)),
                            )
                        {
                            locals.insert(place.local);
                        }
                    }
                }
            }
        }
        // A by-value MULTI-VARIANT ENUM passed as a CALL argument (e.g. an `Option`
        // built via `Some`/`None` branches passed to `.unwrap_or` / `.map`). A
        // runtime-variant enum cannot be packed into the by-value aggregate ABI from
        // scalarized per-field values — its variant is not statically known, so the
        // scalarized `Use` fails ("Use source discriminant before aggregate binding").
        // Slot-backing it stores each constructed variant (with its tag) into the slot
        // and passes the slot. STRUCTS / ARRAYS keep the scalarized-packing path (their
        // fields ARE statically known); only multi-variant enums are routed here.
        if let Some(terminator) = &data.terminator {
            if let TerminatorKind::Call { args, .. } = &terminator.kind {
                for arg in args.iter() {
                    if let Operand::Copy(place) | Operand::Move(place) = &arg.node {
                        if !place.projection.is_empty() {
                            continue;
                        }
                        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
                        if let ty::Adt(adt, _) = ty.kind() {
                            // An unsupported-aggregate enum (e.g. `Option<&str>`
                            // from the O3-inlined `Arguments::as_str` on the
                            // `format!` path, with a fat-pointer `&str` payload) is
                            // simply not memory-backed (swallow the `Err`), keeping
                            // the function lowerable; it can never miscompile.
                            if adt.is_enum()
                                && adt.variants().len() > 1
                                && matches!(
                                    memory_aggregate_layout_shared(ctx.tcx, ty),
                                    Ok(Some(_))
                                )
                            {
                                locals.insert(place.local);
                            }
                        }
                    }
                }
            }
        }
    }

    // (3c) A by-value MULTI-VARIANT ENUM used as a bare-local FIELD / ELEMENT
    // operand of an `Rvalue::Aggregate` (`Outer::L(inner)` enum-in-enum,
    // `[Op::Add(x), Op::Neg]` array-of-payload-enums, `Some(inner)` for
    // `Option<Option<_>>`). When the OUTER aggregate is memory-backed, its
    // construction writes each field via `store_operand_into_memory_at`; a
    // SCALARIZED inner-enum source has no slot to copy and its runtime variant is
    // not a flat scalar leaf, so that path fails closed ("nested enum field operand
    // from a scalarized source is not lowered"). Memory-backing the inner enum makes
    // its OWN construction write tag + payload into a slot
    // (`lower_memory_aggregate_construct`), and the outer field store then byte-copies
    // that slot (`copy_memory_aggregate_leaves`) — byte-exact and runtime-variant
    // correct. Scoped exactly like the call-arg enum case (3): only a multi-variant
    // enum with a usable memory layout (structs/arrays/single-variant enums keep the
    // scalarized path; an unsupported-layout enum is left scalarized, not propagated
    // as an `Err`). A scalarized OUTER with such a field already fails closed in
    // `lower_adt_aggregate`, so this can never steal a case that works today.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            let Rvalue::Aggregate(kind, operands) = rvalue else {
                continue;
            };
            // A TUPLE construct is admitted only when its destination is itself a
            // memory-backed enum-leaf tuple (`(Option<i64>, i64)` — accepted by
            // `memory_aggregate_layout`'s tuple gate, or the niche-leaf
            // `(Option<&i64>, i64)` equivalent): the tuple's field store then
            // needs the enum operand's SLOT to byte-copy (case 2), exactly like the
            // named-struct case this rule already covers. Any other tuple construct
            // keeps the scalarized path untouched.
            let kind_ok = match &**kind {
                mir::AggregateKind::Adt(..) | mir::AggregateKind::Array(_) => true,
                mir::AggregateKind::Tuple => {
                    dst.projection.is_empty()
                        && matches!(
                            memory_aggregate_layout_shared(
                                ctx.tcx,
                                ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local)),
                            ),
                            Ok(Some(layout)) if layout.has_nested_enum_leaf
                                || layout.has_nested_niche_enum_leaf
                        )
                }
                _ => false,
            };
            if !kind_ok {
                continue;
            }
            for operand in operands.iter() {
                let (Operand::Copy(place) | Operand::Move(place)) = operand else {
                    continue;
                };
                if !place.projection.is_empty() || fmt_internal_locals.contains(&place.local) {
                    continue;
                }
                let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
                if let ty::Adt(adt, _) = ty.kind() {
                    if adt.is_enum()
                        && adt.variants().len() > 1
                        && matches!(memory_aggregate_layout_shared(ctx.tcx, ty), Ok(Some(_)))
                    {
                        locals.insert(place.local);
                    }
                }
            }
        }
    }

    // (3e) The BARE multi-variant-enum temp of an INDEXED whole-element copy
    // between an enum-leaf ARRAY slot and the temp — the 3c mirror, both
    // directions:
    //   * COPY-OUT `x = copy arr[i]` (`let x = a[i]; match x {..}`): the element
    //     lives in the array's slot at a runtime offset; a SCALARIZED destination
    //     can never work (it needs a compile-time `AdtDiscriminantBinding`,
    //     impossible for a runtime-variant element). Slot-backing `x` turns the
    //     statement into a slot-to-slot lane copy
    //     (`lower_memory_aggregate_use`'s indexed whole-enum source arm).
    //   * STORE-IN `arr[i] = move t` (rustc's spill of `a[i] = Some(v)`): the
    //     element store byte-copies the source's slot
    //     (`store_operand_into_memory_at`'s memory-backed-source arm), so `t`
    //     needs a slot holding tag + payload.
    // Scoped exactly like 3c: only a multi-variant enum with a usable memory
    // layout (fmt-internal locals excluded; an unsupported-layout enum stays
    // scalarized, not propagated as an `Err`), and only when the ARRAY side is
    // the 0d enum-leaf-array shape (its `memory_aggregate_layout` has an
    // enum/niche-enum leaf, so the array side is guaranteed slot-backed when it
    // is admitted at all), the projection carries a real Index element with no
    // leading `Deref`, and the projected element type equals the temp's type.
    // Every trigger statement fails closed today (the copy-out at
    // `lower_scalarized_aggregate_use`'s source-projection gate, the store at
    // the tagless-aggregate gate), so this can never steal a working path.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                continue;
            };
            let indexed_enum_leaf_array_place = |place: &Place<'tcx>| {
                !place.projection.is_empty()
                    && !matches!(place.projection.first(), Some(ProjectionElem::Deref))
                    && projection_has_index_element(&place.projection)
                    && {
                        let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
                        matches!(base_ty.kind(), ty::Array(..))
                            && matches!(
                                memory_aggregate_layout_shared(ctx.tcx, base_ty),
                                Ok(Some(layout)) if layout.has_nested_enum_leaf
                                    || layout.has_nested_niche_enum_leaf
                            )
                    }
            };
            let bare_memory_enum_place = |place: &Place<'tcx>| {
                if !place.projection.is_empty() || fmt_internal_locals.contains(&place.local) {
                    return false;
                }
                let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
                match ty.kind() {
                    ty::Adt(adt, _) => {
                        adt.is_enum()
                            && adt.variants().len() > 1
                            && matches!(memory_aggregate_layout_shared(ctx.tcx, ty), Ok(Some(_)))
                    }
                    _ => false,
                }
            };
            // COPY-OUT `x = copy arr[i]`: slot-back the destination temp.
            if bare_memory_enum_place(dst)
                && indexed_enum_leaf_array_place(src)
                && place_rust_ty(ctx, body, src)
                    == ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local))
            {
                locals.insert(dst.local);
            }
            // STORE-IN `arr[i] = move t`: slot-back the source temp.
            if indexed_enum_leaf_array_place(dst)
                && bare_memory_enum_place(src)
                && place_rust_ty(ctx, body, dst)
                    == ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local))
            {
                locals.insert(src.local);
            }
            // (3f) DEREF COPY-OUT `x = copy (*p)` — a WHOLE multi-variant enum read
            // through a thin reference / raw pointer into a bare enum temp (the
            // O3-inlined slice-iterator element read `_12 = copy (*_10)` from
            // `for e in &a { e.unwrap_or(0) }`, where the inlined consumer leaves
            // no call to trigger rule 3). Slot-backing `x` routes the statement to
            // `lower_memory_aggregate_use`'s single-`Deref` arm (lane copy from the
            // pointer — the same proven machinery rule 3's call-arg shape uses).
            // No working path can be stolen: a bare-enum dest with ANY projected
            // source fails closed on the scalarized path today
            // (`lower_scalarized_aggregate_use`'s source-projection gate), and the
            // memory deref arm only ever fired for dests already backed by another
            // rule. A source whose pointer local carries no scalar value (a
            // borrowed SCALARIZED aggregate ref) keeps failing closed inside that
            // arm exactly as before.
            if matches!(src.projection.as_ref(), [ProjectionElem::Deref])
                && bare_memory_enum_place(dst)
            {
                let ptr_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
                if is_thin_pointer_ref_ty(ctx.tcx, ptr_ty)
                    && place_rust_ty(ctx, body, src)
                        == ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local))
                {
                    locals.insert(dst.local);
                }
            }
        }
    }

    // (4) Address-taken aggregate locals: any local whose address is taken via a
    // bare (un-projected) `Rvalue::Ref` / `Rvalue::RawPtr` and whose type is a
    // memory-eligible aggregate the scalarized reference path CANNOT represent
    // (a multi-variant Direct enum, or an aggregate with nested aggregate fields
    // — see `memory_aggregate_address_taken_needs_slot`). Giving it a real stack
    // slot lets `&local` lower to the slot pointer and reads/writes through the
    // reference hit the slot. A flat scalar-leaf struct (e.g. `&Pair{u64,u64}`)
    // is deliberately LEFT to the existing scalarized path, and a *projected*
    // borrow (`&local.field`) is skipped, so the working scalar-reference corpus
    // is untouched.
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (_dst, rvalue) = &**boxed;
            let (source, is_raw) = match rvalue {
                Rvalue::Ref(_, _, source) => (source, false),
                Rvalue::RawPtr(_, source) => (source, true),
                _ => continue,
            };
            if !source.projection.is_empty() {
                continue;
            }
            if fmt_internal_locals.contains(&source.local) {
                continue;
            }
            let source_ty = local_rust_ty(ctx, body, source.local);
            if memory_aggregate_address_taken_needs_slot(ctx.tcx, source_ty)? {
                locals.insert(source.local);
            }
            // (4-fat) An address-taken bare FAT-POINTER local — `&str` / `&[T]`
            // (`{data,len}`) or `&dyn Trait` (`{data,vtable}`):
            // `_r = &s` where `s` is a scalarized two-lane local. `<&str as
            // PartialEq>::eq` / `<&[T]>::eq` take `&&str` / `&&[T]`, and
            // `format!("{:?}", d)` takes `&&dyn Debug`, so `a == b` (and any `&s` /
            // `&d`) needs the REFERENT's address — but a scalarized fat
            // pointer has NONE, so `&s` produced a garbage thin pointer and every deref
            // through it (the `.len()` / byte-compare inside `eq`) read garbage: a silent
            // MISCOMPILE (`"x"=="x"` -> false). Give the fat local a real 16-byte slot so
            // `&s` lowers to the slot address and reads recover the true fat pointer.
            // The `&dyn` half is the SAME defect in the other metadata kind — it
            // fails closed today only because a `&dyn` place has no single trust-ir
            // type to name, and closing it here removes that accident rather than
            // relying on it.
            if is_fat_pointer_memory_leaf_ty(ctx.monomorphize_ty(source_ty)) {
                locals.insert(source.local);
            }
            // (4a-coro) An address-taken COROUTINE FRAME (`_7 = &mut _1`, the
            // `Pin::new(&mut g)` that drives the resume loop). The frame's resume
            // STATE is a runtime discriminant the scalarized path cannot carry
            // across `Pin::new`/`resume` calls, and the resume fn reads/writes it
            // through the pointer (`discriminant((*frame))` / `SetDiscriminant`),
            // so the frame MUST occupy a real slot. Only fires for a frame whose
            // layout the byte memory model can represent (`coroutine_memory_layout`
            // returns `Ok(Some)`); an unrepresentable frame fails closed there.
            else if matches!(source_ty.kind(), ty::Coroutine(..))
                && coroutine_memory_layout(ctx.tcx, source_ty)?.is_some()
            {
                locals.insert(source.local);
            }
            // (4b) An address-taken scalar-leaf struct/tuple/single-variant enum
            // whose declaration-order trust-ir image is not rustc's layout of it
            // (`scalar_leaf_pointee_image_diverges`) — a `repr(Rust)` REORDERING, a
            // `#[repr(packed(N))]` TIGHTENING, an over-aligned field, or a
            // `repr(align(N))` aggregate larger and more aligned than its tuple. Its
            // bytes MUST be laid out at rustc offsets, in a slot of rustc's size and
            // alignment (so the `(*r).field…` access — routed through the
            // rustc-layout byte walker by `memory_aggregate_ref_pointee` — reads each
            // field at its real offset, and a whole-object copy or an
            // address-alignment test through the pointer sees the Rust object).
            // Memory-backing the source local materializes it in a slot at rustc
            // offsets (`lower_memory_aggregate_construct`), and `&local` lowers to
            // that slot pointer — so materialization and access agree (an aggregate
            // whose image IS rustc's layout stays on the untouched scalarized path).
            else if scalar_leaf_pointee_image_diverges(ctx.tcx, source_ty)? {
                locals.insert(source.local);
            }
            // (4e) An address-taken UNION (`&raw mut u` of a `MaybeUninit<T>`): a raw
            // pointer to a union needs the union to occupy a real slot, since every
            // access goes through the pointer cast to a field type. The scalarized
            // path cannot represent a union (overlapping fields), so memory-back it.
            // Only fires for a union with a usable memory layout (scalar-leaf / ZST
            // fields); a by-value union never reaching `&raw` keeps the ABI path.
            else if union_memory_layout(ctx.tcx, source_ty)?.is_some() {
                locals.insert(source.local);
            }
            // (4h) A bare `&raw const/mut x` of ANY memory-eligible aggregate
            // (struct / array) whose address is taken as a RAW pointer — e.g.
            // `UnsafeCell::get` = `&raw const cell`, and interior-mutability cells.
            // Unlike a *reference* (which keeps the scalarized snapshot), a raw
            // pointer needs a real address, so the aggregate must occupy a slot.
            // Array references need the same storage: after closure inlining,
            // `(*r)[constant]` reads/writes remain but the capturing aggregate
            // that otherwise requires the slot is gone. Both forms must alias
            // the original array. Unsupported layouts still fail closed.
            else if (is_raw || matches!(source_ty.kind(), ty::Array(..)))
                && memory_backed_local_layout(ctx.tcx, source_ty)?.is_some()
            {
                locals.insert(source.local);
            }
        }
    }

    // (4i) An address-taken local whose type has INTERIOR MUTABILITY (`!Freeze` per
    // rustc: it contains an `UnsafeCell` — `struct S { c: Cell<u32>, k: u32 }`).
    // The scalarized reference model materializes `&s` into a temp alloca and,
    // for a SHARED borrow, never reloads it — correct for a `Freeze` referent
    // (nothing can be written through `&T`), and a silent dropped store for a
    // `Cell::set` through it (the review's `adv_cell_baseline.rs`: `a=1 b=1 c=1`
    // for `100 100 7`). rustc's own answer is a real slot (every borrowed local
    // is `Memory`); give the local one whenever the memory model can represent
    // its layout, so `&s` IS its address and every interior-mutability write
    // lands where the next read looks. A `!Freeze` local the memory model cannot
    // represent stays scalarized and is REFUSED at the shared-borrow call-arg
    // sites (`lower_aggregate_reference_call_arg` /
    // `lower_scalar_reference_call_arg`) — never handed out as a temp.
    //
    // (4j) The referent of a bare `_r = &_s` whose reference `_r` is passed to a
    // call that RETURNS a reference (or a value containing one). The callee may
    // return a reference DERIVED from `_r` — `fn view(s: &S) -> &S { s }`, or
    // `fn id<T>(x: T) -> T` at `T = &S` — and the caller then reads / writes
    // through it after the call: a temp materialized for the call is the wrong
    // object for that (the review's `adv_ref6g_cell_ret.rs`: a `Cell::set`
    // through the returned `&S` never reached the register copy). Memory-backing
    // `_s` makes the passed reference a genuine address, so whatever the callee
    // returns aliases the real local. Over-approximating the callee (any
    // reference anywhere in the monomorphized return type) is the safe side:
    // more slots, never a wrong address. The residual — a referent with no
    // memory layout — is refused by `direct_scalar_ref_select_return`, which
    // fails closed on a shared `&Aggregate` return when a `borrowed_*` binding
    // is passed (the baseline refusal, restored).
    //
    // (4k) The referent of a bare `_r = &_s` whose reference `_r` has its OWN
    // address taken (`_x = &_r` / `&raw _r`, a `&&S`). A scalarized referent has
    // no address, so `_r` carries only a borrow binding and no pointer value;
    // storing `_r` behind `_x` needs `_r` to BE an address. Memory-backing `_s`
    // makes `&_s` its slot pointer, which `_r`'s own cell can then hold. `_r`'s
    // referents are every `&_s` assigned to it in any block, plus those reaching
    // it through `_r = copy _q` / `_r = &(*_q)` chains.
    {
        let typing_env = ty::TypingEnv::fully_monomorphized();
        let mut ref_sources: HashMap<Local, HashSet<Local>> = HashMap::new();
        let mut ref_copies = Vec::new();
        let mut ref_flows: HashMap<Local, Vec<Local>> = HashMap::new();
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                // (4k) reference flow: `_r = copy/move _q` and the reborrow
                // `_r = &(*_q)` make `_r` hold whatever address `_q` holds.
                if dst.projection.is_empty() {
                    let flows_from = match rvalue {
                        Rvalue::Use(Operand::Copy(q) | Operand::Move(q), _)
                            if q.projection.is_empty() =>
                        {
                            Some(q.local)
                        }
                        Rvalue::Ref(_, _, q)
                            if matches!(q.projection.as_slice(), [ProjectionElem::Deref]) =>
                        {
                            Some(q.local)
                        }
                        _ => None,
                    };
                    if let Some(q) = flows_from {
                        if matches!(local_rust_ty(ctx, body, q).kind(), ty::Ref(..)) {
                            ref_flows.entry(dst.local).or_default().push(q);
                        }
                    }
                }
                if let Rvalue::Use(Operand::Copy(source) | Operand::Move(source), _) = rvalue {
                    if dst.projection.is_empty()
                        && source.projection.is_empty()
                        && matches!(
                            ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local))
                                .kind(),
                            ty::Ref(..)
                        )
                    {
                        ref_copies.push((dst.local, source.local));
                    }
                }
                let Rvalue::Ref(_, _, source) = rvalue else {
                    continue;
                };
                if !source.projection.is_empty() || fmt_internal_locals.contains(&source.local) {
                    continue;
                }
                if dst.projection.is_empty() {
                    ref_sources
                        .entry(dst.local)
                        .or_default()
                        .insert(source.local);
                }
                // (4i)
                let source_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, source.local));
                if !source_ty.is_freeze(ctx.tcx, typing_env)
                    && memory_backed_local_layout(ctx.tcx, source_ty)?.is_some()
                {
                    locals.insert(source.local);
                }
            }
        }
        // Keep every possible referent across copies and control-flow joins.
        // This is an address requirement, so over-approximating the points-to
        // set only gives additional locals stable storage.
        loop {
            let mut changed = false;
            for &(dst, source) in &ref_copies {
                let Some(sources) = ref_sources.get(&source).cloned() else {
                    continue;
                };
                let entry = ref_sources.entry(dst).or_default();
                for referent in sources {
                    changed |= entry.insert(referent);
                }
            }
            if !changed {
                break;
            }
        }
        // (4k) A reference stored in an aggregate (including a closure
        // environment) must carry the referent's address, not a scalarized
        // snapshot. Scalar referents use compute_scalar_cell_locals; aggregates
        // use their existing rustc-layout slot. In particular, a captured
        // &mut [u16; 2] must alias the array read after the closure returns.
        for data in body.basic_blocks.iter() {
            for statement in &data.statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                if fmt_internal_locals.contains(&dst.local) {
                    continue;
                }
                let Rvalue::Aggregate(_, operands) = rvalue else {
                    continue;
                };
                for operand in operands {
                    let (Operand::Copy(place) | Operand::Move(place)) = operand else {
                        continue;
                    };
                    if !place.projection.is_empty() {
                        continue;
                    }
                    let Some(sources) = ref_sources.get(&place.local) else {
                        continue;
                    };
                    for &source in sources {
                        let source_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, source));
                        if memory_backed_local_layout(ctx.tcx, source_ty)?.is_some() {
                            locals.insert(source);
                        }
                    }
                }
            }
        }
        // (4k) A reference whose OWN address is taken (`&_r` / `&raw _r`): every
        // referent it may hold — through copies (already merged into `ref_sources`
        // above) and reborrows `_r = &(*_q)` (`ref_flows`) — needs a real address.
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (Rvalue::Ref(_, _, borrowed) | Rvalue::RawPtr(_, borrowed)) = &boxed.1 else {
                    continue;
                };
                if !borrowed.projection.is_empty() {
                    continue;
                }
                // Every referent `_r` may hold: its own `&_s` assignments (in any
                // block) and, transitively, those of each reference it is copied
                // or reborrowed from.
                let mut seen: HashSet<Local> = HashSet::new();
                let mut work = vec![borrowed.local];
                while let Some(r) = work.pop() {
                    if !seen.insert(r) {
                        continue;
                    }
                    if let Some(flows) = ref_flows.get(&r) {
                        work.extend(flows.iter().copied());
                    }
                    let Some(sources) = ref_sources.get(&r) else {
                        continue;
                    };
                    for &source in sources {
                        let source_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, source));
                        if memory_backed_local_layout(ctx.tcx, source_ty)?.is_some() {
                            locals.insert(source);
                        }
                    }
                }
            }
        }
        // (4j)
        for bb in body.basic_blocks.indices() {
            let Some(terminator) = &body.basic_blocks[bb].terminator else {
                continue;
            };
            let TerminatorKind::Call { func, args, .. } = &terminator.kind else {
                continue;
            };
            let Ok(func_ty) = operand_rust_ty(ctx, body, func) else {
                continue;
            };
            let func_ty = ctx.monomorphize_ty(func_ty);
            let output = match func_ty.kind() {
                ty::FnDef(..) => {
                    let item = fn_items::view(func_ty.kind()).expect("matched function item");
                    ctx.tcx
                        .fn_sig(item.def_id())
                        .instantiate(
                            ctx.tcx,
                            item.require_unbound_args("callee reference output")?,
                        )
                        .skip_binder()
                        .output()
                }
                ty::FnPtr(sig_tys, _) => sig_tys.skip_binder().output(),
                _ => continue,
            };
            let output = ctx.monomorphize_ty(output);
            let returns_a_reference = output
                .walk()
                .filter_map(|arg| arg.as_type())
                .any(|t| matches!(t.kind(), ty::Ref(..)));
            if !returns_a_reference {
                continue;
            }
            for arg in args {
                let (Operand::Copy(p) | Operand::Move(p)) = &arg.node else {
                    continue;
                };
                if !p.projection.is_empty() {
                    continue;
                }
                let Some(sources) = ref_sources.get(&p.local) else {
                    continue;
                };
                for &source in sources {
                    let source_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, source));
                    if memory_backed_local_layout(ctx.tcx, source_ty)?.is_some() {
                        locals.insert(source);
                    }
                }
            }
        }
    }

    // (4k) The referent of a bare `_r = &_s` / `&mut _s` whose reference `_r` is then
    // stored AS A VALUE into another aggregate — a closure capture
    // (`<wtf8::EncodeWide as Iterator>::next`: `_9 = &mut _5; _8 = {closure} { buf:
    // move _9, self: move _10 }` with `_5: [u16; 2]`), an ADT field (`H { r: &buf }`,
    // `Some(&buf)`) or a tuple element (`(&p, 4)`). The field holds the POINTER, so
    // the referent needs a real address, and a scalarized referent has none: its `&`
    // is a `borrowed_aggregates` register-model binding, and every such store fails
    // closed today ("borrowed aggregate reference used without deref"). This is the
    // aggregate-referent twin of the scalar-cell pass's "a scalar reference stored
    // INTO an aggregate as a VALUE" rule, and like (4j) it only ever adds a slot —
    // more slots, never a wrong address: `&_s` then lowers to the slot pointer
    // (`lower_scalar_ref`'s whole-memory-local arm) and every other use of `_s` goes
    // through the slot. Scope, stated exactly:
    //   * the reference is a bare `copy _r` / `move _r` operand of the aggregate; a
    //     reference first copied through another local is not followed and keeps
    //     its refusal;
    //   * the referent has a memory layout, is not itself a fat pointer (those are
    //     (4-fat)'s), has no single-scalar representation (a scalar-collapsed
    //     newtype such as `Cell<u64>` stays with the scalar-cell pass), and is not a
    //     slot-MODELED collection (`Vec` / `String` / map, whose value is already
    //     its frame slot's address);
    //   * a statement building a dead `format!`/`write!` feeder
    //     (`ctx.fmt_dead_locals`) is never lowered, so it forces nothing.
    {
        let mut ref_sources: HashMap<Local, Vec<Local>> = HashMap::new();
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                let Rvalue::Ref(_, _, source) = rvalue else {
                    continue;
                };
                if dst.projection.is_empty()
                    && source.projection.is_empty()
                    && !fmt_internal_locals.contains(&source.local)
                {
                    ref_sources.entry(dst.local).or_default().push(source.local);
                }
            }
        }
        if !ref_sources.is_empty() {
            for bb in body.basic_blocks.indices() {
                for statement in &body.basic_blocks[bb].statements {
                    let StatementKind::Assign(boxed) = &statement.kind else {
                        continue;
                    };
                    let (dst, rvalue) = &**boxed;
                    let Rvalue::Aggregate(kind, operands) = rvalue else {
                        continue;
                    };
                    if !matches!(
                        &**kind,
                        mir::AggregateKind::Closure(..)
                            | mir::AggregateKind::Adt(..)
                            | mir::AggregateKind::Tuple
                    ) || (dst.projection.is_empty() && ctx.fmt_dead_locals.contains(&dst.local))
                    {
                        continue;
                    }
                    for operand in operands.iter() {
                        let (Operand::Copy(p) | Operand::Move(p)) = operand else {
                            continue;
                        };
                        if !p.projection.is_empty() {
                            continue;
                        }
                        let Some(sources) = ref_sources.get(&p.local) else {
                            continue;
                        };
                        for &source in sources {
                            let source_ty = local_rust_ty(ctx, body, source);
                            let slot_modeled_collection = vec_element_ty(ctx.tcx, source_ty)
                                .is_some()
                                || is_string_ty(ctx.tcx, source_ty)
                                || btreemap_kv_ty(ctx.tcx, source_ty).is_some()
                                || any_hashmap_kv_ty(ctx.tcx, source_ty).is_some()
                                || is_hashmap_dead_internal_ty(ctx.tcx, source_ty);
                            if !slot_modeled_collection
                                && !is_fat_pointer_memory_leaf_ty(source_ty)
                                && memory_scalar_leaf_ty(ctx.tcx, source_ty).is_err()
                                && memory_backed_local_layout(ctx.tcx, source_ty)?.is_some()
                            {
                                locals.insert(source);
                            }
                        }
                    }
                }
            }
        }
    }

    // (4d) The BASE aggregate of a PROJECTED `Rvalue::RawPtr` (`addr_of!(s.field)`,
    // `addr_of!(a[i])`, `&raw mut s.field`). Unlike a *reference* to a field — which
    // the scalarized path can represent with a borrowed-scalar snapshot — a RAW
    // pointer needs the field to have a REAL address: it can be written through
    // (`*p = v`), offset, or round-tripped to an integer, and any of those must hit
    // the field's actual storage. So the base aggregate must be memory-backed (its
    // slot + the Field/Index offset is the field address; `lower_assign`'s
    // projected-`RawPtr` arm and `memory_place_address` resolve the chain). Applies
    // to EITHER mutability (a `*const` field pointer can be cast to `*mut` and
    // written) and is unconditional (no loop gate, unlike #81): without a slot the
    // raw pointer simply fails closed, so this only ever ENABLES a case. Excludes a
    // leading `Deref` (`&raw (*r).field` borrows through a pointer — separate
    // mechanism) and fmt-internal locals. The base must have a usable memory layout.
    // A projected reference reborrowed as a raw pointer or stored in an
    // aggregate needs the same address. Record the intermediate reference, so
    // `r = &array[i]; p = &raw const *r` gives the array real storage too. At O0
    // a tuple of references can carry the reference before the raw reborrow.
    let mut address_exposed_refs = HashSet::new();
    for data in body.basic_blocks.iter() {
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            if let Rvalue::RawPtr(_, source) = &boxed.1 {
                if matches!(source.projection.as_ref(), [ProjectionElem::Deref])
                    && is_thin_pointer_ref_ty(
                        ctx.tcx,
                        ctx.monomorphize_ty(place_rust_ty(ctx, body, &boxed.0)),
                    )
                {
                    address_exposed_refs.insert(source.local);
                }
            }
            if let Rvalue::Aggregate(_, operands) = &boxed.1 {
                for operand in operands.iter() {
                    if let Operand::Copy(source) | Operand::Move(source) = operand {
                        if source.projection.is_empty()
                            && is_thin_pointer_ref_ty(
                                ctx.tcx,
                                ctx.monomorphize_ty(local_rust_ty(ctx, body, source.local)),
                            )
                        {
                            address_exposed_refs.insert(source.local);
                        }
                    }
                }
            }
        }
    }
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            let source = match rvalue {
                Rvalue::RawPtr(_, source) => source,
                // An aggregate field needs stable storage when borrowed: the
                // borrowed-aggregate binding can name a whole local, but cannot
                // name an aggregate projection. This also includes a FLAT field
                // such as Chars.iter. Testing whether the referent needs a slot
                // as a whole local misses that case. Give the parent a slot so
                // a callee's mutations survive a subsequent whole-value move.
                // ⚑ THE `aarch64` GATE ON THE TWO DISJUNCTS BELOW IS GONE
                // (2026-09-29). Nothing in either is architecture-specific — the
                // comment above states the whole reason, that a borrowed-aggregate
                // binding can name a whole local but not an aggregate PROJECTION —
                // and the gate carried no stated reason. It is the fourth confirmed
                // instance of the aarch64-only rollout pattern in this file.
                //
                // MEASURED: it cost x86-64 TWO `library/core` roots at
                // `-Copt-level=3`. `<Rev<slice::Iter<u8>> as Iterator>` borrows its
                // inner iterator as `_r = &mut (_2.0: slice::Iter<u8>)`, and with
                // `_2` unbacked the aggregate-`Ref` arm in `lower_scalar_ref` has no
                // address to hand out — its OWN comment names this exact shape as
                // what it exists for. The refusal reported `base bound=false
                // cell=false memory_backed=false entry_arg=false`, which is what
                // identified it.
                //
                // Unlike a `&raw` of a field (rule 4d, unconditional), a `&` of a
                // SCALAR field is representable as a borrowed-scalar snapshot and
                // needs no slot; that is why this arm asks for a memory-eligible
                // AGGREGATE referent of nonzero size, which is precisely the case
                // where no snapshot exists.
                Rvalue::Ref(_, _, source)
                    if matches!(
                        ctx.monomorphize_ty(place_rust_ty(ctx, body, source)).kind(),
                        ty::Closure(..)
                    ) || ((address_exposed_refs.contains(&dst.local)
                        && source.projection.iter().all(|p| {
                            matches!(
                                p,
                                ProjectionElem::Field(..)
                                    | ProjectionElem::Downcast(..)
                                    | ProjectionElem::Index(..)
                                    | ProjectionElem::ConstantIndex { .. }
                            )
                        }))
                        || (source.projection.iter().all(|p| {
                            matches!(p, ProjectionElem::Field(..) | ProjectionElem::Downcast(..))
                        }) && {
                            let referent = ctx.monomorphize_ty(place_rust_ty(ctx, body, source));
                            box_dyn_dynamic_data(ctx.tcx, referent).is_some()
                                || matches!(
                                    memory_aggregate_layout_shared(ctx.tcx, referent),
                                    Ok(Some(layout)) if layout.size != 0
                                )
                        })) =>
                {
                    source
                }
                _ => continue,
            };
            if source.projection.is_empty()
                || matches!(source.projection.first(), Some(ProjectionElem::Deref))
            {
                continue;
            }
            if fmt_internal_locals.contains(&source.local) {
                continue;
            }
            let base_ty = local_rust_ty(ctx, body, source.local);
            if memory_backed_local_layout(ctx.tcx, base_ty)?.is_some() {
                locals.insert(source.local);
            }
        }
    }

    // (4g) The array operand/destination of an `int <-> [u8; N]` Transmute
    // (`to_le_bytes` / `from_le_bytes`). The transmute is lowered as a store/load
    // through the array's slot (`lower_int_array_transmute`), so the array must be
    // memory-backed: the DESTINATION array of an `int -> [u8;N]` transmute, or the
    // SOURCE array of a `[u8;N] -> int` transmute.
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            let Rvalue::Cast(mir::CastKind::Transmute, operand, dst_ty) = rvalue else {
                continue;
            };
            let dst_ty_m = ctx.monomorphize_ty(*dst_ty);
            let src_ty = ctx.monomorphize_ty(operand_rust_ty(ctx, body, operand)?);
            // The same array slot is needed when MIR has combined
            // `ptr.addr()` and `usize::to_ne_bytes()` into a single transmute.
            if dst.projection.is_empty()
                && is_raw_pointer_byte_array_transmute(ctx, src_ty, dst_ty_m)?
                && memory_backed_local_layout(ctx.tcx, dst_ty_m)?.is_some()
            {
                locals.insert(dst.local);
            }
            // int -> aggregate ([u8;N] array / dense struct / dense tuple):
            // memory-back the destination so the int store / field reads share a slot.
            if matches!(src_ty.kind(), ty::Int(_) | ty::Uint(_))
                && dst.projection.is_empty()
                && is_int_transmute_aggregate_ty(ctx, dst_ty_m)?
                && memory_backed_local_layout(ctx.tcx, dst_ty_m)?.is_some()
            {
                locals.insert(dst.local);
            }
            // int -> niche/byte-encoded ENUM (`u32 as Option<NonZero<u32>>`, the
            // `NonZero::new` niche encoding): the niche-transmute store needs the enum
            // in a real slot so the memory niche discriminant/payload reads decode it.
            // Width-matched, memory-backable enum, projection-free dest.
            if matches!(src_ty.kind(), ty::Int(_) | ty::Uint(_))
                && matches!(dst_ty_m.kind(), ty::Adt(adt, _) if adt.is_enum())
                && dst.projection.is_empty()
                && memory_aggregate_layout_shared(ctx.tcx, dst_ty_m)?.is_some()
            {
                locals.insert(dst.local);
            }
            // aggregate -> int ([u8;N] array / dense struct / dense tuple):
            // memory-back the source so the int load reads its slot image.
            if matches!(dst_ty_m.kind(), ty::Int(_) | ty::Uint(_)) {
                if let Operand::Copy(src) | Operand::Move(src) = operand {
                    if src.projection.is_empty()
                        && is_int_transmute_aggregate_ty(ctx, src_ty)?
                        && memory_backed_local_layout(ctx.tcx, src_ty)?.is_some()
                    {
                        locals.insert(src.local);
                    }
                }
            }
        }
    }

    // (4c) The SOURCE local of a WHOLE-aggregate write THROUGH a `&mut` / `*mut`
    // reference — `(*r) = move local` — whose type is a memory-eligible MULTI-
    // VARIANT enum the scalarized path cannot represent. This is the
    // `*v = Choice::Left(7)` write-through-reference shape: rustc constructs the
    // enum into `local` (`local = Choice::Left(7)`) then stores it whole through the
    // mutable reference. Memory-backing `local` makes its construction write the tag
    // + payload into the slot (`lower_memory_aggregate_construct`); the whole store
    // then byte-copies the slot through the pointer (`lower_aggregate_memory_store`,
    // slot-to-slot lane copy). A struct/array source keeps the scalarized path.
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            // The destination must be a bare `(*r)` deref of a mutable reference /
            // raw pointer.
            if !matches!(dst.projection.as_ref(), [ProjectionElem::Deref]) {
                continue;
            }
            let dst_base_ty = local_rust_ty(ctx, body, dst.local);
            if !matches!(
                dst_base_ty.kind(),
                ty::Ref(_, _, rustc_hir::Mutability::Mut)
                    | ty::RawPtr(_, rustc_hir::Mutability::Mut)
            ) {
                continue;
            }
            // The stored value must be a whole local move/copy of a memory-eligible
            // multi-variant enum.
            let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                continue;
            };
            if !src.projection.is_empty() || fmt_internal_locals.contains(&src.local) {
                continue;
            }
            let src_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
            if memory_enum_reference_pointee_lane_ty(ctx.tcx, src_ty)?.is_some() {
                locals.insert(src.local);
            }
        }
    }

    // (4a-#81) The BASE aggregate of a PROJECTED mutable borrow (`&mut s.field` /
    // `&mut a[i]`) whose reference escapes to a CALL inside a LOOP. The callee
    // writes through the `&mut`, but a scalarized base keeps the field/element as
    // an SSA value whose in-loop writeback is not threaded across the back-edge —
    // iteration N's mutation is lost on N+1 (a silent O0+O3 miscompile;
    // `while .. { upd(&mut s.a); }` kept `s.a`'s entry value, returning 0 not 21).
    // Giving the base a real stack slot turns `&mut s.field` into a GEP the callee
    // writes and every iteration reads. This is the aggregate analogue of the #80
    // scalar cell: #80 handles a bare `&mut scalar`, this handles `&mut agg.field`.
    //
    // Narrowed like #80: only when the call lies on a cycle (`compute_loop_blocks`),
    // only a MUTABLE borrow that projects directly INTO the local (first elem is not
    // a `Deref` — `&mut (*ptr).field` borrows through a pointer, a separate
    // mechanism), and only a base with a usable memory layout. A bare borrow is left
    // to case (4); a non-loop or read-only projected borrow keeps the scalarized
    // path, so the working scalar-reference corpus is untouched.
    {
        let loop_blocks = compute_loop_blocks(body);
        if !loop_blocks.is_empty() {
            // Reference locals passed as a projection-free argument of a call that
            // sits in a loop block.
            let mut in_loop_call_arg_refs: HashSet<Local> = HashSet::new();
            for bb in body.basic_blocks.indices() {
                if !loop_blocks.contains(&bb) {
                    continue;
                }
                let Some(terminator) = &body.basic_blocks[bb].terminator else {
                    continue;
                };
                let TerminatorKind::Call { args, .. } = &terminator.kind else {
                    continue;
                };
                for arg in args.iter() {
                    if let Operand::Copy(p) | Operand::Move(p) = &arg.node {
                        if p.projection.is_empty() {
                            in_loop_call_arg_refs.insert(p.local);
                        }
                    }
                }
            }
            // ALSO: a reference STORED THROUGH (`*r = ..`) inside a loop, with NO
            // Call — the closure-inlined sibling of the call-arg case above. A
            // closure taking `&mut s.field`, called in a loop, INLINES at O3 into a
            // bare `*r = ..` store with no Call terminator, so the call-arg scan
            // misses it and the projected `&mut s.field` writeback to a scalarized
            // base is silently DROPPED (verified miscompile: `let mut f=|r:&mut i32,v|
            // {*r+=v}; while i<11 { f(&mut s.a, i); }` left `s.a == 0` at O3 vs 55).
            // Same dropped-writeback bug, same fix: memory-back the base aggregate so
            // `&mut s.field` is a real GEP the store lands through and every iteration
            // reads. (The whole-scalar-local `&mut x` form is handled by the #80 /
            // store-through scalar cell; this is the projected `&mut agg.field` form.)
            for bb in body.basic_blocks.indices() {
                if !loop_blocks.contains(&bb) {
                    continue;
                }
                for statement in &body.basic_blocks[bb].statements {
                    let StatementKind::Assign(boxed) = &statement.kind else {
                        continue;
                    };
                    let (dst, _rvalue) = &**boxed;
                    if matches!(dst.projection.first(), Some(mir::ProjectionElem::Deref)) {
                        in_loop_call_arg_refs.insert(dst.local);
                    }
                }
            }
            for bb in body.basic_blocks.indices() {
                for statement in &body.basic_blocks[bb].statements {
                    let StatementKind::Assign(boxed) = &statement.kind else {
                        continue;
                    };
                    let (dst, rvalue) = &**boxed;
                    if !dst.projection.is_empty() || !in_loop_call_arg_refs.contains(&dst.local) {
                        continue;
                    }
                    let Rvalue::Ref(_, mir::BorrowKind::Mut { .. }, source) = rvalue else {
                        continue;
                    };
                    let source_ty = local_rust_ty(ctx, body, source.local);
                    // A single-collection-field USER struct base (`&mut s.v` of
                    // `struct S { v: Vec<int> }` inside a loop — the push-in-a-loop
                    // shape): the field borrow resolves to the struct's SHARED
                    // `{ptr,cap,len}` slot address (stable memory the callee
                    // mutates), so the scalarized-writeback hazard this rule fixes
                    // does not exist — exactly why a bare `&mut v` of a plain `Vec`
                    // is not memory-backed here. Memory-backing it would instead
                    // FAIL the whole function (its `Vec` leaf has no memory-scalar
                    // layout). Skip; an UNBOUND such struct still fails closed at
                    // the borrow/use site.
                    if struct_collection_newtype_field(ctx.tcx, ctx.monomorphize_ty(source_ty))
                        .is_some()
                    {
                        continue;
                    }
                    match source.projection.first() {
                        // (#81) A PROJECTED borrow `&mut s.field` / `&mut a[i]`: memory-
                        // back the BASE local, provided we project directly into its own
                        // aggregate storage and not through a pointer dereference.
                        Some(mir::ProjectionElem::Deref) => continue,
                        Some(_) => {}
                        // (#82) A BARE borrow `&mut agg` of an AGGREGATE (array / struct /
                        // tuple) whose callee mutates it through the `&mut` each iteration:
                        // the same dropped-writeback bug as #80, but for an aggregate the
                        // #80 scalar cell does not cover. A bare `&mut scalar` is left to
                        // the #80 cell (and to case 4 for the enum/nested-aggregate kinds);
                        // only genuine aggregates are memory-backed here.
                        None => {
                            let mono = ctx.monomorphize_ty(source_ty);
                            if matches!(
                                mono.kind(),
                                ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
                            ) {
                                continue;
                            }
                        }
                    }
                    if memory_backed_local_layout(ctx.tcx, source_ty)?.is_some() {
                        locals.insert(source.local);
                    }
                }
            }
        }
    }

    // (4a-zst) The non-zero-sized BASE of a borrowed zero-sized field or element
    // (`&s.z` / `&s.marker` / `&a[i].unit`, a Deref-free projection). rustc places
    // that borrow at `&s + offset_of!(S, z)`, and only a slot gives `s` an address
    // to add the offset to; a scalarized base could only hand out an unrelated
    // placeholder. Memory-backing it makes the borrow the slot address plus
    // rustc's offset (`zst_ref_is_memory_place_address`). A base with no usable
    // memory layout keeps its per-place placeholder.
    for data in body.basic_blocks.iter() {
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let Rvalue::Ref(_, _, source) = &boxed.1 else {
                continue;
            };
            if source.projection.is_empty()
                || source
                    .projection
                    .iter()
                    .any(|elem| matches!(elem, mir::ProjectionElem::Deref))
            {
                continue;
            }
            let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, source.local));
            if is_zero_sized_ty(ctx.tcx, base_ty)
                || !is_zero_sized_ty(
                    ctx.tcx,
                    ctx.monomorphize_ty(place_rust_ty(ctx, body, source)),
                )
                || struct_collection_newtype_field(ctx.tcx, base_ty).is_some()
                || vec_element_ty(ctx.tcx, base_ty).is_some()
                || is_string_ty(ctx.tcx, base_ty)
                || btreemap_kv_ty(ctx.tcx, base_ty).is_some()
                || any_hashmap_kv_ty(ctx.tcx, base_ty).is_some()
                || is_hashmap_dead_internal_ty(ctx.tcx, base_ty)
            {
                continue;
            }
            if memory_backed_local_layout(ctx.tcx, base_ty)?.is_some() {
                locals.insert(source.local);
            }
        }
    }

    // (4b) `for` loop iterator-state locals. A `Range<scalar>` or
    // `core::slice::Iter<T>` local is the mutable state of a desugared `for`
    // loop; the intercepted `into_iter` / `Iterator::next` read and write it
    // through its slot (its NATURAL `{ start, end }` / `{ ptr, end }` layout), and
    // `&mut it` must therefore lower to the slot pointer. These types occur ONLY
    // in `for` loops, so memory-backing every one of them is precise and never
    // steals a working corpus case (the bridge does not otherwise lower them).
    // Also memory-back any scalar-element ARRAY whose `&arr` feeds an `into_iter`
    // call, so the slice iterator's data pointer is the array's real storage.
    for local in body.local_decls.indices() {
        let ty = local_rust_ty(ctx, body, local);
        if range_index_ty(ctx.tcx, ty).is_some()
            || range_inclusive_index_ty(ctx.tcx, ty).is_some()
            || slice_iter_element_ty(ctx.tcx, ty).is_some()
        {
            // Only memory-back it if it has a usable memory layout (it always does
            // for a scalar-index Range / RangeInclusive / scalar-element Iter);
            // otherwise leave it to the existing path, which fails closed on its
            // own terms. A `RangeInclusive<scalar>` (the `start..=end` iterator
            // state) is a 3-field `{ start, end, exhausted }` struct memory-backed
            // exactly like a `Range` so the intercepted `new` / `into_iter` /
            // `next` (and at `-O3` the inlined aggregate + `spec_next`) read & write
            // it through its slot.
            if memory_backed_local_layout(ctx.tcx, ty)?.is_some() {
                locals.insert(local);
            }
        } else if matches!(iter_chain_slot_size(ctx, ty), Ok(Some(_))) {
            // A `Map` / `Filter` (or nested) adapter local: the runtime state of an
            // intercepted iterator-adapter chain. Memory-back it with a raw byte
            // slot (its full layout size) so the adapter constructor / consumer can
            // read & write the inner iterator state and closure-env addresses. Only
            // chains we fully model (scalar source + ZST adapter closures) match
            // here; everything else falls through (and fails closed on its own).
            locals.insert(local);
        }
    }
    // Arrays whose `&arr` is the argument of an `into_iter` call: record
    // `ref_local -> arr`, then memory-back `arr` if `ref_local` feeds `into_iter`.
    {
        let mut array_ref: HashMap<Local, Local> = HashMap::new();
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                let (Rvalue::Ref(_, _, source) | Rvalue::RawPtr(_, source)) = rvalue else {
                    continue;
                };
                if !source.projection.is_empty() || !dst.projection.is_empty() {
                    continue;
                }
                if array_memory_layout(ctx.tcx, local_rust_ty(ctx, body, source.local))?.is_some() {
                    array_ref.insert(dst.local, source.local);
                }
            }
        }
        for bb in body.basic_blocks.indices() {
            let data = &body.basic_blocks[bb];
            let Some(terminator) = &data.terminator else {
                continue;
            };
            let TerminatorKind::Call {
                args, destination, ..
            } = &terminator.kind
            else {
                continue;
            };
            // ONLY a call that produces a `slice::Iter<T>` (i.e. the `into_iter`
            // of a slice / array reference) makes its array argument the iterator's
            // backing storage. A plain `&arr` argument to any OTHER call (e.g.
            // `read_array(&arr)`) must NOT be memory-backed here — that would steal
            // the working scalarized-array-reference corpus. Identify `into_iter`
            // by its `slice::Iter` result type (the only call yielding one).
            if destination.projection.is_empty() {
                let dest_ty = local_rust_ty(ctx, body, destination.local);
                if slice_iter_element_ty(ctx.tcx, dest_ty).is_none() {
                    continue;
                }
            } else {
                continue;
            }
            for arg in args.iter() {
                if let Operand::Copy(place) | Operand::Move(place) = &arg.node {
                    if place.projection.is_empty() {
                        if let Some(arr) = array_ref.get(&place.local) {
                            locals.insert(*arr);
                        }
                    }
                }
            }
        }
    }

    // (5) Scalar-element ARRAY locals whose address feeds a RUNTIME slice fat
    // pointer (a `&arr as &[T]` unsize). `&arr` must produce a REAL address so the
    // slice's data pointer is the array's storage and `data + i*size` lands in it;
    // the array is therefore memory-backed and `&arr` lowers to its slot pointer.
    //
    // This is DELIBERATELY narrow: an array referenced as a FIXED-array reference
    // (`&[u64; 2]` passed by reference / indexed through the scalarized path) is
    // NOT memory-backed, so the existing scalarized array-reference corpus is
    // untouched. We match only the `arr -> &arr -> (&arr as &[T] Unsize)` chain.
    //   1. find every `ref_local = &arr` (a bare `Rvalue::Ref`/`RawPtr` of a
    //      scalar-element array local), recording `ref_local -> arr`;
    //   2. memory-back `arr` iff some `_ = ref_local as &[T] (Unsize)` exists.
    let mut array_ref_source: HashMap<Local, Local> = HashMap::new();
    let mut raw_reborrow_array_sources: HashMap<Local, HashSet<Local>> = HashMap::new();
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            let (Rvalue::Ref(_, _, source) | Rvalue::RawPtr(_, source)) = rvalue else {
                continue;
            };
            if !source.projection.is_empty() || !dst.projection.is_empty() {
                continue;
            }
            if array_memory_layout(ctx.tcx, local_rust_ty(ctx, body, source.local))?.is_some() {
                array_ref_source.insert(dst.local, source.local);
                raw_reborrow_array_sources
                    .entry(dst.local)
                    .or_default()
                    .insert(source.local);
            }
        }
    }
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            // A raw reborrow exposes the scalar array's address just as unsizing
            // does. Keep its backing storage stable before any reference use.
            if let Rvalue::RawPtr(_, source) = rvalue {
                if matches!(source.projection.as_ref(), [ProjectionElem::Deref]) {
                    if let Some(array_locals) = raw_reborrow_array_sources.get(&source.local) {
                        locals.extend(array_locals.iter().copied());
                    }
                }
            }
            let Rvalue::Cast(
                mir::CastKind::PointerCoercion(PointerCoercion::Unsize, _),
                operand,
                dst_ty,
            ) = rvalue
            else {
                continue;
            };
            if !is_slice_or_str_fat_ptr_ty(ctx.monomorphize_ty(*dst_ty)) {
                continue;
            }
            let _ = dst;
            let (Operand::Copy(p) | Operand::Move(p)) = operand else {
                continue;
            };
            if let Some(array_local) = array_ref_source.get(&p.local).copied() {
                locals.insert(array_local);
            }
        }
    }

    // (5b) Scalar-element ARRAY locals indexed by a RUNTIME index. A literal index
    // (`arr[2]`) lowers to `arr[idx]` where `idx` is a const-assigned local — the
    // scalarized array path resolves it to a static field and stays untouched. But
    // a genuine runtime index (`arr[i]` with `i` a loop variable / parameter)
    // cannot be a static field of a scalarized array, so the array must live in a
    // real stack slot whose element address `slot + i*stride` is computed at run
    // time. We memory-back a scalar-element array iff it is indexed by an
    // `Index(local)` whose index local is NOT a compile-time constant.
    //
    // The constant-index set is the locals directly assigned a constant operand
    // (`idx = const N`) — exactly what `projected_field_index` would resolve on the
    // scalarized path. Anything else is treated as runtime, forcing a slot (sound:
    // a slot serves constant indices too, it is just not required for them).
    {
        let mut const_index_locals: HashSet<Local> = HashSet::new();
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                if !dst.projection.is_empty() {
                    continue;
                }
                if matches!(rvalue, Rvalue::Use(Operand::Constant(_), _)) {
                    const_index_locals.insert(dst.local);
                }
            }
        }
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                // The indexed array appears as the base local of any place (the
                // assignment destination or an operand source) carrying an
                // `Index(idx)` projection. Scan both sides.
                let mut places: Vec<&Place<'tcx>> = vec![dst];
                collect_rvalue_places(rvalue, &mut places);
                for place in places {
                    for elem in place.projection.iter() {
                        let ProjectionElem::Index(idx) = elem else {
                            continue;
                        };
                        if const_index_locals.contains(&idx) {
                            continue;
                        }
                        // A runtime index over a scalar-element array local: memory
                        // back it (if it has a scalar-element array layout).
                        let array_ty = local_rust_ty(ctx, body, place.local);
                        if array_memory_layout(ctx.tcx, array_ty)?.is_some() {
                            locals.insert(place.local);
                        }
                    }
                }
            }
        }
    }

    // (5c) AGGREGATE-element ARRAY locals (`[P; N]`, `[(i32,i32); N]`,
    // `[[P; 1]; 1]`) that are CONSTRUCTED locally (an array `Aggregate`, a
    // `Repeat`, or a whole-array `Use` copy) OR accessed through a projected
    // element (`arr[i].field` / `arr[i][j]`). Unlike a scalar-element array, the
    // scalarized representation CANNOT model an array whose element is itself an
    // aggregate: `lower_array_aggregate` fails closed on aggregate-value /
    // const-aggregate element operands, and `lower_const_scalarized_aggregate_use`
    // only handles scalar elements. Such an array must therefore live in a real
    // stack slot, where each element's scalar leaves are stored / loaded at
    // `i*element_size + leaf_offset` (the memory aggregate-element array path,
    // `lower_memory_aggregate_element_array_assign` + `memory_place_address`).
    //
    // Soundness: gated on `array_memory_layout` succeeding, which admits the array
    // ONLY when every element leaf is a memory scalar at a fixed layout offset
    // (rejecting fat-pointer / union / niche-enum / ZST-unit leaves). A
    // scalar-element array (`[u64; N]`) is deliberately EXCLUDED here (its element
    // is a single scalar leaf) so the existing scalarized scalar-array corpus is
    // untouched; those keep their scalarization fast path and are only
    // memory-backed by the runtime-index rule (5b). This rule is purely additive:
    // an aggregate-element array previously failed closed on construction, so
    // memory-backing it can only turn a closed failure into a correct lowering.
    {
        // Element-aggregate arrays whose `array_memory_layout` admits them but
        // whose element is NOT a single scalar leaf (i.e. a genuine aggregate
        // element). A trait-object-element array (`[&dyn T; N]`) has its own
        // dedicated fat-pointer path; it is still byte-addressable here, so it is
        // included when constructed locally.
        let is_aggregate_element_array = |array_ty: Ty<'tcx>| -> Result<bool, String> {
            let ty::Array(element_ty, _) = array_ty.kind() else {
                return Ok(false);
            };
            if array_memory_layout(ctx.tcx, array_ty)?.is_none() {
                return Ok(false);
            }
            // A scalar-leaf element keeps the existing scalarized path.
            Ok(memory_scalar_leaf_ty(ctx.tcx, *element_ty).is_err())
        };
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                // (a) Local construction: `arr = [e0, e1, …]` / `arr = [e; N]` /
                //     `arr = other_arr`, with a projection-free aggregate-element
                //     array destination.
                if dst.projection.is_empty() {
                    let dst_ty = local_rust_ty(ctx, body, dst.local);
                    let constructs = match rvalue {
                        Rvalue::Aggregate(kind, _) => {
                            matches!(&**kind, mir::AggregateKind::Array(_))
                        }
                        Rvalue::Repeat(..) => true,
                        Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) => {
                            src.projection.is_empty()
                        }
                        _ => false,
                    };
                    if constructs && is_aggregate_element_array(dst_ty)? {
                        locals.insert(dst.local);
                    }
                }
                // (b) A projected element access on either side
                //     (`arr[i].f = …` / `… = arr[i].f`): the base array local of
                //     any place carrying an `Index`/`ConstantIndex` projection.
                let mut places: Vec<&Place<'tcx>> = vec![dst];
                collect_rvalue_places(rvalue, &mut places);
                for place in places {
                    if !projection_has_index_element(&place.projection) {
                        continue;
                    }
                    let array_ty = local_rust_ty(ctx, body, place.local);
                    if is_aggregate_element_array(array_ty)? {
                        locals.insert(place.local);
                    }
                }
            }
        }
    }

    // (6) CAPTURING (non-ZST) closure locals: a closure value whose captured
    // upvars all scalarize gets a real stack slot (its layout's lane tuple), so
    // `&closure` / `&mut closure` is the env address the closure body reads its
    // upvars through, and an `FnMut` env's by-value upvar mutations persist
    // across calls (the slot is mutated in place). A ZST closure (no captures —
    // the only closure the prior corpus exercised) has no layout and is NOT
    // matched here, keeping it on the existing scalarized path. A closure with a
    // capture we cannot flat-slot (a moved aggregate / heap value) makes
    // `closure_memory_layout` return `Err`, which propagates and fails the whole
    // function closed rather than miscompiling.
    for local in body.local_decls.indices() {
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if matches!(ty.kind(), ty::Closure(..)) && closure_memory_layout(ctx.tcx, ty)?.is_some() {
            locals.insert(local);
        }
    }

    // (7) Destinations of a `dst = (src.<Downcast>.field)` read where `dst`'s type
    // is itself a memory-eligible aggregate (a nested enum / struct payload). This
    // is the `?`-operator residual: `_res = ((_cf as Break).0: Result<Infallible,
    // E>)` reads the `ControlFlow::Break` payload (a nested enum) out of the
    // memory-backed `ControlFlow` slot into the residual local `_res`, which is
    // then handed to `FromResidual::from_residual`. The scalarized path cannot
    // represent such a nested-enum payload (its discriminant + per-variant payload
    // does not nest under an outer field), so the residual must live in its own
    // slot; the read becomes a byte copy at the field offset
    // (`lower_memory_nested_enum_field_use`). Narrow by construction: only a local
    // whose type genuinely needs a slot (`memory_aggregate_layout` succeeds —
    // multi-variant / nested-field enums & structs the scalar path rejects) read
    // out of a Downcast-projected memory source is matched.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if !dst.projection.is_empty() {
                continue;
            }
            let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                continue;
            };
            let has_downcast = src
                .projection
                .iter()
                .any(|elem| matches!(elem, ProjectionElem::Downcast(..)));
            if !has_downcast {
                continue;
            }
            let dst_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local));
            if matches!(memory_aggregate_layout_shared(ctx.tcx, dst_ty), Ok(Some(_))) {
                locals.insert(dst.local);
            }
        }
    }

    // (8) A memory-eligible ENUM local whose VARIANT is established in two or more
    // DISTINCT basic blocks — i.e. a C-like / multi-variant enum reassigned across
    // a branch:
    //
    // ```text
    // let mut state = State::Idle;        // bb0: _2 = State::Idle
    // if flag { state = State::Busy; }    // bb1: _2 = move _5
    // state                               // bb2: _0 = copy _2
    // ```
    //
    // The scalarized enum representation carries the discriminant as a COMPILE-TIME
    // `adt_discriminants` binding (there is no runtime tag value), so it cannot
    // survive a CFG join where the variant differs per predecessor: after the
    // merge `_2`'s variant is runtime-dependent and the binding is gone, making any
    // later read (`discriminant(_2)`, a whole-aggregate copy `_0 = _2`) fail
    // closed. Giving such a local a real stack slot makes each branch STORE its tag
    // and the post-join read LOAD the runtime tag — exactly the memory-enum path.
    //
    // Narrow by construction: we match only an ENUM whose `memory_aggregate_layout`
    // succeeds (the scalar path already rejects it) and that is assigned (projection
    // -free) in 2+ blocks. A single-block (straight-line) enum keeps the existing
    // scalarized path. Sound: a slot serves a single-block enum too; it is just not
    // required there, so restricting to multi-block avoids disturbing that corpus.
    {
        let mut assign_blocks: HashMap<Local, HashSet<mir::BasicBlock>> = HashMap::new();
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, _rvalue) = &**boxed;
                if !dst.projection.is_empty() {
                    continue;
                }
                let dst_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local));
                let is_enum = matches!(dst_ty.kind(), ty::Adt(adt, _) if adt.is_enum());
                if !is_enum {
                    continue;
                }
                if !matches!(memory_aggregate_layout_shared(ctx.tcx, dst_ty), Ok(Some(_))) {
                    continue;
                }
                assign_blocks.entry(dst.local).or_default().insert(bb);
            }
        }
        for (local, blocks) in assign_blocks {
            if blocks.len() >= 2 {
                locals.insert(local);
            }
        }
    }

    // (A5) The BASE aggregate (struct / tuple / array / nested combination) of a
    // local carrying a `>= 2`-level STRUCTURAL projection chain — `o.b.x`,
    // `o.b.c.x`, `s.arr[i]`, `(t.0).0`, `e.<Downcast>.f.g` — that the SINGLE-LEVEL
    // scalarized binder CANNOT resolve. The scalarized place machinery only binds a
    // ONE-level projection (`projected_field_index` resolves `[Field]`,
    // `[Downcast, Field]`, `[Index(const)]`, `[ConstantIndex]`); a deeper
    // Field/Downcast/Index chain falls through to `place_to_value`'s
    // `Err("Place projection")` on a READ, `scalar_place_binding`'s "assignment
    // destination projection is not scalar-bindable" on a WRITE, and the scalarized
    // aggregate path on CONSTRUCTION (`Ty::[T; N]` field) — i.e. the function FAILS
    // CLOSED today. Memory-backing the base local routes every such access through
    // the byte-offset address walker (`memory_place_address` ->
    // `walk_memory_projection_{offset,runtime_address}`), which already resolves an
    // ARBITRARY-DEPTH Field/Downcast/Index chain: a read becomes a typed `Load` at
    // the leaf offset (`lower_operand_to_value`/`lower_operand` ->
    // `local_is_memory_backed` -> `lower_memory_place_load`), a write a typed
    // `Store` (`lower_assign` -> `lower_memory_aggregate_assign` ->
    // `lower_memory_aggregate_use` -> `lower_memory_place_store`), and construction
    // stores each field operand into the slot at its layout offset
    // (`lower_memory_aggregate_construct` -> `store_operand_into_memory_at`).
    //
    // SOUNDNESS KEYSTONE: this fires ONLY for a `len >= 2`, all-structural chain
    // that `projected_field_index` does NOT resolve — precisely the chains the
    // scalar path cannot bind, so ANY function it alters was already non-compiling.
    // It can only turn a closed failure into a correct lowering; it never regresses
    // a compiling function and never miscompiles. The exclusions are PRESERVED:
    //   * a leading `Deref` is skipped — the ref / raw-ptr `(*r).field…` chain is the
    //     already-fixed A1-A4 path handled by `memory_aggregate_ref_pointee`;
    //   * a `core::fmt` plumbing local is skipped (decoded statically, no layout);
    //   * the layout gate `memory_backed_local_layout == Ok(Some)` EXCLUDES
    //     Vec/String/maps/Box/single-scalar-newtypes (all map to `Ptr`/`None` via
    //     `rust_ty_to_trust_ir_ty`, so `Ok(None)`) and fat-ptr / niche / otherwise
    //     unsupported aggregates (an `Err`, which is SWALLOWED here via
    //     `matches!(.., Ok(Some(_)))` — NOT propagated with `?` — so the enclosing
    //     function stays lowerable and fails closed only when the genuine access is
    //     lowered);
    //   * the `len >= 2` clause never matches the single-level-accessed `(T, bool)`
    //     overflow tuple, so that scalarized interception is untouched.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            let mut places: Vec<&Place<'tcx>> = vec![dst];
            collect_rvalue_places(rvalue, &mut places);
            for place in places {
                // fmt plumbing — decoded statically, never memory-backed.
                if fmt_internal_locals.contains(&place.local) {
                    continue;
                }
                // The ref / raw-ptr `(*r).field…` deref chain is the A1-A4 path
                // (`memory_aggregate_ref_pointee`), not a bare-local projection.
                if matches!(place.projection.first(), Some(ProjectionElem::Deref)) {
                    continue;
                }
                // Only a `>= 2`-level chain the single-level binder cannot resolve.
                if place.projection.len() < 2 {
                    continue;
                }
                let all_structural = place.projection.iter().all(|elem| {
                    matches!(
                        elem,
                        ProjectionElem::Field(..)
                            | ProjectionElem::Downcast(..)
                            | ProjectionElem::Index(_)
                            | ProjectionElem::ConstantIndex { .. }
                    )
                });
                if !all_structural {
                    continue;
                }
                // A single-level projection `projected_field_index` resolves stays
                // on the scalarized path; only the chains it CANNOT bind reach here.
                if matches!(projected_field_index(ctx, place), Ok(Some(_))) {
                    continue;
                }
                let base_ty = local_rust_ty(ctx, body, place.local);
                // SWALLOW an `Err` (fat-ptr / niche / unsupported aggregate base):
                // do NOT propagate with `?` — keep the function lowerable, failing
                // closed only when the genuine access is lowered.
                if matches!(memory_backed_local_layout(ctx.tcx, base_ty), Ok(Some(_))) {
                    locals.insert(place.local);
                }
            }
        }
    }

    // Keep both ends of a whole-enum COPY (`D = copy/move S`, projection-free) on
    // the SAME representation. The `core::mem::replace` / `Option::take` /
    // `Option::replace` shape an `Option<T>` carried across a loop produces mixes a
    // memory-backed enum (a runtime tag in a slot) with a single-use enum temp:
    //
    // ```text
    // _t = Option::Some(move _i);   // build the replacement (single construct)
    // _4 = copy _7;                 // read the OLD value
    // _7 = move _t;                 // replace in place
    // _5 = discriminant(_4);        // then match the OLD value
    // ```
    //
    // `_7` is memory-backed (the multi-block forward/loop case above gave it a
    // runtime tag). A whole-enum copy can only be lowered when DESTINATION and
    // SOURCE share a representation: a memory enum copies its slot leaves
    // (`copy_memory_aggregate_leaves`) and a scalarized enum copies its
    // compile-time `adt_discriminants` binding — the two cannot mix
    // ("memory aggregate whole assignment from non-memory source" /
    // "ADT Use source discriminant before aggregate binding"). So whenever EITHER
    // end of a whole-enum copy is memory-backed, the OTHER (if a layout-eligible
    // enum) must be too: the read-out temp `_4` gets a slot so `discriminant(_4)`
    // reads its runtime tag, and the construct temp `_t` gets a slot so `_7 =
    // move _t` is a memory-to-memory copy.
    //
    // Narrow + sound: fires ONLY when one end is ALREADY memory-backed (a runtime
    // tag — precisely the case the scalarized whole-enum copy cannot represent), so
    // no working compile-time-discriminant copy is disturbed; and only for an enum
    // the scalar path rejects (`memory_aggregate_layout` succeeds, which requires
    // `rust_ty_to_trust_ir_ty` to fail). The fixpoint propagates through copy
    // chains in both directions.
    {
        let is_layout_eligible_enum = |local: Local| {
            let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
            matches!(ty.kind(), ty::Adt(adt, _) if adt.is_enum())
                && matches!(memory_aggregate_layout_shared(ctx.tcx, ty), Ok(Some(_)))
        };
        let mut changed = true;
        while changed {
            changed = false;
            for bb in body.basic_blocks.indices() {
                for statement in &body.basic_blocks[bb].statements {
                    let StatementKind::Assign(boxed) = &statement.kind else {
                        continue;
                    };
                    let (dst, rvalue) = &**boxed;
                    let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                        continue;
                    };
                    if !dst.projection.is_empty() || !src.projection.is_empty() {
                        continue;
                    }
                    let dst_backed = locals.contains(&dst.local);
                    let src_backed = locals.contains(&src.local);
                    // Propagate from whichever end is already memory-backed to the
                    // other layout-eligible enum end.
                    if src_backed
                        && !dst_backed
                        && is_layout_eligible_enum(dst.local)
                        && locals.insert(dst.local)
                    {
                        changed = true;
                    }
                    if dst_backed
                        && !src_backed
                        && is_layout_eligible_enum(src.local)
                        && locals.insert(src.local)
                    {
                        changed = true;
                    }
                }
            }
        }
    }

    // (N) Loop-carried scalarized aggregate accumulators (gap A / the #71
    // store-drop class). A struct/array/tuple LOCAL that is live across a loop
    // back-edge and MUTATED inside the loop (a whole reassign or a field/index
    // store) cannot be carried by the loop-header SCALAR phi machinery (that only
    // threads scalars), so if it stays scalarized its in-loop update is dropped
    // across the back-edge — `loop_carried_completeness_error` fails it closed.
    // Memory-back it: read via `Load`, written via `Store`/`gep`, its stable slot
    // address is loop-invariant so the update round-trips and survives the
    // back-edge (exactly the condition that gate accepts).
    //
    // SAFETY SCOPE — provably avoids the call-interception landmines: we ONLY back
    // a local that is NEVER a call DESTINATION. A scalarizing interception
    // (`overflowing_*` -> a `(T, bool)` tuple bound as projected SSA values, etc.)
    // writes its result on the SCALARIZED path; memory-backing such a destination
    // would make the later `_d.0`/`_d.1` reads load an UNWRITTEN slot and
    // miscompile (see the `integer_byval_tuple_eligible` skip in case 3 above).
    // Restricting to non-call-dest aggregates means the local is built by
    // statement-level construction / field stores / copies — all of which the
    // memory-backing machinery already lowers (case 1-3 aggregates exercise the
    // same Alloca/Load/Store/gep paths). Unions (gate-rejected separately) and
    // enums (niche/discriminant layout, deferred) are excluded. Only aggregates
    // with a real lowerable slot layout are added; anything else stays scalarized
    // and the gate's fail-closed is unchanged.
    {
        let dominators = body.basic_blocks.dominators();
        let predecessors = basic_block_predecessors(body);
        let successors: Vec<Vec<mir::BasicBlock>> = body
            .basic_blocks
            .iter_enumerated()
            .map(|(_, data)| terminator_successors(&data.terminator().kind))
            .collect();
        let live_in = compute_live_in(body, &successors);

        // Whole-local call destinations: excluded (avoids every call-interception
        // landmine, known or unknown).
        let mut call_dest_locals: HashSet<Local> = HashSet::new();
        // Blocks that assign each local by a statement (whole-local OR through a
        // field/index projection), keyed by the assigned local; a store THROUGH a
        // reference (`*r = ..`) does not redefine `r`, so skip deref-leading dests.
        let mut assign_blocks: HashMap<Local, Vec<mir::BasicBlock>> = HashMap::new();
        for (bb, data) in body.basic_blocks.iter_enumerated() {
            for statement in &data.statements {
                if let StatementKind::Assign(boxed) = &statement.kind {
                    if matches!(boxed.0.projection.first(), Some(ProjectionElem::Deref)) {
                        continue;
                    }
                    assign_blocks.entry(boxed.0.local).or_default().push(bb);
                }
            }
            if let Some(term) = &data.terminator {
                if let TerminatorKind::Call { destination, .. } = &term.kind {
                    if destination.projection.is_empty() {
                        call_dest_locals.insert(destination.local);
                    }
                }
            }
        }

        for (header, _) in body.basic_blocks.iter_enumerated() {
            let is_loop_header = predecessors[header.index()]
                .iter()
                .any(|pred| dominators.is_reachable(*pred) && dominators.dominates(header, *pred));
            if !is_loop_header {
                continue;
            }
            for local in live_in[header.index()].iter().copied() {
                if locals.contains(&local)
                    || fmt_internal_locals.contains(&local)
                    || call_dest_locals.contains(&local)
                {
                    continue;
                }
                let mutated_in_loop = assign_blocks.get(&local).is_some_and(|blocks| {
                    blocks
                        .iter()
                        .any(|&b| dominators.is_reachable(b) && dominators.dominates(header, b))
                });
                if !mutated_in_loop {
                    continue;
                }
                let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
                let is_backable_aggregate = match ty.kind() {
                    ty::Adt(adt, _) => adt.is_struct(),
                    ty::Tuple(elems) => !elems.is_empty(),
                    ty::Array(_, _) => true,
                    _ => false,
                };
                if !is_backable_aggregate {
                    continue;
                }
                // Add ONLY when a real slot layout exists; otherwise leave it
                // scalarized (the gate's sound fail-closed is then unchanged).
                if matches!(memory_backed_local_layout(ctx.tcx, ty), Ok(Some(_))) {
                    locals.insert(local);
                }
            }
        }
    }

    // (Nc) A local defined by `dst = const <aggregate>` whose type is a NESTED /
    // non-flat memory aggregate (a struct/tuple/array with a nested-aggregate field,
    // e.g. `const O: Outer = Outer { inner: Inner { .. }, .. }`). Its flat
    // scalarization fails — each field must be a single scalar leaf — so a const use
    // otherwise falls closed at `lower_const_scalarized_struct_or_tuple_use` /
    // `lower_scalarized_aggregate_use` ("ADT/tuple Use from non-place operand").
    // Route it to memory: the const's byte image is written into the slot and every
    // nested field read projects from it — exactly the path an ADDRESS-TAKEN const
    // nested aggregate already takes and that runs == LLVM. `memory_aggregate_layout`
    // returns `Some` ONLY when the flat scalar mapping fails, so a FLAT const
    // struct/tuple (which keeps its working scalarized path) is never matched.
    // Additive: a scalarized const nested aggregate fails closed today, so forcing
    // memory-backing steals no working case.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if !dst.projection.is_empty() || fmt_internal_locals.contains(&dst.local) {
                continue;
            }
            let Rvalue::Use(Operand::Constant(_), _) = rvalue else {
                continue;
            };
            let dst_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local));
            if matches!(memory_aggregate_layout_shared(ctx.tcx, dst_ty), Ok(Some(_))) {
                locals.insert(dst.local);
            }
        }
    }

    // (9-upvar) A slice/str fat-pointer local assigned from a CAPTURING CLOSURE's
    // fat upvar — `dst = copy/move ((*env).N)` where `env` is the closure env
    // pointer and field `N` is a `&[T]`/`&str` fat pointer. This is the `-O0`
    // shape where the closure body copies its fat upvar into a `&[T]`/`&str` temp
    // before `PtrMetadata`/indexing (`_14 = copy ((*_1).0: &[i64])`); at `-O2/-O3`
    // that temp is optimized away (the upvar is read directly in the metadata/index
    // op). Force `dst` memory-backed so the assignment routes through
    // `lower_memory_slice_assign`'s closure-env fat-upvar arm — which loads BOTH
    // `{data,len}` lanes — instead of the scalar operand path, which rejects a fat
    // leaf as "not a single scalar" and fails closed. Seeded BEFORE the (9) fixpoint
    // so any downstream slice-copy chain propagates. Additive: an un-slot-backed
    // fat-upvar-read slice local fails closed today, so this steals no working case.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if !dst.projection.is_empty() || fmt_internal_locals.contains(&dst.local) {
                continue;
            }
            if !is_slice_or_str_fat_ptr_ty(local_rust_ty(ctx, body, dst.local)) {
                continue;
            }
            let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                continue;
            };
            if is_closure_env_fat_field_source(ctx, body, src) {
                locals.insert(dst.local);
            }
        }
    }

    // (9-join) A JOIN-CARRIED CONST slice/str local: a bare `&[T]` / `&str` local
    // whose EVERY definition is a const slice literal, made in at least two blocks
    // with at least two different lengths, and which flows by value into an
    // ADT/tuple aggregate built in a memory-backed destination — directly, or
    // through whole-value copies of it (the -O0 spelling `_3 = copy _2;
    // _0 = (move _3, copy _1)`). The shape is a `match` that picks a literal per
    // arm and wraps it after the join:
    //
    //     bb2:  _2 = const "...";  goto -> bb23;
    //     bb3:  _2 = const "_";    goto -> bb23;
    //     bb23: _0 = Option::<&str>::Some(copy _2);
    //
    // (`rustc_demangle::v0::basic_type`; gimli's `dw!` `static_string`, and every
    // `Display::fmt` it is inlined into.) Left scalarized, the local carries the
    // const-slice representation — a data scalar plus a COMPILE-TIME length in
    // `pointer_metadata_lengths` — and that length cannot cross the join:
    // `merge_scalarized_states` keeps a side-table entry only when every
    // predecessor agrees, so the data pointer is phi'd and the length is DROPPED.
    // The aggregate's fat-leaf store (`store_operand_into_memory_at`) then finds a
    // data half with no length and `resolve_slice_source_data_len` fails closed
    // ("no resolvable (data, len) representation") — correctly, since no single
    // compile-time length is right on every edge. A `{ data, len }` slot is the
    // representation that carries a branch-varying length: each definition stores
    // BOTH lanes through `lower_memory_slice_assign`'s const-literal arm, and the
    // aggregate store reads both back through the resolver's memory-backed arm.
    // Both halves are already exercised on shipped shapes and were measured on the
    // frozen r3 compiler against LLVM at -O0 and -O3: the SAME branch-carried
    // literal passed to a call (which (3b) already slot-backs) returns the per-arm
    // length, and a slot-backed `&str` wrapped in `Some` and returned round-trips
    // its contents. This rule only changes which representation the local gets.
    //
    // Gated so it steals no working case and routes to no unmeasured consumer
    // (`join_carried_const_slice_locals`): equal lengths keep the side table (the
    // merge preserves an agreed length). The unit is the COPY COMPONENT — the
    // locals joined by whole-value `Use`/`Transmute` edges, which rule (9) below
    // slot-backs together anyway — and every member must pass: each definition is
    // a const slice literal or an edge from another member, and every bare
    // by-value use is an ADT/tuple aggregate operand into a memory-backed
    // destination, a call argument, an edge to another member, or a `PtrMetadata`
    // read. Any other definition or bare use — a call destination, a closure
    // capture, an array element, a borrow of the whole local, an aggregate into a
    // SCALARIZED destination — leaves the whole component out and its existing
    // fail-closed path in place. Placed before (9).
    for local in join_carried_const_slice_locals(ctx, body, &locals) {
        if !fmt_internal_locals.contains(&local) {
            locals.insert(local);
        }
    }

    // (9) REASSIGN/copy propagation: a slice-`&[T]` / `&str` fat-pointer local
    // joined to an already-memory-backed slice/str fat-pointer local by a
    // WHOLE-VALUE fat-pointer edge — a `Use` copy (`dst = copy/move src`) OR a
    // slice/str-to-slice/str `Transmute` (`dst = copy/move src as &[u8] (Transmute)`,
    // the inlined `str::as_bytes`), BOTH bare locals — must itself be slot-backed.
    // This is the REASSIGNED-slice-ref shape `let mut r: &[i32] = &[..]; r = &[..];
    // use(r)` (and its `&str` mirror `let mut s = ".."; s = ".."; use(s)`): a
    // reassigned local stays OUT of SSA, so rustc keeps a real fat-pointer statement
    // — `_7 = copy _1; _ = PtrMetadata(move _7)` for a slice; `_1 = move _2
    // (const "..");  _6 = copy _1; len(move _6)` for an out-of-line `&str`; and at
    // `-O`, `_1 = const "hi"; _1 = const "hello"; _5 = copy _1 as &[u8] (Transmute);
    // PtrMetadata(_5)` where the inlined `str::len` transmutes the reassigned local.
    // One side is already slot-backed (`_1` via its `Unsize` construct; `_6` as a
    // by-value call argument; `_5` via the (3b) `Transmute` classifier) while the
    // other is a bare scalar fat-ptr temp. Neither the scalar-borrow path
    // (`_7 = copy _1` -> "borrowed reference Use before scalar borrow binding") nor
    // `lower_memory_slice_assign` (a scalar `Use`/`Transmute` source -> "memory-backed
    // slice assignment Rvalue::{Use,Cast}") can carry a runtime `{ data, len }`
    // across such an edge, so EVERY such mixed edge fails closed today; slot-backing
    // the connected local therefore steals no working case (a both-scalar edge — a
    // CONST-source transmute has no source local and never matches; a scalar-local
    // copy whose source carries a side-table length has NEITHER endpoint
    // memory-backed and is left untouched; a both-slot edge is already handled by
    // `lower_memory_slice_assign`). Run AFTER every other classifier so the complete
    // seed set is visible, and propagate to a fixpoint so a chain (`_2 -> _1 -> _6`)
    // is fully classified. Restricted to slice/str fat-pointer locals joined by
    // projection-free whole-value edges, so ONLY these fat-pointer locals are added.
    loop {
        let mut changed = false;
        for bb in body.basic_blocks.indices() {
            for statement in &body.basic_blocks[bb].statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                if !dst.projection.is_empty() || fmt_internal_locals.contains(&dst.local) {
                    continue;
                }
                let src = match rvalue {
                    Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                    | Rvalue::Cast(
                        mir::CastKind::Transmute,
                        Operand::Copy(src) | Operand::Move(src),
                        _,
                    ) => src,
                    _ => continue,
                };
                if !src.projection.is_empty() || fmt_internal_locals.contains(&src.local) {
                    continue;
                }
                if !is_slice_or_str_fat_ptr_ty(local_rust_ty(ctx, body, dst.local))
                    || !is_slice_or_str_fat_ptr_ty(local_rust_ty(ctx, body, src.local))
                {
                    continue;
                }
                // Fire ONLY when EXACTLY one endpoint is slot-backed — pull the other
                // in. Both-scalar and both-slot edges are already handled as-is.
                let dst_mb = locals.contains(&dst.local);
                let src_mb = locals.contains(&src.local);
                if dst_mb && !src_mb {
                    locals.insert(src.local);
                    changed = true;
                } else if src_mb && !dst_mb {
                    locals.insert(dst.local);
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }

    // Structural drop glue needs the actual address, including for a field
    // dropped after a partial move. Pointer-led places already have storage.
    for bb in body.basic_blocks.indices() {
        let Some(terminator) = &body.basic_blocks[bb].terminator else {
            continue;
        };
        let TerminatorKind::Drop { place, .. } = &terminator.kind else {
            continue;
        };
        if fmt_internal_locals.contains(&place.local)
            || place
                .projection
                .iter()
                .any(|p| matches!(p, ProjectionElem::Deref))
        {
            continue;
        }
        let dropped_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, place));
        let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
        if is_structural_drop_ty(ctx.tcx, dropped_ty)
            && matches!(memory_backed_local_layout(ctx.tcx, base_ty), Ok(Some(_)))
        {
            locals.insert(place.local);
            continue;
        }
        // [TCG-DROP-GLUE-GENERAL] The dropped local of ANY other needs-drop type the
        // general drop-glue arm lowers: that arm hands rustc's own
        // `drop_glue::<T>` the local's slot ADDRESS, so the slot must exist. Keyed on
        // the SAME predicate the arm admits by (`general_drop_glue_type_lowerable`),
        // so admission and allocation cannot drift — a local admitted there without a
        // slot here is a loud refusal, never a synthesized address.
        //
        // This steals no working case: absent a slot, EVERY such drop fails closed
        // today with `TerminatorKind::Drop of type that needs drop`, so no body that
        // compiles now has one of these locals reaching a lowered Drop. (A probe
        // error is treated as "not forced" — the arm re-runs the same probe and turns
        // it into a named refusal there, where the diagnostic can name the type.)
        if matches!(general_drop_glue_type_lowerable(ctx.tcx, base_ty), Ok(true)) {
            locals.insert(place.local);
        }
    }

    // A field moved into a destructor/call temporary also needs a real
    // source image. Whole-value scalarization cannot bind a nested field
    // projection, whereas the existing memory field-copy path can read it.
    for data in body.basic_blocks.iter() {
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                continue;
            };
            if !dst.projection.is_empty()
                || src.projection.is_empty()
                || !src
                    .projection
                    .iter()
                    .all(|p| matches!(p, ProjectionElem::Field(..) | ProjectionElem::Downcast(..)))
                || fmt_internal_locals.contains(&src.local)
            {
                continue;
            }
            let field_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, src));
            let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
            if is_structural_drop_ty(ctx.tcx, field_ty)
                && is_structural_drop_ty(ctx.tcx, base_ty)
                && matches!(memory_backed_local_layout(ctx.tcx, base_ty), Ok(Some(_)))
            {
                locals.insert(src.local);
            }
        }
    }

    // Optimized MIR can move an aggregate into a dedicated drop temporary.
    // Both ends must use the same image, including chains of such moves.
    loop {
        let mut changed = false;
        for data in body.basic_blocks.iter() {
            for statement in &data.statements {
                let StatementKind::Assign(boxed) = &statement.kind else {
                    continue;
                };
                let (dst, rvalue) = &**boxed;
                let Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _) = rvalue else {
                    continue;
                };
                if !dst.projection.is_empty()
                    || !src.projection.is_empty()
                    || fmt_internal_locals.contains(&dst.local)
                    || fmt_internal_locals.contains(&src.local)
                    || locals.contains(&dst.local) == locals.contains(&src.local)
                {
                    continue;
                }
                let dst_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, dst.local));
                let src_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, src.local));
                if dst_ty == src_ty
                    && is_structural_drop_ty(ctx.tcx, dst_ty)
                    && matches!(memory_backed_local_layout(ctx.tcx, dst_ty), Ok(Some(_)))
                {
                    changed |= locals.insert(dst.local);
                    changed |= locals.insert(src.local);
                }
            }
        }
        if !changed {
            break;
        }
    }

    // (ADDR-IDENTITY) A local two of whose places escape as addresses, or one
    // of several locals an escaping reference can address
    // (`address_identity_referents`): a real slot keeps every such address in
    // Rust's relation (equal for one place, a layout offset apart for two).
    // Only a layout the memory model represents; a scalar-leaf referent is
    // celled instead (`compute_scalar_cell_locals`), and anything neither can
    // hold is refused where a second place is materialized (`borrow_home_slot`).
    for &local in &ctx.address_identity_referents {
        if fmt_internal_locals.contains(&local) {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        if matches!(memory_backed_local_layout(ctx.tcx, ty), Ok(Some(_))) {
            locals.insert(local);
        }
    }

    // (4r) A local whose address may be kept beyond this body's view
    // (`ctx.retained_address_locals`: a callee not proven to keep only what it
    // may, a store of the address into memory, an exposed address). A later
    // write through the kept address must reach the local's real storage and
    // every later read must see it, so the local lives in memory for the whole
    // body. A non-primitive local whose layout the memory model represents gets
    // a slot here; a primitive or other cellable scalar gets a cell
    // (`compute_scalar_cell_locals`); anything else is refused by name before
    // lowering (`retained_address_home`).
    for &local in ctx.retained_address_locals.keys() {
        if fmt_internal_locals.contains(&local) {
            continue;
        }
        if retained_address_home(ctx, body, local)? == RetainedAddressHome::Slot {
            locals.insert(local);
        }
    }

    // Never memory-back a `core::fmt` plumbing local (see above) — it is decoded
    // statically and has no lowerable memory layout. Removing it here covers every
    // path that may have added it.
    for l in &fmt_internal_locals {
        locals.remove(l);
    }

    Ok(locals)
}

/// The memory home of a local whose address may be retained
/// (`ctx.retained_address_locals`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RetainedAddressHome {
    /// None is needed. A zero-sized local has no bytes to go stale; a
    /// `core::fmt` plumbing local is decoded statically by the interception;
    /// an intercepted collection's value IS the address of the interception's
    /// own `{ptr,cap,len}` slot, so its state already lives in memory.
    Exempt,
    /// A scalar cell (`compute_scalar_cell_locals`).
    Cell,
    /// A memory slot of its rustc layout (`compute_memory_backed_locals`).
    Slot,
    /// No home this backend can give it: the function is refused.
    Unhomed,
}

/// Where a local whose address may be retained lives: a primitive scalar in a
/// cell, a layout the memory model represents in a slot, any other cellable
/// scalar (a pointer, a scalar newtype, a fieldless enum) in a cell.
fn retained_address_home<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    local: Local,
) -> Result<RetainedAddressHome, String> {
    let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
    if ctx.fmt_dead_locals.contains(&local)
        || is_zero_sized_ty(ctx.tcx, ty)
        || vec_element_ty(ctx.tcx, ty).is_some()
        || btreemap_kv_ty(ctx.tcx, ty).is_some()
        || any_hashmap_kv_ty(ctx.tcx, ty).is_some()
        || is_string_ty(ctx.tcx, ty)
        || is_hashmap_dead_internal_ty(ctx.tcx, ty)
    {
        return Ok(RetainedAddressHome::Exempt);
    }
    if matches!(
        ty.kind(),
        ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
    ) {
        return Ok(RetainedAddressHome::Cell);
    }
    if memory_backed_local_layout(ctx.tcx, ty)?.is_some() {
        return Ok(RetainedAddressHome::Slot);
    }
    if cellable_reference_referent_ty(ctx.tcx, ty) {
        return Ok(RetainedAddressHome::Cell);
    }
    Ok(RetainedAddressHome::Unhomed)
}

/// Refuse, by name, a body with a local whose address may be retained and
/// that neither the memory-backing nor the cell pass gave a memory home: its
/// register copy would go stale after a write through the kept address.
fn retained_address_unhomed_error<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    memory_backed: &HashSet<Local>,
    cells: &HashSet<Local>,
) -> Result<(), String> {
    for (&local, reason) in &ctx.retained_address_locals {
        if memory_backed.contains(&local) || cells.contains(&local) {
            continue;
        }
        if retained_address_home(ctx, body, local)? == RetainedAddressHome::Exempt {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        return Err(format!(
            "[TCG-RETAINED-ADDR] local {local:?} of type `{ty:?}` may have its address kept \
             beyond this function ({reason}), and this backend has no memory home for it: a \
             later write through the kept address would miss its register copy. Failing closed \
             rather than miscompiling. Options: (1) keep the address from escaping (pass a \
             value, or a reference the callee does not store), (2) compile this function with \
             the LLVM backend"
        ));
    }
    Ok(())
}

/// Whether a REFERENT local can be given a real address by the SCALAR CELL
/// mechanism — the predicate the reference-ESCAPING cell pass keys on.
///
/// A cell is one typed `Alloca` plus `Store`/`Load` of the referent's MEMORY
/// LEAF type, so it represents exactly what `memory_scalar_leaf_ty` accepts: a
/// primitive, a `#[repr(transparent)]` scalar newtype, a `NonNull<T>` / `*mut T`
/// / `&T` pointer, a fieldless-enum scalar. The historical narrowing to
/// `Int/Uint/Float/Bool/Char` was chosen to keep `Vec`-as-`Ptr` out (see below)
/// and took "every ADT" with it; that is much narrower than the mechanism, and
/// the cost is a SOUNDNESS refusal rather than a capability one — with no cell,
/// `&mut x` reaches a reference-returning callee as a materialized TEMP whose
/// address the callee hands back, so a later `*r = v` writes a dead temp.
/// `direct_scalar_ref_select_return` refuses that shape by name rather than
/// miscompile it ("promoted mutable / shared aggregate scalar reference return
/// is unsupported"), and celling the referent is the ADDRESS that makes the
/// refusal unnecessary.
///
/// TWO exclusions, each by the INTERCEPTION PREDICATE ITSELF rather than by a
/// typed heuristic (a typed guard is defeatable — `&mut *(p as *mut NonNull<u8>
/// as *mut u8)` walks through one):
///   * the INTERCEPTED collection types — `Vec` / `String` / `BTreeMap` /
///     `HashMap` and the dead `HashMap` internals. Each models as a single `Ptr`
///     whose value IS the address of a synthesized `{ptr,cap,len}` slot produced
///     by the interception, not by a cell; putting a cell in front of it makes
///     the intercept's value undefined at its use ("value not defined before
///     use"). This is the case the original `Int/Uint/…` narrowing existed for.
///   * a UNION, which must flow through the union MEMORY path
///     (`compute_memory_backed_locals` case 4e + `skip_uninit_union_const`) — the
///     same exclusion the raw-pointer-referent cell pass already makes, for the
///     same reason (`MaybeUninit<u32>` types as a scalar but `= const <uninit>`
///     fails closed through a cell).
///
/// Celling is semantically INERT for everything it admits (reads and writes
/// route through the slot), so widening it cannot change a computed result — it
/// only supplies an address that was missing.
fn cellable_reference_referent_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    if matches!(
        ty.kind(),
        ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
    ) {
        return true;
    }
    if matches!(ty.kind(), ty::Adt(adt, _) if adt.is_union()) {
        return false;
    }
    if vec_element_ty(tcx, ty).is_some()
        || btreemap_kv_ty(tcx, ty).is_some()
        || any_hashmap_kv_ty(tcx, ty).is_some()
        || is_string_ty(tcx, ty)
        || is_hashmap_dead_internal_ty(tcx, ty)
    {
        return false;
    }
    memory_scalar_leaf_ty(tcx, ty).is_ok()
}

// Normal-edge cell stores and pointer-sized cell projections are available
// together on Linux AArch64; other targets keep their established EH lowering.
fn cleanup_scalar_homes_enabled(ctx: &MirLoweringCtx<'_>) -> bool {
    ctx.tcx.sess.target.arch.desc() == "aarch64"
        && ctx.tcx.sess.target.os == rustc_target::spec::Os::Linux
}

/// Native lane qualified for call references to droppable numeric scalars and
/// their 16-aligned padded images. Pointer-owner admission has its own rule.
fn droppable_scalar_call_homes_enabled(ctx: &MirLoweringCtx<'_>) -> bool {
    cleanup_scalar_homes_enabled(ctx)
        && ctx.tcx.sess.target.env == rustc_target::spec::Env::Gnu
        && ctx.tcx.data_layout.pointer_size().bytes() == 8
}

/// Cleanup state whose whole runtime value is one checked scalar. A collection
/// header address is not its owned image; wide pointers and aggregate storage
/// retain their dedicated homes. Genuine thin Global boxes hold the heap pointer.
fn cleanup_scalar_home_eligible<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    local: Local,
) -> bool {
    cleanup_scalar_homes_enabled(ctx) && cleanup_scalar_home_shape(ctx, body, local)
}

/// The type half of [`cleanup_scalar_home_eligible`], without its target gate:
/// whether `local`'s whole runtime value is one scalar a frame home can hold.
/// `cleanup_loop_homes` asks it on the targets that home only cleanup-loop state.
fn cleanup_scalar_home_shape<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    local: Local,
) -> bool {
    let ty = ctx.normalize_ty(ctx.monomorphize_ty(local_rust_ty(ctx, body, local)));
    let supported = match ty.kind() {
        ty::Int(_)
        | ty::Uint(_)
        | ty::Float(_)
        | ty::Bool
        | ty::Char
        | ty::Ref(..)
        | ty::RawPtr(..)
        | ty::FnPtr(..) => true,
        ty::Adt(adt, _) if adt.is_struct() => {
            if Some(adt.did()) == ctx.tcx.lang_items().owned_box() {
                box_element_ty(ctx.tcx, ty).is_some()
            } else {
                !is_fmt_internal_ty(ctx.tcx, ty)
                    && cellable_reference_referent_ty(ctx.tcx, ty)
                    && adt_maps_to_single_scalar(ctx.tcx, ty)
            }
        }
        _ => false,
    };
    if !supported {
        return false;
    }
    let Ok(leaf) = memory_scalar_leaf_ty(ctx.tcx, ty) else {
        return false;
    };
    let Some(storage) = scalar_cell_storage_for_target(ctx, &leaf) else {
        return false;
    };
    let Ok(layout) = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
    else {
        return false;
    };
    (matches!(layout.backend_repr, rustc_abi::BackendRepr::Scalar(_))
        && layout.size.bytes() == storage.size
        && layout.align.bytes() == storage.align)
        || padded_scalar_home_extent(ctx, ty, &leaf).is_some()
}

/// Scalar locals whose ADDRESS is captured by a closure: each needs a memory
/// "cell" (an entry-block `Alloca`) so `&local` is a stable runtime address the
/// closure environment can hold and deref. We match a scalar local `L` such that
/// some `r = &L` / `r = &mut L` (a projection-free `Rvalue::Ref` / `RawPtr`) is
/// then stored as an upvar of an `AggregateKind::Closure`. Only scalar leaves are
/// celled (a `&aggregate` capture is out of scope and fails closed elsewhere).
///
/// This is deliberately narrow: a `&local` that does NOT flow into a closure
/// (the existing borrow corpus) is untouched, so no working scalar-reference case
/// is stolen. A celled local routes every read through a typed `Load` and every
/// write through a typed `Store` (see the cell intercepts in `lower_operand_to_value`
/// / `lower_assign` / `lower_scalar_ref`), so a `&mut`-captured upvar's writes
/// through the closure are observed and a `&`-captured upvar reads the live value.
fn compute_scalar_cell_locals<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
) -> Result<HashSet<Local>, String> {
    // First pass: record `ref_local -> referent_local` for every projection-free
    // `ref_local = &referent` / `&mut referent` where `referent` is a scalar leaf.
    // `ref_to_referent` keeps the last referent (closure-capture detection). The
    // `points` map records, for each reference local, the set of scalar locals a
    // MUTABLE `&mut` borrow could make it address — seeded from direct `&mut src`
    // borrows and propagated across reference copies (`r = copy other`) below, so a
    // branch-varying reference assembled through temporaries is detected.
    let mut ref_to_referent: HashMap<Local, Local> = HashMap::new();
    let mut points: HashMap<Local, HashSet<Local>> = HashMap::new();
    let mut borrowed_enum_cells = HashSet::new();
    // `dst = copy/move src` reference-aliasing edges (projection-free), used to
    // propagate points-to sets to a fixpoint.
    let mut copy_edges: Vec<(Local, Local)> = Vec::new();
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            match rvalue {
                Rvalue::Ref(_, _, source) | Rvalue::RawPtr(_, source)
                    if dst.projection.is_empty() && source.projection.is_empty() =>
                {
                    let source_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, source.local));
                    // The referent must be a single scalar leaf (so the cell is one
                    // typed load/store). A `&aggregate` capture is not celled here.
                    if memory_scalar_leaf_ty(ctx.tcx, source_ty).is_ok() {
                        ref_to_referent.insert(dst.local, source.local);
                        // A fieldless Direct-tag enum is exactly one integer
                        // cell. Give every address-taken local stable storage,
                        // including entry arguments borrowed only for equality.
                        // Discriminant reads must observe the same bytes as
                        // references and raw pointers, never an old entry value.
                        if fieldless_enum_tag_scalar_ty(ctx.tcx, source_ty).is_some() {
                            borrowed_enum_cells.insert(source.local);
                        }
                        if matches!(rvalue, Rvalue::Ref(_, mir::BorrowKind::Mut { .. }, _)) {
                            points.entry(dst.local).or_default().insert(source.local);
                        }
                    }
                }
                // A reference copy `dst = copy/move src`: record the alias edge so
                // `src`'s points-to set flows into `dst` at the fixpoint below. (MIR
                // routes `let rp = match c { _ => &mut a, _ => &mut b }` through a
                // shared temporary copied into `rp`, so the branch-varying set only
                // becomes visible after this propagation.)
                Rvalue::Use(Operand::Copy(src) | Operand::Move(src), _)
                    if dst.projection.is_empty() && src.projection.is_empty() =>
                {
                    copy_edges.push((dst.local, src.local));
                }
                _ => {}
            }
        }
    }
    // Propagate points-to sets across reference-copy edges to a fixpoint. Edges
    // whose source carries no `&mut` points-to set contribute nothing (e.g. a plain
    // scalar copy), so this only ever unions addresses originating from a real
    // mutable borrow.
    loop {
        let mut changed = false;
        for (dst, src) in &copy_edges {
            let Some(src_set) = points.get(src).cloned() else {
                continue;
            };
            let entry = points.entry(*dst).or_default();
            for referent in src_set {
                changed |= entry.insert(referent);
            }
        }
        if !changed {
            break;
        }
    }
    // Second pass: a referent is celled iff its reference is captured as a closure
    // upvar.
    let mut cells: HashSet<Local> = borrowed_enum_cells;
    for local in call_references::address_taken_locals(ctx, body) {
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        // A droppable scalar needs its own stable home when a callee can
        // observe its reference: a snapshot changes the owner's address.
        // On the qualified native lane, reuse the checked whole-value
        // cleanup-home shape for integer/float newtypes, so reads, moves and
        // drop glue all use the same cell. Pointer owners keep their existing
        // shape check on every target. Unsupported shapes retain the call-side
        // stable-address refusal.
        if cellable_reference_referent_ty(ctx.tcx, ty)
            && matches!(memory_backed_local_layout(ctx.tcx, ty), Ok(None))
            && (!ty.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized())
                || (cleanup_scalar_home_shape(ctx, body, local)
                    && (droppable_scalar_call_homes_enabled(ctx)
                        || memory_scalar_leaf_ty(ctx.tcx, ty)
                            .is_ok_and(|leaf| is_pointer_like_trust_ir_ty(&leaf)))))
        {
            cells.insert(local);
        }
    }
    // Cleanup-live state survives an unwind edge in its own frame home. The
    // unwinder cannot supply SSA block arguments, even when several throwing
    // predecessors carry different values. Every assignment writes this home;
    // call results are stored only in the existing normal continuation, so a
    // failed replacement leaves the previous owner available to cleanup.
    if ctx.eh_active && !ctx.eh_landing_pad_blocks.is_empty() {
        let successors: Vec<_> = body
            .basic_blocks
            .iter()
            .map(|data| terminator_successors(&data.terminator().kind))
            .collect();
        let live_in = compute_live_in(body, &successors);
        if cleanup_scalar_homes_enabled(ctx) {
            cells.extend(
                ctx.eh_landing_pad_blocks
                    .iter()
                    .flat_map(|pad| live_in[pad.index()].iter().copied())
                    .filter(|local| cleanup_scalar_home_eligible(ctx, body, *local)),
            );
        } else {
            // Preserve the established constant-drop-flag promotion on other targets.
            let candidates: HashSet<_> = ctx
                .eh_landing_pad_blocks
                .iter()
                .flat_map(|pad| live_in[pad.index()].iter().copied())
                .filter(|local| {
                    !is_entry_arg(body, *local)
                        && matches!(
                            ctx.monomorphize_ty(local_rust_ty(ctx, body, *local)).kind(),
                            ty::Bool
                        )
                })
                .collect();
            let mut constant_defs = HashSet::new();
            let mut other_defs = HashSet::new();
            for data in body.basic_blocks.iter() {
                for statement in &data.statements {
                    if let StatementKind::Assign(boxed) = &statement.kind {
                        let (dst, value) = &**boxed;
                        if candidates.contains(&dst.local) {
                            if dst.projection.is_empty()
                                && matches!(value, Rvalue::Use(Operand::Constant(_), _))
                            {
                                constant_defs.insert(dst.local);
                            } else {
                                other_defs.insert(dst.local);
                            }
                        }
                    }
                }
                if let TerminatorKind::Call { destination, .. } = &data.terminator().kind {
                    other_defs.insert(destination.local);
                }
            }
            cells.extend(constant_defs.difference(&other_defs).copied());
        }
    }
    // A scalar-sized wrapper's closure field needs a stable environment address.
    // The same layout witness is checked again when the borrow is lowered.
    for data in body.basic_blocks.iter() {
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            // Inlining a mutable closure can replace the environment borrow
            // with direct writes to the captured scalar through the wrapper.
            if scalar_wrapper_closure_projection(ctx, body, &boxed.0)?.is_some() {
                cells.insert(boxed.0.local);
            }
            if let Rvalue::Ref(_, _, source) = &boxed.1 {
                if scalar_wrapper_closure_projection(ctx, body, source)?.is_some() {
                    cells.insert(source.local);
                }
            }
        }
    }
    // A raw pointer taken to a primitive scalar local (`&raw const/mut x`,
    // `addr_of!(x)`, or `&x as *const T`) needs that scalar to have a real address:
    // a raw pointer carries no aliasing guarantee, so reads, writes, and pointer
    // arithmetic through it must hit the scalar's actual storage. Celling the
    // referent routes every access through a stable slot (semantically inert), so
    // the raw pointer and any direct access observe each other. Two MIR shapes:
    //   * `_p = &raw const x`      -> `RawPtr(_, {x, []})`       (addr_of! / &raw)
    //   * `_p = &raw const (*_r)`  -> `RawPtr(_, {_r, [Deref]})` (`&x as *const`,
    //        where `_r = &x`; the underlying referent is `ref_to_referent[_r]`).
    // Restricted to a genuine primitive scalar or thin raw-pointer leaf,
    // matching the conservative narrowing the loop-call and tuple-arg passes use —
    // this excludes `Vec`-as-`Ptr` and every ADT, whose scalar models are not a
    // plain cell. This is the only thing that makes a `RawPtr` of a scalar (handled
    // in `lower_assign`) sound; without a cell the snapshot model has no address.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (_dst, rvalue) = &**boxed;
            let source = match rvalue {
                Rvalue::RawPtr(_, source) => source,
                Rvalue::Ref(_, _, source)
                    if !source.projection.is_empty()
                        && source
                            .projection
                            .iter()
                            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
                        && is_zero_sized_ty(
                            ctx.tcx,
                            ctx.monomorphize_ty(place_rust_ty(ctx, body, source)),
                        ) =>
                {
                    source
                }
                _ => continue,
            };
            let referent = if source.projection.is_empty() {
                source.local
            } else if matches!(source.projection.as_ref(), [ProjectionElem::Deref]) {
                match ref_to_referent.get(&source.local).copied() {
                    Some(referent) => referent,
                    None => continue,
                }
            } else if source
                .projection
                .iter()
                .all(|elem| matches!(elem, ProjectionElem::Field(..)))
                && scalar_zst_address::field_owner_has_scalar_storage(ctx, body, source.local)
            {
                // Give a scalar wrapper chain stable storage. The raw-borrow
                // lowering checks every field offset, extent and alignment before
                // exposing the address; an unsupported projection still refuses.
                source.local
            } else {
                continue;
            };
            let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
            // Cell a genuine NON-POINTER scalar referent: a primitive
            // (Int/Uint/Float/Bool/Char) OR a TRANSPARENT scalar newtype over one
            // (`UnsafeCell<u32>` / `Wrapping<u32>` — `rust_ty_to_trust_ir_ty` maps it
            // to the inner scalar, so `UnsafeCell::get` = `&raw const cell` gets a real
            // address). Excludes pointer-like ADTs (`Vec`-as-`Ptr`, whose cell model
            // differs) and non-scalar aggregates. EXCLUDES a UNION (`MaybeUninit<u32>`
            // types as a scalar via the ZST-field-skip ABI, but it MUST flow through
            // the union memory-backed path — `compute_memory_backed_locals` case 4e +
            // `skip_uninit_union_const` — not the scalar cell, or `= const <uninit>`
            // fails closed).
            let is_union_ty = matches!(referent_ty.kind(), ty::Adt(adt, _) if adt.is_union());
            // A POINTER-LIKE SINGLE-SCALAR ADT referent — `struct Show<'a>(&'a T)`,
            // `struct Cur(*const u8)`, a `&`-newtype. `rust_ty_to_trust_ir_ty` maps it to
            // ONE POINTER scalar, so the `!is_pointer_like` clause below excludes it from
            // the cell — and `memory_backed_local_layout` returns `None` for every type
            // that mapping accepts, so the memory path (rule 4h) does not fire either.
            // NEITHER address mechanism fires, and the local has no address at all: both
            // `&raw const s` and `&raw const (*r)` of `r = &s` fail closed
            // ("Rvalue::RawPtr (unsupported &raw shape: ...)"). Measured on the frozen
            // round-four build: refusal, never a wrong address — while the SAME struct
            // with a non-pointer leaf (`struct N(u64)`) compiles and runs correctly
            // through this very pass, which is the whole of the difference.
            //
            // The cell is EXACT here for the reason `local_is_single_scalar_storage`
            // already names (measured 2026-09-14 for the pointer newtype): field 0's
            // storage IS the whole local's storage, so the cell holds the local's own
            // bytes at its own address — precisely what `&raw` must hand out, and what
            // `<Show as Display>::fmt` reads back through the `Argument` it is stored in.
            // Celling stays semantically inert: the construct
            // (`lower_adt_aggregate`'s single-scalar arm -> `finish_assign_target`) and
            // every whole-local assignment (`lower_assign`'s celled-place intercept)
            // store into the cell, and reads load from it.
            //
            // EXCLUDED — each keeps its existing fail-closed behaviour, none is widened
            // here: a SLOT-MODELED collection (`Vec`/`String`/`BTreeMap`/`HashMap`, whose
            // one `Ptr` is the address of a `{ptr,cap,len}` FRAME SLOT, not the value, so
            // a cell would hand out the wrong object) — excluded inside
            // `local_is_single_scalar_storage`; a `core::fmt` plumbing type (decoded at
            // compile time, its locals never materialized); a NEEDS-DROP referent
            // (`Box<T>`: `lower_drop_terminator` resolves the pointer through the local's
            // own binding, which the cell would move out from under it); a bare `&T`
            // local (the `&&T` chain keeps its dedicated reference-chain pass).
            // Genuine thin raw pointers use the separate predicate below.
            // A transparent wide-slice NEWTYPE (`NonNull<[T]>`) maps to one `Ptr`
            // too, but since 2026-09-22 `memory_backed_local_layout` answers its
            // two-lane slot, so rule (4h) DOES fire for it — a cell as well would
            // give the local two homes (measured: the cell took the one-lane
            // copy, the slot took the raw store, the boundary read the slot's
            // never-written length lane). The slot is its only home.
            let is_pointer_scalar_storage_referent = !is_union_ty
                && !is_fmt_internal_ty(ctx.tcx, referent_ty)
                && !referent_ty.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized())
                && wide_slice_carrier_layout(ctx.tcx, referent_ty).is_none()
                && local_is_single_scalar_storage(ctx, referent)
                && rust_ty_to_trust_ir_ty(ctx.tcx, referent_ty)
                    .map(|t| is_pointer_like_trust_ir_ty(&t))
                    .unwrap_or(false);
            let is_scalar_referent = !is_union_ty
                && (matches!(
                    referent_ty.kind(),
                    ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
                ) || rust_ty_to_trust_ir_ty(ctx.tcx, referent_ty)
                    .map(|t| t.bit_width().is_some() && !is_pointer_like_trust_ir_ty(&t))
                    .unwrap_or(false));
            // A raw address of a thin reference local points at the POINTER
            // value, not its pointee. Give that value its own cell, just like
            // a raw pointer local. Unaddressable reference initializers still
            // fail closed in lower_scalar_memory_store_value.
            //
            // ⚑ THE `ty::Ref` HALF WAS GATED TO aarch64-linux (`ee201313a`,
            // 2026-09-29) WITH NO STATED REASON, and on x86-64 that gate cost four
            // `library/core` roots at `-Copt-level=3`: `&raw const (*_r)` where
            // `_r: &&Ipv4Addr` / `&&Ipv6Addr` / `&u8` / `&&u16` — the `format_args!`
            // `&&value` chain — refused with `unsupported &raw shape: … [Deref] …
            // base bound=false cell=false memory_backed=false entry_arg=false`,
            // i.e. the referent had NO address mechanism at all because it was not
            // celled here. Nothing in the gate is arch-specific: the cell holds a
            // pointer-sized value at its own address, `layout_size_of == 8` and the
            // 8-byte pointer check below are already explicit, and celling is
            // semantically inert (construct and every whole-local assignment store
            // into the cell, reads load from it). Extended to x86-64 Linux, with
            // `-Ztrust-ir-cg-args=no-x86-ref-referent-cell` to restore the refusal
            // so the two arms are measurable from ONE dylib.
            // The TARGET half is `uses_real_address_reference_model`, shared with
            // `lower_promoted_scalar_ref_return_call` so the two cannot drift apart
            // again; the per-TYPE half stays here.
            let ref_referent_cell_target = matches!(referent_ty.kind(), ty::Ref(..))
                && uses_real_address_reference_model(ctx.tcx);
            let is_raw_pointer_referent = (matches!(referent_ty.kind(), ty::RawPtr(..))
                || ref_referent_cell_target)
                && is_thin_pointer_ref_ty(ctx.tcx, referent_ty)
                && ctx.tcx.data_layout.pointer_size().bytes() == 8
                && layout_size_of(ctx, referent_ty)? == 8
                && memory_scalar_leaf_ty(ctx.tcx, referent_ty).is_ok();
            if is_scalar_referent || is_pointer_scalar_storage_referent || is_raw_pointer_referent {
                cells.insert(referent);
            }
        }
    }
    // A REFERENT WHOSE REFERENCE IS UNSIZED TO A TRAIT OBJECT. Same requirement as
    // the `&raw` pass above and the same remedy — the referent needs a real address —
    // reached by a different MIR shape, so the loop above never considers it:
    //
    //     _r = &x                                    (Rvalue::Ref, no `&raw`)
    //     _d = move _r as &dyn Debug (Unsize)        <- the trigger
    //
    // `materialize_trait_object_data_ptr` needs `x`'s canonical address for the fat
    // pointer's data lane. With `x` scalarized it has none, and that function refuses
    // with `[TCG-DYN-REF-IDENTITY] … from a scalarized borrow`, correctly: a fresh
    // copy would change pointer identity and lose writes made through interior
    // mutability. Celling `x` gives it the address, which is exactly what the refusal
    // asks for ("Pass an existing thin reference whose referent has real storage").
    //
    // MEASURED on `library/core` at `-Copt-level=3`: TEN failed roots, all this
    // message, on four referent types — `char`, `*const RawWakerVTable`,
    // `&*const c_void`, and a `CodeUnit` newtype. Every one is a type the predicates
    // below ALREADY admit; the pass simply never saw them, because a `&dyn Debug`
    // argument is built with `&`, never `&raw`.
    //
    // ⚑ NO NEW TYPE IS ADMITTED. The three predicates are reused verbatim from the
    // `&raw` pass, so this adds a REASON to cell an already-admissible referent and
    // nothing else — a union, a `Vec`-as-`Ptr`, a needs-drop `Box`, a `core::fmt`
    // plumbing type and every non-scalar aggregate keep failing closed exactly as
    // before. Celling stays semantically inert for the same reason recorded there:
    // the construct and every whole-local assignment store into the cell, and reads
    // load from it.
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (_dst, rvalue) = &**boxed;
            let Rvalue::Cast(
                mir::CastKind::PointerCoercion(PointerCoercion::Unsize, _),
                operand,
                cast_dst_ty,
            ) = rvalue
            else {
                continue;
            };
            // Only a TRAIT-OBJECT destination reaches
            // `materialize_trait_object_data_ptr`; a `[T; N] -> [T]` unsize takes a
            // different path and is not what this rule is for.
            if !is_trait_object_reference_ty(ctx.monomorphize_ty(*cast_dst_ty)) {
                continue;
            }
            let (Operand::Copy(source) | Operand::Move(source)) = operand else {
                continue;
            };
            if !source.projection.is_empty() {
                continue;
            }
            // The unsized operand is a REFERENCE local; the address wanted is its
            // referent's, which `ref_to_referent` resolves for the `_r = &x` shape.
            let Some(referent) = ref_to_referent.get(&source.local).copied() else {
                continue;
            };
            let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
            let is_union_ty = matches!(referent_ty.kind(), ty::Adt(adt, _) if adt.is_union());
            let is_pointer_scalar_storage_referent = !is_union_ty
                && !is_fmt_internal_ty(ctx.tcx, referent_ty)
                && !referent_ty.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized())
                && wide_slice_carrier_layout(ctx.tcx, referent_ty).is_none()
                && local_is_single_scalar_storage(ctx, referent)
                && rust_ty_to_trust_ir_ty(ctx.tcx, referent_ty)
                    .map(|t| is_pointer_like_trust_ir_ty(&t))
                    .unwrap_or(false);
            let is_scalar_referent = !is_union_ty
                && (matches!(
                    referent_ty.kind(),
                    ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
                ) || rust_ty_to_trust_ir_ty(ctx.tcx, referent_ty)
                    .map(|t| t.bit_width().is_some() && !is_pointer_like_trust_ir_ty(&t))
                    .unwrap_or(false));
            let is_thin_pointer_referent =
                matches!(referent_ty.kind(), ty::RawPtr(..) | ty::Ref(..))
                    && is_thin_pointer_ref_ty(ctx.tcx, referent_ty)
                    && ctx.tcx.data_layout.pointer_size().bytes() == 8
                    && layout_size_of(ctx, referent_ty)? == 8
                    && memory_scalar_leaf_ty(ctx.tcx, referent_ty).is_ok();
            if is_scalar_referent || is_pointer_scalar_storage_referent || is_thin_pointer_referent
            {
                cells.insert(referent);
            }
        }
    }
    // An INTERIOR-MUTABLE SCALAR CELL (`Cell<iN>` / `UnsafeCell<iN>`) whose `&c` / `&mut c`
    // borrow is passed as a CALL ARGUMENT — the `c.set(v)` = `Cell::set(&c, v)`,
    // `c.get()` = `Cell::get(&c)`, `c.replace(v)` = `Cell::replace(&c, v)` shape at
    // rustc `-O0`, where the libcore accessor bodies are REAL CALLS (at `-O3` they inline
    // to `&raw` ops that the RawPtr-referent pass above already cells). A `Cell` mutates
    // through a SHARED reference, so the scalarized snapshot model is UNSOUND for it:
    // `Cell::set(&c, v)` writes through a `&self` shared borrow, and the snapshot — which
    // only reloads a `&mut` writeback — would DROP that write, so a later `c.get()` reads
    // stale (the interior-mutability stale-read class). Celling the cell local gives it a
    // stable slot: `&c` binds to the slot pointer (`lower_scalar_ref`'s celled arm), the
    // accessor call passes that pointer directly (`lower_aggregate_reference_call_arg`'s
    // `scalar_values` arm), and every get/set/replace routes through the slot with NO
    // caching across the call. Celling is inert for a non-cell scalar; a non-scalar /
    // pointer-like cell is excluded by `is_interior_mutable_scalar_cell` and stays fail-
    // closed. Fires for ANY call (not just in-loop) since a single `set`-then-`get`
    // outside a loop already exhibits the stale-read without a cell.
    for bb in body.basic_blocks.indices() {
        let Some(terminator) = &body.basic_blocks[bb].terminator else {
            continue;
        };
        let TerminatorKind::Call { args, .. } = &terminator.kind else {
            continue;
        };
        for arg in args.iter() {
            let (Operand::Copy(p) | Operand::Move(p)) = &arg.node else {
                continue;
            };
            if !p.projection.is_empty() {
                continue;
            }
            let Some(referent) = ref_to_referent.get(&p.local).copied() else {
                continue;
            };
            let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
            if is_interior_mutable_scalar_cell(ctx.tcx, referent_ty) {
                cells.insert(referent);
            }
        }
    }
    // A BRANCH-VARYING mutable reference: one `&mut` reference local that can address
    // TWO OR MORE distinct scalar locals (`rp = match c { _ => &mut a, _ => &mut b }`).
    // Through control flow `rp` holds the address of *either* `a` or `b`, so a
    // `*rp = v` store must hit the selected scalar's real storage and a later direct
    // read of `a`/`b` must observe it. The scalarized snapshot model (which records
    // only the borrowed *value*) drops the write to the underlying local — a silent
    // miscompile. Celling every such referent gives it a stable address: `&mut a`
    // binds `rp` to the cell pointer, the join becomes an ordinary pointer phi, and
    // `*rp = v` / direct reads route through the cell. (A single-target `&mut a` keeps
    // the snapshot model, so the working scalar-reference corpus is untouched.)
    for referents in points.values() {
        if referents.len() >= 2 {
            cells.extend(referents.iter().copied());
        }
    }
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (_dst, rvalue) = &**boxed;
            let Rvalue::Aggregate(kind, operands) = rvalue else {
                continue;
            };
            // A scalar reference stored INTO an aggregate as a VALUE needs the scalar to
            // have a real address (the aggregate field / enum niche holds the pointer,
            // not the snapshot value). This covers closure captures (`AggregateKind::
            // Closure`) and a reference stored into a struct / enum (`AggregateKind::
            // Adt`) — e.g. `Option::<&i32>::Some(&r)`, whose niche stores `&r`. Celling
            // the referent gives `&r` a stable slot address.
            if !matches!(
                &**kind,
                mir::AggregateKind::Closure(..)
                    | mir::AggregateKind::Adt(..)
                    // A reference stored into a TUPLE as a value — the
                    // `rfind::check` closure builds the `(&&item,)` predicate-arg
                    // tuple from `&param`: the tuple field holds the POINTER, so
                    // the referent needs a real (celled) address exactly like the
                    // Closure/Adt cases.
                    | mir::AggregateKind::Tuple
            ) {
                continue;
            }
            for operand in operands.iter() {
                let (Operand::Copy(p) | Operand::Move(p)) = operand else {
                    continue;
                };
                if !p.projection.is_empty() {
                    continue;
                }
                if let Some(referent) = ref_to_referent.get(&p.local).copied() {
                    cells.insert(referent);
                }
            }
        }
    }
    // MISCOMPILE #80 (loop-carried `&mut`-to-call writeback). A scalar whose MUTABLE
    // `&mut` borrow is passed as a CALL argument inside a LOOP needs a stable address.
    // The non-loop case is handled correctly by `mutable_reload` (materialize a temp
    // slot, call, reload the scalar), but across a loop back-edge the reloaded value is
    // not threaded as a loop-carried SSA phi, so the writeback from iteration N is lost
    // on iteration N+1 — a silent miscompile (`while .. { f(&mut acc); }` kept `acc`'s
    // entry value at O0 and O3). Celling the referent gives it a stable slot the callee
    // writes through and every iteration reads, turning the writeback into an ordinary
    // memory store/load that the loop observes.
    //
    // NARROWED to calls INSIDE A LOOP. Celling is meant to be semantically inert, but
    // applying it to EVERY `f(&mut s)` regressed std-library code reached through the
    // same compile (a `Vec` program crashed — `RawVec`/allocator internals have scalar
    // `&mut`-to-call shapes the cell mechanism does not yet model fully). The bug only
    // manifests when the writeback must survive a loop back-edge, so we cell ONLY when
    // the call's block lies on a cycle. (We key off the call SITE rather than the
    // scalar's live-in set: a scalar mutated solely THROUGH the `&mut` has no explicit
    // in-loop `s = ..` statement, so liveness-based loop-carried detection misses it.)
    let loop_blocks = compute_loop_blocks(body);
    if !loop_blocks.is_empty() {
        for bb in body.basic_blocks.indices() {
            if !loop_blocks.contains(&bb) {
                continue;
            }
            let Some(terminator) = &body.basic_blocks[bb].terminator else {
                continue;
            };
            let TerminatorKind::Call { args, .. } = &terminator.kind else {
                continue;
            };
            for arg in args.iter() {
                let (Operand::Copy(p) | Operand::Move(p)) = &arg.node else {
                    continue;
                };
                if !p.projection.is_empty() {
                    continue;
                }
                if !points.contains_key(&p.local) {
                    continue;
                }
                if let Some(referent) = ref_to_referent.get(&p.local).copied() {
                    // Cell ONLY a genuine primitive scalar. `memory_scalar_leaf_ty`
                    // (used to seed `points`) also accepts heap types the bridge
                    // scalarizes to a single `Ptr` — notably `Vec<T>`, which models as
                    // one pointer. `v.push(i)` is `Vec::push(&mut v, i)`, a scalar-leaf
                    // `&mut`-to-call inside the build loop; celling the `Vec` local
                    // there breaks the Vec interception (its value is produced by the
                    // intercept, not a cell slot — emission then fails "value not
                    // defined before use"). Restricting to Int/Uint/Float/Bool/Char
                    // keeps the #80 numeric-accumulator case and excludes every ADT.
                    let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
                    if matches!(
                        referent_ty.kind(),
                        ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
                    ) {
                        cells.insert(referent);
                    }
                }
            }
        }
    }
    // A scalar reference (`&x` / `&mut x`) stored into a TUPLE that is then passed
    // as a CALL ARGUMENT needs the scalar to have a real address: the tuple element
    // holds the pointer VALUE, and the callee derefs it through a real address (the
    // snapshot-only borrowed-scalar model has no address to pass). This is the
    // `Option::filter` / `Iterator::find` `|&x| ..` shape: `filter`'s body builds
    // `_t = (&x,)` and calls `predicate(_t)` — `<P as FnOnce<(&T,)>>::call_once`,
    // whose untupled `&x` arg the closure body reads through `*_2`. Without a cell,
    // `_t = (copy &x,)` fails closed ("borrowed scalar reference used without
    // deref"). Restricted to: (1) a TUPLE aggregate (closure-call arg tuples are
    // always tuples), (2) whose ref operand's referent is a primitive scalar (the
    // same Int/Uint/Float/Bool/Char narrowing the #80 loop-call pass uses, which
    // excludes Vec-as-Ptr and every ADT), (3) where the tuple local is consumed as
    // a Call argument. Celling is semantically inert (a celled scalar's reads/writes
    // route through the cell), so this never changes a result — it only gives `&x` a
    // real address where the snapshot model could not.
    let mut tuple_ref_referents: HashMap<Local, Vec<Local>> = HashMap::new();
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if !dst.projection.is_empty() {
                continue;
            }
            let Rvalue::Aggregate(kind, operands) = rvalue else {
                continue;
            };
            if !matches!(&**kind, mir::AggregateKind::Tuple) {
                continue;
            }
            for operand in operands.iter() {
                let (Operand::Copy(p) | Operand::Move(p)) = operand else {
                    continue;
                };
                if !p.projection.is_empty() {
                    continue;
                }
                if let Some(referent) = ref_to_referent.get(&p.local).copied() {
                    let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
                    if matches!(
                        referent_ty.kind(),
                        ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
                    ) {
                        tuple_ref_referents
                            .entry(dst.local)
                            .or_default()
                            .push(referent);
                    }
                }
            }
        }
    }
    if !tuple_ref_referents.is_empty() {
        for bb in body.basic_blocks.indices() {
            let Some(terminator) = &body.basic_blocks[bb].terminator else {
                continue;
            };
            let TerminatorKind::Call { args, .. } = &terminator.kind else {
                continue;
            };
            for arg in args.iter() {
                let (Operand::Copy(p) | Operand::Move(p)) = &arg.node else {
                    continue;
                };
                if !p.projection.is_empty() {
                    continue;
                }
                if let Some(referents) = tuple_ref_referents.get(&p.local) {
                    cells.extend(referents.iter().copied());
                }
            }
        }
    }
    // A scalar reference `&x`/`&mut x` passed DIRECTLY as a CALL ARGUMENT to a callee
    // whose RETURN TYPE carries a reference (the callee hands the borrow back out,
    // wrapped in a struct/Option/tuple/Box or as a captured closure upvar). The
    // returned reference must address `x`'s real storage so a later `*r = v` store or
    // read lands; the snapshot-only borrowed-scalar model has no address to thread
    // through the wrapped return and silently drops the write (verified miscompile:
    // `make(&mut x) -> W { p: &mut x }; *w.p = ..` left x unchanged). Celling `x`
    // gives `&mut x` a stable cell-pointer address — which also makes it no longer a
    // borrowed-scalar, so the [TCG-REFRET-WRAP] fail-closed guard naturally stops
    // firing and the call lowers correctly. Narrowed (mirrors the #80 / tuple-call
    // passes): primitive-scalar referent only (excludes Vec-as-Ptr and ADTs), and
    // ONLY when the callee return actually carries a reference. Celling is
    // semantically inert (reads/writes route through the cell), so it cannot change a
    // result — it only supplies the missing address.
    for bb in body.basic_blocks.indices() {
        let Some(terminator) = &body.basic_blocks[bb].terminator else {
            continue;
        };
        let TerminatorKind::Call { func, args, .. } = &terminator.kind else {
            continue;
        };
        // The callee return type must carry a reference for the borrow to escape.
        let Operand::Constant(c) = func else { continue };
        let callee_ty = ctx.monomorphize_ty(c.const_.ty());
        let Some(item) = fn_items::view(callee_ty.kind()) else {
            continue;
        };
        let fn_sig = ctx
            .tcx
            .fn_sig(item.def_id())
            .instantiate(
                ctx.tcx,
                item.require_unbound_args("scalar-cell callee output")?,
            )
            .skip_binder();
        let ret = ctx.monomorphize_ty(fn_sig.output());
        if !ty_carries_reference(ctx.tcx, ret, 0) {
            continue;
        }
        for arg in args.iter() {
            let (Operand::Copy(p) | Operand::Move(p)) = &arg.node else {
                continue;
            };
            if !p.projection.is_empty() {
                continue;
            }
            if let Some(referent) = ref_to_referent.get(&p.local).copied() {
                let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
                // WIDENED from the `Int/Uint/Float/Bool/Char` narrowing to every
                // referent the cell mechanism can actually represent — see
                // `cellable_reference_referent_ty`, which keeps the intercepted
                // collections and unions out by their own predicates. This arm is
                // the one whose narrowness was a SOUNDNESS refusal rather than a
                // capability one (`slice::IterMut::next` and friends in
                // `library/core`); the other three cell passes keep the primitive
                // narrowing, which is deliberate for them.
                if cellable_reference_referent_ty(ctx.tcx, referent_ty) {
                    cells.insert(referent);
                }
            }
        }
    }
    // A scalar reference `&mut x` STORED THROUGH (`*r = v`) INSIDE A LOOP with NO
    // intervening Call. The borrowed-scalar snapshot only threads a write back
    // across a loop when a Call terminator flags `x` loop-carried (the #80 pass)
    // or the borrow escapes via a call (the passes above) — but a closure with a
    // `&mut` PARAMETER, INLINED at O3, leaves a bare `*r = ..` store in the loop
    // body with NO Call, so the loop-carried-`&mut` detection misses it and the
    // write is silently DROPPED across the back-edge (verified miscompile:
    // `let mut add = |s:&mut i64, v| { *s += v }; while i < 10 { add(&mut acc, i); }`
    // left `acc == 0` at O3 vs 45). Cell `x` so `&mut x` is a real address and the
    // store lands. Restricted to a store-through INSIDE a loop (`compute_loop_blocks`)
    // and a primitive-scalar referent (mirrors #80); celling is semantically inert
    // (reads/writes route through the cell), so it cannot change a correct result.
    let loop_blocks = compute_loop_blocks(body);
    for bb in body.basic_blocks.indices() {
        if !loop_blocks.contains(&bb) {
            continue;
        }
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, _rvalue) = &**boxed;
            // A store THROUGH a reference: the destination place derefs `dst.local`
            // (`*r` / `*r.field`). For a scalar-leaf referent this is `*r = v`.
            if !matches!(dst.projection.first(), Some(ProjectionElem::Deref)) {
                continue;
            }
            if let Some(referent) = ref_to_referent.get(&dst.local).copied() {
                let referent_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, referent));
                if matches!(
                    referent_ty.kind(),
                    ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
                ) {
                    cells.insert(referent);
                }
            }
        }
    }
    // A REFERENCE-OF-A-REFERENCE (`rr = &r` where `r` is itself a reference): `r`'s
    // OWN address must be materialized so `&r` has a real pointer value. `r` is
    // modeled as a borrowed-scalar SNAPSHOT with no `scalar_value`, so `&r` otherwise
    // emits a synthetic never-defined `ValueId(r.index())` and the whole function
    // fails closed at `[TCG-SSA-071]`. Cell the WHOLE reference chain down to the
    // scalar referents: then `r = &x` stores a real `&x` (= cell(x).ptr) into
    // cell(r) (see `lower_scalar_ref`'s celled arm, dest-celled branch), `&r` = the
    // Copy of cell(r).ptr, `*rr` loads cell(r) = &x, `**rr` loads cell(x) = x.
    //
    // The chain is every local `r` can take its address from: each `r = &x` (in any
    // block), and through `r = copy q` every such source of `q`, transitively. A
    // reborrow `r = &(*q)` / `&raw (*q)` is not a link: storing it into a cell is
    // not lowered, so a chain through one stays uncelled.
    //
    // Each branch of the walk must end at an ADDRESSABLE terminal: a NON-POINTER
    // scalar referent (a primitive, or a non-union ADT that maps to one non-pointer
    // scalar — `struct Probe(u8)`, the RawPtr pass's own scalar-referent predicate,
    // whose construct and assignments store into the cell), a scalar field with an
    // existing runtime address through an entry reference (a validated projected
    // borrow), or a thin pointer PARAMETER. Pointer parameters already hold real
    // addresses: a scalar-leaf one is celled with the chain (its value, while its
    // pointee stays in caller storage), any other ends its branch uncelled. A
    // reference with no assignment at all (a call result) already holds a real
    // address and ends its branch of the walk.
    //
    // A partial cell with no addressable terminal would leave `r = &referent`
    // unable to store a consistent pointer into r's cell = a defined-but-
    // uninitialized load = miscompile — so a chain that reaches a non-cellable
    // referent (a fat `&[T]`/`&str`, a `Vec`/`Box`, or an aggregate) is left
    // ENTIRELY uncelled and stays fail-closed, and so is a chain that reaches no
    // addressable terminal at all. Additive: `&r` fails closed today for every such
    // chain, so celling the complete chains steals no working case.
    let mut projected_borrow_defs = HashSet::new();
    let mut other_reference_defs = HashSet::new();
    for data in body.basic_blocks.iter() {
        for statement in &data.statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, value) = &**boxed;
            let is_projected_borrow = if dst.projection.is_empty() && !is_entry_arg(body, dst.local)
            {
                if let Rvalue::Ref(_, _, source) = value {
                    entry_aggregate_scalar_borrow(ctx, body, source)?.is_some()
                } else {
                    false
                }
            } else {
                false
            };
            if is_projected_borrow {
                projected_borrow_defs.insert(dst.local);
            } else {
                other_reference_defs.insert(dst.local);
            }
        }
        if let TerminatorKind::Call { destination, .. } = &data.terminator().kind {
            other_reference_defs.insert(destination.local);
        }
    }
    let projected_borrows: HashSet<_> = projected_borrow_defs
        .difference(&other_reference_defs)
        .copied()
        .collect();
    let mut ref_chain_edges: HashMap<Local, Vec<Local>> = HashMap::new();
    let mut ref_of_ref_sources: Vec<Local> = Vec::new();
    for bb in body.basic_blocks.indices() {
        for statement in &body.basic_blocks[bb].statements {
            let StatementKind::Assign(boxed) = &statement.kind else {
                continue;
            };
            let (dst, rvalue) = &**boxed;
            if !dst.projection.is_empty() {
                continue;
            }
            let edge = match rvalue {
                Rvalue::Ref(_, _, source) | Rvalue::RawPtr(_, source)
                    if source.projection.is_empty() =>
                {
                    Some(source.local)
                }
                Rvalue::Use(Operand::Copy(q) | Operand::Move(q), _) if q.projection.is_empty() => {
                    Some(q.local)
                }
                _ => None,
            };
            if let Some(from) = edge {
                ref_chain_edges.entry(dst.local).or_default().push(from);
            }
            // `dst = &source` of a reference `source` takes the address OF a
            // reference. Recorded borrows, validated projected borrows and every
            // thin pointer start a chain — a directly borrowed pointer parameter
            // too: its own address must survive identity observations and writes
            // through a mutable trait object.
            if let Rvalue::Ref(_, _, source) = rvalue {
                if source.projection.is_empty()
                    && (ref_to_referent.contains_key(&source.local)
                        || projected_borrows.contains(&source.local)
                        || is_thin_pointer_ref_ty(
                            ctx.tcx,
                            ctx.monomorphize_ty(local_rust_ty(ctx, body, source.local)),
                        ))
                {
                    ref_of_ref_sources.push(source.local);
                }
            }
        }
    }
    for start in ref_of_ref_sources {
        // Every link must be thin, and every branch must reach a primitive or
        // scalar-newtype referent, a validated projected borrow, or an
        // address-bearing parameter. Cycle/depth-guarded.
        let mut chain: Vec<Local> = Vec::new();
        let mut work = vec![start];
        let mut complete = true;
        let mut reaches_referent = false;
        while let Some(cur) = work.pop() {
            if chain.contains(&cur) {
                continue;
            }
            if chain.len() > 64 {
                complete = false;
                break;
            }
            let cur_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, cur));
            if is_thin_pointer_ref_ty(ctx.tcx, cur_ty) {
                // An addressable TERMINAL: a validated projected borrow (a scalar
                // field's real address through an entry reference) or a
                // scalar-leaf pointer PARAMETER. Celled with the chain (its value;
                // the pointee stays where it is), and its branch ends here.
                if projected_borrows.contains(&cur)
                    || (is_entry_arg(body, cur) && memory_scalar_leaf_ty(ctx.tcx, cur_ty).is_ok())
                {
                    chain.push(cur);
                    reaches_referent = true;
                    continue;
                }
                // Any other parameter already holds a real address and ends its
                // branch uncelled.
                if is_entry_arg(body, cur) {
                    continue;
                }
                chain.push(cur);
                if let Some(from) = ref_chain_edges.get(&cur) {
                    work.extend(from.iter().copied());
                }
            } else if matches!(
                cur_ty.kind(),
                ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
            ) || (!matches!(cur_ty.kind(), ty::Adt(adt, _) if adt.is_union())
                && matches!(cur_ty.kind(), ty::Adt(..))
                && cellable_reference_referent_ty(ctx.tcx, cur_ty)
                && rust_ty_to_trust_ir_ty(ctx.tcx, cur_ty)
                    .map(|t| t.bit_width().is_some() && !is_pointer_like_trust_ir_ty(&t))
                    .unwrap_or(false))
            {
                chain.push(cur);
                reaches_referent = true;
            } else {
                complete = false;
                break;
            }
        }
        if complete && reaches_referent {
            cells.extend(chain);
        }
    }
    // (ADDR-IDENTITY) A scalar referent whose address identity escapes in two
    // places at once (`address_identity_referents`) — `&y.0` and `&y` of a
    // scalar newtype, or `y` as one arm of an escaping `if c { &x } else { &y }`
    // — needs one real address. Celled when it is a NON-POINTER scalar leaf (a
    // primitive or a scalar newtype over one, the RawPtr pass's own predicate)
    // that no memory slot represents (`compute_memory_backed_locals` rule
    // ADDR-IDENTITY takes those). A pointer-like referent is left alone: a cell
    // for it without a cell for ITS referent would store an address that does
    // not exist (see the reference-chain pass above). What neither pass homes
    // is refused where a second place is materialized (`borrow_home_slot`).
    for &local in &ctx.address_identity_referents {
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        let is_union = matches!(ty.kind(), ty::Adt(adt, _) if adt.is_union());
        let non_pointer_scalar = rust_ty_to_trust_ir_ty(ctx.tcx, ty)
            .map(|t| t.bit_width().is_some() && !is_pointer_like_trust_ir_ty(&t))
            .unwrap_or(false);
        if !is_union
            && non_pointer_scalar
            && cellable_reference_referent_ty(ctx.tcx, ty)
            && !matches!(memory_backed_local_layout(ctx.tcx, ty), Ok(Some(_)))
        {
            cells.insert(local);
        }
    }
    // (4r) A scalar whose address may be kept beyond this body's view
    // (`ctx.retained_address_locals`; see `compute_memory_backed_locals` rule
    // 4r): its cell is the one storage every direct access and every write
    // through the kept address share.
    for &local in ctx.retained_address_locals.keys() {
        if retained_address_home(ctx, body, local)? == RetainedAddressHome::Cell {
            cells.insert(local);
        }
    }
    Ok(cells)
}

/// True if `ty` contains a reference (`&`/`&mut`) reachable through struct / tuple /
/// enum / array / Box / closure-upvar nesting — i.e. a value of this type can carry a
/// borrow back out of a function. Bounded depth; pointers other than Box are not
/// traversed (they do not carry a borrowed-scalar address that needs celling here).
fn ty_carries_reference<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, depth: u32) -> bool {
    if depth > 8 {
        return false;
    }
    match ty.kind() {
        ty::Ref(..) => true,
        ty::Adt(def, args) if def.is_box() => ty_carries_reference(tcx, args.type_at(0), depth + 1),
        ty::Adt(def, args) if def.is_struct() || def.is_enum() || def.is_union() => {
            def.variants().iter().any(|v| {
                v.fields.iter().any(|f| {
                    ty_carries_reference(tcx, f.ty(tcx, *args).skip_normalization(), depth + 1)
                })
            })
        }
        ty::Tuple(elems) => elems
            .iter()
            .any(|e| ty_carries_reference(tcx, e, depth + 1)),
        ty::Array(elem, _) => ty_carries_reference(tcx, *elem, depth + 1),
        ty::Closure(_, args) => args
            .as_closure()
            .upvar_tys()
            .iter()
            .any(|u| ty_carries_reference(tcx, u, depth + 1)),
        _ => false,
    }
}

/// The set of basic blocks that lie on a cycle (are inside a loop). A block `B` is on
/// a cycle iff it is reachable from one of its own successors — i.e. control can leave
/// `B` and return to it. Used to narrow the #80 `&mut`-to-call cell trigger to calls
/// that actually occur inside a loop, where the writeback must survive a back-edge;
/// the non-loop `f(&mut s)` shapes (handled correctly by `mutable_reload`) are left
/// un-celled. CFGs here are small, so the transitive-successor closure is cheap.
fn compute_loop_blocks<'tcx>(body: &Body<'tcx>) -> HashSet<mir::BasicBlock> {
    let successors: Vec<Vec<mir::BasicBlock>> = body
        .basic_blocks
        .iter_enumerated()
        .map(|(_, data)| terminator_successors(&data.terminator().kind))
        .collect();
    // reach[b] = every block reachable from b via one or more successor steps,
    // as a fixed-width bitset (word w bit k => block w*64+k). The previous
    // `Vec<HashSet<BasicBlock>>` transitive closure was ~O(n^4) with SipHash set
    // ops on a long straight-line function (which lowers to hundreds of blocks);
    // the bitset makes each per-block union a handful of word ORs and iterating
    // in REVERSE block order converges a mostly-forward CFG in one or two passes.
    // The least fixpoint of `reach[b] = succ(b) | ⋃_{s∈succ(b)} reach[s]` is the
    // same transitive closure the frontier-based version computed, so the
    // resulting loop-block set (blocks that can reach themselves) is identical.
    let n = successors.len();
    let words = n.div_ceil(64);
    let mut reach: Vec<u64> = vec![0u64; n * words];
    for (b, succs) in successors.iter().enumerate() {
        for s in succs {
            let s = s.index();
            reach[b * words + s / 64] |= 1u64 << (s % 64);
        }
    }
    let mut acc = vec![0u64; words];
    loop {
        let mut changed = false;
        for b in (0..n).rev() {
            acc.iter_mut().for_each(|w| *w = 0);
            for s in &successors[b] {
                let base = s.index() * words;
                for (w, a) in acc.iter_mut().enumerate() {
                    *a |= reach[base + w];
                }
            }
            let base = b * words;
            for (w, a) in acc.iter().enumerate() {
                let before = reach[base + w];
                let after = before | a;
                if after != before {
                    reach[base + w] = after;
                    changed = true;
                }
            }
        }
        if !changed {
            break;
        }
    }
    body.basic_blocks
        .indices()
        .filter(|b| {
            let i = b.index();
            reach[i * words + i / 64] & (1u64 << (i % 64)) != 0
        })
        .collect()
}

/// Allocate a stack slot for every memory-backed local, in the entry block, and
/// record each in `ctx.memory_slots`. Runs once before any block is lowered.
/// `backed` / `cells` come from the caller, which has already run
/// `compute_memory_backed_locals` / `compute_scalar_cell_locals` for its own
/// phi-exclusion set. Both are pure in `(tcx, instance, body)`, so recomputing
/// them here returned the identical answer at the cost of a second pass over the
/// whole body -- and left the same decision implemented in two places.
fn allocate_memory_slots<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    backed: &HashSet<Local>,
    cells: &HashSet<Local>,
) -> Result<(), String> {
    let const_images = wasm32_const_image_locals(ctx, body, backed);
    // Allocate in stable local order for deterministic output.
    let mut backed: Vec<Local> = backed.iter().copied().collect();
    backed.sort_by_key(|local| local.index());
    for local in backed {
        if let Some(&(alloc_id, offset)) = const_images.get(&local) {
            // The local IS its constant's read-only image (see
            // `wasm32_const_image_locals`); an image whose global cannot be
            // emitted keeps an ordinary slot.
            if let Ok(global) = emit_const_alloc_addr(ctx, block, alloc_id, 0, TrustIrTy::Ptr) {
                let ptr = if offset == 0 {
                    global
                } else {
                    slot_byte_ptr(ctx, block, global, offset)
                };
                ctx.memory_slots.insert(local, MemorySlot { ptr });
                ctx.wasm32_const_image_slots.insert(local);
                continue;
            }
        }
        let ty = local_rust_ty(ctx, body, local);
        if let Some(layout) = memory_backed_local_layout(ctx.tcx, ty)? {
            let ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: layout.slot_ty.clone(),
                    count: None,
                    align: Some(layout.align),
                })
                .with_result(ptr),
            );
            ctx.memory_slots.insert(local, MemorySlot { ptr });
            continue;
        }
        // An iterator-adapter (`Map`/`Filter`) chain local: a raw byte slot sized
        // to the chain's layout, as pointer-width (8-byte) lanes. 8-byte aligned —
        // every chain field (a pointer or scalar `start`/`end`) is at most 8-aligned.
        if let Some(size) = iter_chain_slot_size(ctx, ty)? {
            let lanes = size.div_ceil(8).max(1);
            let count = emit_i64_const(ctx, block, i128::from(lanes));
            let ptr = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: TrustIrTy::I64,
                    count: Some(count),
                    align: Some(8),
                })
                .with_result(ptr),
            );
            ctx.memory_slots.insert(local, MemorySlot { ptr });
        }
    }

    // Scalar cells: a captured-by-reference scalar local gets an `Alloca` of its
    // scalar leaf type. Reads/writes of the local route through this cell so
    // `&local` is a stable address (see the cell intercepts). Allocated in stable
    // local order after the slots, in the same entry block.
    let mut cells: Vec<Local> = cells.iter().copied().collect();
    cells.sort_by_key(|local| local.index());
    for local in cells {
        // ONE HOME PER LOCAL: a local that received a memory SLOT above gets no
        // cell. The two analyses are independent and a type can satisfy both (a
        // closure environment with exactly one capture is a memory-backed closure
        // AND a single scalar leaf; so is an address-taken `MaybeUninit<u64>` that
        // a closure also captures). With both allocas the lowering arms split
        // between them: `&local` / `&mut local` and whole-local assignments used
        // the CELL, while the entry-block store of a by-value parameter, the
        // by-value closure receiver (`closure_env_ptr`) and the return used the
        // SLOT. A parameter `f` captured by `&mut` in another closure was then
        // handed over as the never-written cell: a SIGSEGV on a null environment,
        // or a `move` closure's state silently restarted from zero (pinned by
        // `tests/closure_param_single_home_differential.rs`). The slot is the home
        // every path can address — `&local` of a slot-backed local is the slot
        // pointer, and its reads and writes are slot loads and stores — so the
        // slot wins. Keyed on the slot actually ALLOCATED, not on membership in
        // `backed`: a backed local whose type has no slot layout gets no slot and
        // keeps its cell.
        if ctx.memory_slots.contains_key(&local) {
            continue;
        }
        let ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, local));
        let leaf_ty = memory_scalar_leaf_ty(ctx.tcx, ty)?;
        let storage = scalar_cell_storage_for_target(ctx, &leaf_ty);
        // An over-aligned scalar newtype's cell (`&a` of an `A16` local) on the
        // indirect-lane targets has rustc's extent and alignment
        // (`padded_scalar_home_extent`, any alignment, including one above the
        // frame's `TARGET_STACK_ALIGN_BYTES`), the scalar at offset 0 — every read
        // and write of the cell stays a `leaf_ty` access there. `storage` stays the
        // leaf's; `home` records the padded extent, so
        // `checked_scalar_cell_projection` can admit a field chain through the
        // newtype (`a.a`) down to that same scalar, and only that. Every other cell
        // (wasm32 included) is `emit_scalar_leaf_object_alloca`'s: the leaf itself,
        // or `size / leaf` leaf elements at rustc's ABI alignment for an object
        // rustc lays out larger or more aligned than its leaf.
        let mut home = None;
        let ptr = match padded_scalar_home_extent(ctx, ty, &leaf_ty) {
            Some((size, align)) => {
                home = Some(ScalarCellStorage { size, align });
                alloca_rustc_extent(ctx, block, size, align)
            }
            None => emit_scalar_leaf_object_alloca(ctx, block, ty, &leaf_ty)?,
        };
        ctx.scalar_cells.insert(
            local,
            ScalarCell {
                ptr,
                allocated_ty: leaf_ty,
                storage,
                home,
            },
        );
    }

    // ZST reference placeholders: ONE `Alloca` per distinct zero-sized referent
    // PLACE that Ref/RawPtr borrows or a supported user Drop receives (see
    // `zst_ref_placeholders`). Allocated here, in the entry block, so the value
    // dominates every borrow site (a borrow inside a loop or a join must not
    // define its own), and keyed by `zst_ref_placeholder_key` so `&f`/`&f` agree,
    // `&f`/`&g` differ — exactly rustc's per-local alloca — and every projection
    // of one zero-sized local (`&zs[i]`, `&t.0`, `&t.1`) shares that local's
    // address. Aligned to the keyed place's own layout alignment (rustc's
    // `dangling()` convention) so an alignment-checking consumer sees a valid
    // pointer. A zero-sized field or element of a MEMORY-BACKED local gets no
    // placeholder: its borrow is the slot address plus rustc's offset
    // (`lower_scalar_ref`). Deterministic order: first borrow/drop in MIR block
    // order. Borrow and Drop of the same place share one address, including
    // cleanup paths.
    for bb in body.basic_blocks.indices() {
        let data = &body.basic_blocks[bb];
        let mut referents: Vec<_> = data
            .statements
            .iter()
            .filter_map(|statement| match &statement.kind {
                StatementKind::Assign(boxed) => match &boxed.1 {
                    Rvalue::Ref(_, _, source) => Some(source),
                    Rvalue::RawPtr(_, source)
                        if zst_ref_placeholder_key(ctx, body, source)
                            .projection
                            .is_empty() =>
                    {
                        Some(source)
                    }
                    _ => None,
                },
                _ => None,
            })
            .collect();
        if let TerminatorKind::Drop { place, .. } = &data.terminator().kind {
            let ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, place));
            if place.projection.is_empty()
                && is_zero_sized_ty(ctx.tcx, ty)
                && is_structural_drop_ty(ctx.tcx, ty)
            {
                referents.push(place);
            }
        }
        for source in referents {
            if zst_ref_is_memory_place_address(ctx, source) {
                continue;
            }
            if scalar_zst_address::field_offset(ctx, body, source)?.is_some() {
                continue;
            }
            let key = zst_ref_placeholder_key(ctx, body, source);
            if ctx.zst_ref_placeholders.contains_key(&key) {
                continue;
            }
            // Slice elements already have an address supplied by the caller,
            // including over-aligned ZSTs. Their borrow uses data + index*0;
            // allocating a stack placeholder would lose that address identity.
            if ctx.tcx.sess.target.arch.desc() == "aarch64"
                && ctx.tcx.sess.target.os == rustc_target::spec::Os::Linux
                && matches!(
                    source.projection.as_ref(),
                    [ProjectionElem::Deref, ProjectionElem::Index(_)]
                        | [ProjectionElem::Deref, ProjectionElem::ConstantIndex { .. }]
                )
                && fat_ptr_slice_or_str_pointee(
                    ctx.tcx,
                    ctx.monomorphize_ty(local_rust_ty(ctx, body, source.local)),
                )
                .is_some()
            {
                continue;
            }
            let source_mono = ctx.monomorphize_ty(place_rust_ty(ctx, body, source));
            if !zst_ref_placeholder_referent(ctx.tcx, source_mono) {
                continue;
            }
            let key_mono = ctx.monomorphize_ty(place_rust_ty(ctx, body, &key));
            let align = ctx
                .tcx
                .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(key_mono))
                .map_err(|e| format!("ZST referent layout_of failed: {e:?}"))?
                .align
                .bytes();
            // An OVER-ALIGNED referent fails closed on a 64-bit session.
            // trust-cg's native frame layout honours an `Alloca`'s `align` only
            // up to the target's stack alignment; beyond that the slot is
            // placed at the frame's own alignment and the address silently
            // violates the type's. Measured 2026-09-10 on aarch64:
            // `#[repr(align(64))] struct Z64;` — rustc prints
            // `&z as usize % 64 == 0`, this placeholder printed `48` (review
            // probe `adv_zst1_align.rs`, `al64=16` in its full form). The
            // bridge refuses an over-aligned NON-zero-sized local there for the
            // same reason. The wasm lane realigns its frame for any
            // power-of-two `Alloca` alignment, so a 32-bit (wasm32) session
            // keeps the placeholder at the referent's own alignment.
            //
            // To compile such a body natively: give the type an alignment <=
            // the stack alignment, borrow it through a raw pointer whose
            // alignment you establish yourself, or build with the LLVM backend.
            if session_pointer_bytes() != 4 && align > TARGET_STACK_ALIGN_BYTES {
                return Err(format!(
                    "Rvalue::Ref of zero-sized `{source_mono:?}` requires {align}-byte \
                     alignment, above the {TARGET_STACK_ALIGN_BYTES}-byte stack alignment \
                     trust-cg's frame layout guarantees; options: lower the type's \
                     `repr(align)`, take the address through a raw pointer you align \
                     yourself, or compile this crate with the LLVM backend"
                ));
            }
            let placeholder = ctx.fresh_value();
            block.body.push(
                InstrNode::new(Inst::Alloca {
                    ty: TrustIrTy::I8,
                    count: None,
                    align: Some(align),
                })
                .with_result(placeholder),
            );
            ctx.zst_ref_placeholders.insert(key, placeholder);
        }
    }
    Ok(())
}

/// Emit the `Alloca` that gives a Rust object of type `rust_ty`, held as its one
/// scalar leaf `leaf_ty` at offset 0, a stable address. The leaf's own
/// `Alloca { ty: leaf_ty }` when rustc lays the object out as exactly that leaf;
/// an object rustc lays out larger or more aligned than its leaf (a
/// `#[repr(align(N))]` newtype, or a nesting of one) gets `size / leaf` leaf
/// elements at the object's ABI alignment — see [`scalar_leaf_object_extent`].
fn emit_scalar_leaf_object_alloca<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    rust_ty: Ty<'tcx>,
    leaf_ty: &TrustIrTy,
) -> Result<ValueId, String> {
    let (count, align) = scalar_leaf_object_extent(ctx.tcx, rust_ty, leaf_ty)?;
    let count = count.map(|n| emit_i64_const(ctx, block, i128::from(n)));
    let ptr = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Alloca {
            ty: leaf_ty.clone(),
            count,
            align,
        })
        .with_result(ptr),
    );
    Ok(ptr)
}

/// The home already kept for `key` in `homes`, if any, for a materialization of
/// the given `Alloca` shape.
///
/// Fails closed (`[TCG-ADDR-IDENTITY]`) when `key` was already materialized
/// with a different shape, or when another key whose base is `key`'s own base
/// or in `related` ([`related_borrow_bases`]) already has a home: Rust relates
/// those addresses (`&p` and `&p.a` are equal, `&p.a` and `&p.b` are a fixed
/// offset apart, a joined `if c { &a } else { &b }` equals `&a` or `&b`) and
/// two unrelated slots would not be.
fn existing_borrow_home(
    homes: &HashMap<BorrowHomeKey, BorrowHome>,
    key: BorrowHomeKey,
    related: &HashSet<Local>,
    ty: &TrustIrTy,
    count: Option<u64>,
    align: Option<u64>,
) -> Result<Option<ValueId>, String> {
    if let Some(home) = homes.get(&key) {
        if home.ty == *ty && home.count == count && home.align == align {
            return Ok(Some(home.ptr));
        }
        return Err(format!(
            "[TCG-ADDR-IDENTITY] the scalarized referent {key:?} is borrowed as two \
             different objects (`{:?}` x {:?} and `{ty:?}` x {count:?}); one address \
             cannot serve both, so the borrows would not compare equal as Rust requires; \
             failing closed rather than miscompiling",
            home.ty, home.count
        ));
    }
    let base = key.base_local();
    let mut others: Vec<BorrowHomeKey> = homes
        .keys()
        .filter(|other| other.base_local() == base || related.contains(&other.base_local()))
        .copied()
        .collect();
    others.sort_by_key(|other| format!("{other:?}"));
    if let Some(other) = others.first() {
        return Err(format!(
            "[TCG-ADDR-IDENTITY] two related places ({other:?} and {key:?}: two places \
             of the scalarized local {base:?}, or a reference that selects between \
             several locals and a place it can select) are borrowed and passed on; \
             without storage of their own their addresses could not keep the relation \
             Rust gives them (equal, or a fixed field offset apart); failing closed \
             rather than miscompiling. Borrowing one place, or copying the values out \
             first, avoids this"
        ));
    }
    Ok(None)
}

/// The other base locals whose borrow homes `base`'s would have to be related
/// to, from `multi` ([`MirLoweringCtx::multi_referent_references`]).
///
/// A multi-referent reference's placeholder home (keyed by the reference) holds
/// what Rust may make the address of any of its referents, so it is related to
/// each referent, and to every other multi-referent reference sharing a
/// referent with it (both may select the same local). Two referents of one
/// reference are NOT related to each other: `a` and `b` in `if c { &a } else
/// { &b }` are distinct objects, and separate homes give them distinct
/// addresses exactly as Rust does.
fn related_borrow_bases(multi: &HashMap<Local, Vec<Local>>, base: Local) -> HashSet<Local> {
    let own = multi.get(&base);
    let mut related = HashSet::new();
    for (reference, referents) in multi {
        if referents.contains(&base) {
            related.insert(*reference);
        }
        if let Some(own) = own {
            if *reference == base {
                related.extend(referents.iter().copied());
            } else if referents.iter().any(|referent| own.contains(referent)) {
                related.insert(*reference);
            }
        }
    }
    related.remove(&base);
    related
}

/// The frame slot [`MirLoweringCtx::borrow_homes`] keeps for `key`, created on
/// first use as an entry-block `Alloca` of exactly this shape (refusals: see
/// [`existing_borrow_home`]).
fn borrow_home_slot(
    ctx: &mut MirLoweringCtx<'_>,
    key: BorrowHomeKey,
    ty: TrustIrTy,
    count: Option<u64>,
    align: Option<u64>,
) -> Result<ValueId, String> {
    let related = related_borrow_bases(&ctx.multi_referent_references, key.base_local());
    if let Some(ptr) = existing_borrow_home(&ctx.borrow_homes, key, &related, &ty, count, align)? {
        return Ok(ptr);
    }
    let count_value = count.map(|n| {
        let value = ctx.fresh_value();
        ctx.entry_allocas.push(
            InstrNode::new(Inst::Const {
                ty: TrustIrTy::I64,
                value: Constant::Int(i128::from(n)),
            })
            .with_result(value),
        );
        value
    });
    let ptr = ctx.fresh_value();
    ctx.entry_allocas.push(
        InstrNode::new(Inst::Alloca {
            ty: ty.clone(),
            count: count_value,
            align,
        })
        .with_result(ptr),
    );
    ctx.borrow_homes.insert(
        key,
        BorrowHome {
            ptr,
            ty,
            count,
            align,
        },
    );
    Ok(ptr)
}

/// [`borrow_home_slot`] for a referent of Rust type `rust_ty` held as its one
/// scalar leaf `leaf_ty`: the slot has [`emit_scalar_leaf_object_alloca`]'s
/// extent, so it covers the whole object at its ABI alignment.
fn borrow_home_scalar_leaf_slot<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    target: ScalarPlaceBinding,
    rust_ty: Ty<'tcx>,
    leaf_ty: &TrustIrTy,
) -> Result<ValueId, String> {
    let (count, align) = scalar_leaf_object_extent(ctx.tcx, rust_ty, leaf_ty)?;
    borrow_home_slot(
        ctx,
        BorrowHomeKey::Scalar(target),
        leaf_ty.clone(),
        count,
        align,
    )
}

/// Move every frame `Alloca` into the entry block, so each one yields ONE
/// slot per activation however often the site that emitted it runs.
///
/// trust-ir gives every EXECUTION of an `Alloca` fresh storage that lives until
/// the function returns, so an `Alloca` left in a loop body grows the frame on
/// every iteration (the wasm32 lane carves shadow-stack bytes per execution and
/// traps once a long loop exhausts them). The bridge's own `Alloca`s are
/// per-use temporaries — call-argument and `&dyn` materializations, by-value
/// argument copies, constant images, iterator-state copies, loop-index and
/// cursor scratch — whose storage is dead before their site can run again, or
/// the [`MirLoweringCtx::borrow_homes`] slots, which are one per referent by
/// construction. For all of them one slot per activation is exact. The
/// exceptions are [`MirLoweringCtx::per_execution_allocas`] (collection header
/// slots whose address IS a value that may outlive the site) and an `Alloca`
/// whose element count is not a `Const` of its own block (its size is only
/// known where it runs); both stay in place.
///
/// The moved instructions (with the `Const` counts they read) are prepended to
/// the entry block in their original order, after
/// [`MirLoweringCtx::entry_allocas`]. They have no other operands, and the
/// entry block dominates every block, so every use stays dominated. Fails
/// closed if anything branches to the entry block: it would then run more than
/// once per activation and hoisting would not bound the frame.
fn hoist_frame_allocas(
    func: &mut TrustIrFunction,
    entry_allocas: Vec<InstrNode>,
    per_execution_allocas: &HashSet<ValueId>,
) -> Result<(), String> {
    let Some(entry_index) = func.blocks.iter().position(|b| b.id == func.entry) else {
        if entry_allocas.is_empty() {
            return Ok(());
        }
        return Err(format!(
            "[TCG-FRAME-ENTRY] {}: materialized borrow slots need an entry block, and \
             the function has none",
            func.name
        ));
    };
    let mut hoisted: Vec<InstrNode> = entry_allocas;
    for (index, block) in func.blocks.iter_mut().enumerate() {
        if index == entry_index {
            continue;
        }
        let local_consts: HashSet<ValueId> = block
            .body
            .iter()
            .filter(|node| matches!(node.inst, Inst::Const { .. }))
            .flat_map(|node| node.results.iter().copied())
            .collect();
        // Movable: a frame `Alloca` whose count, if any, is a `Const` of this
        // block (moved with it, so it is still defined before its use).
        let mut movable: HashSet<ValueId> = HashSet::new();
        let mut counts: HashSet<ValueId> = HashSet::new();
        for node in &block.body {
            let Inst::Alloca { count, .. } = &node.inst else {
                continue;
            };
            let Some(result) = node.results.first().copied() else {
                continue;
            };
            if per_execution_allocas.contains(&result) {
                continue;
            }
            match count {
                None => {}
                Some(c) if local_consts.contains(c) => {
                    counts.insert(*c);
                }
                Some(_) => continue,
            }
            movable.insert(result);
        }
        if movable.is_empty() {
            continue;
        }
        let mut kept = Vec::with_capacity(block.body.len());
        for node in std::mem::take(&mut block.body) {
            let moves = node
                .results
                .first()
                .is_some_and(|r| movable.contains(r) || counts.contains(r));
            if moves {
                hoisted.push(node);
            } else {
                kept.push(node);
            }
        }
        block.body = kept;
    }
    if hoisted.is_empty() {
        return Ok(());
    }
    let entry = func.entry;
    let branches_to_entry = func
        .blocks
        .iter()
        .flat_map(|b| b.body.iter())
        .any(|node| match &node.inst {
            Inst::Br { target, .. } => *target == entry,
            Inst::CondBr {
                then_target,
                else_target,
                ..
            } => *then_target == entry || *else_target == entry,
            Inst::Switch { default, cases, .. } => {
                *default == entry || cases.iter().any(|c| c.target == entry)
            }
            Inst::Invoke {
                normal_dest,
                unwind_dest,
                ..
            } => *normal_dest == entry || *unwind_dest == entry,
            _ => false,
        });
    if branches_to_entry {
        return Err(format!(
            "[TCG-FRAME-ENTRY] {}: the entry block is a branch target, so it runs more than \
             once per call and cannot hold the function's frame slots; failing closed",
            func.name
        ));
    }
    let entry_body = &mut func.blocks[entry_index].body;
    hoisted.append(entry_body);
    *entry_body = hoisted;
    Ok(())
}

/// The `(count, align)` of [`emit_scalar_leaf_object_alloca`]'s `Alloca`.
///
/// `(None, None)` when rustc's size equals the leaf's and its alignment is at
/// most the leaf's (the object IS the leaf); otherwise the leaf-element count
/// that covers rustc's size, at rustc's ABI alignment, so the address is as
/// aligned as Rust guarantees and in-bounds writes to the object's padding stay
/// inside it. A size that is not a whole number of leaves is refused.
///
/// The wasm lane realigns its frame for any power-of-two alloca alignment; a
/// 64-bit session's frame honours an alloca alignment only up to
/// [`TARGET_STACK_ALIGN_BYTES`], so an object aligned above that is refused
/// there rather than placed at a weaker alignment.
fn scalar_leaf_object_extent<'tcx>(
    tcx: TyCtxt<'tcx>,
    rust_ty: Ty<'tcx>,
    leaf_ty: &TrustIrTy,
) -> Result<(Option<u64>, Option<u64>), String> {
    let Some(leaf_bytes) = trust_ir_leaf_byte_size(leaf_ty).filter(|&b| b != 0) else {
        return Ok((None, None));
    };
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(rust_ty))
        .map_err(|e| format!("scalar-leaf object layout_of({rust_ty:?}) failed: {e:?}"))?;
    if !layout.is_sized() {
        return Err(format!("scalar-leaf object `{rust_ty:?}` is unsized"));
    }
    let size = layout.size.bytes();
    let align = layout.align.bytes();
    if size == leaf_bytes && align <= leaf_bytes {
        return Ok((None, None));
    }
    if size % leaf_bytes != 0 || size == 0 {
        return Err(format!(
            "address-taken `{rust_ty:?}` is {size} bytes, not a whole number of its \
             {leaf_bytes}-byte scalar leaf `{leaf_ty:?}`; failing closed"
        ));
    }
    if session_pointer_bytes() != 4 && align > TARGET_STACK_ALIGN_BYTES {
        return Err(format!(
            "address-taken `{rust_ty:?}` requires {align}-byte alignment, above the \
             {TARGET_STACK_ALIGN_BYTES}-byte stack alignment trust-cg's frame layout \
             guarantees; failing closed"
        ));
    }
    let count = size / leaf_bytes;
    Ok(((count > 1).then_some(count), Some(align.max(leaf_bytes))))
}

/// The stack alignment trust-cg's frame layout guarantees for an `Inst::Alloca`
/// slot: 16 bytes on both targets the bridge emits for (AArch64's mandatory SP
/// alignment, and the x86-64 SysV ABI's). A slot asking for MORE is placed at
/// this alignment anyway, so a ZST reference whose type demands more must fail
/// closed rather than hand back a misaligned address.
const TARGET_STACK_ALIGN_BYTES: u64 = 16;

/// The `zst_ref_placeholders` key of a borrow of the zero-sized place `source`.
/// Every projection of a zero-sized LOCAL (a field of a zero-sized struct or
/// tuple, an element of a zero-sized array) lies at byte offset 0 of it — all its
/// field offsets and element strides are 0 — so rustc gives all of them the
/// local's one address, and they share its key. Any other place keys itself.
fn zst_ref_placeholder_key<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    source: &Place<'tcx>,
) -> Place<'tcx> {
    if !source.projection.is_empty()
        && !source
            .projection
            .iter()
            .any(|elem| matches!(elem, ProjectionElem::Deref))
        && is_zero_sized_ty(
            ctx.tcx,
            ctx.monomorphize_ty(local_rust_ty(ctx, body, source.local)),
        )
    {
        Place::from(source.local)
    } else {
        *source
    }
}

/// Whether a borrow of the (zero-sized) place `source` is the real address of a
/// projection into a MEMORY-BACKED local: a Deref-free projection of a local
/// with a slot. Its address is the slot plus rustc's field offsets and element
/// strides (`memory_place_address_raw`), so `&s.z - &s == offset_of!(S, z)` and
/// every element of a zero-sized array shares the array's address.
fn zst_ref_is_memory_place_address(ctx: &MirLoweringCtx<'_>, source: &Place<'_>) -> bool {
    !source.projection.is_empty()
        && !source
            .projection
            .iter()
            .any(|elem| matches!(elem, ProjectionElem::Deref))
        && local_is_memory_backed(ctx, source.local)
}

/// The referent shapes `lower_scalar_ref`'s ZST placeholder arm serves: a
/// zero-sized struct / tuple / enum / fn item, or a closure all of whose upvars
/// are zero-sized. A ZST ARRAY (`[T; 0]`) is deliberately NOT one: its reference
/// is rustc's aligned dangling constant (the const-length slice binding), and
/// must keep that representation for the `&[T; 0] -> &[T]` unsize.
fn zst_ref_placeholder_referent<'tcx>(tcx: TyCtxt<'tcx>, source_mono: Ty<'tcx>) -> bool {
    match source_mono.kind() {
        ty::Closure(_, closure_args) => closure_args
            .as_closure()
            .upvar_tys()
            .iter()
            .all(|u| is_zero_sized_ty(tcx, u)),
        ty::Array(..) => false,
        _ => is_zero_sized_ty(tcx, source_mono),
    }
}

/// The natural-aligned integer lane type + size that tiles an aggregate slot of
/// alignment `align`: the one decision behind the slot's spelling
/// ([`memory_slot_lane_ty`]) and every lane-by-lane copy of its bytes. Fails
/// closed on an alignment we cannot lane.
///
/// The lane is `align` bytes wide up to 16. Above 16 (a `#[repr(align(32))]`
/// / `align(64)` aggregate) only a 32-bit (wasm32) session admits the slot:
/// its lanes stay 16-byte `I128`s, and the slot's `Alloca` carries rustc's
/// alignment explicitly, which the wasm lane honours by realigning the frame
/// for any power of two (`size % align == 0` makes `size / 16` lanes tile the
/// slot exactly). A 64-bit session's frame honours an `Alloca` alignment only
/// up to [`TARGET_STACK_ALIGN_BYTES`], so it keeps refusing such a slot.
fn memory_aggregate_lane(align: u64) -> Result<(TrustIrTy, u64), String> {
    memory_aggregate_lane_at(session_pointer_bytes(), align)
}

/// [`memory_aggregate_lane`] for an explicit pointer width.
fn memory_aggregate_lane_at(pointer_bytes: u64, align: u64) -> Result<(TrustIrTy, u64), String> {
    Ok(match align {
        1 => (TrustIrTy::I8, 1),
        2 => (TrustIrTy::I16, 2),
        4 => (TrustIrTy::I32, 4),
        8 => (TrustIrTy::I64, 8),
        // 16-byte-aligned aggregate: `I128` lanes. `memory_slot_lane_ty` builds the
        // matching `Tuple([I128; size/16])` slot, so `field * 16` is exactly the byte
        // offset of slot field `field` for every caller (`store_incoming_aggregate_param`,
        // the by-value arg pack), and each lane is a 16-aligned `I128` access.
        16 => (TrustIrTy::I128, 16),
        other
            if pointer_bytes == 4
                && other.is_power_of_two()
                && other <= WASM32_MAX_SLOT_ALIGN_BYTES =>
        {
            (TrustIrTy::I128, 16)
        }
        other => return Err(format!("memory aggregate alignment {other} unsupported")),
    })
}

/// The type at which a lane copy between an aggregate VALUE of `slot_ty` and
/// memory must store (or load) lane `lane`, given the integer lane `lane_ty` of
/// `lane_size` bytes that tiles the slot ([`memory_aggregate_lane`]).
///
/// An `ExtractField` of the lane yields the slot's own field type, and so does
/// the value an `InsertField` takes. For every slot whose fields are the
/// integer (or pointer) lanes [`memory_slot_lane_ty`] and the fixed slot
/// spellings tile it with, that is the integer lane's register file, and the
/// copy keeps `lane_ty`. A FLOAT field (the one-float closure environment of
/// [`closure_slot_ty`]) is stored at its own type: the integer spelling stored
/// an `f64` value as an `i64`, which trust-ir's validator refuses
/// (`OperandTypeMismatch`) and which the x86-64 instruction selector, given an
/// XMM value for a general-register store, lowered as a store of an unrelated
/// register. Measured 2026-10-08 (`targo --unverified`, no proof claim): a
/// bridge-built x86-64 binary (Rosetta) calling an LLVM- or bridge-built
/// `impl FnOnce(f64) -> f64` over one captured `f64` stored the closure slot's
/// own address into it and exited 0 against LLVM's 7 at O0-O3 (the family
/// matrix's `env_f64` / `env_f32`); AArch64 placed the same ill-typed store
/// from the value's register and agreed. A float field of any other width than
/// the lane is refused, so the caller's byte offsets stay exact.
fn slot_lane_value_ty(
    slot_ty: &TrustIrTy,
    lane: u32,
    lane_ty: &TrustIrTy,
    lane_size: u64,
) -> Result<TrustIrTy, String> {
    let fields = aggregate_memory_field_tys(slot_ty)?;
    let (_, field_ty) = fields
        .into_iter()
        .find(|(field, _)| *field == lane)
        .ok_or_else(|| format!("slot {slot_ty:?} has no lane {lane}"))?;
    if !field_ty.is_float() {
        return Ok(lane_ty.clone());
    }
    if field_ty.bit_width().map(u64::from) != Some(lane_size * 8) {
        return Err(format!(
            "slot {slot_ty:?} lane {lane} is {field_ty:?}, not a {lane_size}-byte lane; \
             failing closed rather than copy it at another width"
        ));
    }
    Ok(field_ty)
}

/// The largest aggregate alignment a 32-bit (wasm32) session gives a memory
/// slot: rustc's own `#[repr(align)]` limit (2^29). The wasm lane realigns a
/// frame for any power of two up to 2^30.
const WASM32_MAX_SLOT_ALIGN_BYTES: u64 = 1 << 29;

/// Store an incoming by-value aggregate parameter (the SysV aggregate ABI value,
/// a `slot_ty` tuple in `param_value`) into the parameter local's stack slot,
/// lane by lane. The slot's storage IS the parameter's in-memory bytes after
/// this, so the body reads the parameter through the ordinary memory-place path.
fn store_incoming_aggregate_param<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    arg: Local,
    layout: &MemoryAggregateLayout,
    param_value: ValueId,
    hfa_plan: Option<&HfaCarrierPlan>,
) -> Result<(), String> {
    let dst_ptr = ctx
        .memory_slots
        .get(&arg)
        .cloned()
        .ok_or_else(|| "aggregate parameter without slot".to_owned())?
        .ptr;
    let (_lane_ty, lane_size) = memory_aggregate_lane(layout.align)?;
    let lanes = (layout.size / lane_size) as u32;
    for lane in 0..lanes {
        let extracted = if let Some(plan) = hfa_plan {
            extract_hfa_storage_lane(ctx, block, param_value, lane, plan)
        } else {
            let extracted = ctx.fresh_value();
            emit_lane_value_read(ctx, block, &layout.slot_ty, param_value, lane, extracted)?;
            extracted
        };
        // Write the lane through `emit_aggregate_field_store` (a `Store` at
        // `slot_byte_ptr`'s normalized address), not a raw `Store` through the slot
        // pointer: the slot pointer is then never used as a `Store` address, so
        // when this same parameter is re-passed BY VALUE to another call (which
        // re-types the slot pointer to the aggregate `slot_ty`), the entry store
        // and the outgoing argument do not conflict over the slot pointer's type.
        // The uniform-lane `slot_ty` makes lane index == field index, so the
        // field store writes the correct eightbyte.
        emit_aggregate_field_store(ctx, block, layout.slot_ty.clone(), dst_ptr, lane, extracted)?;
    }
    Ok(())
}

/// Extract a field using its actual floating RESULT type, then preserve its
/// bits in the existing integer memory lane. The checked HFA plan guarantees
/// equal widths and offsets; this is not a numeric float-to-integer conversion.
fn extract_hfa_storage_lane(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    aggregate: ValueId,
    field: u32,
    plan: &HfaCarrierPlan,
) -> ValueId {
    let floating = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::ExtractField {
            ty: plan.lane_ty.clone(),
            aggregate,
            field,
        })
        .with_result(floating),
    );
    let integer = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Cast {
            op: CastOp::Bitcast,
            src_ty: plan.lane_ty.clone(),
            dst_ty: plan.integer_lane_ty.clone(),
            operand: floating,
        })
        .with_result(integer),
    );
    integer
}

/// True iff `local` is memory-backed.
fn local_is_memory_backed(ctx: &MirLoweringCtx<'_>, local: Local) -> bool {
    ctx.memory_slots.contains_key(&local)
}

/// Walk a `Field` / `Downcast` projection chain over `base_ty`'s layout,
/// accumulating the byte offset of the leaf and returning `(offset, leaf_ty)`.
///
/// Intermediate aggregate fields are descended through (struct-of-struct,
/// `Option<Result<_,_>>`-shaped nesting), so the chain may pass through nested
/// aggregates as long as it bottoms out at a scalar leaf. `Deref` is permitted
/// only as the FIRST element (the dereference of the base reference itself) and
/// contributes no offset. Any other projection element fails closed.
///
/// `#[track_caller]`, and it CHAINS with `memory_scalar_leaf_ty`'s: without it the
/// leaf refusal names this walker, which every projected read and write goes
/// through and which therefore tells a reader nothing. With it the refusal names
/// the LOWERING PATH that asked — which is the actionable fact.
#[track_caller]
fn walk_memory_projection_offset<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
) -> Result<(u64, TrustIrTy), String> {
    let (offset, cur_ty) = walk_memory_projection_offset_raw(ctx, base_ty, projection)?;
    let leaf_ty = memory_scalar_leaf_ty(ctx.tcx, cur_ty)?;
    Ok((offset, leaf_ty))
}

/// The core of `walk_memory_projection_offset`: fold a FIXED (`Deref`-leading,
/// non-index) `Field`/`Downcast` projection into a byte offset and return the LEAF's
/// Rust type — WITHOUT requiring the leaf to be a scalar. `walk_memory_projection_
/// offset` layers the scalar-leaf conversion on top; the ADDRESS-only ref path
/// (`&mut/& (*r).field` where the field is itself an AGGREGATE — e.g.
/// `&mut Rev<Range>.iter` yielding a `&mut Range`) uses the raw offset directly,
/// since only the byte address is needed and the sub-aggregate leaf has no single
/// scalar type.
fn walk_memory_projection_offset_raw<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
) -> Result<(u64, Ty<'tcx>), String> {
    let cx = LayoutCx(ctx.tcx);
    let mut cur_layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("memory place layout_of failed: {e:?}"))?;
    let mut offset: u64 = 0;
    let mut cur_ty = base_ty;

    for (i, elem) in projection.iter().enumerate() {
        match elem {
            // A leading `Deref` denotes the dereference of the base reference: the
            // base type is already the pointee, so it contributes no offset. Only
            // valid as the first projection element.
            ProjectionElem::Deref if i == 0 => {}
            ProjectionElem::Downcast(_, variant_index) => {
                cur_layout = cur_layout.for_variant(&cx, *variant_index);
                // The downcast itself contributes no offset; the variant's
                // fields are addressed relative to the base.
            }
            ProjectionElem::Field(field, _field_ty) => {
                let field_offset = cur_layout.fields.offset(field.index()).bytes();
                offset += field_offset;
                cur_layout = cur_layout.field(&cx, field.index());
                dyn_tail::refuse_dynamic_offset_field(ctx.tcx, &cur_layout, field_offset)?;
                // Take the leaf type from the layout, not the projection's
                // declared field type: `memory_field_place` supplies a
                // placeholder field type, and the layout is authoritative.
                cur_ty = cur_layout.ty;
            }
            #[cfg(rustc_session_split)]
            ProjectionElem::PhantomDeref => {
                return Err("memory place PhantomDeref is not a runtime address".to_owned());
            }
            ProjectionElem::Deref
            | ProjectionElem::Index(_)
            | ProjectionElem::ConstantIndex { .. }
            | ProjectionElem::Subslice { .. }
            | ProjectionElem::OpaqueCast(_)
            | ProjectionElem::UnwrapUnsafeBinder(_) => {
                return Err(format!(
                    "memory place projection {elem:?} not supported in this increment"
                ));
            }
        }
    }

    Ok((offset, cur_ty))
}

/// True iff the projection contains a runtime array/slice INDEX element — an
/// `Index(local)`, a `ConstantIndex`, or a `Subslice`. These cannot be folded to
/// a static byte offset (the index is a runtime value), so the caller must use
/// the runtime-address walker (`walk_memory_projection_runtime_address`) rather
/// than the constant-offset `walk_memory_projection_offset`.
fn projection_has_index_element<'tcx>(projection: &[ProjectionElem<Local, Ty<'tcx>>]) -> bool {
    projection.iter().any(|elem| {
        matches!(
            elem,
            ProjectionElem::Index(_)
                | ProjectionElem::ConstantIndex { .. }
                | ProjectionElem::Subslice { .. }
        )
    })
}

/// The runtime value of an `Index(index_local)` projection operand — CELL-AWARE.
///
/// A CELLED index local (`compute_scalar_cell_locals`: its address is taken by
/// `&raw`, a closure capture or a `&mut` in a loop, or it is an SSA-071
/// cell-retry local) keeps its live value ONLY in its cell: every write is a
/// `Store` (the `lower_assign` / `finish_assign_target` cell intercepts) and never
/// rebinds `scalar_values`, so its SSA binding is STALE — for an entry argument
/// the INCOMING parameter (a silent wrong index: `(*a)[i]` after
/// `p = &raw const i; i = 5` addressed `a[incoming i]`), for any other local the
/// never-defined synthetic `ValueId(local)`. Load it from the cell, typed as the
/// cell was allocated (`allocate_memory_slots`: `memory_scalar_leaf_ty` of the
/// local's type) — the same `Load` `lower_operand_to_value`'s whole-local cell
/// read emits, through which the `&raw (*s)[i]` arm already reads its index.
/// Every other index local keeps its SSA binding, byte-identically. Every reader
/// of an `Index` operand's VALUE must come through here.
fn index_local_value(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    index_local: Local,
) -> Result<ValueId, String> {
    if let Some(cell) = ctx.scalar_cells.get(&index_local).cloned() {
        return Ok(emit_typed_load(ctx, block, cell.ptr, cell.allocated_ty));
    }
    value_for_scalar_binding(ctx, ScalarPlaceBinding::Local(index_local))
}

/// The element index `len - offset` of a FROM-END `ConstantIndex`, as an `I64`.
/// `len` must be the RUNTIME element count of the slice being indexed (its
/// pointer metadata), never the pattern's `min_length`. MIR defines the
/// projection only when `len >= min_length >= offset >= 1`, so the subtraction
/// does not wrap on a defined execution.
fn emit_from_end_index(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    len: ValueId,
    offset: u64,
) -> ValueId {
    let off = emit_i64_const(ctx, block, i128::from(offset));
    let index = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::BinOp {
            op: TrustIrBinOp::Sub,
            ty: TrustIrTy::I64,
            lhs: len,
            rhs: off,
        })
        .with_result(index),
    );
    index
}

/// Resolve the runtime element index of an `Index`/`ConstantIndex` projection to
/// an `I64` value. `Index(local)` reads the index local's current value
/// ([`index_local_value`]: its cell when it is celled, else its scalar binding —
/// a genuine runtime index); `ConstantIndex` materializes its literal offset
/// (resolving `from_end` against the element count rustc records in
/// `min_length`).
fn resolve_index_value<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    elem: &ProjectionElem<Local, Ty<'tcx>>,
) -> Result<ValueId, String> {
    match elem {
        ProjectionElem::Index(index_local) => index_local_value(ctx, block, *index_local),
        ProjectionElem::ConstantIndex {
            offset,
            min_length,
            from_end,
        } => {
            if *from_end {
                // A FROM-END ConstantIndex resolves against the container's
                // RUNTIME length, which this resolver cannot see — `min_length`
                // is only the pattern's minimum (the bindings count). Subtracting
                // from `min_length` addresses the FRONT for any slice longer than
                // the pattern (the q14 write miscompile). Callers that CAN read
                // the fat-pointer length resolve from_end themselves before
                // reaching here (see the slice-element store/use paths), so fail
                // closed rather than silently mis-address.
                return Err(format!(
                    "from-end ConstantIndex (offset {offset}) needs the runtime slice \
                     length, not min_length {min_length} (failing closed rather than \
                     miscompiling)"
                ));
            }
            Ok(emit_i64_const(ctx, block, i128::from(*offset)))
        }
        other => Err(format!(
            "resolve_index_value on non-index projection {other:?}"
        )),
    }
}

/// The static offset `prefix + k * stride` of a front `ConstantIndex { offset:
/// k, from_end: false }` on the GEP lane ([`wasm32_inbounds`]), or `None` (an
/// `Index`, a from-end index, an overflow, or off the GEP lane), where the
/// caller resolves the index at run time as before.
fn constant_index_static_offset<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    elem: &ProjectionElem<Local, Ty<'tcx>>,
    stride: u64,
    prefix: u64,
) -> Option<u64> {
    let ProjectionElem::ConstantIndex {
        offset,
        from_end: false,
        ..
    } = elem
    else {
        return None;
    };
    if !ctx.place_geps {
        return None;
    }
    offset.checked_mul(stride)?.checked_add(prefix)
}

/// [`resolve_index_value`] for an index met during a layout walk, where the one
/// unsized `[T]` the walk can reach — a walk never crosses a second `Deref` — is
/// the base pointer's own pointee or tail. A FROM-END `ConstantIndex` into that
/// `[T]` counts back from `tail_len`, the base pointer's runtime metadata (Rust
/// defines a slice-tail pointer's metadata as the tail's element count), when the
/// caller supplied it. A sized array never takes a from-end index (rustc_middle
/// `ConstantIndex`: "Always false when indexing an array"), and with no
/// `tail_len` a from-end index stays refused by `resolve_index_value`.
fn walk_index_value<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    elem: &ProjectionElem<Local, Ty<'tcx>>,
    container: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
    tail_len: Option<ValueId>,
) -> Result<ValueId, String> {
    match (elem, container.ty.kind(), tail_len) {
        (
            ProjectionElem::ConstantIndex {
                offset,
                from_end: true,
                ..
            },
            ty::Slice(_),
            Some(len),
        ) => Ok(emit_from_end_index(ctx, block, len, *offset)),
        _ => resolve_index_value(ctx, block, elem),
    }
}

/// The runtime element count of the unsized `[T]` behind a slot-backed
/// length-metadata reference `place.local` (its slot's lane 1), for a walk of
/// `place` from [`memory_place_walk_base`]. Loaded only when the projection
/// indexes that slice FROM ITS END, the one element that needs it; `None` for
/// every other place, which keeps such an index refused.
fn memory_place_walk_tail_len<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<Option<ValueId>, String> {
    let from_end = place
        .projection
        .iter()
        .any(|elem| matches!(elem, ProjectionElem::ConstantIndex { from_end: true, .. }));
    if !from_end || slot_dst_ref_walk_pointee(ctx, body, place).is_none() {
        return Ok(None);
    }
    load_fat_ptr_meta(ctx, block, place.local).map(Some)
}

/// The element layout (size == stride, and Rust type) of an array / slice
/// `cur_layout`. Rust arrays and slices store elements contiguously with no
/// inter-element padding, so the element's own layout size IS the addressing
/// stride. The element layout is read from the container layout's field 0 (every
/// element shares the same layout). Fails closed for any non-array/slice type.
fn array_element_layout<'tcx>(
    cx: &LayoutCx<'tcx>,
    container: &rustc_middle::ty::layout::TyAndLayout<'tcx>,
) -> Result<(u64, Ty<'tcx>), String> {
    match container.ty.kind() {
        ty::Array(..) | ty::Slice(..) => {
            let element = container.field(cx, 0);
            Ok((element.size.bytes(), element.ty))
        }
        other => Err(format!(
            "indexed place base is not an array/slice: {other:?}"
        )),
    }
}

/// Walk a projection that contains a RUNTIME array/slice index, producing the
/// element's byte ADDRESS as a `ValueId` and the trust-ir scalar leaf type stored
/// there. `base_ptr` is the address the projection is relative to: the `Alloca`
/// slot pointer for an array local, or the reference scalar value for an array /
/// slice deref (`(*r)[i]`). `base_ty` is the base local's Rust type.
///
/// Field / Downcast elements accumulate a static byte offset (resolved through
/// the Rust layout, descending into nested aggregates). An `Index(local)` /
/// `ConstantIndex` flushes the accumulated static offset onto the running address
/// ([`wasm32_inbounds::projection_addr`]) and then advances by `index *
/// element_stride` (the `PtrToInt`/add/`IntToPtr` arithmetic of
/// `emit_element_addr`); on the GEP lane a front `ConstantIndex` instead joins
/// the static offset. The current layout descends into the array element so a
/// trailing `arr[i].field` chain keeps working. The bottom-most leaf must be a
/// memory scalar.
///
/// `Subslice` is NOT handled here (it yields a fat pointer, not a scalar leaf);
/// the dedicated subslice path handles it. Any other element fails closed.
fn walk_memory_projection_runtime_address<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    base_ptr: ValueId,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
) -> Result<(ValueId, TrustIrTy), String> {
    walk_memory_projection_runtime_address_in(ctx, block, base_ptr, base_ty, projection, None)
}

/// [`walk_memory_projection_runtime_address`] with `tail_len`, the runtime
/// element count of the unsized `[T]` the walk starts in or reaches (see
/// [`walk_index_value`]); `None` keeps a from-end index refused.
fn walk_memory_projection_runtime_address_in<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    base_ptr: ValueId,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
    tail_len: Option<ValueId>,
) -> Result<(ValueId, TrustIrTy), String> {
    let cx = LayoutCx(ctx.tcx);
    let mut cur_layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("indexed memory place layout_of failed: {e:?}"))?;
    // The running address (after any flushed index strides) and the static byte
    // offset accumulated since the last index flush.
    let mut addr = base_ptr;
    let mut offset: u64 = 0;
    let mut cur_ty = base_ty;

    for (i, elem) in projection.iter().enumerate() {
        match elem {
            ProjectionElem::Deref if i == 0 => {}
            ProjectionElem::Downcast(_, variant_index) => {
                cur_layout = cur_layout.for_variant(&cx, *variant_index);
            }
            ProjectionElem::Field(field, _) => {
                let field_offset = cur_layout.fields.offset(field.index()).bytes();
                offset += field_offset;
                cur_layout = cur_layout.field(&cx, field.index());
                dyn_tail::refuse_dynamic_offset_field(ctx.tcx, &cur_layout, field_offset)?;
                cur_ty = cur_layout.ty;
            }
            ProjectionElem::Index(_) | ProjectionElem::ConstantIndex { .. } => {
                let (stride, element_ty) = array_element_layout(&cx, &cur_layout)?;
                // On the GEP lane a front `ConstantIndex` is one more static
                // step of the in-bounds projection: its element offset joins
                // the static offset, which one GEP then applies.
                if let Some(element_offset) =
                    constant_index_static_offset(ctx, elem, stride, offset)
                {
                    offset = element_offset;
                    cur_layout = cur_layout.field(&cx, 0);
                    cur_ty = element_ty;
                    continue;
                }
                // Flush the static prefix offset onto the running base, then add
                // `index * stride`. Both use 1-byte-stride pointer arithmetic so
                // the byte address is exact.
                if offset != 0 {
                    addr = wasm32_inbounds::projection_addr(ctx, block, addr, offset);
                    offset = 0;
                }
                let index = walk_index_value(ctx, block, elem, &cur_layout, tail_len)?;
                addr = emit_element_addr(ctx, block, addr, index, stride);
                cur_layout = cur_layout.field(&cx, 0);
                cur_ty = element_ty;
            }
            other => {
                return Err(format!(
                    "indexed memory place projection {other:?} not supported"
                ));
            }
        }
    }

    if offset != 0 {
        addr = wasm32_inbounds::projection_addr(ctx, block, addr, offset);
    }
    let leaf_ty = memory_scalar_leaf_ty(ctx.tcx, cur_ty)?;
    Ok((addr, leaf_ty))
}

/// Walk a projection that contains a RUNTIME array/slice index, producing the
/// addressed PLACE's byte ADDRESS as a `ValueId` and the Rust type stored there —
/// WITHOUT requiring the bottom-most type to be a scalar leaf. This is the
/// whole-element/whole-aggregate counterpart of
/// `walk_memory_projection_runtime_address` (which bottoms out at a scalar leaf):
/// it is used by the whole-aggregate-element store path (`arr[i] = P{..}`), where
/// the place `arr[i]` denotes an entire aggregate element, not a single scalar.
///
/// The address arithmetic is identical (Field/Downcast fold to a static offset,
/// each Index flushes the prefix then advances by `index * stride`), so the
/// element base address it returns is exactly the base a later `arr[i].field`
/// leaf read/write would address. The caller is responsible for decomposing the
/// returned aggregate type into its scalar leaves at fixed offsets (the element
/// type was already validated all-scalar-leaf when the array was admitted by
/// `array_memory_layout`).
fn walk_memory_projection_runtime_place_address<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    base_ptr: ValueId,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
) -> Result<(ValueId, Ty<'tcx>), String> {
    walk_memory_projection_runtime_place_address_in(ctx, block, base_ptr, base_ty, projection, None)
}

/// [`walk_memory_projection_runtime_place_address`] with `tail_len`, as
/// [`walk_memory_projection_runtime_address_in`] takes it.
fn walk_memory_projection_runtime_place_address_in<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    base_ptr: ValueId,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
    tail_len: Option<ValueId>,
) -> Result<(ValueId, Ty<'tcx>), String> {
    let cx = LayoutCx(ctx.tcx);
    let mut cur_layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("indexed memory place layout_of failed: {e:?}"))?;
    let mut addr = base_ptr;
    let mut offset: u64 = 0;
    let mut cur_ty = base_ty;

    for (i, elem) in projection.iter().enumerate() {
        match elem {
            ProjectionElem::Deref if i == 0 => {}
            ProjectionElem::Downcast(_, variant_index) => {
                cur_layout = cur_layout.for_variant(&cx, *variant_index);
            }
            ProjectionElem::Field(field, _) => {
                let field_offset = cur_layout.fields.offset(field.index()).bytes();
                offset += field_offset;
                cur_layout = cur_layout.field(&cx, field.index());
                dyn_tail::refuse_dynamic_offset_field(ctx.tcx, &cur_layout, field_offset)?;
                cur_ty = cur_layout.ty;
            }
            ProjectionElem::Index(_) | ProjectionElem::ConstantIndex { .. } => {
                let (stride, element_ty) = array_element_layout(&cx, &cur_layout)?;
                if let Some(element_offset) =
                    constant_index_static_offset(ctx, elem, stride, offset)
                {
                    offset = element_offset;
                    cur_layout = cur_layout.field(&cx, 0);
                    cur_ty = element_ty;
                    continue;
                }
                if offset != 0 {
                    addr = wasm32_inbounds::projection_addr(ctx, block, addr, offset);
                    offset = 0;
                }
                let index = walk_index_value(ctx, block, elem, &cur_layout, tail_len)?;
                addr = emit_element_addr(ctx, block, addr, index, stride);
                cur_layout = cur_layout.field(&cx, 0);
                cur_ty = element_ty;
            }
            // `a[from..to]` of an ARRAY — the `mid @ ..` binding of a pattern on
            // `[T; N]`, borrowed as `&[T; to - from]` — is the SIZED place
            // `[T; to - from]` starting `from` elements in: a static offset of
            // `from * stride`. MIR never sets `from_end` on an array
            // (rustc_middle `Subslice`), and a slice's subslice is unsized (a fat
            // result), which keeps its dedicated `{ data, len }` path; both stay
            // refused here, as does a range the array's layout does not hold.
            ProjectionElem::Subslice {
                from,
                to,
                from_end: false,
            } if matches!(cur_layout.ty.kind(), ty::Array(..)) => {
                let (stride, element_ty) = array_element_layout(&cx, &cur_layout)?;
                let rustc_abi::FieldsShape::Array { count, .. } = cur_layout.fields else {
                    return Err(format!(
                        "array subslice base {:?} has no array layout",
                        cur_ty
                    ));
                };
                if from > to || *to > count {
                    return Err(format!(
                        "array subslice {from}..{to} lies outside its {count}-element array"
                    ));
                }
                offset += from * stride;
                cur_ty = Ty::new_array(ctx.tcx, element_ty, to - from);
                cur_layout = ctx
                    .tcx
                    .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(cur_ty))
                    .map_err(|e| format!("array subslice layout_of failed: {e:?}"))?;
            }
            other => {
                return Err(format!(
                    "indexed memory place projection {other:?} not supported"
                ));
            }
        }
    }

    if offset != 0 {
        addr = wasm32_inbounds::projection_addr(ctx, block, addr, offset);
    }
    Ok((addr, cur_ty))
}

/// The BASE POINTER and BASE TYPE a memory-backed place's projection is walked
/// from.
///
/// For an ordinary memory-backed local that is the slot's own address and the
/// local's own type — `walk_memory_projection_offset_raw`'s `Deref@i==0` arm
/// then treats the base as already being the pointee.
///
/// For a FAT reference to a slice-tail DST it is NOT. Such a local's slot holds
/// `{ data, metadata }`, so the POINTEE's address is the DATA LANE'S VALUE, not
/// the slot's own address, and the layout to walk is the POINTEE's, not the
/// pointer's. Measured on `&Hdr { n: u32, m: u32, tail: [u8] }`: walking from
/// the slot folded `(*h).n` onto the slot's lane 0 and was caught only by a
/// leaf-TYPE mismatch (`memory aggregate field load type Ptr used as U32`) —
/// which a `u64`- or pointer-typed prefix field would NOT have produced. So this
/// is a correctness seam, not a capability one.
///
/// Scoped to the slice-tail DST class this lane introduced (nothing else changes
/// base): a `&[T]` / `&str` / `&dyn` memory-backed base keeps its exact existing
/// treatment at every caller, and those bases have no named field to project
/// anyway.
fn memory_place_walk_base<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<(ValueId, Ty<'tcx>), String> {
    let Some(slot) = ctx.memory_slots.get(&place.local).cloned() else {
        return Err("memory_place_address on non-memory local".to_owned());
    };
    let base_ty = local_rust_ty(ctx, body, place.local);
    if let Some(pointee) = slot_dst_ref_walk_pointee(ctx, body, place) {
        let data = load_fat_ptr_data(ctx, block, place.local)?;
        return Ok((data, pointee));
    }
    Ok((slot.ptr, base_ty))
}

/// The POINTEE a `(*r)…` place must be walked over when `r` is a SLOT-backed
/// reference to a slice-tail DST, or `None` for every other place — the pure,
/// emit-nothing half of [`memory_place_walk_base`] (which calls it, so the two
/// cannot disagree about which places take the data lane).
///
/// # [TCG-DEREF-BASE-ADDR] Why a walk-from-slot site must ask this
///
/// A site that walks a place's projection from `memory_slot_ptr(local)` over
/// `local_rust_ty(local)` is right for an owned aggregate and WRONG for a
/// slot-backed `r: &H<[T]>` with a `Deref`-led projection: the walker skips the
/// leading `Deref`, then folds the first `Field` over the REFERENCE's own
/// `ScalarPair` layout — field 0 is the data word at `+0`, field 1 the length at
/// `+8` — and the load lands in `r`'s slot, not in the pointee. MEASURED at the
/// unpatched tip `572c4ce34`, both opt levels, executed silent wrong answers:
///
///   * `_2 = copy ((*_1).0: Inner)` into a SCALARIZED `_2`
///     (`lower_memory_nested_aggregate_field_use`) read `r`'s `{ data, len }` as
///     `Inner { a, b }`: `nested 3 6098348344 4` vs LLVM `nested 3 31 41` — `b`
///     is the tail LENGTH;
///   * `discriminant(((*_1).1: E))` (`lower_memory_projected_discriminant`) read
///     the tag out of the length word: `disc 0 0` vs LLVM `disc 55 1009`.
///
/// Such a site computes its OFFSET over this type (before any decline, emitting
/// nothing) and takes its BASE POINTER from `memory_place_walk_base` only once
/// it has committed — so a decline leaves no dead load behind.
fn slot_dst_ref_walk_pointee<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> Option<Ty<'tcx>> {
    if !matches!(place.projection.first(), Some(ProjectionElem::Deref)) {
        return None;
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    slice_tail_dst_ref_pointee(ctx.tcx, base_ty).map(|(pointee, _, _)| pointee)
}

/// The TYPE a memory-backed place's projection is walked over: the slice-tail
/// DST's POINTEE for a `Deref`-led place on a slot-backed DST reference (see
/// [`slot_dst_ref_walk_pointee`]), else the local's own type — exactly the type
/// [`memory_place_walk_base`] returns, computed without emitting anything.
fn memory_place_walk_ty<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> Ty<'tcx> {
    slot_dst_ref_walk_pointee(ctx, body, place)
        .unwrap_or_else(|| local_rust_ty(ctx, body, place.local))
}

/// Compute the byte ADDRESS of a memory-backed `place` (and the trust-ir scalar
/// type stored there), resolving Field offsets and enum Downcasts through the
/// Rust layout (descending through nested aggregate fields). A runtime array
/// index (`arr[i]` / `ConstantIndex`) is resolved to `slot + i*stride` runtime
/// arithmetic; pure Field/Downcast chains fold to a static offset. Only the
/// projection chains the memory model supports are handled; anything else fails
/// closed.
///
/// Returns `(addr, leaf_ty)`.
///
/// `#[track_caller]` for the same reason as `walk_memory_projection_offset`: the
/// scalar-leaf refusal it can return is reported verbatim, and naming this
/// function locates nothing.
#[track_caller]
fn memory_place_address<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<(ValueId, TrustIrTy), String> {
    let (base_ptr, base_ty) = memory_place_walk_base(ctx, body, block, place)?;
    // A runtime / constant array index cannot be folded to a static offset;
    // compute the element address with runtime pointer arithmetic.
    if projection_has_index_element(&place.projection) {
        let tail_len = memory_place_walk_tail_len(ctx, body, block, place)?;
        return walk_memory_projection_runtime_address_in(
            ctx,
            block,
            base_ptr,
            base_ty,
            &place.projection,
            tail_len,
        );
    }
    let (offset, leaf_ty) = walk_memory_projection_offset(ctx, base_ty, &place.projection)?;
    let addr = if offset == 0 {
        base_ptr
    } else {
        wasm32_inbounds::projection_addr(ctx, block, base_ptr, offset)
    };
    Ok((addr, leaf_ty))
}

/// Like `memory_place_address` but the projected place may bottom out at an
/// AGGREGATE leaf (a nested struct/tuple/array, or the `ManuallyDrop<T>` payload of
/// a union: `&raw const (union.value)`). Only the byte ADDRESS is returned — the
/// result is a raw pointer regardless of the pointee's shape, so no scalar-leaf
/// conversion (which would fail closed on an aggregate) is required. Used by the
/// raw-pointer-to-sub-place arm (`&raw const/mut (place.field…)`).
fn memory_place_address_raw<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<ValueId, String> {
    // Same base rule as `memory_place_address` — a FAT slice-tail DST reference
    // is walked from its DATA LANE over the POINTEE's layout, never from its own
    // slot. See `memory_place_walk_base`.
    let (base_ptr, base_ty) = memory_place_walk_base(ctx, body, block, place)?;
    if projection_has_index_element(&place.projection) {
        let tail_len = memory_place_walk_tail_len(ctx, body, block, place)?;
        let (addr, _leaf) = walk_memory_projection_runtime_place_address_in(
            ctx,
            block,
            base_ptr,
            base_ty,
            &place.projection,
            tail_len,
        )?;
        return Ok(addr);
    }
    let (offset, _leaf_ty) = walk_memory_projection_offset_raw(ctx, base_ty, &place.projection)?;
    Ok(if offset == 0 {
        base_ptr
    } else {
        wasm32_inbounds::projection_addr(ctx, block, base_ptr, offset)
    })
}

/// Whether `place` is a `(*r).field[.…]` deref through a reference local whose
/// pointee is a memory-eligible aggregate that the EXISTING scalarized-aggregate
/// reference path cannot represent (a multi-variant Direct enum, or an aggregate
/// with nested aggregate fields). Such a deref must be addressed by the memory
/// model's byte offsets. Returns the pointee Rust type.
///
/// Deliberately NARROW so it never steals a working case:
///   * a flat scalar-leaf aggregate pointee (e.g. `&Pair{u64,u64}`) is left to
///     the existing scalarized `aggregate_field_memory_access` machinery (which
///     handles `(*r).field`, whole `*r` reads, and `*r = Aggregate{…}` stores);
///   * a WHOLE-aggregate deref (`*r` with no trailing field) is also left to that
///     path, since the memory model only loads/stores scalar LEAVES here.
/// Whether `ty` is a SCALAR-COLLAPSED NEWTYPE AGGREGATE: a struct or non-empty
/// tuple whose rustc layout is a SINGLE `Scalar` (`BackendRepr::Scalar`) and
/// whose trust-ir mapping collapses to that one scalar (`Box<T>` via its
/// `Unique`/`NonNull`/pattern-type chain -> a pointer scalar; `struct N(i64)` /
/// a user-`Drop` `Guard(i64)` -> `I64`). Such a pointee is a legitimate
/// byte-offset-addressing target for a `(*p).field…` chain: its single non-ZST
/// leaf sits at offset 0 and is loadable with one typed access.
///
/// Deliberately NOT admitted (each keeps its existing handling / fail-closed):
///   * a bare primitive pointee (no `Field` projection exists on it; the
///     scalar deref path owns `*p`),
///   * an intercepted slot-modeled `Vec`/`BTreeMap`/`HashMap`/`String` pointee
///     — their trust-ir "scalar" is a stack-SLOT ADDRESS, not the pointee's
///     bytes (structurally unreachable anyway: their real layouts are 3 words,
///     never `BackendRepr::Scalar`) — and a `Box` over a legacy slot-modeled
///     payload. A genuine Global Box<Vec/String> with a checked inline header
///     has ordinary pointer bytes and is admitted by the scalar/layout checks,
///   * a wrapper whose leaf is wide (`W(&str)` — `ScalarPair`, a single load
///     would truncate),
///   * enums (a `Field` needs a `Downcast`; out of this increment's scope),
///     unions, unsized and ZST pointees.
fn scalar_collapsed_newtype_pointee<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> Result<bool, String> {
    let is_struct = matches!(ty.kind(), ty::Adt(adt, _) if adt.is_struct() && !adt.is_union());
    let is_tuple = matches!(ty.kind(), ty::Tuple(fields) if !fields.is_empty());
    if !is_struct && !is_tuple {
        return Ok(false);
    }
    // Belt-and-suspenders: never byte-address an intercepted slot-modeled type.
    if vec_element_ty(tcx, ty).is_some()
        || btreemap_kv_ty(tcx, ty).is_some()
        || any_hashmap_kv_ty(tcx, ty).is_some()
        || is_hashmap_dead_internal_ty(tcx, ty)
        || is_string_ty(tcx, ty)
    {
        return Ok(false);
    }
    // Legacy slot-modeled payloads cannot be byte-addressed. A genuine
    // Global Box<Vec/String> now stores a real pointer to its checked inline
    // header; the Box's own Unique/NonNull fields are ordinary pointer bytes.
    if let Some(boxed) = box_element_ty(tcx, ty) {
        let real_header = real_vec_string_header_layout(tcx, boxed)?.is_some();
        if !real_header
            && (vec_element_ty(tcx, boxed).is_some()
                || btreemap_kv_ty(tcx, boxed).is_some()
                || any_hashmap_kv_ty(tcx, boxed).is_some()
                || is_hashmap_dead_internal_ty(tcx, boxed)
                || is_string_ty(tcx, boxed))
        {
            return Ok(false);
        }
    }
    // The collapse witness: the whole pointee maps to ONE loadable trust-ir
    // scalar (exactly the condition that makes the addressable predicate's
    // bare-scalar early-exit bounce it).
    if memory_scalar_leaf_ty(tcx, ty).is_err() {
        return Ok(false);
    }
    // The LOAD-BEARING gate: the real memory representation is exactly one
    // scalar — excludes 3-word slot-modeled wrappers, fat-pointer ScalarPair
    // newtypes, and every multi-word aggregate.
    let layout = tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
        .map_err(|e| format!("scalar-collapsed newtype pointee layout_of failed: {e:?}"))?;
    if layout.is_unsized() || layout.size.bytes() == 0 {
        return Ok(false);
    }
    if matches!(layout.backend_repr, rustc_abi::BackendRepr::Scalar(_)) {
        return Ok(true);
    }
    // A repr(C) single-field struct can have Memory ABI while the bridge
    // collapses its value to the field's scalar. A projected read still needs
    // the field's byte address. Require the one scalar field to occupy the
    // entire object at offset zero; padded and multi-field structs stay on
    // their aggregate paths.
    if layout.fields.count() == 1 && layout.fields.offset(0).bytes() == 0 {
        let field = layout.field(&LayoutCx(tcx), 0);
        return Ok(field.size == layout.size
            && matches!(field.backend_repr, rustc_abi::BackendRepr::Scalar(_))
            && rust_ty_to_trust_ir_ty(tcx, ty).is_ok_and(|ty| ty.bit_width().is_some()));
    }
    Ok(false)
}

fn memory_aggregate_ref_pointee<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> Result<Option<Ty<'tcx>>, String> {
    let Some(ProjectionElem::Deref) = place.projection.first() else {
        return Ok(None);
    };
    // Require at least one projection past the Deref (a field / downcast chain),
    // i.e. `(*r).field…`. A bare `*r` (whole aggregate) is not handled here.
    if place.projection.len() < 2 {
        return Ok(None);
    }
    let base_ty = local_rust_ty(ctx, body, place.local);
    let (ty::Ref(_, inner, _) | ty::RawPtr(inner, _)) = base_ty.kind() else {
        return Ok(None);
    };
    let is_raw_ptr = matches!(base_ty.kind(), ty::RawPtr(..));
    let inner = ctx.monomorphize_ty(*inner);
    // Vec/String borrows address their canonical inline header. The same
    // rustc-offset walker must serve projected reads, writes and reborrows.
    if real_vec_string_header_layout(ctx.tcx, inner)?.is_some()
        && (ctx.scalar_values.contains_key(&place.local)
            || ctx.scalar_cells.contains_key(&place.local)
            || is_entry_arg(body, place.local))
    {
        return Ok(Some(inner));
    }
    if ctx.scalar_cells.contains_key(&place.local)
        && raw_ptr_aggregate_pointee_addressable(ctx.tcx, inner)?
    {
        return Ok(Some(inner));
    }

    // An already-bound reference to an over-aligned Rust image needs no stack
    // slot of that alignment. Scalar field accesses use the pointee's actual
    // offsets, even when its padded layout cannot use the flat aggregate lane.
    // A checked padded single-scalar image also needs this route at alignment
    // 16: its ABI is Memory, so the scalar-collapsed reference path cannot claim
    // it. The layout witness below checks the leaf and its real zero offset.
    // Borrowed scalar aliases and spilled pointers retain their existing paths.
    //
    // ⚑ THE `aarch64` GATE BELOW WAS TESTED FOR REMOVAL 2026-09-29 AND KEPT. Nothing
    // in the general over-aligned lane is architecture-specific — its conditions
    // describe the POINTEE's Rust layout (over-16-byte alignment, a struct or
    // tuple, an all-`Field`
    // projection, a scalar leaf) — and the gate carries no stated reason, so it looks
    // like one more of the 50 aarch64-only rollout gates in this file. But ungating
    // it fires on NOTHING: `library/core` at `-Copt-level=3` is unchanged (6 failed
    // roots, the same 4 reasons, 1278 objects, 0 fixed and 0 newly broken), and so
    // are all 18 runtime programs. Shipping it would be an unexercised lowering on
    // this target, which is the one class of widening worth refusing — a wrong arm
    // here miscompiles where the compiler used to fail closed. It needs a CONSTRUCTED
    // over-aligned-pointee test of its own first; when one exists, drop the two
    // conditions and keep the rest.
    if ctx.tcx.sess.target.arch.desc() == "aarch64"
        && ctx.tcx.sess.target.os == rustc_target::spec::Os::Linux
        && is_thin_pointer_ref_ty(ctx.tcx, base_ty)
        && !ctx.borrowed_scalars.contains_key(&place.local)
        && !ctx.scalar_cells.contains_key(&place.local)
        && !ctx.memory_slots.contains_key(&place.local)
        && (ctx.scalar_values.contains_key(&place.local) || is_entry_arg(body, place.local))
        && (matches!(inner.kind(), ty::Adt(adt, _) if adt.is_struct())
            || matches!(inner.kind(), ty::Tuple(_)))
        && place.projection[1..]
            .iter()
            .all(|p| matches!(p, ProjectionElem::Field(..)))
    {
        let layout = ctx
            .tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(inner))
            .map_err(|e| format!("over-aligned reference layout: {e:?}"))?;
        let padded_leaf = (layout.align.bytes() == 16 && droppable_scalar_call_homes_enabled(ctx))
            .then(|| padded_scalar_newtype_leaf(ctx.tcx, inner))
            .flatten();
        if layout.is_sized() && (layout.align.bytes() > 16 || padded_leaf.is_some()) {
            // The padded witness validates the sole scalar and its offset-zero
            // newtype chain. The general validator instead treats a collapsed
            // newtype as a whole-value leaf and rejects its Memory ABI.
            if padded_leaf.is_none() {
                validate_memory_aggregate_field_leaves(ctx.tcx, &LayoutCx(ctx.tcx), &layout)?;
            }
            let (_, leaf) = walk_memory_projection_offset_raw(ctx, inner, &place.projection)?;
            if memory_scalar_leaf_ty(ctx.tcx, leaf).is_ok() {
                return Ok(Some(inner));
            }
        }
    }
    // A `&closure` upvar read (`(*env).N`): the closure environment is laid out
    // by rustc with ALIGNMENT-DRIVEN field reordering (a captured `u8` and `u64`
    // are NOT stored in source order). The caller built the env slot at those
    // real layout offsets (`lower_memory_aggregate_construct`), so the body MUST
    // read each upvar at the SAME layout offset. Route the read through the
    // byte-offset addressing path (`walk_memory_projection_offset` uses rustc's
    // `layout_of`), instead of the scalarized `aggregate_field_memory_access`
    // ExtractField path whose declaration-ORDER trust-ir tuple layout would read
    // the wrong offset for upvars of differing alignment.
    if matches!(inner.kind(), ty::Closure(..)) && closure_memory_layout(ctx.tcx, inner)?.is_some() {
        return Ok(Some(inner));
    }
    // A coroutine FRAME access through the resume fn's frame reference: an upvar
    // is `(*frame).k`, one of the frame's OUTER (prefix) fields, and a saved local
    // is `(*frame as variant).j`, a field of a state variant. Both live at
    // rustc's layout offsets (`lower_memory_aggregate_construct` writes the upvars
    // there), and neither is a lane of the frame's flat lane tuple
    // (`memory_enum_reference_pointee_lane_ty`), so route them through the same
    // rustc-layout walker as the closure env above.
    if matches!(inner.kind(), ty::Coroutine(..))
        && coroutine_memory_layout(ctx.tcx, inner)?.is_some()
    {
        return Ok(Some(inner));
    }
    // A `(*p).field…` read/write through a RAW pointer (`*const T`/`*mut T`) whose
    // pointee is a fixed-offset all-scalar-leaf aggregate (struct / tuple / array,
    // possibly nested). This is exactly how a `Box<Aggregate>` reads/writes its
    // payload: `Box::new` transmutes the box's `NonNull<T>` to `*const T` and reads
    // `(*p).0`/`(*p).x`. There is NO existing scalarized handler for raw-pointer
    // aggregate derefs (`aggregate_field_memory_access` only accepts `&T`), so
    // routing these through the rustc-layout-exact byte-offset path
    // (`walk_memory_projection_offset`) steals no working case and reads each leaf
    // at the SAME offset `Box::new` wrote it (rustc's `layout_of`). Tuples are
    // accepted here too (they are excluded from `memory_aggregate_layout`, but
    // their leaves are still fixed-offset scalars addressable lane-wise).
    if is_raw_ptr && raw_ptr_aggregate_pointee_addressable(ctx.tcx, inner)? {
        return Ok(Some(inner));
    }
    // A `(*p).field…` read/write/borrow through a RAW pointer OR a thin `&`/`&mut`
    // REFERENCE whose pointee is a
    // SCALAR-COLLAPSED NEWTYPE (a single-scalar struct chain: `Box<T>` ->
    // `Unique` -> `NonNull` -> pointer via the pattern-type collapse;
    // `Guard(i64)` / `N(i64)` -> `i64`). `raw_ptr_aggregate_pointee_addressable`
    // deliberately bounces these at its bare-scalar early-exit (a bare `*p` IS
    // the scalar deref path's), but a projection PAST the `Deref` still needs
    // rustc-layout byte addressing: `-O0` reads a box payload's field as
    // `(*p).0` on `*const Guard`, and `-O3` reads the inner pointer of
    // `Box<Box<T>>` as `((*p).0).0: NonNull<T>` on `*const Box<T>`. The reference
    // flavor is the same shape reached through a `&`: `*v[k]` on a
    // `Vec<Box<u64>>` reads the box's inner pointer as `((*_r).0).0: NonNull<u64>`
    // through `_r: &Box<u64>` — the slice-element reference the `-O3`-inlined
    // `<Vec as Index>::index` yields (`_r = &(*_slice)[_k]`). Both flavors load
    // the leaf scalar at the SAME rustc-layout offset; the pointer's flavor
    // (`Ref` vs `RawPtr`) does not change the byte address. Every
    // `Field` step resolves through `layout_of` offsets in
    // `walk_memory_projection_offset` (all at offset 0 for this class, computed
    // never assumed), and any element the walker cannot model exactly (a
    // mid-chain `Deref`, an index, a `Subslice`, a non-scalar or ZST leaf)
    // fails closed there — no partial modeling, no wrong address. The BINDING
    // gate mirrors the array arm below: an UNBOUND base keeps its
    // current fall-through behavior at all four caller sites (without it,
    // `lower_scalar_ref`'s existing fall-through on unbound bases would newly
    // hard-Err inside `memory_aggregate_ref_address` — a working->FC steal).
    // `base_ty` is already `Ref | RawPtr` (checked above), so no separate flavor
    // guard is needed; a NESTED/multi-field aggregate pointee is excluded by
    // `scalar_collapsed_newtype_pointee`'s single-`Scalar`-repr witness and stays
    // on the reference paths below.
    if (ctx.scalar_values.contains_key(&place.local) || is_entry_arg(body, place.local))
        && scalar_collapsed_newtype_pointee(ctx.tcx, inner)?
    {
        return Ok(Some(inner));
    }
    // A `(*r)[i].field` through a `&`/`&mut [T; N]` ARRAY reference whose element is a
    // fixed-offset all-scalar-leaf aggregate. An array is ALWAYS memory-backed at
    // rustc's real layout offsets (its storage is a single `Alloca` laid out by
    // `array_memory_layout`, and `&arr` passes that slot pointer directly — an array
    // is never materialized from scalarized fields the way a by-ref struct arg is). So
    // the bytes at the pointer are rustc-ordered, and the element/field access MUST use
    // rustc offsets too. The scalarized `aggregate_field_memory_access` path addresses
    // the element's fields through a DECLARATION-ORDER flattened trust-ir tuple, which
    // mis-stores/loads a field rustc reordered (`(u8,u64,u16)` places `.1` at offset 0,
    // not 8) — #73. Routing the access through the rustc-layout byte-offset walker
    // (`memory_aggregate_ref_address` -> `walk_memory_projection_runtime_address`)
    // fixes it; identical offsets when not reordered, so no working case is stolen.
    //
    // SCOPE: ONLY array pointees. A by-ref STRUCT/TUPLE arg of a SCALARIZED local is
    // materialized into a slot at DECLARATION order by `lower_aggregate_reference_call_arg`
    // (and reloaded the same way), so that path is internally consistent at declaration
    // order; switching only its ACCESS to rustc order would BREAK it. Struct/tuple
    // pointees therefore stay on the existing path (a reordered memory-backed struct
    // accessed by reference is a separate, pre-existing gap in the systemic
    // declaration-vs-rustc-order frontier, to fix comprehensively, not piecemeal).
    if !is_raw_ptr
        && matches!(inner.kind(), ty::Array(..))
        && (ctx.scalar_values.contains_key(&place.local) || is_entry_arg(body, place.local))
        && raw_ptr_aggregate_pointee_addressable(ctx.tcx, inner)?
    {
        return Ok(Some(inner));
    }
    // A `(*r).field…` read/write through a `&S`/`&mut S` (or `*const`/`*mut S`)
    // reference whose pointee is a scalar-leaf STRUCT, TUPLE or SINGLE-VARIANT ENUM
    // whose declaration-order trust-ir image is not rustc's layout of it
    // (`scalar_leaf_pointee_image_diverges`). Every such shape is the same defect: a
    // `repr(Rust)` REORDERING (a small field declared before a wider one, so
    // descending-alignment layout moves the wide field to offset 0), a
    // `#[repr(packed)]`/`#[repr(packed(N))]` TIGHTENING (the fields stay in
    // declaration order but carry less padding than the lane walk inserts — the
    // `drop_glue::<Pk>` miscompile recorded on
    // `scalar_leaf_aggregate_pointee_lane_offsets`), an over-aligned FIELD type
    // (`#[repr(align(16))]`) whose rustc offset the 8-aligned lane walk never
    // reaches, or a `repr(align(N))` aggregate larger and more aligned than its
    // tuple. The scalarized `aggregate_field_memory_access` path addresses a field
    // through that tuple, whose lane offsets disagree with rustc's real offsets — so
    // when the pointee's bytes are produced at rustc offsets (a by-value return into
    // a borrowed local, a `&mut`-writeback memory-backed slot, a by-value-ABI param)
    // a field is read/written at the wrong byte. (#69-class through a reference: the
    // materialized bytes and the access used different layouts.) Routing the access
    // through the rustc-layout byte-offset walker (`memory_aggregate_ref_address` ->
    // `walk_memory_projection_offset`, which resolves each field via
    // `cur_layout.fields.offset(i)`) reads/writes each field at its REAL offset.
    //
    // SCOPE: ONLY an aggregate whose image actually diverges. One whose tuple image
    // IS rustc's layout has identical offsets either way and needs no change of
    // mechanism — it stays on the existing scalarized path (zero risk, it stays
    // internally consistent). The borrowed diverging source local is additionally
    // forced memory-backed (so its bytes ARE at rustc offsets, in a slot of rustc's
    // size and alignment) by `compute_memory_backed_locals` (4b), making both the
    // materialization and the access agree on rustc layout — the comprehensive (not
    // piecemeal) fix the access-only #73 lesson demanded.
    // AGREEING lane offsets: the same admission, for the case where the two
    // addressing models are the SAME function (see
    // `lane_offset_agreeing_scalar_leaf_aggregate_pointee`). Address-neutral by
    // construction, so it cannot move a byte of an existing lowering; it only stops
    // the shape from reaching the fail-closed catch-all. `<VaListInner as Debug>::fmt`
    // is the measured instance and was the LAST `library/core` root at -O3. Opt out
    // with `-Ztrust-ir-cg-args=no-x86-agreeing-lane-pointee`.
    // SCOPED to x86-64 Linux deliberately. The arm is address-neutral by
    // construction, so it would be sound on aarch64 too — but it is a NEW arm, not
    // the widening of an existing aarch64 one, and this host cannot execute aarch64.
    // Leaving it unscoped would ship an unexercised lowering on that target, the one
    // class of widening this file's `112983` precedent refuses. Every other gate
    // opened in this campaign ADDED x86-64 beside aarch64 rather than dropping the
    // arch test; this is the same discipline for a new arm.
    if ctx.tcx.sess.target.arch.desc() == "x86_64"
        && ctx.tcx.sess.target.os == rustc_target::spec::Os::Linux
        && lane_offset_agreeing_scalar_leaf_aggregate_pointee(ctx.tcx, inner)?
        && !is_raw_ptr
        && is_thin_pointer_ref_ty(ctx.tcx, base_ty)
        && (ctx.scalar_values.contains_key(&place.local) || is_entry_arg(body, place.local))
        && place.projection[1..]
            .iter()
            .all(|p| matches!(p, ProjectionElem::Field(..)))
        && !crate::knobs::is_enabled(crate::knobs::NO_X86_AGREEING_LANE_POINTEE)
    {
        return Ok(Some(inner));
    }
    if scalar_leaf_pointee_image_diverges(ctx.tcx, inner)?
        && (ctx.scalar_values.contains_key(&place.local) || is_entry_arg(body, place.local))
    {
        return Ok(Some(inner));
    }
    // Fire only for a pointee the scalarized path cannot represent (multi-variant
    // Direct enum / nested aggregate), leaving flat scalar-leaf aggregates to it.
    if memory_aggregate_address_taken_needs_slot(ctx.tcx, inner)? {
        Ok(Some(inner))
    } else {
        Ok(None)
    }
}

/// Whether `ty` is a single-variant scalar-leaf STRUCT, non-empty TUPLE or
/// SINGLE-VARIANT ENUM whose by-reference tuple image
/// (`aggregate_reference_pointee_to_trust_ir_ty`) is NOT rustc's layout of it —
/// see [`pointee_tuple_image_diverges_from_rustc_layout`]. That covers a
/// reordered aggregate (rustc moves the wide field of `{small, wide, …}` to
/// offset 0), a `repr(packed)` / `repr(packed(N))` one (offsets below the
/// natural ones), a `repr(align(N))` one (a larger size and alignment), and a
/// univariant enum whose variant fields rustc reorders. Such an aggregate read or
/// written through the declaration-order tuple addresses each field at the wrong
/// byte, and a slot sized by the tuple is smaller or less aligned than the Rust
/// object, so it must be addressed via the rustc-layout byte walker and its
/// address-taken locals must live in a rustc-layout slot.
///
/// It is the UNION of two checks of one hazard: that image comparison (which also
/// sees the aggregate's size and alignment, and covers the univariant enum), and
/// the per-field lane-offset walk of
/// [`lane_offset_mismatched_scalar_leaf_aggregate_pointee`] (which answers for a
/// struct / tuple whose tuple image cannot be built, and counts a lane whose
/// extent it cannot state as a mismatch; its pointer lane is the session's
/// word). Either disagreeing routes the pointee.
///
/// Returns `false` for:
///   * a non-aggregate / multi-variant enum / array (handled elsewhere),
///   * an aggregate whose tuple image IS rustc's layout (the scalarized path is
///     already exact — no change),
///   * any aggregate with a non-scalar / wide / niche leaf, or no computable
///     layout — those keep their existing (fail-closed) handling; every
///     declaration-order tuple access or materialization of a pointee whose image
///     diverges is refused by name (`[TCG-TUPLE-IMAGE-LAYOUT]`).
fn scalar_leaf_pointee_image_diverges<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    use rustc_abi::Variants;
    let is_struct = matches!(ty.kind(), ty::Adt(adt, _) if adt.is_struct());
    let is_tuple = matches!(ty.kind(), ty::Tuple(fields) if !fields.is_empty());
    let is_univariant_enum =
        matches!(ty.kind(), ty::Adt(adt, _) if adt.is_enum() && adt.variants().len() == 1);
    if !is_struct && !is_tuple && !is_univariant_enum {
        return Ok(false);
    }
    let cx = LayoutCx(tcx);
    let ty_and_layout = match tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
    {
        Ok(l) => l,
        Err(_) => return Ok(false),
    };
    if !ty_and_layout.is_sized() || ty_and_layout.size.bytes() == 0 {
        return Ok(false);
    }
    if !matches!(ty_and_layout.layout.variants(), Variants::Single { .. }) {
        return Ok(false);
    }
    let variant = ty_and_layout.for_variant(&cx, rustc_abi::FIRST_VARIANT);
    // Every field must be a fixed-offset memory SCALAR leaf (so the byte walker can
    // address it with one typed load/store); a nested-aggregate / wide / niche leaf
    // is NOT this surface — keep it on the existing path.
    let field_count = variant.fields.count();
    if field_count == 0 {
        return Ok(false);
    }
    for i in 0..field_count {
        let field_layout = variant.field(&cx, i);
        if is_zero_sized_ty(tcx, field_layout.ty) {
            continue;
        }
        if memory_scalar_leaf_ty(tcx, field_layout.ty).is_err() {
            return Ok(false);
        }
    }
    // The lane-offset walk models a pointer lane at the session's word
    // (`trust_ir_lane_natural_extent`), so it answers for wasm32 too; asking it
    // here keeps this routing predicate and the `[TCG-LANE-OFFSET-MISMATCH]`
    // tripwire (the same walk) in agreement on every target.
    Ok(pointee_tuple_image_diverges_from_rustc_layout(tcx, ty)
        || lane_offset_mismatched_scalar_leaf_aggregate_pointee(tcx, ty)?)
}

/// The `(bytes, align)` a single trust-ir SCALAR LANE occupies in the EMITTED
/// declaration-order aggregate image, mirroring `trust_cg_lower::types::Type`'s
/// `bytes()` / `align()` exactly (and the wasm32 lane's layout, whose word is 4
/// bytes): a pointer lane is one session pointer word, a 128-bit
/// scalar is 16-byte aligned (rustc's `align_of::<u128>()` on every triple
/// trust-cg emits for), and every other scalar is aligned to its own width
/// (`bytes().min(8)`).
///
/// `None` only for a lane whose width this backend cannot state at all — which
/// `memory_scalar_leaf_ty`'s admission (`bit_width().is_some()` or pointer-like)
/// already excludes, so it is unreachable from the one caller below. It is still
/// reported as a lane-offset MISMATCH there rather than as agreement: the byte
/// walker addresses from rustc's own layout and cannot be wrong, while the lane
/// path would be addressing from a width nobody computed.
fn trust_ir_lane_natural_extent(ty: &TrustIrTy) -> Option<(u64, u64)> {
    // The session's pointer word (8 bytes natively, 4 on wasm32, whose lane lays
    // a pointer and `usize` out at that width).
    let word = session_pointer_bytes();
    if is_pointer_like_trust_ir_ty(ty) {
        return Some((word, word));
    }
    let bits = ty.bit_width_with(u32::try_from(word * 8).ok()?)?;
    let bytes = u64::from(bits.div_ceil(8)).max(1);
    let align = if bytes >= 16 { 16 } else { bytes };
    Some((bytes, align))
}

/// The byte offsets the EMITTED declaration-order trust-ir tuple places `field_tys`
/// at — i.e. the natural-C packing `trust_cg_lower::types::Type::offset_of` performs,
/// and therefore the EXACT bytes an `ExtractField` on that tuple, or a field store
/// through `emit_aggregate_field_store` (which resolves the same `offset_of`),
/// addresses. Computed from `trust_ir_lane_natural_extent`, which mirrors that
/// crate's `bytes()` / `align()` lane for lane.
///
/// `None` — so the caller compares nothing and changes nothing — when the field
/// indices are not the positional `0..n` this packing assumes, or when a lane's
/// extent is unstatable.
fn trust_ir_tuple_lane_offsets(field_tys: &[(u32, TrustIrTy)]) -> Option<Vec<u64>> {
    let mut offsets = Vec::with_capacity(field_tys.len());
    let mut offset: u64 = 0;
    for (index, (field, field_ty)) in field_tys.iter().enumerate() {
        // `aggregate_memory_field_tys` always enumerates `0..n` in order; a caller
        // that ever hands over a permuted or sparse list would make the positional
        // packing below address the wrong lane, so it is CHECKED, not assumed.
        if u64::from(*field) != index as u64 {
            return None;
        }
        let (bytes, align) = trust_ir_lane_natural_extent(field_ty)?;
        if align > 1 && !offset.is_multiple_of(align) {
            offset += align - (offset % align);
        }
        offsets.push(offset);
        offset += bytes;
    }
    Some(offsets)
}

/// The RUSTC layout byte offset of each of `field_tys`, when `field_tys` IS
/// `pointee_ty`'s flattened scalar-leaf typing — type for type, leaf for leaf.
///
/// `None` when it is not that typing (a uniform lane TILING, a multi-variant enum,
/// or any leaf/count disagreement), in which case the caller has no authority to
/// address by layout offsets and must not.
///
/// # One walker, and why the identity check reads its types rather than a second list
///
/// `enumerate_scalar_leaf_offsets` is the walker that owns this question: it descends
/// declaration-order, skips ZSTs, recurses into nested aggregates, and reads every
/// leaf's byte off rustc's authoritative layout. It also returns each leaf's TRUST-IR
/// TYPE, so the correspondence to the slot's trust-ir fields is established from that
/// same walk — no second flattener to drift against.
///
/// (c) MEASURED: asking `scalar_field_aggregate_trust_ir_fields` for the leaf list
/// instead was a HOLE. It answers `None` for an ARRAY (arrays are not
/// `scalar_field_aggregate` types), so `*p = [Pk { .. }, Pk { .. }]` through
/// `&mut [Pk; 2]` with a `#[repr(packed)] Pk` fell straight past this check and was
/// stored at the lane offsets `0/8/16/24` while rustc's are `0/1/9/10` — silently
/// wrong on the pre-repair backend, the repaired one, and the first version of this
/// fix. `enumerate_scalar_leaf_offsets` walks an array's own `FieldsShape::Array`
/// (`offset(i) == i * stride`) and therefore covers it.
fn flattened_leaf_layout_offsets<'tcx>(
    tcx: TyCtxt<'tcx>,
    pointee_ty: Ty<'tcx>,
    field_tys: &[(u32, TrustIrTy)],
) -> Result<Option<Vec<u64>>, String> {
    let cx = LayoutCx(tcx);
    let base = match tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(pointee_ty))
    {
        Ok(base) => base,
        Err(_) => return Ok(None),
    };
    let mut leaf_offsets: Vec<(u64, TrustIrTy)> = Vec::new();
    if enumerate_scalar_leaf_offsets(tcx, &cx, &base, 0, &mut leaf_offsets)?.is_none()
        || leaf_offsets.len() != field_tys.len()
        || !leaf_offsets
            .iter()
            .zip(field_tys.iter())
            .all(|((_, leaf), (_, slot))| leaf == slot)
        // The returned table is POSITIONAL, and the caller indexes it by trust-ir
        // FIELD NUMBER. `aggregate_memory_field_tys` always enumerates `0..n` in
        // order, so the two coincide — checked here rather than assumed, because a
        // permuted or sparse list would hand every field another field's offset.
        || field_tys
            .iter()
            .enumerate()
            .any(|(index, (field, _))| u64::from(*field) != index as u64)
    {
        return Ok(None);
    }
    Ok(Some(
        leaf_offsets.into_iter().map(|(offset, _)| offset).collect(),
    ))
}

/// The premise of `lower_aggregate_memory_store`'s LANE-TILING copy
/// (`(*r) = move src` from a memory-backed `src` whose slot is not its flattened
/// leaves), checked rather than assumed: `field_tys` are ONE lane type, numbered
/// `0..n` in order, the emitted tuple places lane `k` at `k * lane_bytes` (so the
/// `InsertField` write lands where the offset load read), and `n * lane_bytes` is
/// rustc's size of BOTH `src_ty` and `dest_ty`. Then the lane-by-lane loop is a
/// byte copy of one whole rustc image into another, and it is correct for ANY
/// contents — which is what lets a source the scalar-leaf flattener refuses (a
/// wide `NonNull<dyn Trait>` / `NonNull<[T]>` / `&dyn` leaf) take it.
///
/// `Err` (named) when any of that fails: a tiling shorter than the object would
/// copy a PREFIX of it, a longer one would write past the destination's end, and a
/// mixed or permuted list would read one lane's bytes into another. An empty list
/// is the zero-sized object and is accepted only when both sizes are zero.
fn image_copy_lane_tiling_covers<'tcx>(
    tcx: TyCtxt<'tcx>,
    src_ty: Ty<'tcx>,
    dest_ty: Ty<'tcx>,
    field_tys: &[(u32, TrustIrTy)],
) -> Result<(), String> {
    let size_of = |ty: Ty<'tcx>| -> Result<u64, String> {
        let layout = tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
            .map_err(|e| {
                format!("aggregate deref store lane tiling: layout_of `{ty:?}` failed: {e:?}")
            })?;
        if !layout.is_sized() {
            return Err(format!(
                "aggregate deref store lane tiling: `{ty:?}` is unsized; a whole-image copy \
                 has no size to tile"
            ));
        }
        Ok(layout.size.bytes())
    };
    let src_size = size_of(src_ty)?;
    let dest_size = size_of(dest_ty)?;
    let refuse = |why: String| -> Result<(), String> {
        Err(format!(
            "aggregate deref store source `{src_ty:?}` ({src_size} bytes) into `{dest_ty:?}` \
             ({dest_size} bytes) is addressed as a UNIFORM LANE tiling, but {why}; refusing \
             rather than copying part of the object or writing past its end. Fix options: \
             (a) give the pointee its flattened-scalar-leaf typing so the copy addresses each \
             leaf at its rustc offset, (b) type the slot as `memory_aggregate_layout`'s whole \
             lane tuple, or (c) leave the shape refused."
        ))
    };
    let Some(((_, lane), _)) = field_tys.split_first() else {
        return if src_size == 0 && dest_size == 0 {
            Ok(())
        } else {
            refuse("the tiling has no lanes".to_owned())
        };
    };
    let Some(lane_bytes) = trust_ir_leaf_byte_size(lane) else {
        return refuse(format!("lane `{lane:?}` has no byte size"));
    };
    let mut expected_offsets = Vec::with_capacity(field_tys.len());
    for (index, (field, ty)) in field_tys.iter().enumerate() {
        if u64::from(*field) != index as u64 || ty != lane {
            return refuse(format!(
                "lane {index} is field {field} of type `{ty:?}`, not lane {index} of `{lane:?}`"
            ));
        }
        expected_offsets.push(index as u64 * lane_bytes);
    }
    if trust_ir_tuple_lane_offsets(field_tys).as_ref() != Some(&expected_offsets) {
        return refuse(format!(
            "the emitted tuple does not place its `{lane:?}` lanes at `k * {lane_bytes}`"
        ));
    }
    let covered = field_tys.len() as u64 * lane_bytes;
    if covered != src_size || covered != dest_size {
        return refuse(format!(
            "{} lanes of {lane_bytes} bytes tile {covered} bytes",
            field_tys.len()
        ));
    }
    Ok(())
}

/// Whether `ty` INLINE-CONTAINS — at any depth, and never through a pointer — an
/// aggregate whose rustc field offsets disagree with the declaration-order trust-ir
/// lane packing. Inline means: a struct / tuple / union FIELD, an enum VARIANT's field,
/// or an ARRAY ELEMENT — the things whose bytes are part of THIS object, and therefore
/// part of what a whole-pointee store writes. A reference / raw-pointer / `Box` field is
/// a different object with its own store, so the walk stops there.
///
/// This exists ONLY as the trigger for the fail-closed arm of
/// `whole_pointee_store_layout_offsets`, and it is recursive for a measured reason:
/// keying that arm on `lane_offset_mismatched_scalar_leaf_aggregate_pointee` ALONE made
/// the refusal itself one-sided — that predicate answers `false` for an ARRAY (it admits
/// only a struct or non-empty tuple), so `&mut [Pk; 2]` with a `#[repr(packed)] Pk` had
/// neither an exact path nor a refusal. Proved by mutation: with the exact path forced
/// off, `*p = [Pk { .. }, Pk { .. }]` was still SILENTLY WRONG while every struct shape
/// refused by name. A guard that covers one shape of a hazard is the defect this whole
/// change is about.
///
/// Exceeding `depth` answers `true` (refuse): a walk this deep is not a shape anything
/// in-tree has, and guessing "no mismatch" about a type we declined to finish reading is
/// exactly the inference that produced the original bug.
fn inline_contains_lane_offset_mismatched_aggregate<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    depth: u32,
) -> Result<bool, String> {
    if depth == 0 {
        return Ok(true);
    }
    if lane_offset_mismatched_scalar_leaf_aggregate_pointee(tcx, ty)? {
        return Ok(true);
    }
    match ty.kind() {
        ty::Adt(adt, args) => {
            for variant in adt.variants() {
                for field in &variant.fields {
                    let field_ty = tcx.normalize_erasing_regions(
                        ty::TypingEnv::fully_monomorphized(),
                        field.ty(tcx, *args),
                    );
                    if inline_contains_lane_offset_mismatched_aggregate(tcx, field_ty, depth - 1)? {
                        return Ok(true);
                    }
                }
            }
            Ok(false)
        }
        ty::Tuple(fields) => {
            for field_ty in fields.iter() {
                if inline_contains_lane_offset_mismatched_aggregate(tcx, field_ty, depth - 1)? {
                    return Ok(true);
                }
            }
            Ok(false)
        }
        ty::Array(elem, _) | ty::Slice(elem) => {
            inline_contains_lane_offset_mismatched_aggregate(tcx, *elem, depth - 1)
        }
        _ => Ok(false),
    }
}

/// How a WHOLE-POINTEE store `*r = P { .. }` must address the destination's trust-ir
/// fields.
///
/// # The two-way hazard this closes
///
/// `lane_offset_mismatched_scalar_leaf_aggregate_pointee` routes `(*r).field` READS
/// and FIELD-STORES of a layout-mismatched pointee to the rustc-exact byte walker.
/// The whole-pointee STORE is the OTHER direction of the same hazard and neither of
/// those guards can see it: the routing bails out on `place.projection.len() < 2` and
/// a whole-pointee store's projection is a bare `[Deref]`, and the
/// `[TCG-LANE-OFFSET-MISMATCH]` tripwire sits after `aggregate_deref_field_index`,
/// which answers `None` for a bare `[Deref]`. Left alone, a `#[repr(packed)]` pointee
/// was WRITTEN at the declaration-order lane offsets (`m@0 / a@8 / b@16`) and READ at
/// rustc's (`m@0 / a@1 / b@9`) — the last field landing OUT OF BOUNDS of the 13-byte
/// object, silently, with no diagnostic.
///
/// The answer is the same one the read path now gives: address by rustc's own layout.
/// `lower_memory_aggregate_construct` already materializes every memory-backed
/// aggregate at `variant_layout.fields.offset(i)`, and the memory-backed-SOURCE arm of
/// this same function already copies leaf by leaf at those offsets, so storing here at
/// the flattened-leaf layout offsets makes materialization, read, field-store and
/// whole-store all agree on ONE layout — rustc's.
///
/// Returns:
///   * `Ok(Some(offsets))` — the destination's layout DISAGREES with the lane packing;
///     store each field at `offsets[field]` with a typed store (`Exact`).
///   * `Ok(None)` — the two agree (the overwhelming majority, `repr(C)` included), so
///     the existing lane-offset field store (`emit_aggregate_field_store`) is already
///     addressing the right bytes and
///     is left untouched. Changing a correct mechanism buys nothing and risks
///     something.
/// and REFUSES by name when the pointee is KNOWN to disagree but cannot be addressed
/// exactly — never silently storing at the lane offsets anyway.
fn whole_pointee_store_layout_offsets<'tcx>(
    tcx: TyCtxt<'tcx>,
    pointee_ty: Ty<'tcx>,
    field_tys: &[(u32, TrustIrTy)],
) -> Result<Option<Vec<u64>>, String> {
    if let Some(layout_offsets) = flattened_leaf_layout_offsets(tcx, pointee_ty, field_tys)? {
        // Exact rustc offsets are available and are correct by construction. Decline
        // them ONLY when they are PROVABLY the same bytes the untouched lane-offset
        // field store already addresses — an unprovable case (`trust_ir_tuple_lane_offsets`
        // declining) takes the exact path, because "we could not compute the lane
        // offsets" is not evidence that they agree.
        if trust_ir_tuple_lane_offsets(field_tys).as_ref() == Some(&layout_offsets) {
            return Ok(None);
        }
        return Ok(Some(layout_offsets));
    }
    // Not the flattened-leaf typing (or a lane whose extent is unstatable): there is
    // no per-field layout offset to store at. That is fine for a genuine uniform lane
    // TILING, whose lanes ARE the object's bytes in order — but NOT if this pointee is
    // one the read path has already ruled layout-mismatched, because then the lane
    // offsets this store would use are known to be the wrong bytes. Refuse.
    if inline_contains_lane_offset_mismatched_aggregate(tcx, pointee_ty, 12)? {
        return Err(format!(
            "[TCG-LANE-OFFSET-MISMATCH] whole-pointee store `*r = ..` through \
             `&mut {pointee_ty:?}`: rustc's field offsets for this pointee DISAGREE \
             with the declaration-order trust-ir lane offsets a lane-offset field store \
             addresses with (a `#[repr(packed)]`/`#[repr(packed(N))]` tightening, an \
             over-aligned field, or a reordering), and its trust-ir typing here is NOT \
             this type's flattened scalar leaves, so there is no per-field layout \
             offset to store at instead — refusing rather than writing the wrong \
             bytes (the `(*r).field` READ of the same pointee is already routed \
             through the rustc-layout byte walker, so a lane-offset store would be \
             read back from different bytes). Fix options: (a) give this pointee its \
             flattened-scalar-leaf trust-ir typing so the store can address each leaf \
             at `enumerate_scalar_leaf_offsets`' rustc offset, (b) memory-back the \
             source local so the store takes the byte-copy arm above, or (c) leave \
             the shape refused."
        ));
    }
    Ok(None)
}

/// Whether `ty` is a single-variant scalar-leaf STRUCT or non-empty TUPLE whose
/// rustc field offsets DISAGREE, at any field, with the byte offsets the emitted
/// DECLARATION-ORDER trust-ir tuple would place those lanes at. Such an aggregate
/// read or written through a reference via the scalarized `ExtractField` /
/// field-store path addresses at least one field at the wrong byte whenever the
/// pointee's bytes are in rustc order, so it must be addressed via the
/// rustc-layout byte walker instead.
///
/// # This predicate used to ask about ORDER, and `#[repr(packed)]` walked past it
///
/// It used to answer "did rustc REORDER the fields", implemented as "is the
/// offset-by-declaration-index sequence non-ascending", on the stated premise that
/// *"rustc lays out a non-`repr(C)`/`repr(packed)` aggregate in descending-alignment
/// order"* — i.e. that an ASCENDING sequence proves the declaration-order lane
/// layout agrees. It does not. A `#[repr(packed)]` / `#[repr(C, packed)]` /
/// `#[repr(packed(N))]` struct is declaration-ORDERED and therefore ascending, while
/// its offsets are TIGHTER than the natural-alignment packing the emitted tuple
/// uses. (c) MEASURED on this tree: for `#[repr(packed)] struct Pk { m: u8, a: A }`
/// (`A` = `struct A { n: u64 }` with a user `Drop`) rustc puts `a` at byte **1** and
/// the emitted `Tuple([I8, I64])` puts lane 1 at byte **8** — the shipped
/// `drop_glue::<Pk>` read `add x1, x0, #0x8; ldr x0, [x1]`, eight bytes past the
/// field, and ran the destructor on garbage. The same premise also missed an
/// ASCENDING-but-looser disagreement: a `#[repr(C)]`-ordered struct holding a field
/// whose OWN type is over-aligned (`#[repr(align(16))]`) sits at a rustc offset the
/// 8-aligned lane walk never reaches.
///
/// So the question is not about order at all — it is whether the two layouts put
/// every field at the same byte, and that is now COMPUTED (rustc's
/// `variant.fields.offset(i)` against the lane walk) rather than inferred from a
/// shape. The order test is strictly subsumed: a non-ascending sequence cannot equal
/// the strictly-ascending lane walk, so every aggregate the old predicate routed is
/// still routed.
///
/// Returns `false` for:
///   * a non-aggregate / multi-variant enum / array / union (handled elsewhere),
///   * an aggregate whose every field offset DOES equal its lane offset (`repr(C)`,
///     and the majority of `repr(Rust)` structs) — the scalarized path is already
///     addressing those correctly, so they stay on it untouched,
///   * any aggregate with a non-scalar / wide / niche leaf, or no computable layout
///     — those keep their existing (fail-closed) handling.
/// How a struct/tuple pointee's DECLARATION-ORDER trust-ir lane offsets relate to
/// rustc's own field offsets. Three genuinely different answers, which the older
/// `bool` spelling collapsed: `None` means "not this surface at all" (not a
/// struct/tuple, unsized, ZST, multi-variant, field-less, or some field is not a
/// memory scalar leaf), and `Some(true)`/`Some(false)` mean the surface DOES apply
/// and its lane offsets disagree / agree with rustc's.
///
/// The distinction is load-bearing. `Some(false)` — every field a scalar leaf and
/// EVERY lane offset equal to rustc's — is the case where the two addressing models
/// are the same function, so routing such a pointee through the rustc-layout byte
/// walker cannot move any address. That is what makes the AGREEING admission below
/// safe, and it is exactly what a `bool` could not express, because `false` meant
/// both "agrees" and "not this surface".
fn scalar_leaf_aggregate_pointee_lane_offsets<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<Option<bool>, String> {
    use rustc_abi::Variants;
    let is_struct = matches!(ty.kind(), ty::Adt(adt, _) if adt.is_struct());
    let is_tuple = matches!(ty.kind(), ty::Tuple(fields) if !fields.is_empty());
    let is_univariant_enum =
        matches!(ty.kind(), ty::Adt(adt, _) if adt.is_enum() && adt.variants().len() == 1);
    if !is_struct && !is_tuple && !is_univariant_enum {
        return Ok(None);
    }
    let cx = LayoutCx(tcx);
    let ty_and_layout = match tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
    {
        Ok(l) => l,
        Err(_) => return Ok(None),
    };
    if !ty_and_layout.is_sized() || ty_and_layout.size.bytes() == 0 {
        return Ok(None);
    }
    if !matches!(ty_and_layout.layout.variants(), Variants::Single { .. }) {
        return Ok(None);
    }
    let variant = ty_and_layout.for_variant(&cx, rustc_abi::FIRST_VARIANT);
    // Every field must be a fixed-offset memory SCALAR leaf (so the byte walker can
    // address it with one typed load/store); a nested-aggregate / wide / niche leaf
    // is NOT this surface — keep it on the existing path.
    let field_count = variant.fields.count();
    if field_count == 0 {
        return Ok(None);
    }
    // Walk the NON-ZST fields in declaration order, packing each lane the way
    // `trust_cg_lower::types::Type::offset_of` packs the emitted tuple, and compare
    // every lane's byte with rustc's own offset for that field.
    let mut lane_offset: u64 = 0;
    let mut saw_field = false;
    let mut mismatched = false;
    for i in 0..field_count {
        let field_layout = variant.field(&cx, i);
        if is_zero_sized_ty(tcx, field_layout.ty) {
            // A ZST field occupies no bytes and is dropped from BOTH the rustc-offset
            // walk (offset 0, never read) and the declaration-order tuple
            // (`scalar_field_aggregate_trust_ir_fields` skips it), so it takes part in
            // neither side of the comparison — skip it.
            continue;
        }
        let Ok(leaf) = memory_scalar_leaf_ty(tcx, field_layout.ty) else {
            return Ok(None);
        };
        let Some((lane_bytes, lane_align)) = trust_ir_lane_natural_extent(&leaf) else {
            // A lane with no natural extent cannot be compared, so it is treated as a
            // MISMATCH (conservative: it keeps the agreeing admission from claiming a
            // lane it could not verify).
            return Ok(Some(true));
        };
        if lane_align > 1 && !lane_offset.is_multiple_of(lane_align) {
            lane_offset += lane_align - (lane_offset % lane_align);
        }
        if variant.fields.offset(i).bytes() != lane_offset {
            mismatched = true;
        }
        lane_offset += lane_bytes;
        saw_field = true;
    }
    if !saw_field {
        return Ok(None);
    }
    // The lane walk compares field OFFSETS only. The by-reference tuple image must
    // also BE rustc's layout — every scalar leaf at rustc's byte with rustc's size,
    // and the same total size and ABI alignment
    // (`pointee_tuple_image_diverges_from_rustc_layout`). That second check also
    // catches a `repr(align(N))` aggregate whose field offsets all agree but whose
    // slot the tuple would under-size or under-align, so agreement (`Some(false)`)
    // is claimed only when neither comparison finds a difference.
    Ok(Some(
        mismatched || pointee_tuple_image_diverges_from_rustc_layout(tcx, ty),
    ))
}

/// The original question, preserved for its existing caller: does this pointee's
/// declaration-order lane layout DISAGREE with rustc's field offsets?
fn lane_offset_mismatched_scalar_leaf_aggregate_pointee<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    Ok(scalar_leaf_aggregate_pointee_lane_offsets(tcx, ty)? == Some(true))
}

/// The complement: an all-scalar-leaf struct/tuple pointee whose declaration-order
/// lane offsets AGREE with rustc's at every field.
///
/// Admitting this surface is address-NEUTRAL by construction. The concern recorded
/// against widening this family is the systemic declaration-order-versus-rustc-order
/// frontier — "switching only its ACCESS to rustc order would BREAK it" for a slot
/// that was BUILT at declaration order. That hazard requires the two orders to
/// differ. Here they are equal at every field, so the byte walker and the
/// declaration-order lane model compute the SAME address, and there is no order to
/// switch. It is therefore not the piecemeal fix that warning forbids.
///
/// Measured instance: `<VaListInner as Debug>::fmt`, the LAST `library/core` root at
/// `-Copt-level=3`. It takes `&(*_1).3` where `_1: &VaListInner` is an entry
/// argument and `VaListInner` is `#[repr(C)]` — hence agreeing offsets — and the
/// refusal's classification bits read `pointee is memory-eligible; base thin=true
/// entry_arg=true scalar_value=false`.
fn lane_offset_agreeing_scalar_leaf_aggregate_pointee<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    Ok(scalar_leaf_aggregate_pointee_lane_offsets(tcx, ty)? == Some(false))
}

/// Whether a WHOLE-value store `*p = v` through a thin pointer to `pointee` must
/// be written at rustc's layout offsets instead of through the pointee's
/// by-reference trust-ir type (`reference_pointee_to_trust_ir_ty`).
///
/// That type is a declaration-order tuple image or, for a pointee the flat
/// image cannot represent (an array or nested-aggregate field, a zero-sized
/// field before a sized one), the uniform lane shell of its memory slot. A
/// write-through `InsertField` over it addresses field `k` at the C-rule offset
/// of tuple field `k`, or at `k * lane` in a shell — rustc's offset only when
/// the image is a tuple that matches rustc's layout leaf for leaf
/// ([`tuple_image_matches_rustc_layout`]). Every other image of a sized,
/// non-zero-sized struct, non-empty tuple, single-variant enum or array of
/// aggregates answers `true`. An array of scalar leaves (its elements sit at
/// `k * size` in any image), a scalar image (a newtype over one scalar), a
/// multi-variant enum, a transparent wide-slice newtype, and a pointee with no
/// by-reference type answer `false` and keep their own paths.
fn whole_deref_store_needs_rustc_layout<'tcx>(tcx: TyCtxt<'tcx>, pointee: Ty<'tcx>) -> bool {
    let admitted_kind = match pointee.kind() {
        ty::Adt(adt, _) => adt.is_struct() || (adt.is_enum() && adt.variants().len() == 1),
        ty::Tuple(fields) => !fields.is_empty(),
        ty::Array(element, _) => memory_scalar_leaf_ty(tcx, *element).is_err(),
        _ => false,
    };
    if !admitted_kind || wide_slice_carrier_layout(tcx, pointee).is_some() {
        return false;
    }
    match tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(pointee)) {
        Ok(layout)
            if layout.is_sized()
                && layout.size.bytes() > 0
                && matches!(layout.variants, rustc_abi::Variants::Single { .. }) => {}
        _ => return false,
    }
    let Ok(image) = reference_pointee_to_trust_ir_ty(tcx, pointee) else {
        return false;
    };
    if image.bit_width().is_some()
        || is_pointer_like_trust_ir_ty(&image)
        || aggregate_memory_field_tys(&image).is_err()
    {
        return false;
    }
    !(matches!(image, TrustIrTy::Tuple(_))
        && tuple_image_matches_rustc_layout(tcx, pointee, &image))
}

/// Whether `ty` is a single-variant enum whose rustc layout carries a tag
/// (`Variants::Multiple` — a `#[repr(C)]` / `#[repr(uN)]` enum with one
/// variant). Such an enum has no tuple image: its bytes are the tag followed by
/// the variant's fields at rustc offsets, so it is handled as a memory enum
/// (like a multi-variant one), never as a flat field tuple.
fn is_tagged_univariant_enum<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    if !matches!(ty.kind(), ty::Adt(adt, _) if adt.is_enum() && adt.variants().len() == 1) {
        return false;
    }
    matches!(
        tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty)),
        Ok(layout) if matches!(layout.layout.variants(), rustc_abi::Variants::Multiple { .. })
    )
}

/// Whether the undeclared trust-ir tuple image the bridge gives the by-reference
/// pointee `ty` (`aggregate_reference_pointee_to_trust_ir_ty`) differs from
/// rustc's layout of `ty`. `false` when there is no tuple image.
///
/// An undeclared tuple is laid out by the C rule (declaration order, natural
/// alignment) by the trust-ir interpreter and by every backend lane, so the image
/// is exact only when rustc places every scalar leaf at the C-rule offset and the
/// size and ABI alignment agree ([`tuple_image_matches_rustc_layout`]).
fn pointee_tuple_image_diverges_from_rustc_layout<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>) -> bool {
    match aggregate_reference_pointee_to_trust_ir_ty(tcx, ty) {
        Ok(Some(image)) => !tuple_image_matches_rustc_layout(tcx, ty, &image),
        Ok(None) | Err(_) => false,
    }
}

/// The refusal for a declaration-order tuple access or materialization of a
/// pointee whose tuple image is not rustc's layout.
fn tuple_image_layout_refusal(what: &str, ty: Ty<'_>) -> String {
    format!(
        "[TCG-TUPLE-IMAGE-LAYOUT] {what} `{ty:?}` through its declaration-order tuple image, \
         but rustc lays `{ty:?}` out differently (reordered, packed or over-aligned fields); \
         that access would read or write the wrong bytes, so failing closed. Options: (1) \
         declare the fields in rustc's order or use `#[repr(C)]`, without `packed`/`align`, \
         (2) pass the value by value, (3) compile this crate with the LLVM backend"
    )
}

/// Whether rustc lays `ty` out exactly as the undeclared trust-ir tuple `image`:
/// every scalar leaf at the same byte offset with the same size, and the same
/// total size and ABI alignment. Any shape either side cannot enumerate answers
/// `false`.
fn tuple_image_matches_rustc_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
    image: &TrustIrTy,
) -> bool {
    let Ok(layout) = tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty)) else {
        return false;
    };
    if !layout.is_sized() {
        return false;
    }
    let mut image_leaves = Vec::new();
    let Some((image_size, image_align)) = c_rule_image_leaves(image, 0, &mut image_leaves) else {
        return false;
    };
    let mut rustc_leaves = Vec::new();
    if rustc_scalar_leaf_image(&LayoutCx(tcx), layout, 0, &mut rustc_leaves).is_none() {
        return false;
    }
    layout.size.bytes() == image_size
        && layout.align.bytes() == image_align
        && rustc_leaves == image_leaves
}

/// The C-rule byte offset of each field of the undeclared trust-ir tuple `ty`
/// (see [`c_rule_image_leaves`]); `None` for a non-tuple or a field whose size
/// and alignment the C rule cannot state.
fn c_rule_tuple_field_offsets(ty: &TrustIrTy) -> Option<Vec<u64>> {
    let TrustIrTy::Tuple(fields) = ty else {
        return None;
    };
    let mut cursor = 0u64;
    let mut offsets = Vec::with_capacity(fields.len());
    for field in fields {
        let mut leaves = Vec::new();
        let (size, align) = c_rule_image_leaves(field, 0, &mut leaves)?;
        cursor = cursor.checked_next_multiple_of(align)?;
        offsets.push(cursor);
        cursor = cursor.checked_add(size)?;
    }
    Some(offsets)
}

/// The `(offset, size)` of every scalar leaf of the trust-ir type `ty` placed at
/// `base` by the C rule an undeclared tuple gets — fields in declaration order,
/// each at the next multiple of its own alignment, the whole padded to its
/// largest alignment — and the type's `(size, align)`. A scalar or thin pointer
/// is aligned to its size: that is the scalar table of every target the bridge
/// emits for (`Module::target_has_canonical_scalar_layout`: `x86_64`, `aarch64`,
/// `wasm32`, with `i128` at 16). `None` for anything else (an array spelled by a
/// module type id, a fat pointer).
fn c_rule_image_leaves(
    ty: &TrustIrTy,
    base: u64,
    leaves: &mut Vec<(u64, u64)>,
) -> Option<(u64, u64)> {
    match ty {
        TrustIrTy::Unit => Some((0, 1)),
        TrustIrTy::Tuple(fields) => {
            let mut cursor = 0u64;
            let mut align = 1u64;
            for field in fields {
                let mut field_leaves = Vec::new();
                let (size, field_align) = c_rule_image_leaves(field, 0, &mut field_leaves)?;
                cursor = cursor.checked_next_multiple_of(field_align)?;
                for (offset, leaf_size) in field_leaves {
                    leaves.push((base.checked_add(cursor)?.checked_add(offset)?, leaf_size));
                }
                cursor = cursor.checked_add(size)?;
                align = align.max(field_align);
            }
            Some((cursor.checked_next_multiple_of(align)?, align))
        }
        _ => {
            let size = trust_ir_leaf_byte_size(ty).filter(|size| size.is_power_of_two())?;
            leaves.push((base, size));
            Some((size, size))
        }
    }
}

/// The `(offset, size)` of every scalar leaf of the rustc layout `layout` placed
/// at `base`, in declaration (field-index) order, skipping zero-sized fields. A
/// `Scalar`-ABI layout is one leaf; a single-variant aggregate descends through
/// its fields at rustc's own offsets and an array through its elements at the
/// stride. `None` for a union, a multi-variant enum, or a primitive without a
/// scalar ABI.
fn rustc_scalar_leaf_image<'tcx>(
    cx: &LayoutCx<'tcx>,
    layout: rustc_middle::ty::layout::TyAndLayout<'tcx>,
    base: u64,
    leaves: &mut Vec<(u64, u64)>,
) -> Option<()> {
    use rustc_abi::{BackendRepr, FieldsShape, Variants};
    if layout.is_zst() {
        return Some(());
    }
    if matches!(layout.backend_repr, BackendRepr::Scalar(_)) {
        leaves.push((base, layout.size.bytes()));
        return Some(());
    }
    if !matches!(layout.variants, Variants::Single { .. }) {
        return None;
    }
    match &layout.fields {
        FieldsShape::Primitive | FieldsShape::Union(_) => None,
        FieldsShape::Array { stride, count } => {
            if *count == 0 {
                return Some(());
            }
            let element = layout.field(cx, 0);
            for index in 0..*count {
                let offset = stride.bytes().checked_mul(index)?;
                rustc_scalar_leaf_image(cx, element, base.checked_add(offset)?, leaves)?;
            }
            Some(())
        }
        FieldsShape::Arbitrary { .. } => {
            for index in 0..layout.fields.count() {
                let offset = layout.fields.offset(index).bytes();
                rustc_scalar_leaf_image(
                    cx,
                    layout.field(cx, index),
                    base.checked_add(offset)?,
                    leaves,
                )?;
            }
            Some(())
        }
    }
}

/// Whether a raw-pointer pointee `ty` is a fixed-offset aggregate (struct / tuple
/// / array) whose every leaf bottoms out at a memory scalar at a fixed layout
/// offset, so a `(*p).field…` deref can be addressed by accumulated rustc-layout
/// byte offsets and read/written with single typed accesses. Returns `false` for
/// a bare scalar pointee (handled by the scalar deref-load path), a `Vec` pointee
/// (its value is a single `Ptr`), a non-aggregate, or any aggregate with a
/// non-scalar / wide / niche-enum leaf (validation fails -> not addressable).
fn raw_ptr_aggregate_pointee_addressable<'tcx>(
    tcx: TyCtxt<'tcx>,
    ty: Ty<'tcx>,
) -> Result<bool, String> {
    // A bare scalar pointee keeps the scalar deref-load/store path.
    if memory_scalar_leaf_ty(tcx, ty).is_ok() {
        return Ok(false);
    }
    // An intercepted `Vec<T>` / `BTreeMap<K, V>` / `String` pointee is a single
    // `Ptr` scalar, not a flattenable aggregate — leave it to its interception.
    if vec_element_ty(tcx, ty).is_some()
        || btreemap_kv_ty(tcx, ty).is_some()
        || is_string_ty(tcx, ty)
    {
        return Ok(false);
    }
    // Only struct / tuple / array aggregates are addressed lane-wise here. (A
    // multi-variant enum behind a raw pointer is not produced by `Box::new`'s
    // payload readback and stays on the existing fail-closed path.)
    let is_addressable_aggregate = matches!(
        ty.kind(),
        ty::Tuple(fields) if !fields.is_empty()
    ) || matches!(ty.kind(), ty::Array(..))
        || matches!(
            ty.kind(),
            ty::Adt(adt, _) if adt.is_struct()
        );
    if !is_addressable_aggregate {
        return Ok(false);
    }
    let cx = LayoutCx(tcx);
    let layout = match tcx.layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty)) {
        Ok(layout) => layout,
        Err(_) => return Ok(false),
    };
    if !layout.is_sized() || layout.size.bytes() == 0 {
        return Ok(false);
    }
    // Every leaf must be a fixed-offset memory scalar (so each access is a single
    // typed load/store). A non-scalar / wide / niche-enum leaf fails closed here.
    // A fat-pointer leaf is ALSO excluded here (`Ok(true)` treated as
    // not-addressable): this raw-pointer deref lane-addressing path has not been
    // verified to emit the two-lane fat-pointer store/load through `(*raw_ptr).f`
    // — only the named-local construct/field-read paths were.
    Ok(matches!(
        validate_memory_aggregate_field_leaves(tcx, &cx, &layout),
        Ok(info) if !info.has_fat_pointer_leaf
    ))
}

/// Read the current pointer used as a memory aggregate dereference base.
fn memory_aggregate_ref_base<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<ValueId, String> {
    if !ctx.scalar_values.contains_key(&place.local)
        && !ctx.scalar_cells.contains_key(&place.local)
        && !is_entry_arg(body, place.local)
    {
        return Err("memory aggregate deref before reference pointer binding".to_owned());
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    if wide_deref_base_value_is_not_pointee_addr(ctx.tcx, base_ty) {
        return Err(format!(
            "[TCG-WIDEPTR-DEREF-BASE] length-metadata pointer `{base_ty:?}` requires its data lane before a field access"
        ));
    }
    value_for_runtime_scalar_local(ctx, block, place.local)
}

/// Compute the byte ADDRESS (and leaf type) of a `(*r)[.field…]` place where `r`
/// is a reference whose pointee is a memory-eligible aggregate. The base pointer
/// is the reference local's scalar value (which, for a `&memory_local`, IS the
/// slot pointer). Field / Downcast offsets are accumulated through the pointee's
/// layout exactly as for a memory-backed local.
fn memory_aggregate_ref_address<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
    pointee_ty: Ty<'tcx>,
) -> Result<(ValueId, TrustIrTy), String> {
    let base_ptr = memory_aggregate_ref_base(ctx, body, block, place)?;
    memory_aggregate_ref_address_from_base(ctx, block, place, pointee_ty, base_ptr)
}

/// Compute the pointee address after the pointer's live value has been read.
/// Store refinement models the access relative to that runtime base; loading
/// the pointer cell is outside its local field-store obligation.
fn memory_aggregate_ref_address_from_base<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
    pointee_ty: Ty<'tcx>,
    base_ptr: ValueId,
) -> Result<(ValueId, TrustIrTy), String> {
    // A projection through a runtime/constant array index (`(*r)[i].field`) cannot be
    // folded to a single static offset; the runtime walker emits the `index * stride`
    // arithmetic. Both walkers resolve field offsets through rustc's `layout_of`, so a
    // field rustc reordered (e.g. the `u64` of `(u8,u64,u16)` at offset 0) is addressed
    // correctly either way.
    if projection_has_index_element(&place.projection) {
        return walk_memory_projection_runtime_address(
            ctx,
            block,
            base_ptr,
            pointee_ty,
            &place.projection,
        );
    }
    let (offset, leaf_ty) = walk_memory_projection_offset(ctx, pointee_ty, &place.projection)?;
    let addr = if offset == 0 {
        base_ptr
    } else {
        wasm32_inbounds::projection_addr(ctx, block, base_ptr, offset)
    };
    Ok((addr, leaf_ty))
}

/// A closure projected through scalar wrappers must occupy the entire cell at
/// every level. Derive both the source layout and the emitted allocation size;
/// pointer captures retain pointer-typed storage, never integer byte images.
fn scalar_wrapper_closure_projection<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> Result<Option<TrustIrTy>, String> {
    let projected_ty = ctx.monomorphize_ty(place_rust_ty(ctx, body, place));
    let projects_closure = matches!(projected_ty.kind(), ty::Closure(..));
    let projects_primitive = matches!(
        projected_ty.kind(),
        ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
    );
    if place.projection.is_empty()
        || !place
            .projection
            .iter()
            .all(|p| matches!(p, ProjectionElem::Field(..)))
        || !(projects_closure || projects_primitive)
        || !local_is_single_scalar_storage(ctx, place.local)
    {
        return Ok(None);
    }
    let base_ty = ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local));
    if base_ty.needs_drop(ctx.tcx, ty::TypingEnv::fully_monomorphized())
        || is_fmt_internal_ty(ctx.tcx, base_ty)
    {
        return Ok(None);
    }
    let leaf_ty = memory_scalar_leaf_ty(ctx.tcx, base_ty)?;
    let lowered = trust_cg_lower::adapter::translate_type(&leaf_ty)
        .map_err(|e| format!("closure wrapper cell type cannot be allocated: {e:?}"))?;
    let storage = ScalarCellStorage {
        size: u64::from(lowered.bytes()),
        align: u64::from(lowered.align()),
    };
    let cx = LayoutCx(ctx.tcx);
    let mut layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("closure wrapper cell layout failed: {e:?}"))?;
    let mut crosses_closure = projects_closure;
    for projection in place.projection.iter() {
        let ProjectionElem::Field(field, _) = projection else {
            return Ok(None);
        };
        let container = match layout.ty.kind() {
            ty::Adt(adt, _) => adt.is_struct(),
            ty::Closure(..) => {
                crosses_closure = true;
                true
            }
            _ => false,
        };
        if !container
            || !matches!(layout.backend_repr, rustc_abi::BackendRepr::Scalar(_))
            || field.index() >= layout.fields.count()
            || !scalar_cell_projection_container_matches(
                storage,
                layout.fields.count(),
                layout.fields.offset(field.index()).bytes(),
                layout.size.bytes(),
                layout.align.bytes(),
            )
        {
            return Ok(None);
        }
        layout = layout.field(&cx, field.index());
    }
    if !crosses_closure
        || layout.ty != projected_ty
        || layout.size.bytes() != storage.size
        || layout.align.bytes() != storage.align
        || !matches!(layout.backend_repr, rustc_abi::BackendRepr::Scalar(_))
    {
        return Ok(None);
    }
    if projects_primitive {
        return Ok((memory_scalar_leaf_ty(ctx.tcx, projected_ty)? == leaf_ty).then_some(leaf_ty));
    }
    let mut leaves = Vec::new();
    if enumerate_scalar_leaf_offsets(ctx.tcx, &cx, &layout, 0, &mut leaves)?.is_none()
        || leaves != [(0, leaf_ty.clone())]
    {
        return Ok(None);
    }
    Ok(Some(leaf_ty))
}

/// A source-bound full-range u8 wrapper occupies exactly one byte at every
/// level. This excludes niches, enums, unions, padding and over-aligned homes;
/// it does not authorize a general aggregate or scalar-newtype projection.
fn checked_full_u8_wrapper_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    mut ty: Ty<'tcx>,
) -> Result<bool, String> {
    let env = ty::TypingEnv::fully_monomorphized();
    let cx = LayoutCx(tcx);
    loop {
        let layout = tcx
            .layout_of(env.as_query_input(ty))
            .map_err(|e| format!("[TCG-U8-WRAPPER-LAYOUT] layout_of({ty:?}) failed: {e:?}"))?;
        if !layout.is_sized()
            || layout.size.bytes() != 1
            || layout.align.bytes() != 1
            || !matches!(layout.backend_repr, rustc_abi::BackendRepr::Scalar(
                rustc_abi::Scalar::Initialized {
                    value: rustc_abi::Primitive::Int(rustc_abi::Integer::I8, false), valid_range
                }) if valid_range.start == 0 && valid_range.end == 255)
        {
            return Ok(false);
        }
        if matches!(ty.kind(), ty::Uint(ty::UintTy::U8)) {
            return Ok(true);
        }
        if !(matches!(ty.kind(), ty::Adt(def, _) if def.is_struct() && !def.is_union())
            || matches!(ty.kind(), ty::Tuple(_)))
        {
            return Ok(false);
        }
        let mut sized =
            (0..layout.fields.count()).filter(|index| !layout.field(&cx, *index).is_zst());
        let Some(index) = sized.next() else {
            return Ok(false);
        };
        if sized.next().is_some() || layout.fields.offset(index).bytes() != 0 {
            return Ok(false);
        }
        ty = layout.field(&cx, index).ty;
    }
}

/// Whether `ty` is a chain of struct / tuple wrappers over one primitive scalar
/// (`UnsafeCell<u32>`, `Cell<u64>`, `Wrapping<i16>`) whose every level has
/// exactly one sized field, at offset 0. Without `padded`, every level is the
/// WHOLE value (the container's own size and alignment, with either the same
/// scalar representation or a checked single-scalar memory image). This is an
/// address projection into existing storage, not a calling-ABI equivalence.
/// With `padded` (a 32-bit session, whose scalar cells span rustc's whole extent
/// at rustc's alignment — `scalar_cell_projection_container_matches`), a level
/// may also be a `#[repr(align)]` container padded AROUND its field; the scalar
/// still sits at offset 0, so the value's address is the scalar's.
fn checked_full_scalar_wrapper_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    mut ty: Ty<'tcx>,
    padded: bool,
) -> Result<bool, String> {
    let cx = LayoutCx(tcx);
    for _ in 0..16 {
        let layout = tcx
            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
            .map_err(|e| format!("[TCG-SCALAR-CELL-LAYOUT] wrapper layout failed: {e:?}"))?;
        if !layout.is_sized() {
            return Ok(false);
        }
        if matches!(
            ty.kind(),
            ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
        ) {
            return Ok(matches!(
                layout.backend_repr,
                rustc_abi::BackendRepr::Scalar(_)
            ));
        }
        if !(matches!(ty.kind(), ty::Adt(def, _) if def.is_struct() && !def.is_union())
            || matches!(ty.kind(), ty::Tuple(_)))
        {
            return Ok(false);
        }
        let mut sized =
            (0..layout.fields.count()).filter(|index| !layout.field(&cx, *index).is_zst());
        let Some(index) = sized.next() else {
            return Ok(false);
        };
        if sized.next().is_some() || layout.fields.offset(index).bytes() != 0 {
            return Ok(false);
        }
        let field = layout.field(&cx, index);
        // A memory-represented wrapper can still occupy exactly this scalar
        // cell. Prove its complete zero-offset memory image independently of
        // its calling representation; the surrounding projection checks retain
        // the allocated scalar's type, extent and alignment. This witness is
        // never used to classify a function argument or return value.
        let whole = field.size == layout.size
            && field.align.bytes() == layout.align.bytes()
            && (field.backend_repr == layout.backend_repr
                || repr_c_newtype_scalar_layout(tcx, &cx, &layout));
        let inside =
            padded && field.size <= layout.size && field.align.bytes() <= layout.align.bytes();
        if !(whole || inside) {
            return Ok(false);
        }
        ty = field.ty;
    }
    Ok(false)
}

/// An intermediate pointer wrapper still occupies the original scalar cell.
/// Prove its remaining zero-offset fields all the way to a genuine thin
/// reference/raw pointer. Pattern types constrain validity, not storage, and
/// must independently retain the same initialized pointer layout.
fn checked_full_thin_pointer_wrapper_layout<'tcx>(
    tcx: TyCtxt<'tcx>,
    mut ty: Ty<'tcx>,
    storage: ScalarCellStorage,
) -> Result<bool, String> {
    let env = ty::TypingEnv::fully_monomorphized();
    let cx = LayoutCx(tcx);
    loop {
        let layout = tcx.layout_of(env.as_query_input(ty)).map_err(|e| {
            format!("[TCG-SCALAR-CELL-LAYOUT] pointer wrapper layout failed: {e:?}")
        })?;
        if !layout.is_sized()
            || layout.size.bytes() != storage.size
            || layout.align.bytes() != storage.align
            || !matches!(
                layout.backend_repr,
                rustc_abi::BackendRepr::Scalar(rustc_abi::Scalar::Initialized {
                    value: rustc_abi::Primitive::Pointer(_),
                    ..
                })
            )
        {
            return Ok(false);
        }
        if is_thin_pointer_ref_ty(tcx, ty) {
            return Ok(true);
        }
        if let ty::Pat(base, _) = ty.kind() {
            ty = *base;
            continue;
        }
        if !(matches!(ty.kind(), ty::Adt(def, _) if def.is_struct() && !def.is_union())
            || matches!(ty.kind(), ty::Tuple(_)))
        {
            return Ok(false);
        }
        let mut sized =
            (0..layout.fields.count()).filter(|index| !layout.field(&cx, *index).is_zst());
        let Some(index) = sized.next() else {
            return Ok(false);
        };
        if sized.next().is_some() || layout.fields.offset(index).bytes() != 0 {
            return Ok(false);
        }
        ty = layout.field(&cx, index).ty;
    }
}

/// The actual Direct-u8 formal is its byte, even when MIR reaches that byte
/// through several zero-offset fields (ExitCode(imp::ExitCode(u8))). An
/// address-taken or separately field-bound local keeps its memory/binding path.
fn checked_u8_wrapper_entry_projection<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    place: &Place<'tcx>,
) -> Result<bool, String> {
    if place.projection.is_empty()
        || !place
            .projection
            .iter()
            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
        || ctx.scalar_cells.contains_key(&place.local)
        || ctx.memory_slots.contains_key(&place.local)
        || ctx.borrowed_scalars.contains_key(&place.local)
        || ctx.borrowed_aggregates.contains_key(&place.local)
        || ctx
            .projected_values
            .keys()
            .any(|(local, _)| *local == place.local)
    {
        return Ok(false);
    }
    // The body this context LOWERS, not a re-fetched `instance_mir`: a body
    // rewrite may have renumbered its locals.
    if !ctx.lowered_local_is_arg(place.local) {
        return Ok(false);
    }
    let base_ty = ctx.normalize_ty(ctx.lowered_local_rust_ty(place.local));
    if !checked_full_u8_wrapper_layout(ctx.tcx, base_ty)? {
        return Ok(false);
    }
    let fn_abi = RustcFnAbiSource::Instance(ctx.instance).query(ctx.tcx)?;
    let Some(arg) = place
        .local
        .index()
        .checked_sub(1)
        .and_then(|index| fn_abi.args.get(index))
    else {
        return Ok(false);
    };
    if arg.layout.ty != base_ty || !matches!(arg.mode, rustc_target::callconv::PassMode::Direct(_))
    {
        return Ok(false);
    }
    let cx = LayoutCx(ctx.tcx);
    let mut layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("[TCG-U8-WRAPPER-LAYOUT] entry layout failed: {e:?}"))?;
    for elem in place.projection.iter() {
        let ProjectionElem::Field(field, _) = elem else {
            return Ok(false);
        };
        if field.index() >= layout.fields.count() {
            return Ok(false);
        }
        let selected = layout.field(&cx, field.index());
        if selected.is_zst()
            || layout.fields.offset(field.index()).bytes() != 0
            || !checked_full_u8_wrapper_layout(ctx.tcx, selected.ty)?
        {
            return Ok(false);
        }
        layout = selected;
    }
    let leaf_ty = ctx.normalize_ty(ctx.monomorphize_ty(layout.ty));
    // Every projection is a `Field` (checked above), so the place's type is the
    // last one's field type, as `Place::ty` reads it; asked of the projection,
    // not of a body, for the reason above.
    let Some(ProjectionElem::Field(_, place_ty)) = place.projection.last() else {
        return Ok(false);
    };
    Ok(leaf_ty == ctx.normalize_ty(ctx.monomorphize_ty(*place_ty))
        && memory_scalar_leaf_ty(ctx.tcx, base_ty)? == memory_scalar_leaf_ty(ctx.tcx, leaf_ty)?)
}

/// A direct field projection into an already allocated scalar cell. This does
/// not classify ABIs, allocate replacement storage, or reinterpret projections
/// as SSA keys. Every admitted field occupies exactly the original cell.
fn checked_scalar_cell_projection<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
) -> Result<Option<ScalarCellProjection>, String> {
    if place.projection.is_empty()
        || !place
            .projection
            .iter()
            .all(|elem| matches!(elem, ProjectionElem::Field(..)))
    {
        return Ok(None);
    }
    let Some(cell) = exclusive_scalar_cell(&ctx.scalar_cells, &ctx.memory_slots, place.local)
    else {
        return Ok(None);
    };
    let reject = || {
        "[TCG-SCALAR-CELL-LAYOUT] projected cell must be an exact zero-offset, full-allocation scalar field chain".to_owned()
    };
    let storage = cell.storage.ok_or_else(reject)?;
    let base_ty = ctx.normalize_ty(ctx.monomorphize_ty(local_rust_ty(ctx, body, place.local)));
    if memory_scalar_leaf_ty(ctx.tcx, base_ty)? != cell.allocated_ty {
        return Err(reject());
    }
    let mut layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|_| reject())?;
    let cx = LayoutCx(ctx.tcx);
    for elem in place.projection.iter() {
        let ProjectionElem::Field(field, _) = elem else {
            return Err(reject());
        };
        let container = match layout.ty.kind() {
            ty::Adt(def, _) => def.is_struct(),
            ty::Tuple(_) => true,
            ty::Closure(..) => true,
            _ => false,
        };
        // A container occupies exactly the cell: the leaf's own allocation, or —
        // for an over-aligned newtype's home — rustc's padded extent, whose scalar
        // sits at offset 0 (`padded_scalar_home_extent`). Either way the chain must
        // still end at the cell's one scalar (checked below), so `a.a` of an `A16`
        // home reads the very bytes every whole-cell access uses.
        if !container || !layout.is_sized() || field.index() >= layout.fields.count() {
            return Err(reject());
        }
        let selected = layout.field(&cx, field.index());
        // ZST siblings occupy no scalar bytes. Keep the actual MIR field index
        // (the sized field of `ZstLead((), u64)` is field 1), and require this
        // projection to select the container's only non-ZST field. Its offset,
        // full allocation extent and alignment remain checked below.
        let sized_fields = (0..layout.fields.count())
            .filter(|&index| !layout.field(&cx, index).is_zst())
            .count();
        let fits = |extent: ScalarCellStorage| {
            scalar_cell_projection_container_matches(
                extent,
                sized_fields,
                layout.fields.offset(field.index()).bytes(),
                layout.size.bytes(),
                layout.align.bytes(),
            )
        };
        if selected.is_zst() || !(fits(storage) || cell.home.is_some_and(fits)) {
            return Err(reject());
        }
        layout = selected;
    }
    let leaf_rust_ty = ctx.normalize_ty(ctx.monomorphize_ty(layout.ty));
    let primitive = matches!(
        leaf_rust_ty.kind(),
        ty::Int(_) | ty::Uint(_) | ty::Float(_) | ty::Bool | ty::Char
    );
    let pointer_cell_target = ctx.tcx.sess.target.arch.desc() == "aarch64"
        && ctx.tcx.sess.target.os == rustc_target::spec::Os::Linux
        && ctx.tcx.data_layout.pointer_size().bytes() == 8;
    let thin_pointer = pointer_cell_target && is_thin_pointer_ref_ty(ctx.tcx, leaf_rust_ty);
    let pointer_wrapper = pointer_cell_target
        && !primitive
        && !thin_pointer
        && checked_full_thin_pointer_wrapper_layout(ctx.tcx, leaf_rust_ty, storage)?;
    // Borrowing the intermediate imp::ExitCode field still addresses the
    // original byte cell. Prove the remaining wrapper, rather than interpreting
    // an arbitrary ADT leaf as a primitive or allocating replacement storage.
    let u8_wrapper = !primitive
        && !thin_pointer
        && !pointer_wrapper
        && checked_full_u8_wrapper_layout(ctx.tcx, leaf_rust_ty)?;
    // Likewise a borrow of a transparent-style wrapper over the cell's scalar
    // (`&raw const cell.0` of a `Cell<u32>`, whose field is `UnsafeCell<u32>`)
    // addresses exactly the cell: proved level by level, never inferred.
    let scalar_wrapper = !primitive
        && !thin_pointer
        && !pointer_wrapper
        && !u8_wrapper
        && checked_full_scalar_wrapper_layout(ctx.tcx, leaf_rust_ty, session_pointer_bytes() == 4)?;
    // A wrapper leaf may be padded around the scalar exactly where a container
    // on the chain may (`scalar_cell_projection_container_matches`); every
    // other leaf is the cell's exact extent.
    let extent_fits = if scalar_wrapper {
        scalar_cell_projection_container_matches(
            storage,
            1,
            0,
            layout.size.bytes(),
            layout.align.bytes(),
        )
    } else {
        layout.size.bytes() == storage.size && layout.align.bytes() == storage.align
    };
    if !(primitive || thin_pointer || pointer_wrapper || u8_wrapper || scalar_wrapper)
        || !layout.is_sized()
        || !extent_fits
        || leaf_rust_ty != ctx.normalize_ty(place_rust_ty(ctx, body, place))
    {
        return Err(reject());
    }
    let leaf_ty = memory_scalar_leaf_ty(ctx.tcx, leaf_rust_ty)?;
    if leaf_ty != cell.allocated_ty
        || scalar_cell_storage_for_target(ctx, &leaf_ty) != Some(storage)
    {
        return Err(reject());
    }
    Ok(Some(ScalarCellProjection {
        ptr: cell.ptr,
        leaf_ty,
    }))
}

/// Emit a typed `Load` of `ty` from `ptr`.
fn emit_typed_load(
    ctx: &mut MirLoweringCtx<'_>,
    block: &mut Block,
    ptr: ValueId,
    ty: TrustIrTy,
) -> ValueId {
    let result = ctx.fresh_value();
    block.body.push(
        InstrNode::new(Inst::Load {
            ty,
            ptr,
            volatile: false,
            align: None,
        })
        .with_result(result),
    );
    result
}

/// Emit a typed `Store` of `value: ty` to `ptr`.
fn emit_typed_store(block: &mut Block, ptr: ValueId, ty: TrustIrTy, value: ValueId) {
    block.body.push(InstrNode::new(Inst::Store {
        ty,
        ptr,
        value,
        volatile: false,
        align: None,
    }));
}

/// The type of a function's exception slot (`MirLoweringCtx::eh_exn_slot`):
/// trust-ir types a `LandingPad`'s exception object `Ptr` (its results are
/// `(Ptr, I32)`), so the slot holds that pointer at its own type, from the
/// pad's `Store` to the `Load` a `Resume` re-raises. trust-ir requires a
/// `Store`'s value to have the store's type (`OperandTypeMismatch`), which
/// every ingestion entry refuses since WS7.3 (LD-47); the slot used to be an
/// `I64` written with the `Ptr`, the same eight bytes. Every pad stores at this
/// type and every `Resume` path loads at it, so the slot's size and alignment,
/// the bytes stored and the value `Resume` re-raises do not change.
const EH_EXN_SLOT_TY: TrustIrTy = TrustIrTy::Ptr;

/// Store a `LandingPad`'s exception object `exn` into the exception slot
/// `slot`, at [`EH_EXN_SLOT_TY`].
fn emit_exn_slot_store(block: &mut Block, slot: ValueId, exn: ValueId) {
    emit_typed_store(block, slot, EH_EXN_SLOT_TY, exn);
}

/// Load a memory-backed `place` (read side). Returns `Ok(Some(value))` when the
/// place's base local is memory-backed and the projection is supported.
fn lower_memory_place_load<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
) -> Result<Option<ValueId>, String> {
    if !local_is_memory_backed(ctx, place.local) {
        return Ok(None);
    }
    // Snapshot the block's instruction count so the EMITTED address arithmetic +
    // Load for THIS statement (block.body[start..]) can be captured for the P1
    // memory refinement (the bridge side is folded from these real ops, not from
    // a re-query of the layout — the anti-tautology requirement).
    let emit_start = block.body.len();
    let (addr, ty) = memory_place_address(ctx, body, block, place)?;
    let value = emit_typed_load(ctx, block, addr, ty);
    push_field_load_mem_refinement(ctx, body, place, &block.body[emit_start..]);
    Ok(Some(value))
}

/// Build the SPEC memory-op sequence for a FIXED-offset nested-projection SCALAR
/// FIELD LOAD (`dst = base.f…`): the MIR place semantics designate exactly the
/// `width`-byte cell at `base_addr + layout_offset`. The Field/Downcast chain is
/// resolved to a byte offset and the leaf size INDEPENDENTLY via rustc's
/// `layout_of(...).fields.offset(i)` — the SAME authoritative layout the bridge
/// addresses through — so a wrong EMITTED offset/width (reconstructed separately
/// by `mem_refine::fold_emitted_mem_ops`) refutes. `base_value` is the slot
/// pointer the place's base local lives in (the shared symbolic base anchor).
///
/// `Ok(None)` when the projection is NOT a pure constant-offset Field/Downcast
/// chain (a `Deref`/`Index`/`Subslice` element is out of this fixed-offset
/// slice) or the leaf is not a sized scalar — the caller then pushes nothing.
fn spec_field_load_mem_ops<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
    base_value: ValueId,
) -> Result<
    Option<(
        Vec<trust_cg_verify::mir_semantics::MirMemOp>,
        Vec<trust_cg_verify::mir_semantics::MirMemOp>,
    )>,
    String,
> {
    let cx = LayoutCx(ctx.tcx);
    let mut layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("spec field-load layout_of failed: {e:?}"))?;
    let mut offset: u64 = 0;
    for elem in projection {
        match elem {
            ProjectionElem::Field(field, _) => {
                offset += layout.fields.offset(field.index()).bytes();
                layout = layout.field(&cx, field.index());
            }
            ProjectionElem::Downcast(_, variant_index) => {
                layout = layout.for_variant(&cx, *variant_index);
            }
            // Deref / Index / ConstantIndex / Subslice / OpaqueCast / unsafe
            // binder: out of the fixed-offset Field/Downcast slice.
            _ => return Ok(None),
        }
    }
    // The leaf must be a single sized scalar (its `layout.size` is the load
    // width). A non-scalar leaf is not this lowering's shape.
    let size = layout.size.bytes();
    let Ok(width) = u32::try_from(size) else {
        return Ok(None);
    };
    if width == 0 {
        return Ok(None);
    }
    Ok(Some(mem_refine::field_load_obligation(
        mem_refine::mem_base_name(base_value),
        offset,
        width,
    )))
}

/// Queue a Phase P1 MEMORY refinement obligation for a fixed-offset
/// nested-projection SCALAR FIELD LOAD, if `place` matches that shape and a
/// refinement lane is active. `emitted` is the exact slice of instructions the
/// bridge just appended for this load. No-op (best-effort, additive) otherwise —
/// this NEVER changes lowering behavior and any encoder limitation simply skips
/// the obligation (sound: less coverage, never a wrong verdict).
fn push_field_load_mem_refinement<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
    emitted: &[InstrNode],
) {
    let Some(slot) = ctx.memory_slots.get(&place.local).cloned() else {
        return;
    };
    push_field_load_mem_refinement_at_base(ctx, body, place, slot.ptr, emitted);
}

/// Additive diagnostic only. The caller supplies the actual, already validated
/// storage base used by the emitted access (aggregate slot or scalar cell).
fn push_field_load_mem_refinement_at_base<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
    base_ptr: ValueId,
    emitted: &[InstrNode],
) {
    if !ctx.refinements_active() {
        return;
    }
    // The target shape: a memory-backed base local read through a NON-EMPTY,
    // pure Field/Downcast projection (a fixed byte offset, addressed off the slot
    // pointer directly — no Deref/Index). A bare local read or a runtime index is
    // a different lowering and is left to its own (future) phase.
    if place.projection.is_empty()
        || !place
            .projection
            .iter()
            .all(|e| matches!(e, ProjectionElem::Field(..) | ProjectionElem::Downcast(..)))
    {
        return;
    }
    let base_ty = local_rust_ty(ctx, body, place.local);
    let (harness, spec_ops) =
        match spec_field_load_mem_ops(ctx, base_ty, &place.projection, base_ptr) {
            Ok(Some(pair)) => pair,
            // Out of the fixed-offset slice, or a layout error — skip (sound).
            Ok(None) | Err(_) => return,
        };
    // Dedup by a shape key (base slot + projection layout shape) so a repeated
    // field read of the same local does not re-queue identical work.
    let key = format!(
        "memload:v{}:proj{:?}",
        base_ptr.index(),
        place.projection.as_ref()
    );
    if !ctx.mem_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.mem_refine_sink.push(MemRefinementJob {
        name: key,
        harness,
        spec_ops,
        emitted: emitted.to_vec(),
        place_shape: trust_cg_verify::bridge_coverage::ProjectionKind::Field.name(),
        kind: trust_cg_verify::bridge_coverage::MemRefineKind::FieldLoad,
    });
}

/// Store `value` into a memory-backed `place` (write side). The caller must have
/// confirmed the base local is memory-backed.
fn lower_memory_place_store<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    block: &mut Block,
    place: &Place<'tcx>,
    value: ValueId,
) -> Result<(), String> {
    // Snapshot the block's instruction count so the EMITTED address arithmetic +
    // Store for THIS statement (`block.body[emit_start..]`) can be captured for
    // the P1 field-STORE memory refinement (the bridge side is folded from these
    // real ops, not from a layout re-query — the anti-tautology requirement).
    let emit_start = block.body.len();
    let (addr, ty) = memory_place_address(ctx, body, block, place)?;
    emit_typed_store(block, addr, ty, value);
    push_field_store_mem_refinement(ctx, body, place, value, &block.body[emit_start..]);
    Ok(())
}

/// Build the SPEC memory-op sequences for a FIXED-offset nested-projection SCALAR
/// FIELD STORE (`base.f… = v`): the MIR place designates exactly the `width`-byte
/// cell at `base_addr + layout_offset`, and EVERY sibling leaf cell must be left
/// unchanged. The Field/Downcast chain is resolved to a byte offset + leaf size
/// INDEPENDENTLY via rustc's `layout_of(...).fields.offset(i)` (the SAME
/// authoritative layout the bridge addresses through), and the immediate
/// scalar-leaf SIBLINGS along the projection path (e.g. `o.b.y`, `o.a`) are
/// enumerated as `(offset, width)` cells to PIN as old — so a wrong EMITTED
/// offset/width/value (reconstructed separately by `mem_refine::fold_emitted_mem_ops`)
/// OR a sibling clobber refutes. `stored_value` is the lowered SSA value being
/// stored (the shared value-var anchor); `base_value` is the slot pointer.
///
/// `Ok(None)` when the projection is NOT a pure constant-offset Field/Downcast
/// chain or the leaf is not a sized scalar — the caller then pushes nothing.
fn spec_field_store_mem_ops<'tcx>(
    ctx: &MirLoweringCtx<'tcx>,
    base_ty: Ty<'tcx>,
    projection: &[ProjectionElem<Local, Ty<'tcx>>],
    base_value: ValueId,
    stored_value: ValueId,
) -> Result<
    Option<(
        Vec<trust_cg_verify::mir_semantics::MirMemOp>,
        Vec<trust_cg_verify::mir_semantics::MirMemOp>,
    )>,
    String,
> {
    let cx = LayoutCx(ctx.tcx);
    let mut layout = ctx
        .tcx
        .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(base_ty))
        .map_err(|e| format!("spec field-store layout_of failed: {e:?}"))?;
    let mut offset: u64 = 0;
    // The scalar-leaf SIBLING cells encountered along the projection path — the
    // "elsewhere" the store must leave unchanged (the disjointness witnesses).
    let mut siblings: Vec<(u64, u32)> = Vec::new();
    for elem in projection {
        match elem {
            ProjectionElem::Field(field, _) => {
                let chosen = field.index();
                // Pin each NON-chosen scalar-lane sibling field at this level.
                for j in 0..layout.fields.count() {
                    if j == chosen {
                        continue;
                    }
                    let sib_off = offset + layout.fields.offset(j).bytes();
                    let sib_layout = layout.field(&cx, j);
                    if let Ok(w) = u32::try_from(sib_layout.size.bytes()) {
                        // A scalar lane: power-of-two width in {1,2,4,8}. Larger /
                        // odd-sized siblings are left to the final-memory UNION
                        // check (which still refutes any stray bridge write).
                        if matches!(w, 1 | 2 | 4 | 8) {
                            siblings.push((sib_off, w));
                        }
                    }
                }
                offset += layout.fields.offset(chosen).bytes();
                layout = layout.field(&cx, chosen);
            }
            ProjectionElem::Downcast(_, variant_index) => {
                layout = layout.for_variant(&cx, *variant_index);
            }
            _ => return Ok(None),
        }
    }
    let size = layout.size.bytes();
    let Ok(width) = u32::try_from(size) else {
        return Ok(None);
    };
    if width == 0 {
        return Ok(None);
    }
    Ok(Some(mem_refine::field_store_obligation(
        mem_refine::mem_base_name(base_value),
        offset,
        width,
        stored_value,
        &siblings,
    )))
}

/// Queue a Phase P1 MEMORY refinement obligation for a fixed-offset
/// nested-projection SCALAR FIELD STORE, if `place` matches that shape and a
/// refinement lane is active. `emitted` is the exact slice of instructions the
/// bridge just appended for this store. No-op (best-effort, additive) otherwise —
/// this NEVER changes lowering behavior and any encoder limitation simply skips
/// the obligation (sound: less coverage, never a wrong verdict).
fn push_field_store_mem_refinement<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
    value: ValueId,
    emitted: &[InstrNode],
) {
    let Some(slot) = ctx.memory_slots.get(&place.local).cloned() else {
        return;
    };
    push_field_store_mem_refinement_at_base(ctx, body, place, slot.ptr, value, emitted);
}

/// Additive diagnostic only, with the emitted access's actual validated base.
fn push_field_store_mem_refinement_at_base<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    body: &Body<'tcx>,
    place: &Place<'tcx>,
    base_ptr: ValueId,
    value: ValueId,
    emitted: &[InstrNode],
) {
    if !ctx.refinements_active() {
        return;
    }
    // Same shape as the field LOAD: a memory-backed base local written through a
    // NON-EMPTY pure Field/Downcast projection (a fixed byte offset off the slot).
    if place.projection.is_empty()
        || !place
            .projection
            .iter()
            .all(|e| matches!(e, ProjectionElem::Field(..) | ProjectionElem::Downcast(..)))
    {
        return;
    }
    let base_ty = local_rust_ty(ctx, body, place.local);
    let (harness, spec_ops) =
        match spec_field_store_mem_ops(ctx, base_ty, &place.projection, base_ptr, value) {
            Ok(Some(pair)) => pair,
            Ok(None) | Err(_) => return,
        };
    let key = format!(
        "memstore:v{}:proj{:?}",
        base_ptr.index(),
        place.projection.as_ref()
    );
    if !ctx.mem_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.mem_refine_sink.push(MemRefinementJob {
        name: key,
        harness,
        spec_ops,
        emitted: emitted.to_vec(),
        place_shape: trust_cg_verify::bridge_coverage::ProjectionKind::Field.name(),
        kind: trust_cg_verify::bridge_coverage::MemRefineKind::FieldStore,
    });
}

/// Queue a Phase P1 MEMORY refinement obligation for a `(*r).field[.…] = v`
/// scalar STORE THROUGH A REFERENCE, if a refinement lane is active and the place
/// is that shape. `base_ptr` is `r`'s RUNTIME pointer value (the id
/// `memory_aggregate_ref_address` addressed the store through — captured BEFORE
/// the value was lowered so a value-computation rebind cannot desync it);
/// `addr_nodes` is the EMITTED address arithmetic and `store_node` the EMITTED
/// typed `Store`.
///
/// THE KEY DIFFERENCE FROM `push_field_store_mem_refinement`: the store's base is
/// NOT a stack slot at a symbolic slot pointer — it is `r`'s runtime pointer
/// value. The fold (`fold_emitted_mem_ops`) reconstructs that base from the
/// emitted `Copy`/`PtrToInt`/`Add`/`IntToPtr` chain (an id `r` is bound to, never
/// defined in the slice, so named `mem_base_v{r}`); the SPEC anchors the SAME
/// `mem_base_v{r}` (via `spec_field_store_mem_ops` with `base_value = base_ptr`).
/// So the two meet only on that shared runtime base name: a store the bridge
/// emits through a DIFFERENT base (a bug), at a WRONG offset, or of a WRONG value
/// yields a genuinely different `MirMemOp` and REFUTES.
///
/// SIBLING DISJOINTNESS THROUGH THE REF (proven, not fail-closed): every pointee
/// sibling leaf lives at `base_ptr + other_offset` — the SAME symbolic base as
/// the target, at a distinct CONSTANT offset. The SPEC pins each as old; the
/// store touches only `[offset, offset+width)`; so a bridge that clobbers a
/// sibling overwrites a pinned old cell and REFUTES. This is a purely LOCAL
/// property of the single store (bytes untouched outside its range) and holds
/// regardless of whether `r` aliases any OTHER pointer — all cells are addressed
/// off the one `base_ptr` value, provably `Distinct` at constant offsets, so
/// `MemCheckConfig::default()` discharges it (no aliasing assumption is made).
///
/// No-op (best-effort, additive) otherwise — never changes lowering behavior and
/// any encoder limitation simply skips the obligation (sound: less coverage,
/// never a wrong verdict).
fn push_deref_field_store_mem_refinement<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    place: &Place<'tcx>,
    pointee_ty: Ty<'tcx>,
    base_ptr: Option<ValueId>,
    value: ValueId,
    addr_nodes: Vec<InstrNode>,
    store_node: Option<InstrNode>,
) {
    if !ctx.refinements_active() {
        return;
    }
    // The target shape: a leading `Deref` followed by a NON-EMPTY, pure
    // Field/Downcast projection (`(*r).field…`), addressed off the reference's
    // runtime pointer at a fixed byte offset. A trailing runtime `Index`/`Subslice`
    // (`(*r)[i]…`) is out of the fixed-offset slice; the fold would bail anyway,
    // but we never even queue it.
    let [ProjectionElem::Deref, rest @ ..] = place.projection.as_ref() else {
        return;
    };
    if rest.is_empty()
        || !rest
            .iter()
            .all(|e| matches!(e, ProjectionElem::Field(..) | ProjectionElem::Downcast(..)))
    {
        return;
    }
    let (Some(base_ptr), Some(store_node)) = (base_ptr, store_node) else {
        return;
    };
    // SPEC: the pointee-layout byte offset + leaf width + scalar-leaf siblings,
    // anchored on `r`'s runtime pointer value (`base_ptr`). Reuses the SAME
    // sibling-pinning encoder P1b's field store uses — the only change is the base
    // is a runtime pointer, not a slot pointer.
    let (harness, spec_ops) = match spec_field_store_mem_ops(ctx, pointee_ty, rest, base_ptr, value)
    {
        Ok(Some(pair)) => pair,
        Ok(None) | Err(_) => return,
    };
    // The fold input: the EMITTED address arithmetic terminated by the EMITTED
    // typed store — NOT the value-computation ops (which are excluded by capturing
    // `addr_nodes` before the value was lowered and appending only the store).
    let mut emitted = addr_nodes;
    emitted.push(store_node);
    let key = format!(
        "derefstore:v{}:proj{:?}",
        base_ptr.index(),
        place.projection.as_ref()
    );
    if !ctx.mem_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.mem_refine_sink.push(MemRefinementJob {
        name: key,
        harness,
        spec_ops,
        emitted,
        place_shape: trust_cg_verify::bridge_coverage::ProjectionKind::Deref.name(),
        kind: trust_cg_verify::bridge_coverage::MemRefineKind::DerefStore,
    });
}

/// Queue a Phase P1 MEMORY refinement obligation for the DEGENERATE `*r = v`
/// scalar store through a reference (off=0), if a refinement lane is active. The
/// emitted `Store` addresses `ptr` (r's runtime pointer value) directly; the fold
/// reconstructs base = `ptr` + offset 0, and the SPEC stores the same value var at
/// `mem_base_v{ptr} + 0` (a scalar pointee has no siblings). A wrong base / width
/// / value REFUTES. No-op / skip otherwise (additive, sound).
fn push_deref_scalar_store_mem_refinement<'tcx>(
    ctx: &mut MirLoweringCtx<'tcx>,
    place: &Place<'tcx>,
    ptr: ValueId,
    ty: TrustIrTy,
    value: ValueId,
    store_node: Option<InstrNode>,
) {
    if !ctx.refinements_active() {
        return;
    }
    // Exactly `*r = v`: a lone `Deref`, no further projection.
    if !matches!(place.projection.as_ref(), [ProjectionElem::Deref]) {
        return;
    }
    let Some(store_node) = store_node else {
        return;
    };
    let Some(width) = mem_refine::memory_access_byte_width(&ty) else {
        return;
    };
    // SPEC: store `value` (width bytes) at `mem_base_v{ptr} + 0`, no siblings.
    let (harness, spec_ops) =
        mem_refine::field_store_obligation(mem_refine::mem_base_name(ptr), 0, width, value, &[]);
    let key = format!("derefscalar:v{}:w{}", ptr.index(), width);
    if !ctx.mem_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.mem_refine_sink.push(MemRefinementJob {
        name: key,
        harness,
        spec_ops,
        emitted: vec![store_node],
        place_shape: trust_cg_verify::bridge_coverage::ProjectionKind::Deref.name(),
        kind: trust_cg_verify::bridge_coverage::MemRefineKind::DerefStore,
    });
}

/// Queue a Phase P1 `<[T]>::split_at` / `str::split_at` VALUE refinement job, if a
/// refinement lane is active. `emitted` is the exact trust-ir the bridge produced
/// for the split (the bounds `ICmp`, the two `{data,len}` lane `Store`s,
/// `emit_element_addr`'s Mul/Add for the right data pointer, and the `Sub` for the
/// right length) — captured BEFORE the `CondBr`/`Br`, so the fold sees only the
/// split computation. `ptr`/`len`/`mid` are the receiver's data-pointer / length /
/// split-index; `off0`/`off1` the destination tuple's `{data,len}` field offsets;
/// `elem_size` the element stride. Deduped by `(dest slot, offsets, size)`.
/// No-op (best-effort, additive) otherwise — never changes lowering behavior; an
/// unrecognized emitted shape folds to `None` at discharge time, which the strict
/// lane refuses and the default lanes skip (`refinement_job_unmodeled`).
#[allow(clippy::too_many_arguments)]
fn push_split_at_refinement(
    ctx: &mut MirLoweringCtx<'_>,
    emitted: &[InstrNode],
    ptr: ValueId,
    len: ValueId,
    mid: ValueId,
    dest_slot: ValueId,
    off0: u64,
    off1: u64,
    elem_size: u64,
) {
    if !ctx.refinements_active() {
        return;
    }
    let key = format!(
        "splitat:v{}:off{off0}_{off1}:sz{elem_size}",
        dest_slot.index()
    );
    if !ctx.split_at_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.split_at_refine_sink.push(SplitAtRefinementJob {
        name: key,
        emitted: emitted.to_vec(),
        ptr,
        len,
        mid,
        off0,
        off1,
        elem_size,
    });
}

/// Capture a slice-to-Vec `{ptr, cap, len}` header for TV lane 14.
///
/// `elem_size`/`elem_align` MUST come from the caller's layout-oracle query, not
/// from the emitted constants — the whole refutational content of the size and
/// alignment obligations is that the emission is compared against an
/// INDEPENDENTLY obtained layout.
///
/// Capture the actual emitted header, including its conditional allocation
/// blocks. An unmodeled shape remains visible at discharge: strict refinement
/// refuses it, while default tracing records SKIPPED and grants no proof credit.
fn capture_slice_to_vec_header_refinement(
    ctx: &mut MirLoweringCtx<'_>,
    emitted: &[InstrNode],
    slot_ptr: ValueId,
    n: ValueId,
    elem_size: u64,
    elem_align: u64,
) {
    if !ctx.refinements_active() {
        return;
    }
    // A zero-sized or unaligned element is already rejected upstream; re-assert
    // rather than model a degenerate allocation.
    if elem_size == 0 || elem_align == 0 {
        return;
    }
    ctx.slice_to_vec_header_refine_sink
        .push(SliceToVecHeaderRefinementJob {
            name: format!(
                "tovecheader:v{}:sz{elem_size}:al{elem_align}",
                slot_ptr.index()
            ),
            emitted: emitted.to_vec(),
            n,
            elem_size,
            elem_align,
        });
}

/// Queue a Phase P1 slice STRIDE-ITERATOR constructor (`chunks`/`windows`/
/// `chunks_exact`/`rchunks`/`rchunks_exact`) VALUE refinement job, if a refinement
/// lane is active. `emitted` is the exact trust-ir the bridge produced for the
/// state computation (the `n != 0` `ICmp`, the `*_exact` `URem`/`Sub` split and
/// its `emit_element_addr` Mul/Add, and the state stores) — captured EXCLUDING
/// the `CondBr`/`Br`. `data`/`len`/`n` are the receiver's data-pointer / length /
/// stride; `offsets` the state lanes the stores target (rustc's layout);
/// `elem_size` the element stride. Deduped by `(dest slot, kind, offsets, size)`.
/// No-op (best-effort, additive) otherwise — never changes lowering behavior; any
/// unrecognized emitted shape simply folds to `None` at discharge time (sound).
#[allow(clippy::too_many_arguments)]
fn push_stride_iter_refinement(
    ctx: &mut MirLoweringCtx<'_>,
    emitted: &[InstrNode],
    kind: SliceStrideIter,
    data: ValueId,
    len: ValueId,
    n: ValueId,
    dest_slot: ValueId,
    offsets: mem_refine::StrideIterStateOffsets,
    elem_size: u64,
) {
    if !ctx.refinements_active() {
        return;
    }
    let kind = kind.ctor_kind();
    let rem = offsets
        .rem
        .map_or_else(String::new, |(d, l)| format!("_rem{d}_{l}"));
    let key = format!(
        "strideiter:v{}:{kind:?}:off{}_{}_{}{rem}:sz{elem_size}",
        dest_slot.index(),
        offsets.v_data,
        offsets.v_len,
        offsets.size
    );
    if !ctx.stride_iter_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.stride_iter_refine_sink.push(StrideIterRefinementJob {
        name: key,
        emitted: emitted.to_vec(),
        kind,
        data,
        len,
        n,
        offsets,
        elem_size,
    });
}

/// Queue a Phase P1 CHECKED slice/Vec index (`<Vec<T> as Index>::index` /
/// `index_mut` and `<[T]>::index` — the `v[i]` panic form) VALUE refinement job, if
/// a refinement lane is active. `emitted` is the exact trust-ir the bridge produced
/// for the index computation (the bounds `ICmp Ult(index, len)` from the pre-branch
/// block, then `emit_element_addr`'s Copy/PtrToInt/Copy/[Const,Mul]/Add/IntToPtr for
/// `data + index*elem_size` from the in-bounds work block) — concatenated across the
/// two blocks, captured EXCLUDING the `len`/`data` slot-word loads, the
/// `CondBr`/`Br`, and the trailing `Copy`-to-dest, so the fold sees only the bounds
/// check + the address arithmetic. `data`/`len`/`index` are the receiver's
/// data-pointer / length / index; `elem_size` the element stride. Deduped by
/// `(vec slot, index, size)`. No-op (best-effort, additive) otherwise — never
/// changes lowering behavior; an unrecognized emitted shape folds to `None` at
/// discharge time, which the strict lane refuses and the default lanes skip
/// (`refinement_job_unmodeled`). MUST be called only on the CHECKED path — the
/// `unsafe` `get_unchecked*` variants have no trap and must never be captured.
fn push_vec_index_refinement(
    ctx: &mut MirLoweringCtx<'_>,
    emitted: &[InstrNode],
    data: ValueId,
    len: ValueId,
    index: ValueId,
    slot_ptr: ValueId,
    elem_size: u64,
) {
    if !ctx.refinements_active() {
        return;
    }
    let key = format!(
        "vecindex:v{}:i{}:sz{elem_size}",
        slot_ptr.index(),
        index.index()
    );
    if !ctx.vec_index_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.vec_index_refine_sink.push(VecIndexRefinementJob {
        name: key,
        emitted: emitted.to_vec(),
        data,
        len,
        index,
        elem_size,
    });
}

/// Queue a Phase P1 CHECKED Vec RANGE SUBSLICE (`<Vec<T> as
/// Index<Range|RangeFrom|RangeTo>>::index` / `index_mut` — `&v[a..b]` / `&v[a..]` /
/// `&v[..b]`) VALUE refinement job, if a refinement lane is active. `emitted` is the
/// exact trust-ir the bridge produced for the subslice computation (the
/// `emit_element_addr` Mul/Add for the result pointer, the `Sub` for the result
/// length, the two `{data,len}` lane `Store`s, and the two `ICmp Ule`s + Bool
/// `And`) — captured EXCLUDING the `CondBr`, so the fold sees only the subslice
/// arithmetic + the combined bounds check. `form` selects the range form (the spec's
/// endpoint binding); `data`/`len`/`a`/`b` are the receiver's data-pointer / length /
/// start / end; `elem_size` the element stride. Deduped by `(dest slot, form, size)`.
/// No-op (best-effort, additive) otherwise — never changes lowering behavior; an
/// unrecognized emitted shape folds to `None` at discharge time, which the strict
/// lane refuses and the default lanes skip (`refinement_job_unmodeled`).
#[allow(clippy::too_many_arguments)]
fn push_vec_range_subslice_refinement(
    ctx: &mut MirLoweringCtx<'_>,
    emitted: &[InstrNode],
    form: trust_cg_verify::mir_semantics::RangeForm,
    data: ValueId,
    len: ValueId,
    a: ValueId,
    b: ValueId,
    dest_slot: ValueId,
    elem_size: u64,
) {
    if !ctx.refinements_active() {
        return;
    }
    let key = format!("vecsubslice:v{}:{form:?}:sz{elem_size}", dest_slot.index());
    if !ctx.vec_range_subslice_refine_seen.insert(key.clone()) {
        return;
    }
    ctx.vec_range_subslice_refine_sink
        .push(VecRangeSubsliceRefinementJob {
            name: key,
            emitted: emitted.to_vec(),
            form,
            data,
            len,
            a,
            b,
            elem_size,
        });
}

/// Queue a niche-`Option<&T>` first/last VALUE refinement over the ops the bridge
