    /// A single-float-leaf wrapper constant is spelled from its bits only when
    /// its size is the float's; any other size is refused, never truncated.
    #[test]
    fn float_leaf_const_bits_require_the_float_size() {
        use super::{FloatLeafConstBits, TrustIrTy, float_leaf_const_bits};
        assert_eq!(
            float_leaf_const_bits(&TrustIrTy::F32, 4, 0x7fa0_0000),
            Ok(FloatLeafConstBits::F32(0x7fa0_0000)),
            "a signaling-NaN f32 keeps its exact bits"
        );
        assert_eq!(
            float_leaf_const_bits(&TrustIrTy::F64, 8, 0x4009_21fb_5444_2d18),
            Ok(FloatLeafConstBits::F64(0x4009_21fb_5444_2d18))
        );
        for (ty, bytes) in [
            (TrustIrTy::F32, 8),
            (TrustIrTy::F64, 4),
            (TrustIrTy::F32, 2),
        ] {
            let err = float_leaf_const_bits(&ty, bytes, 1).expect_err("size mismatch");
            assert!(
                err.contains(&format!(
                    "{bytes}-byte scalar constant lowered to float type"
                )),
                "{err}"
            );
        }
    }

    /// A fieldless enum's tag stored into a scalar memory leaf keeps its bytes
    /// whatever the leaf's signedness: `Ordering::Less` (`-1i8`) is `255` in a
    /// `U8` leaf, and `200` (a `u8` tag) is `-56` in an `I8` one.
    #[test]
    fn enum_tag_constant_is_spelled_in_the_leaf_type() {
        assert_eq!(super::int_const_spelled_in_width(-1, 8, false), 255);
        assert_eq!(super::int_const_spelled_in_width(-1, 8, true), -1);
        assert_eq!(super::int_const_spelled_in_width(200, 8, true), -56);
        assert_eq!(super::int_const_spelled_in_width(200, 8, false), 200);
        assert_eq!(super::int_const_spelled_in_width(1, 8, true), 1);
        assert_eq!(
            super::int_const_spelled_in_width(-2, 32, false),
            0xffff_fffe
        );
        assert_eq!(
            super::int_const_spelled_in_width(i128::from(i64::MIN), 64, true),
            i128::from(i64::MIN)
        );
    }

    /// A single-scalar ADT constant (`Cell<bool>`, `struct M(f64)`) arrives as
    /// its scalar's bits in `Constant::Int` and is spelled for the scalar's
    /// trust-ir type with the same bits; a `bool` image other than `0` / `1`
    /// keeps its spelling for trust-ir to refuse. An integer keeps its spelling
    /// here, and the module pass gives a signed pattern its signed value.
    #[test]
    fn single_scalar_adt_constant_is_spelled_for_its_scalar() {
        use super::{Constant, TrustIrTy, scalar_carrier_constant, signed_pattern_spelling};
        let spell = |value, ty: TrustIrTy| scalar_carrier_constant(Constant::Int(value), &ty);
        assert_eq!(spell(1, TrustIrTy::Bool), Constant::Bool(true));
        assert_eq!(spell(0, TrustIrTy::Bool), Constant::Bool(false));
        assert_eq!(spell(2, TrustIrTy::Bool), Constant::Int(2));
        assert_eq!(
            spell(i128::from(1.5f64.to_bits()), TrustIrTy::F64),
            Constant::Float(1.5)
        );
        assert_eq!(
            spell(i128::from(0.25f32.to_bits()), TrustIrTy::F32),
            Constant::Float(0.25)
        );
        // `Cell::new(-3i64)`: unchanged here, `-3` in the canonicalized module.
        assert_eq!(
            spell((1 << 64) - 3, TrustIrTy::I64),
            Constant::Int((1 << 64) - 3)
        );
        assert_eq!(signed_pattern_spelling(&TrustIrTy::I64, (1 << 64) - 3), -3);
        assert_eq!(spell(5, TrustIrTy::U8), Constant::Int(5));
    }

    /// Three queued slice `Iter::next` jobs with no emission: the word-model
    /// drop reads only their names.
    fn word_model_jobs() -> Vec<super::SliceIterNextRefinementJob> {
        (1..=3)
            .map(|index| super::SliceIterNextRefinementJob {
                name: format!("sliceiternext:v{index}"),
                emitted: Vec::new(),
                self_base: super::ValueId::new(1),
                dest_base: super::ValueId::new(2),
                elem_size: 8,
                end_off: 8,
                tag_off: 0,
            })
            .collect()
    }

    fn word_model_job_names(jobs: &[super::SliceIterNextRefinementJob]) -> Vec<&str> {
        jobs.iter().map(|job| job.name.as_str()).collect()
    }

    /// A pointer-word value lane's queued jobs are dropped (no obligation, no
    /// coverage) by the default lanes in a 4-byte-pointer session and kept
    /// untouched in an 8-byte one; an empty queue is left alone in both.
    #[test]
    fn word_model_drain_clears_jobs_only_outside_an_eight_byte_session() {
        let mut jobs = word_model_jobs();
        super::drop_jobs_outside_word_model_at(8, &mut jobs, false, false, "f")
            .expect("the default lanes never refuse");
        assert_eq!(
            word_model_job_names(&jobs),
            ["sliceiternext:v1", "sliceiternext:v2", "sliceiternext:v3"],
            "an 8-byte-pointer session keeps its jobs"
        );
        super::drop_jobs_outside_word_model_at(4, &mut jobs, false, false, "f")
            .expect("the default lanes never refuse");
        assert!(jobs.is_empty(), "a 4-byte-pointer session states nothing");
        let mut none: Vec<super::SliceIterNextRefinementJob> = Vec::new();
        super::drop_jobs_outside_word_model_at(4, &mut none, false, true, "f")
            .expect("the default lanes never refuse");
        assert!(none.is_empty());
    }

    /// The strict lane refuses a queued pointer-word job its word model does
    /// not describe, naming the lane, the symbol, the first job and the
    /// session width, instead of dropping it; an 8-byte session and an empty
    /// queue pass untouched.
    #[test]
    fn strict_word_model_drain_refuses_jobs_outside_an_eight_byte_session() {
        let mut jobs = word_model_jobs();
        super::drop_jobs_outside_word_model_at(8, &mut jobs, true, false, "f")
            .expect("an 8-byte-pointer session states every obligation");
        assert_eq!(jobs.len(), 3, "an 8-byte-pointer session keeps its jobs");
        let err = super::drop_jobs_outside_word_model_at(4, &mut jobs, true, false, "f")
            .expect_err("the strict lane must not drop a queued job");
        for needle in [
            "[TCG-REFINE-SHAPE]",
            "f: slice Iter::next refinement job sliceiternext:v1",
            "4-byte-pointer session",
        ] {
            assert!(err.contains(needle), "{needle:?} missing from {err}");
        }
        let mut none: Vec<super::SliceIterNextRefinementJob> = Vec::new();
        super::drop_jobs_outside_word_model_at(4, &mut none, true, false, "f")
            .expect("an empty queue has nothing to refuse");
    }

    /// A value-lane job whose builder states an EMPTY obligation set.
    struct EmptyObligationSetJob;

    impl super::TvValueJob for EmptyObligationSetJob {
        const LANE: &'static str = "empty-set";

        fn name(&self) -> &str {
            "emptyset:v1"
        }

        fn obligations(
            &self,
            _pointer_bytes: u64,
        ) -> Result<Vec<trust_cg_verify::ProofObligation>, &'static str> {
            Ok(Vec::new())
        }
    }

    /// An empty obligation set would credit a job nothing was checked for, so
    /// it is an unstated job: the strict lane refuses it with
    /// `[TCG-REFINE-SHAPE]` and the default lanes skip it, traced or not.
    #[test]
    fn empty_obligation_set_is_an_unstated_job() {
        let err = super::tv_value_job_obligations(&EmptyObligationSetJob, true, false, "f", 8)
            .expect_err("the strict lane must not credit an empty obligation set");
        for needle in [
            "[TCG-REFINE-SHAPE] f: empty-set refinement job emptyset:v1",
            "the obligation builder stated an empty set",
        ] {
            assert!(err.contains(needle), "{needle:?} missing from {err}");
        }
        for trace in [false, true] {
            let skipped =
                super::tv_value_job_obligations(&EmptyObligationSetJob, false, trace, "f", 8)
                    .expect("the default lanes never refuse");
            assert!(skipped.is_none(), "the default lanes state nothing for it");
        }
    }

    /// The scalar-rvalue lane's way to state nothing for a queued job, an
    /// encoder that cannot state the MIR meaning (`check_rvalue_lowering`
    /// returns `Err` before any solver call), goes through the shared policy
    /// exactly as its drain composes it: the strict lane refuses the job with
    /// `[TCG-REFINE-SHAPE]` naming the lane, the symbol, the job and the
    /// encoder's reason, and the default lanes skip it, traced or not.
    #[test]
    fn strict_lane_refuses_scalar_rvalue_encoder_misses() {
        use trust_cg_verify::mir_semantics::{BridgeLowering, MirRvalue, check_rvalue_lowering};
        let job = "aggregate:zst";
        // A field-less aggregate is outside the encoder's scalar slice.
        let encoder = check_rvalue_lowering(
            job,
            &MirRvalue::Aggregate { fields: Vec::new() },
            &BridgeLowering::Use {
                operand: trust_cg_verify::SmtExpr::bv_const(0, 8),
            },
            &trust_cg_verify::ay_bridge::AYConfig::default(),
        )
        .expect_err("a field-less aggregate is out of the encoder's slice");
        let what = format!("encoder: {encoder}");
        let err = super::refinement_job_unmodeled(true, false, "f", "scalar rvalue", job, &what)
            .expect_err("the strict lane must not skip the job");
        for needle in [
            "[TCG-REFINE-SHAPE] f: scalar rvalue refinement job aggregate:zst",
            "encoder: MIR Aggregate with no fields is out of slice (ZST)",
        ] {
            assert!(err.contains(needle), "{needle:?} missing from {err}");
        }
        for trace in [false, true] {
            super::refinement_job_unmodeled(false, trace, "f", "scalar rvalue", job, &what)
                .expect("the default lanes skip it");
        }
    }

    /// The two halves of the one `FnAbi::args` index must meet: the DECLARATION
    /// adds `closure_env_abi_index_offset` to its own `inputs` index, and the
    /// BODY reads `rustc_fn_abi_arg_index_for_mir_arg` from its MIR local. For a
    /// closure body whose zero-sized env the declaration dropped, the first real
    /// parameter is `inputs[0]` and MIR local `_2`, and BOTH must name rustc's
    /// argument 1 — the env stays `FnAbi::args[0]` on rustc's side.
    ///
    /// Pins the 2026-09-22 defect: the body half used to subtract a second 1 and
    /// the two halves named arguments 0 and 0 of a three-argument `FnAbi`, so the
    /// gate compared the closure ENV against the first real parameter and refused
    /// with "Report this — it is a bridge bug".
    #[test]
    fn the_declaration_and_the_body_name_the_same_rustc_fn_abi_argument() {
        use super::rustc_fn_abi_arg_index_for_mir_arg;
        use rustc_middle::mir::Local;
        // Env DROPPED: declaration `inputs` = [A, B]; MIR locals `_1` (the ZST
        // env), `_2` = A, `_3` = B; rustc's args = [env, A, B].
        let dropped_env_offset = 1;
        assert_eq!(0 + dropped_env_offset, 1);
        assert_eq!(rustc_fn_abi_arg_index_for_mir_arg(Local::new(2)), Some(1));
        assert_eq!(1 + dropped_env_offset, 2);
        assert_eq!(rustc_fn_abi_arg_index_for_mir_arg(Local::new(3)), Some(2));
        // Env PRESENT (`Fn`/`FnMut`, an ordinary fn, a shim, a coroutine resume
        // body): no offset, and MIR `_1` is rustc's argument 0.
        let no_offset = 0;
        assert_eq!(0 + no_offset, 0);
        assert_eq!(rustc_fn_abi_arg_index_for_mir_arg(Local::new(1)), Some(0));
        // `_0` is the return place, never an argument.
        assert_eq!(rustc_fn_abi_arg_index_for_mir_arg(Local::new(0)), None);
    }

    #[test]
    fn layout_error_callback_uses_rustc_fatal_diagnostic() {
        // This selects a test subprocess; it is not a Trust compiler control.
        const CHILD: &str = "BRIDGE_LAYOUT_ERROR_CALLBACK_TEST_CHILD";
        if std::env::var_os(CHILD).is_some() {
            extern crate rustc_interface;

            struct LayoutErrorCallbacks;
            impl rustc_driver::Callbacks for LayoutErrorCallbacks {
                fn config(&mut self, config: &mut rustc_interface::interface::Config) {
                    config.input = rustc_session::config::Input::Str {
                        name: rustc_span::FileName::Custom("layout_callback.rs".to_owned()),
                        input: "pub fn answer() -> u8 { 42 }".to_owned(),
                    };
                }

                fn after_analysis<'tcx>(
                    &mut self,
                    _compiler: &rustc_interface::interface::Compiler,
                    tcx: TyCtxt<'tcx>,
                ) -> rustc_driver::Compilation {
                    use rustc_middle::ty::layout::{LayoutError, LayoutOfHelpers};
                    // Exercise the actual backend callback, not a source case
                    // that rustc could reject before reaching the backend.
                    LayoutCx(tcx).handle_layout_err(
                        LayoutError::SizeOverflow(tcx.types.u8),
                        rustc_span::DUMMY_SP,
                        tcx.types.u8,
                    )
                }
            }

            let sysroot = std::process::Command::new(BUILD_COMPILER)
                .args(["--print", "sysroot"])
                .output()
                .expect("resolve pinned test sysroot");
            assert!(
                sysroot.status.success(),
                "{}",
                String::from_utf8_lossy(&sysroot.stderr)
            );
            let args = vec![
                "rustc".to_owned(),
                "--crate-type=lib".to_owned(),
                "--emit=metadata".to_owned(),
                "--sysroot".to_owned(),
                String::from_utf8(sysroot.stdout).unwrap().trim().to_owned(),
                "-".to_owned(),
            ];
            // This catches rustc's typed FatalError only. An ordinary panic is
            // resumed and fails this child test, as the previous handler did.
            let result = rustc_driver::catch_fatal_errors(|| {
                rustc_driver::run_compiler(&args, &mut LayoutErrorCallbacks);
            });
            assert!(result.is_err(), "layout failure must stop compilation");
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::layout_error_callback_uses_rustc_fatal_diagnostic",
                "--nocapture",
            ])
            .env(CHILD, "1")
            .output()
            .expect("run isolated layout callback regression");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(output.status.success(), "{stderr}");
        assert!(
            stderr.contains("trust-cg memory model: layout_of(u8) failed: SizeOverflow(u8)"),
            "{stderr}"
        );
        assert!(!stderr.contains("panicked"), "{stderr}");
        assert!(!stderr.contains("internal compiler error"), "{stderr}");
    }

    /// PIN: the two fat-pointer leaf predicates, on REAL rustc types.
    ///
    /// `scalar_leaf_trust_ir_fields` refuses a wide-pointer leaf so it can never
    /// be bound into ONE pointer-width lane (which would drop the metadata half
    /// and shift every later field of the aggregate by 8 bytes — the miscompile
    /// `3b9b89a8` closed for `&[T]`/`&str` struct fields). That refusal is only
    /// as good as the predicate under it, and the predicate is the thing a
    /// future `Dynamic` arm in `rust_ty_to_trust_ir_ty_inner` can silently
    /// invalidate: today a `&dyn Trait` leaf escapes single-lane binding ONLY
    /// because that mapping happens to fail, not because anything tested it.
    ///
    /// So both predicates are pinned against a real `TyCtxt`. A struct with an
    /// unsized TAIL used to be the case that separated them: `&Dst` (a `[u8]`
    /// tail) was a wide pointer the KIND predicate answered `false` for and the
    /// LAYOUT predicate `true`. Both tail forms have since been taught to the kind
    /// predicate — `slice_tail::is_pointer` (56b557ea4) and `dyn_tail::is_pointer`
    /// (rustc's `struct_tail_for_codegen`) — and Rust has exactly those two
    /// pointer-metadata kinds, so the two predicates now AGREE on every wide
    /// pointer; the tail rows pin that agreement for both kinds. The guard stays
    /// spelled with the layout predicate, and the never-narrower assertion below
    /// is what fails if a kind predicate ever drifts past it.
    #[test]
    fn fat_pointer_leaf_predicates_match_rustc_layout() {
        // This selects a test subprocess; it is not a Trust compiler control.
        const CHILD: &str = "BRIDGE_FAT_LEAF_PREDICATE_TEST_CHILD";

        // `'static` everywhere: the signature's regions are then early-bound, so
        // `skip_binder` yields no escaping `ReBound` for the sizedness query.
        const PROBE: &str = "\
            pub trait Tr { fn t(&self) -> u8; }\n\
            pub struct Dst(pub u32, pub [u8]);\n\
            pub struct DynTail(pub u32, pub dyn Tr);\n\
            pub fn probe(\n\
                _a: &'static dyn Tr,\n\
                _b: &'static [u32],\n\
                _c: &'static str,\n\
                _d: &'static Dst,\n\
                _e: *const [u8],\n\
                _f: &'static u32,\n\
                _g: *const u32,\n\
                _h: usize,\n\
                _i: &'static DynTail,\n\
            ) {}\n";

        // (index in `probe`'s signature, kind-predicate answer, layout-predicate
        // answer). The tail rows (`&Dst`, `&DynTail`) are where the two used to
        // DISAGREE; the rows where both are `false` are the controls that keep
        // the layout predicate from being a blanket refusal of every pointer.
        const EXPECTED: &[(usize, bool, bool, &str)] = &[
            (0, true, true, "&dyn Tr"),
            (1, true, true, "&[u32]"),
            (2, true, true, "&str"),
            (3, true, true, "&Dst (struct with a [u8] tail)"),
            (4, true, true, "*const [u8]"),
            (5, false, false, "&u32"),
            (6, false, false, "*const u32"),
            (7, false, false, "usize"),
            (8, true, true, "&DynTail (struct with a dyn tail)"),
        ];

        if std::env::var_os(CHILD).is_some() {
            extern crate rustc_interface;

            struct PredicateCallbacks;
            impl rustc_driver::Callbacks for PredicateCallbacks {
                fn config(&mut self, config: &mut rustc_interface::interface::Config) {
                    config.input = rustc_session::config::Input::Str {
                        name: rustc_span::FileName::Custom("fat_leaf_predicate.rs".to_owned()),
                        input: PROBE.to_owned(),
                    };
                }

                fn after_analysis<'tcx>(
                    &mut self,
                    _compiler: &rustc_interface::interface::Compiler,
                    tcx: TyCtxt<'tcx>,
                ) -> rustc_driver::Compilation {
                    let probe = tcx
                        .hir_body_owners()
                        .find(|def_id| tcx.item_name(def_id.to_def_id()).as_str() == "probe")
                        .expect("the probe fn is in the compiled crate");
                    let sig = tcx.fn_sig(probe).instantiate_identity().skip_binder();
                    let inputs = sig.inputs();
                    assert_eq!(inputs.len(), EXPECTED.len(), "probe arity drifted");
                    for &(index, kind_expected, layout_expected, what) in EXPECTED {
                        let ty = inputs[index];
                        assert_eq!(
                            super::is_fat_pointer_memory_leaf_ty(ty),
                            kind_expected,
                            "is_fat_pointer_memory_leaf_ty({what} = {ty:?})"
                        );
                        assert_eq!(
                            super::is_wide_pointer_memory_leaf_ty(tcx, ty),
                            layout_expected,
                            "is_wide_pointer_memory_leaf_ty({what} = {ty:?})"
                        );
                        // The layout predicate must never be NARROWER than the
                        // kind one: the guard is spelled with the layout one, so
                        // a kind-fat leaf it missed would be a regression of the
                        // refusal `3b9b89a8` landed.
                        assert!(
                            !kind_expected || layout_expected,
                            "layout predicate is narrower than the kind predicate for {what}"
                        );
                    }
                    eprintln!("fat-leaf predicate rows checked: {}", EXPECTED.len());
                    rustc_driver::Compilation::Stop
                }
            }

            let sysroot = std::process::Command::new(BUILD_COMPILER)
                .args(["--print", "sysroot"])
                .output()
                .expect("resolve pinned test sysroot");
            assert!(
                sysroot.status.success(),
                "{}",
                String::from_utf8_lossy(&sysroot.stderr)
            );
            let args = vec![
                "rustc".to_owned(),
                "--crate-type=lib".to_owned(),
                "--emit=metadata".to_owned(),
                "--sysroot".to_owned(),
                String::from_utf8(sysroot.stdout).unwrap().trim().to_owned(),
                "-".to_owned(),
            ];
            rustc_driver::run_compiler(&args, &mut PredicateCallbacks);
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::fat_pointer_leaf_predicates_match_rustc_layout",
                "--nocapture",
            ])
            .env(CHILD, "1")
            .output()
            .expect("run isolated fat-leaf predicate pin");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(output.status.success(), "{stderr}");
        // A child that never reached `after_analysis` would also exit 0. Require
        // the proof that every row actually ran: a SILENT instrument reads as a
        // clean result.
        assert!(
            stderr.contains(&format!(
                "fat-leaf predicate rows checked: {}",
                EXPECTED.len()
            )),
            "the predicate rows never ran: {stderr}"
        );
        assert!(!stderr.contains("panicked"), "{stderr}");
    }

    /// PIN: a parameter whose pointee has a `dyn Trait` TAIL (`&Tagged<dyn Erased>`,
    /// the `core::error::Request` shape) is checked against rustc's own `FnAbi`
    /// by `classify_func_ty`'s `dyn_tail` branch.
    ///
    /// That branch used to sit AFTER the `is_vtable_pair_abi_ref_ty` branch, whose
    /// predicate includes every `dyn_tail` pointer, so the check never ran and the
    /// `[TCG-ARG-ABI]` refusal could not fire for these types. The pin hands
    /// `classify_func_ty` the dyn-tailed input with the `FnAbi` of a DIFFERENT
    /// signature (`fn(&'static u32)`): only a check that actually reads rustc's
    /// argument can notice the disagreement. The control is the same input with its
    /// own `FnAbi`, which must still classify as two `Ptr` lanes.
    #[test]
    fn dyn_tail_pointer_parameter_is_checked_against_rustc_fn_abi() {
        // This selects a test subprocess; it is not a Trust compiler control.
        const CHILD: &str = "BRIDGE_DYN_TAIL_PARAM_ABI_TEST_CHILD";
        const PROBE: &str = "\
            pub trait Erased { fn e(&self) -> u8; }\n\
            pub struct Tagged<E: ?Sized> { pub tag: u64, pub e: E }\n\
            pub fn probe(_t: &'static Tagged<dyn Erased>) {}\n\
            pub fn other(_x: &'static u32) {}\n";

        if std::env::var_os(CHILD).is_some() {
            extern crate rustc_interface;

            struct ProbeCallbacks;
            impl rustc_driver::Callbacks for ProbeCallbacks {
                fn config(&mut self, config: &mut rustc_interface::interface::Config) {
                    config.input = rustc_session::config::Input::Str {
                        name: rustc_span::FileName::Custom("dyn_tail_param_abi.rs".to_owned()),
                        input: PROBE.to_owned(),
                    };
                }

                fn after_analysis<'tcx>(
                    &mut self,
                    _compiler: &rustc_interface::interface::Compiler,
                    tcx: TyCtxt<'tcx>,
                ) -> rustc_driver::Compilation {
                    use super::{MirLoweringCtx, RustcFnAbiSource};
                    let find = |name: &str| {
                        tcx.hir_body_owners()
                            .find(|def_id| tcx.item_name(def_id.to_def_id()).as_str() == name)
                            .unwrap_or_else(|| panic!("the {name} fn is in the compiled crate"))
                            .to_def_id()
                    };
                    let probe = find("probe");
                    let other = find("other");
                    let probe_sig = tcx
                        .fn_sig(probe)
                        .instantiate_identity()
                        .skip_normalization();
                    let other_sig = tcx
                        .fn_sig(other)
                        .instantiate_identity()
                        .skip_normalization();
                    let input = probe_sig.skip_binder().inputs()[0];
                    assert_eq!(
                        super::dyn_tail::metadata_offset(tcx, input),
                        Some(8),
                        "`{input:?}` must be a dyn-tailed pointer, or this row tests nothing"
                    );
                    let instance = Instance::mono(tcx, probe);
                    let classify = |source: RustcFnAbiSource<'tcx>| {
                        let mut ctx = MirLoweringCtx::new("dyn_tail_param_abi", tcx, instance);
                        ctx.classify_func_ty(
                            &[input],
                            tcx.types.unit,
                            false,
                            false,
                            None,
                            source,
                            0,
                            false,
                        )
                        .map(|func_ty| ctx.module.func_type(func_ty).cloned())
                    };
                    let own = classify(RustcFnAbiSource::Instance(instance))
                        .expect("the dyn-tailed parameter agrees with its own FnAbi");
                    assert_eq!(
                        own.map(|func_ty| func_ty.params),
                        Some(vec![TrustIrTy::Ptr, TrustIrTy::Ptr]),
                        "the declared shape is two `Ptr` lanes"
                    );
                    let err = classify(RustcFnAbiSource::FnPtr(other_sig))
                        .expect_err("a FnAbi describing another argument must be refused");
                    assert!(err.contains("[TCG-ARG-ABI]"), "{err}");
                    eprintln!("dyn-tail parameter FnAbi check ran: {err}");
                    rustc_driver::Compilation::Stop
                }
            }

            let sysroot = std::process::Command::new(BUILD_COMPILER)
                .args(["--print", "sysroot"])
                .output()
                .expect("resolve pinned test sysroot");
            assert!(
                sysroot.status.success(),
                "{}",
                String::from_utf8_lossy(&sysroot.stderr)
            );
            let args = vec![
                "rustc".to_owned(),
                "--crate-type=lib".to_owned(),
                "--emit=metadata".to_owned(),
                "--sysroot".to_owned(),
                String::from_utf8(sysroot.stdout).unwrap().trim().to_owned(),
                "-".to_owned(),
            ];
            rustc_driver::run_compiler(&args, &mut ProbeCallbacks);
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::dyn_tail_pointer_parameter_is_checked_against_rustc_fn_abi",
                "--nocapture",
            ])
            .env(CHILD, "1")
            .output()
            .expect("run isolated dyn-tail parameter FnAbi pin");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(output.status.success(), "{stderr}");
        // A child that never reached `after_analysis` also exits 0.
        assert!(
            stderr.contains("dyn-tail parameter FnAbi check ran: "),
            "the FnAbi rows never ran: {stderr}"
        );
        assert!(!stderr.contains("panicked"), "{stderr}");
    }

    /// PIN: a method DEFINED in `impl<'a> Iterator for Chars<'a>` is not a dead
    /// std body when `Chars` is the certified cursor.
    ///
    /// The `[TCG-STRIDE-ITER-METHOD]` guard lets a certified `Chars` reach std's
    /// own `size_hint`, which `lower_iterator_call` does not intercept, so that
    /// body is REACHED. Its instance arguments are only the erased lifetime, so an
    /// exclusion keyed on `args.types().next()` never saw `Chars`, and the
    /// `::size_hint` suffix classified the body as dead: any lowering or proof
    /// failure of it became a `ud2` stub the program calls. The control row keeps
    /// the classifier from being disabled wholesale: `<Range<usize> as
    /// Iterator>::size_hint` is still a dead-body candidate.
    #[test]
    fn certified_chars_impl_methods_are_not_dead_bodies() {
        // This selects a test subprocess; it is not a Trust compiler control.
        const CHILD: &str = "BRIDGE_CHARS_DEAD_BODY_TEST_CHILD";
        const PROBE: &str = "\
            pub fn probe(_c: core::str::Chars<'static>, _r: core::ops::Range<usize>) {}\n";

        if std::env::var_os(CHILD).is_some() {
            extern crate rustc_interface;

            struct ProbeCallbacks;
            impl rustc_driver::Callbacks for ProbeCallbacks {
                fn config(&mut self, config: &mut rustc_interface::interface::Config) {
                    config.input = rustc_session::config::Input::Str {
                        name: rustc_span::FileName::Custom("chars_dead_body.rs".to_owned()),
                        input: PROBE.to_owned(),
                    };
                }

                fn after_analysis<'tcx>(
                    &mut self,
                    _compiler: &rustc_interface::interface::Compiler,
                    tcx: TyCtxt<'tcx>,
                ) -> rustc_driver::Compilation {
                    let probe = tcx
                        .hir_body_owners()
                        .find(|def_id| tcx.item_name(def_id.to_def_id()).as_str() == "probe")
                        .expect("the probe fn is in the compiled crate");
                    let sig = tcx.fn_sig(probe).instantiate_identity().skip_binder();
                    let chars = tcx.erase_and_anonymize_regions(sig.inputs()[0]);
                    let range = tcx.erase_and_anonymize_regions(sig.inputs()[1]);
                    assert!(
                        super::is_certified_chars_cursor(tcx, chars),
                        "`{chars:?}` must be the certified cursor, or this row tests nothing"
                    );
                    let iterator = tcx
                        .get_diagnostic_item(rustc_span::sym::Iterator)
                        .expect("the Iterator trait");
                    let size_hint = tcx
                        .associated_items(iterator)
                        .in_definition_order()
                        .find(|item| item.is_fn() && item.name().as_str() == "size_hint")
                        .expect("Iterator::size_hint")
                        .def_id;
                    let resolve = |self_ty: Ty<'tcx>| {
                        Instance::try_resolve(
                            tcx,
                            ty::TypingEnv::fully_monomorphized(),
                            size_hint,
                            tcx.mk_args(&[self_ty.into()]),
                        )
                        .expect("resolve size_hint")
                        .expect("size_hint has an instance")
                    };
                    let chars_size_hint = resolve(chars);
                    assert!(
                        chars_size_hint.args.types().next().is_none(),
                        "the impl-defined method carries no Self type argument: \
                         {chars_size_hint:?}"
                    );
                    assert!(
                        !super::is_dead_std_iterator_reduction_body(tcx, chars_size_hint),
                        "a certified `Chars` size_hint is reached and must never be trapped"
                    );
                    assert!(
                        super::is_dead_std_iterator_reduction_body(tcx, resolve(range)),
                        "`Range<usize>::size_hint` must remain a dead-body candidate"
                    );
                    eprintln!("certified-Chars dead-body rows checked: 2");
                    rustc_driver::Compilation::Stop
                }
            }

            let sysroot = std::process::Command::new(BUILD_COMPILER)
                .args(["--print", "sysroot"])
                .output()
                .expect("resolve pinned test sysroot");
            assert!(
                sysroot.status.success(),
                "{}",
                String::from_utf8_lossy(&sysroot.stderr)
            );
            let args = vec![
                "rustc".to_owned(),
                "--crate-type=lib".to_owned(),
                "--emit=metadata".to_owned(),
                "--sysroot".to_owned(),
                String::from_utf8(sysroot.stdout).unwrap().trim().to_owned(),
                "-".to_owned(),
            ];
            rustc_driver::run_compiler(&args, &mut ProbeCallbacks);
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::certified_chars_impl_methods_are_not_dead_bodies",
                "--nocapture",
            ])
            .env(CHILD, "1")
            .output()
            .expect("run isolated certified-Chars dead-body pin");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(output.status.success(), "{stderr}");
        // A child that never reached `after_analysis` also exits 0.
        assert!(
            stderr.contains("certified-Chars dead-body rows checked: 2"),
            "the dead-body rows never ran: {stderr}"
        );
        assert!(!stderr.contains("panicked"), "{stderr}");
    }

    /// PIN: the const struct/tuple writer binds each leaf under the key the
    /// projected-field READER uses.
    ///
    /// A single-leaf wrapper field (`Wrapping<u32>`) puts the recursive flat
    /// binding in force, so `projected_field_index` keys MIR field `k` by its
    /// FLAT leaf index, and a zero-sized field contributes no leaf. For
    /// `S { m: M, a: Wrapping<u32>, b: u32 }` the read of `s.b` (MIR 2) is keyed
    /// flat 1, and `lower_const_scalarized_struct_or_tuple_use` used to bind MIR
    /// keys 1 and 2, so key 1 held `a`'s value: a same-typed sibling leaf.
    ///
    /// The lane is driven directly on the probe's real MIR (`_1 = const ..;
    /// _0 = copy (_1.2: u32)`), because a whole program does not isolate it:
    /// measured on aarch64-apple-darwin, `compute_memory_backed_locals` (rule Nc)
    /// memory-backs a two-leaf `_1 = const ..` local, and a one-leaf const is a
    /// `ConstValue::Scalar` this lane declines.
    #[test]
    fn const_struct_writer_binds_the_readers_flat_key() {
        // This selects a test subprocess; it is not a Trust compiler control.
        const CHILD: &str = "BRIDGE_CONST_FLAT_KEY_TEST_CHILD";
        const PROBE: &str = "\
            pub struct M;\n\
            pub struct S { pub m: M, pub a: core::num::Wrapping<u32>, pub b: u32 }\n\
            pub const CS: S = S { m: M, a: core::num::Wrapping(3), b: 10 };\n\
            pub const CT: (M, core::num::Wrapping<u32>, u32) = (M, core::num::Wrapping(5), 17);\n\
            pub fn struct_b() -> u32 { let s = CS; s.b }\n\
            pub fn tuple_2() -> u32 { let t = CT; t.2 }\n";
        // (probe fn, flat key of the read, the const value that key must hold)
        const ROWS: &[(&str, u32, i128)] = &[("struct_b", 1, 10), ("tuple_2", 1, 17)];

        if std::env::var_os(CHILD).is_some() {
            extern crate rustc_interface;

            struct ProbeCallbacks;
            impl rustc_driver::Callbacks for ProbeCallbacks {
                fn config(&mut self, config: &mut rustc_interface::interface::Config) {
                    config.input = rustc_session::config::Input::Str {
                        name: rustc_span::FileName::Custom("const_flat_key.rs".to_owned()),
                        input: PROBE.to_owned(),
                    };
                }

                fn after_analysis<'tcx>(
                    &mut self,
                    _compiler: &rustc_interface::interface::Compiler,
                    tcx: TyCtxt<'tcx>,
                ) -> rustc_driver::Compilation {
                    use rustc_middle::mir::{BasicBlock, Operand, Rvalue, StatementKind};
                    for &(name, want_key, want_value) in ROWS {
                        let def_id = tcx
                            .hir_body_owners()
                            .find(|def_id| tcx.item_name(def_id.to_def_id()).as_str() == name)
                            .unwrap_or_else(|| panic!("the {name} fn is in the compiled crate"))
                            .to_def_id();
                        let instance = Instance::mono(tcx, def_id);
                        let body = tcx.instance_mir(instance.def);
                        let statements = &body.basic_blocks[BasicBlock::from_u32(0)].statements;
                        let mut constant_use = None;
                        let mut field_read = None;
                        for statement in statements {
                            let StatementKind::Assign(assign) = &statement.kind else {
                                continue;
                            };
                            match &assign.1 {
                                Rvalue::Use(operand @ Operand::Constant(_), _) => {
                                    constant_use = Some((assign.0, operand.clone()));
                                }
                                Rvalue::Use(Operand::Copy(place), _) => field_read = Some(*place),
                                _ => {}
                            }
                        }
                        let (dest, operand) =
                            constant_use.unwrap_or_else(|| panic!("{name}: no `_l = const ..`"));
                        let read = field_read.unwrap_or_else(|| panic!("{name}: no field read"));
                        let mut ctx = super::MirLoweringCtx::new("const_flat_key", tcx, instance);
                        let mut block = Block::new(BlockId::new(0));
                        let lowered = super::lower_const_scalarized_struct_or_tuple_use(
                            &mut ctx, body, &mut block, &dest, &operand,
                        )
                        .unwrap_or_else(|e| panic!("{name}: the const lane errored: {e}"));
                        assert!(lowered, "{name}: the const struct/tuple lane declined");
                        let key = super::projected_field_index(&ctx, &read)
                            .unwrap_or_else(|e| panic!("{name}: reader key: {e}"));
                        assert_eq!(key, Some(want_key), "{name}: the reader's key for {read:?}");
                        let value = *ctx
                            .projected_values
                            .get(&(read.local, want_key))
                            .unwrap_or_else(|| panic!("{name}: nothing bound at key {want_key}"));
                        let bound = block
                            .body
                            .iter()
                            .find(|node| node.results.contains(&value))
                            .map(|node| &node.inst);
                        assert!(
                            matches!(
                                bound,
                                Some(Inst::Const { value: Constant::Int(v), .. }) if *v == want_value
                            ),
                            "{name}: key {want_key} must hold the const {want_value}, got {bound:?}"
                        );
                    }
                    eprintln!("const flat-key rows checked: {}", ROWS.len());
                    rustc_driver::Compilation::Stop
                }
            }

            let sysroot = std::process::Command::new(BUILD_COMPILER)
                .args(["--print", "sysroot"])
                .output()
                .expect("resolve pinned test sysroot");
            assert!(
                sysroot.status.success(),
                "{}",
                String::from_utf8_lossy(&sysroot.stderr)
            );
            let args = vec![
                "rustc".to_owned(),
                "--crate-type=lib".to_owned(),
                "--emit=metadata".to_owned(),
                "--sysroot".to_owned(),
                String::from_utf8(sysroot.stdout).unwrap().trim().to_owned(),
                "-".to_owned(),
            ];
            rustc_driver::run_compiler(&args, &mut ProbeCallbacks);
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::const_struct_writer_binds_the_readers_flat_key",
                "--nocapture",
            ])
            .env(CHILD, "1")
            .output()
            .expect("run isolated const flat-key pin");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(output.status.success(), "{stderr}");
        // A child that never reached `after_analysis` also exits 0.
        assert!(
            stderr.contains(&format!("const flat-key rows checked: {}", ROWS.len())),
            "the const flat-key rows never ran: {stderr}"
        );
        assert!(!stderr.contains("panicked"), "{stderr}");
    }

    /// PIN: `coerce_to_i64` returns an `emit_i64_const` result unchanged and
    /// copies every other value.
    ///
    /// A same-type `Copy { ty: I64 }` of an emitted constant hides the constant
    /// from ISel, so a constant field offset `base + K` costs a register
    /// materialization and a register-register add (the check-elision kit's
    /// `mr_grid_stencil` safe arm: 209 static instructions with the Copy, 175
    /// without). Both spellings compute the same value, so no differential
    /// fails if the Copy comes back; this pins the spelling. It also pins the
    /// set's per-body scope: after `seed_values_from_body`, an id the previous
    /// body recorded is copied like any other value.
    #[test]
    fn coerce_to_i64_passes_an_emitted_i64_const_through() {
        // This selects a test subprocess; it is not a Trust compiler control.
        const CHILD: &str = "BRIDGE_COERCE_I64_CONST_TEST_CHILD";
        const PROBE: &str = "pub fn word(x: u64) -> u64 { x }\n";
        const MARKER: &str = "coerce_to_i64 const rows checked: 3";

        if std::env::var_os(CHILD).is_some() {
            extern crate rustc_interface;

            struct ProbeCallbacks;
            impl rustc_driver::Callbacks for ProbeCallbacks {
                fn config(&mut self, config: &mut rustc_interface::interface::Config) {
                    config.input = rustc_session::config::Input::Str {
                        name: rustc_span::FileName::Custom("coerce_i64_const.rs".to_owned()),
                        input: PROBE.to_owned(),
                    };
                }

                fn after_analysis<'tcx>(
                    &mut self,
                    _compiler: &rustc_interface::interface::Compiler,
                    tcx: TyCtxt<'tcx>,
                ) -> rustc_driver::Compilation {
                    let def_id = tcx
                        .hir_body_owners()
                        .find(|def_id| tcx.item_name(def_id.to_def_id()).as_str() == "word")
                        .expect("the word fn is in the compiled crate")
                        .to_def_id();
                    let instance = Instance::mono(tcx, def_id);
                    let body = tcx.instance_mir(instance.def);
                    let mut ctx = super::MirLoweringCtx::new("coerce_i64_const", tcx, instance);
                    ctx.seed_values_from_body(body);
                    let is_copy_of = |node: &InstrNode, operand: ValueId| {
                        matches!(
                            node.inst,
                            Inst::Copy { ty: TrustIrTy::I64, operand: o } if o == operand
                        )
                    };

                    // An emitted constant passes through: no node is added.
                    let mut block = Block::new(BlockId::new(0));
                    let k = super::emit_i64_const(&mut ctx, &mut block, 16);
                    let nodes = block.body.len();
                    assert_eq!(super::coerce_to_i64(&mut ctx, &mut block, k), k);
                    assert_eq!(block.body.len(), nodes, "a node was added for {k:?}");

                    // Any other value gets its Copy.
                    let other = ctx.fresh_value();
                    let copied = super::coerce_to_i64(&mut ctx, &mut block, other);
                    assert_ne!(copied, other);
                    let last = block.body.last().expect("the Copy node");
                    assert!(
                        last.results.contains(&copied) && is_copy_of(last, other),
                        "{other:?} is not copied to {copied:?}"
                    );

                    // A new body restarts the value ids, so the old constant's id
                    // no longer names a constant and is copied. The Copy's own
                    // fresh result can carry the same number as `k`, because the
                    // numbering restarted too.
                    ctx.seed_values_from_body(body);
                    let mut next = Block::new(BlockId::new(0));
                    let stale = super::coerce_to_i64(&mut ctx, &mut next, k);
                    assert!(
                        next.body.len() == 1
                            && next.body[0].results.contains(&stale)
                            && is_copy_of(&next.body[0], k),
                        "{k:?} from the previous body is not copied"
                    );

                    eprintln!("{MARKER}");
                    rustc_driver::Compilation::Stop
                }
            }

            let sysroot = std::process::Command::new(BUILD_COMPILER)
                .args(["--print", "sysroot"])
                .output()
                .expect("resolve pinned test sysroot");
            assert!(
                sysroot.status.success(),
                "{}",
                String::from_utf8_lossy(&sysroot.stderr)
            );
            let args = vec![
                "rustc".to_owned(),
                "--crate-type=lib".to_owned(),
                "--emit=metadata".to_owned(),
                "--sysroot".to_owned(),
                String::from_utf8(sysroot.stdout).unwrap().trim().to_owned(),
                "-".to_owned(),
            ];
            rustc_driver::run_compiler(&args, &mut ProbeCallbacks);
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::coerce_to_i64_passes_an_emitted_i64_const_through",
                "--nocapture",
            ])
            .env(CHILD, "1")
            .output()
            .expect("run isolated coerce_to_i64 pin");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(output.status.success(), "{stderr}");
        // A child that never reached `after_analysis` also exits 0.
        assert!(
            stderr.contains(MARKER),
            "the coerce_to_i64 rows never ran: {stderr}"
        );
        assert!(!stderr.contains("panicked"), "{stderr}");
    }

    /// PIN: `scalarized_leaf_binding_keys` names, for every sized scalar leaf, the
    /// key its scalarized aggregate's binder used, and agrees with the projected
    /// field READER (`flat_leaf_field_for_mir_field`, else the MIR index) on every
    /// top-level field that is one leaf. Both are also checked against the
    /// BINDER's own scheme decision, recomputed from the NORMALIZED field types
    /// rustc's layout carries (the view `lower_adt_aggregate` takes after
    /// `monomorphize_ty`): recursive flat when some top-level field is a
    /// scalar-field aggregate, MIR field index otherwise.
    ///
    /// Each row is a shape where the leaf POSITION is not the key, or where an
    /// off-by-one in either direction lands on a bound same-typed sibling:
    /// zero-sized fields first, in the middle, last, first inside a nested field,
    /// a tuple's interior unit, and the `RawVec` nesting (`Unique { pointer,
    /// _marker }`, `Cap`, a zero-sized allocator, an outer marker). The `al_*`
    /// rows declare a field through an associated-type projection (`<u8 as
    /// Tr>::O = W(u32)`, `<u8 as Tr>::Z = Zw`, `T::O` at `T = u8`): unnormalized
    /// they look like single leaves, so a walk that skips normalization picks the
    /// MIR-index scheme where the binder uses the recursive one.
    #[test]
    fn scalarized_leaf_keys_match_the_binders_and_the_reader() {
        // This selects a test subprocess; it is not a Trust compiler control.
        const CHILD: &str = "BRIDGE_ZST_LEAF_KEYS_TEST_CHILD";
        const PROBE: &str = "\
            use std::marker::PhantomData;\n\
            pub struct Zs;\n\
            pub struct N1 { pub zf: (), pub p: u32, pub q: u32 }\n\
            pub struct Z3 { pub a: u32, pub b: u32, pub p: PhantomData<u32>, pub c: u32 }\n\
            pub struct Deep { pub z0: (), pub a: u8, pub n: N1, pub z1: PhantomData<u16>, \
                pub b: u32, pub t: (Zs, u32, u32, ()), pub c: u16, pub zt: () }\n\
            pub struct Uq { pub p: u64, pub m: PhantomData<u8> }\n\
            pub struct Cap(pub u32);\n\
            pub struct Gl;\n\
            pub struct RvInner { pub ptr: Uq, pub cap: Cap, pub alloc: Gl }\n\
            pub struct Rv { pub inner: RvInner, pub m: PhantomData<u16> }\n\
            pub struct Tail { pub a: u8, pub b: u64, pub z: PhantomData<u32> }\n\
            pub fn n1(_: N1) {}\n\
            pub fn z3(_: Z3) {}\n\
            pub fn tup(_: (u32, (), u32)) {}\n\
            pub fn deep(_: Deep) {}\n\
            pub fn rv_inner(_: RvInner) {}\n\
            pub fn rv(_: Rv) {}\n\
            pub fn tail(_: Tail) {}\n\
            pub fn lead_tup(_: ((), (u8, ()), u16)) {}\n\
            pub trait Tr { type O; type Z; }\n\
            pub struct W(pub u32);\n\
            pub struct Zw { pub m: PhantomData<u8> }\n\
            impl Tr for u8 { type O = W; type Z = Zw; }\n\
            pub struct As { pub z: (), pub a: u32, pub o: <u8 as Tr>::O }\n\
            pub struct At { pub z: <u8 as Tr>::Z, pub a: u32, pub b: u32 }\n\
            pub struct Ag<T: Tr> { pub z: (), pub a: u32, pub o: T::O }\n\
            pub fn al_s(_: As) {}\n\
            pub fn al_t(_: At) {}\n\
            pub fn al_g(_: Ag<u8>) {}\n";
        // (probe fn whose one parameter is the aggregate, the key of each leaf)
        const ROWS: &[(&str, &[u32])] = &[
            ("n1", &[1, 2]),
            ("z3", &[0, 1, 3]),
            ("tup", &[0, 2]),
            ("deep", &[0, 1, 2, 3, 4, 5, 6]),
            ("rv_inner", &[0, 1]),
            ("rv", &[0, 1]),
            ("tail", &[0, 1]),
            ("lead_tup", &[0, 1]),
            ("al_s", &[0, 1]),
            ("al_t", &[0, 1]),
            ("al_g", &[0, 1]),
        ];

        if std::env::var_os(CHILD).is_some() {
            extern crate rustc_interface;

            struct ProbeCallbacks;
            impl rustc_driver::Callbacks for ProbeCallbacks {
                fn config(&mut self, config: &mut rustc_interface::interface::Config) {
                    config.input = rustc_session::config::Input::Str {
                        name: rustc_span::FileName::Custom("zst_leaf_keys.rs".to_owned()),
                        input: PROBE.to_owned(),
                    };
                }

                fn after_analysis<'tcx>(
                    &mut self,
                    _compiler: &rustc_interface::interface::Compiler,
                    tcx: TyCtxt<'tcx>,
                ) -> rustc_driver::Compilation {
                    let cx = LayoutCx(tcx);
                    for &(name, want) in ROWS {
                        let def_id = tcx
                            .hir_body_owners()
                            .find(|def_id| tcx.item_name(def_id.to_def_id()).as_str() == name)
                            .unwrap_or_else(|| panic!("the {name} fn is in the compiled crate"));
                        let sig = tcx.fn_sig(def_id).instantiate_identity().skip_binder();
                        let ty = tcx.erase_and_anonymize_regions(sig.inputs()[0]);
                        let layout = tcx
                            .layout_of(ty::TypingEnv::fully_monomorphized().as_query_input(ty))
                            .unwrap_or_else(|e| panic!("{name}: layout_of: {e:?}"));
                        let mut leaves = Vec::new();
                        assert!(
                            super::enumerate_scalar_leaf_offsets(tcx, &cx, &layout, 0, &mut leaves)
                                .unwrap_or_else(|e| panic!("{name}: leaf walk: {e}"))
                                .is_some(),
                            "{name}: the leaf walk declined"
                        );
                        let keys = super::scalarized_leaf_binding_keys(tcx, ty, leaves.len())
                            .unwrap_or_else(|e| panic!("{name}: key scheme: {e}"));
                        assert_eq!(keys, want, "{name}: the key of each leaf of {ty:?}");
                        // The BINDER's decision, from the layout's normalized field
                        // types and independent of the walks under test.
                        let normalized: Vec<Ty<'tcx>> = (0..layout.fields.count())
                            .map(|i| layout.field(&cx, i).ty)
                            .collect();
                        let binder_recursive = normalized.iter().any(|field_ty| {
                            super::scalar_field_aggregate_trust_ir_fields(tcx, *field_ty)
                                .unwrap_or_else(|e| panic!("{name}: flatten: {e}"))
                                .is_some()
                        });
                        let binder_keys: Vec<u32> = if binder_recursive {
                            (0..leaves.len() as u32).collect()
                        } else {
                            normalized
                                .iter()
                                .enumerate()
                                .filter(|(_, field_ty)| !super::is_zero_sized_ty(tcx, **field_ty))
                                .map(|(index, _)| index as u32)
                                .collect()
                        };
                        assert_eq!(keys, binder_keys, "{name}: the binder's keys for {ty:?}");
                        // The READER's key for every top-level field that is one leaf
                        // must be the key this function gives that leaf.
                        let field_tys = super::recursive_flat_binding_field_tys(tcx, ty)
                            .unwrap_or_else(|| panic!("{name}: no field list"));
                        let mut leaf = 0usize;
                        for (mir_field, field_ty) in field_tys.iter().enumerate() {
                            if super::is_zero_sized_ty(tcx, *field_ty) {
                                continue;
                            }
                            let count =
                                super::scalar_field_aggregate_trust_ir_fields(tcx, *field_ty)
                                    .unwrap_or_else(|e| panic!("{name}: flatten: {e}"))
                                    .map_or(1, |nested| nested.len());
                            if count == 1 {
                                let reader = match super::flat_leaf_field_for_mir_field(
                                    tcx,
                                    ty,
                                    mir_field as u32,
                                )
                                .unwrap_or_else(|e| panic!("{name}: reader: {e}"))
                                {
                                    None => mir_field as u32,
                                    Some(super::FlatLeafField::Leaf(flat)) => flat,
                                    Some(other) => panic!("{name}: field {mir_field}: {other:?}"),
                                };
                                assert_eq!(
                                    reader, keys[leaf],
                                    "{name}: the reader keys MIR field {mir_field} as {reader}"
                                );
                            }
                            leaf += count;
                        }
                        assert_eq!(leaf, keys.len(), "{name}: leaf count");
                    }
                    eprintln!("zst leaf-key rows checked: {}", ROWS.len());
                    rustc_driver::Compilation::Stop
                }
            }

            let sysroot = std::process::Command::new(BUILD_COMPILER)
                .args(["--print", "sysroot"])
                .output()
                .expect("resolve pinned test sysroot");
            assert!(
                sysroot.status.success(),
                "{}",
                String::from_utf8_lossy(&sysroot.stderr)
            );
            let args = vec![
                "rustc".to_owned(),
                "--crate-type=lib".to_owned(),
                "--emit=metadata".to_owned(),
                "--sysroot".to_owned(),
                String::from_utf8(sysroot.stdout).unwrap().trim().to_owned(),
                "-".to_owned(),
            ];
            rustc_driver::run_compiler(&args, &mut ProbeCallbacks);
            return;
        }

        let output = std::process::Command::new(std::env::current_exe().unwrap())
            .args([
                "--exact",
                "tests::scalarized_leaf_keys_match_the_binders_and_the_reader",
                "--nocapture",
            ])
            .env(CHILD, "1")
            .output()
            .expect("run isolated zst leaf-key pin");
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(output.status.success(), "{stderr}");
        // A child that never reached `after_analysis` also exits 0.
        assert!(
            stderr.contains(&format!("zst leaf-key rows checked: {}", ROWS.len())),
            "the zst leaf-key rows never ran: {stderr}"
        );
        assert!(!stderr.contains("panicked"), "{stderr}");
    }

    /// The `TyId` <-> lane-type mapping must round-trip in both directions for
    /// every seeded id, and reject anything outside the seeded range. A slot
    /// type names its element by fixed id; if the two directions disagreed, a
    /// slot would resolve to the WRONG lane width -- silent wrong code, not a
    /// fail-closed error.
    #[test]
    fn slot_lane_ty_ids_round_trip() {
        for index in 0..SLOT_LANE_TY_COUNT {
            let lane = slot_lane_ty_by_id(index).expect("seeded id resolves to a lane");
            assert_eq!(
                slot_lane_ty_id(&lane).map(|id| id.index()),
                Some(index),
                "lane {lane:?} must map back to TyId {index}"
            );
        }
        assert_eq!(slot_lane_ty_by_id(SLOT_LANE_TY_COUNT), None);
        // A non-lane type has no id.
        assert_eq!(slot_lane_ty_id(&TrustIrTy::Ptr), None);
        assert_eq!(slot_lane_ty_id(&TrustIrTy::F64), None);
    }

    /// The fat-pointer slot type must be SPELLED by `memory_slot_lane_ty`, never
    /// by hand. A `Box<dyn Trait>` by-value parameter's entry-block type comes
    /// from `fat_ptr_memory_layout()` and its signature type from the generic
    /// `memory_aggregate_layout` walk, and the adapter compares the two `Ty`s
    /// structurally: a hand-written `Tuple([I64, I64])` here drifted from the
    /// `Array(I64, 2)` spelling and failed every `Box<dyn>` by-value boundary
    /// closed (`[TCG-REGALLOC-063]` on `panic_unwind::imp::panic`). This fails
    /// the moment either side is re-spelled on its own.
    #[test]
    fn fat_ptr_slot_ty_is_the_memory_slot_spelling() {
        let owned = memory_slot_lane_ty(16, 8).expect("16/8 is a valid slot");
        assert_eq!(fat_ptr_slot_ty(), owned);
        assert_eq!(fat_ptr_memory_layout().slot_ty, owned);
        assert_eq!(fat_ptr_memory_layout().size, 16);
        assert_eq!(fat_ptr_memory_layout().align, 8);
    }

    /// WS7.1 (b): the fixed-layout slot writes (`emit_vec_field_store`,
    /// `store_fat_ptr_slot_into`) hard-code "word `k` is at byte `8*k`". Pin that
    /// against the adapter's own layout of the same slot types, which is what the
    /// historical store-form `InsertField` they replace was lowered with — so the
    /// migration to `Store` moves no byte. Also pins the lane-array spelling.
    #[test]
    fn vec_and_fat_ptr_slot_word_stores_match_the_adapter_layout() {
        for (field, ty) in [
            (VEC_FIELD_PTR, TrustIrTy::Ptr),
            (VEC_FIELD_CAP, TrustIrTy::I64),
            (VEC_FIELD_LEN, TrustIrTy::I64),
        ] {
            assert_eq!(
                aggregate_field_store_layout(&vec_slot_ty(), field),
                Ok((ty, 8 * u64::from(field))),
                "vec slot field {field}"
            );
        }
        let lane_array = TrustIrTy::Array(
            slot_lane_ty_id(&TrustIrTy::I64).expect("I64 is a seeded lane"),
            2,
        );
        for slot in [fat_ptr_slot_ty(), lane_array] {
            for lane in [0_u32, 1] {
                assert_eq!(
                    aggregate_field_store_layout(&slot, lane),
                    Ok((TrustIrTy::I64, 8 * u64::from(lane))),
                    "{slot:?} lane {lane}"
                );
            }
            assert!(aggregate_field_store_layout(&slot, 2).is_err(), "{slot:?}");
        }
        // A natural-C tuple with padding: the u8 sits at 0, the u64 at 8 —
        // the adapter's offset, not the field index times a lane width.
        assert_eq!(
            aggregate_field_store_layout(&TrustIrTy::Tuple(vec![TrustIrTy::U8, TrustIrTy::U64]), 1),
            Ok((TrustIrTy::U64, 8))
        );
        // Anything the bridge does not lay out itself fails closed.
        assert!(aggregate_field_store_layout(&TrustIrTy::I64, 0).is_err());
    }

    /// WS7.1 (b), review after the wasm32 port: a field store's byte offset is
    /// the one the CONSUMING lane gave the old store-form `InsertField`, and
    /// the wasm lane lays a pointer out in four bytes where the native adapter
    /// uses eight. The C-rule helper used for wasm32 agrees with the native
    /// adapter at eight-byte pointers (so the two widths differ ONLY in the
    /// pointer), gives the wasm32 offsets at four, and refuses every other
    /// width and every shape it cannot place.
    #[test]
    fn field_store_offsets_follow_the_session_pointer_width() {
        let lanes: Vec<TrustIrTy> = (0..SLOT_LANE_TY_COUNT)
            .map_while(slot_lane_ty_by_id)
            .collect();
        let native = trust_ir::TargetInfo {
            triple: "aarch64-apple-darwin".to_owned(),
            pointer_size: 8,
            ..trust_cg_codegen::wasm::wasm32_target_info()
        };
        let lane =
            |ty: &TrustIrTy, n: u64| TrustIrTy::Array(slot_lane_ty_id(ty).expect("seeded lane"), n);
        let ptr_u8 = TrustIrTy::Tuple(vec![TrustIrTy::Ptr, TrustIrTy::U8]);
        let battery = [
            TrustIrTy::Tuple(vec![TrustIrTy::U8, TrustIrTy::U64]),
            TrustIrTy::Tuple(vec![TrustIrTy::Ptr, TrustIrTy::Ptr]),
            TrustIrTy::Tuple(vec![TrustIrTy::U8, TrustIrTy::Ptr, TrustIrTy::U64]),
            TrustIrTy::Tuple(vec![TrustIrTy::U8, ptr_u8.clone(), TrustIrTy::U32]),
            TrustIrTy::Tuple(vec![
                TrustIrTy::Bool,
                TrustIrTy::U16,
                TrustIrTy::I32,
                TrustIrTy::I64,
            ]),
            TrustIrTy::Tuple(vec![TrustIrTy::U8, lane(&TrustIrTy::I32, 3), TrustIrTy::U8]),
            vec_slot_ty(),
            lane(&TrustIrTy::I64, 3),
            lane(&TrustIrTy::I32, 4),
            lane(&TrustIrTy::I8, 5),
        ];
        for ty in &battery {
            let fields = match ty {
                TrustIrTy::Tuple(f) => f.len() as u32,
                TrustIrTy::Array(_, n) => *n as u32,
                _ => unreachable!(),
            };
            for field in 0..fields {
                let adapter = aggregate_field_store_layout_at(ty, field, 8)
                    .expect("the native adapter lays the battery out")
                    .1;
                assert_eq!(
                    wasm32_field_store_offset(ty, field, &lanes, native.clone()),
                    Ok(adapter),
                    "{ty:?} field {field}: the C rule at 8-byte pointers is the adapter's layout"
                );
            }
            // Out of range at either width.
            assert!(
                aggregate_field_store_layout_at(ty, fields, 8).is_err(),
                "{ty:?}"
            );
            assert!(
                aggregate_field_store_layout_at(ty, fields, 4).is_err(),
                "{ty:?}"
            );
        }
        let at4 = |ty: &TrustIrTy| -> Vec<u64> {
            let n = match ty {
                TrustIrTy::Tuple(f) => f.len() as u32,
                TrustIrTy::Array(_, n) => *n as u32,
                _ => unreachable!(),
            };
            (0..n)
                .map(|f| {
                    aggregate_field_store_layout_at(ty, f, 4)
                        .expect("wasm32 layout")
                        .1
                })
                .collect()
        };
        let at8 = |ty: &TrustIrTy| -> Vec<u64> {
            let n = match ty {
                TrustIrTy::Tuple(f) => f.len() as u32,
                TrustIrTy::Array(_, n) => *n as u32,
                _ => unreachable!(),
            };
            (0..n)
                .map(|f| {
                    aggregate_field_store_layout_at(ty, f, 8)
                        .expect("native layout")
                        .1
                })
                .collect()
        };
        // A pointer is four bytes on wasm32: everything after one moves.
        assert_eq!(at4(&battery[1]), vec![0, 4]);
        assert_eq!(at8(&battery[1]), vec![0, 8]);
        assert_eq!(at4(&battery[2]), vec![0, 4, 8]);
        assert_eq!(at8(&battery[2]), vec![0, 8, 16]);
        assert_eq!(at4(&battery[3]), vec![0, 4, 12]);
        assert_eq!(at8(&battery[3]), vec![0, 8, 24]);
        // Integer-only shapes do not depend on the pointer width.
        for ty in [
            &battery[0],
            &battery[4],
            &battery[5],
            &battery[7],
            &battery[8],
            &battery[9],
        ] {
            assert_eq!(at4(ty), at8(ty), "{ty:?}");
        }
        // The fixed-offset word stores: the Vec header keeps its 8-byte words
        // at either width (its `I64` lanes align the pointer lane to 8), and a
        // fat-pointer slot's two pointer words sit `session_pointer_bytes`
        // apart (`store_fat_ptr_slot_into`).
        assert_eq!(at4(&vec_slot_ty()), vec![0, 8, 16]);
        for word in [4_u64, 8] {
            let slot = memory_slot_lane_ty(2 * word, word).expect("fat-pointer slot");
            let offsets: Vec<u64> = (0..2)
                .map(|f| {
                    aggregate_field_store_layout_at(&slot, f, word)
                        .expect("slot")
                        .1
                })
                .collect();
            assert_eq!(offsets, vec![0, word], "{slot:?}");
            let lane_ty = if word == 4 {
                TrustIrTy::I32
            } else {
                TrustIrTy::I64
            };
            assert_eq!(
                aggregate_field_store_layout_at(&slot, 1, word).map(|l| l.0),
                Ok(lane_ty)
            );
        }
        // Other widths, and shapes the bridge never writes, fail closed.
        for width in [0_u64, 2, 16] {
            assert!(
                aggregate_field_store_layout_at(&battery[0], 0, width).is_err(),
                "{width}"
            );
        }
        let non_lane = TrustIrTy::Array(trust_ir::TyId::new(u32::MAX), 2);
        let nested_struct = TrustIrTy::Tuple(vec![
            TrustIrTy::U8,
            TrustIrTy::Struct(trust_ir::StructId::new(0)),
        ]);
        for width in [4_u64, 8] {
            assert!(
                aggregate_field_store_layout_at(&non_lane, 0, width).is_err(),
                "{width}"
            );
            assert!(
                aggregate_field_store_layout_at(&nested_struct, 1, width).is_err(),
                "{width}"
            );
            assert!(
                aggregate_field_store_layout_at(&TrustIrTy::Ptr, 0, width).is_err(),
                "{width}"
            );
        }
    }

    /// WS7.1 (b), review: the lane `Store`s that replaced the store-form
    /// `InsertField` keep its value-type gate (`field_store_value_type_errors`).
    /// `bb0(%0: i64, %1: i32, %2: u64, %3: ptr)`; `%3` is the recorded field
    /// address of an `I64` field; `%4` = a call result; `%6` = an `i64` load.
    fn field_store_gate_fixture(
        stored: ValueId,
        declared: TrustIrTy,
        callee_returns: TrustIrTy,
    ) -> (TrustIrModule, TrustIrFunction, HashMap<ValueId, TrustIrTy>) {
        let mut module = TrustIrModule::new("field_store_gate");
        let own_ty = module
            .add_func_type(FuncTy {
                params: Vec::new(),
                returns: vec![TrustIrTy::I64],
                abi: None,
                is_vararg: false,
            })
            .expect("a fresh module has room for the function type");
        let callee_ty = module
            .add_func_type(FuncTy {
                params: Vec::new(),
                returns: vec![callee_returns],
                abi: None,
                is_vararg: false,
            })
            .expect("a fresh module has room for the callee type");
        let mut callee = TrustIrFunction::new(FuncId::new(1), "callee", callee_ty, BlockId::new(0));
        callee.blocks.push(Block::new(BlockId::new(0)));
        module
            .try_add_function(callee)
            .expect("the claim-free callee is admitted");
        let mut func = TrustIrFunction::new(FuncId::new(0), "f", own_ty, BlockId::new(0));
        let mut entry = Block::new(BlockId::new(0));
        entry.params = vec![
            (ValueId::new(0), TrustIrTy::I64),
            (ValueId::new(1), TrustIrTy::I32),
            (ValueId::new(2), TrustIrTy::U64),
            (ValueId::new(3), TrustIrTy::Ptr),
        ];
        entry.body.push(
            InstrNode::new(Inst::Call {
                callee: FuncId::new(1),
                args: Vec::new(),
            })
            .with_result(ValueId::new(4)),
        );
        // A self-call: `module` does not hold `f` (the bridge adds it later), so
        // its result type is read off `f`'s own signature.
        entry.body.push(
            InstrNode::new(Inst::Call {
                callee: FuncId::new(0),
                args: Vec::new(),
            })
            .with_result(ValueId::new(5)),
        );
        entry.body.push(
            InstrNode::new(Inst::Load {
                ty: TrustIrTy::I64,
                ptr: ValueId::new(3),
                volatile: false,
                align: None,
            })
            .with_result(ValueId::new(6)),
        );
        emit_typed_store(&mut entry, ValueId::new(3), declared, stored);
        entry.body.push(InstrNode::new(Inst::Return {
            values: vec![ValueId::new(0)],
        }));
        func.blocks.push(entry);
        let recorded = HashMap::from([(ValueId::new(3), TrustIrTy::I64)]);
        (module, func, recorded)
    }

    #[test]
    fn field_store_gate_admits_a_value_of_the_field_type() {
        // Block parameter, call result, self-call result and load result.
        for stored in [0_u32, 4, 5, 6] {
            let (module, func, recorded) =
                field_store_gate_fixture(ValueId::new(stored), TrustIrTy::I64, TrustIrTy::I64);
            assert_eq!(
                field_store_value_type_errors(&module, &func, &recorded),
                Ok(()),
                "%{stored}"
            );
        }
    }

    #[test]
    fn field_store_gate_refuses_what_the_store_form_insert_field_refused() {
        let refused = |stored: u32, declared: TrustIrTy, callee_returns: TrustIrTy| {
            let (module, func, recorded) =
                field_store_gate_fixture(ValueId::new(stored), declared, callee_returns);
            let err =
                field_store_value_type_errors(&module, &func, &recorded).expect_err("must refuse");
            assert!(err.starts_with("[TCG-FIELD-STORE-TYPE]"), "{err}");
            err
        };
        // A narrower value (the dangerous width mismatch: the CLI lowers this
        // `Store` to `mov w0, w0` when nothing gates it).
        assert!(refused(1, TrustIrTy::I64, TrustIrTy::I64).contains("I32"));
        // Same width, other signedness: the InsertField gate was exact, so is this.
        assert!(refused(2, TrustIrTy::I64, TrustIrTy::I64).contains("U64"));
        // A call result of the wrong type.
        assert!(refused(4, TrustIrTy::I64, TrustIrTy::I32).contains("I32"));
        // A value this function never defines: unknown is refused, as the
        // adapter refused an InsertField value of unknown type.
        assert!(refused(99, TrustIrTy::I64, TrustIrTy::I64).contains("<unknown>"));
        // The store no longer declares the recorded field type.
        assert!(refused(1, TrustIrTy::I32, TrustIrTy::I64).contains("declares I32"));
    }

    #[test]
    fn field_store_gate_is_scoped_to_the_recorded_field_stores() {
        // Negative twin of the refusals: the same mistyped store through an
        // address that no field store recorded is not this gate's (it is the
        // validator's `Store` finding), and an empty record checks nothing.
        let (module, func, _) =
            field_store_gate_fixture(ValueId::new(1), TrustIrTy::I64, TrustIrTy::I64);
        let other = HashMap::from([(ValueId::new(77), TrustIrTy::I64)]);
        assert_eq!(
            field_store_value_type_errors(&module, &func, &other),
            Ok(())
        );
        assert_eq!(
            field_store_value_type_errors(&module, &func, &HashMap::new()),
            Ok(())
        );
    }

    /// Rebase onto main's closure-body ABI: the bridge spells most
    /// `ExtractField`s with the AGGREGATE type, and the adapter types the result
    /// by the operand (`field_extract_types`). The gate must type it the same
    /// way: `value_environment`'s receiver unpack stores lane 0 of an
    /// `Array(lane I64, 1)` block parameter into an `I64` field.
    #[test]
    fn field_store_gate_types_historical_extracts_as_the_adapter_does() {
        let lane_i64 = slot_lane_ty_id(&TrustIrTy::I64).expect("seeded I64 lane");
        let env_ty = TrustIrTy::Array(lane_i64, 1);
        let pair_ty = TrustIrTy::Tuple(vec![TrustIrTy::I32, TrustIrTy::I64]);
        let nested_ty = TrustIrTy::Tuple(vec![env_ty.clone()]);
        // The SSE class-lane parameter of `ffi_c_abi_sse_aggregate`'s callee,
        // extracted under the two-lane slot type: the adapter refuses that
        // declared type ("ExtractField result type .. does not match field").
        let sse_ty = TrustIrTy::Tuple(vec![TrustIrTy::I64, TrustIrTy::F64]);
        let slot2_ty = TrustIrTy::Array(lane_i64, 2);
        let module = TrustIrModule::new("historical_extract_gate");
        let extract = |ty: &TrustIrTy, aggregate: u32, field: u32, result: u32| {
            InstrNode::new(Inst::ExtractField {
                ty: ty.clone(),
                aggregate: ValueId::new(aggregate),
                field,
            })
            .with_result(ValueId::new(result))
        };
        // `bb0(%0: env, %1: ptr, %2: pair, %3: nested)`. The use of the nested
        // chain (`%11`) sits in a block listed BEFORE its operand's (`%10`), so
        // the typing has to settle across rounds, not in one pass.
        let mut uses = Block::new(BlockId::new(1));
        uses.body.push(extract(&env_ty, 10, 0, 11));
        let mut entry = Block::new(BlockId::new(0));
        entry.params = vec![
            (ValueId::new(0), env_ty.clone()),
            (ValueId::new(1), TrustIrTy::Ptr),
            (ValueId::new(2), pair_ty.clone()),
            (ValueId::new(3), nested_ty.clone()),
            (ValueId::new(12), sse_ty),
        ];
        // Historical spelling over a lane array and a tuple field.
        entry.body.push(extract(&env_ty, 0, 0, 4));
        entry.body.push(extract(&pair_ty, 2, 1, 5));
        // trust-ir's spelling (the declared type is the result).
        entry.body.push(extract(&TrustIrTy::I64, 2, 1, 6));
        // Historical spelling of the wrong lane: field 0 of the pair is I32.
        entry.body.push(extract(&pair_ty, 2, 0, 7));
        // Out of range on the lane array: no type, so refused.
        entry.body.push(extract(&env_ty, 0, 1, 8));
        entry.body.push(extract(&nested_ty, 3, 0, 10));
        // Declared neither the operand's type nor the field's: unknown.
        entry.body.push(extract(&slot2_ty, 12, 0, 13));
        entry.body.push(extract(&TrustIrTy::I64, 12, 1, 15));
        // Declared right, but an F64 lane is not an I64 field.
        entry.body.push(extract(&TrustIrTy::F64, 12, 1, 16));
        // A read through the pointer `%1` (`mem::swap` of two `&[i32]`): the
        // DECLARED slot type's lane. A non-aggregate declared type is unknown.
        entry.body.push(extract(&slot2_ty, 1, 1, 17));
        entry.body.push(extract(&TrustIrTy::I64, 1, 0, 18));
        let func = TrustIrFunction::new(
            FuncId::new(0),
            "f",
            trust_ir::FuncTyId::new(0),
            BlockId::new(0),
        );
        let store_of = |value: u32| {
            let mut func = func.clone();
            let mut entry = entry.clone();
            emit_typed_store(
                &mut entry,
                ValueId::new(1),
                TrustIrTy::I64,
                ValueId::new(value),
            );
            func.blocks.push(entry);
            func.blocks.insert(0, uses.clone());
            func
        };
        let recorded = HashMap::from([(ValueId::new(1), TrustIrTy::I64)]);
        for admitted in [4_u32, 5, 6, 11, 17] {
            assert_eq!(
                field_store_value_type_errors(&module, &store_of(admitted), &recorded),
                Ok(()),
                "%{admitted}"
            );
        }
        let refused = |value: u32| {
            field_store_value_type_errors(&module, &store_of(value), &recorded)
                .expect_err("must refuse")
        };
        assert!(refused(7).contains("of type I32"));
        assert!(refused(8).contains("<unknown>"));
        // The nested aggregate itself is not a lane value.
        assert!(refused(10).contains("of type Array"));
        assert!(refused(13).contains("<unknown>"));
        assert!(refused(15).contains("<unknown>"));
        assert!(refused(16).contains("of type F64"));
        assert!(refused(18).contains("<unknown>"));
    }

    /// WS7.3: the lane reads a lane of an aggregate it names as a slot-lane
    /// `Array` with `ExtractElement` (`emit_lane_value_read`). Over an operand
    /// that IS such an array the declared element type is the result; over a
    /// `Tuple` parameter (`ffi_c_abi_sse_aggregate`'s `(i64, f64)` SSE lanes,
    /// read through the two-lane slot image) trust-ir defines no element read,
    /// so the result is untyped and its field store refused, as the gate refused
    /// the `ExtractField` spelling of the same read.
    #[test]
    fn field_store_gate_types_an_element_read_by_its_operand() {
        let lane_i64 = slot_lane_ty_id(&TrustIrTy::I64).expect("seeded I64 lane");
        let slot2_ty = TrustIrTy::Array(lane_i64, 2);
        let sse_ty = TrustIrTy::Tuple(vec![TrustIrTy::I64, TrustIrTy::F64]);
        let module = TrustIrModule::new("element_read_gate");
        let mut entry = Block::new(BlockId::new(0));
        entry.params = vec![
            (ValueId::new(0), slot2_ty),
            (ValueId::new(1), TrustIrTy::Ptr),
            (ValueId::new(2), sse_ty),
        ];
        entry.body.push(
            InstrNode::new(Inst::Const {
                ty: TrustIrTy::I64,
                value: Constant::Int(1),
            })
            .with_result(ValueId::new(3)),
        );
        for (array, result) in [(0_u32, 4_u32), (2, 5)] {
            entry.body.push(
                InstrNode::new(Inst::ExtractElement {
                    ty: TrustIrTy::I64,
                    array: ValueId::new(array),
                    index: ValueId::new(3),
                })
                .with_result(ValueId::new(result)),
            );
        }
        let store_of = |value: u32| {
            let mut func = TrustIrFunction::new(
                FuncId::new(0),
                "f",
                trust_ir::FuncTyId::new(0),
                BlockId::new(0),
            );
            let mut entry = entry.clone();
            emit_typed_store(
                &mut entry,
                ValueId::new(1),
                TrustIrTy::I64,
                ValueId::new(value),
            );
            func.blocks.push(entry);
            func
        };
        let recorded = HashMap::from([(ValueId::new(1), TrustIrTy::I64)]);
        assert_eq!(
            field_store_value_type_errors(&module, &store_of(4), &recorded),
            Ok(())
        );
        let err = field_store_value_type_errors(&module, &store_of(5), &recorded)
            .expect_err("an element read of a tuple must refuse");
        assert!(err.starts_with("[TCG-FIELD-STORE-TYPE]"), "{err}");
        assert!(err.contains("<unknown>"), "{err}");
    }

    /// WS7.3 review: the field-store gate judges a recorded field store's value
    /// as the lane lowered it. The per-function canonicalization that runs
    /// before the gate re-types no store value, so a thin pointer of another
    /// type and a same-width integer of the other signedness are still refused
    /// by name; only the module pass after the gate
    /// (`retype_stored_and_selected_values`) casts them to the field's type.
    #[test]
    fn field_store_gate_judges_stores_before_their_retype() {
        let ref_i32 = TrustIrTy::Ref(Box::new(TrustIrTy::I32));
        let module = TrustIrModule::new("field_store_order");
        let store_of = |field_ty: TrustIrTy, value_ty: TrustIrTy| {
            let mut func = TrustIrFunction::new(
                FuncId::new(0),
                "f",
                trust_ir::FuncTyId::new(0),
                BlockId::new(0),
            );
            let mut entry = Block::new(BlockId::new(0));
            entry.params = vec![
                (ValueId::new(0), TrustIrTy::Ptr),
                (ValueId::new(1), value_ty),
            ];
            emit_typed_store(&mut entry, ValueId::new(0), field_ty, ValueId::new(1));
            entry
                .body
                .push(InstrNode::new(Inst::Return { values: Vec::new() }));
            func.blocks.push(entry);
            func
        };
        for (field_ty, value_ty) in [
            (ref_i32.clone(), TrustIrTy::Ptr),
            (TrustIrTy::I64, TrustIrTy::U64),
        ] {
            let recorded = HashMap::from([(ValueId::new(0), field_ty.clone())]);
            let mut func = store_of(field_ty.clone(), value_ty.clone());
            let mut next = 2;
            let mut fresh = || {
                let value = ValueId::new(next);
                next += 1;
                value
            };
            canonicalize_copies::canonicalize_reinterpret_copies(&mut func, None, &mut fresh);
            let err = field_store_value_type_errors(&module, &func, &recorded)
                .expect_err("a mismatched field store must refuse");
            assert!(err.starts_with("[TCG-FIELD-STORE-TYPE]"), "{err}");
            // The module pass, which runs after the gate, casts the value.
            canonicalize_copies::retype_stored_and_selected_values(&mut func, None, &mut fresh);
            assert_eq!(
                field_store_value_type_errors(&module, &func, &recorded),
                Ok(()),
                "{field_ty:?} <- {value_ty:?}"
            );
        }
    }

    /// WS7.3: a shift amount is spelled at the shifted value's type the way
    /// rustc converts it (`cast_shift_expr_rhs`): truncate a wider amount,
    /// zero-extend a narrower one of either signedness, reinterpret an
    /// equal-width one. A constant becomes the bits that conversion yields, so
    /// a masked shift reads the same low bits; a non-integer side is refused.
    #[test]
    fn shift_amounts_are_spelled_at_the_value_type_as_rustc_converts_them() {
        use ShiftAmountSpelling::{AsIs, Cast, Constant as Bits};
        let spell = shift_amount_spelling;
        assert_eq!(spell(&TrustIrTy::U64, &TrustIrTy::U64, None), Ok(AsIs));
        assert_eq!(spell(&TrustIrTy::U64, &TrustIrTy::U64, Some(3)), Ok(AsIs));
        // The 128-bit amounts the validator refused (`lshr u128` by an `i32`).
        assert_eq!(
            spell(&TrustIrTy::I32, &TrustIrTy::U128, None),
            Ok(Cast(CastOp::ZExt))
        );
        assert_eq!(
            spell(&TrustIrTy::U32, &TrustIrTy::I128, None),
            Ok(Cast(CastOp::ZExt))
        );
        assert_eq!(
            spell(&TrustIrTy::I128, &TrustIrTy::U128, None),
            Ok(Cast(CastOp::Bitcast))
        );
        // Narrow values: a wider amount keeps its low bits.
        assert_eq!(
            spell(&TrustIrTy::I32, &TrustIrTy::U16, None),
            Ok(Cast(CastOp::Trunc))
        );
        assert_eq!(
            spell(&TrustIrTy::U128, &TrustIrTy::U8, None),
            Ok(Cast(CastOp::Trunc))
        );
        // A narrower SIGNED amount zero-extends, as rustc's does.
        assert_eq!(
            spell(&TrustIrTy::I8, &TrustIrTy::U64, None),
            Ok(Cast(CastOp::ZExt))
        );
        assert_eq!(
            spell(&TrustIrTy::U32, &TrustIrTy::I32, None),
            Ok(Cast(CastOp::Bitcast))
        );
        // Constants: in range unchanged; otherwise the converted bits, whose
        // low `log2(width)` bits are the original's.
        assert_eq!(
            spell(&TrustIrTy::I32, &TrustIrTy::U128, Some(100)),
            Ok(Bits(100))
        );
        assert_eq!(
            spell(&TrustIrTy::U32, &TrustIrTy::U8, Some(300)),
            Ok(Bits(300 & 0xff))
        );
        assert_eq!(
            spell(&TrustIrTy::I8, &TrustIrTy::U64, Some(-1)),
            Ok(Bits(0xff))
        );
        assert_eq!(
            spell(&TrustIrTy::I32, &TrustIrTy::U16, Some(-1)),
            Ok(Bits(0xffff))
        );
        for (amount, value) in [
            (TrustIrTy::Bool, TrustIrTy::U8),
            (TrustIrTy::U8, TrustIrTy::Bool),
            (TrustIrTy::F32, TrustIrTy::U32),
            (TrustIrTy::Ptr, TrustIrTy::U64),
        ] {
            assert!(
                spell(&amount, &value, None).is_err(),
                "{amount:?} -> {value:?}"
            );
        }
    }

    /// Every lane `memory_slot_lane_ty` can pick must be a seeded lane type --
    /// otherwise the array spelling silently falls back to the tuple and the
    /// hazard returns for that alignment.
    #[test]
    fn every_slot_alignment_yields_the_array_spelling() {
        for (align, lanes) in [(1u64, 4096u64), (2, 4096), (4, 4096), (8, 4096), (16, 4096)] {
            let size = align * lanes;
            let ty = memory_slot_lane_ty(size, align).expect("supported alignment");
            assert!(
                matches!(ty, TrustIrTy::Array(_, n) if n == lanes),
                "align {align} slot of {lanes} lanes must use the array spelling, got {ty:?}"
            );
        }
    }
