    #[test]
    fn fixed_module_worker_limit_uses_shared_strict_host_bounded_policy() {
        trust_cg_codegen::env_lock::with_env_overrides_removed(
            &[trust_cg_codegen::resource_limits::TRUST_CG_MAX_PARALLELISM_ENV],
            || assert_eq!(fixed_module_worker_limit(), Ok(1)),
        );

        let available = std::thread::available_parallelism().map_or(1, usize::from);
        trust_cg_codegen::env_lock::with_env_overrides(
            &[(
                trust_cg_codegen::resource_limits::TRUST_CG_MAX_PARALLELISM_ENV,
                " 3 ",
            )],
            || assert_eq!(fixed_module_worker_limit(), Ok(available.min(2))),
        );
        trust_cg_codegen::env_lock::with_env_overrides(
            &[(
                trust_cg_codegen::resource_limits::TRUST_CG_MAX_PARALLELISM_ENV,
                "1",
            )],
            || assert_eq!(fixed_module_worker_limit(), Ok(1)),
        );

        for invalid in [
            "",
            "0",
            "bad",
            "-1",
            "999999999999999999999999999999999999999",
        ] {
            trust_cg_codegen::env_lock::with_env_overrides(
                &[(
                    trust_cg_codegen::resource_limits::TRUST_CG_MAX_PARALLELISM_ENV,
                    invalid,
                )],
                || {
                    let error = fixed_module_worker_limit().unwrap_err();
                    assert!(error.contains("invalid Trust Codegen execution resource budget"));
                    assert!(error.contains("TRUST_CG_MAX_PARALLELISM"));
                },
            );
        }
    }

    #[test]
    fn fixed_module_executor_caps_concurrency_and_preserves_result_identity() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        const JOBS: usize = 6;
        let executor = FixedModuleExecutor::new(2, 2 * 1024 * 1024).unwrap();
        let active = Arc::new(AtomicUsize::new(0));
        let peak = Arc::new(AtomicUsize::new(0));
        let release = Arc::new((std::sync::Mutex::new(false), std::sync::Condvar::new()));
        let (started_sender, started_receiver) = std::sync::mpsc::channel();
        let mut results = Vec::new();

        for id in 0..JOBS {
            let active = Arc::clone(&active);
            let peak = Arc::clone(&peak);
            let release = Arc::clone(&release);
            let started_sender = started_sender.clone();
            results.push(
                executor
                    .schedule(move || {
                        let now = active.fetch_add(1, Ordering::SeqCst) + 1;
                        peak.fetch_max(now, Ordering::SeqCst);
                        started_sender.send(id).unwrap();

                        let (released, wake) = &*release;
                        let mut released = released
                            .lock()
                            .unwrap_or_else(std::sync::PoisonError::into_inner);
                        while !*released {
                            released = wake
                                .wait(released)
                                .unwrap_or_else(std::sync::PoisonError::into_inner);
                        }
                        active.fetch_sub(1, Ordering::SeqCst);
                        id
                    })
                    .unwrap(),
            );
        }
        drop(started_sender);

        // Both workers are now occupied and blocked. A third job cannot start
        // until one of those two releases, regardless of host scheduling.
        let mut first = vec![
            started_receiver
                .recv_timeout(std::time::Duration::from_secs(5))
                .unwrap(),
            started_receiver
                .recv_timeout(std::time::Duration::from_secs(5))
                .unwrap(),
        ];
        first.sort_unstable();
        assert_eq!(first, vec![0, 1]);
        assert!(matches!(
            started_receiver.try_recv(),
            Err(std::sync::mpsc::TryRecvError::Empty)
        ));

        {
            let (released, wake) = &*release;
            *released
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner) = true;
            wake.notify_all();
        }

        // Joining the per-job handles in submission order keeps result identity
        // deterministic even though the two workers may complete out of order.
        let joined: Vec<_> = results
            .into_iter()
            .map(|result| result.join().unwrap())
            .collect();
        assert_eq!(joined, (0..JOBS).collect::<Vec<_>>());
        assert_eq!(peak.load(Ordering::SeqCst), 2);
        assert_eq!(active.load(Ordering::SeqCst), 0);
    }

    #[test]
    fn fixed_module_executor_reports_panics_and_remains_usable() {
        let executor = FixedModuleExecutor::new(1, 2 * 1024 * 1024).unwrap();
        let panicked = executor
            .schedule(|| -> usize { panic!("synthetic fixed-module panic") })
            .unwrap();
        assert_eq!(panicked.join(), Err(FixedModuleTaskError::Panicked));

        let following = executor.schedule(|| 7usize).unwrap();
        assert_eq!(following.join(), Ok(7));
    }

    #[test]
    fn fixed_module_executor_transfers_each_request_environment() {
        const KEY: &str = "TCG_FIXED_MODULE_EXECUTOR_REQUEST_POLICY";
        let executor = FixedModuleExecutor::new(1, 2 * 1024 * 1024).unwrap();

        let first = trust_cg_codegen::env_lock::with_env_overrides(&[(KEY, "first")], || {
            executor
                .schedule(|| trust_cg_codegen::env_lock::var(KEY).ok())
                .unwrap()
        });
        let second = trust_cg_codegen::env_lock::with_env_overrides(&[(KEY, "second")], || {
            executor
                .schedule(|| trust_cg_codegen::env_lock::var(KEY).ok())
                .unwrap()
        });
        let absent = trust_cg_codegen::env_lock::with_env_overrides_removed(&[KEY], || {
            executor
                .schedule(|| trust_cg_codegen::env_lock::var(KEY).ok())
                .unwrap()
        });

        assert_eq!(first.join(), Ok(Some("first".to_owned())));
        assert_eq!(second.join(), Ok(Some("second".to_owned())));
        assert_eq!(absent.join(), Ok(None));
    }

    #[test]
    fn fixed_module_task_disconnect_fails_closed() {
        let (sender, receiver) = std::sync::mpsc::channel::<Result<usize, FixedModuleTaskError>>();
        drop(sender);
        let result = FixedModuleTaskResult { receiver };
        assert_eq!(result.join(), Err(FixedModuleTaskError::ExecutorStopped));
    }

