    #[test]
    fn scalar_cell_projection_storage_matches_actual_alloca_translation() {
        // Independent fixed storage expectations, in addition to the plumbing
        // comparison below. These are allocation bytes/alignment, not bit width.
        for (ty, size, align) in [
            (TrustIrTy::Bool, 1, 1),
            (TrustIrTy::U8, 1, 1),
            (TrustIrTy::U16, 2, 2),
            (TrustIrTy::U32, 4, 4),
            (TrustIrTy::F32, 4, 4),
            (TrustIrTy::F64, 8, 8),
            (TrustIrTy::U64, 8, 8),
        ] {
            assert_eq!(
                scalar_cell_storage(&ty),
                Some(ScalarCellStorage { size, align }),
                "{ty:?}"
            );
        }
        for ty in [
            TrustIrTy::Bool,
            TrustIrTy::I8,
            TrustIrTy::U8,
            TrustIrTy::I16,
            TrustIrTy::U16,
            TrustIrTy::I32,
            TrustIrTy::U32,
            TrustIrTy::I64,
            TrustIrTy::U64,
            TrustIrTy::I128,
            TrustIrTy::U128,
            TrustIrTy::F32,
            TrustIrTy::F64,
        ] {
            let allocated = trust_cg_lower::adapter::translate_type(&ty).unwrap();
            let storage = scalar_cell_storage(&ty).unwrap();
            assert_eq!(storage.size, u64::from(allocated.bytes()), "{ty:?}");
            assert_eq!(storage.align, u64::from(allocated.align()), "{ty:?}");
            assert!(scalar_cell_projection_container_matches(
                storage,
                1,
                0,
                storage.size,
                storage.align,
            ));
        }
        for ty in [
            TrustIrTy::Ptr,
            TrustIrTy::Unit,
            TrustIrTy::Never,
            TrustIrTy::Tuple(vec![TrustIrTy::F64]),
        ] {
            assert_eq!(scalar_cell_storage(&ty), None, "{ty:?}");
        }
    }

    /// The leaf offsets of a lowered C-layout `Type`, recursing into structs.
    fn lowered_c_layout_leaves(
        ty: &trust_cg_lower::types::Type,
        base: u64,
        out: &mut Vec<(u64, u64)>,
    ) {
        if let trust_cg_lower::types::Type::Struct(fields) = ty {
            for (index, field) in fields.iter().enumerate() {
                let offset = u64::from(ty.offset_of(index).unwrap());
                lowered_c_layout_leaves(field, base + offset, out);
            }
        } else {
            out.push((base, u64::from(ty.bytes())));
        }
    }

    #[test]
    fn c_rule_tuple_image_is_the_lowered_undeclared_tuple_layout() {
        use trust_ir::TyG::{Bool, F32, F64, I8, I16, I64, I128, U8, U16, U32, U64};
        let tuples = [
            TrustIrTy::Tuple(vec![U8, U32, U8]),
            TrustIrTy::Tuple(vec![U8, U64, U16]),
            TrustIrTy::Tuple(vec![Bool, I128, U8]),
            TrustIrTy::Tuple(vec![U16, TrustIrTy::Tuple(vec![U8, U64]), U8]),
            TrustIrTy::Tuple(vec![F32, F64, I8]),
            TrustIrTy::Tuple(vec![I16, I16, I64, U8]),
            TrustIrTy::Tuple(vec![U32, U32]),
        ];
        for tuple in &tuples {
            let mut leaves = Vec::new();
            let (size, align) = c_rule_image_leaves(tuple, 0, &mut leaves).unwrap();
            let lowered = trust_cg_lower::adapter::translate_type(tuple).unwrap();
            let mut expected = Vec::new();
            lowered_c_layout_leaves(&lowered, 0, &mut expected);
            assert_eq!(leaves, expected, "{tuple:?}");
            assert_eq!(size, u64::from(lowered.bytes()), "{tuple:?}");
            assert_eq!(align, u64::from(lowered.align()), "{tuple:?}");
        }
        // `(u8, u32, u8)`: 12 bytes at 4 — rustc's reordered `{ u8, u32, u8 }` is 8.
        let mut leaves = Vec::new();
        assert_eq!(
            c_rule_image_leaves(&tuples[0], 0, &mut leaves),
            Some((12, 4))
        );
        assert_eq!(leaves, vec![(0, 1), (4, 4), (8, 1)]);
        // A zero-sized unit lane occupies nothing; an array spelled by a module
        // type id is not modeled and answers `None`.
        assert_eq!(
            c_rule_image_leaves(&TrustIrTy::Unit, 0, &mut Vec::new()),
            Some((0, 1))
        );
        let array = TrustIrTy::Array(slot_lane_ty_id(&TrustIrTy::I32).unwrap(), 2);
        assert_eq!(c_rule_image_leaves(&array, 0, &mut Vec::new()), None);
    }

    #[test]
    fn c_rule_tuple_field_offsets_are_the_lowered_field_offsets() {
        use trust_ir::TyG::{I8, I16, U8, U16, U32, U64};
        let tuples = [
            TrustIrTy::Tuple(vec![U8, U32, U8, U32]),
            TrustIrTy::Tuple(vec![U32, U8, U32, U8]),
            TrustIrTy::Tuple(vec![U16, TrustIrTy::Tuple(vec![U8, U64]), U8]),
            TrustIrTy::Tuple(vec![I8, I16, U64]),
        ];
        for tuple in &tuples {
            let TrustIrTy::Tuple(fields) = tuple else {
                unreachable!()
            };
            let offsets = c_rule_tuple_field_offsets(tuple).unwrap();
            let lowered = trust_cg_lower::adapter::translate_type(tuple).unwrap();
            let expected: Vec<u64> = (0..fields.len())
                .map(|index| u64::from(lowered.offset_of(index).unwrap()))
                .collect();
            assert_eq!(offsets, expected, "{tuple:?}");
        }
        // The flattened image of `[(u8, u32); 2]`: element 1 starts at 8, not
        // at the `k * lane` offset 2 a uniform lane walk would read.
        assert_eq!(
            c_rule_tuple_field_offsets(&tuples[0]),
            Some(vec![0, 4, 8, 12])
        );
        // A lane shell is not a tuple image.
        let shell = TrustIrTy::Array(slot_lane_ty_id(&TrustIrTy::I32).unwrap(), 2);
        assert_eq!(c_rule_tuple_field_offsets(&shell), None);
    }

    #[test]
    fn scalar_cell_projection_rejects_partial_padded_and_misaligned_layouts() {
        for ty in [TrustIrTy::F32, TrustIrTy::F64, TrustIrTy::U64] {
            let storage = scalar_cell_storage(&ty).unwrap();
            for (fields, offset, size, align) in [
                (0, 0, storage.size, storage.align),
                (2, 0, storage.size, storage.align), // including a ZST sibling
                (1, 1, storage.size, storage.align),
                (1, 0, 0, storage.align),
                (1, 0, storage.size / 2, storage.align),
                (1, 0, storage.size * 2, storage.align),
                (1, 0, storage.size, storage.align / 2),
                (1, 0, storage.size, storage.align * 2),
            ] {
                assert!(
                    !scalar_cell_projection_container_matches(storage, fields, offset, size, align,),
                    "{ty:?}: {fields}/{offset}/{size}/{align}"
                );
            }
        }
    }

    #[test]
    fn scalar_cell_projection_admits_over_aligned_padding_only_on_wasm32() {
        let storage = scalar_cell_storage(&TrustIrTy::U64).unwrap();
        // `#[repr(align(64))] struct A64 { a: u64 }` and a 32-aligned wrapper.
        for (size, align) in [(64, 64), (32, 32), (16, 16)] {
            assert!(scalar_cell_projection_container_matches_at(
                4, storage, 1, 0, size, align
            ));
            assert!(!scalar_cell_projection_container_matches_at(
                8, storage, 1, 0, size, align
            ));
        }
        // Padding without the alignment that explains it, a second field, a
        // non-zero offset and a size that is not a multiple of the alignment
        // stay refused on wasm32 too.
        for (fields, offset, size, align) in [
            (1, 0, 16, 8),
            (2, 0, 64, 64),
            (1, 8, 64, 64),
            (1, 0, 48, 32),
            (1, 0, 4, 64),
        ] {
            assert!(
                !scalar_cell_projection_container_matches_at(
                    4, storage, fields, offset, size, align
                ),
                "{fields}/{offset}/{size}/{align}"
            );
        }
    }

    #[test]
    fn slice_swap_lanes_cover_every_element_with_aligned_lanes() {
        // The historical shapes keep their one- or two-lane moves.
        assert_eq!(slice_swap_lanes(1, 1), Some((TrustIrTy::I8, 1, 1)));
        assert_eq!(slice_swap_lanes(4, 1), Some((TrustIrTy::I32, 4, 1)));
        assert_eq!(slice_swap_lanes(8, 4), Some((TrustIrTy::I64, 8, 1)));
        assert_eq!(slice_swap_lanes(16, 8), Some((TrustIrTy::I64, 8, 2)));
        assert_eq!(slice_swap_lanes(16, 16), Some((TrustIrTy::I64, 8, 2)));
        // Wider or under-aligned elements move as lanes of their alignment.
        assert_eq!(slice_swap_lanes(24, 8), Some((TrustIrTy::I64, 8, 3)));
        assert_eq!(slice_swap_lanes(16, 4), Some((TrustIrTy::I32, 4, 4)));
        assert_eq!(slice_swap_lanes(12, 4), Some((TrustIrTy::I32, 4, 3)));
        assert_eq!(slice_swap_lanes(3, 1), Some((TrustIrTy::I8, 1, 3)));
        assert_eq!(slice_swap_lanes(6, 2), Some((TrustIrTy::I16, 2, 3)));
        assert_eq!(slice_swap_lanes(48, 16), Some((TrustIrTy::I64, 8, 6)));
        assert_eq!(slice_swap_lanes(128, 8), Some((TrustIrTy::I64, 8, 16)));
        for (size, align) in [(0, 1), (136, 8), (17, 1), (20, 8), (24, 32)] {
            assert_eq!(slice_swap_lanes(size, align), None, "{size}/{align}");
        }
        for size in 1..=128u64 {
            for align in [1u64, 2, 4, 8, 16] {
                if let Some((ty, bytes, lanes)) = slice_swap_lanes(size, align) {
                    assert_eq!(bytes * lanes as u64, size, "{size}/{align}");
                    assert_eq!(ty.bit_width(), Some(bytes as u32 * 8));
                    // A multi-lane move uses lanes no wider than the alignment.
                    assert!(lanes == 1 || bytes <= align, "{size}/{align}");
                }
            }
        }
    }

    #[test]
    fn memory_aggregate_lane_tiles_over_aligned_slots_only_on_wasm32() {
        for align in [1u64, 2, 4, 8, 16] {
            let wasm = memory_aggregate_lane_at(4, align).unwrap();
            assert_eq!(wasm, memory_aggregate_lane_at(8, align).unwrap());
            assert_eq!(wasm.1, align);
        }
        for align in [32u64, 64, 4096, 1 << 29] {
            assert_eq!(
                memory_aggregate_lane_at(4, align).unwrap(),
                (TrustIrTy::I128, 16)
            );
            assert!(memory_aggregate_lane_at(8, align).is_err());
        }
        for align in [0u64, 3, 48, 1 << 30] {
            assert!(memory_aggregate_lane_at(4, align).is_err(), "{align}");
        }
    }

    #[test]
    fn scalar_cell_projection_leaves_competing_slot_to_existing_path() {
        let local = Local::new(1);
        let other = Local::new(2);
        let mut cells = HashMap::new();
        let mut slots = HashMap::new();
        assert!(exclusive_scalar_cell(&cells, &slots, local).is_none());
        cells.insert(
            local,
            ScalarCell {
                ptr: ValueId::new(10),
                allocated_ty: TrustIrTy::F64,
                storage: scalar_cell_storage(&TrustIrTy::F64),
                home: None,
            },
        );
        assert_eq!(
            exclusive_scalar_cell(&cells, &slots, local).unwrap().ptr,
            ValueId::new(10)
        );
        slots.insert(
            other,
            MemorySlot {
                ptr: ValueId::new(20),
            },
        );
        assert!(exclusive_scalar_cell(&cells, &slots, local).is_some());
        slots.insert(
            local,
            MemorySlot {
                ptr: ValueId::new(30),
            },
        );
        assert!(exclusive_scalar_cell(&cells, &slots, local).is_none());
        assert_eq!(cells[&local].ptr, ValueId::new(10));
        assert_eq!(slots[&local].ptr, ValueId::new(30));
    }

