    fn inequality_compare_counts(
        module: &TrustIrModule,
        float_ty: Option<&TrustIrTy>,
    ) -> (usize, usize) {
        let mut integer_ne = 0;
        let mut float_une = 0;
        for node in module
            .functions
            .iter()
            .flat_map(|function| function.blocks.iter())
            .flat_map(|block| block.body.iter())
        {
            match &node.inst {
                Inst::ICmp { op: ICmpOp::Ne, .. } => integer_ne += 1,
                Inst::FCmp {
                    op: FCmpOp::UNe,
                    ty,
                    ..
                } => {
                    assert_eq!(Some(ty), float_ty);
                    float_une += 1;
                }
                _ => {}
            }
        }
        (integer_ne, float_une)
    }

    fn equality_compare_counts(
        module: &TrustIrModule,
        float_ty: Option<&TrustIrTy>,
    ) -> (usize, usize) {
        let mut integer_eq = 0;
        let mut float_oeq = 0;
        for node in module
            .functions
            .iter()
            .flat_map(|function| function.blocks.iter())
            .flat_map(|block| block.body.iter())
        {
            match &node.inst {
                Inst::ICmp { op: ICmpOp::Eq, .. } => integer_eq += 1,
                Inst::FCmp {
                    op: FCmpOp::OEq,
                    ty,
                    ..
                } => {
                    assert_eq!(Some(ty), float_ty);
                    float_oeq += 1;
                }
                _ => {}
            }
        }
        (integer_eq, float_oeq)
    }

    fn float_order_compare_counts(module: &TrustIrModule, float_ty: &TrustIrTy) -> (usize, usize) {
        let mut ordered_lt = 0;
        let mut ordered_gt = 0;
        for node in module
            .functions
            .iter()
            .flat_map(|function| function.blocks.iter())
            .flat_map(|block| block.body.iter())
        {
            match &node.inst {
                Inst::FCmp {
                    op: FCmpOp::OLt,
                    ty,
                    ..
                } => {
                    assert_eq!(ty, float_ty);
                    ordered_lt += 1;
                }
                Inst::FCmp {
                    op: FCmpOp::OGt,
                    ty,
                    ..
                } => {
                    assert_eq!(ty, float_ty);
                    ordered_gt += 1;
                }
                _ => {}
            }
        }
        (ordered_lt, ordered_gt)
    }

    fn integer_constant_count(module: &TrustIrModule, expected: i128) -> usize {
        module
            .functions
            .iter()
            .flat_map(|function| function.blocks.iter())
            .flat_map(|block| block.body.iter())
            .filter(|node| {
                matches!(
                    node.inst,
                    Inst::Const {
                        value: Constant::Int(value),
                        ..
                    } if value == expected
                )
            })
            .count()
    }

    fn store_types(module: &TrustIrModule) -> Vec<TrustIrTy> {
        module
            .functions
            .iter()
            .flat_map(|function| function.blocks.iter())
            .flat_map(|block| block.body.iter())
            .filter_map(|node| match &node.inst {
                Inst::Store { ty, .. } => Some(ty.clone()),
                _ => None,
            })
            .collect()
    }

    fn trunc_cast_count(module: &TrustIrModule) -> usize {
        module
            .functions
            .iter()
            .flat_map(|function| function.blocks.iter())
            .flat_map(|block| block.body.iter())
            .filter(|node| {
                matches!(
                    node.inst,
                    Inst::Cast {
                        op: CastOp::Trunc,
                        ..
                    }
                )
            })
            .count()
    }

