    #[test]
    fn slice_cmp_float_helpers_use_ieee_partial_order_and_none_niche() {
        for (size, symbol, ty) in [
            (4, "__trustcg_slice_cmp_f32", TrustIrTy::F32),
            (8, "__trustcg_slice_cmp_f64", TrustIrTy::F64),
        ] {
            let module = slice_cmp_trust_ir_module(size, symbol, true).unwrap();
            assert_eq!(
                inequality_compare_counts(&module, Some(&ty)),
                (0, 1),
                "{symbol}: unordered-or-not-equal must select the first decisive lane"
            );
            assert_eq!(
                float_order_compare_counts(&module, &ty),
                (1, 1),
                "{symbol}: ordered less/greater must distinguish Some(Ordering)"
            );
            assert!(
                !matches!(SLICE_CMP_UNORDERED, -1..=1),
                "the unordered sentinel must differ from every ordered code"
            );
            assert_eq!(
                integer_constant_count(&module, SLICE_CMP_UNORDERED),
                1,
                "{symbol}: unordered lanes must return the helper's unordered sentinel, \
                 which `lower_vec_partial_cmp` maps to the layout's `None` byte"
            );
        }
        // The `None` byte is the layout's niche value, never the sentinel: the
        // pinned Trust compiler reserves 0xFE (measured: `None::<Ordering>` is
        // 0xfe under LLVM), and a compiler that reserves 2 maps to 2.
        let (some, none) = (VariantIdx::from_u32(1), VariantIdx::from_u32(0));
        assert_eq!(
            option_ordering_none_byte(some, none, none, 0xFE, some, none),
            Ok(0xFEu8 as i8)
        );
        assert_eq!(
            option_ordering_none_byte(some, none, none, 2, some, none),
            Ok(2)
        );
    }

    #[test]
    fn option_ordering_none_byte_refuses_a_niche_it_cannot_write() {
        let (some, none) = (VariantIdx::from_u32(1), VariantIdx::from_u32(0));
        let refused = |result: Result<i8, String>| {
            result.is_err_and(|e| e.starts_with("[TCG-OPTION-ORDERING-LAYOUT]"))
        };
        // A niche value that is an `Ordering` value would make `None` a `Some`.
        for colliding in [0xFF, 0, 1] {
            assert!(refused(option_ordering_none_byte(
                some, none, none, colliding, some, none
            )));
        }
        // Wider than the one-byte niche.
        assert!(refused(option_ordering_none_byte(
            some, none, none, 0x1FE, some, none
        )));
        // `None` untagged, or more than one niche variant.
        assert!(refused(option_ordering_none_byte(
            none, some, some, 0xFE, some, none
        )));
        assert!(refused(option_ordering_none_byte(
            some,
            none,
            VariantIdx::from_u32(2),
            0xFE,
            some,
            none
        )));
    }

